export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
  correctOption: "A" | "B" | "C" | "D";
  correctAnswer: string;
  questionType: "MCQ";
  explanation: {
    correct_reason: string;
    distractor_reasons: {
      A: string;
      B: string;
      C: string;
      D: string;
    };
  };
}

export const MCQ_BANK_1: MCQItem[] = [{"id":"P1_U1_MCQ_001","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_001","question":"A bakery buys raw flour and yeast for $1.50 per loaf and sells finished bread for $4.50. Which action directly increases the bakery's added value per loaf?","options":{"A":"Increasing the price of raw flour purchased from suppliers","B":"Decorating the loaf with seed toppings and selling it for $5.50","C":"Increasing total weekly bakery production volume","D":"Lowering the hourly wage of the assistant baker"},"correctOption":"B","correctAnswer":"Decorating the loaf with seed toppings and selling it for $5.50","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value is the difference between selling price and raw material costs. Raising the selling price to $5.50 increases the margin over bought-in material costs ($1.50) from $3.00 to $4.00 per loaf.","distractor_reasons":{"A":"Incorrect because higher raw material costs ($1.50) without a selling price increase reduce the gap between cost and selling price, decreasing added value.","C":"Incorrect because increasing production volume changes total profit potential, but does not alter the added value created per individual loaf.","D":"Incorrect because labor wages are an operational overhead expense, not a raw material cost subtracted when calculating unit added value.","B":"Option B is correct because added value is the difference between selling price and raw material costs. Raising the selling price to $5.50 increases the margin over bought-in material costs ($1.50) from $3.00 to $4.00 per loaf."}}},{"id":"P1_U1_MCQ_002","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_002","question":"A furniture maker has limited timber and must choose between manufacturing 10 wooden dining tables or 20 office desks. What is the opportunity cost of choosing to produce the 20 office desks?","options":{"A":"The wages paid to carpenters for making the office desks","B":"The total financial cost of buying timber for 20 desks","C":"The revenue generated from selling all 20 office desks","D":"The 10 wooden dining tables that were not produced"},"correctOption":"D","correctAnswer":"The 10 wooden dining tables that were not produced","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost is the next best alternative foregone when making a choice. Giving up the production of 10 dining tables is the lost alternative.","distractor_reasons":{"A":"Incorrect because labor wages are direct production costs rather than opportunity costs.","B":"Incorrect because buying timber represents monetary expenditure, not the foregone benefit of the alternative product.","C":"Incorrect because revenue earned from the chosen option is financial income, not the alternative given up.","D":"Option D is correct because opportunity cost is the next best alternative foregone when making a choice. Giving up the production of 10 dining tables is the lost alternative."}}},{"id":"P1_U1_MCQ_003","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_003","question":"An agricultural business uses tractors, harvesting machinery, and storage barns to process crops. Which factor of production do these items represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because machinery, equipment, and buildings used in production are classified as capital goods.","distractor_reasons":{"A":"Incorrect because land refers to natural resources such as soil, minerals, and water.","B":"Incorrect because labour refers to the physical and mental effort contributed by human workers.","C":"Option C is correct because machinery, equipment, and buildings used in production are classified as capital goods.","D":"Incorrect because enterprise is the risk-taking and decision-making function of entrepreneurs."}}},{"id":"P1_U1_MCQ_004","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_004","question":"A smartphone assembly plant divides production into repetitive tasks, where each worker fits only one specific component on the assembly line. What is a primary disadvantage of this specialization for the business?","options":{"A":"Higher total expenditure on raw materials per phone","B":"Slower speed of worker training for individual tasks","C":"Decreased output of completed smartphones per hour","D":"Monotony leading to worker boredom and higher error rates"},"correctOption":"D","correctAnswer":"Monotony leading to worker boredom and higher error rates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repetitive tasks in division of labor often lead to boredom, causing reduced motivation, absenteeism, and potential quality errors.","distractor_reasons":{"A":"Incorrect because division of labor does not inherently increase raw material purchase costs.","B":"Incorrect because training workers for a single specialized task is faster, not slower, than training them for full production.","C":"Incorrect because specialization typically increases hourly output efficiency rather than decreasing it.","D":"Option D is correct because repetitive tasks in division of labor often lead to boredom, causing reduced motivation, absenteeism, and potential quality errors."}}},{"id":"P1_U1_MCQ_005","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_005","question":"Which of the following items represents a basic human need rather than a want?","options":{"A":"A luxury wristwatch","B":"A designer handbag","C":"Clean drinking water","D":"A gaming console"},"correctOption":"C","correctAnswer":"Clean drinking water","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clean water is essential for human survival, making it a basic need.","distractor_reasons":{"A":"Incorrect because a luxury watch is a desire that enhances lifestyle, making it a want.","B":"Incorrect because a designer handbag is a non-essential luxury item.","C":"Option C is correct because clean water is essential for human survival, making it a basic need.","D":"Incorrect because a gaming console is an entertainment product, which is a want."}}},{"id":"P1_U1_MCQ_006","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_006","question":"The fundamental economic problem of scarcity arises primarily because of which condition?","options":{"A":"Unlimited human wants exceeding limited economic resources","B":"Excessive supply of raw materials in developing economies","C":"Government price controls placed on basic consumer goods","D":"High profit margins targeted by private sector businesses"},"correctOption":"A","correctAnswer":"Unlimited human wants exceeding limited economic resources","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because scarcity occurs because society has finite resources (land, labour, capital, enterprise) to satisfy infinite human wants.","distractor_reasons":{"A":"Option A is correct because scarcity occurs because society has finite resources (land, labour, capital, enterprise) to satisfy infinite human wants.","B":"Incorrect because an excess supply of raw materials would alleviate scarcity rather than cause it.","C":"Incorrect because price controls are government interventions, not the underlying cause of scarcity.","D":"Incorrect because business profit targets reflect commercial objectives, not resource scarcity."}}},{"id":"P1_U1_MCQ_007","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_007","question":"A clothing brand purchases plain t-shirts for $5 each, adds custom embroidered logos, and packages them in gift boxes to sell for $18 each. What is the added value per t-shirt?","options":{"A":"$5","B":"$18","C":"$13","D":"$23"},"correctOption":"C","correctAnswer":"$13","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because added value = selling price ($18) minus bought-in component cost ($5) = $13.","distractor_reasons":{"A":"Incorrect because $5 is the purchase cost of the plain t-shirt.","B":"Incorrect because $18 is the final selling price, not the added value created.","C":"Option C is correct because added value = selling price ($18) minus bought-in component cost ($5) = $13.","D":"Incorrect because $23 is the sum of selling price and cost ($18 + $5), which is mathematically meaningless in added value."}}},{"id":"P1_U1_MCQ_008","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_008","question":"An entrepreneur invests personal savings into opening a new coffee shop rather than leaving the money in a savings account earning $1,200 annual interest. What is the opportunity cost of this investment?","options":{"A":"The total cost of purchasing commercial coffee machines","B":"The net profit generated by the coffee shop in its first year","C":"The salary paid to the baristas working at the shop","D":"The $1,200 annual interest foregone from the savings account"},"correctOption":"D","correctAnswer":"The $1,200 annual interest foregone from the savings account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the lost return of the next best alternative given up, which is the $1,200 interest.","distractor_reasons":{"A":"Incorrect because purchasing equipment is capital expenditure, not the lost alternative benefit.","B":"Incorrect because profit generated is the return from the chosen venture, not the foregone alternative.","C":"Incorrect because baristas' salaries are operating costs of the business.","D":"Option D is correct because opportunity cost measures the lost return of the next best alternative given up, which is the $1,200 interest."}}},{"id":"P1_U1_MCQ_009","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_009","question":"Which factor of production encompasses natural resources such as copper deposits, crude oil reserves, and fertile agricultural soil?","options":{"A":"Enterprise","B":"Land","C":"Labour","D":"Capital"},"correctOption":"B","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because land includes all natural resources provided by nature used in production.","distractor_reasons":{"A":"Incorrect because enterprise refers to business innovation and risk-taking.","B":"Option B is correct because land includes all natural resources provided by nature used in production.","C":"Incorrect because labour refers to human work effort.","D":"Incorrect because capital refers to man-made goods used in production."}}},{"id":"P1_U1_MCQ_010","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_010","question":"How can a car repair workshop directly increase its added value without changing the price charged to customers?","options":{"A":"Negotiating a lower purchase price for replacement engine parts from suppliers","B":"Increasing total monthly expenditure on local radio advertising","C":"Paying mechanics higher hourly wages to encourage faster work","D":"Expanding the physical size of the customer waiting area"},"correctOption":"A","correctAnswer":"Negotiating a lower purchase price for replacement engine parts from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus bought-in materials cost. Lowering material costs widens this gap without raising prices.","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus bought-in materials cost. Lowering material costs widens this gap without raising prices.","B":"Incorrect because advertising is an overhead expense and does not reduce input material costs.","C":"Incorrect because higher wages increase operational expenses, which lowers profit and does not increase unit added value.","D":"Incorrect because building expansions increase fixed overhead costs."}}},{"id":"P1_U1_MCQ_011","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_011","question":"A manufacturing firm adopts division of labor across its assembly line. Which outcome is an immediate benefit for the firm?","options":{"A":"Workers gain broad multi-skilled experience in all production tasks","B":"Production becomes completely immune to employee absences","C":"Worker speed and efficiency improve through task repetition","D":"Overall machinery maintenance expenses are eliminated"},"correctOption":"C","correctAnswer":"Worker speed and efficiency improve through task repetition","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because repeating a single specialized task allows workers to master it and work faster, raising efficiency.","distractor_reasons":{"A":"Incorrect because division of labor narrows worker skills rather than broadening them.","B":"Incorrect because specialized assembly lines are vulnerable if a key worker is absent, causing bottlenecks.","C":"Option C is correct because repeating a single specialized task allows workers to master it and work faster, raising efficiency.","D":"Incorrect because specialization does not reduce machine maintenance costs."}}},{"id":"P1_U1_MCQ_012","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_012","question":"Which statement best describes the difference between a need and a want?","options":{"A":"Needs are provided by the private sector, while wants are provided by the public sector.","B":"Needs change rapidly with trends, while wants remain fixed over time.","C":"Needs require money to obtain, while wants are completely free of cost.","D":"Needs are essential items required for survival, whereas wants are desires for non-essential goods."},"correctOption":"D","correctAnswer":"Needs are essential items required for survival, whereas wants are desires for non-essential goods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because needs (e.g., food, shelter) are necessary for survival, while wants (e.g., smartphones, vacations) are desires beyond survival needs.","distractor_reasons":{"A":"Incorrect because both sectors produce goods satisfying both needs and wants.","B":"Incorrect because basic needs stay constant while wants change with trends and income.","C":"Incorrect because both needs and wants usually cost money to acquire.","D":"Option D is correct because needs (e.g., food, shelter) are necessary for survival, while wants (e.g., smartphones, vacations) are desires beyond survival needs."}}},{"id":"P1_U1_MCQ_013","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_013","question":"A restaurant owner takes a financial risk by combining land, labor, and capital to start a catering business. Which factor of production is the owner providing?","options":{"A":"Labour","B":"Enterprise","C":"Capital","D":"Land"},"correctOption":"B","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because enterprise involves organizing the other factors of production and taking financial risks.","distractor_reasons":{"A":"Incorrect because labour refers to the execution of work tasks by employees.","B":"Option B is correct because enterprise involves organizing the other factors of production and taking financial risks.","C":"Incorrect because capital refers to the tools, machinery, and funds invested.","D":"Incorrect because land refers to natural resources and premises."}}},{"id":"P1_U1_MCQ_014","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_014","question":"A student decides to spend 2 hours studying for a business exam instead of working part-time at a store earning $12 per hour. What is the opportunity cost of studying?","options":{"A":"The exam grade achieved after studying for 2 hours","B":"The cost of the business textbook used for revision","C":"The $24 in wages that could have been earned at the store","D":"The total duration of 2 hours spent reviewing notes"},"correctOption":"C","correctAnswer":"The $24 in wages that could have been earned at the store","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the foregone alternative is 2 hours of work at $12/hr, totaling $24 lost earnings.","distractor_reasons":{"A":"Incorrect because the grade is the benefit gained, not the alternative sacrificed.","B":"Incorrect because book cost is a direct expenditure, not an opportunity cost.","C":"Option C is correct because the foregone alternative is 2 hours of work at $12/hr, totaling $24 lost earnings.","D":"Incorrect because 2 hours is the time spent, whereas opportunity cost measures the lost alternative value ($24)."}}},{"id":"P1_U1_MCQ_015","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_015","question":"Why do businesses try to add value to their products?","options":{"A":"To guarantee that fixed operational expenses drop to zero","B":"To ensure that all employees receive automatic wage increases","C":"To allow the business to charge a price higher than material costs and cover expenses","D":"To prevent competitors from entering the market entirely"},"correctOption":"C","correctAnswer":"To allow the business to charge a price higher than material costs and cover expenses","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because creating added value allows businesses to price products above raw material costs, enabling them to cover overhead costs and earn a profit.","distractor_reasons":{"A":"Incorrect because added value does not eliminate fixed overhead expenses.","B":"Incorrect because wage increases are internal decisions, not the primary objective of adding value.","C":"Option C is correct because creating added value allows businesses to price products above raw material costs, enabling them to cover overhead costs and earn a profit.","D":"Incorrect because adding value differentiates products but cannot prevent competitors from entering."}}},{"id":"P1_U1_MCQ_016","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_016","question":"Which scenario best illustrates specialization within a business?","options":{"A":"A shop owner performing accounting, stock ordering, and sales alone","B":"A factory requiring all staff to rotate through every job role daily","C":"A business purchasing multi-purpose vehicles for all deliveries","D":"A law firm employing separate experts for tax law, corporate law, and criminal law"},"correctOption":"D","correctAnswer":"A law firm employing separate experts for tax law, corporate law, and criminal law","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dividing legal work among specialists in specific branches of law is a direct application of specialization.","distractor_reasons":{"A":"Incorrect because a sole owner handling all tasks is generalist work, the opposite of specialization.","B":"Incorrect because daily rotation prevents deep specialization in one skill.","C":"Incorrect because multi-purpose vehicles are flexible capital, not worker specialization.","D":"Option D is correct because dividing legal work among specialists in specific branches of law is a direct application of specialization."}}},{"id":"P1_U1_MCQ_017","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_017","question":"A leather bag maker buys raw leather for $30 per bag and spends $10 on buckles and zippers. The finished bag sells for $90. What is the added value per bag?","options":{"A":"$40","B":"$60","C":"$50","D":"$90"},"correctOption":"C","correctAnswer":"$50","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs equal $30 + $10 = $40. Added value = $90 - $40 = $50.","distractor_reasons":{"A":"Incorrect because $40 is total raw material cost, not added value.","B":"Incorrect because $60 subtracts only raw leather ($90 - $30), ignoring the $10 buckle/zipper cost.","C":"Option C is correct because total bought-in material costs equal $30 + $10 = $40. Added value = $90 - $40 = $50.","D":"Incorrect because $90 is total selling price."}}},{"id":"P1_U1_MCQ_018","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_018","question":"Which factor of production includes human work, both physical labor and intellectual contribution?","options":{"A":"Labour","B":"Land","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Labour","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because labour encompasses all physical and mental effort provided by humans in production.","distractor_reasons":{"A":"Option A is correct because labour encompasses all physical and mental effort provided by humans in production.","B":"Incorrect because land refers to natural resources.","C":"Incorrect because capital refers to man-made assets like tools and machinery.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_019","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_019","question":"Why does economic activity exist in human societies?","options":{"A":"To eliminate the need for division of labor across industries","B":"To ensure that all businesses earn equal profit margins","C":"To satisfy consumer needs and wants using scarce economic resources","D":"To prevent governments from collecting business taxes"},"correctOption":"C","correctAnswer":"To satisfy consumer needs and wants using scarce economic resources","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the purpose of economic activity is to combine scarce resources to produce goods and services that satisfy human needs and wants.","distractor_reasons":{"A":"Incorrect because economic activity relies on division of labor to improve efficiency.","B":"Incorrect because profit margins vary across industries and are not the purpose of economic activity.","C":"Option C is correct because the purpose of economic activity is to combine scarce resources to produce goods and services that satisfy human needs and wants.","D":"Incorrect because government taxation is unrelated to why economic activity fundamentally exists."}}},{"id":"P1_U1_MCQ_020","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_020","question":"Which method is most effective for a high-end restaurant to increase its added value?","options":{"A":"Buying lower-quality ingredients to reduce food costs while reducing menu prices","B":"Hiring fewer waiters to decrease labor expenditure during busy hours","C":"Moving to a smaller location with reduced seating capacity","D":"Improving dining atmosphere and service quality to justify higher menu prices"},"correctOption":"D","correctAnswer":"Improving dining atmosphere and service quality to justify higher menu prices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because creating a premium dining experience allows the restaurant to increase menu prices significantly without a proportional increase in raw food costs, raising added value.","distractor_reasons":{"A":"Incorrect because lowering food quality damages brand image and limits pricing power.","B":"Incorrect because reducing waiters lowers service quality and operational costs, but labor costs are not subtracted from revenue to determine added value.","C":"Incorrect because reducing capacity limits output without raising added value per meal.","D":"Option D is correct because creating a premium dining experience allows the restaurant to increase menu prices significantly without a proportional increase in raw food costs, raising added value."}}},{"id":"P1_U1_MCQ_021","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_021","question":"Which economic sector includes activities such as coal mining, oil extraction, and wheat farming?","options":{"A":"Quaternary sector","B":"Secondary sector","C":"Tertiary sector","D":"Primary sector"},"correctOption":"D","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the primary sector extracts or harvests natural resources directly from the Earth.","distractor_reasons":{"A":"Incorrect because quaternary sector is not part of the standard IGCSE classification.","B":"Incorrect because the secondary sector manufactures or processes raw materials into finished goods.","C":"Incorrect because the tertiary sector provides services to consumers and businesses.","D":"Option D is correct because the primary sector extracts or harvests natural resources directly from the Earth."}}},{"id":"P1_U1_MCQ_022","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_022","question":"A country experiences deindustrialization. What structural shift in employment is observed in this economy?","options":{"A":"An increase in the proportion of workers employed in agriculture and mining","B":"A decline in manufacturing jobs and a growth in tertiary service jobs","C":"A complete national transition from private ownership to state ownership","D":"An expansion of primary sector output alongside declining service sector revenues"},"correctOption":"B","correctAnswer":"A decline in manufacturing jobs and a growth in tertiary service jobs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deindustrialization describes a decline in the relative importance of manufacturing (secondary sector) and a rise in the tertiary service sector.","distractor_reasons":{"A":"Incorrect because primary sector employment typically declines during deindustrialization.","B":"Option B is correct because deindustrialization describes a decline in the relative importance of manufacturing (secondary sector) and a rise in the tertiary service sector.","C":"Incorrect because deindustrialization relates to sectoral output and employment, not state vs private ownership.","D":"Incorrect because primary sector expansion is characteristic of early development, not deindustrialization."}}},{"id":"P1_U1_MCQ_023","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_023","question":"Which organisation operates in the public sector of a mixed economy?","options":{"A":"A privately owned chain of retail grocery stores","B":"A multinational automotive manufacturing company","C":"A state-owned hospital managed by the national government","D":"A partnership operating a local law firm"},"correctOption":"C","correctAnswer":"A state-owned hospital managed by the national government","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public sector entities are owned, controlled, and financed by government bodies.","distractor_reasons":{"A":"Incorrect because retail grocery chains are private sector businesses aimed at profit.","B":"Incorrect because private multinational corporations belong to the private sector.","C":"Option C is correct because public sector entities are owned, controlled, and financed by government bodies.","D":"Incorrect because law firm partnerships are private sector businesses."}}},{"id":"P1_U1_MCQ_024","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_024","question":"A factory converts raw timber into wooden kitchen cabinets. In which sector of the economy does this business operate?","options":{"A":"Primary sector","B":"Quaternary sector","C":"Tertiary sector","D":"Secondary sector"},"correctOption":"D","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because manufacturing or processing raw timber into finished furniture is a secondary sector activity.","distractor_reasons":{"A":"Incorrect because cutting down trees (forestry) is primary sector, but manufacturing cabinets is secondary.","B":"Incorrect because quaternary sector is not an IGCSE Business classification.","C":"Incorrect because selling the cabinets in a retail store is tertiary, whereas building them is secondary.","D":"Option D is correct because manufacturing or processing raw timber into finished furniture is a secondary sector activity."}}},{"id":"P1_U1_MCQ_025","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_025","question":"What characterizes a mixed economy?","options":{"A":"The coexistence of both private sector and public sector business activities","B":"Exclusive ownership of all production factors by government authorities","C":"Complete reliance on international trade for basic consumer goods","D":"An economy operating solely through primary sector agricultural production"},"correctOption":"A","correctAnswer":"The coexistence of both private sector and public sector business activities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a mixed economy allocates resources through both private market forces and state (public) provision.","distractor_reasons":{"A":"Option A is correct because a mixed economy allocates resources through both private market forces and state (public) provision.","B":"Incorrect because total state ownership defines a planned/command economy.","C":"Incorrect because reliance on international trade describes an open economy, not a mixed economy.","D":"Incorrect because an agricultural focus describes an undeveloped primary economy."}}},{"id":"P1_U1_MCQ_026","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_026","question":"Which business activity belongs to the tertiary sector?","options":{"A":"Iron ore mining","B":"Car manufacturing","C":"Commercial banking","D":"Cotton growing"},"correctOption":"C","correctAnswer":"Commercial banking","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because commercial banking provides financial services to businesses and individuals, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because iron ore mining extracts natural resources (primary sector).","B":"Incorrect because manufacturing cars transforms raw materials into finished goods (secondary sector).","C":"Option C is correct because commercial banking provides financial services to businesses and individuals, placing it in the tertiary sector.","D":"Incorrect because growing cotton is agricultural extraction (primary sector)."}}},{"id":"P1_U1_MCQ_027","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_027","question":"What primary objective distinguishes most public sector organizations from private sector businesses?","options":{"A":"Maximizing annual dividend payouts to private shareholders","B":"Achieving rapid international expansion and high market share","C":"Providing essential public services to society regardless of profit","D":"Eliminating competition through hostile corporate takeovers"},"correctOption":"C","correctAnswer":"Providing essential public services to society regardless of profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because public sector organizations (e.g., healthcare, defense) focus on public service and social welfare rather than profit maximization.","distractor_reasons":{"A":"Incorrect because public sector bodies do not issue shares to private investors.","B":"Incorrect because market share and expansion are private sector commercial goals.","C":"Option C is correct because public sector organizations (e.g., healthcare, defense) focus on public service and social welfare rather than profit maximization.","D":"Incorrect because state organizations do not conduct hostile corporate takeovers."}}},{"id":"P1_U1_MCQ_028","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_028","question":"A country undergoing rapid industrialization will typically experience which change in its economic sectors?","options":{"A":"A decline in urban factory construction and manufacturing output","B":"A movement of workers out of manufacturing and into farming","C":"An absolute closure of all tertiary sector service businesses","D":"A shift in employment from primary agriculture to secondary manufacturing"},"correctOption":"D","correctAnswer":"A shift in employment from primary agriculture to secondary manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization is the economic transition from primary agriculture to secondary manufacturing.","distractor_reasons":{"A":"Incorrect because factory construction increases during industrialization.","B":"Incorrect because workers move from farming into manufacturing during industrialization.","C":"Incorrect because the service sector generally expands alongside industrial growth.","D":"Option D is correct because industrialization is the economic transition from primary agriculture to secondary manufacturing."}}},{"id":"P1_U1_MCQ_029","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_029","question":"Which of the following is an example of a private sector enterprise?","options":{"A":"A family-owned bakery operating as a sole trader","B":"The national postal service owned by the government","C":"A municipal fire and rescue service funded by local taxes","D":"A state-run railway network managed by the transport ministry"},"correctOption":"A","correctAnswer":"A family-owned bakery operating as a sole trader","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a family-owned bakery is owned by private individuals seeking profit.","distractor_reasons":{"A":"Option A is correct because a family-owned bakery is owned by private individuals seeking profit.","B":"Incorrect because a government-owned national postal service is in the public sector.","C":"Incorrect because tax-funded emergency services belong to the public sector.","D":"Incorrect because state-run railways are public sector entities."}}},{"id":"P1_U1_MCQ_030","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_030","question":"An airline business buys new passenger aircraft from a manufacturer and provides international transport flights. In which economic sectors do these two operations belong?","options":{"A":"Airline operation: Primary sector; Aircraft manufacturing: Secondary sector","B":"Airline operation: Secondary sector; Aircraft manufacturing: Primary sector","C":"Airline operation: Tertiary sector; Aircraft manufacturing: Secondary sector","D":"Airline operation: Tertiary sector; Aircraft manufacturing: Primary sector"},"correctOption":"C","correctAnswer":"Airline operation: Tertiary sector; Aircraft manufacturing: Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because passenger transport is a tertiary service, while manufacturing aircraft is a secondary production activity.","distractor_reasons":{"A":"Incorrect because transport is not primary sector extraction.","B":"Incorrect because operating flights is not secondary manufacturing.","C":"Option C is correct because passenger transport is a tertiary service, while manufacturing aircraft is a secondary production activity.","D":"Incorrect because aircraft manufacturing is secondary, not primary."}}},{"id":"P1_U1_MCQ_031","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_031","question":"Why might a government choose to privatize a public sector electricity supply company?","options":{"A":"To increase state control over consumer pricing structure","B":"To introduce market competition and encourage efficiency gains","C":"To guarantee employment security for all public sector workers","D":"To eliminate the need for private investment in national infrastructure"},"correctOption":"B","correctAnswer":"To introduce market competition and encourage efficiency gains","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers ownership to private investors, introducing profit incentives and competition that tend to boost operational efficiency.","distractor_reasons":{"A":"Incorrect because privatization reduces direct state control.","B":"Option B is correct because privatization transfers ownership to private investors, introducing profit incentives and competition that tend to boost operational efficiency.","C":"Incorrect because privatization often leads to restructuring and potential job cuts.","D":"Incorrect because privatization invites private investment into public assets."}}},{"id":"P1_U1_MCQ_032","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_032","question":"Which combination correctly pairs an activity with its economic sector?","options":{"A":"Fish farming - Secondary sector","B":"Car insurance sales - Primary sector","C":"Furniture assembly - Tertiary sector","D":"Copper mining - Primary sector"},"correctOption":"D","correctAnswer":"Copper mining - Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mining copper directly extracts raw natural resources, which is a primary sector activity.","distractor_reasons":{"A":"Incorrect because fish farming is primary sector extraction/farming.","B":"Incorrect because selling insurance is a tertiary service.","C":"Incorrect because assembling furniture is secondary manufacturing.","D":"Option D is correct because mining copper directly extracts raw natural resources, which is a primary sector activity."}}},{"id":"P1_U1_MCQ_033","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_033","question":"In a developing nation, 60% of workers are employed in agriculture. Over 20 years, employment shifts to 40% manufacturing and 45% services. What is this economic development process called?","options":{"A":"Industrialization followed by growth of the tertiary sector","B":"Nationalization followed by total economic deindustrialization","C":"Privatization of public sector health and education services","D":"Contraction of secondary output in favor of primary extraction"},"correctOption":"A","correctAnswer":"Industrialization followed by growth of the tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shifting from agriculture (primary) to manufacturing (secondary) is industrialization, and subsequent growth in services represents tertiary sector expansion.","distractor_reasons":{"A":"Option A is correct because shifting from agriculture (primary) to manufacturing (secondary) is industrialization, and subsequent growth in services represents tertiary sector expansion.","B":"Incorrect because nationalization refers to state takeovers, not sectoral shifts.","C":"Incorrect because privatization refers to ownership changes, not sectoral labor movements.","D":"Incorrect because secondary manufacturing expanded from low levels, rather than contracting."}}},{"id":"P1_U1_MCQ_034","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_034","question":"Which group of services operates entirely within the tertiary sector?","options":{"A":"Coal extraction, flour milling, software development","B":"Oil refining, house building, wheat harvesting","C":"Hairdressing, tourism consultancy, warehousing","D":"Forestry, steel manufacturing, retail sales"},"correctOption":"C","correctAnswer":"Hairdressing, tourism consultancy, warehousing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hairdressing, tourism consultancy, and warehousing are all non-manufacturing service activities.","distractor_reasons":{"A":"Incorrect because coal extraction is primary and flour milling is secondary.","B":"Incorrect because oil refining and building are secondary, while wheat harvesting is primary.","C":"Option C is correct because hairdressing, tourism consultancy, and warehousing are all non-manufacturing service activities.","D":"Incorrect because forestry is primary and steel manufacturing is secondary."}}},{"id":"P1_U1_MCQ_035","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_035","question":"What is a main feature of public sector enterprises in a mixed economy?","options":{"A":"They are owned and controlled by private shareholders seeking maximum dividends","B":"They are funded or owned by government to provide essential community goods","C":"They operate without any budget constraints or government regulations","D":"They produce goods exclusively for export to foreign markets"},"correctOption":"B","correctAnswer":"They are funded or owned by government to provide essential community goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because state enterprises are funded or controlled by the government to serve public interests.","distractor_reasons":{"A":"Incorrect because private shareholders own private sector enterprises.","B":"Option B is correct because state enterprises are funded or controlled by the government to serve public interests.","C":"Incorrect because public bodies operate under strict government regulatory and financial controls.","D":"Incorrect because public services primarily serve domestic citizens."}}},{"id":"P1_U1_MCQ_036","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_036","question":"A business extracts crude oil, refines it into petrol, and sells it at branded petrol stations. In which order are these three operations classified by sector?","options":{"A":"Secondary, Primary, Tertiary","B":"Tertiary, Secondary, Primary","C":"Primary, Tertiary, Secondary","D":"Primary, Secondary, Tertiary"},"correctOption":"D","correctAnswer":"Primary, Secondary, Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because crude oil extraction is primary, refining petrol is secondary manufacturing, and retailing petrol at stations is tertiary.","distractor_reasons":{"A":"Incorrect because extraction is primary, not secondary.","B":"Incorrect because extraction is primary, not tertiary.","C":"Incorrect because refining is secondary, not tertiary.","D":"Option D is correct because crude oil extraction is primary, refining petrol is secondary manufacturing, and retailing petrol at stations is tertiary."}}},{"id":"P1_U1_MCQ_037","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_037","question":"Which trend is typical of a developed country experiencing deindustrialization?","options":{"A":"Manufacturing contribution to GDP increases rapidly","B":"Service sector contribution to total employment increases","C":"Agricultural output becomes the main source of national income","D":"Public sector ownership expands to cover all private businesses"},"correctOption":"B","correctAnswer":"Service sector contribution to total employment increases","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deindustrialized developed economies see a growing proportion of GDP and jobs generated by service industries.","distractor_reasons":{"A":"Incorrect because manufacturing's relative contribution declines during deindustrialization.","B":"Option B is correct because deindustrialized developed economies see a growing proportion of GDP and jobs generated by service industries.","C":"Incorrect because agriculture remains a minor sector in developed economies.","D":"Incorrect because deindustrialization does not mean total state takeover of businesses."}}},{"id":"P1_U1_MCQ_038","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_038","question":"Why might a private sector business decline to provide street lighting in a city?","options":{"A":"Street lighting requires primary sector extraction techniques","B":"Government laws prohibit private firms from installing electrical equipment","C":"It is difficult to charge non-paying individual users, making profit difficult","D":"Private sector businesses are legally forbidden from operating in urban areas"},"correctOption":"C","correctAnswer":"It is difficult to charge non-paying individual users, making profit difficult","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because street lighting is a public good; private firms cannot easily exclude non-payers, so they cannot easily make a profit.","distractor_reasons":{"A":"Incorrect because street lighting involves installation and power service, not resource extraction.","B":"Incorrect because private contractors can install electrical equipment under contract.","C":"Option C is correct because street lighting is a public good; private firms cannot easily exclude non-payers, so they cannot easily make a profit.","D":"Incorrect because private businesses operate extensively in urban areas."}}},{"id":"P1_U1_MCQ_039","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_039","question":"Which worker is employed in the secondary sector?","options":{"A":"A worker assembling electronic circuit boards in a factory","B":"A farmer picking apples in an orchard","C":"A bus driver operating a city transport route","D":"A financial advisor offering investment guidance"},"correctOption":"A","correctAnswer":"A worker assembling electronic circuit boards in a factory","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assembling electronics is manufacturing, which is in the secondary sector.","distractor_reasons":{"A":"Option A is correct because assembling electronics is manufacturing, which is in the secondary sector.","B":"Incorrect because picking apples is agricultural extraction (primary sector).","C":"Incorrect because driving a bus is transport service (tertiary sector).","D":"Incorrect because financial advice is a service (tertiary sector)."}}},{"id":"P1_U1_MCQ_040","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_040","question":"What is the primary motive of private sector business owners in a market economy?","options":{"A":"Meeting government production quotas set by regional councils","B":"Providing free public infrastructure to rural communities","C":"Maximizing tax payments paid directly to central government","D":"Earning profit as a return on their capital investment"},"correctOption":"D","correctAnswer":"Earning profit as a return on their capital investment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the central goal of private sector enterprise is earning profit for owners/shareholders.","distractor_reasons":{"A":"Incorrect because production quotas are features of planned command economies.","B":"Incorrect because infrastructure provision is typically a public sector objective.","C":"Incorrect because tax minimization, not maximization, is common in business strategy.","D":"Option D is correct because the central goal of private sector enterprise is earning profit for owners/shareholders."}}},{"id":"P1_U1_MCQ_041","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_041","question":"Which characteristic is most vital for an entrepreneur starting a risky new technology venture?","options":{"A":"A preference for working only under direct supervision","B":"Risk-taking capability and resilience in the face of failure","C":"Reluctance to adapt to changing market trends","D":"Avoidance of financial investment responsibility"},"correctOption":"B","correctAnswer":"Risk-taking capability and resilience in the face of failure","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because entrepreneurs must be willing to take calculated risks and show resilience when encountering startup obstacles.","distractor_reasons":{"A":"Incorrect because entrepreneurs are self-motivated leaders, not passive employees seeking supervision.","B":"Option B is correct because entrepreneurs must be willing to take calculated risks and show resilience when encountering startup obstacles.","C":"Incorrect because entrepreneurs must be highly adaptable to market changes.","D":"Incorrect because entrepreneurs actively manage and take financial responsibility for their venture."}}},{"id":"P1_U1_MCQ_042","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_042","question":"Why is a detailed business plan essential for a start-up business seeking a bank loan?","options":{"A":"It demonstrates financial viability and projected cash flows to lenders","B":"It legally exempts the business owner from paying corporate taxes","C":"It guarantees that the business will achieve high profit in its first month","D":"It replaces the requirement to register the business with tax authorities"},"correctOption":"A","correctAnswer":"It demonstrates financial viability and projected cash flows to lenders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks review business plans to evaluate expected revenue, costs, cash flow, and risk before approving loans.","distractor_reasons":{"A":"Option A is correct because banks review business plans to evaluate expected revenue, costs, cash flow, and risk before approving loans.","B":"Incorrect because a business plan has no legal effect on tax liabilities.","C":"Incorrect because a business plan cannot guarantee financial success.","D":"Incorrect because official business registration is a legal requirement separate from planning."}}},{"id":"P1_U1_MCQ_043","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_043","question":"Which metric is a valid method for measuring and comparing the size of two manufacturing businesses?","options":{"A":"Total net profit earned during the year","B":"The unit selling price of their flagship product","C":"The total value of annual sales revenue","D":"The percentage markup applied to raw material costs"},"correctOption":"C","correctAnswer":"The total value of annual sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because value of sales/revenue is a standard metric for comparing business size.","distractor_reasons":{"A":"Incorrect because profit is explicitly NOT a valid measure of size (a small firm can be more profitable than a large firm).","B":"Incorrect because selling price per unit does not indicate the scale or volume of the business.","C":"Option C is correct because value of sales/revenue is a standard metric for comparing business size.","D":"Incorrect because percentage markup reflects pricing strategy, not business size."}}},{"id":"P1_U1_MCQ_044","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_044","question":"Summit Cycling opens three new branches in Newcastle using profits retained from the previous year. What type of growth is this?","options":{"A":"Internal (organic) growth","B":"Horizontal integration","C":"Backward vertical integration","D":"A takeover"},"correctOption":"A","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","distractor_reasons":{"A":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","B":"Horizontal integration means joining with another firm at the same stage of production, usually through a merger or takeover.","C":"Backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"A takeover is external growth involving the purchase of another company rather than expansion using internal funds."}}},{"id":"P1_U1_MCQ_045","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_045","question":"Why do many governments provide grants and low-cost loans to new business start-ups?","options":{"A":"To force older established companies out of the market","B":"To create new jobs and lower national unemployment rates","C":"To ensure that all businesses remain small forever","D":"To eliminate private sector competition in retail sectors"},"correctOption":"B","correctAnswer":"To create new jobs and lower national unemployment rates","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because governments support start-ups to generate employment, spur economic growth, and encourage innovation.","distractor_reasons":{"A":"Incorrect because governments do not aim to destroy established businesses.","B":"Option B is correct because governments support start-ups to generate employment, spur economic growth, and encourage innovation.","C":"Incorrect because governments encourage growth and economic expansion.","D":"Incorrect because start-up support promotes competition, not eliminates it."}}},{"id":"P1_U1_MCQ_046","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_046","question":"Cedar Grove Joinery, a chain of coffee shops, takes over a rival chain of coffee shops in South Wales. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","distractor_reasons":{"A":"Forward vertical integration means moving closer to the final customer, such as a producer buying retail outlets.","B":"Backward vertical integration means moving towards suppliers, such as a retailer buying a manufacturing plant.","C":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","D":"Internal growth uses a firm's own resources; taking over a rival is external growth through acquisition."}}},{"id":"P1_U1_MCQ_047","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_047","question":"Which limitation applies when using the number of employees to measure business size?","options":{"A":"It cannot be used for businesses operating in the service sector.","B":"It is illegal to publish worker numbers under employment law.","C":"A highly automated capital-intensive factory may employ few staff but produce immense output.","D":"Worker numbers change continuously every hour of the working day."},"correctOption":"C","correctAnswer":"A highly automated capital-intensive factory may employ few staff but produce immense output.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because measuring size by employee numbers misleads when comparing capital-intensive automated firms with labor-intensive firms.","distractor_reasons":{"A":"Incorrect because employee headcount is routinely used across service sectors.","B":"Incorrect because reporting headcount is standard corporate financial reporting.","C":"Option C is correct because measuring size by employee numbers misleads when comparing capital-intensive automated firms with labor-intensive firms.","D":"Incorrect because employee numbers are measured by headcount/contracted staff, not hourly fluctuations."}}},{"id":"P1_U1_MCQ_048","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_048","question":"An organic farm owner chooses to remain small despite high demand. What is a common reason for remaining small?","options":{"A":"Small businesses are exempt from paying supplier bills","B":"Large businesses are prohibited from selling organic goods","C":"The business will lose its limited liability status if it grows","D":"The owner wishes to maintain personal control and offer specialized service"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal control and offer specialized service","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often remain small to keep personal control, preserve work-life balance, or offer personalized customer service.","distractor_reasons":{"A":"Incorrect because all businesses must pay their suppliers.","B":"Incorrect because large firms sell organic goods extensively.","C":"Incorrect because company growth does not remove limited liability status.","D":"Option D is correct because business owners often remain small to keep personal control, preserve work-life balance, or offer personalized customer service."}}},{"id":"P1_U1_MCQ_049","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_049","question":"Which method is an example of internal (organic) business growth?","options":{"A":"Buying out a major direct competitor in the same market","B":"Opening new company-owned retail branches in neighbouring towns","C":"Forming a joint venture with an overseas manufacturing partner","D":"Merging with a raw material supplier to secure inventory"},"correctOption":"B","correctAnswer":"Opening new company-owned retail branches in neighbouring towns","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because organic/internal growth expands the business using its own resources, such as opening new outlets or developing new products.","distractor_reasons":{"A":"Incorrect because buying a competitor is external growth via takeover.","B":"Option B is correct because organic/internal growth expands the business using its own resources, such as opening new outlets or developing new products.","C":"Incorrect because a joint venture is external collaboration.","D":"Incorrect because merging with a supplier is external backward vertical growth."}}},{"id":"P1_U1_MCQ_050","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_050","question":"A manufacturer of soy wax candles buys a chain of retail stores that sell its goods to the public. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Organic growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","distractor_reasons":{"A":"Backward vertical integration would involve acquiring a supplier further from the consumer, not a retailer near the end customer.","B":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","C":"Horizontal integration involves a firm at the same production stage, whereas a retailer is at a later stage of the chain.","D":"Organic growth is internal expansion, while purchasing an established retail chain is an external acquisition."}}},{"id":"P1_U1_MCQ_051","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_051","question":"Which of the following is a primary reason why newly established start-up businesses experience high failure rates?","options":{"A":"Excessive access to long-term venture capital finance","B":"Over-qualified management teams making strategic decisions","C":"Excessive consumer demand beyond initial production capacity","D":"Poor cash flow management and lack of working capital"},"correctOption":"D","correctAnswer":"Poor cash flow management and lack of working capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash flow problems and inadequate working capital are primary causes of early business failure.","distractor_reasons":{"A":"Incorrect because access to venture capital provides financial stability, preventing failure.","B":"Incorrect because strong management expertise promotes business survival.","C":"Incorrect because high demand is a commercial opportunity, not the main cause of insolvency.","D":"Option D is correct because cash flow problems and inadequate working capital are primary causes of early business failure."}}},{"id":"P1_U1_MCQ_052","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_052","question":"A company making aluminium laptops purchases the business that supplies its raw ingredients. What type of growth has taken place?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","distractor_reasons":{"A":"Forward vertical integration means moving towards the customer, such as buying distributors, not acquiring a supplier.","B":"Horizontal integration joins firms at the same stage of activity, whereas a raw-material supplier is at an earlier stage.","C":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"Internal growth is funded and achieved within the business, while buying a supplier is an external acquisition."}}},{"id":"P1_U1_MCQ_053","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_053","question":"Which section of a business plan outlines marketing strategies, target market demographics, and competitor analysis?","options":{"A":"Operations plan","B":"Market research and marketing plan","C":"Financial accounts summary","D":"Human resource policy overview"},"correctOption":"B","correctAnswer":"Market research and marketing plan","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because target customer demographics and competitor analysis form the market research and marketing section of a plan.","distractor_reasons":{"A":"Incorrect because operations details production machinery, locations, and logistics.","B":"Option B is correct because target customer demographics and competitor analysis form the market research and marketing section of a plan.","C":"Incorrect because financial accounts contain cash flow forecasts and budgets.","D":"Incorrect because HR policies deal with staffing and organizational hierarchy."}}},{"id":"P1_U1_MCQ_054","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_054","question":"Why is profit NOT considered a reliable method for measuring the physical size of a business?","options":{"A":"A small business with low costs can earn higher profit than a large inefficient firm","B":"Profit cannot be measured or recorded in business accounting records","C":"Government regulations prohibit comparing profit figures across companies","D":"Profit figures only reflect capital employed rather than sales revenue"},"correctOption":"A","correctAnswer":"A small business with low costs can earn higher profit than a large inefficient firm","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit depends on efficiency and margins; a smaller firm can be highly profitable while a large enterprise operates at a loss.","distractor_reasons":{"A":"Option A is correct because profit depends on efficiency and margins; a smaller firm can be highly profitable while a large enterprise operates at a loss.","B":"Incorrect because profit is recorded standardly in income statements.","C":"Incorrect because corporate profit figures are public for published companies.","D":"Incorrect because profit is revenue minus expenses, not capital employed."}}},{"id":"P1_U1_MCQ_055","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_055","question":"What potential problem can arise from rapid business expansion (overtrading)?","options":{"A":"Immediate decrease in overall managerial coordination complexity","B":"Automatic qualification for lower bank interest rates","C":"Excessive cash reserves building up in business bank accounts","D":"Severe cash flow shortages from buying inventory before receiving customer payment"},"correctOption":"D","correctAnswer":"Severe cash flow shortages from buying inventory before receiving customer payment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overtrading occurs when a business expands too quickly, running out of cash to fund working capital and inventory.","distractor_reasons":{"A":"Incorrect because managerial coordination complexity increases, not decreases, with expansion.","B":"Incorrect because rapid growth does not automatically lower borrowing rates.","C":"Incorrect because overtrading drains cash reserves.","D":"Option D is correct because overtrading occurs when a business expands too quickly, running out of cash to fund working capital and inventory."}}},{"id":"P1_U1_MCQ_056","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_056","question":"How might a local government directly support a new enterprise start-up in an economically depressed area?","options":{"A":"By setting maximum selling prices for the start-up's products","B":"By prohibiting all existing national companies from selling in the area","C":"By offering rent-free industrial premises for the first year of operation","D":"By taking majority share ownership in the new enterprise"},"correctOption":"C","correctAnswer":"By offering rent-free industrial premises for the first year of operation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because providing subsidized or rent-free premises directly reduces start-up costs, supporting new enterprise.","distractor_reasons":{"A":"Incorrect because price caps harm business profitability.","B":"Incorrect because governments cannot ban legal competition.","C":"Option C is correct because providing subsidized or rent-free premises directly reduces start-up costs, supporting new enterprise.","D":"Incorrect because government startup support rarely involves taking equity control."}}},{"id":"P1_U1_MCQ_057","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_057","question":"A boutique custom jewelry designer prefers to keep her workshop small. What market factor enables this business to remain successful despite its small size?","options":{"A":"Operating in a massive market dominated by low-cost mass production","B":"Serving a specialized niche market with high willingness to pay for custom items","C":"Relying on government subsidies to cover annual operating losses","D":"Selling standardized mass-manufactured products at wholesale prices"},"correctOption":"B","correctAnswer":"Serving a specialized niche market with high willingness to pay for custom items","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because niche markets value customized, specialized products, allowing small businesses to thrive alongside large mass-market competitors.","distractor_reasons":{"A":"Incorrect because competing head-on in mass markets favors large firms with scale economies.","B":"Option B is correct because niche markets value customized, specialized products, allowing small businesses to thrive alongside large mass-market competitors.","C":"Incorrect because relying on subsidies is not a viable market strategy for small private firms.","D":"Incorrect because mass-manufactured goods require scale, which small workshops lack."}}},{"id":"P1_U1_MCQ_058","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_058","question":"Which measure of business size compares the total monetary value of all capital assets and equity invested in a business?","options":{"A":"Capital employed","B":"Market share percentage","C":"Labour productivity rate","D":"Net profit margin"},"correctOption":"A","correctAnswer":"Capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because capital employed measures the total long-term finance and assets invested in the business.","distractor_reasons":{"A":"Option A is correct because capital employed measures the total long-term finance and assets invested in the business.","B":"Incorrect because market share is the proportion of total industry sales.","C":"Incorrect because labor productivity measures output per worker.","D":"Incorrect because profit margin measures profitability ratio, not capital size."}}},{"id":"P1_U1_MCQ_059","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_059","question":"What is a main advantage of expanding a business through external takeover rather than internal organic growth?","options":{"A":"Complete elimination of managerial cultural clashes","B":"Lower financial investment cost compared to organic expansion","C":"Guaranteed total agreement among all existing staff members","D":"Rapid speed of market expansion and instant customer acquisition"},"correctOption":"D","correctAnswer":"Rapid speed of market expansion and instant customer acquisition","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because acquiring an existing business provides immediate market share, facilities, and customer bases far faster than organic expansion.","distractor_reasons":{"A":"Incorrect because takeovers frequently trigger severe culture clashes.","B":"Incorrect because takeovers are usually very expensive.","C":"Incorrect because staff conflicts often arise during takeovers.","D":"Option D is correct because acquiring an existing business provides immediate market share, facilities, and customer bases far faster than organic expansion."}}},{"id":"P1_U1_MCQ_060","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_060","question":"Which attribute best reflects the 'innovative' characteristic of a successful entrepreneur?","options":{"A":"Repeating identical business processes without evaluating customer feedback","B":"Introducing novel products, processes, or business models to solve market problems","C":"Avoiding all new technology implementations in production lines","D":"Delegating all major decision-making authority to external consultants"},"correctOption":"B","correctAnswer":"Introducing novel products, processes, or business models to solve market problems","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because innovation involves creating original products, methods, or business concepts to satisfy market needs in new ways.","distractor_reasons":{"A":"Incorrect because repeating processes blindly is the opposite of innovation.","B":"Option B is correct because innovation involves creating original products, methods, or business concepts to satisfy market needs in new ways.","C":"Incorrect because avoiding technology hinders innovation.","D":"Incorrect because delegating all decisions reflects lack of leadership, not innovation."}}},{"id":"P1_U1_MCQ_061","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_061","question":"What does unlimited liability mean for a sole trader operating a neighborhood convenience store?","options":{"A":"The business owner is legally protected from any customer lawsuits.","B":"The business can issue an unlimited number of shares on the stock exchange.","C":"The owner is personally responsible for all business debts, risking personal assets.","D":"The bank guarantees to pay all outstanding supplier debts if the store fails."},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, risking personal assets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means there is no legal distinction between the owner and the business; personal assets can be seized to clear business debts.","distractor_reasons":{"A":"Incorrect because sole traders have no liability shield against lawsuits.","B":"Incorrect because sole traders cannot issue shares.","C":"Option C is correct because unlimited liability means there is no legal distinction between the owner and the business; personal assets can be seized to clear business debts.","D":"Incorrect because banks do not pay business debts; owners are liable."}}},{"id":"P1_U1_MCQ_062","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_062","question":"Which feature distinguishes a Public Limited Company (PLC) from a Private Limited Company (LTD)?","options":{"A":"PLCs are prohibited from employing more than 50 employees","B":"PLC owners have unlimited liability for corporate debts","C":"PLCs are managed directly by state government departments","D":"PLC shares can be freely bought and sold by the general public on a stock exchange"},"correctOption":"D","correctAnswer":"PLC shares can be freely bought and sold by the general public on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PLCs can trade shares publicly on stock exchanges, whereas LTD shares can only be sold privately with existing shareholder approval.","distractor_reasons":{"A":"Incorrect because PLCs can employ thousands of workers.","B":"Incorrect because both PLCs and LTDs provide limited liability.","C":"Incorrect because PLCs are private sector entities, not state departments.","D":"Option D is correct because PLCs can trade shares publicly on stock exchanges, whereas LTD shares can only be sold privately with existing shareholder approval."}}},{"id":"P1_U1_MCQ_063","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_063","question":"An individual purchases a franchise from a well-known global fast-food brand. What is a major disadvantage faced by this franchisee?","options":{"A":"Total absence of brand recognition in local consumer markets","B":"Complete freedom to alter recipes and logos without permission","C":"Inability to obtain training or support from the parent company","D":"Payment of mandatory initial franchise fees and ongoing royalties on revenue"},"correctOption":"D","correctAnswer":"Payment of mandatory initial franchise fees and ongoing royalties on revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees must pay upfront license fees and ongoing royalties to the franchisor, reducing net profits.","distractor_reasons":{"A":"Incorrect because global franchises come with established brand recognition.","B":"Incorrect because franchisees are strictly bound by franchisor rules and cannot alter branding.","C":"Incorrect because franchisors provide training and operational support.","D":"Option D is correct because franchisees must pay upfront license fees and ongoing royalties to the franchisor, reducing net profits."}}},{"id":"P1_U1_MCQ_064","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_064","question":"Two technology firms form a joint venture to develop an artificial intelligence software project. What is a key benefit of this arrangement?","options":{"A":"Permanent merger resulting in a single unified corporation","B":"Shared risks, development costs, and complementary expertise","C":"Automatic exemption from all national trade tariffs","D":"Total elimination of decision-making disagreements between partners"},"correctOption":"B","correctAnswer":"Shared risks, development costs, and complementary expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows independent companies to pool resources and expertise while sharing project risks and costs.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary collaborative projects, not full mergers.","B":"Option B is correct because a joint venture allows independent companies to pool resources and expertise while sharing project risks and costs.","C":"Incorrect because joint ventures do not exempt firms from international tariffs.","D":"Incorrect because conflict between joint venture partners is a common risk."}}},{"id":"P1_U1_MCQ_065","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_065","question":"What defines a social enterprise?","options":{"A":"A business that reinvests most profits to achieve social or environmental goals","B":"A government department providing free healthcare services funded by taxation","C":"A partnership designed solely to maximize owner capital withdrawals","D":"A public limited company operating exclusively on social media platforms"},"correctOption":"A","correctAnswer":"A business that reinvests most profits to achieve social or environmental goals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises operate commercially but prioritize reinvesting profits into social, community, or environmental objectives.","distractor_reasons":{"A":"Option A is correct because social enterprises operate commercially but prioritize reinvesting profits into social, community, or environmental objectives.","B":"Incorrect because tax-funded government departments belong to the public sector.","C":"Incorrect because social enterprises do not focus on owner profit extraction.","D":"Incorrect because social media presence does not make a company a social enterprise."}}},{"id":"P1_U1_MCQ_066","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_066","question":"Two doctors set up a medical clinic as a general partnership. What is a primary disadvantage of this form of business organisation?","options":{"A":"Inability to pool financial capital from more than one person","B":"Requirement to publish full annual financial reports to the public","C":"Heavy legal restrictions against hiring additional staff nurses","D":"Unintended joint liability for debts incurred by the other partner"},"correctOption":"D","correctAnswer":"Unintended joint liability for debts incurred by the other partner","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in an ordinary partnership, partners share unlimited liability jointly, meaning one partner is liable for debts created by another partner.","distractor_reasons":{"A":"Incorrect because partnerships pool capital from multiple partners.","B":"Incorrect because general partnerships are not required to publish accounts publicly.","C":"Incorrect because partnerships can hire employees freely.","D":"Option D is correct because in an ordinary partnership, partners share unlimited liability jointly, meaning one partner is liable for debts created by another partner."}}},{"id":"P1_U1_MCQ_067","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_067","question":"Why might the owners of a expanding sole trader business convert it into a Private Limited Company (LTD)?","options":{"A":"To sell shares directly to the general public on the stock exchange","B":"To avoid paying any corporate taxation on business profits","C":"To secure limited liability protection and raise capital from private investors","D":"To eliminate the need to maintain financial accounting records"},"correctOption":"C","correctAnswer":"To secure limited liability protection and raise capital from private investors","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because converting to an LTD protects personal assets via limited liability and allows selling shares to chosen private investors.","distractor_reasons":{"A":"Incorrect because only PLCs (not LTDs) sell shares to the general public.","B":"Incorrect because LTDs must pay corporate profits tax.","C":"Option C is correct because converting to an LTD protects personal assets via limited liability and allows selling shares to chosen private investors.","D":"Incorrect because LTDs face strict financial record-keeping laws."}}},{"id":"P1_U1_MCQ_068","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_068","question":"What is meant by limited liability for shareholders in a company?","options":{"A":"Shareholders can lose an unlimited amount of money if the business fails.","B":"Shareholders' financial loss is restricted to the amount invested in purchasing shares.","C":"The company is exempt from paying debts owed to bank lenders.","D":"Directors are personally liable for paying all company tax liabilities."},"correctOption":"B","correctAnswer":"Shareholders' financial loss is restricted to the amount invested in purchasing shares.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability restricts a shareholder's financial loss to their invested share capital; personal wealth cannot be seized.","distractor_reasons":{"A":"Incorrect because unlimited liability exposes personal wealth.","B":"Option B is correct because limited liability restricts a shareholder's financial loss to their invested share capital; personal wealth cannot be seized.","C":"Incorrect because the company entity remains liable for its bank debts.","D":"Incorrect because directors are not personally liable under limited liability unless fraud occurs."}}},{"id":"P1_U1_MCQ_069","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_069","question":"Which advantage does a franchisor enjoy when expanding through a franchise model?","options":{"A":"Rapid business expansion funded mostly by capital from franchisees","B":"Complete absorption of all local operational risks by the franchisor","C":"Guaranteed 100% profit retention from all individual franchise outlets","D":"Exemption from protecting registered trademarks and brand identity"},"correctOption":"A","correctAnswer":"Rapid business expansion funded mostly by capital from franchisees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the franchisor expands the chain using capital provided by franchisees who buy outlet rights.","distractor_reasons":{"A":"Option A is correct because the franchisor expands the chain using capital provided by franchisees who buy outlet rights.","B":"Incorrect because franchisees take on local operational risks.","C":"Incorrect because franchisees retain operational profits after paying royalties.","D":"Incorrect because franchisors must protect their trademarks."}}},{"id":"P1_U1_MCQ_070","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_070","question":"What is a main risk faced by shareholders of a Public Limited Company (PLC) during a corporate takeover attempt?","options":{"A":"They will be forced to take personal liability for company loans","B":"Their personal bank accounts will be seized by the acquiring company","C":"The company will automatically be converted into a sole trader","D":"Original founding owners may lose overall strategic control of the company"},"correctOption":"D","correctAnswer":"Original founding owners may lose overall strategic control of the company","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PLC shares are publicly traded; external investors can buy majority shares, resulting in original owners losing management control.","distractor_reasons":{"A":"Incorrect because PLC shareholders retain limited liability.","B":"Incorrect because personal assets are separate from corporate shares.","C":"Incorrect because corporate takeovers do not turn PLCs into sole traders.","D":"Option D is correct because PLC shares are publicly traded; external investors can buy majority shares, resulting in original owners losing management control."}}},{"id":"P1_U1_MCQ_071","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_071","question":"Which document regulates the internal working relationships, profit shares, and responsibilities between business partners?","options":{"A":"Articles of Incorporation","B":"Partnership Agreement (Deed of Partnership)","C":"Franchise Royalty Certificate","D":"Certificate of Incorporation"},"correctOption":"B","correctAnswer":"Partnership Agreement (Deed of Partnership)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership outlines profit sharing, capital contributions, and operational duties among partners.","distractor_reasons":{"A":"Incorrect because Articles of Association/Incorporation govern limited companies.","B":"Option B is correct because a Deed of Partnership outlines profit sharing, capital contributions, and operational duties among partners.","C":"Incorrect because royalty certificates do not regulate partnerships.","D":"Incorrect because Certificate of Incorporation registers limited companies."}}},{"id":"P1_U1_MCQ_072","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_072","question":"Which business structure possesses legal personality separate from its owners?","options":{"A":"Sole trader","B":"General partnership","C":"Private Limited Company (LTD)","D":"Unincorporated joint venture"},"correctOption":"C","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an LTD is an incorporated business with legal personality distinct from its owners.","distractor_reasons":{"A":"Incorrect because a sole trader is unincorporated (owner and business are one entity).","B":"Incorrect because a general partnership is unincorporated.","C":"Option C is correct because an LTD is an incorporated business with legal personality distinct from its owners.","D":"Incorrect because unincorporated joint ventures lack separate legal personality."}}},{"id":"P1_U1_MCQ_073","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_073","question":"What is a major advantage of operating as a sole trader?","options":{"A":"Complete owner independence in decision-making and full retention of profits","B":"Ability to raise substantial capital by issuing public shares","C":"Limited liability status protecting personal savings","D":"Shared workload and continuous business operation during owner illness"},"correctOption":"A","correctAnswer":"Complete owner independence in decision-making and full retention of profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sole traders make all decisions independently and keep 100% of profits after tax.","distractor_reasons":{"A":"Option A is correct because sole traders make all decisions independently and keep 100% of profits after tax.","B":"Incorrect because sole traders cannot issue shares.","C":"Incorrect because sole traders have unlimited liability.","D":"Incorrect because sole traders bear all workload and may have to close during illness."}}},{"id":"P1_U1_MCQ_074","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_074","question":"Why might a foreign business choose to enter an overseas market through a joint venture with a local firm rather than opening a wholly owned subsidiary?","options":{"A":"To gain total 100% control over local marketing operations","B":"To ensure that all profits are retained exclusively by the foreign parent firm","C":"To avoid complying with domestic labor and consumer laws","D":"To leverage local market knowledge, contacts, and shared cultural expertise"},"correctOption":"D","correctAnswer":"To leverage local market knowledge, contacts, and shared cultural expertise","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because partnering with a local firm provides crucial insights into domestic regulations, culture, distribution channels, and market conditions.","distractor_reasons":{"A":"Incorrect because joint ventures involve shared control rather than 100% foreign control.","B":"Incorrect because profits are shared with the local partner.","C":"Incorrect because joint ventures must comply with local laws.","D":"Option D is correct because partnering with a local firm provides crucial insights into domestic regulations, culture, distribution channels, and market conditions."}}},{"id":"P1_U1_MCQ_075","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_075","question":"Which condition is a legal requirement for forming a Private Limited Company (LTD)?","options":{"A":"Selling a minimum of $1 million in shares on the stock exchange","B":"Registering Articles of Association and Memorandum of Association with government authorities","C":"Employing at least 100 full-time staff members","D":"Operating in both the primary and tertiary economic sectors"},"correctOption":"B","correctAnswer":"Registering Articles of Association and Memorandum of Association with government authorities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because incorporating an LTD requires filing constitutional documents (Articles and Memorandum) with the official registrar of companies.","distractor_reasons":{"A":"Incorrect because LTDs cannot trade shares publicly.","B":"Option B is correct because incorporating an LTD requires filing constitutional documents (Articles and Memorandum) with the official registrar of companies.","C":"Incorrect because LTDs can have as few as 1 employee.","D":"Incorrect because company structure is independent of economic sector."}}},{"id":"P1_U1_MCQ_076","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_076","question":"What risk does a franchisor face when granting franchise licenses to independent operators?","options":{"A":"The franchisor becomes personally liable for all franchisee bank debts.","B":"The franchisor loses legal ownership of its global trademark","C":"Poor management by a single franchisee can damage the global brand reputation","D":"Franchisees are legally permitted to stop paying agreed royalty percentages"},"correctOption":"C","correctAnswer":"Poor management by a single franchisee can damage the global brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a poorly managed franchise outlet offering bad service or products can harm the brand's reputation worldwide.","distractor_reasons":{"A":"Incorrect because franchisors are not liable for independent franchisee debts.","B":"Incorrect because trademark rights remain with the franchisor.","C":"Option C is correct because a poorly managed franchise outlet offering bad service or products can harm the brand's reputation worldwide.","D":"Incorrect because franchise contracts enforce royalty payments."}}},{"id":"P1_U1_MCQ_077","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_077","question":"Which form of business organisation allows existing shareholders to restrict who can purchase new shares in the company?","options":{"A":"Private Limited Company (LTD)","B":"Public Limited Company (PLC)","C":"Sole Trader","D":"General Partnership"},"correctOption":"A","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because LTD share transfers require approval from existing directors/shareholders, keeping ownership private.","distractor_reasons":{"A":"Option A is correct because LTD share transfers require approval from existing directors/shareholders, keeping ownership private.","B":"Incorrect because PLC shares are freely bought and sold on public stock exchanges.","C":"Incorrect because sole traders do not issue shares.","D":"Incorrect because partnerships do not have shares."}}},{"id":"P1_U1_MCQ_078","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_078","question":"Which statement accurately describes continuity of existence for a business organisation?","options":{"A":"Sole traders automatically continue operating after the owner dies.","B":"Partnerships continue unaffected when a partner leaves, without drafting a new agreement.","C":"Unincorporated entities have legal continuity beyond their owners.","D":"Limited companies have continuous legal existence despite changes in share ownership or owner death."},"correctOption":"D","correctAnswer":"Limited companies have continuous legal existence despite changes in share ownership or owner death.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporated companies have perpetual succession; their existence is legally separate from their shareholders and continues if owners die.","distractor_reasons":{"A":"Incorrect because a sole trader business legally ends upon the owner's death.","B":"Incorrect because partner departure usually dissolves the original partnership legally.","C":"Incorrect because unincorporated businesses lack separate legal continuity.","D":"Option D is correct because incorporated companies have perpetual succession; their existence is legally separate from their shareholders and continues if owners die."}}},{"id":"P1_U1_MCQ_079","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_079","question":"A social enterprise sells handcrafted products to finance vocational training for disadvantaged youth. What is its primary objective?","options":{"A":"Maximizing cash dividend payouts to corporate investors","B":"Achieving a social purpose while maintaining financial sustainability","C":"Minimizing all operational sales to reduce business scale","D":"Selling goods below cost to rely entirely on state subsidies"},"correctOption":"B","correctAnswer":"Achieving a social purpose while maintaining financial sustainability","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social enterprises combine commercial trading to achieve social benefits while staying financially self-sustaining.","distractor_reasons":{"A":"Incorrect because social enterprises do not prioritize investor dividend maximization.","B":"Option B is correct because social enterprises combine commercial trading to achieve social benefits while staying financially self-sustaining.","C":"Incorrect because trading revenue is necessary to fund their social goals.","D":"Incorrect because social enterprises trade commercially rather than relying purely on subsidies."}}},{"id":"P1_U1_MCQ_080","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_080","question":"Which business structure is most suitable for an entrepreneur who wants limited liability but wishes to restrict company control to family members?","options":{"A":"Public Limited Company (PLC)","B":"General Partnership","C":"Private Limited Company (LTD)","D":"Sole Trader"},"correctOption":"C","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an LTD grants limited liability while enabling owners to restrict share sales strictly to family members.","distractor_reasons":{"A":"Incorrect because PLC shares are sold to the public, risking loss of family control.","B":"Incorrect because general partnerships have unlimited liability.","C":"Option C is correct because an LTD grants limited liability while enabling owners to restrict share sales strictly to family members.","D":"Incorrect because sole traders have unlimited liability."}}},{"id":"P1_U1_MCQ_081","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_081","question":"During its first year of operation, a startup restaurant focuses primarily on generating enough cash to cover monthly rent and supplier bills. Which business objective does this reflect?","options":{"A":"Survival","B":"Market share dominance","C":"Rapid international expansion","D":"Profit maximization"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because survival is the primary short-term objective for new start-ups during their vulnerable initial operating period.","distractor_reasons":{"A":"Option A is correct because survival is the primary short-term objective for new start-ups during their vulnerable initial operating period.","B":"Incorrect because market share dominance is a long-term growth objective.","C":"Incorrect because international expansion occurs after established domestic success.","D":"Incorrect because profit maximization becomes realistic only after survival is secured."}}},{"id":"P1_U1_MCQ_082","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_082","question":"A public limited company aims to maximize net profits at the end of the financial year. How does achieving this objective directly benefit shareholders?","options":{"A":"It guarantees immediate reduction in employee wage costs.","B":"It allows higher potential dividend payments and share price growth.","C":"It exempts the company from paying corporate tax to government.","D":"It forces suppliers to extend interest-free credit for two years."},"correctOption":"B","correctAnswer":"It allows higher potential dividend payments and share price growth.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher net profits provide the capital for distribution as dividends and drive shareholder value.","distractor_reasons":{"A":"Incorrect because profit maximization does not guarantee wage reductions.","B":"Option B is correct because higher net profits provide the capital for distribution as dividends and drive shareholder value.","C":"Incorrect because higher profits increase tax liabilities.","D":"Incorrect because supplier credit depends on negotiations, not profits earned."}}},{"id":"P1_U1_MCQ_083","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_083","question":"Why might a established retail company set a business objective of growth and market expansion?","options":{"A":"To increase fixed costs per unit produced","B":"To decrease total annual sales revenue","C":"To gain economies of scale and improve competitive position","D":"To eliminate the need for operational managers"},"correctOption":"C","correctAnswer":"To gain economies of scale and improve competitive position","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because business growth enables economies of scale, lowering unit costs and raising competitiveness.","distractor_reasons":{"A":"Incorrect because growth aims to lower unit fixed costs through scale economies.","B":"Incorrect because expansion aims to increase total revenue.","C":"Option C is correct because business growth enables economies of scale, lowering unit costs and raising competitiveness.","D":"Incorrect because larger businesses require more, not fewer, managers."}}},{"id":"P1_U1_MCQ_084","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_084","question":"Kingsway Motors sets its output and price to earn the largest possible total profit. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Sales revenue maximisation","C":"Market share leadership","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","distractor_reasons":{"A":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","B":"Sales revenue maximisation focuses on total sales value rather than on the difference between revenue and cost.","C":"Market share leadership aims at a large share of industry sales and may accept lower profits to achieve it.","D":"Survival means covering costs to stay in business, which is a more short-term and defensive aim."}}},{"id":"P1_U1_MCQ_085","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_085","question":"Which objective is typically held by internal company shareholders?","options":{"A":"Strict compliance with local environmental noise pollution levels","B":"Low prices and maximum product warranty protection","C":"Maximum tax revenue collection by tax authorities","D":"High return on capital invested through dividends and capital growth"},"correctOption":"D","correctAnswer":"High return on capital invested through dividends and capital growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders invest capital to receive dividends and see capital growth in share value.","distractor_reasons":{"A":"Incorrect because noise abatement is a local community objective.","B":"Incorrect because low prices are customer objectives.","C":"Incorrect because tax collection is a government objective.","D":"Option D is correct because shareholders invest capital to receive dividends and see capital growth in share value."}}},{"id":"P1_U1_MCQ_086","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_086","question":"What is a primary objective for factory employees as an internal stakeholder group?","options":{"A":"Maximizing annual corporate dividend payouts","B":"Job security, fair wages, and safe working conditions","C":"Higher interest rate returns on company bank loans","D":"Lowering selling prices of products sold to customers"},"correctOption":"B","correctAnswer":"Job security, fair wages, and safe working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because workers seek competitive pay, safe environments, and job stability.","distractor_reasons":{"A":"Incorrect because dividends go to shareholders, not factory staff.","B":"Option B is correct because workers seek competitive pay, safe environments, and job stability.","C":"Incorrect because interest returns concern bank lenders.","D":"Incorrect because product pricing is a customer/management concern."}}},{"id":"P1_U1_MCQ_087","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_087","question":"Which goal is most important to senior operational managers in a private limited company?","options":{"A":"Prompt payment of trade credit owed to component suppliers","B":"Maximizing income tax revenues for central government","C":"Career advancement, performance bonuses, and business prestige","D":"Reducing product prices to zero for community consumers"},"correctOption":"C","correctAnswer":"Career advancement, performance bonuses, and business prestige","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because managers are driven by career progression, status, salary, and performance bonuses.","distractor_reasons":{"A":"Incorrect because supplier payments are supplier concerns.","B":"Incorrect because tax revenue is a government goal.","C":"Option C is correct because managers are driven by career progression, status, salary, and performance bonuses.","D":"Incorrect because zero pricing would destroy company revenue."}}},{"id":"P1_U1_MCQ_088","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_088","question":"What is the main objective of customers as external stakeholders of a supermarket?","options":{"A":"Maximizing executive salary payments to supermarket directors","B":"Reducing the supermarket's total employee headcount","C":"Maximizing tax liabilities paid by the supermarket to government","D":"High quality goods, reasonable prices, and reliable customer service"},"correctOption":"D","correctAnswer":"High quality goods, reasonable prices, and reliable customer service","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because customers want value for money, good service, and quality products.","distractor_reasons":{"A":"Incorrect because executive salaries do not benefit consumers.","B":"Incorrect because reducing headcount can worsen customer service.","C":"Incorrect because tax levels are not a primary customer priority.","D":"Option D is correct because customers want value for money, good service, and quality products."}}},{"id":"P1_U1_MCQ_089","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_089","question":"Which objective is prioritized by suppliers selling raw materials to a manufacturing company?","options":{"A":"Regular repeat orders and prompt payment according to credit terms","B":"High dividend payments paid out to the manufacturer's shareholders","C":"Lowering the manufacturer's end-product retail selling prices","D":"Increasing local municipal taxes paid by the factory"},"correctOption":"A","correctAnswer":"Regular repeat orders and prompt payment according to credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suppliers want predictable ongoing purchases and timely payment for goods supplied.","distractor_reasons":{"A":"Option A is correct because suppliers want predictable ongoing purchases and timely payment for goods supplied.","B":"Incorrect because manufacturer dividends go to shareholders, not suppliers.","C":"Incorrect because end-product prices are consumer concerns.","D":"Incorrect because municipal taxes do not benefit raw material suppliers."}}},{"id":"P1_U1_MCQ_090","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_090","question":"What is the primary objective of a commercial bank that lends $500,000 to a business?","options":{"A":"Guaranteeing full employment for the borrowing firm's workforce","B":"Prompt payment of interest and eventual full repayment of loan principal","C":"Maximizing retail sales volume in the borrowing firm's shops","D":"Eliminating all legal contracts between the firm and its customers"},"correctOption":"B","correctAnswer":"Prompt payment of interest and eventual full repayment of loan principal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders prioritize receiving interest payments on schedule and securing full debt repayment.","distractor_reasons":{"A":"Incorrect because workforce employment levels are employee/government concerns.","B":"Option B is correct because bank lenders prioritize receiving interest payments on schedule and securing full debt repayment.","C":"Incorrect because banks care about sales only to the extent that it affects loan repayment.","D":"Incorrect because legal contracts protect business operations."}}},{"id":"P1_U1_MCQ_091","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_091","question":"Why does a national government track and regulate business activity within its country?","options":{"A":"To ensure that all businesses remain unprofitable and dependent on grants","B":"To prevent private businesses from competing in global markets","C":"To encourage job creation, collect tax revenues, and enforce consumer laws","D":"To force all private companies to convert into sole trader partnerships"},"correctOption":"C","correctAnswer":"To encourage job creation, collect tax revenues, and enforce consumer laws","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because governments regulate business activity to foster economic growth, maintain employment, collect tax revenue, and protect workers/consumers.","distractor_reasons":{"A":"Incorrect because governments want profitable businesses that generate taxes.","B":"Incorrect because governments encourage international trade competitiveness.","C":"Option C is correct because governments regulate business activity to foster economic growth, maintain employment, collect tax revenue, and protect workers/consumers.","D":"Incorrect because governments support diverse legal structures."}}},{"id":"P1_U1_MCQ_092","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_092","question":"Which objective is held by the local community residing near a large chemical production plant?","options":{"A":"Increasing factory waste dumping in local rivers to lower production costs","B":"Maximizing annual share dividend payouts to global investors","C":"Forcing the plant to replace all local staff with foreign workers","D":"Environmental protection, minimal traffic congestion, and local employment"},"correctOption":"D","correctAnswer":"Environmental protection, minimal traffic congestion, and local employment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local communities seek clean environments, low disturbance, and job opportunities for local residents.","distractor_reasons":{"A":"Incorrect because communities strongly oppose waste pollution.","B":"Incorrect because share dividends do not directly benefit local residents.","C":"Incorrect because local communities prefer local employment opportunities.","D":"Option D is correct because local communities seek clean environments, low disturbance, and job opportunities for local residents."}}},{"id":"P1_U1_MCQ_093","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_093","question":"A manufacturing firm decides to automate its factory, replacing 50 assembly line staff with robotic arms. Which stakeholder conflict is illustrated?","options":{"A":"Shareholders wanting higher profits vs Employees seeking job security","B":"Suppliers seeking prompt payment vs Customers wanting lower prices","C":"Government wanting tax revenue vs Local community wanting low traffic","D":"Bank lenders seeking interest payments vs Directors wanting larger offices"},"correctOption":"A","correctAnswer":"Shareholders wanting higher profits vs Employees seeking job security","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automation cuts labor costs to boost shareholder profit, conflicting directly with workers' desire for job retention.","distractor_reasons":{"A":"Option A is correct because automation cuts labor costs to boost shareholder profit, conflicting directly with workers' desire for job retention.","B":"Incorrect because automation directly impacts workers, not supplier credit terms.","C":"Incorrect because community traffic is not the central issue in factory automation.","D":"Incorrect because bank interest and director offices do not reflect automation redundancies."}}},{"id":"P1_U1_MCQ_094","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_094","question":"A company decides to operate its freight delivery trucks 24 hours a day to maximize growth and rapid customer deliveries. Local residents complain about night noise. Which two stakeholders are in conflict?","options":{"A":"Government and Bank lenders","B":"Managers/Shareholders and Local community","C":"Suppliers and Employees","D":"Tax authorities and Customers"},"correctOption":"B","correctAnswer":"Managers/Shareholders and Local community","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because management's objective of growth/service conflicts with the local community's desire for peace and quiet at night.","distractor_reasons":{"A":"Incorrect because government and banks are not directly involved in night delivery noise complaints.","B":"Option B is correct because management's objective of growth/service conflicts with the local community's desire for peace and quiet at night.","C":"Incorrect because suppliers and employees are not the primary conflicting groups here.","D":"Incorrect because tax authorities are unrelated to noise pollution."}}},{"id":"P1_U1_MCQ_095","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_095","question":"A pharmaceutical business doubles the retail price of life-saving medicines to maximize short-term profit margins. Which stakeholder conflict arises?","options":{"A":"Suppliers seeking prompt payment vs Government seeking job creation","B":"Employees seeking higher wages vs Bank lenders seeking loan repayment","C":"Shareholders seeking profit maximization vs Customers seeking affordable prices","D":"Local community seeking clean rivers vs Managers seeking promotion"},"correctOption":"C","correctAnswer":"Shareholders seeking profit maximization vs Customers seeking affordable prices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit maximization via price increases directly conflicts with customers' demand for affordable healthcare goods.","distractor_reasons":{"A":"Incorrect because supplier payments and job creation are not the core price conflict.","B":"Incorrect because employee wages vs bank loans do not address customer pricing.","C":"Option C is correct because profit maximization via price increases directly conflicts with customers' demand for affordable healthcare goods.","D":"Incorrect because river pollution is unrelated to pricing strategy."}}},{"id":"P1_U1_MCQ_096","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_096","question":"A business delays paying its raw material suppliers from 30 days to 90 days to improve its own cash liquidity. Which stakeholder conflict does this action create?","options":{"A":"Employees seeking workplace safety vs Customers seeking extended warranties","B":"Local community seeking job creation vs Tax authorities seeking income tax","C":"Shareholders seeking business growth vs Customers seeking lower prices","D":"Owners and managers seeking cash liquidity vs Suppliers seeking prompt payment"},"correctOption":"D","correctAnswer":"Owners and managers seeking cash liquidity vs Suppliers seeking prompt payment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extending credit payment terms improves management's cash flow position but causes cash flow problems for suppliers who expect prompt payment.","distractor_reasons":{"A":"Incorrect because workplace safety and customer warranties are unrelated to supplier trade credit payment terms.","B":"Incorrect because community job creation and tax collection do not involve commercial trade credit disputes.","C":"Incorrect because customer pricing and growth targets do not involve supplier credit management.","D":"Option D is correct because extending credit payment terms improves management's cash flow position but causes cash flow problems for suppliers who expect prompt payment."}}},{"id":"P1_U1_MCQ_097","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_097","question":"A coffee retailer commits to buying 100% of its coffee beans from certified Fairtrade farmers at above-market prices. Which type of business objective is being prioritized?","options":{"A":"Operational cost minimization objective","B":"Short-term survival objective","C":"Social and ethical objective","D":"Immediate profit maximization objective"},"correctOption":"C","correctAnswer":"Social and ethical objective","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because paying above-market rates to support farmer welfare and sustainable farming is a social and ethical business objective.","distractor_reasons":{"A":"Incorrect because buying at above-market prices raises raw material costs rather than minimizing expenses.","B":"Incorrect because paying higher purchasing prices increases costs, which does not focus on short-term financial survival.","C":"Option C is correct because paying above-market rates to support farmer welfare and sustainable farming is a social and ethical business objective.","D":"Incorrect because paying higher input prices reduces short-term profit margins."}}},{"id":"P1_U1_MCQ_098","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_098","question":"Why is establishing clear corporate objectives important for a business organization?","options":{"A":"It guarantees that no competitor can copy the firm's product designs","B":"It provides strategic direction, unifies employee efforts, and allows performance measurement","C":"It legally prevents employees from joining trade unions","D":"It automatically grants the business limited liability status"},"correctOption":"B","correctAnswer":"It provides strategic direction, unifies employee efforts, and allows performance measurement","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business objectives provide target goals, align departmental activities, and allow management to measure actual performance against targets.","distractor_reasons":{"A":"Incorrect because setting internal targets cannot stop external competitors from copying products.","B":"Option B is correct because business objectives provide target goals, align departmental activities, and allow management to measure actual performance against targets.","C":"Incorrect because corporate objectives do not restrict employees' legal right to join trade unions.","D":"Incorrect because limited liability is determined by legal business structure, not corporate objectives."}}},{"id":"P1_U1_MCQ_099","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_099","question":"A software startup focuses on survival in Year 1, achieves profit maximization in Year 3, and targets international expansion in Year 5. What does this progression demonstrate?","options":{"A":"Business objectives remain completely rigid and unchanged over time.","B":"Primary sector activities dominate tertiary software development.","C":"Business objectives change over time as a business matures and satisfies earlier goals.","D":"Government regulations force companies to change their primary objectives every two years."},"correctOption":"C","correctAnswer":"Business objectives change over time as a business matures and satisfies earlier goals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because business objectives evolve dynamically over time as initial risks decrease and higher-level goals become attainable.","distractor_reasons":{"A":"Incorrect because objectives adapt and change over time rather than remaining rigid.","B":"Incorrect because software development is a tertiary service, not a primary sector activity.","C":"Option C is correct because business objectives evolve dynamically over time as initial risks decrease and higher-level goals become attainable.","D":"Incorrect because objective changes are driven by strategic management decisions, not government mandate."}}},{"id":"P1_U1_MCQ_100","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_100","question":"Which statement best defines a business stakeholder?","options":{"A":"An individual who owns majority voting shares in a public limited company","B":"A bank manager responsible for evaluating commercial mortgage applications","C":"A government minister responsible for international trade regulations","D":"Any person or group with a direct interest in or affected by a business's operations and decisions"},"correctOption":"D","correctAnswer":"Any person or group with a direct interest in or affected by a business's operations and decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a stakeholder is defined broadly as any person, group, or organization impacted by or interested in the actions of a business.","distractor_reasons":{"A":"Incorrect because majority shareholders are only one specific subgroup of internal stakeholders.","B":"Incorrect because bank managers represent lenders, which is just one external stakeholder group.","C":"Incorrect because government ministers represent government regulators, not all stakeholders.","D":"Option D is correct because a stakeholder is defined broadly as any person, group, or organization impacted by or interested in the actions of a business."}}},{"id":"P1_U1_MCQ_101","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_101","question":"A juice bar purchases fresh oranges for $0.80 per glass and sells freshly squeezed orange juice for $3.50 per glass. Which action would directly increase the juice bar's added value per glass?","options":{"A":"Serving the juice in a premium glass with custom branding and charging $4.50","B":"Buying higher-cost organic oranges for $1.20 per glass without altering the selling price","C":"Increasing the total volume of orange juice produced each day","D":"Paying higher hourly wages to the bar staff during peak hours"},"correctOption":"A","correctAnswer":"Serving the juice in a premium glass with custom branding and charging $4.50","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus raw material costs. Raising the price to $4.50 increases the margin over orange costs ($0.80) from $2.70 to $3.70 per glass.","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus raw material costs. Raising the price to $4.50 increases the margin over orange costs ($0.80) from $2.70 to $3.70 per glass.","B":"Incorrect because higher orange costs ($1.20) without a selling price increase narrow the gap between price and raw materials, reducing added value.","C":"Incorrect because increasing daily output volume affects total daily profit but does not change the added value per individual glass.","D":"Incorrect because staff wages are overhead operating expenses, not raw material costs subtracted when calculating unit added value."}}},{"id":"P1_U1_MCQ_102","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_102","question":"A pottery maker has enough clay to manufacture either 15 decorative vases or 30 coffee mugs. If she decides to produce the 30 coffee mugs, what is the opportunity cost?","options":{"A":"The financial expenditure required to purchase clay for 30 mugs","B":"The 15 decorative vases that could have been produced instead","C":"The total sales revenue earned from selling the 30 coffee mugs","D":"The electricity cost incurred while firing the kiln for mug production"},"correctOption":"B","correctAnswer":"The 15 decorative vases that could have been produced instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative given up when making an economic choice, which is the 15 decorative vases.","distractor_reasons":{"A":"Incorrect because raw material expenditure is a direct financial cost, not the foregone product alternative.","B":"Option B is correct because opportunity cost is the next best alternative given up when making an economic choice, which is the 15 decorative vases.","C":"Incorrect because revenue earned is the benefit of the chosen option, not the lost benefit of the alternative.","D":"Incorrect because utility bills are operational production costs."}}},{"id":"P1_U1_MCQ_103","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_103","question":"A commercial printing firm purchases new automated printing presses and industrial paper cutters. Which factor of production do these items represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because machinery, physical tools, and factory equipment used in manufacturing are capital assets.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like timber, water, and minerals.","B":"Incorrect because labour refers to human physical and mental work.","C":"Option C is correct because machinery, physical tools, and factory equipment used in manufacturing are capital assets.","D":"Incorrect because enterprise is the risk-taking and business organization function."}}},{"id":"P1_U1_MCQ_104","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_104","question":"A bicycle assembly factory assigns workers to perform identical, narrow tasks on the production line all day. What is a key disadvantage of this division of labor for the factory?","options":{"A":"Workers take longer to learn their specific individual assembly tasks","B":"Total factory output of assembled bicycles per day decreases significantly","C":"The cost of purchasing raw bicycle frames from suppliers increases","D":"Repetitive work leads to employee boredom, lower morale, and potential quality flaws"},"correctOption":"D","correctAnswer":"Repetitive work leads to employee boredom, lower morale, and potential quality flaws","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating the same limited task leads to monotony, decreasing motivation and causing higher error rates.","distractor_reasons":{"A":"Incorrect because training workers for a single simple task is faster than training them for whole assembly.","B":"Incorrect because division of labor increases overall hourly output through specialization.","C":"Incorrect because division of labor does not alter component purchasing prices.","D":"Option D is correct because repeating the same limited task leads to monotony, decreasing motivation and causing higher error rates."}}},{"id":"P1_U1_MCQ_105","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_105","question":"Which of the following items represents a basic human need?","options":{"A":"An annual overseas holiday","B":"A subscription to a streaming service","C":"A high-end smartphone","D":"Basic shelter and housing"},"correctOption":"D","correctAnswer":"Basic shelter and housing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because basic shelter is essential for human survival, classifying it as a need.","distractor_reasons":{"A":"Incorrect because luxury travel is a lifestyle want.","B":"Incorrect because streaming subscriptions are entertainment, which is a want.","C":"Incorrect because a high-end smartphone is a non-essential technology want.","D":"Option D is correct because basic shelter is essential for human survival, classifying it as a need."}}},{"id":"P1_U1_MCQ_106","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_106","question":"The central economic problem of scarcity is caused by which situation?","options":{"A":"Government controls capping maximum retail prices for consumer goods","B":"Finite economic resources being insufficient to satisfy infinite human wants","C":"Private companies setting profit margins too low for long-term survival","D":"An oversupply of skilled labor in industrial manufacturing regions"},"correctOption":"B","correctAnswer":"Finite economic resources being insufficient to satisfy infinite human wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity occurs because limited factors of production cannot satisfy unlimited human needs and wants.","distractor_reasons":{"A":"Incorrect because government price caps are regulatory interventions, not the source of scarcity.","B":"Option B is correct because scarcity occurs because limited factors of production cannot satisfy unlimited human needs and wants.","C":"Incorrect because profit margins reflect pricing strategy, not resource availability.","D":"Incorrect because an oversupply of labor reduces scarcity of that factor rather than causing general economic scarcity."}}},{"id":"P1_U1_MCQ_107","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_107","question":"A tailor buys fabric for $20 and buttons/zippers for $5 per jacket. The completed suit jacket is sold for $75. What is the added value per jacket?","options":{"A":"$25","B":"$55","C":"$50","D":"$75"},"correctOption":"C","correctAnswer":"$50","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in component costs are $20 + $5 = $25. Added value = $75 - $25 = $50.","distractor_reasons":{"A":"Incorrect because $25 is the total material cost.","B":"Incorrect because $55 subtracts only fabric cost ($75 - $20), ignoring the $5 button/zipper cost.","C":"Option C is correct because total bought-in component costs are $20 + $5 = $25. Added value = $75 - $25 = $50.","D":"Incorrect because $75 is the final selling price."}}},{"id":"P1_U1_MCQ_108","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_108","question":"An individual leaves a full-time corporate job paying $45,000 per year to set up an independent consulting firm. What is the opportunity cost of starting this enterprise?","options":{"A":"The office rent paid for the consulting firm's business premises","B":"The total sales revenue earned from consulting clients in Year 1","C":"The money spent advertising the new consulting service online","D":"The $45,000 salary sacrificed from the corporate employment"},"correctOption":"D","correctAnswer":"The $45,000 salary sacrificed from the corporate employment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the foregone alternative is the $45,000 corporate salary given up to run the business.","distractor_reasons":{"A":"Incorrect because office rent is a direct operating expense.","B":"Incorrect because client revenue is the benefit of the new choice, not the lost alternative.","C":"Incorrect because online advertising is a marketing expense.","D":"Option D is correct because the foregone alternative is the $45,000 corporate salary given up to run the business."}}},{"id":"P1_U1_MCQ_109","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_109","question":"Which factor of production includes natural resources such as coal deposits, natural gas, and fresh water supplies?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all naturally occurring resources provided by nature used in production.","distractor_reasons":{"A":"Option A is correct because land covers all naturally occurring resources provided by nature used in production.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Incorrect because capital refers to man-made goods such as equipment and machinery.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_110","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_110","question":"Why is business activity essential in modern economies?","options":{"A":"To eliminate the need for international trade between countries","B":"To ensure that all businesses operate without paying interest on loans","C":"To combine factors of production to produce goods and services that satisfy human wants","D":"To prevent governments from collecting taxes from commercial firms"},"correctOption":"C","correctAnswer":"To combine factors of production to produce goods and services that satisfy human wants","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the core purpose of business activity is combining scarce resources to create products that meet human needs and wants.","distractor_reasons":{"A":"Incorrect because business activity stimulates rather than eliminates international trade.","B":"Incorrect because business activity does not eliminate financial interest payments.","C":"Option C is correct because the core purpose of business activity is combining scarce resources to create products that meet human needs and wants.","D":"Incorrect because business activity generates taxable profits, helping governments collect tax revenue."}}},{"id":"P1_U1_MCQ_111","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_111","question":"Which activity is classified under the primary sector of an economy?","options":{"A":"Assembling motor vehicles on an industrial assembly line","B":"Harvesting timber from managed forestry plantations","C":"Providing legal advice through a commercial law firm","D":"Retailing clothing in a shopping mall store"},"correctOption":"B","correctAnswer":"Harvesting timber from managed forestry plantations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting timber directly extracts natural resources, which defines the primary sector.","distractor_reasons":{"A":"Incorrect because assembling vehicles is secondary sector manufacturing.","B":"Option B is correct because harvesting timber directly extracts natural resources, which defines the primary sector.","C":"Incorrect because providing legal advice is a tertiary service activity.","D":"Incorrect because retail selling is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_112","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_112","question":"A nation experiences deindustrialization over a ten-year period. Which trend is observed in its workforce distribution?","options":{"A":"A rapid increase in the proportion of workers employed in mining and farming","B":"An expansion in factory assembly jobs accompanied by shrinking financial services","C":"A decline in secondary sector manufacturing jobs and growth in tertiary service jobs","D":"Complete nationalization of all private sector manufacturing businesses by the state"},"correctOption":"C","correctAnswer":"A decline in secondary sector manufacturing jobs and growth in tertiary service jobs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because deindustrialization involves a structural drop in manufacturing (secondary) employment and output, matched by tertiary service expansion.","distractor_reasons":{"A":"Incorrect because primary sector jobs typically decline alongside manufacturing during deindustrialization.","B":"Incorrect because factory jobs shrink rather than expand during deindustrialization.","C":"Option C is correct because deindustrialization involves a structural drop in manufacturing (secondary) employment and output, matched by tertiary service expansion.","D":"Incorrect because deindustrialization relates to sector proportions, not state ownership."}}},{"id":"P1_U1_MCQ_113","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_113","question":"Which organization operates in the public sector of a mixed economy?","options":{"A":"A private chain of fitness gyms owned by shareholders","B":"A commercial airline trading shares on a stock exchange","C":"A partnership operating a local dental clinic","D":"A state-owned municipal water supply corporation funded by government"},"correctOption":"D","correctAnswer":"A state-owned municipal water supply corporation funded by government","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because public sector entities are owned, controlled, and managed by central or local government bodies to serve the public.","distractor_reasons":{"A":"Incorrect because fitness gym chains are private sector businesses aimed at making profit.","B":"Incorrect because public limited companies traded on stock exchanges belong to the private sector.","C":"Incorrect because partnerships belong to the private sector.","D":"Option D is correct because public sector entities are owned, controlled, and managed by central or local government bodies to serve the public."}}},{"id":"P1_U1_MCQ_114","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_114","question":"A business extracts bauxite ore, refines it into raw aluminum metal, and manufactures aluminum drink cans. What is the correct sectoral order for these three stages?","options":{"A":"Bauxite extraction: Primary; Metal refining: Tertiary; Can manufacturing: Secondary","B":"Bauxite extraction: Secondary; Metal refining: Primary; Can manufacturing: Tertiary","C":"Bauxite extraction: Primary; Metal refining: Secondary; Can manufacturing: Secondary","D":"Bauxite extraction: Tertiary; Metal refining: Secondary; Can manufacturing: Primary"},"correctOption":"C","correctAnswer":"Bauxite extraction: Primary; Metal refining: Secondary; Can manufacturing: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extraction is primary, while both refining metal and manufacturing cans transform materials into products, placing both in the secondary sector.","distractor_reasons":{"A":"Incorrect because metal refining is processing (secondary), not a service (tertiary).","B":"Incorrect because extraction is primary, not secondary.","C":"Option C is correct because extraction is primary, while both refining metal and manufacturing cans transform materials into products, placing both in the secondary sector.","D":"Incorrect because extraction is primary, not tertiary."}}},{"id":"P1_U1_MCQ_115","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_115","question":"What is a primary characteristic of a mixed economy?","options":{"A":"Complete prohibition of private sector business ownership","B":"Total elimination of government taxation on corporate profits","C":"Exclusive reliance on primary sector agriculture to generate national income","D":"The allocation of economic resources through both private market forces and state intervention"},"correctOption":"D","correctAnswer":"The allocation of economic resources through both private market forces and state intervention","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a mixed economy balances private enterprise with public sector state provision.","distractor_reasons":{"A":"Incorrect because command economies prohibit private business, whereas mixed economies permit it.","B":"Incorrect because governments collect corporate taxes in mixed economies.","C":"Incorrect because mixed economies contain primary, secondary, and tertiary sectors.","D":"Option D is correct because a mixed economy balances private enterprise with public sector state provision."}}},{"id":"P1_U1_MCQ_116","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_116","question":"Which activity belongs entirely to the tertiary sector?","options":{"A":"Fishing for wild cod in coastal waters","B":"Refining raw crude oil into diesel fuel","C":"Providing insurance policies to commercial businesses","D":"Farming organic wheat on agricultural land"},"correctOption":"C","correctAnswer":"Providing insurance policies to commercial businesses","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because financial insurance is a service provided to consumers and businesses, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because fishing is primary sector resource extraction.","B":"Incorrect because oil refining is secondary sector manufacturing/processing.","C":"Option C is correct because financial insurance is a service provided to consumers and businesses, placing it in the tertiary sector.","D":"Incorrect because wheat farming is primary sector agriculture."}}},{"id":"P1_U1_MCQ_117","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_117","question":"What main goal drives private sector businesses in a market economy?","options":{"A":"Meeting state production output targets set by central planners","B":"Providing free public services to low-income citizens","C":"Maximizing tax liabilities paid directly to local councils","D":"Generating profit to provide a return on capital invested by owners"},"correctOption":"D","correctAnswer":"Generating profit to provide a return on capital invested by owners","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because earning profit is the primary commercial objective of private sector business owners.","distractor_reasons":{"A":"Incorrect because production quotas belong to planned command economies.","B":"Incorrect because providing free public services is a public sector objective.","C":"Incorrect because private firms seek to manage tax legally rather than maximize tax liabilities.","D":"Option D is correct because earning profit is the primary commercial objective of private sector business owners."}}},{"id":"P1_U1_MCQ_118","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_118","question":"Why might a national government decide to privatize a state-run postal delivery service?","options":{"A":"To introduce market competition, profit motives, and operational efficiency","B":"To ensure that all postal employees receive permanent government civil service status","C":"To completely eliminate the need for private investment in postal infrastructure","D":"To increase state ownership over national communication networks"},"correctOption":"A","correctAnswer":"To introduce market competition, profit motives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because privatization transfers state assets to private owners, bringing market discipline and profit incentives that boost efficiency.","distractor_reasons":{"A":"Option A is correct because privatization transfers state assets to private owners, bringing market discipline and profit incentives that boost efficiency.","B":"Incorrect because privatized workers lose state civil service status.","C":"Incorrect because privatization invites private investment into the infrastructure.","D":"Incorrect because privatization reduces state ownership."}}},{"id":"P1_U1_MCQ_119","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_119","question":"Which pair correctly matches the business activity with its economic sector?","options":{"A":"Automobile assembly – Primary sector","B":"Dairy cattle farming – Tertiary sector","C":"Hotel and hospitality management – Tertiary sector","D":"Gold mining – Secondary sector"},"correctOption":"C","correctAnswer":"Hotel and hospitality management – Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hotel hospitality is a commercial service, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because car assembly is secondary sector manufacturing.","B":"Incorrect because dairy farming is primary sector agriculture.","C":"Option C is correct because hotel hospitality is a commercial service, placing it in the tertiary sector.","D":"Incorrect because gold mining is primary sector extraction."}}},{"id":"P1_U1_MCQ_120","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_120","question":"As an economy undergoes industrialization, what shift typically occurs in its GDP composition?","options":{"A":"Primary agriculture increases its percentage contribution to total national GDP","B":"Tertiary service industries close down completely to prioritize farming","C":"Secondary manufacturing increases its percentage contribution to total national GDP","D":"Public sector entities take over 100% of all private retail operations"},"correctOption":"C","correctAnswer":"Secondary manufacturing increases its percentage contribution to total national GDP","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because industrialization marks the growth of manufacturing and processing, expanding secondary sector contribution to national GDP.","distractor_reasons":{"A":"Incorrect because primary sector GDP share drops relative to secondary manufacturing during industrialization.","B":"Incorrect because service industries grow alongside industrial development.","C":"Option C is correct because industrialization marks the growth of manufacturing and processing, expanding secondary sector contribution to national GDP.","D":"Incorrect because industrialization is a structural economic shift, not total state takeover."}}},{"id":"P1_U1_MCQ_121","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_121","question":"Which quality is most characteristic of a successful entrepreneur?","options":{"A":"Reluctance to modify initial business plans when market conditions change","B":"Preference for working under direct managerial orders in established firms","C":"Avoidance of financial risks and commercial decision-making","D":"Self-motivation, risk-taking willingness, and resilience after setbacks"},"correctOption":"D","correctAnswer":"Self-motivation, risk-taking willingness, and resilience after setbacks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entrepreneurs require initiative, drive, willingness to accept calculated risk, and determination to overcome early challenges.","distractor_reasons":{"A":"Incorrect because flexibility and adaptability are crucial entrepreneurial traits.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Incorrect because taking calculated financial risk is central to enterprise.","D":"Option D is correct because entrepreneurs require initiative, drive, willingness to accept calculated risk, and determination to overcome early challenges."}}},{"id":"P1_U1_MCQ_122","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_122","question":"Why is preparing a detailed business plan important for a new venture requesting a commercial bank loan?","options":{"A":"It shows projected revenue, costs, and cash flow to prove loan repayment ability to lenders","B":"It legally protects the business owner from personal debt liability without needing incorporation","C":"It guarantees that the business will make a net profit during its first six months","D":"It replaces official commercial tax registration documents required by government"},"correctOption":"A","correctAnswer":"It shows projected revenue, costs, and cash flow to prove loan repayment ability to lenders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks examine financial forecasts in a business plan to assess financial viability and loan default risk.","distractor_reasons":{"A":"Option A is correct because banks examine financial forecasts in a business plan to assess financial viability and loan default risk.","B":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","C":"Incorrect because business plans present projections, not profit guarantees.","D":"Incorrect because tax registration is a mandatory statutory legal process independent of business planning."}}},{"id":"P1_U1_MCQ_123","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_123","question":"Which metric is a standard, valid method for comparing the size of two businesses in the same industry?","options":{"A":"The net profit earned by each business at the end of the year","B":"The unit selling price of their main commercial products","C":"The total monetary value of capital employed in each business","D":"The percentage dividend rate paid to corporate shareholders"},"correctOption":"C","correctAnswer":"The total monetary value of capital employed in each business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term finance invested) is a recognized metric for assessing business size.","distractor_reasons":{"A":"Incorrect because net profit is NOT a valid size measure; a small efficient business can earn higher profit than a large inefficient firm.","B":"Incorrect because unit selling price reflects positioning, not company scale.","C":"Option C is correct because capital employed (total long-term finance invested) is a recognized metric for assessing business size.","D":"Incorrect because dividend payout percentages reflect financial policy, not physical business size."}}},{"id":"P1_U1_MCQ_124","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_124","question":"Callum is setting up a business in Yorkshire. Which action best describes the role of an entrepreneur?","options":{"A":"Taking financial risk and organising resources to create and run a business","B":"Receiving a fixed salary for carrying out routine office work","C":"Guaranteeing that the business will never face competition","D":"Owning the business but avoiding all decision-making"},"correctOption":"A","correctAnswer":"Taking financial risk and organising resources to create and run a business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","distractor_reasons":{"A":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","B":"A fixed salary for routine work describes an employee, not an entrepreneur who bears risk and organises the business.","C":"No entrepreneur can guarantee the absence of competition, which is outside their control in a market.","D":"Entrepreneurs are actively involved in decisions; avoiding all decision-making is not an entrepreneurial role."}}},{"id":"P1_U1_MCQ_125","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_125","question":"Why do national governments offer start-up grants and advisory support to new business entrepreneurs?","options":{"A":"To create new jobs, foster innovation, and lower national unemployment","B":"To eliminate competition for established state-owned enterprises","C":"To force small business owners to convert into public limited companies","D":"To prevent foreign businesses from trading in domestic markets"},"correctOption":"A","correctAnswer":"To create new jobs, foster innovation, and lower national unemployment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government start-up support aims to stimulate economic growth, generate employment, and boost innovation.","distractor_reasons":{"A":"Option A is correct because government start-up support aims to stimulate economic growth, generate employment, and boost innovation.","B":"Incorrect because governments encourage start-ups to foster competition rather than eliminate it.","C":"Incorrect because governments support all valid legal forms, not just PLCs.","D":"Incorrect because start-up grants support domestic enterprise rather than enforcing trade protectionism."}}},{"id":"P1_U1_MCQ_126","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_126","question":"Grace is preparing a business plan before launching a new venture. What is the main purpose of a business plan?","options":{"A":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","B":"To guarantee that the business will make a profit in its first year","C":"To remove the need for any market research before launching","D":"To avoid having to keep any accounting records"},"correctOption":"A","correctAnswer":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","distractor_reasons":{"A":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","B":"A plan cannot guarantee profit, which depends on future trading conditions and many factors outside the plan.","C":"A business plan supports rather than replaces market research, which remains necessary to understand customers.","D":"A business plan does not remove the legal and practical need to keep proper financial records."}}},{"id":"P1_U1_MCQ_127","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_127","question":"An analyst wants to compare the size of Greenfield Organics with other firms in the same industry. Which of these is a measure of business size?","options":{"A":"Gross profit margin","B":"Number of employees","C":"Current ratio","D":"Return on capital employed"},"correctOption":"B","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","distractor_reasons":{"A":"Gross profit margin measures profitability relative to revenue, not the physical scale or size of the business.","B":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","C":"The current ratio measures short-term liquidity and says nothing about how large the business is.","D":"Return on capital employed is a profitability ratio rather than a measure of the size of the business."}}},{"id":"P1_U1_MCQ_128","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_128","question":"Silverstream Bottling has grown very rapidly over two years. Which is most likely to be a problem caused by such rapid growth?","options":{"A":"Communication and decision-making become slower as the organisation grows","B":"The business automatically gains a monopoly position","C":"Its products immediately become lower in price than all rivals","D":"Its shareholders are no longer entitled to any dividend"},"correctOption":"A","correctAnswer":"Communication and decision-making become slower as the organisation grows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","distractor_reasons":{"A":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","B":"Rapid growth does not automatically create a monopoly, which would require dominance of the whole market.","C":"Growth gives no guarantee of lower prices than competitors, which depend on costs and pricing decisions.","D":"Shareholders keep their dividend rights regardless of how quickly the business expands."}}},{"id":"P1_U1_MCQ_129","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_129","question":"Why might the owner of a successful specialized hair salon choose to keep the business small rather than expand?","options":{"A":"To maintain close personal relationships with customers and full personal management control","B":"Because small service businesses are exempt from paying supplier bills","C":"Because expanding a business automatically removes its limited liability protection","D":"Because government legislation caps the maximum revenue small businesses can earn"},"correctOption":"A","correctAnswer":"To maintain close personal relationships with customers and full personal management control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owners often stay small to preserve personal contact with clients, manage workload, and keep direct control.","distractor_reasons":{"A":"Option A is correct because owners often stay small to preserve personal contact with clients, manage workload, and keep direct control.","B":"Incorrect because all businesses must pay suppliers regardless of size.","C":"Incorrect because business expansion does not cancel limited liability.","D":"Incorrect because governments do not limit the legal sales revenue of private businesses."}}},{"id":"P1_U1_MCQ_130","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_130","question":"What major risk can cause a rapidly growing business to experience financial failure (overtrading)?","options":{"A":"Accumulating excess cash reserves in business bank accounts","B":"Experiencing lower managerial coordination complexity","C":"Qualifying automatically for lower supplier purchase prices","D":"Running out of cash working capital due to buying inventory before receiving customer payment"},"correctOption":"D","correctAnswer":"Running out of cash working capital due to buying inventory before receiving customer payment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overtrading occurs when rapid sales expansion drains cash reserves to fund stock and receivables before cash is collected.","distractor_reasons":{"A":"Incorrect because overtrading depletes cash rather than building excess reserves.","B":"Incorrect because growth increases managerial complexity.","C":"Incorrect because overtrading is a liquidity crisis, not a discount benefit.","D":"Option D is correct because overtrading occurs when rapid sales expansion drains cash reserves to fund stock and receivables before cash is collected."}}},{"id":"P1_U1_MCQ_131","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_131","question":"What does unlimited liability mean for a sole trader operating a local carpentry shop?","options":{"A":"The business owner's financial liability is limited strictly to invested share capital.","B":"The business can issue shares to the general public on the stock exchange.","C":"The owner is personally responsible for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay all outstanding supplier debts if the shop goes bankrupt."},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to satisfy unpaid business debts.","distractor_reasons":{"A":"Incorrect because limiting liability to share capital describes limited companies.","B":"Incorrect because sole traders cannot issue shares.","C":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to satisfy unpaid business debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_132","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_132","question":"Nadia runs a business selling ceramic mugs as a sole trader. What is the position regarding liability for the business debts?","options":{"A":"Nadia has unlimited liability and is personally responsible for all the debts","B":"Nadia has limited liability and risks only the money invested","C":"Liability is shared equally with the government","D":"There is no liability because the business is not registered"},"correctOption":"A","correctAnswer":"Nadia has unlimited liability and is personally responsible for all the debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","distractor_reasons":{"A":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","B":"Limited liability applies to shareholders in limited companies, not to a sole trader who personally owns the business.","C":"The government does not share a sole trader's debts; the owner alone is responsible for them.","D":"Registering the business does not remove liability; a sole trader remains personally liable whether registered or not."}}},{"id":"P1_U1_MCQ_133","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_133","question":"An individual buys a franchise from a major international fast-food chain. What is a primary disadvantage experienced by this franchisee?","options":{"A":"Complete lack of established brand identity in the local market","B":"Inability to receive operational training from the franchisor","C":"Complete freedom to modify menu products without corporate approval","D":"Mandatory payment of initial license fees and ongoing revenue royalties to the franchisor"},"correctOption":"D","correctAnswer":"Mandatory payment of initial license fees and ongoing revenue royalties to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins.","distractor_reasons":{"A":"Incorrect because global franchises provide immediate brand recognition.","B":"Incorrect because franchisors provide training and operational support.","C":"Incorrect because franchisees must strictly adhere to brand standards and cannot change menus freely.","D":"Option D is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins."}}},{"id":"P1_U1_MCQ_134","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_134","question":"Two engineering companies establish a joint venture to build a renewable energy power plant. What is a major advantage of this structure?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing capital costs, operational risks, and specialized technical expertise","C":"Complete exemption from national business tax laws","D":"Total elimination of management disagreements between the two companies"},"correctOption":"B","correctAnswer":"Sharing capital costs, operational risks, and specialized technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_135","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_135","question":"Mei starts a business in Stirling with two friends, sharing ownership and management. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Public corporation"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","distractor_reasons":{"A":"A sole trader has a single owner, whereas this business has several owners sharing management.","B":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","C":"A public limited company sells shares on a stock exchange and has limited liability, unlike a simple partnership.","D":"A public corporation is government-owned and provides a public service, which is not the case here."}}},{"id":"P1_U1_MCQ_136","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_136","question":"Why might the owners of a successful partnership choose to incorporate as a Private Limited Company (LTD)?","options":{"A":"To sell company shares publicly on the national stock exchange","B":"To eliminate the legal requirement to maintain financial accounts","C":"To secure limited liability protection and access private equity capital","D":"To avoid paying any corporate income taxes on annual profits"},"correctOption":"C","correctAnswer":"To secure limited liability protection and access private equity capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors.","distractor_reasons":{"A":"Incorrect because only PLCs sell shares on public stock exchanges.","B":"Incorrect because LTDs face strict legal accounting standards.","C":"Option C is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors.","D":"Incorrect because LTDs must pay corporate profits tax."}}},{"id":"P1_U1_MCQ_137","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_137","question":"What is the meaning of limited liability for shareholders in a company?","options":{"A":"Shareholders can lose unlimited personal savings if the business goes bankrupt.","B":"The business is exempt from repaying bank loans if revenues drop.","C":"Company directors bear full personal liability for corporate debts.","D":"Shareholders' financial risk is limited strictly to the amount invested in buying shares."},"correctOption":"D","correctAnswer":"Shareholders' financial risk is limited strictly to the amount invested in buying shares.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because limited liability caps shareholder potential losses to their equity investment, protecting personal wealth.","distractor_reasons":{"A":"Incorrect because unlimited liability exposes personal wealth.","B":"Incorrect because corporate entities remain legally liable for bank debts.","C":"Incorrect because directors are protected under limited liability unless illegal actions occur.","D":"Option D is correct because limited liability caps shareholder potential losses to their equity investment, protecting personal wealth."}}},{"id":"P1_U1_MCQ_138","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_138","question":"Which legal document regulates internal rules, partner profit shares, and management duties in a partnership?","options":{"A":"Certificate of Incorporation","B":"Deed of Partnership (Partnership Agreement)","C":"Memorandum of Association","D":"Trading Standards License"},"correctOption":"B","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation registers limited companies.","B":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","C":"Incorrect because Memorandum of Association is for company formation.","D":"Incorrect because trading licenses are municipal permits."}}},{"id":"P1_U1_MCQ_139","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_139","question":"Which business organization has legal personality separate from its owners?","options":{"A":"Private Limited Company (LTD)","B":"Sole trader","C":"General partnership","D":"Unincorporated joint venture"},"correctOption":"A","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because incorporated entities like LTDs exist as separate legal persons from their owners.","distractor_reasons":{"A":"Option A is correct because incorporated entities like LTDs exist as separate legal persons from their owners.","B":"Incorrect because sole traders are unincorporated (owner and firm are legally one).","C":"Incorrect because general partnerships are unincorporated.","D":"Incorrect because unincorporated joint ventures do not possess separate legal personality."}}},{"id":"P1_U1_MCQ_140","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_140","question":"What risk does a franchisor face when licensing its business model to franchisees?","options":{"A":"The franchisor loses trademark ownership of the brand.","B":"The franchisor becomes personally liable for all franchisee debts.","C":"Poor quality or service at a single franchise store can damage overall brand reputation","D":"Franchisees are legally allowed to stop paying agreed royalties"},"correctOption":"C","correctAnswer":"Poor quality or service at a single franchise store can damage overall brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because substandard performance at one franchise store harms the overall reputation of the global brand.","distractor_reasons":{"A":"Incorrect because trademark ownership remains with the franchisor.","B":"Incorrect because franchisors are not liable for independent franchisee debts.","C":"Option C is correct because substandard performance at one franchise store harms the overall reputation of the global brand.","D":"Incorrect because franchise contracts strictly enforce royalty obligations."}}},{"id":"P1_U1_MCQ_141","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_141","question":"A new retail boutique focuses on surviving its first six months of operation. What is its primary financial concern during this initial phase?","options":{"A":"Maximizing dividend payouts to external stock market investors","B":"Achieving maximum market share across national retail markets","C":"Generating sufficient cash flow to cover daily operational costs and bills","D":"Expanding operations by opening ten new regional branches"},"correctOption":"C","correctAnswer":"Generating sufficient cash flow to cover daily operational costs and bills","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because survival depends on maintaining sufficient cash flow to satisfy immediate overhead and supplier commitments.","distractor_reasons":{"A":"Incorrect because new boutiques do not trade on stock exchanges.","B":"Incorrect because market dominance is a long-term growth goal, not an initial survival goal.","C":"Option C is correct because survival depends on maintaining sufficient cash flow to satisfy immediate overhead and supplier commitments.","D":"Incorrect because expansion is premature during early survival."}}},{"id":"P1_U1_MCQ_142","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_142","question":"How does achieving high corporate profits directly benefit shareholders of a company?","options":{"A":"By providing funds for dividend payments and increasing share valuation","B":"By reducing total annual corporate tax payments to central government","C":"By guaranteeing wage increases for all factory workers","D":"By eliminating bank interest rates on commercial debt"},"correctOption":"A","correctAnswer":"By providing funds for dividend payments and increasing share valuation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because net profit provides capital for dividend payouts and enhances company valuation for shareholders.","distractor_reasons":{"A":"Option A is correct because net profit provides capital for dividend payouts and enhances company valuation for shareholders.","B":"Incorrect because higher profits increase corporate tax liabilities.","C":"Incorrect because profit maximization does not automatically raise worker wages.","D":"Incorrect because profit levels do not alter contracted bank loan interest rates."}}},{"id":"P1_U1_MCQ_143","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_143","question":"Facing falling demand in Manchester, Bramble House Candles concentrates on covering its costs and staying in business. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","distractor_reasons":{"A":"Growth means increasing sales, output or the size of the business, which is not the priority when simply staying afloat.","B":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","C":"Profit maximisation seeks the highest profit, whereas here the firm only aims to cover its costs.","D":"Social responsibility concerns the impact on society and is not the aim described in this difficult trading situation."}}},{"id":"P1_U1_MCQ_144","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_144","question":"Which objective is typical for company employees as an internal stakeholder group?","options":{"A":"Maximizing annual corporate dividend payouts to shareholders","B":"Securing minimum product selling prices for end consumers","C":"Fair compensation, job security, and safe working conditions","D":"Minimizing local government tax collections"},"correctOption":"C","correctAnswer":"Fair compensation, job security, and safe working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employees prioritize competitive salaries, workplace safety, and job stability.","distractor_reasons":{"A":"Incorrect because dividends go to shareholders, not employees.","B":"Incorrect because product pricing concerns consumers.","C":"Option C is correct because employees prioritize competitive salaries, workplace safety, and job stability.","D":"Incorrect because government tax collection is a public sector objective."}}},{"id":"P1_U1_MCQ_145","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_145","question":"What is the primary objective of customers as external stakeholders of a consumer electronics company?","options":{"A":"Maximizing executive bonus payouts to board directors","B":"High quality products, fair prices, and reliable after-sales support","C":"Increasing local property taxes paid by the company factory","D":"Reducing total employee headcount across manufacturing plants"},"correctOption":"B","correctAnswer":"High quality products, fair prices, and reliable after-sales support","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because customers seek good value, reliable product quality, and effective customer service.","distractor_reasons":{"A":"Incorrect because executive bonuses do not benefit consumers.","B":"Option B is correct because customers seek good value, reliable product quality, and effective customer service.","C":"Incorrect because property tax levels do not concern retail customers directly.","D":"Incorrect because employee headcount cuts are internal operational matters."}}},{"id":"P1_U1_MCQ_146","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_146","question":"Which outcome represents the primary goal of raw material suppliers to a manufacturing business?","options":{"A":"Increasing local municipal taxes paid by the manufacturing factory","B":"Maximum dividend payments distributed to the manufacturer's equity holders","C":"Lowering retail selling prices for the manufacturer's final goods","D":"Regular order volumes and prompt payment according to agreed credit terms"},"correctOption":"D","correctAnswer":"Regular order volumes and prompt payment according to agreed credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers desire steady demand and timely settlement of invoices to maintain their cash flow.","distractor_reasons":{"A":"Incorrect because local taxes do not benefit raw material suppliers.","B":"Incorrect because dividends go to shareholders, not suppliers.","C":"Incorrect because final consumer prices are customer/marketing concerns.","D":"Option D is correct because suppliers desire steady demand and timely settlement of invoices to maintain their cash flow."}}},{"id":"P1_U1_MCQ_147","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_147","question":"Which objective is prioritized by the local community near a manufacturing facility?","options":{"A":"Maximizing waste dumping in nearby rivers to cut business costs","B":"Maximizing share dividends paid to foreign equity investors","C":"Replacing local staff with lower-cost offshore workers","D":"Environmental safety, local job creation, and minimal pollution"},"correctOption":"D","correctAnswer":"Environmental safety, local job creation, and minimal pollution","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local communities want clean environments, minimal disruption, and local employment opportunities.","distractor_reasons":{"A":"Incorrect because communities strongly oppose environmental pollution.","B":"Incorrect because equity dividends do not benefit local residents.","C":"Incorrect because communities prefer local employment over offshore hiring.","D":"Option D is correct because local communities want clean environments, minimal disruption, and local employment opportunities."}}},{"id":"P1_U1_MCQ_148","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_148","question":"A manufacturing firm automates its factory, replacing 40 workers with robotics to lower unit costs. Which stakeholder conflict is illustrated?","options":{"A":"Suppliers wanting prompt payment vs Customers wanting longer warranties","B":"Shareholders seeking higher profits vs Employees seeking job security","C":"Government seeking tax revenue vs Community seeking low traffic","D":"Bank lenders seeking interest vs Managers seeking larger offices"},"correctOption":"B","correctAnswer":"Shareholders seeking higher profits vs Employees seeking job security","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security.","distractor_reasons":{"A":"Incorrect because supplier payments and warranties do not involve automation redundancies.","B":"Option B is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security.","C":"Incorrect because tax revenue and community traffic are not the primary issues in factory automation.","D":"Incorrect because bank interest and director offices do not reflect automation redundancies."}}},{"id":"P1_U1_MCQ_149","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_149","question":"A haulage firm runs night delivery fleets to maximize sales growth, but local residents protest against noise pollution. Which two stakeholders are in conflict?","options":{"A":"Government and Lenders","B":"Suppliers and Customers","C":"Managers/Shareholders and Local community","D":"Tax authorities and Employees"},"correctOption":"C","correctAnswer":"Managers/Shareholders and Local community","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","distractor_reasons":{"A":"Incorrect because government and lenders are not the primary parties involved in night noise complaints.","B":"Incorrect because suppliers and customers are not in conflict over local delivery noise.","C":"Option C is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","D":"Incorrect because tax authorities are unrelated to noise pollution disputes."}}},{"id":"P1_U1_MCQ_150","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_150","question":"What is the general definition of a business stakeholder?","options":{"A":"A government official responsible for corporate tax collection","B":"An investor who owns majority voting shares in a public limited company","C":"Any person or group with a direct interest in or affected by a business's decisions and actions","D":"A financial auditor who inspects company accounting statements"},"correctOption":"C","correctAnswer":"Any person or group with a direct interest in or affected by a business's decisions and actions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a stakeholder is any individual, group, or entity with an interest in or affected by business operations.","distractor_reasons":{"A":"Incorrect because tax officials represent government, which is just one external stakeholder.","B":"Incorrect because majority shareholders are only one specific internal stakeholder group.","C":"Option C is correct because a stakeholder is any individual, group, or entity with an interest in or affected by business operations.","D":"Incorrect because financial auditors represent one specific regulatory/professional group."}}},{"id":"P1_U1_MCQ_151","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_151","question":"A furniture workshop purchases timber and metal fittings for $80 per dining chair and sells each finished chair for $200. Which change would directly increase the added value per chair by $30?","options":{"A":"Applying a premium varnish finish and increasing the selling price to $230","B":"Increasing total factory chair production volume from 50 to 80 chairs per week","C":"Reducing the hourly wage paid to the assembly line workers by $30 per day","D":"Purchasing $30 more timber stock to store in the raw material warehouse"},"correctOption":"A","correctAnswer":"Applying a premium varnish finish and increasing the selling price to $230","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value is calculated as selling price minus bought-in material costs ($200 - $80 = $120). Raising the selling price to $230 without altering raw material costs increases added value to $150 per chair, an increase of $30.","distractor_reasons":{"A":"Option A is correct because added value is calculated as selling price minus bought-in material costs ($200 - $80 = $120). Raising the selling price to $230 without altering raw material costs increases added value to $150 per chair, an increase of $30.","B":"Incorrect because increasing production volume alters overall weekly business profit potential, but does not change the added value created per individual chair.","C":"Incorrect because labor wages are an operational overhead expense rather than a raw material cost subtracted to determine unit added value.","D":"Incorrect because purchasing extra warehouse stock increases inventory assets and cash outlay, but does not increase unit added value."}}},{"id":"P1_U1_MCQ_152","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_152","question":"A baker has limited oven space and must choose between baking 40 loaves of specialty sourdough bread or 80 sweet pastries. What is the opportunity cost of choosing to bake the 80 sweet pastries?","options":{"A":"The total financial expenditure on flour and sugar for the 80 sweet pastries","B":"The 40 loaves of specialty sourdough bread that could not be produced","C":"The total sales revenue earned from selling the 80 sweet pastries to customers","D":"The electricity cost incurred while heating the baking ovens for two hours"},"correctOption":"B","correctAnswer":"The 40 loaves of specialty sourdough bread that could not be produced","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 40 sourdough loaves.","distractor_reasons":{"A":"Incorrect because raw material cost is a monetary production expenditure, not the lost product alternative.","B":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 40 sourdough loaves.","C":"Incorrect because sales revenue represents the financial benefit of the chosen option, not the alternative sacrificed.","D":"Incorrect because energy bills are overhead operational costs."}}},{"id":"P1_U1_MCQ_153","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_153","question":"A textile mill utilizes cotton crops, machine operators, industrial looms, and an entrepreneur's management skills. Which factor of production do the industrial looms represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical assets, machinery, and equipment used in the manufacturing process.","distractor_reasons":{"A":"Incorrect because land includes natural resources provided by nature, such as cotton crops.","B":"Incorrect because labour represents the human physical and mental effort contributed by workers.","C":"Option C is correct because capital consists of man-made physical assets, machinery, and equipment used in the manufacturing process.","D":"Incorrect because enterprise is the risk-taking and organizational role performed by the business owner."}}},{"id":"P1_U1_MCQ_154","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_154","question":"A smartphone manufacturer introduces specialization by assigning every assembly worker to fit a single microchip repeatedly. What is a primary limitation of this division of labor?","options":{"A":"Workers require longer training periods to master their individual assembly tasks","B":"The unit cost of purchasing raw microchips from external suppliers increases","C":"Hourly factory output of completed smartphones drops significantly","D":"Monotony can lead to worker boredom, lower morale, and increased assembly errors"},"correctOption":"D","correctAnswer":"Monotony can lead to worker boredom, lower morale, and increased assembly errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extreme specialization often results in worker boredom and fatigue, leading to lower motivation, higher absenteeism, and potential quality defects.","distractor_reasons":{"A":"Incorrect because training workers for a single narrow task is faster, not slower, than training them for full production.","B":"Incorrect because division of labor is an internal operational structure that does not affect supplier purchase prices.","C":"Incorrect because specialization typically increases output efficiency and speed per hour.","D":"Option D is correct because extreme specialization often results in worker boredom and fatigue, leading to lower motivation, higher absenteeism, and potential quality defects."}}},{"id":"P1_U1_MCQ_155","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_155","question":"Which of the following items represents a basic human need required for survival?","options":{"A":"A modern gaming laptop","B":"A subscription to a video streaming platform","C":"Clean drinking water and basic nutrition","D":"Designer branded footwear"},"correctOption":"C","correctAnswer":"Clean drinking water and basic nutrition","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clean water and basic nutrition are essential physical requirements for human survival.","distractor_reasons":{"A":"Incorrect because a gaming laptop is a technology product desired for leisure, making it a want.","B":"Incorrect because video streaming is entertainment, which is a want.","C":"Option C is correct because clean water and basic nutrition are essential physical requirements for human survival.","D":"Incorrect because designer footwear is a non-essential luxury item."}}},{"id":"P1_U1_MCQ_156","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_156","question":"What fundamental cause creates the economic problem of scarcity in all human societies?","options":{"A":"Excessive taxation imposed by central governments on commercial businesses","B":"Unlimited consumer wants exceeding limited economic resources available","C":"Low profit margins targeted by private sector retail corporations","D":"An oversupply of skilled factory workers in industrialized countries"},"correctOption":"B","correctAnswer":"Unlimited consumer wants exceeding limited economic resources available","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally arises because economic resources (land, labour, capital, enterprise) are finite while human wants are infinite.","distractor_reasons":{"A":"Incorrect because government taxation affects income distribution, but is not the root cause of resource scarcity.","B":"Option B is correct because scarcity fundamentally arises because economic resources (land, labour, capital, enterprise) are finite while human wants are infinite.","C":"Incorrect because business profit margins reflect commercial pricing strategies rather than resource availability.","D":"Incorrect because an abundance of workers reduces scarcity of that factor rather than causing general economic scarcity."}}},{"id":"P1_U1_MCQ_157","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_157","question":"A leather goods maker buys raw hides for $25 and metal buckles for $5 per belt. The finished belt is sold in retail stores for $65. What is the added value per belt?","options":{"A":"$25","B":"$30","C":"$35","D":"$65"},"correctOption":"C","correctAnswer":"$35","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs equal $25 + $5 = $30. Added value = selling price ($65) minus bought-in costs ($30) = $35.","distractor_reasons":{"A":"Incorrect because $25 is only the cost of the raw hides.","B":"Incorrect because $30 is the total bought-in raw material cost.","C":"Option C is correct because total bought-in material costs equal $25 + $5 = $30. Added value = selling price ($65) minus bought-in costs ($30) = $35.","D":"Incorrect because $65 is the final retail selling price."}}},{"id":"P1_U1_MCQ_158","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_158","question":"An engineer leaves a salaried position earning $50,000 annually to launch a private software consultancy firm. What is the opportunity cost of launching this new business?","options":{"A":"The commercial office rent paid for the consultancy's new premises","B":"The total sales revenue collected from software clients during Year 1","C":"The capital spent purchasing computer hardware and software licenses","D":"The $50,000 annual salary foregone by leaving the engineering position"},"correctOption":"D","correctAnswer":"The $50,000 annual salary foregone by leaving the engineering position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative option given up, which is the $50,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is an explicit operational business expenditure.","B":"Incorrect because client revenue is the financial gain from the chosen venture, not the foregone option.","C":"Incorrect because hardware purchases are direct capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative option given up, which is the $50,000 salary."}}},{"id":"P1_U1_MCQ_159","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_159","question":"Which factor of production includes natural assets such as crude oil deposits, fertile soil, and natural timber forests?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all gifts of nature and natural resources used in economic production.","distractor_reasons":{"A":"Option A is correct because land encompasses all gifts of nature and natural resources used in economic production.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Incorrect because capital refers to manufactured assets like machinery and factories.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_160","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_160","question":"How can a high-end coffee shop directly increase its added value per cup of coffee without raising its prices?","options":{"A":"Increasing total monthly expenditure on social media marketing campaigns","B":"Negotiating a lower purchase price for coffee beans with wholesale suppliers","C":"Increasing the hourly wage rate paid to experienced baristas","D":"Expanding the physical size of the customer seating area"},"correctOption":"B","correctAnswer":"Negotiating a lower purchase price for coffee beans with wholesale suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw coffee bean costs widens this gap without raising menu prices.","distractor_reasons":{"A":"Incorrect because advertising is an operational overhead cost, not a raw material input subtracted when determining added value.","B":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw coffee bean costs widens this gap without raising menu prices.","C":"Incorrect because raising wages increases operating expenses, lowering net profit rather than increasing unit added value.","D":"Incorrect because expanding seating increases capital expenditure and fixed overheads."}}},{"id":"P1_U1_MCQ_161","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_161","question":"Which commercial activity is classified as part of the primary economic sector?","options":{"A":"Assembling passenger motor vehicles in an automated factory","B":"Providing legal representation to business clients","C":"Extracting iron ore from underground mines","D":"Selling electronics in a city retail store"},"correctOption":"C","correctAnswer":"Extracting iron ore from underground mines","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting natural raw materials directly from the earth is a primary sector activity.","distractor_reasons":{"A":"Incorrect because assembling motor vehicles is secondary sector manufacturing.","B":"Incorrect because legal representation is a tertiary sector service.","C":"Option C is correct because extracting natural raw materials directly from the earth is a primary sector activity.","D":"Incorrect because retail selling is a tertiary sector distribution service."}}},{"id":"P1_U1_MCQ_162","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_162","question":"A country experiences deindustrialization. What pattern of structural economic change takes place?","options":{"A":"Employment shifts primarily from service industries into agricultural farming","B":"Public sector enterprises take over all privately owned retail businesses","C":"Manufacturing output doubles while tertiary service revenues decline rapidly","D":"Secondary manufacturing employment contracts while tertiary service employment expands"},"correctOption":"D","correctAnswer":"Secondary manufacturing employment contracts while tertiary service employment expands","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes the decline in the relative importance of manufacturing (secondary sector) and the relative growth of the service (tertiary) sector.","distractor_reasons":{"A":"Incorrect because primary agricultural jobs usually decline in deindustrialized economies.","B":"Incorrect because deindustrialization relates to economic sectors, not state nationalization.","C":"Incorrect because manufacturing output share declines relative to services during deindustrialization.","D":"Option D is correct because deindustrialization describes the decline in the relative importance of manufacturing (secondary sector) and the relative growth of the service (tertiary) sector."}}},{"id":"P1_U1_MCQ_163","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_163","question":"Which organisation belongs to the public sector of a mixed economy?","options":{"A":"A state-run emergency ambulance service funded by national taxes","B":"A privately owned chain of commercial fitness clubs","C":"A partnership operating an architecture consultancy firm","D":"A public limited company manufacturing pharmaceuticals"},"correctOption":"A","correctAnswer":"A state-run emergency ambulance service funded by national taxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public sector entities are owned, controlled, and financed by central or local government to provide essential services.","distractor_reasons":{"A":"Option A is correct because public sector entities are owned, controlled, and financed by central or local government to provide essential services.","B":"Incorrect because commercial fitness clubs are private sector businesses aiming for profit.","C":"Incorrect because architecture partnerships are private sector businesses.","D":"Incorrect because public limited companies (PLCs) are owned by private shareholders, not the government."}}},{"id":"P1_U1_MCQ_164","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_164","question":"A forestry company cuts down trees, a mill processes timber into wooden planks, and a furniture store sells dining tables. How are these three activities classified by sector?","options":{"A":"Forestry: Secondary; Milling: Primary; Retailing: Tertiary","B":"Forestry: Primary; Milling: Secondary; Retailing: Tertiary","C":"Forestry: Primary; Milling: Tertiary; Retailing: Secondary","D":"Forestry: Tertiary; Milling: Secondary; Retailing: Primary"},"correctOption":"B","correctAnswer":"Forestry: Primary; Milling: Secondary; Retailing: Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting down trees is primary (resource extraction), milling timber into planks is secondary (processing), and retail sales is tertiary (service).","distractor_reasons":{"A":"Incorrect because forestry is primary extraction, not secondary processing.","B":"Option B is correct because cutting down trees is primary (resource extraction), milling timber into planks is secondary (processing), and retail sales is tertiary (service).","C":"Incorrect because milling timber is secondary processing, not tertiary service.","D":"Incorrect because the order of sectors is completely inverted."}}},{"id":"P1_U1_MCQ_165","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_165","question":"What defines a mixed economy?","options":{"A":"Total state control over all factors of production and central pricing","B":"Complete absence of government taxation and economic regulation","C":"The co-existence of private sector enterprises and public sector state organizations","D":"Exclusive economic reliance on primary sector agricultural exports"},"correctOption":"C","correctAnswer":"The co-existence of private sector enterprises and public sector state organizations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a mixed economy allocates resources through both private market forces (private sector) and state intervention (public sector).","distractor_reasons":{"A":"Incorrect because total state control defines a planned or command economy.","B":"Incorrect because free market economies still have some regulation, and mixed economies have significant government intervention.","C":"Option C is correct because a mixed economy allocates resources through both private market forces (private sector) and state intervention (public sector).","D":"Incorrect because mixed economies operate across all three economic sectors."}}},{"id":"P1_U1_MCQ_166","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_166","question":"Which activity operates exclusively within the tertiary economic sector?","options":{"A":"Coal mining","B":"Aircraft manufacturing","C":"Wheat harvesting","D":"Commercial banking"},"correctOption":"D","correctAnswer":"Commercial banking","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because commercial banking provides financial services to individuals and businesses, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because coal mining is primary sector resource extraction.","B":"Incorrect because manufacturing aircraft is secondary sector production.","C":"Incorrect because harvesting wheat is primary sector agriculture.","D":"Option D is correct because commercial banking provides financial services to individuals and businesses, placing it in the tertiary sector."}}},{"id":"P1_U1_MCQ_167","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_167","question":"What is the primary driving motive for private sector business owners in a market economy?","options":{"A":"Generating profit to provide a financial return on invested capital","B":"Meeting production quotas established by central government planners","C":"Providing free public services to local municipal residents","D":"Maximizing annual corporate tax payments to central government"},"correctOption":"A","correctAnswer":"Generating profit to provide a financial return on invested capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the primary goal of private sector business ownership is making profit for owners/shareholders.","distractor_reasons":{"A":"Option A is correct because the primary goal of private sector business ownership is making profit for owners/shareholders.","B":"Incorrect because production quotas are features of state-planned economies.","C":"Incorrect because providing free public goods is a public sector objective.","D":"Incorrect because private firms view tax as a cost to manage legally, not an objective to maximize."}}},{"id":"P1_U1_MCQ_168","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_168","question":"Why might a national government choose to privatize a state-owned telecommunications company?","options":{"A":"To increase direct state control over consumer pricing tariffs","B":"To introduce market competition, profit incentives, and operational efficiency","C":"To guarantee permanent employment security for civil service workers","D":"To eliminate private capital investment in national infrastructure"},"correctOption":"B","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, bringing market competition and profit motives that tend to improve efficiency.","distractor_reasons":{"A":"Incorrect because privatization reduces direct state control.","B":"Option B is correct because privatization transfers state assets to private owners, bringing market competition and profit motives that tend to improve efficiency.","C":"Incorrect because privatized businesses often restructure and cut redundant staff.","D":"Incorrect because privatization invites private capital investment."}}},{"id":"P1_U1_MCQ_169","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_169","question":"Which option correctly pairs an economic activity with its corresponding sector?","options":{"A":"Dairy farming - Secondary sector","B":"Car assembly - Primary sector","C":"Hotel management - Tertiary sector","D":"Iron mining - Tertiary sector"},"correctOption":"C","correctAnswer":"Hotel management - Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hotel management provides hospitality services, which is a tertiary sector activity.","distractor_reasons":{"A":"Incorrect because dairy farming is primary sector agriculture.","B":"Incorrect because car assembly is secondary sector manufacturing.","C":"Option C is correct because hotel management provides hospitality services, which is a tertiary sector activity.","D":"Incorrect because iron mining is primary sector resource extraction."}}},{"id":"P1_U1_MCQ_170","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_170","question":"What structural employment shift occurs as a developing nation undergoes rapid industrialization?","options":{"A":"Workers move out of secondary manufacturing into primary farming","B":"Tertiary sector service businesses close down completely","C":"Public sector ownership expands to absorb 100% of all private firms","D":"Workers shift from primary agriculture into secondary manufacturing"},"correctOption":"D","correctAnswer":"Workers shift from primary agriculture into secondary manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization is defined by the growth of factory manufacturing, pulling labor from primary agriculture into secondary production.","distractor_reasons":{"A":"Incorrect because workers move from agriculture into manufacturing, not the reverse.","B":"Incorrect because service industries expand alongside industrial development.","C":"Incorrect because industrialization is a sectoral economic change, not total state nationalization.","D":"Option D is correct because industrialization is defined by the growth of factory manufacturing, pulling labor from primary agriculture into secondary production."}}},{"id":"P1_U1_MCQ_171","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_171","question":"Which trait is essential for an entrepreneur launching an innovative start-up venture?","options":{"A":"Willingness to take calculated risks and resilience when encountering failure","B":"Preference for working under direct managerial supervision","C":"Reluctance to adapt business strategies to changing market trends","D":"Avoidance of personal financial responsibility for business liabilities"},"correctOption":"A","correctAnswer":"Willingness to take calculated risks and resilience when encountering failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because successful entrepreneurs must be risk-takers who persevere and adapt when facing business obstacles.","distractor_reasons":{"A":"Option A is correct because successful entrepreneurs must be risk-takers who persevere and adapt when facing business obstacles.","B":"Incorrect because entrepreneurs are self-directed leaders rather than supervised employees.","C":"Incorrect because adaptability is crucial to entrepreneurial survival.","D":"Incorrect because entrepreneurs actively manage and bear financial risks."}}},{"id":"P1_U1_MCQ_172","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_172","question":"Why is a formal business plan vital when applying for a commercial bank loan?","options":{"A":"It legally exempts the business owner from paying corporate income taxes","B":"It presents financial projections and cash flow forecasts to demonstrate repayment ability","C":"It guarantees that the start-up will earn a profit within its first quarter","D":"It replaces official business incorporation documents required by law"},"correctOption":"B","correctAnswer":"It presents financial projections and cash flow forecasts to demonstrate repayment ability","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because banks examine financial plans to assess revenue potential, cash flow viability, and loan default risk.","distractor_reasons":{"A":"Incorrect because a business plan has no legal bearing on tax obligations.","B":"Option B is correct because banks examine financial plans to assess revenue potential, cash flow viability, and loan default risk.","C":"Incorrect because business plans present forecasts, not profit guarantees.","D":"Incorrect because business registration is a statutory legal requirement independent of planning."}}},{"id":"P1_U1_MCQ_173","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_173","question":"Which metric is a valid method for measuring and comparing business size?","options":{"A":"Total net profit earned at year-end","B":"The unit selling price of flagship products","C":"Capital employed in the business","D":"Percentage markup applied to raw material costs"},"correctOption":"C","correctAnswer":"Capital employed in the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term funds invested) is a standard metric for measuring business size.","distractor_reasons":{"A":"Incorrect because profit is explicitly NOT a valid size measure (a small firm can earn higher profit than a large inefficient firm).","B":"Incorrect because unit price reflects product positioning, not scale.","C":"Option C is correct because capital employed (total long-term funds invested) is a standard metric for measuring business size.","D":"Incorrect because markup percentage reflects pricing strategy, not company size."}}},{"id":"P1_U1_MCQ_174","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_174","question":"What is the most likely immediate cause of failure for a newly established business such as Rosewood Ceramics?","options":{"A":"Sustained cash-flow shortages leaving it unable to pay bills when due","B":"Having too few customers relative to its production capacity","C":"Unable to obtain any market research data","D":"Paying dividends to shareholders"},"correctOption":"A","correctAnswer":"Sustained cash-flow shortages leaving it unable to pay bills when due","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","distractor_reasons":{"A":"Option A is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","B":"Too few customers is a symptom of weak demand, but the immediate trigger of failure is usually the resulting cash shortage.","C":"A lack of market research raises risk but does not by itself prevent a business from trading.","D":"Paying dividends is a choice made from profits and is not a typical cause of a new business failing."}}},{"id":"P1_U1_MCQ_175","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_175","question":"Why do governments provide grants and low-cost loans to new business start-ups?","options":{"A":"To create new jobs, stimulate economic growth, and foster innovation","B":"To eliminate competition for established state-owned enterprises","C":"To force small businesses to convert into public limited companies","D":"To prevent foreign companies from trading in domestic markets"},"correctOption":"A","correctAnswer":"To create new jobs, stimulate economic growth, and foster innovation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government support for start-ups aims to lower unemployment, spur economic activity, and encourage innovation.","distractor_reasons":{"A":"Option A is correct because government support for start-ups aims to lower unemployment, spur economic activity, and encourage innovation.","B":"Incorrect because governments support start-ups to increase market competition, not eliminate it.","C":"Incorrect because government grants do not force companies to change legal structures.","D":"Incorrect because start-up assistance focuses on domestic enterprise growth, not trade protectionism."}}},{"id":"P1_U1_MCQ_176","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_176","question":"In the Midlands, which measure is most likely to be used by a government to support people starting new businesses?","options":{"A":"Grants or low-interest loans specifically for start-ups","B":"Higher taxes on all new firms","C":"A ban on selling to overseas customers","D":"Requiring every start-up to become a public limited company"},"correctOption":"A","correctAnswer":"Grants or low-interest loans specifically for start-ups","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","distractor_reasons":{"A":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","B":"Higher taxes would discourage rather than help new businesses by reducing their available funds.","C":"Banning overseas sales would restrict market access and hinder the growth of new firms.","D":"Start-ups are not required to become public limited companies; many begin as sole traders or private limited companies."}}},{"id":"P1_U1_MCQ_177","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_177","question":"Which limitation applies when measuring business size by the number of employees?","options":{"A":"Employee numbers cannot be calculated for service sector firms","B":"It is illegal to record worker numbers under commercial law","C":"A highly automated, capital-intensive factory may employ few staff but produce immense output","D":"Employee headcount changes every hour during normal operations"},"correctOption":"C","correctAnswer":"A highly automated, capital-intensive factory may employ few staff but produce immense output","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employee headcount misleads when comparing capital-intensive automated firms with labor-intensive firms.","distractor_reasons":{"A":"Incorrect because headcount is standardly measured across service firms.","B":"Incorrect because reporting headcount is standard business practice.","C":"Option C is correct because employee headcount misleads when comparing capital-intensive automated firms with labor-intensive firms.","D":"Incorrect because worker numbers are measured by contracted employment headcount, not hourly shifts."}}},{"id":"P1_U1_MCQ_178","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_178","question":"Why might the owner of a boutique craft shop choose to remain small despite strong customer demand?","options":{"A":"Small businesses are exempt from paying supplier invoices","B":"Large companies are legally banned from selling craft goods","C":"The firm will lose its limited liability status if it expands","D":"The owner wishes to maintain personal control and offer personalized customer service"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal control and offer personalized customer service","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners frequently remain small to preserve personal management control, work-life balance, and close customer relationships.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because large firms sell craft goods extensively.","C":"Incorrect because growth does not alter limited liability status.","D":"Option D is correct because business owners frequently remain small to preserve personal management control, work-life balance, and close customer relationships."}}},{"id":"P1_U1_MCQ_179","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_179","question":"Kingsway Motors and an overseas company create a jointly owned business in Cardiff to share costs and expertise. What is this arrangement called?","options":{"A":"A sole trader business","B":"A joint venture","C":"Internal growth","D":"A franchise"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","distractor_reasons":{"A":"A sole trader business has a single owner, which is the opposite of a jointly owned venture.","B":"Option B is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","C":"Internal growth is expansion from within; here two separate firms combine resources externally.","D":"A franchise involves one party paying to use another's brand and system, not creating a jointly owned company."}}},{"id":"P1_U1_MCQ_180","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_180","question":"Rather than buying another firm, Silverdale Foods develops and launches artisan sourdough loaves using its own research team and spare cash. What type of growth is this?","options":{"A":"Backward vertical integration","B":"External takeover","C":"Internal (organic) growth","D":"Horizontal integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","distractor_reasons":{"A":"Backward vertical integration requires acquiring a supplier, which has not happened here.","B":"An external takeover means buying another business; this firm grew without acquiring one.","C":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","D":"Horizontal integration involves combining with another firm at the same stage of an industry."}}},{"id":"P1_U1_MCQ_181","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_181","question":"What does unlimited liability mean for a sole trader operating a convenience store?","options":{"A":"The owner is legally protected from any customer injury lawsuits.","B":"The store can issue shares to the public on the stock exchange.","C":"The owner is personally responsible for all business debts, risking personal assets.","D":"The bank guarantees to pay supplier debts if the store fails."},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, risking personal assets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means there is no legal distinction between the owner and the business; personal assets can be taken to satisfy unpaid business debts.","distractor_reasons":{"A":"Incorrect because sole traders have no liability shield against lawsuits.","B":"Incorrect because sole traders cannot issue shares.","C":"Option C is correct because unlimited liability means there is no legal distinction between the owner and the business; personal assets can be taken to satisfy unpaid business debts.","D":"Incorrect because banks do not pay business debts on behalf of owners."}}},{"id":"P1_U1_MCQ_182","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_182","question":"Northwind Toys is a private limited company. What does limited liability mean for its shareholders?","options":{"A":"They are responsible for all company debts with their personal property","B":"They can only lose the amount they invested in shares and no more","C":"They are forbidden from selling their shares to anyone else","D":"They receive a guaranteed annual salary from the company"},"correctOption":"B","correctAnswer":"They can only lose the amount they invested in shares and no more","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","distractor_reasons":{"A":"Personal property is only at risk for owners with unlimited liability such as sole traders and ordinary partners.","B":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","C":"Shareholders in a private limited company may sell shares, subject to any restrictions in the company's rules.","D":"Shareholders are not employees and have no automatic right to a salary; they may receive dividends if profits allow."}}},{"id":"P1_U1_MCQ_183","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_183","question":"An individual buys a franchise from a major fast-food brand. What is a primary disadvantage faced by this franchisee?","options":{"A":"Paying initial franchise fees and ongoing royalties on sales revenue","B":"Complete absence of brand recognition in the local consumer market","C":"Complete freedom to alter food recipes without corporate permission","D":"Inability to obtain staff training from the parent company"},"correctOption":"A","correctAnswer":"Paying initial franchise fees and ongoing royalties on sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront license fees and ongoing royalties to the franchisor, reducing net profits.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront license fees and ongoing royalties to the franchisor, reducing net profits.","B":"Incorrect because established franchises provide strong initial brand recognition.","C":"Incorrect because franchisees are strictly bound by franchisor rules and cannot alter products.","D":"Incorrect because franchisors provide comprehensive training and operational support."}}},{"id":"P1_U1_MCQ_184","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_184","question":"Two tech companies form a joint venture to build a new software platform. What is a major advantage of this arrangement?","options":{"A":"A permanent merger creating a single unified corporation","B":"Shared risks, development costs, and complementary expertise","C":"Automatic exemption from all national business taxes","D":"Total elimination of management disagreements between partners"},"correctOption":"B","correctAnswer":"Shared risks, development costs, and complementary expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because joint ventures allow separate firms to pool resources and expertise for a specific project while sharing risks and costs.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary collaborative projects, not full mergers.","B":"Option B is correct because joint ventures allow separate firms to pool resources and expertise for a specific project while sharing risks and costs.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because friction between joint venture partners is a common risk."}}},{"id":"P1_U1_MCQ_185","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_185","question":"Which feature distinguishes a public limited company such as Ridgeview Winery from a private limited company?","options":{"A":"Its shares can be bought and sold on a stock exchange","B":"Its owners have unlimited liability for all debts","C":"It must be owned by exactly one person","D":"It cannot employ any staff"},"correctOption":"A","correctAnswer":"Its shares can be bought and sold on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","distractor_reasons":{"A":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","B":"Both private and public limited companies give shareholders limited liability, so this is not a distinguishing feature.","C":"A public limited company needs at least two shareholders and cannot be owned by a single person in the way described.","D":"Public limited companies employ staff just like other business organisations, so this is not a distinguishing feature."}}},{"id":"P1_U1_MCQ_186","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_186","question":"Two accountants establish an accounting firm as a general partnership. What is a primary disadvantage of this business structure?","options":{"A":"Inability to pool financial capital from more than one person","B":"Legal requirement to publish full annual accounts publicly","C":"Heavy legal restrictions against hiring additional employees","D":"Unintended joint liability for debts incurred by the other partner"},"correctOption":"D","correctAnswer":"Unintended joint liability for debts incurred by the other partner","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in a general partnership, partners share unlimited liability jointly, meaning one partner is liable for business debts created by another partner.","distractor_reasons":{"A":"Incorrect because partnerships pool capital from multiple partners.","B":"Incorrect because general partnerships do not publish accounts publicly.","C":"Incorrect because partnerships can hire employees freely.","D":"Option D is correct because in a general partnership, partners share unlimited liability jointly, meaning one partner is liable for business debts created by another partner."}}},{"id":"P1_U1_MCQ_187","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_187","question":"Why might the owner of an expanding sole trader business convert it into a Private Limited Company (LTD)?","options":{"A":"To secure limited liability protection and raise capital from private investors","B":"To sell shares directly to the general public on the stock exchange","C":"To avoid paying any corporate taxation on annual profits","D":"To eliminate the requirement to maintain financial accounting records"},"correctOption":"A","correctAnswer":"To secure limited liability protection and raise capital from private investors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because converting to an LTD protects personal assets via limited liability and allows selling shares to chosen private investors.","distractor_reasons":{"A":"Option A is correct because converting to an LTD protects personal assets via limited liability and allows selling shares to chosen private investors.","B":"Incorrect because only PLCs (not LTDs) sell shares to the general public.","C":"Incorrect because LTDs must pay corporate profits tax.","D":"Incorrect because LTDs face strict accounting record-keeping laws."}}},{"id":"P1_U1_MCQ_188","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_188","question":"What does limited liability mean for shareholders in a company?","options":{"A":"Shareholders can lose an unlimited amount of personal wealth if the firm fails.","B":"Shareholders' financial loss is restricted to the amount invested in buying shares.","C":"The company is exempt from paying debts owed to bank lenders.","D":"Company directors are personally liable for paying all corporate taxes."},"correctOption":"B","correctAnswer":"Shareholders' financial loss is restricted to the amount invested in buying shares.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability restricts a shareholder's financial loss to their invested share capital; personal wealth cannot be seized.","distractor_reasons":{"A":"Incorrect because unlimited liability exposes personal wealth.","B":"Option B is correct because limited liability restricts a shareholder's financial loss to their invested share capital; personal wealth cannot be seized.","C":"Incorrect because the company entity remains liable for its bank debts.","D":"Incorrect because directors are not personally liable under limited liability unless fraud occurs."}}},{"id":"P1_U1_MCQ_189","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_189","question":"Which advantage does a franchisor gain when expanding through a franchise model?","options":{"A":"Total absorption of all local store operational risks by the franchisor","B":"Guaranteed 100% profit retention from all individual franchise stores","C":"Rapid business expansion funded mostly by capital provided by franchisees","D":"Exemption from protecting registered trademarks and brand identity"},"correctOption":"C","correctAnswer":"Rapid business expansion funded mostly by capital provided by franchisees","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the franchisor expands the retail network quickly using investment capital supplied by franchisees.","distractor_reasons":{"A":"Incorrect because franchisees assume local operational risks.","B":"Incorrect because franchisees retain store operating profits after paying royalties.","C":"Option C is correct because the franchisor expands the retail network quickly using investment capital supplied by franchisees.","D":"Incorrect because franchisors must protect their trademarks."}}},{"id":"P1_U1_MCQ_190","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_190","question":"What risk do founding shareholders of a Public Limited Company (PLC) face during an aggressive takeover attempt?","options":{"A":"They will be forced to take personal liability for company loans","B":"Their personal bank accounts will be seized by the acquiring company","C":"The company will automatically be converted into a sole trader","D":"Founding owners may lose strategic voting control of the company"},"correctOption":"D","correctAnswer":"Founding owners may lose strategic voting control of the company","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PLC shares are publicly traded; external investors can acquire a majority stake, causing original owners to lose control.","distractor_reasons":{"A":"Incorrect because PLC shareholders retain limited liability.","B":"Incorrect because personal assets are separate from corporate shares.","C":"Incorrect because corporate takeovers do not convert PLCs into sole traders.","D":"Option D is correct because PLC shares are publicly traded; external investors can acquire a majority stake, causing original owners to lose control."}}},{"id":"P1_U1_MCQ_191","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_191","question":"During its first year of operation, a startup cafe focuses primarily on earning enough cash revenue to pay rent and supplier bills. Which objective does this reflect?","options":{"A":"Survival","B":"Market share dominance","C":"Rapid international expansion","D":"Profit maximization"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because survival is the main short-term goal for new start-ups during their vulnerable initial operating period.","distractor_reasons":{"A":"Option A is correct because survival is the main short-term goal for new start-ups during their vulnerable initial operating period.","B":"Incorrect because market share dominance is a long-term growth objective.","C":"Incorrect because international expansion comes after established domestic success.","D":"Incorrect because profit maximization is realistic only after survival is secured."}}},{"id":"P1_U1_MCQ_192","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_192","question":"A public limited company maximizes net profits at year-end. How does achieving this objective directly benefit shareholders?","options":{"A":"It guarantees immediate reduction in factory employee wages","B":"It enables higher dividend payouts and increases share value","C":"It exempts the company from paying corporate profit taxes","D":"It forces suppliers to extend interest-free trade credit"},"correctOption":"B","correctAnswer":"It enables higher dividend payouts and increases share value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher net profit provides funds for dividend distribution and drives share valuation.","distractor_reasons":{"A":"Incorrect because profit maximization does not guarantee wage cuts.","B":"Option B is correct because higher net profit provides funds for dividend distribution and drives share valuation.","C":"Incorrect because higher profits increase corporate tax liabilities.","D":"Incorrect because supplier credit depends on negotiation, not profit level."}}},{"id":"P1_U1_MCQ_193","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_193","question":"Why might an established retail company set a business objective of growth and market expansion?","options":{"A":"To increase fixed costs per unit produced","B":"To decrease total annual sales revenue","C":"To gain economies of scale and improve competitive market position","D":"To eliminate the need for operational managers"},"correctOption":"C","correctAnswer":"To gain economies of scale and improve competitive market position","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because business growth allows firms to achieve economies of scale, reducing average unit costs and raising competitiveness.","distractor_reasons":{"A":"Incorrect because growth aims to lower average unit costs through scale economies.","B":"Incorrect because expansion aims to increase total sales revenue.","C":"Option C is correct because business growth allows firms to achieve economies of scale, reducing average unit costs and raising competitiveness.","D":"Incorrect because larger firms require more management structure."}}},{"id":"P1_U1_MCQ_194","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_194","question":"Oakfield Furniture wants to raise its percentage of total industry sales in the coming year. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Increasing market share","D":"Cost minimisation alone"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","distractor_reasons":{"A":"Profit maximisation targets the largest profit, which may not coincide with selling a larger share of the market.","B":"Survival is about covering costs and continuing to trade rather than winning a greater share of sales.","C":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","D":"Cost minimisation concerns reducing expenses and does not directly describe gaining a larger share of industry sales."}}},{"id":"P1_U1_MCQ_195","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_195","question":"Riverbend Textiles aims to sell as many units as possible, even if profit per unit is low. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Social enterprise","D":"Sales revenue maximisation"},"correctOption":"D","correctAnswer":"Sales revenue maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","distractor_reasons":{"A":"Profit maximisation would not knowingly accept low profit per unit in order to boost sales volume.","B":"Survival only requires covering costs, whereas this firm deliberately pursues a high volume of sales.","C":"A social enterprise reinvests profits for a social purpose, which is different from maximising sales revenue.","D":"Option D is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins."}}},{"id":"P1_U1_MCQ_196","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_196","question":"What is a primary objective for factory workers as an internal stakeholder group?","options":{"A":"Maximizing annual dividend payouts to equity investors","B":"Job security, fair wages, and safe working conditions","C":"Higher interest rate returns on company bank loans","D":"Lowering selling prices of products sold to consumers"},"correctOption":"B","correctAnswer":"Job security, fair wages, and safe working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because employees prioritize fair pay, safe working environments, and job stability.","distractor_reasons":{"A":"Incorrect because dividends go to shareholders, not factory workers.","B":"Option B is correct because employees prioritize fair pay, safe working environments, and job stability.","C":"Incorrect because interest returns concern bank lenders.","D":"Incorrect because product pricing is a customer concern."}}},{"id":"P1_U1_MCQ_197","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_197","question":"A business in Devon, founded by Grace, reinvests its surplus to tackle a social or environmental problem. What is this business called?","options":{"A":"A social enterprise","B":"A public corporation","C":"A sole trader focused only on profit","D":"A franchise"},"correctOption":"A","correctAnswer":"A social enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","distractor_reasons":{"A":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","B":"A public corporation is government-owned and provides public services, which is different from a mission-led trading business.","C":"A profit-only sole trader does not reinvest surpluses specifically to address a social or environmental problem.","D":"A franchise uses another firm's brand and system and is not defined by a social reinvestment purpose."}}},{"id":"P1_U1_MCQ_198","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_198","question":"What is the main objective of customers as external stakeholders of a retail business?","options":{"A":"Maximizing executive salary payments to company directors","B":"Reducing the business's total employee headcount","C":"Maximizing tax liabilities paid by the business to government","D":"High quality goods, fair prices, and reliable customer service"},"correctOption":"D","correctAnswer":"High quality goods, fair prices, and reliable customer service","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because customers want value for money, good service, and reliable quality.","distractor_reasons":{"A":"Incorrect because executive salaries do not benefit consumers.","B":"Incorrect because reducing headcount can worsen customer service.","C":"Incorrect because tax levels are not a customer priority.","D":"Option D is correct because customers want value for money, good service, and reliable quality."}}},{"id":"P1_U1_MCQ_199","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_199","question":"Which objective is prioritized by suppliers selling raw materials to a factory?","options":{"A":"Regular order volumes and prompt payment according to credit terms","B":"High dividend payouts paid out to the factory's shareholders","C":"Lowering the factory's end-product retail selling prices","D":"Increasing local municipal taxes paid by the factory"},"correctOption":"A","correctAnswer":"Regular order volumes and prompt payment according to credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suppliers want predictable ongoing purchases and timely payment for goods supplied.","distractor_reasons":{"A":"Option A is correct because suppliers want predictable ongoing purchases and timely payment for goods supplied.","B":"Incorrect because factory dividends go to shareholders, not suppliers.","C":"Incorrect because end-product prices are consumer concerns.","D":"Incorrect because municipal taxes do not benefit raw material suppliers."}}},{"id":"P1_U1_MCQ_200","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_200","question":"What is the primary objective of a commercial bank that grants a long-term loan to a business?","options":{"A":"Guaranteeing full employment for the borrowing firm's workforce","B":"Prompt payment of interest and eventual full repayment of loan principal","C":"Maximizing retail sales volume in the borrowing firm's shops","D":"Eliminating all legal contracts between the firm and its customers"},"correctOption":"B","correctAnswer":"Prompt payment of interest and eventual full repayment of loan principal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders prioritize receiving interest payments on schedule and securing full debt repayment.","distractor_reasons":{"A":"Incorrect because workforce employment levels are employee/government concerns.","B":"Option B is correct because bank lenders prioritize receiving interest payments on schedule and securing full debt repayment.","C":"Incorrect because banks care about sales only to the extent that it affects loan repayment.","D":"Incorrect because legal contracts protect business operations."}}},{"id":"P1_U1_MCQ_201","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_201","question":"A leather wallet maker purchases raw leather for $15 and metal clips for $3 per wallet. The finished wallets are sold for $48 each. Which action will directly increase the added value per wallet by $5?","options":{"A":"Improving the brand packaging and increasing the retail price to $53","B":"Increasing total factory daily output from 40 wallets to 60 wallets","C":"Paying workers an extra $5 per hour during overtime shifts","D":"Purchasing $5 worth of additional leather stock to keep in inventory"},"correctOption":"A","correctAnswer":"Improving the brand packaging and increasing the retail price to $53","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value is calculated as selling price minus raw material costs ($48 - $18 = $30). Increasing the price to $53 without changing raw material costs raises added value to $35 ($5 increase).","distractor_reasons":{"A":"Option A is correct because added value is calculated as selling price minus raw material costs ($48 - $18 = $30). Increasing the price to $53 without changing raw material costs raises added value to $35 ($5 increase).","B":"Incorrect because increasing daily output volume alters total daily profit potential, not unit added value.","C":"Incorrect because labor wages are overhead operating expenses, not bought-in material costs subtracted in added value calculations.","D":"Incorrect because storing extra raw material inventory increases stock assets, but does not alter unit added value."}}},{"id":"P1_U1_MCQ_202","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_202","question":"A farmer has enough land to cultivate either 100 tonnes of wheat or 60 tonnes of barley. If the farmer decides to grow 60 tonnes of barley, what is the opportunity cost?","options":{"A":"The financial cost of fertilizer and seeds required for barley production","B":"The 100 tonnes of wheat that could have been cultivated instead","C":"The sales revenue earned from selling the 60 tonnes of barley","D":"The diesel fuel expense incurred operating harvesting machinery"},"correctOption":"B","correctAnswer":"The 100 tonnes of wheat that could have been cultivated instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 100 tonnes of wheat.","distractor_reasons":{"A":"Incorrect because seed and fertilizer costs are direct monetary production costs.","B":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 100 tonnes of wheat.","C":"Incorrect because revenue is the financial gain of the chosen decision, not the foregone alternative.","D":"Incorrect because machinery fuel represents an operating cost."}}},{"id":"P1_U1_MCQ_203","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_203","question":"A manufacturing company utilizes crude oil, chemical technicians, automated robotic arms, and a factory director. Which factor of production do the automated robotic arms represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical tools, equipment, and machinery used to manufacture goods.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like crude oil.","B":"Incorrect because labour refers to human physical and mental work.","C":"Option C is correct because capital consists of man-made physical tools, equipment, and machinery used to manufacture goods.","D":"Incorrect because enterprise is the risk-taking and business organization function."}}},{"id":"P1_U1_MCQ_204","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_204","question":"An automobile manufacturer introduces extreme specialization by assigning each worker on the assembly line to install windshield wipers exclusively. What is a primary drawback of this division of labor?","options":{"A":"Workers require much longer training periods to learn their specific assembly step","B":"The purchase price of raw windshield wipers from suppliers increases","C":"Total hourly output of assembled cars per factory line decreases","D":"Task repetition causes worker boredom, low morale, and potential quality flaws"},"correctOption":"D","correctAnswer":"Task repetition causes worker boredom, low morale, and potential quality flaws","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single limited task continuously leads to monotony, lowering motivation and increasing quality errors.","distractor_reasons":{"A":"Incorrect because training a worker for a single simple task is fast and straightforward.","B":"Incorrect because division of labor is an internal workflow process and does not affect supplier pricing.","C":"Incorrect because specialization generally speeds up assembly and increases hourly output.","D":"Option D is correct because repeating a single limited task continuously leads to monotony, lowering motivation and increasing quality errors."}}},{"id":"P1_U1_MCQ_205","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_205","question":"Which of the following items represents a basic human need necessary for survival?","options":{"A":"Protection from extreme weather through basic clothing","B":"A subscription to an online streaming service","C":"An expensive sports car","D":"A luxury overseas vacation"},"correctOption":"A","correctAnswer":"Protection from extreme weather through basic clothing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because basic clothing and shelter are fundamental physical requirements for human survival.","distractor_reasons":{"A":"Option A is correct because basic clothing and shelter are fundamental physical requirements for human survival.","B":"Incorrect because streaming subscriptions are entertainment, which is a want.","C":"Incorrect because a sports car is a non-essential luxury item.","D":"Incorrect because luxury travel is a lifestyle want."}}},{"id":"P1_U1_MCQ_206","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_206","question":"Why does the economic problem of scarcity affect all societies regardless of their level of wealth?","options":{"A":"Governments enforce strict price ceilings on basic consumer goods","B":"Finite economic resources cannot satisfy unlimited human needs and wants","C":"Private companies deliberately restrict production to raise profit margins","D":"Excess supply of skilled labor reduces overall factory productivity"},"correctOption":"B","correctAnswer":"Finite economic resources cannot satisfy unlimited human needs and wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity occurs because limited factors of production cannot fulfill infinite human wants.","distractor_reasons":{"A":"Incorrect because price ceilings are regulatory policies, not the fundamental cause of scarcity.","B":"Option B is correct because scarcity occurs because limited factors of production cannot fulfill infinite human wants.","C":"Incorrect because corporate profit strategies do not cause economic resource scarcity.","D":"Incorrect because an excess supply of labor reduces scarcity of that factor rather than causing general economic scarcity."}}},{"id":"P1_U1_MCQ_207","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_207","question":"A commercial print shop buys paper for $10 and ink for $4 per customized poster. The finished poster is sold to clients for $40. What is the added value per poster?","options":{"A":"$14","B":"$30","C":"$26","D":"$40"},"correctOption":"C","correctAnswer":"$26","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in component costs equal $10 + $4 = $14. Added value = selling price ($40) minus material costs ($14) = $26.","distractor_reasons":{"A":"Incorrect because $14 is the total material cost.","B":"Incorrect because $30 subtracts only paper cost ($40 - $10), ignoring ink costs.","C":"Option C is correct because total bought-in component costs equal $10 + $4 = $14. Added value = selling price ($40) minus material costs ($14) = $26.","D":"Incorrect because $40 is the final selling price."}}},{"id":"P1_U1_MCQ_208","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_208","question":"A manager leaves a corporate job paying $60,000 per year to open an independent coffee shop. What is the opportunity cost of establishing this new business?","options":{"A":"The monthly rental payment for the shop premises","B":"The total sales revenue generated from coffee sales in Year 1","C":"The money spent purchasing espresso machines and grinders","D":"The $60,000 corporate salary sacrificed by leaving the employment"},"correctOption":"D","correctAnswer":"The $60,000 corporate salary sacrificed by leaving the employment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed benefit of the foregone alternative, which is the $60,000 annual salary.","distractor_reasons":{"A":"Incorrect because rent is an operational monetary expenditure.","B":"Incorrect because revenue is the gain from the chosen option, not the sacrificed alternative.","C":"Incorrect because machine purchases are direct capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed benefit of the foregone alternative, which is the $60,000 annual salary."}}},{"id":"P1_U1_MCQ_209","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_209","question":"Which factor of production encompasses natural resources such as copper ore, fertile farmland, and natural gas deposits?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all natural resources provided by nature used in economic output.","distractor_reasons":{"A":"Option A is correct because land covers all natural resources provided by nature used in economic output.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Incorrect because capital refers to man-made assets such as equipment and infrastructure.","D":"Incorrect because enterprise is the risk-taking business organization function."}}},{"id":"P1_U1_MCQ_210","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_210","question":"How can a custom shoe maker directly increase the added value of its shoes without raising the final retail selling price?","options":{"A":"Increasing monthly spending on local billboard advertising","B":"Securing lower purchase prices for raw leather inputs from suppliers","C":"Increasing hourly wage rates for workshop shoe craftsmen","D":"Leasing a larger storage facility for excess raw materials"},"correctOption":"B","correctAnswer":"Securing lower purchase prices for raw leather inputs from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus raw material costs. Reducing raw material input costs widens the added value gap.","distractor_reasons":{"A":"Incorrect because billboard advertising is an operational overhead expense, not a raw material input.","B":"Option B is correct because added value equals selling price minus raw material costs. Reducing raw material input costs widens the added value gap.","C":"Incorrect because higher wages raise operating expenses, lowering profit rather than unit added value.","D":"Incorrect because leasing larger storage increases fixed overhead costs."}}},{"id":"P1_U1_MCQ_211","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_211","question":"Which activity is categorized within the primary economic sector?","options":{"A":"Manufacturing electronic components in a high-tech factory","B":"Offering financial auditing services to corporate clients","C":"Drilling for offshore crude oil and natural gas","D":"Operating a supermarket retail grocery store"},"correctOption":"C","correctAnswer":"Drilling for offshore crude oil and natural gas","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting natural resources directly from nature is a primary sector activity.","distractor_reasons":{"A":"Incorrect because electronic component manufacturing belongs to the secondary sector.","B":"Incorrect because auditing is a tertiary sector professional service.","C":"Option C is correct because extracting natural resources directly from nature is a primary sector activity.","D":"Incorrect because supermarket retailing is a tertiary sector distribution service."}}},{"id":"P1_U1_MCQ_212","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_212","question":"What structural employment change characterizes a country undergoing deindustrialization?","options":{"A":"A rapid movement of workers from service industries into agricultural farming","B":"A major expansion of state ownership across all commercial businesses","C":"A doubling of factory output alongside shrinking tertiary service revenues","D":"A decline in secondary manufacturing jobs and expansion in tertiary service jobs"},"correctOption":"D","correctAnswer":"A decline in secondary manufacturing jobs and expansion in tertiary service jobs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization involves a relative decline in secondary manufacturing output/jobs and growth in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs usually contract during deindustrialization.","B":"Incorrect because deindustrialization concerns sectoral shifts, not state ownership.","C":"Incorrect because manufacturing share declines relative to service growth during deindustrialization.","D":"Option D is correct because deindustrialization involves a relative decline in secondary manufacturing output/jobs and growth in tertiary services."}}},{"id":"P1_U1_MCQ_213","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_213","question":"A worker is cutting timber in a forest in Bristol. Which economic sector does this activity belong to?","options":{"A":"Public sector","B":"Secondary sector","C":"Tertiary sector","D":"Primary sector"},"correctOption":"D","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature.","distractor_reasons":{"A":"Public sector refers to government ownership, a different classification from the primary, secondary and tertiary sectors.","B":"The secondary sector manufactures or processes materials into finished goods, which is not what extracting a natural resource involves.","C":"The tertiary sector provides services to consumers and businesses rather than extracting raw materials from the natural environment.","D":"Option D is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature."}}},{"id":"P1_U1_MCQ_214","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_214","question":"An enterprise mines iron ore, a steel mill processes the ore into steel beams, and a construction firm uses the beams to build bridges. How are these three activities classified by economic sector?","options":{"A":"Mining: Secondary; Steel milling: Primary; Construction: Tertiary","B":"Mining: Primary; Steel milling: Secondary; Construction: Secondary","C":"Mining: Primary; Steel milling: Tertiary; Construction: Secondary","D":"Mining: Tertiary; Steel milling: Secondary; Construction: Primary"},"correctOption":"B","correctAnswer":"Mining: Primary; Steel milling: Secondary; Construction: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mining iron ore is primary (resource extraction), while both steel milling and construction involve transforming materials into finished goods/structures (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Option B is correct because mining iron ore is primary (resource extraction), while both steel milling and construction involve transforming materials into finished goods/structures (secondary sector).","C":"Incorrect because steel milling is manufacturing/processing (secondary), not service (tertiary).","D":"Incorrect because the sector order is completely inaccurate."}}},{"id":"P1_U1_MCQ_215","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_215","question":"What is a defining feature of a mixed economy?","options":{"A":"Exclusive state control over all business activity and pricing","B":"Complete absence of government tax collection and market regulation","C":"Economic resource allocation split between private enterprises and state organizations","D":"Total dependence on primary sector agricultural exports"},"correctOption":"C","correctAnswer":"Economic resource allocation split between private enterprises and state organizations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a mixed economy balances private enterprise (market mechanism) with state provision (public sector).","distractor_reasons":{"A":"Incorrect because total state control describes a planned/command economy.","B":"Incorrect because mixed economies rely on government tax revenue and statutory regulations.","C":"Option C is correct because a mixed economy balances private enterprise (market mechanism) with state provision (public sector).","D":"Incorrect because mixed economies operate across all three sectors."}}},{"id":"P1_U1_MCQ_216","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_216","question":"Which activity belongs entirely to the tertiary economic sector?","options":{"A":"Gold mining extraction","B":"Automobile engine assembly","C":"Cotton harvesting","D":"Hotel hospitality management"},"correctOption":"D","correctAnswer":"Hotel hospitality management","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because hotel hospitality provides consumer services, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because gold mining is primary extraction.","B":"Incorrect because engine assembly is secondary manufacturing.","C":"Incorrect because cotton harvesting is primary agriculture.","D":"Option D is correct because hotel hospitality provides consumer services, placing it in the tertiary sector."}}},{"id":"P1_U1_MCQ_217","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_217","question":"What main goal drives private sector business enterprises in a free market economy?","options":{"A":"Earning profit to reward owners and shareholders for invested capital","B":"Meeting state production output quotas set by government officials","C":"Providing free public goods to all citizens regardless of cost","D":"Maximizing annual tax liabilities payable to municipal authorities"},"correctOption":"A","correctAnswer":"Earning profit to reward owners and shareholders for invested capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profit is the primary commercial goal of private sector owners.","distractor_reasons":{"A":"Option A is correct because earning profit is the primary commercial goal of private sector owners.","B":"Incorrect because state production quotas belong to command economies.","C":"Incorrect because providing free public goods is a public sector objective.","D":"Incorrect because private firms manage tax legally rather than maximizing tax payments."}}},{"id":"P1_U1_MCQ_218","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_218","question":"Why might a national government privatize a state-run railway network?","options":{"A":"To grant civil service employment status to all railway staff","B":"To increase direct state control over daily passenger train schedules","C":"To eliminate private capital investment in national transport infrastructure","D":"To introduce market competition, profit incentives, and operational efficiency"},"correctOption":"D","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because privatization transfers state assets to private owners, bringing market incentives that improve operational efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Incorrect because privatization reduces direct state control.","C":"Incorrect because privatization encourages private capital investment.","D":"Option D is correct because privatization transfers state assets to private owners, bringing market incentives that improve operational efficiency."}}},{"id":"P1_U1_MCQ_219","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_219","question":"Which pair correctly matches an economic activity with its proper sector?","options":{"A":"Wheat farming - Secondary sector","B":"Bicycle manufacturing - Primary sector","C":"Insurance underwriting - Tertiary sector","D":"Coal mining - Tertiary sector"},"correctOption":"C","correctAnswer":"Insurance underwriting - Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because insurance is a commercial financial service, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because wheat farming is primary sector agriculture.","B":"Incorrect because bicycle manufacturing is secondary sector production.","C":"Option C is correct because insurance is a commercial financial service, placing it in the tertiary sector.","D":"Incorrect because coal mining is primary sector extraction."}}},{"id":"P1_U1_MCQ_220","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_220","question":"What structural shift in employment typically occurs as a developing nation experiences rapid industrialization?","options":{"A":"Labor shifts out of factory assembly into primary crop farming","B":"Tertiary service businesses close down completely to prioritize mining","C":"Public sector entities take over 100% of all private retail shops","D":"Labor moves out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Labor moves out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization is defined by expanding manufacturing factories, drawing labor from primary agriculture into secondary production.","distractor_reasons":{"A":"Incorrect because labor moves from farming into manufacturing, not the reverse.","B":"Incorrect because service industries expand alongside industrialization.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization is defined by expanding manufacturing factories, drawing labor from primary agriculture into secondary production."}}},{"id":"P1_U1_MCQ_221","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_221","question":"Which characteristic is essential for a successful entrepreneur starting a new business venture?","options":{"A":"Self-motivation, willingness to accept risk, and resilience after failures","B":"Preference for following orders from senior managers in large firms","C":"Reluctance to adapt business operations when market demand shifts","D":"Avoidance of financial liability for business debts"},"correctOption":"A","correctAnswer":"Self-motivation, willingness to accept risk, and resilience after failures","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early setbacks.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early setbacks.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Incorrect because flexibility is vital to entrepreneurial success.","D":"Incorrect because entrepreneurs bear and manage business risks."}}},{"id":"P1_U1_MCQ_222","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_222","question":"Why is producing a comprehensive business plan critical for a new startup applying for a bank loan?","options":{"A":"It automatically grants the business limited liability protection without incorporation","B":"It presents financial forecasts proving the firm's ability to service and repay loan debt","C":"It guarantees that the startup will achieve net profit in its first year","D":"It replaces tax registration requirements enforced by government"},"correctOption":"B","correctAnswer":"It presents financial forecasts proving the firm's ability to service and repay loan debt","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders analyze financial projections in a business plan to evaluate repayment capacity and default risk.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","B":"Option B is correct because bank lenders analyze financial projections in a business plan to evaluate repayment capacity and default risk.","C":"Incorrect because business plans present projections, not profit guarantees.","D":"Incorrect because tax registration is a statutory legal obligation independent of planning."}}},{"id":"P1_U1_MCQ_223","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_223","question":"Which metric is a standard, valid measure used to evaluate and compare business size within an industry?","options":{"A":"Annual net profit generated by the firm","B":"Unit retail price of flagship products","C":"Total monetary value of capital employed","D":"Percentage margin applied to raw materials"},"correctOption":"C","correctAnswer":"Total monetary value of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term funds invested) is a standard recognized metric of business scale.","distractor_reasons":{"A":"Incorrect because net profit is NOT a valid size metric (a small firm can earn higher profit than a large inefficient firm).","B":"Incorrect because unit price reflects product positioning, not business scale.","C":"Option C is correct because capital employed (total long-term funds invested) is a standard recognized metric of business scale.","D":"Incorrect because margin percentage reflects pricing strategy, not company size."}}},{"id":"P1_U1_MCQ_224","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_224","question":"Pinehurst Paper opens three new branches in Newcastle using profits retained from the previous year. What type of growth is this?","options":{"A":"Internal (organic) growth","B":"Horizontal integration","C":"Backward vertical integration","D":"A takeover"},"correctOption":"A","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","distractor_reasons":{"A":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","B":"Horizontal integration means joining with another firm at the same stage of production, usually through a merger or takeover.","C":"Backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"A takeover is external growth involving the purchase of another company rather than expansion using internal funds."}}},{"id":"P1_U1_MCQ_225","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_225","question":"Why do national governments offer advisory services and startup grants to new entrepreneurs?","options":{"A":"To create new jobs, stimulate innovation, and expand economic growth","B":"To eliminate market competition for state-owned monopolies","C":"To force small business owners to convert into public limited companies","D":"To prevent foreign commercial enterprises from importing goods"},"correctOption":"A","correctAnswer":"To create new jobs, stimulate innovation, and expand economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government startup support aims to reduce unemployment, foster innovation, and drive economic growth.","distractor_reasons":{"A":"Option A is correct because government startup support aims to reduce unemployment, foster innovation, and drive economic growth.","B":"Incorrect because governments encourage startups to foster competition, not eliminate it.","C":"Incorrect because government grants do not force changes in legal business structures.","D":"Incorrect because startup grants focus on domestic enterprise development, not import barriers."}}},{"id":"P1_U1_MCQ_226","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_226","question":"Ashgrove Travel, a chain of coffee shops, takes over a rival chain of coffee shops in South Wales. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","distractor_reasons":{"A":"Forward vertical integration means moving closer to the final customer, such as a producer buying retail outlets.","B":"Backward vertical integration means moving towards suppliers, such as a retailer buying a manufacturing plant.","C":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","D":"Internal growth uses a firm's own resources; taking over a rival is external growth through acquisition."}}},{"id":"P1_U1_MCQ_227","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_227","question":"Which limitation arises when measuring business size solely by sales revenue?","options":{"A":"Sales revenue cannot be calculated for manufacturing firms","B":"It is illegal under commercial law to report sales revenue","C":"High sales revenue in low-margin industries may not reflect a larger physical scale than low-revenue high-margin luxury firms","D":"Sales revenue remains identical for all businesses operating in the same economy"},"correctOption":"C","correctAnswer":"High sales revenue in low-margin industries may not reflect a larger physical scale than low-revenue high-margin luxury firms","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because comparing sales revenue across different market sectors can be misleading due to varying profit margins and pricing structures.","distractor_reasons":{"A":"Incorrect because sales revenue is standardly calculated for manufacturing firms.","B":"Incorrect because reporting sales revenue is standard accounting practice.","C":"Option C is correct because comparing sales revenue across different market sectors can be misleading due to varying profit margins and pricing structures.","D":"Incorrect because sales revenues vary widely among businesses."}}},{"id":"P1_U1_MCQ_228","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_228","question":"Why might the owner of an independent dental practice prefer to keep the business small rather than open multiple branches?","options":{"A":"Small practices are exempt from paying supplier bills","B":"Large dental practices are legally prohibited by government","C":"Expanding the practice automatically removes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct operational control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct operational control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because owners often stay small to preserve personal contact with clients, manage workload, and keep direct control.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because large dental chains operate legally in many countries.","C":"Incorrect because expansion does not cancel limited liability.","D":"Option D is correct because owners often stay small to preserve personal contact with clients, manage workload, and keep direct control."}}},{"id":"P1_U1_MCQ_229","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_229","question":"Which activity represents an example of internal (organic) business growth?","options":{"A":"Launching a new product line using retained profits","B":"Acquiring a major competitor in the domestic market","C":"Establishing a joint venture with an overseas supplier","D":"Merging with a logistics transport company"},"correctOption":"A","correctAnswer":"Launching a new product line using retained profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as developing new products or opening new branches.","distractor_reasons":{"A":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as developing new products or opening new branches.","B":"Incorrect because acquiring a competitor is external growth via takeover.","C":"Incorrect because joint ventures are external corporate collaborations.","D":"Incorrect because merging with a logistics company is external vertical growth."}}},{"id":"P1_U1_MCQ_230","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_230","question":"A manufacturer of ceramic mugs buys a chain of retail stores that sell its goods to the public. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Organic growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","distractor_reasons":{"A":"Backward vertical integration would involve acquiring a supplier further from the consumer, not a retailer near the end customer.","B":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","C":"Horizontal integration involves a firm at the same production stage, whereas a retailer is at a later stage of the chain.","D":"Organic growth is internal expansion, while purchasing an established retail chain is an external acquisition."}}},{"id":"P1_U1_MCQ_231","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_231","question":"What does unlimited liability mean for a sole trader operating a local plumbing business?","options":{"A":"The business owner's liability is limited strictly to invested share capital.","B":"The business can issue public shares on the national stock exchange.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to settle supplier debts if the plumbing business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to satisfy unpaid business debts.","distractor_reasons":{"A":"Incorrect because limiting liability to share capital describes limited companies.","B":"Incorrect because sole traders cannot issue shares.","C":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to satisfy unpaid business debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_232","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_232","question":"Aisha pays a fee to use the well-known brand and business model of Harborside Fisheries. What is this arrangement called?","options":{"A":"A joint venture","B":"A franchise","C":"A partnership","D":"A public corporation"},"correctOption":"B","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","distractor_reasons":{"A":"A joint venture involves joint ownership of a new business, not paying for the right to use an existing brand.","B":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","C":"A partnership shares ownership and management between partners rather than licensing a brand for a fee.","D":"A public corporation is government-owned and is unrelated to this private fee-paying arrangement."}}},{"id":"P1_U1_MCQ_233","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_233","question":"An individual buys a franchise license from a global coffee brand. What is a key disadvantage experienced by this franchisee?","options":{"A":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to change store menus without corporate approval","D":"Inability to receive operational training from the franchisor"},"correctOption":"A","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins.","B":"Incorrect because global franchises provide immediate brand recognition.","C":"Incorrect because franchisees must strictly adhere to brand standards and cannot change menus freely.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_234","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_234","question":"Two aerospace companies form a joint venture to develop an eco-friendly aircraft engine. What is a primary benefit of this arrangement?","options":{"A":"A permanent merger creating a single combined corporation","B":"Total elimination of management disagreements between partner executives","C":"Complete exemption from national business corporate taxes","D":"Sharing high development costs, operational risks, and specialized technical expertise"},"correctOption":"D","correctAnswer":"Sharing high development costs, operational risks, and specialized technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Incorrect because management friction between joint venture partners is a known risk.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Option D is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks."}}},{"id":"P1_U1_MCQ_235","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_235","question":"An organisation is wholly owned by the government and provides an essential public service in Norfolk. What is it called?","options":{"A":"A public corporation","B":"A sole trader","C":"A private limited company","D":"A franchise"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","distractor_reasons":{"A":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","B":"A sole trader is a privately owned one-person business, not a government-owned organisation.","C":"A private limited company is owned by private shareholders and is not wholly owned by the government.","D":"A franchise is a private commercial arrangement to use a brand, not a government-owned public service body."}}},{"id":"P1_U1_MCQ_236","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_236","question":"Why might partners in an expanding partnership decide to incorporate as a Private Limited Company (LTD)?","options":{"A":"To sell company shares publicly on the national stock exchange","B":"To eliminate the legal requirement to maintain accounting records","C":"To avoid paying corporate income taxes on annual profits","D":"To protect personal assets through limited liability and facilitate raising private equity"},"correctOption":"D","correctAnswer":"To protect personal assets through limited liability and facilitate raising private equity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors.","distractor_reasons":{"A":"Incorrect because only PLCs sell shares on public stock exchanges.","B":"Incorrect because LTDs face strict legal accounting standards.","C":"Incorrect because LTDs must pay corporate profits tax.","D":"Option D is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors."}}},{"id":"P1_U1_MCQ_237","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_237","question":"What does limited liability mean for shareholders of a company?","options":{"A":"Shareholders' potential financial loss is limited strictly to the amount invested in buying shares","B":"Shareholders can lose unlimited personal wealth if the firm goes bankrupt","C":"The company is exempt from paying back corporate bank loans","D":"Company directors bear full personal financial liability for corporate debt"},"correctOption":"A","correctAnswer":"Shareholders' potential financial loss is limited strictly to the amount invested in buying shares","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because limited liability caps shareholder potential losses to their equity investment, protecting personal wealth.","distractor_reasons":{"A":"Option A is correct because limited liability caps shareholder potential losses to their equity investment, protecting personal wealth.","B":"Incorrect because unlimited liability exposes personal wealth.","C":"Incorrect because corporate entities remain legally liable for bank debts.","D":"Incorrect because directors are protected under limited liability unless illegal actions occur."}}},{"id":"P1_U1_MCQ_238","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_238","question":"Which legal document governs profit allocation, partner responsibilities, and decision-making rules in a partnership?","options":{"A":"Certificate of Incorporation","B":"Deed of Partnership (Partnership Agreement)","C":"Memorandum of Association","D":"Articles of Incorporation"},"correctOption":"B","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation registers limited companies.","B":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","C":"Incorrect because Memorandum of Association is for company formation.","D":"Incorrect because Articles of Incorporation form joint-stock companies."}}},{"id":"P1_U1_MCQ_239","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_239","question":"Which business entity possesses a legal identity separate from its owners?","options":{"A":"Sole trader","B":"General partnership","C":"Private Limited Company (LTD)","D":"Unincorporated joint venture"},"correctOption":"C","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because incorporated entities like LTDs exist as separate legal persons from their owners.","distractor_reasons":{"A":"Incorrect because sole traders are unincorporated (owner and firm are legally one).","B":"Incorrect because general partnerships are unincorporated.","C":"Option C is correct because incorporated entities like LTDs exist as separate legal persons from their owners.","D":"Incorrect because unincorporated joint ventures do not possess separate legal personality."}}},{"id":"P1_U1_MCQ_240","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_240","question":"What risk does a franchisor take when expanding through franchise licensing?","options":{"A":"The franchisor loses legal ownership of the corporate trademark","B":"The franchisor becomes personally liable for all franchisee commercial loans","C":"Franchisees are legally allowed to stop paying agreed royalties","D":"Poor quality or customer service at a franchisee store can damage the overall brand reputation"},"correctOption":"D","correctAnswer":"Poor quality or customer service at a franchisee store can damage the overall brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because substandard performance at one franchise store harms the overall reputation of the global brand.","distractor_reasons":{"A":"Incorrect because trademark ownership remains with the franchisor.","B":"Incorrect because franchisors are not liable for independent franchisee debts.","C":"Incorrect because franchise contracts strictly enforce royalty obligations.","D":"Option D is correct because substandard performance at one franchise store harms the overall reputation of the global brand."}}},{"id":"P1_U1_MCQ_241","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_241","question":"During its first year of operation, a startup restaurant focuses primarily on earning sufficient cash revenue to pay rent and supplier bills. What objective does this reflect?","options":{"A":"Survival","B":"Market share dominance","C":"Rapid international expansion","D":"Profit maximization"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because survival is the primary short-term goal for new startups during their vulnerable initial operating period.","distractor_reasons":{"A":"Option A is correct because survival is the primary short-term goal for new startups during their vulnerable initial operating period.","B":"Incorrect because market share dominance is a long-term growth objective.","C":"Incorrect because international expansion comes after established domestic success.","D":"Incorrect because profit maximization is realistic only after survival is secured."}}},{"id":"P1_U1_MCQ_242","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_242","question":"How does achieving high net profit directly benefit company shareholders?","options":{"A":"It guarantees immediate wage increases for all factory workers","B":"It enables higher dividend payouts and enhances company share valuation","C":"It exempts the company from paying corporate profit taxes","D":"It forces raw material suppliers to extend interest-free trade credit"},"correctOption":"B","correctAnswer":"It enables higher dividend payouts and enhances company share valuation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher net profit provides capital for dividend payouts and enhances company valuation for shareholders.","distractor_reasons":{"A":"Incorrect because profit maximization does not automatically raise worker wages.","B":"Option B is correct because higher net profit provides capital for dividend payouts and enhances company valuation for shareholders.","C":"Incorrect because higher profits increase corporate tax liabilities.","D":"Incorrect because profit levels do not alter contracted trade credit terms."}}},{"id":"P1_U1_MCQ_243","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_243","question":"In a business such as Highland Woollens, which situation shows a clear conflict of interest between two stakeholder groups?","options":{"A":"Shareholders want higher dividends while employees want higher wages","B":"Customers want lower prices and better quality","C":"The government collects taxes from profitable firms","D":"Suppliers deliver raw materials on the agreed date"},"correctOption":"A","correctAnswer":"Shareholders want higher dividends while employees want higher wages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","distractor_reasons":{"A":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","B":"Customers wanting lower prices and better quality is a single group's preference, not a conflict between two stakeholder groups.","C":"Tax collection is a standard obligation and does not by itself describe opposing demands from two stakeholder groups.","D":"On-time delivery by suppliers is normal performance and involves no clash of competing interests."}}},{"id":"P1_U1_MCQ_244","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_244","question":"Which outcome represents a primary objective for factory workers as an internal stakeholder group?","options":{"A":"Maximizing annual dividend payouts to equity investors","B":"Securing minimum product selling prices for end consumers","C":"Minimizing local government tax collections","D":"Fair compensation, job security, and safe working conditions"},"correctOption":"D","correctAnswer":"Fair compensation, job security, and safe working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employees prioritize competitive salaries, workplace safety, and job stability.","distractor_reasons":{"A":"Incorrect because dividends go to shareholders, not factory workers.","B":"Incorrect because product pricing concerns consumers.","C":"Incorrect because tax collection is a public sector objective.","D":"Option D is correct because employees prioritize competitive salaries, workplace safety, and job stability."}}},{"id":"P1_U1_MCQ_245","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_245","question":"What is the primary objective of customers as external stakeholders of a consumer electronics business?","options":{"A":"High quality goods, fair prices, and reliable after-sales support","B":"Maximizing executive bonus payouts to board directors","C":"Increasing local property taxes paid by the company factory","D":"Reducing total employee headcount across manufacturing plants"},"correctOption":"A","correctAnswer":"High quality goods, fair prices, and reliable after-sales support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers seek good value, reliable product quality, and effective customer service.","distractor_reasons":{"A":"Option A is correct because customers seek good value, reliable product quality, and effective customer service.","B":"Incorrect because executive bonuses do not benefit consumers.","C":"Incorrect because property tax levels do not concern retail customers directly.","D":"Incorrect because employee headcount cuts are internal operational matters."}}},{"id":"P1_U1_MCQ_246","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_246","question":"Which goal is prioritized by raw material suppliers to a manufacturing firm?","options":{"A":"Maximum dividend payments distributed to the manufacturer's equity holders","B":"Regular order volumes and prompt payment according to agreed credit terms","C":"Lowering retail selling prices for the manufacturer's final goods","D":"Increasing local municipal taxes paid by the manufacturing factory"},"correctOption":"B","correctAnswer":"Regular order volumes and prompt payment according to agreed credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because suppliers desire steady demand and timely settlement of invoices to maintain their cash flow.","distractor_reasons":{"A":"Incorrect because dividends go to shareholders, not suppliers.","B":"Option B is correct because suppliers desire steady demand and timely settlement of invoices to maintain their cash flow.","C":"Incorrect because final consumer prices are customer/marketing concerns.","D":"Incorrect because local taxes do not benefit raw material suppliers."}}},{"id":"P1_U1_MCQ_247","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_247","question":"Which objective is prioritized by the local community residing near a chemical plant?","options":{"A":"Maximizing waste dumping in local rivers to cut business costs","B":"Maximizing share dividends paid to foreign equity investors","C":"Environmental safety, local job creation, and minimal pollution","D":"Replacing local staff with lower-cost offshore workers"},"correctOption":"C","correctAnswer":"Environmental safety, local job creation, and minimal pollution","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities want clean environments, minimal disruption, and local employment opportunities.","distractor_reasons":{"A":"Incorrect because communities strongly oppose environmental pollution.","B":"Incorrect because equity dividends do not benefit local residents.","C":"Option C is correct because local communities want clean environments, minimal disruption, and local employment opportunities.","D":"Incorrect because communities prefer local employment over offshore hiring."}}},{"id":"P1_U1_MCQ_248","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_248","question":"A manufacturing firm automates its production line, laying off 50 workers to lower unit costs. Which stakeholder conflict does this action illustrate?","options":{"A":"Suppliers wanting prompt payment vs Customers wanting longer warranties","B":"Government seeking tax revenue vs Community seeking low traffic","C":"Bank lenders seeking interest vs Managers seeking larger offices","D":"Shareholders seeking higher profits vs Employees seeking job security"},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits vs Employees seeking job security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security.","distractor_reasons":{"A":"Incorrect because supplier payments and warranties do not involve automation redundancies.","B":"Incorrect because tax revenue and community traffic are not the primary issues in factory automation.","C":"Incorrect because bank interest and director offices do not reflect automation redundancies.","D":"Option D is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security."}}},{"id":"P1_U1_MCQ_249","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_249","question":"A logistics company runs night delivery fleets to maximize sales growth, but local residents protest against noise pollution. Which two stakeholders are in conflict?","options":{"A":"Suppliers and Customers","B":"Government and Lenders","C":"Managers/Shareholders and Local community","D":"Tax authorities and Employees"},"correctOption":"C","correctAnswer":"Managers/Shareholders and Local community","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","distractor_reasons":{"A":"Incorrect because suppliers and customers are not in conflict over local delivery noise.","B":"Incorrect because government and lenders are not the primary parties involved in night noise complaints.","C":"Option C is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","D":"Incorrect because tax authorities are unrelated to noise pollution disputes."}}},{"id":"P1_U1_MCQ_250","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_250","question":"A firm that supplies raw materials to Fernhill Pharmaceuticals is which of its stakeholders?","options":{"A":"A customer","B":"A shareholder","C":"A supplier","D":"A competitor"},"correctOption":"C","correctAnswer":"A supplier","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","distractor_reasons":{"A":"A customer buys the finished goods from the business rather than providing raw materials to it.","B":"A shareholder owns part of the business, which is a different relationship from selling it inputs.","C":"Option C is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","D":"A competitor sells rival products in the same market rather than supplying this business."}}},{"id":"P1_U1_MCQ_251","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_251","question":"A toy manufacturer purchases plastic resin and paint for $6 per toy and sells finished action figures for $20 each. Which action directly increases the added value per toy by $4?","options":{"A":"Enhancing product design and selling each action figure for $24","B":"Increasing total factory production from 1,000 to 1,500 toys per week","C":"Reducing assembly line workers' hourly wages by $4 per day","D":"Buying $4 worth of extra packaging materials to store in inventory"},"correctOption":"A","correctAnswer":"Enhancing product design and selling each action figure for $24","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus bought-in material costs ($20 - $6 = $14). Raising the price to $24 increases unit added value to $18, an increase of $4.","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus bought-in material costs ($20 - $6 = $14). Raising the price to $24 increases unit added value to $18, an increase of $4.","B":"Incorrect because increasing volume affects overall business profit potential, not unit added value.","C":"Incorrect because wages are overhead operational expenses, not raw material costs subtracted in added value calculation.","D":"Incorrect because storing extra packaging stock increases inventory assets without increasing unit added value."}}},{"id":"P1_U1_MCQ_252","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_252","question":"A farmer has sufficient land to raise either 200 sheep or 50 beef cattle. If the farmer chooses to raise 50 beef cattle, what is the opportunity cost?","options":{"A":"The financial cost of purchasing animal feed for the cattle","B":"The 200 sheep that could have been raised instead","C":"The total sales revenue earned from selling beef","D":"The cost of fencing the cattle pasture"},"correctOption":"B","correctAnswer":"The 200 sheep that could have been raised instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative given up when making a choice, which is raising 200 sheep.","distractor_reasons":{"A":"Incorrect because feed cost is a direct monetary expenditure.","B":"Option B is correct because opportunity cost is the next best alternative given up when making a choice, which is raising 200 sheep.","C":"Incorrect because revenue is the benefit of the chosen option, not the foregone alternative.","D":"Incorrect because fencing is a capital/operating expenditure."}}},{"id":"P1_U1_MCQ_253","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_253","question":"A food processing factory uses sugar cane, machine operators, conveyor belts, and an operations manager. Which factor of production do the conveyor belts represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment and machinery used in production.","distractor_reasons":{"A":"Incorrect because land covers natural resources like sugar cane.","B":"Incorrect because labour covers human physical and mental effort.","C":"Option C is correct because capital consists of man-made physical equipment and machinery used in production.","D":"Incorrect because enterprise is the risk-taking and managerial function."}}},{"id":"P1_U1_MCQ_254","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_254","question":"A computer hardware firm applies division of labor by having a worker fit power supplies into cases all day. What is a key disadvantage of this operational strategy?","options":{"A":"Workers take longer to master their single assembly task","B":"The unit purchase price of power supplies from suppliers rises","C":"Hourly output of computer cases per factory line decreases","D":"Task repetition causes employee boredom, leading to higher absenteeism and potential errors"},"correctOption":"D","correctAnswer":"Task repetition causes employee boredom, leading to higher absenteeism and potential errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repetitive tasks cause monotony, lowering morale and increasing error rates.","distractor_reasons":{"A":"Incorrect because learning a single repetitive task takes less time.","B":"Incorrect because internal division of labor does not alter external supplier pricing.","C":"Incorrect because specialization typically increases output efficiency.","D":"Option D is correct because repetitive tasks cause monotony, lowering morale and increasing error rates."}}},{"id":"P1_U1_MCQ_255","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_255","question":"Northwind Toys buys raw materials for $6 per unit and sells the finished item for $18. Which change would directly increase the value added per unit?","options":{"A":"Paying a higher price to its raw-material suppliers","B":"Hiring two more office administrators","C":"Doubling the number of units produced each week","D":"Improving the product so it can be sold for $20"},"correctOption":"D","correctAnswer":"Improving the product so it can be sold for $20","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because value added per unit equals selling price minus raw-material cost; raising the price to $20 widens the gap from $12 to $14.","distractor_reasons":{"A":"Paying suppliers more increases the raw-material cost per unit and so reduces, rather than increases, the value added per unit.","B":"Administrative wages are overheads and are not the bought-in material cost used when calculating value added per unit.","C":"Producing more units raises total output but leaves selling price and material cost per unit unchanged, so value added per unit is unaffected.","D":"Option D is correct because value added per unit equals selling price minus raw-material cost; raising the price to $20 widens the gap from $12 to $14."}}},{"id":"P1_U1_MCQ_256","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_256","question":"Why does the economic problem of scarcity exist in both developing and developed countries?","options":{"A":"Governments set maximum retail prices on luxury products","B":"Limited economic resources are insufficient to satisfy unlimited human wants","C":"Commercial businesses deliberately operate at a financial loss","D":"An oversupply of raw materials depresses market prices"},"correctOption":"B","correctAnswer":"Limited economic resources are insufficient to satisfy unlimited human wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally stems from finite resources facing infinite human wants.","distractor_reasons":{"A":"Incorrect because price controls are state interventions, not the cause of scarcity.","B":"Option B is correct because scarcity fundamentally stems from finite resources facing infinite human wants.","C":"Incorrect because operating losses relate to firm management, not fundamental scarcity.","D":"Incorrect because raw material oversupply reduces scarcity of those resources."}}},{"id":"P1_U1_MCQ_257","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_257","question":"A craft shop purchases raw wood for $12 and metal hinges for $3 per wooden box. The completed box is sold for $45. What is the added value per box?","options":{"A":"$15","B":"$33","C":"$30","D":"$45"},"correctOption":"C","correctAnswer":"$30","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bought-in material costs equal $12 + $3 = $15. Added value = selling price ($45) minus material costs ($15) = $30.","distractor_reasons":{"A":"Incorrect because $15 is the total material cost.","B":"Incorrect because $33 subtracts only raw wood cost ($45 - $12).","C":"Option C is correct because bought-in material costs equal $12 + $3 = $15. Added value = selling price ($45) minus material costs ($15) = $30.","D":"Incorrect because $45 is the final selling price."}}},{"id":"P1_U1_MCQ_258","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_258","question":"A chef resigns from a restaurant job paying $40,000 annually to set up a private catering service. What is the opportunity cost of starting this catering enterprise?","options":{"A":"The lease expense paid for the commercial kitchen space","B":"The total sales revenue generated from catering events in Year 1","C":"The capital spent purchasing professional cookware","D":"The $40,000 annual restaurant salary foregone"},"correctOption":"D","correctAnswer":"The $40,000 annual restaurant salary foregone","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost is the sacrificed benefit of the next best alternative given up, which is the $40,000 salary.","distractor_reasons":{"A":"Incorrect because kitchen lease is an explicit operational expenditure.","B":"Incorrect because revenue is the benefit of the chosen option.","C":"Incorrect because cookware is a direct capital outlay.","D":"Option D is correct because opportunity cost is the sacrificed benefit of the next best alternative given up, which is the $40,000 salary."}}},{"id":"P1_U1_MCQ_259","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_259","question":"Which factor of production includes natural resources such as iron ore, crude oil, and agricultural land?","options":{"A":"Capital","B":"Labour","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because land covers all natural resources provided by nature used in production.","distractor_reasons":{"A":"Incorrect because capital refers to man-made assets like machinery.","B":"Incorrect because labour refers to human physical/mental effort.","C":"Option C is correct because land covers all natural resources provided by nature used in production.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_260","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_260","question":"How can a bakery directly increase the added value of its cakes without raising their retail selling price?","options":{"A":"Increasing monthly spending on local newspaper advertisements","B":"Negotiating lower wholesale prices for flour and sugar from suppliers","C":"Increasing the hourly wage rate paid to assistant bakers","D":"Renting a larger storage room for spare equipment"},"correctOption":"B","correctAnswer":"Negotiating lower wholesale prices for flour and sugar from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw ingredient costs widens the added value gap.","distractor_reasons":{"A":"Incorrect because advertising is an operational overhead cost.","B":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw ingredient costs widens the added value gap.","C":"Incorrect because higher wages raise operating expenses, lowering profit rather than unit added value.","D":"Incorrect because renting storage increases fixed overheads."}}},{"id":"P1_U1_MCQ_261","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_261","question":"Which commercial activity is classified within the primary sector?","options":{"A":"Manufacturing agricultural tractors in a heavy industry plant","B":"Providing accounting services to farm businesses","C":"Harvesting apples in a commercial fruit orchard","D":"Selling fresh fruit in a supermarket chain"},"correctOption":"C","correctAnswer":"Harvesting apples in a commercial fruit orchard","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because harvesting apples directly extracts natural agricultural produce, placing it in the primary sector.","distractor_reasons":{"A":"Incorrect because tractor manufacturing is secondary sector industry.","B":"Incorrect because accounting is a tertiary service.","C":"Option C is correct because harvesting apples directly extracts natural agricultural produce, placing it in the primary sector.","D":"Incorrect because supermarket sales are tertiary distribution."}}},{"id":"P1_U1_MCQ_262","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_262","question":"What structural employment change takes place when an economy undergoes deindustrialization?","options":{"A":"Employment shifts from service industries into agricultural farming","B":"The state nationalizes all private manufacturing firms","C":"Factory output doubles while service sector employment shrinks","D":"Employment contracts in secondary manufacturing and expands in tertiary services"},"correctOption":"D","correctAnswer":"Employment contracts in secondary manufacturing and expands in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization involves a structural decline in secondary manufacturing and a relative expansion in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs usually decline during deindustrialization.","B":"Incorrect because deindustrialization concerns sector distribution, not state nationalization.","C":"Incorrect because manufacturing share declines relative to services.","D":"Option D is correct because deindustrialization involves a structural decline in secondary manufacturing and a relative expansion in tertiary services."}}},{"id":"P1_U1_MCQ_263","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_263","question":"A worker is assembling cars in a factory in the Scottish Highlands. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","distractor_reasons":{"A":"The primary sector extracts natural resources in their raw state; assembling or processing materials is a manufacturing activity instead.","B":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","C":"The tertiary sector is concerned with providing services, not with the physical conversion of materials into products.","D":"Public sector describes who owns an organisation, not the type of productive activity being carried out."}}},{"id":"P1_U1_MCQ_264","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_264","question":"A mining firm extracts copper ore, a smelting facility refines the ore into raw copper sheets, and an electronics plant uses the sheets to manufacture wiring. How are these three activities categorized?","options":{"A":"Mining: Secondary; Smelting: Primary; Wiring production: Tertiary","B":"Mining: Primary; Smelting: Secondary; Wiring production: Secondary","C":"Mining: Primary; Smelting: Tertiary; Wiring production: Secondary","D":"Mining: Tertiary; Smelting: Secondary; Wiring production: Primary"},"correctOption":"B","correctAnswer":"Mining: Primary; Smelting: Secondary; Wiring production: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mining copper is primary (extraction), while both smelting and wire manufacturing process materials into finished forms (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction.","B":"Option B is correct because mining copper is primary (extraction), while both smelting and wire manufacturing process materials into finished forms (secondary sector).","C":"Incorrect because smelting is secondary processing, not tertiary service.","D":"Incorrect because sector order is inverted."}}},{"id":"P1_U1_MCQ_265","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_265","question":"What is a central feature of a mixed economy?","options":{"A":"Total state ownership of all production factors and central planning","B":"Complete absence of government regulation and corporate taxation","C":"Resource allocation split between private market enterprises and public state provision","D":"Total dependence on primary agricultural exports"},"correctOption":"C","correctAnswer":"Resource allocation split between private market enterprises and public state provision","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a mixed economy balances private enterprise with state public sector activity.","distractor_reasons":{"A":"Incorrect because total state ownership defines a command economy.","B":"Incorrect because mixed economies utilize state regulation and tax.","C":"Option C is correct because a mixed economy balances private enterprise with state public sector activity.","D":"Incorrect because mixed economies operate across all sectors."}}},{"id":"P1_U1_MCQ_266","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_266","question":"A worker is driving a delivery lorry in Devon. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","distractor_reasons":{"A":"The primary sector involves extracting raw materials from nature, which is different from providing a service to a customer.","B":"The secondary sector makes physical products by processing materials, whereas this activity involves delivering a service.","C":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","D":"Public sector refers to government ownership and is not one of the three productive sectors being described here."}}},{"id":"P1_U1_MCQ_267","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_267","question":"Over twenty years Essex has seen its large factories close and employment shift towards shops, offices and services. What is this change called?","options":{"A":"Industrialisation","B":"De-industrialisation","C":"Primary-sector expansion","D":"Nationalisation"},"correctOption":"B","correctAnswer":"De-industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","distractor_reasons":{"A":"Industrialisation is the opposite process, building up manufacturing industry rather than losing it.","B":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","C":"Primary-sector expansion would mean more farming, mining or fishing, not the closure of factories and growth of services.","D":"Nationalisation means transferring private assets into government ownership and is unrelated to the decline of manufacturing jobs."}}},{"id":"P1_U1_MCQ_268","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_268","question":"Why might a government choose to privatize a state-run electric power utility?","options":{"A":"To grant civil service employment status to utility staff","B":"To introduce market competition, profit incentives, and operational efficiency","C":"To eliminate private capital investment in national energy infrastructure","D":"To increase direct state control over daily electricity pricing"},"correctOption":"B","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners to foster competition, profit motives, and efficiency.","distractor_reasons":{"A":"Incorrect because privatized employees lose civil service status.","B":"Option B is correct because privatization transfers state assets to private owners to foster competition, profit motives, and efficiency.","C":"Incorrect because privatization invites private capital investment.","D":"Incorrect because privatization reduces direct state control."}}},{"id":"P1_U1_MCQ_269","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_269","question":"Which pair correctly matches an economic activity with its sector?","options":{"A":"Fishing - Secondary sector","B":"Car assembly - Primary sector","C":"Tourism management - Tertiary sector","D":"Coal mining - Tertiary sector"},"correctOption":"C","correctAnswer":"Tourism management - Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tourism management is a commercial service, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because fishing is primary sector resource extraction.","B":"Incorrect because car assembly is secondary sector manufacturing.","C":"Option C is correct because tourism management is a commercial service, placing it in the tertiary sector.","D":"Incorrect because coal mining is primary sector extraction."}}},{"id":"P1_U1_MCQ_270","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_270","question":"What structural shift occurs in employment as a country undergoes industrialization?","options":{"A":"Workers move from secondary manufacturing into primary farming","B":"Service sector businesses close down completely","C":"Public sector entities absorb 100% of all private retail businesses","D":"Workers shift from primary agriculture into secondary manufacturing"},"correctOption":"D","correctAnswer":"Workers shift from primary agriculture into secondary manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization marks the growth of manufacturing factories, pulling labor from primary agriculture into secondary production.","distractor_reasons":{"A":"Incorrect because labor shifts from agriculture into manufacturing, not the reverse.","B":"Incorrect because service industries expand alongside industrial development.","C":"Incorrect because industrialization is a sectoral economic shift, not state nationalization.","D":"Option D is correct because industrialization marks the growth of manufacturing factories, pulling labor from primary agriculture into secondary production."}}},{"id":"P1_U1_MCQ_271","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_271","question":"Which characteristic is most vital for a successful entrepreneur?","options":{"A":"Self-motivation, risk-taking capacity, and resilience when encountering obstacles","B":"Preference for taking direct operational orders from corporate superiors","C":"Reluctance to adapt business strategies when customer demand changes","D":"Avoidance of personal financial responsibility for commercial decisions"},"correctOption":"A","correctAnswer":"Self-motivation, risk-taking capacity, and resilience when encountering obstacles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require drive, willingness to take calculated risks, and resilience to overcome start-up challenges.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require drive, willingness to take calculated risks, and resilience to overcome start-up challenges.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Incorrect because adaptability is crucial for business survival.","D":"Incorrect because entrepreneurs take financial responsibility."}}},{"id":"P1_U1_MCQ_272","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_272","question":"Why is preparing a detailed business plan essential when applying for a commercial bank loan?","options":{"A":"It automatically grants limited liability protection to sole traders","B":"It presents financial forecasts proving the business's ability to service and repay loan debt","C":"It guarantees that the start-up will earn profit within six months","D":"It replaces official tax registration documents required by law"},"correctOption":"B","correctAnswer":"It presents financial forecasts proving the business's ability to service and repay loan debt","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because banks examine financial projections in a business plan to evaluate debt repayment ability and risk.","distractor_reasons":{"A":"Incorrect because limited liability requires incorporation (e.g. LTD), which a plan cannot grant.","B":"Option B is correct because banks examine financial projections in a business plan to evaluate debt repayment ability and risk.","C":"Incorrect because plans present forecasts, not profit guarantees.","D":"Incorrect because tax registration is a statutory legal obligation independent of planning."}}},{"id":"P1_U1_MCQ_273","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_273","question":"Which metric is a standard, valid method for measuring and comparing business size within an industry?","options":{"A":"Annual net profit generated by the firm","B":"Unit selling price of flagship products","C":"Total monetary value of capital employed","D":"Percentage profit markup on raw materials"},"correctOption":"C","correctAnswer":"Total monetary value of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term funds invested) is a standard recognized metric of business scale.","distractor_reasons":{"A":"Incorrect because net profit is NOT a valid size metric (a small firm can earn higher profit than a large inefficient firm).","B":"Incorrect because unit price reflects product positioning, not scale.","C":"Option C is correct because capital employed (total long-term funds invested) is a standard recognized metric of business scale.","D":"Incorrect because markup percentage reflects pricing strategy, not company size."}}},{"id":"P1_U1_MCQ_274","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_274","question":"A company making woollen jumpers purchases the business that supplies its raw ingredients. What type of growth has taken place?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","distractor_reasons":{"A":"Forward vertical integration means moving towards the customer, such as buying distributors, not acquiring a supplier.","B":"Horizontal integration joins firms at the same stage of activity, whereas a raw-material supplier is at an earlier stage.","C":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"Internal growth is funded and achieved within the business, while buying a supplier is an external acquisition."}}},{"id":"P1_U1_MCQ_275","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_275","question":"Why do national governments offer start-up grants and advisory support to new entrepreneurs?","options":{"A":"To create new jobs, stimulate innovation, and expand economic growth","B":"To eliminate competition for state-owned enterprises","C":"To force small business owners to convert into public limited companies","D":"To prevent foreign commercial enterprises from importing goods"},"correctOption":"A","correctAnswer":"To create new jobs, stimulate innovation, and expand economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government start-up support aims to reduce unemployment, foster innovation, and drive economic growth.","distractor_reasons":{"A":"Option A is correct because government start-up support aims to reduce unemployment, foster innovation, and drive economic growth.","B":"Incorrect because governments encourage start-ups to foster competition, not eliminate it.","C":"Incorrect because grants do not force changes in legal structures.","D":"Incorrect because start-up grants focus on domestic enterprise development, not import barriers."}}},{"id":"P1_U1_MCQ_276","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_276","question":"Daniel is setting up a business in Stirling. Which action best describes the role of an entrepreneur?","options":{"A":"Taking financial risk and organising resources to create and run a business","B":"Receiving a fixed salary for carrying out routine office work","C":"Guaranteeing that the business will never face competition","D":"Owning the business but avoiding all decision-making"},"correctOption":"A","correctAnswer":"Taking financial risk and organising resources to create and run a business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","distractor_reasons":{"A":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","B":"A fixed salary for routine work describes an employee, not an entrepreneur who bears risk and organises the business.","C":"No entrepreneur can guarantee the absence of competition, which is outside their control in a market.","D":"Entrepreneurs are actively involved in decisions; avoiding all decision-making is not an entrepreneurial role."}}},{"id":"P1_U1_MCQ_277","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_277","question":"Which limitation applies when measuring business size solely by the number of employees?","options":{"A":"Employee headcount cannot be calculated for service sector firms","B":"It is illegal under commercial law to report employee numbers","C":"A capital-intensive automated factory may employ few staff but produce massive output","D":"Employee headcount changes every hour during normal factory operations"},"correctOption":"C","correctAnswer":"A capital-intensive automated factory may employ few staff but produce massive output","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employee headcount can give a misleading picture when comparing automated, capital-intensive firms with labor-intensive firms.","distractor_reasons":{"A":"Incorrect because headcount is measured standardly in service firms.","B":"Incorrect because reporting headcount is standard practice.","C":"Option C is correct because employee headcount can give a misleading picture when comparing automated, capital-intensive firms with labor-intensive firms.","D":"Incorrect because employee headcount is measured by contracted staff numbers."}}},{"id":"P1_U1_MCQ_278","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_278","question":"Why might the owner of a successful specialized jewelry studio choose to keep the business small rather than expand?","options":{"A":"Small studios are exempt from paying supplier bills","B":"Large companies are legally banned from selling jewelry","C":"Expanding automatically removes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct control over design quality"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct control over design quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often stay small to preserve personal contact with clients, control quality, and keep direct management control.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because large retail jewelry chains operate legally.","C":"Incorrect because expansion does not cancel limited liability.","D":"Option D is correct because business owners often stay small to preserve personal contact with clients, control quality, and keep direct management control."}}},{"id":"P1_U1_MCQ_279","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_279","question":"Which activity is an example of internal (organic) business growth?","options":{"A":"Opening new branch locations using retained profit","B":"Acquiring a major competitor in the domestic market","C":"Establishing a joint venture with an overseas manufacturer","D":"Merging with a logistics transport company"},"correctOption":"A","correctAnswer":"Opening new branch locations using retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as opening new branches.","distractor_reasons":{"A":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as opening new branches.","B":"Incorrect because acquiring a competitor is external growth via takeover.","C":"Incorrect because joint ventures are external corporate collaborations.","D":"Incorrect because merging with a logistics company is external vertical growth."}}},{"id":"P1_U1_MCQ_280","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_280","question":"Kwame is preparing a business plan before launching a new venture. What is the main purpose of a business plan?","options":{"A":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","B":"To guarantee that the business will make a profit in its first year","C":"To remove the need for any market research before launching","D":"To avoid having to keep any accounting records"},"correctOption":"A","correctAnswer":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","distractor_reasons":{"A":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","B":"A plan cannot guarantee profit, which depends on future trading conditions and many factors outside the plan.","C":"A business plan supports rather than replaces market research, which remains necessary to understand customers.","D":"A business plan does not remove the legal and practical need to keep proper financial records."}}},{"id":"P1_U1_MCQ_281","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_281","question":"What does unlimited liability mean for a sole trader operating a local bakery?","options":{"A":"The owner's financial liability is limited strictly to invested share capital.","B":"The bakery can issue public shares on the stock exchange.","C":"The owner is personally responsible for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to settle supplier debts if the bakery fails."},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to pay unpaid business debts.","distractor_reasons":{"A":"Incorrect because limiting liability to share capital describes limited companies.","B":"Incorrect because sole traders cannot issue shares.","C":"Option C is correct because unlimited liability means the owner and business are legally identical; personal property can be seized to pay unpaid business debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_282","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_282","question":"What is a dividend in the context of a company such as Coastline Cartons?","options":{"A":"A share of company profits paid out to shareholders","B":"The total value of the company's fixed assets","C":"A tax that the company pays to the government only","D":"The wage paid to the highest-paid employee"},"correctOption":"A","correctAnswer":"A share of company profits paid out to shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","distractor_reasons":{"A":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","B":"The value of fixed assets appears in the statement of financial position and is not a payment to shareholders.","C":"Company tax is paid to the government, whereas a dividend is paid to the owners of the business.","D":"Wages are payments to employees for labour, not distributions of profit to shareholders."}}},{"id":"P1_U1_MCQ_283","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_283","question":"An entrepreneur purchases a franchise license from an international hotel chain. What is a key disadvantage faced by this franchisee?","options":{"A":"Paying initial license fees and ongoing revenue royalties to the franchisor","B":"Complete absence of brand recognition in the hospitality market","C":"Complete freedom to alter hotel operational standards without permission","D":"Inability to receive staff training and operational support"},"correctOption":"A","correctAnswer":"Paying initial license fees and ongoing revenue royalties to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront fees and regular royalties, reducing net profit margins.","B":"Incorrect because global franchises provide immediate brand recognition.","C":"Incorrect because franchisees must strictly adhere to franchisor operational standards.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_284","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_284","question":"Two technology firms establish a joint venture to build an artificial intelligence platform. What is a primary benefit of this business setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing high development costs, operational risks, and specialized technical expertise","C":"Complete exemption from national business corporate taxes","D":"Total elimination of management disputes between executive teams"},"correctOption":"B","correctAnswer":"Sharing high development costs, operational risks, and specialized technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific project while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific project while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_285","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_285","question":"Which statement about a sole trader such as Priya selling artisan sourdough loaves is correct?","options":{"A":"The owner keeps all the profits but has unlimited liability","B":"The owner must share all profits with the government","C":"The owner has limited liability and pays no tax","D":"The owner cannot make any business decisions alone"},"correctOption":"A","correctAnswer":"The owner keeps all the profits but has unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","distractor_reasons":{"A":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","B":"The owner keeps the profits but pays tax on them; profits are not shared with the government as owners' earnings.","C":"A sole trader has unlimited liability, not limited liability, and is still liable to pay income tax on profits.","D":"A sole trader makes the business decisions alone, which is one of the advantages of this form of organisation."}}},{"id":"P1_U1_MCQ_286","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_286","question":"Why might partners in an expanding legal partnership choose to incorporate as a Private Limited Company (LTD)?","options":{"A":"To sell company shares publicly on the national stock exchange","B":"To eliminate the legal requirement to maintain financial accounts","C":"To avoid paying corporate income taxes on annual profits","D":"To protect personal assets through limited liability and facilitate raising private equity"},"correctOption":"D","correctAnswer":"To protect personal assets through limited liability and facilitate raising private equity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors.","distractor_reasons":{"A":"Incorrect because only PLCs sell shares on public stock exchanges.","B":"Incorrect because LTDs face strict legal accounting standards.","C":"Incorrect because LTDs must pay corporate profits tax.","D":"Option D is correct because incorporating as an LTD provides limited liability protection for owners' personal assets and simplifies raising capital from private investors."}}},{"id":"P1_U1_MCQ_287","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_287","question":"Which source of finance involves selling ownership stakes in a private limited company such as Greenfield Organics?","options":{"A":"Bank overdraft","B":"Issuing shares","C":"Trade credit","D":"Leasing equipment"},"correctOption":"B","correctAnswer":"Issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","distractor_reasons":{"A":"A bank overdraft is borrowed money that must be repaid and does not transfer ownership of the business.","B":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","C":"Trade credit delays payment to suppliers and is a short-term source of finance, not a sale of ownership.","D":"Leasing is renting an asset instead of buying it and does not give investors any share in the company."}}},{"id":"P1_U1_MCQ_288","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_288","question":"Which legal document regulates partner profit shares, management duties, and voting rights in a partnership?","options":{"A":"Certificate of Incorporation","B":"Deed of Partnership (Partnership Agreement)","C":"Memorandum of Association","D":"Trading License Certificate"},"correctOption":"B","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation registers limited companies.","B":"Option B is correct because a Deed of Partnership specifies profit sharing ratios, decision rights, and responsibilities among partners.","C":"Incorrect because Memorandum of Association is for company formation.","D":"Incorrect because trading licenses are municipal permits."}}},{"id":"P1_U1_MCQ_289","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_289","question":"What is a benefit to Callum of becoming a franchisee of Silverstream Bottling rather than starting an independent business?","options":{"A":"The franchisee has complete freedom to change the product range","B":"The franchisee keeps every pound of profit with no fees to pay","C":"Using an established brand and proven business model lowers the risk of failure","D":"The franchisee has no need to follow any trading standards"},"correctOption":"C","correctAnswer":"Using an established brand and proven business model lowers the risk of failure","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","distractor_reasons":{"A":"Franchise agreements usually require the franchisee to follow the franchisor's products and methods, limiting freedom.","B":"Franchisees normally pay an initial fee and ongoing royalties, so they do not keep all the profit.","C":"Option C is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","D":"Franchisees must still meet legal and quality standards set by the franchisor and by law."}}},{"id":"P1_U1_MCQ_290","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_290","question":"What risk does a franchisor take when licensing its business model to franchisees?","options":{"A":"The franchisor loses legal ownership of the corporate trademark","B":"The franchisor becomes personally liable for all franchisee commercial loans","C":"Franchisees are legally allowed to stop paying agreed royalties","D":"Poor quality or customer service at a franchisee store can damage overall brand reputation"},"correctOption":"D","correctAnswer":"Poor quality or customer service at a franchisee store can damage overall brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because substandard performance at one franchise store harms the overall reputation of the global brand.","distractor_reasons":{"A":"Incorrect because trademark ownership remains with the franchisor.","B":"Incorrect because franchisors are not liable for independent franchisee debts.","C":"Incorrect because franchise contracts strictly enforce royalty obligations.","D":"Option D is correct because substandard performance at one franchise store harms the overall reputation of the global brand."}}},{"id":"P1_U1_MCQ_291","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_291","question":"During its first year of operation, a startup tech firm focuses primarily on securing enough cash revenue to pay office rent and developer salaries. What objective does this reflect?","options":{"A":"Survival","B":"Market share dominance","C":"Rapid international expansion","D":"Profit maximization"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because survival is the primary short-term goal for new start-ups during their vulnerable initial operating period.","distractor_reasons":{"A":"Option A is correct because survival is the primary short-term goal for new start-ups during their vulnerable initial operating period.","B":"Incorrect because market share dominance is a long-term growth objective.","C":"Incorrect because international expansion comes after established domestic success.","D":"Incorrect because profit maximization is realistic only after survival is secured."}}},{"id":"P1_U1_MCQ_292","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_292","question":"Which is a typical objective of a public-sector organisation such as a state-funded hospital in Kent?","options":{"A":"To maximise dividends for private shareholders","B":"To provide a service for the community rather than to maximise profit","C":"To avoid serving customers who cannot pay","D":"To keep prices as high as the market will bear"},"correctOption":"B","correctAnswer":"To provide a service for the community rather than to maximise profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","distractor_reasons":{"A":"Public-sector organisations do not have private shareholders seeking dividends, so this cannot be their objective.","B":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","C":"Public services generally aim to be accessible to the whole community, including those who cannot afford to pay.","D":"Charging the highest possible prices is a private profit-seeking objective, not the aim of a public service provider."}}},{"id":"P1_U1_MCQ_293","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_293","question":"What is usually the primary objective of a private-sector business such as Silverdale Foods?","options":{"A":"To be owned by the state","B":"To provide free public services","C":"To avoid all competition","D":"To make a profit"},"correctOption":"D","correctAnswer":"To make a profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","distractor_reasons":{"A":"Private-sector firms are owned by private individuals or shareholders, not by the state.","B":"Providing free public services is typical of the public sector, not of privately owned businesses seeking a return.","C":"Businesses cannot normally avoid competition, which is a feature of the market in which they operate.","D":"Option D is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners."}}},{"id":"P1_U1_MCQ_294","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_294","question":"Which group is most directly interested in Northwind Toys paying competitive wages and offering safe working conditions?","options":{"A":"Its employees","B":"Its customers","C":"Its shareholders","D":"Its local suppliers"},"correctOption":"A","correctAnswer":"Its employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","distractor_reasons":{"A":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","B":"Customers are mainly concerned with the price, quality and availability of the products they buy.","C":"Shareholders are primarily interested in returns on their investment and the profitability of the business.","D":"Suppliers are mainly interested in receiving payment and maintaining orders for their materials."}}},{"id":"P1_U1_MCQ_295","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_295","question":"What is the primary objective of customers as external stakeholders of an appliance company?","options":{"A":"High quality goods, fair prices, and reliable after-sales support","B":"Maximizing executive bonus payouts to board directors","C":"Increasing local property taxes paid by the company factory","D":"Reducing total employee headcount across manufacturing plants"},"correctOption":"A","correctAnswer":"High quality goods, fair prices, and reliable after-sales support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers seek good value, reliable product quality, and effective customer service.","distractor_reasons":{"A":"Option A is correct because customers seek good value, reliable product quality, and effective customer service.","B":"Incorrect because executive bonuses do not benefit consumers.","C":"Incorrect because property tax levels do not concern retail customers directly.","D":"Incorrect because employee headcount cuts are internal operational matters."}}},{"id":"P1_U1_MCQ_296","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_296","question":"A local council in Norfolk is concerned that Ridgeview Winery may close a factory and cause job losses. In what capacity is the council a stakeholder?","options":{"A":"As a competitor in the same market","B":"As part of the local community and government","C":"As a supplier of raw materials","D":"As a shareholder seeking dividends"},"correctOption":"B","correctAnswer":"As part of the local community and government","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","distractor_reasons":{"A":"A local council is not usually a rival business competing to sell the same products in the market.","B":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","C":"The council is not providing raw materials to the firm in this situation, so it is not acting as a supplier.","D":"The council has not bought shares here, so it is not acting as a shareholder seeking dividends."}}},{"id":"P1_U1_MCQ_297","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_297","question":"Which objective is prioritized by the local community residing near a paper mill?","options":{"A":"Maximizing waste dumping in local rivers to cut business costs","B":"Maximizing share dividends paid to foreign equity investors","C":"Environmental safety, local job creation, and minimal pollution","D":"Replacing local staff with lower-cost offshore workers"},"correctOption":"C","correctAnswer":"Environmental safety, local job creation, and minimal pollution","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities want clean environments, minimal disruption, and local employment opportunities.","distractor_reasons":{"A":"Incorrect because communities strongly oppose environmental pollution.","B":"Incorrect because equity dividends do not benefit local residents.","C":"Option C is correct because local communities want clean environments, minimal disruption, and local employment opportunities.","D":"Incorrect because communities prefer local employment over offshore hiring."}}},{"id":"P1_U1_MCQ_298","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_298","question":"A manufacturing firm automates its packing plant, making 30 workers redundant to cut unit costs. Which stakeholder conflict does this action illustrate?","options":{"A":"Suppliers wanting prompt payment vs Customers wanting longer warranties","B":"Government seeking tax revenue vs Community seeking low traffic","C":"Bank lenders seeking interest vs Managers seeking larger offices","D":"Shareholders seeking higher profits vs Employees seeking job security"},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits vs Employees seeking job security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security.","distractor_reasons":{"A":"Incorrect because supplier payments and warranties do not involve automation redundancies.","B":"Incorrect because tax revenue and community traffic are not the primary issues in factory automation.","C":"Incorrect because bank interest and director offices do not reflect automation redundancies.","D":"Option D is correct because cost-cutting via automation boosts shareholder profit but creates job loss for workers seeking security."}}},{"id":"P1_U1_MCQ_299","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_299","question":"A distribution firm operates 24-hour truck fleets to maximize growth, but local residents protest against late-night noise. Which two stakeholders are in conflict?","options":{"A":"Managers/Shareholders and Local community","B":"Government and Lenders","C":"Suppliers and Customers","D":"Tax authorities and Employees"},"correctOption":"A","correctAnswer":"Managers/Shareholders and Local community","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","distractor_reasons":{"A":"Option A is correct because management's growth objective conflicts directly with the local community's demand for quiet night hours.","B":"Incorrect because government and lenders are not the primary parties involved in night noise complaints.","C":"Incorrect because suppliers and customers are not in conflict over local delivery noise.","D":"Incorrect because tax authorities are unrelated to noise pollution disputes."}}},{"id":"P1_U1_MCQ_300","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_300","question":"Bramble House Candles aims to increase the scale of its operations by opening new markets and increasing output over five years. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Social responsibility","D":"Short-term profit maximisation"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","distractor_reasons":{"A":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","B":"Survival is a short-term defensive aim of covering costs, not of expanding into new markets.","C":"Social responsibility concerns the effect on society and is not the objective described by expansion and higher output.","D":"Short-term profit maximisation focuses on immediate profit rather than a planned five-year expansion."}}},{"id":"P1_U1_MCQ_301","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_301","question":"A pottery manufacturer buys raw clay and glaze for $5 per vase and sells each finished vase for $25. Which action will directly increase the added value per vase by $5?","options":{"A":"Applying hand-painted designs and increasing the retail selling price to $30","B":"Increasing total factory vase output from 200 to 400 units per week","C":"Reducing kiln operator wages by $5 per day","D":"Purchasing $5 of extra raw clay to store in the stockroom"},"correctOption":"A","correctAnswer":"Applying hand-painted designs and increasing the retail selling price to $30","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus bought-in material costs ($25 - $5 = $20). Raising the price to $30 increases unit added value to $25, an increase of $5.","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus bought-in material costs ($25 - $5 = $20). Raising the price to $30 increases unit added value to $25, an increase of $5.","B":"Incorrect because increasing production volume affects total weekly profit potential, not unit added value.","C":"Incorrect because wages are operating overhead expenses, not bought-in material costs subtracted in added value calculations.","D":"Incorrect because storing extra raw material inventory increases stock assets without increasing unit added value."}}},{"id":"P1_U1_MCQ_302","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_302","question":"A clothing designer has enough fabric to produce either 20 evening gowns or 50 casual shirts. If the designer chooses to make 50 casual shirts, what is the opportunity cost?","options":{"A":"The financial cost of thread and buttons for the 50 casual shirts","B":"The 20 evening gowns that could have been produced instead","C":"The sales revenue collected from selling the 50 casual shirts","D":"The electricity cost of operating sewing machines"},"correctOption":"B","correctAnswer":"The 20 evening gowns that could have been produced instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative foregone when making a choice, which is the 20 evening gowns.","distractor_reasons":{"A":"Incorrect because material cost is a direct monetary expense.","B":"Option B is correct because opportunity cost is the next best alternative foregone when making a choice, which is the 20 evening gowns.","C":"Incorrect because revenue is the benefit of the chosen option, not the foregone alternative.","D":"Incorrect because electricity is an operational utility expense."}}},{"id":"P1_U1_MCQ_303","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_303","question":"A commercial bakery uses wheat crops, bakers, industrial ovens, and the owner's risk-taking vision. Which factor of production do the industrial ovens represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used in production.","distractor_reasons":{"A":"Incorrect because land covers natural resources like wheat crops.","B":"Incorrect because labour covers human physical and mental effort.","C":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used in production.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_304","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_304","question":"A car assembly plant implements division of labor by assigning a worker solely to attach front bumpers. What is a key limitation of this method?","options":{"A":"Workers take longer to learn their specific individual assembly task","B":"The purchase price of raw bumpers from suppliers increases","C":"Total hourly factory car output decreases","D":"Repetitive task execution can cause worker boredom, leading to reduced morale and quality errors"},"correctOption":"D","correctAnswer":"Repetitive task execution can cause worker boredom, leading to reduced morale and quality errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single narrow task leads to monotony, lowering motivation and increasing error rates.","distractor_reasons":{"A":"Incorrect because training a worker for a single task is fast and straightforward.","B":"Incorrect because internal division of labor does not alter external supplier pricing.","C":"Incorrect because specialization typically increases output efficiency.","D":"Option D is correct because repeating a single narrow task leads to monotony, lowering motivation and increasing error rates."}}},{"id":"P1_U1_MCQ_305","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_305","question":"Noah can use a small workshop in Bristol either to produce soy wax candles or to produce teak garden furniture. If Noah decides to produce soy wax candles, what is the opportunity cost?","options":{"A":"The profit earned from selling soy wax candles","B":"The teak garden furniture that could have been produced instead","C":"The rent already paid for the workshop","D":"The cost of materials used to make the chosen product"},"correctOption":"B","correctAnswer":"The teak garden furniture that could have been produced instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the value of the next best alternative forgone, here the teak garden furniture that cannot now be made.","distractor_reasons":{"A":"The profit from the chosen product is the benefit gained, not the value of the alternative that was given up.","B":"Option B is correct because opportunity cost is the value of the next best alternative forgone, here the teak garden furniture that cannot now be made.","C":"Rent already paid is a sunk cost incurred either way and is therefore not the opportunity cost of this decision.","D":"Material costs of the chosen product are an explicit cost of what was selected, not the forgone alternative."}}},{"id":"P1_U1_MCQ_306","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_306","question":"What fundamental cause creates the economic problem of scarcity in all countries?","options":{"A":"Government caps on maximum retail prices for consumer goods","B":"Finite economic resources being unable to satisfy infinite human wants","C":"Low corporate profit targets set by business executives","D":"An oversupply of skilled labor in urban regions"},"correctOption":"B","correctAnswer":"Finite economic resources being unable to satisfy infinite human wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally arises because limited factors of production cannot satisfy unlimited human wants.","distractor_reasons":{"A":"Incorrect because price caps are regulatory policies, not the root cause of scarcity.","B":"Option B is correct because scarcity fundamentally arises because limited factors of production cannot satisfy unlimited human wants.","C":"Incorrect because profit targets reflect business strategy, not resource availability.","D":"Incorrect because an oversupply of labor reduces scarcity of that factor."}}},{"id":"P1_U1_MCQ_307","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_307","question":"A shoemaker buys raw leather for $18 and rubber soles for $7 per pair of boots. The finished boots sell for $80. What is the added value per pair of boots?","options":{"A":"$25","B":"$62","C":"$55","D":"$80"},"correctOption":"C","correctAnswer":"$55","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs equal $18 + $7 = $25. Added value = selling price ($80) minus material costs ($25) = $55.","distractor_reasons":{"A":"Incorrect because $25 is the total material cost.","B":"Incorrect because $62 subtracts only leather cost ($80 - $18).","C":"Option C is correct because total bought-in material costs equal $18 + $7 = $25. Added value = selling price ($80) minus material costs ($25) = $55.","D":"Incorrect because $80 is the final retail price."}}},{"id":"P1_U1_MCQ_308","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_308","question":"An accountant quits a corporate job paying $55,000 per year to establish an independent tax consultancy. What is the opportunity cost of starting this new business?","options":{"A":"The office rent paid for consultancy premises","B":"The total client fees collected in Year 1","C":"The cost of buying office computers and accounting software","D":"The $55,000 corporate salary sacrificed"},"correctOption":"D","correctAnswer":"The $55,000 corporate salary sacrificed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $55,000 salary.","distractor_reasons":{"A":"Incorrect because rent is an operational monetary expenditure.","B":"Incorrect because client fees represent the gain from the chosen decision.","C":"Incorrect because computers and software are direct capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $55,000 salary."}}},{"id":"P1_U1_MCQ_309","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_309","question":"Which factor of production includes natural resources such as bauxite deposits, natural timber, and fresh river water?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural resources provided by nature used in economic output.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural resources provided by nature used in economic output.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Incorrect because capital refers to man-made assets like machinery.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_310","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_310","question":"How can a jewelry maker directly increase the added value of its rings without increasing their retail price?","options":{"A":"Increasing monthly spending on magazine advertising","B":"Renting a larger storage room for excess inventory","C":"Increasing hourly wages for workshop jewelers","D":"Securing lower purchase prices for raw precious metal inputs from suppliers"},"correctOption":"D","correctAnswer":"Securing lower purchase prices for raw precious metal inputs from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because added value equals selling price minus raw material costs. Lowering raw material input costs widens the added value gap.","distractor_reasons":{"A":"Incorrect because advertising is an operational overhead cost.","B":"Incorrect because renting storage increases fixed overheads.","C":"Incorrect because higher wages raise operating expenses, lowering profit rather than unit added value.","D":"Option D is correct because added value equals selling price minus raw material costs. Lowering raw material input costs widens the added value gap."}}},{"id":"P1_U1_MCQ_311","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_311","question":"A government-funded school in Belfast is owned and funded by the government to provide a service for the community. Which sector does it belong to?","options":{"A":"Private sector","B":"Public sector","C":"Primary sector","D":"Voluntary sector"},"correctOption":"B","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","distractor_reasons":{"A":"The private sector consists of businesses owned by private individuals or shareholders, not organisations funded and run by the government.","B":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","C":"The primary sector extracts natural resources and is unrelated to whether an organisation is government-owned.","D":"The voluntary sector is made up of charities and non-profit groups, which are separate from government-provided public services."}}},{"id":"P1_U1_MCQ_312","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_312","question":"What structural shift in employment occurs when an economy experiences deindustrialization?","options":{"A":"Workers move from service industries into primary crop farming","B":"The state nationalizes all private manufacturing firms","C":"Factory output doubles while service revenues decline rapidly","D":"Secondary manufacturing employment contracts while tertiary service employment expands"},"correctOption":"D","correctAnswer":"Secondary manufacturing employment contracts while tertiary service employment expands","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization involves a relative decline in secondary manufacturing output/jobs and growth in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs usually contract during deindustrialization.","B":"Incorrect because deindustrialization concerns sectoral shifts, not state ownership.","C":"Incorrect because manufacturing share declines relative to service growth.","D":"Option D is correct because deindustrialization involves a relative decline in secondary manufacturing output/jobs and growth in tertiary services."}}},{"id":"P1_U1_MCQ_313","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_313","question":"A furniture business cuts timber from its own woodland, makes stainless steel water bottles in a factory and sells them through its own shops. Which sectors does it operate in?","options":{"A":"Primary and secondary only","B":"Secondary and tertiary only","C":"Primary, secondary and tertiary","D":"Primary and tertiary only"},"correctOption":"C","correctAnswer":"Primary, secondary and tertiary","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","distractor_reasons":{"A":"This answer leaves out the retail shops, which are a tertiary activity, so it does not cover all the stages described.","B":"This answer omits the woodland timber extraction, which is a primary-sector activity carried out by the business.","C":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","D":"This answer misses the factory manufacturing stage, which is clearly a secondary-sector activity."}}},{"id":"P1_U1_MCQ_314","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_314","question":"A logging business cuts timber, a sawmill converts logs into wooden boards, and a construction firm uses the boards to build houses. How are these three activities classified?","options":{"A":"Logging: Secondary; Sawmilling: Primary; Construction: Tertiary","B":"Logging: Primary; Sawmilling: Secondary; Construction: Secondary","C":"Logging: Primary; Sawmilling: Tertiary; Construction: Secondary","D":"Logging: Tertiary; Sawmilling: Secondary; Construction: Primary"},"correctOption":"B","correctAnswer":"Logging: Primary; Sawmilling: Secondary; Construction: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting timber is primary (resource extraction), while both sawmilling and house construction process materials into finished structures (secondary sector).","distractor_reasons":{"A":"Incorrect because logging is primary extraction, not secondary.","B":"Option B is correct because cutting timber is primary (resource extraction), while both sawmilling and house construction process materials into finished structures (secondary sector).","C":"Incorrect because sawmilling is secondary processing, not tertiary service.","D":"Incorrect because the sector order is completely inaccurate."}}},{"id":"P1_U1_MCQ_315","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_315","question":"A low-income country builds many new factories and moves workers from farming into manufacturing in the Midlands. What is this process called?","options":{"A":"Industrialisation","B":"De-industrialisation","C":"Tertiarisation","D":"Privatisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because industrialisation is the process of developing manufacturing industry and shifting employment from agriculture into factories.","distractor_reasons":{"A":"Option A is correct because industrialisation is the process of developing manufacturing industry and shifting employment from agriculture into factories.","B":"De-industrialisation is the reverse process, in which manufacturing declines and factory jobs are lost.","C":"Tertiarisation would mean growth of service employment rather than a move into factory-based manufacturing.","D":"Privatisation is the transfer of state-owned assets to private owners and does not describe the growth of manufacturing."}}},{"id":"P1_U1_MCQ_316","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_316","question":"A private firm such as Tamarind Foods trades alongside government-run services in Bristol. Which statement best distinguishes the private sector from the public sector?","options":{"A":"Private-sector firms are owned by individuals or shareholders, while public-sector bodies are owned by the government","B":"Private-sector firms only provide services, while public-sector bodies only make goods","C":"Private-sector firms are always small, while public-sector bodies are always large","D":"Private-sector firms never employ workers, while public-sector bodies always do"},"correctOption":"A","correctAnswer":"Private-sector firms are owned by individuals or shareholders, while public-sector bodies are owned by the government","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ownership is the key difference: private firms belong to private investors, public bodies to the government.","distractor_reasons":{"A":"Option A is correct because ownership is the key difference: private firms belong to private investors, public bodies to the government.","B":"Both sectors can produce goods or provide services, so the type of output does not distinguish them.","C":"Business size is not the defining feature; private firms can be very large and public bodies can be small.","D":"Both private and public organisations employ workers, so employment is not a distinguishing characteristic."}}},{"id":"P1_U1_MCQ_317","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_317","question":"What main goal drives private sector business owners in a market economy?","options":{"A":"Earning profit to provide a financial return on invested capital","B":"Fulfilling production output targets set by state planners","C":"Providing free public goods to all citizens regardless of cost","D":"Maximizing annual corporate tax payments to municipal authorities"},"correctOption":"A","correctAnswer":"Earning profit to provide a financial return on invested capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profit is the primary commercial goal of private sector business owners.","distractor_reasons":{"A":"Option A is correct because earning profit is the primary commercial goal of private sector business owners.","B":"Incorrect because state production quotas belong to command economies.","C":"Incorrect because providing free public goods is a public sector objective.","D":"Incorrect because private firms manage tax legally rather than maximizing tax payments."}}},{"id":"P1_U1_MCQ_318","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_318","question":"Why might a national government choose to privatize a state-run water utility company?","options":{"A":"To grant permanent civil service employment status to utility staff","B":"To introduce market competition, profit incentives, and operational efficiency","C":"To eliminate private capital investment in national water infrastructure","D":"To increase direct state control over daily customer billing tariffs"},"correctOption":"B","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners to foster market competition, profit motives, and operational efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose civil service status.","B":"Option B is correct because privatization transfers state assets to private owners to foster market competition, profit motives, and operational efficiency.","C":"Incorrect because privatization invites private capital investment.","D":"Incorrect because privatization reduces direct state control."}}},{"id":"P1_U1_MCQ_319","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_319","question":"Which pair correctly matches an economic activity with its corresponding sector?","options":{"A":"Cotton farming - Secondary sector","B":"Furniture manufacturing - Primary sector","C":"Hotel management - Tertiary sector","D":"Oil extraction - Tertiary sector"},"correctOption":"C","correctAnswer":"Hotel management - Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hotel management provides hospitality services, which is a tertiary sector activity.","distractor_reasons":{"A":"Incorrect because cotton farming is primary sector agriculture.","B":"Incorrect because furniture manufacturing is secondary sector production.","C":"Option C is correct because hotel management provides hospitality services, which is a tertiary sector activity.","D":"Incorrect because oil extraction is primary sector resource extraction."}}},{"id":"P1_U1_MCQ_320","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_320","question":"What structural employment shift typically occurs as a developing country undergoes rapid industrialization?","options":{"A":"Labor shifts out of secondary manufacturing into primary farming","B":"Tertiary service businesses close down completely to prioritize mining","C":"Public sector entities take over 100% of all private retail shops","D":"Labor moves out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Labor moves out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization is defined by expanding manufacturing factories, drawing labor from primary agriculture into secondary production.","distractor_reasons":{"A":"Incorrect because labor moves from farming into manufacturing, not the reverse.","B":"Incorrect because service industries expand alongside industrialization.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization is defined by expanding manufacturing factories, drawing labor from primary agriculture into secondary production."}}},{"id":"P1_U1_MCQ_321","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_321","question":"Which quality is essential for a successful entrepreneur starting a new commercial venture?","options":{"A":"Self-motivation, willingness to accept calculated risk, and resilience after setbacks","B":"Preference for working under direct managerial supervision in established firms","C":"Reluctance to adapt business strategies when customer demand shifts","D":"Avoidance of personal financial responsibility for business liabilities"},"correctOption":"A","correctAnswer":"Self-motivation, willingness to accept calculated risk, and resilience after setbacks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early challenges.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early challenges.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Incorrect because flexibility is vital to entrepreneurial success.","D":"Incorrect because entrepreneurs bear and manage business risks."}}},{"id":"P1_U1_MCQ_322","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_322","question":"An analyst wants to compare the size of Highland Woollens with other firms in the same industry. Which of these is a measure of business size?","options":{"A":"Gross profit margin","B":"Number of employees","C":"Current ratio","D":"Return on capital employed"},"correctOption":"B","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","distractor_reasons":{"A":"Gross profit margin measures profitability relative to revenue, not the physical scale or size of the business.","B":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","C":"The current ratio measures short-term liquidity and says nothing about how large the business is.","D":"Return on capital employed is a profitability ratio rather than a measure of the size of the business."}}},{"id":"P1_U1_MCQ_323","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_323","question":"Appleton Electrics has grown very rapidly over two years. Which is most likely to be a problem caused by such rapid growth?","options":{"A":"Its shareholders are no longer entitled to any dividend","B":"The business automatically gains a monopoly position","C":"Its products immediately become lower in price than all rivals","D":"Communication and decision-making become slower as the organisation grows"},"correctOption":"D","correctAnswer":"Communication and decision-making become slower as the organisation grows","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","distractor_reasons":{"A":"Shareholders keep their dividend rights regardless of how quickly the business expands.","B":"Rapid growth does not automatically create a monopoly, which would require dominance of the whole market.","C":"Growth gives no guarantee of lower prices than competitors, which depend on costs and pricing decisions.","D":"Option D is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions."}}},{"id":"P1_U1_MCQ_324","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_324","question":"What is the most likely immediate cause of failure for a newly established business such as Stonebridge Logistics?","options":{"A":"Paying dividends to shareholders","B":"Having too few customers relative to its production capacity","C":"Unable to obtain any market research data","D":"Sustained cash-flow shortages leaving it unable to pay bills when due"},"correctOption":"D","correctAnswer":"Sustained cash-flow shortages leaving it unable to pay bills when due","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","distractor_reasons":{"A":"Paying dividends is a choice made from profits and is not a typical cause of a new business failing.","B":"Too few customers is a symptom of weak demand, but the immediate trigger of failure is usually the resulting cash shortage.","C":"A lack of market research raises risk but does not by itself prevent a business from trading.","D":"Option D is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations."}}},{"id":"P1_U1_MCQ_325","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_325","question":"In Newcastle, which measure is most likely to be used by a government to support people starting new businesses?","options":{"A":"Grants or low-interest loans specifically for start-ups","B":"Higher taxes on all new firms","C":"A ban on selling to overseas customers","D":"Requiring every start-up to become a public limited company"},"correctOption":"A","correctAnswer":"Grants or low-interest loans specifically for start-ups","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","distractor_reasons":{"A":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","B":"Higher taxes would discourage rather than help new businesses by reducing their available funds.","C":"Banning overseas sales would restrict market access and hinder the growth of new firms.","D":"Start-ups are not required to become public limited companies; many begin as sole traders or private limited companies."}}},{"id":"P1_U1_MCQ_326","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_326","question":"Pinehurst Paper and an overseas company create a jointly owned business in Stirling to share costs and expertise. What is this arrangement called?","options":{"A":"A sole trader business","B":"A franchise","C":"Internal growth","D":"A joint venture"},"correctOption":"D","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","distractor_reasons":{"A":"A sole trader business has a single owner, which is the opposite of a jointly owned venture.","B":"A franchise involves one party paying to use another's brand and system, not creating a jointly owned company.","C":"Internal growth is expansion from within; here two separate firms combine resources externally.","D":"Option D is correct because a joint venture is a business set up and owned jointly by two or more independent organisations."}}},{"id":"P1_U1_MCQ_327","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_327","question":"Rather than buying another firm, Ashgrove Travel develops and launches woollen jumpers using its own research team and spare cash. What type of growth is this?","options":{"A":"Backward vertical integration","B":"External takeover","C":"Internal (organic) growth","D":"Horizontal integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","distractor_reasons":{"A":"Backward vertical integration requires acquiring a supplier, which has not happened here.","B":"An external takeover means buying another business; this firm grew without acquiring one.","C":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","D":"Horizontal integration involves combining with another firm at the same stage of an industry."}}},{"id":"P1_U1_MCQ_328","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_328","question":"Bluepeak Software opens three new branches in Oxfordshire using profits retained from the previous year. What type of growth is this?","options":{"A":"Internal (organic) growth","B":"Horizontal integration","C":"Backward vertical integration","D":"A takeover"},"correctOption":"A","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","distractor_reasons":{"A":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","B":"Horizontal integration means joining with another firm at the same stage of production, usually through a merger or takeover.","C":"Backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"A takeover is external growth involving the purchase of another company rather than expansion using internal funds."}}},{"id":"P1_U1_MCQ_329","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_329","question":"Stonebridge Logistics, a chain of coffee shops, takes over a rival chain of coffee shops in Leeds. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","distractor_reasons":{"A":"Forward vertical integration means moving closer to the final customer, such as a producer buying retail outlets.","B":"Backward vertical integration means moving towards suppliers, such as a retailer buying a manufacturing plant.","C":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","D":"Internal growth uses a firm's own resources; taking over a rival is external growth through acquisition."}}},{"id":"P1_U1_MCQ_330","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_330","question":"A manufacturer of fresh orange juice buys a chain of retail stores that sell its goods to the public. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Organic growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","distractor_reasons":{"A":"Backward vertical integration would involve acquiring a supplier further from the consumer, not a retailer near the end customer.","B":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","C":"Horizontal integration involves a firm at the same production stage, whereas a retailer is at a later stage of the chain.","D":"Organic growth is internal expansion, while purchasing an established retail chain is an external acquisition."}}},{"id":"P1_U1_MCQ_331","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_331","question":"Two competing firms in Newcastle decide to form a jointly owned new company to develop a shared distribution network. What is this?","options":{"A":"A merger into a single existing firm","B":"A joint venture","C":"A sole trader","D":"An internal expansion"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","distractor_reasons":{"A":"A merger combines existing businesses into one, rather than setting up a separate jointly owned company.","B":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","C":"A sole trader has one owner, whereas here two firms jointly own the new company.","D":"Internal expansion uses a firm's own resources rather than a partnership with another business."}}},{"id":"P1_U1_MCQ_332","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_332","question":"A business such as Oakfield Furniture has owners with limited liability and shares that cannot be traded on a stock exchange. Which type of organisation is it?","options":{"A":"Sole trader","B":"Private limited company such as Oakfield Furniture","C":"Public limited company","D":"Partnership"},"correctOption":"B","correctAnswer":"Private limited company such as Oakfield Furniture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","distractor_reasons":{"A":"A sole trader has unlimited liability, so it does not meet the limited-liability condition in the question.","B":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","C":"A public limited company has shares that can be traded on a stock exchange, which this question rules out.","D":"A traditional partnership gives owners unlimited liability rather than limited liability."}}},{"id":"P1_U1_MCQ_333","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_333","question":"Fatima runs a business selling artisan sourdough loaves as a sole trader. What is the position regarding liability for the business debts?","options":{"A":"Fatima has unlimited liability and is personally responsible for all the debts","B":"Fatima has limited liability and risks only the money invested","C":"Liability is shared equally with the government","D":"There is no liability because the business is not registered"},"correctOption":"A","correctAnswer":"Fatima has unlimited liability and is personally responsible for all the debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","distractor_reasons":{"A":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","B":"Limited liability applies to shareholders in limited companies, not to a sole trader who personally owns the business.","C":"The government does not share a sole trader's debts; the owner alone is responsible for them.","D":"Registering the business does not remove liability; a sole trader remains personally liable whether registered or not."}}},{"id":"P1_U1_MCQ_334","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_334","question":"Yusuf starts a business in the West Country with two friends, sharing ownership and management. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Public corporation"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","distractor_reasons":{"A":"A sole trader has a single owner, whereas this business has several owners sharing management.","B":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","C":"A public limited company sells shares on a stock exchange and has limited liability, unlike a simple partnership.","D":"A public corporation is government-owned and provides a public service, which is not the case here."}}},{"id":"P1_U1_MCQ_335","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_335","question":"Westfield Mills is a private limited company. What does limited liability mean for its shareholders?","options":{"A":"They are responsible for all company debts with their personal property","B":"They can only lose the amount they invested in shares and no more","C":"They are forbidden from selling their shares to anyone else","D":"They receive a guaranteed annual salary from the company"},"correctOption":"B","correctAnswer":"They can only lose the amount they invested in shares and no more","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","distractor_reasons":{"A":"Personal property is only at risk for owners with unlimited liability such as sole traders and ordinary partners.","B":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","C":"Shareholders in a private limited company may sell shares, subject to any restrictions in the company's rules.","D":"Shareholders are not employees and have no automatic right to a salary; they may receive dividends if profits allow."}}},{"id":"P1_U1_MCQ_336","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_336","question":"Which feature distinguishes a public limited company such as Tamarind Foods from a private limited company?","options":{"A":"Its shares can be bought and sold on a stock exchange","B":"Its owners have unlimited liability for all debts","C":"It must be owned by exactly one person","D":"It cannot employ any staff"},"correctOption":"A","correctAnswer":"Its shares can be bought and sold on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","distractor_reasons":{"A":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","B":"Both private and public limited companies give shareholders limited liability, so this is not a distinguishing feature.","C":"A public limited company needs at least two shareholders and cannot be owned by a single person in the way described.","D":"Public limited companies employ staff just like other business organisations, so this is not a distinguishing feature."}}},{"id":"P1_U1_MCQ_337","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_337","question":"Oliver pays a fee to use the well-known brand and business model of Oakfield Furniture. What is this arrangement called?","options":{"A":"A joint venture","B":"A public corporation","C":"A partnership","D":"A franchise"},"correctOption":"D","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","distractor_reasons":{"A":"A joint venture involves joint ownership of a new business, not paying for the right to use an existing brand.","B":"A public corporation is government-owned and is unrelated to this private fee-paying arrangement.","C":"A partnership shares ownership and management between partners rather than licensing a brand for a fee.","D":"Option D is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system."}}},{"id":"P1_U1_MCQ_338","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_338","question":"An organisation is wholly owned by the government and provides an essential public service in Devon. What is it called?","options":{"A":"A public corporation","B":"A sole trader","C":"A private limited company","D":"A franchise"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","distractor_reasons":{"A":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","B":"A sole trader is a privately owned one-person business, not a government-owned organisation.","C":"A private limited company is owned by private shareholders and is not wholly owned by the government.","D":"A franchise is a private commercial arrangement to use a brand, not a government-owned public service body."}}},{"id":"P1_U1_MCQ_339","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_339","question":"What is a dividend in the context of a company such as Summit Cycling?","options":{"A":"A share of company profits paid out to shareholders","B":"The total value of the company's fixed assets","C":"A tax that the company pays to the government only","D":"The wage paid to the highest-paid employee"},"correctOption":"A","correctAnswer":"A share of company profits paid out to shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","distractor_reasons":{"A":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","B":"The value of fixed assets appears in the statement of financial position and is not a payment to shareholders.","C":"Company tax is paid to the government, whereas a dividend is paid to the owners of the business.","D":"Wages are payments to employees for labour, not distributions of profit to shareholders."}}},{"id":"P1_U1_MCQ_340","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_340","question":"Which statement about a sole trader such as Daniel selling trail running shoes is correct?","options":{"A":"The owner keeps all the profits but has unlimited liability","B":"The owner must share all profits with the government","C":"The owner has limited liability and pays no tax","D":"The owner cannot make any business decisions alone"},"correctOption":"A","correctAnswer":"The owner keeps all the profits but has unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","distractor_reasons":{"A":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","B":"The owner keeps the profits but pays tax on them; profits are not shared with the government as owners' earnings.","C":"A sole trader has unlimited liability, not limited liability, and is still liable to pay income tax on profits.","D":"A sole trader makes the business decisions alone, which is one of the advantages of this form of organisation."}}},{"id":"P1_U1_MCQ_341","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_341","question":"Mapleton Printing sets its output and price to earn the largest possible total profit. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Sales revenue maximisation","C":"Market share leadership","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","distractor_reasons":{"A":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","B":"Sales revenue maximisation focuses on total sales value rather than on the difference between revenue and cost.","C":"Market share leadership aims at a large share of industry sales and may accept lower profits to achieve it.","D":"Survival means covering costs to stay in business, which is a more short-term and defensive aim."}}},{"id":"P1_U1_MCQ_342","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_342","question":"Facing falling demand in Derbyshire, Fernhill Pharmaceuticals concentrates on covering its costs and staying in business. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","distractor_reasons":{"A":"Growth means increasing sales, output or the size of the business, which is not the priority when simply staying afloat.","B":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","C":"Profit maximisation seeks the highest profit, whereas here the firm only aims to cover its costs.","D":"Social responsibility concerns the impact on society and is not the aim described in this difficult trading situation."}}},{"id":"P1_U1_MCQ_343","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_343","question":"Greenfield Organics wants to raise its percentage of total industry sales in the coming year. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Increasing market share","D":"Cost minimisation alone"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","distractor_reasons":{"A":"Profit maximisation targets the largest profit, which may not coincide with selling a larger share of the market.","B":"Survival is about covering costs and continuing to trade rather than winning a greater share of sales.","C":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","D":"Cost minimisation concerns reducing expenses and does not directly describe gaining a larger share of industry sales."}}},{"id":"P1_U1_MCQ_344","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_344","question":"Silverstream Bottling aims to sell as many units as possible, even if profit per unit is low. Which objective is this?","options":{"A":"Sales revenue maximisation","B":"Survival","C":"Social enterprise","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Sales revenue maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","distractor_reasons":{"A":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","B":"Survival only requires covering costs, whereas this firm deliberately pursues a high volume of sales.","C":"A social enterprise reinvests profits for a social purpose, which is different from maximising sales revenue.","D":"Profit maximisation would not knowingly accept low profit per unit in order to boost sales volume."}}},{"id":"P1_U1_MCQ_345","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_345","question":"A business in Bristol, founded by Liam, reinvests its surplus to tackle a social or environmental problem. What is this business called?","options":{"A":"A social enterprise","B":"A public corporation","C":"A sole trader focused only on profit","D":"A franchise"},"correctOption":"A","correctAnswer":"A social enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","distractor_reasons":{"A":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","B":"A public corporation is government-owned and provides public services, which is different from a mission-led trading business.","C":"A profit-only sole trader does not reinvest surpluses specifically to address a social or environmental problem.","D":"A franchise uses another firm's brand and system and is not defined by a social reinvestment purpose."}}},{"id":"P1_U1_MCQ_346","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_346","question":"In a business such as Pinehurst Paper, which situation shows a clear conflict of interest between two stakeholder groups?","options":{"A":"Shareholders want higher dividends while employees want higher wages","B":"Customers want lower prices and better quality","C":"The government collects taxes from profitable firms","D":"Suppliers deliver raw materials on the agreed date"},"correctOption":"A","correctAnswer":"Shareholders want higher dividends while employees want higher wages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","distractor_reasons":{"A":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","B":"Customers wanting lower prices and better quality is a single group's preference, not a conflict between two stakeholder groups.","C":"Tax collection is a standard obligation and does not by itself describe opposing demands from two stakeholder groups.","D":"On-time delivery by suppliers is normal performance and involves no clash of competing interests."}}},{"id":"P1_U1_MCQ_347","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_347","question":"A firm that supplies raw materials to Bluepeak Software is which of its stakeholders?","options":{"A":"A customer","B":"A shareholder","C":"A supplier","D":"A competitor"},"correctOption":"C","correctAnswer":"A supplier","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","distractor_reasons":{"A":"A customer buys the finished goods from the business rather than providing raw materials to it.","B":"A shareholder owns part of the business, which is a different relationship from selling it inputs.","C":"Option C is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","D":"A competitor sells rival products in the same market rather than supplying this business."}}},{"id":"P1_U1_MCQ_348","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_348","question":"Which is a typical objective of a public-sector organisation such as a state-funded hospital in Belfast?","options":{"A":"To maximise dividends for private shareholders","B":"To provide a service for the community rather than to maximise profit","C":"To avoid serving customers who cannot pay","D":"To keep prices as high as the market will bear"},"correctOption":"B","correctAnswer":"To provide a service for the community rather than to maximise profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","distractor_reasons":{"A":"Public-sector organisations do not have private shareholders seeking dividends, so this cannot be their objective.","B":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","C":"Public services generally aim to be accessible to the whole community, including those who cannot afford to pay.","D":"Charging the highest possible prices is a private profit-seeking objective, not the aim of a public service provider."}}},{"id":"P1_U1_MCQ_349","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_349","question":"What is usually the primary objective of a private-sector business such as Evergreen Gardens?","options":{"A":"To make a profit","B":"To provide free public services","C":"To avoid all competition","D":"To be owned by the state"},"correctOption":"A","correctAnswer":"To make a profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","distractor_reasons":{"A":"Option A is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","B":"Providing free public services is typical of the public sector, not of privately owned businesses seeking a return.","C":"Businesses cannot normally avoid competition, which is a feature of the market in which they operate.","D":"Private-sector firms are owned by private individuals or shareholders, not by the state."}}},{"id":"P1_U1_MCQ_350","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_350","question":"Which group is most directly interested in Pinehurst Paper paying competitive wages and offering safe working conditions?","options":{"A":"Its employees","B":"Its customers","C":"Its shareholders","D":"Its local suppliers"},"correctOption":"A","correctAnswer":"Its employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","distractor_reasons":{"A":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","B":"Customers are mainly concerned with the price, quality and availability of the products they buy.","C":"Shareholders are primarily interested in returns on their investment and the profitability of the business.","D":"Suppliers are mainly interested in receiving payment and maintaining orders for their materials."}}},{"id":"P1_U1_MCQ_351","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_351","question":"A metal fabricator buys raw steel for $20 and plastic fittings for $5 per chair frame. The finished frame sells for $60. Which action will directly increase the added value per chair frame by $10?","options":{"A":"Purchasing $10 of additional raw steel stock for inventory","B":"Increasing daily factory frame output from 100 to 150 units","C":"Reducing welder overtime pay by $10 per day","D":"Applying powder coating and raising the selling price to $70"},"correctOption":"D","correctAnswer":"Applying powder coating and raising the selling price to $70","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because added value equals selling price minus bought-in material costs ($60 - $25 = $35). Raising the price to $70 increases unit added value to $45, an increase of $10.","distractor_reasons":{"A":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value.","B":"Incorrect because increasing daily output alters total volume profit potential, not unit added value.","C":"Incorrect because overtime pay is an operational labor expense, not a bought-in material cost.","D":"Option D is correct because added value equals selling price minus bought-in material costs ($60 - $25 = $35). Raising the price to $70 increases unit added value to $45, an increase of $10."}}},{"id":"P1_U1_MCQ_352","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_352","question":"A vineyard has enough land capacity to harvest either 500 cases of Pinot Noir or 800 cases of Chardonnay. If the vineyard owner chooses to harvest 800 cases of Chardonnay, what is the opportunity cost?","options":{"A":"The financial cost of bottles and corks used for Chardonnay","B":"The 500 cases of Pinot Noir that could have been harvested instead","C":"The sales revenue collected from selling Chardonnay cases","D":"The fuel cost of operating grape harvesting tractors"},"correctOption":"B","correctAnswer":"The 500 cases of Pinot Noir that could have been harvested instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 500 cases of Pinot Noir.","distractor_reasons":{"A":"Incorrect because packaging materials are direct production expenses.","B":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic decision, which is the 500 cases of Pinot Noir.","C":"Incorrect because revenue is the financial gain from the chosen option, not the foregone alternative.","D":"Incorrect because fuel is an operational machinery expense."}}},{"id":"P1_U1_MCQ_353","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_353","question":"A textile manufacturer uses raw cotton, machine operators, weaving looms, and an innovative managing director. Which factor of production do the weaving looms represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment and machinery used in manufacturing.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like raw cotton.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Option C is correct because capital consists of man-made physical equipment and machinery used in manufacturing.","D":"Incorrect because enterprise is the risk-taking organizational function."}}},{"id":"P1_U1_MCQ_354","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_354","question":"An electronics factory introduces division of labor by assigning a worker exclusively to solder circuit board capacitors. What is a key disadvantage of this operational method?","options":{"A":"Workers require longer initial training to perform their single task","B":"The wholesale price of capacitors from suppliers increases","C":"Hourly production rate of circuit boards decreases","D":"Monotony and task repetition lower worker morale, potentially causing quality errors"},"correctOption":"D","correctAnswer":"Monotony and task repetition lower worker morale, potentially causing quality errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because performing a single repetitive task continuously leads to boredom, lower motivation, and potential quality flaws.","distractor_reasons":{"A":"Incorrect because training a worker for a single task is fast and simple.","B":"Incorrect because internal division of labor does not alter external supplier pricing.","C":"Incorrect because specialization generally increases hourly output.","D":"Option D is correct because performing a single repetitive task continuously leads to boredom, lower motivation, and potential quality flaws."}}},{"id":"P1_U1_MCQ_355","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_355","question":"Which of the following items represents a basic human need essential for survival?","options":{"A":"Basic shelter and clean drinking water","B":"A subscription to a satellite television network","C":"A luxury wristwatch","D":"An annual pass to a theme park"},"correctOption":"A","correctAnswer":"Basic shelter and clean drinking water","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shelter and clean water are essential physical requirements for human survival.","distractor_reasons":{"A":"Option A is correct because shelter and clean water are essential physical requirements for human survival.","B":"Incorrect because satellite TV is an entertainment want.","C":"Incorrect because a luxury wristwatch is a non-essential lifestyle want.","D":"Incorrect because theme park passes are leisure wants."}}},{"id":"P1_U1_MCQ_356","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_356","question":"Why does the economic problem of scarcity affect all nations regardless of their income level?","options":{"A":"Governments fix maximum prices on imported food products","B":"Limited factors of production cannot satisfy unlimited human needs and wants","C":"Commercial businesses deliberately restrict sales output to lower taxes","D":"Excess supply of skilled labor reduces national output"},"correctOption":"B","correctAnswer":"Limited factors of production cannot satisfy unlimited human needs and wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally exists because finite economic resources cannot fulfill infinite human wants.","distractor_reasons":{"A":"Incorrect because price fixes are government policies, not the root cause of scarcity.","B":"Option B is correct because scarcity fundamentally exists because finite economic resources cannot fulfill infinite human wants.","C":"Incorrect because corporate tax strategies do not cause economic resource scarcity.","D":"Incorrect because excess labor supply reduces scarcity of that factor."}}},{"id":"P1_U1_MCQ_357","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_357","question":"A leather goods maker purchases raw hide for $22 and metal buckles for $8 per belt. The finished belt is sold for $75. What is the added value per belt?","options":{"A":"$30","B":"$53","C":"$45","D":"$75"},"correctOption":"C","correctAnswer":"$45","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bought-in material costs equal $22 + $8 = $30. Added value = selling price ($75) minus material costs ($30) = $45.","distractor_reasons":{"A":"Incorrect because $30 is the total bought-in material cost.","B":"Incorrect because $53 subtracts only hide cost ($75 - $22), ignoring buckle costs.","C":"Option C is correct because bought-in material costs equal $22 + $8 = $30. Added value = selling price ($75) minus material costs ($30) = $45.","D":"Incorrect because $75 is the final retail price."}}},{"id":"P1_U1_MCQ_358","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_358","question":"A financial analyst quits a corporate position earning $70,000 annually to set up a private investment advisory firm. What is the opportunity cost of starting this enterprise?","options":{"A":"The monthly rental payment for office space","B":"The total advisory fees collected from clients in Year 1","C":"The capital spent on computers and office furniture","D":"The $70,000 corporate analyst salary foregone"},"correctOption":"D","correctAnswer":"The $70,000 corporate analyst salary foregone","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the foregone benefit of the next best alternative given up, which is the $70,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is a direct monetary expenditure.","B":"Incorrect because advisory fees are the financial return from the chosen option.","C":"Incorrect because furniture and computers are capital outlays.","D":"Option D is correct because opportunity cost measures the foregone benefit of the next best alternative given up, which is the $70,000 salary."}}},{"id":"P1_U1_MCQ_359","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_359","question":"Which factor of production encompasses natural resources such as crude oil reserves, fertile soil, and iron ore deposits?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all natural gifts of nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land covers all natural gifts of nature used in economic production.","B":"Incorrect because labour refers to human work effort.","C":"Incorrect because capital refers to man-made physical equipment and tools.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_360","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_360","question":"How can a custom watchmaker directly increase the added value of its timepieces without raising their retail price?","options":{"A":"Increasing monthly spending on social media advertising","B":"Securing lower purchase prices for raw watch casings from component suppliers","C":"Increasing hourly wage rates for watchmakers","D":"Leasing a larger warehouse for spare component parts"},"correctOption":"B","correctAnswer":"Securing lower purchase prices for raw watch casings from component suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering raw material costs widens the added value margin.","distractor_reasons":{"A":"Incorrect because social media advertising is an operational overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering raw material costs widens the added value margin.","C":"Incorrect because higher wages increase overhead operational costs, reducing profit rather than unit added value.","D":"Incorrect because leasing a warehouse increases fixed overhead costs."}}},{"id":"P1_U1_MCQ_361","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_361","question":"Which commercial activity is classified within the primary economic sector?","options":{"A":"Assembling heavy machinery in an industrial plant","B":"Providing tax advisory services to small businesses","C":"Commercial deep-sea fishing for tuna","D":"Operating a retail department store"},"correctOption":"C","correctAnswer":"Commercial deep-sea fishing for tuna","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because commercial deep-sea fishing directly extracts natural resources from the environment (primary sector).","distractor_reasons":{"A":"Incorrect because machinery assembly is secondary sector manufacturing.","B":"Incorrect because tax advisory is a tertiary professional service.","C":"Option C is correct because commercial deep-sea fishing directly extracts natural resources from the environment (primary sector).","D":"Incorrect because department store retailing is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_362","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_362","question":"What structural shift in employment takes place when an economy undergoes deindustrialization?","options":{"A":"Labor moves out of service industries into primary farming","B":"The state takes complete ownership of all manufacturing plants","C":"Factory output doubles while service sector revenues decline","D":"Employment declines in secondary manufacturing and expands in tertiary services"},"correctOption":"D","correctAnswer":"Employment declines in secondary manufacturing and expands in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization involves a relative contraction in secondary manufacturing and growth in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs usually decline during deindustrialization.","B":"Incorrect because deindustrialization concerns sectoral shifts, not state ownership.","C":"Incorrect because manufacturing share contracts relative to services.","D":"Option D is correct because deindustrialization involves a relative contraction in secondary manufacturing and growth in tertiary services."}}},{"id":"P1_U1_MCQ_363","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_363","question":"A worker is fishing for cod at sea in Norfolk. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"A","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature.","distractor_reasons":{"A":"Option A is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature.","B":"The secondary sector manufactures or processes materials into finished goods, which is not what extracting a natural resource involves.","C":"The tertiary sector provides services to consumers and businesses rather than extracting raw materials from the natural environment.","D":"Public sector refers to government ownership, a different classification from the primary, secondary and tertiary sectors."}}},{"id":"P1_U1_MCQ_364","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_364","question":"A forestry firm cuts down trees, a paper mill processes wood pulp into rolls of paper, and a printing house uses the paper to print books. How are these three activities categorized?","options":{"A":"Forestry: Secondary; Paper milling: Primary; Printing: Tertiary","B":"Forestry: Primary; Paper milling: Secondary; Printing: Secondary","C":"Forestry: Primary; Paper milling: Tertiary; Printing: Secondary","D":"Forestry: Tertiary; Paper milling: Secondary; Printing: Primary"},"correctOption":"B","correctAnswer":"Forestry: Primary; Paper milling: Secondary; Printing: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting trees is primary (resource extraction), while both paper milling and printing transform raw materials into processed products (secondary sector).","distractor_reasons":{"A":"Incorrect because forestry is primary extraction, not secondary.","B":"Option B is correct because cutting trees is primary (resource extraction), while both paper milling and printing transform raw materials into processed products (secondary sector).","C":"Incorrect because paper milling is secondary processing, not tertiary service.","D":"Incorrect because sector order is inverted."}}},{"id":"P1_U1_MCQ_365","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_365","question":"A worker is refining raw sugar in Lancashire. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","distractor_reasons":{"A":"The primary sector extracts natural resources in their raw state; assembling or processing materials is a manufacturing activity instead.","B":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","C":"The tertiary sector is concerned with providing services, not with the physical conversion of materials into products.","D":"Public sector describes who owns an organisation, not the type of productive activity being carried out."}}},{"id":"P1_U1_MCQ_366","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_366","question":"Which activity operates entirely within the tertiary economic sector?","options":{"A":"Coal mining extraction","B":"Automobile body stamping","C":"Wheat harvesting","D":"Commercial logistics and freight transport"},"correctOption":"D","correctAnswer":"Commercial logistics and freight transport","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because transport and logistics provide commercial services, placing them in the tertiary sector.","distractor_reasons":{"A":"Incorrect because coal mining is primary extraction.","B":"Incorrect because body stamping is secondary manufacturing.","C":"Incorrect because wheat harvesting is primary agriculture.","D":"Option D is correct because transport and logistics provide commercial services, placing them in the tertiary sector."}}},{"id":"P1_U1_MCQ_367","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_367","question":"A worker is repairing household appliances in Oxfordshire. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","distractor_reasons":{"A":"The primary sector involves extracting raw materials from nature, which is different from providing a service to a customer.","B":"The secondary sector makes physical products by processing materials, whereas this activity involves delivering a service.","C":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","D":"Public sector refers to government ownership and is not one of the three productive sectors being described here."}}},{"id":"P1_U1_MCQ_368","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_368","question":"Why might a national government choose to privatize a state-run telecom provider?","options":{"A":"To grant civil service employment status to all telecom staff","B":"To introduce market competition, profit incentives, and operational efficiency","C":"To eliminate private capital investment in national telecommunications infrastructure","D":"To increase direct state control over daily internet billing rates"},"correctOption":"B","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners to foster market competition, profit motives, and operational efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Option B is correct because privatization transfers state assets to private owners to foster market competition, profit motives, and operational efficiency.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct state control."}}},{"id":"P1_U1_MCQ_369","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_369","question":"Over twenty years Leeds has seen its large factories close and employment shift towards shops, offices and services. What is this change called?","options":{"A":"Industrialisation","B":"De-industrialisation","C":"Primary-sector expansion","D":"Nationalisation"},"correctOption":"B","correctAnswer":"De-industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","distractor_reasons":{"A":"Industrialisation is the opposite process, building up manufacturing industry rather than losing it.","B":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","C":"Primary-sector expansion would mean more farming, mining or fishing, not the closure of factories and growth of services.","D":"Nationalisation means transferring private assets into government ownership and is unrelated to the decline of manufacturing jobs."}}},{"id":"P1_U1_MCQ_370","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_370","question":"A state-run hospital in Stirling is owned and funded by the government to provide a service for the community. Which sector does it belong to?","options":{"A":"Private sector","B":"Public sector","C":"Primary sector","D":"Voluntary sector"},"correctOption":"B","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","distractor_reasons":{"A":"The private sector consists of businesses owned by private individuals or shareholders, not organisations funded and run by the government.","B":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","C":"The primary sector extracts natural resources and is unrelated to whether an organisation is government-owned.","D":"The voluntary sector is made up of charities and non-profit groups, which are separate from government-provided public services."}}},{"id":"P1_U1_MCQ_371","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_371","question":"A company making soy wax candles purchases the business that supplies its raw ingredients. What type of growth has taken place?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","distractor_reasons":{"A":"Forward vertical integration means moving towards the customer, such as buying distributors, not acquiring a supplier.","B":"Horizontal integration joins firms at the same stage of activity, whereas a raw-material supplier is at an earlier stage.","C":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"Internal growth is funded and achieved within the business, while buying a supplier is an external acquisition."}}},{"id":"P1_U1_MCQ_372","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_372","question":"Yusuf is setting up a business in Newcastle. Which action best describes the role of an entrepreneur?","options":{"A":"Taking financial risk and organising resources to create and run a business","B":"Receiving a fixed salary for carrying out routine office work","C":"Guaranteeing that the business will never face competition","D":"Owning the business but avoiding all decision-making"},"correctOption":"A","correctAnswer":"Taking financial risk and organising resources to create and run a business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","distractor_reasons":{"A":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","B":"A fixed salary for routine work describes an employee, not an entrepreneur who bears risk and organises the business.","C":"No entrepreneur can guarantee the absence of competition, which is outside their control in a market.","D":"Entrepreneurs are actively involved in decisions; avoiding all decision-making is not an entrepreneurial role."}}},{"id":"P1_U1_MCQ_373","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_373","question":"Ethan is preparing a business plan before launching a new venture. What is the main purpose of a business plan?","options":{"A":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","B":"To guarantee that the business will make a profit in its first year","C":"To remove the need for any market research before launching","D":"To avoid having to keep any accounting records"},"correctOption":"A","correctAnswer":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","distractor_reasons":{"A":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","B":"A plan cannot guarantee profit, which depends on future trading conditions and many factors outside the plan.","C":"A business plan supports rather than replaces market research, which remains necessary to understand customers.","D":"A business plan does not remove the legal and practical need to keep proper financial records."}}},{"id":"P1_U1_MCQ_374","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_374","question":"An analyst wants to compare the size of Ironbridge Engineering with other firms in the same industry. Which of these is a measure of business size?","options":{"A":"Gross profit margin","B":"Number of employees","C":"Current ratio","D":"Return on capital employed"},"correctOption":"B","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","distractor_reasons":{"A":"Gross profit margin measures profitability relative to revenue, not the physical scale or size of the business.","B":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","C":"The current ratio measures short-term liquidity and says nothing about how large the business is.","D":"Return on capital employed is a profitability ratio rather than a measure of the size of the business."}}},{"id":"P1_U1_MCQ_375","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_375","question":"Highland Woollens has grown very rapidly over two years. Which is most likely to be a problem caused by such rapid growth?","options":{"A":"Its shareholders are no longer entitled to any dividend","B":"The business automatically gains a monopoly position","C":"Its products immediately become lower in price than all rivals","D":"Communication and decision-making become slower as the organisation grows"},"correctOption":"D","correctAnswer":"Communication and decision-making become slower as the organisation grows","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","distractor_reasons":{"A":"Shareholders keep their dividend rights regardless of how quickly the business expands.","B":"Rapid growth does not automatically create a monopoly, which would require dominance of the whole market.","C":"Growth gives no guarantee of lower prices than competitors, which depend on costs and pricing decisions.","D":"Option D is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions."}}},{"id":"P1_U1_MCQ_376","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_376","question":"What is the most likely immediate cause of failure for a newly established business such as Appleton Electrics?","options":{"A":"Sustained cash-flow shortages leaving it unable to pay bills when due","B":"Having too few customers relative to its production capacity","C":"Unable to obtain any market research data","D":"Paying dividends to shareholders"},"correctOption":"A","correctAnswer":"Sustained cash-flow shortages leaving it unable to pay bills when due","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","distractor_reasons":{"A":"Option A is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","B":"Too few customers is a symptom of weak demand, but the immediate trigger of failure is usually the resulting cash shortage.","C":"A lack of market research raises risk but does not by itself prevent a business from trading.","D":"Paying dividends is a choice made from profits and is not a typical cause of a new business failing."}}},{"id":"P1_U1_MCQ_377","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_377","question":"In Leeds, which measure is most likely to be used by a government to support people starting new businesses?","options":{"A":"Grants or low-interest loans specifically for start-ups","B":"Higher taxes on all new firms","C":"A ban on selling to overseas customers","D":"Requiring every start-up to become a public limited company"},"correctOption":"A","correctAnswer":"Grants or low-interest loans specifically for start-ups","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","distractor_reasons":{"A":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","B":"Higher taxes would discourage rather than help new businesses by reducing their available funds.","C":"Banning overseas sales would restrict market access and hinder the growth of new firms.","D":"Start-ups are not required to become public limited companies; many begin as sole traders or private limited companies."}}},{"id":"P1_U1_MCQ_378","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_378","question":"Stonebridge Logistics and an overseas company create a jointly owned business in Yorkshire to share costs and expertise. What is this arrangement called?","options":{"A":"A sole trader business","B":"Internal growth","C":"A joint venture","D":"A franchise"},"correctOption":"C","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","distractor_reasons":{"A":"A sole trader business has a single owner, which is the opposite of a jointly owned venture.","B":"Internal growth is expansion from within; here two separate firms combine resources externally.","C":"Option C is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","D":"A franchise involves one party paying to use another's brand and system, not creating a jointly owned company."}}},{"id":"P1_U1_MCQ_379","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_379","question":"Rather than buying another firm, Kingsway Motors develops and launches fresh orange juice using its own research team and spare cash. What type of growth is this?","options":{"A":"Backward vertical integration","B":"External takeover","C":"Internal (organic) growth","D":"Horizontal integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","distractor_reasons":{"A":"Backward vertical integration requires acquiring a supplier, which has not happened here.","B":"An external takeover means buying another business; this firm grew without acquiring one.","C":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","D":"Horizontal integration involves combining with another firm at the same stage of an industry."}}},{"id":"P1_U1_MCQ_380","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_380","question":"Highland Woollens opens three new branches in Devon using profits retained from the previous year. What type of growth is this?","options":{"A":"Internal (organic) growth","B":"Horizontal integration","C":"Backward vertical integration","D":"A takeover"},"correctOption":"A","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","distractor_reasons":{"A":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","B":"Horizontal integration means joining with another firm at the same stage of production, usually through a merger or takeover.","C":"Backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"A takeover is external growth involving the purchase of another company rather than expansion using internal funds."}}},{"id":"P1_U1_MCQ_381","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_381","question":"Which source of finance involves selling ownership stakes in a private limited company such as Quayside Seafood?","options":{"A":"Bank overdraft","B":"Issuing shares","C":"Trade credit","D":"Leasing equipment"},"correctOption":"B","correctAnswer":"Issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","distractor_reasons":{"A":"A bank overdraft is borrowed money that must be repaid and does not transfer ownership of the business.","B":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","C":"Trade credit delays payment to suppliers and is a short-term source of finance, not a sale of ownership.","D":"Leasing is renting an asset instead of buying it and does not give investors any share in the company."}}},{"id":"P1_U1_MCQ_382","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_382","question":"What is a benefit to Priya of becoming a franchisee of Cobalt Chemicals rather than starting an independent business?","options":{"A":"Using an established brand and proven business model lowers the risk of failure","B":"The franchisee keeps every pound of profit with no fees to pay","C":"The franchisee has complete freedom to change the product range","D":"The franchisee has no need to follow any trading standards"},"correctOption":"A","correctAnswer":"Using an established brand and proven business model lowers the risk of failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","distractor_reasons":{"A":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","B":"Franchisees normally pay an initial fee and ongoing royalties, so they do not keep all the profit.","C":"Franchise agreements usually require the franchisee to follow the franchisor's products and methods, limiting freedom.","D":"Franchisees must still meet legal and quality standards set by the franchisor and by law."}}},{"id":"P1_U1_MCQ_383","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_383","question":"Two competing firms in Leeds decide to form a jointly owned new company to develop a shared distribution network. What is this?","options":{"A":"A merger into a single existing firm","B":"A joint venture","C":"A sole trader","D":"An internal expansion"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","distractor_reasons":{"A":"A merger combines existing businesses into one, rather than setting up a separate jointly owned company.","B":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","C":"A sole trader has one owner, whereas here two firms jointly own the new company.","D":"Internal expansion uses a firm's own resources rather than a partnership with another business."}}},{"id":"P1_U1_MCQ_384","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_384","question":"A business such as Holloway Bakers has owners with limited liability and shares that cannot be traded on a stock exchange. Which type of organisation is it?","options":{"A":"Sole trader","B":"Private limited company such as Holloway Bakers","C":"Public limited company","D":"Partnership"},"correctOption":"B","correctAnswer":"Private limited company such as Holloway Bakers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","distractor_reasons":{"A":"A sole trader has unlimited liability, so it does not meet the limited-liability condition in the question.","B":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","C":"A public limited company has shares that can be traded on a stock exchange, which this question rules out.","D":"A traditional partnership gives owners unlimited liability rather than limited liability."}}},{"id":"P1_U1_MCQ_385","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_385","question":"Liam runs a business selling handmade wooden chairs as a sole trader. What is the position regarding liability for the business debts?","options":{"A":"Liam has unlimited liability and is personally responsible for all the debts","B":"Liam has limited liability and risks only the money invested","C":"Liability is shared equally with the government","D":"There is no liability because the business is not registered"},"correctOption":"A","correctAnswer":"Liam has unlimited liability and is personally responsible for all the debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","distractor_reasons":{"A":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","B":"Limited liability applies to shareholders in limited companies, not to a sole trader who personally owns the business.","C":"The government does not share a sole trader's debts; the owner alone is responsible for them.","D":"Registering the business does not remove liability; a sole trader remains personally liable whether registered or not."}}},{"id":"P1_U1_MCQ_386","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_386","question":"Noah starts a business in Bristol with two friends, sharing ownership and management. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Public corporation"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","distractor_reasons":{"A":"A sole trader has a single owner, whereas this business has several owners sharing management.","B":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","C":"A public limited company sells shares on a stock exchange and has limited liability, unlike a simple partnership.","D":"A public corporation is government-owned and provides a public service, which is not the case here."}}},{"id":"P1_U1_MCQ_387","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_387","question":"Cobalt Chemicals is a private limited company. What does limited liability mean for its shareholders?","options":{"A":"They are responsible for all company debts with their personal property","B":"They can only lose the amount they invested in shares and no more","C":"They are forbidden from selling their shares to anyone else","D":"They receive a guaranteed annual salary from the company"},"correctOption":"B","correctAnswer":"They can only lose the amount they invested in shares and no more","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","distractor_reasons":{"A":"Personal property is only at risk for owners with unlimited liability such as sole traders and ordinary partners.","B":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","C":"Shareholders in a private limited company may sell shares, subject to any restrictions in the company's rules.","D":"Shareholders are not employees and have no automatic right to a salary; they may receive dividends if profits allow."}}},{"id":"P1_U1_MCQ_388","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_388","question":"Which feature distinguishes a public limited company such as Foxglove Ceramics from a private limited company?","options":{"A":"Its shares can be bought and sold on a stock exchange","B":"Its owners have unlimited liability for all debts","C":"It must be owned by exactly one person","D":"It cannot employ any staff"},"correctOption":"A","correctAnswer":"Its shares can be bought and sold on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","distractor_reasons":{"A":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","B":"Both private and public limited companies give shareholders limited liability, so this is not a distinguishing feature.","C":"A public limited company needs at least two shareholders and cannot be owned by a single person in the way described.","D":"Public limited companies employ staff just like other business organisations, so this is not a distinguishing feature."}}},{"id":"P1_U1_MCQ_389","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_389","question":"Grace pays a fee to use the well-known brand and business model of Holloway Bakers. What is this arrangement called?","options":{"A":"A joint venture","B":"A franchise","C":"A partnership","D":"A public corporation"},"correctOption":"B","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","distractor_reasons":{"A":"A joint venture involves joint ownership of a new business, not paying for the right to use an existing brand.","B":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","C":"A partnership shares ownership and management between partners rather than licensing a brand for a fee.","D":"A public corporation is government-owned and is unrelated to this private fee-paying arrangement."}}},{"id":"P1_U1_MCQ_390","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_390","question":"An organisation is wholly owned by the government and provides an essential public service in Birmingham. What is it called?","options":{"A":"A private limited company","B":"A sole trader","C":"A public corporation","D":"A franchise"},"correctOption":"C","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","distractor_reasons":{"A":"A private limited company is owned by private shareholders and is not wholly owned by the government.","B":"A sole trader is a privately owned one-person business, not a government-owned organisation.","C":"Option C is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","D":"A franchise is a private commercial arrangement to use a brand, not a government-owned public service body."}}},{"id":"P1_U1_MCQ_391","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_391","question":"A local council in Kent is concerned that Fernhill Pharmaceuticals may close a factory and cause job losses. In what capacity is the council a stakeholder?","options":{"A":"As a competitor in the same market","B":"As part of the local community and government","C":"As a supplier of raw materials","D":"As a shareholder seeking dividends"},"correctOption":"B","correctAnswer":"As part of the local community and government","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","distractor_reasons":{"A":"A local council is not usually a rival business competing to sell the same products in the market.","B":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","C":"The council is not providing raw materials to the firm in this situation, so it is not acting as a supplier.","D":"The council has not bought shares here, so it is not acting as a shareholder seeking dividends."}}},{"id":"P1_U1_MCQ_392","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_392","question":"Greenfield Organics aims to increase the scale of its operations by opening new markets and increasing output over five years. Which objective is this?","options":{"A":"Short-term profit maximisation","B":"Survival","C":"Social responsibility","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","distractor_reasons":{"A":"Short-term profit maximisation focuses on immediate profit rather than a planned five-year expansion.","B":"Survival is a short-term defensive aim of covering costs, not of expanding into new markets.","C":"Social responsibility concerns the effect on society and is not the objective described by expansion and higher output.","D":"Option D is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business."}}},{"id":"P1_U1_MCQ_393","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_393","question":"Willowvale Cosmetics sets its output and price to earn the largest possible total profit. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Sales revenue maximisation","C":"Market share leadership","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","distractor_reasons":{"A":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","B":"Sales revenue maximisation focuses on total sales value rather than on the difference between revenue and cost.","C":"Market share leadership aims at a large share of industry sales and may accept lower profits to achieve it.","D":"Survival means covering costs to stay in business, which is a more short-term and defensive aim."}}},{"id":"P1_U1_MCQ_394","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_394","question":"Facing falling demand in Kent, Sunrise Poultry concentrates on covering its costs and staying in business. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","distractor_reasons":{"A":"Growth means increasing sales, output or the size of the business, which is not the priority when simply staying afloat.","B":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","C":"Profit maximisation seeks the highest profit, whereas here the firm only aims to cover its costs.","D":"Social responsibility concerns the impact on society and is not the aim described in this difficult trading situation."}}},{"id":"P1_U1_MCQ_395","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_395","question":"Coastline Cartons wants to raise its percentage of total industry sales in the coming year. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Increasing market share","D":"Cost minimisation alone"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","distractor_reasons":{"A":"Profit maximisation targets the largest profit, which may not coincide with selling a larger share of the market.","B":"Survival is about covering costs and continuing to trade rather than winning a greater share of sales.","C":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","D":"Cost minimisation concerns reducing expenses and does not directly describe gaining a larger share of industry sales."}}},{"id":"P1_U1_MCQ_396","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_396","question":"Marlow Boats aims to sell as many units as possible, even if profit per unit is low. Which objective is this?","options":{"A":"Sales revenue maximisation","B":"Survival","C":"Social enterprise","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Sales revenue maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","distractor_reasons":{"A":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","B":"Survival only requires covering costs, whereas this firm deliberately pursues a high volume of sales.","C":"A social enterprise reinvests profits for a social purpose, which is different from maximising sales revenue.","D":"Profit maximisation would not knowingly accept low profit per unit in order to boost sales volume."}}},{"id":"P1_U1_MCQ_397","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_397","question":"A business in Norfolk, founded by Amara, reinvests its surplus to tackle a social or environmental problem. What is this business called?","options":{"A":"A social enterprise","B":"A public corporation","C":"A sole trader focused only on profit","D":"A franchise"},"correctOption":"A","correctAnswer":"A social enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","distractor_reasons":{"A":"Option A is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","B":"A public corporation is government-owned and provides public services, which is different from a mission-led trading business.","C":"A profit-only sole trader does not reinvest surpluses specifically to address a social or environmental problem.","D":"A franchise uses another firm's brand and system and is not defined by a social reinvestment purpose."}}},{"id":"P1_U1_MCQ_398","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_398","question":"In a business such as Stonebridge Logistics, which situation shows a clear conflict of interest between two stakeholder groups?","options":{"A":"Shareholders want higher dividends while employees want higher wages","B":"Customers want lower prices and better quality","C":"The government collects taxes from profitable firms","D":"Suppliers deliver raw materials on the agreed date"},"correctOption":"A","correctAnswer":"Shareholders want higher dividends while employees want higher wages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","distractor_reasons":{"A":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","B":"Customers wanting lower prices and better quality is a single group's preference, not a conflict between two stakeholder groups.","C":"Tax collection is a standard obligation and does not by itself describe opposing demands from two stakeholder groups.","D":"On-time delivery by suppliers is normal performance and involves no clash of competing interests."}}},{"id":"P1_U1_MCQ_399","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_399","question":"A firm that supplies raw materials to Highland Woollens is which of its stakeholders?","options":{"A":"A customer","B":"A supplier","C":"A shareholder","D":"A competitor"},"correctOption":"B","correctAnswer":"A supplier","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","distractor_reasons":{"A":"A customer buys the finished goods from the business rather than providing raw materials to it.","B":"Option B is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","C":"A shareholder owns part of the business, which is a different relationship from selling it inputs.","D":"A competitor sells rival products in the same market rather than supplying this business."}}},{"id":"P1_U1_MCQ_400","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_400","question":"Which is a typical objective of a public-sector organisation such as a state-funded hospital in Oxfordshire?","options":{"A":"To maximise dividends for private shareholders","B":"To provide a service for the community rather than to maximise profit","C":"To avoid serving customers who cannot pay","D":"To keep prices as high as the market will bear"},"correctOption":"B","correctAnswer":"To provide a service for the community rather than to maximise profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","distractor_reasons":{"A":"Public-sector organisations do not have private shareholders seeking dividends, so this cannot be their objective.","B":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","C":"Public services generally aim to be accessible to the whole community, including those who cannot afford to pay.","D":"Charging the highest possible prices is a private profit-seeking objective, not the aim of a public service provider."}}},{"id":"P1_U1_MCQ_401","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_401","question":"A furniture maker buys timber and screws for $30 per table and sells finished dining tables for $100. Which action will directly increase the added value per table by $15?","options":{"A":"Applying custom wood engraving and raising the retail price to $115","B":"Increasing total weekly table output from 50 to 80 tables","C":"Reducing carpenter wage rates by $15 per shift","D":"Purchasing $15 worth of spare timber to hold in reserve"},"correctOption":"A","correctAnswer":"Applying custom wood engraving and raising the retail price to $115","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus bought-in material costs ($100 - $30 = $70). Raising the price to $115 without changing material costs increases added value to $85 ($15 increase).","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus bought-in material costs ($100 - $30 = $70). Raising the price to $115 without changing material costs increases added value to $85 ($15 increase).","B":"Incorrect because increasing output volume changes overall business profit potential, not unit added value.","C":"Incorrect because labor wages are overhead operating costs, not bought-in material costs subtracted in added value calculation.","D":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value."}}},{"id":"P1_U1_MCQ_402","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_402","question":"A commercial orchard owner can use land to harvest either 400 cases of apples or 250 cases of pears. If the owner chooses to harvest 250 cases of pears, what is the opportunity cost?","options":{"A":"The financial cost of purchasing pest control chemicals for the pears","B":"The sales revenue generated from selling the 250 cases of pears","C":"The 400 cases of apples that could have been harvested instead","D":"The diesel expense of running irrigation pumps"},"correctOption":"C","correctAnswer":"The 400 cases of apples that could have been harvested instead","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because opportunity cost is the next best alternative foregone when making an economic choice, which is the 400 cases of apples.","distractor_reasons":{"A":"Incorrect because chemical cost is a direct monetary expenditure.","B":"Incorrect because revenue is the financial return from the chosen decision.","C":"Option C is correct because opportunity cost is the next best alternative foregone when making an economic choice, which is the 400 cases of apples.","D":"Incorrect because fuel is an operational utility expense."}}},{"id":"P1_U1_MCQ_403","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_403","question":"A garment factory uses raw silk, sewing machine operators, industrial cutting machines, and a creative design director. Which factor of production do the industrial cutting machines represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical tools, equipment, and machinery used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like raw silk.","B":"Incorrect because labour refers to human physical and mental work effort.","C":"Option C is correct because capital consists of man-made physical tools, equipment, and machinery used in production.","D":"Incorrect because enterprise is the risk-taking and organizational function."}}},{"id":"P1_U1_MCQ_404","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_404","question":"A bicycle manufacturer introduces division of labor by assigning a worker solely to attach pedals. What is a key limitation of this specialization strategy?","options":{"A":"Workers require longer training periods to master their single task","B":"The purchase price of pedals from component suppliers increases","C":"Hourly output of assembled bicycles per line decreases","D":"Task repetition causes worker boredom, low morale, and potential quality flaws"},"correctOption":"D","correctAnswer":"Task repetition causes worker boredom, low morale, and potential quality flaws","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single narrow task continuously leads to monotony, lowering worker motivation and increasing quality errors.","distractor_reasons":{"A":"Incorrect because learning a single task is fast and simple.","B":"Incorrect because division of labor is an internal operational process and does not affect supplier pricing.","C":"Incorrect because specialization generally speeds up assembly and increases hourly output.","D":"Option D is correct because repeating a single narrow task continuously leads to monotony, lowering worker motivation and increasing quality errors."}}},{"id":"P1_U1_MCQ_405","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_405","question":"Foxglove Ceramics installs new automated machines to help manufacture soy wax candles in its factory. Which factor of production do these machines represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital as a factor of production means manufactured resources such as machinery and equipment used to produce goods.","distractor_reasons":{"A":"Land refers to natural resources such as raw materials and sites, not to man-made machines installed in a factory.","B":"Labour is the human effort and skills used in production, whereas the machines themselves are physical equipment.","C":"Option C is correct because capital as a factor of production means manufactured resources such as machinery and equipment used to produce goods.","D":"Enterprise is the risk-taking and organising ability of the entrepreneur, not the physical capital goods that were bought."}}},{"id":"P1_U1_MCQ_406","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_406","question":"Why does the economic problem of scarcity affect all societies, regardless of economic development?","options":{"A":"Governments place price controls on basic goods","B":"Finite resources are insufficient to satisfy infinite human needs and wants","C":"Private firms intentionally limit factory output to boost profits","D":"An excess supply of labor lowers economic efficiency"},"correctOption":"B","correctAnswer":"Finite resources are insufficient to satisfy infinite human needs and wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity occurs because limited factors of production cannot fulfill infinite human wants.","distractor_reasons":{"A":"Incorrect because price controls are regulatory policy measures, not the root cause of scarcity.","B":"Option B is correct because scarcity occurs because limited factors of production cannot fulfill infinite human wants.","C":"Incorrect because corporate profit tactics do not cause fundamental economic resource scarcity.","D":"Incorrect because excess labor supply reduces scarcity of that factor."}}},{"id":"P1_U1_MCQ_407","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_407","question":"A metal fabricator buys raw steel for $14 and bolts for $2 per frame. The finished frame sells for $50. What is the added value per frame?","options":{"A":"$16","B":"$36","C":"$34","D":"$50"},"correctOption":"C","correctAnswer":"$34","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs equal $14 + $2 = $16. Added value = selling price ($50) minus material costs ($16) = $34.","distractor_reasons":{"A":"Incorrect because $16 is the total material cost.","B":"Incorrect because $36 subtracts only raw steel cost ($50 - $14), ignoring bolts.","C":"Option C is correct because total bought-in material costs equal $14 + $2 = $16. Added value = selling price ($50) minus material costs ($16) = $34.","D":"Incorrect because $50 is the final retail price."}}},{"id":"P1_U1_MCQ_408","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_408","question":"An engineer leaves a job paying $65,000 per year to open an independent engineering consultancy. What is the opportunity cost of starting this consultancy?","options":{"A":"The office lease expense for the consultancy space","B":"The total client fees collected in Year 1","C":"The capital spent on engineering software licenses","D":"The $65,000 corporate engineering salary sacrificed"},"correctOption":"D","correctAnswer":"The $65,000 corporate engineering salary sacrificed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $65,000 salary.","distractor_reasons":{"A":"Incorrect because office lease is an explicit operational monetary expenditure.","B":"Incorrect because client fees are the gain from the chosen option.","C":"Incorrect because software licenses are direct capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $65,000 salary."}}},{"id":"P1_U1_MCQ_409","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_409","question":"Which factor of production encompasses natural resources such as copper deposits, crude oil, and timber forests?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all natural resources provided by nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land covers all natural resources provided by nature used in economic production.","B":"Incorrect because labour refers to human physical and mental effort.","C":"Incorrect because capital refers to man-made assets such as equipment and infrastructure.","D":"Incorrect because enterprise is the risk-taking organizational function."}}},{"id":"P1_U1_MCQ_410","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_410","question":"How can a custom cabinet maker directly increase the added value of its products without increasing retail selling prices?","options":{"A":"Increasing monthly spending on local radio advertising","B":"Securing lower purchase prices for raw timber from suppliers","C":"Increasing hourly wage rates for cabinet craftsmen","D":"Leasing a larger warehouse for storing raw materials"},"correctOption":"B","correctAnswer":"Securing lower purchase prices for raw timber from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw material costs widens the added value gap.","distractor_reasons":{"A":"Incorrect because radio advertising is an operational overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering raw material costs widens the added value gap.","C":"Incorrect because higher wages raise operating expenses, lowering profit rather than unit added value.","D":"Incorrect because leasing a warehouse increases fixed overheads."}}},{"id":"P1_U1_MCQ_411","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_411","question":"A furniture business cuts timber from its own woodland, makes handmade wooden chairs in a factory and sells them through its own shops. Which sectors does it operate in?","options":{"A":"Primary and secondary only","B":"Secondary and tertiary only","C":"Primary, secondary and tertiary","D":"Primary and tertiary only"},"correctOption":"C","correctAnswer":"Primary, secondary and tertiary","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","distractor_reasons":{"A":"This answer leaves out the retail shops, which are a tertiary activity, so it does not cover all the stages described.","B":"This answer omits the woodland timber extraction, which is a primary-sector activity carried out by the business.","C":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","D":"This answer misses the factory manufacturing stage, which is clearly a secondary-sector activity."}}},{"id":"P1_U1_MCQ_412","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_412","question":"A low-income country builds many new factories and moves workers from farming into manufacturing in Devon. What is this process called?","options":{"A":"Industrialisation","B":"De-industrialisation","C":"Tertiarisation","D":"Privatisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because industrialisation is the process of developing manufacturing industry and shifting employment from agriculture into factories.","distractor_reasons":{"A":"Option A is correct because industrialisation is the process of developing manufacturing industry and shifting employment from agriculture into factories.","B":"De-industrialisation is the reverse process, in which manufacturing declines and factory jobs are lost.","C":"Tertiarisation would mean growth of service employment rather than a move into factory-based manufacturing.","D":"Privatisation is the transfer of state-owned assets to private owners and does not describe the growth of manufacturing."}}},{"id":"P1_U1_MCQ_413","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_413","question":"A private firm such as Ashgrove Travel trades alongside government-run services in Glasgow. Which statement best distinguishes the private sector from the public sector?","options":{"A":"Private-sector firms are owned by individuals or shareholders, while public-sector bodies are owned by the government","B":"Private-sector firms only provide services, while public-sector bodies only make goods","C":"Private-sector firms are always small, while public-sector bodies are always large","D":"Private-sector firms never employ workers, while public-sector bodies always do"},"correctOption":"A","correctAnswer":"Private-sector firms are owned by individuals or shareholders, while public-sector bodies are owned by the government","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ownership is the key difference: private firms belong to private investors, public bodies to the government.","distractor_reasons":{"A":"Option A is correct because ownership is the key difference: private firms belong to private investors, public bodies to the government.","B":"Both sectors can produce goods or provide services, so the type of output does not distinguish them.","C":"Business size is not the defining feature; private firms can be very large and public bodies can be small.","D":"Both private and public organisations employ workers, so employment is not a distinguishing characteristic."}}},{"id":"P1_U1_MCQ_414","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_414","question":"A mining company extracts bauxite, a refinery converts bauxite into aluminum ingots, and an aircraft plant uses the ingots to construct airplane bodies. How are these three activities classified?","options":{"A":"Mining: Secondary; Refining: Primary; Aircraft construction: Tertiary","B":"Mining: Tertiary; Refining: Secondary; Aircraft construction: Primary","C":"Mining: Primary; Refining: Tertiary; Aircraft construction: Secondary","D":"Mining: Primary; Refining: Secondary; Aircraft construction: Secondary"},"correctOption":"D","correctAnswer":"Mining: Primary; Refining: Secondary; Aircraft construction: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mining bauxite is primary (extraction), while both refining and aircraft construction transform materials into finished products/structures (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Incorrect because the sector order is completely inaccurate.","C":"Incorrect because refining is manufacturing/processing (secondary), not service (tertiary).","D":"Option D is correct because mining bauxite is primary (extraction), while both refining and aircraft construction transform materials into finished products/structures (secondary sector)."}}},{"id":"P1_U1_MCQ_415","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_415","question":"A worker is quarrying limestone in the Scottish Highlands. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"A","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature.","distractor_reasons":{"A":"Option A is correct because the primary sector extracts natural resources such as crops, minerals, fish and timber directly from nature.","B":"The secondary sector manufactures or processes materials into finished goods, which is not what extracting a natural resource involves.","C":"The tertiary sector provides services to consumers and businesses rather than extracting raw materials from the natural environment.","D":"Public sector refers to government ownership, a different classification from the primary, secondary and tertiary sectors."}}},{"id":"P1_U1_MCQ_416","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_416","question":"A worker is assembling cars in a factory in Devon. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","distractor_reasons":{"A":"The primary sector extracts natural resources in their raw state; assembling or processing materials is a manufacturing activity instead.","B":"Option B is correct because the secondary sector processes raw materials and components into finished or semi-finished goods in factories and workshops.","C":"The tertiary sector is concerned with providing services, not with the physical conversion of materials into products.","D":"Public sector describes who owns an organisation, not the type of productive activity being carried out."}}},{"id":"P1_U1_MCQ_417","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_417","question":"A worker is driving a delivery lorry in Essex. Which economic sector does this activity belong to?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","distractor_reasons":{"A":"The primary sector involves extracting raw materials from nature, which is different from providing a service to a customer.","B":"The secondary sector makes physical products by processing materials, whereas this activity involves delivering a service.","C":"Option C is correct because the tertiary sector provides services to customers and other businesses rather than extracting or manufacturing goods.","D":"Public sector refers to government ownership and is not one of the three productive sectors being described here."}}},{"id":"P1_U1_MCQ_418","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_418","question":"Why might a national government privatize a state-run airport authority?","options":{"A":"To grant civil service employment status to all airport staff","B":"To introduce market competition, profit incentives, and operational efficiency","C":"To eliminate private capital investment in national aviation infrastructure","D":"To increase direct state control over daily flight departure schedules"},"correctOption":"B","correctAnswer":"To introduce market competition, profit incentives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, bringing market incentives that improve operational efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Option B is correct because privatization transfers state assets to private owners, bringing market incentives that improve operational efficiency.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct state control."}}},{"id":"P1_U1_MCQ_419","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_419","question":"Over twenty years Cornwall has seen its large factories close and employment shift towards shops, offices and services. What is this change called?","options":{"A":"Industrialisation","B":"De-industrialisation","C":"Primary-sector expansion","D":"Nationalisation"},"correctOption":"B","correctAnswer":"De-industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","distractor_reasons":{"A":"Industrialisation is the opposite process, building up manufacturing industry rather than losing it.","B":"Option B is correct because de-industrialisation is the long-term decline of manufacturing industry and factory employment in a region or country.","C":"Primary-sector expansion would mean more farming, mining or fishing, not the closure of factories and growth of services.","D":"Nationalisation means transferring private assets into government ownership and is unrelated to the decline of manufacturing jobs."}}},{"id":"P1_U1_MCQ_420","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_420","question":"A state-run hospital in Norfolk is owned and funded by the government to provide a service for the community. Which sector does it belong to?","options":{"A":"Private sector","B":"Public sector","C":"Primary sector","D":"Voluntary sector"},"correctOption":"B","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","distractor_reasons":{"A":"The private sector consists of businesses owned by private individuals or shareholders, not organisations funded and run by the government.","B":"Option B is correct because the public sector consists of organisations owned and controlled by the government to provide services rather than to make private profit.","C":"The primary sector extracts natural resources and is unrelated to whether an organisation is government-owned.","D":"The voluntary sector is made up of charities and non-profit groups, which are separate from government-provided public services."}}},{"id":"P1_U1_MCQ_421","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_421","question":"Granite Ridge Mining, a chain of coffee shops, takes over a rival chain of coffee shops in Leeds. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","distractor_reasons":{"A":"Forward vertical integration means moving closer to the final customer, such as a producer buying retail outlets.","B":"Backward vertical integration means moving towards suppliers, such as a retailer buying a manufacturing plant.","C":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","D":"Internal growth uses a firm's own resources; taking over a rival is external growth through acquisition."}}},{"id":"P1_U1_MCQ_422","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_422","question":"A manufacturer of artisan sourdough loaves buys a chain of retail stores that sell its goods to the public. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Organic growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","distractor_reasons":{"A":"Backward vertical integration would involve acquiring a supplier further from the consumer, not a retailer near the end customer.","B":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","C":"Horizontal integration involves a firm at the same production stage, whereas a retailer is at a later stage of the chain.","D":"Organic growth is internal expansion, while purchasing an established retail chain is an external acquisition."}}},{"id":"P1_U1_MCQ_423","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_423","question":"A company making organic skincare creams purchases the business that supplies its raw ingredients. What type of growth has taken place?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","distractor_reasons":{"A":"Forward vertical integration means moving towards the customer, such as buying distributors, not acquiring a supplier.","B":"Horizontal integration joins firms at the same stage of activity, whereas a raw-material supplier is at an earlier stage.","C":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"Internal growth is funded and achieved within the business, while buying a supplier is an external acquisition."}}},{"id":"P1_U1_MCQ_424","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_424","question":"Grace is setting up a business in Glasgow. Which action best describes the role of an entrepreneur?","options":{"A":"Taking financial risk and organising resources to create and run a business","B":"Receiving a fixed salary for carrying out routine office work","C":"Guaranteeing that the business will never face competition","D":"Owning the business but avoiding all decision-making"},"correctOption":"A","correctAnswer":"Taking financial risk and organising resources to create and run a business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","distractor_reasons":{"A":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","B":"A fixed salary for routine work describes an employee, not an entrepreneur who bears risk and organises the business.","C":"No entrepreneur can guarantee the absence of competition, which is outside their control in a market.","D":"Entrepreneurs are actively involved in decisions; avoiding all decision-making is not an entrepreneurial role."}}},{"id":"P1_U1_MCQ_425","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_425","question":"Aisha is preparing a business plan before launching a new venture. What is the main purpose of a business plan?","options":{"A":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","B":"To guarantee that the business will make a profit in its first year","C":"To remove the need for any market research before launching","D":"To avoid having to keep any accounting records"},"correctOption":"A","correctAnswer":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","distractor_reasons":{"A":"Option A is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","B":"A plan cannot guarantee profit, which depends on future trading conditions and many factors outside the plan.","C":"A business plan supports rather than replaces market research, which remains necessary to understand customers.","D":"A business plan does not remove the legal and practical need to keep proper financial records."}}},{"id":"P1_U1_MCQ_426","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_426","question":"An analyst wants to compare the size of Silverstream Bottling with other firms in the same industry. Which of these is a measure of business size?","options":{"A":"Gross profit margin","B":"Number of employees","C":"Current ratio","D":"Return on capital employed"},"correctOption":"B","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","distractor_reasons":{"A":"Gross profit margin measures profitability relative to revenue, not the physical scale or size of the business.","B":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","C":"The current ratio measures short-term liquidity and says nothing about how large the business is.","D":"Return on capital employed is a profitability ratio rather than a measure of the size of the business."}}},{"id":"P1_U1_MCQ_427","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_427","question":"Delta Footwear has grown very rapidly over two years. Which is most likely to be a problem caused by such rapid growth?","options":{"A":"Communication and decision-making become slower as the organisation grows","B":"The business automatically gains a monopoly position","C":"Its products immediately become lower in price than all rivals","D":"Its shareholders are no longer entitled to any dividend"},"correctOption":"A","correctAnswer":"Communication and decision-making become slower as the organisation grows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","distractor_reasons":{"A":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","B":"Rapid growth does not automatically create a monopoly, which would require dominance of the whole market.","C":"Growth gives no guarantee of lower prices than competitors, which depend on costs and pricing decisions.","D":"Shareholders keep their dividend rights regardless of how quickly the business expands."}}},{"id":"P1_U1_MCQ_428","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_428","question":"What is the most likely immediate cause of failure for a newly established business such as Bluepeak Software?","options":{"A":"Paying dividends to shareholders","B":"Having too few customers relative to its production capacity","C":"Unable to obtain any market research data","D":"Sustained cash-flow shortages leaving it unable to pay bills when due"},"correctOption":"D","correctAnswer":"Sustained cash-flow shortages leaving it unable to pay bills when due","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations.","distractor_reasons":{"A":"Paying dividends is a choice made from profits and is not a typical cause of a new business failing.","B":"Too few customers is a symptom of weak demand, but the immediate trigger of failure is usually the resulting cash shortage.","C":"A lack of market research raises risk but does not by itself prevent a business from trading.","D":"Option D is correct because a business can be profitable on paper yet still fail if it runs out of cash to meet its short-term obligations."}}},{"id":"P1_U1_MCQ_429","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_429","question":"In Derbyshire, which measure is most likely to be used by a government to support people starting new businesses?","options":{"A":"Grants or low-interest loans specifically for start-ups","B":"Higher taxes on all new firms","C":"A ban on selling to overseas customers","D":"Requiring every start-up to become a public limited company"},"correctOption":"A","correctAnswer":"Grants or low-interest loans specifically for start-ups","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","distractor_reasons":{"A":"Option A is correct because grants and subsidised loans lower the financial barrier to entry and are a common form of start-up support.","B":"Higher taxes would discourage rather than help new businesses by reducing their available funds.","C":"Banning overseas sales would restrict market access and hinder the growth of new firms.","D":"Start-ups are not required to become public limited companies; many begin as sole traders or private limited companies."}}},{"id":"P1_U1_MCQ_430","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_430","question":"Evergreen Gardens and an overseas company create a jointly owned business in the Scottish Highlands to share costs and expertise. What is this arrangement called?","options":{"A":"A sole trader business","B":"A joint venture","C":"Internal growth","D":"A franchise"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","distractor_reasons":{"A":"A sole trader business has a single owner, which is the opposite of a jointly owned venture.","B":"Option B is correct because a joint venture is a business set up and owned jointly by two or more independent organisations.","C":"Internal growth is expansion from within; here two separate firms combine resources externally.","D":"A franchise involves one party paying to use another's brand and system, not creating a jointly owned company."}}},{"id":"P1_U1_MCQ_431","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_431","question":"What is a dividend in the context of a company such as Golden Fleece Textiles?","options":{"A":"A share of company profits paid out to shareholders","B":"The total value of the company's fixed assets","C":"A tax that the company pays to the government only","D":"The wage paid to the highest-paid employee"},"correctOption":"A","correctAnswer":"A share of company profits paid out to shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","distractor_reasons":{"A":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","B":"The value of fixed assets appears in the statement of financial position and is not a payment to shareholders.","C":"Company tax is paid to the government, whereas a dividend is paid to the owners of the business.","D":"Wages are payments to employees for labour, not distributions of profit to shareholders."}}},{"id":"P1_U1_MCQ_432","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_432","question":"Which statement about a sole trader such as Sofia selling organic skincare creams is correct?","options":{"A":"The owner keeps all the profits but has unlimited liability","B":"The owner must share all profits with the government","C":"The owner has limited liability and pays no tax","D":"The owner cannot make any business decisions alone"},"correctOption":"A","correctAnswer":"The owner keeps all the profits but has unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","distractor_reasons":{"A":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","B":"The owner keeps the profits but pays tax on them; profits are not shared with the government as owners' earnings.","C":"A sole trader has unlimited liability, not limited liability, and is still liable to pay income tax on profits.","D":"A sole trader makes the business decisions alone, which is one of the advantages of this form of organisation."}}},{"id":"P1_U1_MCQ_433","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_433","question":"Which source of finance involves selling ownership stakes in a private limited company such as Bramble House Candles?","options":{"A":"Bank overdraft","B":"Issuing shares","C":"Trade credit","D":"Leasing equipment"},"correctOption":"B","correctAnswer":"Issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","distractor_reasons":{"A":"A bank overdraft is borrowed money that must be repaid and does not transfer ownership of the business.","B":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","C":"Trade credit delays payment to suppliers and is a short-term source of finance, not a sale of ownership.","D":"Leasing is renting an asset instead of buying it and does not give investors any share in the company."}}},{"id":"P1_U1_MCQ_434","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_434","question":"What is a benefit to Noah of becoming a franchisee of Meadowbrook Poultry rather than starting an independent business?","options":{"A":"Using an established brand and proven business model lowers the risk of failure","B":"The franchisee keeps every pound of profit with no fees to pay","C":"The franchisee has complete freedom to change the product range","D":"The franchisee has no need to follow any trading standards"},"correctOption":"A","correctAnswer":"Using an established brand and proven business model lowers the risk of failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","distractor_reasons":{"A":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","B":"Franchisees normally pay an initial fee and ongoing royalties, so they do not keep all the profit.","C":"Franchise agreements usually require the franchisee to follow the franchisor's products and methods, limiting freedom.","D":"Franchisees must still meet legal and quality standards set by the franchisor and by law."}}},{"id":"P1_U1_MCQ_435","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_435","question":"Two competing firms in Derbyshire decide to form a jointly owned new company to develop a shared distribution network. What is this?","options":{"A":"A merger into a single existing firm","B":"A joint venture","C":"A sole trader","D":"An internal expansion"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","distractor_reasons":{"A":"A merger combines existing businesses into one, rather than setting up a separate jointly owned company.","B":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","C":"A sole trader has one owner, whereas here two firms jointly own the new company.","D":"Internal expansion uses a firm's own resources rather than a partnership with another business."}}},{"id":"P1_U1_MCQ_436","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_436","question":"A business such as Tamarind Foods has owners with limited liability and shares that cannot be traded on a stock exchange. Which type of organisation is it?","options":{"A":"Sole trader","B":"Public limited company","C":"Private limited company such as Tamarind Foods","D":"Partnership"},"correctOption":"C","correctAnswer":"Private limited company such as Tamarind Foods","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","distractor_reasons":{"A":"A sole trader has unlimited liability, so it does not meet the limited-liability condition in the question.","B":"A public limited company has shares that can be traded on a stock exchange, which this question rules out.","C":"Option C is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","D":"A traditional partnership gives owners unlimited liability rather than limited liability."}}},{"id":"P1_U1_MCQ_437","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_437","question":"Priya runs a business selling fresh orange juice as a sole trader. What is the position regarding liability for the business debts?","options":{"A":"Priya has unlimited liability and is personally responsible for all the debts","B":"Priya has limited liability and risks only the money invested","C":"Liability is shared equally with the government","D":"There is no liability because the business is not registered"},"correctOption":"A","correctAnswer":"Priya has unlimited liability and is personally responsible for all the debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","distractor_reasons":{"A":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","B":"Limited liability applies to shareholders in limited companies, not to a sole trader who personally owns the business.","C":"The government does not share a sole trader's debts; the owner alone is responsible for them.","D":"Registering the business does not remove liability; a sole trader remains personally liable whether registered or not."}}},{"id":"P1_U1_MCQ_438","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_438","question":"Fatima starts a business in Oxfordshire with two friends, sharing ownership and management. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Public corporation"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","distractor_reasons":{"A":"A sole trader has a single owner, whereas this business has several owners sharing management.","B":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","C":"A public limited company sells shares on a stock exchange and has limited liability, unlike a simple partnership.","D":"A public corporation is government-owned and provides a public service, which is not the case here."}}},{"id":"P1_U1_MCQ_439","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_439","question":"Meadowbrook Poultry is a private limited company. What does limited liability mean for its shareholders?","options":{"A":"They are responsible for all company debts with their personal property","B":"They can only lose the amount they invested in shares and no more","C":"They are forbidden from selling their shares to anyone else","D":"They receive a guaranteed annual salary from the company"},"correctOption":"B","correctAnswer":"They can only lose the amount they invested in shares and no more","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","distractor_reasons":{"A":"Personal property is only at risk for owners with unlimited liability such as sole traders and ordinary partners.","B":"Option B is correct because limited liability protects shareholders so they lose only the capital they subscribed, not their private assets.","C":"Shareholders in a private limited company may sell shares, subject to any restrictions in the company's rules.","D":"Shareholders are not employees and have no automatic right to a salary; they may receive dividends if profits allow."}}},{"id":"P1_U1_MCQ_440","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_440","question":"Which feature distinguishes a public limited company such as Westfield Mills from a private limited company?","options":{"A":"Its shares can be bought and sold on a stock exchange","B":"Its owners have unlimited liability for all debts","C":"It must be owned by exactly one person","D":"It cannot employ any staff"},"correctOption":"A","correctAnswer":"Its shares can be bought and sold on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","distractor_reasons":{"A":"Option A is correct because a public limited company may offer its shares to the public and have them traded on a stock exchange.","B":"Both private and public limited companies give shareholders limited liability, so this is not a distinguishing feature.","C":"A public limited company needs at least two shareholders and cannot be owned by a single person in the way described.","D":"Public limited companies employ staff just like other business organisations, so this is not a distinguishing feature."}}},{"id":"P1_U1_MCQ_441","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_441","question":"What is usually the primary objective of a private-sector business such as Sunrise Poultry?","options":{"A":"To make a profit","B":"To provide free public services","C":"To avoid all competition","D":"To be owned by the state"},"correctOption":"A","correctAnswer":"To make a profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","distractor_reasons":{"A":"Option A is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","B":"Providing free public services is typical of the public sector, not of privately owned businesses seeking a return.","C":"Businesses cannot normally avoid competition, which is a feature of the market in which they operate.","D":"Private-sector firms are owned by private individuals or shareholders, not by the state."}}},{"id":"P1_U1_MCQ_442","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_442","question":"Which group is most directly interested in Coastline Cartons paying competitive wages and offering safe working conditions?","options":{"A":"Its employees","B":"Its customers","C":"Its shareholders","D":"Its local suppliers"},"correctOption":"A","correctAnswer":"Its employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","distractor_reasons":{"A":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","B":"Customers are mainly concerned with the price, quality and availability of the products they buy.","C":"Shareholders are primarily interested in returns on their investment and the profitability of the business.","D":"Suppliers are mainly interested in receiving payment and maintaining orders for their materials."}}},{"id":"P1_U1_MCQ_443","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_443","question":"A local council in South Wales is concerned that Marlow Boats may close a factory and cause job losses. In what capacity is the council a stakeholder?","options":{"A":"As a competitor in the same market","B":"As part of the local community and government","C":"As a supplier of raw materials","D":"As a shareholder seeking dividends"},"correctOption":"B","correctAnswer":"As part of the local community and government","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","distractor_reasons":{"A":"A local council is not usually a rival business competing to sell the same products in the market.","B":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","C":"The council is not providing raw materials to the firm in this situation, so it is not acting as a supplier.","D":"The council has not bought shares here, so it is not acting as a shareholder seeking dividends."}}},{"id":"P1_U1_MCQ_444","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_444","question":"Ironbridge Engineering aims to increase the scale of its operations by opening new markets and increasing output over five years. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Social responsibility","D":"Short-term profit maximisation"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","distractor_reasons":{"A":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","B":"Survival is a short-term defensive aim of covering costs, not of expanding into new markets.","C":"Social responsibility concerns the effect on society and is not the objective described by expansion and higher output.","D":"Short-term profit maximisation focuses on immediate profit rather than a planned five-year expansion."}}},{"id":"P1_U1_MCQ_445","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_445","question":"Granite Ridge Mining sets its output and price to earn the largest possible total profit. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Sales revenue maximisation","C":"Market share leadership","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","distractor_reasons":{"A":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","B":"Sales revenue maximisation focuses on total sales value rather than on the difference between revenue and cost.","C":"Market share leadership aims at a large share of industry sales and may accept lower profits to achieve it.","D":"Survival means covering costs to stay in business, which is a more short-term and defensive aim."}}},{"id":"P1_U1_MCQ_446","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_446","question":"Facing falling demand in South Wales, Mapleton Printing concentrates on covering its costs and staying in business. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","distractor_reasons":{"A":"Growth means increasing sales, output or the size of the business, which is not the priority when simply staying afloat.","B":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","C":"Profit maximisation seeks the highest profit, whereas here the firm only aims to cover its costs.","D":"Social responsibility concerns the impact on society and is not the aim described in this difficult trading situation."}}},{"id":"P1_U1_MCQ_447","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_447","question":"Fernhill Pharmaceuticals wants to raise its percentage of total industry sales in the coming year. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Increasing market share","D":"Cost minimisation alone"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","distractor_reasons":{"A":"Profit maximisation targets the largest profit, which may not coincide with selling a larger share of the market.","B":"Survival is about covering costs and continuing to trade rather than winning a greater share of sales.","C":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","D":"Cost minimisation concerns reducing expenses and does not directly describe gaining a larger share of industry sales."}}},{"id":"P1_U1_MCQ_448","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_448","question":"Greenfield Organics aims to sell as many units as possible, even if profit per unit is low. Which objective is this?","options":{"A":"Sales revenue maximisation","B":"Survival","C":"Social enterprise","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Sales revenue maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","distractor_reasons":{"A":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","B":"Survival only requires covering costs, whereas this firm deliberately pursues a high volume of sales.","C":"A social enterprise reinvests profits for a social purpose, which is different from maximising sales revenue.","D":"Profit maximisation would not knowingly accept low profit per unit in order to boost sales volume."}}},{"id":"P1_U1_MCQ_449","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_449","question":"A business in Devon, founded by Raj, reinvests its surplus to tackle a social or environmental problem. What is this business called?","options":{"A":"A sole trader focused only on profit","B":"A public corporation","C":"A social enterprise","D":"A franchise"},"correctOption":"C","correctAnswer":"A social enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","distractor_reasons":{"A":"A profit-only sole trader does not reinvest surpluses specifically to address a social or environmental problem.","B":"A public corporation is government-owned and provides public services, which is different from a mission-led trading business.","C":"Option C is correct because a social enterprise trades to achieve a social or environmental goal and reinvests profits towards that mission.","D":"A franchise uses another firm's brand and system and is not defined by a social reinvestment purpose."}}},{"id":"P1_U1_MCQ_450","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_450","question":"In a business such as Evergreen Gardens, which situation shows a clear conflict of interest between two stakeholder groups?","options":{"A":"Shareholders want higher dividends while employees want higher wages","B":"Customers want lower prices and better quality","C":"The government collects taxes from profitable firms","D":"Suppliers deliver raw materials on the agreed date"},"correctOption":"A","correctAnswer":"Shareholders want higher dividends while employees want higher wages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","distractor_reasons":{"A":"Option A is correct because money paid out as dividends cannot also be paid as wages, so the two groups want the limited funds used differently.","B":"Customers wanting lower prices and better quality is a single group's preference, not a conflict between two stakeholder groups.","C":"Tax collection is a standard obligation and does not by itself describe opposing demands from two stakeholder groups.","D":"On-time delivery by suppliers is normal performance and involves no clash of competing interests."}}},{"id":"P1_U1_MCQ_451","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_451","question":"A shoe manufacturer purchases raw leather for $15 and rubber soles for $5 per pair. The finished shoes sell for $70. Which action directly increases the added value per pair of shoes by $10?","options":{"A":"Adding custom embroidery and increasing the retail price to $80","B":"Increasing daily factory shoe production from 200 to 300 pairs","C":"Reducing shoemaker hourly wage rates by $10 per shift","D":"Purchasing $10 of additional raw leather for warehouse stock"},"correctOption":"A","correctAnswer":"Adding custom embroidery and increasing the retail price to $80","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because added value equals selling price minus bought-in material costs ($70 - $20 = $50). Increasing the retail price to $80 without altering material costs raises added value to $60 ($10 increase).","distractor_reasons":{"A":"Option A is correct because added value equals selling price minus bought-in material costs ($70 - $20 = $50). Increasing the retail price to $80 without altering material costs raises added value to $60 ($10 increase).","B":"Incorrect because increasing daily output alters overall sales volume profit potential, not unit added value.","C":"Incorrect because labor wages are overhead operating expenses, not bought-in material costs.","D":"Incorrect because holding extra raw material stock increases inventory without altering unit added value."}}},{"id":"P1_U1_MCQ_452","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_452","question":"A commercial farm has enough land to cultivate either 600 tonnes of wheat or 400 tonnes of corn. If the farmer decides to plant 400 tonnes of corn, what is the opportunity cost?","options":{"A":"The financial cost of corn seeds and fertilizers","B":"The 600 tonnes of wheat that could have been cultivated instead","C":"The total sales revenue earned from selling the corn harvest","D":"The fuel expense of running harvest combines"},"correctOption":"B","correctAnswer":"The 600 tonnes of wheat that could have been cultivated instead","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic choice, which is the 600 tonnes of wheat.","distractor_reasons":{"A":"Incorrect because seed and fertilizer costs are direct operational expenses.","B":"Option B is correct because opportunity cost is the next best alternative foregone when making an economic choice, which is the 600 tonnes of wheat.","C":"Incorrect because sales revenue is the financial gain from the chosen option.","D":"Incorrect because fuel is a machinery running cost."}}},{"id":"P1_U1_MCQ_453","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_453","question":"A bakery uses flour, bakers, industrial ovens, and an entrepreneurial owner. Which factor of production do the industrial ovens represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical tools, machinery, and equipment used in business production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like flour/wheat.","B":"Incorrect because labour refers to human work effort.","C":"Option C is correct because capital consists of man-made physical tools, machinery, and equipment used in business production.","D":"Incorrect because enterprise is the risk-taking organizational role."}}},{"id":"P1_U1_MCQ_454","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_454","question":"An automobile plant implements division of labor by assigning a worker exclusively to install windshield wipers. What is a primary drawback of this operational approach?","options":{"A":"Workers require extensive multi-year training to master the single task","B":"The component cost of windshield wipers purchased from suppliers increases","C":"Overall assembly line output rate per hour declines","D":"Repetitive task execution can lead to boredom, reduced motivation, and quality defects"},"correctOption":"D","correctAnswer":"Repetitive task execution can lead to boredom, reduced motivation, and quality defects","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single narrow task continuously can cause boredom and fatigue, leading to lower worker morale and careless errors.","distractor_reasons":{"A":"Incorrect because learning a single repetitive task takes minimal time.","B":"Incorrect because internal division of labor does not affect component purchase prices.","C":"Incorrect because specialization typically speeds up work and increases hourly output.","D":"Option D is correct because repeating a single narrow task continuously can cause boredom and fatigue, leading to lower worker morale and careless errors."}}},{"id":"P1_U1_MCQ_455","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_455","question":"A factory making handmade wooden chairs divides the process into separate teams, each repeating one task. What is the main advantage of this division of labour?","options":{"A":"Total output falls because the work becomes less interesting","B":"Every worker learns to perform every stage of production","C":"The factory no longer needs to buy any capital equipment","D":"Workers become faster and more skilled through repetition of their task"},"correctOption":"D","correctAnswer":"Workers become faster and more skilled through repetition of their task","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because specialisation lets workers practise one task repeatedly, increasing speed, skill and overall output.","distractor_reasons":{"A":"Division of labour normally raises total output; reduced job variety is a possible disadvantage, not the main advantage.","B":"Division of labour does the opposite of multi-skilling: workers focus narrowly on one task instead of learning all stages.","C":"Specialisation does not remove the need for machinery; many divided production lines still rely heavily on capital equipment.","D":"Option D is correct because specialisation lets workers practise one task repeatedly, increasing speed, skill and overall output."}}},{"id":"P1_U1_MCQ_456","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_456","question":"Why does the economic problem of scarcity persist in both developed and developing economies?","options":{"A":"Governments mandate maximum prices on essential consumer goods","B":"Unlimited human wants continuously exceed finite economic resources available","C":"Corporations artificially hold back output to lower corporate income tax","D":"High unemployment rates reduce total factory productivity"},"correctOption":"B","correctAnswer":"Unlimited human wants continuously exceed finite economic resources available","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally arises from the conflict between infinite human wants and limited economic resources.","distractor_reasons":{"A":"Incorrect because price mandates are economic policies, not the root cause of scarcity.","B":"Option B is correct because scarcity fundamentally arises from the conflict between infinite human wants and limited economic resources.","C":"Incorrect because corporate tax strategies do not cause fundamental resource scarcity.","D":"Incorrect because unemployment affects labor utilization, not basic resource scarcity."}}},{"id":"P1_U1_MCQ_457","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_457","question":"A smartphone assembler purchases screens for $40 and casings for $10 per unit. The assembled phone sells for $200. What is the added value per phone?","options":{"A":"$50","B":"$160","C":"$150","D":"$200"},"correctOption":"C","correctAnswer":"$150","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bought-in material costs equal $40 + $10 = $50. Added value = selling price ($200) minus material costs ($50) = $150.","distractor_reasons":{"A":"Incorrect because $50 is the total bought-in component cost.","B":"Incorrect because $160 subtracts screen cost only ($200 - $40), ignoring casing cost.","C":"Option C is correct because bought-in material costs equal $40 + $10 = $50. Added value = selling price ($200) minus material costs ($50) = $150.","D":"Incorrect because $200 is the final retail price."}}},{"id":"P1_U1_MCQ_458","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_458","question":"A graphic designer resigns from a job earning $50,000 per year to establish a freelance design agency. What is the opportunity cost of starting this freelance venture?","options":{"A":"The annual lease cost of the office workspace","B":"The total fee billing generated from clients in Year 1","C":"The capital outlay for high-performance design computers","D":"The $50,000 salary given up from the previous job"},"correctOption":"D","correctAnswer":"The $50,000 salary given up from the previous job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the value of the next best alternative foregone, which is the $50,000 salary.","distractor_reasons":{"A":"Incorrect because workspace lease is a direct monetary expense.","B":"Incorrect because client billings are revenue from the chosen option.","C":"Incorrect because hardware purchase is a capital outlay.","D":"Option D is correct because opportunity cost measures the value of the next best alternative foregone, which is the $50,000 salary."}}},{"id":"P1_U1_MCQ_459","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_459","question":"Which factor of production includes natural gifts of nature such as gold deposits, timberland, and fresh water rivers?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all natural resources provided by nature used in production.","distractor_reasons":{"A":"Option A is correct because land covers all natural resources provided by nature used in production.","B":"Incorrect because labour refers to human work effort.","C":"Incorrect because capital refers to man-made physical machinery and tools.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_460","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_460","question":"How can a jewelry maker directly increase the added value of its hand-crafted necklaces without increasing their retail price?","options":{"A":"Increasing monthly advertising expenditures on social media","B":"Renting a larger showroom in a commercial district","C":"Increasing hourly wages for workshop jewelers","D":"Negotiating lower wholesale prices for precious stones from suppliers"},"correctOption":"D","correctAnswer":"Negotiating lower wholesale prices for precious stones from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because added value equals selling price minus bought-in component costs. Reducing material purchase prices widens the added value gap.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Incorrect because renting a showroom increases fixed overheads.","C":"Incorrect because higher wages increase overhead labor costs, lowering profit margin rather than unit added value.","D":"Option D is correct because added value equals selling price minus bought-in component costs. Reducing material purchase prices widens the added value gap."}}},{"id":"P1_U1_MCQ_461","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_461","question":"Which economic activity is classified under the primary sector?","options":{"A":"Refining crude oil into commercial gasoline","B":"Providing accounting and audit services to corporate clients","C":"Cultivating wheat crops on commercial farmland","D":"Operating a retail supermarket chain"},"correctOption":"C","correctAnswer":"Cultivating wheat crops on commercial farmland","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because crop farming involves direct extraction/growing of natural resources from the environment (primary sector).","distractor_reasons":{"A":"Incorrect because oil refining is secondary sector processing.","B":"Incorrect because accounting is a tertiary professional service.","C":"Option C is correct because crop farming involves direct extraction/growing of natural resources from the environment (primary sector).","D":"Incorrect because supermarket retailing is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_462","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_462","question":"What structural economic change occurs when an economy undergoes deindustrialization?","options":{"A":"Employment shifts out of service industries into agriculture","B":"The government nationalizes all private manufacturing plants","C":"Industrial manufacturing output doubles while commercial services collapse","D":"Employment and output decline in secondary manufacturing and expand in tertiary services"},"correctOption":"D","correctAnswer":"Employment and output decline in secondary manufacturing and expand in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a structural decline in the relative importance of manufacturing (secondary sector) and growth in services (tertiary sector).","distractor_reasons":{"A":"Incorrect because primary sector jobs do not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to sector proportions, not ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a structural decline in the relative importance of manufacturing (secondary sector) and growth in services (tertiary sector)."}}},{"id":"P1_U1_MCQ_463","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_463","question":"Which entity operates in the public sector of a mixed economy?","options":{"A":"A municipal government department providing public street cleaning","B":"A private waste management company owned by three partners","C":"A commercial recycling corporation listed on the stock market","D":"An independent cleaning contractor operating as a sole trader"},"correctOption":"A","correctAnswer":"A municipal government department providing public street cleaning","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because municipal government departments are public sector entities funded and managed by state/local authorities.","distractor_reasons":{"A":"Option A is correct because municipal government departments are public sector entities funded and managed by state/local authorities.","B":"Incorrect because private partnerships belong to the private sector.","C":"Incorrect because publicly listed corporations belong to the private sector.","D":"Incorrect because sole traders belong to the private sector."}}},{"id":"P1_U1_MCQ_464","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_464","question":"A mining firm extracts iron ore, a steelworks processes ore into steel sheets, and an appliance maker uses steel sheets to manufacture refrigerators. How are these three businesses classified?","options":{"A":"Iron ore mining: Secondary; Steelworks: Primary; Appliance maker: Tertiary","B":"Iron ore mining: Primary; Steelworks: Secondary; Appliance maker: Secondary","C":"Iron ore mining: Primary; Steelworks: Tertiary; Appliance maker: Secondary","D":"Iron ore mining: Tertiary; Steelworks: Secondary; Appliance maker: Primary"},"correctOption":"B","correctAnswer":"Iron ore mining: Primary; Steelworks: Secondary; Appliance maker: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mining iron ore is primary extraction, while both steelmaking and appliance manufacturing process materials into manufactured goods (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Option B is correct because mining iron ore is primary extraction, while both steelmaking and appliance manufacturing process materials into manufactured goods (secondary sector).","C":"Incorrect because steelmaking is secondary processing, not tertiary service.","D":"Incorrect because sector order is reversed."}}},{"id":"P1_U1_MCQ_465","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_465","question":"What is a key feature of a mixed economy?","options":{"A":"100% government control over all production and distribution","B":"Complete absence of state taxes and statutory employment laws","C":"A balance of resource allocation between private market enterprises and public state providers","D":"Total economic dependence on primary sector mining and farming"},"correctOption":"C","correctAnswer":"A balance of resource allocation between private market enterprises and public state providers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a mixed economy combines private enterprise (market mechanism) with public sector state provision.","distractor_reasons":{"A":"Incorrect because total state control describes a command economy.","B":"Incorrect because mixed economies rely on state taxes and workplace regulations.","C":"Option C is correct because a mixed economy combines private enterprise (market mechanism) with public sector state provision.","D":"Incorrect because mixed economies feature all economic sectors."}}},{"id":"P1_U1_MCQ_466","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_466","question":"Which activity operates entirely in the tertiary economic sector?","options":{"A":"Diamond mining extraction","B":"Furniture assembly factory work","C":"Cotton farming","D":"Hotel hospitality and management services"},"correctOption":"D","correctAnswer":"Hotel hospitality and management services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because hotel hospitality provides commercial consumer services, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because diamond mining is primary extraction.","B":"Incorrect because furniture assembly is secondary manufacturing.","C":"Incorrect because cotton farming is primary agriculture.","D":"Option D is correct because hotel hospitality provides commercial consumer services, placing it in the tertiary sector."}}},{"id":"P1_U1_MCQ_467","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_467","question":"What is the primary motive driving private sector business owners in a market economy?","options":{"A":"Earning profit to provide a financial return on capital invested","B":"Meeting output quotas established by central government planners","C":"Providing free public services to all citizens regardless of cost","D":"Maximizing annual tax liabilities payable to government authorities"},"correctOption":"A","correctAnswer":"Earning profit to provide a financial return on capital invested","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profit is the primary commercial objective of private sector business owners.","distractor_reasons":{"A":"Option A is correct because earning profit is the primary commercial objective of private sector business owners.","B":"Incorrect because central output quotas belong to command economies.","C":"Incorrect because providing free public services is a public sector objective.","D":"Incorrect because private firms seek to manage tax legally rather than maximize tax payments."}}},{"id":"P1_U1_MCQ_468","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_468","question":"Why might a national government choose to privatize a state-run postal service?","options":{"A":"To convert postal workers into civil service state employees","B":"To increase direct government control over postal stamp prices","C":"To prevent private capital investment in national logistics infrastructure","D":"To introduce market competition, profit motives, and operational efficiency"},"correctOption":"D","correctAnswer":"To introduce market competition, profit motives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because privatization transfers state assets to private ownership, bringing market incentives that increase efficiency and innovation.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Incorrect because privatization reduces direct government control.","C":"Incorrect because privatization encourages private capital investment.","D":"Option D is correct because privatization transfers state assets to private ownership, bringing market incentives that increase efficiency and innovation."}}},{"id":"P1_U1_MCQ_469","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_469","question":"A furniture business cuts timber from its own woodland, makes woollen jumpers in a factory and sells them through its own shops. Which sectors does it operate in?","options":{"A":"Primary and secondary only","B":"Secondary and tertiary only","C":"Primary, secondary and tertiary","D":"Primary and tertiary only"},"correctOption":"C","correctAnswer":"Primary, secondary and tertiary","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","distractor_reasons":{"A":"This answer leaves out the retail shops, which are a tertiary activity, so it does not cover all the stages described.","B":"This answer omits the woodland timber extraction, which is a primary-sector activity carried out by the business.","C":"Option C is correct because extracting timber is primary, manufacturing furniture is secondary and retailing through shops is tertiary.","D":"This answer misses the factory manufacturing stage, which is clearly a secondary-sector activity."}}},{"id":"P1_U1_MCQ_470","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_470","question":"What structural shift in labor distribution usually accompanies rapid industrialization in a country?","options":{"A":"Workers move from factory manufacturing into primary crop farming","B":"Service sector firms close down completely to prioritize mining","C":"Public sector agencies take complete control of all private retail shops","D":"Workers shift out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Workers shift out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization involves expanding secondary manufacturing, attracting labor away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves from farming into manufacturing, not the reverse.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization involves expanding secondary manufacturing, attracting labor away from primary agriculture."}}},{"id":"P1_U1_MCQ_471","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_471","question":"Which quality is vital for an entrepreneur starting a new commercial venture?","options":{"A":"Reluctance to adapt business operations when market demand shifts","B":"Preference for following orders from senior managers in large firms","C":"Self-motivation, willingness to accept risk, and resilience after failures","D":"Avoidance of financial liability for business debts"},"correctOption":"C","correctAnswer":"Self-motivation, willingness to accept risk, and resilience after failures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early setbacks.","distractor_reasons":{"A":"Incorrect because flexibility is vital to entrepreneurial success.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Option C is correct because entrepreneurs require initiative, willingness to take calculated risks, and determination to overcome early setbacks.","D":"Incorrect because entrepreneurs bear and manage business risks."}}},{"id":"P1_U1_MCQ_472","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_472","question":"Rather than buying another firm, Granite Ridge Mining develops and launches teak garden furniture using its own research team and spare cash. What type of growth is this?","options":{"A":"Backward vertical integration","B":"External takeover","C":"Internal (organic) growth","D":"Horizontal integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","distractor_reasons":{"A":"Backward vertical integration requires acquiring a supplier, which has not happened here.","B":"An external takeover means buying another business; this firm grew without acquiring one.","C":"Option C is correct because developing new products with internal resources is a form of internal or organic growth.","D":"Horizontal integration involves combining with another firm at the same stage of an industry."}}},{"id":"P1_U1_MCQ_473","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_473","question":"Brightleaf Bakery opens three new branches in the Scottish Highlands using profits retained from the previous year. What type of growth is this?","options":{"A":"Internal (organic) growth","B":"Horizontal integration","C":"Backward vertical integration","D":"A takeover"},"correctOption":"A","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","distractor_reasons":{"A":"Option A is correct because internal or organic growth expands a business from within using its own resources such as retained profits.","B":"Horizontal integration means joining with another firm at the same stage of production, usually through a merger or takeover.","C":"Backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"A takeover is external growth involving the purchase of another company rather than expansion using internal funds."}}},{"id":"P1_U1_MCQ_474","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_474","question":"Summit Cycling, a chain of coffee shops, takes over a rival chain of coffee shops in Devon. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","distractor_reasons":{"A":"Forward vertical integration means moving closer to the final customer, such as a producer buying retail outlets.","B":"Backward vertical integration means moving towards suppliers, such as a retailer buying a manufacturing plant.","C":"Option C is correct because horizontal integration is the joining of firms at the same stage of activity in the same industry.","D":"Internal growth uses a firm's own resources; taking over a rival is external growth through acquisition."}}},{"id":"P1_U1_MCQ_475","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_475","question":"A manufacturer of aluminium laptops buys a chain of retail stores that sell its goods to the public. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Organic growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","distractor_reasons":{"A":"Backward vertical integration would involve acquiring a supplier further from the consumer, not a retailer near the end customer.","B":"Option B is correct because forward vertical integration occurs when a producer acquires a business closer to the final consumer, such as retail outlets.","C":"Horizontal integration involves a firm at the same production stage, whereas a retailer is at a later stage of the chain.","D":"Organic growth is internal expansion, while purchasing an established retail chain is an external acquisition."}}},{"id":"P1_U1_MCQ_476","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_476","question":"A company making handmade wooden chairs purchases the business that supplies its raw ingredients. What type of growth has taken place?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","distractor_reasons":{"A":"Forward vertical integration means moving towards the customer, such as buying distributors, not acquiring a supplier.","B":"Horizontal integration joins firms at the same stage of activity, whereas a raw-material supplier is at an earlier stage.","C":"Option C is correct because backward vertical integration means acquiring a supplier at an earlier stage of the production chain.","D":"Internal growth is funded and achieved within the business, while buying a supplier is an external acquisition."}}},{"id":"P1_U1_MCQ_477","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_477","question":"Priya is setting up a business in Cornwall. Which action best describes the role of an entrepreneur?","options":{"A":"Taking financial risk and organising resources to create and run a business","B":"Receiving a fixed salary for carrying out routine office work","C":"Guaranteeing that the business will never face competition","D":"Owning the business but avoiding all decision-making"},"correctOption":"A","correctAnswer":"Taking financial risk and organising resources to create and run a business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","distractor_reasons":{"A":"Option A is correct because entrepreneurs identify opportunities, organise factors of production and accept the risk of profit or loss.","B":"A fixed salary for routine work describes an employee, not an entrepreneur who bears risk and organises the business.","C":"No entrepreneur can guarantee the absence of competition, which is outside their control in a market.","D":"Entrepreneurs are actively involved in decisions; avoiding all decision-making is not an entrepreneurial role."}}},{"id":"P1_U1_MCQ_478","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_478","question":"Fatima is preparing a business plan before launching a new venture. What is the main purpose of a business plan?","options":{"A":"To avoid having to keep any accounting records","B":"To guarantee that the business will make a profit in its first year","C":"To remove the need for any market research before launching","D":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance"},"correctOption":"D","correctAnswer":"To set out the business idea, targets and financial forecasts to guide decisions and attract finance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors.","distractor_reasons":{"A":"A business plan does not remove the legal and practical need to keep proper financial records.","B":"A plan cannot guarantee profit, which depends on future trading conditions and many factors outside the plan.","C":"A business plan supports rather than replaces market research, which remains necessary to understand customers.","D":"Option D is correct because a business plan records objectives, strategy and projected finances to guide the owner and persuade lenders or investors."}}},{"id":"P1_U1_MCQ_479","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_479","question":"An analyst wants to compare the size of Coastline Cartons with other firms in the same industry. Which of these is a measure of business size?","options":{"A":"Gross profit margin","B":"Number of employees","C":"Current ratio","D":"Return on capital employed"},"correctOption":"B","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","distractor_reasons":{"A":"Gross profit margin measures profitability relative to revenue, not the physical scale or size of the business.","B":"Option B is correct because the number of employees is a direct indicator of the scale of a business and is commonly used to compare firm size.","C":"The current ratio measures short-term liquidity and says nothing about how large the business is.","D":"Return on capital employed is a profitability ratio rather than a measure of the size of the business."}}},{"id":"P1_U1_MCQ_480","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_480","question":"Marlow Boats has grown very rapidly over two years. Which is most likely to be a problem caused by such rapid growth?","options":{"A":"Communication and decision-making become slower as the organisation grows","B":"The business automatically gains a monopoly position","C":"Its products immediately become lower in price than all rivals","D":"Its shareholders are no longer entitled to any dividend"},"correctOption":"A","correctAnswer":"Communication and decision-making become slower as the organisation grows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","distractor_reasons":{"A":"Option A is correct because rapid growth often strains management structures, lengthening communication lines and slowing decisions.","B":"Rapid growth does not automatically create a monopoly, which would require dominance of the whole market.","C":"Growth gives no guarantee of lower prices than competitors, which depend on costs and pricing decisions.","D":"Shareholders keep their dividend rights regardless of how quickly the business expands."}}},{"id":"P1_U1_MCQ_481","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_481","question":"Oliver pays a fee to use the well-known brand and business model of Bluepeak Software. What is this arrangement called?","options":{"A":"A joint venture","B":"A franchise","C":"A partnership","D":"A public corporation"},"correctOption":"B","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","distractor_reasons":{"A":"A joint venture involves joint ownership of a new business, not paying for the right to use an existing brand.","B":"Option B is correct because a franchise is an arrangement where a franchisee pays to trade using another firm's established brand and system.","C":"A partnership shares ownership and management between partners rather than licensing a brand for a fee.","D":"A public corporation is government-owned and is unrelated to this private fee-paying arrangement."}}},{"id":"P1_U1_MCQ_482","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_482","question":"An organisation is wholly owned by the government and provides an essential public service in Manchester. What is it called?","options":{"A":"A public corporation","B":"A sole trader","C":"A private limited company","D":"A franchise"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","distractor_reasons":{"A":"Option A is correct because a public corporation is a government-owned body set up to provide services on behalf of the state.","B":"A sole trader is a privately owned one-person business, not a government-owned organisation.","C":"A private limited company is owned by private shareholders and is not wholly owned by the government.","D":"A franchise is a private commercial arrangement to use a brand, not a government-owned public service body."}}},{"id":"P1_U1_MCQ_483","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_483","question":"What is a dividend in the context of a company such as Evergreen Gardens?","options":{"A":"A share of company profits paid out to shareholders","B":"The total value of the company's fixed assets","C":"A tax that the company pays to the government only","D":"The wage paid to the highest-paid employee"},"correctOption":"A","correctAnswer":"A share of company profits paid out to shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","distractor_reasons":{"A":"Option A is correct because a dividend is a distribution of a portion of company profits to shareholders as a return on their investment.","B":"The value of fixed assets appears in the statement of financial position and is not a payment to shareholders.","C":"Company tax is paid to the government, whereas a dividend is paid to the owners of the business.","D":"Wages are payments to employees for labour, not distributions of profit to shareholders."}}},{"id":"P1_U1_MCQ_484","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_484","question":"Which statement about a sole trader such as Daniel selling artisan sourdough loaves is correct?","options":{"A":"The owner keeps all the profits but has unlimited liability","B":"The owner must share all profits with the government","C":"The owner has limited liability and pays no tax","D":"The owner cannot make any business decisions alone"},"correctOption":"A","correctAnswer":"The owner keeps all the profits but has unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","distractor_reasons":{"A":"Option A is correct because a sole trader owns the business, keeps the profits and carries unlimited personal liability for its debts.","B":"The owner keeps the profits but pays tax on them; profits are not shared with the government as owners' earnings.","C":"A sole trader has unlimited liability, not limited liability, and is still liable to pay income tax on profits.","D":"A sole trader makes the business decisions alone, which is one of the advantages of this form of organisation."}}},{"id":"P1_U1_MCQ_485","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_485","question":"Which source of finance involves selling ownership stakes in a private limited company such as Silverdale Foods?","options":{"A":"Bank overdraft","B":"Issuing shares","C":"Trade credit","D":"Leasing equipment"},"correctOption":"B","correctAnswer":"Issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","distractor_reasons":{"A":"A bank overdraft is borrowed money that must be repaid and does not transfer ownership of the business.","B":"Option B is correct because issuing shares raises finance by selling part-ownership of the company to investors.","C":"Trade credit delays payment to suppliers and is a short-term source of finance, not a sale of ownership.","D":"Leasing is renting an asset instead of buying it and does not give investors any share in the company."}}},{"id":"P1_U1_MCQ_486","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_486","question":"What is a benefit to Elena of becoming a franchisee of Northwind Toys rather than starting an independent business?","options":{"A":"Using an established brand and proven business model lowers the risk of failure","B":"The franchisee keeps every pound of profit with no fees to pay","C":"The franchisee has complete freedom to change the product range","D":"The franchisee has no need to follow any trading standards"},"correctOption":"A","correctAnswer":"Using an established brand and proven business model lowers the risk of failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","distractor_reasons":{"A":"Option A is correct because a recognised brand and tested procedures attract customers and reduce the uncertainty of a new venture.","B":"Franchisees normally pay an initial fee and ongoing royalties, so they do not keep all the profit.","C":"Franchise agreements usually require the franchisee to follow the franchisor's products and methods, limiting freedom.","D":"Franchisees must still meet legal and quality standards set by the franchisor and by law."}}},{"id":"P1_U1_MCQ_487","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_487","question":"Two competing firms in South Wales decide to form a jointly owned new company to develop a shared distribution network. What is this?","options":{"A":"A merger into a single existing firm","B":"A joint venture","C":"A sole trader","D":"An internal expansion"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","distractor_reasons":{"A":"A merger combines existing businesses into one, rather than setting up a separate jointly owned company.","B":"Option B is correct because a joint venture creates a separate business owned jointly by the participating organisations for a shared purpose.","C":"A sole trader has one owner, whereas here two firms jointly own the new company.","D":"Internal expansion uses a firm's own resources rather than a partnership with another business."}}},{"id":"P1_U1_MCQ_488","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_488","question":"A business such as Bramble House Candles has owners with limited liability and shares that cannot be traded on a stock exchange. Which type of organisation is it?","options":{"A":"Sole trader","B":"Private limited company such as Bramble House Candles","C":"Public limited company","D":"Partnership"},"correctOption":"B","correctAnswer":"Private limited company such as Bramble House Candles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","distractor_reasons":{"A":"A sole trader has unlimited liability, so it does not meet the limited-liability condition in the question.","B":"Option B is correct because a private limited company gives limited liability but its shares are not freely traded on a public stock exchange.","C":"A public limited company has shares that can be traded on a stock exchange, which this question rules out.","D":"A traditional partnership gives owners unlimited liability rather than limited liability."}}},{"id":"P1_U1_MCQ_489","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_489","question":"Kwame runs a business selling stainless steel water bottles as a sole trader. What is the position regarding liability for the business debts?","options":{"A":"Kwame has unlimited liability and is personally responsible for all the debts","B":"Kwame has limited liability and risks only the money invested","C":"Liability is shared equally with the government","D":"There is no liability because the business is not registered"},"correctOption":"A","correctAnswer":"Kwame has unlimited liability and is personally responsible for all the debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","distractor_reasons":{"A":"Option A is correct because a sole trader has unlimited liability, so personal assets can be used to settle business debts.","B":"Limited liability applies to shareholders in limited companies, not to a sole trader who personally owns the business.","C":"The government does not share a sole trader's debts; the owner alone is responsible for them.","D":"Registering the business does not remove liability; a sole trader remains personally liable whether registered or not."}}},{"id":"P1_U1_MCQ_490","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_490","question":"Amara starts a business in the Midlands with two friends, sharing ownership and management. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Public corporation"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","distractor_reasons":{"A":"A sole trader has a single owner, whereas this business has several owners sharing management.","B":"Option B is correct because a partnership is a business owned and usually managed by two or more people who share profits and responsibility.","C":"A public limited company sells shares on a stock exchange and has limited liability, unlike a simple partnership.","D":"A public corporation is government-owned and provides a public service, which is not the case here."}}},{"id":"P1_U1_MCQ_491","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_491","question":"A firm that supplies raw materials to Oakfield Furniture is which of its stakeholders?","options":{"A":"A customer","B":"A supplier","C":"A shareholder","D":"A competitor"},"correctOption":"B","correctAnswer":"A supplier","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","distractor_reasons":{"A":"A customer buys the finished goods from the business rather than providing raw materials to it.","B":"Option B is correct because a supplier is a stakeholder that provides goods or materials the business needs for production.","C":"A shareholder owns part of the business, which is a different relationship from selling it inputs.","D":"A competitor sells rival products in the same market rather than supplying this business."}}},{"id":"P1_U1_MCQ_492","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_492","question":"Which is a typical objective of a public-sector organisation such as a state-funded hospital in Cornwall?","options":{"A":"To maximise dividends for private shareholders","B":"To provide a service for the community rather than to maximise profit","C":"To avoid serving customers who cannot pay","D":"To keep prices as high as the market will bear"},"correctOption":"B","correctAnswer":"To provide a service for the community rather than to maximise profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","distractor_reasons":{"A":"Public-sector organisations do not have private shareholders seeking dividends, so this cannot be their objective.","B":"Option B is correct because public-sector bodies aim to provide services for the public good rather than to generate private profit.","C":"Public services generally aim to be accessible to the whole community, including those who cannot afford to pay.","D":"Charging the highest possible prices is a private profit-seeking objective, not the aim of a public service provider."}}},{"id":"P1_U1_MCQ_493","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_493","question":"What is usually the primary objective of a private-sector business such as Summit Cycling?","options":{"A":"To avoid all competition","B":"To provide free public services","C":"To make a profit","D":"To be owned by the state"},"correctOption":"C","correctAnswer":"To make a profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","distractor_reasons":{"A":"Businesses cannot normally avoid competition, which is a feature of the market in which they operate.","B":"Providing free public services is typical of the public sector, not of privately owned businesses seeking a return.","C":"Option C is correct because private-sector businesses are owned by private investors and normally aim to earn a profit for their owners.","D":"Private-sector firms are owned by private individuals or shareholders, not by the state."}}},{"id":"P1_U1_MCQ_494","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_494","question":"Which group is most directly interested in Cedar Grove Joinery paying competitive wages and offering safe working conditions?","options":{"A":"Its employees","B":"Its customers","C":"Its shareholders","D":"Its local suppliers"},"correctOption":"A","correctAnswer":"Its employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","distractor_reasons":{"A":"Option A is correct because employees are the stakeholder group whose pay and workplace safety directly affect their wellbeing.","B":"Customers are mainly concerned with the price, quality and availability of the products they buy.","C":"Shareholders are primarily interested in returns on their investment and the profitability of the business.","D":"Suppliers are mainly interested in receiving payment and maintaining orders for their materials."}}},{"id":"P1_U1_MCQ_495","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_495","question":"A local council in Stirling is concerned that Willowvale Cosmetics may close a factory and cause job losses. In what capacity is the council a stakeholder?","options":{"A":"As a competitor in the same market","B":"As part of the local community and government","C":"As a supplier of raw materials","D":"As a shareholder seeking dividends"},"correctOption":"B","correctAnswer":"As part of the local community and government","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","distractor_reasons":{"A":"A local council is not usually a rival business competing to sell the same products in the market.","B":"Option B is correct because the local council represents the community and government interests such as employment and local economic wellbeing.","C":"The council is not providing raw materials to the firm in this situation, so it is not acting as a supplier.","D":"The council has not bought shares here, so it is not acting as a shareholder seeking dividends."}}},{"id":"P1_U1_MCQ_496","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_496","question":"Sunrise Poultry aims to increase the scale of its operations by opening new markets and increasing output over five years. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Social responsibility","D":"Short-term profit maximisation"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","distractor_reasons":{"A":"Option A is correct because growth is a long-term objective concerned with increasing the size, output and market reach of a business.","B":"Survival is a short-term defensive aim of covering costs, not of expanding into new markets.","C":"Social responsibility concerns the effect on society and is not the objective described by expansion and higher output.","D":"Short-term profit maximisation focuses on immediate profit rather than a planned five-year expansion."}}},{"id":"P1_U1_MCQ_497","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_497","question":"Riverbend Textiles sets its output and price to earn the largest possible total profit. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Sales revenue maximisation","C":"Market share leadership","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","distractor_reasons":{"A":"Option A is correct because profit maximisation means choosing the level of output where total revenue minus total cost is greatest.","B":"Sales revenue maximisation focuses on total sales value rather than on the difference between revenue and cost.","C":"Market share leadership aims at a large share of industry sales and may accept lower profits to achieve it.","D":"Survival means covering costs to stay in business, which is a more short-term and defensive aim."}}},{"id":"P1_U1_MCQ_498","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_498","question":"Facing falling demand in Stirling, Lakeside Dairy concentrates on covering its costs and staying in business. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","distractor_reasons":{"A":"Growth means increasing sales, output or the size of the business, which is not the priority when simply staying afloat.","B":"Option B is correct because survival is a short-term objective focused on generating enough revenue to cover costs and continue trading.","C":"Profit maximisation seeks the highest profit, whereas here the firm only aims to cover its costs.","D":"Social responsibility concerns the impact on society and is not the aim described in this difficult trading situation."}}},{"id":"P1_U1_MCQ_499","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_499","question":"Nortex Electronics wants to raise its percentage of total industry sales in the coming year. Which objective is this?","options":{"A":"Profit maximisation","B":"Survival","C":"Increasing market share","D":"Cost minimisation alone"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","distractor_reasons":{"A":"Profit maximisation targets the largest profit, which may not coincide with selling a larger share of the market.","B":"Survival is about covering costs and continuing to trade rather than winning a greater share of sales.","C":"Option C is correct because market share measures the firm's sales as a percentage of total market sales and raising it is a distinct objective.","D":"Cost minimisation concerns reducing expenses and does not directly describe gaining a larger share of industry sales."}}},{"id":"P1_U1_MCQ_500","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_500","question":"Granite Ridge Mining aims to sell as many units as possible, even if profit per unit is low. Which objective is this?","options":{"A":"Sales revenue maximisation","B":"Survival","C":"Social enterprise","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Sales revenue maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","distractor_reasons":{"A":"Option A is correct because sales revenue maximisation prioritises a high volume of sales and total revenue over high profit margins.","B":"Survival only requires covering costs, whereas this firm deliberately pursues a high volume of sales.","C":"A social enterprise reinvests profits for a social purpose, which is different from maximising sales revenue.","D":"Profit maximisation would not knowingly accept low profit per unit in order to boost sales volume."}}},{"id":"P1_U1_MCQ_501","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_501","question":"Dubois Plastics Ltd has a limited stock of raw materials at its Manila factory. The materials can be used to make either 60 units of school backpacks or 25 units of smartphones. The firm decides to make the 25 units of smartphones. What is the opportunity cost of this decision?","options":{"A":"The 60 units of school backpacks that could have been made instead","B":"The sales revenue earned from selling all the smartphones","C":"The cash paid to buy the raw materials for the smartphones","D":"The wages paid to the workers who make the smartphones"},"correctOption":"A","correctAnswer":"The 60 units of school backpacks that could have been made instead","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because opportunity cost is the value of the next best alternative foregone, which here is the 60 units of school backpacks given up when the smartphones are chosen.","distractor_reasons":{"B":"Revenue from the product actually chosen is the return from the decision, whereas opportunity cost measures what was sacrificed, not what was gained.","C":"This is an explicit monetary expense of the chosen option, not the value of the foregone alternative, so it is not an opportunity cost.","D":"Wages are a production cost incurred in the chosen activity and do not represent the alternative output that was not produced.","A":"Option is correct because opportunity cost is the value of the next best alternative foregone, which here is the 60 units of school backpacks given up when the smartphones are chosen."}}},{"id":"P1_U1_MCQ_502","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_502","question":"A pottery workshop purchases raw clay and glaze for $8 per vase and sells the hand-painted vase for $35. Which action will directly increase the added value per vase by $5?","options":{"A":"Increasing total weekly vase output from 50 to 100 units","B":"Adding premium gift packaging and raising the retail price to $40","C":"Reducing potter overtime wage payments by $5 per shift","D":"Purchasing $5 worth of extra raw clay to store in inventory"},"correctOption":"B","correctAnswer":"Adding premium gift packaging and raising the retail price to $40","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs ($35 - $8 = $27). Raising the price to $40 while keeping material costs constant increases added value to $32 ($5 increase).","distractor_reasons":{"A":"Incorrect because increasing production volume affects overall output and revenue potential, not unit added value.","B":"Option B is correct because added value equals selling price minus bought-in material costs ($35 - $8 = $27). Raising the price to $40 while keeping material costs constant increases added value to $32 ($5 increase).","C":"Incorrect because wages are internal operating expenses, not bought-in material costs.","D":"Incorrect because purchasing extra inventory increases raw material assets without altering unit added value."}}},{"id":"P1_U1_MCQ_503","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_503","question":"A commercial bakery relies on wheat fields, baking staff, industrial ovens, and an innovative head baker who manages business risks. Which factor of production do the wheat fields represent?","options":{"A":"Capital","B":"Labour","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because land encompasses all natural resources and physical space provided by nature used in production.","distractor_reasons":{"A":"Incorrect because capital refers to man-made machinery and tools such as industrial ovens.","B":"Incorrect because labour refers to the physical and mental effort of human workers.","C":"Option C is correct because land encompasses all natural resources and physical space provided by nature used in production.","D":"Incorrect because enterprise refers to the risk-taking and managerial role of the entrepreneur."}}},{"id":"P1_U1_MCQ_504","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_504","question":"A car manufacturing plant splits its assembly line into distinct tasks, assigning one worker exclusively to fit tires. What is a primary disadvantage of using division of labor in this way?","options":{"A":"Training workers for their specific task takes a significantly longer time","B":"The purchase price of tires from external suppliers increases","C":"Overall production speed and output per hour decrease","D":"Monotony and repetition can lead to worker boredom, low morale, and quality errors"},"correctOption":"D","correctAnswer":"Monotony and repetition can lead to worker boredom, low morale, and quality errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single narrow task continuously leads to monotony, lowering worker motivation and increasing the risk of assembly mistakes.","distractor_reasons":{"A":"Incorrect because training a worker for a single simple task is fast and inexpensive.","B":"Incorrect because internal division of labor has no impact on external supplier component pricing.","C":"Incorrect because specialization generally increases production speed and hourly output.","D":"Option D is correct because repeating a single narrow task continuously leads to monotony, lowering worker motivation and increasing the risk of assembly mistakes."}}},{"id":"P1_U1_MCQ_505","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_505","question":"Which of the following items represents a basic human need required for fundamental survival?","options":{"A":"Clean drinking water and essential shelter","B":"A subscription to a video streaming service","C":"A high-end smartphone","D":"A ticket to a music festival"},"correctOption":"A","correctAnswer":"Clean drinking water and essential shelter","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because clean water and shelter are essential physical requirements for human survival.","distractor_reasons":{"A":"Option A is correct because clean water and shelter are essential physical requirements for human survival.","B":"Incorrect because streaming services are entertainment wants.","C":"Incorrect because smartphones are communication and technology wants.","D":"Incorrect because festival tickets are leisure wants."}}},{"id":"P1_U1_MCQ_506","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_506","question":"Why does the economic problem of scarcity exist in all countries regardless of their wealth?","options":{"A":"Governments set price ceilings on consumer goods","B":"Finite factors of production are insufficient to satisfy unlimited human wants","C":"Businesses intentionally limit production to keep profit margins high","D":"High taxation reduces consumer income across the economy"},"correctOption":"B","correctAnswer":"Finite factors of production are insufficient to satisfy unlimited human wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally stems from having limited economic resources available to satisfy infinite human wants.","distractor_reasons":{"A":"Incorrect because price ceilings are government intervention policies, not the fundamental cause of scarcity.","B":"Option B is correct because scarcity fundamentally stems from having limited economic resources available to satisfy infinite human wants.","C":"Incorrect because private business output restrictions do not cause basic economic resource scarcity.","D":"Incorrect because taxation affects purchasing power, not fundamental resource availability."}}},{"id":"P1_U1_MCQ_507","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_507","question":"A handbag manufacturer buys raw leather for $25 and metal zippers for $5 per bag. If the finished handbag is sold to customers for $90, what is the added value per handbag?","options":{"A":"$30","B":"$65","C":"$60","D":"$90"},"correctOption":"C","correctAnswer":"$60","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bought-in material costs equal $25 + $5 = $30. Added value = selling price ($90) - material costs ($30) = $60.","distractor_reasons":{"A":"Incorrect because $30 is the total bought-in material cost.","B":"Incorrect because $65 subtracts only the leather cost ($90 - $25), ignoring the zipper cost.","C":"Option C is correct because bought-in material costs equal $25 + $5 = $30. Added value = selling price ($90) - material costs ($30) = $60.","D":"Incorrect because $90 is the final retail selling price."}}},{"id":"P1_U1_MCQ_508","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_508","question":"A software developer leaves a salaried job paying $80,000 per year to start an independent mobile app development business. What is the opportunity cost of this decision?","options":{"A":"The cost of buying new computer hardware for the business","B":"The office rent paid for the new business premises","C":"The annual revenue earned from selling mobile apps","D":"The $80,000 salary foregone from the corporate job"},"correctOption":"D","correctAnswer":"The $80,000 salary foregone from the corporate job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost is the sacrificed return of the next best alternative given up, which is the $80,000 salary.","distractor_reasons":{"A":"Incorrect because hardware purchase is a direct capital outlay.","B":"Incorrect because office rent is a direct monetary operating expense.","C":"Incorrect because revenue earned is the benefit of the chosen path, not the foregone option.","D":"Option D is correct because opportunity cost is the sacrificed return of the next best alternative given up, which is the $80,000 salary."}}},{"id":"P1_U1_MCQ_509","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_509","question":"Which factor of production includes all natural resources provided by nature, such as mineral deposits, crude oil, and agricultural soil?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land covers all gifts of nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land covers all gifts of nature used in economic production.","B":"Incorrect because labour refers to human work effort.","C":"Incorrect because capital refers to man-made equipment and tools.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_510","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_510","question":"How can a custom watchmaker directly increase the added value of its timepieces without raising retail selling prices?","options":{"A":"Increasing monthly spending on magazine advertising","B":"Negotiating lower purchase prices for raw watch casings from suppliers","C":"Increasing hourly wages for assembly line workers","D":"Renting a larger storage warehouse for raw components"},"correctOption":"B","correctAnswer":"Negotiating lower purchase prices for raw watch casings from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing material purchase costs widens the added value gap.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing material purchase costs widens the added value gap.","C":"Incorrect because higher wages raise operating costs, reducing net profit rather than unit added value.","D":"Incorrect because warehouse rent is an operational overhead."}}},{"id":"P1_U1_MCQ_511","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_511","question":"Which commercial activity is classified under the primary economic sector?","options":{"A":"Assembling consumer electronics in a factory","B":"Providing legal advice to corporate clients","C":"Extracting crude oil from offshore oil rigs","D":"Operating a chain of retail clothing stores"},"correctOption":"C","correctAnswer":"Extracting crude oil from offshore oil rigs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting natural resources directly from the environment is a primary sector activity.","distractor_reasons":{"A":"Incorrect because assembling electronics is secondary sector manufacturing.","B":"Incorrect because legal advice is a tertiary professional service.","C":"Option C is correct because extracting natural resources directly from the environment is a primary sector activity.","D":"Incorrect because retail selling is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_512","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_512","question":"What structural change in employment occurs when a developed country experiences deindustrialization?","options":{"A":"Employment shifts out of service industries into crop farming","B":"The state takes complete ownership of all manufacturing plants","C":"Factory output doubles while service sector revenues decline","D":"Employment contracts in secondary manufacturing and expands in tertiary services"},"correctOption":"D","correctAnswer":"Employment contracts in secondary manufacturing and expands in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization involves a relative decline in secondary sector manufacturing and growth in tertiary sector services.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to economic sectors, not state ownership.","C":"Incorrect because manufacturing contracts relative to services during deindustrialization.","D":"Option D is correct because deindustrialization involves a relative decline in secondary sector manufacturing and growth in tertiary sector services."}}},{"id":"P1_U1_MCQ_513","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_513","question":"Which sector of the economy does this activity belong to? Mei Lin owns a farm in Bristol and harvests cocoa for sale.","options":{"A":"Primary sector","B":"Secondary sector","C":"Public sector","D":"Tertiary sector"},"correctOption":"A","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it.","distractor_reasons":{"B":"The secondary sector involves manufacturing and construction; the described activity is not the processing of materials into goods.","C":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","D":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","A":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it."}}},{"id":"P1_U1_MCQ_514","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_514","question":"A forestry firm cuts down timber, a saw mill processes logs into wooden planks, and a furniture factory uses planks to build tables. How are these three activities categorized?","options":{"A":"Forestry: Secondary; Saw mill: Primary; Furniture factory: Tertiary","B":"Forestry: Primary; Saw mill: Secondary; Furniture factory: Secondary","C":"Forestry: Primary; Saw mill: Tertiary; Furniture factory: Secondary","D":"Forestry: Tertiary; Saw mill: Secondary; Furniture factory: Primary"},"correctOption":"B","correctAnswer":"Forestry: Primary; Saw mill: Secondary; Furniture factory: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting timber is primary extraction, while both processing logs and building tables transform materials into manufactured goods (secondary sector).","distractor_reasons":{"A":"Incorrect because forestry is primary extraction, not secondary.","B":"Option B is correct because cutting timber is primary extraction, while both processing logs and building tables transform materials into manufactured goods (secondary sector).","C":"Incorrect because a saw mill is secondary processing, not tertiary service.","D":"Incorrect because the sector categorization order is incorrect."}}},{"id":"P1_U1_MCQ_515","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_515","question":"Over the past decade the economy around Istanbul has moved workers out of farming and into new factories producing trainers, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Industrialisation","B":"Deindustrialisation","C":"Privatisation","D":"Specialisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"B":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","C":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","D":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","A":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_516","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_516","question":"In Istanbul, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Industrialisation","B":"Division of labour","C":"Primary sector growth","D":"Deindustrialisation"},"correctOption":"D","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","B":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","C":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","D":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_517","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_517","question":"What is the main objective of private sector business owners in a market economy?","options":{"A":"Earning profit to provide a financial return on capital invested","B":"Meeting central government output targets and quotas","C":"Providing free public goods and services to all citizens","D":"Maximizing tax payments made to municipal government authorities"},"correctOption":"A","correctAnswer":"Earning profit to provide a financial return on capital invested","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profit is the primary commercial driver for private sector business owners.","distractor_reasons":{"A":"Option A is correct because earning profit is the primary commercial driver for private sector business owners.","B":"Incorrect because government output quotas belong to planned economies.","C":"Incorrect because providing free public goods is a public sector objective.","D":"Incorrect because private firms manage taxes legally rather than seeking to maximize tax payments."}}},{"id":"P1_U1_MCQ_518","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_518","question":"Why might a national government choose to privatize a state-run railway network?","options":{"A":"To convert railway workers into civil service state employees","B":"To introduce market competition, profit motives, and operational efficiency","C":"To prevent private investment in national transport infrastructure","D":"To increase direct government control over daily ticket prices"},"correctOption":"B","correctAnswer":"To introduce market competition, profit motives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private ownership to foster competition, profit incentives, and higher efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil servant status.","B":"Option B is correct because privatization transfers state assets to private ownership to foster competition, profit incentives, and higher efficiency.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_519","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_519","question":"Which pair correctly matches an economic activity with its correct economic sector?","options":{"A":"Wheat farming - Secondary sector","B":"Car assembly - Primary sector","C":"Management consultancy - Tertiary sector","D":"Copper mining - Tertiary sector"},"correctOption":"C","correctAnswer":"Management consultancy - Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because management consultancy is a commercial service, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because wheat farming is primary sector agriculture.","B":"Incorrect because car assembly is secondary sector manufacturing.","C":"Option C is correct because management consultancy is a commercial service, placing it in the tertiary sector.","D":"Incorrect because copper mining is primary sector extraction."}}},{"id":"P1_U1_MCQ_520","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_520","question":"What structural shift in labor distribution typically occurs as a developing nation undergoes rapid industrialization?","options":{"A":"Workers shift out of factory production into subsistence farming","B":"Service sector businesses close down completely to prioritize mining","C":"Public sector entities nationalize 100% of all private retail shops","D":"Workers move out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Workers move out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization involves expanding manufacturing, drawing labor from primary farming into secondary manufacturing.","distractor_reasons":{"A":"Incorrect because labor shifts from agriculture into manufacturing during industrialization.","B":"Incorrect because tertiary service industries expand alongside manufacturing.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization involves expanding manufacturing, drawing labor from primary farming into secondary manufacturing."}}},{"id":"P1_U1_MCQ_521","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_521","question":"Which characteristic is essential for a successful entrepreneur starting a new commercial venture?","options":{"A":"Avoidance of financial liability for business startup decisions","B":"Preference for taking direct orders from senior managers in large corporations","C":"Unwillingness to change operational methods when market demand shifts","D":"Self-motivation, willingness to accept risk, and resilience after setbacks"},"correctOption":"D","correctAnswer":"Self-motivation, willingness to accept risk, and resilience after setbacks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entrepreneurs require self-drive, calculated risk-taking, and resilience to handle initial startup challenges.","distractor_reasons":{"A":"Incorrect because entrepreneurs assume business risks.","B":"Incorrect because entrepreneurs lead independent ventures rather than seeking employee supervision.","C":"Incorrect because adaptability is vital for entrepreneurial survival.","D":"Option D is correct because entrepreneurs require self-drive, calculated risk-taking, and resilience to handle initial startup challenges."}}},{"id":"P1_U1_MCQ_522","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_522","question":"Why is preparing a comprehensive business plan essential for a new startup applying for a bank loan?","options":{"A":"It automatically grants the firm limited liability status without incorporation","B":"It provides financial projections showing the firm's ability to service and repay loan debt","C":"It guarantees that the startup will achieve net profit during its first year","D":"It fulfills all legal tax registration requirements imposed by government"},"correctOption":"B","correctAnswer":"It provides financial projections showing the firm's ability to service and repay loan debt","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders analyze financial forecasts in a business plan to assess cash flow and debt repayment ability.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","B":"Option B is correct because bank lenders analyze financial forecasts in a business plan to assess cash flow and debt repayment ability.","C":"Incorrect because business plans contain projections, not profit guarantees.","D":"Incorrect because tax registration is a legal requirement independent of business plans."}}},{"id":"P1_U1_MCQ_523","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_523","question":"Nadia Hassan noticed a gap in the local market in Seoul, invested personal savings, took the financial risk and set up a new business making textbooks. Which role is Nadia carrying out?","options":{"A":"A shareholder only","B":"An employee","C":"An entrepreneur","D":"A trade union official"},"correctOption":"C","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","B":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","D":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","C":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_524","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_524","question":"Kwame Boateng wants to start a chain of hair salons in Dar es Salaam and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A business plan","B":"A delivery note","C":"An organisation chart","D":"A statement of profit or loss"},"correctOption":"A","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"B":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","C":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","D":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","A":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_525","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_525","question":"Why do national governments provide grants and advisory assistance to new entrepreneurs?","options":{"A":"To create new jobs, foster innovation, and expand economic growth","B":"To eliminate market competition for state-owned monopolies","C":"To force small business owners to convert into public limited companies","D":"To prevent foreign commercial enterprises from importing goods"},"correctOption":"A","correctAnswer":"To create new jobs, foster innovation, and expand economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government startup support aims to reduce unemployment, stimulate innovation, and drive economic growth.","distractor_reasons":{"A":"Option A is correct because government startup support aims to reduce unemployment, stimulate innovation, and drive economic growth.","B":"Incorrect because governments encourage startups to foster competition, not eliminate it.","C":"Incorrect because government grants do not force changes in legal structure.","D":"Incorrect because startup grants focus on domestic enterprise development, not import tariffs."}}},{"id":"P1_U1_MCQ_526","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_526","question":"A government wants to encourage more people in Osaka to set up small businesses making kitchen utensils. Which of the following is an example of government support for new business start-ups?","options":{"A":"Offering low-interest start-up loans and grant funding to new firms.","B":"Removing all forms of business advice and training for new owners.","C":"Raising the rate of corporation tax on all company profits.","D":"Introducing stricter rules that make it harder to register a new firm."},"correctOption":"A","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"B":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","C":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","D":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","A":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_527","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_527","question":"Okafor Dairy Ltd is a laptops business in Nairobi with 35 employees and annual sales revenue of $3m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The brand image and the quality of its products.","B":"The share price and the dividend yield.","C":"The number of employees and the annual sales turnover.","D":"The profit margin and the current ratio."},"correctOption":"C","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"A":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","B":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","D":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","C":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_528","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_528","question":"Why might the owner of a boutique hair salon prefer to keep the business small rather than expand into a regional chain?","options":{"A":"Small businesses are exempt from paying supplier bills","B":"Regional salon chains are legally prohibited by government regulation","C":"Business expansion automatically revokes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often remain small to keep direct operational control, manage workload, and preserve personal customer service.","distractor_reasons":{"A":"Incorrect because all firms must settle supplier invoices regardless of size.","B":"Incorrect because regional salon chains operate legally.","C":"Incorrect because expansion does not cancel limited liability.","D":"Option D is correct because business owners often remain small to keep direct operational control, manage workload, and preserve personal customer service."}}},{"id":"P1_U1_MCQ_529","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_529","question":"Over five years Bauer Plastics Ltd expanded its trainers business in Seoul by reinvesting its own profits to open 3 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Backward vertical integration","D":"Internal (organic) growth"},"correctOption":"D","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","B":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","C":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","D":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_530","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_530","question":"Mensah Textiles Ltd, a chocolate bars manufacturer in Birmingham, has taken over a rival firm that makes the same chocolate bars at the same stage of production. What type of integration is this?","options":{"A":"Internal growth","B":"Horizontal integration","C":"Backward vertical integration","D":"Forward vertical integration"},"correctOption":"B","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","C":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","D":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","B":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_531","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_531","question":"Carlos Mendez is the single owner of a chain of hair salons in Auckland and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"Its shares are freely traded on a stock exchange.","B":"The business has a separate legal identity from its owner.","C":"The owner has unlimited liability for all the business debts.","D":"The owner must publish detailed annual accounts publicly."},"correctOption":"C","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","B":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","D":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","C":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_532","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_532","question":"James Mwangi and Kwame Boateng have set up a business together in Lagos, sharing the ownership, management and profits of a wedding planning business. What type of business organisation have they created?","options":{"A":"A franchise","B":"A public limited company","C":"A partnership","D":"A sole trader business"},"correctOption":"C","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","B":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","D":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","C":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_533","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_533","question":"An individual purchases a franchise license to open a branded fast-food outlet. What is a key disadvantage experienced by this franchisee?","options":{"A":"Paying initial franchise fees and ongoing royalties on sales revenue to the franchisor","B":"Total absence of brand recognition in the local market","C":"Complete freedom to alter store branding without head office approval","D":"Inability to receive staff training or operational guidance from the franchisor"},"correctOption":"A","correctAnswer":"Paying initial franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront fees and ongoing royalty payments, which reduce operating profits.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront fees and ongoing royalty payments, which reduce operating profits.","B":"Incorrect because established franchises provide strong brand recognition.","C":"Incorrect because franchisees must strictly follow brand operational rules.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_534","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_534","question":"Two car manufacturers form a joint venture to build an electric vehicle battery plant. What is a primary benefit of this strategic setup?","options":{"A":"A permanent merger combining both parent corporations into one firm","B":"Sharing high development costs, operational risks, and specialized technical expertise","C":"Complete exemption from paying corporate profit taxes","D":"Total elimination of management disagreements between executives of both firms"},"correctOption":"B","correctAnswer":"Sharing high development costs, operational risks, and specialized technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows separate businesses to share high capital expenses, risks, and technical know-how on a specific project.","distractor_reasons":{"A":"Incorrect because joint ventures are project-based separate entities, not full mergers.","B":"Option B is correct because a joint venture allows separate businesses to share high capital expenses, risks, and technical know-how on a specific project.","C":"Incorrect because joint ventures remain subject to tax laws.","D":"Incorrect because management conflict between joint venture partners is a recognized risk."}}},{"id":"P1_U1_MCQ_535","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_535","question":"Boateng Furniture Ltd is a privately owned cement company in Dubai. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A partnership","B":"A sole trader","C":"A public limited company (Plc)","D":"A private limited company (Ltd)"},"correctOption":"D","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","B":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","C":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","D":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_536","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_536","question":"Why might owners of an expanding partnership choose to re-incorporate as a Private Limited Company (LTD)?","options":{"A":"To issue company shares on the public stock exchange","B":"To remove the legal requirement to publish annual financial accounts","C":"To avoid paying national corporate profit tax","D":"To protect personal wealth via limited liability and simplify raising private equity capital"},"correctOption":"D","correctAnswer":"To protect personal wealth via limited liability and simplify raising private equity capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD limits owner liability to their invested capital and makes it easier to sell private shares to new investors.","distractor_reasons":{"A":"Incorrect because only PLCs can sell shares on public stock exchanges.","B":"Incorrect because LTDs face strict accounting and reporting standards.","C":"Incorrect because LTDs must pay corporate profits tax.","D":"Option D is correct because incorporating as an LTD limits owner liability to their invested capital and makes it easier to sell private shares to new investors."}}},{"id":"P1_U1_MCQ_537","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_537","question":"A large school backpacks business in Accra, Nasser Glassware Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A public limited company (Plc)","B":"A private limited company (Ltd)","C":"A partnership","D":"A sole trader"},"correctOption":"A","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"B":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","C":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","D":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","A":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_538","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_538","question":"Which legal document details profit-sharing ratios, partner responsibilities, and dispute resolution rules in a partnership?","options":{"A":"Certificate of Incorporation","B":"Deed of Partnership (Partnership Agreement)","C":"Memorandum of Association","D":"Articles of Incorporation"},"correctOption":"B","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership sets out the internal operational terms, profit splits, and duties agreed among partners.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation registers a limited company.","B":"Option B is correct because a Deed of Partnership sets out the internal operational terms, profit splits, and duties agreed among partners.","C":"Incorrect because Memorandum of Association governs company external relationships.","D":"Incorrect because Articles of Incorporation form limited companies."}}},{"id":"P1_U1_MCQ_539","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_539","question":"Which business organization has a separate legal identity from its owners?","options":{"A":"Sole trader","B":"General partnership","C":"Private Limited Company (LTD)","D":"Unincorporated joint venture"},"correctOption":"C","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because incorporated entities like LTDs exist as separate legal persons from their shareholders.","distractor_reasons":{"A":"Incorrect because sole traders are unincorporated (owner and business are legally identical).","B":"Incorrect because general partnerships are unincorporated.","C":"Option C is correct because incorporated entities like LTDs exist as separate legal persons from their shareholders.","D":"Incorrect because unincorporated joint ventures do not have separate legal personality."}}},{"id":"P1_U1_MCQ_540","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_540","question":"What risk does a franchisor face when granting franchise rights to independent operators?","options":{"A":"The franchisor loses legal ownership of the corporate trademark","B":"The franchisor becomes personally liable for franchisee bank loans","C":"Franchisees can legally stop paying contractually agreed royalties","D":"Poor service or low quality at one franchisee outlet can harm the global brand reputation"},"correctOption":"D","correctAnswer":"Poor service or low quality at one franchisee outlet can harm the global brand reputation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because bad performance at a single franchisee store damages customer perception across the entire brand chain.","distractor_reasons":{"A":"Incorrect because trademark ownership stays with the franchisor.","B":"Incorrect because franchisors are not liable for franchisee debt.","C":"Incorrect because franchise contracts mandate royalty payments.","D":"Option D is correct because bad performance at a single franchisee store damages customer perception across the entire brand chain."}}},{"id":"P1_U1_MCQ_541","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_541","question":"During a severe downturn in Kuala Lumpur, Rossi Foods Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Survival","B":"Growth","C":"Profit maximisation","D":"Market share"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"B":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","C":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","D":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","A":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_542","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_542","question":"Patel Publishing Ltd in Lagos has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Growth","B":"Social enterprise","C":"Survival","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"B":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","C":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","D":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","A":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_543","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_543","question":"Petrova Glassware Ltd wants to increase the proportion of total sales in the bottled water market in Auckland that it captures for itself. Which objective is this?","options":{"A":"Survival","B":"Cost minimisation","C":"Increasing market share","D":"Social enterprise"},"correctOption":"C","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","B":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","D":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","C":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_544","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_544","question":"Ali Plastics Ltd in Lisbon reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Market share","B":"Social enterprise objectives","C":"Cost minimisation","D":"Profit maximisation"},"correctOption":"B","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","D":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","B":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_545","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_545","question":"Which stakeholder group is described here in relation to Hassan Machinery Ltd, a furniture manufacturer in Nairobi? The firms customers who buy its products and depend on their quality.","options":{"A":"Shareholders","B":"Customers","C":"The local community","D":"Employees"},"correctOption":"B","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price.","distractor_reasons":{"A":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","C":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","D":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","B":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price."}}},{"id":"P1_U1_MCQ_546","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_546","question":"At Adeyemi Bakery Ltd in Birmingham, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Managers seeking faster growth conflict with customers seeking better quality.","B":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","C":"The government seeking lower taxes conflicts with the local community seeking more jobs.","D":"Customers seeking lower prices conflict with suppliers seeking higher prices."},"correctOption":"B","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","C":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","D":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","B":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_547","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_547","question":"A state-run healthcare provider in Lisbon is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to maximise returns for private shareholders.","B":"It mainly aims to increase its share of the global healthcare market.","C":"It mainly aims to provide a service to the community rather than maximise profit.","D":"It mainly aims to extract natural resources for export earnings."},"correctOption":"C","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","B":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","D":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","C":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_548","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_548","question":"Costa Paper Ltd sells 50 units of denim clothing in Leeds. Total sales of denim clothing in the whole market are 200 units. What is the firms market share?","options":{"A":"25%","B":"10%","C":"30%","D":"20%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (50/200) x 100 = 25%.","distractor_reasons":{"B":"10% is not the market share: dividing 50 by 200 and multiplying by 100 gives 25%, not 10%.","C":"30% is wrong; the correct calculation of firm sales over total market sales times 100 yields 25%.","D":"20% is incorrect because it does not result from dividing the firms 50 units by the 200 total market units.","A":"Option is correct because market share = (firm sales / total market sales) x 100 = (50/200) x 100 = 25%."}}},{"id":"P1_U1_MCQ_549","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_549","question":"Dubois Bakery Ltd, a textbooks firm in Accra, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Survival","C":"Market share","D":"Social enterprise"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"B":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","C":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","D":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","A":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_550","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_550","question":"During a severe downturn in Kampala, Haddad Steel Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Growth","B":"Market share","C":"Survival","D":"Profit maximisation"},"correctOption":"C","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","B":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","D":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","C":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_551","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_551","question":"A textile manufacturer has enough cotton yarn to weave either 500 blankets or 800 shirts. If the business decides to manufacture 500 blankets, what is the opportunity cost of this decision?","options":{"A":"The 800 shirts that could have been produced instead","B":"The total purchase cost of the raw cotton yarn","C":"The sales revenue generated from selling the 500 blankets","D":"The electricity cost of operating the weaving machinery"},"correctOption":"A","correctAnswer":"The 800 shirts that could have been produced instead","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is defined as the next best alternative foregone when an economic decision is made, which is the 800 shirts.","distractor_reasons":{"A":"Option A is correct because opportunity cost is defined as the next best alternative foregone when an economic decision is made, which is the 800 shirts.","B":"Incorrect because raw material expenditure is a direct financial cost, not the sacrificed alternative.","C":"Incorrect because sales revenue is the financial return from the chosen decision, not the opportunity cost.","D":"Incorrect because electricity cost is a running operating expense."}}},{"id":"P1_U1_MCQ_552","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_552","question":"A leather goods maker buys raw hides for $20 and metal buckles for $5 per leather belt. The finished belt sells for $60. Which business action will directly increase the added value per belt by $10?","options":{"A":"Increasing weekly belt output from 100 to 200 units","B":"Attaching a designer label and increasing the retail price to $70","C":"Reducing leather cutter hourly wages by $10 per shift","D":"Storing $10 worth of additional raw hides in the warehouse"},"correctOption":"B","correctAnswer":"Attaching a designer label and increasing the retail price to $70","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs ($60 - $25 = $35). Raising the selling price to $70 without changing material costs increases added value to $45 ($10 increase).","distractor_reasons":{"A":"Incorrect because increasing output alters total revenue and volume profits, not unit added value.","B":"Option B is correct because added value equals selling price minus bought-in material costs ($60 - $25 = $35). Raising the selling price to $70 without changing material costs increases added value to $45 ($10 increase).","C":"Incorrect because worker wages are overhead operational expenses, not bought-in material costs.","D":"Incorrect because holding extra inventory increases stock assets without affecting unit added value."}}},{"id":"P1_U1_MCQ_553","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_553","question":"A commercial farm utilizes fertile soil, tractor operators, harvesting machinery, and an innovative farm director. Which factor of production does the harvesting machinery represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used in the production process.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like fertile soil.","B":"Incorrect because labour refers to the physical and mental human effort of tractor operators.","C":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used in the production process.","D":"Incorrect because enterprise refers to the risk-taking role of the farm director."}}},{"id":"P1_U1_MCQ_554","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_554","question":"An electronics assembly plant assigns a worker to perform a single specialized task of soldering circuit boards all day. What is a key limitation of division of labor in this scenario?","options":{"A":"Workers require years of expensive higher education to master a single task","B":"The component cost of circuit boards purchased from suppliers increases","C":"Production speed per worker drops significantly across the shift","D":"Repetitive execution of one task can cause boredom, lower motivation, and careless errors"},"correctOption":"D","correctAnswer":"Repetitive execution of one task can cause boredom, lower motivation, and careless errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because specialization in a single monotonous task leads to worker boredom, which can reduce morale and cause higher defect rates.","distractor_reasons":{"A":"Incorrect because single narrow tasks require minimal training time.","B":"Incorrect because internal division of labor does not alter supplier prices.","C":"Incorrect because division of labor typically speeds up production output rates.","D":"Option D is correct because specialization in a single monotonous task leads to worker boredom, which can reduce morale and cause higher defect rates."}}},{"id":"P1_U1_MCQ_555","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_555","question":"Which of the following items is classified as a basic human need necessary for survival?","options":{"A":"Basic clothing for warmth and protection","B":"A luxury smartwatch","C":"A high-speed gaming console","D":"A weekend stay at a resort hotel"},"correctOption":"A","correctAnswer":"Basic clothing for warmth and protection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adequate clothing for protection against weather is a fundamental human survival need.","distractor_reasons":{"A":"Option A is correct because adequate clothing for protection against weather is a fundamental human survival need.","B":"Incorrect because luxury smartwatches are consumer wants.","C":"Incorrect because gaming consoles are entertainment wants.","D":"Incorrect because resort hotel stays are leisure wants."}}},{"id":"P1_U1_MCQ_556","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_556","question":"Why does the economic problem of scarcity exist in all modern economies?","options":{"A":"Central government planners fix strict output quotas on manufactured goods","B":"Unlimited human wants exceed the limited economic resources available to produce goods","C":"Private firms deliberately refuse to hire unemployed workers","D":"High commercial interest rates reduce corporate capital investments"},"correctOption":"B","correctAnswer":"Unlimited human wants exceed the limited economic resources available to produce goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity is the basic economic problem arising from infinite human wants facing finite resources.","distractor_reasons":{"A":"Incorrect because government quotas are administrative controls, not the root cause of scarcity.","B":"Option B is correct because scarcity is the basic economic problem arising from infinite human wants facing finite resources.","C":"Incorrect because private hiring decisions do not create basic resource scarcity.","D":"Incorrect because interest rates influence investment levels, not the basic existence of economic scarcity."}}},{"id":"P1_U1_MCQ_557","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_557","question":"A bicycle manufacturer buys metal tubing for $30 and rubber tires for $10 per bicycle. The completed bicycle is sold for $180. What is the added value per bicycle?","options":{"A":"$40","B":"$150","C":"$140","D":"$180"},"correctOption":"C","correctAnswer":"$140","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material cost = $30 + $10 = $40. Added value = selling price ($180) minus material costs ($40) = $140.","distractor_reasons":{"A":"Incorrect because $40 is the total bought-in material cost.","B":"Incorrect because $150 subtracts only the metal tubing cost ($180 - $30), omitting tire costs.","C":"Option C is correct because total bought-in material cost = $30 + $10 = $40. Added value = selling price ($180) minus material costs ($40) = $140.","D":"Incorrect because $180 is the total selling price."}}},{"id":"P1_U1_MCQ_558","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_558","question":"An accountant quits a corporate position earning $60,000 per year to set up an independent tax consultancy business. What is the opportunity cost of starting this new enterprise?","options":{"A":"The annual lease cost of renting a professional office space","B":"The fees billed to consultancy clients during the first year of trading","C":"The capital spent purchasing accounting software licenses","D":"The $60,000 salary foregone from the previous corporate job"},"correctOption":"D","correctAnswer":"The $60,000 salary foregone from the previous corporate job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the value of the next best alternative given up, which is the $60,000 salary.","distractor_reasons":{"A":"Incorrect because office lease is an explicit cash outlay.","B":"Incorrect because client fees represent revenue from the new business choice.","C":"Incorrect because software purchases are capital expenditure outlays.","D":"Option D is correct because opportunity cost measures the value of the next best alternative given up, which is the $60,000 salary."}}},{"id":"P1_U1_MCQ_559","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_559","question":"Which factor of production encompasses all natural resources such as copper ore, natural gas, and coastal fisheries?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land includes all raw, unrefined natural resources found on or under the earth.","distractor_reasons":{"A":"Option A is correct because land includes all raw, unrefined natural resources found on or under the earth.","B":"Incorrect because labour represents human work effort.","C":"Incorrect because capital represents man-made machinery and facilities.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_560","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_560","question":"How can a shoe maker directly increase the added value of its product without raising the final selling price to consumers?","options":{"A":"Increasing advertising spending on national television networks","B":"Negotiating lower component prices for leather upper soles from suppliers","C":"Increasing hourly wage rates paid to factory assembly workers","D":"Renting a larger distribution warehouse near a freight port"},"correctOption":"B","correctAnswer":"Negotiating lower component prices for leather upper soles from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering raw material purchase costs increases unit added value.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering raw material purchase costs increases unit added value.","C":"Incorrect because higher labor wages increase overhead expenses, reducing profit margin rather than unit added value.","D":"Incorrect because warehouse rent increases operational overhead costs."}}},{"id":"P1_U1_MCQ_561","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_561","question":"Which economic operation is classified as belonging to the primary sector?","options":{"A":"Refining raw bauxite into aluminum sheets","B":"Providing tax audit advice to corporate businesses","C":"Harvesting coffee beans on a agricultural estate","D":"Operating a chain of retail coffee shops"},"correctOption":"C","correctAnswer":"Harvesting coffee beans on a agricultural estate","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because harvesting agricultural products involves direct extraction/growing of natural resources (primary sector).","distractor_reasons":{"A":"Incorrect because refining bauxite is secondary sector processing.","B":"Incorrect because tax auditing is a tertiary professional service.","C":"Option C is correct because harvesting agricultural products involves direct extraction/growing of natural resources (primary sector).","D":"Incorrect because running coffee shops is a tertiary retail service."}}},{"id":"P1_U1_MCQ_562","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_562","question":"What structural economic transition occurs when an economy experiences deindustrialization?","options":{"A":"Workers move out of financial services into primary mining","B":"The central government nationalizes all private manufacturing plants","C":"Manufacturing factory output expands while service sector revenue drops","D":"Employment and national output contract in manufacturing and expand in tertiary services"},"correctOption":"D","correctAnswer":"Employment and national output contract in manufacturing and expand in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative structural decline in secondary manufacturing and growth in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to sector proportions, not ownership.","C":"Incorrect because manufacturing output contracts relative to tertiary services.","D":"Option D is correct because deindustrialization describes a relative structural decline in secondary manufacturing and growth in tertiary services."}}},{"id":"P1_U1_MCQ_563","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_563","question":"A national government owns and operates a travel agency in Cape Town in order to provide a public service for citizens. Which sector of the economy does this organisation belong to?","options":{"A":"Primary sector","B":"Private sector","C":"Public sector","D":"Secondary sector"},"correctOption":"C","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned and run by the government, which defines the public sector.","distractor_reasons":{"A":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","B":"The private sector consists of businesses owned by private individuals or shareholders; this organisation is not privately owned.","D":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","C":"Option is correct because the organisation is owned and run by the government, which defines the public sector."}}},{"id":"P1_U1_MCQ_564","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_564","question":"A mining firm extracts lithium ore, a processing plant refines the ore into battery-grade lithium, and an electric car maker uses the lithium to produce car batteries. How are these three firms classified?","options":{"A":"Mining: Secondary; Processing plant: Primary; Car maker: Tertiary","B":"Mining: Primary; Processing plant: Secondary; Car maker: Secondary","C":"Mining: Primary; Processing plant: Tertiary; Car maker: Secondary","D":"Mining: Tertiary; Processing plant: Secondary; Car maker: Primary"},"correctOption":"B","correctAnswer":"Mining: Primary; Processing plant: Secondary; Car maker: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mining lithium ore is primary extraction, while both refining ore and manufacturing batteries transform raw materials into manufactured products (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Option B is correct because mining lithium ore is primary extraction, while both refining ore and manufacturing batteries transform raw materials into manufactured products (secondary sector).","C":"Incorrect because a processing plant is secondary manufacturing, not tertiary service.","D":"Incorrect because sector order is incorrect."}}},{"id":"P1_U1_MCQ_565","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_565","question":"What is a key feature of a mixed economic system?","options":{"A":"100% state ownership and allocation of all land and factory assets","B":"Total absence of workplace safety laws and business taxes","C":"Co-existence of private sector market enterprises and public sector state provision","D":"Exclusive reliance on primary sector farming and mineral extraction"},"correctOption":"C","correctAnswer":"Co-existence of private sector market enterprises and public sector state provision","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a mixed economy allocates economic resources through both private market forces and public government intervention.","distractor_reasons":{"A":"Incorrect because total state control describes a planned economy.","B":"Incorrect because mixed economies utilize taxes and regulatory standards.","C":"Option C is correct because a mixed economy allocates economic resources through both private market forces and public government intervention.","D":"Incorrect because mixed economies operate across all economic sectors."}}},{"id":"P1_U1_MCQ_566","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_566","question":"In Lagos, 70% of workers are employed in the primary sector, 20% in the secondary sector and 55% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Tertiary sector","B":"Public sector","C":"Secondary sector","D":"Primary sector"},"correctOption":"D","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"The primary sector employs 70% of workers, which is lower than the largest share of 70%, so it does not employ the most workers.","distractor_reasons":{"B":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","C":"The secondary sector employs 20% of workers, which is lower than the largest share of 70%, so it does not employ the most workers.","D":"The primary sector employs 70% of workers, which is lower than the largest share of 70%, so it does not employ the most workers.","A":"The tertiary sector employs 55% of workers, the largest share of the three sectors, so it employs the most workers."}}},{"id":"P1_U1_MCQ_567","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_567","question":"What primary motive drives private sector business owners in a market economy?","options":{"A":"Earning profit to provide a financial return on capital invested","B":"Achieving output quotas specified by government ministers","C":"Providing free public services to all citizens regardless of cost","D":"Maximizing annual tax liabilities paid to tax authorities"},"correctOption":"A","correctAnswer":"Earning profit to provide a financial return on capital invested","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profit is the primary commercial goal of private business owners.","distractor_reasons":{"A":"Option A is correct because earning profit is the primary commercial goal of private business owners.","B":"Incorrect because output quotas belong to command economies.","C":"Incorrect because providing free public services is a public sector objective.","D":"Incorrect because private firms manage taxes legally rather than maximizing tax payments."}}},{"id":"P1_U1_MCQ_568","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_568","question":"Why might a state government decide to privatize a national telecommunications provider?","options":{"A":"To convert telecom engineers into state civil servants","B":"To restrict private capital investment in digital infrastructure","C":"To introduce profit incentives, private capital, and market competition to boost efficiency","D":"To increase direct government control over consumer broadband prices"},"correctOption":"C","correctAnswer":"To introduce profit incentives, private capital, and market competition to boost efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because privatization transfers state assets to private owners, introducing market competition and profit motives that drive efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil servant status.","B":"Incorrect because privatization encourages private investment.","C":"Option C is correct because privatization transfers state assets to private owners, introducing market competition and profit motives that drive efficiency.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_569","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_569","question":"A state-owned organisation in Mumbai provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To provide a service to the community rather than to maximise profit.","B":"To maximise profit for its private shareholders.","C":"To increase the wealth of the governments individual ministers.","D":"To extract and sell as many natural resources as possible."},"correctOption":"A","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"B":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","C":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","D":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","A":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_570","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_570","question":"What structural employment shift generally occurs as an economy moves through rapid industrialization?","options":{"A":"Workers leave factory work to take up primary farming","B":"Commercial service firms close down completely to prioritize mining","C":"Public sector departments nationalize all private retail stores","D":"Labor moves out of primary agriculture into secondary manufacturing"},"correctOption":"D","correctAnswer":"Labor moves out of primary agriculture into secondary manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization expands secondary manufacturing, drawing labor away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves into manufacturing during industrialization, not out of it.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization expands secondary manufacturing, drawing labor away from primary agriculture."}}},{"id":"P1_U1_MCQ_571","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_571","question":"Which personal attribute is vital for an entrepreneur launching a new business enterprise?","options":{"A":"Self-drive, risk tolerance, and resilience when facing challenges","B":"Preference for working under direct supervisor orders in a large company","C":"Reluctance to adapt business operations when market demand changes","D":"Avoidance of financial responsibility for startup expenses"},"correctOption":"A","correctAnswer":"Self-drive, risk tolerance, and resilience when facing challenges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because successful entrepreneurs need initiative, willingness to accept financial risk, and resilience against failure.","distractor_reasons":{"A":"Option A is correct because successful entrepreneurs need initiative, willingness to accept financial risk, and resilience against failure.","B":"Incorrect because entrepreneurs lead independent ventures.","C":"Incorrect because adaptability is crucial for business survival.","D":"Incorrect because entrepreneurs take on financial responsibility."}}},{"id":"P1_U1_MCQ_572","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_572","question":"Why is producing a comprehensive business plan essential when a new startup seeks bank loan financing?","options":{"A":"It automatically grants the company limited liability status without legal incorporation","B":"It details financial forecasts proving the firm's capacity to service interest and repay principal","C":"It guarantees that the startup will make a profit in its first year","D":"It replaces statutory tax filing obligations enforced by government"},"correctOption":"B","correctAnswer":"It details financial forecasts proving the firm's capacity to service interest and repay principal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders analyze cash flow forecasts in a business plan to evaluate default risk and repayment capacity.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","B":"Option B is correct because bank lenders analyze cash flow forecasts in a business plan to evaluate default risk and repayment capacity.","C":"Incorrect because business plans contain projections, not profit guarantees.","D":"Incorrect because tax filing is a legal requirement separate from planning."}}},{"id":"P1_U1_MCQ_573","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_573","question":"Which metric is a standard, valid measure used to evaluate and compare business size within an industry sector?","options":{"A":"Annual net profit generated by the business","B":"Unit retail price of leading products","C":"Total monetary value of capital employed","D":"Percentage profit margin added to raw material costs"},"correctOption":"C","correctAnswer":"Total monetary value of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term investment) is a universally recognized standard metric of business scale.","distractor_reasons":{"A":"Incorrect because net profit is NOT a valid size metric (a small firm can earn higher profit than a large inefficient firm).","B":"Incorrect because unit price reflects product positioning, not company scale.","C":"Option C is correct because capital employed (total long-term investment) is a universally recognized standard metric of business scale.","D":"Incorrect because margin percentage reflects pricing strategy, not business size."}}},{"id":"P1_U1_MCQ_574","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_574","question":"A bicycles manufacturer in Bristol, Rossi Steel Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Horizontal integration","B":"Internal growth","C":"Forward vertical integration","D":"Backward vertical integration"},"correctOption":"C","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain.","B":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","D":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","C":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain."}}},{"id":"P1_U1_MCQ_575","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_575","question":"Why do national governments offer advisory support and grants to newly established small businesses?","options":{"A":"To generate employment, encourage innovation, and stimulate economic growth","B":"To eliminate market competition for state-owned monopolies","C":"To force small businesses to re-register as public limited companies","D":"To restrict foreign commercial enterprises from importing goods"},"correctOption":"A","correctAnswer":"To generate employment, encourage innovation, and stimulate economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because supporting new business startups helps lower unemployment, foster innovation, and increase national output.","distractor_reasons":{"A":"Option A is correct because supporting new business startups helps lower unemployment, foster innovation, and increase national output.","B":"Incorrect because government grants promote competition rather than eliminate it.","C":"Incorrect because grants do not force changes in legal ownership structures.","D":"Incorrect because startup grants focus on domestic business creation, not import barriers."}}},{"id":"P1_U1_MCQ_576","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_576","question":"Costa Furniture Ltd, a ceramic tiles producer in Accra, has purchased a steel works that previously supplied its raw materials. What type of integration is this?","options":{"A":"Backward vertical integration","B":"Horizontal integration","C":"Forward vertical integration","D":"Internal growth"},"correctOption":"A","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"B":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","C":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","D":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","A":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_577","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_577","question":"After a period of very rapid expansion, Bennett Beverages Ltd in Sao Paulo found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing bottled water business. Which problem of growth does this illustrate?","options":{"A":"A reduction in the number of competitors in the market.","B":"Loss of control and coordination difficulties as the business becomes larger.","C":"Higher staff morale throughout the workforce.","D":"Lower average costs from economies of scale."},"correctOption":"B","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","C":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","D":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","B":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_578","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_578","question":"Why might the owner of a local bakery prefer to remain small rather than expand into a regional bakery chain?","options":{"A":"Small bakeries are exempt from paying supplier bills","B":"Regional bakery chains are legally prohibited by government","C":"Expanding the business automatically revokes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct operational control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct operational control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because regional bakery chains operate legally.","C":"Incorrect because business expansion does not cancel limited liability.","D":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact."}}},{"id":"P1_U1_MCQ_579","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_579","question":"Which action represents an example of internal (organic) business growth?","options":{"A":"Developing a new product range funded by retained profits","B":"Acquiring a major competitor in the domestic market","C":"Forming a joint venture with an overseas supplier","D":"Merging with a third-party logistics company"},"correctOption":"A","correctAnswer":"Developing a new product range funded by retained profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as developing new products or opening new locations.","distractor_reasons":{"A":"Option A is correct because organic/internal growth expands the business using its own internal resources, such as developing new products or opening new locations.","B":"Incorrect because acquiring a competitor is external growth via takeover.","C":"Incorrect because joint ventures are external strategic partnerships.","D":"Incorrect because merging with a logistics company is external vertical growth."}}},{"id":"P1_U1_MCQ_580","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_580","question":"Rahman Dairy Ltd, a ceramic tiles firm in Hanoi, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"A shortage of customer demand for its products.","B":"Excessive profitability that attracted too much competition.","C":"Cash flow problems, leaving it unable to pay debts as they fell due.","D":"Over-regulation of the market by the government."},"correctOption":"C","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"A":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","B":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","D":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","C":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_581","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_581","question":"What does unlimited liability mean for a sole trader operating an auto repair shop?","options":{"A":"The business owner's risk is limited strictly to invested capital.","B":"The business is eligible to trade shares publicly on stock exchanges.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay off supplier debts if the business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","distractor_reasons":{"A":"Incorrect because limiting liability to invested capital describes limited companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_582","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_582","question":"Which characteristic distinguishes a Public Limited Company (PLC) from a Private Limited Company (LTD)?","options":{"A":"PLC directors have unlimited personal liability for corporate debts","B":"PLCs are managed directly by state government departments","C":"PLCs are legally restricted from trading internationally","D":"PLC shares can be traded publicly on a stock exchange without restriction"},"correctOption":"D","correctAnswer":"PLC shares can be traded publicly on a stock exchange without restriction","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PLCs can offer shares publicly on stock exchanges, whereas LTD shares are sold privately with shareholder approval.","distractor_reasons":{"A":"Incorrect because both PLCs and LTDs provide limited liability protection.","B":"Incorrect because PLCs are private sector entities, not state departments.","C":"Incorrect because PLCs frequently operate internationally.","D":"Option D is correct because PLCs can offer shares publicly on stock exchanges, whereas LTD shares are sold privately with shareholder approval."}}},{"id":"P1_U1_MCQ_583","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_583","question":"An entrepreneur buys a franchise license to operate a branded fitness center. What is a key drawback faced by this franchisee?","options":{"A":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to alter gym equipment and branding without corporate approval","D":"Inability to receive staff training or operational support from the franchisor"},"correctOption":"A","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","B":"Incorrect because established franchises offer strong brand recognition.","C":"Incorrect because franchisees must strictly comply with franchisor operational rules.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_584","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_584","question":"Two technology firms form a joint venture to develop artificial intelligence software. What is a primary benefit of this business setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing high research costs, operational risks, and technical expertise","C":"Complete exemption from paying national corporate taxes","D":"Total elimination of management disagreements between executive teams"},"correctOption":"B","correctAnswer":"Sharing high research costs, operational risks, and technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_585","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_585","question":"Ahmed Nasser pays an upfront fee and regular royalties to a well-known chocolate bars brand for the right to trade under its name in Dubai and follow its established business system. What is this arrangement called?","options":{"A":"A public corporation","B":"A franchise","C":"A takeover","D":"A joint venture"},"correctOption":"B","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"A":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","C":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","D":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand.","B":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model."}}},{"id":"P1_U1_MCQ_586","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_586","question":"Two separate firms in Leeds agree to create a new jointly owned business to develop a new canned tomatoes, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A franchise","B":"A sole trader","C":"A joint venture","D":"A merger"},"correctOption":"C","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","B":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","D":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","C":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_587","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_587","question":"An organisation in Osaka is owned by the government but operates as a separate business providing a parcel delivery service to the public. What type of organisation is it?","options":{"A":"A public corporation","B":"A sole trader","C":"A partnership","D":"A public limited company"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"B":"A sole trader is owned by one private individual with unlimited liability, not by the government.","C":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","D":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","A":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_588","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_588","question":"Carlos Mendez owns a business in Auckland. The business incurs debts it cannot repay, and Carloss personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"No liability","B":"Shared liability","C":"Limited liability","D":"Unlimited liability"},"correctOption":"D","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","B":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","C":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","D":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_589","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_589","question":"Anika Singh is the single owner of a computer repair service in Lisbon and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"Its shares are freely traded on a stock exchange.","B":"The business has a separate legal identity from its owner.","C":"The owner has unlimited liability for all the business debts.","D":"The owner must publish detailed annual accounts publicly."},"correctOption":"C","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","B":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","D":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","C":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_590","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_590","question":"Samuel Mensah and Lucia Ferrari have set up a business together in Istanbul, sharing the ownership, management and profits of a parcel delivery service. What type of business organisation have they created?","options":{"A":"A sole trader business","B":"A partnership","C":"A franchise","D":"A public limited company"},"correctOption":"B","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","C":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","D":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","B":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_591","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_591","question":"Mensah Pharmaceuticals Ltd in Bogota has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Growth","B":"Social enterprise","C":"Survival","D":"Profit maximisation"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"B":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","C":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","D":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","A":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_592","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_592","question":"Bauer Auto Parts Ltd wants to increase the proportion of total sales in the cement market in Accra that it captures for itself. Which objective is this?","options":{"A":"Survival","B":"Cost minimisation","C":"Social enterprise","D":"Increasing market share"},"correctOption":"D","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","B":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","C":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","D":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_593","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_593","question":"Okafor Machinery Ltd in Lisbon reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Social enterprise objectives","B":"Market share","C":"Profit maximisation","D":"Cost minimisation"},"correctOption":"A","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"B":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","D":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","A":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_594","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_594","question":"Which stakeholder group is described here in relation to Ali Auto Parts Ltd, a denim clothing manufacturer in Accra? The firms customers who buy its products and depend on their quality.","options":{"A":"The local community","B":"Customers","C":"Shareholders","D":"Employees"},"correctOption":"B","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price.","distractor_reasons":{"A":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","C":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","D":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","B":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price."}}},{"id":"P1_U1_MCQ_595","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_595","question":"At Ruiz Ceramics Ltd in Hanoi, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Managers seeking faster growth conflict with customers seeking better quality.","B":"Customers seeking lower prices conflict with suppliers seeking higher prices.","C":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","D":"The government seeking lower taxes conflicts with the local community seeking more jobs."},"correctOption":"C","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","B":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","D":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","C":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_596","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_596","question":"A state-run healthcare provider in Leeds is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to maximise returns for private shareholders.","B":"It mainly aims to provide a service to the community rather than maximise profit.","C":"It mainly aims to extract natural resources for export earnings.","D":"It mainly aims to increase its share of the global healthcare market."},"correctOption":"B","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","C":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","D":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","B":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_597","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_597","question":"Rossi Packaging Ltd sells 40 units of textbooks in Cape Town. Total sales of textbooks in the whole market are 200 units. What is the firms market share?","options":{"A":"40%","B":"20%","C":"80%","D":"60%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (40/200) x 100 = 20%.","distractor_reasons":{"A":"40% is wrong; the correct calculation of firm sales over total market sales times 100 yields 20%.","C":"80% is not the market share: dividing 40 by 200 and multiplying by 100 gives 20%, not 80%.","D":"60% is incorrect because it does not result from dividing the firms 40 units by the 200 total market units.","B":"Option is correct because market share = (firm sales / total market sales) x 100 = (40/200) x 100 = 20%."}}},{"id":"P1_U1_MCQ_598","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_598","question":"Costa Bakery Ltd, a kitchen utensils firm in Accra, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Market share","B":"Profit maximisation","C":"Survival","D":"Social enterprise"},"correctOption":"B","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","C":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","D":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","B":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_599","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_599","question":"During a severe downturn in Shanghai, Rossi Packaging Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Growth","B":"Profit maximisation","C":"Market share","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","C":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","D":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","B":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business."}}},{"id":"P1_U1_MCQ_600","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_600","question":"Tanaka Foods Ltd in Sao Paulo has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Profit maximisation","B":"Growth","C":"Social enterprise","D":"Survival"},"correctOption":"B","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"A":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","C":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","D":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","B":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_601","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_601","question":"A furniture maker has limited timber and must choose between manufacturing 12 wooden dining tables or 24 office desks. What is the opportunity cost of choosing to produce the 24 office desks?","options":{"A":"The 12 wooden dining tables foregone","B":"The total purchase cost of timber for the office desks","C":"The sales revenue from selling all 24 office desks","D":"The hourly wages paid to the carpenters making the desks"},"correctOption":"A","correctAnswer":"The 12 wooden dining tables foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative foregone when an economic choice is made, which is the 12 wooden dining tables.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative foregone when an economic choice is made, which is the 12 wooden dining tables.","B":"Incorrect because timber expenditure is a direct monetary expense, not the foregone product alternative.","C":"Incorrect because sales revenue is the return from the chosen decision.","D":"Incorrect because carpenter wages are direct operational expenses."}}},{"id":"P1_U1_MCQ_602","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_602","question":"A craft shop purchases raw glass for $6 and dye for $4 per handmade ornament. The finished ornament sells for $30. Which action directly increases the added value per ornament by $5?","options":{"A":"Increasing total daily output of ornaments from 40 to 80 units","B":"Adding custom decorative packaging and raising the retail price to $35","C":"Reducing glassblower hourly wages by $5 per shift","D":"Purchasing $5 of extra raw glass to hold in storage"},"correctOption":"B","correctAnswer":"Adding custom decorative packaging and raising the retail price to $35","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value = selling price ($30) - material costs ($10) = $20. Increasing price to $35 without altering material costs raises added value to $25 ($5 increase).","distractor_reasons":{"A":"Incorrect because increasing daily production volume changes overall sales profits, not unit added value.","B":"Option B is correct because added value = selling price ($30) - material costs ($10) = $20. Increasing price to $35 without altering material costs raises added value to $25 ($5 increase).","C":"Incorrect because worker wages are operating expenses, not bought-in material costs.","D":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value."}}},{"id":"P1_U1_MCQ_603","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_603","question":"A commercial orchard relies on fertile land, fruit pickers, automated sorting machines, and an enterprising farm manager. Which factor of production do the automated sorting machines represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical tools, machinery, and equipment used in business production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like fertile orchard land.","B":"Incorrect because labour refers to human work effort like fruit pickers.","C":"Option C is correct because capital consists of man-made physical tools, machinery, and equipment used in business production.","D":"Incorrect because enterprise refers to the risk-taking organizational role."}}},{"id":"P1_U1_MCQ_604","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_604","question":"A computer assembly plant divides its workflow so that one worker is responsible solely for attaching cooling fans to motherboards. What is a primary drawback of this division of labor?","options":{"A":"The task requires long, expensive specialized training for each worker","B":"The component cost of cooling fans purchased from suppliers increases","C":"The total assembly speed of computers decreases overall","D":"Monotonous task repetition can cause worker boredom, reduced motivation, and quality errors"},"correctOption":"D","correctAnswer":"Monotonous task repetition can cause worker boredom, reduced motivation, and quality errors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one single task continuously can lead to boredom, causing lower worker morale and careless assembly mistakes.","distractor_reasons":{"A":"Incorrect because performing a single repetitive task requires very little training time.","B":"Incorrect because internal division of labor does not alter component purchase prices.","C":"Incorrect because specialization typically speeds up work and increases output per hour.","D":"Option D is correct because repeating one single task continuously can lead to boredom, causing lower worker morale and careless assembly mistakes."}}},{"id":"P1_U1_MCQ_605","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_605","question":"Which item represents a fundamental human need essential for biological survival?","options":{"A":"Nutritious food and clean drinking water","B":"A subscription to an online gaming platform","C":"A high-performance sports car","D":"Designer branded sunglasses"},"correctOption":"A","correctAnswer":"Nutritious food and clean drinking water","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because food and clean water are essential biological requirements for human survival.","distractor_reasons":{"A":"Option A is correct because food and clean water are essential biological requirements for human survival.","B":"Incorrect because gaming subscriptions are entertainment wants.","C":"Incorrect because sports cars are luxury transportation wants.","D":"Incorrect because designer sunglasses are fashion wants."}}},{"id":"P1_U1_MCQ_606","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_606","question":"Why does the basic economic problem of scarcity exist in all global economies?","options":{"A":"Governments enact strict price controls on standard consumer products","B":"Finite factors of production are insufficient to satisfy infinite human wants","C":"Firms limit manufacturing output to maintain artificially high profit margins","D":"High national unemployment rates lower worker productivity"},"correctOption":"B","correctAnswer":"Finite factors of production are insufficient to satisfy infinite human wants","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity fundamentally stems from unlimited human wants exceeding the limited resources available.","distractor_reasons":{"A":"Incorrect because price controls are government policies, not the root cause of scarcity.","B":"Option B is correct because scarcity fundamentally stems from unlimited human wants exceeding the limited resources available.","C":"Incorrect because corporate supply restrictions do not cause basic economic resource scarcity.","D":"Incorrect because unemployment affects labor utilization, not fundamental resource scarcity."}}},{"id":"P1_U1_MCQ_607","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_607","question":"A garment factory buys fabric for $18 and buttons for $2 per shirt. The completed shirt sells for $65. What is the added value per shirt?","options":{"A":"$20","B":"$47","C":"$45","D":"$65"},"correctOption":"C","correctAnswer":"$45","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs = $18 + $2 = $20. Added value = selling price ($65) - material costs ($20) = $45.","distractor_reasons":{"A":"Incorrect because $20 is the total bought-in material cost.","B":"Incorrect because $47 subtracts only the fabric cost ($65 - $18), ignoring button costs.","C":"Option C is correct because total bought-in material costs = $18 + $2 = $20. Added value = selling price ($65) - material costs ($20) = $45.","D":"Incorrect because $65 is the final selling price."}}},{"id":"P1_U1_MCQ_608","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_608","question":"A mechanical engineer gives up a job paying $75,000 per year to open an independent engineering consultancy. What is the opportunity cost of establishing this venture?","options":{"A":"The annual lease cost of renting commercial office space","B":"The total fee revenue billed to clients during Year 1","C":"The cost of purchasing professional engineering design software","D":"The $75,000 salary foregone from the previous job"},"correctOption":"D","correctAnswer":"The $75,000 salary foregone from the previous job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative foregone, which is the $75,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is a direct monetary expense.","B":"Incorrect because client billing is revenue from the chosen option.","C":"Incorrect because software purchases are capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative foregone, which is the $75,000 salary."}}},{"id":"P1_U1_MCQ_609","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_609","question":"Which factor of production includes natural gifts of nature such as iron ore deposits, pine forests, and natural lakes?","options":{"A":"Capital","B":"Labour","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because land encompasses all natural unrefined resources provided by nature used in economic production.","distractor_reasons":{"A":"Incorrect because capital refers to man-made physical equipment and tools.","B":"Incorrect because labour refers to human work effort.","C":"Option C is correct because land encompasses all natural unrefined resources provided by nature used in economic production.","D":"Incorrect because enterprise is the risk-taking management function."}}},{"id":"P1_U1_MCQ_610","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_610","question":"How can a custom watch manufacturer directly increase the added value of its watches without raising retail prices?","options":{"A":"Increasing monthly advertising expenditures on social media networks","B":"Negotiating lower wholesale prices for stainless steel casings from suppliers","C":"Increasing hourly wage rates for workshop watchmakers","D":"Renting a larger showroom in a central shopping district"},"correctOption":"B","correctAnswer":"Negotiating lower wholesale prices for stainless steel casings from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing material purchase prices widens the added value gap.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing material purchase prices widens the added value gap.","C":"Incorrect because higher wages increase operating costs, lowering profit margins rather than unit added value.","D":"Incorrect because renting a showroom increases fixed overheads."}}},{"id":"P1_U1_MCQ_611","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_611","question":"Which economic activity belongs to the primary sector?","options":{"A":"Smelting copper ore into industrial metal sheets","B":"Providing financial planning services to retail clients","C":"Logging timber in commercial natural forests","D":"Operating a hardware store selling building supplies"},"correctOption":"C","correctAnswer":"Logging timber in commercial natural forests","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because logging timber involves direct extraction/harvesting of natural resources from the environment (primary sector).","distractor_reasons":{"A":"Incorrect because smelting copper is secondary sector processing.","B":"Incorrect because financial planning is a tertiary professional service.","C":"Option C is correct because logging timber involves direct extraction/harvesting of natural resources from the environment (primary sector).","D":"Incorrect because operating a hardware store is a tertiary retail service."}}},{"id":"P1_U1_MCQ_612","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_612","question":"What structural employment trend occurs when an economy undergoes deindustrialization?","options":{"A":"Workers shift out of commercial banking into crop farming","B":"The state government nationalizes all private manufacturing plants","C":"Industrial manufacturing output doubles while service revenues drop","D":"Employment contracts in secondary manufacturing and expands in tertiary service industries"},"correctOption":"D","correctAnswer":"Employment contracts in secondary manufacturing and expands in tertiary service industries","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a structural decline in the relative importance of manufacturing (secondary sector) and growth in services (tertiary sector).","distractor_reasons":{"A":"Incorrect because primary sector jobs do not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to sector proportions, not ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a structural decline in the relative importance of manufacturing (secondary sector) and growth in services (tertiary sector)."}}},{"id":"P1_U1_MCQ_613","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_613","question":"Which sector of the economy does this activity belong to? Kwame Boateng owns a farm in Hanoi and harvests tea for sale.","options":{"A":"Public sector","B":"Primary sector","C":"Tertiary sector","D":"Secondary sector"},"correctOption":"B","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it.","distractor_reasons":{"A":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","C":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","D":"The secondary sector involves manufacturing and construction; the described activity is not the processing of materials into goods.","B":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it."}}},{"id":"P1_U1_MCQ_614","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_614","question":"A rubber plantation harvests raw latex, a factory processes latex into rubber sheets, and a tire manufacturer uses rubber sheets to produce car tires. How are these three businesses classified?","options":{"A":"Rubber plantation: Secondary; Factory: Primary; Tire manufacturer: Tertiary","B":"Rubber plantation: Primary; Factory: Secondary; Tire manufacturer: Secondary","C":"Rubber plantation: Primary; Factory: Tertiary; Tire manufacturer: Secondary","D":"Rubber plantation: Tertiary; Factory: Secondary; Tire manufacturer: Primary"},"correctOption":"B","correctAnswer":"Rubber plantation: Primary; Factory: Secondary; Tire manufacturer: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting latex is primary extraction, while both processing latex and tire manufacturing transform raw materials into manufactured products (secondary sector).","distractor_reasons":{"A":"Incorrect because harvesting raw latex is primary, not secondary.","B":"Option B is correct because harvesting latex is primary extraction, while both processing latex and tire manufacturing transform raw materials into manufactured products (secondary sector).","C":"Incorrect because processing latex is secondary manufacturing, not tertiary service.","D":"Incorrect because sector order is reversed."}}},{"id":"P1_U1_MCQ_615","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_615","question":"Over the past decade the economy around Auckland has moved workers out of farming and into new factories producing denim clothing, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Privatisation","B":"Deindustrialisation","C":"Industrialisation","D":"Specialisation"},"correctOption":"C","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"A":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","B":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","D":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","C":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_616","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_616","question":"In Jakarta, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Deindustrialisation","B":"Division of labour","C":"Primary sector growth","D":"Industrialisation"},"correctOption":"A","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"B":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","C":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","D":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","A":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_617","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_617","question":"A national government owns and operates a chain of hair salons in Cairo in order to provide a public service for citizens. Which sector of the economy does this organisation belong to?","options":{"A":"Private sector","B":"Primary sector","C":"Secondary sector","D":"Public sector"},"correctOption":"D","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned and run by the government, which defines the public sector.","distractor_reasons":{"A":"The private sector consists of businesses owned by private individuals or shareholders; this organisation is not privately owned.","B":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","C":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","D":"Option is correct because the organisation is owned and run by the government, which defines the public sector."}}},{"id":"P1_U1_MCQ_618","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_618","question":"Why might a national government choose to privatize a state-run electric utility company?","options":{"A":"To convert power plant workers into civil service state employees","B":"To introduce market competition, profit motives, and operational efficiency","C":"To prevent private capital investment in energy infrastructure","D":"To increase direct government control over consumer electricity tariffs"},"correctOption":"B","correctAnswer":"To introduce market competition, profit motives, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private ownership, bringing market incentives that increase efficiency and innovation.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Option B is correct because privatization transfers state assets to private ownership, bringing market incentives that increase efficiency and innovation.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_619","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_619","question":"In Dubai, 60% of workers are employed in the primary sector, 20% in the secondary sector and 45% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Secondary sector","B":"Tertiary sector","C":"Primary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","distractor_reasons":{"A":"The secondary sector employs 20% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","B":"The tertiary sector employs 45% of workers, the largest share of the three sectors, so it employs the most workers.","D":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","C":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_620","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_620","question":"A state-owned organisation in Manila provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To maximise profit for its private shareholders.","B":"To increase the wealth of the governments individual ministers.","C":"To extract and sell as many natural resources as possible.","D":"To provide a service to the community rather than to maximise profit."},"correctOption":"D","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"A":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","B":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","C":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","D":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_621","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_621","question":"Liam O'Connor noticed a gap in the local market in Dar es Salaam, invested personal savings, took the financial risk and set up a new business making ceramic tiles. Which role is Liam carrying out?","options":{"A":"A shareholder only","B":"A trade union official","C":"An entrepreneur","D":"An employee"},"correctOption":"C","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","B":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","D":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","C":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_622","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_622","question":"Lena Fischer wants to start a chain of hair salons in Shanghai and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A statement of profit or loss","B":"A delivery note","C":"A business plan","D":"An organisation chart"},"correctOption":"C","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"A":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","B":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","D":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","C":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_623","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_623","question":"A government wants to encourage more people in Johannesburg to set up small businesses making LED bulbs. Which of the following is an example of government support for new business start-ups?","options":{"A":"Removing all forms of business advice and training for new owners.","B":"Introducing stricter rules that make it harder to register a new firm.","C":"Offering low-interest start-up loans and grant funding to new firms.","D":"Raising the rate of corporation tax on all company profits."},"correctOption":"C","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"A":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","B":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","D":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","C":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_624","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_624","question":"Petrova Glassware Ltd is a textbooks business in Osaka with 75 employees and annual sales revenue of $2m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The number of employees and the annual sales turnover.","B":"The share price and the dividend yield.","C":"The brand image and the quality of its products.","D":"The profit margin and the current ratio."},"correctOption":"A","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"B":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","C":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","D":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","A":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_625","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_625","question":"Over five years Williams Plastics Ltd expanded its school backpacks business in Dubai by reinvesting its own profits to open 6 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Internal (organic) growth","D":"Horizontal integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","B":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","D":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","C":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_626","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_626","question":"Adeyemi Footwear Ltd, a school backpacks manufacturer in Lagos, has taken over a rival firm that makes the same school backpacks at the same stage of production. What type of integration is this?","options":{"A":"Internal growth","B":"Forward vertical integration","C":"Horizontal integration","D":"Backward vertical integration"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","B":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","D":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","C":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_627","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_627","question":"A bottled water manufacturer in Accra, Lin Bakery Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Internal growth","D":"Horizontal integration"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","C":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","D":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain.","B":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain."}}},{"id":"P1_U1_MCQ_628","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_628","question":"Fischer Machinery Ltd, a textbooks producer in Sao Paulo, has purchased a steel works that previously supplied its raw materials. What type of integration is this?","options":{"A":"Internal growth","B":"Backward vertical integration","C":"Horizontal integration","D":"Forward vertical integration"},"correctOption":"B","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"A":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","C":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","D":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","B":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_629","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_629","question":"After a period of very rapid expansion, Lin Foods Ltd in Toronto found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing chocolate bars business. Which problem of growth does this illustrate?","options":{"A":"A reduction in the number of competitors in the market.","B":"Higher staff morale throughout the workforce.","C":"Loss of control and coordination difficulties as the business becomes larger.","D":"Lower average costs from economies of scale."},"correctOption":"C","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","B":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","D":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","C":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_630","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_630","question":"Osei Dairy Ltd, a canned tomatoes firm in Bristol, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"Cash flow problems, leaving it unable to pay debts as they fell due.","B":"A shortage of customer demand for its products.","C":"Over-regulation of the market by the government.","D":"Excessive profitability that attracted too much competition."},"correctOption":"A","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"B":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","C":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","D":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","A":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_631","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_631","question":"Kim Furniture Ltd is a privately owned trainers company in Osaka. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A public limited company (Plc)","B":"A partnership","C":"A private limited company (Ltd)","D":"A sole trader"},"correctOption":"C","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","B":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","D":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","C":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_632","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_632","question":"A large kitchen utensils business in Manila, Tanaka Foods Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A public limited company (Plc)","B":"A partnership","C":"A private limited company (Ltd)","D":"A sole trader"},"correctOption":"A","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"B":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","C":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","D":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","A":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_633","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_633","question":"Ravi Patel pays an upfront fee and regular royalties to a well-known school backpacks brand for the right to trade under its name in Dublin and follow its established business system. What is this arrangement called?","options":{"A":"A takeover","B":"A joint venture","C":"A franchise","D":"A public corporation"},"correctOption":"C","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"A":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","C":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","D":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","B":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand."}}},{"id":"P1_U1_MCQ_634","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_634","question":"Two separate firms in Osaka agree to create a new jointly owned business to develop a new chocolate bars, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A franchise","C":"A merger","D":"A joint venture"},"correctOption":"D","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","B":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","C":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","D":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_635","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_635","question":"An organisation in Accra is owned by the government but operates as a separate business providing an accounting practice to the public. What type of organisation is it?","options":{"A":"A partnership","B":"A public limited company","C":"A public corporation","D":"A sole trader"},"correctOption":"C","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"A":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","B":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","D":"A sole trader is owned by one private individual with unlimited liability, not by the government.","C":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_636","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_636","question":"Priya Sharma owns a business in Toronto. The business incurs debts it cannot repay, and Priyas personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"Shared liability","B":"Limited liability","C":"Unlimited liability","D":"No liability"},"correctOption":"C","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","B":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","D":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","C":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_637","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_637","question":"Yuki Tanaka is the single owner of a fitness gym in Dublin and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"The owner must publish detailed annual accounts publicly.","B":"The owner has unlimited liability for all the business debts.","C":"Its shares are freely traded on a stock exchange.","D":"The business has a separate legal identity from its owner."},"correctOption":"B","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","C":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","D":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","B":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_638","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_638","question":"Aisha Rahman and Samuel Mensah have set up a business together in Bogota, sharing the ownership, management and profits of a car rental firm. What type of business organisation have they created?","options":{"A":"A public limited company","B":"A partnership","C":"A sole trader business","D":"A franchise"},"correctOption":"B","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","C":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","D":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","B":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_639","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_639","question":"Sharma Electronics Ltd is a privately owned laptops company in Birmingham. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A sole trader","B":"A private limited company (Ltd)","C":"A partnership","D":"A public limited company (Plc)"},"correctOption":"B","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","C":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","D":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","B":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_640","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_640","question":"A large chocolate bars business in Lyon, Ferrari Bakery Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A partnership","B":"A private limited company (Ltd)","C":"A sole trader","D":"A public limited company (Plc)"},"correctOption":"D","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"A":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","C":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","D":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","B":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange."}}},{"id":"P1_U1_MCQ_641","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_641","question":"Fischer Furniture Ltd wants to increase the proportion of total sales in the canned tomatoes market in Accra that it captures for itself. Which objective is this?","options":{"A":"Cost minimisation","B":"Social enterprise","C":"Survival","D":"Increasing market share"},"correctOption":"D","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","B":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","C":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","D":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_642","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_642","question":"Boateng Packaging Ltd in Lyon reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Cost minimisation","B":"Profit maximisation","C":"Social enterprise objectives","D":"Market share"},"correctOption":"C","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","B":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","D":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_643","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_643","question":"Which stakeholder group is described here in relation to Larsen Plastics Ltd, a cement manufacturer in Melbourne? The people who have bought shares in the business and expect a return on their investment.","options":{"A":"Shareholders","B":"Customers","C":"Employees","D":"The local community"},"correctOption":"A","correctAnswer":"Shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns.","distractor_reasons":{"B":"Customers are the people who buy the firms products; the described stakeholders are not the purchasers of its output.","C":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","D":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","A":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns."}}},{"id":"P1_U1_MCQ_644","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_644","question":"At Boateng Auto Parts Ltd in Glasgow, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"The government seeking lower taxes conflicts with the local community seeking more jobs.","B":"Managers seeking faster growth conflict with customers seeking better quality.","C":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","D":"Customers seeking lower prices conflict with suppliers seeking higher prices."},"correctOption":"C","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","C":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","D":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","B":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality."}}},{"id":"P1_U1_MCQ_645","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_645","question":"A state-run healthcare provider in Cape Town is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to maximise returns for private shareholders.","B":"It mainly aims to provide a service to the community rather than maximise profit.","C":"It mainly aims to extract natural resources for export earnings.","D":"It mainly aims to increase its share of the global healthcare market."},"correctOption":"B","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","C":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","D":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","B":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_646","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_646","question":"Zahra Publishing Ltd sells 200 units of bicycles in Jakarta. Total sales of bicycles in the whole market are 400 units. What is the firms market share?","options":{"A":"60%","B":"20%","C":"50%","D":"40%"},"correctOption":"C","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (200/400) x 100 = 50%.","distractor_reasons":{"A":"60% is incorrect because it does not result from dividing the firms 200 units by the 400 total market units.","B":"20% is not the market share: dividing 200 by 400 and multiplying by 100 gives 50%, not 20%.","D":"40% is wrong; the correct calculation of firm sales over total market sales times 100 yields 50%.","C":"Option is correct because market share = (firm sales / total market sales) x 100 = (200/400) x 100 = 50%."}}},{"id":"P1_U1_MCQ_647","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_647","question":"Mwangi Foods Ltd, a LED bulbs firm in Birmingham, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Profit maximisation","B":"Market share","C":"Social enterprise","D":"Survival"},"correctOption":"A","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"B":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","C":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","D":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","A":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_648","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_648","question":"During a severe downturn in Lyon, Boateng Machinery Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Growth","B":"Market share","C":"Profit maximisation","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","B":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","C":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","D":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_649","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_649","question":"Fischer Beverages Ltd in Bogota has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Growth","B":"Survival","C":"Profit maximisation","D":"Social enterprise"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"B":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","C":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","D":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","A":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_650","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_650","question":"Ruiz Plastics Ltd wants to increase the proportion of total sales in the denim clothing market in Sydney that it captures for itself. Which objective is this?","options":{"A":"Survival","B":"Increasing market share","C":"Social enterprise","D":"Cost minimisation"},"correctOption":"B","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","C":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","D":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","B":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_651","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_651","question":"A pottery studio has a limited supply of clay and can produce either 20 handmade ceramic vases or 40 tea mugs. If the owner decides to make 20 ceramic vases, what is the opportunity cost of this choice?","options":{"A":"The 40 tea mugs that were not produced","B":"The total purchase cost of the raw clay used","C":"The sales revenue collected from selling the 20 ceramic vases","D":"The cost of gas used to fire the pottery kiln"},"correctOption":"A","correctAnswer":"The 40 tea mugs that were not produced","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost represents the next best alternative foregone, which is the 40 tea mugs.","distractor_reasons":{"A":"Option A is correct because opportunity cost represents the next best alternative foregone, which is the 40 tea mugs.","B":"Incorrect because raw clay expenditure is a direct monetary cost, not the sacrificed alternative.","C":"Incorrect because sales revenue is the outcome of the choice made.","D":"Incorrect because kiln gas cost is an operating expense."}}},{"id":"P1_U1_MCQ_652","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_652","question":"A toy maker purchases plastic resin for $4 and electronic chips for $6 per toy robot. The finished robot sells for $35. Which action directly increases the added value per toy robot by $8?","options":{"A":"Increasing weekly toy robot output from 100 to 300 units","B":"Adding a voice-activation feature and increasing the retail price to $43","C":"Reducing assembly line worker wages by $8 per shift","D":"Buying $8 worth of extra plastic resin to keep in inventory"},"correctOption":"B","correctAnswer":"Adding a voice-activation feature and increasing the retail price to $43","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because initial added value = $35 - $10 = $25. Raising price to $43 with constant material costs increases added value to $33 ($8 increase).","distractor_reasons":{"A":"Incorrect because increasing production volume affects total overall profit, not unit added value.","B":"Option B is correct because initial added value = $35 - $10 = $25. Raising price to $43 with constant material costs increases added value to $33 ($8 increase).","C":"Incorrect because worker wages are overhead expenses, not component material costs.","D":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value."}}},{"id":"P1_U1_MCQ_653","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_653","question":"A commercial bakery operates using flour, bakers, industrial baking ovens, and an innovative master baker. Which factor of production do the industrial baking ovens represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment, machinery, and facilities used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources.","B":"Incorrect because labour refers to the physical and mental work of bakers.","C":"Option C is correct because capital consists of man-made physical equipment, machinery, and facilities used in production.","D":"Incorrect because enterprise refers to the risk-taking managerial function."}}},{"id":"P1_U1_MCQ_654","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_654","question":"An automobile factory assigns a worker to perform only the single task of attaching door handles during an 8-hour shift. What is a key disadvantage of division of labor in this scenario?","options":{"A":"Workers require years of specialized university education to perform the task","B":"The component cost of door handles purchased from suppliers rises","C":"Overall factory assembly line speed decreases","D":"Monotonous task repetition can lead to worker boredom, low morale, and increased assembly defects"},"correctOption":"D","correctAnswer":"Monotonous task repetition can lead to worker boredom, low morale, and increased assembly defects","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one simple task leads to boredom, which can reduce worker engagement and cause quality errors.","distractor_reasons":{"A":"Incorrect because single repetitive tasks require minimal training.","B":"Incorrect because internal division of labor does not alter component purchase prices.","C":"Incorrect because specialization usually increases production efficiency and output speed.","D":"Option D is correct because repeating one simple task leads to boredom, which can reduce worker engagement and cause quality errors."}}},{"id":"P1_U1_MCQ_655","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_655","question":"Which item is classified as a fundamental human need necessary for basic survival?","options":{"A":"Adequate shelter and warmth","B":"A home theater sound system","C":"A high-end smartphone","D":"First-class air travel tickets"},"correctOption":"A","correctAnswer":"Adequate shelter and warmth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adequate shelter and warmth are fundamental biological requirements for survival.","distractor_reasons":{"A":"Option A is correct because adequate shelter and warmth are fundamental biological requirements for survival.","B":"Incorrect because home theater systems are entertainment wants.","C":"Incorrect because high-end smartphones are luxury communication wants.","D":"Incorrect because first-class air travel is a luxury transport want."}}},{"id":"P1_U1_MCQ_656","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_656","question":"What is the primary cause of the economic problem of scarcity?","options":{"A":"Commercial banks refusing to issue business loans","B":"Excessive business taxes reducing corporate profits","C":"High import tariffs imposed by foreign governments","D":"Unlimited consumer wants exceeding the limited economic resources available"},"correctOption":"D","correctAnswer":"Unlimited consumer wants exceeding the limited economic resources available","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because scarcity is caused by infinite human wants confronting finite productive resources.","distractor_reasons":{"A":"Incorrect because credit policy does not cause fundamental resource scarcity.","B":"Incorrect because business tax rates do not alter the fundamental existence of resource scarcity.","C":"Incorrect because import tariffs are trade policy measures.","D":"Option D is correct because scarcity is caused by infinite human wants confronting finite productive resources."}}},{"id":"P1_U1_MCQ_657","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_657","question":"A manufacturer buys steel for $40 and plastic trim for $10 per lawnmower. The finished lawnmower is sold for $220. What is the added value per lawnmower?","options":{"A":"$50","B":"$180","C":"$170","D":"$220"},"correctOption":"C","correctAnswer":"$170","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs = $40 + $10 = $50. Added value = selling price ($220) - material costs ($50) = $170.","distractor_reasons":{"A":"Incorrect because $50 is the total bought-in material cost.","B":"Incorrect because $180 subtracts only the steel cost ($220 - $40), ignoring plastic trim.","C":"Option C is correct because total bought-in material costs = $40 + $10 = $50. Added value = selling price ($220) - material costs ($50) = $170.","D":"Incorrect because $220 is the final selling price."}}},{"id":"P1_U1_MCQ_658","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_658","question":"A chef resigns from a restaurant job earning $50,000 per year to start a catering business. What is the opportunity cost of launching this new business?","options":{"A":"The annual rent for the commercial kitchen facility","B":"The revenue earned from catering events during Year 1","C":"The money spent purchasing cooking appliances","D":"The $50,000 salary foregone from the previous restaurant position"},"correctOption":"D","correctAnswer":"The $50,000 salary foregone from the previous restaurant position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $50,000 salary.","distractor_reasons":{"A":"Incorrect because kitchen rent is an explicit operational cost.","B":"Incorrect because event revenue is the benefit of the chosen decision.","C":"Incorrect because cooking equipment is capital expenditure.","D":"Option D is correct because opportunity cost measures the sacrificed benefit of the next best alternative given up, which is the $50,000 salary."}}},{"id":"P1_U1_MCQ_659","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_659","question":"Which factor of production includes natural gifts such as crude oil deposits, fertile soil, and timber forests?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in economic activity.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in economic activity.","B":"Incorrect because labour represents human work effort.","C":"Incorrect because capital represents man-made equipment and facilities.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_660","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_660","question":"How can a jewelry maker directly increase the added value of its products without increasing final retail prices?","options":{"A":"Increasing spending on television commercials","B":"Increasing hourly wages paid to bench jewellers","C":"Negotiating lower component costs for silver chains from suppliers","D":"Renting a larger boutique store in a high-rent city district"},"correctOption":"C","correctAnswer":"Negotiating lower component costs for silver chains from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because added value equals selling price minus bought-in material costs. Negotiating lower component costs widens this difference.","distractor_reasons":{"A":"Incorrect because advertising is an operating expense.","B":"Incorrect because higher worker wages increase operating expenses, lowering profit margin rather than unit added value.","C":"Option C is correct because added value equals selling price minus bought-in material costs. Negotiating lower component costs widens this difference.","D":"Incorrect because boutique rent increases overhead costs."}}},{"id":"P1_U1_MCQ_661","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_661","question":"Which sector of the economy does this activity belong to? A privately owned factory in Seoul turns raw materials into bottled water.","options":{"A":"Primary sector","B":"Secondary sector","C":"Public sector","D":"Tertiary sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it.","distractor_reasons":{"A":"The primary sector involves extracting natural resources and farming; the described activity is not extraction or farming.","C":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","D":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","B":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it."}}},{"id":"P1_U1_MCQ_662","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_662","question":"What structural shift occurs during deindustrialization in a developed country?","options":{"A":"Workforce shifts from financial technology into coal mining","B":"The central government takes ownership of all private manufacturing plants","C":"Manufacturing output grows rapidly while service industry revenue contracts","D":"Secondary sector manufacturing declines relative to the expansion of tertiary sector services"},"correctOption":"D","correctAnswer":"Secondary sector manufacturing declines relative to the expansion of tertiary sector services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion in tertiary service industries.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not grow during deindustrialization.","B":"Incorrect because deindustrialization concerns sector composition, not state ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion in tertiary service industries."}}},{"id":"P1_U1_MCQ_663","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_663","question":"Which entity operates within the public sector of a mixed economy?","options":{"A":"A state-owned national railway corporation managed by government ministers","B":"A commercial logistics company owned by two partners","C":"A freight airline listed on the national stock market","D":"An independent truck driver operating as a sole trader"},"correctOption":"A","correctAnswer":"A state-owned national railway corporation managed by government ministers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because state-owned railway corporations are public sector entities owned and controlled by government bodies.","distractor_reasons":{"A":"Option A is correct because state-owned railway corporations are public sector entities owned and controlled by government bodies.","B":"Incorrect because partner-owned logistics firms belong to the private sector.","C":"Incorrect because stock market listed airlines belong to the private sector.","D":"Incorrect because sole traders belong to the private sector."}}},{"id":"P1_U1_MCQ_664","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_664","question":"A forestry business harvests logs, a sawmill processes logs into timber boards, and a construction company uses timber boards to build houses. How are these three businesses classified?","options":{"A":"Forestry: Secondary; Sawmill: Primary; Construction: Tertiary","B":"Forestry: Primary; Sawmill: Secondary; Construction: Secondary","C":"Forestry: Primary; Sawmill: Tertiary; Construction: Secondary","D":"Forestry: Tertiary; Sawmill: Secondary; Construction: Primary"},"correctOption":"B","correctAnswer":"Forestry: Primary; Sawmill: Secondary; Construction: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting logs is primary extraction, while processing logs at a sawmill and constructing houses both involve manufacturing/construction (secondary sector).","distractor_reasons":{"A":"Incorrect because harvesting timber is primary, not secondary.","B":"Option B is correct because harvesting logs is primary extraction, while processing logs at a sawmill and constructing houses both involve manufacturing/construction (secondary sector).","C":"Incorrect because a sawmill is secondary processing, not tertiary service.","D":"Incorrect because sector order is incorrect."}}},{"id":"P1_U1_MCQ_665","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_665","question":"Over the past decade the economy around Mumbai has moved workers out of farming and into new factories producing bottled water, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Industrialisation","B":"Privatisation","C":"Specialisation","D":"Deindustrialisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"B":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","C":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","D":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","A":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_666","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_666","question":"Which activity is part of the tertiary economic sector?","options":{"A":"Iron ore extraction","B":"Steel manufacturing","C":"Cotton growing","D":"Retail banking services"},"correctOption":"D","correctAnswer":"Retail banking services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retail banking provides a financial service, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because iron ore extraction is primary.","B":"Incorrect because steel manufacturing is secondary.","C":"Incorrect because cotton growing is primary.","D":"Option D is correct because retail banking provides a financial service, placing it in the tertiary sector."}}},{"id":"P1_U1_MCQ_667","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_667","question":"In Leeds, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Division of labour","B":"Industrialisation","C":"Primary sector growth","D":"Deindustrialisation"},"correctOption":"D","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","B":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","C":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","D":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_668","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_668","question":"Why might a government choose to privatize a state-owned water utility company?","options":{"A":"To turn water utility staff into civil service employees","B":"To introduce market competition, private capital, and operational efficiency","C":"To restrict private capital investment in water infrastructure","D":"To increase direct state control over consumer water rates"},"correctOption":"B","correctAnswer":"To introduce market competition, private capital, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, introducing profit motives and competition that improve efficiency.","distractor_reasons":{"A":"Incorrect because privatized employees lose civil servant status.","B":"Option B is correct because privatization transfers state assets to private owners, introducing profit motives and competition that improve efficiency.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_669","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_669","question":"A group of private investors owns and operates a parcel delivery service in Seoul with the aim of earning a profit. Which sector of the economy does this organisation belong to?","options":{"A":"Secondary sector","B":"Primary sector","C":"Private sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Private sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector.","distractor_reasons":{"A":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","B":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","D":"The public sector consists of organisations owned and controlled by the government; this business is not government-owned.","C":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector."}}},{"id":"P1_U1_MCQ_670","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_670","question":"What structural employment change typically occurs as a developing country undergoes rapid industrialization?","options":{"A":"Employment shifts out of manufacturing into primary farming","B":"Service businesses close down completely to focus on mining","C":"Public sector departments nationalize all private retail stores","D":"Employment shifts out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Employment shifts out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves into manufacturing during industrialization, not out of it.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture."}}},{"id":"P1_U1_MCQ_671","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_671","question":"Which characteristic is essential for an entrepreneur setting up a new business?","options":{"A":"Self-drive, risk-taking ability, and resilience when encountering obstacles","B":"Preference for taking direct instructions from senior corporate managers","C":"Unwillingness to change operational methods when consumer tastes evolve","D":"Avoidance of financial responsibility for setup costs"},"correctOption":"A","correctAnswer":"Self-drive, risk-taking ability, and resilience when encountering obstacles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require initiative, willingness to accept financial risk, and resilience to handle early business difficulties.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require initiative, willingness to accept financial risk, and resilience to handle early business difficulties.","B":"Incorrect because entrepreneurs lead independent ventures.","C":"Incorrect because adaptability is crucial for business survival.","D":"Incorrect because entrepreneurs take on financial responsibility."}}},{"id":"P1_U1_MCQ_672","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_672","question":"Anika Singh noticed a gap in the local market in Seoul, invested personal savings, took the financial risk and set up a new business making smartphones. Which role is Anika carrying out?","options":{"A":"A shareholder only","B":"An entrepreneur","C":"A trade union official","D":"An employee"},"correctOption":"B","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","C":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","D":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","B":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_673","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_673","question":"Samuel Mensah wants to start a chain of coffee shops in Bogota and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A delivery note","B":"A statement of profit or loss","C":"A business plan","D":"An organisation chart"},"correctOption":"C","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"A":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","B":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","D":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","C":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_674","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_674","question":"A government wants to encourage more people in Dar es Salaam to set up small businesses making textbooks. Which of the following is an example of government support for new business start-ups?","options":{"A":"Introducing stricter rules that make it harder to register a new firm.","B":"Removing all forms of business advice and training for new owners.","C":"Offering low-interest start-up loans and grant funding to new firms.","D":"Raising the rate of corporation tax on all company profits."},"correctOption":"C","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"A":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","B":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","D":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","C":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_675","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_675","question":"Why do national governments offer advisory support and financial grants to newly established small businesses?","options":{"A":"To create employment, foster innovation, and promote economic growth","B":"To eliminate market competition for state-owned monopolies","C":"To force small businesses to convert into public limited companies","D":"To restrict foreign commercial enterprises from importing goods"},"correctOption":"A","correctAnswer":"To create employment, foster innovation, and promote economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because supporting new business startups helps lower unemployment, foster innovation, and increase national output.","distractor_reasons":{"A":"Option A is correct because supporting new business startups helps lower unemployment, foster innovation, and increase national output.","B":"Incorrect because government grants promote competition rather than eliminate it.","C":"Incorrect because grants do not force changes in legal ownership structures.","D":"Incorrect because startup grants focus on domestic business creation, not import barriers."}}},{"id":"P1_U1_MCQ_676","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_676","question":"Okafor Glassware Ltd is a ceramic tiles business in Lisbon with 75 employees and annual sales revenue of $12m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The profit margin and the current ratio.","B":"The share price and the dividend yield.","C":"The number of employees and the annual sales turnover.","D":"The brand image and the quality of its products."},"correctOption":"C","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"A":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","B":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","D":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","C":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_677","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_677","question":"Over five years Kowalski Furniture Ltd expanded its bicycles business in Dar es Salaam by reinvesting its own profits to open 6 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Horizontal integration","C":"Internal (organic) growth","D":"Forward vertical integration"},"correctOption":"C","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","C":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","D":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","B":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here."}}},{"id":"P1_U1_MCQ_678","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_678","question":"Why might the owner of a local bookstore prefer to remain small rather than expand into a national retail chain?","options":{"A":"Small bookstores are exempt from paying publisher bills","B":"National bookstore chains are legally prohibited by government","C":"Expanding the business automatically revokes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct operational control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct operational control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because national bookstore chains operate legally.","C":"Incorrect because business expansion does not cancel limited liability.","D":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact."}}},{"id":"P1_U1_MCQ_679","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_679","question":"Hassan Plastics Ltd, a canned tomatoes manufacturer in Sao Paulo, has taken over a rival firm that makes the same canned tomatoes at the same stage of production. What type of integration is this?","options":{"A":"Horizontal integration","B":"Internal growth","C":"Forward vertical integration","D":"Backward vertical integration"},"correctOption":"A","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"B":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","C":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","D":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","A":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_680","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_680","question":"A kitchen utensils manufacturer in Toronto, Patel Machinery Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"B","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","C":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain.","D":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","B":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain."}}},{"id":"P1_U1_MCQ_681","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_681","question":"What does unlimited liability mean for a sole trader running a catering business?","options":{"A":"The business owner's financial risk is strictly capped at invested capital.","B":"The business can issue public shares on national stock exchanges.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay off supplier debts if the business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","distractor_reasons":{"A":"Incorrect because limiting liability to invested capital describes limited companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_682","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_682","question":"Noah Williams pays an upfront fee and regular royalties to a well-known smartphones brand for the right to trade under its name in Bristol and follow its established business system. What is this arrangement called?","options":{"A":"A franchise","B":"A takeover","C":"A joint venture","D":"A public corporation"},"correctOption":"A","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"B":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","C":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand.","D":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","A":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model."}}},{"id":"P1_U1_MCQ_683","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_683","question":"An entrepreneur buys a franchise license to operate a branded fast-food restaurant. What is a primary drawback faced by this franchisee?","options":{"A":"Inability to receive staff training or operational support from the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to alter recipes and branding without corporate approval","D":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor"},"correctOption":"D","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","distractor_reasons":{"A":"Incorrect because franchisors provide training and operational support.","B":"Incorrect because established franchises offer strong brand recognition.","C":"Incorrect because franchisees must strictly comply with franchisor operational rules.","D":"Option D is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins."}}},{"id":"P1_U1_MCQ_684","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_684","question":"Two technology firms form a joint venture to manufacture solar panels. What is a primary benefit of this setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing high research costs, operational risks, and technical expertise","C":"Complete exemption from paying national corporate taxes","D":"Total elimination of management disagreements between executive teams"},"correctOption":"B","correctAnswer":"Sharing high research costs, operational risks, and technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_685","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_685","question":"Two separate firms in Cairo agree to create a new jointly owned business to develop a new canned tomatoes, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A franchise","C":"A merger","D":"A joint venture"},"correctOption":"D","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","B":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","C":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","D":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_686","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_686","question":"An organisation in Lagos is owned by the government but operates as a separate business providing an online tuition service to the public. What type of organisation is it?","options":{"A":"A public corporation","B":"A public limited company","C":"A sole trader","D":"A partnership"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"B":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","C":"A sole trader is owned by one private individual with unlimited liability, not by the government.","D":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","A":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_687","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_687","question":"Lucia Ferrari owns a business in Warsaw. The business incurs debts it cannot repay, and Lucias personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"Limited liability","B":"Shared liability","C":"No liability","D":"Unlimited liability"},"correctOption":"D","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","B":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","C":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","D":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_688","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_688","question":"Omar Haddad is the single owner of a car rental firm in Lyon and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"Its shares are freely traded on a stock exchange.","B":"The owner must publish detailed annual accounts publicly.","C":"The business has a separate legal identity from its owner.","D":"The owner has unlimited liability for all the business debts."},"correctOption":"D","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","B":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","C":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","D":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_689","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_689","question":"Hassan Farouk and Carlos Mendez have set up a business together in Nairobi, sharing the ownership, management and profits of a chain of hair salons. What type of business organisation have they created?","options":{"A":"A public limited company","B":"A sole trader business","C":"A franchise","D":"A partnership"},"correctOption":"D","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","B":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","C":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","D":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_690","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_690","question":"Adeyemi Electronics Ltd is a privately owned textbooks company in Leeds. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A partnership","B":"A public limited company (Plc)","C":"A private limited company (Ltd)","D":"A sole trader"},"correctOption":"C","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","B":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","D":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","C":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_691","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_691","question":"Mensah Textiles Ltd in Birmingham reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Profit maximisation","B":"Market share","C":"Cost minimisation","D":"Social enterprise objectives"},"correctOption":"D","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","B":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","D":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_692","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_692","question":"Which stakeholder group is described here in relation to Adeyemi Glassware Ltd, a ceramic tiles manufacturer in Accra? The firms customers who buy its products and depend on their quality.","options":{"A":"Employees","B":"Shareholders","C":"The local community","D":"Customers"},"correctOption":"D","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price.","distractor_reasons":{"A":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","B":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","C":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","D":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price."}}},{"id":"P1_U1_MCQ_693","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_693","question":"At Johnson Publishing Ltd in Dubai, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Customers seeking lower prices conflict with suppliers seeking higher prices.","B":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","C":"Managers seeking faster growth conflict with customers seeking better quality.","D":"The government seeking lower taxes conflicts with the local community seeking more jobs."},"correctOption":"B","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","C":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","D":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","B":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_694","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_694","question":"A state-run healthcare provider in Dar es Salaam is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to maximise returns for private shareholders.","B":"It mainly aims to increase its share of the global healthcare market.","C":"It mainly aims to extract natural resources for export earnings.","D":"It mainly aims to provide a service to the community rather than maximise profit."},"correctOption":"D","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","B":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","C":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","D":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_695","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_695","question":"Mwangi Pharmaceuticals Ltd sells 1,500 units of denim clothing in Johannesburg. Total sales of denim clothing in the whole market are 2,000 units. What is the firms market share?","options":{"A":"75%","B":"40%","C":"10%","D":"60%"},"correctOption":"A","correctAnswer":"75%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (1,500/2,000) x 100 = 75%.","distractor_reasons":{"B":"40% is wrong; the correct calculation of firm sales over total market sales times 100 yields 75%.","C":"10% is incorrect because it does not result from dividing the firms 1,500 units by the 2,000 total market units.","D":"60% is not the market share: dividing 1,500 by 2,000 and multiplying by 100 gives 75%, not 60%.","A":"Option is correct because market share = (firm sales / total market sales) x 100 = (1,500/2,000) x 100 = 75%."}}},{"id":"P1_U1_MCQ_696","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_696","question":"Patel Auto Parts Ltd, a school backpacks firm in Sydney, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Market share","B":"Social enterprise","C":"Survival","D":"Profit maximisation"},"correctOption":"D","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","B":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","C":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","D":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_697","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_697","question":"During a severe downturn in Nairobi, Costa Publishing Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Survival","B":"Growth","C":"Profit maximisation","D":"Market share"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"B":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","C":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","D":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","A":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_698","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_698","question":"Wanjiku Foods Ltd in Bogota has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Survival","B":"Profit maximisation","C":"Social enterprise","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"A":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","B":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","C":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","D":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_699","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_699","question":"Kowalski Pharmaceuticals Ltd wants to increase the proportion of total sales in the ceramic tiles market in Hanoi that it captures for itself. Which objective is this?","options":{"A":"Increasing market share","B":"Survival","C":"Cost minimisation","D":"Social enterprise"},"correctOption":"A","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"B":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","C":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","D":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","A":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_700","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_700","question":"Nasser Machinery Ltd in Leeds reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Market share","B":"Profit maximisation","C":"Cost minimisation","D":"Social enterprise objectives"},"correctOption":"D","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","B":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","C":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","D":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_701","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_701","question":"A shoe manufacturer has enough leather to produce either 100 pairs of boots or 150 pairs of sneakers. If the firm chooses to manufacture 100 pairs of boots, what is the opportunity cost of this decision?","options":{"A":"The 150 pairs of sneakers foregone","B":"The total cost of purchasing raw leather hides","C":"The sales revenue collected from selling 100 pairs of boots","D":"The electricity cost of operating shoe stitching machinery"},"correctOption":"A","correctAnswer":"The 150 pairs of sneakers foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative given up when making an economic choice, which is the 150 pairs of sneakers.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative given up when making an economic choice, which is the 150 pairs of sneakers.","B":"Incorrect because leather purchase cost is a direct financial outlay.","C":"Incorrect because sales revenue is the return from the selected choice.","D":"Incorrect because electricity cost is an operating expense."}}},{"id":"P1_U1_MCQ_702","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_702","question":"A handbag maker buys raw canvas for $12 and metal zippers for $3 per tote bag. The completed bag sells for $50. Which business decision directly increases the added value per tote bag by $6?","options":{"A":"Increasing daily output of tote bags from 50 to 100 units","B":"Reducing stitcher hourly wages by $6 per shift","C":"Adding custom embroidery and increasing the retail price to $56","D":"Purchasing $6 worth of extra canvas to hold in stock"},"correctOption":"C","correctAnswer":"Adding custom embroidery and increasing the retail price to $56","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because added value = selling price ($50) - material costs ($15) = $35. Increasing price to $56 with constant material costs raises added value to $41 ($6 increase).","distractor_reasons":{"A":"Incorrect because increasing volume alters total business profit, not unit added value.","B":"Incorrect because worker wages are operating overheads, not bought-in material costs.","C":"Option C is correct because added value = selling price ($50) - material costs ($15) = $35. Increasing price to $56 with constant material costs raises added value to $41 ($6 increase).","D":"Incorrect because holding extra inventory increases stock assets without affecting unit added value."}}},{"id":"P1_U1_MCQ_703","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_703","question":"A commercial vineyard utilizes fertile land, grape pickers, automated pressing machinery, and an ambitious vineyard director. Which factor of production does the automated pressing machinery represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made tools, equipment, and machinery used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like vineyard soil.","B":"Incorrect because labour refers to the effort of grape pickers.","C":"Option C is correct because capital consists of man-made tools, equipment, and machinery used in production.","D":"Incorrect because enterprise refers to the risk-taking role of the director."}}},{"id":"P1_U1_MCQ_704","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_704","question":"A food processing factory assigns a worker to perform only the single task of labeling tin cans for 8 hours a day. What is a key disadvantage of division of labor in this workplace?","options":{"A":"The task requires long, costly university training for each employee","B":"The component cost of tin labels bought from suppliers increases","C":"Overall factory production speed drops significantly","D":"Repetitive execution of a single task causes boredom, lower motivation, and careless mistakes"},"correctOption":"D","correctAnswer":"Repetitive execution of a single task causes boredom, lower motivation, and careless mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extreme specialization in monotonous tasks causes worker boredom, reducing morale and accuracy.","distractor_reasons":{"A":"Incorrect because single narrow tasks require minimal training.","B":"Incorrect because internal task division does not affect supplier component costs.","C":"Incorrect because specialization typically speeds up workflow.","D":"Option D is correct because extreme specialization in monotonous tasks causes worker boredom, reducing morale and accuracy."}}},{"id":"P1_U1_MCQ_705","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_705","question":"Which item represents a fundamental human need essential for maintaining life?","options":{"A":"Designer fashion wristwatches","B":"A subscription to a movie streaming platform","C":"A luxury electric sports car","D":"Clean drinking water and essential food"},"correctOption":"D","correctAnswer":"Clean drinking water and essential food","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because water and basic food are physiological necessities for human survival.","distractor_reasons":{"A":"Incorrect because designer wristwatches are fashion wants.","B":"Incorrect because streaming subscriptions are entertainment wants.","C":"Incorrect because sports cars are luxury wants.","D":"Option D is correct because water and basic food are physiological necessities for human survival."}}},{"id":"P1_U1_MCQ_706","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_706","question":"Why does economic scarcity exist across all human societies?","options":{"A":"Central authorities impose strict production caps on consumer products","B":"Unlimited human wants exceed the finite economic resources available to satisfy them","C":"Private companies refuse to recruit available unemployed workers","D":"High commercial interest rates discourage corporate investment"},"correctOption":"B","correctAnswer":"Unlimited human wants exceed the finite economic resources available to satisfy them","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because scarcity is the fundamental economic problem where infinite wants clash with finite resources.","distractor_reasons":{"A":"Incorrect because production caps are regulatory actions, not the root cause of scarcity.","B":"Option B is correct because scarcity is the fundamental economic problem where infinite wants clash with finite resources.","C":"Incorrect because private hiring decisions do not create basic resource scarcity.","D":"Incorrect because interest rates affect investment, not the fundamental existence of economic scarcity."}}},{"id":"P1_U1_MCQ_707","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_707","question":"A bicycle manufacturer buys steel tubes for $45 and tires for $15 per unit. The finished bicycle is sold for $250. What is the added value per bicycle?","options":{"A":"$60","B":"$205","C":"$190","D":"$250"},"correctOption":"C","correctAnswer":"$190","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total material cost = $45 + $15 = $60. Added value = selling price ($250) - material costs ($60) = $190.","distractor_reasons":{"A":"Incorrect because $60 is the total bought-in material cost.","B":"Incorrect because $205 subtracts only the steel cost ($250 - $45), ignoring tires.","C":"Option C is correct because total material cost = $45 + $15 = $60. Added value = selling price ($250) - material costs ($60) = $190.","D":"Incorrect because $250 is the total selling price."}}},{"id":"P1_U1_MCQ_708","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_708","question":"A web designer leaves a salaried position earning $55,000 per year to launch a freelance web agency. What is the opportunity cost of starting this new venture?","options":{"A":"The annual rental fee for office space","B":"The total revenue billed to clients in the first year","C":"The capital spent purchasing computer hardware","D":"The $55,000 salary foregone from the previous employment"},"correctOption":"D","correctAnswer":"The $55,000 salary foregone from the previous employment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost is the foregone return of the next best alternative, which is the $55,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is a direct cash expense.","B":"Incorrect because client billing is revenue from the new decision.","C":"Incorrect because hardware purchases are capital expenditures.","D":"Option D is correct because opportunity cost is the foregone return of the next best alternative, which is the $55,000 salary."}}},{"id":"P1_U1_MCQ_709","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_709","question":"Which factor of production includes natural assets such as gold reserves, natural gas, and uncultivated land?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural unrefined resources provided by the environment.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural unrefined resources provided by the environment.","B":"Incorrect because labour refers to human physical and mental work.","C":"Incorrect because capital refers to man-made equipment and infrastructure.","D":"Incorrect because enterprise is the risk-taking managerial function."}}},{"id":"P1_U1_MCQ_710","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_710","question":"How can a watchmaker directly increase the added value of its timepieces without increasing final retail prices?","options":{"A":"Increasing monthly spending on magazine advertisements","B":"Negotiating lower component costs for leather straps from suppliers","C":"Increasing hourly wage rates paid to assembly line technicians","D":"Renting a larger distribution warehouse facility"},"correctOption":"B","correctAnswer":"Negotiating lower component costs for leather straps from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering material costs widens added value.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering material costs widens added value.","C":"Incorrect because higher labor wages increase operational costs, reducing profit margin rather than unit added value.","D":"Incorrect because warehouse rent increases overhead expenses."}}},{"id":"P1_U1_MCQ_711","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_711","question":"Which business activity belongs to the primary sector of an economy?","options":{"A":"Processing raw bauxite into aluminum ingots","B":"Providing legal advice to corporate clients","C":"Catching wild fish on ocean trawlers","D":"Operating a chain of retail seafood markets"},"correctOption":"C","correctAnswer":"Catching wild fish on ocean trawlers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because catching wild fish involves direct extraction of natural resources from the environment (primary sector).","distractor_reasons":{"A":"Incorrect because processing bauxite is secondary sector manufacturing.","B":"Incorrect because legal advice is a tertiary professional service.","C":"Option C is correct because catching wild fish involves direct extraction of natural resources from the environment (primary sector).","D":"Incorrect because operating seafood markets is a tertiary retail service."}}},{"id":"P1_U1_MCQ_712","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_712","question":"What structural employment change defines deindustrialization in an economy?","options":{"A":"Workers shift out of software engineering into copper mining","B":"The central government takes ownership of all private manufacturing plants","C":"Manufacturing output expands while service sector employment drops","D":"Employment declines in secondary manufacturing and expands in tertiary services"},"correctOption":"D","correctAnswer":"Employment declines in secondary manufacturing and expands in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization refers to the relative decline of secondary manufacturing and growth of tertiary services in an economy.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not grow during deindustrialization.","B":"Incorrect because deindustrialization relates to sector proportions, not ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization refers to the relative decline of secondary manufacturing and growth of tertiary services in an economy."}}},{"id":"P1_U1_MCQ_713","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_713","question":"In Nairobi, 20% of workers are employed in the primary sector, 15% in the secondary sector and 55% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Public sector","B":"Secondary sector","C":"Tertiary sector","D":"Primary sector"},"correctOption":"C","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"The tertiary sector employs 55% of workers, the largest share of the three sectors, so it employs the most workers.","distractor_reasons":{"A":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","B":"The secondary sector employs 15% of workers, which is lower than the largest share of 55%, so it does not employ the most workers.","D":"The primary sector employs 20% of workers, which is lower than the largest share of 55%, so it does not employ the most workers.","C":"The tertiary sector employs 55% of workers, the largest share of the three sectors, so it employs the most workers."}}},{"id":"P1_U1_MCQ_714","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_714","question":"A mining business extracts crude salt, a chemical factory refines the salt into industrial chlorine, and a plastic maker uses chlorine to produce PVC pipes. How are these three firms classified?","options":{"A":"Mining: Secondary; Chemical factory: Primary; Plastic maker: Tertiary","B":"Mining: Tertiary; Chemical factory: Secondary; Plastic maker: Primary","C":"Mining: Primary; Chemical factory: Tertiary; Plastic maker: Secondary","D":"Mining: Primary; Chemical factory: Secondary; Plastic maker: Secondary"},"correctOption":"D","correctAnswer":"Mining: Primary; Chemical factory: Secondary; Plastic maker: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because salt mining is primary extraction, while refining chemicals and manufacturing plastic pipes both transform raw materials into manufactured products (secondary sector).","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Incorrect because sector order is incorrect.","C":"Incorrect because a chemical refining factory is secondary manufacturing, not tertiary service.","D":"Option D is correct because salt mining is primary extraction, while refining chemicals and manufacturing plastic pipes both transform raw materials into manufactured products (secondary sector)."}}},{"id":"P1_U1_MCQ_715","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_715","question":"A state-owned organisation in Bristol provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To increase the wealth of the governments individual ministers.","B":"To provide a service to the community rather than to maximise profit.","C":"To extract and sell as many natural resources as possible.","D":"To maximise profit for its private shareholders."},"correctOption":"B","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"A":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","C":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","D":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","B":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_716","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_716","question":"Which sector of the economy does this activity belong to? Anika Singh owns a farm in Cairo and harvests sugar cane for sale.","options":{"A":"Secondary sector","B":"Tertiary sector","C":"Primary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it.","distractor_reasons":{"A":"The secondary sector involves manufacturing and construction; the described activity is not the processing of materials into goods.","B":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","D":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","C":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it."}}},{"id":"P1_U1_MCQ_717","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_717","question":"Over the past decade the economy around Jakarta has moved workers out of farming and into new factories producing denim clothing, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Privatisation","B":"Industrialisation","C":"Deindustrialisation","D":"Specialisation"},"correctOption":"B","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"A":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","C":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","D":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","B":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_718","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_718","question":"Why might a state government choose to privatize a national postal service?","options":{"A":"To turn postal workers into civil service employees","B":"To introduce profit incentives, private investment capital, and market competition to boost efficiency","C":"To restrict private capital investment in logistics infrastructure","D":"To increase direct government control over stamp pricing"},"correctOption":"B","correctAnswer":"To introduce profit incentives, private investment capital, and market competition to boost efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, introducing market forces that drive efficiency and innovation.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Option B is correct because privatization transfers state assets to private owners, introducing market forces that drive efficiency and innovation.","C":"Incorrect because privatization encourages private investment.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_719","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_719","question":"In Shanghai, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Industrialisation","B":"Primary sector growth","C":"Division of labour","D":"Deindustrialisation"},"correctOption":"D","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","B":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","C":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","D":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_720","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_720","question":"What structural employment shift generally occurs as an economy experiences rapid industrialization?","options":{"A":"Workers leave factory work to take up primary crop farming","B":"Commercial service firms close down completely to prioritize mining","C":"Public sector departments nationalize all private retail stores","D":"Labor moves out of primary agriculture into secondary manufacturing"},"correctOption":"D","correctAnswer":"Labor moves out of primary agriculture into secondary manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization expands secondary manufacturing, drawing labor away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves into manufacturing during industrialization, not out of it.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization expands secondary manufacturing, drawing labor away from primary agriculture."}}},{"id":"P1_U1_MCQ_721","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_721","question":"Which personal quality is crucial for an entrepreneur launching a new startup venture?","options":{"A":"Self-motivation, willingness to accept financial risk, and resilience when encountering difficulties","B":"Preference for taking direct operational instructions from corporate managers","C":"Reluctance to adapt business operations when market demand shifts","D":"Avoidance of personal financial liability for startup debts"},"correctOption":"A","correctAnswer":"Self-motivation, willingness to accept financial risk, and resilience when encountering difficulties","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because successful entrepreneurs need drive, risk tolerance, and resilience against failure.","distractor_reasons":{"A":"Option A is correct because successful entrepreneurs need drive, risk tolerance, and resilience against failure.","B":"Incorrect because entrepreneurs lead independent ventures.","C":"Incorrect because adaptability is crucial for business survival.","D":"Incorrect because entrepreneurs take on financial responsibility."}}},{"id":"P1_U1_MCQ_722","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_722","question":"Why is preparing a comprehensive business plan essential when a new firm seeks a bank loan?","options":{"A":"It automatically grants the company limited liability status without legal incorporation","B":"It presents financial projections proving the firm's ability to service interest and repay principal","C":"It guarantees that the startup will make a profit in its first year","D":"It replaces statutory tax filing obligations enforced by government"},"correctOption":"B","correctAnswer":"It presents financial projections proving the firm's ability to service interest and repay principal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank lenders evaluate financial forecasts in a business plan to assess default risk and repayment capacity.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","B":"Option B is correct because bank lenders evaluate financial forecasts in a business plan to assess default risk and repayment capacity.","C":"Incorrect because business plans present projections, not profit guarantees.","D":"Incorrect because tax filing is a legal requirement separate from planning."}}},{"id":"P1_U1_MCQ_723","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_723","question":"Okafor Auto Parts Ltd, a ceramic tiles producer in Lisbon, has purchased a component maker that previously supplied its raw materials. What type of integration is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Internal growth","D":"Horizontal integration"},"correctOption":"B","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"A":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","C":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","D":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","B":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_724","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_724","question":"After a period of very rapid expansion, Bauer Glassware Ltd in Sao Paulo found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing furniture business. Which problem of growth does this illustrate?","options":{"A":"A reduction in the number of competitors in the market.","B":"Loss of control and coordination difficulties as the business becomes larger.","C":"Lower average costs from economies of scale.","D":"Higher staff morale throughout the workforce."},"correctOption":"B","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","C":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","D":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","B":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_725","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_725","question":"Farouk Machinery Ltd, a denim clothing firm in Dublin, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"A shortage of customer demand for its products.","B":"Over-regulation of the market by the government.","C":"Cash flow problems, leaving it unable to pay debts as they fell due.","D":"Excessive profitability that attracted too much competition."},"correctOption":"C","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"A":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","B":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","D":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","C":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_726","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_726","question":"Samuel Mensah noticed a gap in the local market in Lyon, invested personal savings, took the financial risk and set up a new business making canned tomatoes. Which role is Samuel carrying out?","options":{"A":"A trade union official","B":"A shareholder only","C":"An entrepreneur","D":"An employee"},"correctOption":"C","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","B":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","D":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","C":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_727","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_727","question":"Sofia Rossi wants to start a landscape gardening business in Sao Paulo and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A business plan","B":"A delivery note","C":"An organisation chart","D":"A statement of profit or loss"},"correctOption":"A","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"B":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","C":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","D":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","A":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_728","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_728","question":"Why might the owner of a local coffee shop prefer to remain small rather than expand into a regional coffee chain?","options":{"A":"Small coffee shops are exempt from paying supplier bills","B":"Regional coffee chains are legally prohibited by government","C":"Expanding the business automatically revokes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct operational control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct operational control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because regional coffee chains operate legally.","C":"Incorrect because business expansion does not cancel limited liability.","D":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact."}}},{"id":"P1_U1_MCQ_729","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_729","question":"A government wants to encourage more people in Cape Town to set up small businesses making smartphones. Which of the following is an example of government support for new business start-ups?","options":{"A":"Offering low-interest start-up loans and grant funding to new firms.","B":"Raising the rate of corporation tax on all company profits.","C":"Removing all forms of business advice and training for new owners.","D":"Introducing stricter rules that make it harder to register a new firm."},"correctOption":"A","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"B":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","C":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","D":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","A":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_730","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_730","question":"Singh Bakery Ltd is a LED bulbs business in Toronto with 35 employees and annual sales revenue of $12m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The profit margin and the current ratio.","B":"The number of employees and the annual sales turnover.","C":"The brand image and the quality of its products.","D":"The share price and the dividend yield."},"correctOption":"B","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"A":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","C":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","D":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","B":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_731","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_731","question":"What does unlimited liability mean for a sole trader operating a landscaping service?","options":{"A":"The business owner's risk is limited strictly to invested capital.","B":"The business is eligible to trade shares publicly on stock exchanges.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay off supplier debts if the business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","distractor_reasons":{"A":"Incorrect because limiting liability to invested capital describes limited companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_732","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_732","question":"A large kitchen utensils business in Manila, Costa Footwear Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A private limited company (Ltd)","B":"A partnership","C":"A sole trader","D":"A public limited company (Plc)"},"correctOption":"D","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"A":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","B":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","C":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","D":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_733","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_733","question":"An entrepreneur buys a franchise license to operate a branded car rental agency. What is a key drawback faced by this franchisee?","options":{"A":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to alter rental policies and branding without corporate approval","D":"Inability to receive staff training or operational support from the franchisor"},"correctOption":"A","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","B":"Incorrect because established franchises offer strong brand recognition.","C":"Incorrect because franchisees must strictly comply with franchisor operational rules.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_734","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_734","question":"Two automotive manufacturers form a joint venture to build an electric vehicle battery factory. What is a primary benefit of this business setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing high research costs, operational risks, and technical expertise","C":"Complete exemption from paying national corporate taxes","D":"Total elimination of management disagreements between executive teams"},"correctOption":"B","correctAnswer":"Sharing high research costs, operational risks, and technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_735","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_735","question":"Two separate firms in Sydney agree to create a new jointly owned business to develop a new ceramic tiles, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A joint venture","C":"A merger","D":"A franchise"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","C":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","D":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","B":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_736","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_736","question":"An organisation in Accra is owned by the government but operates as a separate business providing a wedding planning business to the public. What type of organisation is it?","options":{"A":"A sole trader","B":"A public corporation","C":"A public limited company","D":"A partnership"},"correctOption":"B","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"A":"A sole trader is owned by one private individual with unlimited liability, not by the government.","C":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","D":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","B":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_737","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_737","question":"Zainab Ali owns a business in Cairo. The business incurs debts it cannot repay, and Zainabs personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"No liability","B":"Shared liability","C":"Limited liability","D":"Unlimited liability"},"correctOption":"D","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"B":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","C":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","D":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","A":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form."}}},{"id":"P1_U1_MCQ_738","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_738","question":"Grace Wanjiku is the single owner of a wedding planning business in Istanbul and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"The business has a separate legal identity from its owner.","B":"The owner has unlimited liability for all the business debts.","C":"The owner must publish detailed annual accounts publicly.","D":"Its shares are freely traded on a stock exchange."},"correctOption":"B","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","C":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","D":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","B":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_739","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_739","question":"Amara Okafor and Pablo Ruiz have set up a business together in Sao Paulo, sharing the ownership, management and profits of a landscape gardening business. What type of business organisation have they created?","options":{"A":"A public limited company","B":"A franchise","C":"A sole trader business","D":"A partnership"},"correctOption":"D","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","B":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","C":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","D":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_740","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_740","question":"Ali Footwear Ltd is a privately owned bicycles company in Accra. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A private limited company (Ltd)","B":"A partnership","C":"A public limited company (Plc)","D":"A sole trader"},"correctOption":"A","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"B":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","C":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","D":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","A":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_741","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_741","question":"Which stakeholder group is described here in relation to Kim Textiles Ltd, a canned tomatoes manufacturer in Cairo? The firms customers who buy its products and depend on their quality.","options":{"A":"Employees","B":"Shareholders","C":"Customers","D":"The local community"},"correctOption":"C","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price.","distractor_reasons":{"A":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","B":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","D":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","C":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price."}}},{"id":"P1_U1_MCQ_742","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_742","question":"At Bennett Beverages Ltd in Warsaw, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"The government seeking lower taxes conflicts with the local community seeking more jobs.","B":"Customers seeking lower prices conflict with suppliers seeking higher prices.","C":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","D":"Managers seeking faster growth conflict with customers seeking better quality."},"correctOption":"C","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","B":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","D":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","C":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_743","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_743","question":"Haddad Pharmaceuticals Ltd sells 60 units of chocolate bars in Jakarta. Total sales of chocolate bars in the whole market are 100 units. What is the firms market share?","options":{"A":"40%","B":"60%","C":"75%","D":"25%"},"correctOption":"B","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (60/100) x 100 = 60%.","distractor_reasons":{"A":"40% is incorrect because it does not result from dividing the firms 60 units by the 100 total market units.","C":"75% is not the market share: dividing 60 by 100 and multiplying by 100 gives 60%, not 75%.","D":"25% is wrong; the correct calculation of firm sales over total market sales times 100 yields 60%.","B":"Option is correct because market share = (firm sales / total market sales) x 100 = (60/100) x 100 = 60%."}}},{"id":"P1_U1_MCQ_744","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_744","question":"Haddad Footwear Ltd, a textbooks firm in Accra, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Survival","B":"Social enterprise","C":"Market share","D":"Profit maximisation"},"correctOption":"D","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","B":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","C":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","D":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_745","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_745","question":"During a severe downturn in Nairobi, Bauer Auto Parts Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Survival","B":"Market share","C":"Profit maximisation","D":"Growth"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"B":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","C":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","D":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","A":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_746","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_746","question":"Mwangi Plastics Ltd in Kampala has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Profit maximisation","B":"Growth","C":"Survival","D":"Social enterprise"},"correctOption":"B","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"A":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","C":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","D":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","B":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_747","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_747","question":"Bennett Footwear Ltd wants to increase the proportion of total sales in the ceramic tiles market in Warsaw that it captures for itself. Which objective is this?","options":{"A":"Cost minimisation","B":"Increasing market share","C":"Survival","D":"Social enterprise"},"correctOption":"B","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","C":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","D":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","B":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_748","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_748","question":"Ruiz Plastics Ltd in Glasgow reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Market share","B":"Profit maximisation","C":"Social enterprise objectives","D":"Cost minimisation"},"correctOption":"C","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","B":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","D":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","C":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_749","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_749","question":"Which stakeholder group is described here in relation to Patel Paper Ltd, a motorbikes manufacturer in Kuala Lumpur? The people who have bought shares in the business and expect a return on their investment.","options":{"A":"Employees","B":"The local community","C":"Shareholders","D":"Customers"},"correctOption":"C","correctAnswer":"Shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns.","distractor_reasons":{"A":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","C":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns.","D":"Customers are the people who buy the firms products; the described stakeholders are not the purchasers of its output.","B":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area."}}},{"id":"P1_U1_MCQ_750","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_750","question":"At Haddad Bakery Ltd in Cape Town, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Managers seeking faster growth conflict with customers seeking better quality.","B":"The government seeking lower taxes conflicts with the local community seeking more jobs.","C":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","D":"Customers seeking lower prices conflict with suppliers seeking higher prices."},"correctOption":"C","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","B":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","D":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","C":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_751","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_751","question":"A furniture maker has timber resources available to produce either 10 solid oak dining tables or 25 oak chairs. If the craftsman decides to manufacture 10 solid oak dining tables, what is the opportunity cost of this decision?","options":{"A":"The 25 oak chairs foregone","B":"The purchase invoice cost of the raw oak timber","C":"The sales revenue earned from selling 10 dining tables","D":"The electricity cost of operating the wood turning lathe"},"correctOption":"A","correctAnswer":"The 25 oak chairs foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost represents the next best alternative sacrificed when making a choice, which is the 25 oak chairs.","distractor_reasons":{"A":"Option A is correct because opportunity cost represents the next best alternative sacrificed when making a choice, which is the 25 oak chairs.","B":"Incorrect because raw timber invoice cost is a direct monetary expenditure.","C":"Incorrect because sales revenue is the financial gain from the chosen option.","D":"Incorrect because electricity cost is an operational expense."}}},{"id":"P1_U1_MCQ_752","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_752","question":"A leather artisan purchases hide for $20 and brass fittings for $5 per belt. The finished belt sells for $75. Which business action directly increases the added value per belt by $10?","options":{"A":"Increasing total weekly production of belts from 40 to 120 units","B":"Adding custom monogramming and raising the retail price to $85","C":"Reducing hourly wages paid to shop assistants by $10 per shift","D":"Purchasing $10 worth of additional brass fittings to store as inventory"},"correctOption":"B","correctAnswer":"Adding custom monogramming and raising the retail price to $85","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value = selling price ($75) - material costs ($25) = $50. Increasing selling price to $85 with constant material costs raises added value to $60 ($10 increase).","distractor_reasons":{"A":"Incorrect because increasing production volume affects total revenue/profit, not unit added value.","B":"Option B is correct because added value = selling price ($75) - material costs ($25) = $50. Increasing selling price to $85 with constant material costs raises added value to $60 ($10 increase).","C":"Incorrect because assistant wages are operational overheads, not bought-in component costs.","D":"Incorrect because storing extra component fittings increases raw inventory without altering unit added value."}}},{"id":"P1_U1_MCQ_753","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_753","question":"A commercial farm uses fertile soil, agricultural workers, harvesting combine machinery, and an innovative farm manager. Which factor of production does the harvesting combine machinery represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used to assist production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources like fertile soil.","B":"Incorrect because labour refers to the physical and mental work of farm laborers.","C":"Option C is correct because capital consists of man-made physical equipment, machinery, and tools used to assist production.","D":"Incorrect because enterprise refers to the risk-taking and organizational role of the manager."}}},{"id":"P1_U1_MCQ_754","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_754","question":"An electronics assembly factory assigns a worker to perform only the single task of soldering circuit board wires for 8 hours daily. What is a primary drawback of division of labor in this scenario?","options":{"A":"The soldering task requires extensive postgraduate university education","B":"The purchase price of solder wire paid to suppliers increases","C":"Overall assembly line speed drops drastically","D":"Continuous task repetition leads to boredom, declining morale, and potential quality mistakes"},"correctOption":"D","correctAnswer":"Continuous task repetition leads to boredom, declining morale, and potential quality mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating a single narrow task repeatedly causes monotony, which leads to boredom, reduced employee engagement, and quality errors.","distractor_reasons":{"A":"Incorrect because simplified single tasks require minimal training.","B":"Incorrect because internal task division does not affect supplier material prices.","C":"Incorrect because division of labor typically speeds up production output.","D":"Option D is correct because repeating a single narrow task repeatedly causes monotony, which leads to boredom, reduced employee engagement, and quality errors."}}},{"id":"P1_U1_MCQ_755","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_755","question":"Which item is classified as a fundamental human need essential for survival?","options":{"A":"Basic nutritional food and safe drinking water","B":"A premium subscription to a music streaming app","C":"A high-performance gaming computer","D":"Designer luxury footwear"},"correctOption":"A","correctAnswer":"Basic nutritional food and safe drinking water","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because nutrition and water are physiological necessities required for human life.","distractor_reasons":{"A":"Option A is correct because nutrition and water are physiological necessities required for human life.","B":"Incorrect because music streaming is an entertainment want.","C":"Incorrect because gaming equipment is a recreational want.","D":"Incorrect because luxury footwear is a fashion want."}}},{"id":"P1_U1_MCQ_756","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_756","question":"What is the primary cause of the economic problem of scarcity in society?","options":{"A":"Commercial banks restricting business overdraft facilities","B":"High tariff rates enforced on foreign manufactured goods","C":"Unlimited human wants exceeding finite productive resources available","D":"Excessive tax rates on corporate profits"},"correctOption":"C","correctAnswer":"Unlimited human wants exceeding finite productive resources available","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because scarcity arises because economic resources are limited while consumer wants are virtually infinite.","distractor_reasons":{"A":"Incorrect because credit limits do not create fundamental resource scarcity.","B":"Incorrect because tariffs affect trade policy, not global resource scarcity.","C":"Option C is correct because scarcity arises because economic resources are limited while consumer wants are virtually infinite.","D":"Incorrect because corporate taxation does not alter the fundamental existence of resource scarcity."}}},{"id":"P1_U1_MCQ_757","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_757","question":"A watchmaker buys stainless steel casing for $30 and movement parts for $20 per wristwatch. The assembled wristwatch sells for $300. What is the added value per wristwatch?","options":{"A":"$50","B":"$270","C":"$250","D":"$300"},"correctOption":"C","correctAnswer":"$250","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total material cost = $30 + $20 = $50. Added value = selling price ($300) - material costs ($50) = $250.","distractor_reasons":{"A":"Incorrect because $50 is total bought-in material cost.","B":"Incorrect because $270 subtracts only casing cost ($300 - $30), ignoring movement parts.","C":"Option C is correct because total material cost = $30 + $20 = $50. Added value = selling price ($300) - material costs ($50) = $250.","D":"Incorrect because $300 is final selling price."}}},{"id":"P1_U1_MCQ_758","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_758","question":"An accountant resigns from a firm earning $60,000 annually to set up a private tax advisory practice. What is the opportunity cost of launching this new enterprise?","options":{"A":"The annual lease payment for office premises","B":"The gross fee revenue earned from clients in Year 1","C":"The capital spent purchasing accounting software","D":"The $60,000 salary foregone from the former accounting employment"},"correctOption":"D","correctAnswer":"The $60,000 salary foregone from the former accounting employment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative, which is the $60,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is an explicit operational cost.","B":"Incorrect because client fees are revenues from the chosen venture.","C":"Incorrect because software purchases are capital outlays.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative, which is the $60,000 salary."}}},{"id":"P1_U1_MCQ_759","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_759","question":"Which factor of production includes natural resources such as copper deposits, rainwater, and natural pine forests?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural unrefined inputs provided by nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural unrefined inputs provided by nature used in economic production.","B":"Incorrect because labour refers to human physical/mental effort.","C":"Incorrect because capital refers to manufactured equipment/machinery.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_760","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_760","question":"How can a suit tailor directly increase the added value of bespoke suits without raising retail prices?","options":{"A":"Increasing spending on newspaper advertisements","B":"Negotiating lower component costs for wool cloth from suppliers","C":"Increasing hourly wage rates paid to tailors","D":"Renting a larger showroom in a high-street location"},"correctOption":"B","correctAnswer":"Negotiating lower component costs for wool cloth from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing wool cloth costs widens this gap.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Reducing wool cloth costs widens this gap.","C":"Incorrect because higher tailor wages increase operating expenses, lowering profit margin rather than unit added value.","D":"Incorrect because showroom rent increases overhead costs."}}},{"id":"P1_U1_MCQ_761","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_761","question":"Which activity is classified within the primary sector of an economy?","options":{"A":"Smelting iron ore into steel ingots","B":"Providing legal advice to commercial clients","C":"Extracting coal from underground mines","D":"Operating a chain of hardware retail stores"},"correctOption":"C","correctAnswer":"Extracting coal from underground mines","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting coal involves direct harvesting/mining of natural resources (primary sector).","distractor_reasons":{"A":"Incorrect because smelting iron ore into steel is secondary manufacturing.","B":"Incorrect because legal advice is a tertiary professional service.","C":"Option C is correct because extracting coal involves direct harvesting/mining of natural resources (primary sector).","D":"Incorrect because operating retail hardware stores is tertiary distribution."}}},{"id":"P1_U1_MCQ_762","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_762","question":"What structural shift occurs in an economy undergoing deindustrialization?","options":{"A":"Workers shift out of cloud computing services into farming","B":"The government nationalizes all private manufacturing plants","C":"Manufacturing output expands rapidly while service industries decline","D":"Secondary sector manufacturing declines relative to the growth of tertiary sector services"},"correctOption":"D","correctAnswer":"Secondary sector manufacturing declines relative to the growth of tertiary sector services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion of tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not experience rapid growth during deindustrialization.","B":"Incorrect because deindustrialization refers to sector proportion changes, not state nationalization.","C":"Incorrect because manufacturing output contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion of tertiary services."}}},{"id":"P1_U1_MCQ_763","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_763","question":"A national government owns and operates a travel agency in Leeds in order to provide a public service for citizens. Which sector of the economy does this organisation belong to?","options":{"A":"Primary sector","B":"Public sector","C":"Private sector","D":"Secondary sector"},"correctOption":"B","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned and run by the government, which defines the public sector.","distractor_reasons":{"A":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","C":"The private sector consists of businesses owned by private individuals or shareholders; this organisation is not privately owned.","D":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","B":"Option is correct because the organisation is owned and run by the government, which defines the public sector."}}},{"id":"P1_U1_MCQ_764","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_764","question":"A farming business grows sugar beets, a refinery processes sugar beets into refined sugar, and a confectionery business uses refined sugar to manufacture candy. How are these three firms classified?","options":{"A":"Farming: Secondary; Refinery: Primary; Confectionery: Tertiary","B":"Farming: Primary; Refinery: Secondary; Confectionery: Secondary","C":"Farming: Primary; Refinery: Tertiary; Confectionery: Secondary","D":"Farming: Tertiary; Refinery: Secondary; Confectionery: Primary"},"correctOption":"B","correctAnswer":"Farming: Primary; Refinery: Secondary; Confectionery: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because growing sugar beets is primary agriculture, while refining sugar and manufacturing candy both involve secondary sector processing/manufacturing.","distractor_reasons":{"A":"Incorrect because farming is primary extraction, not secondary.","B":"Option B is correct because growing sugar beets is primary agriculture, while refining sugar and manufacturing candy both involve secondary sector processing/manufacturing.","C":"Incorrect because sugar refining is secondary processing, not tertiary service.","D":"Incorrect because sector order is incorrect."}}},{"id":"P1_U1_MCQ_765","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_765","question":"In Nairobi, 10% of workers are employed in the primary sector, 50% in the secondary sector and 15% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Secondary sector","B":"Tertiary sector","C":"Public sector","D":"Primary sector"},"correctOption":"A","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"The secondary sector employs 50% of workers, which is lower than the largest share of 50%, so it does not employ the most workers.","distractor_reasons":{"B":"The tertiary sector employs 15% of workers, the largest share of the three sectors, so it employs the most workers.","C":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","D":"The primary sector employs 10% of workers, which is lower than the largest share of 50%, so it does not employ the most workers.","A":"The secondary sector employs 50% of workers, which is lower than the largest share of 50%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_766","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_766","question":"A state-owned organisation in Melbourne provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To maximise profit for its private shareholders.","B":"To increase the wealth of the governments individual ministers.","C":"To extract and sell as many natural resources as possible.","D":"To provide a service to the community rather than to maximise profit."},"correctOption":"D","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"A":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","B":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","C":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","D":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_767","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_767","question":"What is the primary objective of private sector business owners in a market economy?","options":{"A":"Generating profit to provide a financial return on invested capital","B":"Fulfilling central government production quotas","C":"Providing free public services to all citizens","D":"Maximizing annual corporate tax payments to the treasury"},"correctOption":"A","correctAnswer":"Generating profit to provide a financial return on invested capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because earning profits is the primary financial incentive for private sector owners.","distractor_reasons":{"A":"Option A is correct because earning profits is the primary financial incentive for private sector owners.","B":"Incorrect because production quotas belong to command economies.","C":"Incorrect because free public services are provided by the public sector.","D":"Incorrect because private firms seek to manage tax liabilities legally, not maximize tax."}}},{"id":"P1_U1_MCQ_768","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_768","question":"Why might a government choose to privatize a state-owned telecommunications company?","options":{"A":"To convert telecommunications technicians into civil servants","B":"To introduce market competition, private capital investment, and operational efficiency","C":"To restrict private capital investment in fiber optic networks","D":"To increase direct state control over consumer monthly subscription rates"},"correctOption":"B","correctAnswer":"To introduce market competition, private capital investment, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, introducing market competition and profit incentives that boost efficiency.","distractor_reasons":{"A":"Incorrect because privatized employees lose civil servant status.","B":"Option B is correct because privatization transfers state assets to private owners, introducing market competition and profit incentives that boost efficiency.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct government control over pricing."}}},{"id":"P1_U1_MCQ_769","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_769","question":"Which sector of the economy does this activity belong to? Pablo Ruiz owns a farm in Hanoi and harvests cotton for sale.","options":{"A":"Tertiary sector","B":"Primary sector","C":"Public sector","D":"Secondary sector"},"correctOption":"B","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it.","distractor_reasons":{"A":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","C":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","D":"The secondary sector involves manufacturing and construction; the described activity is not the processing of materials into goods.","B":"Option is correct because the primary sector extracts and harvests natural resources, so farming and harvesting crops belongs to it."}}},{"id":"P1_U1_MCQ_770","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_770","question":"Over the past decade the economy around Osaka has moved workers out of farming and into new factories producing chocolate bars, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Deindustrialisation","B":"Privatisation","C":"Specialisation","D":"Industrialisation"},"correctOption":"D","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"A":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","B":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","C":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","D":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_771","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_771","question":"Over five years Hassan Foods Ltd expanded its laptops business in Kampala by reinvesting its own profits to open 4 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Backward vertical integration","B":"Horizontal integration","C":"Forward vertical integration","D":"Internal (organic) growth"},"correctOption":"D","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","B":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","C":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","D":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_772","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_772","question":"Petrova Steel Ltd, a cement manufacturer in Seoul, has taken over a rival firm that makes the same cement at the same stage of production. What type of integration is this?","options":{"A":"Internal growth","B":"Forward vertical integration","C":"Backward vertical integration","D":"Horizontal integration"},"correctOption":"D","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","B":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","C":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","D":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_773","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_773","question":"A textbooks manufacturer in Cairo, Mensah Bakery Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Horizontal integration","B":"Backward vertical integration","C":"Forward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain.","B":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","D":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","C":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain."}}},{"id":"P1_U1_MCQ_774","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_774","question":"Williams Ceramics Ltd, a LED bulbs producer in Dublin, has purchased a steel works that previously supplied its raw materials. What type of integration is this?","options":{"A":"Horizontal integration","B":"Internal growth","C":"Backward vertical integration","D":"Forward vertical integration"},"correctOption":"C","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"A":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","B":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","D":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","C":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_775","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_775","question":"After a period of very rapid expansion, Tanaka Foods Ltd in Manila found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing school backpacks business. Which problem of growth does this illustrate?","options":{"A":"Higher staff morale throughout the workforce.","B":"A reduction in the number of competitors in the market.","C":"Lower average costs from economies of scale.","D":"Loss of control and coordination difficulties as the business becomes larger."},"correctOption":"D","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","B":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","C":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","D":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_776","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_776","question":"Adeyemi Textiles Ltd, a LED bulbs firm in Kampala, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"Over-regulation of the market by the government.","B":"Excessive profitability that attracted too much competition.","C":"Cash flow problems, leaving it unable to pay debts as they fell due.","D":"A shortage of customer demand for its products."},"correctOption":"C","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"A":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","B":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","D":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","C":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_777","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_777","question":"Pablo Ruiz noticed a gap in the local market in Manila, invested personal savings, took the financial risk and set up a new business making laptops. Which role is Pablo carrying out?","options":{"A":"A trade union official","B":"A shareholder only","C":"An employee","D":"An entrepreneur"},"correctOption":"D","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","B":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","C":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","D":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_778","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_778","question":"Noah Williams wants to start a parcel delivery service in Dar es Salaam and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A delivery note","B":"An organisation chart","C":"A statement of profit or loss","D":"A business plan"},"correctOption":"D","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"B":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","C":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","D":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","A":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan."}}},{"id":"P1_U1_MCQ_779","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_779","question":"A government wants to encourage more people in Mumbai to set up small businesses making school backpacks. Which of the following is an example of government support for new business start-ups?","options":{"A":"Offering low-interest start-up loans and grant funding to new firms.","B":"Removing all forms of business advice and training for new owners.","C":"Raising the rate of corporation tax on all company profits.","D":"Introducing stricter rules that make it harder to register a new firm."},"correctOption":"A","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"B":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","C":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","D":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","A":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_780","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_780","question":"Ferrari Pharmaceuticals Ltd is a chocolate bars business in Glasgow with 75 employees and annual sales revenue of $12m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The profit margin and the current ratio.","B":"The brand image and the quality of its products.","C":"The share price and the dividend yield.","D":"The number of employees and the annual sales turnover."},"correctOption":"D","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"A":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","B":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","C":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","D":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_781","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_781","question":"What does unlimited liability mean for a sole trader running a plumbing service?","options":{"A":"The business owner's financial risk is strictly capped at invested capital.","B":"The business can issue public shares on national stock exchanges.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay off supplier debts if the business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","distractor_reasons":{"A":"Incorrect because limiting liability to invested capital describes limited companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_782","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_782","question":"A large ceramic tiles business in Birmingham, Lin Steel Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A partnership","B":"A private limited company (Ltd)","C":"A sole trader","D":"A public limited company (Plc)"},"correctOption":"D","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"A":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","B":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","C":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","D":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_783","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_783","question":"An entrepreneur buys a franchise license to operate a branded hotel. What is a primary drawback faced by this franchisee?","options":{"A":"Inability to receive staff training or operational support from the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to alter room design and branding without corporate approval","D":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor"},"correctOption":"D","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","distractor_reasons":{"A":"Incorrect because franchisors provide training and operational support.","B":"Incorrect because established franchises offer strong brand recognition.","C":"Incorrect because franchisees must strictly comply with franchisor operational rules.","D":"Option D is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins."}}},{"id":"P1_U1_MCQ_784","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_784","question":"Two pharmaceutical firms form a joint venture to research a new vaccine. What is a primary benefit of this setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Sharing high research costs, operational risks, and technical expertise","C":"Complete exemption from paying national corporate taxes","D":"Total elimination of management disagreements between executive teams"},"correctOption":"B","correctAnswer":"Sharing high research costs, operational risks, and technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Option B is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Incorrect because management friction between joint venture partners is a known risk."}}},{"id":"P1_U1_MCQ_785","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_785","question":"Chloe Dubois pays an upfront fee and regular royalties to a well-known motorbikes brand for the right to trade under its name in Warsaw and follow its established business system. What is this arrangement called?","options":{"A":"A franchise","B":"A takeover","C":"A public corporation","D":"A joint venture"},"correctOption":"A","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"B":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","C":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","D":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand.","A":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model."}}},{"id":"P1_U1_MCQ_786","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_786","question":"Two separate firms in Osaka agree to create a new jointly owned business to develop a new motorbikes, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A merger","C":"A franchise","D":"A joint venture"},"correctOption":"D","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","C":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","D":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","B":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business."}}},{"id":"P1_U1_MCQ_787","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_787","question":"An organisation in Lyon is owned by the government but operates as a separate business providing a home cleaning service to the public. What type of organisation is it?","options":{"A":"A sole trader","B":"A partnership","C":"A public corporation","D":"A public limited company"},"correctOption":"C","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"A":"A sole trader is owned by one private individual with unlimited liability, not by the government.","B":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","D":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","C":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_788","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_788","question":"Isabella Costa owns a business in Manchester. The business incurs debts it cannot repay, and Isabellas personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"Limited liability","B":"Shared liability","C":"Unlimited liability","D":"No liability"},"correctOption":"C","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","B":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","D":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","C":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_789","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_789","question":"Lucia Ferrari is the single owner of a travel agency in Istanbul and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"The owner must publish detailed annual accounts publicly.","B":"The business has a separate legal identity from its owner.","C":"The owner has unlimited liability for all the business debts.","D":"Its shares are freely traded on a stock exchange."},"correctOption":"C","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"A":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","B":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","D":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","C":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_790","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_790","question":"Isabella Costa and Yuki Tanaka have set up a business together in Birmingham, sharing the ownership, management and profits of a chain of coffee shops. What type of business organisation have they created?","options":{"A":"A public limited company","B":"A franchise","C":"A partnership","D":"A sole trader business"},"correctOption":"C","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","B":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","D":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","C":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_791","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_791","question":"A state-run healthcare provider in Cairo is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to increase its share of the global healthcare market.","B":"It mainly aims to extract natural resources for export earnings.","C":"It mainly aims to maximise returns for private shareholders.","D":"It mainly aims to provide a service to the community rather than maximise profit."},"correctOption":"D","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","B":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","C":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","D":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_792","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_792","question":"Boateng Bakery Ltd sells 200 units of trainers in Kuala Lumpur. Total sales of trainers in the whole market are 500 units. What is the firms market share?","options":{"A":"20%","B":"25%","C":"10%","D":"40%"},"correctOption":"D","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (200/500) x 100 = 40%.","distractor_reasons":{"A":"20% is not the market share: dividing 200 by 500 and multiplying by 100 gives 40%, not 20%.","B":"25% is incorrect because it does not result from dividing the firms 200 units by the 500 total market units.","C":"10% is wrong; the correct calculation of firm sales over total market sales times 100 yields 40%.","D":"Option is correct because market share = (firm sales / total market sales) x 100 = (200/500) x 100 = 40%."}}},{"id":"P1_U1_MCQ_793","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_793","question":"Nasser Bakery Ltd, a ceramic tiles firm in Nairobi, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Survival","B":"Social enterprise","C":"Profit maximisation","D":"Market share"},"correctOption":"C","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","B":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","D":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","C":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_794","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_794","question":"During a severe downturn in Manila, Okafor Machinery Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Profit maximisation","B":"Growth","C":"Market share","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","B":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","C":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","D":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_795","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_795","question":"Williams Electronics Ltd in Birmingham has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Social enterprise","B":"Profit maximisation","C":"Survival","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"B":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","C":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","D":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","A":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets."}}},{"id":"P1_U1_MCQ_796","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_796","question":"Okafor Dairy Ltd wants to increase the proportion of total sales in the ceramic tiles market in Auckland that it captures for itself. Which objective is this?","options":{"A":"Cost minimisation","B":"Increasing market share","C":"Survival","D":"Social enterprise"},"correctOption":"B","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","C":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","D":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","B":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_797","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_797","question":"Kim Foods Ltd in Nairobi reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Market share","B":"Social enterprise objectives","C":"Cost minimisation","D":"Profit maximisation"},"correctOption":"B","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","D":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","B":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_798","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_798","question":"Which stakeholder group is described here in relation to Johnson Steel Ltd, a furniture manufacturer in Cape Town? The people who work on the production line and depend on the firm for their wages.","options":{"A":"The local community","B":"Shareholders","C":"Employees","D":"Customers"},"correctOption":"C","correctAnswer":"Employees","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because employees are an internal stakeholder group because they work for the business and depend on it for income.","distractor_reasons":{"A":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","B":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","D":"Customers are the people who buy the firms products; the described stakeholders are not the purchasers of its output.","C":"Option is correct because employees are an internal stakeholder group because they work for the business and depend on it for income."}}},{"id":"P1_U1_MCQ_799","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_799","question":"At Mwangi Auto Parts Ltd in Mumbai, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","B":"The government seeking lower taxes conflicts with the local community seeking more jobs.","C":"Managers seeking faster growth conflict with customers seeking better quality.","D":"Customers seeking lower prices conflict with suppliers seeking higher prices."},"correctOption":"A","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"B":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","C":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","D":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","A":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_800","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_800","question":"A state-run healthcare provider in Sao Paulo is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to increase its share of the global healthcare market.","B":"It mainly aims to provide a service to the community rather than maximise profit.","C":"It mainly aims to extract natural resources for export earnings.","D":"It mainly aims to maximise returns for private shareholders."},"correctOption":"B","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","C":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","D":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","B":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_801","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_801","question":"A textile workshop has sufficient cotton thread to produce either 30 bath towels or 60 face cloths. If the manager decides to manufacture 30 bath towels, what is the opportunity cost of this choice?","options":{"A":"The 60 face cloths foregone","B":"The purchase cost of the raw cotton thread","C":"The revenue generated from selling the 30 bath towels","D":"The maintenance cost of the weaving looms"},"correctOption":"A","correctAnswer":"The 60 face cloths foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative foregone, which is the 60 face cloths.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative foregone, which is the 60 face cloths.","B":"Incorrect because cotton thread cost is a direct material expenditure.","C":"Incorrect because revenue is the financial yield from the chosen option.","D":"Incorrect because loom maintenance is an operational expense."}}},{"id":"P1_U1_MCQ_802","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_802","question":"A candle maker buys soy wax for $5 and scent oil for $3 per jar candle. The finished candle sells for $25. Which business decision directly increases the added value per candle by $5?","options":{"A":"Increasing weekly candle output from 200 to 500 units","B":"Packaging the candle in a gift box and raising the retail price to $30","C":"Reducing candle pourer hourly wages by $5 per shift","D":"Purchasing $5 worth of extra soy wax to keep in storage"},"correctOption":"B","correctAnswer":"Packaging the candle in a gift box and raising the retail price to $30","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because initial added value = $25 - $8 = $17. Increasing the retail price to $30 with constant component costs increases added value to $22 ($5 increase).","distractor_reasons":{"A":"Incorrect because increasing production volume affects total overall profit, not unit added value.","B":"Option B is correct because initial added value = $25 - $8 = $17. Increasing the retail price to $30 with constant component costs increases added value to $22 ($5 increase).","C":"Incorrect because worker wages are overhead expenses, not bought-in component costs.","D":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value."}}},{"id":"P1_U1_MCQ_803","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_803","question":"A commercial printing press operates using paper rolls, press operators, high-speed offset printing presses, and an innovative print director. Which factor of production do the high-speed offset printing presses represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical equipment and machinery used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources.","B":"Incorrect because labour refers to the physical and mental work of press operators.","C":"Option C is correct because capital consists of man-made physical equipment and machinery used in production.","D":"Incorrect because enterprise refers to the risk-taking managerial function."}}},{"id":"P1_U1_MCQ_804","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_804","question":"A garment factory assigns a seamstress to perform only the single task of sewing shirt collars for 8 hours daily. What is a key disadvantage of division of labor in this situation?","options":{"A":"Seamstresses require years of university education to sew collars","B":"The component cost of collar fabric purchased from suppliers increases","C":"Overall shirt output speed decreases","D":"Monotonous task repetition can lead to worker boredom, fatigue, and lower work quality"},"correctOption":"D","correctAnswer":"Monotonous task repetition can lead to worker boredom, fatigue, and lower work quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one simple task leads to boredom, which reduces motivation and leads to errors.","distractor_reasons":{"A":"Incorrect because single repetitive tasks require minimal training.","B":"Incorrect because internal division of labor does not alter component purchase prices.","C":"Incorrect because specialization usually increases production efficiency and speed.","D":"Option D is correct because repeating one simple task leads to boredom, which reduces motivation and leads to errors."}}},{"id":"P1_U1_MCQ_805","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_805","question":"Which item is classified as a fundamental human need necessary for physical survival?","options":{"A":"Basic medical care and sanitation","B":"A subscription to a video gaming platform","C":"A luxury smartwatch","D":"High-speed international flight tickets"},"correctOption":"A","correctAnswer":"Basic medical care and sanitation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because health and sanitation are fundamental requirements for human survival.","distractor_reasons":{"A":"Option A is correct because health and sanitation are fundamental requirements for human survival.","B":"Incorrect because video gaming subscriptions are entertainment wants.","C":"Incorrect because smartwatches are luxury electronic wants.","D":"Incorrect because international flights are travel wants."}}},{"id":"P1_U1_MCQ_806","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_806","question":"Larsen Dairy Ltd makes denim clothing in Manila. Which factor of production is illustrated by the machines, tools and delivery vans used in the production process?","options":{"A":"Enterprise","B":"Land","C":"Capital","D":"Labour"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because capital means man-made aids to production such as machinery and vehicles, so these items are capital.","distractor_reasons":{"A":"Enterprise is the risk-taking organiser combining the other factors; the described item is not that organising role.","B":"Land refers to natural resources and the physical site used in production; the described item is not a natural resource or site.","D":"Labour is the effort and skills of workers; the described item is not the human effort applied to production.","C":"Option is correct because capital means man-made aids to production such as machinery and vehicles, so these items are capital."}}},{"id":"P1_U1_MCQ_807","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_807","question":"A coffee roaster buys green coffee beans for $6 and packaging materials for $2 per bag. The roasted coffee sells for $20 per bag. What is the added value per bag?","options":{"A":"$8","B":"$14","C":"$12","D":"$20"},"correctOption":"C","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs = $6 + $2 = $8. Added value = selling price ($20) - material costs ($8) = $12.","distractor_reasons":{"A":"Incorrect because $8 is total bought-in material cost.","B":"Incorrect because $14 subtracts only bean cost ($20 - $6), ignoring packaging.","C":"Option C is correct because total bought-in material costs = $6 + $2 = $8. Added value = selling price ($20) - material costs ($8) = $12.","D":"Incorrect because $20 is the selling price."}}},{"id":"P1_U1_MCQ_808","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_808","question":"A software engineer leaves a job paying $70,000 per year to set up an independent app development firm. What is the opportunity cost of launching this new business?","options":{"A":"The annual rent paid for office space","B":"The first-year sales revenue from app downloads","C":"The capital spent purchasing high-end workstations","D":"The $70,000 salary foregone from the previous engineering job"},"correctOption":"D","correctAnswer":"The $70,000 salary foregone from the previous engineering job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $70,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is an explicit operational cost.","B":"Incorrect because app sales revenue is the return from the chosen venture.","C":"Incorrect because workstation purchases are capital expenditures.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $70,000 salary."}}},{"id":"P1_U1_MCQ_809","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_809","question":"Which factor of production includes natural assets such as iron ore deposits, fresh water rivers, and natural gas fields?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in economic activity.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in economic activity.","B":"Incorrect because labour represents human work effort.","C":"Incorrect because capital represents man-made equipment and facilities.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_810","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_810","question":"How can a bicycle manufacturer directly increase the added value of its bikes without increasing final retail prices?","options":{"A":"Increasing spending on digital marketing ads","B":"Negotiating lower component costs for gear sets from suppliers","C":"Increasing hourly wages paid to assembly line mechanics","D":"Renting a larger distribution center in an urban area"},"correctOption":"B","correctAnswer":"Negotiating lower component costs for gear sets from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering component costs widens this difference.","distractor_reasons":{"A":"Incorrect because marketing ads are operating expenses.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering component costs widens this difference.","C":"Incorrect because higher mechanic wages increase operating expenses, lowering profit margin rather than unit added value.","D":"Incorrect because warehouse rent increases overhead costs."}}},{"id":"P1_U1_MCQ_811","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_811","question":"In Sao Paulo, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Primary sector growth","B":"Deindustrialisation","C":"Division of labour","D":"Industrialisation"},"correctOption":"B","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","C":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","D":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","B":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_812","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_812","question":"What structural employment change occurs during deindustrialization in a developed country?","options":{"A":"Labor moves out of banking services into crop farming","B":"The state government takes ownership of all private manufacturing plants","C":"Manufacturing output expands while service industry employment contracts","D":"Employment contracts in secondary manufacturing and expands in tertiary services"},"correctOption":"D","correctAnswer":"Employment contracts in secondary manufacturing and expands in tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing employment and expansion in tertiary services.","distractor_reasons":{"A":"Incorrect because primary sector jobs do not grow during deindustrialization.","B":"Incorrect because deindustrialization concerns sector composition, not state ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing employment and expansion in tertiary services."}}},{"id":"P1_U1_MCQ_813","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_813","question":"A group of private investors owns and operates an online tuition service in Lyon with the aim of earning a profit. Which sector of the economy does this organisation belong to?","options":{"A":"Public sector","B":"Secondary sector","C":"Primary sector","D":"Private sector"},"correctOption":"D","correctAnswer":"Private sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector.","distractor_reasons":{"A":"The public sector consists of organisations owned and controlled by the government; this business is not government-owned.","B":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","C":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","D":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector."}}},{"id":"P1_U1_MCQ_814","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_814","question":"A mining business extracts iron ore, a foundry processes iron ore into steel sheets, and an appliance maker uses steel sheets to manufacture refrigerators. How are these three businesses classified?","options":{"A":"Mining: Secondary; Foundry: Primary; Appliance maker: Tertiary","B":"Mining: Primary; Foundry: Secondary; Appliance maker: Secondary","C":"Mining: Primary; Foundry: Tertiary; Appliance maker: Secondary","D":"Mining: Tertiary; Foundry: Secondary; Appliance maker: Primary"},"correctOption":"B","correctAnswer":"Mining: Primary; Foundry: Secondary; Appliance maker: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because iron ore mining is primary extraction, while processing steel and manufacturing appliances both belong to the secondary manufacturing sector.","distractor_reasons":{"A":"Incorrect because mining is primary extraction, not secondary.","B":"Option B is correct because iron ore mining is primary extraction, while processing steel and manufacturing appliances both belong to the secondary manufacturing sector.","C":"Incorrect because a foundry processing steel is secondary manufacturing, not tertiary service.","D":"Incorrect because sector order is incorrect."}}},{"id":"P1_U1_MCQ_815","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_815","question":"In Warsaw, 20% of workers are employed in the primary sector, 45% in the secondary sector and 70% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Primary sector","B":"Public sector","C":"Secondary sector","D":"Tertiary sector"},"correctOption":"D","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"The tertiary sector employs 70% of workers, the largest share of the three sectors, so it employs the most workers.","distractor_reasons":{"B":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","C":"The secondary sector employs 45% of workers, which is lower than the largest share of 70%, so it does not employ the most workers.","D":"The tertiary sector employs 70% of workers, the largest share of the three sectors, so it employs the most workers.","A":"The primary sector employs 20% of workers, which is lower than the largest share of 70%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_816","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_816","question":"Which sector of the economy does this activity belong to? A privately owned factory in Seoul turns raw materials into chocolate bars.","options":{"A":"Public sector","B":"Secondary sector","C":"Tertiary sector","D":"Primary sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it.","distractor_reasons":{"A":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","C":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","D":"The primary sector involves extracting natural resources and farming; the described activity is not extraction or farming.","B":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it."}}},{"id":"P1_U1_MCQ_817","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_817","question":"Over the past decade the economy around Bogota has moved workers out of farming and into new factories producing smartphones, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Industrialisation","B":"Privatisation","C":"Specialisation","D":"Deindustrialisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"B":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","C":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","D":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","A":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_818","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_818","question":"Why might a government choose to privatize a state-owned electric utility provider?","options":{"A":"To turn utility engineers into civil service employees","B":"To introduce market competition, private capital investment, and operational efficiency","C":"To restrict private capital investment in energy infrastructure","D":"To increase direct state control over consumer electricity tariffs"},"correctOption":"B","correctAnswer":"To introduce market competition, private capital investment, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private owners, introducing profit motives and market competition that boost efficiency.","distractor_reasons":{"A":"Incorrect because privatized workers lose state civil service status.","B":"Option B is correct because privatization transfers state assets to private owners, introducing profit motives and market competition that boost efficiency.","C":"Incorrect because privatization encourages private investment.","D":"Incorrect because privatization reduces direct government control."}}},{"id":"P1_U1_MCQ_819","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_819","question":"In Dublin, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Industrialisation","B":"Deindustrialisation","C":"Division of labour","D":"Primary sector growth"},"correctOption":"B","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","C":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","D":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","B":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_820","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_820","question":"A group of private investors owns and operates an accounting practice in Dar es Salaam with the aim of earning a profit. Which sector of the economy does this organisation belong to?","options":{"A":"Private sector","B":"Primary sector","C":"Public sector","D":"Secondary sector"},"correctOption":"A","correctAnswer":"Private sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector.","distractor_reasons":{"B":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","C":"The public sector consists of organisations owned and controlled by the government; this business is not government-owned.","D":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","A":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector."}}},{"id":"P1_U1_MCQ_821","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_821","question":"Over five years Mensah Ceramics Ltd expanded its smartphones business in Kuala Lumpur by reinvesting its own profits to open 4 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Internal (organic) growth","C":"Backward vertical integration","D":"Horizontal integration"},"correctOption":"B","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","C":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","D":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","B":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_822","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_822","question":"Larsen Paper Ltd, a bicycles manufacturer in Manchester, has taken over a rival firm that makes the same bicycles at the same stage of production. What type of integration is this?","options":{"A":"Internal growth","B":"Forward vertical integration","C":"Backward vertical integration","D":"Horizontal integration"},"correctOption":"D","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","B":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","C":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","D":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_823","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_823","question":"A school backpacks manufacturer in Sao Paulo, Fischer Beverages Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Backward vertical integration","B":"Horizontal integration","C":"Forward vertical integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","C":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","D":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","B":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain."}}},{"id":"P1_U1_MCQ_824","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_824","question":"Bauer Foods Ltd, a smartphones producer in Cape Town, has purchased a steel works that previously supplied its raw materials. What type of integration is this?","options":{"A":"Forward vertical integration","B":"Horizontal integration","C":"Internal growth","D":"Backward vertical integration"},"correctOption":"D","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"A":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","B":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","C":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","D":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_825","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_825","question":"After a period of very rapid expansion, Larsen Electronics Ltd in Osaka found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing laptops business. Which problem of growth does this illustrate?","options":{"A":"A reduction in the number of competitors in the market.","B":"Lower average costs from economies of scale.","C":"Loss of control and coordination difficulties as the business becomes larger.","D":"Higher staff morale throughout the workforce."},"correctOption":"C","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","B":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","D":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","C":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_826","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_826","question":"Bennett Textiles Ltd, a school backpacks firm in Sydney, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"Cash flow problems, leaving it unable to pay debts as they fell due.","B":"A shortage of customer demand for its products.","C":"Over-regulation of the market by the government.","D":"Excessive profitability that attracted too much competition."},"correctOption":"A","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"B":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","C":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","D":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","A":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_827","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_827","question":"Omar Haddad noticed a gap in the local market in Bristol, invested personal savings, took the financial risk and set up a new business making laptops. Which role is Omar carrying out?","options":{"A":"An entrepreneur","B":"A trade union official","C":"A shareholder only","D":"An employee"},"correctOption":"A","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"B":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","C":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","D":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","A":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_828","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_828","question":"Why might the owner of a boutique hotel prefer to remain small rather than expand into a national hotel chain?","options":{"A":"Small boutique hotels are exempt from paying linen supplier bills","B":"National hotel chains are legally prohibited by government","C":"Expanding the business automatically revokes limited liability protection","D":"The owner wishes to maintain personal customer relationships and direct operational control"},"correctOption":"D","correctAnswer":"The owner wishes to maintain personal customer relationships and direct operational control","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because national hotel chains operate legally.","C":"Incorrect because business expansion does not cancel limited liability.","D":"Option D is correct because business owners often choose to remain small to retain direct operational control, manage workload, and preserve personal customer contact."}}},{"id":"P1_U1_MCQ_829","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_829","question":"Emmanuel Adeyemi wants to start an accounting practice in Accra and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"An organisation chart","B":"A business plan","C":"A delivery note","D":"A statement of profit or loss"},"correctOption":"B","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"A":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","C":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","D":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","B":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_830","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_830","question":"A government wants to encourage more people in Accra to set up small businesses making bicycles. Which of the following is an example of government support for new business start-ups?","options":{"A":"Offering low-interest start-up loans and grant funding to new firms.","B":"Removing all forms of business advice and training for new owners.","C":"Raising the rate of corporation tax on all company profits.","D":"Introducing stricter rules that make it harder to register a new firm."},"correctOption":"A","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"B":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","C":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","D":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","A":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_831","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_831","question":"What does unlimited liability mean for a sole trader running an electrical repair shop?","options":{"A":"The business owner's financial risk is strictly capped at invested capital.","B":"The business can issue public shares on national stock exchanges.","C":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","D":"The bank guarantees to pay off supplier debts if the business fails."},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, risking personal assets if the firm fails.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","distractor_reasons":{"A":"Incorrect because limiting liability to invested capital describes limited companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means the sole trader and business are legally identical; personal assets can be taken to satisfy unpaid commercial debts.","D":"Incorrect because banks do not assume liability for business debts."}}},{"id":"P1_U1_MCQ_832","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_832","question":"Costa Packaging Ltd is a privately owned ceramic tiles company in Dar es Salaam. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A sole trader","B":"A private limited company (Ltd)","C":"A public limited company (Plc)","D":"A partnership"},"correctOption":"B","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","C":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","D":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","B":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_833","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_833","question":"An entrepreneur buys a franchise license to operate a branded fitness center. What is a primary drawback faced by this franchisee?","options":{"A":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","B":"Complete lack of consumer brand awareness in the local market","C":"Complete freedom to alter gym equipment and branding without corporate approval","D":"Inability to receive staff training or operational support from the franchisor"},"correctOption":"A","correctAnswer":"Paying upfront franchise fees and ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","distractor_reasons":{"A":"Option A is correct because franchisees must pay upfront setup fees and continuous royalty fees, which reduce net profit margins.","B":"Incorrect because established franchises offer strong brand recognition.","C":"Incorrect because franchisees must strictly comply with franchisor operational rules.","D":"Incorrect because franchisors provide training and operational support."}}},{"id":"P1_U1_MCQ_834","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_834","question":"Two aerospace companies form a joint venture to build a satellite navigation network. What is a primary benefit of this setup?","options":{"A":"A permanent merger creating a single combined corporation","B":"Total elimination of management disagreements between executive teams","C":"Complete exemption from paying national corporate taxes","D":"Sharing high research costs, operational risks, and technical expertise"},"correctOption":"D","correctAnswer":"Sharing high research costs, operational risks, and technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks.","distractor_reasons":{"A":"Incorrect because joint ventures are temporary project-based collaborations, not full mergers.","B":"Incorrect because management friction between joint venture partners is a known risk.","C":"Incorrect because joint ventures remain subject to national tax laws.","D":"Option D is correct because a joint venture allows two separate businesses to pool expertise and capital for a specific venture while sharing risks."}}},{"id":"P1_U1_MCQ_835","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_835","question":"A large cement business in Dar es Salaam, Haddad Publishing Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A public limited company (Plc)","B":"A partnership","C":"A sole trader","D":"A private limited company (Ltd)"},"correctOption":"A","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"B":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","C":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","D":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","A":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_836","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_836","question":"James Mwangi pays an upfront fee and regular royalties to a well-known chocolate bars brand for the right to trade under its name in Sao Paulo and follow its established business system. What is this arrangement called?","options":{"A":"A public corporation","B":"A joint venture","C":"A takeover","D":"A franchise"},"correctOption":"D","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"A":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","B":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand.","C":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","D":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model."}}},{"id":"P1_U1_MCQ_837","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_837","question":"Two separate firms in Melbourne agree to create a new jointly owned business to develop a new canned tomatoes, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A merger","C":"A franchise","D":"A joint venture"},"correctOption":"D","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","B":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","C":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","D":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_838","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_838","question":"An organisation in Bogota is owned by the government but operates as a separate business providing a wedding planning business to the public. What type of organisation is it?","options":{"A":"A public corporation","B":"A partnership","C":"A sole trader","D":"A public limited company"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"B":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","C":"A sole trader is owned by one private individual with unlimited liability, not by the government.","D":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","A":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_839","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_839","question":"Anika Singh owns a business in Istanbul. The business incurs debts it cannot repay, and Anikas personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"No liability","B":"Limited liability","C":"Shared liability","D":"Unlimited liability"},"correctOption":"D","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","B":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","C":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","D":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_840","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_840","question":"Freya Larsen is the single owner of a dental clinic in Lisbon and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"The owner has unlimited liability for all the business debts.","B":"The owner must publish detailed annual accounts publicly.","C":"Its shares are freely traded on a stock exchange.","D":"The business has a separate legal identity from its owner."},"correctOption":"A","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"B":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","C":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","D":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","A":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_841","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_841","question":"Rossi Paper Ltd sells 125 units of laptops in Sydney. Total sales of laptops in the whole market are 250 units. What is the firms market share?","options":{"A":"80%","B":"10%","C":"50%","D":"25%"},"correctOption":"C","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (125/250) x 100 = 50%.","distractor_reasons":{"A":"80% is wrong; the correct calculation of firm sales over total market sales times 100 yields 50%.","B":"10% is not the market share: dividing 125 by 250 and multiplying by 100 gives 50%, not 10%.","D":"25% is incorrect because it does not result from dividing the firms 125 units by the 250 total market units.","C":"Option is correct because market share = (firm sales / total market sales) x 100 = (125/250) x 100 = 50%."}}},{"id":"P1_U1_MCQ_842","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_842","question":"Johnson Footwear Ltd, a motorbikes firm in Mumbai, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Social enterprise","B":"Market share","C":"Survival","D":"Profit maximisation"},"correctOption":"D","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","B":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","C":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","D":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_843","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_843","question":"During a severe downturn in Kuala Lumpur, Fischer Packaging Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Market share","B":"Profit maximisation","C":"Growth","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","B":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","C":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn.","D":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions."}}},{"id":"P1_U1_MCQ_844","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_844","question":"Okafor Paper Ltd in Nairobi has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Profit maximisation","B":"Social enterprise","C":"Survival","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"A":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","B":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","C":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","D":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_845","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_845","question":"Larsen Dairy Ltd wants to increase the proportion of total sales in the furniture market in Bristol that it captures for itself. Which objective is this?","options":{"A":"Cost minimisation","B":"Social enterprise","C":"Survival","D":"Increasing market share"},"correctOption":"D","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"B":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","C":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","D":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","A":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves."}}},{"id":"P1_U1_MCQ_846","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_846","question":"Larsen Auto Parts Ltd in Lisbon reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Market share","B":"Cost minimisation","C":"Social enterprise objectives","D":"Profit maximisation"},"correctOption":"C","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","B":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","D":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","C":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_847","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_847","question":"Which stakeholder group is described here in relation to Petrova Packaging Ltd, a chocolate bars manufacturer in Cairo? The people who have bought shares in the business and expect a return on their investment.","options":{"A":"Employees","B":"Shareholders","C":"Customers","D":"The local community"},"correctOption":"B","correctAnswer":"Shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns.","distractor_reasons":{"A":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","C":"Customers are the people who buy the firms products; the described stakeholders are not the purchasers of its output.","D":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","B":"Option is correct because shareholders are internal stakeholders who own part of the business and expect financial returns."}}},{"id":"P1_U1_MCQ_848","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_848","question":"At Johnson Plastics Ltd in Kampala, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Customers seeking lower prices conflict with suppliers seeking higher prices.","B":"The government seeking lower taxes conflicts with the local community seeking more jobs.","C":"Managers seeking faster growth conflict with customers seeking better quality.","D":"Shareholders seeking higher profits conflict with employees seeking better pay and security."},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","B":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","C":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","D":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_849","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_849","question":"A state-run healthcare provider in Accra is funded by taxation and aims to give all citizens access to treatment. Which statement about its objectives is most likely to be correct?","options":{"A":"It mainly aims to maximise returns for private shareholders.","B":"It mainly aims to extract natural resources for export earnings.","C":"It mainly aims to provide a service to the community rather than maximise profit.","D":"It mainly aims to increase its share of the global healthcare market."},"correctOption":"C","correctAnswer":"It mainly aims to provide a service to the community rather than maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit.","distractor_reasons":{"A":"Maximising returns for private shareholders is the objective of private sector firms, not a tax-funded public healthcare provider.","B":"Extracting resources for export is a primary sector activity and is unrelated to the aims of a publicly funded healthcare provider.","D":"Seeking a larger global market share is a commercial growth objective, not the community service goal of a state-run provider.","C":"Option is correct because public sector organisations usually aim to serve the public interest and provide services, not to maximise profit."}}},{"id":"P1_U1_MCQ_850","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_850","question":"Costa Packaging Ltd sells 120 units of textbooks in Leeds. Total sales of textbooks in the whole market are 400 units. What is the firms market share?","options":{"A":"40%","B":"80%","C":"30%","D":"10%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share = (firm sales / total market sales) x 100 = (120/400) x 100 = 30%.","distractor_reasons":{"A":"40% is wrong; the correct calculation of firm sales over total market sales times 100 yields 30%.","C":"Option is correct because market share = (firm sales / total market sales) x 100 = (120/400) x 100 = 30%.","D":"10% is incorrect because it does not result from dividing the firms 120 units by the 400 total market units.","B":"80% is not the market share: dividing 120 by 400 and multiplying by 100 gives 30%, not 80%."}}},{"id":"P1_U1_MCQ_851","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_851","question":"A glassblowing studio has enough molten crystal to produce either 15 decorative pitchers or 45 drinking glasses. If the artisan decides to craft 15 decorative pitchers, what is the opportunity cost of this decision?","options":{"A":"The 45 drinking glasses foregone","B":"The purchase cost of the raw silica and crystal materials","C":"The sales revenue earned from selling the 15 pitchers","D":"The fuel cost of heating the glassblowing furnace"},"correctOption":"A","correctAnswer":"The 45 drinking glasses foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 45 drinking glasses.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 45 drinking glasses.","B":"Incorrect because raw material cost is a direct monetary expenditure, not the foregone alternative.","C":"Incorrect because sales revenue is the financial return from the chosen option.","D":"Incorrect because furnace fuel is an operating expense."}}},{"id":"P1_U1_MCQ_852","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_852","question":"A perfume maker buys essential oils for $9 and glass bottles for $3 per bottle of fragrance. The finished perfume sells for $40. Which business action directly increases the added value per bottle by $7?","options":{"A":"Increasing monthly perfume production from 400 to 900 bottles","B":"Offering custom bottle engraving and raising the retail price to $47","C":"Reducing bottling technicians' wages by $7 per shift","D":"Buying $7 worth of extra essential oils to keep in warehouse stock"},"correctOption":"B","correctAnswer":"Offering custom bottle engraving and raising the retail price to $47","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because initial added value = $40 - $12 = $28. Raising the selling price to $47 with constant component costs increases added value to $35 ($7 increase).","distractor_reasons":{"A":"Incorrect because increasing output volume alters total overall profit, not unit added value.","B":"Option B is correct because initial added value = $40 - $12 = $28. Raising the selling price to $47 with constant component costs increases added value to $35 ($7 increase).","C":"Incorrect because worker wages are overhead expenses, not bought-in component costs.","D":"Incorrect because storing extra raw materials increases inventory assets without altering unit added value."}}},{"id":"P1_U1_MCQ_853","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_853","question":"A commercial fishing company operates using ocean fishing grounds, deckhands, deep-sea trawler vessels, and an experienced fleet owner. Which factor of production do the deep-sea trawler vessels represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical machinery, vessels, and equipment used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural resources such as ocean fish stocks.","B":"Incorrect because labour refers to the physical and mental work of the deckhands.","C":"Option C is correct because capital consists of man-made physical machinery, vessels, and equipment used in production.","D":"Incorrect because enterprise refers to the risk-taking organizational role of the owner."}}},{"id":"P1_U1_MCQ_854","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_854","question":"A beverage bottling plant assigns a worker to perform only the single task of visually inspecting bottle caps for 8 hours daily. What is a primary disadvantage of division of labor in this workplace?","options":{"A":"Workers require years of university engineering study to inspect bottle caps","B":"The purchase price of bottle caps bought from suppliers increases","C":"Overall bottling line speed slows down significantly","D":"Monotonous task repetition causes worker boredom, reduced concentration, and missed defects"},"correctOption":"D","correctAnswer":"Monotonous task repetition causes worker boredom, reduced concentration, and missed defects","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one simple task leads to boredom and fatigue, lowering motivation and increasing error rates.","distractor_reasons":{"A":"Incorrect because narrow repetitive tasks require minimal training.","B":"Incorrect because internal division of labor does not alter supplier component prices.","C":"Incorrect because specialization typically increases production efficiency and speed.","D":"Option D is correct because repeating one simple task leads to boredom and fatigue, lowering motivation and increasing error rates."}}},{"id":"P1_U1_MCQ_855","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_855","question":"Which item is classified as a fundamental human need essential for physical survival?","options":{"A":"Warm protective clothing in cold climates","B":"Designer sunglasses","C":"VIP concert tickets","D":"A luxury sailing yacht"},"correctOption":"A","correctAnswer":"Warm protective clothing in cold climates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because basic clothing for protection against the elements is a fundamental human need for survival.","distractor_reasons":{"A":"Option A is correct because basic clothing for protection against the elements is a fundamental human need for survival.","B":"Incorrect because designer sunglasses are fashion wants.","C":"Incorrect because concert tickets are entertainment wants.","D":"Incorrect because a sailing yacht is a luxury leisure want."}}},{"id":"P1_U1_MCQ_856","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_856","question":"What is the fundamental cause of the economic problem of scarcity?","options":{"A":"Commercial banks refusing to offer overdrafts to consumers","B":"High value-added tax rates on luxury goods","C":"Strict customs inspections at international borders","D":"Unlimited human wants exceeding the limited resources available to satisfy them"},"correctOption":"D","correctAnswer":"Unlimited human wants exceeding the limited resources available to satisfy them","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because scarcity exists when infinite consumer wants confront finite economic resources.","distractor_reasons":{"A":"Incorrect because banking credit limits do not cause underlying resource scarcity.","B":"Incorrect because sales taxes do not create the fundamental economic problem of scarcity.","C":"Incorrect because customs procedures affect trade logistics, not basic resource limits.","D":"Option D is correct because scarcity exists when infinite consumer wants confront finite economic resources."}}},{"id":"P1_U1_MCQ_857","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_857","question":"A ceramic tile maker buys raw clay for $3 and mineral glaze for $2 per square meter of tile. The finished tiles sell for $18 per square meter. What is the added value per square meter?","options":{"A":"$5","B":"$15","C":"$13","D":"$18"},"correctOption":"C","correctAnswer":"$13","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs = $3 + $2 = $5. Added value = selling price ($18) - material costs ($5) = $13.","distractor_reasons":{"A":"Incorrect because $5 is total bought-in material cost.","B":"Incorrect because $15 subtracts only clay cost ($18 - $3), ignoring mineral glaze.","C":"Option C is correct because total bought-in material costs = $3 + $2 = $5. Added value = selling price ($18) - material costs ($5) = $13.","D":"Incorrect because $18 is the final selling price."}}},{"id":"P1_U1_MCQ_858","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_858","question":"A civil engineer resigns from a salaried job earning $65,000 per year to establish an independent structural engineering consultancy. What is the opportunity cost of starting this consultancy?","options":{"A":"The annual lease cost for the consultancy office","B":"The consulting fee revenue generated in Year 1","C":"The money spent buying computer-aided design software","D":"The $65,000 salary foregone from the previous engineering job"},"correctOption":"D","correctAnswer":"The $65,000 salary foregone from the previous engineering job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $65,000 salary.","distractor_reasons":{"A":"Incorrect because office lease cost is a direct operating expense.","B":"Incorrect because consulting fees are revenue from the chosen venture.","C":"Incorrect because software purchases are capital expenditures.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $65,000 salary."}}},{"id":"P1_U1_MCQ_859","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_859","question":"Which factor of production includes natural resources such as natural spring water, bauxite deposits, and wild timber forests?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in production.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural unrefined resources provided by nature used in production.","B":"Incorrect because labour represents human physical and mental effort.","C":"Incorrect because capital represents man-made equipment and machinery.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_860","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_860","question":"How can an acoustic guitar maker directly increase the added value of its guitars without raising final retail prices?","options":{"A":"Increasing spending on online music magazine ads","B":"Renting a larger retail showroom in the city center","C":"Increasing hourly wages paid to master luthiers","D":"Negotiating lower component prices for mahogany tonewood from timber suppliers"},"correctOption":"D","correctAnswer":"Negotiating lower component prices for mahogany tonewood from timber suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because added value equals selling price minus bought-in component costs. Lowering wood material costs widens this gap.","distractor_reasons":{"A":"Incorrect because advertising is an operating overhead expense.","B":"Incorrect because showroom rent increases overhead costs.","C":"Incorrect because higher luthier wages increase operating costs, lowering profit margin rather than unit added value.","D":"Option D is correct because added value equals selling price minus bought-in component costs. Lowering wood material costs widens this gap."}}},{"id":"P1_U1_MCQ_861","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_861","question":"Which business activity is classified within the primary sector of an economy?","options":{"A":"Manufacturing cement bags at a factory","B":"Providing architectural design services to builders","C":"Quarrying raw limestone rock from the earth","D":"Operating a chain of building supply retail stores"},"correctOption":"C","correctAnswer":"Quarrying raw limestone rock from the earth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because quarrying limestone involves direct extraction of natural resources from the earth (primary sector).","distractor_reasons":{"A":"Incorrect because cement manufacturing is secondary sector processing.","B":"Incorrect because architectural design is a tertiary professional service.","C":"Option C is correct because quarrying limestone involves direct extraction of natural resources from the earth (primary sector).","D":"Incorrect because building supply retail is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_862","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_862","question":"What structural change characterizes deindustrialization in an economy?","options":{"A":"Workforce shifts out of financial services into coal mining","B":"The government nationalizes all private factories","C":"Manufacturing output grows rapidly while service sector output falls","D":"Secondary sector manufacturing declines in importance relative to the growth of tertiary services"},"correctOption":"D","correctAnswer":"Secondary sector manufacturing declines in importance relative to the growth of tertiary services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion of tertiary service industries.","distractor_reasons":{"A":"Incorrect because primary sector employment does not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to sector composition, not state ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing and expansion of tertiary service industries."}}},{"id":"P1_U1_MCQ_863","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_863","question":"Which organization operates within the public sector of a mixed economy?","options":{"A":"A state-owned national electricity grid operator controlled by the energy ministry","B":"A solar panel installation firm owned by two partners","C":"A renewable energy developer listed on the national stock exchange","D":"An independent electrician operating as a sole trader"},"correctOption":"A","correctAnswer":"A state-owned national electricity grid operator controlled by the energy ministry","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because state-owned grid operators are public sector entities owned and controlled by government ministries.","distractor_reasons":{"A":"Option A is correct because state-owned grid operators are public sector entities owned and controlled by government ministries.","B":"Incorrect because partner-owned firms belong to the private sector.","C":"Incorrect because stock exchange listed corporations belong to the private sector.","D":"Incorrect because sole traders belong to the private sector."}}},{"id":"P1_U1_MCQ_864","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_864","question":"A cotton farm harvests raw cotton, a textile mill weaves the cotton into cloth, and a garment factory stitches the cloth into shirts. How are these three businesses classified?","options":{"A":"Cotton farm: Secondary; Textile mill: Primary; Garment factory: Tertiary","B":"Cotton farm: Primary; Textile mill: Secondary; Garment factory: Secondary","C":"Cotton farm: Primary; Textile mill: Tertiary; Garment factory: Secondary","D":"Cotton farm: Tertiary; Textile mill: Secondary; Garment factory: Primary"},"correctOption":"B","correctAnswer":"Cotton farm: Primary; Textile mill: Secondary; Garment factory: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting cotton is primary agriculture, while weaving cloth and stitching shirts both transform raw materials into manufactured goods (secondary sector).","distractor_reasons":{"A":"Incorrect because cotton farming is primary extraction, not secondary.","B":"Option B is correct because harvesting cotton is primary agriculture, while weaving cloth and stitching shirts both transform raw materials into manufactured goods (secondary sector).","C":"Incorrect because a textile mill is secondary manufacturing, not tertiary service.","D":"Incorrect because sector order is incorrect."}}},{"id":"P1_U1_MCQ_865","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_865","question":"In Istanbul, 60% of workers are employed in the primary sector, 45% in the secondary sector and 25% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"A","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","distractor_reasons":{"B":"The secondary sector employs 45% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","C":"The tertiary sector employs 25% of workers, the largest share of the three sectors, so it employs the most workers.","D":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","A":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_866","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_866","question":"Which activity belongs to the tertiary economic sector?","options":{"A":"Copper ore mining","B":"Glass bottle manufacturing","C":"Cocoa bean farming","D":"Freight forwarding and logistics services"},"correctOption":"D","correctAnswer":"Freight forwarding and logistics services","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because freight forwarding provides commercial transport and logistics services, placing it in the tertiary sector.","distractor_reasons":{"A":"Incorrect because copper mining is primary.","B":"Incorrect because glass bottle manufacturing is secondary.","C":"Incorrect because cocoa farming is primary.","D":"Option D is correct because freight forwarding provides commercial transport and logistics services, placing it in the tertiary sector."}}},{"id":"P1_U1_MCQ_867","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_867","question":"A state-owned organisation in Johannesburg provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To extract and sell as many natural resources as possible.","B":"To maximise profit for its private shareholders.","C":"To provide a service to the community rather than to maximise profit.","D":"To increase the wealth of the governments individual ministers."},"correctOption":"C","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"A":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","C":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","D":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","B":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service."}}},{"id":"P1_U1_MCQ_868","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_868","question":"Why might a government choose to privatize a state-owned national airline?","options":{"A":"To convert airline pilots into government civil servants","B":"To introduce market competition, private capital investment, and operational efficiency","C":"To restrict private capital investment in aviation infrastructure","D":"To increase direct state control over passenger ticket fares"},"correctOption":"B","correctAnswer":"To introduce market competition, private capital investment, and operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private investors, introducing profit motives and competition that enhance efficiency.","distractor_reasons":{"A":"Incorrect because privatized employees lose civil servant status.","B":"Option B is correct because privatization transfers state assets to private investors, introducing profit motives and competition that enhance efficiency.","C":"Incorrect because privatization encourages private investment.","D":"Incorrect because privatization reduces direct government control over pricing."}}},{"id":"P1_U1_MCQ_869","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_869","question":"Which sector of the economy does this activity belong to? A privately owned factory in Hanoi turns raw materials into kitchen utensils.","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it.","distractor_reasons":{"A":"The primary sector involves extracting natural resources and farming; the described activity is not extraction or farming.","C":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","D":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","B":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it."}}},{"id":"P1_U1_MCQ_870","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_870","question":"What structural employment change typically occurs as a developing economy undergoes rapid industrialization?","options":{"A":"Workers move out of factory jobs into subsistence farming","B":"Service firms shut down completely to focus on mining","C":"Public sector ministries nationalize all private retail stores","D":"Workers move out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Workers move out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves into manufacturing during industrialization, not out of it.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture."}}},{"id":"P1_U1_MCQ_871","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_871","question":"Which characteristic is essential for an entrepreneur starting a new commercial venture?","options":{"A":"Avoidance of personal responsibility for business decisions","B":"Preference for following strict daily instructions from senior executives","C":"Refusal to adapt products when customer preferences change","D":"Creativity, willingness to take calculated risks, and perseverance when facing setbacks"},"correctOption":"D","correctAnswer":"Creativity, willingness to take calculated risks, and perseverance when facing setbacks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entrepreneurs require creativity, calculated risk-taking, and resilience to overcome early startup challenges.","distractor_reasons":{"A":"Incorrect because entrepreneurs take responsibility for strategic decisions.","B":"Incorrect because entrepreneurs lead independent enterprises.","C":"Incorrect because adaptability is vital for business survival.","D":"Option D is correct because entrepreneurs require creativity, calculated risk-taking, and resilience to overcome early startup challenges."}}},{"id":"P1_U1_MCQ_872","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_872","question":"Why is preparing a detailed business plan important when a new startup applies for bank financing?","options":{"A":"It automatically grants limited liability status without legal registration","B":"It exempts the business from paying corporate taxes","C":"It guarantees that the startup will earn a profit in its first operating year","D":"It provides market research and cash flow forecasts proving the startup can repay the loan"},"correctOption":"D","correctAnswer":"It provides market research and cash flow forecasts proving the startup can repay the loan","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because banks examine cash flow forecasts and market analysis in a business plan to assess repayment capability and risk.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot confer.","B":"Incorrect because tax obligations are determined by law, not business plans.","C":"Incorrect because business plans contain forecasts, not profit guarantees.","D":"Option D is correct because banks examine cash flow forecasts and market analysis in a business plan to assess repayment capability and risk."}}},{"id":"P1_U1_MCQ_873","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_873","question":"Which metric is a standard, valid measure used to compare business size within an industry?","options":{"A":"Annual net profit earned by the business","B":"Unit selling price of flagship products","C":"Total monetary value of capital employed","D":"Percentage markup added to raw material costs"},"correctOption":"C","correctAnswer":"Total monetary value of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (total long-term funds invested) is a recognized standard indicator of business scale.","distractor_reasons":{"A":"Incorrect because net profit is NOT a valid size metric (a small firm can earn higher profit than a large inefficient firm).","B":"Incorrect because unit price reflects market positioning, not business size.","C":"Option C is correct because capital employed (total long-term funds invested) is a recognized standard indicator of business scale.","D":"Incorrect because markup percentage reflects pricing strategy, not company scale."}}},{"id":"P1_U1_MCQ_874","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_874","question":"Adeyemi Auto Parts Ltd is a furniture business in Dublin with 35 employees and annual sales revenue of $12m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The brand image and the quality of its products.","B":"The share price and the dividend yield.","C":"The profit margin and the current ratio.","D":"The number of employees and the annual sales turnover."},"correctOption":"D","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"A":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","B":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","C":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","D":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_875","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_875","question":"Why do governments provide training programs and startup grants to new entrepreneurs?","options":{"A":"To force small firms to list shares on the national stock exchange","B":"To eliminate competition for state-owned enterprises","C":"To reduce unemployment, encourage innovation, and stimulate economic growth","D":"To prevent foreign businesses from exporting goods"},"correctOption":"C","correctAnswer":"To reduce unemployment, encourage innovation, and stimulate economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because supporting new startups generates jobs, fosters innovation, and increases national economic output.","distractor_reasons":{"A":"Incorrect because grants do not compel stock exchange listing.","B":"Incorrect because startup support increases market competition rather than eliminating it.","C":"Option C is correct because supporting new startups generates jobs, fosters innovation, and increases national economic output.","D":"Incorrect because domestic startup grants target local enterprise creation, not trade bans."}}},{"id":"P1_U1_MCQ_876","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_876","question":"Over five years Farouk Footwear Ltd expanded its smartphones business in Johannesburg by reinvesting its own profits to open 4 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal (organic) growth"},"correctOption":"D","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","B":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","C":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","D":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_877","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_877","question":"Which limitation arises when measuring business size solely by the number of employees?","options":{"A":"Employee headcount cannot be counted in service businesses","B":"Employment laws prohibit firms from disclosing staff numbers","C":"Highly automated, capital-intensive firms can achieve huge output with very few employees","D":"All businesses in the same industry employ the exact same number of workers"},"correctOption":"C","correctAnswer":"Highly automated, capital-intensive firms can achieve huge output with very few employees","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital-intensive businesses rely on robotics and machinery, meaning a large-scale producer may employ relatively few workers.","distractor_reasons":{"A":"Incorrect because staff numbers are easily counted across service firms.","B":"Incorrect because disclosing employee numbers is standard practice.","C":"Option C is correct because capital-intensive businesses rely on robotics and machinery, meaning a large-scale producer may employ relatively few workers.","D":"Incorrect because workforce size varies widely among competitors."}}},{"id":"P1_U1_MCQ_878","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_878","question":"Why might the owner of a neighborhood veterinary clinic choose to keep the business small rather than expand into a national chain?","options":{"A":"Small clinics are legally exempt from paying medical supply bills","B":"National veterinary chains are prohibited by government regulation","C":"Expanding a business automatically cancels limited liability status","D":"The owner wants to avoid extra administrative workload and maintain close personal contact with clients"},"correctOption":"D","correctAnswer":"The owner wants to avoid extra administrative workload and maintain close personal contact with clients","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because owners often keep firms small to retain direct control, avoid excessive stress, and maintain personal client relationships.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because national chains operate legally.","C":"Incorrect because business growth does not revoke limited liability.","D":"Option D is correct because owners often keep firms small to retain direct control, avoid excessive stress, and maintain personal client relationships."}}},{"id":"P1_U1_MCQ_879","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_879","question":"Which action is an example of internal (organic) business growth?","options":{"A":"Developing and launching a new product range funded by retained profits","B":"Taking over a rival company in the same industry","C":"Forming a joint venture with a foreign distributor","D":"Merging with a raw material supplier"},"correctOption":"A","correctAnswer":"Developing and launching a new product range funded by retained profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal/organic growth expands the business using its own internal resources, such as developing new products or opening new branches.","distractor_reasons":{"A":"Option A is correct because internal/organic growth expands the business using its own internal resources, such as developing new products or opening new branches.","B":"Incorrect because taking over a rival is external growth.","C":"Incorrect because joint ventures are external collaborations.","D":"Incorrect because merging with a supplier is external vertical integration."}}},{"id":"P1_U1_MCQ_880","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_880","question":"Farouk Packaging Ltd, a ceramic tiles manufacturer in Melbourne, has taken over a rival firm that makes the same ceramic tiles at the same stage of production. What type of integration is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","B":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","D":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","C":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_881","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_881","question":"What does unlimited liability mean for a sole trader operating a local florist shop?","options":{"A":"The owner's financial loss is strictly limited to the initial cash invested in the shop","B":"The florist shop can sell shares to the public on a stock exchange","C":"The owner is personally responsible for all business debts, putting personal savings and assets at risk","D":"Commercial banks guarantee to cover unpaid supplier invoices if the shop closes"},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, putting personal savings and assets at risk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means there is no legal separation between the owner and the business; personal wealth can be claimed to pay business debts.","distractor_reasons":{"A":"Incorrect because capping loss to invested capital describes limited liability companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means there is no legal separation between the owner and the business; personal wealth can be claimed to pay business debts.","D":"Incorrect because banks do not guarantee business debts."}}},{"id":"P1_U1_MCQ_882","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_882","question":"Daniel Kim and Pablo Ruiz have set up a business together in Lisbon, sharing the ownership, management and profits of a computer repair service. What type of business organisation have they created?","options":{"A":"A sole trader business","B":"A public limited company","C":"A franchise","D":"A partnership"},"correctOption":"D","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","B":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","C":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","D":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_883","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_883","question":"An entrepreneur buys a franchise license to run a branded specialty coffee shop. What is a major disadvantage for this franchisee?","options":{"A":"Receiving zero training or operational guidance from the franchisor","B":"Complete absence of brand recognition among local consumers","C":"Full freedom to change menu items and store branding without permission","D":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor"},"correctOption":"D","correctAnswer":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees must pay initial license fees and regular royalties based on revenue, reducing their retained profit.","distractor_reasons":{"A":"Incorrect because franchisors supply training and ongoing operational support.","B":"Incorrect because established franchises provide immediate brand recognition.","C":"Incorrect because franchisees must follow strict brand and operational rules.","D":"Option D is correct because franchisees must pay initial license fees and regular royalties based on revenue, reducing their retained profit."}}},{"id":"P1_U1_MCQ_884","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_884","question":"Two engineering companies form a joint venture to construct a high-speed rail bridge. What is a primary advantage of forming this joint venture?","options":{"A":"A permanent merger that dissolves both original companies","B":"Sharing high capital costs, project risks, and specialized technical expertise","C":"Complete legal exemption from corporate income taxes","D":"Guaranteed absence of cultural or management disagreements"},"correctOption":"B","correctAnswer":"Sharing high capital costs, project risks, and specialized technical expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because joint ventures enable independent businesses to share capital requirements, risks, and specialist knowledge for a specific project.","distractor_reasons":{"A":"Incorrect because joint ventures are separate project collaborations where parent firms remain independent.","B":"Option B is correct because joint ventures enable independent businesses to share capital requirements, risks, and specialist knowledge for a specific project.","C":"Incorrect because joint ventures are subject to standard tax regulations.","D":"Incorrect because management conflicts between partner firms can occur."}}},{"id":"P1_U1_MCQ_885","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_885","question":"What best defines a social enterprise?","options":{"A":"A tax-funded government agency providing free public libraries","B":"A partnership established solely to maximize cash dividends for wealthy investors","C":"A business with social or environmental objectives that reinvests most of its profits to achieve those goals","D":"A commercial company that sells social media advertising"},"correctOption":"C","correctAnswer":"A business with social or environmental objectives that reinvests most of its profits to achieve those goals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social enterprises trade commercially to earn revenue and reinvest their surpluses into social or environmental missions.","distractor_reasons":{"A":"Incorrect because tax-funded government agencies are public sector organizations.","B":"Incorrect because social enterprises prioritize social impact over private wealth distribution.","C":"Option C is correct because social enterprises trade commercially to earn revenue and reinvest their surpluses into social or environmental missions.","D":"Incorrect because selling social media ads is simply a commercial digital service."}}},{"id":"P1_U1_MCQ_886","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_886","question":"Why might the partners of a growing architectural partnership decide to convert into a Private Limited Company (LTD)?","options":{"A":"To advertise and sell shares to the general public on a stock exchange","B":"To avoid the legal duty to prepare annual financial accounts","C":"To become exempt from paying corporate profits tax","D":"To gain limited liability protection for personal assets and continuity of business existence"},"correctOption":"D","correctAnswer":"To gain limited liability protection for personal assets and continuity of business existence","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures the company continues even if a shareholder leaves or dies.","distractor_reasons":{"A":"Incorrect because only PLCs can sell shares publicly on a stock exchange.","B":"Incorrect because LTDs are legally required to file annual accounts.","C":"Incorrect because LTDs must pay corporate tax on profits.","D":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures the company continues even if a shareholder leaves or dies."}}},{"id":"P1_U1_MCQ_887","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_887","question":"What does limited liability mean for shareholders of an incorporated company?","options":{"A":"Company directors must personally pay all supplier debts if the business fails","B":"Shareholders' personal homes and savings can be seized to pay company debts","C":"The company is legally excused from repaying overdue bank loans","D":"Shareholders' maximum financial loss is restricted to the amount they invested in company shares"},"correctOption":"D","correctAnswer":"Shareholders' maximum financial loss is restricted to the amount they invested in company shares","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because limited liability caps shareholders' financial liability strictly at the value of their share investment.","distractor_reasons":{"A":"Incorrect because directors are not personally liable for corporate debts unless they act fraudulently.","B":"Incorrect because personal asset seizure occurs under unlimited liability.","C":"Incorrect because the incorporated company itself remains liable for its debts.","D":"Option D is correct because limited liability caps shareholders' financial liability strictly at the value of their share investment."}}},{"id":"P1_U1_MCQ_888","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_888","question":"Which document sets out how profits and losses are shared, capital contributions, and partner duties in a business partnership?","options":{"A":"Certificate of Incorporation","B":"Deed of Partnership (Partnership Agreement)","C":"Memorandum of Association","D":"Share Prospectus"},"correctOption":"B","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a Deed of Partnership is a written agreement defining profit-sharing ratios, capital inputs, and partner responsibilities.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation legally forms a limited company.","B":"Option B is correct because a Deed of Partnership is a written agreement defining profit-sharing ratios, capital inputs, and partner responsibilities.","C":"Incorrect because Memorandum of Association is used when incorporating a company.","D":"Incorrect because a Share Prospectus invites the public to buy shares in a PLC."}}},{"id":"P1_U1_MCQ_889","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_889","question":"Which type of business organization has a separate legal identity from its owners?","options":{"A":"Sole trader","B":"Unincorporated partnership","C":"Private Limited Company (LTD)","D":"Unincorporated joint venture"},"correctOption":"C","correctAnswer":"Private Limited Company (LTD)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because incorporated companies such as LTDs are separate legal entities distinct from their shareholders.","distractor_reasons":{"A":"Incorrect because a sole trader is unincorporated and legally identical to the owner.","B":"Incorrect because an unincorporated partnership has no separate legal personality.","C":"Option C is correct because incorporated companies such as LTDs are separate legal entities distinct from their shareholders.","D":"Incorrect because unincorporated joint ventures do not create a separate legal person."}}},{"id":"P1_U1_MCQ_890","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_890","question":"What major risk does a franchisor face when allowing franchisees to operate outlets under its brand name?","options":{"A":"The franchisor permanently forfeits legal ownership of its brand trademark","B":"The franchisor must personally repay bank loans taken out by franchisees","C":"Franchisees can legally refuse to pay contractually agreed royalty fees","D":"Poor hygiene or poor customer service at one franchise outlet can damage the reputation of the entire brand"},"correctOption":"D","correctAnswer":"Poor hygiene or poor customer service at one franchise outlet can damage the reputation of the entire brand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inconsistent quality or bad service at a single franchisee location harms customer trust across the whole franchise network.","distractor_reasons":{"A":"Incorrect because the franchisor retains full ownership of the brand trademark.","B":"Incorrect because franchisees are independent businesses responsible for their own loans.","C":"Incorrect because royalty payments are legally binding under the franchise agreement.","D":"Option D is correct because inconsistent quality or bad service at a single franchisee location harms customer trust across the whole franchise network."}}},{"id":"P1_U1_MCQ_891","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_891","question":"During its first six months of trading, a new neighborhood bakery focuses on generating enough cash inflows to cover rent, ingredients, and utility bills. What business objective does this represent?","options":{"A":"Maximum dividend distribution","B":"Global market leadership","C":"Diversification into unrelated industries","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because survival is the primary objective for newly established businesses trying to cover costs in a competitive market.","distractor_reasons":{"A":"Incorrect because dividend distribution applies to established profitable companies.","B":"Incorrect because global leadership is a long-term strategic objective for large firms.","C":"Incorrect because diversification is an expansion strategy.","D":"Option D is correct because survival is the primary objective for newly established businesses trying to cover costs in a competitive market."}}},{"id":"P1_U1_MCQ_892","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_892","question":"How does achieving sustained profit growth directly benefit company shareholders?","options":{"A":"It automatically doubles hourly wage rates for factory workers","B":"It allows higher dividend payouts and increases the market value of their shares","C":"It exempts the company from paying corporate income tax","D":"It forces suppliers to reduce raw material prices"},"correctOption":"B","correctAnswer":"It allows higher dividend payouts and increases the market value of their shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher profits provide funds for shareholder dividends and boost share prices.","distractor_reasons":{"A":"Incorrect because higher profits do not automatically double worker wages.","B":"Option B is correct because higher profits provide funds for shareholder dividends and boost share prices.","C":"Incorrect because higher profits result in higher corporate tax obligations.","D":"Incorrect because company profit does not force suppliers to cut prices."}}},{"id":"P1_U1_MCQ_893","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_893","question":"Dubois Packaging Ltd, a denim clothing firm in Sao Paulo, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Market share","B":"Survival","C":"Social enterprise","D":"Profit maximisation"},"correctOption":"D","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"B":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","C":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","D":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","A":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs."}}},{"id":"P1_U1_MCQ_894","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_894","question":"Which outcome is a primary objective of employees as an internal stakeholder group?","options":{"A":"Maximizing annual dividend payouts to external shareholders","B":"Lowering retail prices for end consumers","C":"Minimizing corporate tax revenue paid to the government","D":"Fair wages, safe working conditions, and long-term job security"},"correctOption":"D","correctAnswer":"Fair wages, safe working conditions, and long-term job security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because employees seek fair pay, safe workplaces, and job stability.","distractor_reasons":{"A":"Incorrect because dividends are an objective of shareholders.","B":"Incorrect because lower retail prices are an objective of customers.","C":"Incorrect because minimizing taxes does not represent an employee objective.","D":"Option D is correct because employees seek fair pay, safe workplaces, and job stability."}}},{"id":"P1_U1_MCQ_895","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_895","question":"What is a primary objective of customers as external stakeholders of a home appliance manufacturer?","options":{"A":"Safe, reliable products sold at fair prices with good after-sales service","B":"Higher annual bonuses paid to senior company directors","C":"Increased local business rates paid by the factory","D":"Reduced workforce headcount across assembly lines"},"correctOption":"A","correctAnswer":"Safe, reliable products sold at fair prices with good after-sales service","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers want good value for money, safe and durable products, and reliable customer support.","distractor_reasons":{"A":"Option A is correct because customers want good value for money, safe and durable products, and reliable customer support.","B":"Incorrect because director bonuses do not benefit customers.","C":"Incorrect because local business taxes do not concern retail customers.","D":"Incorrect because workforce cuts are internal operational decisions."}}},{"id":"P1_U1_MCQ_896","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_896","question":"Which goal is prioritized by component suppliers to an electronics manufacturer?","options":{"A":"Maximum dividend payouts to the electronics firm's shareholders","B":"Consistent repeat orders and prompt payment within agreed credit terms","C":"Lower retail prices for the electronics firm's finished smartphones","D":"Higher municipal property taxes paid by the assembly plant"},"correctOption":"B","correctAnswer":"Consistent repeat orders and prompt payment within agreed credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because suppliers rely on steady orders and timely invoice payments to maintain healthy cash flow.","distractor_reasons":{"A":"Incorrect because dividends benefit shareholders, not suppliers.","B":"Option B is correct because suppliers rely on steady orders and timely invoice payments to maintain healthy cash flow.","C":"Incorrect because final retail pricing concerns consumers.","D":"Incorrect because municipal taxes do not benefit component suppliers."}}},{"id":"P1_U1_MCQ_897","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_897","question":"Which objective is prioritized by the local community living near a large manufacturing plant?","options":{"A":"Allowing untreated factory waste into local waterways to cut costs","B":"Maximizing share dividends paid to overseas institutional investors","C":"Local employment opportunities, safe operations, and minimal environmental pollution","D":"Replacing local workers with lower-paid overseas staff"},"correctOption":"C","correctAnswer":"Local employment opportunities, safe operations, and minimal environmental pollution","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities value local job creation, safe practices, and minimal air, water, and noise pollution.","distractor_reasons":{"A":"Incorrect because local communities strongly oppose environmental pollution.","B":"Incorrect because overseas investor dividends do not benefit local residents.","C":"Option C is correct because local communities value local job creation, safe practices, and minimal air, water, and noise pollution.","D":"Incorrect because communities prefer local job creation over offshoring."}}},{"id":"P1_U1_MCQ_898","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_898","question":"A clothing company closes its domestic factory and relocates production overseas to reduce labor costs, making 120 domestic workers redundant. Which stakeholder conflict does this illustrate?","options":{"A":"Suppliers seeking prompt payment vs Customers seeking longer warranties","B":"Government seeking tax revenue vs Community seeking quieter roads","C":"Lenders seeking loan interest vs Managers seeking company cars","D":"Shareholders seeking higher profits vs Employees seeking job security"},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits vs Employees seeking job security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cutting labor costs increases profits for shareholders but causes job losses for domestic employees.","distractor_reasons":{"A":"Incorrect because supplier payments and warranties are not the core conflict in factory relocation.","B":"Incorrect because tax revenue and road noise are not the primary issue in domestic redundancies.","C":"Incorrect because loan interest and company cars do not reflect factory closure redundancies.","D":"Option D is correct because cutting labor costs increases profits for shareholders but causes job losses for domestic employees."}}},{"id":"P1_U1_MCQ_899","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_899","question":"A parcel distribution hub extends its heavy truck loading operations to 24 hours a day to boost sales, causing nearby residents to complain about sleep disturbance. Which two stakeholder groups are in conflict?","options":{"A":"Managers/Shareholders and Local community","B":"Government and Commercial banks","C":"Raw material suppliers and Retail customers","D":"Tax inspectors and Factory workers"},"correctOption":"A","correctAnswer":"Managers/Shareholders and Local community","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because management and shareholders' goal of sales and profit growth conflicts directly with the local community's desire for a quiet living environment.","distractor_reasons":{"A":"Option A is correct because management and shareholders' goal of sales and profit growth conflicts directly with the local community's desire for a quiet living environment.","B":"Incorrect because government and banks are not the primary parties in night noise disputes.","C":"Incorrect because suppliers and customers are not in conflict over local hub noise.","D":"Incorrect because tax inspectors are unrelated to local noise disturbances."}}},{"id":"P1_U1_MCQ_900","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_900","question":"What is the best definition of a business stakeholder?","options":{"A":"An executive director who owns a majority of voting shares in a company","B":"An external auditor appointed to verify company balance sheets","C":"A government official responsible for collecting corporate value-added tax","D":"Any individual or group with a direct interest in or affected by the activities and decisions of a business"},"correctOption":"D","correctAnswer":"Any individual or group with a direct interest in or affected by the activities and decisions of a business","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a stakeholder is any person, group, or organization that has an interest in or is affected by a business's operations.","distractor_reasons":{"A":"Incorrect because majority shareholders are only one specific internal stakeholder group.","B":"Incorrect because external auditors are only one specific professional group.","C":"Incorrect because tax officials represent government, which is just one external stakeholder.","D":"Option D is correct because a stakeholder is any person, group, or organization that has an interest in or is affected by a business's operations."}}},{"id":"P1_U1_MCQ_901","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_901","question":"A furniture workshop has enough seasoned oak timber to craft either 4 dining tables or 16 dining chairs. If the carpenter decides to build 4 dining tables, what is the opportunity cost of this decision?","options":{"A":"The 16 dining chairs foregone","B":"The purchase cost of the raw oak timber","C":"The sales revenue earned from selling the 4 dining tables","D":"The electricity cost of running the workshop saws"},"correctOption":"A","correctAnswer":"The 16 dining chairs foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 16 dining chairs.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 16 dining chairs.","B":"Incorrect because timber cost is a direct material expenditure, not the foregone alternative.","C":"Incorrect because sales revenue is the return generated by the chosen option.","D":"Incorrect because workshop electricity is an operating expense."}}},{"id":"P1_U1_MCQ_902","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_902","question":"An artisan chocolatier buys cocoa ingredients for $4 and decorative gift boxes for $2 per box of truffles. The finished truffle box sells for $22. Which business action directly increases the added value per box by $5?","options":{"A":"Increasing weekly production from 300 to 700 boxes","B":"Adding a handwritten gift card service and raising the retail price to $27","C":"Reducing chocolatier hourly wages by $5 per shift","D":"Buying $5 worth of extra cocoa ingredients to store in inventory"},"correctOption":"B","correctAnswer":"Adding a handwritten gift card service and raising the retail price to $27","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because initial added value = $22 - $6 = $16. Raising the retail price to $27 with unchanged bought-in component costs increases added value to $21 ($5 increase).","distractor_reasons":{"A":"Incorrect because increasing output volume affects total profit rather than unit added value.","B":"Option B is correct because initial added value = $22 - $6 = $16. Raising the retail price to $27 with unchanged bought-in component costs increases added value to $21 ($5 increase).","C":"Incorrect because worker wages are internal labor expenses, not bought-in material costs.","D":"Incorrect because storing extra raw ingredients increases inventory assets without changing unit added value."}}},{"id":"P1_U1_MCQ_903","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_903","question":"A commercial bakery operates using wheat flour, skilled bakers, industrial deck ovens, and a risk-taking founder. Which factor of production do the industrial deck ovens represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical machinery, ovens, and equipment used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural agricultural resources.","B":"Incorrect because labour refers to the physical and mental effort of the bakers.","C":"Option C is correct because capital consists of man-made physical machinery, ovens, and equipment used in production.","D":"Incorrect because enterprise refers to the risk-taking organizational role of the founder."}}},{"id":"P1_U1_MCQ_904","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_904","question":"An electronics assembly plant assigns a technician to perform only the single task of soldering one circuit board pin for 8 hours daily. What is a primary disadvantage of division of labor in this workplace?","options":{"A":"Technicians require years of university study to solder a single pin","B":"The purchase price of circuit boards bought from suppliers increases","C":"Overall assembly line speed decreases substantially","D":"Monotonous task repetition leads to worker boredom, lower morale, and higher defect rates"},"correctOption":"D","correctAnswer":"Monotonous task repetition leads to worker boredom, lower morale, and higher defect rates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one simple task causes boredom and fatigue, reducing motivation and increasing assembly errors.","distractor_reasons":{"A":"Incorrect because narrow repetitive tasks require minimal training.","B":"Incorrect because internal division of labor does not alter supplier component prices.","C":"Incorrect because specialization typically increases production efficiency and speed.","D":"Option D is correct because repeating one simple task causes boredom and fatigue, reducing motivation and increasing assembly errors."}}},{"id":"P1_U1_MCQ_905","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_905","question":"At Sharma Plastics Ltd in Lisbon, each worker repeatedly performs just one small step in making denim clothing instead of every worker making a complete product. What is this way of organising production called?","options":{"A":"Division of labour (specialisation)","B":"Mechanisation","C":"Delegation","D":"Vertical integration"},"correctOption":"A","correctAnswer":"Division of labour (specialisation)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because division of labour splits the production process into separate tasks so that each worker specialises in one task, raising output.","distractor_reasons":{"B":"Mechanisation means using machines instead of human effort; the scenario describes workers specialising in tasks, not replacing them with machines.","C":"Delegation is a manager handing authority to a subordinate; it concerns authority in the hierarchy, not the splitting of a production process into tasks.","D":"Vertical integration is a growth strategy of owning different stages of the supply chain, which is unrelated to how workers are allocated to tasks.","A":"Option is correct because division of labour splits the production process into separate tasks so that each worker specialises in one task, raising output."}}},{"id":"P1_U1_MCQ_906","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_906","question":"A timber farmer in Jakarta sells raw timber to a processor for $80 per crate. The processor cleans, grades and packages it and sells the finished product for $120 per crate. What is the increase in worth created by these stages called?","options":{"A":"Opportunity cost","B":"Economies of scale","C":"Division of labour","D":"Adding value"},"correctOption":"D","correctAnswer":"Adding value","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because adding value is the increase in a product's worth from one stage of production to the next; here value rises from $80 to $120.","distractor_reasons":{"A":"Opportunity cost is the next best alternative foregone in a decision, not the increase in a product value as it passes through production stages.","B":"Economies of scale refer to falling average costs as output rises, which is a cost phenomenon and not the extra worth built into a product.","C":"Division of labour is the splitting of work into specialised tasks; it may help create value but it is not the name for the increase in worth itself.","D":"Option is correct because adding value is the increase in a product's worth from one stage of production to the next; here value rises from $80 to $120."}}},{"id":"P1_U1_MCQ_907","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_907","question":"A leather goods workshop buys cowhide leather for $18 and brass buckles for $4 per satchel. The finished satchel sells for $65. What is the added value per satchel?","options":{"A":"$22","B":"$47","C":"$43","D":"$65"},"correctOption":"C","correctAnswer":"$43","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in material costs = $18 + $4 = $22. Added value = selling price ($65) - material costs ($22) = $43.","distractor_reasons":{"A":"Incorrect because $22 is total bought-in material cost.","B":"Incorrect because $47 subtracts only leather cost ($65 - $18), ignoring brass buckles.","C":"Option C is correct because total bought-in material costs = $18 + $4 = $22. Added value = selling price ($65) - material costs ($22) = $43.","D":"Incorrect because $65 is the final selling price."}}},{"id":"P1_U1_MCQ_908","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_908","question":"A marketing director resigns from a salaried position earning $80,000 per year to launch an independent digital advertising agency. What is the opportunity cost of starting this agency?","options":{"A":"The annual rent paid for the agency studio","B":"The client retainer revenue earned during Year 1","C":"The capital spent purchasing video editing computers","D":"The $80,000 salary foregone from the previous marketing job"},"correctOption":"D","correctAnswer":"The $80,000 salary foregone from the previous marketing job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $80,000 salary.","distractor_reasons":{"A":"Incorrect because studio rent is an explicit operating expense.","B":"Incorrect because client retainers represent revenue from the chosen venture.","C":"Incorrect because computer purchases are capital expenditures.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $80,000 salary."}}},{"id":"P1_U1_MCQ_909","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_909","question":"Which factor of production includes natural assets such as crude oil reserves, fertile agricultural soil, and wind energy resources?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural resources provided by nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural resources provided by nature used in economic production.","B":"Incorrect because labour represents human physical and mental effort.","C":"Incorrect because capital represents man-made equipment and machinery.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_910","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_910","question":"How can a smartwatch manufacturer directly increase the added value of its watches without increasing retail selling prices?","options":{"A":"Increasing spending on television advertising campaigns","B":"Negotiating lower component costs for OLED touchscreens from suppliers","C":"Raising hourly wage rates paid to assembly technicians","D":"Leasing a larger regional warehouse facility"},"correctOption":"B","correctAnswer":"Negotiating lower component costs for OLED touchscreens from suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering component costs widens this margin.","distractor_reasons":{"A":"Incorrect because television advertising is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in component costs. Lowering component costs widens this margin.","C":"Incorrect because higher technician wages increase operating expenses, lowering profit margin rather than unit added value.","D":"Incorrect because warehouse leasing increases overhead costs."}}},{"id":"P1_U1_MCQ_911","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_911","question":"Which business activity is classified under the primary sector of an economy?","options":{"A":"Refining crude petroleum into aviation fuel","B":"Providing marine engineering consultancy services","C":"Extracting crude oil from offshore drilling rigs","D":"Operating a network of roadside petrol stations"},"correctOption":"C","correctAnswer":"Extracting crude oil from offshore drilling rigs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extracting crude oil involves direct extraction of natural resources from the earth (primary sector).","distractor_reasons":{"A":"Incorrect because refining petroleum is secondary manufacturing.","B":"Incorrect because engineering consultancy is a tertiary service.","C":"Option C is correct because extracting crude oil involves direct extraction of natural resources from the earth (primary sector).","D":"Incorrect because petrol station retail is a tertiary distribution service."}}},{"id":"P1_U1_MCQ_912","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_912","question":"What structural shift occurs when a developed economy experiences deindustrialization?","options":{"A":"Workers move out of software services into subsistence farming","B":"The central government takes ownership of all private factories","C":"Manufacturing employment rises sharply while service sector jobs disappear","D":"Secondary manufacturing declines in relative importance while tertiary services expand"},"correctOption":"D","correctAnswer":"Secondary manufacturing declines in relative importance while tertiary services expand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative contraction in secondary manufacturing alongside growth in tertiary service industries.","distractor_reasons":{"A":"Incorrect because primary sector employment does not expand during deindustrialization.","B":"Incorrect because deindustrialization reflects sectoral change, not state ownership.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative contraction in secondary manufacturing alongside growth in tertiary service industries."}}},{"id":"P1_U1_MCQ_913","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_913","question":"Over the past decade the economy around Dublin has moved workers out of farming and into new factories producing school backpacks, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Specialisation","B":"Industrialisation","C":"Deindustrialisation","D":"Privatisation"},"correctOption":"B","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"A":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","C":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","D":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","B":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_914","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_914","question":"A wheat farm harvests grain, a flour mill grinds the grain into flour, and a commercial bakery bakes the flour into bread loaves. How are these three businesses classified?","options":{"A":"Wheat farm: Secondary; Flour mill: Primary; Commercial bakery: Tertiary","B":"Wheat farm: Primary; Flour mill: Secondary; Commercial bakery: Secondary","C":"Wheat farm: Primary; Flour mill: Tertiary; Commercial bakery: Secondary","D":"Wheat farm: Tertiary; Flour mill: Secondary; Commercial bakery: Primary"},"correctOption":"B","correctAnswer":"Wheat farm: Primary; Flour mill: Secondary; Commercial bakery: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because harvesting wheat is primary agriculture, while milling flour and baking bread both process raw inputs into manufactured goods (secondary sector).","distractor_reasons":{"A":"Incorrect because wheat farming is primary extraction, not secondary.","B":"Option B is correct because harvesting wheat is primary agriculture, while milling flour and baking bread both process raw inputs into manufactured goods (secondary sector).","C":"Incorrect because a flour mill is secondary manufacturing, not tertiary service.","D":"Incorrect because sector classifications are reversed."}}},{"id":"P1_U1_MCQ_915","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_915","question":"In Kuala Lumpur, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Deindustrialisation","B":"Primary sector growth","C":"Division of labour","D":"Industrialisation"},"correctOption":"A","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"B":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","C":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","D":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","A":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_916","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_916","question":"A national government owns and operates a home cleaning service in Dubai in order to provide a public service for citizens. Which sector of the economy does this organisation belong to?","options":{"A":"Private sector","B":"Public sector","C":"Secondary sector","D":"Primary sector"},"correctOption":"B","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned and run by the government, which defines the public sector.","distractor_reasons":{"A":"The private sector consists of businesses owned by private individuals or shareholders; this organisation is not privately owned.","C":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","D":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","B":"Option is correct because the organisation is owned and run by the government, which defines the public sector."}}},{"id":"P1_U1_MCQ_917","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_917","question":"In Warsaw, 45% of workers are employed in the primary sector, 10% in the secondary sector and 25% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Secondary sector","B":"Public sector","C":"Tertiary sector","D":"Primary sector"},"correctOption":"D","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"The primary sector employs 45% of workers, which is lower than the largest share of 45%, so it does not employ the most workers.","distractor_reasons":{"A":"The secondary sector employs 10% of workers, which is lower than the largest share of 45%, so it does not employ the most workers.","B":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","C":"The tertiary sector employs 25% of workers, the largest share of the three sectors, so it employs the most workers.","D":"The primary sector employs 45% of workers, which is lower than the largest share of 45%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_918","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_918","question":"Why might a government choose to privatize a state-owned telecommunications provider?","options":{"A":"To turn telecom engineers into government civil servants","B":"To encourage market competition, attract private investment, and raise operational efficiency","C":"To prevent private investors from funding mobile network upgrades","D":"To strengthen direct ministerial control over consumer phone tariffs"},"correctOption":"B","correctAnswer":"To encourage market competition, attract private investment, and raise operational efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private ownership, introducing profit incentives and competition that boost efficiency and raise funds.","distractor_reasons":{"A":"Incorrect because privatized workers leave government employment.","B":"Option B is correct because privatization transfers state assets to private ownership, introducing profit incentives and competition that boost efficiency and raise funds.","C":"Incorrect because privatization attracts private capital investment.","D":"Incorrect because privatization reduces direct government control over pricing."}}},{"id":"P1_U1_MCQ_919","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_919","question":"A state-owned organisation in Toronto provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To provide a service to the community rather than to maximise profit.","B":"To maximise profit for its private shareholders.","C":"To increase the wealth of the governments individual ministers.","D":"To extract and sell as many natural resources as possible."},"correctOption":"A","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"B":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","C":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","D":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","A":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_920","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_920","question":"Which sector of the economy does this activity belong to? A privately owned factory in Manila turns raw materials into canned tomatoes.","options":{"A":"Tertiary sector","B":"Secondary sector","C":"Public sector","D":"Primary sector"},"correctOption":"B","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it.","distractor_reasons":{"A":"The tertiary sector involves providing services to customers; the described activity is not a service provision.","C":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","D":"The primary sector involves extracting natural resources and farming; the described activity is not extraction or farming.","B":"Option is correct because the secondary sector manufactures goods by processing raw materials, so factory production of goods belongs to it."}}},{"id":"P1_U1_MCQ_921","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_921","question":"Which characteristic is essential for an entrepreneur launching a new commercial enterprise?","options":{"A":"Innovation, willingness to take calculated risks, and determination when facing challenges","B":"Preference for following routine instructions from senior corporate managers","C":"Unwillingness to adjust products when consumer demand shifts","D":"Avoidance of financial accountability for startup decisions"},"correctOption":"A","correctAnswer":"Innovation, willingness to take calculated risks, and determination when facing challenges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require innovation, calculated risk-taking, and determination to overcome early startup hurdles.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require innovation, calculated risk-taking, and determination to overcome early startup hurdles.","B":"Incorrect because entrepreneurs lead independent businesses.","C":"Incorrect because adaptability is essential for startup survival.","D":"Incorrect because entrepreneurs assume accountability for their decisions."}}},{"id":"P1_U1_MCQ_922","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_922","question":"Why is preparing a well-structured business plan valuable when a startup approaches a bank for a loan?","options":{"A":"It automatically grants limited liability status without legal incorporation","B":"It guarantees that the startup will achieve profitability in its first year","C":"It sets out cash flow forecasts and market analysis demonstrating the firm's ability to repay debt","D":"It exempts the business from statutory tax obligations"},"correctOption":"C","correctAnswer":"It sets out cash flow forecasts and market analysis demonstrating the firm's ability to repay debt","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lenders review cash flow forecasts and market research in a business plan to evaluate default risk and repayment ability.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot grant.","B":"Incorrect because business plans contain projections, not profit guarantees.","C":"Option C is correct because lenders review cash flow forecasts and market research in a business plan to evaluate default risk and repayment ability.","D":"Incorrect because tax obligations are governed by law, not business plans."}}},{"id":"P1_U1_MCQ_923","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_923","question":"A bottled water manufacturer in Dublin, Boateng Textiles Ltd, has bought a chain of retail shops that sells its finished products straight to the public. What type of integration is this?","options":{"A":"Backward vertical integration","B":"Internal growth","C":"Horizontal integration","D":"Forward vertical integration"},"correctOption":"D","correctAnswer":"Forward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain.","distractor_reasons":{"A":"Backward vertical integration means taking over a supplier nearer the raw material stage, whereas retail shops are nearer the final customer.","B":"Internal growth relies on the firm expanding its own operations, but here growth happened through acquiring another business.","C":"Horizontal integration is joining a competitor at the same production stage; a retailer is at a different, downstream stage of the chain.","D":"Option is correct because forward vertical integration is acquiring a business nearer the consumer, such as a retailer, in the same supply chain."}}},{"id":"P1_U1_MCQ_924","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_924","question":"Costa Furniture Ltd, a chocolate bars producer in Bristol, has purchased a raw material supplier that previously supplied its raw materials. What type of integration is this?","options":{"A":"Horizontal integration","B":"Backward vertical integration","C":"Internal growth","D":"Forward vertical integration"},"correctOption":"B","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself.","distractor_reasons":{"A":"Horizontal integration means joining a competing firm at the same stage of production, not acquiring a firm that supplies raw materials.","C":"Internal growth means expanding using the firms own resources, but this business grew through the acquisition of a supplier.","D":"Forward vertical integration is moving towards the final customer, such as buying a retailer, whereas a supplier is at the opposite end of the chain.","B":"Option is correct because backward vertical integration is taking over a supplier at an earlier stage of the supply chain than the firm itself."}}},{"id":"P1_U1_MCQ_925","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_925","question":"Why do governments provide advisory services and startup grants to newly formed small businesses?","options":{"A":"To reduce unemployment, encourage innovation, and boost national economic output","B":"To eliminate competition for state-owned monopolies","C":"To compel small firms to list shares on the national stock exchange","D":"To prevent foreign companies from exporting goods"},"correctOption":"A","correctAnswer":"To reduce unemployment, encourage innovation, and boost national economic output","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because supporting new startups generates jobs, stimulates innovation, and expands economic growth.","distractor_reasons":{"A":"Option A is correct because supporting new startups generates jobs, stimulates innovation, and expands economic growth.","B":"Incorrect because startup support promotes market competition rather than eliminating it.","C":"Incorrect because grants do not force stock exchange listing.","D":"Incorrect because domestic startup grants target local enterprise creation, not import bans."}}},{"id":"P1_U1_MCQ_926","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_926","question":"After a period of very rapid expansion, Patel Packaging Ltd in Shanghai found that messages were delayed, decisions took much longer and senior managers struggled to coordinate the growing cement business. Which problem of growth does this illustrate?","options":{"A":"A reduction in the number of competitors in the market.","B":"Higher staff morale throughout the workforce.","C":"Loss of control and coordination difficulties as the business becomes larger.","D":"Lower average costs from economies of scale."},"correctOption":"C","correctAnswer":"Loss of control and coordination difficulties as the business becomes larger.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations.","distractor_reasons":{"A":"The number of competitors is a market condition and does not explain the internal communication and control difficulties described.","B":"Higher morale is a positive outcome and is not shown by delayed messages and managers struggling to coordinate a larger business.","D":"Economies of scale reduce average costs and are a benefit of growth, not the communication and coordination problems described here.","C":"Option is correct because rapid growth can stretch communication and management systems, leading to poor coordination and loss of control over operations."}}},{"id":"P1_U1_MCQ_927","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_927","question":"Which limitation arises when measuring business size solely by the value of capital employed?","options":{"A":"Capital employed cannot be calculated for manufacturing businesses","B":"Accounting rules prohibit businesses from reporting capital employed","C":"Labor-intensive service firms can employ large workforces and earn high revenue with relatively little physical capital","D":"All companies in an economy employ the exact same amount of capital"},"correctOption":"C","correctAnswer":"Labor-intensive service firms can employ large workforces and earn high revenue with relatively little physical capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because labor-intensive businesses (such as software consultancies or cleaning agencies) require minimal expensive machinery, making them appear small on a capital employed metric despite large staff numbers.","distractor_reasons":{"A":"Incorrect because capital employed is routinely calculated for manufacturers.","B":"Incorrect because reporting capital employed is standard accounting practice.","C":"Option C is correct because labor-intensive businesses (such as software consultancies or cleaning agencies) require minimal expensive machinery, making them appear small on a capital employed metric despite large staff numbers.","D":"Incorrect because capital intensity varies widely across firms and industries."}}},{"id":"P1_U1_MCQ_928","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_928","question":"Why might the owner of a bespoke tailoring shop prefer to keep the business small rather than expand into a nationwide clothing chain?","options":{"A":"Small tailoring shops are legally exempt from paying fabric supplier bills","B":"Nationwide clothing chains are prohibited by government law","C":"Expanding a business automatically revokes limited liability protection","D":"The owner wants to retain direct personal control and provide personalized customer service"},"correctOption":"D","correctAnswer":"The owner wants to retain direct personal control and provide personalized customer service","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because owners often keep firms small to maintain direct operational control, avoid excessive workload, and preserve close customer relationships.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because nationwide retail chains operate legally.","C":"Incorrect because business expansion does not revoke limited liability.","D":"Option D is correct because owners often keep firms small to maintain direct operational control, avoid excessive workload, and preserve close customer relationships."}}},{"id":"P1_U1_MCQ_929","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_929","question":"Boateng Electronics Ltd, a bicycles firm in Nairobi, stopped trading even though it was making sales, because it could not pay its suppliers and had too little cash to keep operating. What was the most likely cause of failure?","options":{"A":"Over-regulation of the market by the government.","B":"Excessive profitability that attracted too much competition.","C":"A shortage of customer demand for its products.","D":"Cash flow problems, leaving it unable to pay debts as they fell due."},"correctOption":"D","correctAnswer":"Cash flow problems, leaving it unable to pay debts as they fell due.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers.","distractor_reasons":{"A":"The scenario gives no evidence of regulation; the immediate problem described is an inability to pay suppliers from available cash.","B":"High profits would help a business survive rather than cause failure, and the scenario points to a shortage of cash, not excess profit.","C":"The firm was making sales, so weak demand is not the cause; the problem was its inability to pay debts despite those sales.","D":"Option is correct because a profitable-looking business can still fail if it runs out of cash and cannot meet its short-term obligations to suppliers."}}},{"id":"P1_U1_MCQ_930","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_930","question":"Ahmed Nasser noticed a gap in the local market in Johannesburg, invested personal savings, took the financial risk and set up a new business making furniture. Which role is Ahmed carrying out?","options":{"A":"An employee","B":"A trade union official","C":"A shareholder only","D":"An entrepreneur"},"correctOption":"D","correctAnswer":"An entrepreneur","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture.","distractor_reasons":{"A":"An employee is hired to work for a business and does not bear the financial risk or own the new venture being set up.","B":"A trade union official represents employees in negotiations with employers, which is unrelated to founding and risking a new business.","C":"A shareholder merely owns shares; the scenario describes someone who actively organised and took the risk of creating the business.","D":"Option is correct because an entrepreneur identifies a business opportunity, organises resources and takes the financial risk of starting a new venture."}}},{"id":"P1_U1_MCQ_931","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_931","question":"What does unlimited liability mean for a sole trader operating a bicycle repair shop?","options":{"A":"The owner's financial loss is strictly capped at the initial capital invested in tools","B":"The repair shop can issue shares to the public on a stock exchange","C":"The owner is personally liable for all business debts, putting personal savings and property at risk","D":"Commercial banks guarantee to pay off unpaid supplier bills if the shop closes"},"correctOption":"C","correctAnswer":"The owner is personally liable for all business debts, putting personal savings and property at risk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means there is no legal separation between the sole trader and the business; personal assets can be claimed to settle business debts.","distractor_reasons":{"A":"Incorrect because capping loss to invested capital describes limited liability companies.","B":"Incorrect because sole traders cannot sell public shares.","C":"Option C is correct because unlimited liability means there is no legal separation between the sole trader and the business; personal assets can be claimed to settle business debts.","D":"Incorrect because banks do not guarantee business debts."}}},{"id":"P1_U1_MCQ_932","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_932","question":"Singh Dairy Ltd is a privately owned laptops company in Kampala. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A sole trader","B":"A public limited company (Plc)","C":"A partnership","D":"A private limited company (Ltd)"},"correctOption":"D","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","B":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","C":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","D":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_933","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_933","question":"An entrepreneur buys a franchise license to operate a branded quick-service smoothie bar. What is a major drawback for this franchisee?","options":{"A":"Total freedom to alter recipes and store branding without franchisor consent","B":"Complete lack of brand awareness among local consumers","C":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor","D":"Receiving zero staff training or operational guidance from the franchisor"},"correctOption":"C","correctAnswer":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because franchisees must pay initial license fees and ongoing revenue-based royalties, which reduce retained net profit.","distractor_reasons":{"A":"Incorrect because franchisees must follow strict brand and recipe standards.","B":"Incorrect because established franchises offer strong brand awareness.","C":"Option C is correct because franchisees must pay initial license fees and ongoing revenue-based royalties, which reduce retained net profit.","D":"Incorrect because franchisors provide training and ongoing operational support."}}},{"id":"P1_U1_MCQ_934","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_934","question":"Two renewable energy firms form a joint venture to construct an offshore wind farm. What is a primary benefit of forming this joint venture?","options":{"A":"A permanent merger that dissolves both parent corporations","B":"Sharing high capital costs, project risks, and specialized engineering expertise","C":"Complete legal exemption from paying national corporate taxes","D":"Guaranteed elimination of management disagreements between partner teams"},"correctOption":"B","correctAnswer":"Sharing high capital costs, project risks, and specialized engineering expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because joint ventures allow independent firms to pool capital, share risks, and combine specialist knowledge for a specific project.","distractor_reasons":{"A":"Incorrect because joint ventures are separate collaborations where parent firms remain independent.","B":"Option B is correct because joint ventures allow independent firms to pool capital, share risks, and combine specialist knowledge for a specific project.","C":"Incorrect because joint ventures are subject to standard tax laws.","D":"Incorrect because management disagreements between partner firms can still arise."}}},{"id":"P1_U1_MCQ_935","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_935","question":"A large laptops business in Lagos, Mwangi Footwear Ltd, has shares that are traded on a stock exchange and can be bought by members of the general public. What type of company is it?","options":{"A":"A private limited company (Ltd)","B":"A sole trader","C":"A partnership","D":"A public limited company (Plc)"},"correctOption":"D","correctAnswer":"A public limited company (Plc)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange.","distractor_reasons":{"A":"A private limited company cannot offer its shares to the general public, so it cannot have shares traded on a stock exchange.","B":"A sole trader is a single owner with unlimited liability and cannot issue shares that are traded on a stock exchange.","C":"A partnership is an unincorporated business owned by several people and does not have publicly traded shares.","D":"Option is correct because a public limited company is a separate legal entity whose shares may be sold to the public on a stock exchange."}}},{"id":"P1_U1_MCQ_936","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_936","question":"Why might the partners of an expanding software consultancy partnership decide to convert into a Private Limited Company (LTD)?","options":{"A":"To sell shares openly to the general public on a stock exchange","B":"To avoid the legal requirement to maintain annual financial accounts","C":"To become exempt from paying corporate profits tax","D":"To gain limited liability protection for personal assets and continuity of business existence"},"correctOption":"D","correctAnswer":"To gain limited liability protection for personal assets and continuity of business existence","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures business continuity if a shareholder leaves or dies.","distractor_reasons":{"A":"Incorrect because only PLCs can sell shares publicly on a stock exchange.","B":"Incorrect because LTDs are legally required to prepare and file annual accounts.","C":"Incorrect because LTDs must pay corporate tax on profits.","D":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures business continuity if a shareholder leaves or dies."}}},{"id":"P1_U1_MCQ_937","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_937","question":"Marcus Johnson pays an upfront fee and regular royalties to a well-known furniture brand for the right to trade under its name in Sao Paulo and follow its established business system. What is this arrangement called?","options":{"A":"A joint venture","B":"A public corporation","C":"A takeover","D":"A franchise"},"correctOption":"D","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model.","distractor_reasons":{"A":"A joint venture is a new business jointly owned by two or more firms sharing control, not a single owner paying to use an established brand.","B":"A public corporation is a government-owned organisation, whereas the scenario describes a private individual buying into a brand system.","C":"A takeover is one firm buying control of another; here the person is paying for the right to use a brand, not buying the brand owner.","D":"Option is correct because franchising is where a franchisee pays a fee and royalties to a franchisor to use its brand name and business model."}}},{"id":"P1_U1_MCQ_938","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_938","question":"Which document specifies profit-sharing ratios, capital inputs, and partner responsibilities in a business partnership?","options":{"A":"Certificate of Incorporation","B":"Share Prospectus","C":"Memorandum of Association","D":"Deed of Partnership (Partnership Agreement)"},"correctOption":"D","correctAnswer":"Deed of Partnership (Partnership Agreement)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a Deed of Partnership is a formal agreement defining profit-sharing ratios, capital contributions, and partner duties.","distractor_reasons":{"A":"Incorrect because a Certificate of Incorporation legally registers a limited company.","B":"Incorrect because a Share Prospectus invites the public to buy shares in a PLC.","C":"Incorrect because Memorandum of Association is used when incorporating a company.","D":"Option D is correct because a Deed of Partnership is a formal agreement defining profit-sharing ratios, capital contributions, and partner duties."}}},{"id":"P1_U1_MCQ_939","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_939","question":"Which type of business organization possesses a separate legal identity from its owners?","options":{"A":"Sole trader","B":"Unincorporated partnership","C":"Public Limited Company (PLC)","D":"Unincorporated joint venture"},"correctOption":"C","correctAnswer":"Public Limited Company (PLC)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because incorporated companies such as PLCs are separate legal persons distinct from their shareholders.","distractor_reasons":{"A":"Incorrect because a sole trader is unincorporated and legally identical to the owner.","B":"Incorrect because an unincorporated partnership has no separate legal identity.","C":"Option C is correct because incorporated companies such as PLCs are separate legal persons distinct from their shareholders.","D":"Incorrect because unincorporated joint ventures do not create a separate legal entity."}}},{"id":"P1_U1_MCQ_940","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_940","question":"What major risk does a franchisor face when licensing franchisees to operate outlets under its brand name?","options":{"A":"The franchisor permanently forfeits legal ownership of its brand trademark","B":"The franchisor must personally repay bank loans taken out by franchisees","C":"Franchisees can legally refuse to pay contractually agreed royalty fees","D":"Poor product quality or poor customer service at one franchise branch can harm the reputation of the entire brand"},"correctOption":"D","correctAnswer":"Poor product quality or poor customer service at one franchise branch can harm the reputation of the entire brand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because substandard quality or poor service at a single franchisee location damages customer trust across the whole franchise brand.","distractor_reasons":{"A":"Incorrect because the franchisor retains full ownership of the brand trademark.","B":"Incorrect because franchisees are independent businesses responsible for their own debts.","C":"Incorrect because royalty payments are legally binding under the franchise contract.","D":"Option D is correct because substandard quality or poor service at a single franchisee location damages customer trust across the whole franchise brand."}}},{"id":"P1_U1_MCQ_941","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_941","question":"During a severe downturn in Shanghai, Tanaka Auto Parts Ltd concentrates on covering its costs and staying in business rather than earning high profits. Which objective is the business pursuing?","options":{"A":"Market share","B":"Growth","C":"Profit maximisation","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","distractor_reasons":{"A":"Market share concerns a firms share of industry sales and does not describe simply covering costs to continue trading.","C":"Profit maximisation seeks the largest possible profit, whereas this firm is satisfied with covering costs to remain in business.","D":"Option is correct because a survival objective means covering costs and continuing to trade, especially during difficult market conditions.","B":"A growth objective involves expanding sales or output, not the defensive aim of covering costs during a downturn."}}},{"id":"P1_U1_MCQ_942","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_942","question":"How does achieving sustained net profit growth directly benefit company shareholders?","options":{"A":"It automatically doubles hourly wage rates for assembly workers","B":"It supports higher dividend payouts and increases the market value of their shares","C":"It exempts the company from paying corporate income tax","D":"It forces raw material suppliers to lower their prices"},"correctOption":"B","correctAnswer":"It supports higher dividend payouts and increases the market value of their shares","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher profits provide funds for shareholder dividends and drive up share prices.","distractor_reasons":{"A":"Incorrect because higher profits do not automatically double worker wages.","B":"Option B is correct because higher profits provide funds for shareholder dividends and drive up share prices.","C":"Incorrect because higher profits lead to higher corporate tax liabilities.","D":"Incorrect because company profit does not force suppliers to cut prices."}}},{"id":"P1_U1_MCQ_943","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_943","question":"An athletic footwear brand sells 15 million pairs of shoes in a market where total industry sales equal 60 million pairs. What is the company's market share?","options":{"A":"15%","B":"60%","C":"25%","D":"75%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share = (company sales / total market sales) * 100 = (15 million / 60 million) * 100 = 25%.","distractor_reasons":{"A":"Incorrect because 15 million is the unit sales volume, not the percentage market share.","B":"Incorrect because 60 million is total industry sales volume.","C":"Option C is correct because market share = (company sales / total market sales) * 100 = (15 million / 60 million) * 100 = 25%.","D":"Incorrect because 75% represents the combined market share of all rival brands."}}},{"id":"P1_U1_MCQ_944","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_944","question":"Osei Steel Ltd in Bogota has set itself the target of increasing its sales revenue and the number of its outlets every year. Which objective is this?","options":{"A":"Social enterprise","B":"Survival","C":"Profit maximisation","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets.","distractor_reasons":{"A":"A social enterprise focuses on social goals and community benefit rather than on expanding sales and the number of outlets.","B":"Survival is about staying in business by covering costs, not about increasing sales revenue and opening more outlets.","C":"Profit maximisation focuses on the gap between revenue and costs, not simply on expanding the size of sales and operations.","D":"Option is correct because a growth objective aims to increase the scale of the business, such as its sales revenue or number of outlets."}}},{"id":"P1_U1_MCQ_945","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_945","question":"What is a primary objective of customers as external stakeholders of a consumer electronics manufacturer?","options":{"A":"Increased local property taxes paid by the assembly plant","B":"Higher annual bonuses paid to senior company executives","C":"Reliable, high-quality products sold at fair prices with dependable after-sales support","D":"Reduced staff headcount across manufacturing lines"},"correctOption":"C","correctAnswer":"Reliable, high-quality products sold at fair prices with dependable after-sales support","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customers seek good value for money, reliable product quality, and responsive customer service.","distractor_reasons":{"A":"Incorrect because local property taxes do not concern retail customers.","B":"Incorrect because executive bonuses do not benefit customers.","C":"Option C is correct because customers seek good value for money, reliable product quality, and responsive customer service.","D":"Incorrect because workforce reductions are internal operational decisions."}}},{"id":"P1_U1_MCQ_946","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_946","question":"Which goal is prioritized by packaging suppliers to a food processing company?","options":{"A":"Maximum dividend payouts to the food processor's shareholders","B":"Consistent repeat orders and prompt payment within agreed credit terms","C":"Lower supermarket retail prices for the food processor's finished meals","D":"Higher municipal business taxes paid by the food factory"},"correctOption":"B","correctAnswer":"Consistent repeat orders and prompt payment within agreed credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because suppliers rely on regular repeat orders and timely invoice settlement to maintain strong cash flow.","distractor_reasons":{"A":"Incorrect because dividends benefit shareholders, not suppliers.","B":"Option B is correct because suppliers rely on regular repeat orders and timely invoice settlement to maintain strong cash flow.","C":"Incorrect because final supermarket pricing concerns consumers.","D":"Incorrect because municipal taxes do not benefit packaging suppliers."}}},{"id":"P1_U1_MCQ_947","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_947","question":"Which objective is prioritized by the local community residing near a large industrial park?","options":{"A":"Allowing untreated industrial waste into local rivers to reduce firm costs","B":"Maximizing share dividends paid to overseas institutional investors","C":"Local employment opportunities, safe operations, and minimal environmental pollution","D":"Replacing local employees with lower-paid overseas workers"},"correctOption":"C","correctAnswer":"Local employment opportunities, safe operations, and minimal environmental pollution","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities value local job creation, safe operations, and minimal air, water, and noise pollution.","distractor_reasons":{"A":"Incorrect because local communities strongly oppose environmental pollution.","B":"Incorrect because overseas investor dividends do not benefit local residents.","C":"Option C is correct because local communities value local job creation, safe operations, and minimal air, water, and noise pollution.","D":"Incorrect because communities prefer local job creation over offshoring."}}},{"id":"P1_U1_MCQ_948","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_948","question":"A paper mill discharges untreated chemical wastewater into a nearby river to cut disposal costs and raise profits, sparking protests from local residents. Which stakeholder conflict does this illustrate?","options":{"A":"Suppliers seeking prompt payment vs Customers seeking longer warranties","B":"Government seeking tax revenue vs Bank lenders seeking loan interest","C":"Lenders seeking debt repayment vs Employees seeking flexible hours","D":"Shareholders seeking higher profits vs Local community seeking environmental protection"},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits vs Local community seeking environmental protection","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cutting waste treatment costs increases profits for shareholders but harms the local community's environment and health.","distractor_reasons":{"A":"Incorrect because supplier payments and warranties are unrelated to river pollution.","B":"Incorrect because tax revenue and loan interest do not represent the environmental dispute.","C":"Incorrect because debt repayment and flexible hours do not reflect wastewater pollution.","D":"Option D is correct because cutting waste treatment costs increases profits for shareholders but harms the local community's environment and health."}}},{"id":"P1_U1_MCQ_949","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_949","question":"An online retailer introduces mandatory unpaid overtime shifts to speed up order dispatch and grow sales, leading warehouse workers to strike. Which two stakeholder groups are in conflict?","options":{"A":"Managers/Shareholders and Employees","B":"Government and Commercial banks","C":"Raw material suppliers and Retail customers","D":"Tax authorities and Local residents"},"correctOption":"A","correctAnswer":"Managers/Shareholders and Employees","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because management and shareholders' goal of sales and profit growth conflicts directly with employees' desire for fair pay and reasonable working conditions.","distractor_reasons":{"A":"Option A is correct because management and shareholders' goal of sales and profit growth conflicts directly with employees' desire for fair pay and reasonable working conditions.","B":"Incorrect because government and banks are not the parties involved in warehouse labor disputes.","C":"Incorrect because suppliers and customers are not the primary conflicting parties in this strike.","D":"Incorrect because tax authorities and local residents are unrelated to internal overtime policies."}}},{"id":"P1_U1_MCQ_950","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_950","question":"Singh Glassware Ltd wants to increase the proportion of total sales in the LED bulbs market in Dublin that it captures for itself. Which objective is this?","options":{"A":"Survival","B":"Cost minimisation","C":"Social enterprise","D":"Increasing market share"},"correctOption":"D","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective.","distractor_reasons":{"A":"Survival means covering costs to continue trading; it does not involve trying to raise the firms share of market sales.","B":"Cost minimisation is about reducing expenses, not about increasing the proportion of total market sales a firm achieves.","C":"A social enterprise pursues community and social goals rather than increasing its share of a commercial market.","D":"Option is correct because market share is the proportion of total market sales achieved by one firm, so raising it is a market share objective."}}},{"id":"P1_U1_MCQ_951","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_951","question":"A printing press has enough recycled paper stock to print either 500 hardcover novels or 2,000 paperback magazines. If the publisher decides to print 500 hardcover novels, what is the opportunity cost of this decision?","options":{"A":"The 2,000 paperback magazines foregone","B":"The purchase cost of the recycled paper stock","C":"The sales revenue earned from selling the 500 hardcover novels","D":"The electricity cost of operating the printing presses"},"correctOption":"A","correctAnswer":"The 2,000 paperback magazines foregone","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 2,000 paperback magazines.","distractor_reasons":{"A":"Option A is correct because opportunity cost is the next best alternative given up when making a choice, which is the 2,000 paperback magazines.","B":"Incorrect because paper stock cost is a direct material expenditure, not the foregone alternative.","C":"Incorrect because sales revenue is the financial return from the chosen option.","D":"Incorrect because press electricity is an operating expense."}}},{"id":"P1_U1_MCQ_952","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_952","question":"A candle maker buys soy wax for $2 and essential fragrance oil for $1 per candle. The finished candle sells for $14. Which business action directly increases the added value per candle by $4?","options":{"A":"Increasing monthly output from 500 to 1,200 candles","B":"Using hand-painted ceramic jars at no extra material cost and raising the retail price to $18","C":"Reducing workshop assistants' hourly wages by $4 per shift","D":"Buying $4 worth of extra soy wax to hold in raw material inventory"},"correctOption":"B","correctAnswer":"Using hand-painted ceramic jars at no extra material cost and raising the retail price to $18","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because initial added value = $14 - $3 = $11. Raising the retail price to $18 with unchanged bought-in material costs increases added value to $15 ($4 increase).","distractor_reasons":{"A":"Incorrect because increasing output volume alters total overall profit rather than unit added value.","B":"Option B is correct because initial added value = $14 - $3 = $11. Raising the retail price to $18 with unchanged bought-in material costs increases added value to $15 ($4 increase).","C":"Incorrect because worker wages are internal labor expenses, not bought-in material costs.","D":"Incorrect because storing extra raw materials increases inventory assets without changing unit added value."}}},{"id":"P1_U1_MCQ_953","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_953","question":"A commercial vineyard operates using fertile hillside land, seasonal grape harvesters, stainless steel fermentation tanks, and an enterprising founder. Which factor of production do the stainless steel fermentation tanks represent?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"C","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital consists of man-made physical machinery, tanks, and equipment used in production.","distractor_reasons":{"A":"Incorrect because land refers to natural agricultural resources.","B":"Incorrect because labour refers to the physical and mental effort of the grape harvesters.","C":"Option C is correct because capital consists of man-made physical machinery, tanks, and equipment used in production.","D":"Incorrect because enterprise refers to the risk-taking organizational role of the founder."}}},{"id":"P1_U1_MCQ_954","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_954","question":"A garment factory assigns a sewing machinist to perform only the single task of stitching left shirt cuffs for 8 hours daily. What is a primary disadvantage of division of labor in this workplace?","options":{"A":"Machinists require years of university engineering study to stitch a shirt cuff","B":"The purchase price of cotton fabric bought from textile mills increases","C":"Overall garment assembly line speed slows down dramatically","D":"Monotonous task repetition causes worker boredom, lower job satisfaction, and stitching mistakes"},"correctOption":"D","correctAnswer":"Monotonous task repetition causes worker boredom, lower job satisfaction, and stitching mistakes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because repeating one narrow task leads to boredom and fatigue, lowering motivation and increasing production errors.","distractor_reasons":{"A":"Incorrect because narrow repetitive tasks require minimal training.","B":"Incorrect because internal division of labor does not alter supplier fabric prices.","C":"Incorrect because specialization typically increases production efficiency and speed.","D":"Option D is correct because repeating one narrow task leads to boredom and fatigue, lowering motivation and increasing production errors."}}},{"id":"P1_U1_MCQ_955","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_955","question":"A consumer in Hanoi has a limited income and must decide how to spend it. They require basic food and shelter but would also like to own a new furniture. Which statement correctly distinguishes a need from a want?","options":{"A":"A need is something a person can afford, while a want is something they cannot afford.","B":"A want is always a physical product, while a need is always a service.","C":"A need is essential for survival or basic well-being, while a want is a desire that is not essential.","D":"A want must be satisfied before a need can be considered by a consumer."},"correctOption":"C","correctAnswer":"A need is essential for survival or basic well-being, while a want is a desire that is not essential.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because needs such as food and shelter are required for basic survival, whereas wants such as luxury goods are desires beyond necessity.","distractor_reasons":{"A":"Affordability does not define needs and wants: a person may need something they cannot afford and may want something they can easily afford.","B":"Both needs and wants can be either goods or services; the distinction is about necessity, not the physical form of the item.","D":"Consumers normally prioritise needs over wants because income is limited; the statement reverses the usual order of priority.","C":"Option is correct because needs such as food and shelter are required for basic survival, whereas wants such as luxury goods are desires beyond necessity."}}},{"id":"P1_U1_MCQ_956","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_956","question":"The region around Lyon has only a limited supply of salt, yet farmers, factories and households all want to use it. What is the fundamental economic problem illustrated by this situation?","options":{"A":"Prices are the only factor that determines how resources are distributed.","B":"All resources are infinite, so every want can be fully satisfied.","C":"Resources are scarce, so choices have to be made about how they are used.","D":"Specialisation removes the need for any economic choice."},"correctOption":"C","correctAnswer":"Resources are scarce, so choices have to be made about how they are used.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the basic economic problem is that finite resources have competing uses, forcing individuals and firms to make choices.","distractor_reasons":{"A":"Prices are one allocation mechanism but the fundamental problem is scarcity itself, and governments or queues can also allocate resources.","B":"This is the opposite of the economic problem: resources are finite, so not every want can be satisfied and choices are unavoidable.","D":"Specialisation can raise output but it does not remove scarcity, so choices about resource use are still required.","C":"Option is correct because the basic economic problem is that finite resources have competing uses, forcing individuals and firms to make choices."}}},{"id":"P1_U1_MCQ_957","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_957","question":"A watchmaker buys stainless steel cases for $25 and quartz movements for $10 per watch. The finished watches sell for $95 each. What is the added value per watch?","options":{"A":"$35","B":"$70","C":"$60","D":"$95"},"correctOption":"C","correctAnswer":"$60","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total bought-in component costs = $25 + $10 = $35. Added value = selling price ($95) - component costs ($35) = $60.","distractor_reasons":{"A":"Incorrect because $35 is total bought-in component cost.","B":"Incorrect because $70 subtracts only the steel case cost ($95 - $25), ignoring the quartz movement.","C":"Option C is correct because total bought-in component costs = $25 + $10 = $35. Added value = selling price ($95) - component costs ($35) = $60.","D":"Incorrect because $95 is the final selling price."}}},{"id":"P1_U1_MCQ_958","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_958","question":"A cybersecurity architect resigns from a salaried role earning $95,000 per year to establish an independent data protection consultancy. What is the opportunity cost of starting this consultancy?","options":{"A":"The annual rent paid for the consultancy office suite","B":"The client audit fees generated in Year 1","C":"The capital spent purchasing encrypted servers","D":"The $95,000 salary foregone from the previous cybersecurity job"},"correctOption":"D","correctAnswer":"The $95,000 salary foregone from the previous cybersecurity job","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $95,000 salary.","distractor_reasons":{"A":"Incorrect because office rent is a direct operating expense.","B":"Incorrect because client audit fees represent revenue from the chosen venture.","C":"Incorrect because server purchases are capital expenditures.","D":"Option D is correct because opportunity cost measures the sacrificed return of the next best alternative given up, which is the $95,000 salary."}}},{"id":"P1_U1_MCQ_959","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_959","question":"Which factor of production includes natural endowments such as iron ore deposits, wild marine fish stocks, and natural river water?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land encompasses all natural resources provided by nature used in economic production.","distractor_reasons":{"A":"Option A is correct because land encompasses all natural resources provided by nature used in economic production.","B":"Incorrect because labour represents human physical and mental effort.","C":"Incorrect because capital represents man-made equipment and machinery.","D":"Incorrect because enterprise is the managerial risk-taking function."}}},{"id":"P1_U1_MCQ_960","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_960","question":"How can a specialty coffee roaster directly increase the added value of its roasted coffee bags without raising final retail prices?","options":{"A":"Increasing spending on social media influencer promotions","B":"Negotiating lower purchase prices for raw green coffee beans from agricultural cooperatives","C":"Increasing hourly wage rates paid to roasting technicians","D":"Renting a larger retail cafe in the downtown district"},"correctOption":"B","correctAnswer":"Negotiating lower purchase prices for raw green coffee beans from agricultural cooperatives","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering green bean purchase costs widens this gap.","distractor_reasons":{"A":"Incorrect because social media promotion is an operating overhead expense.","B":"Option B is correct because added value equals selling price minus bought-in material costs. Lowering green bean purchase costs widens this gap.","C":"Incorrect because higher technician wages increase operating costs, lowering profit margin rather than unit added value.","D":"Incorrect because cafe rent increases overhead costs."}}},{"id":"P1_U1_MCQ_961","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_961","question":"Over the past decade the economy around Toronto has moved workers out of farming and into new factories producing cement, and manufacturing output has grown rapidly. This process is best described as:","options":{"A":"Industrialisation","B":"Deindustrialisation","C":"Specialisation","D":"Privatisation"},"correctOption":"A","correctAnswer":"Industrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories.","distractor_reasons":{"B":"Deindustrialisation is the decline of manufacturing and closure of factories, the reverse of the expansion described in this scenario.","C":"Specialisation means concentrating on a narrow range of tasks or products, which is not the economy-wide shift from farming to industry described.","D":"Privatisation is the transfer of state-owned assets to private owners; it concerns ownership and is not the shift into manufacturing described.","A":"Option is correct because industrialisation is the growth of manufacturing and industry in an economy, with workers shifting from agriculture into factories."}}},{"id":"P1_U1_MCQ_962","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_962","question":"What structural change characterizes deindustrialization in a mature economy?","options":{"A":"Workforce shifts out of banking services into coal mining","B":"The government nationalizes all private retail businesses","C":"Factory manufacturing output expands rapidly while service industries shrink","D":"Secondary sector manufacturing declines in relative importance while tertiary services expand"},"correctOption":"D","correctAnswer":"Secondary sector manufacturing declines in relative importance while tertiary services expand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing alongside growth in tertiary service industries.","distractor_reasons":{"A":"Incorrect because primary sector employment does not expand during deindustrialization.","B":"Incorrect because deindustrialization relates to sectoral composition, not state nationalization.","C":"Incorrect because manufacturing contracts relative to services.","D":"Option D is correct because deindustrialization describes a relative decline in secondary manufacturing alongside growth in tertiary service industries."}}},{"id":"P1_U1_MCQ_963","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_963","question":"In Accra, many manufacturing plants have closed over twenty years, factory employment has fallen sharply and the economy now depends far more on services. This change is an example of:","options":{"A":"Industrialisation","B":"Deindustrialisation","C":"Primary sector growth","D":"Division of labour"},"correctOption":"B","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy.","distractor_reasons":{"A":"Industrialisation is the growth of manufacturing and factory employment, which is the opposite of the decline in factories described here.","C":"Primary sector growth means more farming or extraction activity, but the scenario describes a fall in manufacturing and a rise in services.","D":"Division of labour is the splitting of production into specialised tasks within a firm, not a long-run change in a countrys industrial structure.","B":"Option is correct because deindustrialisation is the long-run decline of manufacturing industry and factory jobs within an economy."}}},{"id":"P1_U1_MCQ_964","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_964","question":"An iron ore mine extracts raw ore, a steelworks smelts the ore into structural steel beams, and a construction firm builds office towers using the steel. How are these three businesses classified?","options":{"A":"Iron ore mine: Secondary; Steelworks: Primary; Construction firm: Tertiary","B":"Iron ore mine: Primary; Steelworks: Secondary; Construction firm: Secondary","C":"Iron ore mine: Primary; Steelworks: Tertiary; Construction firm: Secondary","D":"Iron ore mine: Tertiary; Steelworks: Secondary; Construction firm: Primary"},"correctOption":"B","correctAnswer":"Iron ore mine: Primary; Steelworks: Secondary; Construction firm: Secondary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mining iron ore is primary extraction, while smelting steel and constructing buildings both transform materials into physical goods and structures (secondary sector).","distractor_reasons":{"A":"Incorrect because iron ore mining is primary extraction, not secondary.","B":"Option B is correct because mining iron ore is primary extraction, while smelting steel and constructing buildings both transform materials into physical goods and structures (secondary sector).","C":"Incorrect because a steelworks is secondary manufacturing, not tertiary service.","D":"Incorrect because sector classifications are reversed."}}},{"id":"P1_U1_MCQ_965","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_965","question":"A group of private investors owns and operates a chain of hair salons in Bogota with the aim of earning a profit. Which sector of the economy does this organisation belong to?","options":{"A":"Private sector","B":"Public sector","C":"Secondary sector","D":"Primary sector"},"correctOption":"A","correctAnswer":"Private sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector.","distractor_reasons":{"B":"The public sector consists of organisations owned and controlled by the government; this business is not government-owned.","C":"The secondary sector is concerned with manufacturing goods, which is a different classification from who owns the organisation.","D":"The primary sector is concerned with extracting natural resources and farming, which is a different classification from ownership.","A":"Option is correct because the organisation is owned by private individuals seeking profit, which defines the private sector."}}},{"id":"P1_U1_MCQ_966","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_966","question":"In Sao Paulo, 60% of workers are employed in the primary sector, 45% in the secondary sector and 15% in the tertiary sector. In which sector do the most workers work?","options":{"A":"Secondary sector","B":"Primary sector","C":"Public sector","D":"Tertiary sector"},"correctOption":"B","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","distractor_reasons":{"A":"The secondary sector employs 45% of workers, which is lower than the largest share of 60%, so it does not employ the most workers.","C":"The figures classify workers by productive sector rather than by ownership, so the public sector cannot be identified from this data.","D":"The tertiary sector employs 15% of workers, the largest share of the three sectors, so it employs the most workers.","B":"The primary sector employs 60% of workers, which is lower than the largest share of 60%, so it does not employ the most workers."}}},{"id":"P1_U1_MCQ_967","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_967","question":"A state-owned organisation in Kampala provides a service for the whole community and is funded partly by taxation. Which statement best describes its main purpose?","options":{"A":"To extract and sell as many natural resources as possible.","B":"To maximise profit for its private shareholders.","C":"To increase the wealth of the governments individual ministers.","D":"To provide a service to the community rather than to maximise profit."},"correctOption":"D","correctAnswer":"To provide a service to the community rather than to maximise profit.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit.","distractor_reasons":{"A":"Extracting resources for sale is a primary sector activity, not the purpose of a state organisation set up to deliver a community service.","B":"Maximising profit for private shareholders is the aim of private sector firms, not a tax-funded state organisation providing a community service.","C":"A public organisation does not exist to enrich individual ministers; its role is to provide services funded for the benefit of the community.","D":"Option is correct because public sector organisations generally aim to serve the public interest and provide essential services rather than maximise profit."}}},{"id":"P1_U1_MCQ_968","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_968","question":"Why might a government choose to privatize a state-owned passenger railway operator?","options":{"A":"To convert train drivers into government civil servants","B":"To introduce market competition, attract private capital investment, and improve service efficiency","C":"To prevent private investors from upgrading railway stations","D":"To increase direct ministerial control over daily train ticket prices"},"correctOption":"B","correctAnswer":"To introduce market competition, attract private capital investment, and improve service efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because privatization transfers state assets to private ownership, introducing profit motives and competition that enhance efficiency and raise funds.","distractor_reasons":{"A":"Incorrect because privatized staff lose civil servant status.","B":"Option B is correct because privatization transfers state assets to private ownership, introducing profit motives and competition that enhance efficiency and raise funds.","C":"Incorrect because privatization encourages private capital investment.","D":"Incorrect because privatization reduces direct government control over pricing."}}},{"id":"P1_U1_MCQ_969","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_969","question":"Which sector of the economy does this activity belong to? A privately owned firm in Warsaw runs an online tuition service for customers.","options":{"A":"Public sector","B":"Tertiary sector","C":"Secondary sector","D":"Primary sector"},"correctOption":"B","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because the tertiary sector provides services rather than extracting or manufacturing goods, so this service business belongs to it.","distractor_reasons":{"A":"The public sector refers to government ownership rather than the type of productive activity, so it is not the sector classification being asked for here.","C":"The secondary sector involves manufacturing and construction; the described activity is not the processing of materials into goods.","D":"The primary sector involves extracting natural resources and farming; the described activity is not extraction or farming.","B":"Option is correct because the tertiary sector provides services rather than extracting or manufacturing goods, so this service business belongs to it."}}},{"id":"P1_U1_MCQ_970","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_970","question":"What structural employment shift typically occurs as a developing economy undergoes rapid industrialization?","options":{"A":"Workers leave factory assembly jobs to return to subsistence farming","B":"Service firms shut down completely to focus on fishing","C":"Public sector ministries nationalize all private retail stores","D":"Workers move out of primary agriculture into secondary factory manufacturing"},"correctOption":"D","correctAnswer":"Workers move out of primary agriculture into secondary factory manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture.","distractor_reasons":{"A":"Incorrect because labor moves into manufacturing during industrialization, not out of it.","B":"Incorrect because service industries expand alongside industrial growth.","C":"Incorrect because industrialization is a sectoral shift, not total state nationalization.","D":"Option D is correct because industrialization expands secondary manufacturing, attracting workers away from primary agriculture."}}},{"id":"P1_U1_MCQ_971","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_971","question":"Which characteristic is essential for an entrepreneur starting a new commercial enterprise?","options":{"A":"Self-confidence, willingness to take calculated risks, and creative problem-solving","B":"Preference for following strict daily instructions from senior executives","C":"Refusal to adapt products when customer needs evolve","D":"Avoidance of personal responsibility for business outcomes"},"correctOption":"A","correctAnswer":"Self-confidence, willingness to take calculated risks, and creative problem-solving","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneurs require self-confidence, calculated risk-taking, and creativity to build a successful venture.","distractor_reasons":{"A":"Option A is correct because entrepreneurs require self-confidence, calculated risk-taking, and creativity to build a successful venture.","B":"Incorrect because entrepreneurs lead independent ventures.","C":"Incorrect because adaptability is vital for startup survival.","D":"Incorrect because entrepreneurs take responsibility for strategic decisions."}}},{"id":"P1_U1_MCQ_972","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_972","question":"Why is preparing a detailed business plan important when a startup seeks investment from a venture capital firm?","options":{"A":"It automatically grants limited liability status without legal registration","B":"It outlines market demand, competitive strategy, and financial projections proving growth potential","C":"It guarantees that the startup will achieve positive net profit in Month 1","D":"It exempts the business from paying corporate income tax"},"correctOption":"B","correctAnswer":"It outlines market demand, competitive strategy, and financial projections proving growth potential","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because investors examine market research, business strategy, and financial forecasts in a business plan to evaluate risk and return potential.","distractor_reasons":{"A":"Incorrect because limited liability requires legal incorporation (e.g., LTD), which a business plan cannot confer.","B":"Option B is correct because investors examine market research, business strategy, and financial forecasts in a business plan to evaluate risk and return potential.","C":"Incorrect because business plans contain forecasts, not profit guarantees.","D":"Incorrect because tax obligations are determined by law, not business plans."}}},{"id":"P1_U1_MCQ_973","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_973","question":"Noah Williams wants to start a chain of hair salons in Jakarta and apply to a bank for a loan. Which document should set out the business idea, market research, marketing plans and financial forecasts for the bank to assess?","options":{"A":"A statement of profit or loss","B":"A business plan","C":"An organisation chart","D":"A delivery note"},"correctOption":"B","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance.","distractor_reasons":{"A":"A statement of profit or loss reports past income and expenses for a period; a new venture has no trading history and needs a forward-looking plan.","C":"An organisation chart shows the structure, roles and reporting relationships within a business; it does not present market research or financial forecasts.","D":"A delivery note is a document sent with goods to confirm what has been dispatched and has no role in planning a business or applying for a loan.","B":"Option is correct because a business plan is a written document describing the idea, market, operations and financial forecasts, used to seek finance."}}},{"id":"P1_U1_MCQ_974","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_974","question":"A government wants to encourage more people in Accra to set up small businesses making laptops. Which of the following is an example of government support for new business start-ups?","options":{"A":"Offering low-interest start-up loans and grant funding to new firms.","B":"Introducing stricter rules that make it harder to register a new firm.","C":"Raising the rate of corporation tax on all company profits.","D":"Removing all forms of business advice and training for new owners."},"correctOption":"A","correctAnswer":"Offering low-interest start-up loans and grant funding to new firms.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business.","distractor_reasons":{"B":"More restrictive registration rules increase the barriers to entry and would hinder, not help, people starting a business.","C":"Raising tax on company profits would discourage new businesses rather than support them, as it reduces the reward from trading.","D":"Withdrawing advice and training would leave new owners without guidance, which is the opposite of supporting start-ups.","A":"Option is correct because governments support start-ups through schemes such as grants, loans and advice that lower the barriers to setting up a business."}}},{"id":"P1_U1_MCQ_975","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_975","question":"Why do governments offer low-interest startup loans and enterprise incubators to new entrepreneurs?","options":{"A":"To create new jobs, foster innovation, and stimulate national economic growth","B":"To eliminate competition for state-owned enterprises","C":"To force small startups to list shares on the national stock exchange","D":"To prevent foreign businesses from exporting goods"},"correctOption":"A","correctAnswer":"To create new jobs, foster innovation, and stimulate national economic growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because supporting new startups generates employment, encourages innovation, and increases national economic output.","distractor_reasons":{"A":"Option A is correct because supporting new startups generates employment, encourages innovation, and increases national economic output.","B":"Incorrect because startup support increases market competition rather than eliminating it.","C":"Incorrect because startup loans do not compel stock exchange listing.","D":"Incorrect because domestic startup support targets local enterprise creation, not trade bans."}}},{"id":"P1_U1_MCQ_976","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_976","question":"Patel Packaging Ltd is a denim clothing business in Shanghai with 75 employees and annual sales revenue of $8m. Which pair of measures could be used to assess the size of this business?","options":{"A":"The number of employees and the annual sales turnover.","B":"The share price and the dividend yield.","C":"The profit margin and the current ratio.","D":"The brand image and the quality of its products."},"correctOption":"A","correctAnswer":"The number of employees and the annual sales turnover.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue.","distractor_reasons":{"B":"Share price and dividend yield relate to a listed companys shares and investor returns, not to the measure of business size.","C":"Profit margin and current ratio are measures of profitability and liquidity, not of the physical or financial size of the business.","D":"Brand image and product quality are qualitative features of a business and are not standard measures of its size.","A":"Option is correct because business size is commonly measured by the number of people employed, the value of output or the level of sales revenue."}}},{"id":"P1_U1_MCQ_977","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_977","question":"Which limitation arises when measuring business size solely by the value of sales revenue (turnover)?","options":{"A":"Sales revenue cannot be recorded by retail businesses","B":"Tax authorities prohibit firms from disclosing annual sales revenue","C":"A boutique selling expensive luxury goods can generate high sales revenue despite having very few employees and small premises","D":"All businesses in an economy generate the exact same annual sales revenue"},"correctOption":"C","correctAnswer":"A boutique selling expensive luxury goods can generate high sales revenue despite having very few employees and small premises","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because firms selling high-value luxury products (such as fine jewelry or supercars) can record high turnover despite small workforces and premises.","distractor_reasons":{"A":"Incorrect because sales revenue is routinely recorded across all retail businesses.","B":"Incorrect because disclosing sales revenue is standard accounting practice.","C":"Option C is correct because firms selling high-value luxury products (such as fine jewelry or supercars) can record high turnover despite small workforces and premises.","D":"Incorrect because sales revenue varies widely across companies."}}},{"id":"P1_U1_MCQ_978","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_978","question":"Why might the owner of a neighborhood independent bookstore choose to keep the business small rather than expand into a national chain?","options":{"A":"Small bookstores are legally exempt from paying book publisher invoices","B":"National bookstore chains are prohibited by government regulation","C":"Expanding a business automatically cancels limited liability status","D":"The owner wants to avoid extra management stress and preserve close personal contact with regular readers"},"correctOption":"D","correctAnswer":"The owner wants to avoid extra management stress and preserve close personal contact with regular readers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because owners often keep firms small to retain direct control, avoid excessive workload, and maintain personal customer relationships.","distractor_reasons":{"A":"Incorrect because all businesses must pay suppliers regardless of size.","B":"Incorrect because national bookstore chains operate legally.","C":"Incorrect because business growth does not revoke limited liability.","D":"Option D is correct because owners often keep firms small to retain direct control, avoid excessive workload, and maintain personal customer relationships."}}},{"id":"P1_U1_MCQ_979","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_979","question":"Over five years Ali Foods Ltd expanded its LED bulbs business in Bristol by reinvesting its own profits to open 2 new branches itself, without merging with or taking over any other firm. What type of growth is this?","options":{"A":"Horizontal integration","B":"Internal (organic) growth","C":"Forward vertical integration","D":"Backward vertical integration"},"correctOption":"B","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself.","distractor_reasons":{"A":"Horizontal integration means taking over or merging with another firm at the same stage of production, which did not happen here.","C":"Forward vertical integration means acquiring a downstream business such as retailers; this firm simply opened its own branches in the same trade.","D":"Backward vertical integration means taking over a supplier of raw materials, which is not what this business did to expand.","B":"Option is correct because organic growth is expansion from within the business, financed by retained profits and achieved by opening new outlets itself."}}},{"id":"P1_U1_MCQ_980","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_980","question":"Mensah Paper Ltd, a ceramic tiles manufacturer in Shanghai, has taken over a rival firm that makes the same ceramic tiles at the same stage of production. What type of integration is this?","options":{"A":"Forward vertical integration","B":"Backward vertical integration","C":"Horizontal integration","D":"Internal growth"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry.","distractor_reasons":{"A":"Forward vertical integration involves moving closer to the customer by acquiring a retailer or distributor, not taking over a rival producer.","B":"Backward vertical integration involves taking over a supplier of raw materials, not a competitor at the same production stage.","D":"Internal growth means expanding using the firms own resources, whereas this business grew by taking over another existing firm.","C":"Option is correct because horizontal integration is the joining of two firms that operate at the same stage of production in the same industry."}}},{"id":"P1_U1_MCQ_981","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_981","question":"What does unlimited liability mean for a sole trader operating an independent auto repair garage?","options":{"A":"The owner's financial loss is strictly limited to the initial cash invested in garage equipment","B":"The auto garage can sell shares to the public on a stock exchange","C":"The owner is personally responsible for all business debts, putting personal home equity and savings at risk","D":"Commercial banks guarantee to cover unpaid parts invoices if the garage closes"},"correctOption":"C","correctAnswer":"The owner is personally responsible for all business debts, putting personal home equity and savings at risk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unlimited liability means there is no legal separation between the owner and the business; personal wealth can be claimed to pay business debts.","distractor_reasons":{"A":"Incorrect because capping loss to invested capital describes limited liability companies.","B":"Incorrect because sole traders cannot issue public shares.","C":"Option C is correct because unlimited liability means there is no legal separation between the owner and the business; personal wealth can be claimed to pay business debts.","D":"Incorrect because banks do not guarantee business debts."}}},{"id":"P1_U1_MCQ_982","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_982","question":"Two separate firms in Dublin agree to create a new jointly owned business to develop a new trainers, sharing the costs, control and profits. What type of business organisation is this?","options":{"A":"A sole trader","B":"A joint venture","C":"A franchise","D":"A merger"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits.","distractor_reasons":{"A":"A sole trader has a single owner with unlimited liability, which cannot describe a business jointly owned by two firms.","C":"A franchise involves one party paying to trade under another firm brand and system, not two firms jointly owning a new venture.","D":"A merger is the combining of two existing firms into one, not the creation of a separate jointly owned new business.","B":"Option is correct because a joint venture is a business set up and jointly owned by two or more parties who share its costs, control and profits."}}},{"id":"P1_U1_MCQ_983","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_983","question":"An entrepreneur buys a franchise license to run a branded gourmet burger restaurant. What is a major disadvantage for this franchisee?","options":{"A":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor","B":"Complete absence of brand recognition among local diners","C":"Full freedom to change burger recipes and store branding without permission","D":"Receiving zero training or operational guidance from the franchisor"},"correctOption":"A","correctAnswer":"Paying an upfront franchise fee plus ongoing royalties on sales revenue to the franchisor","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchisees must pay initial license fees and regular royalties based on revenue, reducing their retained profit.","distractor_reasons":{"A":"Option A is correct because franchisees must pay initial license fees and regular royalties based on revenue, reducing their retained profit.","B":"Incorrect because established franchises provide immediate brand recognition.","C":"Incorrect because franchisees must follow strict brand and operational rules.","D":"Incorrect because franchisors supply training and ongoing operational support."}}},{"id":"P1_U1_MCQ_984","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_984","question":"Two biotechnology companies form a joint venture to develop a new medical diagnostic device. What is a primary advantage of forming this joint venture?","options":{"A":"A permanent merger that dissolves both original companies","B":"Sharing high research and development costs, project risks, and specialized scientific expertise","C":"Complete legal exemption from corporate income taxes","D":"Guaranteed absence of cultural or management disagreements"},"correctOption":"B","correctAnswer":"Sharing high research and development costs, project risks, and specialized scientific expertise","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because joint ventures enable independent businesses to share capital requirements, risks, and specialist knowledge for a specific project.","distractor_reasons":{"A":"Incorrect because joint ventures are separate project collaborations where parent firms remain independent.","B":"Option B is correct because joint ventures enable independent businesses to share capital requirements, risks, and specialist knowledge for a specific project.","C":"Incorrect because joint ventures are subject to standard tax regulations.","D":"Incorrect because management conflicts between partner firms can occur."}}},{"id":"P1_U1_MCQ_985","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_985","question":"An organisation in Jakarta is owned by the government but operates as a separate business providing a car rental firm to the public. What type of organisation is it?","options":{"A":"A partnership","B":"A public corporation","C":"A sole trader","D":"A public limited company"},"correctOption":"B","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public.","distractor_reasons":{"A":"A partnership is owned by two or more private individuals, whereas the organisation described is owned by the government.","C":"A sole trader is owned by one private individual with unlimited liability, not by the government.","D":"A public limited company has shares traded on a stock exchange and private shareholders, unlike this government-owned body.","B":"Option is correct because a public corporation is a state-owned body that is separate from government and provides services to the public."}}},{"id":"P1_U1_MCQ_986","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_986","question":"Why might the partners of a growing civil engineering partnership decide to convert into a Private Limited Company (LTD)?","options":{"A":"To advertise and sell shares to the general public on a stock exchange","B":"To avoid the legal duty to prepare annual financial accounts","C":"To become exempt from paying corporate profits tax","D":"To gain limited liability protection for personal assets and continuity of business existence"},"correctOption":"D","correctAnswer":"To gain limited liability protection for personal assets and continuity of business existence","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures the company continues even if a shareholder leaves or dies.","distractor_reasons":{"A":"Incorrect because only PLCs can sell shares publicly on a stock exchange.","B":"Incorrect because LTDs are legally required to file annual accounts.","C":"Incorrect because LTDs must pay corporate tax on profits.","D":"Option D is correct because incorporating as an LTD protects owners' personal assets via limited liability and ensures the company continues even if a shareholder leaves or dies."}}},{"id":"P1_U1_MCQ_987","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_987","question":"Isabella Costa owns a business in Leeds. The business incurs debts it cannot repay, and Isabellas personal savings can be used to pay those debts. What type of liability does the business have?","options":{"A":"Shared liability","B":"Limited liability","C":"Unlimited liability","D":"No liability"},"correctOption":"C","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts.","distractor_reasons":{"A":"Shared liability is not the correct term here; the defining feature described is the owners full personal responsibility for all debts.","B":"With limited liability the owners risk is capped at the amount invested, so personal savings could not be taken to pay business debts.","D":"No business owner is completely free of liability for the debts of their business; the owners assets are exposed in some form.","C":"Option is correct because unlimited liability means the owner has no legal protection and must use personal assets to settle business debts."}}},{"id":"P1_U1_MCQ_988","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_988","question":"Sofia Rossi is the single owner of a wedding planning business in Sao Paulo and runs the business alone. Which statement about this type of business organisation is correct?","options":{"A":"The owner has unlimited liability for all the business debts.","B":"The business has a separate legal identity from its owner.","C":"Its shares are freely traded on a stock exchange.","D":"The owner must publish detailed annual accounts publicly."},"correctOption":"A","correctAnswer":"The owner has unlimited liability for all the business debts.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business.","distractor_reasons":{"B":"A sole trader has no separate legal personality; the owner and the business are treated as the same legal person.","C":"A sole trader does not issue shares and cannot list on a stock exchange; that is a feature of a public limited company.","D":"Sole traders are not required to publish detailed accounts publicly; that obligation applies to certain larger companies.","A":"Option is correct because a sole trader has unlimited liability, meaning the owner is personally responsible for all debts of the business."}}},{"id":"P1_U1_MCQ_989","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_989","question":"Aisha Rahman and Lena Fischer have set up a business together in Cairo, sharing the ownership, management and profits of a computer repair service. What type of business organisation have they created?","options":{"A":"A public limited company","B":"A franchise","C":"A sole trader business","D":"A partnership"},"correctOption":"D","correctAnswer":"A partnership","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks.","distractor_reasons":{"A":"A public limited company is a separate legal entity whose shares can be sold to the public, which is not described here.","B":"A franchise involves paying a fee to trade under an established brands name and system, which is not what these two owners have done.","C":"A sole trader has exactly one owner, but this business was set up jointly by two people sharing ownership and profits.","D":"Option is correct because a partnership is a business owned and managed by two or more people who share the profits and the risks."}}},{"id":"P1_U1_MCQ_990","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_990","question":"Lin Plastics Ltd is a privately owned bottled water company in Mumbai. Its shares are not traded on a stock exchange and its owners enjoy limited liability. What type of business organisation is it?","options":{"A":"A sole trader","B":"A public limited company (Plc)","C":"A private limited company (Ltd)","D":"A partnership"},"correctOption":"C","correctAnswer":"A private limited company (Ltd)","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public.","distractor_reasons":{"A":"A sole trader has one owner with unlimited liability and no limited company status, unlike this incorporated business.","B":"A public limited company can sell its shares to the public on a stock exchange, but this companys shares are not publicly traded.","D":"A partnership is owned by two or more people usually with unlimited liability and does not have the limited liability described.","C":"Option is correct because a private limited company has limited liability and its shares cannot be offered for sale to the general public."}}},{"id":"P1_U1_MCQ_991","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_991","question":"During its first six months of trading, a new independent fitness studio focuses on generating enough membership cash inflows to pay studio rent, equipment leases, and instructor wages. What business objective does this represent?","options":{"A":"Survival","B":"Global market leadership","C":"Diversification into unrelated industries","D":"Maximum dividend distribution"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because survival is the primary objective for newly established businesses trying to cover operating costs in a competitive market.","distractor_reasons":{"A":"Option A is correct because survival is the primary objective for newly established businesses trying to cover operating costs in a competitive market.","B":"Incorrect because global leadership is a long-term strategic objective for large firms.","C":"Incorrect because diversification is an expansion strategy.","D":"Incorrect because dividend distribution applies to established profitable companies."}}},{"id":"P1_U1_MCQ_992","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_992","question":"Mensah Plastics Ltd in Warsaw reinvests its surplus to train unemployed local people and reduce poverty, rather than paying out profits to owners. Which objective does this business primarily pursue?","options":{"A":"Cost minimisation","B":"Market share","C":"Profit maximisation","D":"Social enterprise objectives"},"correctOption":"D","correctAnswer":"Social enterprise objectives","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty.","distractor_reasons":{"A":"Cost minimisation means reducing costs; the business described is focused on spending its surplus on social objectives.","B":"Market share concerns the proportion of industry sales, which is not the community-focused goal described in this scenario.","C":"Profit maximisation seeks the largest financial return for owners, whereas this firm prioritises social benefit over profit distribution.","D":"Option is correct because a social enterprise reinvests its surplus to achieve social goals such as training and reducing poverty."}}},{"id":"P1_U1_MCQ_993","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_993","question":"Which stakeholder group is described here in relation to Johnson Beverages Ltd, a ceramic tiles manufacturer in Lisbon? The firms customers who buy its products and depend on their quality.","options":{"A":"Employees","B":"Shareholders","C":"The local community","D":"Customers"},"correctOption":"D","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price.","distractor_reasons":{"A":"Employees are the people who work for the business; the described stakeholders are not the firms own workers.","B":"Shareholders are the owners of shares in the business; the described stakeholders are not people who have invested in shares.","C":"The local community is the group living near the business; the described stakeholders are not the people living in the surrounding area.","D":"Option is correct because customers are an external stakeholder group that buys the firms products and is affected by their quality and price."}}},{"id":"P1_U1_MCQ_994","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_994","question":"At Adeyemi Steel Ltd in Kuala Lumpur, shareholders want to keep costs low to raise profits and dividends, while employees want higher wages and greater job security. Which stakeholder conflict does this illustrate?","options":{"A":"Managers seeking faster growth conflict with customers seeking better quality.","B":"The government seeking lower taxes conflicts with the local community seeking more jobs.","C":"Customers seeking lower prices conflict with suppliers seeking higher prices.","D":"Shareholders seeking higher profits conflict with employees seeking better pay and security."},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits conflict with employees seeking better pay and security.","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash.","distractor_reasons":{"A":"The disagreement described is over wages, job security and profit returns, not over growth targets or product quality.","B":"The scenario involves shareholders and employees inside the firm, not a dispute between government and the local community.","C":"The conflict described is between owners and workers over costs and pay, not between customers and suppliers over prices.","D":"Option is correct because owners want lower costs and higher returns, while employees want higher wages and job security, so their interests clash."}}},{"id":"P1_U1_MCQ_995","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_995","question":"What is a primary objective of customers as external stakeholders of an electric bicycle manufacturer?","options":{"A":"Safe, reliable bicycles sold at fair prices with dependable warranty support","B":"Higher annual bonuses paid to senior company directors","C":"Increased local business rates paid by the assembly plant","D":"Reduced workforce headcount across assembly lines"},"correctOption":"A","correctAnswer":"Safe, reliable bicycles sold at fair prices with dependable warranty support","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers want good value for money, safe and durable products, and reliable customer support.","distractor_reasons":{"A":"Option A is correct because customers want good value for money, safe and durable products, and reliable customer support.","B":"Incorrect because director bonuses do not benefit customers.","C":"Incorrect because local business taxes do not concern retail customers.","D":"Incorrect because workforce cuts are internal operational decisions."}}},{"id":"P1_U1_MCQ_996","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_996","question":"Which goal is prioritized by fabric suppliers to an outdoor apparel manufacturer?","options":{"A":"Maximum dividend payouts to the apparel firm's shareholders","B":"Consistent repeat orders and prompt payment within agreed credit terms","C":"Lower retail prices for the apparel firm's finished jackets","D":"Higher municipal property taxes paid by the garment factory"},"correctOption":"B","correctAnswer":"Consistent repeat orders and prompt payment within agreed credit terms","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because suppliers rely on steady orders and timely invoice payments to maintain healthy cash flow.","distractor_reasons":{"A":"Incorrect because dividends benefit shareholders, not suppliers.","B":"Option B is correct because suppliers rely on steady orders and timely invoice payments to maintain healthy cash flow.","C":"Incorrect because final retail pricing concerns consumers.","D":"Incorrect because municipal taxes do not benefit fabric suppliers."}}},{"id":"P1_U1_MCQ_997","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_997","question":"Which objective is prioritized by the local community living near a large chemical manufacturing plant?","options":{"A":"Allowing untreated plant emissions into local air and water to cut firm costs","B":"Maximizing share dividends paid to overseas institutional investors","C":"Local employment opportunities, safe operations, and minimal environmental pollution","D":"Replacing local workers with lower-paid overseas staff"},"correctOption":"C","correctAnswer":"Local employment opportunities, safe operations, and minimal environmental pollution","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local communities value local job creation, safe practices, and minimal air, water, and noise pollution.","distractor_reasons":{"A":"Incorrect because local communities strongly oppose environmental pollution.","B":"Incorrect because overseas investor dividends do not benefit local residents.","C":"Option C is correct because local communities value local job creation, safe practices, and minimal air, water, and noise pollution.","D":"Incorrect because communities prefer local job creation over offshoring."}}},{"id":"P1_U1_MCQ_998","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_998","question":"A telecommunications provider raises monthly broadband prices by 20% to increase profit margins and shareholder dividends, prompting widespread customer complaints. Which stakeholder conflict does this illustrate?","options":{"A":"Suppliers seeking prompt payment vs Employees seeking flexible hours","B":"Government seeking tax revenue vs Community seeking quieter streets","C":"Lenders seeking loan interest vs Managers seeking company cars","D":"Shareholders seeking higher profits vs Customers seeking affordable prices"},"correctOption":"D","correctAnswer":"Shareholders seeking higher profits vs Customers seeking affordable prices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because raising prices boosts profits for shareholders but harms customers who want fair and affordable pricing.","distractor_reasons":{"A":"Incorrect because supplier payments and flexible hours are unrelated to subscription price hikes.","B":"Incorrect because tax revenue and street noise do not represent the pricing dispute.","C":"Incorrect because loan interest and company cars do not reflect consumer price increases.","D":"Option D is correct because raising prices boosts profits for shareholders but harms customers who want fair and affordable pricing."}}},{"id":"P1_U1_MCQ_999","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_999","question":"A supermarket chain extends its payment terms to small agricultural producers from 30 days to 120 days to improve its own cash reserves, causing financial strain for farmers. Which two stakeholder groups are in conflict?","options":{"A":"Managers/Shareholders and Suppliers","B":"Government and Commercial banks","C":"Retail customers and Local residents","D":"Tax inspectors and Factory workers"},"correctOption":"A","correctAnswer":"Managers/Shareholders and Suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because management and shareholders' goal of preserving company cash flow conflicts directly with suppliers' need for prompt payment.","distractor_reasons":{"A":"Option A is correct because management and shareholders' goal of preserving company cash flow conflicts directly with suppliers' need for prompt payment.","B":"Incorrect because government and banks are not the primary parties in supplier credit disputes.","C":"Incorrect because retail customers and local residents are not in conflict over supplier payment terms.","D":"Incorrect because tax inspectors are unrelated to commercial trade credit terms."}}},{"id":"P1_U1_MCQ_1000","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1000","question":"Johnson Steel Ltd, a kitchen utensils firm in Leeds, is trying to maximise the difference between its total sales revenue and its total costs. Which business objective is it pursuing?","options":{"A":"Social enterprise","B":"Profit maximisation","C":"Market share","D":"Survival"},"correctOption":"B","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation.","distractor_reasons":{"A":"A social enterprise prioritises social goals and reinvesting for community benefit rather than maximising financial profit.","C":"Market share concerns the proportion of total industry sales, not the difference between a single firms revenue and its costs.","D":"Survival means covering costs to stay in business, not actively seeking the largest possible difference between revenue and costs.","B":"Option is correct because profit is total revenue minus total costs, so seeking the largest gap between them is profit maximisation."}}},{"id":"P1_U1_MCQ_1001","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1001","question":"Ashfield Electronics, a Manila appliance retailer, advises the Cruz family, who can fund only one purchase this month: replacing the refrigerator that stores their food safely, or buying a second television for the living room. They choose the refrigerator. Which statement correctly classifies the two purchases?","options":{"A":"Both purchases are needs because both are household goods","B":"The refrigerator is a need and the second television is a want","C":"Both purchases are wants because the family could live without either","D":"The television is a need and the refrigerator is a want"},"correctOption":"B","correctAnswer":"The refrigerator is a need and the second television is a want","questionType":"MCQ","explanation":{"correct_reason":"Correct because a working refrigerator protects the family's food supply and health, an essential need, whereas a second television is an optional want the family can live without.","distractor_reasons":{"A":"Incorrect because being a household item does not make a product a need; a second television adds entertainment rather than meeting a basic requirement.","B":"Correct because a working refrigerator protects the family's food supply and health, an essential need, whereas a second television is an optional want the family can live without.","C":"Incorrect because safe food storage is an essential need, so the family cannot simply live without a working refrigerator.","D":"Incorrect because the classifications are reversed: food storage is essential while extra entertainment is not."}}},{"id":"P1_U1_MCQ_1002","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1002","question":"Ashbury Fisheries, a fishing company in Chile, catches anchovies and sells them unprocessed to a fishmeal plant. Which sector of economic activity does the company operate in, and why?","options":{"A":"Secondary, because the catch is sold to a processing plant","B":"Primary, because it extracts a natural resource directly from the sea","C":"Tertiary, because the fish are later transported to buyers","D":"Public sector, because fishing rights are licensed by government"},"correctOption":"B","correctAnswer":"Primary, because it extracts a natural resource directly from the sea","questionType":"MCQ","explanation":{"correct_reason":"Correct because catching anchovies involves taking a natural resource from the sea, which is the defining feature of primary sector activity.","distractor_reasons":{"A":"Incorrect because the company does no processing itself; selling its catch to a plant does not make its own activity secondary.","B":"Correct because catching anchovies involves taking a natural resource from the sea, which is the defining feature of primary sector activity.","C":"Incorrect because transport is carried out by the buyer's haulier, not by the fishing company.","D":"Incorrect because licensing does not place a privately owned fishing firm in the public sector."}}},{"id":"P1_U1_MCQ_1003","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1003","question":"Ashhurst Bakery is a bakery in Jordan whose owner notices that hotels throw away unsold bread each evening while nearby families buy stale loaves. She starts collecting the surplus to bake fresh loaves for those families. Which entrepreneurial characteristic does this best show?","options":{"A":"Avoiding risk by copying an existing bakery","B":"Relying on government subsidies to cover costs","C":"Maximising output by using the latest machinery","D":"Spotting an opportunity and organising resources to meet it"},"correctOption":"D","correctAnswer":"Spotting an opportunity and organising resources to meet it","questionType":"MCQ","explanation":{"correct_reason":"Correct because she identified unused bread and unmet demand, then combined suppliers, baking skills and customers into a new business.","distractor_reasons":{"A":"Incorrect because she created a new approach rather than copying an established business, and took on the risk of a start-up.","B":"Incorrect because no subsidy is mentioned; the opportunity itself is what she exploited.","C":"Incorrect because the case describes recognising a market gap, not investment in advanced equipment.","D":"Correct because she identified unused bread and unmet demand, then combined suppliers, baking skills and customers into a new business."}}},{"id":"P1_U1_MCQ_1004","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1004","question":"Ashstead Furniture, a sole trader in Ghana, runs a furniture workshop. A customer wins a court claim of $95,000 after a faulty chair causes injury, but the business holds only $40,000 of assets. What is the consequence of unlimited liability?","options":{"A":"The debt is cancelled because the business has insufficient assets","B":"The owner must pay the remaining $55,000 from personal assets","C":"Only the business assets are at risk because the owner is a shareholder","D":"The government compensates the customer for the shortfall"},"correctOption":"B","correctAnswer":"The owner must pay the remaining $55,000 from personal assets","questionType":"MCQ","explanation":{"correct_reason":"Correct because unlimited liability makes the sole trader personally responsible for all business debts, so the $55,000 shortfall must come from personal assets.","distractor_reasons":{"A":"Incorrect because limited assets do not cancel a sole trader's liability; the owner remains responsible for the balance.","B":"Correct because unlimited liability makes the sole trader personally responsible for all business debts, so the $55,000 shortfall must come from personal assets.","C":"Incorrect because a sole trader is not a shareholder and has no limited liability protection.","D":"Incorrect because no state compensation scheme is described, and liability rests with the owner."}}},{"id":"P1_U1_MCQ_1005","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1005","question":"Ashholm Brewing, a brewery in Belgium, raises its prices and renegotiates barley contracts so that total revenue exceeds total costs by the largest possible amount, lifting annual profit from $2.0 million to $2.8 million. Which business objective is it pursuing?","options":{"A":"Survival","B":"Increasing market share","C":"Providing a social service","D":"Profit maximisation"},"correctOption":"D","correctAnswer":"Profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Correct because the brewery is deliberately widening the gap between total revenue and total costs, lifting profit from $2.0 million to $2.8 million.","distractor_reasons":{"A":"Incorrect because the brewery is already profitable and is pushing profit higher, not merely trying to stay in business.","B":"Incorrect because the case reports profit rising, and higher prices would normally reduce rather than raise market share.","C":"Incorrect because the objective described is the largest possible surplus of revenue over costs, a private profit goal.","D":"Correct because the brewery is deliberately widening the gap between total revenue and total costs, lifting profit from $2.0 million to $2.8 million."}}},{"id":"P1_U1_MCQ_1006","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1006","question":"Ashfield Council, a regional authority in Ghana, holds a fixed budget of $40 million, but hospitals, schools and road departments have submitted requests worth $95 million in total. Officials must rank the requests and fund only part of them. Which economic problem does this illustrate?","options":{"A":"Inflation, because prices of hospital equipment rise each year","B":"Unemployment, because building roads needs extra workers","C":"Specialisation, because each department performs one task","D":"Scarcity, because wants exceed the resources available"},"correctOption":"D","correctAnswer":"Scarcity, because wants exceed the resources available","questionType":"MCQ","explanation":{"correct_reason":"Correct because the $95 million of requests exceeds the $40 million budget, so limited resources cannot satisfy every want and choices have to be made.","distractor_reasons":{"A":"Incorrect because no price rise is described; the difficulty is that requests worth $95 million cannot all be met from $40 million.","B":"Incorrect because the stem describes a shortage of money for projects, not a shortage of jobs for workers.","C":"Incorrect because specialisation concerns dividing work between departments, not a budget too small for all the requests.","D":"Correct because the $95 million of requests exceeds the $40 million budget, so limited resources cannot satisfy every want and choices have to be made."}}},{"id":"P1_U1_MCQ_1007","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1007","question":"Ashbury Motors, a car plant in Slovakia, stamps steel panels and assembles them into complete cars, while a nearby office sells insurance policies. Which pairing correctly classifies the two activities?","options":{"A":"Car assembly is tertiary and insurance selling is secondary","B":"Both activities are secondary because both are businesses","C":"Car assembly is secondary and insurance selling is tertiary","D":"Both activities are tertiary because each sells a product to customers"},"correctOption":"C","correctAnswer":"Car assembly is secondary and insurance selling is tertiary","questionType":"MCQ","explanation":{"correct_reason":"Correct because manufacturing cars processes materials into finished goods, which is secondary, while selling insurance provides a service, which is tertiary.","distractor_reasons":{"A":"Incorrect because the classifications are reversed; making cars is manufacturing and insurance is a service.","B":"Incorrect because being a business says nothing about sector; only the car plant processes materials.","C":"Correct because manufacturing cars processes materials into finished goods, which is secondary, while selling insurance provides a service, which is tertiary.","D":"Incorrect because the car plant makes a physical good; selling output does not turn manufacturing into a service."}}},{"id":"P1_U1_MCQ_1008","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1008","question":"Ashhurst Cafes is a coffee roastery being set up in Vietnam by two graduates who want a $180,000 bank loan. The bank asks for a document showing market demand, projected costs, cash needs and expected profit over three years. Why is this business plan useful?","options":{"A":"It guarantees that the business will make a profit","B":"It gives lenders evidence that the venture is viable and can repay the loan","C":"It removes the need for the owners to contribute any capital","D":"It sets the price the roastery must charge by law"},"correctOption":"B","correctAnswer":"It gives lenders evidence that the venture is viable and can repay the loan","questionType":"MCQ","explanation":{"correct_reason":"Correct because demand, costs, cash needs and expected profit allow the bank to judge whether the $180,000 can be serviced.","distractor_reasons":{"A":"Incorrect because a plan is only a forecast; it cannot guarantee that demand or costs will turn out as projected.","B":"Correct because demand, costs, cash needs and expected profit allow the bank to judge whether the $180,000 can be serviced.","C":"Incorrect because a plan supports a loan application but does not replace the owners' own stake.","D":"Incorrect because prices are a commercial decision, not something a business plan legally fixes."}}},{"id":"P1_U1_MCQ_1009","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1009","question":"Ashstead Accountancy is an accountancy partnership in Ireland; the two partners each put in $60,000 and share the workload so that one can cover clients when the other is ill. Which advantage of a partnership does this show?","options":{"A":"Limited liability for all partners","B":"Shared capital and shared responsibility for running the business","C":"The ability to sell shares on a stock exchange","D":"Complete independence for each partner to decide alone"},"correctOption":"B","correctAnswer":"Shared capital and shared responsibility for running the business","questionType":"MCQ","explanation":{"correct_reason":"Correct because the partners combine $120,000 of capital and cover each other's work, spreading both finance and workload.","distractor_reasons":{"A":"Incorrect because ordinary partners in a partnership still have unlimited liability for business debts.","B":"Correct because the partners combine $120,000 of capital and cover each other's work, spreading both finance and workload.","C":"Incorrect because only public limited companies can offer shares to the public in that way.","D":"Incorrect because partners share decisions and responsibility rather than acting independently."}}},{"id":"P1_U1_MCQ_1010","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1010","question":"Ashholm Cafes, a new restaurant in Hungary, has made losses for eight months, and the owner keeps trading by cutting staff hours and delaying equipment purchases until demand improves. Which objective is being pursued?","options":{"A":"Profit maximisation","B":"Market share growth","C":"Survival","D":"Social objectives"},"correctOption":"C","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Correct because the owner is reducing costs and postponing spending in order to keep the business trading through a loss-making period.","distractor_reasons":{"A":"Incorrect because the business is making losses and is focused on staying open, not on maximising profit.","B":"Incorrect because no attempt to win customers from rivals is described, only cost cutting to remain open.","C":"Correct because the owner is reducing costs and postponing spending in order to keep the business trading through a loss-making period.","D":"Incorrect because the decisions aim to keep the private business alive, not to deliver community benefits."}}},{"id":"P1_U1_MCQ_1011","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1011","question":"Ashfield Farm, a farming cooperative in Costa Rica, has $60,000 to invest. A refrigerated van would add about $22,000 a year in income; a new packing line would add about $31,000 a year. The cooperative buys the van. What is the opportunity cost of this decision?","options":{"A":"$31,000 a year of income forgone from the packing line","B":"$22,000 a year, the income expected from the van","C":"$9,000, the difference between the two annual returns","D":"$60,000, the full amount of money invested"},"correctOption":"A","correctAnswer":"$31,000 a year of income forgone from the packing line","questionType":"MCQ","explanation":{"correct_reason":"Correct because opportunity cost is the value of the next best alternative given up, which here is the $31,000 of annual income the packing line would have earned.","distractor_reasons":{"A":"Correct because opportunity cost is the value of the next best alternative given up, which here is the $31,000 of annual income the packing line would have earned.","B":"Incorrect because $22,000 is the return actually gained from the choice made, not the alternative that was sacrificed.","C":"Incorrect because opportunity cost is the whole return given up from the packing line, not merely the $9,000 gap between the two options.","D":"Incorrect because $60,000 would be spent under either option, so the cash outlay is not the benefit that is lost."}}},{"id":"P1_U1_MCQ_1012","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1012","question":"Ashbury Metals, a metals manufacturer in Spain, has seen manufacturing's share of employment fall from 28% to 14% over twenty years while jobs in hotels, banking and healthcare grew. Which term describes this change?","options":{"A":"Specialisation","B":"Privatisation","C":"Nationalisation","D":"Deindustrialisation"},"correctOption":"D","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"Correct because deindustrialisation means a falling relative importance of manufacturing, shown by the drop from 28% to 14% of employment.","distractor_reasons":{"A":"Incorrect because specialisation means concentrating on particular products or tasks, not a shrinking manufacturing share.","B":"Incorrect because privatisation is the sale of state-owned assets to private owners, which the stem does not describe.","C":"Incorrect because nationalisation is government takeover of private firms, the opposite of what is described.","D":"Correct because deindustrialisation means a falling relative importance of manufacturing, shown by the drop from 28% to 14% of employment."}}},{"id":"P1_U1_MCQ_1013","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1013","question":"Ashhurst Consulting, a business adviser, compares a manufacturer employing 950 staff, with capital employed of $210 million and a 22% market share, against a rival employing 300 staff with capital employed of $260 million. Which conclusion is most sound?","options":{"A":"The first firm is definitely larger because it has more employees","B":"The rival is definitely larger because capital employed is always the best measure","C":"Comparisons can conflict because firms differ on different measures of size","D":"The two firms are the same size because their measures differ"},"correctOption":"C","correctAnswer":"Comparisons can conflict because firms differ on different measures of size","questionType":"MCQ","explanation":{"correct_reason":"Correct because the first firm is larger by employees while the rival is larger by capital employed, so no single measure settles the question.","distractor_reasons":{"A":"Incorrect because the rival's $260 million of capital employed exceeds the first firm's $210 million, so the comparison is not settled.","B":"Incorrect because no single measure is always best; employees and market share give a different picture here.","C":"Correct because the first firm is larger by employees while the rival is larger by capital employed, so no single measure settles the question.","D":"Incorrect because different measures do not make the firms equal; they simply show that size is multi-dimensional."}}},{"id":"P1_U1_MCQ_1014","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1014","question":"Ashbridge Furniture is a furniture company being set up by three friends in Malaysia, who want to raise $400,000 by selling shares to family members only, without offering shares to the public, and want limited liability. Which form of organisation should they choose?","options":{"A":"A sole trader","B":"A partnership","C":"A public limited company","D":"A private limited company"},"correctOption":"D","correctAnswer":"A private limited company","questionType":"MCQ","explanation":{"correct_reason":"Correct because a private limited company can sell shares privately to chosen investors and gives shareholders limited liability.","distractor_reasons":{"A":"Incorrect because a sole trader cannot sell shares and has unlimited liability.","B":"Incorrect because a partnership cannot issue shares and does not offer limited liability to ordinary partners.","C":"Incorrect because a public limited company must be able to offer shares to the general public, which the friends do not want.","D":"Correct because a private limited company can sell shares privately to chosen investors and gives shareholders limited liability."}}},{"id":"P1_U1_MCQ_1015","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1015","question":"Ashholm Digital, a mobile network in Nigeria, cuts prices to win subscribers, accepting lower profit per customer. Its share of the national market rises from 14% to 19%. Which objective was prioritised?","options":{"A":"Increasing market share","B":"Profit maximisation","C":"Survival","D":"Employee welfare"},"correctOption":"A","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"Correct because the firm accepted lower profit per customer in order to lift its share of the national market from 14% to 19%.","distractor_reasons":{"A":"Correct because the firm accepted lower profit per customer in order to lift its share of the national market from 14% to 19%.","B":"Incorrect because profit per customer fell, which is the opposite of maximising profit.","C":"Incorrect because the firm is investing to grow its position, not struggling to stay in business.","D":"Incorrect because no change to pay or conditions is described."}}},{"id":"P1_U1_MCQ_1016","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1016","question":"Ashfield Fruit, a family-owned asparagus exporter in Peru, lists its resources: 180 hectares of irrigated land, 90 field workers, refrigerated packing machinery and the owner's decision to risk $400,000 on a new export contract. Which resource is the factor of production known as capital?","options":{"A":"The 180 hectares of irrigated land","B":"The refrigerated packing machinery","C":"The 90 field workers","D":"The owner's willingness to risk $400,000"},"correctOption":"B","correctAnswer":"The refrigerated packing machinery","questionType":"MCQ","explanation":{"correct_reason":"Correct because capital means man-made goods used to produce other goods and services, which describes the refrigerated packing machinery.","distractor_reasons":{"A":"Incorrect because land covers natural resources, so the hectares are land rather than capital.","B":"Correct because capital means man-made goods used to produce other goods and services, which describes the refrigerated packing machinery.","C":"Incorrect because workers supply labour, a human factor of production, not capital.","D":"Incorrect because risk-bearing by the owner is enterprise, which is separate from capital."}}},{"id":"P1_U1_MCQ_1017","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1017","question":"Ashmere Research, a market research firm, reports that where average household incomes rose by 35% in a decade, spending on restaurant meals, travel and personal training grew much faster than spending on basic food. Which explanation best fits this trend?","options":{"A":"Manufacturing has replaced services in the economy","B":"Consumers buy fewer services when incomes rise","C":"As incomes rise, households spend a larger share on services","D":"The primary sector grows fastest in rich economies"},"correctOption":"C","correctAnswer":"As incomes rise, households spend a larger share on services","questionType":"MCQ","explanation":{"correct_reason":"Correct because the 35% rise in income allows families to spend more on discretionary services once essential food is covered.","distractor_reasons":{"A":"Incorrect because the fastest growth described is in services such as meals and travel, not manufacturing.","B":"Incorrect because the stem shows service spending growing faster, the opposite of this claim.","C":"Correct because the 35% rise in income allows families to spend more on discretionary services once essential food is covered.","D":"Incorrect because no farming or extraction growth is mentioned, and demand for services is what increased."}}},{"id":"P1_U1_MCQ_1018","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1018","question":"Ashhurst Dairy, a dairy in Ireland, sells $18 million of milk and cheese in a national market worth $120 million. What is its market share?","options":{"A":"6.7%","B":"18%","C":"85%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Correct because $18 million divided by $120 million is 0.15, which equals 15% of the market.","distractor_reasons":{"A":"Incorrect because this is $120 million divided by $18 million, the ratio inverted.","B":"Incorrect because 18 is the sales figure in millions, not a percentage of the market.","C":"Incorrect because 85% is the share of the market held by other producers.","D":"Correct because $18 million divided by $120 million is 0.15, which equals 15% of the market."}}},{"id":"P1_U1_MCQ_1019","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1019","question":"Ashbridge Foods, a supermarket group in Sweden, wants to raise $500 million by advertising shares for sale to any investor on a stock exchange. Which type of organisation is it becoming?","options":{"A":"A private limited company","B":"A public limited company","C":"A partnership","D":"A cooperative"},"correctOption":"B","correctAnswer":"A public limited company","questionType":"MCQ","explanation":{"correct_reason":"Correct because advertising shares to the general public through a stock exchange is only possible for a public limited company.","distractor_reasons":{"A":"Incorrect because a private limited company may not offer its shares to the general public.","B":"Correct because advertising shares to the general public through a stock exchange is only possible for a public limited company.","C":"Incorrect because partnerships cannot raise finance by issuing shares on an exchange.","D":"Incorrect because a cooperative is owned by its members and does not sell shares publicly."}}},{"id":"P1_U1_MCQ_1020","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1020","question":"Ashholm Recycling, a social enterprise in Scotland, reinvests 80% of its surplus into training unemployed young people and keeps its prices modest. Which objective best describes its approach?","options":{"A":"Social objectives taking priority over profit maximisation","B":"Profit maximisation for distribution to shareholders","C":"Growth by acquiring rival training firms","D":"Survival through higher prices"},"correctOption":"A","correctAnswer":"Social objectives taking priority over profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Correct because most of the surplus funds training for unemployed young people rather than being distributed to owners.","distractor_reasons":{"A":"Correct because most of the surplus funds training for unemployed young people rather than being distributed to owners.","B":"Incorrect because 80% of the surplus is reinvested in training rather than paid out.","C":"Incorrect because no acquisitions are mentioned; the focus is on using surplus for a social purpose.","D":"Incorrect because prices are kept modest and no financial crisis is described."}}},{"id":"P1_U1_MCQ_1021","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1021","question":"Ashfield Software is a software company in Turkey whose founder invests $250,000 of personal savings, hires twelve programmers and accepts that the money may be lost if customers do not buy the product. Which factor of production does the founder provide, and what is its reward?","options":{"A":"Capital, rewarded by interest","B":"Labour, rewarded by wages","C":"Enterprise, rewarded by profit","D":"Land, rewarded by rent"},"correctOption":"C","correctAnswer":"Enterprise, rewarded by profit","questionType":"MCQ","explanation":{"correct_reason":"Correct because organising the other factors of production and bearing the risk of loss is enterprise, and the reward for enterprise is profit.","distractor_reasons":{"A":"Incorrect because the savings become capital once invested, but organising and risking the venture is enterprise; interest rewards lenders.","B":"Incorrect because the founder is not paid wages for manual work but takes the risk of the venture.","C":"Correct because organising the other factors of production and bearing the risk of loss is enterprise, and the reward for enterprise is profit.","D":"Incorrect because land refers to natural resources, and rent goes to landowners rather than to the founder who bears risk."}}},{"id":"P1_U1_MCQ_1022","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1022","question":"Ashmere Digital, a telecoms investor, is studying India, where a private company runs the mobile phone network while a government agency operates the national rail service and public hospitals. Which description of India's economy is correct?","options":{"A":"A command economy where all decisions are made by the state","B":"A free market economy with no government ownership","C":"A mixed economy with both private and public sector organisations","D":"A primary economy dependent on extraction"},"correctOption":"C","correctAnswer":"A mixed economy with both private and public sector organisations","questionType":"MCQ","explanation":{"correct_reason":"Correct because privately owned firms and state-owned organisations both operate, which is the defining feature of a mixed economy.","distractor_reasons":{"A":"Incorrect because a private phone company makes its own decisions, so the state does not control everything.","B":"Incorrect because the rail service and hospitals are state owned.","C":"Correct because privately owned firms and state-owned organisations both operate, which is the defining feature of a mixed economy.","D":"Incorrect because the activities described are services, not extraction of natural resources."}}},{"id":"P1_U1_MCQ_1023","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1023","question":"Ashhurst Nurseries, a garden centre in New Zealand, opened three extra branches and doubled its plant range, paying for the expansion from profit kept in the business. Which type of growth is this?","options":{"A":"Growth by merger with another garden centre","B":"Organic growth funded from retained profit","C":"Growth by takeover of a competitor","D":"Growth through a franchise agreement"},"correctOption":"B","correctAnswer":"Organic growth funded from retained profit","questionType":"MCQ","explanation":{"correct_reason":"Correct because the business expanded its own operations and used its own retained profit rather than merging with another firm.","distractor_reasons":{"A":"Incorrect because no other business was combined with this one; the branches were opened by the firm itself.","B":"Correct because the business expanded its own operations and used its own retained profit rather than merging with another firm.","C":"Incorrect because buying another company is not described; the firm built new branches.","D":"Incorrect because no franchisor or royalty payment is mentioned."}}},{"id":"P1_U1_MCQ_1024","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1024","question":"Ashcroft Foods is a fried chicken outlet in the UAE opened by an entrepreneur using a well-known brand's recipes, signage and supplier list, and paying 9% of monthly sales for the right to do so. Which arrangement is this?","options":{"A":"A joint venture","B":"A cooperative","C":"A franchise","D":"A public corporation"},"correctOption":"C","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Correct because the entrepreneur buys the right to trade under an established brand and pays a percentage of sales for that right.","distractor_reasons":{"A":"Incorrect because a joint venture involves two firms creating and sharing a separate business, not one buying brand rights.","B":"Incorrect because the outlet is privately run for the owner's profit, not owned by member customers or workers.","C":"Correct because the entrepreneur buys the right to trade under an established brand and pays a percentage of sales for that right.","D":"Incorrect because the business is privately owned, not state owned."}}},{"id":"P1_U1_MCQ_1025","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1025","question":"Ashley Metals, a manufacturing firm in Italy, proposes a 6% pay rise for its 400 workers, which would cut the dividend paid to shareholders by $1.2 million. Which two stakeholder groups are in direct conflict?","options":{"A":"Employees and shareholders","B":"Customers and suppliers","C":"Government and local residents","D":"Managers and trade unions"},"correctOption":"A","correctAnswer":"Employees and shareholders","questionType":"MCQ","explanation":{"correct_reason":"Correct because the pay rise benefits the 400 workers while the $1.2 million reduction in dividends harms shareholders.","distractor_reasons":{"A":"Correct because the pay rise benefits the 400 workers while the $1.2 million reduction in dividends harms shareholders.","B":"Incorrect because neither group is affected by the pay and dividend decision described.","C":"Incorrect because no tax or community issue is involved in the pay rise.","D":"Incorrect because the conflict described is between wage earners and owners, not managers and unions."}}},{"id":"P1_U1_MCQ_1026","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1026","question":"Ashfield Sports, a skateboard workshop in Vietnam, buys deck blanks, wheels and trucks for $18 per board and sells each finished board for $45. Labour and factory rent are paid from the difference. What is the added value per skateboard?","options":{"A":"$18, the cost of the bought-in components","B":"$45, the selling price of each board","C":"$27","D":"$63, the sum of price and material cost"},"correctOption":"C","correctAnswer":"$27","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added per unit is the selling price minus the cost of bought-in materials and components: $45 - $18 = $27.","distractor_reasons":{"A":"Incorrect because $18 is the input cost that is deducted from the selling price, not the value added.","B":"Incorrect because value added is the margin over bought-in materials, not the whole $45 selling price.","C":"Correct because value added per unit is the selling price minus the cost of bought-in materials and components: $45 - $18 = $27.","D":"Incorrect because adding the two figures together is meaningless; material cost must be subtracted from the price."}}},{"id":"P1_U1_MCQ_1027","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1027","question":"Ashmere Water is a water treatment works serving 600,000 residents; the city council owns and funds it, and any surplus is reinvested in pipes rather than paid to shareholders. Which type of organisation is this?","options":{"A":"A public limited company","B":"A partnership","C":"A public sector organisation","D":"A cooperative"},"correctOption":"C","correctAnswer":"A public sector organisation","questionType":"MCQ","explanation":{"correct_reason":"Correct because the works is owned and funded by local government and does not distribute surplus to shareholders.","distractor_reasons":{"A":"Incorrect because a public limited company is owned by shareholders and can sell shares to the public, which this works does not do.","B":"Incorrect because a partnership is owned by private partners sharing profit, not by a city council.","C":"Correct because the works is owned and funded by local government and does not distribute surplus to shareholders.","D":"Incorrect because a cooperative is owned and controlled by its members, not by a local authority."}}},{"id":"P1_U1_MCQ_1028","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1028","question":"Ashcombe Bakery, a family-owned chain with 42 shops across northern Spain, has agreed with a rival chain of similar size to combine the two businesses into one company, with neither side buying the other's shares. Which term best describes this arrangement?","options":{"A":"A takeover","B":"A franchise","C":"A merger","D":"A joint venture"},"correctOption":"C","correctAnswer":"A merger","questionType":"MCQ","explanation":{"correct_reason":"Correct because two separate firms of similar standing joined voluntarily into a single company rather than one purchasing the other.","distractor_reasons":{"A":"Incorrect because a takeover involves one firm buying control of another, which the stem explicitly rules out.","B":"Incorrect because franchising licenses a brand to independent operators rather than combining two chains.","C":"Correct because two separate firms of similar standing joined voluntarily into a single company rather than one purchasing the other.","D":"Incorrect because a joint venture creates a separate project company, whereas here the two chains become one company."}}},{"id":"P1_U1_MCQ_1029","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1029","question":"Ashcroft Energy, a Brazilian engineering firm, has created a separate company with a Japanese battery maker to build battery plants in Brazil, sharing the $80 million cost and the commercial risk. Which arrangement is this?","options":{"A":"A joint venture","B":"A takeover","C":"A franchise","D":"A merger"},"correctOption":"A","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Correct because two independent firms set up and share ownership of a new business, dividing the $80 million cost and the risk.","distractor_reasons":{"A":"Correct because two independent firms set up and share ownership of a new business, dividing the $80 million cost and the risk.","B":"Incorrect because neither firm is buying control of the other; they are creating a new shared company.","C":"Incorrect because no brand licence or royalty is involved.","D":"Incorrect because the two firms remain separate and only the new plant company is jointly owned."}}},{"id":"P1_U1_MCQ_1030","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1030","question":"Ashley Bakery, a bakery in Norway, plans to raise loaf prices by 12% to protect its profit as flour costs rise. Which stakeholder group loses most directly from this decision?","options":{"A":"Shareholders, who receive lower dividends","B":"Suppliers, who receive lower prices for flour","C":"Customers, who pay more for the same bread","D":"The government, which collects less tax"},"correctOption":"C","correctAnswer":"Customers, who pay more for the same bread","questionType":"MCQ","explanation":{"correct_reason":"Correct because the 12% price rise is paid by shoppers buying the loaves, reducing what their money can buy.","distractor_reasons":{"A":"Incorrect because the price rise is intended to protect profit and therefore dividends, not reduce them.","B":"Incorrect because flour costs are rising, so suppliers are not losing from the decision.","C":"Correct because the 12% price rise is paid by shoppers buying the loaves, reducing what their money can buy.","D":"Incorrect because protected profit supports tax revenue rather than reducing it."}}},{"id":"P1_U1_MCQ_1031","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1031","question":"Ashfield Footwear, a sandal factory in Brazil, makes 4,500 pairs a week, buying rubber, straps and packaging at $7.20 per pair and selling at $16.00 per pair. What total value does the factory add each week?","options":{"A":"$39,600","B":"$72,000, total sales revenue","C":"$32,400, total materials cost","D":"$8.80, the value added per pair"},"correctOption":"A","correctAnswer":"$39,600","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added per pair is $16.00 - $7.20 = $8.80, and 4,500 pairs times $8.80 gives $39,600.","distractor_reasons":{"A":"Correct because value added per pair is $16.00 - $7.20 = $8.80, and 4,500 pairs times $8.80 gives $39,600.","B":"Incorrect because $72,000 is revenue; the $7.20 of bought-in materials per pair has not been deducted.","C":"Incorrect because $32,400 is the input cost, not the value created by processing those materials.","D":"Incorrect because $8.80 is the per-pair figure, while the question asks for the total across 4,500 pairs."}}},{"id":"P1_U1_MCQ_1032","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1032","question":"Ashmere Couriers, a private transport group, has bought a loss-making bus company from the government and cut waiting times while raising some fares to improve profit. Which reason for private ownership does this illustrate?","options":{"A":"Private firms always charge customers less","B":"Private firms cannot make losses","C":"Public ownership guarantees lower prices","D":"The profit motive can encourage greater efficiency"},"correctOption":"D","correctAnswer":"The profit motive can encourage greater efficiency","questionType":"MCQ","explanation":{"correct_reason":"Correct because the new owners improved service frequency and adjusted fares in order to raise profit, showing the pressure of the profit motive.","distractor_reasons":{"A":"Incorrect because fares were raised in the case, so lower prices are not guaranteed.","B":"Incorrect because private ownership offers no guarantee of profit, and many private firms do make losses.","C":"Incorrect because the state-owned company was already loss-making and required subsidy, so low prices were not sustained.","D":"Correct because the new owners improved service frequency and adjusted fares in order to raise profit, showing the pressure of the profit motive."}}},{"id":"P1_U1_MCQ_1033","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1033","question":"Ashcombe Logistics, a small logistics firm in the Netherlands, merges with a rival, closing one depot and sharing a delivery fleet so that annual costs fall by $1.4 million. Which benefit of integration does this show?","options":{"A":"Higher prices charged to customers","B":"Increased competition between the two firms","C":"Greater government regulation of the merged firm","D":"Cost savings from combining duplicate operations"},"correctOption":"D","correctAnswer":"Cost savings from combining duplicate operations","questionType":"MCQ","explanation":{"correct_reason":"Correct because closing a depot and sharing one fleet removes duplicated overheads, producing the $1.4 million annual saving.","distractor_reasons":{"A":"Incorrect because the case reports falling costs, not a pricing decision.","B":"Incorrect because the firms have merged, so rivalry between them ends.","C":"Incorrect because regulation is not mentioned and is not a benefit of merging.","D":"Correct because closing a depot and sharing one fleet removes duplicated overheads, producing the $1.4 million annual saving."}}},{"id":"P1_U1_MCQ_1034","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1034","question":"Ashcroft Dairy is a dairy cooperative in Denmark owned by two hundred farmers, each having one vote and sharing profit according to the litres of milk supplied. Which type of organisation is this?","options":{"A":"A public limited company","B":"A public corporation","C":"A cooperative","D":"A sole trader"},"correctOption":"C","correctAnswer":"A cooperative","questionType":"MCQ","explanation":{"correct_reason":"Correct because the plant is owned and democratically controlled by its farmer members, with benefits shared according to their supply.","distractor_reasons":{"A":"Incorrect because shares are not traded publicly and voting is one member one vote, not one share one vote.","B":"Incorrect because the plant is owned by farmers, not by the state.","C":"Correct because the plant is owned and democratically controlled by its farmer members, with benefits shared according to their supply.","D":"Incorrect because the plant has 200 owners rather than one."}}},{"id":"P1_U1_MCQ_1035","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1035","question":"Ashley Quarrying, a quarry in India, plans to expand onto farmland, creating 200 jobs and $6 million of extra annual sales. Which stakeholder is most concerned with collecting tax on the extra profit and enforcing planning rules?","options":{"A":"Local residents","B":"Customers","C":"Employees","D":"The government"},"correctOption":"D","correctAnswer":"The government","questionType":"MCQ","explanation":{"correct_reason":"Correct because government collects company tax and sets and enforces planning permission for the expansion.","distractor_reasons":{"A":"Incorrect because residents may object to noise or traffic but do not collect company tax.","B":"Incorrect because buyers of stone are concerned with price and supply, not planning enforcement.","C":"Incorrect because workers gain the 200 jobs and do not enforce planning law.","D":"Correct because government collects company tax and sets and enforces planning permission for the expansion."}}},{"id":"P1_U1_MCQ_1036","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1036","question":"Ashfield Ceramics, a ceramics studio in Portugal, sells a dinner plate for $24.00. Bought-in clay, glaze and packaging cost $15.00 per plate. What is the added value per plate expressed as a percentage of the selling price?","options":{"A":"60.0%","B":"37.5%","C":"62.5%, the share taken by bought-in materials","D":"9.0%"},"correctOption":"B","correctAnswer":"37.5%","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added is $24.00 - $15.00 = $9.00, and $9.00 divided by $24.00 multiplied by 100 gives 37.5%.","distractor_reasons":{"A":"Incorrect because 60% is the bought-in material cost as a share of the price ($15 divided by $24), not the value added share.","B":"Correct because value added is $24.00 - $15.00 = $9.00, and $9.00 divided by $24.00 multiplied by 100 gives 37.5%.","C":"Incorrect because 62.5% is $15.00 divided by $24.00, the proportion spent on materials, not the proportion added.","D":"Incorrect because $9.00 is a dollar amount, not a percentage; it must be divided by the $24.00 price first."}}},{"id":"P1_U1_MCQ_1037","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1037","question":"Economists at Ashwick Research, a research institute, report a country with a workforce of 2,000,000 people, of whom 340,000 work in agriculture, forestry and fishing. What share of the workforce is employed in the primary sector?","options":{"A":"34%","B":"6.8%","C":"17%","D":"83%"},"correctOption":"C","correctAnswer":"17%","questionType":"MCQ","explanation":{"correct_reason":"Correct because 340,000 divided by 2,000,000 is 0.17, which equals 17% of the workforce.","distractor_reasons":{"A":"Incorrect because 34% would mean 680,000 primary workers, double the number given.","B":"Incorrect because this comes from misplacing the decimal point when dividing 340,000 by 2,000,000.","C":"Correct because 340,000 divided by 2,000,000 is 0.17, which equals 17% of the workforce.","D":"Incorrect because 83% is the share of workers not in the primary sector."}}},{"id":"P1_U1_MCQ_1038","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1038","question":"After Ashcombe Engineering, a German engineering firm, took over a subsidiary, the two sales teams kept separate bonus schemes and blamed each other for lost orders; annual profit fell 18%. Which problem does this illustrate?","options":{"A":"A clash of organisational cultures after integration","B":"Economies of scale from sharing a sales force","C":"A shortage of working capital after the takeover","D":"Poor demand for engineering products in the market"},"correctOption":"A","correctAnswer":"A clash of organisational cultures after integration","questionType":"MCQ","explanation":{"correct_reason":"Correct because incompatible bonus schemes and mutual blame between the two sales teams show cultural and management differences damaging performance.","distractor_reasons":{"A":"Correct because incompatible bonus schemes and mutual blame between the two sales teams show cultural and management differences damaging performance.","B":"Incorrect because the two teams did not work together, so no scale benefit was achieved.","C":"Incorrect because the case describes behaviour and lost orders, not a lack of cash.","D":"Incorrect because the lost orders are attributed to internal blame between teams, not to market demand."}}},{"id":"P1_U1_MCQ_1039","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1039","question":"Ashgate Energy, a national government-owned electricity transmission company, must keep prices affordable in remote regions even at a loss. Which type of organisation is this?","options":{"A":"A private limited company","B":"A public corporation","C":"A cooperative","D":"A franchise"},"correctOption":"B","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Correct because the company is state owned and expected to meet a service obligation rather than to maximise profit.","distractor_reasons":{"A":"Incorrect because private companies are not normally required to supply loss-making remote areas at controlled prices.","B":"Correct because the company is state owned and expected to meet a service obligation rather than to maximise profit.","C":"Incorrect because the company is owned by government, not by member customers.","D":"Incorrect because there is no franchisor granting brand rights to independent operators."}}},{"id":"P1_U1_MCQ_1040","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1040","question":"Ashley Chemicals, a chemical plant in Spain, wants to route its tankers through a residential street at night to cut $500,000 from distribution costs. Which stakeholder group is most likely to object because of noise and safety?","options":{"A":"Shareholders","B":"Local residents","C":"Suppliers","D":"The government"},"correctOption":"B","correctAnswer":"Local residents","questionType":"MCQ","explanation":{"correct_reason":"Correct because people living on the street bear the nighttime noise and safety risk while gaining none of the $500,000 saving.","distractor_reasons":{"A":"Incorrect because shareholders gain from the $500,000 cost saving and are not exposed to the street-level disturbance.","B":"Correct because people living on the street bear the nighttime noise and safety risk while gaining none of the $500,000 saving.","C":"Incorrect because suppliers deliver to the plant and are not affected by the route through the residential street.","D":"Incorrect because the objection described concerns local noise and safety, not national policy."}}},{"id":"P1_U1_MCQ_1041","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1041","question":"Ashfield Pottery, a pottery in Thailand, sells mugs at $12 each, with bought-in clay and glaze costing $5. The owner wants to raise the value added per mug. Which change is most likely to achieve this?","options":{"A":"Cutting the workforce by 15%","B":"Producing 20% more mugs at the same price and material cost","C":"Adding $2 of packaging to each mug while holding the price at $12","D":"Redesigning the mug with hand-painted patterns and raising the price to $16 while materials stay at $5"},"correctOption":"D","correctAnswer":"Redesigning the mug with hand-painted patterns and raising the price to $16 while materials stay at $5","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added rises from $7 ($12 - $5) to $11 ($16 - $5) per mug, an increase of $4 per mug.","distractor_reasons":{"A":"Incorrect because staffing is not a bought-in material cost, so cutting jobs does not directly widen the gap between price and material cost.","B":"Incorrect because every mug still adds $7; selling more raises total value added but not value added per mug.","C":"Incorrect because bought-in cost rises to $7 and value added per mug falls from $7 to $5.","D":"Correct because value added rises from $7 ($12 - $5) to $11 ($16 - $5) per mug, an increase of $4 per mug."}}},{"id":"P1_U1_MCQ_1042","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1042","question":"Ashwick Development, a regional development agency, reports that a town's 8,000 workers were split 30% primary, 45% secondary and 25% tertiary. After a new call centre opened, the tertiary share rose to 33% while total employment stayed at 8,000. How many extra workers moved into tertiary jobs?","options":{"A":"2,000","B":"640","C":"2,640","D":"8,000"},"correctOption":"B","correctAnswer":"640","questionType":"MCQ","explanation":{"correct_reason":"Correct because tertiary employment rose from 25% of 8,000 (2,000 workers) to 33% of 8,000 (2,640 workers), a gain of 640.","distractor_reasons":{"A":"Incorrect because 2,000 was the number in tertiary jobs before the call centre opened, not the increase.","B":"Correct because tertiary employment rose from 25% of 8,000 (2,000 workers) to 33% of 8,000 (2,640 workers), a gain of 640.","C":"Incorrect because 2,640 is the total number in tertiary jobs afterwards, including the original 2,000.","D":"Incorrect because 8,000 is total employment, which did not change."}}},{"id":"P1_U1_MCQ_1043","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1043","question":"Ashcombe Software, a software firm in Estonia, grew revenue from $4.2 million to $5.25 million in one year. What was the percentage growth in revenue?","options":{"A":"25%","B":"20%","C":"105%","D":"80%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Correct because the increase is $1.05 million, and $1.05 million divided by $4.2 million equals 0.25, or 25%.","distractor_reasons":{"A":"Correct because the increase is $1.05 million, and $1.05 million divided by $4.2 million equals 0.25, or 25%.","B":"Incorrect because 20% of $4.2 million would be $0.84 million, giving revenue of $5.04 million, not $5.25 million.","C":"Incorrect because 105% is the increase expressed against the original figure incorrectly; the growth is a quarter.","D":"Incorrect because this is the original revenue as a share of the new figure, not the growth rate."}}},{"id":"P1_U1_MCQ_1044","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1044","question":"Ashgate Accountancy, a partnership in Cyprus, earns profit of $85,000. The agreement shares profit in the ratio 3:2 between the senior and junior partner. How much does the senior partner receive?","options":{"A":"$51,000","B":"$34,000","C":"$42,500","D":"$85,000"},"correctOption":"A","correctAnswer":"$51,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because the senior partner takes three of the five shares: $85,000 divided by 5 is $17,000, and 3 times $17,000 is $51,000.","distractor_reasons":{"A":"Correct because the senior partner takes three of the five shares: $85,000 divided by 5 is $17,000, and 3 times $17,000 is $51,000.","B":"Incorrect because $34,000 is the junior partner's two-fifths share.","C":"Incorrect because this splits the $85,000 equally, ignoring the 3:2 agreement.","D":"Incorrect because the whole profit is not paid to one partner under a 3:2 split."}}},{"id":"P1_U1_MCQ_1045","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1045","question":"A bakery in Australia trading as Ashmoor Bakery runs three shops and has annual revenue of $1.8 million against total costs of $1.52 million. What is its profit for the year?","options":{"A":"$1,520,000, total costs","B":"$28,000","C":"$280,000","D":"$3,320,000"},"correctOption":"C","correctAnswer":"$280,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because profit is revenue minus total costs: $1,800,000 - $1,520,000 = $280,000.","distractor_reasons":{"A":"Incorrect because total costs are an expense, not the profit earned.","B":"Incorrect because this misplaces a zero; the difference between the two figures is ten times larger.","C":"Correct because profit is revenue minus total costs: $1,800,000 - $1,520,000 = $280,000.","D":"Incorrect because this adds revenue and costs together instead of subtracting."}}},{"id":"P1_U1_MCQ_1046","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1046","question":"Ashfield Jewellery, a bead workshop in Kenya, once had each of its 12 artisans making a whole necklace, completing 18 necklaces a day. After splitting work into cutting, threading and finishing tasks, the same 12 artisans complete 30 necklaces a day. Which benefit of division of labour does this show?","options":{"A":"Lower wage costs because fewer artisans are needed","B":"Higher output per worker because each person repeats a single task","C":"Better quality because every artisan makes the whole necklace","D":"Lower material waste because tasks are rotated"},"correctOption":"B","correctAnswer":"Higher output per worker because each person repeats a single task","questionType":"MCQ","explanation":{"correct_reason":"Correct because output rose from 18 to 30 necklaces a day with the same 12 artisans, showing greater labour productivity through task specialisation.","distractor_reasons":{"A":"Incorrect because all 12 artisans are still employed, so no wage bill saving is described.","B":"Correct because output rose from 18 to 30 necklaces a day with the same 12 artisans, showing greater labour productivity through task specialisation.","C":"Incorrect because each artisan now makes only part of a necklace, which is the opposite of the statement.","D":"Incorrect because the stem reports nothing about materials or waste."}}},{"id":"P1_U1_MCQ_1047","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1047","question":"The statistics office cited by Ashdale Research, a business lobby group, reports that Norway has a GDP of $480 billion, with manufacturing output valued at $132 billion. What is manufacturing's share of GDP?","options":{"A":"13.2%","B":"36.4%","C":"27.5%","D":"132%"},"correctOption":"C","correctAnswer":"27.5%","questionType":"MCQ","explanation":{"correct_reason":"Correct because $132 billion divided by $480 billion is 0.275, or 27.5% of GDP.","distractor_reasons":{"A":"Incorrect because this comes from halving the correct percentage by mistake; the actual division gives 27.5%.","B":"Incorrect because this is $480 billion divided by $132 billion, the ratio inverted.","C":"Correct because $132 billion divided by $480 billion is 0.275, or 27.5% of GDP.","D":"Incorrect because a sector's share of GDP cannot exceed 100%, and the figure is simply the unadjusted dollar value."}}},{"id":"P1_U1_MCQ_1048","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1048","question":"Ashcombe Electronics, an online retailer in Singapore, employs 300 staff and earns annual revenue of $27 million from sales across the region. What is its revenue per employee?","options":{"A":"$9,000","B":"$90,000","C":"$900,000","D":"$2.7 million"},"correctOption":"B","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because $27,000,000 divided by 300 employees gives $90,000 of revenue per employee.","distractor_reasons":{"A":"Incorrect because this result comes from dividing by 3,000 rather than 300 employees.","B":"Correct because $27,000,000 divided by 300 employees gives $90,000 of revenue per employee.","C":"Incorrect because this treats 300 as 30 employees, making the figure ten times too large.","D":"Incorrect because this is revenue per 10 employees, not per single employee."}}},{"id":"P1_U1_MCQ_1049","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1049","question":"Ashgate Printing, a private limited company in Poland, makes profit after tax of $240,000. It pays a dividend of $0.30 on each of its 500,000 shares. How much profit is retained in the business?","options":{"A":"$90,000","B":"$150,000, the total dividend paid","C":"$240,000, the whole profit after tax","D":"$75,000"},"correctOption":"A","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because dividends total $150,000 (500,000 shares at $0.30), so $240,000 minus $150,000 leaves $90,000 retained.","distractor_reasons":{"A":"Correct because dividends total $150,000 (500,000 shares at $0.30), so $240,000 minus $150,000 leaves $90,000 retained.","B":"Incorrect because $150,000 is distributed to shareholders, not kept in the business.","C":"Incorrect because this ignores the dividend that has been paid out.","D":"Incorrect because this would require a dividend of $165,000, which does not match $0.30 per share on 500,000 shares."}}},{"id":"P1_U1_MCQ_1050","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1050","question":"Ashmoor Fashion, a clothing retailer in Canada, has annual revenue of $4.5 million and makes a profit of $540,000 before tax. What is its profit margin for the year?","options":{"A":"8.3%","B":"88%","C":"12%","D":"45%"},"correctOption":"C","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Correct because $540,000 divided by $4,500,000 equals 0.12, or 12% of revenue.","distractor_reasons":{"A":"Incorrect because this divides revenue by profit, reversing the calculation.","B":"Incorrect because this is the share of revenue taken by costs, not the profit margin.","C":"Correct because $540,000 divided by $4,500,000 equals 0.12, or 12% of revenue.","D":"Incorrect because 45 is the revenue figure in hundreds of thousands, not a percentage."}}},{"id":"P1_U1_MCQ_1051","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1051","question":"Ashfield Fashion, a garment factory in Bangladesh, reorganised its sewing room into single repetitive tasks. Output rose, but absence rose from 3% to 9% of staff and several workers complained that the work was boring. Which disadvantage of division of labour does this describe?","options":{"A":"Higher training costs for multi-skilled staff","B":"Slower production because workers must swap tasks","C":"Worker boredom and demotivation from repetitive work","D":"Higher material costs from greater waste"},"correctOption":"C","correctAnswer":"Worker boredom and demotivation from repetitive work","questionType":"MCQ","explanation":{"correct_reason":"Correct because the rise in absence from 3% to 9% and complaints about boring work show the motivational cost of narrow, repetitive tasks.","distractor_reasons":{"A":"Incorrect because the new system narrows each job rather than creating multi-skilled staff, and no training figures are given.","B":"Incorrect because output rose in the case, so speed is not the problem described.","C":"Correct because the rise in absence from 3% to 9% and complaints about boring work show the motivational cost of narrow, repetitive tasks.","D":"Incorrect because the case mentions no material or waste data."}}},{"id":"P1_U1_MCQ_1052","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1052","question":"Ashdale Recruitment, a recruitment agency, notes that a country employs 4.5 million workers, of whom 28% work in manufacturing and construction. How many workers is that?","options":{"A":"126,000","B":"2,160,000","C":"450,000","D":"1,260,000"},"correctOption":"D","correctAnswer":"1,260,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because 4.5 million multiplied by 0.28 equals 1.26 million workers in manufacturing and construction.","distractor_reasons":{"A":"Incorrect because this is ten times too small; 28% of 4.5 million is over a million workers.","B":"Incorrect because this would be 48% of the workforce, not 28%.","C":"Incorrect because 450,000 is 10% of 4.5 million, not 28%.","D":"Correct because 4.5 million multiplied by 0.28 equals 1.26 million workers in manufacturing and construction."}}},{"id":"P1_U1_MCQ_1053","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1053","question":"Ashcombe Foods, a supermarket chain, sold $54 million in a market worth $300 million. The next year it sold $63 million in a market worth $315 million. By how many percentage points did its market share change?","options":{"A":"3 percentage points","B":"9 percentage points","C":"18 percentage points","D":"2 percentage points"},"correctOption":"D","correctAnswer":"2 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Correct because the share rose from 18% ($54m of $300m) to 20% ($63m of $315m), a change of 2 percentage points.","distractor_reasons":{"A":"Incorrect because this uses the $9 million sales increase as though it were a change in share.","B":"Incorrect because 9 is the increase in sales in millions, not a change in market share.","C":"Incorrect because 18% was the original share, not the change.","D":"Correct because the share rose from 18% ($54m of $300m) to 20% ($63m of $315m), a change of 2 percentage points."}}},{"id":"P1_U1_MCQ_1054","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1054","question":"Ashgate Cafes, a franchisee in Qatar, sells $320,000 worth of goods in a year and pays a royalty of 8% of sales plus a fixed fee of $15,000. What is the total payment to the franchisor?","options":{"A":"$40,600","B":"$25,600, the royalty on sales","C":"$15,000, the fixed fee","D":"$55,600"},"correctOption":"A","correctAnswer":"$40,600","questionType":"MCQ","explanation":{"correct_reason":"Correct because the royalty is 8% of $320,000, which is $25,600, and adding the $15,000 fixed fee gives $40,600.","distractor_reasons":{"A":"Correct because the royalty is 8% of $320,000, which is $25,600, and adding the $15,000 fixed fee gives $40,600.","B":"Incorrect because the fixed fee of $15,000 must also be added to the royalty.","C":"Incorrect because this ignores the royalty of $25,600 on sales.","D":"Incorrect because this adds the $15,000 fee twice, or applies the royalty to an inflated sales figure."}}},{"id":"P1_U1_MCQ_1055","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1055","question":"Ashmoor Pharmacy, a company in Switzerland, makes profit after tax of $180,000. The board keeps 40% as retained profit and distributes the rest as dividends across 300,000 shares. What dividend is paid per share?","options":{"A":"$0.24","B":"$0.60","C":"$0.18","D":"$0.36"},"correctOption":"D","correctAnswer":"$0.36","questionType":"MCQ","explanation":{"correct_reason":"Correct because dividends total 60% of $180,000, which is $108,000, and $108,000 divided by 300,000 shares is $0.36.","distractor_reasons":{"A":"Incorrect because this pays out only 40% of profit, which is the share retained rather than distributed.","B":"Incorrect because this treats the whole $180,000 as dividends before applying the 60% payout.","C":"Incorrect because this divides profit by one million shares rather than 300,000.","D":"Correct because dividends total 60% of $180,000, which is $108,000, and $108,000 divided by 300,000 shares is $0.36."}}},{"id":"P1_U1_MCQ_1056","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1056","question":"Ashford Ceramics, a pottery in Portugal, employs 15 workers who produce 3,600 plant pots a week. After introducing division of labour, weekly output rises by 20% with the same workforce. What is the new weekly output per worker?","options":{"A":"240 pots, the output per worker before the change","B":"288 pots","C":"300 pots","D":"4,320 pots"},"correctOption":"B","correctAnswer":"288 pots","questionType":"MCQ","explanation":{"correct_reason":"Correct because output rises from 3,600 to 4,320 pots, and 4,320 divided by 15 workers gives 288 pots per worker.","distractor_reasons":{"A":"Incorrect because 240 is the original figure (3,600 divided by 15), before the 20% rise.","B":"Correct because output rises from 3,600 to 4,320 pots, and 4,320 divided by 15 workers gives 288 pots per worker.","C":"Incorrect because 300 per worker would need weekly output of 4,500 pots, more than the 20% increase allows.","D":"Incorrect because 4,320 is total weekly output, not output per worker."}}},{"id":"P1_U1_MCQ_1057","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1057","question":"Ashdale Trust, a rural development charity, reports that primary sector employment in a region fell from 640,000 to 512,000 in five years as farms and mines mechanised. What was the percentage fall?","options":{"A":"12.8%","B":"25%","C":"80%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Correct because the fall is 128,000 workers, and 128,000 divided by the original 640,000 equals 20%.","distractor_reasons":{"A":"Incorrect because 12.8% confuses the absolute fall of 128,000 with a percentage of the workforce.","B":"Incorrect because 25% would be a fall of 160,000 workers, more than actually occurred.","C":"Incorrect because 80% is the share of primary jobs that remained (512,000 of 640,000).","D":"Correct because the fall is 128,000 workers, and 128,000 divided by the original 640,000 equals 20%."}}},{"id":"P1_U1_MCQ_1058","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1058","question":"Ashcombe Packaging, a packaging plant, employs 200 workers who produce 5,000 boxes a day. To raise output to 6,500 boxes at the same productivity per worker, how many workers are needed?","options":{"A":"200 workers","B":"260 workers","C":"325 workers","D":"300 workers"},"correctOption":"B","correctAnswer":"260 workers","questionType":"MCQ","explanation":{"correct_reason":"Correct because each worker makes 25 boxes, and 6,500 divided by 25 gives 260 workers.","distractor_reasons":{"A":"Incorrect because 200 workers would still produce only 5,000 boxes at 25 each.","B":"Correct because each worker makes 25 boxes, and 6,500 divided by 25 gives 260 workers.","C":"Incorrect because this would produce 8,125 boxes, far above the 6,500 target.","D":"Incorrect because 300 workers at 25 boxes each would make 7,500 boxes, more than required."}}},{"id":"P1_U1_MCQ_1059","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1059","question":"Ashgate Hardware, a sole trader in Bulgaria, has inventory worth $32,000, trade receivables of $21,000, cash of $15,000 and current liabilities of $40,000. What is the working capital?","options":{"A":"$68,000, total current assets","B":"$40,000, total current liabilities","C":"$108,000","D":"$28,000"},"correctOption":"D","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because current assets total $68,000 ($32,000 + $21,000 + $15,000) and $68,000 minus $40,000 of current liabilities is $28,000.","distractor_reasons":{"A":"Incorrect because current liabilities of $40,000 have not been deducted.","B":"Incorrect because working capital is the surplus of current assets over liabilities, not the liabilities themselves.","C":"Incorrect because this adds liabilities to current assets instead of subtracting them.","D":"Correct because current assets total $68,000 ($32,000 + $21,000 + $15,000) and $68,000 minus $40,000 of current liabilities is $28,000."}}},{"id":"P1_U1_MCQ_1060","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1060","question":"Ashmoor Ceramics, a ceramics workshop in Tunisia, has fixed costs of $84,000 a year, sells each vase for $25 and has variable costs of $11 per vase. What is the break-even output?","options":{"A":"3,360 vases","B":"6,000 vases","C":"7,636 vases","D":"8,400 vases"},"correctOption":"B","correctAnswer":"6,000 vases","questionType":"MCQ","explanation":{"correct_reason":"Correct because contribution per vase is $25 - $11 = $14, and $84,000 divided by $14 gives 6,000 vases.","distractor_reasons":{"A":"Incorrect because this divides fixed costs by the $25 selling price instead of by contribution.","B":"Correct because contribution per vase is $25 - $11 = $14, and $84,000 divided by $14 gives 6,000 vases.","C":"Incorrect because this divides fixed costs by the $11 variable cost, which is not contribution.","D":"Incorrect because this divides $84,000 by $10, a contribution figure that does not match the data."}}},{"id":"P1_U1_MCQ_1061","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1061","question":"Ashford Bakery, a bakery in Poland, buys flour, hires bakers, rents an oven and sells bread to local households. Which statement best explains the purpose of this business activity?","options":{"A":"It combines factors of production to make output that satisfies customer wants","B":"It exists mainly to provide employment for local bakers","C":"It aims to increase the amount of flour produced in Poland","D":"It exists to collect taxes for the government"},"correctOption":"A","correctAnswer":"It combines factors of production to make output that satisfies customer wants","questionType":"MCQ","explanation":{"correct_reason":"Correct because the bakery transforms bought-in materials, labour and capital into bread that households want and are willing to pay for.","distractor_reasons":{"A":"Correct because the bakery transforms bought-in materials, labour and capital into bread that households want and are willing to pay for.","B":"Incorrect because employment is a result of the business, not its main purpose, which is to meet customer wants.","C":"Incorrect because the bakery buys flour rather than producing it, so it does not add to flour output.","D":"Incorrect because tax collection is a government function; the bakery pays tax rather than collecting it."}}},{"id":"P1_U1_MCQ_1062","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1062","question":"Ashdale Consulting, a commodities analyst, notes that a country earns 70% of its export revenue from unprocessed copper, and world copper prices fell by 25% last year. Which risk does this concentration create?","options":{"A":"Manufacturing output will rise as copper prices fall","B":"The country becomes less dependent on primary exports","C":"Domestic food prices are unaffected by the fall","D":"Export earnings and government revenue fall sharply when commodity prices drop"},"correctOption":"D","correctAnswer":"Export earnings and government revenue fall sharply when commodity prices drop","questionType":"MCQ","explanation":{"correct_reason":"Correct because with 70% of export revenue tied to copper, a 25% price fall cuts earnings and the tax revenue that depends on them.","distractor_reasons":{"A":"Incorrect because cheap copper does not automatically create manufacturing capacity, and no such link is described.","B":"Incorrect because concentrating on one commodity increases dependence rather than reducing it.","C":"Incorrect because the question concerns vulnerability of export earnings, and the claim ignores the wider economic impact.","D":"Correct because with 70% of export revenue tied to copper, a 25% price fall cuts earnings and the tax revenue that depends on them."}}},{"id":"P1_U1_MCQ_1063","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1063","question":"Ashcombe Fashion, a two-person tailoring business in Croatia, can alter a wedding suit within 24 hours because the owner knows each customer personally. Which advantage of small firms does this show?","options":{"A":"Lower average costs from bulk buying","B":"Greater access to stock-market finance","C":"Wider range of products than large rivals","D":"Personal service and the flexibility to respond quickly"},"correctOption":"D","correctAnswer":"Personal service and the flexibility to respond quickly","questionType":"MCQ","explanation":{"correct_reason":"Correct because a small team dealing directly with known customers can complete a 24-hour alteration that a larger firm might not.","distractor_reasons":{"A":"Incorrect because small firms buy in small quantities and usually pay more per unit, not less.","B":"Incorrect because a two-person business cannot raise funds by selling shares publicly.","C":"Incorrect because the case describes fast personal service, not a broader product range.","D":"Correct because a small team dealing directly with known customers can complete a 24-hour alteration that a larger firm might not."}}},{"id":"P1_U1_MCQ_1064","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1064","question":"Partners at Ashholm Printing, a small printing business, report current assets of $54,000, made up of inventory $24,000, receivables $18,000 and cash $12,000. Current liabilities are $30,000. What is the current ratio?","options":{"A":"1.5 : 1","B":"2.4 : 1","C":"0.56 : 1","D":"1.8 : 1"},"correctOption":"D","correctAnswer":"1.8 : 1","questionType":"MCQ","explanation":{"correct_reason":"Correct because current assets of $54,000 divided by current liabilities of $30,000 equals 1.8, written as 1.8 : 1.","distractor_reasons":{"A":"Incorrect because this ratio would require current assets of $45,000, not $54,000.","B":"Incorrect because this figure comes from comparing only part of the assets with a wrong liability total, not total current assets of $54,000 with $30,000.","C":"Incorrect because this reverses the calculation, dividing liabilities by assets.","D":"Correct because current assets of $54,000 divided by current liabilities of $30,000 equals 1.8, written as 1.8 : 1."}}},{"id":"P1_U1_MCQ_1065","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1065","question":"Ashmoor Printing, a printer in Latvia, has a break-even output of 4,000 units a month and currently produces and sells 5,600 units. What is its margin of safety?","options":{"A":"4,000 units","B":"5,600 units","C":"1,600 units","D":"1,400 units"},"correctOption":"C","correctAnswer":"1,600 units","questionType":"MCQ","explanation":{"correct_reason":"Correct because margin of safety is current output minus break-even output: 5,600 - 4,000 = 1,600 units.","distractor_reasons":{"A":"Incorrect because 4,000 is the break-even output, not the cushion above it.","B":"Incorrect because 5,600 is total current output, which includes the break-even volume.","C":"Correct because margin of safety is current output minus break-even output: 5,600 - 4,000 = 1,600 units.","D":"Incorrect because this would need current output of 5,400 units, not 5,600."}}},{"id":"P1_U1_MCQ_1066","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1066","question":"Ashford Tours, a firm in Malaysia, runs airport transfer minibuses and also sells branded T-shirts from a kiosk. Which statement correctly classifies these two products?","options":{"A":"The minibus transfer is a service and the T-shirt is a good","B":"Both products are services because both are sold to travellers","C":"The minibus transfer is a good and the T-shirt is a service","D":"Both products are goods because the firm earns revenue from each"},"correctOption":"A","correctAnswer":"The minibus transfer is a service and the T-shirt is a good","questionType":"MCQ","explanation":{"correct_reason":"Correct because a transfer is intangible and consumed as it is provided, while a T-shirt is a tangible physical product that can be stored and owned.","distractor_reasons":{"A":"Correct because a transfer is intangible and consumed as it is provided, while a T-shirt is a tangible physical product that can be stored and owned.","B":"Incorrect because being sold to travellers does not make a T-shirt intangible.","C":"Incorrect because the classifications are reversed: transport is intangible and clothing is tangible.","D":"Incorrect because earning revenue does not confer tangibility, and a transfer remains a service."}}},{"id":"P1_U1_MCQ_1067","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1067","question":"In a coastal town studied by Ashton Consulting, a tourism consultancy, tourism has created 1,500 hotel, guide and catering jobs while the fish catch has stayed the same. What is a likely benefit of this growth in the tertiary sector?","options":{"A":"More employment without putting extra pressure on fish stocks","B":"Higher fish catches because tourists eat more seafood","C":"Fewer jobs overall because hotels replace fishing","D":"A fall in the town's export earnings from services"},"correctOption":"A","correctAnswer":"More employment without putting extra pressure on fish stocks","questionType":"MCQ","explanation":{"correct_reason":"Correct because 1,500 service jobs were added while the catch stayed constant, so incomes rise without extra extraction.","distractor_reasons":{"A":"Correct because 1,500 service jobs were added while the catch stayed constant, so incomes rise without extra extraction.","B":"Incorrect because the stem states the catch has stayed the same.","C":"Incorrect because 1,500 jobs were created, which is additional employment.","D":"Incorrect because tourist spending brings money into the town, and no fall in earnings is described."}}},{"id":"P1_U1_MCQ_1068","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1068","question":"Ashcombe Brewing, a large brewery in Mexico, buys barley in bulk at 12% below the price paid by small local breweries. Which advantage of large-scale operation does this show?","options":{"A":"Technical economies from better machinery","B":"Marketing economies from national advertising","C":"Purchasing economies of scale","D":"Financial economies from cheaper borrowing"},"correctOption":"C","correctAnswer":"Purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Correct because buying barley in large quantities lowers the price per unit by 12%, which is a purchasing economy.","distractor_reasons":{"A":"Incorrect because the saving comes from the price of barley, not from machinery.","B":"Incorrect because no advertising or brand spending is described.","C":"Correct because buying barley in large quantities lowers the price per unit by 12%, which is a purchasing economy.","D":"Incorrect because the discount applies to raw material purchases, not interest rates."}}},{"id":"P1_U1_MCQ_1069","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1069","question":"Ashholm Metals, a private limited company in Chile, owes $300,000 to suppliers and holds assets worth $180,000. Its two shareholders have fully paid for their shares and hold $500,000 of personal savings. How much of the debt must the shareholders pay from personal funds?","options":{"A":"$120,000, the shortfall between debts and assets","B":"$300,000, the full amount owed","C":"Nothing, because limited liability protects their personal assets","D":"$500,000, all of their personal savings"},"correctOption":"C","correctAnswer":"Nothing, because limited liability protects their personal assets","questionType":"MCQ","explanation":{"correct_reason":"Correct because the shareholders have fully paid for their shares, so their personal savings are protected and the company's assets cover only part of the debt.","distractor_reasons":{"A":"Incorrect because limited liability means shareholders are not required to cover the company's shortfall from personal funds.","B":"Incorrect because the debt belongs to the company, not to the shareholders personally.","C":"Correct because the shareholders have fully paid for their shares, so their personal savings are protected and the company's assets cover only part of the debt.","D":"Incorrect because limited liability exists precisely to protect personal savings beyond the share capital paid."}}},{"id":"P1_U1_MCQ_1070","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1070","question":"Ashmoor Lighting, a candle maker in Belgium, has fixed costs of $60,000, a selling price of $9 per candle and variable costs of $4 per candle. How many candles must it sell to make a profit of $30,000?","options":{"A":"18,000 candles","B":"12,000 candles","C":"22,500 candles","D":"6,667 candles"},"correctOption":"A","correctAnswer":"18,000 candles","questionType":"MCQ","explanation":{"correct_reason":"Correct because contribution is $5 per candle, and fixed costs plus target profit of $90,000 divided by $5 gives 18,000 candles.","distractor_reasons":{"A":"Correct because contribution is $5 per candle, and fixed costs plus target profit of $90,000 divided by $5 gives 18,000 candles.","B":"Incorrect because 12,000 covers the $60,000 fixed costs only, leaving no profit.","C":"Incorrect because this divides $90,000 by $4, the variable cost, instead of by contribution.","D":"Incorrect because this divides the $60,000 fixed cost by $9, the selling price, ignoring variable costs and target profit."}}},{"id":"P1_U1_MCQ_1071","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1071","question":"Ashford Cafes, a cafe in South Africa, has $12,000 to spend on one item. A new coffee machine would raise annual profit by $9,000; a second oven would raise annual profit by $18,000. The owner buys the coffee machine. What is the opportunity cost?","options":{"A":"$18,000 a year of profit forgone from the second oven","B":"$9,000 a year, the profit from the coffee machine","C":"$12,000, the amount spent","D":"$6,000, the gap between the two profit figures"},"correctOption":"A","correctAnswer":"$18,000 a year of profit forgone from the second oven","questionType":"MCQ","explanation":{"correct_reason":"Correct because opportunity cost is the value of the best alternative given up, which is the $18,000 of annual profit the oven would have generated.","distractor_reasons":{"A":"Correct because opportunity cost is the value of the best alternative given up, which is the $18,000 of annual profit the oven would have generated.","B":"Incorrect because $9,000 is the gain actually received, not the alternative that was given up.","C":"Incorrect because the same $12,000 would be spent on either item, so the cash itself is not the forgone benefit.","D":"Incorrect because the whole $18,000 of oven profit is sacrificed, not just the $6,000 difference."}}},{"id":"P1_U1_MCQ_1072","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1072","question":"Ashton Council is a municipality that installs street lights everyone can use without paying individually, and no private firm is willing to fund them. Why does the public sector provide this service?","options":{"A":"The service benefits the whole community and cannot easily be charged for","B":"Street lighting would be more profitable for a private firm","C":"Private firms are legally banned from selling any services","D":"The service is a luxury good demanded only by wealthy residents"},"correctOption":"A","correctAnswer":"The service benefits the whole community and cannot easily be charged for","questionType":"MCQ","explanation":{"correct_reason":"Correct because street lighting benefits all users at once and it is impractical to charge each person, so private firms cannot profit from it.","distractor_reasons":{"A":"Correct because street lighting benefits all users at once and it is impractical to charge each person, so private firms cannot profit from it.","B":"Incorrect because the stem says no private firm is willing to fund it, so profit cannot be the reason.","C":"Incorrect because private firms sell many services; the issue is the nature of street lighting.","D":"Incorrect because street lighting is a basic public service used by the whole community."}}},{"id":"P1_U1_MCQ_1073","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1073","question":"Ashcombe Furniture, a furniture manufacturer with 1,200 staff, found that head-office approval for small purchases now takes ten days, slowing production and raising costs. Which concept does this describe?","options":{"A":"Diseconomies of scale caused by poor coordination","B":"Economies of scale from bulk purchasing","C":"Organic growth through new product ranges","D":"Improved labour productivity from specialisation"},"correctOption":"A","correctAnswer":"Diseconomies of scale caused by poor coordination","questionType":"MCQ","explanation":{"correct_reason":"Correct because growth to 1,200 staff has lengthened decision-making and slowed production, raising average costs.","distractor_reasons":{"A":"Correct because growth to 1,200 staff has lengthened decision-making and slowed production, raising average costs.","B":"Incorrect because costs are rising and delays are worsening, the opposite of a scale economy.","C":"Incorrect because the case is about internal inefficiency, not expansion into new products.","D":"Incorrect because production has slowed, so productivity is not improving."}}},{"id":"P1_U1_MCQ_1074","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1074","question":"Ashholm Bakery is a bakery in Morocco whose owner keeps all the profit, sets prices without consulting anyone and closes early on quiet days. Which advantage of being a sole trader does this show?","options":{"A":"Shared decision-making with partners","B":"Full control and the freedom to act quickly","C":"Limited liability for business debts","D":"Access to stock-market finance for expansion"},"correctOption":"B","correctAnswer":"Full control and the freedom to act quickly","questionType":"MCQ","explanation":{"correct_reason":"Correct because the owner makes pricing and opening decisions alone and keeps the profit, which are key advantages of sole trading.","distractor_reasons":{"A":"Incorrect because the owner consults nobody, which is the opposite of shared decisions.","B":"Correct because the owner makes pricing and opening decisions alone and keeps the profit, which are key advantages of sole trading.","C":"Incorrect because a sole trader has unlimited liability.","D":"Incorrect because sole traders cannot issue shares to the public."}}},{"id":"P1_U1_MCQ_1075","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1075","question":"Ashmoor Furniture, a retail chain in the United Kingdom, extends payment terms to suppliers from 30 days to 90 days so that more cash is available to pay dividends. Which two stakeholder groups are in direct conflict?","options":{"A":"Shareholders and suppliers","B":"Customers and employees","C":"Government and local residents","D":"Managers and customers"},"correctOption":"A","correctAnswer":"Shareholders and suppliers","questionType":"MCQ","explanation":{"correct_reason":"Correct because shareholders gain from higher dividends while suppliers wait up to 90 days for payment, straining their cash flow.","distractor_reasons":{"A":"Correct because shareholders gain from higher dividends while suppliers wait up to 90 days for payment, straining their cash flow.","B":"Incorrect because neither group is directly affected by the change in supplier payment terms.","C":"Incorrect because no tax or community matter is involved in the payment terms.","D":"Incorrect because the cash released goes to shareholders, not managers, and customers are unaffected."}}},{"id":"P1_U1_MCQ_1076","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1076","question":"Ashbury Bakery, a bakery in the Czech Republic, cut the price of a loaf from $6.00 to $5.40 to win back customers. Bought-in flour and yeast still cost $2.10 per loaf. By how much did value added per loaf fall?","options":{"A":"$3.30, the new value added per loaf","B":"$3.90, the original value added per loaf","C":"$0.60","D":"$2.10, the material cost per loaf"},"correctOption":"C","correctAnswer":"$0.60","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added was $6.00 - $2.10 = $3.90 and is now $5.40 - $2.10 = $3.30, a fall of $0.60.","distractor_reasons":{"A":"Incorrect because $3.30 is the value added that remains, not the amount lost.","B":"Incorrect because $3.90 is the starting figure; the fall is the difference between the two figures.","C":"Correct because value added was $6.00 - $2.10 = $3.90 and is now $5.40 - $2.10 = $3.30, a fall of $0.60.","D":"Incorrect because the material cost did not change, so it cannot be the amount by which value added fell."}}},{"id":"P1_U1_MCQ_1077","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1077","question":"Ashton Timber is a forestry firm that fells timber; a sawmill cuts the logs into boards, and a courier delivers the boards to builders. Which sequence correctly shows the chain of production?","options":{"A":"Secondary forestry, then primary sawmill, then tertiary courier","B":"Primary forestry, then secondary sawmill, then tertiary courier","C":"Primary forestry, then tertiary sawmill, then secondary courier","D":"Tertiary forestry, then secondary sawmill, then primary courier"},"correctOption":"B","correctAnswer":"Primary forestry, then secondary sawmill, then tertiary courier","questionType":"MCQ","explanation":{"correct_reason":"Correct because felling timber extracts a natural resource, cutting boards processes it, and delivery provides a service.","distractor_reasons":{"A":"Incorrect because felling trees is extraction, not manufacturing, so forestry cannot be secondary.","B":"Correct because felling timber extracts a natural resource, cutting boards processes it, and delivery provides a service.","C":"Incorrect because sawing boards is manufacturing, while delivery is a service, so these two are swapped.","D":"Incorrect because forestry and delivery are misclassified, leaving only the sawmill correct."}}},{"id":"P1_U1_MCQ_1078","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1078","question":"Ashstead Bakery is a family bakery in Italy whose owner rejects a merger that would triple sales, preferring to keep control and avoid borrowing. Which reason for staying small does this show?","options":{"A":"The owner's wish to retain control and avoid financial risk","B":"A desire to benefit from bulk-buying discounts","C":"Pressure from the government to remain small","D":"The need to satisfy shareholders who want rapid growth"},"correctOption":"A","correctAnswer":"The owner's wish to retain control and avoid financial risk","questionType":"MCQ","explanation":{"correct_reason":"Correct because the owner values decision-making control and is unwilling to take on the borrowing and shared ownership a merger would require.","distractor_reasons":{"A":"Correct because the owner values decision-making control and is unwilling to take on the borrowing and shared ownership a merger would require.","B":"Incorrect because staying small usually means losing such discounts, not gaining them.","C":"Incorrect because no government policy is mentioned.","D":"Incorrect because a family bakery owner is not answerable to outside shareholders seeking growth."}}},{"id":"P1_U1_MCQ_1079","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1079","question":"Small cocoa growers in Ghana join a cooperative that negotiates a price 14% above what each could obtain alone and shares the cost of storage. Which benefit does the cooperative provide?","options":{"A":"Stronger bargaining power and shared costs for members","B":"Limited liability for every member's other business debts","C":"The right to sell shares on a stock exchange","D":"Freedom from paying any tax on member sales"},"correctOption":"A","correctAnswer":"Stronger bargaining power and shared costs for members","questionType":"MCQ","explanation":{"correct_reason":"Correct because acting together wins a price 14% higher than individual sales and spreads storage costs across members.","distractor_reasons":{"A":"Correct because acting together wins a price 14% higher than individual sales and spreads storage costs across members.","B":"Incorrect because the cooperative's benefit described is bargaining and shared costs, not protection from unrelated debts.","C":"Incorrect because cooperatives are owned by members and do not float shares publicly.","D":"Incorrect because no tax exemption is described or implied by joining a cooperative."}}},{"id":"P1_U1_MCQ_1080","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1080","question":"Ashmoor Metals, an engineering firm in the Netherlands, needs to replace worn machines costing $2 million over the next three years. Why is earning profit important for this plan?","options":{"A":"Profit guarantees that customers will buy the new machines' output","B":"Profit is the amount the firm must pay to its suppliers","C":"Profit can be retained to fund investment without borrowing","D":"Profit reduces the price of machinery automatically"},"correctOption":"C","correctAnswer":"Profit can be retained to fund investment without borrowing","questionType":"MCQ","explanation":{"correct_reason":"Correct because profit kept in the business provides internal finance for the $2 million of machinery, avoiding interest costs.","distractor_reasons":{"A":"Incorrect because profit funds investment but does not guarantee future demand.","B":"Incorrect because supplier payments are costs, not profit.","C":"Correct because profit kept in the business provides internal finance for the $2 million of machinery, avoiding interest costs.","D":"Incorrect because machinery prices are set by suppliers and are unaffected by the buyer's profit."}}},{"id":"P1_U1_MCQ_1081","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1081","question":"Ashbury Furniture, a furniture maker in Romania, adds $40 of value to each chair and sells 5,000 chairs a year. Why is this added value important to the business?","options":{"A":"It is the same as the firm's total revenue","B":"It measures how many chairs the firm sells","C":"It is the amount the firm pays in tax","D":"It helps cover wages, rent and other costs and can leave a profit"},"correctOption":"D","correctAnswer":"It helps cover wages, rent and other costs and can leave a profit","questionType":"MCQ","explanation":{"correct_reason":"Correct because $40 per chair, or $200,000 across 5,000 chairs, is the pool from which all other costs are paid and any profit must come.","distractor_reasons":{"A":"Incorrect because value added excludes bought-in materials, so it is smaller than total revenue.","B":"Incorrect because volume is shown by the 5,000 chairs, while value added measures the margin on each chair.","C":"Incorrect because tax is based on profit, not on value added per unit.","D":"Correct because $40 per chair, or $200,000 across 5,000 chairs, is the pool from which all other costs are paid and any profit must come."}}},{"id":"P1_U1_MCQ_1082","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1082","question":"Ashton Statistics, a government statistics unit, reports total output in a small economy of $90 million, with the tertiary sector supplying 60% and the primary sector 15%. What is the value of secondary sector output?","options":{"A":"$13.5 million","B":"$22.5 million","C":"$54 million","D":"$25 million"},"correctOption":"B","correctAnswer":"$22.5 million","questionType":"MCQ","explanation":{"correct_reason":"Correct because secondary output is the remaining 25% of $90 million, which is $22.5 million.","distractor_reasons":{"A":"Incorrect because $13.5 million is the primary sector's 15% of output.","B":"Correct because secondary output is the remaining 25% of $90 million, which is $22.5 million.","C":"Incorrect because $54 million is the tertiary sector's 60% of output.","D":"Incorrect because 25 is a percentage, not a value in millions of dollars; it must be applied to $90 million."}}},{"id":"P1_U1_MCQ_1083","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1083","question":"Ashstead Hotels, a hotel group in Greece, expanded from 480 to 600 employees after opening a new resort. By what percentage did its workforce grow?","options":{"A":"20%","B":"25%","C":"80%","D":"120%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Correct because the increase is 120 employees, and 120 divided by 480 equals 0.25, or 25%.","distractor_reasons":{"A":"Incorrect because 20% of 480 would be 96 employees, giving a total of 576 rather than 600.","B":"Correct because the increase is 120 employees, and 120 divided by 480 equals 0.25, or 25%.","C":"Incorrect because this is the original workforce as a share of the new total.","D":"Incorrect because 120 is the number of extra employees, not a percentage."}}},{"id":"P1_U1_MCQ_1084","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1084","question":"Ashholm Post is the state-owned postal service in Portugal, required to deliver to every village, including remote ones, and subsidised for the loss this makes. Which objective is it pursuing?","options":{"A":"The franchisee cannot use the brand's proven recipes","B":"The franchisor takes all of the outlet's revenue","C":"Royalties and brand rules reduce the franchisee's profit and independence","D":"The franchisee must publish accounts publicly"},"correctOption":"C","correctAnswer":"Royalties and brand rules reduce the franchisee's profit and independence","questionType":"MCQ","explanation":{"correct_reason":"Correct because 11% of sales leaves the outlet and the required fittings add cost, cutting the profit the franchisee keeps.","distractor_reasons":{"A":"Incorrect because using the brand's methods is a benefit of franchising, not the problem described.","B":"Incorrect because the franchisee keeps 89% of sales after the 11% royalty.","C":"Correct because 11% of sales leaves the outlet and the required fittings add cost, cutting the profit the franchisee keeps.","D":"Incorrect because publication of accounts applies to public limited companies, not franchisees as such."}}},{"id":"P1_U1_MCQ_1085","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1085","question":"Ashmoor Leisure is a council-run swimming pool in Finland that charges low entry fees, runs at a loss and is funded from local taxes so that all families can swim. Which objective is it following?","options":{"A":"Providing a public service rather than maximising profit","B":"Maximising profit from entry fees","C":"Growing market share against private gyms","D":"Survival by cutting services to local families"},"correctOption":"A","correctAnswer":"Providing a public service rather than maximising profit","questionType":"MCQ","explanation":{"correct_reason":"Correct because the pool accepts losses and low fees so that local families can use the facility, which is a service objective.","distractor_reasons":{"A":"Correct because the pool accepts losses and low fees so that local families can use the facility, which is a service objective.","B":"Incorrect because fees are deliberately low and the pool runs at a loss.","C":"Incorrect because the aim is affordable access, not competitive expansion.","D":"Incorrect because the pool continues to serve families with tax support rather than withdrawing the service."}}},{"id":"P1_U1_MCQ_1086","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1086","question":"Ashbury Salons is a new laundry in Egypt, set up with $30,000 of the owner's savings; demand looks steady but rival laundries may undercut its prices. Which quality is most important for success in this venture?","options":{"A":"Refusing to borrow money under any circumstances","B":"Copying exactly whatever rival laundries do","C":"Making every decision alone without advice","D":"Willingness to take a calculated risk"},"correctOption":"D","correctAnswer":"Willingness to take a calculated risk","questionType":"MCQ","explanation":{"correct_reason":"Correct because the entrepreneur commits $30,000 to a venture facing price competition, so accepting measured risk is essential.","distractor_reasons":{"A":"Incorrect because avoiding finance entirely may block necessary equipment purchases; the quality needed is judgement about risk, not blanket refusal.","B":"Incorrect because imitation without differentiation leaves the new firm with no advantage over established rivals.","C":"Incorrect because refusing advice is a weakness; entrepreneurs need information and expertise to judge risk.","D":"Correct because the entrepreneur commits $30,000 to a venture facing price competition, so accepting measured risk is essential."}}},{"id":"P1_U1_MCQ_1087","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1087","question":"Ashton Foods, a sugar estate in Fiji, replaced 120 cane cutters with two mechanical harvesters, cutting the field workforce to 20. Which effect on primary sector employment does this show?","options":{"A":"Primary output must fall when machines are used","B":"Mechanisation moves the workers into the public sector","C":"Capital-intensive methods reduce the number of workers needed in primary production","D":"The estate has become a tertiary business"},"correctOption":"C","correctAnswer":"Capital-intensive methods reduce the number of workers needed in primary production","questionType":"MCQ","explanation":{"correct_reason":"Correct because two machines replaced 120 cutters, leaving only 20 field workers, so capital substituted for labour.","distractor_reasons":{"A":"Incorrect because mechanisation usually raises output; the stem reports no fall in cane harvested.","B":"Incorrect because the redundant cutters are not described as taking government jobs.","C":"Correct because two machines replaced 120 cutters, leaving only 20 field workers, so capital substituted for labour.","D":"Incorrect because growing and harvesting cane remains primary activity."}}},{"id":"P1_U1_MCQ_1088","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1088","question":"Ashstead Printing, a printing firm in Kenya, funded a second press using profit it had kept in the business instead of distributing it to owners. What source of finance did it use?","options":{"A":"Retained profit","B":"A bank loan","C":"A share issue","D":"Trade credit from suppliers"},"correctOption":"A","correctAnswer":"Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Correct because profit left in the business after distributions is retained profit, an internal source of finance.","distractor_reasons":{"A":"Correct because profit left in the business after distributions is retained profit, an internal source of finance.","B":"Incorrect because no borrowing is described; the money came from the firm's own profit.","C":"Incorrect because no new shares were sold to raise the funds.","D":"Incorrect because trade credit means paying suppliers later, not using past profit."}}},{"id":"P1_U1_MCQ_1089","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1089","question":"Ashholm Cocoa is a cocoa cooperative in Ghana whose small grower members negotiate a price 14% above what each could obtain alone and share the cost of storage. Which benefit does the cooperative provide?","options":{"A":"A service objective set by government rather than profit maximisation","B":"Profit maximisation by charging higher prices in remote areas","C":"Growth by taking over private courier firms","D":"Survival by reducing the services it offers"},"correctOption":"A","correctAnswer":"A service objective set by government rather than profit maximisation","questionType":"MCQ","explanation":{"correct_reason":"Correct because the service must reach remote villages despite losses, showing a public service obligation instead of a profit goal.","distractor_reasons":{"A":"Correct because the service must reach remote villages despite losses, showing a public service obligation instead of a profit goal.","B":"Incorrect because the service makes a loss on remote delivery and is subsidised rather than charging what the market would bear.","C":"Incorrect because no acquisition is described.","D":"Incorrect because the service is expanding coverage to every village, not cutting back."}}},{"id":"P1_U1_MCQ_1090","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1090","question":"Ashmoor Hotels, a hotel in Greece, raises pay for its 150 cleaners by 5%, costing $180,000 a year. Which stakeholder group benefits most directly from this decision?","options":{"A":"The shareholders, who receive higher dividends","B":"The customers, who pay lower room rates","C":"The suppliers, who receive earlier payment","D":"The employees, who receive higher wages"},"correctOption":"D","correctAnswer":"The employees, who receive higher wages","questionType":"MCQ","explanation":{"correct_reason":"Correct because the 150 cleaners gain the 5% pay increase, worth $180,000 in total across the workforce.","distractor_reasons":{"A":"Incorrect because the extra $180,000 wage cost reduces profit available for dividends.","B":"Incorrect because no change to room prices is described.","C":"Incorrect because the decision concerns wages, not payment terms to suppliers.","D":"Correct because the 150 cleaners gain the 5% pay increase, worth $180,000 in total across the workforce."}}},{"id":"P1_U1_MCQ_1091","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1091","question":"Managers at Ashbury Construction, a Norwegian construction firm, note that even a high-income country such as Norway cannot provide every hospital, school and road its citizens request. Which statement best explains why scarcity exists there?","options":{"A":"Scarcity exists only in countries with low incomes","B":"Wants are unlimited while the resources available to meet them are limited","C":"Scarcity disappears once a government raises enough tax","D":"Scarcity means that some goods are too expensive to buy"},"correctOption":"B","correctAnswer":"Wants are unlimited while the resources available to meet them are limited","questionType":"MCQ","explanation":{"correct_reason":"Correct because scarcity is a universal condition: resources such as tax revenue and trained labour are finite while wants keep growing.","distractor_reasons":{"A":"Incorrect because Norway is high-income yet still faces limits, showing scarcity is not confined to poor countries.","B":"Correct because scarcity is a universal condition: resources such as tax revenue and trained labour are finite while wants keep growing.","C":"Incorrect because extra tax revenue still cannot cover every possible want, so choices remain necessary.","D":"Incorrect because high prices are a symptom of scarcity, not its definition, which concerns limited resources against unlimited wants."}}},{"id":"P1_U1_MCQ_1092","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1092","question":"Ashhurst Foods, a firm in Colombia, grows coffee on its own farms, roasts the beans in a factory and sells drinks in its city cafes. How should its activities be classified?","options":{"A":"It operates only in the secondary sector because it roasts beans","B":"It operates only in the tertiary sector because it sells drinks","C":"It operates only in the primary sector because it owns farms","D":"It operates in primary, secondary and tertiary activities"},"correctOption":"D","correctAnswer":"It operates in primary, secondary and tertiary activities","questionType":"MCQ","explanation":{"correct_reason":"Correct because growing coffee is primary, roasting is secondary processing, and running cafes is a tertiary service.","distractor_reasons":{"A":"Incorrect because farming and cafe service are also carried out, so roasting is only one of three stages.","B":"Incorrect because the firm also grows and processes the coffee itself.","C":"Incorrect because owning farms is only the first stage of its activities.","D":"Correct because growing coffee is primary, roasting is secondary processing, and running cafes is a tertiary service."}}},{"id":"P1_U1_MCQ_1093","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1093","question":"Ashstead Transport, a transport regulator, compared two bus companies: one carries 4 million passengers on short town routes, the other 1.2 million on long-distance routes with much higher fares. Why is passenger number a poor measure of relative size?","options":{"A":"Trip length and fare differences mean passenger counts do not reflect revenue","B":"Passenger numbers always understate the size of long-distance firms","C":"Revenue is irrelevant when comparing transport firms","D":"Both firms must carry the same number of passengers to be comparable"},"correctOption":"A","correctAnswer":"Trip length and fare differences mean passenger counts do not reflect revenue","questionType":"MCQ","explanation":{"correct_reason":"Correct because 4 million short cheap trips may earn less revenue than 1.2 million long expensive trips, so counts mislead.","distractor_reasons":{"A":"Correct because 4 million short cheap trips may earn less revenue than 1.2 million long expensive trips, so counts mislead.","B":"Incorrect because the point is that counts ignore fare and distance, not that they always understate one type of firm.","C":"Incorrect because revenue is a standard measure of size and directly affected by fares.","D":"Incorrect because firms can be compared on revenue or capital employed without equal passenger numbers."}}},{"id":"P1_U1_MCQ_1094","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1094","question":"Ashholm Accountancy is a partnership in Estonia whose two partners contribute $90,000 and $60,000 and share profit in proportion to their capital. Annual profit is $75,000. How much does the larger contributor receive?","options":{"A":"$30,000","B":"$37,500","C":"$60,000","D":"$45,000"},"correctOption":"D","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because the larger partner supplies $90,000 of the $150,000 total, or 60%, and 60% of $75,000 is $45,000.","distractor_reasons":{"A":"Incorrect because $30,000 is the smaller partner's 40% share.","B":"Incorrect because this splits the profit equally, ignoring the different capital contributions.","C":"Incorrect because $60,000 is the capital contributed, not the profit share.","D":"Correct because the larger partner supplies $90,000 of the $150,000 total, or 60%, and 60% of $75,000 is $45,000."}}},{"id":"P1_U1_MCQ_1095","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1095","question":"Ashmoor Couriers, a start-up delivery firm in Kenya, spent its first two years covering costs and is now opening new depots and aiming for 25% of city deliveries. How have its objectives changed?","options":{"A":"From profit maximisation to social objectives","B":"From survival to growth and market share","C":"From growth to survival","D":"From public service to profit maximisation"},"correctOption":"B","correctAnswer":"From survival to growth and market share","questionType":"MCQ","explanation":{"correct_reason":"Correct because the firm has moved from merely covering costs to expanding depots and targeting 25% of city deliveries.","distractor_reasons":{"A":"Incorrect because the firm is now pursuing expansion and market share, not community aims.","B":"Correct because the firm has moved from merely covering costs to expanding depots and targeting 25% of city deliveries.","C":"Incorrect because the direction is reversed: the firm is expanding after a period of covering costs.","D":"Incorrect because the firm is a private start-up, not a public service organisation."}}},{"id":"P1_U1_MCQ_1096","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1096","question":"Ashbury Research, a market research agency in Canada, compared four firms: Firm P sells at $8 with $3 of materials; Firm Q at $15 with $11; Firm R at $22 with $14; Firm S at $30 with $23. Which firm adds the most value per unit?","options":{"A":"Firm P, adding $5 per unit","B":"Firm Q, adding $4 per unit","C":"Firm S, adding $7 per unit","D":"Firm R, adding $8 per unit"},"correctOption":"D","correctAnswer":"Firm R, adding $8 per unit","questionType":"MCQ","explanation":{"correct_reason":"Correct because value added is price minus materials: P adds $5, Q adds $4, R adds $8 and S adds $7, so R adds the most.","distractor_reasons":{"A":"Incorrect because $5 is less than the $8 added by Firm R, so P does not add the most.","B":"Incorrect because $4 is the smallest margin of the four firms.","C":"Incorrect because $7 is high but still below the $8 added by Firm R.","D":"Correct because value added is price minus materials: P adds $5, Q adds $4, R adds $8 and S adds $7, so R adds the most."}}},{"id":"P1_U1_MCQ_1097","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1097","question":"Ashhurst Textiles, an employment agency, reports that in 2015, 42% of a country's workers were employed in agriculture; by 2025 the figure was 27%. By how many percentage points did the agricultural share fall?","options":{"A":"15%","B":"15 percentage points","C":"27%","D":"69%"},"correctOption":"B","correctAnswer":"15 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Correct because 42% minus 27% equals 15 percentage points, which measures the change between the two shares.","distractor_reasons":{"A":"Incorrect because the fall measured relative to the original 42% would be about 36%, not 15%; the change in shares is in points.","B":"Correct because 42% minus 27% equals 15 percentage points, which measures the change between the two shares.","C":"Incorrect because 27% is the share remaining in 2025, not the size of the fall.","D":"Incorrect because 69% is the two shares added together, which has no meaning here."}}},{"id":"P1_U1_MCQ_1098","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1098","question":"Ashstead Cycles, a bicycle maker in Portugal, sells 15,000 bikes a year in a market of 120,000 bikes. Its target is a 15% market share. How many extra bikes must it sell to reach the target?","options":{"A":"15,000 bikes","B":"18,000 bikes","C":"3,000 bikes","D":"5,000 bikes"},"correctOption":"C","correctAnswer":"3,000 bikes","questionType":"MCQ","explanation":{"correct_reason":"Correct because 15% of 120,000 is 18,000 bikes, and 18,000 minus the current 15,000 leaves 3,000 extra.","distractor_reasons":{"A":"Incorrect because 15,000 is the current volume, not the number of additional bikes needed.","B":"Incorrect because 18,000 is the total sales needed, which includes the 15,000 already sold.","C":"Correct because 15% of 120,000 is 18,000 bikes, and 18,000 minus the current 15,000 leaves 3,000 extra.","D":"Incorrect because this would give 20,000 bikes, a market share of about 16.7%."}}},{"id":"P1_U1_MCQ_1099","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1099","question":"Ashholm Law, a four-partner law firm in Austria, makes profit after tax of $96,000 and shares it equally. One partner also received a salary of $40,000 during the year, already deducted as a cost. How much profit does each partner receive?","options":{"A":"$40,000, the salary already paid","B":"$96,000, the whole profit after tax","C":"$9,600","D":"$24,000"},"correctOption":"D","correctAnswer":"$24,000","questionType":"MCQ","explanation":{"correct_reason":"Correct because $96,000 divided equally among four partners gives $24,000 each, and the salary was already treated as a cost.","distractor_reasons":{"A":"Incorrect because the salary is a separate payment already deducted, not the share of remaining profit.","B":"Incorrect because the profit is shared among four partners, not paid to one.","C":"Incorrect because this divides the profit by ten rather than by four partners.","D":"Correct because $96,000 divided equally among four partners gives $24,000 each, and the salary was already treated as a cost."}}},{"id":"P1_U1_MCQ_1100","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1100","question":"Ashmoor Paper, a paper mill in Finland, discharges waste into a lake. A local fishing association and an environmental group campaign for tighter limits, while the mill says compliance would cost $3 million. Which stakeholder conflict does this show?","options":{"A":"Customers against suppliers over product quality","B":"The local community's environmental interest against the owners' profit interest","C":"Employees against managers over pay","D":"Government against shareholders over dividend policy"},"correctOption":"B","correctAnswer":"The local community's environmental interest against the owners' profit interest","questionType":"MCQ","explanation":{"correct_reason":"Correct because residents and campaigners want a clean lake while the mill's owners resist $3 million of compliance costs.","distractor_reasons":{"A":"Incorrect because the dispute concerns lake pollution and compliance costs, not product quality between buyers and sellers.","B":"Correct because residents and campaigners want a clean lake while the mill's owners resist $3 million of compliance costs.","C":"Incorrect because no wage dispute is described.","D":"Incorrect because the campaigners are local groups, and the issue is pollution rather than dividends."}}},{"id":"P1_U1_MCQ_1101","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1101","question":"Harbottle Farm in Cumbria has saved $18,000. The owner can spend it either on a new shearing machine or on new fencing for two extra grazing fields. She decides to buy the shearing machine. What is the opportunity cost of her decision?","options":{"A":"The fencing for the two extra fields that was not bought","B":"The $18,000 of savings spent on the machine","C":"The wool produced by the farm's existing 400 sheep","D":"The extra grazing land that the fencing would have created"},"correctOption":"A","correctAnswer":"The fencing for the two extra fields that was not bought","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best alternative given up, so by buying the $18,000 shearing machine Harbottle Farm gives up the fencing for two extra fields.","distractor_reasons":{"A":"Opportunity cost is the value of the next best alternative given up, so by buying the $18,000 shearing machine Harbottle Farm gives up the fencing for two extra fields.","B":"The $18,000 is simply the money spent on the chosen option, not the benefit of the alternative that was sacrificed.","C":"The wool from the existing 400 sheep would still be produced either way, so it is not the alternative forgone.","D":"The extra grazing land is a result of the rejected fencing, but the opportunity cost is the fencing itself that was not bought."}}},{"id":"P1_U1_MCQ_1102","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1102","question":"Glenmoran Slate employs 22 workers at a quarry in north Wales, splitting rock by hand and selling the blocks to building firms. Which sector of the economy does Glenmoran Slate operate in?","options":{"A":"Secondary","B":"Tertiary","C":"Public","D":"Primary"},"correctOption":"D","correctAnswer":"Primary","questionType":"MCQ","explanation":{"correct_reason":"Quarrying extracts slate directly from the ground, which is a primary sector activity because it takes a natural resource.","distractor_reasons":{"A":"The secondary sector processes raw materials into manufactured goods, whereas Glenmoran only splits and sells the rock.","B":"The tertiary sector provides services, but Glenmoran sells quarried stone rather than a service.","C":"The public sector refers to government ownership, and nothing in the stem says the quarry is state-owned.","D":"Quarrying extracts slate directly from the ground, which is a primary sector activity because it takes a natural resource."}}},{"id":"P1_U1_MCQ_1103","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1103","question":"Ridgeway Alpaca Farm sells 620 fleeces a year at $85 each. Its total costs, including feed, shearing and transport, are $38,000 a year. What is the farm's annual profit?","options":{"A":"$52,700","B":"$38,000","C":"$14,700","D":"$24,700"},"correctOption":"C","correctAnswer":"$14,700","questionType":"MCQ","explanation":{"correct_reason":"Revenue is 620 multiplied by $85, giving $52,700, and profit is $52,700 minus the $38,000 of costs, which equals $14,700.","distractor_reasons":{"A":"$52,700 is total sales revenue before the $38,000 of costs has been deducted.","B":"$38,000 is the total cost of running the farm, not the profit earned from selling the fleeces.","C":"Revenue is 620 multiplied by $85, giving $52,700, and profit is $52,700 minus the $38,000 of costs, which equals $14,700.","D":"$24,700 does not follow from these figures and would require costs of only about $28,000."}}},{"id":"P1_U1_MCQ_1104","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1104","question":"Ewan Tulloch runs Tulloch Cycle Repairs as a sole trader. He owes a parts supplier $23,000, but the business bank account holds only $6,000. What is Ewan's legal position?","options":{"A":"His liability is limited to the $6,000 in the business account","B":"He is personally liable for the remaining $17,000 of debt","C":"The supplier must accept $6,000 and write off the rest","D":"Only the business's customers are liable for the debt"},"correctOption":"B","correctAnswer":"He is personally liable for the remaining $17,000 of debt","questionType":"MCQ","explanation":{"correct_reason":"A sole trader has unlimited liability, so Ewan must pay the $17,000 balance from personal funds once the business's $6,000 has been used.","distractor_reasons":{"A":"Limited liability would cap his loss at $6,000, but a sole trader is personally responsible for the whole debt.","B":"A sole trader has unlimited liability, so Ewan must pay the $17,000 balance from personal funds once the business's $6,000 has been used.","C":"The supplier does not have to write off the debt, because the owner remains liable for the unpaid balance.","D":"Customers are not liable for a business's debts; the sole trader who owns the business is."}}},{"id":"P1_U1_MCQ_1105","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1105","question":"Pilmoor Mobile has 12% of the national mobile market, and its board sets a target of 18% within two years, even if this means charging lower prices. Which business objective is the board pursuing?","options":{"A":"Profit maximisation","B":"Increasing market share","C":"Survival","D":"Providing a public service"},"correctOption":"B","correctAnswer":"Increasing market share","questionType":"MCQ","explanation":{"correct_reason":"A target of 18% of the national market, up from 12%, is a market share objective even if lower prices reduce profit.","distractor_reasons":{"A":"Profit maximisation would focus on the gap between revenue and costs, not on the percentage of the market held.","B":"A target of 18% of the national market, up from 12%, is a market share objective even if lower prices reduce profit.","C":"Survival means covering costs to stay in business, which is not the aim stated by the board.","D":"A public service objective would concern providing a service to the community, but Pilmoor is pursuing market position."}}},{"id":"P1_U1_MCQ_1106","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1106","question":"Wrenfold Pottery buys 1,200 kilograms of clay at $4 per kilogram and spends $2,400 on glazes and fuel. It sells all the mugs made from these materials for $11,600. What is the added value created by Wrenfold Pottery?","options":{"A":"$4,400","B":"$6,800","C":"$9,200","D":"$11,600"},"correctOption":"A","correctAnswer":"$4,400","questionType":"MCQ","explanation":{"correct_reason":"Added value is selling price minus bought-in costs, so $11,600 of revenue less $7,200 spent on clay, glazes and fuel gives $4,400.","distractor_reasons":{"A":"Added value is selling price minus bought-in costs, so $11,600 of revenue less $7,200 spent on clay, glazes and fuel gives $4,400.","B":"$6,800 wrongly subtracts only part of the clay cost and ignores the $2,400 spent on glazes and fuel.","C":"$9,200 subtracts only the $2,400 glaze and fuel cost from revenue and leaves out the $4,800 of clay.","D":"$11,600 is total sales revenue rather than added value, because the $7,200 of bought-in costs has not been deducted."}}},{"id":"P1_U1_MCQ_1107","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1107","question":"Ravensworth Steelworks melts scrap metal in an electric furnace and rolls it into steel beams for construction companies. Into which sector of economic activity should Ravensworth Steelworks be placed?","options":{"A":"Primary","B":"Tertiary","C":"Public","D":"Secondary"},"correctOption":"D","correctAnswer":"Secondary","questionType":"MCQ","explanation":{"correct_reason":"Melting scrap and rolling steel beams is manufacturing, which places Ravensworth Steelworks in the secondary sector.","distractor_reasons":{"A":"The primary sector extracts raw materials, but this firm processes metal that has already been produced.","B":"Ravensworth makes a physical product, so it is not providing a service to consumers.","C":"Sector of economic activity describes the type of production, not whether the owner is the government.","D":"Melting scrap and rolling steel beams is manufacturing, which places Ravensworth Steelworks in the secondary sector."}}},{"id":"P1_U1_MCQ_1108","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1108","question":"Nessa Okafor leaves her salaried job to open Fenlow Physiotherapy. She invests $42,000 of savings, leases a clinic and accepts that the business may fail within two years. Which entrepreneurial characteristic is she showing?","options":{"A":"A desire for a guaranteed income","B":"Reluctance to make business decisions","C":"Willingness to take a financial risk","D":"A preference for working for others"},"correctOption":"C","correctAnswer":"Willingness to take a financial risk","questionType":"MCQ","explanation":{"correct_reason":"She gives up a salary, invests $42,000 of her own savings and accepts possible failure, which shows willingness to take risk.","distractor_reasons":{"A":"An entrepreneur gives up guaranteed pay, and Nessa has left a salaried job to start the clinic.","B":"Opening a clinic requires many decisions, so reluctance to decide is not shown.","C":"She gives up a salary, invests $42,000 of her own savings and accepts possible failure, which shows willingness to take risk.","D":"She left employment to work for herself, which is the opposite of preferring to work for others."}}},{"id":"P1_U1_MCQ_1109","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1109","question":"The two owners of Hollinrake Farm Partnership signed a deed agreeing how profits and losses are shared and how a partner may leave the business. Why is such a deed useful?","options":{"A":"It gives both partners limited liability for business debts","B":"It allows shares in the partnership to be sold on a stock exchange","C":"It reduces disputes by setting out each partner's rights and obligations","D":"It removes the need for the partnership to keep accounts"},"correctOption":"C","correctAnswer":"It reduces disputes by setting out each partner's rights and obligations","questionType":"MCQ","explanation":{"correct_reason":"A written deed makes profit shares, losses and exit terms clear in advance, which reduces arguments between the partners.","distractor_reasons":{"A":"A deed cannot create limited liability, because ordinary partners remain fully liable for the firm's debts.","B":"Partnerships cannot quote shares on a stock exchange, which is a feature of public limited companies.","C":"A written deed makes profit shares, losses and exit terms clear in advance, which reduces arguments between the partners.","D":"A deed does not remove accounting duties; partners still need records to calculate and share profit."}}},{"id":"P1_U1_MCQ_1110","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1110","question":"Barrowhill Bakery is owned by a charity. It trains young people who have left school without qualifications and uses any surplus to fund free breakfast clubs. Which objective best describes its main aim?","options":{"A":"Maximising dividends for shareholders","B":"Meeting a social objective","C":"Becoming a public limited company","D":"Reducing its market share"},"correctOption":"B","correctAnswer":"Meeting a social objective","questionType":"MCQ","explanation":{"correct_reason":"Training disadvantaged young people and funding breakfast clubs are social aims, so the bakery's main objective is social rather than profit.","distractor_reasons":{"A":"A charity-owned bakery does not aim to maximise dividends for shareholders.","B":"Training disadvantaged young people and funding breakfast clubs are social aims, so the bakery's main objective is social rather than profit.","C":"Becoming a public limited company is a legal structure, not the social objective described.","D":"Reducing market share would not help it to train more young people or fund more breakfast clubs."}}},{"id":"P1_U1_MCQ_1111","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1111","question":"Drumlin Dairy in County Down has taken delivery of a 95,000 euro pasteurising tank, employs a plant manager on a salary of 46,000 euros a year and rents 30 hectares of grazing land. Which factor of production does the pasteurising tank represent?","options":{"A":"Capital","B":"Land","C":"Labour","D":"Enterprise"},"correctOption":"A","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"A pasteurising tank is man-made equipment used to produce goods, so it is capital, while land is the natural resource and labour is the workforce.","distractor_reasons":{"A":"A pasteurising tank is man-made equipment used to produce goods, so it is capital, while land is the natural resource and labour is the workforce.","B":"Land refers to natural resources such as the 30 hectares of grazing, not to a manufactured tank.","C":"Labour is the human effort supplied by the plant manager and other workers, not the tank.","D":"Enterprise is the risk-taking and decision-making of the owner, not a piece of machinery."}}},{"id":"P1_U1_MCQ_1112","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1112","question":"Puffin Post Couriers collects parcels from online retailers in Aberdeen and delivers them to households across Scotland, employing 60 drivers. Which sector does this business belong to?","options":{"A":"Secondary","B":"Primary","C":"Primary and secondary equally","D":"Tertiary"},"correctOption":"D","correctAnswer":"Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Collecting and delivering parcels is a transport service, so Puffin Post belongs to the tertiary sector.","distractor_reasons":{"A":"The firm does not manufacture parcels; it moves them, which is a service activity.","B":"The primary sector extracts natural resources, which is unrelated to parcel delivery.","C":"Puffin Post only provides a delivery service, so it is not also engaged in extraction or manufacturing.","D":"Collecting and delivering parcels is a transport service, so Puffin Post belongs to the tertiary sector."}}},{"id":"P1_U1_MCQ_1113","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1113","question":"Tamar Valley Cider sells 48,000 litres a year. Total cider sales in its region are 400,000 litres a year. What is Tamar Valley Cider's market share?","options":{"A":"8.3%","B":"48%","C":"1.2%","D":"12%"},"correctOption":"D","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Market share is 48,000 divided by 400,000, multiplied by 100, which gives 12% of regional cider sales.","distractor_reasons":{"A":"8.3% comes from dividing the total market by the firm's sales, which reverses the calculation.","B":"48% treats the 48,000 litres as a percentage instead of dividing by the 400,000-litre market.","C":"1.2% misplaces the decimal point, because the correct division gives 0.12, or 12%.","D":"Market share is 48,000 divided by 400,000, multiplied by 100, which gives 12% of regional cider sales."}}},{"id":"P1_U1_MCQ_1114","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1114","question":"Redesdale Textiles Ltd has 150,000 ordinary shares. It makes a profit after tax of $96,000 and keeps $36,000 in the business for new machinery. What dividend is paid per share?","options":{"A":"$0.64","B":"$0.24","C":"$0.40","D":"$4.00"},"correctOption":"C","correctAnswer":"$0.40","questionType":"MCQ","explanation":{"correct_reason":"Dividends total $96,000 minus $36,000, giving $60,000, and $60,000 divided by 150,000 shares equals $0.40 per share.","distractor_reasons":{"A":"$0.64 divides the whole $96,000 profit by 150,000 shares and ignores the $36,000 that is retained.","B":"$0.24 divides the $36,000 of retained profit by the number of shares, which is the wrong figure.","C":"Dividends total $96,000 minus $36,000, giving $60,000, and $60,000 divided by 150,000 shares equals $0.40 per share.","D":"$4.00 misplaces the decimal point, because the correct dividend is 40 cents per share."}}},{"id":"P1_U1_MCQ_1115","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1115","question":"Hobson Shipyard announces that it will replace 40 welders with robots next year. Which stakeholder group is most directly and immediately affected by this decision?","options":{"A":"The government's tax office","B":"The welders employed at the shipyard","C":"The shipyard's shareholders","D":"Local suppliers of welding gas"},"correctOption":"B","correctAnswer":"The welders employed at the shipyard","questionType":"MCQ","explanation":{"correct_reason":"The 40 welders whose jobs are replaced by robots are the group most directly and immediately affected by the decision.","distractor_reasons":{"A":"The tax office is affected only indirectly, through any change in the tax the shipyard pays.","B":"The 40 welders whose jobs are replaced by robots are the group most directly and immediately affected by the decision.","C":"Shareholders may be affected through profit, but not as directly as the workers losing their jobs.","D":"Welding gas suppliers may lose some sales, but the job losses hit the welders first."}}},{"id":"P1_U1_MCQ_1116","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1116","question":"Mullion Cove Holidays offers four packages to visitors in Cornwall: a shuttle to a hospital appointment, a bottle of drinking water on arrival, a guided tour of a castle and a basic room for the night. Which package best satisfies a want rather than a need?","options":{"A":"The guided tour of a castle","B":"The shuttle to a hospital appointment","C":"The bottle of drinking water on arrival","D":"The basic room for the night"},"correctOption":"A","correctAnswer":"The guided tour of a castle","questionType":"MCQ","explanation":{"correct_reason":"A guided castle tour is a want because it is enjoyable but not needed for survival, unlike clean water, shelter or medical travel.","distractor_reasons":{"A":"A guided castle tour is a want because it is enjoyable but not needed for survival, unlike clean water, shelter or medical travel.","B":"Travel to a hospital appointment meets a basic health need rather than a discretionary want.","C":"Drinking water is a basic need for survival, so it cannot be classified as a want.","D":"A basic room for the night provides shelter, which is a need rather than a want."}}},{"id":"P1_U1_MCQ_1117","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1117","question":"In Corran Bay in 2015, 24,000 of the region's 60,000 workers had manufacturing jobs. By 2025 only 16,200 of 54,000 workers did. What happened to manufacturing's share of total employment?","options":{"A":"It fell by 10 percentage points","B":"It fell by 7,800 workers","C":"It rose by 10 percentage points","D":"It fell by 25%"},"correctOption":"A","correctAnswer":"It fell by 10 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The share was 24,000 divided by 60,000, giving 40% in 2015, and 16,200 divided by 54,000, giving 30% in 2025, a fall of 10 percentage points.","distractor_reasons":{"A":"The share was 24,000 divided by 60,000, giving 40% in 2015, and 16,200 divided by 54,000, giving 30% in 2025, a fall of 10 percentage points.","B":"7,800 is the fall in the number of manufacturing workers, not the change in their share of the workforce.","C":"The share fell from 40% to 30%, so it did not rise by 10 percentage points.","D":"The number of manufacturing jobs fell by 32.5%, not 25%, and the question asks about the share."}}},{"id":"P1_U1_MCQ_1118","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1118","question":"Saltway Organics increased its revenue from $185,000 in 2024 to $222,000 in 2025, yet its profit stayed at $18,000. What does this show about business growth?","options":{"A":"Profit always rises when revenue rises","B":"The business must have reduced its selling prices","C":"Growth is impossible without a merger","D":"Revenue can grow without profit rising if costs increase by a similar amount"},"correctOption":"D","correctAnswer":"Revenue can grow without profit rising if costs increase by a similar amount","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $37,000 while profit stayed at $18,000, so costs must have risen by almost the same amount as the extra sales.","distractor_reasons":{"A":"Profit stayed at $18,000 despite higher revenue, so the two do not always move together.","B":"The stem does not say prices fell, and the rise in revenue could come from selling more units.","C":"Saltway grew its revenue without any mention of a merger, which contradicts this claim.","D":"Revenue rose by $37,000 while profit stayed at $18,000, so costs must have risen by almost the same amount as the extra sales."}}},{"id":"P1_U1_MCQ_1119","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1119","question":"Gledhill Foods plc issues 500,000 new ordinary shares at $2.40 each to pay for a new factory. How much capital does the share issue raise?","options":{"A":"$120,000","B":"$2,400,000","C":"$1,200,000","D":"$500,000"},"correctOption":"C","correctAnswer":"$1,200,000","questionType":"MCQ","explanation":{"correct_reason":"500,000 shares at $2.40 each raise 500,000 multiplied by $2.40, which equals $1,200,000.","distractor_reasons":{"A":"$120,000 misplaces a decimal point and would need a share price of only 24 cents.","B":"$2,400,000 doubles the capital, perhaps by counting the $2.40 share price twice.","C":"500,000 shares at $2.40 each raise 500,000 multiplied by $2.40, which equals $1,200,000.","D":"$500,000 is the number of shares issued, not the money raised from selling them."}}},{"id":"P1_U1_MCQ_1120","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1120","question":"Wainfleet Motors makes a $4 million profit. Shareholders want a larger dividend while the union wants a 6% wage rise. Why is this a stakeholder conflict?","options":{"A":"Both groups want the company to close down","B":"Paying more to shareholders leaves less profit available to fund wage rises","C":"Shareholders are employees of the company","D":"A wage rise would increase profit automatically"},"correctOption":"B","correctAnswer":"Paying more to shareholders leaves less profit available to fund wage rises","questionType":"MCQ","explanation":{"correct_reason":"Profit can either be paid out as dividends or used to raise wages, so a bigger payout to one group leaves less for the other.","distractor_reasons":{"A":"Neither group wants the company to close; they disagree over how the $4 million profit should be shared.","B":"Profit can either be paid out as dividends or used to raise wages, so a bigger payout to one group leaves less for the other.","C":"Shareholders own the company and are not employees, so this statement is false.","D":"A 6% wage rise raises costs and would reduce profit, not increase it automatically."}}},{"id":"P1_U1_MCQ_1121","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1121","question":"Bramblewick Preserves buys 800 kilograms of damsons at $3.50 per kilogram and spends a further $1,900 on sugar, jars and fuel. The jam made from these inputs sells for $12,400. What is the added value as a percentage of sales revenue?","options":{"A":"37.9%","B":"62.1%","C":"26.9%","D":"58.1%"},"correctOption":"B","correctAnswer":"62.1%","questionType":"MCQ","explanation":{"correct_reason":"Bought-in costs total $2,800 for damsons plus $1,900 for jars and fuel, so added value is $7,700 and $7,700 divided by $12,400 is 62.1%.","distractor_reasons":{"A":"37.9% shows bought-in costs as a share of revenue, which is the opposite of the added value share.","B":"Bought-in costs total $2,800 for damsons plus $1,900 for jars and fuel, so added value is $7,700 and $7,700 divided by $12,400 is 62.1%.","C":"26.9% does not come from these figures; it confuses the $3.50 price per kilogram with a percentage calculation.","D":"58.1% would need about $7,200 of added value, but the added value here is $7,700."}}},{"id":"P1_U1_MCQ_1122","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1122","question":"The economy of Norvik Fjord produced total output worth $480 million last year. Fishing, forestry and mining together contributed $72 million of that total. What percentage of output came from the primary sector?","options":{"A":"15%","B":"6.7%","C":"72%","D":"12.5%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The primary sector contributed $72 million of the $480 million total, and 72 divided by 480 multiplied by 100 gives 15%.","distractor_reasons":{"A":"The primary sector contributed $72 million of the $480 million total, and 72 divided by 480 multiplied by 100 gives 15%.","B":"6.7% comes from dividing $72 million by a much larger figure than the $480 million of total output.","C":"72% treats the $72 million contribution as a percentage instead of dividing it by total output.","D":"12.5% would need $60 million of primary output, but the stem gives $72 million."}}},{"id":"P1_U1_MCQ_1123","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1123","question":"Redmarley Brewery employs 240 staff in a single plant, while a rival brewer employs 75 staff across four small sites. The owners want to compare the size of the two businesses. Which measure would give the most useful comparison?","options":{"A":"Number of separate sites","B":"Age of each business","C":"Number of products sold","D":"Number of employees"},"correctOption":"D","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Number of employees is a common measure of business size that can be compared across firms in the same industry.","distractor_reasons":{"A":"The number of sites does not show scale reliably, since one large plant may exceed four small sites.","B":"Age shows how long a firm has traded, not how large its operations are.","C":"The number of products sold does not measure the scale of the business's operations.","D":"Number of employees is a common measure of business size that can be compared across firms in the same industry."}}},{"id":"P1_U1_MCQ_1124","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1124","question":"A franchisee pays Cobblers Yard Coffee an initial fee of $45,000 and a royalty of 6% of monthly sales. In the first month the outlet's sales are $38,000. How much does the franchisee pay the franchisor in total that month?","options":{"A":"$2,280","B":"$45,000","C":"$47,280","D":"$68,000"},"correctOption":"C","correctAnswer":"$47,280","questionType":"MCQ","explanation":{"correct_reason":"The royalty is 6% of $38,000, which is $2,280, and adding the $45,000 initial fee gives $47,280 paid in the first month.","distractor_reasons":{"A":"$2,280 is only the monthly royalty and leaves out the $45,000 initial franchise fee.","B":"$45,000 is only the initial fee and ignores the 6% royalty on $38,000 of sales.","C":"The royalty is 6% of $38,000, which is $2,280, and adding the $45,000 initial fee gives $47,280 paid in the first month.","D":"$68,000 does not follow from the figures and appears to apply 6% to the fee rather than to sales."}}},{"id":"P1_U1_MCQ_1125","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1125","question":"Cresswell Chemicals wants to expand its plant, but a local campaign group says extra lorry traffic will worsen air quality near a school. Which stakeholder is the campaign group representing?","options":{"A":"The company's shareholders","B":"The company's suppliers","C":"The local community","D":"The government"},"correctOption":"C","correctAnswer":"The local community","questionType":"MCQ","explanation":{"correct_reason":"The campaign group speaks for residents near the school who would suffer from extra lorry traffic and poorer air quality.","distractor_reasons":{"A":"Shareholders are concerned with profit and dividends, not with local traffic and air quality.","B":"Suppliers deliver materials to the plant and are not represented by a residents' campaign.","C":"The campaign group speaks for residents near the school who would suffer from extra lorry traffic and poorer air quality.","D":"The group is a local campaign, not a government body enforcing environmental regulations."}}},{"id":"P1_U1_MCQ_1126","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1126","question":"Tarnside Furniture employs 12 workers who together make 240 chairs a week. After the owner divides the work into six specialist stages, the same 12 workers make 336 chairs a week. What is the increase in output per worker per week?","options":{"A":"28 chairs","B":"8 chairs","C":"96 chairs","D":"12 chairs"},"correctOption":"B","correctAnswer":"8 chairs","questionType":"MCQ","explanation":{"correct_reason":"Output per worker was 240 divided by 12, giving 20 chairs, then 336 divided by 12, giving 28 chairs, so the increase is 8 chairs.","distractor_reasons":{"A":"28 chairs is the new output per worker after specialisation, not the increase that the question asks for.","B":"Output per worker was 240 divided by 12, giving 20 chairs, then 336 divided by 12, giving 28 chairs, so the increase is 8 chairs.","C":"96 chairs is the rise in total weekly output, from 240 to 336, not the rise per worker.","D":"12 is the number of workers employed, not the change in output per worker."}}},{"id":"P1_U1_MCQ_1127","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1127","question":"Kestrelmoor Fish Hatchery breeds trout for sale to restaurants, while three other Kerry firms cook trout, smoke and pack trout, and sell fishing equipment. Which of these four businesses operates in the primary sector?","options":{"A":"A hatchery that breeds trout for sale to restaurants","B":"A restaurant that cooks and serves trout to diners","C":"A factory that smokes and packs trout for shops","D":"A shop that sells fishing equipment to anglers"},"correctOption":"A","correctAnswer":"A hatchery that breeds trout for sale to restaurants","questionType":"MCQ","explanation":{"correct_reason":"Breeding trout is rearing a natural resource, which is a primary sector activity.","distractor_reasons":{"A":"Breeding trout is rearing a natural resource, which is a primary sector activity.","B":"Cooking and serving trout is a tertiary service provided to diners.","C":"Smoking and packing trout processes the fish, which is secondary sector manufacturing.","D":"Selling fishing equipment is a retail service, so it belongs to the tertiary sector."}}},{"id":"P1_U1_MCQ_1128","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1128","question":"Cobham Analytics opens a second office in Leeds, recruits 14 extra analysts and wins new clients through advertising, without buying another company. Which type of growth is this?","options":{"A":"A merger","B":"A takeover","C":"Vertical integration","D":"Internal (organic) growth"},"correctOption":"D","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Opening a new office and winning clients through advertising is internal growth, because no other business is acquired.","distractor_reasons":{"A":"A merger joins two businesses together, but Cobham has expanded its own operations instead.","B":"No shares or ownership of another firm have been bought, so this is not a takeover.","C":"Vertical integration involves buying a supplier or customer, which Cobham has not done.","D":"Opening a new office and winning clients through advertising is internal growth, because no other business is acquired."}}},{"id":"P1_U1_MCQ_1129","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1129","question":"Amberley Books Ltd wants to open four more shops and needs $600,000. It can sell shares to family and friends but cannot advertise shares to the general public. Which feature of a private limited company explains this?","options":{"A":"Its owners have unlimited liability for its debts","B":"It must have at least two hundred shareholders","C":"It is owned by the government","D":"Its shares cannot be offered for sale to the general public"},"correctOption":"D","correctAnswer":"Its shares cannot be offered for sale to the general public","questionType":"MCQ","explanation":{"correct_reason":"A private limited company may sell shares privately, but it cannot offer them to the public, which limits how much capital it can raise.","distractor_reasons":{"A":"Shareholders in a limited company have limited liability, so this does not explain the restriction.","B":"There is no rule requiring two hundred shareholders; that confuses a private company with a public one.","C":"The company is owned by its shareholders, and the stem gives no sign of government ownership.","D":"A private limited company may sell shares privately, but it cannot offer them to the public, which limits how much capital it can raise."}}},{"id":"P1_U1_MCQ_1130","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1130","question":"Dunscar Distribution is a road haulage firm. Last year it earned revenue of $840,000 and paid $690,000 in wages, fuel, rent and other costs. What was its profit?","options":{"A":"$690,000","B":"$840,000","C":"$150,000","D":"$1,530,000"},"correctOption":"C","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Profit is revenue minus costs, so $840,000 minus $690,000 equals $150,000.","distractor_reasons":{"A":"$690,000 is total costs, not the profit remaining after those costs are paid.","B":"$840,000 is revenue before the $690,000 of costs has been deducted.","C":"Profit is revenue minus costs, so $840,000 minus $690,000 equals $150,000.","D":"$1,530,000 adds revenue and costs together instead of subtracting costs from revenue."}}},{"id":"P1_U1_MCQ_1131","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1131","question":"Coldharbour Coffee Roasters has a monthly budget of $26,000 and has been offered contracts by nine green-bean suppliers costing $8,000 each. The owner can afford to sign only three contracts. Which economic idea does this situation illustrate?","options":{"A":"Opportunity cost","B":"Scarcity","C":"Specialisation","D":"Division of labour"},"correctOption":"B","correctAnswer":"Scarcity","questionType":"MCQ","explanation":{"correct_reason":"Scarcity exists because $26,000 of funds cannot cover all nine contracts worth $72,000, forcing the owner to choose among limited resources.","distractor_reasons":{"A":"Opportunity cost would describe the specific contracts given up by the choice, not the general shortage of funds against wants.","B":"Scarcity exists because $26,000 of funds cannot cover all nine contracts worth $72,000, forcing the owner to choose among limited resources.","C":"Specialisation means concentrating on one product or task, which is not what a limited purchasing budget shows.","D":"Division of labour means splitting production into separate tasks, which is unrelated to a limited purchasing budget."}}},{"id":"P1_U1_MCQ_1132","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1132","question":"Menabilly Cocoa Estate harvests and dries cocoa pods, then sells the beans to a chocolate factory in the same country. Which statement best describes this link between sectors?","options":{"A":"The secondary sector depends on primary sector output as its raw material","B":"The primary sector depends on the tertiary sector for raw materials","C":"Both businesses belong to the tertiary sector","D":"The factory belongs to the primary sector because it uses cocoa"},"correctOption":"A","correctAnswer":"The secondary sector depends on primary sector output as its raw material","questionType":"MCQ","explanation":{"correct_reason":"The estate extracts and dries cocoa, and the factory processes those beans, so secondary manufacturing depends on primary output.","distractor_reasons":{"A":"The estate extracts and dries cocoa, and the factory processes those beans, so secondary manufacturing depends on primary output.","B":"Primary businesses supply raw materials to manufacturers; they do not obtain raw materials from services.","C":"Growing and processing cocoa are primary and secondary activities, not services.","D":"Processing beans into chocolate is manufacturing, so the factory is secondary even though its input is primary."}}},{"id":"P1_U1_MCQ_1133","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1133","question":"Hartsop Joinery buys 100% of the shares of a rival window manufacturer, which continues trading under its own name as part of the larger group. Which type of growth has taken place?","options":{"A":"A takeover, which is external growth","B":"Organic growth","C":"A partnership","D":"A franchise"},"correctOption":"A","correctAnswer":"A takeover, which is external growth","questionType":"MCQ","explanation":{"correct_reason":"Buying 100% of a rival's shares is a takeover, which is external growth because control of another business is acquired.","distractor_reasons":{"A":"Buying 100% of a rival's shares is a takeover, which is external growth because control of another business is acquired.","B":"Organic growth would mean expanding its own output, not purchasing a rival manufacturer.","C":"A partnership is a legal structure with shared ownership by partners, not the purchase of a company.","D":"A franchise involves a franchisee paying for a brand and system, not buying all of a rival's shares."}}},{"id":"P1_U1_MCQ_1134","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1134","question":"Tarnhow Toys Ltd goes into liquidation owing $140,000 to creditors. Its shareholders have already paid $80,000 for their shares and hold no other business assets. How much of the debt must the shareholders pay from personal funds?","options":{"A":"$60,000, which is the unpaid part of the debt","B":"The full $140,000 owed to creditors","C":"$80,000, which they originally invested","D":"Nothing, because liability is limited to the amount paid for shares"},"correctOption":"D","correctAnswer":"Nothing, because liability is limited to the amount paid for shares","questionType":"MCQ","explanation":{"correct_reason":"Limited liability means shareholders lose only the $80,000 already paid for shares and are not liable for the remaining debt.","distractor_reasons":{"A":"$60,000 is the shortfall in the company's debts, which shareholders do not have to pay personally.","B":"Unlimited liability would make owners pay the whole $140,000, but a limited company protects them.","C":"The $80,000 has already been paid for shares, and shareholders are not required to pay it a second time.","D":"Limited liability means shareholders lose only the $80,000 already paid for shares and are not liable for the remaining debt."}}},{"id":"P1_U1_MCQ_1135","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1135","question":"A care home group is deciding whether to cut staff training in order to raise profit. Which stakeholder group would be most concerned about the effect on the quality of working life and job security?","options":{"A":"Customers' banks","B":"The tax authority","C":"Employees","D":"Shareholders seeking dividends"},"correctOption":"C","correctAnswer":"Employees","questionType":"MCQ","explanation":{"correct_reason":"Cutting training affects staff directly through less support, weaker skills and possibly less job security, so employees are most concerned.","distractor_reasons":{"A":"Customers' banks have no direct interest in the care home's training budget.","B":"The tax authority is concerned with tax paid, not with staff training and working conditions.","C":"Cutting training affects staff directly through less support, weaker skills and possibly less job security, so employees are most concerned.","D":"Shareholders mainly gain from higher profit, so they are unlikely to object to the cut."}}},{"id":"P1_U1_MCQ_1136","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1136","question":"The head gardener at Hollins Park has 40 paid hours each week and a long list of jobs. She decides to spend 12 of those hours restoring the rose garden, so the hedge cutting and path repairs are delayed. What is the opportunity cost of her decision?","options":{"A":"The 12 hours spent working on the rose garden","B":"The hedge cutting and path repairs that were delayed","C":"The wages paid for 40 hours of gardening work","D":"The plants bought for the rose garden"},"correctOption":"B","correctAnswer":"The hedge cutting and path repairs that were delayed","questionType":"MCQ","explanation":{"correct_reason":"The opportunity cost is the hedge cutting and path repairs that were delayed, because those are the next best uses of the gardener's 40 hours.","distractor_reasons":{"A":"The 12 hours are the resource used, not the benefit of the alternative work that was given up.","B":"The opportunity cost is the hedge cutting and path repairs that were delayed, because those are the next best uses of the gardener's 40 hours.","C":"The wages are a cost of employing the gardener, not the alternative output sacrificed.","D":"The plants are an input to the chosen project, not the next best alternative forgone."}}},{"id":"P1_U1_MCQ_1137","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1137","question":"Dunster Bakeries buys flour, butter and yeast and bakes them into bread rolls, which it sells to local cafes. A few staff also deliver the rolls by van. The bakery's main activity belongs to which sector?","options":{"A":"Primary","B":"Secondary","C":"Tertiary","D":"No single sector"},"correctOption":"B","correctAnswer":"Secondary","questionType":"MCQ","explanation":{"correct_reason":"Baking flour, butter and yeast into rolls is manufacturing, so the bakery's main activity is in the secondary sector.","distractor_reasons":{"A":"The bakery buys its flour rather than extracting it, so it is not a primary producer.","B":"Baking flour, butter and yeast into rolls is manufacturing, so the bakery's main activity is in the secondary sector.","C":"Delivery is a minor service activity, but the bakery's main activity is making bread rolls.","D":"The main activity is clearly baking, and one secondary activity dominates the business."}}},{"id":"P1_U1_MCQ_1138","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1138","question":"Mardale Outdoor Co, a maker of walking boots, merges with a competitor that also makes walking boots for the same customers. Which type of integration is this?","options":{"A":"Horizontal integration","B":"Backward vertical integration","C":"Forward vertical integration","D":"Diversification"},"correctOption":"A","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Two businesses at the same stage of production, both making walking boots, merge, which is horizontal integration.","distractor_reasons":{"A":"Two businesses at the same stage of production, both making walking boots, merge, which is horizontal integration.","B":"Backward vertical integration would mean buying a supplier such as a leather producer.","C":"Forward vertical integration would mean buying a retailer or distributor of boots.","D":"Diversification means moving into a different product or market, but both firms make walking boots."}}},{"id":"P1_U1_MCQ_1139","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1139","question":"Marta Ruiz runs Ruiz Cakes as a one-person business from her kitchen. She makes every decision herself and keeps all of the profit that remains after tax. Which advantage of being a sole trader does this describe?","options":{"A":"Limited liability for business debts","B":"Easier access to large bank loans","C":"Continuity of the business if the owner retires","D":"Complete control and the right to keep all profit"},"correctOption":"D","correctAnswer":"Complete control and the right to keep all profit","questionType":"MCQ","explanation":{"correct_reason":"A sole trader makes all decisions alone and keeps the profit, which gives complete control and direct reward.","distractor_reasons":{"A":"Sole traders have unlimited liability, which is a disadvantage rather than an advantage.","B":"Banks often see sole traders as riskier, so large loans are harder to obtain.","C":"A sole trader business usually ends or must be sold when the owner retires, so continuity is weak.","D":"A sole trader makes all decisions alone and keeps the profit, which gives complete control and direct reward."}}},{"id":"P1_U1_MCQ_1140","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1140","question":"Slaidburn Farms is a dairy business that was fined for discharging slurry into a river after a pollution incident. Which stakeholder receives the fine and also expects the business to follow environmental rules?","options":{"A":"The farm's customers","B":"The farm's lender","C":"The government","D":"A local wildlife charity"},"correctOption":"C","correctAnswer":"The government","questionType":"MCQ","explanation":{"correct_reason":"The government sets environmental rules and collects fines, so it is the stakeholder receiving the penalty.","distractor_reasons":{"A":"Customers buy the farm's produce and do not issue fines for river pollution.","B":"A lender provides finance and does not enforce environmental law.","C":"The government sets environmental rules and collects fines, so it is the stakeholder receiving the penalty.","D":"A wildlife charity may campaign for cleaner rivers, but it cannot impose a fine."}}},{"id":"P1_U1_MCQ_1141","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1141","question":"Loxley Vale Farm is run by Priya Shah, who left a secure job in a bank, invested $60,000 of her own savings and now takes the risk of deciding which crops to grow each season. Which factor of production does Priya mainly provide?","options":{"A":"Capital","B":"Labour","C":"Enterprise","D":"Land"},"correctOption":"C","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Priya supplies enterprise by risking her $60,000 savings and deciding which crops to grow, which is the organising and risk-taking factor.","distractor_reasons":{"A":"Capital refers to the money and equipment used, but the question asks about the person taking the risk and making decisions.","B":"Labour is the physical and mental effort of workers, not the owner's risk-taking role.","C":"Priya supplies enterprise by risking her $60,000 savings and deciding which crops to grow, which is the organising and risk-taking factor.","D":"Land means natural resources such as soil and water, not the owner's decision-making."}}},{"id":"P1_U1_MCQ_1142","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1142","question":"Vellinor Insurance employs 300 people in Bristol who sell household policies and settle claims for customers whose homes are damaged. Which sector of the economy does Vellinor Insurance belong to?","options":{"A":"Secondary","B":"Tertiary","C":"Primary","D":"Primary, because it insures property"},"correctOption":"B","correctAnswer":"Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Selling insurance policies and settling claims are financial services, which place Vellinor in the tertiary sector.","distractor_reasons":{"A":"Vellinor does not manufacture a physical product; it provides cover and handles claims.","B":"Selling insurance policies and settling claims are financial services, which place Vellinor in the tertiary sector.","C":"The primary sector extracts natural resources, which insurance does not do.","D":"Insuring property is a service; the property itself is not being extracted or processed."}}},{"id":"P1_U1_MCQ_1143","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1143","question":"Bexington Bakery buys the flour mill that has supplied its bread flour for years, so that the mill now forms part of the bakery business. Which type of integration is this?","options":{"A":"Backward vertical integration","B":"Forward vertical integration","C":"Horizontal integration","D":"A joint venture"},"correctOption":"A","correctAnswer":"Backward vertical integration","questionType":"MCQ","explanation":{"correct_reason":"Buying the flour mill that supplies its main raw material is backward vertical integration into an earlier stage of production.","distractor_reasons":{"A":"Buying the flour mill that supplies its main raw material is backward vertical integration into an earlier stage of production.","B":"Forward vertical integration would mean buying a customer such as a chain of cafes.","C":"Horizontal integration would mean merging with another bakery at the same stage of production.","D":"A joint venture is a shared new project with another firm, not the outright purchase of a supplier."}}},{"id":"P1_U1_MCQ_1144","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1144","question":"Two accountants form a partnership. One wants to open a second office, but the other disagrees and refuses to sign the lease, so the plan fails. Which disadvantage of a partnership does this show?","options":{"A":"All profits must be paid to outside shareholders","B":"The partners automatically have limited liability","C":"Its accounts must be published for the public","D":"Decision-making can be slowed by disagreements between partners"},"correctOption":"D","correctAnswer":"Decision-making can be slowed by disagreements between partners","questionType":"MCQ","explanation":{"correct_reason":"Partners must agree major decisions, and one partner's refusal blocked the second office, showing slower decision-making.","distractor_reasons":{"A":"A partnership has no outside shareholders; profits are shared between the partners themselves.","B":"Ordinary partners have unlimited liability, so this statement about partnerships is false.","C":"Partnership accounts are private, unlike those of a public limited company.","D":"Partners must agree major decisions, and one partner's refusal blocked the second office, showing slower decision-making."}}},{"id":"P1_U1_MCQ_1145","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1145","question":"Rothbury Energy is a small renewable electricity supplier. It made a profit of $64,000 in 2024 and $80,000 in 2025. What was the percentage increase in profit?","options":{"A":"20%","B":"16%","C":"80%","D":"25%"},"correctOption":"D","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Profit rose by $80,000 minus $64,000, giving $16,000, and $16,000 divided by the original $64,000 gives 25%.","distractor_reasons":{"A":"20% divides the $16,000 increase by the new profit of $80,000 instead of the original $64,000.","B":"16% confuses the $16,000 cash increase with a percentage rate.","C":"80% would mean a rise of $51,200, far more than the $16,000 actually achieved.","D":"Profit rose by $80,000 minus $64,000, giving $16,000, and $16,000 divided by the original $64,000 gives 25%."}}},{"id":"P1_U1_MCQ_1146","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1146","question":"Skerries Smokehouse sells 3,000 kilograms of smoked salmon at $24 per kilogram. The raw fish costs $9 per kilogram and other bought-in inputs, such as packaging and fuel, cost $18,000 in total. What is the added value?","options":{"A":"$45,000","B":"$54,000","C":"$27,000","D":"$72,000"},"correctOption":"C","correctAnswer":"$27,000","questionType":"MCQ","explanation":{"correct_reason":"Sales revenue is 3,000 multiplied by $24, giving $72,000, and bought-in costs are $27,000 for fish plus $18,000, so added value is $27,000.","distractor_reasons":{"A":"$45,000 is the total bought-in cost of fish, packaging and fuel, not the added value created.","B":"$54,000 wrongly deducts only the $18,000 of other inputs and ignores the $27,000 spent on fish.","C":"Sales revenue is 3,000 multiplied by $24, giving $72,000, and bought-in costs are $27,000 for fish plus $18,000, so added value is $27,000.","D":"$72,000 is total sales revenue before any bought-in costs are subtracted."}}},{"id":"P1_U1_MCQ_1147","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1147","question":"Marchwood Timber employs 1,200 workers across its region. Of these, 45% work in sawmills and joinery workshops that process timber into boards and frames. How many workers are employed in the secondary sector?","options":{"A":"660","B":"540","C":"450","D":"120"},"correctOption":"B","correctAnswer":"540","questionType":"MCQ","explanation":{"correct_reason":"45% of 1,200 workers is 0.45 multiplied by 1,200, which equals 540 workers in sawmills and joinery workshops.","distractor_reasons":{"A":"660 is the remaining 55% of workers, not the 45% employed in secondary processing.","B":"45% of 1,200 workers is 0.45 multiplied by 1,200, which equals 540 workers in sawmills and joinery workshops.","C":"450 would be 37.5% of 1,200, not the 45% stated in the stem.","D":"120 is 10% of the workforce and does not match the 45% given."}}},{"id":"P1_U1_MCQ_1148","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1148","question":"Lullington Software sold 36,000 licences in 2025 when the market totalled 240,000 licences. In 2026 it sold 52,000 licences in a market of 260,000. What happened to its market share?","options":{"A":"It rose by 5 percentage points","B":"It rose by 16 percentage points","C":"It rose by 44%","D":"It fell by 5 percentage points"},"correctOption":"A","correctAnswer":"It rose by 5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Share was 36,000 divided by 240,000, or 15%, in 2025 and 52,000 divided by 260,000, or 20%, in 2026, a rise of 5 percentage points.","distractor_reasons":{"A":"Share was 36,000 divided by 240,000, or 15%, in 2025 and 52,000 divided by 260,000, or 20%, in 2026, a rise of 5 percentage points.","B":"16 percentage points confuses the growth in licence sales with the change in market share.","C":"44% is the percentage rise in licences sold, not the change in market share.","D":"The share rose from 15% to 20%, so it did not fall by 5 percentage points."}}},{"id":"P1_U1_MCQ_1149","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1149","question":"A growing joinery business needs $250,000 for new machinery. As a private limited company it can sell shares to 12 investors, whereas as a sole trader it could only borrow. Which advantage of incorporation does this show?","options":{"A":"It can raise capital by selling shares","B":"It pays no tax on its profits","C":"It faces fewer reporting requirements","D":"It cannot be sued by customers"},"correctOption":"A","correctAnswer":"It can raise capital by selling shares","questionType":"MCQ","explanation":{"correct_reason":"A private limited company can issue shares to investors, which lets it raise $250,000 that a sole trader could only borrow.","distractor_reasons":{"A":"A private limited company can issue shares to investors, which lets it raise $250,000 that a sole trader could only borrow.","B":"Companies pay tax on profits, so incorporation does not remove the tax bill.","C":"A limited company faces more reporting requirements, not fewer, than a sole trader.","D":"A company is a separate legal entity and can still be sued by customers."}}},{"id":"P1_U1_MCQ_1150","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1150","question":"Kirkside Retail opened during a recession and its first aim was to cover costs and stay open. Two years later it is profitable and now plans 20 new stores. What does this show about business objectives?","options":{"A":"Objectives are fixed for the whole life of a business","B":"Survival is only relevant to large firms","C":"Growth is impossible for retail businesses","D":"Objectives can change as a business's circumstances change"},"correctOption":"D","correctAnswer":"Objectives can change as a business's circumstances change","questionType":"MCQ","explanation":{"correct_reason":"The aim moved from survival to growth as the business became established, showing that objectives change with circumstances.","distractor_reasons":{"A":"Kirkside's aims changed within two years, so objectives are not fixed for the life of a business.","B":"Survival can matter to firms of any size during a crisis, not only to small ones.","C":"Many retailers grow by opening new stores, so growth is clearly possible.","D":"The aim moved from survival to growth as the business became established, showing that objectives change with circumstances."}}},{"id":"P1_U1_MCQ_1151","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1151","question":"Pendennis Legal Services advises house buyers in Falmouth, charging $450 for each property transaction and employing four solicitors. Which statement about the output of this business is correct?","options":{"A":"Its output is tangible and can be stored as stock","B":"It belongs to the secondary sector of the economy","C":"It provides a service rather than a physical good","D":"It sells goods to other businesses"},"correctOption":"C","correctAnswer":"It provides a service rather than a physical good","questionType":"MCQ","explanation":{"correct_reason":"Legal advice is an intangible service, so Pendennis sells expertise rather than a physical good that can be stored.","distractor_reasons":{"A":"Legal advice cannot be stored as stock; it is consumed as it is provided, which is typical of a service.","B":"The secondary sector makes physical goods, whereas this firm sells advice to house buyers.","C":"Legal advice is an intangible service, so Pendennis sells expertise rather than a physical good that can be stored.","D":"Pendennis sells a service to households, not goods to other businesses."}}},{"id":"P1_U1_MCQ_1152","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1152","question":"Calderbank Hospital Trust is owned and funded by the government, treats patients free of charge and is managed by a board appointed by the health ministry. Which type of organisation is it?","options":{"A":"A public limited company","B":"A public sector organisation","C":"A sole trader","D":"A workers' co-operative"},"correctOption":"B","correctAnswer":"A public sector organisation","questionType":"MCQ","explanation":{"correct_reason":"Government ownership, free treatment and a minister-appointed board are features of a public sector organisation.","distractor_reasons":{"A":"A public limited company is owned by shareholders and aims to make profit, not by the government.","B":"Government ownership, free treatment and a minister-appointed board are features of a public sector organisation.","C":"A sole trader is one owner running a business, which cannot describe a state-funded hospital trust.","D":"A co-operative is owned by its members, not funded and controlled by a government ministry."}}},{"id":"P1_U1_MCQ_1153","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1153","question":"Carrowdale Nurseries earned revenue of $180,000 last year. After paying all of its costs it kept a profit of $27,000. What was its profit margin?","options":{"A":"6.7%","B":"15%","C":"17.6%","D":"85%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit margin is profit divided by revenue, so $27,000 divided by $180,000 multiplied by 100 gives 15%.","distractor_reasons":{"A":"6.7% divides the profit by a much larger figure than the $180,000 of revenue.","B":"Profit margin is profit divided by revenue, so $27,000 divided by $180,000 multiplied by 100 gives 15%.","C":"17.6% divides profit by costs of $153,000 rather than by revenue.","D":"85% is the proportion of revenue absorbed by costs, not the profit margin."}}},{"id":"P1_U1_MCQ_1154","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1154","question":"A family owns 45% of the shares in a company quoted on the stock exchange. A rival buys 30% of the shares and demands seats on the board. Which disadvantage of a public limited company does this show?","options":{"A":"Control can be lost to outside shareholders or a takeover","B":"Shares cannot be transferred between owners","C":"Owners face unlimited liability for company debts","D":"The company is unable to borrow money"},"correctOption":"A","correctAnswer":"Control can be lost to outside shareholders or a takeover","questionType":"MCQ","explanation":{"correct_reason":"Shares in a quoted company can be bought by outsiders, so the family's 45% stake can be challenged by a rival holding 30%.","distractor_reasons":{"A":"Shares in a quoted company can be bought by outsiders, so the family's 45% stake can be challenged by a rival holding 30%.","B":"Plc shares are freely transferable, which is exactly how the rival bought its 30% stake.","C":"Shareholders of a plc have limited liability, not unlimited liability.","D":"A plc can borrow, and its ability to raise large amounts of capital is one of its advantages."}}},{"id":"P1_U1_MCQ_1155","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1155","question":"Trevose Fishmongers raises its prices by 8% after its rent increases, and several regular shoppers say they will buy fish from the supermarket instead. Which stakeholder is reacting to the decision?","options":{"A":"Suppliers of fish","B":"The landlord","C":"The employees","D":"Customers"},"correctOption":"D","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"The regular shoppers deciding to move to the supermarket are customers reacting to the 8% price rise.","distractor_reasons":{"A":"Suppliers provide fish to the shop and are not the group choosing where to shop.","B":"The landlord caused the rent rise but is not reacting as a buyer of fish.","C":"Employees work in the shop and are not the group switching to the supermarket.","D":"The regular shoppers deciding to move to the supermarket are customers reacting to the 8% price rise."}}},{"id":"P1_U1_MCQ_1156","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1156","question":"Kilve Chocolate makes 4,000 bars a week. Ingredients and wrappers cost $1.85 per bar and each bar sells for $3.20. What is the added value per bar?","options":{"A":"$1.85","B":"$3.20","C":"$1.35","D":"$5.05"},"correctOption":"C","correctAnswer":"$1.35","questionType":"MCQ","explanation":{"correct_reason":"Added value per bar is the $3.20 selling price minus the $1.85 of ingredients and wrappers, which equals $1.35.","distractor_reasons":{"A":"$1.85 is the bought-in cost per bar, not the value added to it.","B":"$3.20 is the selling price, which still includes the $1.85 of bought-in materials.","C":"Added value per bar is the $3.20 selling price minus the $1.85 of ingredients and wrappers, which equals $1.35.","D":"$5.05 adds the price and the cost together instead of subtracting the cost from the price."}}},{"id":"P1_U1_MCQ_1157","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1157","question":"Sennenwick Fishing Fleet once employed 140 people. After the harbour installed automated ice-packing and the larger boats needed fewer crew, it employs 85. Which reason for the decline of primary sector employment does this show?","options":{"A":"Rising demand for fish from households","B":"A government ban on all fishing","C":"Increased use of machinery replacing labour","D":"Higher prices paid for fish by supermarkets"},"correctOption":"C","correctAnswer":"Increased use of machinery replacing labour","questionType":"MCQ","explanation":{"correct_reason":"Automated ice-packing and larger boats needing fewer crew show mechanisation replacing labour, a main cause of falling primary employment.","distractor_reasons":{"A":"Rising demand for fish would usually support employment, not reduce it from 140 to 85.","B":"The fleet still operates with 85 workers, so there is no ban on fishing.","C":"Automated ice-packing and larger boats needing fewer crew show mechanisation replacing labour, a main cause of falling primary employment.","D":"Higher prices paid by supermarkets would not by themselves explain the fall in crew numbers."}}},{"id":"P1_U1_MCQ_1158","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1158","question":"Stydd Garden Centre is a family-run shop that offers personal advice, unusual plants and home delivery within ten miles, none of which the large out-of-town chain provides. Why can this small firm survive alongside bigger rivals?","options":{"A":"It benefits from large-scale economies of production","B":"It offers personal service and a niche range that larger firms do not provide","C":"It can raise capital more easily than a national chain","D":"It has lower average costs than the chain"},"correctOption":"B","correctAnswer":"It offers personal service and a niche range that larger firms do not provide","questionType":"MCQ","explanation":{"correct_reason":"Personal advice, unusual plants and local delivery are niche services that let a small firm compete without large-scale economies.","distractor_reasons":{"A":"A single garden centre cannot match the bulk-buying economies of a large chain.","B":"Personal advice, unusual plants and local delivery are niche services that let a small firm compete without large-scale economies.","C":"Small firms usually find it harder, not easier, to raise large amounts of capital.","D":"The chain is more likely to have lower average costs because of its scale."}}},{"id":"P1_U1_MCQ_1159","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1159","question":"Glendinning Foods Ltd earns a profit after tax of $250,000, and its board decides to keep most of it for a new production line, paying only a small amount to shareholders. What is the payment to shareholders called?","options":{"A":"A dividend, which is a share of profit paid to shareholders","B":"Interest, which is a payment made to lenders","C":"Corporation tax, which is paid to the government","D":"A trade discount, which is given to customers"},"correctOption":"A","correctAnswer":"A dividend, which is a share of profit paid to shareholders","questionType":"MCQ","explanation":{"correct_reason":"A dividend is the part of profit after tax that a company distributes to its shareholders.","distractor_reasons":{"A":"A dividend is the part of profit after tax that a company distributes to its shareholders.","B":"Interest is paid to lenders for borrowed money, not to shareholders out of profit.","C":"Corporation tax is paid on profits to the government, not distributed to shareholders.","D":"A trade discount reduces the price charged to customers and has nothing to do with profit distribution."}}},{"id":"P1_U1_MCQ_1160","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1160","question":"The managers of a chain of garden centres propose buying two rivals, which would raise their salaries and status but reduce the dividend paid this year. Which stakeholder conflict does this create?","options":{"A":"Customers against suppliers","B":"Government against employees","C":"Local residents against customers","D":"Managers wanting growth against shareholders wanting income now"},"correctOption":"D","correctAnswer":"Managers wanting growth against shareholders wanting income now","questionType":"MCQ","explanation":{"correct_reason":"Managers gain salary and status from expansion, while shareholders lose dividend income this year, so their interests conflict.","distractor_reasons":{"A":"The stem concerns ownership and rewards, not a dispute between customers and suppliers.","B":"Government and employees are not the two groups whose rewards are set against each other here.","C":"Local residents and customers are not mentioned as parties to this decision.","D":"Managers gain salary and status from expansion, while shareholders lose dividend income this year, so their interests conflict."}}},{"id":"P1_U1_MCQ_1161","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1161","question":"Haytor Hill Sheepskins stopped making its own woollen rugs and now concentrates on tanning fleeces, buying finished rugs from another workshop. Output of tanned fleeces rose by 30% from the same resources. Which benefit of specialisation does this show?","options":{"A":"Lower total demand for the firm's products","B":"The firm no longer depends on other businesses","C":"A wider range of products made on site","D":"Greater output from the same resources by concentrating on one task"},"correctOption":"D","correctAnswer":"Greater output from the same resources by concentrating on one task","questionType":"MCQ","explanation":{"correct_reason":"By concentrating on tanning fleeces, Haytor Hill uses its resources on the task it does best, raising output by 30% from the same inputs.","distractor_reasons":{"A":"Specialisation is intended to raise efficiency and output, not to reduce demand for the firm's products.","B":"Specialising usually increases interdependence, because the firm now buys finished rugs from another workshop.","C":"The firm has narrowed its range by dropping rug making, so its on-site product range has become smaller.","D":"By concentrating on tanning fleeces, Haytor Hill uses its resources on the task it does best, raising output by 30% from the same inputs."}}},{"id":"P1_U1_MCQ_1162","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1162","question":"Rosslare Bay has a workforce of 80,000. Fishing employs 12,000, canning and packing employs 28,000, and hotels, shops and transport employ the rest. What percentage of the workforce is in the tertiary sector?","options":{"A":"35%","B":"15%","C":"50%","D":"65%"},"correctOption":"C","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Tertiary workers are 80,000 minus 12,000 minus 28,000, giving 40,000, and 40,000 divided by 80,000 is 50%.","distractor_reasons":{"A":"35% is the share employed in canning and packing, not the share employed in services.","B":"15% is the share employed in fishing, not the tertiary share.","C":"Tertiary workers are 80,000 minus 12,000 minus 28,000, giving 40,000, and 40,000 divided by 80,000 is 50%.","D":"65% combines fishing and canning, which is the non-tertiary share of the workforce."}}},{"id":"P1_U1_MCQ_1163","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1163","question":"Penyard Packaging's owner writes a document setting out her aims, target customers, expected costs of $84,000 and forecast sales before approaching a bank for a loan. What is this document called?","options":{"A":"A statement of financial position","B":"A business plan","C":"A cash flow forecast","D":"A partnership agreement"},"correctOption":"B","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"A business plan sets out aims, target customers, expected costs and forecast sales, and is used to support a loan application.","distractor_reasons":{"A":"A statement of financial position records assets and liabilities at a point in time, not future plans and targets.","B":"A business plan sets out aims, target customers, expected costs and forecast sales, and is used to support a loan application.","C":"A cash flow forecast only projects receipts and payments, not aims and target customers.","D":"A partnership agreement covers the terms between partners, not market plans and a loan application."}}},{"id":"P1_U1_MCQ_1164","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1164","question":"The Larkrise Cafe trains long-term unemployed people as chefs and spends any surplus on free meals for older residents, rather than paying dividends. Which type of organisation is it?","options":{"A":"A social enterprise","B":"A public limited company","C":"A franchise","D":"A public corporation"},"correctOption":"A","correctAnswer":"A social enterprise","questionType":"MCQ","explanation":{"correct_reason":"Training unemployed people and spending surplus on free meals instead of dividends are social aims, so the cafe is a social enterprise.","distractor_reasons":{"A":"Training unemployed people and spending surplus on free meals instead of dividends are social aims, so the cafe is a social enterprise.","B":"A public limited company exists to reward shareholders, which this cafe explicitly does not do.","C":"A franchise is a licence to trade under another firm's brand, not a charity-funded training cafe.","D":"A public corporation is state-owned, whereas this cafe is run by a charity."}}},{"id":"P1_U1_MCQ_1165","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1165","question":"Staindrop Textiles Ltd makes a profit after tax of $320,000 and pays $96,000 to its shareholders. What percentage of profit after tax is paid as dividends?","options":{"A":"30%","B":"70%","C":"33.3%","D":"3.3%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Dividends as a share of profit after tax are $96,000 divided by $320,000, multiplied by 100, which gives 30%.","distractor_reasons":{"A":"Dividends as a share of profit after tax are $96,000 divided by $320,000, multiplied by 100, which gives 30%.","B":"70% is the share of profit retained in the business, not the share paid out as dividends.","C":"33.3% would need $106,667 of dividends, not the $96,000 actually paid.","D":"3.3% misplaces the decimal point, because the correct answer is ten times larger."}}},{"id":"P1_U1_MCQ_1166","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1166","question":"Berewick Apiaries now has each of its six staff doing one repeated job all day: one fills jars, one labels, one packs boxes. Staff say the work is dull and two have resigned. Which disadvantage of division of labour is shown?","options":{"A":"Output per worker always falls when tasks are divided","B":"Every worker must be trained in all of the firm's tasks","C":"Specialised machinery can no longer be used","D":"Workers become bored and demotivated by repetitive tasks"},"correctOption":"D","correctAnswer":"Workers become bored and demotivated by repetitive tasks","questionType":"MCQ","explanation":{"correct_reason":"Repeating one narrow task all day is monotonous, and the two resignations show the boredom and low motivation that division of labour can cause.","distractor_reasons":{"A":"Division of labour normally raises output per worker, so an automatic fall in output is not the problem shown.","B":"Division of labour reduces training needs because each worker learns only one narrow task.","C":"Specialised machinery can be used alongside division of labour, so this is not the disadvantage shown.","D":"Repeating one narrow task all day is monotonous, and the two resignations show the boredom and low motivation that division of labour can cause."}}},{"id":"P1_U1_MCQ_1167","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1167","question":"Thornbury Weavers closed two mills as cheaper imported cloth took its customers, and the town's textile jobs fell from 3,100 to 1,400 in ten years. Which term describes this change?","options":{"A":"Urbanisation","B":"Specialisation","C":"Deindustrialisation","D":"A mixed economy"},"correctOption":"C","correctAnswer":"Deindustrialisation","questionType":"MCQ","explanation":{"correct_reason":"A long-term fall in manufacturing employment as imports take customers is deindustrialisation.","distractor_reasons":{"A":"Urbanisation describes population moving to towns, not the loss of textile jobs to imports.","B":"Specialisation means concentrating on particular tasks or products, not a decline in manufacturing jobs.","C":"A long-term fall in manufacturing employment as imports take customers is deindustrialisation.","D":"A mixed economy describes public and private ownership, not the change in textile employment."}}},{"id":"P1_U1_MCQ_1168","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1168","question":"Usk Valley Mushrooms needs $36,000 for growing sheds, $9,000 for stock, $2,500 for legal fees and $7,500 as working capital. The owner will invest $30,000 of her own money. How much must she borrow?","options":{"A":"$30,000","B":"$25,000","C":"$55,000","D":"$45,000"},"correctOption":"B","correctAnswer":"$25,000","questionType":"MCQ","explanation":{"correct_reason":"Total needs are $36,000 plus $9,000 plus $2,500 plus $7,500, giving $55,000, so borrowing is $55,000 minus $30,000, which is $25,000.","distractor_reasons":{"A":"$30,000 is the owner's own investment, not the amount still needed from a lender.","B":"Total needs are $36,000 plus $9,000 plus $2,500 plus $7,500, giving $55,000, so borrowing is $55,000 minus $30,000, which is $25,000.","C":"$55,000 is the total funding required before the owner's $30,000 is deducted.","D":"$45,000 ignores the $7,500 of working capital and part of the other start-up costs."}}},{"id":"P1_U1_MCQ_1169","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1169","question":"Before signing a franchise agreement, a new franchisee is told she must follow the franchisor's recipes, shop design and pricing rules. What is the main benefit to her of accepting these rules?","options":{"A":"She can change the menu whenever she chooses","B":"She gains a proven brand and operating system","C":"She avoids paying any fees to the franchisor","D":"She owns the brand name outright"},"correctOption":"B","correctAnswer":"She gains a proven brand and operating system","questionType":"MCQ","explanation":{"correct_reason":"Following the franchisor's recipes, design and prices gives the franchisee a recognised brand and a tested way of running the outlet.","distractor_reasons":{"A":"Franchise rules restrict what the franchisee may change, so free menu changes are not a benefit.","B":"Following the franchisor's recipes, design and prices gives the franchisee a recognised brand and a tested way of running the outlet.","C":"A franchisee pays an initial fee and usually a royalty, so fees are not avoided.","D":"The brand remains the franchisor's property and is only licensed to the franchisee."}}},{"id":"P1_U1_MCQ_1170","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1170","question":"The total market for garden sheds is 500,000 units a year. A manufacturer sets an objective of a 22% market share. How many sheds must it sell to achieve this target?","options":{"A":"110,000","B":"22,000","C":"500,000","D":"78,000"},"correctOption":"A","correctAnswer":"110,000","questionType":"MCQ","explanation":{"correct_reason":"22% of 500,000 units is 0.22 multiplied by 500,000, which equals 110,000 sheds a year.","distractor_reasons":{"A":"22% of 500,000 units is 0.22 multiplied by 500,000, which equals 110,000 sheds a year.","B":"22,000 would be only 4.4% of the 500,000-unit market, far below the target.","C":"500,000 is the whole market, which would represent a 100% share.","D":"78,000 is the 15.6% of the market the firm would not hold, not the target."}}},{"id":"P1_U1_MCQ_1171","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1171","question":"Colwyn Slate Works sells 900 roofing slates at $14 each and 150 decorative slabs at $40 each. Its total bought-in costs are $9,700. What is the added value created?","options":{"A":"$9,700","B":"$18,600","C":"$12,600","D":"$8,900"},"correctOption":"D","correctAnswer":"$8,900","questionType":"MCQ","explanation":{"correct_reason":"Revenue is 900 multiplied by $14, giving $12,600, plus 150 multiplied by $40, giving $6,000, so total revenue of $18,600 less $9,700 leaves $8,900.","distractor_reasons":{"A":"$9,700 is the bought-in cost, not the added value created by selling the slates.","B":"$18,600 is total sales revenue before the $9,700 of bought-in costs is deducted.","C":"$12,600 is only the revenue from the 900 roofing slates and ignores the decorative slabs.","D":"Revenue is 900 multiplied by $14, giving $12,600, plus 150 multiplied by $40, giving $6,000, so total revenue of $18,600 less $9,700 leaves $8,900."}}},{"id":"P1_U1_MCQ_1172","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1172","question":"Illingworth Coachworks earned $2.4 million from building bus bodies and $600,000 from servicing buses last year. What percentage of its revenue came from secondary sector activity?","options":{"A":"75%","B":"25%","C":"80%","D":"20%"},"correctOption":"C","correctAnswer":"80%","questionType":"MCQ","explanation":{"correct_reason":"Total revenue is $2.4 million plus $600,000, giving $3.0 million, and building bus bodies gives $2.4 million divided by $3.0 million, or 80%.","distractor_reasons":{"A":"75% would mean $2.25 million of manufacturing revenue, but the stem gives $2.4 million.","B":"25% is the servicing share of revenue, not the secondary manufacturing share.","C":"Total revenue is $2.4 million plus $600,000, giving $3.0 million, and building bus bodies gives $2.4 million divided by $3.0 million, or 80%.","D":"20% would leave manufacturing at $600,000, the same as servicing."}}},{"id":"P1_U1_MCQ_1173","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1173","question":"Threlkeld Kitchens is a fitted-kitchen manufacturer in Cumbria. It employs 85 workers across two shifts and produced 34,000 kitchen units last year. What is its output per worker per year?","options":{"A":"4,000 units","B":"40 units","C":"400 units","D":"340 units"},"correctOption":"C","correctAnswer":"400 units","questionType":"MCQ","explanation":{"correct_reason":"Output per worker is 34,000 units divided by 85 workers, which equals 400 units a year.","distractor_reasons":{"A":"4,000 units would need only 8.5 workers at this rate, so it is ten times too high.","B":"40 units is too low, because dividing 34,000 by 85 gives 400 rather than 40.","C":"Output per worker is 34,000 units divided by 85 workers, which equals 400 units a year.","D":"340 units does not follow from these figures and would give total output of only 28,900 units."}}},{"id":"P1_U1_MCQ_1174","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1174","question":"A partnership's two owners contribute $60,000 and $40,000 and agree to share profit in proportion to capital. Profit for the year is $72,000. What does the second partner receive?","options":{"A":"$43,200","B":"$28,800","C":"$36,000","D":"$32,000"},"correctOption":"B","correctAnswer":"$28,800","questionType":"MCQ","explanation":{"correct_reason":"The second partner contributed $40,000 of the $100,000 total, so receives 40% of $72,000, which is $28,800.","distractor_reasons":{"A":"$43,200 is the first partner's 60% share of the $72,000 profit, not the second partner's share.","B":"The second partner contributed $40,000 of the $100,000 total, so receives 40% of $72,000, which is $28,800.","C":"$36,000 would be an equal 50:50 split, which ignores the agreed capital ratio.","D":"$32,000 does not match a 40% share of the $72,000 profit."}}},{"id":"P1_U1_MCQ_1175","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1175","question":"A government-owned bus company in the Highlands runs unprofitable rural routes at a loss because villagers would otherwise have no transport to shops or hospitals. Which objective best explains this decision?","options":{"A":"Providing a service to the public","B":"Maximising profit","C":"Increasing market share","D":"Paying high dividends to shareholders"},"correctOption":"A","correctAnswer":"Providing a service to the public","questionType":"MCQ","explanation":{"correct_reason":"Running unprofitable rural routes to keep villagers connected is a public service objective rather than profit maximisation.","distractor_reasons":{"A":"Running unprofitable rural routes to keep villagers connected is a public service objective rather than profit maximisation.","B":"The routes lose money, so keeping them open does not maximise profit.","C":"The decision is about serving isolated villages, not about the share of the bus market.","D":"A government-owned bus company does not pay dividends to private shareholders."}}},{"id":"P1_U1_MCQ_1176","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1176","question":"Fennymoor Glass has one furnace that can make either 2,000 window panes or 700 glass bottles in a day. The manager chooses to make the window panes. Which statement describes the opportunity cost of this choice?","options":{"A":"The 2,000 window panes that are actually produced","B":"The fuel used to heat the furnace during the day","C":"The wages of the furnace operators","D":"The 700 glass bottles that the furnace could have made instead"},"correctOption":"D","correctAnswer":"The 700 glass bottles that the furnace could have made instead","questionType":"MCQ","explanation":{"correct_reason":"Choosing 2,000 panes means the 700 bottles that the same furnace could have made are the next best alternative given up.","distractor_reasons":{"A":"The panes are the option actually chosen, not the alternative that was sacrificed.","B":"Fuel is an input used in either choice, not the alternative output forgone.","C":"Wages are a cost of production that would be paid either way, not the opportunity cost.","D":"Choosing 2,000 panes means the 700 bottles that the same furnace could have made are the next best alternative given up."}}},{"id":"P1_U1_MCQ_1177","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1177","question":"In Poldhu, milk is collected by a privately owned dairy, but the government sets minimum hygiene standards and funds a free school milk scheme. Which term best describes this economy?","options":{"A":"A command economy only","B":"A free market economy only","C":"A primary sector economy","D":"A mixed economy"},"correctOption":"D","correctAnswer":"A mixed economy","questionType":"MCQ","explanation":{"correct_reason":"A privately owned dairy operating alongside government regulation and a state-funded milk scheme is a mixed economy.","distractor_reasons":{"A":"A command economy would have the government own and direct production, but the dairy is privately owned.","B":"A pure free market would have no government standards or funded scheme, which the stem describes.","C":"The economy includes private business, regulation and services, so it is not defined only by its primary sector.","D":"A privately owned dairy operating alongside government regulation and a state-funded milk scheme is a mixed economy."}}},{"id":"P1_U1_MCQ_1178","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1178","question":"Wooler Wear doubles its output after winning a large export order, but it must pay for extra cloth and wages 60 days before the customer pays. Which problem of growth does this best illustrate?","options":{"A":"A fall in fixed costs as output doubles","B":"Loss of control by the owner","C":"Cash flow difficulties while waiting for payment","D":"A reduced need for working capital"},"correctOption":"C","correctAnswer":"Cash flow difficulties while waiting for payment","questionType":"MCQ","explanation":{"correct_reason":"Paying for cloth and wages 60 days before receiving payment creates a cash outflow gap, a common cash flow problem of rapid growth.","distractor_reasons":{"A":"Doubling output usually raises costs, and the stem describes a timing gap rather than falling fixed costs.","B":"The stem says nothing about ownership or decision-making changing as the firm grows.","C":"Paying for cloth and wages 60 days before receiving payment creates a cash outflow gap, a common cash flow problem of rapid growth.","D":"Growth increases the need for working capital, because more cash is tied up in stock and wages."}}},{"id":"P1_U1_MCQ_1179","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1179","question":"A family owns 1,200,000 of the 2,000,000 ordinary shares in a private limited company and wants to keep control of it. What does this majority holding allow the family to do?","options":{"A":"Guarantee a fixed dividend every year","B":"Elect the directors and control major decisions","C":"Avoid all liability for the company's debts","D":"Sell its shares on a stock exchange"},"correctOption":"B","correctAnswer":"Elect the directors and control major decisions","questionType":"MCQ","explanation":{"correct_reason":"A majority shareholding carries most votes at general meetings, so the family can appoint directors and approve major decisions.","distractor_reasons":{"A":"Dividends depend on profit and board decisions, so a majority stake cannot guarantee a fixed payment.","B":"A majority shareholding carries most votes at general meetings, so the family can appoint directors and approve major decisions.","C":"Shareholders have limited liability, but this is a legal protection, not a total avoidance of every obligation.","D":"A private limited company's shares are not traded on a stock exchange."}}},{"id":"P1_U1_MCQ_1180","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1180","question":"A listed company's largest investor sells its shares after two years of spending on research that reduced profit. Which pressure on business objectives does this illustrate?","options":{"A":"Shareholders may push for short-term profit rather than long-term investment","B":"Customers demanding lower prices","C":"Employees preferring lower wages","D":"Government requiring research spending"},"correctOption":"A","correctAnswer":"Shareholders may push for short-term profit rather than long-term investment","questionType":"MCQ","explanation":{"correct_reason":"The investor sold because research spending reduced short-term profit, showing shareholder pressure for quick returns over long investment.","distractor_reasons":{"A":"The investor sold because research spending reduced short-term profit, showing shareholder pressure for quick returns over long investment.","B":"Nothing in the stem says customers demanded lower prices.","C":"Employees are not said to prefer lower wages; the issue is the investor's reaction.","D":"The stem describes an investor selling shares, not a government requirement."}}},{"id":"P1_U1_MCQ_1181","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1181","question":"Ravensgill Ropeworks sells climbing ropes to retailers at $38 each. It begins adding a free inspection certificate and a longer guarantee, which allows it to charge $46 for each rope. Which change has increased its added value?","options":{"A":"Adding a service feature that raises the price customers pay","B":"Paying its workers a higher hourly wage while the price stays at $38","C":"Using more nylon in every rope while the price stays at $38","D":"Moving the factory to a larger site while the price stays at $38"},"correctOption":"A","correctAnswer":"Adding a service feature that raises the price customers pay","questionType":"MCQ","explanation":{"correct_reason":"Added value rises because the certificate and guarantee let Ravensgill charge $46 instead of $38 for the same bought-in rope, adding $8 of value.","distractor_reasons":{"A":"Added value rises because the certificate and guarantee let Ravensgill charge $46 instead of $38 for the same bought-in rope, adding $8 of value.","B":"Paying higher wages raises costs but does not raise the price customers pay, so it does not increase added value.","C":"Using more nylon raises bought-in costs while the price stays at $38, which reduces rather than increases added value.","D":"A larger site adds fixed costs without changing the price or the bought-in cost of each rope."}}},{"id":"P1_U1_MCQ_1182","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1182","question":"Barrowcourt's three sectors produced output worth $340 million in total. Farming contributed $51 million and manufacturing $119 million. What was the value of tertiary sector output?","options":{"A":"$119 million","B":"$51 million","C":"$221 million","D":"$170 million"},"correctOption":"D","correctAnswer":"$170 million","questionType":"MCQ","explanation":{"correct_reason":"Tertiary output is $340 million minus $51 million minus $119 million, which leaves $170 million.","distractor_reasons":{"A":"$119 million is manufacturing output, which belongs to the secondary sector.","B":"$51 million is farming output, which belongs to the primary sector.","C":"$221 million adds primary and secondary output instead of subtracting them from the total.","D":"Tertiary output is $340 million minus $51 million minus $119 million, which leaves $170 million."}}},{"id":"P1_U1_MCQ_1183","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1183","question":"Yarrowfield Farm sells 2,400 boxes of vegetables at $46 a box each year and also runs guided tours, which bring in a further $12,400. What is the farm's total annual revenue?","options":{"A":"$110,400","B":"$98,000","C":"$122,800","D":"$134,400"},"correctOption":"C","correctAnswer":"$122,800","questionType":"MCQ","explanation":{"correct_reason":"Total revenue is 2,400 multiplied by $46, giving $110,400 from boxes, plus $12,400 from tours, which equals $122,800.","distractor_reasons":{"A":"$110,400 is only the vegetable box revenue and excludes the farm tour income.","B":"$98,000 subtracts the tour income instead of adding it to the box sales.","C":"Total revenue is 2,400 multiplied by $46, giving $110,400 from boxes, plus $12,400 from tours, which equals $122,800.","D":"$134,400 adds the tour income twice, overstating total revenue."}}},{"id":"P1_U1_MCQ_1184","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1184","question":"The water authority in Kenya is owned by the government, reports to a minister and must supply water at a price set by the regulator. Which type of organisation is this?","options":{"A":"A public limited company","B":"A public corporation","C":"A workers' co-operative","D":"A partnership"},"correctOption":"B","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Government ownership, ministerial accountability and a regulated price are features of a public corporation.","distractor_reasons":{"A":"A public limited company is owned by private shareholders who expect a return, not by the government.","B":"Government ownership, ministerial accountability and a regulated price are features of a public corporation.","C":"A co-operative is owned by its members, not by a government minister.","D":"A partnership has a small number of owners sharing profit, not state ownership and ministerial control."}}},{"id":"P1_U1_MCQ_1185","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1185","question":"A hotel chain asks its laundry supplier to accept payment after 90 days instead of 30 days. Which stakeholder bears the immediate cost of this change?","options":{"A":"The hotel's guests","B":"The laundry supplier","C":"The hotel's shareholders","D":"The local council"},"correctOption":"B","correctAnswer":"The laundry supplier","questionType":"MCQ","explanation":{"correct_reason":"Waiting 90 days instead of 30 for payment ties up the supplier's cash for two extra months, so the supplier bears the cost.","distractor_reasons":{"A":"Hotel guests pay for rooms and are not affected by the hotel's payment terms with a supplier.","B":"Waiting 90 days instead of 30 for payment ties up the supplier's cash for two extra months, so the supplier bears the cost.","C":"Shareholders gain from the hotel holding cash longer, so they do not bear the immediate cost.","D":"The local council is not a party to these commercial payment terms."}}},{"id":"P1_U1_MCQ_1186","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1186","question":"Barrowden Herb Farm grows rosemary and thyme on eight hectares of rented land, uses two second-hand tractors and employs five pickers. Which factor of production is represented by the eight hectares of land?","options":{"A":"Land","B":"Capital","C":"Labour","D":"Enterprise"},"correctOption":"A","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"The eight hectares are a natural resource used in growing herbs, which makes them land rather than capital or labour.","distractor_reasons":{"A":"The eight hectares are a natural resource used in growing herbs, which makes them land rather than capital or labour.","B":"Capital refers to man-made aids such as the two tractors, not to the soil itself.","C":"Labour is the work done by the five pickers, not the hectares they cultivate.","D":"Enterprise is the owner's risk-taking and decision-making, not the farmland."}}},{"id":"P1_U1_MCQ_1187","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1187","question":"In Vietnam, 62% of workers are employed in farming, 14% in manufacturing and 24% in services. Which conclusion about Vietnam is best supported by these figures?","options":{"A":"It is a developed country with a large tertiary sector","B":"Its secondary sector is larger than its primary sector","C":"Most of its workers are employed by the government","D":"It is likely to be a developing country with a large primary sector"},"correctOption":"D","correctAnswer":"It is likely to be a developing country with a large primary sector","questionType":"MCQ","explanation":{"correct_reason":"With 62% of workers in farming, Vietnam has a large primary sector of the kind typical of a developing economy.","distractor_reasons":{"A":"A developed economy usually has most workers in services, not 62% in farming.","B":"Manufacturing employs 14%, which is far smaller than the 62% employed in farming.","C":"The stem gives no information about public sector employment, so this cannot be concluded.","D":"With 62% of workers in farming, Vietnam has a large primary sector of the kind typical of a developing economy."}}},{"id":"P1_U1_MCQ_1188","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1188","question":"Zeals Ceramics was started by two designers who spotted demand for handmade tiles, rented a workshop and now employ 18 people. Which benefit of enterprise to an economy does this best show?","options":{"A":"It reduces competition between existing firms","B":"It removes the need for government spending","C":"It creates new businesses and jobs","D":"It guarantees profits for investors"},"correctOption":"C","correctAnswer":"It creates new businesses and jobs","questionType":"MCQ","explanation":{"correct_reason":"Two designers spotted a market, started a firm and now employ 18 people, showing that enterprise creates new businesses and jobs.","distractor_reasons":{"A":"New entrants usually increase competition in a market rather than reduce it.","B":"Enterprise does not remove the need for government spending on public services.","C":"Two designers spotted a market, started a firm and now employ 18 people, showing that enterprise creates new businesses and jobs.","D":"Starting a business involves risk, so profits are never guaranteed to investors."}}},{"id":"P1_U1_MCQ_1189","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1189","question":"A private limited company wants to raise $900,000 to build a warehouse, has no retained profit available and its shareholders do not want the firm to take on more debt. Which source of finance is most suitable?","options":{"A":"A bank overdraft","B":"Trade credit from building suppliers","C":"Issuing more ordinary shares to new investors","D":"Retained profit from previous years"},"correctOption":"C","correctAnswer":"Issuing more ordinary shares to new investors","questionType":"MCQ","explanation":{"correct_reason":"Selling additional shares brings in capital without borrowing, which suits the shareholders' wish to avoid more debt.","distractor_reasons":{"A":"An overdraft is short-term borrowing and would add to the debt the shareholders want to avoid.","B":"Trade credit only delays payment for materials and cannot fund a $900,000 building project.","C":"Selling additional shares brings in capital without borrowing, which suits the shareholders' wish to avoid more debt.","D":"The stem gives no indication that $900,000 of retained profit is available inside the company."}}},{"id":"P1_U1_MCQ_1190","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1190","question":"A bakery reduces the weight of each loaf by 10% but keeps the price unchanged in order to protect its profit. Which stakeholders are most likely to feel disadvantaged by this decision?","options":{"A":"Shareholders","B":"Customers","C":"The tax authority","D":"The bakery's bank"},"correctOption":"B","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Customers pay the same price for 10% less bread, so they receive less value and are the disadvantaged stakeholder group.","distractor_reasons":{"A":"Keeping the price while cutting ingredients protects profit, which benefits shareholders.","B":"Customers pay the same price for 10% less bread, so they receive less value and are the disadvantaged stakeholder group.","C":"The tax authority receives tax based on profit, which this change may support rather than harm.","D":"The bakery's bank is concerned with loan repayments, not with the weight of loaves."}}},{"id":"P1_U1_MCQ_1191","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1191","question":"Torcross Dairy has 8 workers who fill 560 bottles an hour. After introducing a conveyor line with each worker doing one task, the same team fills 720 bottles an hour. What is the percentage increase in output per hour?","options":{"A":"28.6%","B":"22.2%","C":"160%","D":"77.8%"},"correctOption":"A","correctAnswer":"28.6%","questionType":"MCQ","explanation":{"correct_reason":"Output rises from 560 to 720 bottles an hour, a gain of 160, and 160 divided by the original 560 gives 28.6%.","distractor_reasons":{"A":"Output rises from 560 to 720 bottles an hour, a gain of 160, and 160 divided by the original 560 gives 28.6%.","B":"22.2% divides the 160-bottle gain by the new output of 720 instead of the original 560.","C":"160 is the absolute increase in bottles per hour, not a percentage increase.","D":"77.8% is the old output as a share of the new output, not the rate of increase."}}},{"id":"P1_U1_MCQ_1192","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1192","question":"Ellesmere Marina Services has opened a chandlery, a cafe and a boat-repair yard as local incomes rose and more people took up sailing holidays. Which explanation for tertiary sector growth does this illustrate?","options":{"A":"Falling incomes force families to buy more services","B":"Machinery has replaced service workers","C":"The primary sector is expanding rapidly","D":"Rising incomes increase spending on leisure services"},"correctOption":"D","correctAnswer":"Rising incomes increase spending on leisure services","questionType":"MCQ","explanation":{"correct_reason":"Higher incomes allowed households to spend more on sailing holidays and marina services, which is a demand-side cause of tertiary growth.","distractor_reasons":{"A":"The stem says incomes rose, and falling incomes would reduce spending on leisure services.","B":"Machinery replacing workers explains job losses in farming or manufacturing, not growth in marina services.","C":"The new chandlery, cafe and repair yard are service activities, not primary extraction.","D":"Higher incomes allowed households to spend more on sailing holidays and marina services, which is a demand-side cause of tertiary growth."}}},{"id":"P1_U1_MCQ_1193","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1193","question":"Pendeen Boatyard builds small wooden dinghies for sailing schools. Last year it completed 1,200 dinghies and made a total profit of $18,600. What was its average profit per dinghy built?","options":{"A":"$155","B":"$1.55","C":"$18.60","D":"$15.50"},"correctOption":"D","correctAnswer":"$15.50","questionType":"MCQ","explanation":{"correct_reason":"Average profit per dinghy is $18,600 divided by 1,200, which equals $15.50.","distractor_reasons":{"A":"155 is ten times too large, because the correct division gives 15.5.","B":"1.55 misplaces the decimal point by one place, making the answer ten times too small.","C":"18.60 divides the profit by 1,000 rather than by the 1,200 dinghies built.","D":"Average profit per dinghy is $18,600 divided by 1,200, which equals $15.50."}}},{"id":"P1_U1_MCQ_1194","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1194","question":"A customer is injured by a partner's employee at a farm supply partnership, and the compensation awarded by the court is greater than the firm's entire bank balance. How are the partners affected?","options":{"A":"Their liability is limited to the capital they invested","B":"Only the employee who caused the injury is liable","C":"They may have to use personal assets because their liability is unlimited","D":"The customer must insure against the loss"},"correctOption":"C","correctAnswer":"They may have to use personal assets because their liability is unlimited","questionType":"MCQ","explanation":{"correct_reason":"Partners in an ordinary partnership have unlimited liability, so they can be required to sell personal assets to pay the compensation.","distractor_reasons":{"A":"Limited liability applies to shareholders in companies, not to ordinary partners in a partnership.","B":"The business as a whole is liable for its employee's actions, and the partners must meet that liability.","C":"Partners in an ordinary partnership have unlimited liability, so they can be required to sell personal assets to pay the compensation.","D":"The injured customer can claim compensation from the business, and the partners carry the liability."}}},{"id":"P1_U1_MCQ_1195","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1195","question":"A family-owned furniture maker rejects a buyout offer from a larger rival because the family wants to keep control, even though the offer would double the family's wealth. Which objective is the family prioritising?","options":{"A":"Maximising profit","B":"Maintaining ownership and control","C":"Increasing market share","D":"Survival"},"correctOption":"B","correctAnswer":"Maintaining ownership and control","questionType":"MCQ","explanation":{"correct_reason":"The family rejects a profitable offer in order to keep ownership and control, showing that control can be an objective alongside profit.","distractor_reasons":{"A":"Rejecting an offer that would double their wealth is not profit maximisation.","B":"The family rejects a profitable offer in order to keep ownership and control, showing that control can be an objective alongside profit.","C":"The stem says nothing about the firm's share of its market.","D":"The business is not described as struggling to survive; it is choosing control over a buyout."}}},{"id":"P1_U1_MCQ_1196","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1196","question":"Wildebrook Toys buys wooden blanks for $6 each, paints and assembles them in its workshop and sells the finished toys for $19. The owner says the business exists to create value rather than simply to sell wood. What does this illustrate?","options":{"A":"Production transforms inputs into output with greater value to customers","B":"The business is a charity providing free toys to children","C":"Retailers decide the price of the finished toy","D":"Wood is a consumer want rather than a raw material"},"correctOption":"A","correctAnswer":"Production transforms inputs into output with greater value to customers","questionType":"MCQ","explanation":{"correct_reason":"Wildebrook turns $6 blanks into toys worth $19 by painting and assembling them, so production creates added value for customers.","distractor_reasons":{"A":"Wildebrook turns $6 blanks into toys worth $19 by painting and assembling them, so production creates added value for customers.","B":"The business sells its toys for $19, so it is a commercial producer rather than a charity giving toys away.","C":"The stem states the finished toy sells for $19, and the manufacturer is the business that adds the value.","D":"Wood is a raw material input, not a consumer want, so this does not explain the transformation."}}},{"id":"P1_U1_MCQ_1197","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1197","question":"Fenwick Haulage employed 480 drivers in 2020 and 552 drivers in 2026. What was the percentage increase in the number of drivers over this period?","options":{"A":"15%","B":"13%","C":"72%","D":"115%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The number of drivers rose by 552 minus 480, giving 72, and 72 divided by the original 480 gives 15%.","distractor_reasons":{"A":"The number of drivers rose by 552 minus 480, giving 72, and 72 divided by the original 480 gives 15%.","B":"13% divides the 72 extra drivers by the 2026 figure of 552 instead of the 2020 figure.","C":"72 is the absolute increase in drivers, not the percentage increase.","D":"115% would be the 2026 total expressed as a percentage of the 2020 total, not the increase."}}},{"id":"P1_U1_MCQ_1198","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1198","question":"Culworth Foods earned revenue of $96,000 from selling 1,600 cases of soup, but its profit fell because the cost of tomatoes rose sharply. Which statement best explains the fall in profit?","options":{"A":"Revenue fell, so profit had to fall as well","B":"The number of cases sold must have fallen","C":"Profit can fall only when selling prices are cut","D":"Revenue stayed the same while costs rose, so the profit margin narrowed"},"correctOption":"D","correctAnswer":"Revenue stayed the same while costs rose, so the profit margin narrowed","questionType":"MCQ","explanation":{"correct_reason":"The revenue of $96,000 did not change, so higher tomato costs reduced the profit left from each case of soup.","distractor_reasons":{"A":"The stem states revenue was $96,000 and gives no indication that it fell.","B":"The stem says 1,600 cases were sold, so the explanation must lie in costs rather than volume.","C":"Rising costs cut profit even when prices are unchanged, so this statement is false.","D":"The revenue of $96,000 did not change, so higher tomato costs reduced the profit left from each case of soup."}}},{"id":"P1_U1_MCQ_1199","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1199","question":"Takings at Hazel's Florists are $148,000 for the year. Materials cost $54,000, rent is $26,500 and other costs such as insurance and fuel are $17,000. What is the shop's profit?","options":{"A":"$97,500","B":"$68,000","C":"$50,500","D":"$121,000"},"correctOption":"C","correctAnswer":"$50,500","questionType":"MCQ","explanation":{"correct_reason":"Total costs are $54,000 plus $26,500 plus $17,000, giving $97,500, so profit is $148,000 minus $97,500, which is $50,500.","distractor_reasons":{"A":"$97,500 is total costs, not the profit left after paying them.","B":"$68,000 subtracts only materials and other costs and ignores the $26,500 of rent.","C":"Total costs are $54,000 plus $26,500 plus $17,000, giving $97,500, so profit is $148,000 minus $97,500, which is $50,500.","D":"$121,000 subtracts only the rent from takings and ignores the other costs."}}},{"id":"P1_U1_MCQ_1200","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1200","question":"A retailer reports a profit of $60,000 but cannot pay its suppliers on time because $95,000 is owed by customers. What does this show about business objectives?","options":{"A":"A profitable business can never fail","B":"Profitability does not guarantee that a business has enough cash","C":"Profit and cash flow are the same thing","D":"Only loss-making firms are owed money by customers"},"correctOption":"B","correctAnswer":"Profitability does not guarantee that a business has enough cash","questionType":"MCQ","explanation":{"correct_reason":"Profit of $60,000 can coexist with a cash shortage when $95,000 is tied up in unpaid customer invoices, so profit and cash differ.","distractor_reasons":{"A":"Profitable firms can fail if they cannot pay debts when they fall due.","B":"Profit of $60,000 can coexist with a cash shortage when $95,000 is tied up in unpaid customer invoices, so profit and cash differ.","C":"Profit records revenue and costs, while cash flow records money actually received and paid.","D":"Credit customers owe money to profitable firms too, so this statement is false."}}},{"id":"P1_U1_MCQ_1201","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1201","question":"Brightloom Candles buys wax, wicks and glass jars for $95,000 and spends a further $15,000 on packaging. It sells all of its candles for $180,000. What is the value added by Brightloom Candles?","options":{"A":"$70,000","B":"$85,000","C":"$165,000","D":"$180,000"},"correctOption":"A","correctAnswer":"$70,000","questionType":"MCQ","explanation":{"correct_reason":"Value added equals sales revenue of $180,000 minus the bought-in materials and packaging of $95,000 plus $15,000, which comes to $70,000.","distractor_reasons":{"A":"Value added equals sales revenue of $180,000 minus the bought-in materials and packaging of $95,000 plus $15,000, which comes to $70,000.","B":"$85,000 subtracts only the $95,000 materials cost from $180,000 and ignores the separate $15,000 packaging cost.","C":"$165,000 subtracts only the $15,000 packaging cost and forgets the $95,000 spent on wax, wicks and jars.","D":"$180,000 is simply the sales revenue and makes no deduction for any bought-in costs."}}},{"id":"P1_U1_MCQ_1202","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1202","question":"Silverdale Quarry, which extracts granite, employs 240 workers. The total local workforce is 1,200 people. What percentage of the local workforce is employed in the primary sector at Silverdale Quarry?","options":{"A":"6%","B":"20%","C":"24%","D":"80%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The primary sector share is 240 quarry workers divided by the 1,200 people in the local workforce, multiplied by 100, which equals 20%.","distractor_reasons":{"A":"6% would mean only 72 workers, but Silverdale Quarry actually employs 240 people out of 1,200.","B":"The primary sector share is 240 quarry workers divided by the 1,200 people in the local workforce, multiplied by 100, which equals 20%.","C":"24% confuses the 240 workers with a percentage and ignores the 1,200 total workforce.","D":"80% is the share of the workforce not employed by the quarry, not the primary sector share."}}},{"id":"P1_U1_MCQ_1203","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1203","question":"Solent Cartons, a packaging firm, sold 48,000 boxes last year. Total sales in the box market were 240,000 boxes. What was Solent Cartons' market share?","options":{"A":"5%","B":"12%","C":"20%","D":"48%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share is Solent's 48,000 boxes divided by the 240,000 boxes sold in the whole market, multiplied by 100, which gives 20%.","distractor_reasons":{"A":"5% equals 12,000 boxes, which is only one quarter of Solent's actual sales of 48,000.","B":"12% comes from dividing 48,000 by 400,000 rather than by the 240,000 market total.","C":"Market share is Solent's 48,000 boxes divided by the 240,000 boxes sold in the whole market, multiplied by 100, which gives 20%.","D":"48% repeats the 48,000 figure as a percentage and does not divide by total market sales."}}},{"id":"P1_U1_MCQ_1204","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1204","question":"Hollowbrook Partners is a two-person partnership. Last year it made a profit of $84,000, shared between the partners in the ratio 3:4. How much does the partner with the larger share receive?","options":{"A":"$36,000","B":"$42,000","C":"$52,500","D":"$48,000"},"correctOption":"D","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"The larger share is 4 of the 7 total parts, so the partner receives 4/7 of $84,000, which equals $48,000.","distractor_reasons":{"A":"$36,000 is the smaller partner's 3/7 share of the $84,000 profit, not the larger share.","B":"$42,000 would be an equal half share of $84,000, but the agreed ratio is 3:4.","C":"$52,500 comes from dividing $84,000 by 8 and taking five parts, which is not the 3:4 ratio in the stem.","D":"The larger share is 4 of the 7 total parts, so the partner receives 4/7 of $84,000, which equals $48,000."}}},{"id":"P1_U1_MCQ_1205","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1205","question":"Halcyon Care Homes is owned by private shareholders, while residents' families pay the fees. Which statement best explains why the owners and the families may have conflicting objectives?","options":{"A":"Owners want higher fees and profits, while families want lower fees and better care.","B":"Both groups want the home to close so that its costs fall.","C":"Families want higher dividends, while owners want lower fees.","D":"Owners want to cut all staff, and families want fewer nurses."},"correctOption":"A","correctAnswer":"Owners want higher fees and profits, while families want lower fees and better care.","questionType":"MCQ","explanation":{"correct_reason":"The owners of Halcyon Care Homes pursue profit through higher fees, whereas families want affordable fees and good quality care, so their aims pull in opposite directions.","distractor_reasons":{"A":"The owners of Halcyon Care Homes pursue profit through higher fees, whereas families want affordable fees and good quality care, so their aims pull in opposite directions.","B":"Neither group wants the care home to close, because families need the service and owners need the fees.","C":"This reverses the roles, since families do not receive dividends and owners would not campaign for lower fees.","D":"Owners may cut costs, but families want more nursing care rather than fewer nurses."}}},{"id":"P1_U1_MCQ_1206","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1206","question":"Sable & Finch Cafe divides work so that one worker takes orders, one prepares food and one clears tables. Which is the main benefit of this division of labour?","options":{"A":"Lower rent for the cafe premises","B":"Faster service because each worker repeats one task","C":"Every worker learns all three jobs equally","D":"Fewer customers are needed to fill the cafe"},"correctOption":"B","correctAnswer":"Faster service because each worker repeats one task","questionType":"MCQ","explanation":{"correct_reason":"Repeating one task lets each Sable & Finch worker become quicker and more skilled at it, so orders are served faster than if everyone did every job.","distractor_reasons":{"A":"Rent depends on the premises, not on how the cafe splits tasks among its three workers.","B":"Repeating one task lets each Sable & Finch worker become quicker and more skilled at it, so orders are served faster than if everyone did every job.","C":"Division of labour does the opposite, because each worker specialises in only one job rather than learning all three.","D":"Specialisation aims to serve more customers in the same time, not to reduce the number of customers."}}},{"id":"P1_U1_MCQ_1207","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1207","question":"Hearthstone Builders constructs houses and office blocks. Which government policy would most directly increase employment in the secondary sector in which this construction firm operates?","options":{"A":"Subsidies for deep-sea fishing fleets","B":"More funding for primary schools","C":"Grants for firms buying construction machinery and factories","D":"Training courses for hotel receptionists"},"correctOption":"C","correctAnswer":"Grants for firms buying construction machinery and factories","questionType":"MCQ","explanation":{"correct_reason":"Grants for machinery and factories support secondary producers such as Hearthstone Builders, since construction is a secondary activity that turns materials into buildings.","distractor_reasons":{"A":"Fishing is a primary activity, so subsidies for fleets would raise primary rather than secondary employment.","B":"Funding schools expands a tertiary service and does not directly create construction jobs.","C":"Grants for machinery and factories support secondary producers such as Hearthstone Builders, since construction is a secondary activity that turns materials into buildings.","D":"Hotel reception work is tertiary, so this training would not support secondary sector employment."}}},{"id":"P1_U1_MCQ_1208","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1208","question":"Ridgeway Poultry wants to compare its size with a rival that uses more machinery and fewer staff. Which measure would give the fairest comparison of the two businesses?","options":{"A":"The number of shareholders in each firm","B":"The age of each business","C":"The location of the poultry farms","D":"The value of annual sales revenue"},"correctOption":"D","correctAnswer":"The value of annual sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Sales revenue reflects the scale of Ridgeway Poultry and its rival even when they use different amounts of labour and machinery, so it is the fairest single measure.","distractor_reasons":{"A":"Shareholders do not show the scale of operations, and a sole trader could be large with no shareholders.","B":"Age says nothing about current size, because an old firm can be small and a new one large.","C":"Location describes where the farms are, not how much output or revenue each business generates.","D":"Sales revenue reflects the scale of Ridgeway Poultry and its rival even when they use different amounts of labour and machinery, so it is the fairest single measure."}}},{"id":"P1_U1_MCQ_1209","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1209","question":"Ashgrove Housing Co-op is owned and controlled by its tenant members, each of whom has one vote at meetings. Which type of business organisation is this?","options":{"A":"A co-operative","B":"A partnership","C":"A private limited company","D":"A public limited company"},"correctOption":"A","correctAnswer":"A co-operative","questionType":"MCQ","explanation":{"correct_reason":"A co-operative is owned and democratically controlled by its members, which matches Ashgrove Housing Co-op's tenant members holding one vote each.","distractor_reasons":{"A":"A co-operative is owned and democratically controlled by its members, which matches Ashgrove Housing Co-op's tenant members holding one vote each.","B":"A partnership is owned by partners who share profits, not by tenant members with one vote each.","C":"A private limited company is owned by shareholders whose votes depend on the size of their shareholdings.","D":"A public limited company trades its shares on a stock exchange and is not owned by tenant members."}}},{"id":"P1_U1_MCQ_1210","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1210","question":"Beacon Trust Hospital, which treats public patients in its clinics, reports long waiting lists for operations. Which stakeholder group is most directly affected by these delays?","options":{"A":"Shareholders who receive dividends","B":"Patients waiting for treatment","C":"Suppliers of bandages and gloves","D":"The local tax office"},"correctOption":"B","correctAnswer":"Patients waiting for treatment","questionType":"MCQ","explanation":{"correct_reason":"Patients are the people waiting for operations at Beacon Trust Hospital, so delays in treatment affect their health and daily lives most directly.","distractor_reasons":{"A":"The hospital is a trust serving patients, and waiting lists do not directly reduce shareholders' dividends here.","B":"Patients are the people waiting for operations at Beacon Trust Hospital, so delays in treatment affect their health and daily lives most directly.","C":"Suppliers still sell bandages and gloves, and slower operations may only change the timing of their orders.","D":"The tax office is concerned with tax collection, not with how long patients wait for surgery."}}},{"id":"P1_U1_MCQ_1211","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1211","question":"Copper Kettle Bakes received $96,000 from sales last year. Its total costs, including ingredients, wages and rent, came to $74,500. What profit did the bakery make?","options":{"A":"$74,500","B":"$96,000","C":"$21,500","D":"$170,500"},"correctOption":"C","correctAnswer":"$21,500","questionType":"MCQ","explanation":{"correct_reason":"Profit is sales revenue of $96,000 minus total costs of $74,500, which leaves Copper Kettle Bakes with a profit of $21,500 for the year.","distractor_reasons":{"A":"$74,500 is the total cost figure, not the profit, because costs must be subtracted from revenue.","B":"$96,000 is the sales revenue before any costs are deducted, so it is not profit.","C":"Profit is sales revenue of $96,000 minus total costs of $74,500, which leaves Copper Kettle Bakes with a profit of $21,500 for the year.","D":"$170,500 adds revenue and costs together instead of subtracting costs from revenue."}}},{"id":"P1_U1_MCQ_1212","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1212","question":"Marsh Harrier Fishing employed 480 workers in 2024 and 360 workers in 2025. What was the percentage fall in employment at this fishing business over the year?","options":{"A":"20%","B":"30%","C":"33.3%","D":"25%"},"correctOption":"D","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Employment fell by 480 minus 360, which is 120 workers, and 120 divided by the original 480 gives a fall of 25%.","distractor_reasons":{"A":"20% would be a fall of 96 workers, but the actual reduction from 480 to 360 is 120.","B":"30% would be a fall of 144 workers, which is larger than the 120 jobs actually lost.","C":"33.3% comes from dividing 120 by the new figure of 360 rather than by the original 480.","D":"Employment fell by 480 minus 360, which is 120 workers, and 120 divided by the original 480 gives a fall of 25%."}}},{"id":"P1_U1_MCQ_1213","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1213","question":"Blue Harbour Ferries earned revenue of $250,000 in 2024 and $290,000 in 2025. What was the percentage increase in its revenue over that trading year?","options":{"A":"16%","B":"14.5%","C":"40%","D":"29%"},"correctOption":"A","correctAnswer":"16%","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $290,000 minus $250,000, which is $40,000, and $40,000 divided by the original $250,000 gives a 16% increase.","distractor_reasons":{"A":"Revenue rose by $290,000 minus $250,000, which is $40,000, and $40,000 divided by the original $250,000 gives a 16% increase.","B":"14.5% would be an increase of about $36,250, not the actual $40,000 rise in revenue.","C":"40% confuses the $40,000 cash increase with a percentage of the original revenue.","D":"29% misreads the two revenue figures and does not equal $40,000 divided by the original $250,000."}}},{"id":"P1_U1_MCQ_1214","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1214","question":"Marram Construction Ltd has issued 5,000 ordinary shares. The directors declare a dividend of $0.60 per share. What total dividend is paid to shareholders for the year?","options":{"A":"$600","B":"$3,000","C":"$5,000","D":"$8,333"},"correctOption":"B","correctAnswer":"$3,000","questionType":"MCQ","explanation":{"correct_reason":"The total dividend is 5,000 shares multiplied by $0.60 per share, which equals $3,000 paid to Marram Construction's shareholders.","distractor_reasons":{"A":"$600 would be the dividend on only 1,000 shares, not on all 5,000 shares issued.","B":"The total dividend is 5,000 shares multiplied by $0.60 per share, which equals $3,000 paid to Marram Construction's shareholders.","C":"$5,000 repeats the number of shares as a dollar amount and ignores the $0.60 rate.","D":"$8,333 divides 5,000 by $0.60 instead of multiplying the shares by the dividend rate."}}},{"id":"P1_U1_MCQ_1215","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1215","question":"Pelham Academy, a private school, set a profit target of $120,000 for the year but actually made $138,000. By what percentage did profit exceed the target?","options":{"A":"12%","B":"13%","C":"15%","D":"18%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit was $138,000 against a target of $120,000, an excess of $18,000, and $18,000 divided by $120,000 equals 15% above target.","distractor_reasons":{"A":"12% would be an excess of $14,400, not the actual $18,000 above the $120,000 target.","B":"13% would mean profit of about $135,600, below the $138,000 actually achieved.","C":"Profit was $138,000 against a target of $120,000, an excess of $18,000, and $18,000 divided by $120,000 equals 15% above target.","D":"18% repeats the $18,000 cash excess as if it were already a percentage of the target."}}},{"id":"P1_U1_MCQ_1216","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1216","question":"Tallow & Wick Soapery makes handmade soap from bought-in oils and sells it in plain wrappers. Which action would most increase the value added by this business?","options":{"A":"Buying cheaper oils from a new supplier","B":"Selling the soap without any packaging","C":"Employing more staff at the same pay","D":"Branding the soap and packaging it as a gift set"},"correctOption":"D","correctAnswer":"Branding the soap and packaging it as a gift set","questionType":"MCQ","explanation":{"correct_reason":"Branding and gift packaging raise the price customers pay without adding much bought-in cost, so the gap between Tallow & Wick's revenue and material costs grows.","distractor_reasons":{"A":"Cheaper oils lower bought-in costs, but they may also lower quality, and value added depends on the price the soap fetches as well.","B":"Selling unpackaged soap is likely to lower the price customers pay, which reduces rather than increases value added.","C":"Extra staff raise wage costs, and unless output or price rises more, the value added by Tallow & Wick need not increase.","D":"Branding and gift packaging raise the price customers pay without adding much bought-in cost, so the gap between Tallow & Wick's revenue and material costs grows."}}},{"id":"P1_U1_MCQ_1217","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1217","question":"Employment in services has grown steadily in many countries, including at Lumen Health Clinic. Which factor best explains this long-term growth in the tertiary sector?","options":{"A":"Rising incomes lead households to spend more on services such as healthcare","B":"Consumers have stopped buying manufactured goods","C":"Primary production now needs far more workers","D":"Governments have banned factory employment"},"correctOption":"A","correctAnswer":"Rising incomes lead households to spend more on services such as healthcare","questionType":"MCQ","explanation":{"correct_reason":"As incomes rise, households spend a larger share on services, so demand for clinics such as Lumen Health Clinic grows and creates tertiary jobs.","distractor_reasons":{"A":"As incomes rise, households spend a larger share on services, so demand for clinics such as Lumen Health Clinic grows and creates tertiary jobs.","B":"People still buy manufactured goods, so this does not explain the shift towards service employment.","C":"Primary production generally uses fewer workers because of machinery, which reduces rather than raises farm jobs.","D":"Factory employment has not been banned; manufacturing jobs have declined mainly through mechanisation and imports."}}},{"id":"P1_U1_MCQ_1218","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1218","question":"Fable Toys expanded rapidly and now employs 900 staff in one factory. Managers report slow communication and rising unit costs. What does this situation illustrate?","options":{"A":"Economies of scale","B":"Diseconomies of scale","C":"Division of labour","D":"External growth"},"correctOption":"B","correctAnswer":"Diseconomies of scale","questionType":"MCQ","explanation":{"correct_reason":"Rising unit costs and poor communication after rapid expansion are signs of diseconomies of scale, where Fable Toys has grown beyond its efficient size.","distractor_reasons":{"A":"Economies of scale would lower unit costs as output rises, but Fable Toys reports the opposite.","B":"Rising unit costs and poor communication after rapid expansion are signs of diseconomies of scale, where Fable Toys has grown beyond its efficient size.","C":"Division of labour splits tasks, which is not the same as the management problems caused by growing too large.","D":"External growth means merging with or taking over another firm, and the stem only describes internal expansion."}}},{"id":"P1_U1_MCQ_1219","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1219","question":"Thistle & Sparrow Design is a partnership between an illustrator and a web developer. Which is the main advantage of this structure compared with a sole trader?","options":{"A":"Both partners automatically have limited liability","B":"Shares can be sold on a stock exchange","C":"Workload and complementary skills are shared","D":"Profits are completely free of tax"},"correctOption":"C","correctAnswer":"Workload and complementary skills are shared","questionType":"MCQ","explanation":{"correct_reason":"A partnership lets the two owners of Thistle & Sparrow share the workload and combine illustration and web skills, which a single sole trader would find harder.","distractor_reasons":{"A":"Partners in an ordinary partnership have unlimited liability, so limited liability is not automatic.","B":"Only a public limited company can offer shares for sale on a stock exchange.","C":"A partnership lets the two owners of Thistle & Sparrow share the workload and combine illustration and web skills, which a single sole trader would find harder.","D":"Partners still pay tax on their share of profits, so profits are not free of tax."}}},{"id":"P1_U1_MCQ_1220","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1220","question":"Loxley Water wants to raise water charges by 12% to repair pipes, but customers say bills are already too high. Which two stakeholder groups are in conflict here?","options":{"A":"Customers and employees","B":"The government and suppliers","C":"Employees and managers","D":"Customers and shareholders"},"correctOption":"D","correctAnswer":"Customers and shareholders","questionType":"MCQ","explanation":{"correct_reason":"Customers want affordable bills, while the shareholders of Loxley Water want the higher revenue and profit that a 12% charge rise would bring, so their objectives conflict.","distractor_reasons":{"A":"Employees are not the group directly opposing the charge rise in this scenario, since their concern is pay and jobs.","B":"The stem does not describe a disagreement between the government and pipe suppliers.","C":"Managers are implementing the rise, and employees are not shown as an opposing stakeholder group here.","D":"Customers want affordable bills, while the shareholders of Loxley Water want the higher revenue and profit that a 12% charge rise would bring, so their objectives conflict."}}},{"id":"P1_U1_MCQ_1221","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1221","question":"Meridian Lawn Care cuts grass and trims hedges for local households. Why is a customer's purchase of this service best described as a want rather than a need?","options":{"A":"The garden could be maintained by the owner, so the service is not essential for survival","B":"Without a lawn service people cannot survive","C":"The business uses scarce resources","D":"Services are always more valuable than goods"},"correctOption":"A","correctAnswer":"The garden could be maintained by the owner, so the service is not essential for survival","questionType":"MCQ","explanation":{"correct_reason":"A tidy garden is desirable but not essential for life, and the householder could cut the grass personally, so Meridian Lawn Care's service satisfies a want.","distractor_reasons":{"A":"A tidy garden is desirable but not essential for life, and the householder could cut the grass personally, so Meridian Lawn Care's service satisfies a want.","B":"No household needs a lawn-care service in order to survive, which is the opposite of the statement.","C":"Scarcity of resources explains why the service has a price, not why the purchase is a want.","D":"The value of services and goods varies by situation, so it is wrong to say services are always more valuable."}}},{"id":"P1_U1_MCQ_1222","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1222","question":"Wexford Logistics is part of a national workforce of 20 million people, of whom 3 million work in the primary sector and 5 million in the secondary sector. What percentage of the workforce works in the tertiary sector?","options":{"A":"40%","B":"60%","C":"15%","D":"85%"},"correctOption":"B","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"The tertiary sector employs 20 million minus 3 million and 5 million, which is 12 million people, and 12 million divided by 20 million equals 60%.","distractor_reasons":{"A":"40% is the combined primary and secondary share of 8 million workers, not the tertiary share.","B":"The tertiary sector employs 20 million minus 3 million and 5 million, which is 12 million people, and 12 million divided by 20 million equals 60%.","C":"15% equals the 3 million primary workers as a share of 20 million, not the service sector share.","D":"85% would be 17 million workers, leaving only 3 million rather than the correct 12 million in services."}}},{"id":"P1_U1_MCQ_1223","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1223","question":"Kestrel Optics produced 12,000 lenses last year and its total costs were $84,000. What was the average cost of producing one lens at Kestrel Optics?","options":{"A":"$0.14","B":"$6.00","C":"$7.00","D":"$14.00"},"correctOption":"C","correctAnswer":"$7.00","questionType":"MCQ","explanation":{"correct_reason":"Average cost is total cost of $84,000 divided by output of 12,000 lenses, which equals $7.00 per lens for Kestrel Optics.","distractor_reasons":{"A":"$0.14 comes from dividing 12,000 lenses by $84,000, which reverses the correct calculation.","B":"$6.00 would need total costs of $72,000 at an output of 12,000 lenses, not the $84,000 given.","C":"Average cost is total cost of $84,000 divided by output of 12,000 lenses, which equals $7.00 per lens for Kestrel Optics.","D":"$14.00 would be the cost per lens if only 6,000 lenses had been produced from $84,000."}}},{"id":"P1_U1_MCQ_1224","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1224","question":"Pentwyn Dairy is a sole trader business with debts of $62,000 and business assets worth $45,000. If the business fails, how much of the debt must the owner pay from personal funds?","options":{"A":"$0","B":"$45,000","C":"$62,000","D":"$17,000"},"correctOption":"D","correctAnswer":"$17,000","questionType":"MCQ","explanation":{"correct_reason":"A sole trader has unlimited liability, so the owner must cover the $62,000 debt not met by $45,000 of business assets, which leaves $17,000 from personal funds.","distractor_reasons":{"A":"$0 is wrong because a sole trader cannot limit liability to the business assets alone.","B":"$45,000 is the value of the business assets, not the shortfall the owner must find.","C":"$62,000 ignores that the $45,000 of business assets is used first, leaving only $17,000.","D":"A sole trader has unlimited liability, so the owner must cover the $62,000 debt not met by $45,000 of business assets, which leaves $17,000 from personal funds."}}},{"id":"P1_U1_MCQ_1225","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1225","question":"Thistle & Thyme Grocers had revenue of $250,000 last year and paid wages of $62,500. What percentage of revenue was spent on wages at this grocer?","options":{"A":"25%","B":"40%","C":"4%","D":"62.5%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Wages of $62,500 divided by revenue of $250,000 equals 0.25, so Thistle & Thyme spent 25% of its revenue on wages.","distractor_reasons":{"A":"Wages of $62,500 divided by revenue of $250,000 equals 0.25, so Thistle & Thyme spent 25% of its revenue on wages.","B":"40% would mean wages of $100,000, which is well above the $62,500 actually paid.","C":"4% would mean wages of only $10,000, far below the $62,500 wage bill.","D":"62.5% repeats the wage figure in thousands and does not divide it by the $250,000 revenue."}}},{"id":"P1_U1_MCQ_1226","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1226","question":"Northgate Bike Hire buys bicycles from a manufacturer and then services them, insures riders and delivers to customers' homes. How does this most clearly add value?","options":{"A":"It charges less than other hire firms","B":"It provides services that make the bikes more useful to customers","C":"It stores the bicycles in a large warehouse","D":"It buys bicycles in very large quantities"},"correctOption":"B","correctAnswer":"It provides services that make the bikes more useful to customers","questionType":"MCQ","explanation":{"correct_reason":"Servicing, insurance and home delivery make the hired bike more convenient and safer, so customers pay more than for the bare bicycle, which raises value added.","distractor_reasons":{"A":"Charging less would reduce the price and so reduce value added rather than increase it.","B":"Servicing, insurance and home delivery make the hired bike more convenient and safer, so customers pay more than for the bare bicycle, which raises value added.","C":"Warehouse storage is an internal activity that does not directly make the bike more useful to the customer.","D":"Bulk buying lowers costs, but on its own it does not create the extra customer benefit that adds value."}}},{"id":"P1_U1_MCQ_1227","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1227","question":"The economy is often divided into primary, secondary and tertiary sectors. Which row correctly matches a named business with the sector in which it mainly operates?","options":{"A":"Silverdale Quarry - tertiary sector","B":"Lumen Health Clinic - primary sector","C":"Tinderbox Media - tertiary sector","D":"Verdant Fields Dairy - secondary sector"},"correctOption":"C","correctAnswer":"Tinderbox Media - tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Tinderbox Media provides media services, and services belong to the tertiary sector, so this row is the only correct match.","distractor_reasons":{"A":"Quarrying extracts stone from the ground, which is a primary activity, not a tertiary one.","B":"A health clinic provides a service, so it belongs to the tertiary sector rather than the primary sector.","C":"Tinderbox Media provides media services, and services belong to the tertiary sector, so this row is the only correct match.","D":"A dairy farm produces milk from animals, which is primary, not secondary manufacturing."}}},{"id":"P1_U1_MCQ_1228","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1228","question":"Amberline Couriers buys a rival parcel delivery company and takes over its depots and vans. Which term best describes this method of growth for Amberline Couriers?","options":{"A":"Internal growth","B":"A partnership","C":"A franchise","D":"External growth by takeover"},"correctOption":"D","correctAnswer":"External growth by takeover","questionType":"MCQ","explanation":{"correct_reason":"Buying another business outright is a takeover, which is a form of external growth because Amberline Couriers expands by absorbing an existing firm.","distractor_reasons":{"A":"Internal growth means expanding its own operations, such as opening new depots, not buying a rival.","B":"A partnership is a form of ownership with shared profits, not a method of buying another company.","C":"A franchise lets someone trade under another firm's brand, and it does not describe buying a rival outright.","D":"Buying another business outright is a takeover, which is a form of external growth because Amberline Couriers expands by absorbing an existing firm."}}},{"id":"P1_U1_MCQ_1229","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1229","question":"Starlight Cinema Ltd has debts of $400,000 and assets of $250,000. Its shareholders have limited liability. What does limited liability mean for these shareholders in practice?","options":{"A":"They risk only the capital they invested in the company","B":"They must personally repay the $150,000 shortfall","C":"They must sell their homes to pay the debts","D":"They become personally responsible for all company debts"},"correctOption":"A","correctAnswer":"They risk only the capital they invested in the company","questionType":"MCQ","explanation":{"correct_reason":"Limited liability means the shareholders of Starlight Cinema can lose only the money they put into shares, not their personal assets, even though debts exceed assets.","distractor_reasons":{"A":"Limited liability means the shareholders of Starlight Cinema can lose only the money they put into shares, not their personal assets, even though debts exceed assets.","B":"Paying the $150,000 shortfall is exactly what limited liability prevents shareholders from having to do.","C":"Selling homes would be unlimited liability, while limited liability protects personal property from company debts.","D":"Personal responsibility for all debts describes unlimited liability, which applies to sole traders and ordinary partners."}}},{"id":"P1_U1_MCQ_1230","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1230","question":"Sandpiper Airlines cuts cabin crew pay by 8% to reduce costs. Which stakeholder group is most directly harmed by this decision at the airline in the short term?","options":{"A":"Shareholders receiving dividends","B":"Cabin crew employees","C":"Travel agents selling tickets","D":"Aircraft manufacturers"},"correctOption":"B","correctAnswer":"Cabin crew employees","questionType":"MCQ","explanation":{"correct_reason":"Cabin crew lose 8% of their pay, so employees are the group directly affected by Sandpiper Airlines' cost-cutting decision, while shareholders may gain.","distractor_reasons":{"A":"Shareholders are likely to benefit from lower costs, so they are not the group harmed by the pay cut.","B":"Cabin crew lose 8% of their pay, so employees are the group directly affected by Sandpiper Airlines' cost-cutting decision, while shareholders may gain.","C":"Travel agents earn commission on ticket sales and are not directly affected by cabin crew pay.","D":"Aircraft manufacturers sell planes and are not directly affected by the cabin crew pay cut."}}},{"id":"P1_U1_MCQ_1231","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1231","question":"Fernway Tutoring asks each tutor to teach only one subject, such as maths or chemistry. Which is the most likely benefit of this specialisation for the tutoring business?","options":{"A":"Tutors must prepare lessons for every subject","B":"Lessons become less consistent for students","C":"Tutors gain deeper expertise and teach more effectively","D":"The business can no longer advertise its services"},"correctOption":"C","correctAnswer":"Tutors gain deeper expertise and teach more effectively","questionType":"MCQ","explanation":{"correct_reason":"Focusing on one subject lets Fernway tutors build deeper expertise and prepare better lessons, which should improve the quality of each lesson.","distractor_reasons":{"A":"Specialisation reduces, rather than increases, the number of subjects each tutor must prepare.","B":"Better focused preparation is likely to make lessons more consistent, not less.","C":"Focusing on one subject lets Fernway tutors build deeper expertise and prepare better lessons, which should improve the quality of each lesson.","D":"Specialising by subject does not prevent a tutoring business from advertising its services."}}},{"id":"P1_U1_MCQ_1232","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1232","question":"Kloof Tin Works, a tin mine, cut its workforce from 640 miners in 2024 to 512 in 2025. Which is the most likely reason for this fall in primary employment?","options":{"A":"Demand for tin has risen sharply","B":"The mine has opened a new shaft","C":"More miners have been recruited","D":"Machinery has replaced some manual mining work"},"correctOption":"D","correctAnswer":"Machinery has replaced some manual mining work","questionType":"MCQ","explanation":{"correct_reason":"Mechanisation lets a mine such as Kloof Tin Works produce with fewer workers, so machinery replacing manual tasks explains the fall from 640 to 512.","distractor_reasons":{"A":"Rising demand for tin would usually support or increase mining jobs, not reduce them.","B":"A new shaft would normally require more labour, at least in the short term.","C":"Recruiting more miners would raise the workforce above 512, not cut it from 640.","D":"Mechanisation lets a mine such as Kloof Tin Works produce with fewer workers, so machinery replacing manual tasks explains the fall from 640 to 512."}}},{"id":"P1_U1_MCQ_1233","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1233","question":"Small independent shops such as Highfell Outdoor still survive in many towns alongside large retail chains. Which is the best explanation for this in retailing?","options":{"A":"They offer personal service and specialist products in niche markets","B":"They always have lower average costs than large chains","C":"Large chains cannot use modern technology","D":"Small firms are always protected by limited liability"},"correctOption":"A","correctAnswer":"They offer personal service and specialist products in niche markets","questionType":"MCQ","explanation":{"correct_reason":"Niche markets and personal service give small shops such as Highfell Outdoor a loyal group of customers that large chains may not serve as well.","distractor_reasons":{"A":"Niche markets and personal service give small shops such as Highfell Outdoor a loyal group of customers that large chains may not serve as well.","B":"Large chains usually benefit from economies of scale, so small shops rarely have lower average costs.","C":"Large chains often use more technology, such as self-checkouts and central ordering systems.","D":"Limited liability is a legal feature of incorporated firms and does not explain why small shops survive."}}},{"id":"P1_U1_MCQ_1234","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1234","question":"Halliday Software Ltd wants to become a public limited company. Which is the main benefit of making this change for the software firm's future growth?","options":{"A":"The original owners keep complete control","B":"Shares can be sold to the public to raise large amounts of finance","C":"The company avoids all government regulation","D":"The company no longer pays any tax"},"correctOption":"B","correctAnswer":"Shares can be sold to the public to raise large amounts of finance","questionType":"MCQ","explanation":{"correct_reason":"A public limited company can offer shares for sale to investors, which lets Halliday Software raise much larger sums than a private company.","distractor_reasons":{"A":"Floating on the stock exchange usually reduces the original owners' control as outside shareholders gain votes.","B":"A public limited company can offer shares for sale to investors, which lets Halliday Software raise much larger sums than a private company.","C":"Public companies face more, not less, regulation, including publishing annual accounts.","D":"Companies still pay tax on profits whatever their legal form, so this is not a benefit."}}},{"id":"P1_U1_MCQ_1235","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1235","question":"Westgate Bus Company plans to run more frequent services on its busiest routes in the town. Which stakeholder group benefits most directly from this service plan?","options":{"A":"The local tax office","B":"Rival bus operators","C":"Passengers who face shorter waiting times","D":"Suppliers of diesel fuel"},"correctOption":"C","correctAnswer":"Passengers who face shorter waiting times","questionType":"MCQ","explanation":{"correct_reason":"More frequent buses reduce the time passengers wait at stops, which is the most direct benefit of Westgate Bus Company's plan.","distractor_reasons":{"A":"The tax office collects tax and does not gain directly from more frequent bus services.","B":"Rival operators may lose passengers, so they are unlikely to benefit from the plan.","C":"More frequent buses reduce the time passengers wait at stops, which is the most direct benefit of Westgate Bus Company's plan.","D":"Fuel suppliers may sell slightly more diesel, but the benefit to passengers is far more direct."}}},{"id":"P1_U1_MCQ_1236","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1236","question":"Quarto Print Studio has a limited stock of specialist paper and cannot buy more until next month, while customers keep asking for printed invitations. What does this situation illustrate?","options":{"A":"Paper is unlimited but expensive","B":"Only wealthy customers want printing","C":"Scarcity means paper is simply rare","D":"Limited resources cannot satisfy all the wants of customers"},"correctOption":"D","correctAnswer":"Limited resources cannot satisfy all the wants of customers","questionType":"MCQ","explanation":{"correct_reason":"Quarto Print Studio has limited paper but many customers wanting invitations, which is scarcity: limited resources against unlimited wants.","distractor_reasons":{"A":"The stem says the paper stock is limited, so paper is not unlimited in this case.","B":"Many customers are asking for invitations, not only wealthy ones, so this does not explain the shortage.","C":"Scarcity is about limited resources relative to wants, not about something being rare in an absolute sense.","D":"Quarto Print Studio has limited paper but many customers wanting invitations, which is scarcity: limited resources against unlimited wants."}}},{"id":"P1_U1_MCQ_1237","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1237","question":"Employment in services has expanded in the region where Calloway Insurance operates. Which change is most likely to have caused this expansion of the tertiary sector?","options":{"A":"Rising household incomes and more automation in factories","B":"A sharp fall in household incomes","C":"A ban on importing services","D":"A decline in the number of city residents"},"correctOption":"A","correctAnswer":"Rising household incomes and more automation in factories","questionType":"MCQ","explanation":{"correct_reason":"Higher incomes increase spending on services such as insurance, while factory automation releases labour from manufacturing, so both push employment towards the tertiary sector.","distractor_reasons":{"A":"Higher incomes increase spending on services such as insurance, while factory automation releases labour from manufacturing, so both push employment towards the tertiary sector.","B":"Falling incomes usually reduce spending on services and would slow tertiary growth.","C":"A ban on imported services might protect some firms but would not generally expand service employment.","D":"A falling city population reduces demand for local services such as insurance offices."}}},{"id":"P1_U1_MCQ_1238","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1238","question":"Vellum Books is a small independent bookshop whose owner values personal service more than expansion. Which reason best explains why the owner may not want to grow the business?","options":{"A":"Growth always reduces profit","B":"Growth would require more staff and reduce the owner's personal control","C":"Larger firms cannot compete with small shops","D":"The book market is certain to shrink"},"correctOption":"B","correctAnswer":"Growth would require more staff and reduce the owner's personal control","questionType":"MCQ","explanation":{"correct_reason":"Expanding Vellum Books would mean hiring and managing more staff, which would dilute the owner's close personal control and service style.","distractor_reasons":{"A":"Growth can raise profit through economies of scale, so it does not always reduce profit.","B":"Expanding Vellum Books would mean hiring and managing more staff, which would dilute the owner's close personal control and service style.","C":"Large chains often compete strongly through lower prices and wider ranges.","D":"There is no evidence in the stem that the book market is certain to shrink."}}},{"id":"P1_U1_MCQ_1239","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1239","question":"Cwtch Bakery is owned and run by one person as a sole trader. Which statement about the owner's liability is correct for this bakery business?","options":{"A":"Liability is limited to the money the owner invested","B":"The owner cannot be sued by unpaid suppliers","C":"The owner is personally liable for all the debts of the business","D":"Liability is shared equally with the bakery's customers"},"correctOption":"C","correctAnswer":"The owner is personally liable for all the debts of the business","questionType":"MCQ","explanation":{"correct_reason":"A sole trader such as Cwtch Bakery has unlimited liability, so the owner is personally responsible for every debt the business cannot pay.","distractor_reasons":{"A":"Limited liability belongs to incorporated companies, not to a sole trader such as Cwtch Bakery.","B":"Unpaid suppliers can sue the owner personally, because the sole trader and the business are not separate in law.","C":"A sole trader such as Cwtch Bakery has unlimited liability, so the owner is personally responsible for every debt the business cannot pay.","D":"Customers have no responsibility for the bakery's debts, so liability is not shared with them."}}},{"id":"P1_U1_MCQ_1240","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1240","question":"Harbourlight Charity runs a cafe whose profits fund a shelter for homeless people in the city. Which objective best describes this organisation's main aim in the community?","options":{"A":"Maximise dividends for shareholders","B":"Increase market share at the expense of rivals","C":"Reduce costs by cutting all services","D":"Provide a social benefit while covering its costs"},"correctOption":"D","correctAnswer":"Provide a social benefit while covering its costs","questionType":"MCQ","explanation":{"correct_reason":"Harbourlight Charity uses cafe profits to fund a shelter, so its aim is a social benefit supported by trading income rather than maximising returns for owners.","distractor_reasons":{"A":"A charity has no shareholders expecting dividends, so this is not its objective.","B":"Beating rival cafes is not the purpose of the charity's trading activity.","C":"Cutting all services would destroy the shelter, which contradicts the organisation's social aim.","D":"Harbourlight Charity uses cafe profits to fund a shelter, so its aim is a social benefit supported by trading income rather than maximising returns for owners."}}},{"id":"P1_U1_MCQ_1241","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1241","question":"Juniper Lane Deli had sales of $240,000. It spent $132,000 on bought-in food and $28,000 on other bought-in supplies. What value did the deli add?","options":{"A":"$80,000","B":"$108,000","C":"$212,000","D":"$240,000"},"correctOption":"A","correctAnswer":"$80,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is $240,000 of sales minus bought-in costs of $132,000 plus $28,000, which comes to $80,000 for Juniper Lane Deli.","distractor_reasons":{"A":"Value added is $240,000 of sales minus bought-in costs of $132,000 plus $28,000, which comes to $80,000 for Juniper Lane Deli.","B":"$108,000 subtracts only the $132,000 food cost and ignores the $28,000 of other bought-in supplies.","C":"$212,000 subtracts only the $28,000 of supplies and leaves the $132,000 food cost in.","D":"$240,000 is the sales figure with no bought-in costs deducted at all."}}},{"id":"P1_U1_MCQ_1242","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1242","question":"A country's GDP is $500 billion. Primary industries contribute $40 billion, secondary industries $150 billion and the rest comes from services. What percentage of GDP comes from the tertiary sector?","options":{"A":"30%","B":"62%","C":"38%","D":"8%"},"correctOption":"B","correctAnswer":"62%","questionType":"MCQ","explanation":{"correct_reason":"Services contribute $500 billion minus $40 billion and $150 billion, which is $310 billion, and $310 billion divided by $500 billion equals 62%.","distractor_reasons":{"A":"30% is the combined primary and secondary share, equal to $190 billion, not the service share.","B":"Services contribute $500 billion minus $40 billion and $150 billion, which is $310 billion, and $310 billion divided by $500 billion equals 62%.","C":"38% is the primary and secondary share of $190 billion, which leaves out the tertiary contribution.","D":"8% is the primary sector's $40 billion as a share of $500 billion, not the service share."}}},{"id":"P1_U1_MCQ_1243","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1243","question":"Thrush Music had sales revenue of $180,000 last year and total costs of $151,200. What profit did the music business make from these sales in the year?","options":{"A":"$28,700","B":"$151,200","C":"$28,800","D":"$180,000"},"correctOption":"C","correctAnswer":"$28,800","questionType":"MCQ","explanation":{"correct_reason":"Profit is revenue of $180,000 minus total costs of $151,200, which equals $28,800 for Thrush Music.","distractor_reasons":{"A":"$28,700 is $100 too low and does not match the subtraction of $151,200 from $180,000.","B":"$151,200 is the total cost figure, not the profit earned by the business.","C":"Profit is revenue of $180,000 minus total costs of $151,200, which equals $28,800 for Thrush Music.","D":"$180,000 is the sales revenue before any costs have been deducted."}}},{"id":"P1_U1_MCQ_1244","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1244","question":"Oakenshaw Farm is a partnership of three farmers who share profits equally. Last year the partnership made a profit of $96,000. How much does each partner receive?","options":{"A":"$96,000","B":"$48,000","C":"$24,000","D":"$32,000"},"correctOption":"D","correctAnswer":"$32,000","questionType":"MCQ","explanation":{"correct_reason":"With an equal split, each of the three partners receives $96,000 divided by 3, which is $32,000.","distractor_reasons":{"A":"$96,000 is the whole partnership profit, not one partner's equal share.","B":"$48,000 would be the share of each partner if only two partners split $96,000 equally.","C":"$24,000 would be the share of each partner if four partners split $96,000 equally.","D":"With an equal split, each of the three partners receives $96,000 divided by 3, which is $32,000."}}},{"id":"P1_U1_MCQ_1245","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1245","question":"Newlyn Fish Market has revenue of $400,000. It pays $96,000 in wages and $24,000 in rent. What percentage of revenue is spent on these two costs combined?","options":{"A":"30%","B":"24%","C":"6%","D":"40%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Wages and rent together are $96,000 plus $24,000, which is $120,000, and $120,000 divided by $400,000 revenue equals 30%.","distractor_reasons":{"A":"Wages and rent together are $96,000 plus $24,000, which is $120,000, and $120,000 divided by $400,000 revenue equals 30%.","B":"24% is the rent of $24,000 expressed as a percentage of the revenue, ignoring wages.","C":"6% is far too low and does not match the $120,000 combined cost against $400,000 revenue.","D":"40% would mean combined costs of $160,000, which is $40,000 more than the actual figure."}}},{"id":"P1_U1_MCQ_1246","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1246","question":"The owner of Dovetail Upholstery uses $25,000 of personal savings, which were earning 4% interest, to buy fabric and tools. What is the opportunity cost of this decision?","options":{"A":"The $25,000 of savings","B":"The interest income given up by not leaving the savings in the bank","C":"The cost of the fabric and tools","D":"The wages paid to the upholsterers"},"correctOption":"B","correctAnswer":"The interest income given up by not leaving the savings in the bank","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the next best alternative forgone, which here is the 4% interest the owner no longer earns on the $25,000 of savings.","distractor_reasons":{"A":"The $25,000 is the amount invested, not the alternative benefit given up by using it.","B":"Opportunity cost is the next best alternative forgone, which here is the 4% interest the owner no longer earns on the $25,000 of savings.","C":"Fabric and tools are what the money buys, not the alternative use of the savings.","D":"Wages are a running cost of the business and are not the opportunity cost of using the savings."}}},{"id":"P1_U1_MCQ_1247","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1247","question":"Ravensworth Media has grown as factory employment in its region has fallen over recent decades. Which factor best explains this decline in manufacturing employment in the region?","options":{"A":"A rise in the number of farm workers","B":"Higher tariffs on imported services","C":"Cheaper manufactured imports and growing demand for services","D":"A fall in household incomes"},"correctOption":"C","correctAnswer":"Cheaper manufactured imports and growing demand for services","questionType":"MCQ","explanation":{"correct_reason":"Cheaper imports of manufactured goods reduce demand for domestic factory output, while rising demand for services such as media shifts employment towards the tertiary sector.","distractor_reasons":{"A":"More farm workers would raise primary employment, not explain the fall in factory jobs.","B":"Tariffs on imported services affect trade in services rather than the decline in manufacturing jobs.","C":"Cheaper imports of manufactured goods reduce demand for domestic factory output, while rising demand for services such as media shifts employment towards the tertiary sector.","D":"Falling household incomes would reduce demand for services too, so it does not explain service growth."}}},{"id":"P1_U1_MCQ_1248","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1248","question":"Elmcroft Furniture wants to compare its size with a rival that uses much more machinery. Which measure is likely to be most misleading on its own?","options":{"A":"Value of sales revenue","B":"Value of output","C":"Market share","D":"Number of employees"},"correctOption":"D","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Number of employees is misleading here because machinery can replace labour, so a highly mechanised rival could be larger in output while employing fewer people.","distractor_reasons":{"A":"Sales revenue reflects the value customers pay and is not distorted by how much machinery is used.","B":"Value of output measures the volume produced and is not affected by replacing workers with machines.","C":"Market share compares sales with the whole market and does not depend on the labour force.","D":"Number of employees is misleading here because machinery can replace labour, so a highly mechanised rival could be larger in output while employing fewer people."}}},{"id":"P1_U1_MCQ_1249","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1249","question":"Greyfriars Press plc wants to raise $2 million to buy new printing presses. Which feature of a public limited company makes raising this finance easiest?","options":{"A":"Its shares can be offered for sale to the public","B":"Its partners share unlimited liability","C":"It is not allowed to borrow money","D":"Its profits are exempt from tax"},"correctOption":"A","correctAnswer":"Its shares can be offered for sale to the public","questionType":"MCQ","explanation":{"correct_reason":"A public limited company such as Greyfriars Press can sell shares to the public, which allows it to raise $2 million from many investors at once.","distractor_reasons":{"A":"A public limited company such as Greyfriars Press can sell shares to the public, which allows it to raise $2 million from many investors at once.","B":"A public limited company has shareholders rather than partners, and its shareholders have limited liability.","C":"Public limited companies can borrow as well as issue shares, so this statement is untrue.","D":"Profits of a public limited company are still subject to corporation tax, so they are not exempt."}}},{"id":"P1_U1_MCQ_1250","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1250","question":"Harrowfield Sports Club is owned by its members, who pay a yearly subscription and elect a committee. Which objective is most likely to be its main aim?","options":{"A":"Maximise dividends for outside shareholders","B":"Provide sports facilities for members at an affordable cost","C":"Expand overseas sales of equipment","D":"Increase the price of its shares on the stock exchange"},"correctOption":"B","correctAnswer":"Provide sports facilities for members at an affordable cost","questionType":"MCQ","explanation":{"correct_reason":"A members' club exists to serve its members, so Harrowfield Sports Club aims to provide good facilities at a subscription members can afford rather than to make profit.","distractor_reasons":{"A":"There are no outside shareholders in a members' club, so dividends are not its objective.","B":"A members' club exists to serve its members, so Harrowfield Sports Club aims to provide good facilities at a subscription members can afford rather than to make profit.","C":"Selling equipment overseas is unrelated to a local sports club owned by its members.","D":"A members' club has no shares traded on a stock exchange, so it has no share price to raise."}}},{"id":"P1_U1_MCQ_1251","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1251","question":"Pebble Bay Kayaks buys kayaks from a maker for $45,000 and hires them out for $75,000 over the season. It spends nothing else on bought-in items. What value has it added?","options":{"A":"$45,000","B":"$120,000","C":"$30,000","D":"$75,000"},"correctOption":"C","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is hire revenue of $75,000 minus the $45,000 cost of the bought-in kayaks, which gives $30,000 for Pebble Bay Kayaks.","distractor_reasons":{"A":"$45,000 is the bought-in cost of the kayaks, not the value that the business adds.","B":"$120,000 adds the revenue and the cost together instead of subtracting the cost.","C":"Value added is hire revenue of $75,000 minus the $45,000 cost of the bought-in kayaks, which gives $30,000 for Pebble Bay Kayaks.","D":"$75,000 is the total hire revenue before any bought-in cost is deducted."}}},{"id":"P1_U1_MCQ_1252","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1252","question":"Umber & Oast Brewery turns barley, hops and water into bottled beer. Which statement best explains why it is classified in the secondary sector for official statistics?","options":{"A":"It grows the barley used in its beer","B":"It sells beer directly to customers","C":"It transports beer to supermarkets","D":"It manufactures a finished product from raw materials"},"correctOption":"D","correctAnswer":"It manufactures a finished product from raw materials","questionType":"MCQ","explanation":{"correct_reason":"Brewing turns raw materials such as barley and hops into a finished product, and manufacturing belongs to the secondary sector.","distractor_reasons":{"A":"Growing barley is a primary activity, and the brewery buys rather than grows its inputs.","B":"Selling beer directly to customers is a tertiary retail activity, not the reason for its classification.","C":"Transporting goods to supermarkets is a tertiary service, not manufacturing.","D":"Brewing turns raw materials such as barley and hops into a finished product, and manufacturing belongs to the secondary sector."}}},{"id":"P1_U1_MCQ_1253","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1253","question":"Quartz Analytics earned revenue of $420,000 in 2024 and $504,000 in 2025. What was the percentage increase in its revenue over the year for the analytics firm?","options":{"A":"20%","B":"$84,000","C":"16.7%","D":"120%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Revenue increased by $504,000 minus $420,000, which is $84,000, and $84,000 divided by the original $420,000 equals 20%.","distractor_reasons":{"A":"Revenue increased by $504,000 minus $420,000, which is $84,000, and $84,000 divided by the original $420,000 equals 20%.","B":"$84,000 is the cash increase in revenue, not the percentage increase the question asks for.","C":"16.7% comes from dividing $84,000 by the new revenue of $504,000 rather than the original figure.","D":"120% would mean revenue rose to $924,000, far above the $504,000 actually achieved."}}},{"id":"P1_U1_MCQ_1254","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1254","question":"Four friends are considering forming a partnership to run a catering business. Which statement about an ordinary partnership is correct under the law in this case?","options":{"A":"It must issue shares to the public","B":"Profits and debts are shared among the partners","C":"Every partner automatically has limited liability","D":"It cannot employ any staff"},"correctOption":"B","correctAnswer":"Profits and debts are shared among the partners","questionType":"MCQ","explanation":{"correct_reason":"In an ordinary partnership the partners share the profits and are jointly responsible for the debts, which is a key feature of this legal structure.","distractor_reasons":{"A":"Only a public limited company issues shares to the public, so a partnership cannot do this.","B":"In an ordinary partnership the partners share the profits and are jointly responsible for the debts, which is a key feature of this legal structure.","C":"Ordinary partners have unlimited liability, so limited liability is not automatic.","D":"A partnership can employ staff, and many catering partnerships have several employees."}}},{"id":"P1_U1_MCQ_1255","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1255","question":"Dovecote Pharmacy's owner wants to raise prices to increase profit, while local customers want cheaper medicines. Which statement best describes this situation for the business?","options":{"A":"All stakeholders always share the same objectives","B":"The government sets every medicine price","C":"Different stakeholders can have conflicting objectives","D":"Customers own the pharmacy and receive its profit"},"correctOption":"C","correctAnswer":"Different stakeholders can have conflicting objectives","questionType":"MCQ","explanation":{"correct_reason":"The owner wants higher prices for more profit while customers want lower prices, which shows that different stakeholders of Dovecote Pharmacy have conflicting objectives.","distractor_reasons":{"A":"The stem clearly shows a disagreement, so stakeholders do not always share the same objectives.","B":"The owner is deciding on prices here, and the stem does not say the government sets every price.","C":"The owner wants higher prices for more profit while customers want lower prices, which shows that different stakeholders of Dovecote Pharmacy have conflicting objectives.","D":"The pharmacy is owned by its proprietor, not by its customers, so customers do not receive its profit."}}},{"id":"P1_U1_MCQ_1256","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1256","question":"Ironbark Joinery divides production into six repetitive tasks, with each worker doing only one. Which is a likely disadvantage of this division of labour for the firm?","options":{"A":"Workers become more skilled at their task","B":"Output per worker rises quickly","C":"Training time for each worker falls","D":"Boredom may reduce quality and increase staff turnover"},"correctOption":"D","correctAnswer":"Boredom may reduce quality and increase staff turnover","questionType":"MCQ","explanation":{"correct_reason":"Repeating one narrow task can make Ironbark Joinery's workers bored and careless, which may lower quality and push staff to leave.","distractor_reasons":{"A":"Greater skill is a benefit of division of labour, not a disadvantage.","B":"Rising output per worker is a benefit, and the question asks for a disadvantage.","C":"Shorter training is another advantage, since each worker learns only one task.","D":"Repeating one narrow task can make Ironbark Joinery's workers bored and careless, which may lower quality and push staff to leave."}}},{"id":"P1_U1_MCQ_1257","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1257","question":"A country's businesses can be grouped into primary, secondary and tertiary sectors for official statistics. Which of these businesses operates mainly in the secondary sector?","options":{"A":"Alder Smelting, which turns iron ore into steel beams","B":"Marsh Harrier Fishing, which catches cod","C":"Calloway Insurance, which sells policies","D":"Granite Row Quarry, which extracts stone"},"correctOption":"A","correctAnswer":"Alder Smelting, which turns iron ore into steel beams","questionType":"MCQ","explanation":{"correct_reason":"Alder Smelting processes iron ore into steel beams, and transforming raw materials into manufactured products is a secondary sector activity.","distractor_reasons":{"A":"Alder Smelting processes iron ore into steel beams, and transforming raw materials into manufactured products is a secondary sector activity.","B":"Catching cod is a primary activity because it takes a natural resource directly from the sea.","C":"Selling insurance policies is a service, so it belongs to the tertiary sector.","D":"Extracting stone from a quarry is a primary activity, not manufacturing."}}},{"id":"P1_U1_MCQ_1258","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1258","question":"Dunescape Hotels opens three new hotels using profits it has retained over several years. Which type of growth is this for the hotel group over that period?","options":{"A":"A takeover of a rival chain","B":"Internal (organic) growth","C":"A merger with another hotel group","D":"A sale of shares to the public"},"correctOption":"B","correctAnswer":"Internal (organic) growth","questionType":"MCQ","explanation":{"correct_reason":"Opening new hotels with retained profit expands Dunescape's own operations rather than buying another firm, so this is internal or organic growth.","distractor_reasons":{"A":"A takeover would mean buying an existing hotel business, which the stem does not describe.","B":"Opening new hotels with retained profit expands Dunescape's own operations rather than buying another firm, so this is internal or organic growth.","C":"A merger would combine Dunescape with another hotel group, not build new hotels itself.","D":"Selling shares to the public is a way to raise finance, not the type of growth described here."}}},{"id":"P1_U1_MCQ_1259","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1259","question":"Redwick Family Butchers is a sole trader business in a small town. Which is an advantage of this legal structure for the owner of the shop?","options":{"A":"The owner has limited liability for business debts","B":"It is easier to raise large amounts of finance","C":"The owner keeps all profits and decides quickly","D":"The business continues automatically after the owner retires"},"correctOption":"C","correctAnswer":"The owner keeps all profits and decides quickly","questionType":"MCQ","explanation":{"correct_reason":"A sole trader such as Redwick Family Butchers keeps all the profit and can make decisions without consulting partners or shareholders.","distractor_reasons":{"A":"A sole trader has unlimited liability, so limited liability is not an advantage of this structure.","B":"Banks often see sole traders as riskier, so raising large sums is usually harder than for a company.","C":"A sole trader such as Redwick Family Butchers keeps all the profit and can make decisions without consulting partners or shareholders.","D":"A sole trader business has no automatic continuity and may close when the owner retires or dies."}}},{"id":"P1_U1_MCQ_1260","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1260","question":"Umberdale Dairy Co-op is owned by 40 farmers who share profits according to the milk they supply. Which objective is most consistent with this structure?","options":{"A":"Maximising the share price on the stock exchange","B":"Paying members the lowest possible milk price","C":"Attracting outside shareholders to buy shares","D":"Securing a fair price for members' milk"},"correctOption":"D","correctAnswer":"Securing a fair price for members' milk","questionType":"MCQ","explanation":{"correct_reason":"A co-operative is run for its members, so Umberdale Dairy aims to obtain a fair milk price for the 40 farmers who own and supply it.","distractor_reasons":{"A":"A co-operative has no shares traded on a stock exchange, so it has no share price to maximise.","B":"Paying the lowest milk price would harm the farmer members who own the co-operative.","C":"Ownership is restricted to the farmer members, so attracting outside shareholders is not its aim.","D":"A co-operative is run for its members, so Umberdale Dairy aims to obtain a fair milk price for the 40 farmers who own and supply it."}}},{"id":"P1_U1_MCQ_1261","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1261","question":"A customer buys a bouquet from Larkspur Florists for a birthday. Which statement best explains why this purchase is a want rather than a need for the customer?","options":{"A":"Flowers are not essential for the customer's survival","B":"Flowers are scarce in the shop","C":"The florist adds value to the flowers","D":"The customer has unlimited income"},"correctOption":"A","correctAnswer":"Flowers are not essential for the customer's survival","questionType":"MCQ","explanation":{"correct_reason":"A birthday bouquet is a pleasure rather than something required to live, so the purchase from Larkspur Florists satisfies a want.","distractor_reasons":{"A":"A birthday bouquet is a pleasure rather than something required to live, so the purchase from Larkspur Florists satisfies a want.","B":"Scarcity explains why the flowers have a price, not why the customer's purchase is a want.","C":"Adding value affects the price charged, but it does not turn a want into a need.","D":"No customer has unlimited income, and limited income is why choices have to be made."}}},{"id":"P1_U1_MCQ_1262","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1262","question":"In the region where Marlow Coachworks operates, the share of workers in services rose from 45% in 2010 to 63% in 2025. What was the increase in percentage points?","options":{"A":"18%","B":"18 percentage points","C":"40%","D":"63 percentage points"},"correctOption":"B","correctAnswer":"18 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The service share rose from 45% to 63%, and 63 minus 45 equals an increase of 18 percentage points.","distractor_reasons":{"A":"18% describes a relative change, but the question asks for the simple difference between two percentages.","B":"The service share rose from 45% to 63%, and 63 minus 45 equals an increase of 18 percentage points.","C":"40% does not match the difference between the 45% and 63% shares in the stem.","D":"63 percentage points repeats the final share rather than the change in the share."}}},{"id":"P1_U1_MCQ_1263","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1263","question":"Whitethorn Nurseries plans to grow by taking over a rival garden centre. Which is a likely drawback of this takeover for the nursery in the short term?","options":{"A":"An immediate increase in selling capacity","B":"Economies of scale from buying in bulk","C":"Clashes of management style and redundancy costs","D":"A guaranteed rise in profit"},"correctOption":"C","correctAnswer":"Clashes of management style and redundancy costs","questionType":"MCQ","explanation":{"correct_reason":"Bringing two garden centres together can create clashes over how to manage staff and may require redundancy payments, which are real drawbacks of a takeover.","distractor_reasons":{"A":"More selling capacity is a possible benefit of the takeover, not a drawback.","B":"Bulk buying economies are an advantage that the takeover may bring.","C":"Bringing two garden centres together can create clashes over how to manage staff and may require redundancy payments, which are real drawbacks of a takeover.","D":"No takeover guarantees higher profit, so this is not a valid drawback either."}}},{"id":"P1_U1_MCQ_1264","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1264","question":"Five Bells Inn is a partnership of two people who share profit in the ratio 5:3. Last year the partnership made $88,000. How much does the partner with the smaller share receive?","options":{"A":"$33,000","B":"$55,000","C":"$44,000","D":"$35,200"},"correctOption":"A","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"The smaller share is 3 of the 8 total parts, so the partner receives 3/8 of $88,000, which equals $33,000.","distractor_reasons":{"A":"The smaller share is 3 of the 8 total parts, so the partner receives 3/8 of $88,000, which equals $33,000.","B":"$55,000 is the larger partner's 5/8 share of the $88,000 profit.","C":"$44,000 would be an equal half share, but the partners agreed a 5:3 ratio.","D":"$35,200 comes from dividing $88,000 into five parts and taking two, which is not the 5:3 ratio."}}},{"id":"P1_U1_MCQ_1265","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1265","question":"Orchard Gate School, a private school, received fees of $1,200,000 and had costs of $1,050,000. What was its surplus as a percentage of fee income?","options":{"A":"12.5%","B":"14.3%","C":"8%","D":"$150,000"},"correctOption":"A","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"The surplus is $1,200,000 minus $1,050,000, which is $150,000, and $150,000 divided by $1,200,000 equals 12.5%.","distractor_reasons":{"A":"The surplus is $1,200,000 minus $1,050,000, which is $150,000, and $150,000 divided by $1,200,000 equals 12.5%.","B":"14.3% divides $150,000 by the $1,050,000 costs rather than by the fee income.","C":"8% does not match a surplus of $150,000 on fee income of $1,200,000.","D":"$150,000 is the cash surplus, not its percentage of fee income."}}},{"id":"P1_U1_MCQ_1266","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1266","question":"Cinderpath Pottery sells bowls for more than the clay and glaze cost. Which statement correctly defines the value added by the pottery in this case?","options":{"A":"Total revenue minus all costs, including wages","B":"The difference between the selling price and the cost of bought-in materials","C":"The profit paid out to the owners","D":"The total wage bill of the business"},"correctOption":"B","correctAnswer":"The difference between the selling price and the cost of bought-in materials","questionType":"MCQ","explanation":{"correct_reason":"Value added is the selling price of Cinderpath's bowls minus the cost of the bought-in clay and glaze, which measures the extra worth the pottery creates.","distractor_reasons":{"A":"Subtracting all costs gives profit, while value added deducts only bought-in materials.","B":"Value added is the selling price of Cinderpath's bowls minus the cost of the bought-in clay and glaze, which measures the extra worth the pottery creates.","C":"Profit paid to the owners is a distribution of profit, not the definition of value added.","D":"The wage bill is one cost of production and does not measure value added."}}},{"id":"P1_U1_MCQ_1267","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1267","question":"Which change best explains the rapid growth of the secondary sector during industrialisation, when firms such as Riverstone Masonry expanded their output in that period?","options":{"A":"Most workers moved back to farms","B":"Demand for personal services fell sharply","C":"Machinery and factories allowed mass production of goods","D":"Governments restricted the building of factories"},"correctOption":"C","correctAnswer":"Machinery and factories allowed mass production of goods","questionType":"MCQ","explanation":{"correct_reason":"Mechanised factories allowed goods to be produced in large quantities at lower cost, which is why secondary output and employment grew so quickly.","distractor_reasons":{"A":"Industrialisation moved workers away from farms towards factories, not back to farms.","B":"Demand for services generally grew later, and it did not fall sharply during industrialisation.","C":"Mechanised factories allowed goods to be produced in large quantities at lower cost, which is why secondary output and employment grew so quickly.","D":"Factory building was not restricted; it expanded rapidly in industrialising countries."}}},{"id":"P1_U1_MCQ_1268","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1268","question":"Rookwood Publishing employs 40 staff and earns revenue of $2 million. A rival employs 400 staff and earns revenue of $20 million. Which statement is correct?","options":{"A":"Rookwood is larger on both measures","B":"The two firms are the same size","C":"Business size cannot be compared using figures","D":"The rival is larger on both measures"},"correctOption":"D","correctAnswer":"The rival is larger on both measures","questionType":"MCQ","explanation":{"correct_reason":"The rival's 400 staff and $20 million revenue are each ten times Rookwood's 40 staff and $2 million, so the rival is larger on both measures.","distractor_reasons":{"A":"Rookwood has the smaller workforce and the smaller revenue, so it is not larger.","B":"A tenfold difference in staff and revenue shows the firms are not the same size.","C":"Figures such as employees and revenue can be compared directly, as this example shows.","D":"The rival's 400 staff and $20 million revenue are each ten times Rookwood's 40 staff and $2 million, so the rival is larger on both measures."}}},{"id":"P1_U1_MCQ_1269","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1269","question":"Tarnside Plumbing is a sole trader with business debts of $30,000 and business assets of $18,000. What happens if the business cannot pay all its debts?","options":{"A":"The owner must pay the $12,000 shortfall from personal funds","B":"The debt is written off by the suppliers","C":"Shareholders must pay the shortfall","D":"The government repays the debt"},"correctOption":"A","correctAnswer":"The owner must pay the $12,000 shortfall from personal funds","questionType":"MCQ","explanation":{"correct_reason":"Unlimited liability means the owner of Tarnside Plumbing must cover the $30,000 debt left after the $18,000 of business assets, so $12,000 comes from personal funds.","distractor_reasons":{"A":"Unlimited liability means the owner of Tarnside Plumbing must cover the $30,000 debt left after the $18,000 of business assets, so $12,000 comes from personal funds.","B":"Suppliers are entitled to be paid and do not simply write off a sole trader's debts.","C":"A sole trader has no shareholders, so no shareholders can be asked to pay the shortfall.","D":"The government does not repay the private debts of a sole trader."}}},{"id":"P1_U1_MCQ_1270","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1270","question":"Bexley Rail plans to cut late-night services to reduce its operating costs. Which stakeholder group benefits most from this decision in the short term at the rail firm?","options":{"A":"Passengers who travel after midnight","B":"Shareholders through lower costs and higher profit","C":"Train drivers who work nights","D":"Shops near stations that open late"},"correctOption":"B","correctAnswer":"Shareholders through lower costs and higher profit","questionType":"MCQ","explanation":{"correct_reason":"Cutting late-night services lowers Bexley Rail's operating costs, which can raise profit and benefit its shareholders, at least in the short term.","distractor_reasons":{"A":"Passengers who travel after midnight lose their service, so they are harmed rather than helped.","B":"Cutting late-night services lowers Bexley Rail's operating costs, which can raise profit and benefit its shareholders, at least in the short term.","C":"Drivers who work nights may lose shifts or pay, so they do not benefit from the decision.","D":"Shops near stations may lose late-evening customers when the trains stop running."}}},{"id":"P1_U1_MCQ_1271","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1271","question":"Windrow Joinery had sales of $320,000. It spent $148,000 on timber and glue and $24,000 on bought-in delivery services. What value did the joinery add?","options":{"A":"$172,000","B":"$124,000","C":"$148,000","D":"$320,000"},"correctOption":"C","correctAnswer":"$148,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is $320,000 of sales minus bought-in costs of $148,000 plus $24,000, which leaves $148,000 for Windrow Joinery.","distractor_reasons":{"A":"$172,000 subtracts only the $148,000 timber cost and ignores the $24,000 delivery cost.","B":"$124,000 subtracts the $172,000 of bought-in costs twice, so it understates value added.","C":"Value added is $320,000 of sales minus bought-in costs of $148,000 plus $24,000, which leaves $148,000 for Windrow Joinery.","D":"$320,000 is the sales revenue with no bought-in costs deducted at all."}}},{"id":"P1_U1_MCQ_1272","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1272","question":"Tintern Forest Products harvests timber, which other firms saw into boards and turn into furniture. Which statement correctly describes this chain of production in the timber industry?","options":{"A":"The tertiary sector comes first in the chain","B":"Only the primary sector adds value to the timber","C":"Furniture making is a primary sector activity","D":"Timber harvesting is primary and furniture making is secondary"},"correctOption":"D","correctAnswer":"Timber harvesting is primary and furniture making is secondary","questionType":"MCQ","explanation":{"correct_reason":"Harvesting timber takes a natural resource directly from the environment, so it is primary, while turning boards into furniture is manufacturing, which is secondary.","distractor_reasons":{"A":"The tertiary sector provides services and comes later in the chain, not first.","B":"Sawing and furniture making also add value as the timber is processed through the chain.","C":"Furniture making transforms materials into goods, which makes it a secondary activity.","D":"Harvesting timber takes a natural resource directly from the environment, so it is primary, while turning boards into furniture is manufacturing, which is secondary."}}},{"id":"P1_U1_MCQ_1273","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1273","question":"Piper's Row Records sold 84,000 albums last year. Total album sales in its market were 560,000. What was the record label's market share of album sales?","options":{"A":"15%","B":"6.7%","C":"84%","D":"66.7%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is 84,000 albums divided by 560,000 total album sales, multiplied by 100, which equals 15%.","distractor_reasons":{"A":"Market share is 84,000 albums divided by 560,000 total album sales, multiplied by 100, which equals 15%.","B":"6.7% comes from dividing 560,000 by 84,000, which reverses the correct calculation.","C":"84% repeats the 84,000 sales figure as though it were already a percentage of the market.","D":"66.7% would be the share of the market not sold by Piper's Row Records."}}},{"id":"P1_U1_MCQ_1274","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1274","question":"Quayside Storage Ltd has 20,000 ordinary shares in issue. The directors declare a dividend of $1.20 per share. What total dividend is paid to shareholders?","options":{"A":"$1,200","B":"$24,000","C":"$20,000","D":"$16,667"},"correctOption":"B","correctAnswer":"$24,000","questionType":"MCQ","explanation":{"correct_reason":"Total dividend is 20,000 shares multiplied by $1.20 per share, which equals $24,000 for Quayside Storage's shareholders.","distractor_reasons":{"A":"$1,200 treats the $1.20 rate as if only 1,000 shares had been issued.","B":"Total dividend is 20,000 shares multiplied by $1.20 per share, which equals $24,000 for Quayside Storage's shareholders.","C":"$20,000 repeats the number of shares and ignores the $1.20 dividend rate.","D":"$16,667 divides 20,000 shares by $1.20 instead of multiplying the two figures."}}},{"id":"P1_U1_MCQ_1275","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1275","question":"Calder Vale Clinic, a private clinic, aimed for a surplus of $300,000 but achieved $270,000. By what percentage did the surplus fall short of the target?","options":{"A":"30%","B":"11.1%","C":"10%","D":"90%"},"correctOption":"C","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"The shortfall is $300,000 minus $270,000, which is $30,000, and $30,000 divided by the $300,000 target equals 10%.","distractor_reasons":{"A":"30% would be a shortfall of $90,000, not the actual $30,000 below target.","B":"11.1% divides the $30,000 shortfall by the $270,000 achieved rather than by the target.","C":"The shortfall is $300,000 minus $270,000, which is $30,000, and $30,000 divided by the $300,000 target equals 10%.","D":"90% is the proportion of the target that was achieved, not the shortfall."}}},{"id":"P1_U1_MCQ_1276","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1276","question":"Oakhaven Removals can either buy a second removal van or hire two extra staff with the same $40,000. Which concept does this decision best illustrate?","options":{"A":"Unlimited resources","B":"Specialisation of labour","C":"Diseconomies of scale","D":"Opportunity cost"},"correctOption":"D","correctAnswer":"Opportunity cost","questionType":"MCQ","explanation":{"correct_reason":"Spending the $40,000 on a van means giving up the extra staff, so the alternative forgone is the opportunity cost of the choice.","distractor_reasons":{"A":"The $40,000 is a limited budget, so resources are not unlimited in this decision.","B":"Specialisation concerns dividing tasks between workers, not choosing between a van and staff.","C":"Diseconomies of scale are rising unit costs as a firm grows, which is not the issue here.","D":"Spending the $40,000 on a van means giving up the extra staff, so the alternative forgone is the opportunity cost of the choice."}}},{"id":"P1_U1_MCQ_1277","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1277","question":"Granite Row Quarry extracts stone from the ground. Which statement about the primary sector is correct for the economy as a whole, given this example?","options":{"A":"It extracts raw materials directly from the natural environment","B":"It processes raw materials into finished goods","C":"It provides services such as insurance and banking","D":"It includes retailing and tourism"},"correctOption":"A","correctAnswer":"It extracts raw materials directly from the natural environment","questionType":"MCQ","explanation":{"correct_reason":"The primary sector covers activities such as quarrying, farming and fishing that take raw materials directly from nature, as Granite Row Quarry does.","distractor_reasons":{"A":"The primary sector covers activities such as quarrying, farming and fishing that take raw materials directly from nature, as Granite Row Quarry does.","B":"Processing raw materials into finished goods is manufacturing, which belongs to the secondary sector.","C":"Insurance and banking are services, so they belong to the tertiary sector.","D":"Retailing and tourism are service activities and are part of the tertiary sector."}}},{"id":"P1_U1_MCQ_1278","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1278","question":"Cobbleford Toys plans to expand its factory and workforce over the next year. Which is the most likely reason the owners want the business to grow?","options":{"A":"To reduce its market share","B":"To gain economies of scale and higher profit","C":"To increase average unit costs","D":"To avoid having to borrow money"},"correctOption":"B","correctAnswer":"To gain economies of scale and higher profit","questionType":"MCQ","explanation":{"correct_reason":"Expanding output can lower Cobbleford Toys' average costs through economies of scale, which supports higher profit, a common reason owners seek growth.","distractor_reasons":{"A":"Growth is normally intended to increase market share, not to reduce it.","B":"Expanding output can lower Cobbleford Toys' average costs through economies of scale, which supports higher profit, a common reason owners seek growth.","C":"Owners aim to lower average unit costs through growth, not to raise them.","D":"Expansion often requires finance, so avoiding borrowing is not a typical reason to grow."}}},{"id":"P1_U1_MCQ_1279","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1279","question":"Bluebell Nursery is run as a partnership rather than a limited company. Which is a disadvantage of this legal structure for the owners of the nursery?","options":{"A":"It cannot employ any staff","B":"Profits must be shared with customers","C":"The partners have unlimited liability for the nursery's debts","D":"It must sell shares on a stock exchange"},"correctOption":"C","correctAnswer":"The partners have unlimited liability for the nursery's debts","questionType":"MCQ","explanation":{"correct_reason":"Partners in an ordinary partnership have unlimited liability, so the owners of Bluebell Nursery could lose personal assets if the business cannot pay its debts.","distractor_reasons":{"A":"A partnership can employ staff, and many nurseries have several employees.","B":"Customers buy plants and do not share in the partnership's profits.","C":"Partners in an ordinary partnership have unlimited liability, so the owners of Bluebell Nursery could lose personal assets if the business cannot pay its debts.","D":"A partnership cannot sell shares on a stock exchange, so this is not a requirement."}}},{"id":"P1_U1_MCQ_1280","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1280","question":"Fenwick Community Shop is a social enterprise that sells local produce. Which statement best describes how it is likely to use its profits each year?","options":{"A":"Distribute all profits to outside shareholders","B":"Pay large bonuses to its directors","C":"Keep all profits as cash and never use them","D":"Reinvest profits to support its social aim"},"correctOption":"D","correctAnswer":"Reinvest profits to support its social aim","questionType":"MCQ","explanation":{"correct_reason":"A social enterprise such as Fenwick Community Shop reinvests its surplus in its social purpose rather than distributing it to owners or shareholders.","distractor_reasons":{"A":"A social enterprise does not aim to pay all profits to outside shareholders.","B":"Large director bonuses would conflict with the shop's social purpose.","C":"Holding all profits as idle cash would not support the community aim the shop exists for.","D":"A social enterprise such as Fenwick Community Shop reinvests its surplus in its social purpose rather than distributing it to owners or shareholders."}}},{"id":"P1_U1_MCQ_1281","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1281","question":"Kingsmoor Tutoring charges $48,000 in fees over a year and spends $12,000 on bought-in books and software. What value has the tutoring business added over the year?","options":{"A":"$36,000","B":"$12,000","C":"$48,000","D":"$60,000"},"correctOption":"A","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is fee income of $48,000 minus the $12,000 spent on bought-in books and software, which equals $36,000 for Kingsmoor Tutoring.","distractor_reasons":{"A":"Value added is fee income of $48,000 minus the $12,000 spent on bought-in books and software, which equals $36,000 for Kingsmoor Tutoring.","B":"$12,000 is the bought-in cost, not the value that the tutoring business adds.","C":"$48,000 is total fee income before any bought-in costs are deducted.","D":"$60,000 adds fees and bought-in costs together instead of subtracting the cost."}}},{"id":"P1_U1_MCQ_1282","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1282","question":"A country employs 3.6 million people in the tertiary sector out of a total workforce of 4.5 million. Wrenfield Clinics operates in this country. What percentage of the workforce works in the tertiary sector?","options":{"A":"20%","B":"80%","C":"45%","D":"125%"},"correctOption":"B","correctAnswer":"80%","questionType":"MCQ","explanation":{"correct_reason":"The tertiary share is 3.6 million service workers divided by the 4.5 million total workforce, multiplied by 100, which equals 80%.","distractor_reasons":{"A":"20% is the share of the workforce not in the tertiary sector, equal to 0.9 million people.","B":"The tertiary share is 3.6 million service workers divided by the 4.5 million total workforce, multiplied by 100, which equals 80%.","C":"45% would be 2.025 million workers, far below the 3.6 million in services.","D":"125% is impossible because a sector cannot employ more people than the whole workforce."}}},{"id":"P1_U1_MCQ_1283","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1283","question":"Barrow Lane Books is a sole trader business whose owner is nearing retirement and has no family successor. Which is a likely consequence for the business?","options":{"A":"It will float on the stock exchange","B":"Its shares will be sold to the public","C":"It may close because there is no automatic successor","D":"New partners will automatically buy the owner's share"},"correctOption":"C","correctAnswer":"It may close because there is no automatic successor","questionType":"MCQ","explanation":{"correct_reason":"A sole trader business has no separate legal identity, so Barrow Lane Books may simply close when its owner retires without a successor.","distractor_reasons":{"A":"A sole trader business has no shares and cannot float on a stock exchange.","B":"There are no shares in a sole trader business to sell to the public.","C":"A sole trader business has no separate legal identity, so Barrow Lane Books may simply close when its owner retires without a successor.","D":"There are no partners in a sole trader business, so none can automatically buy a share."}}},{"id":"P1_U1_MCQ_1284","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1284","question":"Milima Farmers Co-operative in Kenya has 800 members who each sell their coffee through the group. It made a surplus of $240,000 this year, and every member has one vote at meetings. Which statement about how this co-operative operates is correct?","options":{"A":"Surplus is divided in proportion to members' shareholdings, with extra votes given to larger investors.","B":"The entire surplus is kept by the directors and none of the $240,000 is returned to members.","C":"Voting power depends on sales value, so the biggest coffee farmer controls the co-operative.","D":"Surplus is shared according to how much each member traded, with one vote per member."},"correctOption":"D","correctAnswer":"Surplus is shared according to how much each member traded, with one vote per member.","questionType":"MCQ","explanation":{"correct_reason":"A co-operative is owned and democratically controlled by its members, each having one vote, and any surplus is shared according to how much they trade with it. Milima's 800 members therefore get one vote each, so its $240,000 surplus is distributed by trading volume rather than shareholding.","distractor_reasons":{"A":"A co-operative distributes surplus by members' trading, not by shareholding, and gives each member one vote rather than weighting votes towards larger investors; share-weighted voting belongs to limited companies.","B":"A co-operative returns its surplus to members rather than allowing directors to keep all of it; retaining the whole $240,000 would contradict the member-owned purpose of Milima Farmers Co-operative.","C":"A co-operative gives every member one vote regardless of how much they supply, so the largest coffee farmer at Milima does not gain control simply through the value of coffee sold.","D":"A co-operative is owned and democratically controlled by its members, each having one vote, and any surplus is shared according to how much they trade with it. Milima's 800 members therefore get one vote each, so its $240,000 surplus is distributed by trading volume rather than shareholding."}}},{"id":"P1_U1_MCQ_1285","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1285","question":"Cranborne Motors plans to cut its apprenticeship programme to save money. Which stakeholder group is most directly affected by this decision at the garage in the long run?","options":{"A":"Apprentices who lose training and pay","B":"Customers who want lower prices","C":"Shareholders seeking higher dividends","D":"Steel suppliers to the garage"},"correctOption":"A","correctAnswer":"Apprentices who lose training and pay","questionType":"MCQ","explanation":{"correct_reason":"Apprentices lose their training places and wages when Cranborne Motors cuts the programme, so they are the group most directly harmed.","distractor_reasons":{"A":"Apprentices lose their training places and wages when Cranborne Motors cuts the programme, so they are the group most directly harmed.","B":"Customers may benefit from lower costs, so they are not the group most directly harmed.","C":"Shareholders may gain from cost savings, so the decision does not harm them directly.","D":"Steel suppliers sell materials for repairs and are not directly affected by apprentice training."}}},{"id":"P1_U1_MCQ_1286","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1286","question":"Tidewater Instrument Services repairs and services sonar equipment for a fishing fleet. Which customer need does this business mainly satisfy for the fleet each week?","options":{"A":"A luxury item for the boat's cabin","B":"Working equipment needed to locate fish safely","C":"Decorative cushions for the crew","D":"A sponsorship banner for the harbour"},"correctOption":"B","correctAnswer":"Working equipment needed to locate fish safely","questionType":"MCQ","explanation":{"correct_reason":"A fishing fleet needs reliable sonar to find fish and avoid hazards, so repairing this equipment meets an essential operational need rather than a luxury want.","distractor_reasons":{"A":"A luxury cabin item is a want and is not what sonar repair provides.","B":"A fishing fleet needs reliable sonar to find fish and avoid hazards, so repairing this equipment meets an essential operational need rather than a luxury want.","C":"Decorative cushions are unrelated to the sonar equipment that Tidewater services.","D":"A sponsorship banner is promotional and does not help the fleet locate fish safely."}}},{"id":"P1_U1_MCQ_1287","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1287","question":"Fennel Lane Pharmacy dispenses prescriptions and gives health advice to customers. Which sector does this business mainly belong to for official statistics in the economy?","options":{"A":"Primary, because it uses natural ingredients","B":"Secondary, because it makes up medicines","C":"Tertiary, because it provides a service","D":"Primary, because it sells to the public"},"correctOption":"C","correctAnswer":"Tertiary, because it provides a service","questionType":"MCQ","explanation":{"correct_reason":"Dispensing prescriptions and giving health advice are services, so Fennel Lane Pharmacy belongs to the tertiary sector.","distractor_reasons":{"A":"Using ingredients does not make a pharmacy primary, because it is not extracting raw materials from nature.","B":"A pharmacy dispenses medicines made elsewhere; it does not manufacture them on a large scale.","C":"Dispensing prescriptions and giving health advice are services, so Fennel Lane Pharmacy belongs to the tertiary sector.","D":"Selling to the public is a service activity and belongs to the tertiary sector, not the primary sector."}}},{"id":"P1_U1_MCQ_1288","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1288","question":"Saltire Seafoods employs 40 workers and processes 8,000 cases of fish a week. Which is a limitation of using the number of employees to compare its size with rivals?","options":{"A":"It always reflects profit accurately","B":"All fish firms use identical machinery","C":"It measures market share directly","D":"It ignores differences in machinery and output between firms"},"correctOption":"D","correctAnswer":"It ignores differences in machinery and output between firms","questionType":"MCQ","explanation":{"correct_reason":"A rival using more machinery could process more cases with fewer staff, so employee numbers alone ignore differences in capital and output when comparing size.","distractor_reasons":{"A":"Employee numbers say nothing about profit, so they certainly do not always reflect it accurately.","B":"Fish firms do not all use identical machinery, which is exactly why headcount can mislead.","C":"Employee numbers do not measure market share, which requires sales compared with the whole market.","D":"A rival using more machinery could process more cases with fewer staff, so employee numbers alone ignore differences in capital and output when comparing size."}}},{"id":"P1_U1_MCQ_1289","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1289","question":"Hollinsworth Coachworks is a sole trader business whose owner becomes seriously ill and cannot work for months. Which is a likely consequence for the business?","options":{"A":"The business may stop trading because no one else can make decisions","B":"Shareholders will vote for a new director","C":"The company must publish its annual accounts","D":"The bank will automatically take over the business"},"correctOption":"A","correctAnswer":"The business may stop trading because no one else can make decisions","questionType":"MCQ","explanation":{"correct_reason":"A sole trader has no partners or directors, so Hollinsworth Coachworks may stop trading while the owner is unable to make decisions and manage work.","distractor_reasons":{"A":"A sole trader has no partners or directors, so Hollinsworth Coachworks may stop trading while the owner is unable to make decisions and manage work.","B":"A sole trader business has no shareholders, so none can vote for a new director.","C":"A sole trader is not required to publish annual accounts in the way a company must.","D":"A bank does not automatically take over a sole trader business when the owner is ill."}}},{"id":"P1_U1_MCQ_1290","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1290","question":"Kingsholm Hotel is deciding whether to spend its profit on refurbishment or on higher staff pay. Which objective would its employees most likely prioritise in this situation?","options":{"A":"Higher dividends for shareholders","B":"Higher wages and more secure hours","C":"Lower room prices for guests","D":"Faster expansion into other cities"},"correctOption":"B","correctAnswer":"Higher wages and more secure hours","questionType":"MCQ","explanation":{"correct_reason":"Employees of Kingsholm Hotel gain directly from better pay and more secure working hours, so this is the objective they would prioritise.","distractor_reasons":{"A":"Dividends go to shareholders, not to the hotel's employees.","B":"Employees of Kingsholm Hotel gain directly from better pay and more secure working hours, so this is the objective they would prioritise.","C":"Lower room prices help guests, while employees are more concerned with their own pay.","D":"Expansion may create opportunities but does not directly raise employees' current pay and security."}}},{"id":"P1_U1_MCQ_1291","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1291","question":"Arden Bridge Gym combines exercise equipment with personal coaching for each client. How does the gym most clearly add value for its customers in this way?","options":{"A":"It sells memberships at the lowest price in town","B":"It buys its equipment in bulk","C":"It combines equipment and expert coaching to improve clients' fitness","D":"It stays open for longer hours"},"correctOption":"C","correctAnswer":"It combines equipment and expert coaching to improve clients' fitness","questionType":"MCQ","explanation":{"correct_reason":"Combining equipment with expert coaching gives clients a more effective service than either alone, which raises the value Arden Bridge Gym provides.","distractor_reasons":{"A":"A lower price reduces the amount customers pay and does not by itself increase value added.","B":"Bulk buying lowers the gym's costs but does not directly improve what clients receive.","C":"Combining equipment with expert coaching gives clients a more effective service than either alone, which raises the value Arden Bridge Gym provides.","D":"Longer opening hours add convenience but do not show how equipment and coaching together create extra value."}}},{"id":"P1_U1_MCQ_1292","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1292","question":"A furniture maker buys timber from a forestry firm. Why does the secondary sector depend on the primary sector in this chain of production activity?","options":{"A":"Primary firms provide banking and insurance services","B":"Secondary firms supply raw materials to primary firms","C":"The tertiary sector mines all the raw materials","D":"Primary firms supply the raw materials that secondary firms process"},"correctOption":"D","correctAnswer":"Primary firms supply the raw materials that secondary firms process","questionType":"MCQ","explanation":{"correct_reason":"The forestry firm supplies timber that the furniture maker processes, so secondary production depends on primary firms for its raw materials.","distractor_reasons":{"A":"Banking and insurance are tertiary services, not primary sector activities.","B":"The direction is reversed, because primary firms supply materials to secondary firms.","C":"Mining is a primary activity, so the tertiary sector does not mine raw materials.","D":"The forestry firm supplies timber that the furniture maker processes, so secondary production depends on primary firms for its raw materials."}}},{"id":"P1_U1_MCQ_1293","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1293","question":"Fennimore Nurseries wants to expand its business in the market. Which of these actions would be an example of external growth for the nursery business?","options":{"A":"Merging with a rival nursery","B":"Opening a new branch using retained profit","C":"Hiring more staff for the same site","D":"Spending more on local advertising"},"correctOption":"A","correctAnswer":"Merging with a rival nursery","questionType":"MCQ","explanation":{"correct_reason":"A merger joins Fennimore Nurseries with another business, so growth comes from outside the firm, which is external growth.","distractor_reasons":{"A":"A merger joins Fennimore Nurseries with another business, so growth comes from outside the firm, which is external growth.","B":"Opening a new branch with retained profit expands the firm's own operations, which is internal growth.","C":"Hiring more staff on the same site is internal expansion, not external growth.","D":"More advertising supports internal growth by raising sales, but no other business is acquired."}}},{"id":"P1_U1_MCQ_1294","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1294","question":"Wold Chemicals plc is considering becoming a private limited company. Which advantage of being a public limited company would it lose by making this change?","options":{"A":"Limited liability for its shareholders","B":"The ability to offer shares for sale to the public","C":"A separate legal identity from its owners","D":"The right to employ staff"},"correctOption":"B","correctAnswer":"The ability to offer shares for sale to the public","questionType":"MCQ","explanation":{"correct_reason":"A public limited company can offer its shares to the general public, and Wold Chemicals would lose this ability if it became a private limited company.","distractor_reasons":{"A":"Shareholders of a private limited company also have limited liability, so this would not be lost.","B":"A public limited company can offer its shares to the general public, and Wold Chemicals would lose this ability if it became a private limited company.","C":"A private limited company also has a separate legal identity from its owners.","D":"Both public and private limited companies can employ staff, so this right would remain."}}},{"id":"P1_U1_MCQ_1295","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1295","question":"Bellwether Wool Co-op made a surplus of $250,000 and decided to retain 60% to invest in new equipment. How much is left to distribute to its members?","options":{"A":"$150,000","B":"$250,000","C":"$100,000","D":"$40,000"},"correctOption":"C","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"If 60% of $250,000 is retained, which is $150,000, the remaining 40% is $100,000 available for distribution to members.","distractor_reasons":{"A":"$150,000 is the 60% retained for new equipment, not the amount distributed.","B":"$250,000 is the whole surplus before any retention takes place.","C":"If 60% of $250,000 is retained, which is $150,000, the remaining 40% is $100,000 available for distribution to members.","D":"$40,000 would be 40% of $100,000, not 40% of the $250,000 surplus."}}},{"id":"P1_U1_MCQ_1296","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1296","question":"Honeystone Farm now uses one worker to pick fruit and another to pack it. Which benefit is most likely to result from this specialisation on the farm?","options":{"A":"Output falls because tasks are repeated","B":"Workers need much longer training","C":"Each worker must learn every task","D":"Each worker becomes faster at one task, raising output"},"correctOption":"D","correctAnswer":"Each worker becomes faster at one task, raising output","questionType":"MCQ","explanation":{"correct_reason":"Repeating one task lets each Honeystone Farm worker become quicker and more skilled at it, so total output rises for the same working time.","distractor_reasons":{"A":"Specialisation usually raises output, so it does not cause output to fall.","B":"Learning one task usually shortens training, rather than making it much longer.","C":"Specialisation means each worker learns one task, not every task on the farm.","D":"Repeating one task lets each Honeystone Farm worker become quicker and more skilled at it, so total output rises for the same working time."}}},{"id":"P1_U1_MCQ_1297","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1297","question":"Which factor best explains the rapid growth of tertiary businesses such as Pinecrest Software in many developed economies around the world over recent decades since the 1980s?","options":{"A":"Rising incomes and greater demand for services","B":"Falling demand for services","C":"More workers needed on farms","D":"A decline in computer technology"},"correctOption":"A","correctAnswer":"Rising incomes and greater demand for services","questionType":"MCQ","explanation":{"correct_reason":"As incomes rise, households and firms buy more services, which increases demand for firms such as Pinecrest Software and expands tertiary employment.","distractor_reasons":{"A":"As incomes rise, households and firms buy more services, which increases demand for firms such as Pinecrest Software and expands tertiary employment.","B":"Falling demand for services would shrink the tertiary sector rather than grow it.","C":"Modern farming uses fewer workers because of machinery, so farm employment has generally fallen.","D":"Computer technology has advanced rapidly, which has supported rather than reduced software services."}}},{"id":"P1_U1_MCQ_1298","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1298","question":"Trevose & Co grew from 5 employees to 60 in a single year. Which problem is most likely to result from such rapid growth for the firm?","options":{"A":"Immediate lower unit costs","B":"Difficulties in communication and control","C":"A guaranteed increase in market share","D":"The complete loss of unlimited liability"},"correctOption":"B","correctAnswer":"Difficulties in communication and control","questionType":"MCQ","explanation":{"correct_reason":"Moving from 5 to 60 staff in a year can overwhelm management systems, so Trevose & Co is likely to suffer communication and control problems.","distractor_reasons":{"A":"Rapid growth often raises costs at first as systems and staff are stretched, so lower unit costs are not immediate.","B":"Moving from 5 to 60 staff in a year can overwhelm management systems, so Trevose & Co is likely to suffer communication and control problems.","C":"Growth may raise sales, but a larger market share is not guaranteed.","D":"Unlimited liability is a legal feature and does not disappear simply because the firm grows."}}},{"id":"P1_U1_MCQ_1299","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1299","question":"Oakfield Press plc and a local partnership both publish magazines. Which statement about Oakfield Press plc is correct as a public limited company under company law?","options":{"A":"It is owned by partners who share unlimited liability","B":"It has unlimited liability for its debts","C":"Its shares can be bought and sold by the public","D":"It cannot employ more than 50 staff"},"correctOption":"C","correctAnswer":"Its shares can be bought and sold by the public","questionType":"MCQ","explanation":{"correct_reason":"A public limited company such as Oakfield Press can list its shares so that members of the public buy and sell them on a stock exchange.","distractor_reasons":{"A":"A public limited company is owned by shareholders, not partners with unlimited liability.","B":"Shareholders in a public limited company have limited liability, so the company's debts are not their personal responsibility.","C":"A public limited company such as Oakfield Press can list its shares so that members of the public buy and sell them on a stock exchange.","D":"A public limited company can employ as many staff as it needs, so there is no 50-staff limit."}}},{"id":"P1_U1_MCQ_1300","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1300","question":"Thornleigh Hotel plans to close its restaurant in the evening to save money. Which stakeholder group is most directly affected by losing this service and the related jobs?","options":{"A":"The hotel's shareholders only","B":"Linen suppliers only","C":"The local council only","D":"Guests and restaurant staff who lose service and jobs"},"correctOption":"D","correctAnswer":"Guests and restaurant staff who lose service and jobs","questionType":"MCQ","explanation":{"correct_reason":"Closing the restaurant removes an evening service from guests and eliminates the restaurant jobs at Thornleigh Hotel, so these two groups are most directly affected.","distractor_reasons":{"A":"Shareholders may gain from lower costs, so they are not the group most directly affected by the lost service.","B":"Linen suppliers may lose some orders, but the loss of service and jobs hits guests and staff far more directly.","C":"The local council is not directly involved in the hotel's restaurant service or staffing.","D":"Closing the restaurant removes an evening service from guests and eliminates the restaurant jobs at Thornleigh Hotel, so these two groups are most directly affected."}}},{"id":"P1_U1_MCQ_1301","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1301","question":"Harlow Printworks Ltd has $48,000 available and must choose one project. A second digital press would add $9,500 profit a year, while a delivery van would add $6,200 a year. The directors choose the press. What is the opportunity cost of their decision?","options":{"A":"$3,300 a year","B":"$6,200 a year","C":"$9,500 a year","D":"$48,000"},"correctOption":"B","correctAnswer":"$6,200 a year","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best alternative forgone, which is the van's $6,200 annual profit; the $9,500 press profit is the chosen option, not the cost.","distractor_reasons":{"B":"Opportunity cost is the value of the next best alternative forgone, which is the van's $6,200 annual profit; the $9,500 press profit is the chosen option, not the cost.","A":"$3,300 is the difference between the two profit figures, not the value of the alternative that was given up, so it does not measure opportunity cost.","C":"$9,500 is the profit expected from the chosen press, so it is the benefit gained rather than the benefit lost by rejecting the van.","D":"$48,000 is the total sum available to invest, not the annual profit sacrificed, so it overstates the opportunity cost of the choice."}}},{"id":"P1_U1_MCQ_1302","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1302","question":"Kestrel Marine Ltd catches mackerel off its coast, freezes and packs the fish at its plant, then delivers the boxes to supermarkets. Which combination correctly classifies these three activities?","options":{"A":"Primary, tertiary and secondary","B":"Primary, secondary and tertiary","C":"Secondary, primary and tertiary","D":"Tertiary, secondary and primary"},"correctOption":"B","correctAnswer":"Primary, secondary and tertiary","questionType":"MCQ","explanation":{"correct_reason":"Catching fish extracts a natural resource (primary), freezing and packing manufacture a product (secondary), and delivery is a service (tertiary).","distractor_reasons":{"B":"Catching fish extracts a natural resource (primary), freezing and packing manufacture a product (secondary), and delivery is a service (tertiary).","A":"Freezing and packing is a manufacturing activity, so it belongs to the secondary sector rather than to the tertiary sector.","C":"Catching mackerel from the sea extracts a raw material, which is primary, so it cannot be classified as secondary.","D":"Catching fish comes first and is primary, while delivery is the service, so this order reverses the activities."}}},{"id":"P1_U1_MCQ_1303","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1303","question":"Priya wants to open a small bakery. She leases a shop, hires two bakers, buys ovens and uses her own savings, knowing she could lose them. Which is her role as an entrepreneur?","options":{"A":"Guaranteeing that the business will make a profit","B":"Organising land, labour and capital and bearing the risk of loss","C":"Setting prices by law for all rival bakeries","D":"Avoiding all borrowing and personal responsibility"},"correctOption":"B","correctAnswer":"Organising land, labour and capital and bearing the risk of loss","questionType":"MCQ","explanation":{"correct_reason":"An entrepreneur combines the factors of production, makes the key decisions and risks capital, but cannot guarantee profit or control what rivals do.","distractor_reasons":{"B":"An entrepreneur combines the factors of production, makes the key decisions and risks capital, but cannot guarantee profit or control what rivals do.","A":"No owner can guarantee profit, because demand, costs and competition are uncertain, so this is not a realistic role.","C":"Prices are set by the business and the market, and a new bakery has no legal power over competitors' prices.","D":"Entrepreneurs often borrow and must accept responsibility for decisions, so avoiding both is the opposite of the role."}}},{"id":"P1_U1_MCQ_1304","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1304","question":"A sole trader plumber owes $18,000 to suppliers after a bad year, and the business bank account is empty. What does unlimited liability mean in this situation?","options":{"A":"Only the money invested in the business is at risk","B":"Personal assets can be sold to pay business debts","C":"The government pays all the business debts","D":"Debts are shared equally with customers"},"correctOption":"B","correctAnswer":"Personal assets can be sold to pay business debts","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is not a separate legal entity, so personal possessions may be used to settle business debts if the firm cannot pay.","distractor_reasons":{"B":"A sole trader is not a separate legal entity, so personal possessions may be used to settle business debts if the firm cannot pay.","A":"That describes limited liability, which a sole trader does not have, so personal assets remain exposed.","C":"Governments do not settle private business debts, and the owner remains responsible for them personally.","D":"Customers owe money only for services bought, and they are not liable for the plumber's business debts."}}},{"id":"P1_U1_MCQ_1305","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1305","question":"During a recession a furniture retailer cuts prices to fill its empty showroom and keep trading through the downturn. Which business objective is it prioritising?","options":{"A":"Profit maximisation","B":"Survival","C":"Market share leadership","D":"Social responsibility"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Cutting prices to keep sales and cash coming in during a downturn shows survival as the main objective, ahead of profit or growth.","distractor_reasons":{"B":"Cutting prices to keep sales and cash coming in during a downturn shows survival as the main objective, ahead of profit or growth.","A":"Cutting prices to fill the showroom is more likely to reduce profit margins, so the firm is not maximising profit.","C":"The aim described is to keep trading, not to become the largest seller, and no market share target is mentioned.","D":"Price cuts to keep trading are a commercial response to recession, not a social or ethical objective."}}},{"id":"P1_U1_MCQ_1306","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1306","question":"Cedar & Loom Furniture Ltd buys oak worth $140 for each table and sells the finished table for $320. Its carpenters are paid $65 per table for their work. What is the added value per table?","options":{"A":"$115","B":"$155","C":"$180","D":"$460"},"correctOption":"C","correctAnswer":"$180","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price minus the cost of bought-in materials, so $320 - $140 = $180; the $65 wage is a cost the firm meets, not a bought-in material.","distractor_reasons":{"C":"Added value is the selling price minus the cost of bought-in materials, so $320 - $140 = $180; the $65 wage is a cost the firm meets, not a bought-in material.","A":"$115 subtracts both the $140 timber and the $65 wages from $320, but added value deducts only bought-in materials and components.","B":"$155 deducts the $140 timber and part of the wages, which mixes added value with a profit calculation rather than using its definition.","D":"$460 adds the timber and wages to the selling price instead of subtracting bought-in materials, so it cannot be added value."}}},{"id":"P1_U1_MCQ_1307","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1307","question":"In Brazil, 2.4 million of its 8 million workers are employed in primary activities and 2.8 million in secondary activities. The rest work in the tertiary sector. What percentage of the workforce is in the tertiary sector?","options":{"A":"25%","B":"30%","C":"35%","D":"65%"},"correctOption":"C","correctAnswer":"35%","questionType":"MCQ","explanation":{"correct_reason":"Tertiary workers are 8 - 2.4 - 2.8 = 2.8 million, and 2.8 / 8 x 100 = 35% of the workforce.","distractor_reasons":{"C":"Tertiary workers are 8 - 2.4 - 2.8 = 2.8 million, and 2.8 / 8 x 100 = 35% of the workforce.","A":"25% would be 2 million workers, which does not match the 2.8 million left after primary and secondary employment.","B":"30% would be 2.4 million workers, but the tertiary total is 2.8 million once the other two sectors are subtracted.","D":"65% is the combined primary and secondary share, not the tertiary share that remains after those sectors."}}},{"id":"P1_U1_MCQ_1308","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1308","question":"Why would a bank most likely ask a new business such as a bicycle repair shop for a business plan before agreeing a five-year loan?","options":{"A":"To take ownership of the business if it succeeds","B":"To set the shop's prices for the next five years","C":"To judge whether the idea is viable and the loan can be repaid","D":"To confirm that the owner has no competitors"},"correctOption":"C","correctAnswer":"To judge whether the idea is viable and the loan can be repaid","questionType":"MCQ","explanation":{"correct_reason":"A plan shows the market, costs and cash flow forecast, helping the lender assess risk and the business's ability to repay.","distractor_reasons":{"C":"A plan shows the market, costs and cash flow forecast, helping the lender assess risk and the business's ability to repay.","A":"A bank lending money does not normally take ownership; it earns interest and expects repayment of the loan.","B":"Pricing is a management decision for the business, not something a lender controls through a business plan.","D":"Every repair shop faces competitors, and a plan analyses the market rather than pretending competition does not exist."}}},{"id":"P1_U1_MCQ_1309","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1309","question":"Three partners share profits in the ratio 3:2:1. In a year the partnership makes a profit of $96,000. How much does the partner with the largest share receive?","options":{"A":"$16,000","B":"$32,000","C":"$48,000","D":"$96,000"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio has 3 + 2 + 1 = 6 parts, each worth $96,000/6 = $16,000, so the largest 3-part share is $48,000.","distractor_reasons":{"C":"The ratio has 3 + 2 + 1 = 6 parts, each worth $96,000/6 = $16,000, so the largest 3-part share is $48,000.","A":"$16,000 is the value of one part of the ratio, which is the smallest partner's share rather than the largest.","B":"$32,000 is the two-part share received by the middle partner, not the three-part largest share.","D":"$96,000 is the whole partnership profit, which must first be divided among all three partners."}}},{"id":"P1_U1_MCQ_1310","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1310","question":"A firm wants a 25% share of a market where 400,000 units are sold. It currently sells 70,000 units. How many extra units must it sell?","options":{"A":"70,000 units","B":"100,000 units","C":"30,000 units","D":"130,000 units"},"correctOption":"C","correctAnswer":"30,000 units","questionType":"MCQ","explanation":{"correct_reason":"A 25% share is 0.25 x 400,000 = 100,000 units, so the firm needs 100,000 - 70,000 = 30,000 extra sales.","distractor_reasons":{"C":"A 25% share is 0.25 x 400,000 = 100,000 units, so the firm needs 100,000 - 70,000 = 30,000 extra sales.","A":"70,000 is the firm's current sales, not the extra amount needed to reach a 25% share.","B":"100,000 is the total sales required for a 25% share, which includes the 70,000 already sold.","D":"130,000 adds current sales to the target instead of subtracting current sales from the target."}}},{"id":"P1_U1_MCQ_1311","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1311","question":"Fenwick Chocolate Ltd packs 900 boxes a day when each of its 6 workers completes a whole box. After dividing the tasks, the same 6 workers pack 1,260 boxes a day. What is the increase in output per worker?","options":{"A":"60 boxes","B":"150 boxes","C":"210 boxes","D":"360 boxes"},"correctOption":"A","correctAnswer":"60 boxes","questionType":"MCQ","explanation":{"correct_reason":"Output per worker rises from 900 / 6 = 150 boxes to 1,260 / 6 = 210 boxes, which is an increase of 60 boxes per worker from specialisation.","distractor_reasons":{"A":"Output per worker rises from 900 / 6 = 150 boxes to 1,260 / 6 = 210 boxes, which is an increase of 60 boxes per worker from specialisation.","B":"150 boxes is the original output per worker before tasks were divided, not the increase achieved after specialisation, so it answers a different question.","C":"210 boxes is the new output per worker after specialisation, not the increase, so the final subtraction of 150 has been left out.","D":"360 boxes is the total rise in daily output for the whole team of six, not the rise for each individual worker."}}},{"id":"P1_U1_MCQ_1312","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1312","question":"Ridgeway Insurance Brokers arranges cover for small shops, while other local firms quarry stone, assemble dishwashers and grow barley. Which of these businesses operates in the tertiary sector?","options":{"A":"An insurance broker arranging cover for shops","B":"A quarry extracting limestone","C":"A factory assembling dishwashers","D":"A farm growing barley"},"correctOption":"A","correctAnswer":"An insurance broker arranging cover for shops","questionType":"MCQ","explanation":{"correct_reason":"An insurance broker provides a service rather than extracting or manufacturing a product, so it belongs to the tertiary sector.","distractor_reasons":{"A":"An insurance broker provides a service rather than extracting or manufacturing a product, so it belongs to the tertiary sector.","B":"Quarrying removes stone from the ground, which is a primary activity that produces a raw material.","C":"Assembling dishwashers turns components into a finished product in a factory, which is a secondary manufacturing activity rather than a service.","D":"Growing barley is agriculture, which uses land to produce a raw material and belongs to the primary sector."}}},{"id":"P1_U1_MCQ_1313","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1313","question":"Helmstead Cycles Ltd sold 18,000 bicycles last year in a country where consumers bought a total of 120,000 bicycles. What is the firm's market share?","options":{"A":"15%","B":"6.7%","C":"18%","D":"85%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, so 18,000/120,000 x 100 = 15% of the market.","distractor_reasons":{"A":"Market share is the firm's sales divided by total market sales, so 18,000/120,000 x 100 = 15% of the market.","B":"6.7% comes from dividing 120,000 by 18,000, which reverses the market share calculation and gives the wrong figure.","C":"18% uses the firm's 18,000 sales as if they were a percentage, without dividing by the 120,000 total market.","D":"85% would mean the firm sold six times more than it did, leaving almost no sales for all its competitors."}}},{"id":"P1_U1_MCQ_1314","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1314","question":"A sole trader and a private limited company both run small building firms. Which feature distinguishes the private limited company from the sole trader in law?","options":{"A":"The company has a separate legal identity from its owners","B":"The company cannot employ more than ten staff","C":"The company's owners have unlimited liability","D":"The company cannot keep its accounts private"},"correctOption":"A","correctAnswer":"The company has a separate legal identity from its owners","questionType":"MCQ","explanation":{"correct_reason":"Incorporation gives a private limited company its own legal identity, so it can own property and be sued separately from its shareholders.","distractor_reasons":{"A":"Incorporation gives a private limited company its own legal identity, so it can own property and be sued separately from its shareholders.","B":"There is no such limit on a private limited company, which may employ as many staff as it needs.","C":"Owners of a private limited company have limited liability, which is the opposite of the sole trader position.","D":"Private limited companies can generally keep their accounts private, unlike public limited companies, so this is not a distinguishing disadvantage in this comparison."}}},{"id":"P1_U1_MCQ_1315","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1315","question":"A clothing company raises the pay of its sewing staff by 6%. Which stakeholder group is most likely to be affected negatively in the short term?","options":{"A":"Shareholders, through lower profit for dividends","B":"Employees, through lower wages","C":"Customers, through worse quality automatically","D":"The local government, through lost tax revenue"},"correctOption":"A","correctAnswer":"Shareholders, through lower profit for dividends","questionType":"MCQ","explanation":{"correct_reason":"Higher wages raise costs, so profit available for dividends may fall, which disadvantages shareholders while staff gain in the short term.","distractor_reasons":{"A":"Higher wages raise costs, so profit available for dividends may fall, which disadvantages shareholders while staff gain in the short term.","B":"The scenario says pay rises by 6%, so employees gain rather than lose from this change.","C":"A pay rise does not automatically reduce quality, and customers may even benefit from better-motivated staff.","D":"Higher wages usually increase income tax revenue, so local government is not the group most likely to lose."}}},{"id":"P1_U1_MCQ_1316","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1316","question":"Rosemark Bakery Ltd uses two ovens, four bakers, flour bought from a mill and the owner's savings, which she risks to open a second shop. Which factor of production is represented by the owner risking her savings?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"D","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Enterprise is the factor that organises the other inputs and bears risk; the owner risking her savings to expand is acting as the entrepreneur.","distractor_reasons":{"D":"Enterprise is the factor that organises the other inputs and bears risk; the owner risking her savings to expand is acting as the entrepreneur.","A":"Land covers natural resources such as the wheat used for flour or the building site, not the owner's willingness to risk her own savings.","B":"Labour refers to the four bakers and their effort, while the owner's risk-taking is a separate factor of production.","C":"Capital means the ovens and other manufactured equipment used in production, not the personal savings risked by the owner."}}},{"id":"P1_U1_MCQ_1317","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1317","question":"A region's manufacturing output was $180m out of $450m total output. It is now $150m out of $500m total output. By how many percentage points did manufacturing's share of output fall?","options":{"A":"20 percentage points","B":"30 percentage points","C":"40 percentage points","D":"10 percentage points"},"correctOption":"D","correctAnswer":"10 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The share fell from $180m/$450m = 40% to $150m/$500m = 30%, which is a fall of 10 percentage points, not 10% of the original.","distractor_reasons":{"D":"The share fell from $180m/$450m = 40% to $150m/$500m = 30%, which is a fall of 10 percentage points, not 10% of the original.","A":"20 points would take the share from 40% to 20%, but the new share is 30%, so the fall is smaller.","B":"30 points would leave only 10%, yet manufacturing still provides $150m of the $500m total, or 30%.","C":"40 points is the original share of output, not the change in that share over the period."}}},{"id":"P1_U1_MCQ_1318","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1318","question":"Halstead Boxes Ltd had annual revenue of $2,400,000 last year and employed 80 people across its two cardboard factories. What was its revenue per employee?","options":{"A":"$80,000","B":"$192,000","C":"$300,000","D":"$30,000"},"correctOption":"D","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"$2,400,000 divided by 80 employees equals $30,000 of revenue per employee, a common measure of business size when comparing firms.","distractor_reasons":{"D":"$2,400,000 divided by 80 employees equals $30,000 of revenue per employee, a common measure of business size when comparing firms.","A":"$80,000 would require revenue of $6.4m, so this figure does not follow from the $2,400,000 and 80 given.","B":"$192,000 multiplies the revenue by the number of employees instead of dividing revenue by employees.","C":"$300,000 would need only eight employees at the stated revenue, so it misplaces the division."}}},{"id":"P1_U1_MCQ_1319","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1319","question":"A company has 400,000 ordinary shares in issue. It makes profit after tax of $180,000 and pays 40% of this as dividends. What is the dividend per share?","options":{"A":"$0.45","B":"$0.72","C":"$1.80","D":"$0.18"},"correctOption":"D","correctAnswer":"$0.18","questionType":"MCQ","explanation":{"correct_reason":"Dividends total 40% of $180,000 = $72,000, and $72,000/400,000 shares = $0.18 per share, so each share receives 18 cents.","distractor_reasons":{"D":"Dividends total 40% of $180,000 = $72,000, and $72,000/400,000 shares = $0.18 per share, so each share receives 18 cents.","A":"$0.45 divides the full $180,000 by the shares, ignoring that only 40% of profit is paid out.","B":"$0.72 misplaces the decimal point; the total dividend of $72,000 spread over 400,000 shares is much smaller.","C":"$1.80 would require dividends of $720,000, which is four times the whole profit after tax."}}},{"id":"P1_U1_MCQ_1320","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1320","question":"A kitchen fitting firm has annual revenue of $480,000 and sets an objective of a 12% profit margin. What profit must it earn to meet this objective?","options":{"A":"$40,000","B":"$96,000","C":"$120,000","D":"$57,600"},"correctOption":"D","correctAnswer":"$57,600","questionType":"MCQ","explanation":{"correct_reason":"A 12% margin means profit of 12% of $480,000, which is 0.12 x 480,000 = $57,600 for the year.","distractor_reasons":{"D":"A 12% margin means profit of 12% of $480,000, which is 0.12 x 480,000 = $57,600 for the year.","A":"$40,000 is only about 8.3% of the $480,000 revenue, which falls short of the 12% profit margin the firm has targeted.","B":"$96,000 is 20% of the $480,000 revenue, which is well above the 12% margin the firm has set itself.","C":"$120,000 is 25% of the $480,000 revenue, more than double the profit required by the 12% target."}}},{"id":"P1_U1_MCQ_1321","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1321","question":"A family with a low income buys bread, clean water and bus fares to work each week, but keeps postponing the purchase of a games console. Which statement correctly distinguishes needs from wants?","options":{"A":"Bread, water and bus fares are wants because the family chooses them, while the console is a basic need.","B":"Bread, water and bus fares are needs essential for survival, while the console is a want that can be postponed.","C":"All four items are needs because the family spends income on them each week.","D":"All four items are wants because the family could live without any of them."},"correctOption":"B","correctAnswer":"Bread, water and bus fares are needs essential for survival, while the console is a want that can be postponed.","questionType":"MCQ","explanation":{"correct_reason":"Needs are goods or services essential for survival, such as food, water and transport to work, whereas a games console is a non-essential want.","distractor_reasons":{"B":"Needs are goods or services essential for survival, such as food, water and transport to work, whereas a games console is a non-essential want.","A":"The family does choose all four items, but choosing something does not make it a want; food, water and travel to work are essential needs.","C":"Spending income on an item does not make it a need, since a games console is not essential for survival or basic wellbeing.","D":"The family could not live healthily without food and water, so treating every item as a want ignores the meaning of a need."}}},{"id":"P1_U1_MCQ_1322","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1322","question":"Over twenty years a developed country's factories have installed more robots and faced cheaper imported goods. Which is the most likely result for secondary sector employment?","options":{"A":"Consumers spend a larger share of income on manufactured goods","B":"Factories use more automation and imports of manufactured goods are cheaper","C":"The country's primary sector has disappeared completely","D":"Governments have banned all manufacturing exports"},"correctOption":"B","correctAnswer":"Factories use more automation and imports of manufactured goods are cheaper","questionType":"MCQ","explanation":{"correct_reason":"Automation replaces factory workers and cheaper imports reduce domestic production, both cutting secondary employment as the economy shifts towards services.","distractor_reasons":{"B":"Automation replaces factory workers and cheaper imports reduce domestic production, both cutting secondary employment as the economy shifts towards services.","A":"Spending more on manufactured goods would support factory output and jobs, so it would not explain a fall in secondary employment.","C":"Primary industries still exist in developed countries, and their decline does not directly remove factory jobs.","D":"No such general ban exists, and the fall in secondary employment has continued without bans on manufactured exports."}}},{"id":"P1_U1_MCQ_1323","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1323","question":"Two rival firms are compared. Firm A has 240 employees; Firm B has 180 employees but higher annual revenue. Why can it be difficult to say which firm is larger?","options":{"A":"Employees and revenue are always identical measures of size","B":"Different measures of size can give different rankings of the two firms","C":"Firm B must be smaller because it employs fewer people","D":"Only the number of owners can decide business size"},"correctOption":"B","correctAnswer":"Different measures of size can give different rankings of the two firms","questionType":"MCQ","explanation":{"correct_reason":"Size can be measured by employees, revenue, capital or market share, and these measures may rank the two firms differently.","distractor_reasons":{"B":"Size can be measured by employees, revenue, capital or market share, and these measures may rank the two firms differently.","A":"The two measures can point in opposite directions, as they do here, so they are not identical indicators of size.","C":"Firm B has higher revenue, so calling it smaller ignores a valid measure and assumes employees are the only test.","D":"Ownership count says nothing about output, sales or capital, so it is not a recognised measure of business size."}}},{"id":"P1_U1_MCQ_1324","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1324","question":"A cafe owner is considering buying a franchise from a national coffee brand instead of trading under her own name. Which is a benefit of becoming a franchisee?","options":{"A":"Complete freedom from any payments to the franchisor","B":"Use of an established brand and proven operating methods","C":"Ownership of the franchisor's whole company","D":"No need to follow any quality standards"},"correctOption":"B","correctAnswer":"Use of an established brand and proven operating methods","questionType":"MCQ","explanation":{"correct_reason":"A franchisee gains a recognised brand, training and a tested business format, which can reduce the risk of failure compared with an unknown start-up.","distractor_reasons":{"B":"A franchisee gains a recognised brand, training and a tested business format, which can reduce the risk of failure compared with an unknown start-up.","A":"Franchisees normally pay an initial fee and ongoing royalties, so they are not free of payments.","C":"A franchisee buys the right to use the brand and system, not ownership of the franchisor's company.","D":"Franchise agreements require standards to protect the brand, so franchisees must follow them rather than inventing their own methods freely."}}},{"id":"P1_U1_MCQ_1325","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1325","question":"A chain of sports shops publishes a short statement saying it exists to help everyone enjoy sport, and managers use it when setting objectives. What is the purpose of this statement?","options":{"A":"To record the exact profit made last year","B":"To summarise its overall purpose and guide decisions by managers","C":"To list every product the firm has ever sold","D":"To set the legal tax rate for the company"},"correctOption":"B","correctAnswer":"To summarise its overall purpose and guide decisions by managers","questionType":"MCQ","explanation":{"correct_reason":"A mission statement expresses the organisation's overall purpose and values, helping managers and staff choose consistent objectives and actions over time.","distractor_reasons":{"B":"A mission statement expresses the organisation's overall purpose and values, helping managers and staff choose consistent objectives and actions over time.","A":"A mission statement is forward-looking and general, not a financial record of the previous year's profit.","C":"Product lists change constantly and belong in catalogues or records, not in a statement of purpose.","D":"Tax rates are set by government, and no business can determine its own legal tax rate."}}},{"id":"P1_U1_MCQ_1326","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1326","question":"Tarnfield Dairy Ltd owns one refrigerated truck. It can use it either for morning deliveries to 40 shops or for afternoon deliveries to 25 cafes, but not both. What basic economic problem does this situation best illustrate?","options":{"A":"Unlimited resources and limited wants","B":"Inflation, because the price of fuel is rising","C":"Scarcity, because a limited resource forces a choice with an opportunity cost","D":"Specialisation, because the firm serves only one customer type"},"correctOption":"C","correctAnswer":"Scarcity, because a limited resource forces a choice with an opportunity cost","questionType":"MCQ","explanation":{"correct_reason":"The firm has one truck but two competing uses, so the resource is scarce and choosing one delivery round means the other must be sacrificed.","distractor_reasons":{"C":"The firm has one truck but two competing uses, so the resource is scarce and choosing one delivery round means the other must be sacrificed.","A":"The truck is a limited resource while the firm has competing uses for it, so this option reverses the relationship between resources and wants.","B":"No price change is mentioned in the scenario, and rising fuel prices are not what forces the dairy to choose between two rounds.","D":"Specialisation means concentrating on a narrow range of tasks, while here the issue is one truck serving competing groups of customers."}}},{"id":"P1_U1_MCQ_1327","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1327","question":"Malaysia once employed 600,000 people in primary activities. It now employs 510,000 in these activities while its total workforce remains 3,000,000. By how many percentage points did the primary share fall?","options":{"A":"9 percentage points","B":"17 percentage points","C":"3 percentage points","D":"20 percentage points"},"correctOption":"C","correctAnswer":"3 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The share fell from 600,000/3,000,000 = 20% to 510,000/3,000,000 = 17%, a fall of 3 percentage points, even though 90,000 jobs were lost.","distractor_reasons":{"C":"The share fell from 600,000/3,000,000 = 20% to 510,000/3,000,000 = 17%, a fall of 3 percentage points, even though 90,000 jobs were lost.","A":"9 points would mean a fall to 11%, but 510,000 out of 3,000,000 is 17%, not 11%.","B":"17% is the new primary share itself, not the fall in the share from its earlier level.","D":"20% is the original primary share, so quoting it as the fall confuses the starting level with the change."}}},{"id":"P1_U1_MCQ_1328","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1328","question":"A growing bakery buys the flour mill that has supplied its bread ingredients for many years, while keeping the mill's name. What type of integration is this?","options":{"A":"Vertical forward","B":"Horizontal","C":"Vertical backward","D":"Diversification"},"correctOption":"C","correctAnswer":"Vertical backward","questionType":"MCQ","explanation":{"correct_reason":"The bakery is buying a supplier further back in the chain of production, which is vertical backward integration, not a merger with a rival.","distractor_reasons":{"C":"The bakery is buying a supplier further back in the chain of production, which is vertical backward integration, not a merger with a rival.","A":"Forward integration means moving towards the customer, such as a mill buying a bakery, which is the reverse of this case.","B":"Horizontal integration combines firms at the same stage, but a bakery and a flour mill are at different stages of production.","D":"Diversification means entering an unrelated market, whereas flour is a direct input to the bakery's existing products."}}},{"id":"P1_U1_MCQ_1329","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1329","question":"A franchisee pays an initial fee of $25,000 plus a royalty of 8% of revenue. First-year revenue is $300,000. What is the total paid to the franchisor in year one?","options":{"A":"$24,000","B":"$27,400","C":"$49,000","D":"$325,000"},"correctOption":"C","correctAnswer":"$49,000","questionType":"MCQ","explanation":{"correct_reason":"The royalty is 8% of $300,000 = $24,000, and adding the $25,000 initial fee gives a total of $49,000 paid in year one.","distractor_reasons":{"C":"The royalty is 8% of $300,000 = $24,000, and adding the $25,000 initial fee gives a total of $49,000 paid in year one.","A":"$24,000 is only the royalty on revenue and leaves out the $25,000 initial franchise fee.","B":"$27,400 does not follow from an 8% royalty plus the fee; it appears to confuse the percentages.","D":"$325,000 adds all revenue to the initial fee, but the royalty is only 8% of revenue."}}},{"id":"P1_U1_MCQ_1330","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1330","question":"A social enterprise runs a community cafe and uses its trading surplus to fund free meals for homeless people. Which statement best describes the objective of this organisation?","options":{"A":"To avoid earning any revenue from customers","B":"To pay all surplus to private shareholders","C":"To reinvest profit in a social purpose rather than maximise owner returns","D":"To close once it has covered its costs"},"correctOption":"C","correctAnswer":"To reinvest profit in a social purpose rather than maximise owner returns","questionType":"MCQ","explanation":{"correct_reason":"A social enterprise trades to earn income but uses its surplus to pursue a social mission, rather than distributing it to owners.","distractor_reasons":{"C":"A social enterprise trades to earn income but uses its surplus to pursue a social mission, rather than distributing it to owners.","A":"The cafe does earn revenue from customers, and trading income is what funds its social work.","B":"A social enterprise directs surplus to its social purpose, not to private shareholders seeking returns.","D":"The cafe aims to continue and expand its support, not to shut down as soon as costs are covered."}}},{"id":"P1_U1_MCQ_1331","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1331","question":"Before specialisation, two workers at Elmtree Furniture Ltd each complete 6 chairs a day, giving 12 chairs. After splitting the tasks, the pair completes 18 chairs a day. What is the daily increase in output?","options":{"A":"6 chairs","B":"12 chairs","C":"18 chairs","D":"30 chairs"},"correctOption":"A","correctAnswer":"6 chairs","questionType":"MCQ","explanation":{"correct_reason":"Output rises from 12 chairs to 18 chairs a day, a gain of 6 chairs, because each worker now repeats a narrower set of tasks more quickly.","distractor_reasons":{"A":"Output rises from 12 chairs to 18 chairs a day, a gain of 6 chairs, because each worker now repeats a narrower set of tasks more quickly.","B":"12 chairs is the original daily output of the two workers before specialisation, not the extra output created by dividing the tasks.","C":"18 chairs is the new total daily output after specialisation, so it includes the 12 chairs already produced before the change.","D":"30 chairs adds the old and new outputs together, but the question asks for the increase, which requires subtracting the old figure."}}},{"id":"P1_U1_MCQ_1332","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1332","question":"As incomes rise in a developing country, households spend a smaller share on food and more on education, travel and banking. Which effect on the tertiary sector does this describe?","options":{"A":"Demand for services grows, so tertiary employment and output rise","B":"The primary sector expands because food demand falls","C":"The secondary sector must shrink because incomes are rising","D":"The tertiary sector declines as households save more"},"correctOption":"A","correctAnswer":"Demand for services grows, so tertiary employment and output rise","questionType":"MCQ","explanation":{"correct_reason":"Higher incomes raise demand for services such as education, travel and banking, which are tertiary activities, so that sector grows in both output and jobs.","distractor_reasons":{"A":"Higher incomes raise demand for services such as education, travel and banking, which are tertiary activities, so that sector grows in both output and jobs.","B":"Falling demand for food would reduce primary activity, not expand it, so this option contradicts the scenario.","C":"Rising incomes can increase demand for manufactured goods too, so a shrinking secondary sector is not a necessary result.","D":"The scenario says households spend more on services, which raises tertiary activity rather than causing it to decline."}}},{"id":"P1_U1_MCQ_1333","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1333","question":"Pemberton Toys Ltd increased its annual sales revenue from $1.5m to $1.8m over the last financial year. What was the exact percentage growth in revenue achieved?","options":{"A":"20%","B":"16.7%","C":"30%","D":"120%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the $0.3m increase divided by the original $1.5m, so 0.3/1.5 x 100 = 20%, which equals 20% growth for the year.","distractor_reasons":{"A":"Growth is the $0.3m increase divided by the original $1.5m, so 0.3/1.5 x 100 = 20%, which equals 20% growth for the year.","B":"16.7% divides the $0.3m increase by the new $1.8m figure, but growth is measured against the original revenue.","C":"30% would mean an increase of $0.45m on $1.5m, but the actual increase is only $0.3m.","D":"120% treats the new revenue as a percentage of the old, which overstates growth by including the original $1.5m."}}},{"id":"P1_U1_MCQ_1334","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1334","question":"A growing family firm wants to raise capital by selling shares to the general public and having them traded on a stock exchange. Which statement about this public limited company is correct?","options":{"A":"Its shares can be advertised and traded on a stock exchange","B":"Its shares may only be sold to the original founders","C":"It must have at least 50 shareholders at all times","D":"It cannot raise capital by issuing shares"},"correctOption":"A","correctAnswer":"Its shares can be advertised and traded on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"A PLC may offer its shares to the general public and have them traded on a stock exchange, which allows it to raise large amounts of capital.","distractor_reasons":{"A":"A PLC may offer its shares to the general public and have them traded on a stock exchange, which allows it to raise large amounts of capital.","B":"A PLC's defining feature is that shares can be offered widely, not restricted to the founders.","C":"There is no rule requiring 50 shareholders, and a PLC may have fewer at any particular time.","D":"Issuing shares to the public is a main way a PLC raises capital, so this statement is the reverse of the truth."}}},{"id":"P1_U1_MCQ_1335","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1335","question":"A firm creates value added of $900,000 a year, and its total wage bill is $360,000. What percentage of value added goes to employees as wages?","options":{"A":"40%","B":"25%","C":"60%","D":"360%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Wages as a share of value added are 360,000/900,000 x 100, which equals 40%, leaving 60% for the other stakeholders.","distractor_reasons":{"A":"Wages as a share of value added are 360,000/900,000 x 100, which equals 40%, leaving 60% for the other stakeholders.","B":"25% would be $225,000 of wages, but the wage bill is $360,000 out of $900,000.","C":"60% is the share of value added left for other stakeholders after wages, not the employees' 40% share.","D":"360% treats the wage bill as a percentage of itself rather than of the $900,000 value added."}}},{"id":"P1_U1_MCQ_1336","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1336","question":"Brightwell Catering Ltd buys vegetables, gas and packaging and turns them into meals sold to office workers. Which statement best explains the purpose of this business activity?","options":{"A":"To increase the scarcity of resources so that prices rise","B":"To remove the need for consumers to make choices","C":"To ensure that all factors of production are owned by government","D":"To satisfy consumer needs and wants by adding value, usually while making a profit"},"correctOption":"D","correctAnswer":"To satisfy consumer needs and wants by adding value, usually while making a profit","questionType":"MCQ","explanation":{"correct_reason":"Businesses combine inputs such as vegetables and gas to produce meals that meet consumers' wants, adding value and normally aiming for profit.","distractor_reasons":{"D":"Businesses combine inputs such as vegetables and gas to produce meals that meet consumers' wants, adding value and normally aiming for profit.","A":"Businesses do use scarce resources, but deliberately increasing scarcity is not their purpose and would not satisfy consumer wants.","B":"Consumers still choose which meals to buy, and business activity does not remove the need to make choices about limited resources.","C":"Most catering businesses are privately owned, and government ownership of every factor is not the purpose of business activity."}}},{"id":"P1_U1_MCQ_1337","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1337","question":"In a low-income developing country most households farm small plots and sell any surplus locally, while factories and offices employ relatively few people. Which sector employs the largest share of the workforce?","options":{"A":"Secondary","B":"Tertiary","C":"Public","D":"Primary"},"correctOption":"D","correctAnswer":"Primary","questionType":"MCQ","explanation":{"correct_reason":"Most workers in low-income countries are farmers, fishers or miners, so primary activities usually provide the largest share of employment rather than services or factories.","distractor_reasons":{"D":"Most workers in low-income countries are farmers, fishers or miners, so primary activities usually provide the largest share of employment rather than services or factories.","A":"Factory production typically employs a smaller share in low-income countries, where much work is still on the land.","B":"Services usually become the largest employer only as incomes rise, not in a low-income economy with widespread subsistence farming.","C":"The public sector is not one of the three production sectors and does not usually employ most workers in a low-income country."}}},{"id":"P1_U1_MCQ_1338","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1338","question":"Which is an example of internal (organic) growth for a small chain that already runs three cafes in one city and wants to expand without buying another business?","options":{"A":"Buying a rival chain of twelve cafes","B":"Merging with a bakery supplier","C":"Being taken over by a larger restaurant group","D":"Using retained profit to open two more cafes under the same name"},"correctOption":"D","correctAnswer":"Using retained profit to open two more cafes under the same name","questionType":"MCQ","explanation":{"correct_reason":"Organic growth comes from expanding the firm's own operations, such as opening new outlets financed by retained profit, rather than acquiring another business.","distractor_reasons":{"D":"Organic growth comes from expanding the firm's own operations, such as opening new outlets financed by retained profit, rather than acquiring another business.","A":"Buying an existing rival is external growth through a takeover, not expansion from within the firm.","B":"A merger with a supplier is external growth, because it combines the firm with another existing business.","C":"A takeover by another group means the chain becomes part of a larger business rather than growing itself."}}},{"id":"P1_U1_MCQ_1339","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1339","question":"A national railway is owned by the state, run by a board appointed by government and funded mainly from taxation rather than fares. Which type of organisation is it?","options":{"A":"A private limited company","B":"A partnership","C":"A franchise","D":"A public corporation"},"correctOption":"D","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"A public corporation is owned by government, set up by law and funded from public money to provide a service rather than to maximise profit.","distractor_reasons":{"D":"A public corporation is owned by government, set up by law and funded from public money to provide a service rather than to maximise profit.","A":"A private limited company is owned by private shareholders rather than by government and taxpayers, so it is not a state-funded railway.","B":"A partnership is owned by a small group of private partners and is not government-owned or tax-funded.","C":"A franchise is a licence granted to a private operator, not a state-owned railway funded by taxation."}}},{"id":"P1_U1_MCQ_1340","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1340","question":"A bakery buys flour, eggs and packaging from several small firms, all of which depend on being paid within 30 days. Which stakeholder group is most concerned about prompt payment?","options":{"A":"Local residents","B":"Trade unions","C":"Shareholders","D":"Suppliers"},"correctOption":"D","correctAnswer":"Suppliers","questionType":"MCQ","explanation":{"correct_reason":"Suppliers depend on prompt payment to manage their own cash flow, so late payment by a customer business directly harms them.","distractor_reasons":{"D":"Suppliers depend on prompt payment to manage their own cash flow, so late payment by a customer business directly harms them.","A":"Local residents may care about noise or traffic, but they are not waiting for payments from the business.","B":"Trade unions represent employees' pay and conditions, not the payment of the firm's invoices to other businesses.","C":"Shareholders focus on profit and dividends rather than on the timing of payments to individual suppliers."}}},{"id":"P1_U1_MCQ_1341","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1341","question":"Bramblewood Pottery Ltd sells handmade mugs for $12 each. Its clay currently costs $4 per mug. Which change would most directly increase the added value of each mug?","options":{"A":"Paying the potters $1 more per mug","B":"Buying clay of the same quality for $3 per mug","C":"Producing 200 more mugs each week","D":"Reducing the selling price to $11"},"correctOption":"B","correctAnswer":"Buying clay of the same quality for $3 per mug","questionType":"MCQ","explanation":{"correct_reason":"Added value is selling price minus bought-in materials, so cutting clay cost from $4 to $3 raises added value per mug from $8 to $9.","distractor_reasons":{"B":"Added value is selling price minus bought-in materials, so cutting clay cost from $4 to $3 raises added value per mug from $8 to $9.","A":"Higher wages raise the firm's costs and reduce profit, but wages are not bought-in materials, so added value stays at $8.","C":"Selling more mugs raises total added value but does not increase the added value earned on each individual mug.","D":"A lower selling price with the same $4 clay cost cuts added value per mug from $8 to $7 rather than increasing it."}}},{"id":"P1_U1_MCQ_1342","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1342","question":"Dunmere Aggregates Ltd earns $360,000 from quarrying stone, $90,000 from selling concrete blocks and $150,000 from haulage. What percentage of its total revenue comes from secondary activities?","options":{"A":"25%","B":"15%","C":"40%","D":"60%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Total revenue is $600,000 and block making is the secondary activity, so 90,000/600,000 x 100 = 15%, while quarrying is primary and haulage is tertiary.","distractor_reasons":{"B":"Total revenue is $600,000 and block making is the secondary activity, so 90,000/600,000 x 100 = 15%, while quarrying is primary and haulage is tertiary.","A":"25% would be $150,000, which is the haulage revenue from a tertiary service rather than the block-making revenue.","C":"40% would be $240,000, but the secondary revenue from concrete blocks is only $90,000 of the $600,000 total.","D":"60% is the share earned from quarrying, which is a primary activity, not the secondary share."}}},{"id":"P1_U1_MCQ_1343","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1343","question":"A sole trader runs a busy hair salon and earns enough to open a second branch, but she decides to stay in one shop. Which is a likely reason for her choice?","options":{"A":"Expansion always reduces the firm's revenue","B":"She wants to keep personal control and close contact with customers","C":"Larger firms are not allowed to borrow money","D":"Sole traders cannot employ any staff"},"correctOption":"B","correctAnswer":"She wants to keep personal control and close contact with customers","questionType":"MCQ","explanation":{"correct_reason":"Some owners value independence and personal service more than higher sales, so they avoid the loss of control that expansion may bring.","distractor_reasons":{"B":"Some owners value independence and personal service more than higher sales, so they avoid the loss of control that expansion may bring.","A":"Expansion often raises revenue, so an automatic fall is not a valid reason and is not generally true.","C":"Larger firms can borrow, often on better terms, so a legal ban on lending to them does not exist.","D":"Sole traders may employ staff, so this claim is false and does not explain a decision about growth."}}},{"id":"P1_U1_MCQ_1344","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1344","question":"A growing company issues 250,000 new shares at $2.40 each to help fund a new factory. How much capital does the share issue raise in total?","options":{"A":"$104,167","B":"$600,000","C":"$250,000","D":"$625,000"},"correctOption":"B","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"Capital raised equals the number of shares multiplied by the issue price, so 250,000 x $2.40 = $600,000, before any issue costs.","distractor_reasons":{"B":"Capital raised equals the number of shares multiplied by the issue price, so 250,000 x $2.40 = $600,000, before any issue costs.","A":"$104,167 divides the share price by the number of shares instead of multiplying the two figures.","C":"$250,000 treats the number of shares as the money raised and ignores the $2.40 issue price.","D":"$625,000 uses the wrong price; at $2.40 each, the 250,000 shares raise $600,000, not $625,000, so this overstates the capital."}}},{"id":"P1_U1_MCQ_1345","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1345","question":"A company makes profit after tax of $600,000 for the year and pays dividends of $210,000. What percentage of the profit is retained in the business?","options":{"A":"35%","B":"65%","C":"55%","D":"210%"},"correctOption":"B","correctAnswer":"65%","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is $600,000 - $210,000 = $390,000, and 390,000/600,000 x 100 = 65% of profit after tax.","distractor_reasons":{"B":"Retained profit is $600,000 - $210,000 = $390,000, and 390,000/600,000 x 100 = 65% of profit after tax.","A":"35% is the share paid out as dividends, $210,000 of $600,000, not the share retained.","C":"55% does not match the figures, since the $390,000 retained out of $600,000 profit after tax is exactly 65%.","D":"210% would mean retained profit exceeds the whole profit, which is impossible with a $210,000 dividend."}}},{"id":"P1_U1_MCQ_1346","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1346","question":"Which is the most likely disadvantage for a garment factory that introduces extensive division of labour on its production line, with each worker repeating one small stitching task all day?","options":{"A":"Workers must learn every stage of production before starting","B":"Output per worker usually falls sharply at first","C":"Workers may become bored and less motivated by repeating one small task","D":"The firm can no longer use any machinery"},"correctOption":"C","correctAnswer":"Workers may become bored and less motivated by repeating one small task","questionType":"MCQ","explanation":{"correct_reason":"Repeating a single narrow task can cause boredom and low motivation, which may raise absenteeism and reduce the quality of output.","distractor_reasons":{"C":"Repeating a single narrow task can cause boredom and low motivation, which may raise absenteeism and reduce the quality of output.","A":"Division of labour narrows each worker's task, so staff need to learn less rather than every stage of production.","B":"Specialisation generally raises output per worker as tasks are repeated, so a sharp permanent fall is not the expected result.","D":"Division of labour is often combined with machinery on a production line, so it does not prevent the use of equipment."}}},{"id":"P1_U1_MCQ_1347","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1347","question":"A country's state schools, public hospitals and national railway are owned and controlled by government. Which statement about this part of the economy is correct?","options":{"A":"It includes every business that sells shares to the public","B":"It contains only businesses that make a profit","C":"It consists of organisations owned or controlled by government","D":"It is another name for the tertiary sector"},"correctOption":"C","correctAnswer":"It consists of organisations owned or controlled by government","questionType":"MCQ","explanation":{"correct_reason":"The public sector covers organisations owned or controlled by government, such as state schools and public corporations, not private shareholders.","distractor_reasons":{"C":"The public sector covers organisations owned or controlled by government, such as state schools and public corporations, not private shareholders.","A":"Selling shares to the public makes a business a public limited company in the private sector, not part of the public sector.","B":"Many public sector organisations provide services and may make a loss funded by taxation rather than aiming for profit.","D":"The public sector can include primary, secondary and tertiary organisations, so it is not the same as the service sector."}}},{"id":"P1_U1_MCQ_1348","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1348","question":"Marlowe Kitchens Ltd earned revenue of $860,000 from fitted kitchens last year and its total costs were $731,000. What was its profit before any tax is deducted?","options":{"A":"$131,000","B":"$1,591,000","C":"$129,000","D":"$860,000"},"correctOption":"C","correctAnswer":"$129,000","questionType":"MCQ","explanation":{"correct_reason":"Profit is revenue minus total costs, so $860,000 - $731,000 = $129,000 for the year, before any tax is deducted.","distractor_reasons":{"C":"Profit is revenue minus total costs, so $860,000 - $731,000 = $129,000 for the year, before any tax is deducted.","A":"$131,000 does not follow from the figures; the gap between $860,000 and $731,000 is $129,000.","B":"$1,591,000 adds revenue and costs together, but profit is found by subtracting costs from revenue.","D":"$860,000 is the revenue alone and takes no account of the $731,000 of costs incurred."}}},{"id":"P1_U1_MCQ_1349","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1349","question":"Two qualified accountants want to set up together, share the workload and combine their savings, but they are not ready to form a company. Which is an advantage of their partnership?","options":{"A":"The partners gain limited liability automatically","B":"Profits do not have to be shared with anyone","C":"More capital and a wider range of skills can be contributed","D":"The business can sell shares on a stock exchange"},"correctOption":"C","correctAnswer":"More capital and a wider range of skills can be contributed","questionType":"MCQ","explanation":{"correct_reason":"Two partners can pool savings and combine different skills, although a standard partnership still leaves the partners with unlimited liability.","distractor_reasons":{"C":"Two partners can pool savings and combine different skills, although a standard partnership still leaves the partners with unlimited liability.","A":"An ordinary partnership does not give limited liability, so the partners remain personally responsible for debts.","B":"Partnership profits must be shared among the partners, so this is untrue and not an advantage.","D":"Only a public limited company can have its shares traded on a stock exchange, not a partnership."}}},{"id":"P1_U1_MCQ_1350","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1350","question":"A firm's managers want to open five new stores this year, but its shareholders want higher dividends paid now. What does this situation best illustrate?","options":{"A":"A complete agreement between all stakeholders","B":"A fall in the firm's total revenue","C":"A conflict between growth objectives and shareholder objectives","D":"A government decision to nationalise the firm"},"correctOption":"C","correctAnswer":"A conflict between growth objectives and shareholder objectives","questionType":"MCQ","explanation":{"correct_reason":"Expansion uses profit that could be paid as dividends, so the growth aim of managers conflicts with shareholders' wish for immediate income.","distractor_reasons":{"C":"Expansion uses profit that could be paid as dividends, so the growth aim of managers conflicts with shareholders' wish for immediate income.","A":"The two groups want to use the same profit differently, which is a conflict rather than agreement.","B":"No revenue figures are given, and the disagreement concerns how to use profit, not a fall in sales.","D":"Nationalisation is a state takeover of a business, and nothing in the scenario suggests any government involvement or ownership."}}},{"id":"P1_U1_MCQ_1351","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1351","question":"Nettlefold Joinery Ltd owns a workshop that could be rented to another firm for $2,400 a month. Instead it uses the workshop for its own furniture production. What is the monthly opportunity cost of using the workshop?","options":{"A":"$2,400","B":"$0","C":"$1,200","D":"$4,800"},"correctOption":"A","correctAnswer":"$2,400","questionType":"MCQ","explanation":{"correct_reason":"The next best alternative is renting the workshop out for $2,400 a month, so that forgone rent is the opportunity cost of using it internally.","distractor_reasons":{"A":"The next best alternative is renting the workshop out for $2,400 a month, so that forgone rent is the opportunity cost of using it internally.","B":"The workshop could earn rent if let out, so using it internally does involve a real sacrifice and cannot have zero opportunity cost.","C":"Half the monthly rent has no basis in the figures given, and opportunity cost uses the full value of the alternative forgone.","D":"Two months of rent is not the monthly sacrifice; the opportunity cost for one month is the $2,400 that could have been earned."}}},{"id":"P1_U1_MCQ_1352","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1352","question":"A country's service output rose from $280m to $420m while its total output rose from $500m to $600m. By how many percentage points did the tertiary share rise?","options":{"A":"14 percentage points","B":"10 percentage points","C":"20 percentage points","D":"56 percentage points"},"correctOption":"A","correctAnswer":"14 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The service share rose from 280/500 = 56% to 420/600 = 70%, which is an increase of 14 percentage points.","distractor_reasons":{"A":"The service share rose from 280/500 = 56% to 420/600 = 70%, which is an increase of 14 percentage points.","B":"10 points would take the share from 56% to 66%, but the new share is 70%, so the rise is larger.","C":"20 points would give 76%, which is above the 70% service share calculated from the new figures.","D":"56% is the original service share, not the change in that share between the two years."}}},{"id":"P1_U1_MCQ_1353","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1353","question":"Two rival bus companies that serve the same city agree to merge into a single firm. Which is the most likely benefit of this horizontal merger?","options":{"A":"A larger market share and the chance to cut duplicate routes","B":"Guaranteed lower fares for every passenger","C":"Complete freedom from government regulation","D":"The removal of all fixed costs"},"correctOption":"A","correctAnswer":"A larger market share and the chance to cut duplicate routes","questionType":"MCQ","explanation":{"correct_reason":"Combining two competitors raises market share and allows duplicate routes, depots and administration to be cut, though fares are not guaranteed to fall.","distractor_reasons":{"A":"Combining two competitors raises market share and allows duplicate routes, depots and administration to be cut, though fares are not guaranteed to fall.","B":"A merger can reduce competition, and lower fares are not guaranteed; they may even rise if competition weakens.","C":"Bus services remain regulated, and a merger does not exempt the combined firm from safety or competition rules.","D":"Merging may reduce some duplicate costs, but depots, vehicles and insurance still involve fixed costs."}}},{"id":"P1_U1_MCQ_1354","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1354","question":"Two independent construction firms each contribute capital and expertise to a single wind farm project, sharing its costs, risks and profits for ten years. Which arrangement is this?","options":{"A":"They share the project's costs, risks and profits but remain separate businesses","B":"One firm must buy all the shares of the other","C":"The two firms become a single public corporation","D":"The project is owned entirely by the government"},"correctOption":"A","correctAnswer":"They share the project's costs, risks and profits but remain separate businesses","questionType":"MCQ","explanation":{"correct_reason":"In a joint venture, independent firms create a shared project, dividing investment, risk and returns while each keeps its separate legal identity.","distractor_reasons":{"A":"In a joint venture, independent firms create a shared project, dividing investment, risk and returns while each keeps its separate legal identity.","B":"That describes a takeover, whereas a joint venture leaves both firms independent and sharing a project.","C":"A joint venture does not merge the firms into a state-owned corporation; they remain separate private businesses.","D":"A joint venture between two firms is privately owned unless government is itself one of the partners."}}},{"id":"P1_U1_MCQ_1355","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1355","question":"A hospital is owned by the government, funded from taxation and treats patients free of charge. Which objective is most likely to guide its managers?","options":{"A":"Providing accessible treatment to patients rather than maximising profit","B":"Maximising dividends for private shareholders","C":"Reducing the number of patients treated each year","D":"Selling the hospital to the highest bidder"},"correctOption":"A","correctAnswer":"Providing accessible treatment to patients rather than maximising profit","questionType":"MCQ","explanation":{"correct_reason":"Public hospitals aim to provide accessible healthcare as a service, with funding from government rather than profit from patients or shareholders.","distractor_reasons":{"A":"Public hospitals aim to provide accessible healthcare as a service, with funding from government rather than profit from patients or shareholders.","B":"A government-owned hospital has no private shareholders, so paying dividends to them cannot be one of its objectives.","C":"Public health providers aim to treat patients who need care, not to turn them away.","D":"Selling the hospital would remove it from public ownership and is not an operating objective."}}},{"id":"P1_U1_MCQ_1356","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1356","question":"A laundry business owns washing machines, a delivery van and a building, and it employs eight staff. Which of these items is capital as a factor of production?","options":{"A":"The water used in the washing machines","B":"The wages paid to the laundry staff","C":"The owner's idea for a new service","D":"The delivery van used to collect linen"},"correctOption":"D","correctAnswer":"The delivery van used to collect linen","questionType":"MCQ","explanation":{"correct_reason":"Capital means manufactured goods used to produce other goods or services, such as the delivery van, rather than water, labour or enterprise.","distractor_reasons":{"D":"Capital means manufactured goods used to produce other goods or services, such as the delivery van, rather than water, labour or enterprise.","A":"Water is a natural resource used up in the process, so it belongs to land rather than to capital.","B":"Wages are the payment for labour, which is human effort, not a manufactured good used in production.","C":"An idea is part of enterprise and risk-taking, not a physical manufactured asset used to produce output."}}},{"id":"P1_U1_MCQ_1357","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1357","question":"Aldergrove Minerals Ltd blasts copper ore from an open pit, crushes it on site and loads the untreated rock onto ships for export. Which sector does this activity belong to?","options":{"A":"Refining copper into wire","B":"Designing electrical circuits","C":"Selling copper fittings in a shop","D":"Mining copper ore"},"correctOption":"D","correctAnswer":"Mining copper ore","questionType":"MCQ","explanation":{"correct_reason":"Mining extracts a raw material from the earth, which is a primary activity, while refining, designing and retailing are secondary or tertiary.","distractor_reasons":{"D":"Mining extracts a raw material from the earth, which is a primary activity, while refining, designing and retailing are secondary or tertiary.","A":"Refining transforms the ore into a manufactured product, which is a secondary activity rather than primary extraction.","B":"Designing circuits is a professional service, so it belongs to the tertiary sector rather than to primary production.","C":"Retailing is a service that distributes goods to customers, which places it in the tertiary sector."}}},{"id":"P1_U1_MCQ_1358","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1358","question":"Firm A has 240 employees and revenue of $4m. Firm B has 180 employees and revenue of $5m. Using revenue as the measure, how much larger is Firm B?","options":{"A":"$1m smaller","B":"$2m larger","C":"The same size","D":"$1m larger"},"correctOption":"D","correctAnswer":"$1m larger","questionType":"MCQ","explanation":{"correct_reason":"On revenue, Firm B's $5m exceeds Firm A's $4m by $1m, even though Firm B employs fewer people, so revenue ranks Firm B as larger.","distractor_reasons":{"D":"On revenue, Firm B's $5m exceeds Firm A's $4m by $1m, even though Firm B employs fewer people, so revenue ranks Firm B as larger.","A":"The direction is wrong: $5m is greater than $4m, so Firm B is larger on revenue, not smaller.","B":"$2m would require Firm B to have revenue of $6m, but its stated revenue is $5m.","C":"The two revenues differ by $1m, so they are not the same size when revenue is the chosen measure."}}},{"id":"P1_U1_MCQ_1359","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1359","question":"Partners A and B agree that A receives a salary of $30,000, with the remaining profit shared equally. The partnership makes a profit of $110,000. What is A's total income from the partnership?","options":{"A":"$55,000","B":"$80,000","C":"$110,000","D":"$70,000"},"correctOption":"D","correctAnswer":"$70,000","questionType":"MCQ","explanation":{"correct_reason":"After A's $30,000 salary, $80,000 remains and is split equally at $40,000 each, so A receives $30,000 + $40,000 = $70,000.","distractor_reasons":{"D":"After A's $30,000 salary, $80,000 remains and is split equally at $40,000 each, so A receives $30,000 + $40,000 = $70,000.","A":"$55,000 splits the whole profit equally and ignores A's separate $30,000 salary entitlement, which is paid before the remaining profit is shared.","B":"$80,000 is the profit remaining after the salary, before it is shared between the two partners.","C":"$110,000 is the entire partnership profit, which must also provide B's share of the remaining profit."}}},{"id":"P1_U1_MCQ_1360","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1360","question":"A firm's annual revenue rose by 8% over the year to reach $540,000. What was its revenue at the start of the year, before the increase?","options":{"A":"$432,000","B":"$496,800","C":"$583,200","D":"$500,000"},"correctOption":"D","correctAnswer":"$500,000","questionType":"MCQ","explanation":{"correct_reason":"Last year's revenue is the amount that grows by 8% to $540,000, so 540,000/1.08 = $500,000 at the start of the year.","distractor_reasons":{"D":"Last year's revenue is the amount that grows by 8% to $540,000, so 540,000/1.08 = $500,000 at the start of the year.","A":"$432,000 applies an 8% fall rather than reversing an 8% rise, so it is below the correct starting figure.","B":"$496,800 subtracts 8% of $540,000, but the 8% growth was calculated on the smaller original amount.","C":"$583,200 adds 8% to $540,000, which grows the figure again instead of reversing the increase."}}},{"id":"P1_U1_MCQ_1361","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1361","question":"Kenya's households want more food, housing and healthcare than they can afford, but the country has only limited farmland, skilled workers and machinery. Which basic economic problem does this describe?","options":{"A":"Specialisation","B":"Scarcity","C":"Inflation","D":"A trade surplus"},"correctOption":"B","correctAnswer":"Scarcity","questionType":"MCQ","explanation":{"correct_reason":"Resources are limited while wants are unlimited, which is the economic problem of scarcity that forces every economy to make choices.","distractor_reasons":{"B":"Resources are limited while wants are unlimited, which is the economic problem of scarcity that forces every economy to make choices.","A":"Specialisation is concentrating on particular tasks or products, not the mismatch between unlimited wants and limited resources.","C":"Inflation is a sustained rise in prices, and no price changes are described in the scenario about limited farmland and machinery.","D":"A trade surplus means exports exceed imports, which is unrelated to the shortage of resources compared with households' wants."}}},{"id":"P1_U1_MCQ_1362","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1362","question":"A country has 12 million workers. Of these, 45% work in primary activities and 30% in secondary activities. How many workers are employed in the tertiary sector?","options":{"A":"3.6 million","B":"3 million","C":"5.4 million","D":"9 million"},"correctOption":"B","correctAnswer":"3 million","questionType":"MCQ","explanation":{"correct_reason":"Tertiary workers are 100 - 45 - 30 = 25% of 12 million, which equals 3 million people, or one quarter of the workforce.","distractor_reasons":{"B":"Tertiary workers are 100 - 45 - 30 = 25% of 12 million, which equals 3 million people, or one quarter of the workforce.","A":"3.6 million is 30% of 12 million, which is the secondary sector's workforce rather than the tertiary total.","C":"5.4 million is 45% of 12 million, the primary sector's workforce, not the number in tertiary activities.","D":"9 million is the combined primary and secondary workforce, leaving only 3 million for the tertiary sector."}}},{"id":"P1_U1_MCQ_1363","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1363","question":"A new restaurant is full every evening, yet it runs out of cash within a year and closes. Which is the most likely explanation for its failure?","options":{"A":"It has too many paying customers each evening","B":"Its cash flow is poor because customers pay later while suppliers and wages must be paid now","C":"It keeps complete records of every sale","D":"It charges prices that cover all its costs"},"correctOption":"B","correctAnswer":"Its cash flow is poor because customers pay later while suppliers and wages must be paid now","questionType":"MCQ","explanation":{"correct_reason":"A firm can be profitable on paper yet run out of cash when payments are delayed, so poor cash flow commonly causes early failure.","distractor_reasons":{"B":"A firm can be profitable on paper yet run out of cash when payments are delayed, so poor cash flow commonly causes early failure.","A":"Strong customer numbers usually help a restaurant cover its costs, so having plenty of diners would not normally be the cause of failure.","C":"Accurate records support good management and control, so keeping complete sales records is unlikely to make a restaurant run out of cash.","D":"Prices covering all costs should support profitability, so this is not a plausible cause of failure."}}},{"id":"P1_U1_MCQ_1364","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1364","question":"A self-employed electrician works alone, funds tools from personal savings and has no business partners or shareholders. Which is a disadvantage of this sole trader arrangement?","options":{"A":"The owner must publish annual accounts for the public","B":"Raising finance is limited and personal assets are at risk","C":"Profits are taxed twice, once for the firm and once for the owner","D":"The owner cannot make decisions quickly"},"correctOption":"B","correctAnswer":"Raising finance is limited and personal assets are at risk","questionType":"MCQ","explanation":{"correct_reason":"A sole trader relies mainly on personal savings and loans, and because there is no limited liability, personal assets can be lost.","distractor_reasons":{"B":"A sole trader relies mainly on personal savings and loans, and because there is no limited liability, personal assets can be lost.","A":"Sole traders do not have to publish accounts publicly, so this is not a disadvantage they face.","C":"Sole trader profits are taxed once as the owner's income, so double taxation does not apply.","D":"A sole trader can usually decide quickly because there are no partners or board to consult."}}},{"id":"P1_U1_MCQ_1365","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1365","question":"A clothing factory installs a new water treatment plant and funds apprenticeships at the local college, going beyond what the law requires. Which action best demonstrates corporate social responsibility?","options":{"A":"Paying suppliers as late as legally possible","B":"Funding apprenticeships at a local college","C":"Ignoring complaints about factory noise","D":"Cutting all staff training to raise profit"},"correctOption":"B","correctAnswer":"Funding apprenticeships at a local college","questionType":"MCQ","explanation":{"correct_reason":"Sponsoring apprenticeships benefits the local community and workforce beyond the firm's legal duties, which is the essence of social responsibility.","distractor_reasons":{"B":"Sponsoring apprenticeships benefits the local community and workforce beyond the firm's legal duties, which is the essence of social responsibility.","A":"Late payment harms suppliers' cash flow and shows little social responsibility, even if it is legal.","C":"Ignoring neighbours' complaints about noise damages the local community and is the opposite of responsible behaviour for a firm.","D":"Cutting training harms employees' development in return for short-term profit, which is not a socially responsible action."}}},{"id":"P1_U1_MCQ_1366","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1366","question":"Ellerby Glassworks Ltd uses 8 tonnes of sand at $45 a tonne to make 1,000 bottles, which it sells for $0.90 each. What is the total added value of this batch?","options":{"A":"$360","B":"$900","C":"$540","D":"$1,260"},"correctOption":"C","correctAnswer":"$540","questionType":"MCQ","explanation":{"correct_reason":"Revenue is 1,000 x $0.90 = $900 and bought-in sand costs 8 x $45 = $360, so added value is $900 - $360 = $540.","distractor_reasons":{"C":"Revenue is 1,000 x $0.90 = $900 and bought-in sand costs 8 x $45 = $360, so added value is $900 - $360 = $540.","A":"$360 is only the cost of the sand bought in, not the value the firm adds by turning it into bottles.","B":"$900 is the sales revenue of the batch, which ignores the $360 cost of bought-in materials that must be deducted.","D":"$1,260 adds revenue to material cost instead of subtracting, so it cannot represent the value added by production."}}},{"id":"P1_U1_MCQ_1367","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1367","question":"A sawmill cuts timber, a builder uses the timber to construct a house and the builder's client pays a surveyor to inspect the work. Which example of interdependence does this describe?","options":{"A":"A farmer grows wheat and sells it directly at a roadside stall","B":"A factory makes all its own components and delivers them itself","C":"A sawmill sells timber to a builder, which hires a surveyor for its client","D":"A government raises the rate of income tax"},"correctOption":"C","correctAnswer":"A sawmill sells timber to a builder, which hires a surveyor for its client","questionType":"MCQ","explanation":{"correct_reason":"The sawmill is primary, the builder secondary and the surveyor tertiary, so each stage depends on the output or service of another sector.","distractor_reasons":{"C":"The sawmill is primary, the builder secondary and the surveyor tertiary, so each stage depends on the output or service of another sector.","A":"This example stays within primary production and direct selling, so it does not show links across all three sectors.","B":"Keeping every stage inside one firm reduces interdependence with other sectors rather than demonstrating it.","D":"A tax change is a government policy measure, not an example of production stages relying on one another."}}},{"id":"P1_U1_MCQ_1368","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1368","question":"Last year a firm sold 20,000 units in a market of 160,000. This year it sold 30,000 in a market of 200,000. By how many percentage points did its market share rise?","options":{"A":"5 percentage points","B":"10 percentage points","C":"2.5 percentage points","D":"15 percentage points"},"correctOption":"C","correctAnswer":"2.5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Market share rose from 20,000/160,000 = 12.5% to 30,000/200,000 = 15%, which is a rise of 2.5 percentage points.","distractor_reasons":{"C":"Market share rose from 20,000/160,000 = 12.5% to 30,000/200,000 = 15%, which is a rise of 2.5 percentage points.","A":"5 points would take the share to 17.5%, but the new share is 15%, so the rise is smaller.","B":"10 points would almost double the old share, yet the firm moved only from 12.5% to 15%.","D":"15% is the new market share itself, not the increase in the share between the two years."}}},{"id":"P1_U1_MCQ_1369","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1369","question":"When a private limited company is sued, the company itself is taken to court rather than its shareholders personally. Which feature of this business form does this illustrate?","options":{"A":"A sole trader","B":"An ordinary partnership","C":"A private limited company","D":"An unincorporated club"},"correctOption":"C","correctAnswer":"A private limited company","questionType":"MCQ","explanation":{"correct_reason":"Incorporation creates a separate legal identity, so the company itself can own assets, sign contracts and be sued, independently of its shareholders.","distractor_reasons":{"C":"Incorporation creates a separate legal identity, so the company itself can own assets, sign contracts and be sued, independently of its shareholders.","A":"A sole trader and the owner are the same legal person, so there is no separate legal identity.","B":"An ordinary partnership is unincorporated, so the partners and the business are not legally separate.","D":"An unincorporated club has no separate legal identity, and its members may be personally responsible."}}},{"id":"P1_U1_MCQ_1370","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1370","question":"A bakery's bank refuses a loan for a second shop because of weak sales forecasts. Which objective is the bakery most likely to adopt instead?","options":{"A":"Maximising market share within one year","B":"Selling shares on the stock exchange","C":"Growing more slowly using retained profit","D":"Closing the business immediately"},"correctOption":"C","correctAnswer":"Growing more slowly using retained profit","questionType":"MCQ","explanation":{"correct_reason":"Without loan finance, rapid expansion is unlikely, so the bakery may use retained profit to grow gradually within its existing means.","distractor_reasons":{"C":"Without loan finance, rapid expansion is unlikely, so the bakery may use retained profit to grow gradually within its existing means.","A":"A rapid market share push usually needs finance the bakery has just been refused, so it is unrealistic.","B":"A small bakery is not a public limited company and cannot quickly list shares to raise funds.","D":"A refused expansion loan does not make the existing bakery unviable, so immediate closure is an overreaction."}}},{"id":"P1_U1_MCQ_1371","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1371","question":"A country's households are earning higher real incomes than five years ago and can now afford foreign holidays and smart phones. Which change best explains this growth in their wants?","options":{"A":"Rising incomes that make holidays and smart phones affordable","B":"A fall in the population of the country","C":"A government ban on advertising","D":"A rise in the price of basic food"},"correctOption":"A","correctAnswer":"Rising incomes that make holidays and smart phones affordable","questionType":"MCQ","explanation":{"correct_reason":"As incomes rise, households can afford more goods and services beyond basic needs, so their wants expand to include luxuries.","distractor_reasons":{"A":"As incomes rise, households can afford more goods and services beyond basic needs, so their wants expand to include luxuries.","B":"Fewer households would reduce total demand, and population change does not by itself make each household want more goods.","C":"Less advertising would tend to reduce awareness of products, which is more likely to limit wants than to increase them.","D":"Higher food prices reduce the income left for other purchases, so households would satisfy fewer wants rather than more."}}},{"id":"P1_U1_MCQ_1372","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1372","question":"In a developed economy households now spend a larger share of their rising incomes on tourism, insurance and eating out. Which factor most explains the growth of the tertiary sector?","options":{"A":"Higher incomes and more leisure time increase demand for services","B":"Falling incomes force households to buy fewer goods","C":"Machines have replaced most service workers","D":"Governments have closed most schools and hospitals"},"correctOption":"A","correctAnswer":"Higher incomes and more leisure time increase demand for services","questionType":"MCQ","explanation":{"correct_reason":"Rising incomes and more leisure time shift household spending towards services such as tourism, retail and finance, expanding tertiary activity.","distractor_reasons":{"A":"Rising incomes and more leisure time shift household spending towards services such as tourism, retail and finance, expanding tertiary activity.","B":"Falling incomes would reduce demand for services too, and developed economies have generally seen rising rather than falling incomes.","C":"Machines have mainly replaced routine production tasks, and many services still require personal contact and judgement.","D":"Closing schools and hospitals would shrink public services and reduce tertiary employment rather than expand it."}}},{"id":"P1_U1_MCQ_1373","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1373","question":"A rival launches a cheaper version of a product that a small firm sells. Which characteristic would most help the firm's owner respond quickly to this threat?","options":{"A":"Willingness to take calculated risks and try new ideas","B":"A preference for keeping every procedure unchanged","C":"A refusal to listen to customer complaints","D":"A decision to avoid all contact with suppliers"},"correctOption":"A","correctAnswer":"Willingness to take calculated risks and try new ideas","questionType":"MCQ","explanation":{"correct_reason":"Entrepreneurs who accept calculated risk can redesign products or change prices quickly, which helps them respond to a new competitor.","distractor_reasons":{"A":"Entrepreneurs who accept calculated risk can redesign products or change prices quickly, which helps them respond to a new competitor.","B":"Refusing to change procedures would leave the firm exposed to the cheaper rival rather than helping it respond.","C":"Ignoring complaints hides useful information about why customers might switch to the cheaper rival, which makes a quick response much harder.","D":"Suppliers provide inputs and ideas for cost savings, so cutting contact would weaken the firm's response."}}},{"id":"P1_U1_MCQ_1374","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1374","question":"A company makes profit after tax of $250,000 for the year and decides to retain 60% of it. What total dividend does it pay to shareholders?","options":{"A":"$100,000","B":"$150,000","C":"$250,000","D":"$400,000"},"correctOption":"A","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is 60% of $250,000 = $150,000, so the dividend paid is the remaining 40%, which equals $100,000.","distractor_reasons":{"A":"Retained profit is 60% of $250,000 = $150,000, so the dividend paid is the remaining 40%, which equals $100,000.","B":"$150,000 is the amount retained in the business, not the dividend paid out to shareholders.","C":"$250,000 is the whole profit after tax, which ignores the decision to retain 60% of it.","D":"$400,000 exceeds the profit itself, so the company cannot pay a dividend of that size."}}},{"id":"P1_U1_MCQ_1375","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1375","question":"A firm makes a profit of $240,000. It uses 40% for dividends, 35% for retained profit and the rest for an employee bonus. How much is the employee bonus?","options":{"A":"$60,000","B":"$84,000","C":"$96,000","D":"$144,000"},"correctOption":"A","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Dividends and retained profit use 40% + 35% = 75%, leaving 25% of $240,000 = $60,000 for the employee bonus.","distractor_reasons":{"A":"Dividends and retained profit use 40% + 35% = 75%, leaving 25% of $240,000 = $60,000 for the employee bonus.","B":"$84,000 is 35% of profit, which is the retained profit rather than the employee bonus.","C":"$96,000 is 40% of profit, which is the dividend paid to shareholders, not the bonus.","D":"$144,000 combines the dividend and retained profit, which together use 75% of the profit, leaving only $60,000 for employees."}}},{"id":"P1_U1_MCQ_1376","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1376","question":"A bicycle frame maker divides production so that each employee repeatedly performs one welding task. Which is a benefit of this specialisation for the business?","options":{"A":"The business becomes independent of all other firms","B":"Workers become more skilled at one task, raising output per worker","C":"Every worker can easily cover any absent colleague's job","D":"The firm no longer needs to train its employees"},"correctOption":"B","correctAnswer":"Workers become more skilled at one task, raising output per worker","questionType":"MCQ","explanation":{"correct_reason":"Repeating one task builds skill and speed, so specialisation usually raises labour productivity and lowers the average cost of each unit produced.","distractor_reasons":{"B":"Repeating one task builds skill and speed, so specialisation usually raises labour productivity and lowers the average cost of each unit produced.","A":"Specialised firms usually depend more on other businesses for components and services, so independence is not a benefit.","C":"Narrow specialised training can make it harder to cover absent colleagues, which is a disadvantage rather than a benefit.","D":"Specialised workers still need training in their particular task, and skills must be maintained as methods change."}}},{"id":"P1_U1_MCQ_1377","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1377","question":"In a high-income country, finance, health, education, tourism and retail together produce far more output than farming or manufacturing. Which sector is largest by value of national output?","options":{"A":"Primary","B":"Secondary","C":"The public sector","D":"Tertiary"},"correctOption":"D","correctAnswer":"Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Services such as finance, health, education and retail dominate output in high-income economies, so the tertiary sector is largest by value.","distractor_reasons":{"D":"Services such as finance, health, education and retail dominate output in high-income economies, so the tertiary sector is largest by value.","A":"Primary production such as farming and mining provides only a small share of output in high-income economies.","B":"Manufacturing's share has generally fallen in high-income countries as services have expanded, so it is not the largest.","C":"The public sector cuts across all three production sectors and is not one of the sector categories used in national output."}}},{"id":"P1_U1_MCQ_1378","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1378","question":"One company buys enough shares to control another with the agreement of its board; in a different deal two firms agree to combine as equals. What is the difference between these deals?","options":{"A":"A merger always involves a sole trader, while a takeover involves a company","B":"A takeover creates a new firm, while a merger never changes ownership","C":"A merger is illegal, while a takeover is always approved","D":"A merger is agreed between two firms, while a takeover is one firm buying control of another"},"correctOption":"D","correctAnswer":"A merger is agreed between two firms, while a takeover is one firm buying control of another","questionType":"MCQ","explanation":{"correct_reason":"In a merger the owners of two firms agree to combine, whereas in a takeover the acquiring firm buys enough shares to control the target.","distractor_reasons":{"D":"In a merger the owners of two firms agree to combine, whereas in a takeover the acquiring firm buys enough shares to control the target.","A":"Mergers usually involve companies, and a sole trader cannot merge in the same way, so this distinction is inaccurate.","B":"Both change ownership, and a takeover does not necessarily create a new firm, so the statement is reversed.","C":"Mergers are legal and may need approval, while takeovers can be blocked, so neither absolute claim is correct."}}},{"id":"P1_U1_MCQ_1379","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1379","question":"A former office worker buys a sandwich franchise, pays an initial fee and an ongoing royalty, and must follow the franchisor's menu and branding. Which is a disadvantage for her?","options":{"A":"The franchisee cannot use the franchisor's brand","B":"The franchisee receives no training or support","C":"The franchisee must invent every product from scratch","D":"Royalty payments reduce the profit kept from each sale"},"correctOption":"D","correctAnswer":"Royalty payments reduce the profit kept from each sale","questionType":"MCQ","explanation":{"correct_reason":"Franchisees usually pay an ongoing royalty based on revenue, which lowers the profit they keep, and they must follow the franchisor's rules.","distractor_reasons":{"D":"Franchisees usually pay an ongoing royalty based on revenue, which lowers the profit they keep, and they must follow the franchisor's rules.","A":"Using the established brand is a main benefit of a franchise, so this states the opposite of the arrangement.","B":"Franchisors normally provide training and support, which is one reason people buy a franchise, so a lack of training is not a disadvantage here.","C":"Franchisees sell the franchisor's established products rather than inventing their own range, so being forced to create new products is not the issue."}}},{"id":"P1_U1_MCQ_1380","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1380","question":"A primary school is funded by the state, charges no fees and reports to a local education authority. Which objective is most likely to be set for it?","options":{"A":"Maximising profit for its owners","B":"Increasing its share price on the stock exchange","C":"Paying the highest dividend in its industry","D":"Improving pupils' literacy levels within the available budget"},"correctOption":"D","correctAnswer":"Improving pupils' literacy levels within the available budget","questionType":"MCQ","explanation":{"correct_reason":"A state school pursues educational and social aims with public funding, not profit, share price or dividends for owners or private investors.","distractor_reasons":{"D":"A state school pursues educational and social aims with public funding, not profit, share price or dividends for owners or private investors.","A":"A state-funded school is not run to generate profit for owners, and its funding comes from government.","B":"A state school has no shares and is not listed on a stock exchange, so it has no share price.","C":"Schools do not pay dividends, and a state school has no shareholders to receive them."}}},{"id":"P1_U1_MCQ_1381","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1381","question":"Orchardbrook Cider Ltd employs 6 workers who together press 4,800 litres of juice a week. After new training, each worker presses 950 litres a week. How many extra litres does the firm produce each week?","options":{"A":"950 litres","B":"5,700 litres","C":"900 litres","D":"6,900 litres"},"correctOption":"C","correctAnswer":"900 litres","questionType":"MCQ","explanation":{"correct_reason":"New output is 6 x 950 = 5,700 litres, so the increase is 5,700 - 4,800 = 900 litres a week.","distractor_reasons":{"C":"New output is 6 x 950 = 5,700 litres, so the increase is 5,700 - 4,800 = 900 litres a week.","A":"950 litres is one worker's new weekly output, not the extra output of the whole team after training.","B":"5,700 litres is the new total weekly output, which includes the 4,800 litres already produced before training.","D":"6,900 litres adds the old and new totals together, but the increase is found by subtracting the old output."}}},{"id":"P1_U1_MCQ_1382","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1382","question":"In a mixed economy some services are funded by taxation and run by government while others are sold by private firms. Which service is most likely to be provided by the public sector?","options":{"A":"Hairdressing","B":"National defence","C":"Smartphone manufacture","D":"Restaurant meals"},"correctOption":"B","correctAnswer":"National defence","questionType":"MCQ","explanation":{"correct_reason":"National defence is funded by taxation and provided by government for the whole country, while the other examples are private sector businesses.","distractor_reasons":{"B":"National defence is funded by taxation and provided by government for the whole country, while the other examples are private sector businesses.","A":"Hairdressing is a competitive personal service usually supplied by private salons that charge customers directly, so it is not normally a public sector service.","C":"Smartphone manufacture is carried out by private companies competing in consumer electronics markets, so it belongs to the private sector rather than government.","D":"Restaurant meals are sold by private businesses, and governments do not normally provide them as a public service."}}},{"id":"P1_U1_MCQ_1383","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1383","question":"Analysts want to compare the stock market value of two companies by multiplying each company's share price by its number of issued shares. Which measure are they using?","options":{"A":"Market share","B":"Market capitalisation","C":"Working capital","D":"Share capital"},"correctOption":"B","correctAnswer":"Market capitalisation","questionType":"MCQ","explanation":{"correct_reason":"Market capitalisation values all issued shares at the current market price, giving the stock market's view of the company's size, and it changes daily.","distractor_reasons":{"B":"Market capitalisation values all issued shares at the current market price, giving the stock market's view of the company's size, and it changes daily.","A":"Market share compares a firm's sales with total market sales, not its share price with the number of shares.","C":"Working capital is current assets minus current liabilities, a liquidity measure rather than a valuation of shares.","D":"Share capital is the original money raised from issuing shares, not their current market value multiplied by the number in issue."}}},{"id":"P1_U1_MCQ_1384","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1384","question":"Two friends setting up a garden centre want limited liability and want to keep ownership within their families, without offering shares to the public. Which form is most suitable?","options":{"A":"Public limited company","B":"Private limited company","C":"Ordinary partnership","D":"Sole trader"},"correctOption":"B","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives limited liability and a separate identity while shares stay private, unlike a PLC or an ordinary partnership.","distractor_reasons":{"B":"A private limited company gives limited liability and a separate identity while shares stay private, unlike a PLC or an ordinary partnership.","A":"A PLC offers shares to the public, which the friends explicitly want to avoid, so it does not meet their wishes.","C":"An ordinary partnership does not give limited liability, so the friends' personal assets would remain at risk.","D":"A sole trader has unlimited liability and only one owner, so it cannot give two friends limited liability."}}},{"id":"P1_U1_MCQ_1385","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1385","question":"A company's annual report lists its shareholders, its employees and the suppliers who depend on its orders. Which statement correctly distinguishes shareholders from the other stakeholders?","options":{"A":"Shareholders are customers who buy the company's products","B":"Shareholders own part of the company and expect dividends, while other stakeholders are affected by its actions","C":"Shareholders have no financial interest in the company","D":"Other stakeholders legally own the company's shares"},"correctOption":"B","correctAnswer":"Shareholders own part of the company and expect dividends, while other stakeholders are affected by its actions","questionType":"MCQ","explanation":{"correct_reason":"Shareholders hold shares, giving them part-ownership and a claim on dividends, whereas stakeholders such as employees or suppliers are affected without owning shares.","distractor_reasons":{"B":"Shareholders hold shares, giving them part-ownership and a claim on dividends, whereas stakeholders such as employees or suppliers are affected without owning shares.","A":"Customers may also be stakeholders, but buying products does not make them shareholders or part-owners.","C":"Shareholders have a direct financial interest through share value and dividends, so this is the opposite of the truth.","D":"Employees, suppliers and residents generally do not own shares, so they are not legal owners of the company."}}},{"id":"P1_U1_MCQ_1386","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1386","question":"A household's weekly spending includes bread, clean drinking water, a cinema ticket and a designer handbag. Which of these items is a need rather than a want for the household?","options":{"A":"A cinema ticket","B":"A designer handbag","C":"A foreign holiday","D":"Clean drinking water"},"correctOption":"D","correctAnswer":"Clean drinking water","questionType":"MCQ","explanation":{"correct_reason":"Clean drinking water is essential for survival, whereas cinema tickets, designer handbags and foreign holidays are non-essential wants that can be postponed.","distractor_reasons":{"D":"Clean drinking water is essential for survival, whereas cinema tickets, designer handbags and foreign holidays are non-essential wants that can be postponed.","A":"A cinema ticket provides entertainment and can be given up without harm, so it is a want rather than a need.","B":"A designer handbag is a luxury that is not required for survival or basic wellbeing, so it is clearly a want.","C":"A foreign holiday is a discretionary purchase that households can postpone, which makes it a want rather than a need."}}},{"id":"P1_U1_MCQ_1387","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1387","question":"A town had 4,500 secondary sector jobs. After a factory closure, 1,350 of those jobs were lost. What percentage of the town's secondary jobs remained?","options":{"A":"30%","B":"65%","C":"70%","D":"135%"},"correctOption":"C","correctAnswer":"70%","questionType":"MCQ","explanation":{"correct_reason":"Remaining jobs are 4,500 - 1,350 = 3,150, so 3,150/4,500 x 100 = 70% of the original secondary jobs remained.","distractor_reasons":{"C":"Remaining jobs are 4,500 - 1,350 = 3,150, so 3,150/4,500 x 100 = 70% of the original secondary jobs remained.","A":"30% is the proportion of jobs lost, 1,350 out of 4,500, not the proportion that remained.","B":"65% does not match the figures, because the 3,150 remaining jobs out of the original 4,500 are exactly 70%, so this option is too low.","D":"135% is impossible, because the remaining jobs cannot exceed the 4,500 jobs that existed before the closure."}}},{"id":"P1_U1_MCQ_1388","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1388","question":"A young couple are applying for a loan to start an online clothing shop and must submit a business plan to the bank. Which document is most likely to appear in that plan?","options":{"A":"The final audited accounts for the first five years","B":"A list of every customer who will ever buy","C":"A cash flow forecast for the first twelve months","D":"The company's income tax return for last year"},"correctOption":"C","correctAnswer":"A cash flow forecast for the first twelve months","questionType":"MCQ","explanation":{"correct_reason":"A new business has no trading history, so a plan includes forecasts such as projected cash flow, sales and costs to show viability.","distractor_reasons":{"C":"A new business has no trading history, so a plan includes forecasts such as projected cash flow, sales and costs to show viability.","A":"A new business has not traded for five years, so final audited accounts for that period cannot exist yet.","B":"Future customers cannot be listed in advance, although the plan may estimate target market size.","D":"A start-up has no previous year's tax return, and a plan looks forward rather than reporting past tax."}}},{"id":"P1_U1_MCQ_1389","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1389","question":"Two partners want to open five new branches but their bank will lend only a small sum and they cannot sell shares. Why might the partnership struggle to raise large amounts of finance?","options":{"A":"Partners are legally barred from contributing capital","B":"Banks may not lend to any business with fewer than 100 owners","C":"Its unlimited liability and lack of share issue make lenders and investors cautious","D":"A partnership cannot open a bank account"},"correctOption":"C","correctAnswer":"Its unlimited liability and lack of share issue make lenders and investors cautious","questionType":"MCQ","explanation":{"correct_reason":"Partners face unlimited liability and cannot sell shares to the public, so the funds available are limited to partners' capital and loans.","distractor_reasons":{"C":"Partners face unlimited liability and cannot sell shares to the public, so the funds available are limited to partners' capital and loans.","A":"Partners can and normally do contribute capital to their business, so a legal bar preventing partners from investing does not exist.","B":"Banks lend to small partnerships regularly, and no minimum owner rule of that kind exists.","D":"Partnerships can open and hold bank accounts, so an inability to bank does not explain why raising large amounts of finance is difficult."}}},{"id":"P1_U1_MCQ_1390","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1390","question":"A firm wants to raise its market share from 12% to 15% in a market of 500,000 units. How many extra units must it sell?","options":{"A":"60,000 units","B":"75,000 units","C":"15,000 units","D":"150,000 units"},"correctOption":"C","correctAnswer":"15,000 units","questionType":"MCQ","explanation":{"correct_reason":"The rise is 15% - 12% = 3 percentage points, and 0.03 x 500,000 = 15,000 extra units must be sold.","distractor_reasons":{"C":"The rise is 15% - 12% = 3 percentage points, and 0.03 x 500,000 = 15,000 extra units must be sold.","A":"60,000 is 12% of the market, the firm's current sales, not the additional sales needed.","B":"75,000 is 15% of the market, the target level of sales, which includes the current 60,000.","D":"150,000 is 30% of the 500,000-unit market, far more than the 3 percentage point rise requires."}}},{"id":"P1_U1_MCQ_1391","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1391","question":"Marden Tool Hire Ltd has $20,000 to invest. It could buy an excavator adding $4,000 profit a year, a van adding $2,500, or refit its workshop adding $1,800. It buys the excavator. What is the opportunity cost?","options":{"A":"$2,500","B":"$1,800","C":"$4,000","D":"$20,000"},"correctOption":"A","correctAnswer":"$2,500","questionType":"MCQ","explanation":{"correct_reason":"The next best alternative is the van with $2,500 annual profit, so that forgone profit is the opportunity cost, not the refit's $1,800.","distractor_reasons":{"A":"The next best alternative is the van with $2,500 annual profit, so that forgone profit is the opportunity cost, not the refit's $1,800.","B":"$1,800 is the profit from the third-ranked option, but opportunity cost uses the next best alternative, which is the van.","C":"$4,000 is the profit from the excavator actually chosen, so it is the benefit gained rather than the alternative sacrificed.","D":"$20,000 is the total investment budget, not the annual profit given up by rejecting the van, so it overstates the cost."}}},{"id":"P1_U1_MCQ_1392","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1392","question":"A firm extracts slate blocks from its own quarry, loads them onto trucks and sells the unprocessed stone straight to builders. In which sector does the firm mainly operate?","options":{"A":"Primary","B":"Secondary","C":"Tertiary","D":"Quaternary"},"correctOption":"A","correctAnswer":"Primary","questionType":"MCQ","explanation":{"correct_reason":"The firm only extracts a raw material and does not process it, so its main activity is primary, even though selling is a service.","distractor_reasons":{"A":"The firm only extracts a raw material and does not process it, so its main activity is primary, even though selling is a service.","B":"Secondary activity involves processing or manufacturing, but the firm sells the slate unprocessed, so it does not manufacture.","C":"Delivery and selling are service activities, but they support the firm's main work of extracting stone, which is primary.","D":"Quaternary is not one of the three production sectors in the syllabus, and the firm's core work is simple extraction."}}},{"id":"P1_U1_MCQ_1393","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1393","question":"A workshop with 50 employees produces 12,000 units a week. After hiring 10 more employees, output rises to 15,600 units. What is the change in output per employee each week?","options":{"A":"+20 units","B":"+40 units","C":"+240 units","D":"+260 units"},"correctOption":"A","correctAnswer":"+20 units","questionType":"MCQ","explanation":{"correct_reason":"Output per employee rises from 12,000/50 = 240 to 15,600/60 = 260, which is an increase of 20 units each week.","distractor_reasons":{"A":"Output per employee rises from 12,000/50 = 240 to 15,600/60 = 260, which is an increase of 20 units each week.","B":"+40 would take output per employee to 280, but 15,600 divided by 60 is 260, not 280.","C":"240 units is the original output per employee, not the change after the extra staff were hired.","D":"260 units is the new output per employee, so it includes the 240 already produced before the change."}}},{"id":"P1_U1_MCQ_1394","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1394","question":"A government owns the country's only water supplier, sets prices to keep water affordable and funds upgrades from taxation. Why might it prefer this to private ownership?","options":{"A":"To provide an essential service at an affordable price rather than to maximise profit","B":"To increase the number of shareholders receiving dividends","C":"To remove all government control over the industry","D":"To sell the service to the highest bidder each year"},"correctOption":"A","correctAnswer":"To provide an essential service at an affordable price rather than to maximise profit","questionType":"MCQ","explanation":{"correct_reason":"Essential services may be run as public corporations so that access and price matter more than profit, with government funding and control.","distractor_reasons":{"A":"Essential services may be run as public corporations so that access and price matter more than profit, with government funding and control.","B":"A public corporation has no private shareholders receiving dividends, so this is not a reason for state ownership.","C":"State ownership increases government control over the industry rather than removing it, so this is the opposite of the effect of nationalisation.","D":"Public corporations provide a continuing service to households, not an annual sale of the business to the highest bidder."}}},{"id":"P1_U1_MCQ_1395","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1395","question":"A family-owned engineering firm spends $400,000 on research instead of paying shareholders a larger dividend this year. Which business objective does this spending decision best illustrate?","options":{"A":"Long-term growth through innovation","B":"Short-term profit maximisation","C":"Survival in the current month","D":"Maximising employee wages"},"correctOption":"A","correctAnswer":"Long-term growth through innovation","questionType":"MCQ","explanation":{"correct_reason":"Investing profit in research aims to create future products and sales, so it reflects a long-term growth objective rather than immediate dividends.","distractor_reasons":{"A":"Investing profit in research aims to create future products and sales, so it reflects a long-term growth objective rather than immediate dividends.","B":"Research spending raises costs now, so it does not maximise short-term profit for the current year.","C":"A $400,000 research budget is a strategic choice, not a response to an immediate threat to survival.","D":"The money is spent on research rather than on wages, so this is not an employee pay objective."}}},{"id":"P1_U1_MCQ_1396","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1396","question":"Two firms each sell their product for $50. Firm K buys materials for $20 a unit; Firm L buys materials for $30 a unit and has lower wage costs. Which statement about added value is correct?","options":{"A":"Firm L must have higher added value because its wage costs are lower","B":"Firm K adds $30 a unit, which is more than Firm L's $20, regardless of their profits","C":"Added value and profit are the same figure for both firms","D":"Both firms have identical added value because their selling prices match"},"correctOption":"B","correctAnswer":"Firm K adds $30 a unit, which is more than Firm L's $20, regardless of their profits","questionType":"MCQ","explanation":{"correct_reason":"Added value is selling price minus bought-in materials, so Firm K adds $30 and Firm L adds $20; lower wages affect profit, not added value.","distractor_reasons":{"B":"Added value is selling price minus bought-in materials, so Firm K adds $30 and Firm L adds $20; lower wages affect profit, not added value.","A":"Lower wages raise profit but wages are not bought-in materials, so Firm L's added value remains $20 rather than rising.","C":"Added value ignores wages and other costs, so it would only equal profit if the firms had no other costs at all.","D":"Identical prices can still produce different added value when the cost of bought-in materials differs between the firms."}}},{"id":"P1_U1_MCQ_1397","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1397","question":"A region's coal mines are closing and many miners are losing their jobs. Why might the government encourage service businesses such as tourism and healthcare to expand there?","options":{"A":"Services always need fewer skills than farming or mining","B":"Service businesses pay no taxes to government","C":"Services require no customers or markets","D":"Service businesses can create new jobs and incomes for former primary workers"},"correctOption":"D","correctAnswer":"Service businesses can create new jobs and incomes for former primary workers","questionType":"MCQ","explanation":{"correct_reason":"Expanding services such as tourism and healthcare can absorb workers who lose primary jobs, raising employment and household incomes across the region.","distractor_reasons":{"D":"Expanding services such as tourism and healthcare can absorb workers who lose primary jobs, raising employment and household incomes across the region.","A":"Many services require specialist skills and training, so this general claim is untrue and not a reason for government support.","B":"Service businesses do pay taxes, and tax exemption is neither accurate nor the reason for encouraging the sector.","C":"Every service needs customers, so a claim that markets are unnecessary misunderstands how service businesses earn revenue."}}},{"id":"P1_U1_MCQ_1398","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1398","question":"A small chain of garden centres doubles its number of outlets in eighteen months and then finds costs rising faster than sales. Which is the most likely explanation?","options":{"A":"All employees become more motivated automatically","B":"The firm's fixed costs disappear","C":"Decision making becomes faster at every level","D":"Communication and coordination become harder, raising average costs"},"correctOption":"D","correctAnswer":"Communication and coordination become harder, raising average costs","questionType":"MCQ","explanation":{"correct_reason":"Rapid growth can create diseconomies of scale, such as poor communication, slower decisions and weaker control, which push average costs up.","distractor_reasons":{"D":"Rapid growth can create diseconomies of scale, such as poor communication, slower decisions and weaker control, which push average costs up.","A":"Rapid growth can leave staff feeling overlooked, so higher motivation for everyone is not an automatic result.","B":"Fixed costs such as rent and insurance generally rise as a firm adds premises and equipment, rather than disappearing.","C":"More layers and sites usually slow decisions, which is one of the coordination problems of rapid growth."}}},{"id":"P1_U1_MCQ_1399","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1399","question":"A public limited company has 5 million shares in issue, and its shares trade at $3.20 each on the stock exchange. What is its market capitalisation?","options":{"A":"$1.6m","B":"$6.25m","C":"$160m","D":"$16m"},"correctOption":"D","correctAnswer":"$16m","questionType":"MCQ","explanation":{"correct_reason":"Market capitalisation is share price multiplied by shares in issue: 5,000,000 x $3.20 = $16,000,000, or $16m in total value.","distractor_reasons":{"D":"Market capitalisation is share price multiplied by shares in issue: 5,000,000 x $3.20 = $16,000,000, or $16m in total value.","A":"$1.6m misplaces the decimal, since 5 million shares at $3.20 each is ten times that amount.","B":"$6.25m divides the number of shares by the price instead of multiplying the two figures.","C":"$160m would need a share price of $32, which is ten times the $3.20 quoted."}}},{"id":"P1_U1_MCQ_1400","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1400","question":"A newly launched courier firm concentrates on winning enough customers to cover its costs, while a rival established a decade ago plans new depots. How do objectives commonly change as a firm becomes established?","options":{"A":"Profit is the first aim, and survival only matters later","B":"Objectives never change once the business plan is written","C":"Established firms always aim only to survive","D":"Survival gives way to profit and growth as the firm gains customers"},"correctOption":"D","correctAnswer":"Survival gives way to profit and growth as the firm gains customers","questionType":"MCQ","explanation":{"correct_reason":"A new firm usually focuses on surviving its early years, then pursues profit, market share and growth once it has stable sales.","distractor_reasons":{"D":"A new firm usually focuses on surviving its early years, then pursues profit, market share and growth once it has stable sales.","A":"The order is reversed: new firms usually seek survival first because they lack customers and cash.","B":"Objectives are reviewed as markets and performance change, so they are not fixed for ever by the plan.","C":"Established firms often pursue profit, growth or market share, so survival is not their only aim."}}},{"id":"P1_U1_MCQ_1401","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1401","question":"Ravi owns a small print shop. He can spend his $12,000 savings on a new digital press that would earn $3,600 a year, or leave the money in a savings account paying 4% a year. If he buys the press, what is the annual opportunity cost of the money?","options":{"A":"$480","B":"$3,600","C":"$12,480","D":"$0"},"correctOption":"A","correctAnswer":"$480","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the next best alternative forgone. Leaving the $12,000 in savings would have earned 4% of $12,000, which is $480 a year, so that is the annual benefit Ravi gives up by buying the press.","distractor_reasons":{"A":"Opportunity cost is the next best alternative forgone. Leaving the $12,000 in savings would have earned 4% of $12,000, which is $480 a year, so that is the annual benefit Ravi gives up by buying the press.","B":"$3,600 is the expected annual return from the new press itself, not the benefit sacrificed, so it describes the chosen option rather than the alternative.","C":"$12,480 adds the $480 of interest to the $12,000 capital, but the capital is not lost when it is switched from a savings account into equipment.","D":"Zero would mean no alternative use existed for the $12,000, yet the savings account at 4% clearly offered a positive annual return."}}},{"id":"P1_U1_MCQ_1402","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1402","question":"In the country of Marovia, 1,250 of the 5,000 people in work are employed in farming and mining, while 1,750 work in factories. What percentage of the workforce is employed in the primary sector?","options":{"A":"20%","B":"25%","C":"35%","D":"40%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Primary sector employment is 1,250 people out of a workforce of 5,000. Dividing 1,250 by 5,000 and multiplying by 100 gives 25%, the share working in farming and mining.","distractor_reasons":{"A":"20% would require 1,000 primary workers, but Marovia has 1,250, so this understates the primary share of the 5,000 workers.","B":"Primary sector employment is 1,250 people out of a workforce of 5,000. Dividing 1,250 by 5,000 and multiplying by 100 gives 25%, the share working in farming and mining.","C":"35% would require 1,750 primary workers, yet that figure is the number employed in factories, which belong to the secondary sector.","D":"40% would require 2,000 primary workers and ignores the stated total, so it overstates the proportion in farming and mining."}}},{"id":"P1_U1_MCQ_1403","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1403","question":"Kestrel Tools sells $180,000 of garden tools in a year. Total sales across the whole garden tool market are $2,400,000. What is Kestrel Tools' market share?","options":{"A":"5.0%","B":"6.5%","C":"7.5%","D":"13.3%"},"correctOption":"C","correctAnswer":"7.5%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Here $180,000 divided by $2,400,000 equals 0.075, which is a market share of 7.5%.","distractor_reasons":{"A":"5.0% would result from sales of $120,000 in a $2,400,000 market, so it does not match Kestrel's printed revenue of $180,000.","B":"6.5% would require sales of $156,000, which is below the $180,000 Kestrel actually records, so the division is wrong. The option is therefore mistaken and cannot be the right selection.","C":"Market share is the firm's sales divided by total market sales, multiplied by 100. Here $180,000 divided by $2,400,000 equals 0.075, which is a market share of 7.5%.","D":"13.3% reverses the calculation by dividing the market total by Kestrel's sales, which overstates its share by a wide margin."}}},{"id":"P1_U1_MCQ_1404","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1404","question":"Three friends form a partnership and agree to share profit equally. In the first year the partnership makes a profit of $84,000 after all costs have been paid. What is each partner's share of the profit?","options":{"A":"$21,000","B":"$42,000","C":"$84,000","D":"$28,000"},"correctOption":"D","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"With an equal profit-sharing agreement, the $84,000 profit is divided by the three partners. $84,000 divided by 3 equals $28,000, which is each partner's share for the year.","distractor_reasons":{"A":"$21,000 would be correct only if the profit were split four ways, but this partnership has three named partners sharing equally.","B":"$42,000 is half of the profit, which would suit two partners rather than the three friends who formed this partnership.","C":"$84,000 is the whole profit, and giving it to one partner would leave the other two with nothing under an equal-split agreement.","D":"With an equal profit-sharing agreement, the $84,000 profit is divided by the three partners. $84,000 divided by 3 equals $28,000, which is each partner's share for the year."}}},{"id":"P1_U1_MCQ_1405","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1405","question":"Northfield Bakery makes an annual profit of $150,000. Its owners set aside 8% of profit as a bonus pool for the 12 employees. What is the total value of the bonus pool?","options":{"A":"$1,200","B":"$12,000","C":"$18,750","D":"$8,000"},"correctOption":"B","correctAnswer":"$12,000","questionType":"MCQ","explanation":{"correct_reason":"The bonus pool is 8% of the $150,000 profit. Multiplying $150,000 by 0.08 gives $12,000, which is the amount available to distribute among the twelve employees.","distractor_reasons":{"A":"$1,200 is 8% of $15,000, not of the $150,000 profit, so the decimal place has been moved incorrectly. It therefore cannot be accepted as the correct answer to the question.","B":"The bonus pool is 8% of the $150,000 profit. Multiplying $150,000 by 0.08 gives $12,000, which is the amount available to distribute among the twelve employees.","C":"$18,750 divides the profit by eight instead of taking 8% of it, which produces a much larger pool than the policy states.","D":"$8,000 confuses the 8% rate with a money amount and ignores the $150,000 profit figure printed in the scenario. The option is therefore mistaken and cannot be the right selection."}}},{"id":"P1_U1_MCQ_1406","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1406","question":"A family whose roof starts leaking after a storm spends $900 on urgent repairs and postpones buying a games console. Which statement best explains why the family made this choice?","options":{"A":"The games console is a need and the roof repair is a want","B":"The roof repair is a want that could easily be delayed","C":"Shelter is a basic need, so the repair took priority over an optional want","D":"The family had unlimited income and could satisfy every want"},"correctOption":"C","correctAnswer":"Shelter is a basic need, so the repair took priority over an optional want","questionType":"MCQ","explanation":{"correct_reason":"A leaking roof threatens shelter, which is a basic need, while a games console is a want that can be postponed. With limited income the family satisfied the need first, which is the essence of the economic problem.","distractor_reasons":{"A":"This reverses the two categories, because a games console is a want and a weatherproof roof is a basic need for shelter and safety.","B":"A leaking roof causes further damage and affects shelter, so it is not a want that can safely be delayed like a games console.","C":"A leaking roof threatens shelter, which is a basic need, while a games console is a want that can be postponed. With limited income the family satisfied the need first, which is the essence of the economic problem.","D":"The need to postpone the console shows income is limited, not unlimited, so the family cannot satisfy every want at once."}}},{"id":"P1_U1_MCQ_1407","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1407","question":"Cedar & Co buys raw wool from farmers, spins it into yarn and sells the yarn to knitting shops. Which sector of the economy does Cedar & Co operate in?","options":{"A":"Primary","B":"Tertiary","C":"Quaternary","D":"Secondary"},"correctOption":"D","correctAnswer":"Secondary","questionType":"MCQ","explanation":{"correct_reason":"Cedar & Co processes raw wool into yarn, which is manufacturing and therefore part of the secondary sector. It does not extract the wool itself or merely sell the finished yarn to consumers.","distractor_reasons":{"A":"The primary sector covers extraction such as farming and mining; Cedar & Co buys the wool from farmers rather than producing it.","B":"The tertiary sector provides services, but Cedar & Co makes a physical product by spinning wool into yarn, which is manufacturing.","C":"The quaternary sector covers knowledge-based services such as research, not the physical transformation of wool into yarn. It therefore cannot be accepted as the correct answer to the question.","D":"Cedar & Co processes raw wool into yarn, which is manufacturing and therefore part of the secondary sector. It does not extract the wool itself or merely sell the finished yarn to consumers."}}},{"id":"P1_U1_MCQ_1408","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1408","question":"Priya plans to open a mobile bike repair service. She writes a document setting out her target customers, expected costs, likely revenue and the cash she will need in the first year. What is this document called?","options":{"A":"A business plan","B":"A cash flow forecast","C":"A partnership deed","D":"A statement of financial position"},"correctOption":"A","correctAnswer":"A business plan","questionType":"MCQ","explanation":{"correct_reason":"The document covers the whole venture, including target market, costs, expected revenue and finance needed, which is exactly what a business plan contains. It helps Priya test the idea and persuade lenders.","distractor_reasons":{"A":"The document covers the whole venture, including target market, costs, expected revenue and finance needed, which is exactly what a business plan contains. It helps Priya test the idea and persuade lenders.","B":"A cash flow forecast shows the timing of cash inflows and outflows month by month, not the market analysis and overall strategy Priya is writing.","C":"A partnership deed is a legal agreement between partners, but Priya is described as planning her own business rather than forming a partnership.","D":"A statement of financial position records assets, liabilities and capital at a point in time, not the forward-looking plan for a new service."}}},{"id":"P1_U1_MCQ_1409","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1409","question":"Tomas runs a sole trader plumbing business. A faulty installation causes $60,000 of damage and his insurance pays only $20,000. Why might Tomas have to sell personal assets to settle the claim?","options":{"A":"Shareholders are liable for company debts","B":"The business has limited liability","C":"A sole trader has unlimited liability for business debts","D":"Partners must cover each other's mistakes"},"correctOption":"C","correctAnswer":"A sole trader has unlimited liability for business debts","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is not a separate legal entity from its owner, so Tomas has unlimited liability. The unpaid $40,000 of damage can be claimed from his personal assets, such as his home or savings.","distractor_reasons":{"A":"There are no shareholders in a sole trader business; Tomas alone owns and controls the plumbing business described. For this reason it clearly cannot be the best answer to the question.","B":"Limited liability means owners lose only the capital they invested, which would protect Tomas rather than force a personal asset sale.","C":"A sole trader is not a separate legal entity from its owner, so Tomas has unlimited liability. The unpaid $40,000 of damage can be claimed from his personal assets, such as his home or savings.","D":"Tomas is a sole trader with no partners, so the rule that partners cover each other's mistakes does not apply here."}}},{"id":"P1_U1_MCQ_1410","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1410","question":"A clothing factory announces record profit and proposes a larger dividend, while refusing a 4% wage rise for its workers. Which two stakeholder groups have directly conflicting objectives?","options":{"A":"Customers and suppliers","B":"The government and the local community","C":"Managers and customers","D":"Employees and shareholders"},"correctOption":"D","correctAnswer":"Employees and shareholders","questionType":"MCQ","explanation":{"correct_reason":"Employees want higher wages, while shareholders gain from larger dividends and retained profit. The larger dividend and the refused 4% pay rise show these two groups competing for the same profit.","distractor_reasons":{"A":"Customers want good value and suppliers want prompt payment, but neither group is directly affected by the dividend and wage decision described.","B":"The government and local community have no direct claim on the profit split, so their objectives are not the conflict shown here.","C":"Managers usually share the owners' interest in profit, and customers are not involved in the decision to refuse the wage rise.","D":"Employees want higher wages, while shareholders gain from larger dividends and retained profit. The larger dividend and the refused 4% pay rise show these two groups competing for the same profit."}}},{"id":"P1_U1_MCQ_1411","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1411","question":"A pottery workshop divides production into shaping, glazing and packing, and each worker repeats one task all day. What is the main benefit the owner expects from this division of labour?","options":{"A":"Higher output per worker through specialisation","B":"A lower total wage bill for the workshop","C":"A reduction in the clay and glaze needed","D":"A wider range of pottery designs"},"correctOption":"A","correctAnswer":"Higher output per worker through specialisation","questionType":"MCQ","explanation":{"correct_reason":"Repeating one task lets each worker become faster and more skilled, so output per worker rises. This specialisation is the main gain from dividing the pottery-making process into separate stages.","distractor_reasons":{"A":"Repeating one task lets each worker become faster and more skilled, so output per worker rises. This specialisation is the main gain from dividing the pottery-making process into separate stages.","B":"Workers are still paid for their time, and specialisation may even require higher pay for skilled glazers, so the wage bill need not fall.","C":"Division of labour changes how work is organised, not how much clay or glaze each pot requires, so material use is unaffected.","D":"Repeating one narrow task tends to limit variety and creativity rather than widen the range of designs the workshop offers."}}},{"id":"P1_U1_MCQ_1412","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1412","question":"Over twenty years, a region's steelworks close and most new jobs appear in call centres, hotels and hospitals. Which change in the structure of the economy has occurred?","options":{"A":"From primary to secondary","B":"From secondary to tertiary","C":"From tertiary to primary","D":"From secondary to primary"},"correctOption":"B","correctAnswer":"From secondary to tertiary","questionType":"MCQ","explanation":{"correct_reason":"Steelmaking is secondary activity and call centres, hotels and hospitals are services, so employment has moved from the secondary sector to the tertiary sector. This is the deindustrialisation pattern seen in many developed economies.","distractor_reasons":{"A":"Primary to secondary would mean moving from farming or mining into factories, but the steelworks were already factories and they closed.","B":"Steelmaking is secondary activity and call centres, hotels and hospitals are services, so employment has moved from the secondary sector to the tertiary sector. This is the deindustrialisation pattern seen in many developed economies.","C":"Tertiary to primary would mean services declining and farming or mining expanding, which is the opposite of what the region experienced.","D":"Secondary to primary would mean manufacturing jobs being replaced by extraction, yet the new jobs listed are service jobs. It therefore cannot be accepted as the correct answer to the question."}}},{"id":"P1_U1_MCQ_1413","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1413","question":"Despite competition from large national chains, a family-run bakery in a small town thrives by baking specialist rye bread for local restaurants. Which reason best explains its survival?","options":{"A":"It benefits from large economies of scale","B":"It has lower costs than the national chains","C":"It receives a government grant","D":"It offers personal service and a niche product"},"correctOption":"D","correctAnswer":"It offers personal service and a niche product","questionType":"MCQ","explanation":{"correct_reason":"The bakery survives by serving a small, specific market that the large chains do not target. Personal service and specialist rye bread give it a distinct appeal, which is a classic advantage of small firms.","distractor_reasons":{"A":"A single family bakery operates on a small scale and cannot match the bulk-buying economies of scale available to national chains.","B":"Large chains usually buy ingredients more cheaply, so the family bakery is more likely to have higher, not lower, unit costs.","C":"No grant is mentioned, and the scenario attributes success to specialist bread and local restaurant customers instead. This error rules the option out and makes the choice incorrect.","D":"The bakery survives by serving a small, specific market that the large chains do not target. Personal service and specialist rye bread give it a distinct appeal, which is a classic advantage of small firms."}}},{"id":"P1_U1_MCQ_1414","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1414","question":"A couple pay $25,000 to use a national coffee brand's name, recipes and training, and also pay 6% of monthly revenue to the brand owner. What type of business organisation have they joined?","options":{"A":"A franchise","B":"A partnership","C":"A public corporation","D":"A cooperative"},"correctOption":"A","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Paying an initial fee for a brand's name, recipes and training, plus a percentage of revenue, is the standard franchise arrangement. The couple own their outlet but operate under the established brand.","distractor_reasons":{"A":"Paying an initial fee for a brand's name, recipes and training, plus a percentage of revenue, is the standard franchise arrangement. The couple own their outlet but operate under the established brand.","B":"A partnership is formed by two or more owners sharing a business, but the couple are buying rights from an existing brand owner instead.","C":"A public corporation is state-owned and funded by government, which does not match a private couple paying a brand fee.","D":"A cooperative is owned and run by its members, not by a couple purchasing usage rights from a separate brand owner."}}},{"id":"P1_U1_MCQ_1415","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1415","question":"A newly opened gym focuses on surviving its first year; three years later the same gym aims to open four more branches. What does this change best illustrate?","options":{"A":"Business objectives never change once they are written","B":"Objectives develop as the business grows and its circumstances change","C":"Survival is always a long-term objective","D":"Shareholders alone decide every business aim"},"correctOption":"B","correctAnswer":"Objectives develop as the business grows and its circumstances change","questionType":"MCQ","explanation":{"correct_reason":"The gym first needed to establish itself, so survival mattered most. Once established, it could pursue expansion, showing that objectives evolve with the firm's stage of growth and resources.","distractor_reasons":{"A":"The gym replaced its survival focus with expansion aims, which directly contradicts the claim that objectives never change. So it should not be selected as the correct option in this situation.","B":"The gym first needed to establish itself, so survival mattered most. Once established, it could pursue expansion, showing that objectives evolve with the firm's stage of growth and resources.","C":"Survival is typically a short-term aim for a new or struggling firm, and this gym has moved beyond it after three years.","D":"The scenario describes the gym's own changing aims, not a decision imposed solely by shareholders. Such a result is not what the question actually requires from the student."}}},{"id":"P1_U1_MCQ_1416","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1416","question":"Pinewood Furniture buys timber and fittings for $140 per table, pays workers $60 per table and sells each table for $260. What is the added value per table?","options":{"A":"$60","B":"$200","C":"$120","D":"$260"},"correctOption":"C","correctAnswer":"$120","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price minus the cost of bought-in materials and components: $260 minus $140 equals $120. The $60 labour cost is part of the value the business itself adds, so it is not deducted.","distractor_reasons":{"A":"$60 is the labour cost per table, but wages are part of the value added by the firm rather than a bought-in material cost.","B":"$200 subtracts only the labour cost from the price, yet the $140 of bought-in timber and fittings must also be deducted.","C":"Added value is the selling price minus the cost of bought-in materials and components: $260 minus $140 equals $120. The $60 labour cost is part of the value the business itself adds, so it is not deducted.","D":"$260 is the full selling price and ignores both the bought-in materials and the meaning of added value. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1417","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1417","question":"In Dunmere, primary sector employment fell from 480 workers to 408 workers over five years as farms consolidated. What was the percentage change in primary sector employment?","options":{"A":"A fall of 15%","B":"A fall of 17.6%","C":"A rise of 15%","D":"A fall of 72%"},"correctOption":"A","correctAnswer":"A fall of 15%","questionType":"MCQ","explanation":{"correct_reason":"The fall is 480 minus 408, which equals 72 workers. Dividing 72 by the original 480 and multiplying by 100 gives a 15% fall in primary sector employment.","distractor_reasons":{"A":"The fall is 480 minus 408, which equals 72 workers. Dividing 72 by the original 480 and multiplying by 100 gives a 15% fall in primary sector employment.","B":"17.6% comes from dividing the 72 fall by the new figure of 408, but percentage change is measured against the original 480.","C":"Employment clearly fell from 480 to 408, so the direction is a decrease rather than a 15% increase. So it should not be selected as the correct option in this situation.","D":"72 is the number of jobs lost, not a percentage, and treating it as 72% confuses the absolute fall with the rate of change."}}},{"id":"P1_U1_MCQ_1418","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1418","question":"Harlow Digital employs 80 people across its design and support teams and earns annual revenue of $4,800,000 for the year. What is the average revenue per employee?","options":{"A":"$48,000","B":"$60,000","C":"$6,000","D":"$384,000"},"correctOption":"B","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue per employee is total revenue divided by the number of employees. $4,800,000 divided by 80 equals $60,000, which measures the sales generated per worker.","distractor_reasons":{"A":"$48,000 would result from dividing $4,800,000 by 100 employees, but Harlow Digital actually employs 80 people. This leaves it as an incorrect option that should be rejected.","B":"Revenue per employee is total revenue divided by the number of employees. $4,800,000 divided by 80 equals $60,000, which measures the sales generated per worker.","C":"$6,000 is far too low and would imply 800 employees, so the division has an extra zero error. Such a result is not what the question actually requires from the student.","D":"$384,000 multiplies the revenue by the employee count instead of dividing, producing a meaningless figure. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1419","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1419","question":"Two partners invest $90,000 and $60,000 and agree to share profit in proportion to their capital. Annual profit is $75,000. How much does the larger investor receive?","options":{"A":"$30,000","B":"$37,500","C":"$45,000","D":"$60,000"},"correctOption":"C","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Total capital is $150,000, so the larger investor owns $90,000 divided by $150,000, which is 60%. Taking 60% of the $75,000 profit gives $45,000 for that partner.","distractor_reasons":{"A":"$30,000 is 40% of the profit, which is the share belonging to the smaller investor who contributed $60,000. This error rules the option out and makes the choice incorrect.","B":"$37,500 would be an equal split of the $75,000 profit, but the partners agreed to share in proportion to capital, not equally.","C":"Total capital is $150,000, so the larger investor owns $90,000 divided by $150,000, which is 60%. Taking 60% of the $75,000 profit gives $45,000 for that partner.","D":"$60,000 matches the smaller partner's capital contribution, not the larger investor's 60% share of the $75,000 profit. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1420","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1420","question":"Ridgeway Ltd earns profit after tax of $240,000 and pays $84,000 as dividends to shareholders. What percentage of the profit is retained in the business?","options":{"A":"35%","B":"84%","C":"156%","D":"65%"},"correctOption":"D","correctAnswer":"65%","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is $240,000 minus $84,000, which equals $156,000. Dividing $156,000 by the $240,000 profit and multiplying by 100 gives 65% retained in the business.","distractor_reasons":{"A":"35% is the proportion paid out as dividends, not the proportion kept, so it answers the opposite part of the question.","B":"84% confuses the $84,000 dividend amount with a percentage of the $240,000 profit, which is actually 35%. So it should not be selected as the correct option in this situation.","C":"156% comes from treating the $156,000 retained figure as a percentage without dividing by the $240,000 profit. This leaves it as an incorrect option that should be rejected.","D":"Retained profit is $240,000 minus $84,000, which equals $156,000. Dividing $156,000 by the $240,000 profit and multiplying by 100 gives 65% retained in the business."}}},{"id":"P1_U1_MCQ_1421","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1421","question":"A new wind farm uses coastal land, 40 technicians, turbine equipment and an entrepreneur's decision to invest. Which factor of production is represented by the 40 technicians?","options":{"A":"Land","B":"Labour","C":"Capital","D":"Enterprise"},"correctOption":"B","correctAnswer":"Labour","questionType":"MCQ","explanation":{"correct_reason":"The technicians supply human effort and skills to operate and maintain the wind farm, which makes them the labour factor of production. Land is the site, capital is the equipment and enterprise is the investor's risk-taking.","distractor_reasons":{"A":"Land refers to natural resources such as the coastal site, not to the people who work on the turbines. It therefore cannot be accepted as the correct answer to the question.","B":"The technicians supply human effort and skills to operate and maintain the wind farm, which makes them the labour factor of production. Land is the site, capital is the equipment and enterprise is the investor's risk-taking.","C":"Capital refers to the manufactured equipment such as turbines, whereas the technicians are human workers. This error rules the option out and makes the choice incorrect.","D":"Enterprise is the willingness to take risks and organise the project, which is represented by the investor rather than the technicians."}}},{"id":"P1_U1_MCQ_1422","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1422","question":"In a low-income country, most workers grow crops to feed their own families and very few factories exist. Which sector dominates the economy, and why?","options":{"A":"The tertiary sector, because tourism creates most jobs","B":"The secondary sector, because factories employ most people","C":"The primary sector, because farming provides most employment","D":"The public sector, because the government employs everyone"},"correctOption":"C","correctAnswer":"The primary sector, because farming provides most employment","questionType":"MCQ","explanation":{"correct_reason":"Growing crops is primary activity, and the scenario says most workers do it, so the primary sector dominates. Low-income economies typically rely heavily on farming and other extraction.","distractor_reasons":{"A":"Tourism is a tertiary service, but the scenario describes crop growing and states that very few other activities exist. The option is therefore mistaken and cannot be the right selection.","B":"The scenario says very few factories exist, so manufacturing cannot be the dominant source of employment. For this reason it clearly cannot be the best answer to the question.","C":"Growing crops is primary activity, and the scenario says most workers do it, so the primary sector dominates. Low-income economies typically rely heavily on farming and other extraction.","D":"No information suggests government employment is widespread, and the stated work is subsistence farming. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1423","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1423","question":"A supermarket buys all the shares of a small chain of convenience stores, which then trades as part of the larger group. Which method of business growth does this describe?","options":{"A":"Internal growth","B":"A merger","C":"A franchise","D":"A takeover"},"correctOption":"D","correctAnswer":"A takeover","questionType":"MCQ","explanation":{"correct_reason":"One business has purchased all the shares of another and brought it under its control, which is a takeover. A merger would involve two firms agreeing to combine as roughly equal partners.","distractor_reasons":{"A":"Internal growth means expanding sales from within by opening new outlets, not buying control of an existing chain. So it should not be selected as the correct option in this situation.","B":"A merger is an agreed combination of two businesses, whereas here the supermarket is clearly the buyer taking control. This leaves it as an incorrect option that should be rejected.","C":"A franchise involves selling the right to use a brand, but the supermarket has bought the convenience chain outright. It therefore cannot be accepted as the correct answer to the question.","D":"One business has purchased all the shares of another and brought it under its control, which is a takeover. A merger would involve two firms agreeing to combine as roughly equal partners."}}},{"id":"P1_U1_MCQ_1424","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1424","question":"A national rail network is owned and funded by the government and aims to provide affordable transport rather than maximise profit. What type of organisation is it?","options":{"A":"A public corporation","B":"A public limited company","C":"A private limited company","D":"A sole trader"},"correctOption":"A","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"Government ownership, public funding and a service rather than profit aim are the defining features of a public corporation. Its purpose is to meet a public need, not to reward private shareholders.","distractor_reasons":{"A":"Government ownership, public funding and a service rather than profit aim are the defining features of a public corporation. Its purpose is to meet a public need, not to reward private shareholders.","B":"A public limited company is owned by private shareholders and can be bought and sold on a stock exchange, unlike this state-owned network.","C":"A private limited company is owned by a small number of private shareholders, not by the government. The option is therefore mistaken and cannot be the right selection.","D":"A sole trader is a single owner running a business, which cannot describe a national rail network funded by the state."}}},{"id":"P1_U1_MCQ_1425","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1425","question":"A manufacturer installs costly filters that reduce pollution beyond the legal requirement, which lowers this year's profit but benefits nearby residents. Which objective is the business pursuing?","options":{"A":"Profit maximisation","B":"Survival","C":"Environmental responsibility towards the community","D":"An increase in market share"},"correctOption":"C","correctAnswer":"Environmental responsibility towards the community","questionType":"MCQ","explanation":{"correct_reason":"Spending on filters that go beyond the legal minimum sacrifices profit to reduce pollution, which benefits the local community and the environment. This is a social and environmental objective rather than a financial one.","distractor_reasons":{"A":"Profit maximisation would avoid unnecessary spending, but the filters are costly and deliberately exceed what the law demands. For this reason it clearly cannot be the best answer to the question.","B":"Survival is about staying in business during difficulty, not about investing in cleaner equipment that lowers this year's profit. That makes it the wrong choice in the circumstances described in the case.","C":"Spending on filters that go beyond the legal minimum sacrifices profit to reduce pollution, which benefits the local community and the environment. This is a social and environmental objective rather than a financial one.","D":"Market share is gained through sales and pricing, yet no information suggests the filters will increase the manufacturer's sales. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1426","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1426","question":"A community centre has $5,000 and must choose between a new heating system and a children's play area, since both would cost about the same. What does this situation best illustrate?","options":{"A":"The centre has unlimited funds","B":"Neither project has an opportunity cost","C":"The play area is a need and heating is a want","D":"Limited funds create scarcity and force a choice"},"correctOption":"D","correctAnswer":"Limited funds create scarcity and force a choice","questionType":"MCQ","explanation":{"correct_reason":"With only $5,000, the centre cannot fund both projects, so limited resources create scarcity and force a choice. The project not chosen becomes the opportunity cost of the one selected.","distractor_reasons":{"A":"The need to choose between two projects shows the funds are limited, not unlimited, because both cannot be afforded together.","B":"Choosing the heating system means giving up the play area, so an opportunity cost clearly exists even though both are worthwhile.","C":"Heating and a play area both meet important needs, so labelling one a need and the other a want misreads the situation.","D":"With only $5,000, the centre cannot fund both projects, so limited resources create scarcity and force a choice. The project not chosen becomes the opportunity cost of the one selected."}}},{"id":"P1_U1_MCQ_1427","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1427","question":"As household incomes rise in Verona, families spend a larger share of their budget on restaurant meals, travel and personal training. Which sector grows most, and why?","options":{"A":"The tertiary sector, because higher incomes raise demand for services","B":"The primary sector, because more food must be grown","C":"The secondary sector, because more factories are needed","D":"The primary sector, because travel uses natural resources"},"correctOption":"A","correctAnswer":"The tertiary sector, because higher incomes raise demand for services","questionType":"MCQ","explanation":{"correct_reason":"Restaurant meals, travel and personal training are services, so they belong to the tertiary sector. When incomes rise, households spend more on services, which makes the tertiary sector grow fastest.","distractor_reasons":{"A":"Restaurant meals, travel and personal training are services, so they belong to the tertiary sector. When incomes rise, households spend more on services, which makes the tertiary sector grow fastest.","B":"More food may be required, but the spending described is on meals out, travel and training, which are services rather than farming.","C":"No extra factories are mentioned, and the growing items are services consumed directly by households rather than manufactured goods. For this reason it clearly cannot be the best answer to the question.","D":"Travel may use natural resources, but the activity itself is a service provided to customers, not primary extraction. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1428","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1428","question":"Firm X has 300 employees and revenue of $20 million; Firm Y has 90 employees and revenue of $45 million. Why is employee numbers an unreliable way to compare their size?","options":{"A":"Employee numbers are always the best size measure","B":"A capital-intensive firm can earn much more revenue with fewer staff","C":"Revenue is always lower than employee numbers","D":"Small firms cannot be large by any measure"},"correctOption":"B","correctAnswer":"A capital-intensive firm can earn much more revenue with fewer staff","questionType":"MCQ","explanation":{"correct_reason":"Firm Y earns more than twice Firm X's revenue using fewer than a third of the employees, showing it is capital-intensive. Employee numbers therefore understate the size of highly automated firms.","distractor_reasons":{"A":"The example shows the opposite, because the firm with far fewer employees earns much higher revenue than the larger employer.","B":"Firm Y earns more than twice Firm X's revenue using fewer than a third of the employees, showing it is capital-intensive. Employee numbers therefore understate the size of highly automated firms.","C":"Revenue is measured in dollars and employees in people, so the two figures cannot be compared as if one were always lower.","D":"Firm Y is small in employee numbers yet large in revenue, which disproves the claim that small firms cannot be large by any measure."}}},{"id":"P1_U1_MCQ_1429","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1429","question":"Two accountants set up a partnership instead of working as sole traders, so that they can share clients, cover each other's holidays and combine different specialisms. What is the main advantage they gain?","options":{"A":"Limited liability for both partners","B":"Shares that can be traded on a stock exchange","C":"A separate legal identity from its owners","D":"Shared workload and complementary skills"},"correctOption":"D","correctAnswer":"Shared workload and complementary skills","questionType":"MCQ","explanation":{"correct_reason":"The partners pool clients and different specialisms and can cover each other's absences, which spreads the workload and widens the skills available. These are the practical advantages of a partnership over sole trading.","distractor_reasons":{"A":"Ordinary partners in a partnership still have unlimited liability, so their personal assets remain at risk for business debts. It therefore cannot be accepted as the correct answer to the question.","B":"Partnership shares are not listed or traded on a stock exchange, which is a feature of public limited companies instead.","C":"A partnership is not a separate legal entity from its partners, unlike a limited company, so this is not an advantage it offers.","D":"The partners pool clients and different specialisms and can cover each other's absences, which spreads the workload and widens the skills available. These are the practical advantages of a partnership over sole trading."}}},{"id":"P1_U1_MCQ_1430","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1430","question":"A listed retailer's board rejects a takeover that would raise the share price because it would close 30 stores and cut 900 jobs. Which objective is the board prioritising?","options":{"A":"The welfare of employees and local communities over shareholder gain","B":"Maximum short-term profit for shareholders","C":"Rapid growth in market share","D":"Survival of the business at any cost"},"correctOption":"A","correctAnswer":"The welfare of employees and local communities over shareholder gain","questionType":"MCQ","explanation":{"correct_reason":"The board gives up a higher share price to protect 900 jobs and 30 local stores, so it is prioritising employee and community welfare over shareholder returns. This shows stakeholder objectives overriding shareholder gain.","distractor_reasons":{"A":"The board gives up a higher share price to protect 900 jobs and 30 local stores, so it is prioritising employee and community welfare over shareholder returns. This shows stakeholder objectives overriding shareholder gain.","B":"Rejecting the bid forgoes a higher share price, which is the opposite of maximising short-term shareholder profit. For this reason it clearly cannot be the best answer to the question.","C":"The takeover would have expanded the business, so rejecting it limits growth rather than pursuing rapid market share gains. That makes it the wrong choice in the circumstances described in the case.","D":"The retailer is not described as facing collapse, so survival at any cost does not explain the decision. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1431","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1431","question":"A garden centre buys young plants for $6 each, spends another $4 per plant on pots and labour, and sells each plant for $18. What is the added value per plant?","options":{"A":"$8","B":"$12","C":"$18","D":"$14"},"correctOption":"B","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price minus the cost of bought-in materials: $18 minus $6 equals $12. The $4 spent on pots and labour is part of the value the garden centre itself adds, so it is not deducted.","distractor_reasons":{"A":"$8 subtracts both the $6 plant cost and the $4 of pots and labour from the $18 price, but labour is part of the value added rather than a bought-in material.","B":"Added value is the selling price minus the cost of bought-in materials: $18 minus $6 equals $12. The $4 spent on pots and labour is part of the value the garden centre itself adds, so it is not deducted.","C":"$18 is the full selling price and ignores the $6 cost of the young plant that the garden centre bought in.","D":"$14 deducts only the $4 labour and potting cost, but the $6 purchase cost of the plant must also be subtracted."}}},{"id":"P1_U1_MCQ_1432","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1432","question":"In Norvale, 3,600 of the 9,000 workers are employed in services, 2,700 work in manufacturing and the rest work in farming. What percentage of the workforce is in the primary sector?","options":{"A":"20%","B":"40%","C":"30%","D":"25%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Primary employment is the remainder after services and manufacturing: 9,000 minus 3,600 minus 2,700 equals 2,700 workers. Dividing 2,700 by 9,000 and multiplying by 100 gives 30%.","distractor_reasons":{"A":"20% would mean 1,800 farm workers, but the remainder after the other two sectors is 2,700 people. Such a result is not what the question actually requires from the student.","B":"40% is the 3,600 service workers as a share of 9,000, which is tertiary rather than primary employment. This error rules the option out and makes the choice incorrect.","C":"Primary employment is the remainder after services and manufacturing: 9,000 minus 3,600 minus 2,700 equals 2,700 workers. Dividing 2,700 by 9,000 and multiplying by 100 gives 30%.","D":"25% would mean 2,250 farm workers, which does not match the 2,700 left after services and manufacturing. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1433","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1433","question":"Tarnfield Optics sold 24,000 lenses this year, up from 20,000 last year, while the total market stayed at 400,000 lenses. What was Tarnfield's market share this year?","options":{"A":"6%","B":"5%","C":"6.7%","D":"12%"},"correctOption":"A","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"Market share is this year's sales divided by total market sales: 24,000 divided by 400,000 equals 0.06. Multiplying by 100 gives Tarnfield a 6% share of the lens market this year.","distractor_reasons":{"A":"Market share is this year's sales divided by total market sales: 24,000 divided by 400,000 equals 0.06. Multiplying by 100 gives Tarnfield a 6% share of the lens market this year.","B":"5% was Tarnfield's share last year, when it sold 20,000 of the 400,000 lenses, not its current share. That makes it the wrong choice in the circumstances described in the case.","C":"6.7% divides the 24,000 lenses by 360,000, which is not the total market figure given in the scenario. So it should not be selected as the correct option in this situation.","D":"12% would mean sales of 48,000 lenses, double the 24,000 Tarnfield actually sold this year. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1434","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1434","question":"Three partners agree to share profit in the ratio 2:2:1. The partnership makes a profit of $90,000 for the year. How much does the partner with the smallest share receive?","options":{"A":"$36,000","B":"$18,000","C":"$45,000","D":"$22,500"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio 2:2:1 has five parts in total, so one part is $90,000 divided by 5, which equals $18,000. The partner with the smallest share holds one part and therefore receives $18,000.","distractor_reasons":{"A":"$36,000 is two parts of the profit, which is the share of each of the two larger partners rather than the smallest holder.","B":"The ratio 2:2:1 has five parts in total, so one part is $90,000 divided by 5, which equals $18,000. The partner with the smallest share holds one part and therefore receives $18,000.","C":"$45,000 is half the profit and ignores the agreed 2:2:1 ratio entirely. Such a result is not what the question actually requires from the student.","D":"$22,500 divides the profit into four parts, but the ratio 2:2:1 actually creates five equal parts. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1435","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1435","question":"A social enterprise makes a profit of $80,000 and reinvests 65% of it in training programmes for unemployed young people. How much money is reinvested?","options":{"A":"$28,000","B":"$65,000","C":"$52,000","D":"$48,000"},"correctOption":"C","correctAnswer":"$52,000","questionType":"MCQ","explanation":{"correct_reason":"The amount reinvested is 65% of the $80,000 profit. Multiplying $80,000 by 0.65 gives $52,000, which is the sum directed into the training programmes.","distractor_reasons":{"A":"$28,000 is the 35% of profit not reinvested, so it answers the opposite part of the question. This error rules the option out and makes the choice incorrect.","B":"$65,000 confuses the 65% rate with a money amount and ignores the $80,000 profit. The option is therefore mistaken and cannot be the right selection.","C":"The amount reinvested is 65% of the $80,000 profit. Multiplying $80,000 by 0.65 gives $52,000, which is the sum directed into the training programmes.","D":"$48,000 would be 60% of the profit, not the stated 65%, so the percentage has been applied incorrectly. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1436","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1436","question":"A firm combines fabric, sewing machines, designers and factory labour to make outdoor clothing that customers value. Which statement best describes the economic role of this business?","options":{"A":"It removes the need for consumers to make choices","B":"It creates unlimited resources for society","C":"It only redistributes existing goods without changing them","D":"It combines factors of production to create goods that satisfy wants and add value"},"correctOption":"D","correctAnswer":"It combines factors of production to create goods that satisfy wants and add value","questionType":"MCQ","explanation":{"correct_reason":"The firm brings together land, capital, labour and enterprise to transform fabric into clothing that customers want. In doing so it adds value and satisfies consumer wants, which is the core role of business activity.","distractor_reasons":{"A":"Businesses produce goods and services, but consumers still face scarcity and must choose how to spend limited incomes. That makes it the wrong choice in the circumstances described in the case.","B":"Resources such as fabric and labour are finite, so a single firm cannot create unlimited resources for society. So it should not be selected as the correct option in this situation.","C":"The firm transforms fabric into clothing, which changes the goods rather than merely redistributing them unchanged. This leaves it as an incorrect option that should be rejected.","D":"The firm brings together land, capital, labour and enterprise to transform fabric into clothing that customers want. In doing so it adds value and satisfies consumer wants, which is the core role of business activity."}}},{"id":"P1_U1_MCQ_1437","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1437","question":"A government decides to support its steel industry because steel is bought by construction firms and car plants. Which reason for supporting the secondary sector does this best reflect?","options":{"A":"The secondary sector employs every worker in the economy","B":"Steel production is a service activity","C":"The primary sector needs no support at all","D":"Manufacturing supplies inputs to other industries and supports jobs"},"correctOption":"D","correctAnswer":"Manufacturing supplies inputs to other industries and supports jobs","questionType":"MCQ","explanation":{"correct_reason":"Steel is an input for construction and car manufacturing, so a strong secondary sector supports employment and output in industries that depend on it. This linkage is a key reason governments value manufacturing.","distractor_reasons":{"A":"No economy has every worker in manufacturing, and the scenario refers only to steel's links with construction and car plants.","B":"Steel production transforms raw materials into a physical product, so it belongs to the secondary sector rather than services. Such a result is not what the question actually requires from the student.","C":"The scenario is about supporting steel, and it makes no claim about whether primary industries need assistance. This error rules the option out and makes the choice incorrect.","D":"Steel is an input for construction and car manufacturing, so a strong secondary sector supports employment and output in industries that depend on it. This linkage is a key reason governments value manufacturing."}}},{"id":"P1_U1_MCQ_1438","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1438","question":"A bakery opens three new outlets and increases advertising in its existing town rather than buying a rival chain. Which method of growth is it using?","options":{"A":"Internal growth","B":"A takeover","C":"A merger","D":"A joint venture"},"correctOption":"A","correctAnswer":"Internal growth","questionType":"MCQ","explanation":{"correct_reason":"The bakery expands by opening its own new outlets and raising advertising, which grows sales from within the existing business. This is internal, or organic, growth rather than growth by acquiring another firm.","distractor_reasons":{"A":"The bakery expands by opening its own new outlets and raising advertising, which grows sales from within the existing business. This is internal, or organic, growth rather than growth by acquiring another firm.","B":"A takeover would mean buying control of the rival chain, which the bakery has explicitly decided not to do. For this reason it clearly cannot be the best answer to the question.","C":"A merger involves combining with another business, but the bakery is expanding its own operations instead. That makes it the wrong choice in the circumstances described in the case.","D":"A joint venture requires a new business shared with another partner, and no partner is described here. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1439","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1439","question":"A group of dairy farmers jointly owns a processing plant and shares the profit according to how much milk each farmer supplies. What type of business organisation is this?","options":{"A":"A public limited company","B":"A sole trader","C":"A cooperative","D":"A franchise"},"correctOption":"C","correctAnswer":"A cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and controlled by its members, who share the benefits in proportion to their use of it. Here the farmers own the plant together and share profit according to milk supplied, which fits that model.","distractor_reasons":{"A":"A public limited company is owned by outside shareholders and listed publicly, not jointly by the farmers who supply it.","B":"A sole trader has one owner, whereas this processing plant is jointly owned by a group of dairy farmers. This leaves it as an incorrect option that should be rejected.","C":"A cooperative is owned and controlled by its members, who share the benefits in proportion to their use of it. Here the farmers own the plant together and share profit according to milk supplied, which fits that model.","D":"A franchise involves paying a brand owner for the right to trade under its name, which is not described here."}}},{"id":"P1_U1_MCQ_1440","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1440","question":"A start-up spends heavily on discounts and advertising to win customers from established rivals and reports a loss in its second year. Which objective is it prioritising?","options":{"A":"Growth and market share over short-term profit","B":"Maximum profit in the current year","C":"Survival with no thought of expansion","D":"Reducing its environmental impact"},"correctOption":"A","correctAnswer":"Growth and market share over short-term profit","questionType":"MCQ","explanation":{"correct_reason":"Heavy spending on discounts and advertising to attract customers sacrifices current profit in order to build sales and market share. The firm is therefore prioritising growth over short-term profitability.","distractor_reasons":{"A":"Heavy spending on discounts and advertising to attract customers sacrifices current profit in order to build sales and market share. The firm is therefore prioritising growth over short-term profitability.","B":"Deliberately accepting a loss while funding discounts and advertising is the opposite of maximising current-year profit. This error rules the option out and makes the choice incorrect.","C":"Discounts and advertising aimed at winning customers show an expansion aim, not a bare fight to survive. The option is therefore mistaken and cannot be the right selection.","D":"No environmental measure is mentioned, and the spending described is directed at customers and sales. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1441","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1441","question":"A landlord receives rent, factory workers receive wages and a bank receives interest on a loan. Which factor of production earns profit as its reward?","options":{"A":"Land","B":"Labour","C":"Enterprise","D":"Capital"},"correctOption":"C","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Enterprise is the factor that organises the other inputs and bears the risk of the business, and its reward is profit. Rent rewards land, wages reward labour and interest rewards capital.","distractor_reasons":{"A":"Land earns rent, which is the payment described for the landlord rather than the profit sought by an entrepreneur. For this reason it clearly cannot be the best answer to the question.","B":"Labour earns wages or salaries, as shown by the factory workers, not profit from risk-bearing. That makes it the wrong choice in the circumstances described in the case.","C":"Enterprise is the factor that organises the other inputs and bears the risk of the business, and its reward is profit. Rent rewards land, wages reward labour and interest rewards capital.","D":"Capital earns interest, as the bank receives on its loan, so it is not the factor rewarded with profit. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1442","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1442","question":"A firm gives insurance advice and processes claims for its clients but makes no physical product at all. Which sector of the economy does it belong to?","options":{"A":"Primary","B":"Tertiary","C":"Secondary","D":"Primary and secondary equally"},"correctOption":"B","correctAnswer":"Tertiary","questionType":"MCQ","explanation":{"correct_reason":"Insurance advice and claims handling are services provided directly to clients, which places the firm in the tertiary sector. No raw material is extracted and no physical good is manufactured.","distractor_reasons":{"A":"The primary sector involves extracting natural resources such as coal or crops, none of which this firm does. This leaves it as an incorrect option that should be rejected.","B":"Insurance advice and claims handling are services provided directly to clients, which places the firm in the tertiary sector. No raw material is extracted and no physical good is manufactured.","C":"The secondary sector makes physical products, but the firm explicitly makes no physical product. Such a result is not what the question actually requires from the student.","D":"The firm's activity is entirely service-based, so it cannot be split equally between primary and secondary activity. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1443","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1443","question":"After doubling its number of outlets in one year, a sandwich chain finds stock control and staff communication at head office have deteriorated. What does this illustrate?","options":{"A":"A problem of rapid business growth","B":"The benefits of economies of scale","C":"A reason to become a sole trader","D":"The effect of lower fixed costs"},"correctOption":"A","correctAnswer":"A problem of rapid business growth","questionType":"MCQ","explanation":{"correct_reason":"Fast expansion has stretched the chain's systems, so stock control and communication have suffered. These coordination problems are a recognised drawback of growing too quickly.","distractor_reasons":{"A":"Fast expansion has stretched the chain's systems, so stock control and communication have suffered. These coordination problems are a recognised drawback of growing too quickly.","B":"Economies of scale would show as falling unit costs, whereas the scenario reports control and communication problems instead. The option is therefore mistaken and cannot be the right selection.","C":"Becoming a sole trader would reduce the scale of the business and does not follow from problems caused by expansion.","D":"No fall in fixed costs is described, and the issues concern coordination rather than cost savings. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1444","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1444","question":"A local construction firm and a foreign engineering group create a new, separately owned company to build a bridge, sharing the costs and technical expertise. Which form of organisation is this?","options":{"A":"A sole trader","B":"A joint venture","C":"A franchise","D":"A public corporation"},"correctOption":"B","correctAnswer":"A joint venture","questionType":"MCQ","explanation":{"correct_reason":"Two independent businesses have set up a new company together, sharing costs, risk and expertise on a specific project. That arrangement is a joint venture, which lets each partner gain from the other's strengths.","distractor_reasons":{"A":"A sole trader is a single owner, but here two separate businesses jointly own the new company. That makes it the wrong choice in the circumstances described in the case.","B":"Two independent businesses have set up a new company together, sharing costs, risk and expertise on a specific project. That arrangement is a joint venture, which lets each partner gain from the other's strengths.","C":"A franchise involves one firm paying another for brand rights, not two firms jointly owning a project company. This leaves it as an incorrect option that should be rejected.","D":"A public corporation is owned by government, whereas this company is created by two private businesses. It therefore cannot be accepted as the correct answer to the question."}}},{"id":"P1_U1_MCQ_1445","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1445","question":"A manufacturer relocates its factory 200 kilometres away to a cheaper site in another region. Which stakeholder group is most directly affected by longer commuting or possible redundancy?","options":{"A":"Customers of the manufacturer","B":"The national government","C":"Suppliers of packaging","D":"The factory's employees"},"correctOption":"D","correctAnswer":"The factory's employees","questionType":"MCQ","explanation":{"correct_reason":"Employees face the immediate choice of a much longer commute or losing their jobs, so relocation affects them most directly. Their livelihoods depend on the workplace that is moving.","distractor_reasons":{"A":"Customers may experience delivery changes, but they do not face commuting or redundancy as a direct result of the move.","B":"The government may lose some tax revenue, but it is not directly exposed to commuting or job loss in the way employees are.","C":"Packaging suppliers may lose an account, yet their day-to-day working lives are not directly disrupted by the commute. This error rules the option out and makes the choice incorrect.","D":"Employees face the immediate choice of a much longer commute or losing their jobs, so relocation affects them most directly. Their livelihoods depend on the workplace that is moving."}}},{"id":"P1_U1_MCQ_1446","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1446","question":"Rosemere Jam produces 1,500 jars in a month. Each jar sells for $24, and the fruit, sugar and jars cost $9 per jar. What is the total added value created in the month?","options":{"A":"$22,500","B":"$36,000","C":"$13,500","D":"$24"},"correctOption":"A","correctAnswer":"$22,500","questionType":"MCQ","explanation":{"correct_reason":"Added value per jar is the $24 selling price minus the $9 of bought-in materials, which equals $15. Multiplying $15 by 1,500 jars gives total added value of $22,500 for the month.","distractor_reasons":{"A":"Added value per jar is the $24 selling price minus the $9 of bought-in materials, which equals $15. Multiplying $15 by 1,500 jars gives total added value of $22,500 for the month.","B":"$36,000 is the total revenue from 1,500 jars at $24 each, before any bought-in material costs are deducted. For this reason it clearly cannot be the best answer to the question.","C":"$13,500 is the total spent on fruit, sugar and jars, which is a cost rather than the value the business adds.","D":"$24 is the price of a single jar and takes no account of materials or the 1,500 jars produced. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1447","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1447","question":"A country has a GDP of $500 billion, of which manufacturing, construction and utilities contribute $125 billion. What percentage of GDP comes from the secondary sector?","options":{"A":"20%","B":"25%","C":"75%","D":"40%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Secondary sector output is $125 billion out of a total GDP of $500 billion. Dividing $125 billion by $500 billion and multiplying by 100 gives 25% of GDP from the secondary sector.","distractor_reasons":{"A":"20% would mean $100 billion of secondary output, but the figure given is $125 billion out of the $500 billion total.","B":"Secondary sector output is $125 billion out of a total GDP of $500 billion. Dividing $125 billion by $500 billion and multiplying by 100 gives 25% of GDP from the secondary sector.","C":"75% is the share of GDP from the other sectors, so it answers a different question from the one asked.","D":"40% would require $200 billion of secondary output, which is well above the stated $125 billion. Such a result is not what the question actually requires from the student."}}},{"id":"P1_U1_MCQ_1448","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1448","question":"Yardley Furnishings saw its annual revenue rise from $320,000 to $368,000 during the year after a successful advertising campaign. What was the percentage increase in revenue?","options":{"A":"12.8%","B":"48%","C":"15%","D":"13%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $368,000 minus $320,000, which is $48,000. Dividing the $48,000 increase by the original $320,000 and multiplying by 100 gives a 15% increase.","distractor_reasons":{"A":"12.8% divides the $48,000 increase by the new $368,000 figure, but percentage change uses the original $320,000 as the base.","B":"48% confuses the $48,000 cash increase with a percentage of the original revenue. This error rules the option out and makes the choice incorrect.","C":"Revenue rose by $368,000 minus $320,000, which is $48,000. Dividing the $48,000 increase by the original $320,000 and multiplying by 100 gives a 15% increase.","D":"13% does not match the correct division of $48,000 by $320,000, which gives exactly 15%. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1449","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1449","question":"Brambleford Textiles needs to raise $600,000 to buy new looms by issuing 240,000 ordinary shares to private investors. At what price must each share be issued?","options":{"A":"$2.50","B":"$0.40","C":"$2.40","D":"$6.00"},"correctOption":"A","correctAnswer":"$2.50","questionType":"MCQ","explanation":{"correct_reason":"The required capital is divided by the number of shares issued. $600,000 divided by 240,000 shares equals $2.50 per share, which is the issue price needed to raise the target amount.","distractor_reasons":{"A":"The required capital is divided by the number of shares issued. $600,000 divided by 240,000 shares equals $2.50 per share, which is the issue price needed to raise the target amount.","B":"$0.40 comes from dividing 240,000 shares by $600,000, which reverses the calculation and raises only $96,000. That makes it the wrong choice in the circumstances described in the case.","C":"$2.40 would raise $576,000, which is $24,000 short of the $600,000 the company needs. So it should not be selected as the correct option in this situation.","D":"$6.00 would raise $1,440,000, far more than the $600,000 target, so the division is incorrect. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1450","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1450","question":"A worker-owned firm sets aside a profit-sharing pool of $36,000 to be divided equally among its 45 employees at the end of the year. How much does each employee receive?","options":{"A":"$450","B":"$800","C":"$1,620","D":"$36,000"},"correctOption":"B","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"The pool is shared equally, so $36,000 is divided by 45 employees. That equals $800 per employee, which is the individual profit share for the year.","distractor_reasons":{"A":"$450 would result from dividing $36,000 by 80 employees, not by the stated 45 employees. This leaves it as an incorrect option that should be rejected.","B":"The pool is shared equally, so $36,000 is divided by 45 employees. That equals $800 per employee, which is the individual profit share for the year.","C":"$1,620 comes from dividing $36,000 by roughly 22 people, so the number of employees has been misapplied. Such a result is not what the question actually requires from the student.","D":"$36,000 is the whole pool and would give every employee the entire amount, ignoring the equal sharing among 45 workers."}}},{"id":"P1_U1_MCQ_1451","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1451","question":"A coastal town has enough land for either a new housing estate or a business park, but not both, and there is demand for each. What fundamental economic problem does this show?","options":{"A":"Land is an unlimited resource in the town","B":"Choosing one use has no opportunity cost","C":"Scarcity of land forces a choice between competing uses","D":"Housing and business premises are free goods"},"correctOption":"C","correctAnswer":"Scarcity of land forces a choice between competing uses","questionType":"MCQ","explanation":{"correct_reason":"There is only enough land for one project although both are wanted, so land is scarce relative to demand. The town must choose, and the project not built becomes the opportunity cost.","distractor_reasons":{"A":"The town cannot satisfy both uses, which shows land is limited rather than unlimited. This error rules the option out and makes the choice incorrect.","B":"Building the housing estate means giving up the business park, so a clear opportunity cost does exist. The option is therefore mistaken and cannot be the right selection.","C":"There is only enough land for one project although both are wanted, so land is scarce relative to demand. The town must choose, and the project not built becomes the opportunity cost.","D":"Both projects require costly land and construction, so neither housing nor business premises is a free good. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1452","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1452","question":"A furniture maker buys oak from a forestry firm and sells its chairs through a furniture retailer. Which statement best describes the links shown in this chain?","options":{"A":"The primary firm is unnecessary to the furniture maker","B":"The retailer manufactures the chairs itself","C":"All the output stays within the secondary sector","D":"The sectors are interdependent, with each stage adding value"},"correctOption":"D","correctAnswer":"The sectors are interdependent, with each stage adding value","questionType":"MCQ","explanation":{"correct_reason":"The forestry firm supplies timber, the furniture maker turns it into chairs and the retailer sells them, so each stage depends on the others. Together the three sectors form an interdependent chain in which value is added at each stage.","distractor_reasons":{"A":"The furniture maker needs the forestry firm's oak, so the primary supplier is essential rather than unnecessary. That makes it the wrong choice in the circumstances described in the case.","B":"The retailer sells the finished chairs to customers and does not manufacture them in this chain. So it should not be selected as the correct option in this situation.","C":"The chain includes primary forestry and tertiary retailing, so output does not stay only in the secondary sector. This leaves it as an incorrect option that should be rejected.","D":"The forestry firm supplies timber, the furniture maker turns it into chairs and the retailer sells them, so each stage depends on the others. Together the three sectors form an interdependent chain in which value is added at each stage."}}},{"id":"P1_U1_MCQ_1453","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1453","question":"Amir prepares a detailed business plan before approaching a bank for a $40,000 loan to open a bicycle workshop. What is the main benefit of doing this?","options":{"A":"It guarantees that the workshop will make a profit","B":"It shows the idea has been researched and is financially viable, improving the chance of a loan","C":"It removes the need for any start-up capital","D":"It transfers all business risk to the bank"},"correctOption":"B","correctAnswer":"It shows the idea has been researched and is financially viable, improving the chance of a loan","questionType":"MCQ","explanation":{"correct_reason":"A business plan sets out the market, costs, expected revenue and finance needed, which shows the bank that Amir has researched the idea. A convincing plan improves his chance of securing the $40,000 loan.","distractor_reasons":{"A":"No plan can guarantee profit, since demand and costs may still change after the workshop opens. It therefore cannot be accepted as the correct answer to the question.","B":"A business plan sets out the market, costs, expected revenue and finance needed, which shows the bank that Amir has researched the idea. A convincing plan improves his chance of securing the $40,000 loan.","C":"The plan may help Amir obtain finance, but he still needs the $40,000 capital to equip and open the workshop.","D":"The bank lends money but does not take over the risks of running the bicycle workshop, which remain with Amir."}}},{"id":"P1_U1_MCQ_1454","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1454","question":"Why can a growing private limited company raise more capital than a sole trader while still protecting the owners' personal assets if the firm fails?","options":{"A":"It has no legal identity of its own","B":"Its owners all have unlimited liability","C":"It can sell shares to several investors and its owners have limited liability","D":"It is always owned by the government"},"correctOption":"C","correctAnswer":"It can sell shares to several investors and its owners have limited liability","questionType":"MCQ","explanation":{"correct_reason":"A private limited company can issue shares to a number of investors, which brings in more capital than one owner could provide. Because it is a separate legal entity, shareholders have limited liability and risk only the capital they invested.","distractor_reasons":{"A":"A private limited company does have its own legal identity, which is precisely what separates the company's debts from its owners.","B":"Unlimited liability would deter investors and expose owners' personal assets, which is not the protection described. For this reason it clearly cannot be the best answer to the question.","C":"A private limited company can issue shares to a number of investors, which brings in more capital than one owner could provide. Because it is a separate legal entity, shareholders have limited liability and risk only the capital they invested.","D":"Government ownership describes a public corporation, not a private limited company with private shareholders. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1455","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1455","question":"A shareholder buys shares in a supermarket chain mainly to receive an annual dividend and to gain from a rise in the share price. Which objective does this reflect?","options":{"A":"Improving employees' working conditions","B":"Protecting the local environment","C":"Increasing the range of products sold","D":"Maximising the return on the shareholder's investment"},"correctOption":"D","correctAnswer":"Maximising the return on the shareholder's investment","questionType":"MCQ","explanation":{"correct_reason":"Dividends and capital gains are the financial returns a shareholder receives, so this investor is seeking the highest possible return. That is the shareholder objective of maximising return on investment.","distractor_reasons":{"A":"Better working conditions may help a business, but this shareholder is motivated by dividends and share price gains. So it should not be selected as the correct option in this situation.","B":"Environmental protection is a community or social objective, not the financial return described here. This leaves it as an incorrect option that should be rejected.","C":"A wider product range is a marketing or growth aim, not the direct reason this shareholder is investing. It therefore cannot be accepted as the correct answer to the question.","D":"Dividends and capital gains are the financial returns a shareholder receives, so this investor is seeking the highest possible return. That is the shareholder objective of maximising return on investment."}}},{"id":"P1_U1_MCQ_1456","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1456","question":"A coffee roaster charges cafes a premium because it offers a distinctive brand, attractive packaging and free barista training. Which source of added value is mainly described?","options":{"A":"Branding and service quality","B":"Cheaper raw materials","C":"A larger factory","D":"Government subsidies"},"correctOption":"A","correctAnswer":"Branding and service quality","questionType":"MCQ","explanation":{"correct_reason":"The roaster adds value through a recognised brand, appealing packaging and free training, which let it charge more than a generic supplier. Branding and service quality are the sources of that extra value.","distractor_reasons":{"A":"The roaster adds value through a recognised brand, appealing packaging and free training, which let it charge more than a generic supplier. Branding and service quality are the sources of that extra value.","B":"No cheaper coffee beans are mentioned, and the premium comes from brand and training rather than lower material costs. This error rules the option out and makes the choice incorrect.","C":"A larger factory could raise output, but it would not by itself explain the higher price cafes are willing to pay.","D":"No subsidy is mentioned, and the premium is attributed to branding, packaging and barista training. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1457","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1457","question":"Four businesses in the same region are a tin mine, a sawmill, a parcel delivery service and a wheat farm. Which one is carrying out a tertiary sector activity?","options":{"A":"A tin mine extracting ore","B":"A sawmill cutting logs into planks","C":"A parcel delivery service transporting online orders","D":"A wheat farm harvesting grain"},"correctOption":"C","correctAnswer":"A parcel delivery service transporting online orders","questionType":"MCQ","explanation":{"correct_reason":"Parcel delivery is a service that moves goods for customers, which makes it a tertiary activity. Mining, sawmilling and farming all involve extracting or processing physical materials.","distractor_reasons":{"A":"A tin mine extracts a natural resource from the ground, which is primary sector activity. For this reason it clearly cannot be the best answer to the question.","B":"A sawmill processes logs into planks, which is manufacturing and therefore secondary sector activity. That makes it the wrong choice in the circumstances described in the case.","C":"Parcel delivery is a service that moves goods for customers, which makes it a tertiary activity. Mining, sawmilling and farming all involve extracting or processing physical materials.","D":"A wheat farm grows and harvests a crop, which is primary sector activity rather than a service. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1458","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1458","question":"A government offers grants, training and advice to people who start small firms in depressed regions. Why might a government encourage new enterprise in this way?","options":{"A":"New firms always pay lower wages","B":"Enterprise removes the need for taxation","C":"Starting a business guarantees export success","D":"New enterprises create jobs, output and tax revenue"},"correctOption":"D","correctAnswer":"New enterprises create jobs, output and tax revenue","questionType":"MCQ","explanation":{"correct_reason":"New firms hire workers, produce goods and services and eventually pay tax, which benefits the wider economy. Supporting enterprise is therefore a way to stimulate employment, output and government revenue.","distractor_reasons":{"A":"Lower wages would reduce living standards and are not the reason governments support start-ups. This leaves it as an incorrect option that should be rejected.","B":"New businesses generate tax revenue rather than removing the need for taxation, which funds public services. It therefore cannot be accepted as the correct answer to the question.","C":"Most new firms serve local markets, and starting up cannot guarantee success in exporting. Such a result is not what the question actually requires from the student.","D":"New firms hire workers, produce goods and services and eventually pay tax, which benefits the wider economy. Supporting enterprise is therefore a way to stimulate employment, output and government revenue."}}},{"id":"P1_U1_MCQ_1459","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1459","question":"A franchisee must pay 8% of revenue to the franchisor and follow set menus, suppliers and prices. What is a disadvantage of this arrangement for the franchisee?","options":{"A":"The royalty reduces profit and the franchisee has little independence","B":"The franchisee cannot use an established brand name","C":"The franchisee has to design every product from scratch","D":"The franchisee receives no training or support"},"correctOption":"A","correctAnswer":"The royalty reduces profit and the franchisee has little independence","questionType":"MCQ","explanation":{"correct_reason":"Paying 8% of revenue away lowers the profit the franchisee keeps, and the fixed menus, suppliers and prices leave little freedom to run the outlet differently. These are the main costs of buying into a franchise.","distractor_reasons":{"A":"Paying 8% of revenue away lowers the profit the franchisee keeps, and the fixed menus, suppliers and prices leave little freedom to run the outlet differently. These are the main costs of buying into a franchise.","B":"Using the established brand is the main benefit of a franchise, so the franchisee does have access to it. The option is therefore mistaken and cannot be the right selection.","C":"Products are set by the franchisor, which means the franchisee avoids designing them from scratch. For this reason it clearly cannot be the best answer to the question.","D":"Franchisors typically provide training and support, and the scenario mentions set menus and suppliers rather than a lack of help."}}},{"id":"P1_U1_MCQ_1460","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1460","question":"A nightclub's neighbours complain about late-night noise and litter, while the owner wants to extend opening hours to raise profit. Which conflict between stakeholders is shown?","options":{"A":"Employees and suppliers","B":"Local residents' quality of life and the owner's profit objective","C":"Customers and the government","D":"Managers and shareholders"},"correctOption":"B","correctAnswer":"Local residents' quality of life and the owner's profit objective","questionType":"MCQ","explanation":{"correct_reason":"Residents want quieter nights, while the owner wants longer hours to increase profit, so their objectives clash directly. This is a classic conflict between a local community and a business owner.","distractor_reasons":{"A":"Employees and suppliers are not mentioned, and the dispute is between nearby residents and the nightclub owner. That makes it the wrong choice in the circumstances described in the case.","B":"Residents want quieter nights, while the owner wants longer hours to increase profit, so their objectives clash directly. This is a classic conflict between a local community and a business owner.","C":"Customers may welcome longer hours, and no government objective is described in the scenario. This leaves it as an incorrect option that should be rejected.","D":"The owner and managers would normally share the profit objective, so they are not the conflicting groups here. It therefore cannot be accepted as the correct answer to the question."}}},{"id":"P1_U1_MCQ_1461","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1461","question":"A builder can keep her van for delivery work expected to earn $18,000 a year, or sell it immediately for $15,000. If she keeps the van, what is the annual opportunity cost of that decision?","options":{"A":"$18,000","B":"$3,000","C":"$33,000","D":"$15,000"},"correctOption":"D","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"The next best alternative to keeping the van is selling it for $15,000, so that forgone amount is the opportunity cost. The $18,000 delivery income is the return from the option she actually chooses.","distractor_reasons":{"A":"$18,000 is the income expected from using the van for deliveries, which is the chosen option's benefit rather than the alternative given up.","B":"$3,000 is merely the difference between the delivery income and the sale price, not the value of the alternative forgone.","C":"$33,000 adds the sale price to the delivery income, which double counts the van's value and misstates opportunity cost. This error rules the option out and makes the choice incorrect.","D":"The next best alternative to keeping the van is selling it for $15,000, so that forgone amount is the opportunity cost. The $18,000 delivery income is the return from the option she actually chooses."}}},{"id":"P1_U1_MCQ_1462","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1462","question":"An economy has total output of $80 billion, made up of $6 billion from primary industries and $24 billion from secondary industries. What percentage of output comes from the tertiary sector?","options":{"A":"62.5%","B":"30%","C":"7.5%","D":"37.5%"},"correctOption":"A","correctAnswer":"62.5%","questionType":"MCQ","explanation":{"correct_reason":"Primary and secondary output together total $30 billion, so the tertiary sector contributes $80 billion minus $30 billion, which is $50 billion. Dividing $50 billion by $80 billion and multiplying by 100 gives 62.5%.","distractor_reasons":{"A":"Primary and secondary output together total $30 billion, so the tertiary sector contributes $80 billion minus $30 billion, which is $50 billion. Dividing $50 billion by $80 billion and multiplying by 100 gives 62.5%.","B":"30% is the secondary sector's $24 billion share of the $80 billion total, not the tertiary share. For this reason it clearly cannot be the best answer to the question.","C":"7.5% is the primary sector's $6 billion share, which is far too small to represent the tertiary sector. That makes it the wrong choice in the circumstances described in the case.","D":"37.5% is the combined primary and secondary share of $30 billion, not the tertiary sector alone. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1463","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1463","question":"Dunmore Cycles sells 9,000 bicycles in a year when the total market for bicycles is 180,000 units across the country. What is Dunmore Cycles' market share?","options":{"A":"4.5%","B":"5%","C":"9%","D":"20%"},"correctOption":"B","correctAnswer":"5%","questionType":"MCQ","explanation":{"correct_reason":"Market share is Dunmore's sales divided by total market sales: 9,000 divided by 180,000 equals 0.05. Multiplying by 100 gives a market share of 5%.","distractor_reasons":{"A":"4.5% would correspond to sales of 8,100 bicycles, but Dunmore actually sells 9,000 units. So it should not be selected as the correct option in this situation.","B":"Market share is Dunmore's sales divided by total market sales: 9,000 divided by 180,000 equals 0.05. Multiplying by 100 gives a market share of 5%.","C":"9% mistakes the 9,000 bicycles sold for a percentage instead of dividing by the 180,000-unit market. It therefore cannot be accepted as the correct answer to the question.","D":"20% comes from dividing 180,000 by 9,000, which reverses the market share calculation. Such a result is not what the question actually requires from the student."}}},{"id":"P1_U1_MCQ_1464","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1464","question":"A franchisee's outlet takes $48,000 of revenue in a month and pays the franchisor a royalty of 7% of revenue. How much royalty is payable for that month?","options":{"A":"$560","B":"$4,800","C":"$3,360","D":"$33,600"},"correctOption":"C","correctAnswer":"$3,360","questionType":"MCQ","explanation":{"correct_reason":"The royalty is 7% of the $48,000 monthly revenue. Multiplying $48,000 by 0.07 gives $3,360, which is the amount owed to the franchisor for the month.","distractor_reasons":{"A":"$560 would be 7% of only $8,000 of revenue, but the outlet took $48,000 in the month. Such a result is not what the question actually requires from the student.","B":"$4,800 is 10% of $48,000, so it applies the wrong royalty rate to the correct revenue. This error rules the option out and makes the choice incorrect.","C":"The royalty is 7% of the $48,000 monthly revenue. Multiplying $48,000 by 0.07 gives $3,360, which is the amount owed to the franchisor for the month.","D":"$33,600 is 7% of $480,000, which misplaces a zero in the monthly revenue figure. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1465","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1465","question":"A family-owned printer makes a profit of $180,000 and spends $27,000 sponsoring a local sports league. What percentage of its profit is spent on this community sponsorship?","options":{"A":"15%","B":"6.7%","C":"27%","D":"12%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The sponsorship is $27,000 out of a $180,000 profit. Dividing $27,000 by $180,000 and multiplying by 100 gives 15%, the share of profit committed to the community.","distractor_reasons":{"A":"The sponsorship is $27,000 out of a $180,000 profit. Dividing $27,000 by $180,000 and multiplying by 100 gives 15%, the share of profit committed to the community.","B":"6.7% divides the $180,000 profit by the $27,000 sponsorship, which reverses the calculation. That makes it the wrong choice in the circumstances described in the case.","C":"27% confuses the $27,000 cash amount with a percentage of the $180,000 profit. So it should not be selected as the correct option in this situation.","D":"12% does not follow from $27,000 divided by $180,000, which equals exactly 15%. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1466","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1466","question":"A courier firm buys five electric vans to add to its delivery fleet and reduce fuel costs. Which factor of production do the vans represent?","options":{"A":"Land","B":"Capital","C":"Labour","D":"Enterprise"},"correctOption":"B","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"The vans are manufactured goods used to help produce the delivery service, which makes them capital. They are not natural resources, workers or the risk-taking that organised the business.","distractor_reasons":{"A":"Land refers to natural resources such as the site the depot stands on, not to manufactured vehicles. This leaves it as an incorrect option that should be rejected.","B":"The vans are manufactured goods used to help produce the delivery service, which makes them capital. They are not natural resources, workers or the risk-taking that organised the business.","C":"Labour is human effort supplied by the drivers, whereas the vans are equipment owned by the firm. Such a result is not what the question actually requires from the student.","D":"Enterprise is the risk-taking and organising role of the owner, not the physical delivery vehicles themselves. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1467","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1467","question":"A former textile town now has empty mills and growing employment in warehousing and care homes on the edge of town. Which consequence of deindustrialisation does this best show?","options":{"A":"Primary employment has risen sharply","B":"Manufacturing has expanded into new mills","C":"Manufacturing jobs have been replaced by service employment, leaving unused industrial sites","D":"All workers have moved into farming"},"correctOption":"C","correctAnswer":"Manufacturing jobs have been replaced by service employment, leaving unused industrial sites","questionType":"MCQ","explanation":{"correct_reason":"The textile mills, which were secondary industry, have closed and new jobs are in warehousing and care, which are services. The empty mills are the visible sign of that shift from manufacturing to tertiary employment.","distractor_reasons":{"A":"No growth in farming or extraction is described, and the new jobs are in services rather than primary industries. This error rules the option out and makes the choice incorrect.","B":"The mills are described as empty, which shows manufacturing has contracted rather than expanded. The option is therefore mistaken and cannot be the right selection.","C":"The textile mills, which were secondary industry, have closed and new jobs are in warehousing and care, which are services. The empty mills are the visible sign of that shift from manufacturing to tertiary employment.","D":"The new employment is in warehousing and care homes, not in farming or other primary activity. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1468","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1468","question":"Why might a small bakery prefer to take over a rival bakery nearby rather than open a completely new outlet from scratch in the same town?","options":{"A":"A takeover always costs less than opening a shop","B":"A takeover removes all competition permanently","C":"A takeover avoids the need for any staff","D":"It gains an established customer base and market share immediately"},"correctOption":"D","correctAnswer":"It gains an established customer base and market share immediately","questionType":"MCQ","explanation":{"correct_reason":"Buying an existing bakery gives the owner its customers, reputation and sales straight away, so market share grows without waiting for a new outlet to attract trade. Speed of gaining custom is the main attraction.","distractor_reasons":{"A":"A takeover often costs more than fitting out a new shop because the buyer pays for goodwill and existing equipment.","B":"Other bakeries and shops may still compete, so a single takeover does not remove all competition permanently. So it should not be selected as the correct option in this situation.","C":"The existing bakery already employs staff who usually transfer with the business, so no staffing need is avoided. This leaves it as an incorrect option that should be rejected.","D":"Buying an existing bakery gives the owner its customers, reputation and sales straight away, so market share grows without waiting for a new outlet to attract trade. Speed of gaining custom is the main attraction."}}},{"id":"P1_U1_MCQ_1469","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1469","question":"A successful private limited company wants to expand rapidly by building a new factory. What is a main advantage of converting the company into a public limited company?","options":{"A":"It no longer has to publish annual accounts","B":"It can raise large amounts of capital by selling shares to the public","C":"It becomes exempt from corporation tax","D":"Its shareholders gain unlimited liability"},"correctOption":"B","correctAnswer":"It can raise large amounts of capital by selling shares to the public","questionType":"MCQ","explanation":{"correct_reason":"A public limited company can offer its shares to the general public through a stock exchange, which allows it to raise far more capital than a private company. That access to wide investment is the main advantage.","distractor_reasons":{"A":"Public companies face stricter disclosure rules, so they must publish more financial information rather than less. It therefore cannot be accepted as the correct answer to the question.","B":"A public limited company can offer its shares to the general public through a stock exchange, which allows it to raise far more capital than a private company. That access to wide investment is the main advantage.","C":"Listing does not exempt a company from corporation tax, which remains payable on its profits. This error rules the option out and makes the choice incorrect.","D":"Shareholders of a public limited company have limited liability, so their personal assets remain protected. The option is therefore mistaken and cannot be the right selection."}}},{"id":"P1_U1_MCQ_1470","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1470","question":"A budget airline sets a target of carrying 12 million passengers next year, up from 10 million this year. Which business objective does this target state most directly?","options":{"A":"Profit maximisation","B":"Survival","C":"Growth in passenger numbers and market share","D":"Environmental sustainability"},"correctOption":"C","correctAnswer":"Growth in passenger numbers and market share","questionType":"MCQ","explanation":{"correct_reason":"The airline plans to raise passenger numbers from 10 million to 12 million, which is a growth objective measured by customers carried. More passengers would also tend to increase its market share.","distractor_reasons":{"A":"Carrying more passengers may raise profit, but the stated target is passenger numbers rather than the size of profit. The option is therefore mistaken and cannot be the right selection.","B":"A firm aiming to grow from 10 million to 12 million passengers is expanding rather than merely trying to survive.","C":"The airline plans to raise passenger numbers from 10 million to 12 million, which is a growth objective measured by customers carried. More passengers would also tend to increase its market share.","D":"No environmental measure such as emissions or fuel use is mentioned in the target. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1471","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1471","question":"A hospital separates patient triage, surgery and rehabilitation into specialist teams that each handle one stage. What is the main advantage of this division of labour?","options":{"A":"Every team becomes equally skilled at all tasks","B":"Patients no longer need to be assessed","C":"The hospital needs fewer specialist staff","D":"Specialisation improves speed and expertise at each stage"},"correctOption":"D","correctAnswer":"Specialisation improves speed and expertise at each stage","questionType":"MCQ","explanation":{"correct_reason":"Each team repeats one stage, so its members become quicker and more expert at that work. This specialisation improves both the speed and the quality of triage, surgery and rehabilitation.","distractor_reasons":{"A":"Specialist teams become expert in one stage rather than equally skilled across every stage of patient care. So it should not be selected as the correct option in this situation.","B":"Triage is the assessment stage, so separating it into a specialist team makes assessment more important, not unnecessary. This leaves it as an incorrect option that should be rejected.","C":"Specialisation usually requires more narrowly skilled staff, not fewer, because each stage needs its own experts. It therefore cannot be accepted as the correct answer to the question.","D":"Each team repeats one stage, so its members become quicker and more expert at that work. This specialisation improves both the speed and the quality of triage, surgery and rehabilitation."}}},{"id":"P1_U1_MCQ_1472","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1472","question":"A company uses a fleet of boats to catch wild mackerel, which it sells to fish processors. Which sector of the economy is the company operating in?","options":{"A":"Primary","B":"Secondary","C":"Tertiary","D":"Quaternary"},"correctOption":"A","correctAnswer":"Primary","questionType":"MCQ","explanation":{"correct_reason":"Catching wild fish is extracting a natural resource from the sea, which is primary sector activity. The company does not process the mackerel itself or provide a service to consumers.","distractor_reasons":{"A":"Catching wild fish is extracting a natural resource from the sea, which is primary sector activity. The company does not process the mackerel itself or provide a service to consumers.","B":"The secondary sector processes raw materials into products, but this company only catches and sells the fish. This error rules the option out and makes the choice incorrect.","C":"The tertiary sector provides services, whereas fishing produces a physical catch from a natural resource. The option is therefore mistaken and cannot be the right selection.","D":"The quaternary sector covers knowledge-based services such as research, not commercial fishing. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1473","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1473","question":"A firm's owners want to increase sales so that fixed costs such as factory rent are spread over more units and unit costs fall. Which reason for business growth does this describe?","options":{"A":"To reduce the quality of its products","B":"To avoid all business risk","C":"To benefit from economies of scale","D":"To reduce its total fixed costs"},"correctOption":"C","correctAnswer":"To benefit from economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Spreading fixed costs over more units lowers average cost, which is an economy of scale. Growing sales is therefore a way to benefit from lower unit costs and improved competitiveness.","distractor_reasons":{"A":"Lower quality is not a reason for growth, and spreading fixed costs says nothing about reducing product standards. For this reason it clearly cannot be the best answer to the question.","B":"Growth often increases risk because more capital and capacity are committed, so it does not avoid risk. That makes it the wrong choice in the circumstances described in the case.","C":"Spreading fixed costs over more units lowers average cost, which is an economy of scale. Growing sales is therefore a way to benefit from lower unit costs and improved competitiveness.","D":"Total fixed costs such as rent do not fall; it is the fixed cost per unit that falls as output rises."}}},{"id":"P1_U1_MCQ_1474","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1474","question":"Two partners increasingly disagree about whether to expand, and one threatens to leave the business and sell his share. Which disadvantage of a partnership does this show?","options":{"A":"Profits must always be shared equally","B":"A partnership cannot employ staff","C":"Partners have limited liability for debts","D":"Decision-making can be slowed by disagreements between partners"},"correctOption":"D","correctAnswer":"Decision-making can be slowed by disagreements between partners","questionType":"MCQ","explanation":{"correct_reason":"Because partners share control, a serious disagreement about expansion can block decisions and even break up the business. Shared decision-making is therefore a potential weakness as well as a strength.","distractor_reasons":{"A":"Partners can agree any profit-sharing ratio, so equal sharing is not a required feature of every partnership. This leaves it as an incorrect option that should be rejected.","B":"Partnerships can and commonly do employ staff; the dispute here concerns expansion rather than hiring. It therefore cannot be accepted as the correct answer to the question.","C":"Ordinary partners have unlimited liability, so this statement is false and is not the disadvantage shown. Such a result is not what the question actually requires from the student.","D":"Because partners share control, a serious disagreement about expansion can block decisions and even break up the business. Shared decision-making is therefore a potential weakness as well as a strength."}}},{"id":"P1_U1_MCQ_1475","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1475","question":"A bank has lent $200,000 to an expanding bakery and expects scheduled repayments with interest over five years. Which stakeholder objective does the bank mainly have?","options":{"A":"Timely repayment of the loan with interest","B":"Higher wages for the bakery's staff","C":"Lower prices for the bakery's customers","D":"Rapid growth in the bakery's market share"},"correctOption":"A","correctAnswer":"Timely repayment of the loan with interest","questionType":"MCQ","explanation":{"correct_reason":"A lender earns interest and expects the principal to be repaid on schedule, so the bank's main concern is the bakery's ability to service the $200,000 loan. The bakery's growth matters only as far as it supports repayment.","distractor_reasons":{"A":"A lender earns interest and expects the principal to be repaid on schedule, so the bank's main concern is the bakery's ability to service the $200,000 loan. The bakery's growth matters only as far as it supports repayment.","B":"Higher staff wages would raise the bakery's costs, which is not the bank's objective as a lender. The option is therefore mistaken and cannot be the right selection.","C":"Lower customer prices are a marketing aim and would not directly serve the bank's interest in repayment. For this reason it clearly cannot be the best answer to the question.","D":"Faster growth may help repayments, but the bank's own objective remains the return of its money with interest. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1476","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1476","question":"A bakery can buy oven A, which would save $9,000 a year in fuel, or oven B, which would save $11,000 a year; both cost $30,000. If the owner buys oven A, what is the annual opportunity cost?","options":{"A":"$2,000","B":"$11,000","C":"$9,000","D":"$30,000"},"correctOption":"B","correctAnswer":"$11,000","questionType":"MCQ","explanation":{"correct_reason":"The next best alternative is oven B, whose annual fuel saving is $11,000. By choosing oven A, the owner gives up that $11,000 saving, so it is the annual opportunity cost of the decision.","distractor_reasons":{"A":"$2,000 is only the difference between the two ovens' savings, not the full value of the alternative that is forgone.","B":"The next best alternative is oven B, whose annual fuel saving is $11,000. By choosing oven A, the owner gives up that $11,000 saving, so it is the annual opportunity cost of the decision.","C":"$9,000 is the saving from oven A, which is the option actually chosen rather than the alternative sacrificed. This leaves it as an incorrect option that should be rejected.","D":"$30,000 is the purchase price, which is the same for both ovens and is not the annual benefit given up."}}},{"id":"P1_U1_MCQ_1477","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1477","question":"A region has 2,400 workers: 360 in farming and mining, 840 in manufacturing and the rest in services. What percentage of the workforce is employed in the tertiary sector?","options":{"A":"15%","B":"35%","C":"65%","D":"50%"},"correctOption":"D","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Primary and secondary employment total 1,200 workers, so the tertiary sector employs 2,400 minus 1,200, which is 1,200 people. Dividing 1,200 by 2,400 and multiplying by 100 gives 50%.","distractor_reasons":{"A":"15% is the 360 primary workers as a share of 2,400, not the tertiary share. It therefore cannot be accepted as the correct answer to the question.","B":"35% is the 840 manufacturing workers as a share of the workforce, which is secondary rather than tertiary employment. Such a result is not what the question actually requires from the student.","C":"65% is the combined primary and secondary share, which leaves out the service workers the question asks about. This error rules the option out and makes the choice incorrect.","D":"Primary and secondary employment total 1,200 workers, so the tertiary sector employs 2,400 minus 1,200, which is 1,200 people. Dividing 1,200 by 2,400 and multiplying by 100 gives 50%."}}},{"id":"P1_U1_MCQ_1478","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1478","question":"Harbourline Foods buys a rival supplier, giving it combined sales of 64,000 units in a market where total sales are 800,000 units. What is the combined firm's market share?","options":{"A":"8%","B":"6.4%","C":"12.5%","D":"5%"},"correctOption":"A","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Market share is combined sales divided by total market sales: 64,000 divided by 800,000 equals 0.08. Multiplying by 100 gives an 8% share of the market after the purchase.","distractor_reasons":{"A":"Market share is combined sales divided by total market sales: 64,000 divided by 800,000 equals 0.08. Multiplying by 100 gives an 8% share of the market after the purchase.","B":"6.4% would correspond to 51,200 units sold, not the 64,000 units stated after the purchase. For this reason it clearly cannot be the best answer to the question.","C":"12.5% comes from dividing 800,000 by 64,000, which reverses the market share formula. That makes it the wrong choice in the circumstances described in the case.","D":"5% would require sales of 40,000 units, well below the 64,000 that Harbourline now sells. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1479","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1479","question":"Two partners each take a salary of $20,000, then share the remaining profit equally. The partnership makes a total profit of $70,000. How much does each partner receive altogether?","options":{"A":"$20,000","B":"$35,000","C":"$15,000","D":"$50,000"},"correctOption":"B","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Salaries of $20,000 each use $40,000, leaving $30,000 to split equally, which is $15,000 each. Adding the $15,000 share to the $20,000 salary gives each partner $35,000 in total.","distractor_reasons":{"A":"$20,000 is only the salary and ignores the $15,000 share of the remaining profit each partner also receives. So it should not be selected as the correct option in this situation.","B":"Salaries of $20,000 each use $40,000, leaving $30,000 to split equally, which is $15,000 each. Adding the $15,000 share to the $20,000 salary gives each partner $35,000 in total.","C":"$15,000 is the share of remaining profit alone, without the $20,000 salary that must be added to it. It therefore cannot be accepted as the correct answer to the question.","D":"$50,000 would give one partner most of the $70,000 profit and leaves nothing for the other partner's salary and share."}}},{"id":"P1_U1_MCQ_1480","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1480","question":"A company reports profit after tax of $320,000 and pays $96,000 in dividends to shareholders for the year. What is the retained profit for the year?","options":{"A":"$96,000","B":"$320,000","C":"$224,000","D":"$416,000"},"correctOption":"C","correctAnswer":"$224,000","questionType":"MCQ","explanation":{"correct_reason":"Retained profit is the profit after tax minus the dividends paid. $320,000 minus $96,000 equals $224,000, which stays in the business to fund future investment.","distractor_reasons":{"A":"$96,000 is the dividend paid out to shareholders, which is the opposite of the profit retained. Such a result is not what the question actually requires from the student.","B":"$320,000 is the whole profit after tax and takes no account of the $96,000 distributed as dividends. This error rules the option out and makes the choice incorrect.","C":"Retained profit is the profit after tax minus the dividends paid. $320,000 minus $96,000 equals $224,000, which stays in the business to fund future investment.","D":"$416,000 adds the dividend to the profit instead of subtracting it, which overstates the retained amount. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1481","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1481","question":"A family replaces its old fridge with an efficient model but delays buying a second television. Which statement best explains how these purchases are classified?","options":{"A":"The fridge is a need because it stores food safely, while the television is a want","B":"The fridge is a want and the television is a need","C":"Both items are needs because they are electrical goods","D":"Both items are wants because neither is essential to life"},"correctOption":"A","correctAnswer":"The fridge is a need because it stores food safely, while the television is a want","questionType":"MCQ","explanation":{"correct_reason":"A fridge helps preserve food and supports basic household health, so it is treated as a need. A second television provides entertainment rather than survival, so it is a want that can be postponed.","distractor_reasons":{"A":"A fridge helps preserve food and supports basic household health, so it is treated as a need. A second television provides entertainment rather than survival, so it is a want that can be postponed.","B":"This reverses the classification, since food storage is more essential than a second television for entertainment. That makes it the wrong choice in the circumstances described in the case.","C":"Being electrical does not make an item a need; a second television is a luxury rather than a necessity. So it should not be selected as the correct option in this situation.","D":"The fridge meets a basic need for safe food storage, so it cannot be grouped with the television as a pure want."}}},{"id":"P1_U1_MCQ_1482","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1482","question":"In a high-income economy, most workers are employed in retail, finance, health and education rather than factories or farms. Which statement about the structure of that economy is correct?","options":{"A":"The primary sector employs the largest share of workers","B":"The tertiary sector employs the largest share of workers","C":"The secondary sector employs the largest share of workers","D":"The primary sector has disappeared completely"},"correctOption":"B","correctAnswer":"The tertiary sector employs the largest share of workers","questionType":"MCQ","explanation":{"correct_reason":"Retail, finance, health and education are all services, so the tertiary sector is the largest employer. This pattern is typical of high-income economies, where manufacturing and farming employ a smaller share.","distractor_reasons":{"A":"Farming and mining are not listed among the main employers, so the primary sector is not the largest. This leaves it as an incorrect option that should be rejected.","B":"Retail, finance, health and education are all services, so the tertiary sector is the largest employer. This pattern is typical of high-income economies, where manufacturing and farming employ a smaller share.","C":"Factories are not the main employers in the sectors listed, which are all service activities. Such a result is not what the question actually requires from the student.","D":"A small primary sector may remain even in high-income economies, so it has not necessarily disappeared completely. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1483","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1483","question":"Two rival brewers want to compare how dominant each is within the national beer market before a planned merger. Which measure is most useful for this purpose?","options":{"A":"The number of employees each brewer has","B":"The total value of each brewer's assets","C":"Each brewer's market share","D":"The number of years each brewer has traded"},"correctOption":"C","correctAnswer":"Each brewer's market share","questionType":"MCQ","explanation":{"correct_reason":"Market share expresses a firm's sales as a percentage of total market sales, so it directly shows how dominant each brewer is. Employee numbers, assets and age describe size or history but not control of the market.","distractor_reasons":{"A":"Employee numbers show how labour-intensive a brewer is, but not how much of the beer market it controls. This error rules the option out and makes the choice incorrect.","B":"Total assets indicate the scale of the business, yet they say nothing about its share of national beer sales. The option is therefore mistaken and cannot be the right selection.","C":"Market share expresses a firm's sales as a percentage of total market sales, so it directly shows how dominant each brewer is. Employee numbers, assets and age describe size or history but not control of the market.","D":"Years of trading show experience and history, not the proportion of the market each brewer currently supplies. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1484","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1484","question":"A florist who runs a small shop is deciding whether to remain a sole trader or incorporate as a limited company. Why might she stay a sole trader?","options":{"A":"To gain limited liability for business debts","B":"To sell shares to the public","C":"To avoid paying any tax on profit","D":"To keep all profit and retain full control with simple set-up"},"correctOption":"D","correctAnswer":"To keep all profit and retain full control with simple set-up","questionType":"MCQ","explanation":{"correct_reason":"A sole trader keeps every pound of profit and makes decisions alone, and the business is simple and cheap to establish. Those advantages can outweigh the benefits of incorporation for a small florist.","distractor_reasons":{"A":"Limited liability comes from incorporation, so remaining a sole trader keeps the owner personally liable rather than gaining protection. That makes it the wrong choice in the circumstances described in the case.","B":"Only a public limited company can offer shares to the public, which a sole trader cannot do. So it should not be selected as the correct option in this situation.","C":"A sole trader still pays income tax on business profit, so remaining unincorporated does not remove tax. This leaves it as an incorrect option that should be rejected.","D":"A sole trader keeps every pound of profit and makes decisions alone, and the business is simple and cheap to establish. Those advantages can outweigh the benefits of incorporation for a small florist."}}},{"id":"P1_U1_MCQ_1485","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1485","question":"During a recession a hotel cuts room prices and postpones refurbishment simply to keep trading through the downturn and retain its staff. Which objective is it pursuing?","options":{"A":"Profit maximisation","B":"Survival","C":"Rapid expansion","D":"An increase in market share"},"correctOption":"B","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Cutting prices and delaying investment are defensive steps to keep the hotel open when demand is weak. The aim is to survive the recession rather than to maximise profit or expand.","distractor_reasons":{"A":"Lower prices and postponed investment reduce short-term profit, so this is not profit maximisation. It therefore cannot be accepted as the correct answer to the question.","B":"Cutting prices and delaying investment are defensive steps to keep the hotel open when demand is weak. The aim is to survive the recession rather than to maximise profit or expand.","C":"Delaying refurbishment and cutting prices shrink the business rather than support rapid expansion. This error rules the option out and makes the choice incorrect.","D":"The hotel is trying to stay afloat, not to win a larger share of a shrinking market. The option is therefore mistaken and cannot be the right selection."}}},{"id":"P1_U1_MCQ_1486","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1486","question":"A car plant installs robots for welding but still needs skilled workers to program and inspect them. What does this show about capital and labour?","options":{"A":"Capital can fully replace labour in every task","B":"Labour is no longer needed in manufacturing","C":"Capital and labour are complementary, with machinery raising productivity but requiring skills","D":"Robots are a natural resource rather than capital"},"correctOption":"C","correctAnswer":"Capital and labour are complementary, with machinery raising productivity but requiring skills","questionType":"MCQ","explanation":{"correct_reason":"The robots do the welding but need skilled workers to program and inspect them, so capital and labour work together. Machinery raises output per worker but does not remove the need for human skill.","distractor_reasons":{"A":"The need for programmers and inspectors shows that capital cannot fully replace labour in this plant. The option is therefore mistaken and cannot be the right selection.","B":"Skilled workers are still employed to run and check the robots, so labour remains essential. For this reason it clearly cannot be the best answer to the question.","C":"The robots do the welding but need skilled workers to program and inspect them, so capital and labour work together. Machinery raises output per worker but does not remove the need for human skill.","D":"Robots are manufactured equipment used in production, which makes them capital rather than a natural resource. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1487","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1487","question":"In a developing country, mining provides 60% of export earnings but employs only 8% of the workforce. What does this suggest about the primary sector there?","options":{"A":"It employs the majority of all workers","B":"It produces no output for export","C":"It is entirely owned by the government","D":"It can dominate exports while employing relatively few people"},"correctOption":"D","correctAnswer":"It can dominate exports while employing relatively few people","questionType":"MCQ","explanation":{"correct_reason":"Mining generates most export revenue but only 8% of jobs, which shows it is capital-intensive. A primary industry can therefore be vital for foreign earnings without employing most of the workforce.","distractor_reasons":{"A":"Only 8% of workers are employed in mining, so the primary sector does not employ the majority. So it should not be selected as the correct option in this situation.","B":"Mining supplies 60% of export earnings, so it clearly produces substantial output for export. This leaves it as an incorrect option that should be rejected.","C":"No information about ownership is given, and state ownership does not follow from the employment and export figures. It therefore cannot be accepted as the correct answer to the question.","D":"Mining generates most export revenue but only 8% of jobs, which shows it is capital-intensive. A primary industry can therefore be vital for foreign earnings without employing most of the workforce."}}},{"id":"P1_U1_MCQ_1488","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1488","question":"Two competing house-building firms of roughly equal size agree to combine into a single company with shared ownership. Which method of growth does this describe?","options":{"A":"A merger","B":"A takeover","C":"Internal growth","D":"A franchise"},"correctOption":"A","correctAnswer":"A merger","questionType":"MCQ","explanation":{"correct_reason":"The two firms agree to join together as one company of roughly equal size, which is a merger. A takeover would involve one firm buying control of the other rather than an agreed combination.","distractor_reasons":{"A":"The two firms agree to join together as one company of roughly equal size, which is a merger. A takeover would involve one firm buying control of the other rather than an agreed combination.","B":"A takeover means one business buys control of another, but here the firms combine as roughly equal partners. This error rules the option out and makes the choice incorrect.","C":"Internal growth comes from expanding the firm's own operations, not from joining with a competitor. The option is therefore mistaken and cannot be the right selection.","D":"A franchise involves paying for brand rights, which is unrelated to two builders combining into one company. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1489","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1489","question":"A shareholder has invested $5,000 in a company that now cannot pay its debts after a collapse. What does limited liability mean for this shareholder's personal assets?","options":{"A":"They must pay every business debt from their personal savings","B":"They are personally responsible for the firm's borrowings","C":"They can lose only the money they invested in their shares","D":"They can never lose any money at all"},"correctOption":"C","correctAnswer":"They can lose only the money they invested in their shares","questionType":"MCQ","explanation":{"correct_reason":"Limited liability means a shareholder's maximum loss is the amount paid for their shares. Their personal assets, such as a home, are protected if the company fails.","distractor_reasons":{"A":"Unlimited liability would expose personal savings, but limited liability protects them beyond the share investment. For this reason it clearly cannot be the best answer to the question.","B":"Shareholders are not personally liable for company borrowings under limited liability, which is the protection it gives. That makes it the wrong choice in the circumstances described in the case.","C":"Limited liability means a shareholder's maximum loss is the amount paid for their shares. Their personal assets, such as a home, are protected if the company fails.","D":"Shareholders can lose the value of their shares if the company fails, so they are not completely protected from loss."}}},{"id":"P1_U1_MCQ_1490","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1490","question":"A supermarket's customers complain about long queues at the checkouts and stale produce on the shelves. Which stakeholder group's objective is clearly not being met?","options":{"A":"Shareholders' desire for dividends","B":"Employees' desire for training","C":"Suppliers' desire for prompt payment","D":"Customers' desire for good quality and service"},"correctOption":"D","correctAnswer":"Customers' desire for good quality and service","questionType":"MCQ","explanation":{"correct_reason":"Long queues and stale produce directly harm the shopping experience, so customers' objectives of good service and fresh quality are unmet. The complaints come from the customer stakeholder group.","distractor_reasons":{"A":"Dividends concern shareholders' financial return and are not addressed by complaints about queues and produce. This leaves it as an incorrect option that should be rejected.","B":"Training is an employee concern, and the complaints described are about service and food quality rather than staff development. It therefore cannot be accepted as the correct answer to the question.","C":"Prompt payment relates to suppliers, but the scenario reports customer complaints rather than supplier payment problems. Such a result is not what the question actually requires from the student.","D":"Long queues and stale produce directly harm the shopping experience, so customers' objectives of good service and fresh quality are unmet. The complaints come from the customer stakeholder group."}}},{"id":"P1_U1_MCQ_1491","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1491","question":"A furniture maker is reviewing its material costs and selling prices before setting next year's budget. Which action is most likely to increase the added value of its output?","options":{"A":"Buying more timber than the workshop needs","B":"Reducing the selling price of every item","C":"Using cheaper packaging that damages items in transit","D":"Designing distinctive furniture that customers will pay more for"},"correctOption":"D","correctAnswer":"Designing distinctive furniture that customers will pay more for","questionType":"MCQ","explanation":{"correct_reason":"Distinctive design raises the price customers are willing to pay without a matching rise in material costs, so the gap between price and bought-in costs widens. That gap is added value.","distractor_reasons":{"A":"Extra timber that is not needed adds to costs without raising the price customers pay, which reduces rather than increases added value.","B":"Cutting prices narrows the gap between selling price and material costs, so added value falls. The option is therefore mistaken and cannot be the right selection.","C":"Cheaper packaging that damages goods creates replacements and complaints, which raises costs and harms the price customers will pay. For this reason it clearly cannot be the best answer to the question.","D":"Distinctive design raises the price customers are willing to pay without a matching rise in material costs, so the gap between price and bought-in costs widens. That gap is added value."}}},{"id":"P1_U1_MCQ_1492","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1492","question":"A manufacturer closes its own cleaning and catering departments and hires specialist firms to provide those services on contract instead. Which change does this represent?","options":{"A":"A decline in the tertiary sector","B":"Growth of tertiary services through outsourcing","C":"A return to primary production","D":"An increase in secondary manufacturing capacity"},"correctOption":"B","correctAnswer":"Growth of tertiary services through outsourcing","questionType":"MCQ","explanation":{"correct_reason":"Cleaning and catering are services, and hiring specialist providers instead of employing them in-house is outsourcing. This shifts work to the tertiary sector and expands service businesses.","distractor_reasons":{"A":"Outsourcing increases demand for specialist service firms, so it expands rather than reduces tertiary activity. That makes it the wrong choice in the circumstances described in the case.","B":"Cleaning and catering are services, and hiring specialist providers instead of employing them in-house is outsourcing. This shifts work to the tertiary sector and expands service businesses.","C":"The manufacturer is not returning to farming or extraction, and the work being outsourced is service work. This leaves it as an incorrect option that should be rejected.","D":"The change concerns support services rather than manufacturing capacity, so it does not increase secondary output. It therefore cannot be accepted as the correct answer to the question."}}},{"id":"P1_U1_MCQ_1493","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1493","question":"A rapidly growing online retailer must pay its suppliers before customers pay for their orders, leaving it short of cash. Which problem of growth does this illustrate?","options":{"A":"Too few customer orders","B":"Excessive profit","C":"A fall in fixed costs","D":"A working capital and cash flow strain"},"correctOption":"D","correctAnswer":"A working capital and cash flow strain","questionType":"MCQ","explanation":{"correct_reason":"Paying suppliers ahead of receiving customer payments ties up cash, which can leave a growing retailer short of working capital. Fast growth often creates this cash flow pressure even when sales are rising.","distractor_reasons":{"A":"The retailer is described as rapidly growing, so the problem is not a shortage of customer orders. It therefore cannot be accepted as the correct answer to the question.","B":"Excessive profit would provide cash rather than create the shortage described, so this misreads the issue. Such a result is not what the question actually requires from the student.","C":"A fall in fixed costs would ease finances, and the scenario instead describes a cash shortage from payment timing. This error rules the option out and makes the choice incorrect.","D":"Paying suppliers ahead of receiving customer payments ties up cash, which can leave a growing retailer short of working capital. Fast growth often creates this cash flow pressure even when sales are rising."}}},{"id":"P1_U1_MCQ_1494","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1494","question":"A new entrepreneur is comparing two ways to enter the coffee shop trade. Why might she choose to open a franchise rather than an independent start-up?","options":{"A":"An established brand and proven model reduce the risk of failure","B":"It guarantees a profit in the first year","C":"It gives complete freedom over prices and products","D":"It avoids the need to pay any initial investment"},"correctOption":"A","correctAnswer":"An established brand and proven model reduce the risk of failure","questionType":"MCQ","explanation":{"correct_reason":"A franchise supplies a recognised brand, tested products and training, so customers are more likely to trust the outlet from the start. That support lowers some of the risk faced by an independent start-up.","distractor_reasons":{"A":"A franchise supplies a recognised brand, tested products and training, so customers are more likely to trust the outlet from the start. That support lowers some of the risk faced by an independent start-up.","B":"No franchise can guarantee a profit, since local demand and costs still affect the outlet's results. For this reason it clearly cannot be the best answer to the question.","C":"Franchisees usually must follow set prices and products, so they have less freedom than independent owners. That makes it the wrong choice in the circumstances described in the case.","D":"Franchisees pay an initial fee and ongoing royalties, so a franchise requires investment rather than avoiding it. So it should not be selected as the correct option in this situation."}}},{"id":"P1_U1_MCQ_1495","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1495","question":"A company's managers propose a costly acquisition that would raise their own salaries and status, even though it may reduce returns to shareholders. Which conflict is shown?","options":{"A":"Customers against suppliers","B":"Managers' personal goals against shareholders' returns","C":"Employees against the local community","D":"Government against competitors"},"correctOption":"B","correctAnswer":"Managers' personal goals against shareholders' returns","questionType":"MCQ","explanation":{"correct_reason":"Managers gain higher pay and status from the acquisition, while shareholders may lose returns if it destroys value. This is a conflict between managers' own interests and shareholders' financial objectives.","distractor_reasons":{"A":"Customers and suppliers do not appear in the proposal, which concerns managers and shareholders. So it should not be selected as the correct option in this situation.","B":"Managers gain higher pay and status from the acquisition, while shareholders may lose returns if it destroys value. This is a conflict between managers' own interests and shareholders' financial objectives.","C":"Employees and the local community are not the groups whose interests are being weighed here. It therefore cannot be accepted as the correct answer to the question.","D":"Government and competitors play no part in the internal decision about the acquisition. Such a result is not what the question actually requires from the student."}}},{"id":"P1_U1_MCQ_1496","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1496","question":"A vineyard uses 20 hectares of hillside, seasonal grape pickers and a stainless-steel fermentation plant. Which factor of production is represented by the 20 hectares?","options":{"A":"Labour","B":"Capital","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Land covers all natural resources used in production, including the hillside on which the vines grow. The pickers supply labour, the plant is capital and the owner provides enterprise.","distractor_reasons":{"A":"Labour is the human effort of the seasonal pickers, not the physical hillside itself. Such a result is not what the question actually requires from the student.","B":"Capital refers to manufactured assets such as the fermentation plant, not the natural land. This error rules the option out and makes the choice incorrect.","C":"Land covers all natural resources used in production, including the hillside on which the vines grow. The pickers supply labour, the plant is capital and the owner provides enterprise.","D":"Enterprise is the risk-taking and organising role of the vineyard owner, not the hectares of hillside. For this reason it clearly cannot be the best answer to the question."}}},{"id":"P1_U1_MCQ_1497","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1497","question":"As an economy industrialises, large numbers of workers leave subsistence farming to take better-paid jobs in new factories. Which change in sector structure is occurring?","options":{"A":"From primary to secondary","B":"From secondary to tertiary","C":"From tertiary to primary","D":"From secondary to primary"},"correctOption":"A","correctAnswer":"From primary to secondary","questionType":"MCQ","explanation":{"correct_reason":"Farming is primary activity and factory work is secondary, so workers are moving from the primary to the secondary sector. This shift is a common feature of early industrialisation.","distractor_reasons":{"A":"Farming is primary activity and factory work is secondary, so workers are moving from the primary to the secondary sector. This shift is a common feature of early industrialisation.","B":"Secondary to tertiary would mean factory workers moving into services, but here they are moving into factories. That makes it the wrong choice in the circumstances described in the case.","C":"Tertiary to primary would mean service workers becoming farmers, which is the reverse of the change described. So it should not be selected as the correct option in this situation.","D":"Secondary to primary would mean factory workers returning to farming, again the opposite of industrialisation. This leaves it as an incorrect option that should be rejected."}}},{"id":"P1_U1_MCQ_1498","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1498","question":"A skilled carpenter refuses to expand his workshop because he values independence and does not want the burden of managing staff. Which reason for staying small does this show?","options":{"A":"A lack of customer demand","B":"The owner's preference for control and lower responsibility","C":"Government limits on workshop size","D":"An inability to obtain any tools"},"correctOption":"B","correctAnswer":"The owner's preference for control and lower responsibility","questionType":"MCQ","explanation":{"correct_reason":"The carpenter chooses to stay small because he values independence and wants to avoid the responsibility of managing employees. Personal preference, rather than market conditions, is the reason here.","distractor_reasons":{"A":"No shortage of customers is mentioned, and the stated reason is the owner's wish for independence. This leaves it as an incorrect option that should be rejected.","B":"The carpenter chooses to stay small because he values independence and wants to avoid the responsibility of managing employees. Personal preference, rather than market conditions, is the reason here.","C":"No government restriction on size is described, and the carpenter's motivation is personal control. Such a result is not what the question actually requires from the student.","D":"The carpenter is already skilled and equipped, so a lack of tools is not the reason for staying small. This error rules the option out and makes the choice incorrect."}}},{"id":"P1_U1_MCQ_1499","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1499","question":"A publicly owned water company is instructed to keep bills affordable and invest in leak repairs rather than pay dividends. What type of organisation and aim does this describe?","options":{"A":"A public limited company maximising shareholder returns","B":"A partnership sharing profit among owners","C":"A public corporation pursuing a public service objective","D":"A sole trader seeking rapid growth"},"correctOption":"C","correctAnswer":"A public corporation pursuing a public service objective","questionType":"MCQ","explanation":{"correct_reason":"Government ownership and an instruction to serve customers through affordable bills and repairs fit a public corporation. Its objective is public service rather than profit distribution to shareholders.","distractor_reasons":{"A":"A public limited company pays dividends to private shareholders, which the scenario explicitly rules out. This error rules the option out and makes the choice incorrect.","B":"A partnership is owned by private partners sharing profit, not by the government providing a public service. The option is therefore mistaken and cannot be the right selection.","C":"Government ownership and an instruction to serve customers through affordable bills and repairs fit a public corporation. Its objective is public service rather than profit distribution to shareholders.","D":"A sole trader is a single private owner, which cannot describe a publicly owned water company. That makes it the wrong choice in the circumstances described in the case."}}},{"id":"P1_U1_MCQ_1500","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1500","question":"A bus operator plans to cut unprofitable rural routes to protect shareholder returns, angering villagers who rely on the service. Which stakeholder conflict does this show?","options":{"A":"Employees against suppliers","B":"Managers against customers","C":"The government against competitors","D":"Rural customers and the community against shareholders"},"correctOption":"D","correctAnswer":"Rural customers and the community against shareholders","questionType":"MCQ","explanation":{"correct_reason":"Villagers depend on the routes for travel, while shareholders benefit from cutting losses on them. The conflict is therefore between rural customers and the community on one side and shareholders on the other.","distractor_reasons":{"A":"Employees and suppliers are not the groups directly divided by the decision to cut rural routes. That makes it the wrong choice in the circumstances described in the case.","B":"Managers are making the proposal, and the stated conflict is with villagers and shareholders rather than managers against customers. So it should not be selected as the correct option in this situation.","C":"No government or competitor position is described, and the dispute concerns route cuts and shareholder returns. This leaves it as an incorrect option that should be rejected.","D":"Villagers depend on the routes for travel, while shareholders benefit from cutting losses on them. The conflict is therefore between rural customers and the community on one side and shareholders on the other."}}},{"id":"P1_U1_MCQ_1501","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1501","question":"Mombasa Roastery in Mombasa, Kenya, buys green coffee beans for $6 per kilogram, roasts and packages them, and sells the finished coffee for $15 per kilogram. What is the value added by the roastery per kilogram of coffee?","options":{"A":"$6","B":"$9","C":"$15","D":"$21"},"correctOption":"B","correctAnswer":"$9","questionType":"MCQ","explanation":{"correct_reason":"Value added is selling price less the cost of bought-in materials: $15 minus $6 gives $9 per kilogram. Mombasa Roastery creates that margin by roasting and packaging beans it purchased from growers.","distractor_reasons":{"A":"The $6 figure is the price paid for green beans bought in from suppliers, not the value added. Value added deducts bought-in material cost from the selling price rather than copying that cost.","B":"Value added is selling price less the cost of bought-in materials: $15 minus $6 gives $9 per kilogram. Mombasa Roastery creates that margin by roasting and packaging beans it purchased from growers.","C":"The $15 figure is the full selling price of a kilogram of roasted coffee, not the value added. The cost of the bought-in green beans must be subtracted before the margin can be found.","D":"The $21 figure wrongly adds the $6 bean cost to the $15 selling price. Value added is a difference between selling price and bought-in cost, never the sum of those two amounts."}}},{"id":"P1_U1_MCQ_1502","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1502","question":"Bight Fisheries operates a fleet of small boats out of Lagos, Nigeria, catching herring and selling the unprocessed fish at the harbour each morning. Which economic sector does this business belong to?","options":{"A":"The secondary sector","B":"The quaternary sector","C":"The primary sector","D":"The tertiary sector"},"correctOption":"C","correctAnswer":"The primary sector","questionType":"MCQ","explanation":{"correct_reason":"Catching wild fish is the extraction of a natural resource, which places Bight Fisheries in the primary sector. The boats land an unprocessed catch at Lagos rather than manufacturing goods or supplying specialist knowledge services.","distractor_reasons":{"A":"Secondary sector businesses turn raw materials into finished goods through manufacturing or construction. Bight Fisheries lands fish without processing them into products, so that classification does not fit its activity.","B":"Quaternary sector work involves research, information and specialist knowledge services. Catching herring off Lagos involves none of those activities, making this an unsuitable description of the business.","C":"Catching wild fish is the extraction of a natural resource, which places Bight Fisheries in the primary sector. The boats land an unprocessed catch at Lagos rather than manufacturing goods or supplying specialist knowledge services.","D":"Tertiary sector firms provide services to customers instead of extracting raw materials. Selling the catch at the harbour does not change the core activity of Bight Fisheries, which remains the harvesting of fish."}}},{"id":"P1_U1_MCQ_1503","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1503","question":"In Ho Chi Minh City, Vietnam, Linh invested her savings to open Cholon Noodle Startup after noticing office workers queuing for fresh noodles at lunchtime. She chose the site and price and could lose her savings. What best describes Linh's role?","options":{"A":"An entrepreneur taking financial risk to meet a market need","B":"A manager carrying out a government production plan","C":"A shareholder receiving guaranteed dividend payments","D":"A civil servant appointed to run a local market"},"correctOption":"A","correctAnswer":"An entrepreneur taking financial risk to meet a market need","questionType":"MCQ","explanation":{"correct_reason":"Linh spotted an unmet need among office workers, committed her own savings and accepted the risk of loss. Those are the defining features of an entrepreneur, who organises resources and takes financial risk in search of opportunity.","distractor_reasons":{"A":"Linh spotted an unmet need among office workers, committed her own savings and accepted the risk of loss. Those are the defining features of an entrepreneur, who organises resources and takes financial risk in search of opportunity.","B":"A manager implementing a government plan would not personally invest savings or face the risk of losing them. Linh identified the opportunity herself in Ho Chi Minh City, so this description does not fit.","C":"Shareholders are not guaranteed dividends, and Linh is running the business rather than merely holding shares. Her invested savings are at risk, which is the opposite of a guaranteed payment.","D":"A civil servant appointed to manage a market would be carrying out public duties, not investing private savings in a new noodle business. Linh acted independently to serve customers, so this is wrong."}}},{"id":"P1_U1_MCQ_1504","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1504","question":"Krakow Metalworks in Krakow, Poland, is owned and managed by two friends who share all profits. They have not registered a separate legal company, so their personal savings could be used to pay business debts. Which structure is this?","options":{"A":"A public limited company","B":"A private limited company with limited liability","C":"A public corporation owned by the state","D":"A partnership with unlimited liability"},"correctOption":"D","correctAnswer":"A partnership with unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Two owners who share profits and management without a separate legal company form a partnership. Because their personal savings can be taken for firm debts, liability is unlimited, which matches Krakow Metalworks exactly.","distractor_reasons":{"A":"A public limited company has a separate legal identity and shareholders whose liability is limited to their investment. That protection conflicts with the personal asset risk described at Krakow Metalworks.","B":"A private limited company also gives its owners limited liability through a separate legal entity. The scenario says the friends' own savings are exposed to business debts, so limited liability cannot apply.","C":"A public corporation is state owned and exists to provide a public service. Krakow Metalworks is owned by two private friends sharing profit, so government ownership is plainly the wrong classification.","D":"Two owners who share profits and management without a separate legal company form a partnership. Because their personal savings can be taken for firm debts, liability is unlimited, which matches Krakow Metalworks exactly."}}},{"id":"P1_U1_MCQ_1505","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1505","question":"Sao Paulo Transit in Sao Paulo, Brazil, earned a profit of $400,000 last year. Its board decided to distribute 25% of that profit to shareholders as dividends and retain the remainder to buy new buses. How much was paid in dividends?","options":{"A":"$40,000","B":"$80,000","C":"$100,000","D":"$125,000"},"correctOption":"C","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"A quarter of the $400,000 profit equals $100,000, so that is the dividend payment. Sao Paulo Transit retains the other $300,000 for buses, confirming the board's 25% distribution policy.","distractor_reasons":{"A":"The $40,000 figure is only ten percent of the $400,000 profit, not the quarter the board approved. Ten percent would leave far more money retained than the stated policy allows.","B":"The $80,000 figure represents twenty percent of the $400,000 profit. The board committed twenty five percent, so this understates the dividend and would leave $320,000 retained rather than $300,000.","C":"A quarter of the $400,000 profit equals $100,000, so that is the dividend payment. Sao Paulo Transit retains the other $300,000 for buses, confirming the board's 25% distribution policy.","D":"The $125,000 figure is a quarter of $500,000, not of the actual $400,000 profit. The calculation must begin from the profit figure stated in the scenario, not from an invented amount."}}},{"id":"P1_U1_MCQ_1506","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1506","question":"Guadalajara Paper Works in Guadalajara, Mexico, has installed two automated paper-making machines worth $2 million to replace hand-operated presses. Which factor of production do these machines represent for the business?","options":{"A":"Capital","B":"Land","C":"Labour","D":"Enterprise"},"correctOption":"A","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Capital as a factor of production means the man-made equipment used in production. The $2 million paper-making machines are purchased assets that help Guadalajara Paper Works turn pulp into finished paper.","distractor_reasons":{"A":"Capital as a factor of production means the man-made equipment used in production. The $2 million paper-making machines are purchased assets that help Guadalajara Paper Works turn pulp into finished paper.","B":"Land refers to natural resources such as the site or raw materials, not to purchased machinery. The machines in Guadalajara are manufactured equipment, so they cannot be classified as land.","C":"Labour is the human effort and skill contributed by employees. Automated machines replace hand-operated presses, so they are physical equipment rather than the work of the workforce.","D":"Enterprise is the risk-taking organising skill of the owner or entrepreneur. Machinery does not make decisions or accept risk, so calling the paper-making machines enterprise is incorrect."}}},{"id":"P1_U1_MCQ_1507","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1507","question":"Hanoi Home Care in Hanoi, Vietnam, employs 240 nurses who visit elderly residents and help with daily tasks. The firm has doubled its staff in five years as the population ages. Which statement best explains the growth of this business?","options":{"A":"Growth in primary extraction is creating demand for visiting nurses","B":"Manufacturing employment is shifting from factories into the secondary sector","C":"Research jobs in the quaternary sector are replacing service employment","D":"Rising demand for services in the tertiary sector as incomes and longevity increase"},"correctOption":"D","correctAnswer":"Rising demand for services in the tertiary sector as incomes and longevity increase","questionType":"MCQ","explanation":{"correct_reason":"Visiting nurses provide a service, placing Hanoi Home Care in the tertiary sector. An ageing population and higher incomes increase demand for such services, which explains why its workforce grew to 240 nurses.","distractor_reasons":{"A":"Primary extraction involves obtaining raw materials, which does not explain demand for nursing visits in Hanoi. An ageing population drives care services rather than the extraction sector.","B":"Nursing care is not manufacturing, and the scenario describes service jobs rather than factory work. Growth from 120 to 240 visiting nurses reflects tertiary demand, not a shift into secondary activity.","C":"Quaternary work is research and information based, whereas these 240 nurses deliver hands-on care to residents. Nothing in the scenario suggests research jobs are replacing their employment.","D":"Visiting nurses provide a service, placing Hanoi Home Care in the tertiary sector. An ageing population and higher incomes increase demand for such services, which explains why its workforce grew to 240 nurses."}}},{"id":"P1_U1_MCQ_1508","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1508","question":"Fez Leather Studio in Fez, Morocco, employs six craft workers who make hand-stitched bags to each customer's design. The owner can change a price or design the same day without consulting head office. Which advantage of being small is shown?","options":{"A":"The ability to exploit economies of scale better than large factories","B":"The ability to offer customised products and respond quickly to customers","C":"Guaranteed access to cheaper finance than public companies enjoy","D":"Complete protection from competition by overseas producers"},"correctOption":"B","correctAnswer":"The ability to offer customised products and respond quickly to customers","questionType":"MCQ","explanation":{"correct_reason":"Six workers making bags to individual designs show flexibility and a niche focus. Because Fez Leather Studio has no head office to consult, it can react the same day, which is a clear advantage of small-scale operation.","distractor_reasons":{"A":"Economies of scale belong to large-scale output, where unit costs fall as volume rises. A six-worker studio producing individual bags cannot achieve that, so it is not the advantage illustrated here.","B":"Six workers making bags to individual designs show flexibility and a niche focus. Because Fez Leather Studio has no head office to consult, it can react the same day, which is a clear advantage of small-scale operation.","C":"Small firms often face higher borrowing costs than public companies, not cheaper finance. Nothing in the Fez scenario mentions interest rates or funding, so this claim is unsupported and wrong.","D":"No business is fully protected from overseas competition. Hand-made bags in Fez still compete with imported products, so complete protection is an unrealistic and incorrect advantage."}}},{"id":"P1_U1_MCQ_1509","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1509","question":"Tallinn Software Co in Tallinn, Estonia, has issued 200,000 ordinary shares. An investor purchases 50,000 of those shares. What percentage of the company's ownership does the investor acquire?","options":{"A":"10%","B":"25%","C":"40%","D":"50%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Fifty thousand shares out of two hundred thousand is exactly one quarter, so the investor owns 25% of Tallinn Software Co and would receive a matching share of any dividends the company declares.","distractor_reasons":{"A":"Ten percent of 200,000 shares is only 20,000 shares. The investor bought 50,000, so this percentage understates the true stake and must be rejected.","B":"Fifty thousand shares out of two hundred thousand is exactly one quarter, so the investor owns 25% of Tallinn Software Co and would receive a matching share of any dividends the company declares.","C":"Forty percent of 200,000 shares would be 80,000 shares, which is more than the 50,000 purchased. The correct ownership share is therefore smaller than forty percent.","D":"Half of 200,000 shares would require a purchase of 100,000 shares. With only 50,000 shares held, the investor controls a quarter of Tallinn Software Co, not half of it."}}},{"id":"P1_U1_MCQ_1510","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1510","question":"Durban Textile Mills in Durban, South Africa, faces a wage claim from its workers while shareholders insist that dividend payments must be maintained. Paying the claim would reduce profit available to owners. Which stakeholder conflict is this?","options":{"A":"Customers versus suppliers over delivery times","B":"The government versus the local community over taxation","C":"Employees seeking higher wages versus shareholders seeking dividends","D":"Managers versus shareholders over the choice of location"},"correctOption":"C","correctAnswer":"Employees seeking higher wages versus shareholders seeking dividends","questionType":"MCQ","explanation":{"correct_reason":"Workers want higher wages and shareholders want dividends maintained from the same profit. The wage claim directly reduces the amount available to owners, so the conflict is between employees and shareholders at Durban Textile Mills.","distractor_reasons":{"A":"No customer or supplier disagreement is described in the Durban scenario. The competing claims come from workers and owners over how profit is divided, not from delivery arrangements.","B":"Government taxation and community interests are not mentioned in the case. The dispute concerns a wage claim and dividend payments, so these two groups are not the ones in conflict.","C":"Workers want higher wages and shareholders want dividends maintained from the same profit. The wage claim directly reduces the amount available to owners, so the conflict is between employees and shareholders at Durban Textile Mills.","D":"Managers are not shown disagreeing about location, and shareholders are not the party opposing them. The real division is between employees pressing for wages and owners protecting dividends."}}},{"id":"P1_U1_MCQ_1511","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1511","question":"Naples Shoe Workshop in Naples, Italy, reorganised production so that one worker cuts leather, another stitches uppers and a third attaches soles. Daily output rose from 20 pairs to 30 pairs. What does this change illustrate?","options":{"A":"Diminishing returns from adding more machinery","B":"Higher unit costs caused by overstaffing the workshop","C":"A decline in quality caused by repetitive work","D":"Division of labour raising output through specialisation"},"correctOption":"D","correctAnswer":"Division of labour raising output through specialisation","questionType":"MCQ","explanation":{"correct_reason":"Splitting shoemaking into cutting, stitching and sole-attaching tasks lets each worker specialise. The rise in daily output from 20 to 30 pairs shows division of labour improving productivity at Naples Shoe Workshop.","distractor_reasons":{"A":"Diminishing returns would mean output rising by smaller amounts as more of a factor is added. The scenario instead reports a clear gain from reorganising tasks, with no mention of extra machinery.","B":"Overstaffing is not described; the same workshop simply assigned separate tasks to workers. Output rose from 20 to 30 pairs, which suggests improved productivity rather than wasteful employment.","C":"No information about defects or quality is given. The only reported result is higher output from specialisation, so a claimed decline in quality has no support in the Naples case.","D":"Splitting shoemaking into cutting, stitching and sole-attaching tasks lets each worker specialise. The rise in daily output from 20 to 30 pairs shows division of labour improving productivity at Naples Shoe Workshop."}}},{"id":"P1_U1_MCQ_1512","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1512","question":"Cordoba Olive Groves in Cordoba, Spain, harvests olives and sells them to processors rather than bottling oil itself. Which statement about the primary sector is best illustrated by this business?","options":{"A":"It supplies raw materials to other sectors and is exposed to weather risks","B":"It converts raw materials into finished consumer goods for shops","C":"It is made up mainly of shops, hospitals and transport services","D":"It operates only in countries with large manufacturing industries"},"correctOption":"A","correctAnswer":"It supplies raw materials to other sectors and is exposed to weather risks","questionType":"MCQ","explanation":{"correct_reason":"Olives are a natural product sold on for processing, so Cordoba Olive Groves supplies raw materials to later stages of production. Because the crop depends on growing conditions, frost or drought can damage the harvest.","distractor_reasons":{"A":"Olives are a natural product sold on for processing, so Cordoba Olive Groves supplies raw materials to later stages of production. Because the crop depends on growing conditions, frost or drought can damage the harvest.","B":"Turning raw materials into finished consumer goods is secondary sector manufacturing. Cordoba Olive Groves sells olives unchanged to processors, so it does not carry out that conversion itself.","C":"Shops, hospitals and transport services belong to the tertiary sector. The grove's activity is harvesting olives, which is extraction of a natural product rather than service provision.","D":"Primary activity exists in many countries regardless of manufacturing size. Farming in Cordoba shows that extraction is widespread, so limiting the sector to industrial countries is incorrect."}}},{"id":"P1_U1_MCQ_1513","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1513","question":"Kigali Solar in Kigali, Rwanda, increased its annual turnover from $1.2 million in 2024 to $1.5 million in 2025. What was the percentage increase in turnover over that year?","options":{"A":"15%","B":"20%","C":"25%","D":"30%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Turnover rose by $300,000 from a base of $1.2 million, and $300,000 divided by $1.2 million equals 25%. Kigali Solar therefore increased its sales revenue by one quarter during 2025.","distractor_reasons":{"A":"A fifteen percent rise would add only $180,000 to the original $1.2 million turnover. The actual increase to $1.5 million is larger, so this percentage is clearly too low.","B":"Twenty percent of $1.2 million is $240,000, giving turnover of $1.44 million. Since the reported figure is $1.5 million, twenty percent understates the true growth of Kigali Solar.","C":"Turnover rose by $300,000 from a base of $1.2 million, and $300,000 divided by $1.2 million equals 25%. Kigali Solar therefore increased its sales revenue by one quarter during 2025.","D":"Thirty percent of $1.2 million is $360,000, which would produce $1.56 million of turnover. The final figure is $1.5 million, so the growth rate must be lower than thirty percent."}}},{"id":"P1_U1_MCQ_1514","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1514","question":"Bangalore Textile Plc in Bengaluru, India, raises finance by selling shares that are traded on the stock exchange. It must publish detailed accounts for investors. Which feature distinguishes this form of organisation?","options":{"A":"Its shares can be bought and sold by the general public on a stock exchange","B":"It is owned and funded entirely by one private individual","C":"Its owners face unlimited liability for all company debts","D":"It is forbidden by law from issuing shares to outside investors"},"correctOption":"A","correctAnswer":"Its shares can be bought and sold by the general public on a stock exchange","questionType":"MCQ","explanation":{"correct_reason":"A public limited company can offer its shares to the general public and have them traded on a stock exchange. The traded shares and published accounts described at Bangalore Textile Plc identify this legal structure.","distractor_reasons":{"A":"A public limited company can offer its shares to the general public and have them traded on a stock exchange. The traded shares and published accounts described at Bangalore Textile Plc identify this legal structure.","B":"A business owned by one individual would be a sole trader, not a public limited company. Bangalore Textile Plc has many outside shareholders whose shares trade publicly, so single ownership is wrong.","C":"Shareholders in a public limited company enjoy limited liability to the value of their shares. Unlimited liability would make them personally responsible for debts, which contradicts the company form described.","D":"Issuing shares to outside investors is exactly how the business raised finance. Saying it is forbidden from doing so contradicts the scenario, which states that its shares are traded on the exchange."}}},{"id":"P1_U1_MCQ_1515","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1515","question":"Ubud Eco Resort in Ubud, Bali, Indonesia, publishes a statement promising guests sustainable comfort while protecting the surrounding rice terraces and employing local villagers. What is this published statement best described as?","options":{"A":"A short-term financial sales target","B":"A mission statement expressing the business's overall purpose","C":"A detailed daily production schedule for housekeeping","D":"A legally binding supply contract with local farmers"},"correctOption":"B","correctAnswer":"A mission statement expressing the business's overall purpose","questionType":"MCQ","explanation":{"correct_reason":"The statement sets out why Ubud Eco Resort exists, covering guests, the rice terraces and local employment. That broad statement of purpose is a mission statement rather than a narrow target or routine schedule.","distractor_reasons":{"A":"A short-term financial target would specify a sales figure or deadline. The resort's promise covers sustainability and community, so it is broader than a single financial objective.","B":"The statement sets out why Ubud Eco Resort exists, covering guests, the rice terraces and local employment. That broad statement of purpose is a mission statement rather than a narrow target or routine schedule.","C":"A housekeeping schedule would list rooms and cleaning times. The published statement instead explains the resort's wider purpose, which makes it a mission statement rather than an operational rota.","D":"A supply contract would set prices and delivery terms with farmers. Nothing in the scenario describes legal obligations of that kind, so treating the statement as a contract is incorrect."}}},{"id":"P1_U1_MCQ_1516","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1516","question":"Accra Bakery in Accra, Ghana, has just enough flour this week to produce either 200 loaves of bread or 300 cakes. The owner decides to make the 200 loaves. What is the opportunity cost of that decision?","options":{"A":"The profit earned from selling the 200 loaves","B":"The next best alternative, the 300 cakes that could have been made","C":"The flour, because it is used up in baking the bread","D":"The oven and the bakery's rent for the week"},"correctOption":"B","correctAnswer":"The next best alternative, the 300 cakes that could have been made","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best alternative given up. By choosing 200 loaves, Accra Bakery forgoes the 300 cakes it could otherwise have produced with the same flour, so that is the cost.","distractor_reasons":{"A":"Profit from the loaves is the benefit of the chosen option, not the cost of the option rejected. Opportunity cost looks at what was given up, which here is the cake output.","B":"Opportunity cost is the value of the next best alternative given up. By choosing 200 loaves, Accra Bakery forgoes the 300 cakes it could otherwise have produced with the same flour, so that is the cost.","C":"The flour is a resource used in both alternatives rather than the alternative forgone. Opportunity cost is measured by the next best use of that flour, namely the 300 cakes.","D":"The oven and rent would be incurred whichever product was made. Since they are not a rejected alternative, they do not represent the opportunity cost of the bakery's choice."}}},{"id":"P1_U1_MCQ_1517","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1517","question":"A survey of Surabaya's logistics district in Surabaya, Indonesia, counted 12,000 workers. Of these, 9,000 worked for shipping agents, trucking firms and warehouses providing services. What percentage of the workforce was in the tertiary sector?","options":{"A":"75%","B":"25%","C":"60%","D":"80%"},"correctOption":"A","correctAnswer":"75%","questionType":"MCQ","explanation":{"correct_reason":"Nine thousand of the twelve thousand workers hold service jobs, and 9,000 divided by 12,000 equals 0.75 or 75%. Three quarters of Surabaya's logistics workforce therefore work in the tertiary sector.","distractor_reasons":{"A":"Nine thousand of the twelve thousand workers hold service jobs, and 9,000 divided by 12,000 equals 0.75 or 75%. Three quarters of Surabaya's logistics workforce therefore work in the tertiary sector.","B":"Twenty five percent is the share of workers outside the service firms, that is 3,000 out of 12,000. The question asks for the tertiary share, which is the much larger group of 9,000.","C":"Sixty percent of 12,000 workers is 7,200, which is fewer than the 9,000 people employed by shipping agents, trucking firms and warehouses in Surabaya's logistics district.","D":"Eighty percent would require 9,600 service workers out of 12,000. Only 9,000 were counted in tertiary employment, so this percentage is too high for the district."}}},{"id":"P1_U1_MCQ_1518","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1518","question":"Lima Food Markets in Lima, Peru, expanded from one store to nine over eight years, funding each new outlet from retained profit and opening them one at a time. Which method of growth has the business used?","options":{"A":"A takeover of a rival chain of stores","B":"A merger with a competing food business","C":"Organic growth financed from retained earnings","D":"A franchise agreement with overseas partners"},"correctOption":"C","correctAnswer":"Organic growth financed from retained earnings","questionType":"MCQ","explanation":{"correct_reason":"Lima Food Markets grew gradually by opening its own stores and paying for them from profit kept in the business. That internal expansion without buying another company is organic growth from retained earnings.","distractor_reasons":{"A":"A takeover means buying control of an existing rival. The scenario describes new outlets opened one at a time in Lima, so no purchase of another chain took place.","B":"A merger joins two existing businesses into one. Lima Food Markets simply added its own stores, so there is no evidence of combining with a competing firm.","C":"Lima Food Markets grew gradually by opening its own stores and paying for them from profit kept in the business. That internal expansion without buying another company is organic growth from retained earnings.","D":"A franchise would involve overseas partners operating outlets under a licence. All nine stores were opened by the business itself using retained profit, so franchising is not shown."}}},{"id":"P1_U1_MCQ_1519","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1519","question":"Tirana Farmers Co-operative in Tirana, Albania, is owned by 85 member farmers. Each member has one vote regardless of how much they supply, and any surplus is shared among members. Which form of organisation is this?","options":{"A":"A group of independent sole traders with no shared ownership","B":"A public limited company with outside shareholders","C":"A government department providing a public service","D":"A co-operative owned and democratically controlled by its members"},"correctOption":"D","correctAnswer":"A co-operative owned and democratically controlled by its members","questionType":"MCQ","explanation":{"correct_reason":"Shared ownership by 85 member farmers, one vote per member and a surplus distributed among members are the defining features of a co-operative. Democratic member control makes Tirana Farmers Co-operative that structure.","distractor_reasons":{"A":"Sole traders own their businesses individually and do not share surplus through a common organisation. The 85 members here jointly own the co-operative and vote on its affairs.","B":"A public limited company gives voting power broadly according to shares held and can have outside investors. One vote per member regardless of supply is a co-operative principle, not a company one.","C":"A government department would be state funded and accountable to ministers. Tirana Farmers Co-operative is owned by its member farmers, so public ownership is the wrong description.","D":"Shared ownership by 85 member farmers, one vote per member and a surplus distributed among members are the defining features of a co-operative. Democratic member control makes Tirana Farmers Co-operative that structure."}}},{"id":"P1_U1_MCQ_1520","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1520","question":"Osaka Circuit Works in Osaka, Japan, pays wages above the local average and uses recycled packaging even though both choices raise costs. The board says it wants to protect workers and reduce waste while still earning a profit. Which objectives does this show?","options":{"A":"Short-term profit maximisation at any cost to other groups","B":"Ethical and social objectives pursued alongside profit","C":"Survival achieved by cutting every discretionary payment","D":"Maximum market share through the lowest possible prices"},"correctOption":"B","correctAnswer":"Ethical and social objectives pursued alongside profit","questionType":"MCQ","explanation":{"correct_reason":"Paying above-average wages and choosing recycled packaging despite higher costs show concern for employees and the environment. Osaka Circuit Works balances these ethical and social aims with earning a profit.","distractor_reasons":{"A":"Profit maximisation at any cost would cut wages and avoid expensive packaging. The board accepts higher costs to benefit workers and waste reduction, so that description is contradicted.","B":"Paying above-average wages and choosing recycled packaging despite higher costs show concern for employees and the environment. Osaka Circuit Works balances these ethical and social aims with earning a profit.","C":"Survival through cutting payments would mean reducing wages, not paying above the local average. The scenario describes extra spending on staff and materials, so it cannot be cost cutting.","D":"Low prices are not mentioned in the Osaka case. The choices raise costs rather than minimise them, so seeking market share through the lowest prices is not supported by the evidence."}}},{"id":"P1_U1_MCQ_1521","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1521","question":"Thimphu Weaving in Thimphu, Bhutan, buys yarn for $12 per shawl, weaves each shawl by hand and sells it for $40. Last month it sold 500 shawls. What was the total value added by the business last month?","options":{"A":"$6,000","B":"$12,000","C":"$14,000","D":"$20,000"},"correctOption":"C","correctAnswer":"$14,000","questionType":"MCQ","explanation":{"correct_reason":"Each shawl adds $28 of value, calculated as the $40 selling price less $12 of bought-in yarn. Across 500 shawls, Thimphu Weaving adds $14,000 in total, which is the figure the question requests.","distractor_reasons":{"A":"The $6,000 figure is the total spent on yarn, found by multiplying 500 shawls by $12. It is a material cost, not the value the weavers add by turning yarn into finished shawls.","B":"The $12,000 figure would arise from subtracting $16 from each $40 shawl. The actual bought-in cost is $12, leaving a $28 margin, so the total added value must be larger than this.","C":"Each shawl adds $28 of value, calculated as the $40 selling price less $12 of bought-in yarn. Across 500 shawls, Thimphu Weaving adds $14,000 in total, which is the figure the question requests.","D":"The $20,000 figure is total sales revenue from 500 shawls at $40 each, not value added. The $6,000 spent on bought-in yarn must be deducted, leaving $14,000 created by the business."}}},{"id":"P1_U1_MCQ_1522","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1522","question":"Dunedin Marine Research in Dunedin, New Zealand, employs scientists who analyse ocean temperature data and publish findings for fishing firms. Which economic sector does this knowledge-based business belong to?","options":{"A":"The quaternary sector","B":"The primary sector","C":"The secondary sector","D":"The tertiary sector"},"correctOption":"A","correctAnswer":"The quaternary sector","questionType":"MCQ","explanation":{"correct_reason":"Analysing ocean data and producing research findings are specialist knowledge activities, placing Dunedin Marine Research in the quaternary sector. It neither catches fish nor manufactures products, and its work is more specialised than routine services.","distractor_reasons":{"A":"Analysing ocean data and producing research findings are specialist knowledge activities, placing Dunedin Marine Research in the quaternary sector. It neither catches fish nor manufactures products, and its work is more specialised than routine services.","B":"Primary activity extracts natural resources such as fish caught at sea. The Dunedin laboratory studies marine conditions and produces research, so it is not harvesting natural resources itself.","C":"Secondary activity converts materials into manufactured goods or constructs buildings. The lab's output is analysis and published findings rather than physical products, so this classification is wrong.","D":"Research can be seen as a service in a broad sense, but the specialist knowledge work of the quaternary sector is more precise. Analysing ocean datasets in Dunedin is a classic quaternary activity."}}},{"id":"P1_U1_MCQ_1523","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1523","question":"Lagos Garment Factory in Lagos, Nigeria, expanded from 300 to 1,500 workers. Managers now struggle to coordinate shifts, and average cost per garment has begun to rise. Which problem is the factory experiencing?","options":{"A":"Economies of scale from bulk buying of cloth","B":"Higher total revenue from a larger customer market","C":"A fall in average costs as output continues to rise","D":"Diseconomies of scale caused by coordination difficulties"},"correctOption":"D","correctAnswer":"Diseconomies of scale caused by coordination difficulties","questionType":"MCQ","explanation":{"correct_reason":"When a larger workforce of 1,500 creates communication and coordination problems, average costs rise as output expands. That is diseconomies of scale, which is exactly what Lagos Garment Factory now reports.","distractor_reasons":{"A":"Economies of scale would lower average costs through bulk purchases. Here average cost per garment is rising after expansion, so the benefits of larger scale are not being realised.","B":"Higher revenue might follow a larger market, but the scenario describes rising unit costs and coordination trouble. Revenue growth does not explain or remove the problem being reported.","C":"A fall in average costs is the opposite of what the factory experiences. Its cost per garment has begun to rise as the workforce grew to 1,500, so this statement is contradicted.","D":"When a larger workforce of 1,500 creates communication and coordination problems, average costs rise as output expands. That is diseconomies of scale, which is exactly what Lagos Garment Factory now reports."}}},{"id":"P1_U1_MCQ_1524","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1524","question":"Kathmandu Cycle Repairs in Kathmandu, Nepal, is run by one mechanic who keeps all the profit, makes every decision alone and is personally liable for any debts. Which legal structure does this business have?","options":{"A":"A partnership between two or more owners","B":"A sole trader with unlimited liability","C":"A private limited company owned by shareholders","D":"A public corporation providing a service"},"correctOption":"B","correctAnswer":"A sole trader with unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"One owner who keeps all profit and makes all decisions is a sole trader. Personal liability for debts means there is no separate legal entity, which matches the position of the mechanic in Kathmandu.","distractor_reasons":{"A":"A partnership requires at least two owners sharing the business. Kathmandu Cycle Repairs has a single mechanic making all decisions, so there is no second partner to form a partnership.","B":"One owner who keeps all profit and makes all decisions is a sole trader. Personal liability for debts means there is no separate legal entity, which matches the position of the mechanic in Kathmandu.","C":"A private limited company has a separate legal identity and shareholders with limited liability. The mechanic here is personally responsible for debts, which rules out that company structure.","D":"A public corporation is state owned and run for public service. A single privately owned repair shop in Kathmandu has none of those features, so this option is clearly inappropriate."}}},{"id":"P1_U1_MCQ_1525","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1525","question":"Antananarivo Vanilla Collective in Antananarivo, Madagascar, made a profit of $240,000 and promised local community projects 15% of that profit. How much money was allocated to the community projects?","options":{"A":"$36,000","B":"$24,000","C":"$48,000","D":"$60,000"},"correctOption":"A","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Fifteen percent of the $240,000 profit is $36,000, so that is the sum allocated to community projects. The remaining $204,000 stays with the business, confirming the promised share was calculated correctly.","distractor_reasons":{"A":"Fifteen percent of the $240,000 profit is $36,000, so that is the sum allocated to community projects. The remaining $204,000 stays with the business, confirming the promised share was calculated correctly.","B":"The $24,000 figure is only ten percent of the $240,000 profit. The growers committed fifteen percent to local projects, so this amount understates the promised community allocation.","C":"The $48,000 figure represents twenty percent of the $240,000 profit. Since the promise was fifteen percent, this option gives too much to community projects and cannot be correct.","D":"The $60,000 figure would be one quarter of the $240,000 profit. The stated pledge was fifteen percent, so this answer wrongly inflates the payment to local projects."}}},{"id":"P1_U1_MCQ_1526","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1526","question":"Almaty Fresh Milk in Almaty, Kazakhstan, found in a survey that customers need affordable fresh milk but would like flavoured drinks as a treat. Which statement correctly distinguishes needs from wants in this case?","options":{"A":"A want is essential for survival while a need is an optional luxury","B":"Needs are always created by advertising campaigns","C":"Wants and needs are exactly the same thing to marketers","D":"Needs are basic requirements while wants are particular ways of satisfying them"},"correctOption":"D","correctAnswer":"Needs are basic requirements while wants are particular ways of satisfying them","questionType":"MCQ","explanation":{"correct_reason":"Affordable fresh milk meets a basic need for food and drink, while flavoured drinks are a preferred way of satisfying that need. Almaty Fresh Milk's survey therefore illustrates needs as requirements and wants as specific choices.","distractor_reasons":{"A":"The statement reverses the terms. A need such as nourishment is fundamental, whereas a want such as a flavoured drink is an optional preference, so this answer cannot describe the survey.","B":"Advertising may shape wants, but basic needs such as affordable milk exist independently of promotion. The Almaty survey records a need without suggesting that advertising created it.","C":"Marketers treat needs and wants as different ideas. If they were identical, the survey's distinction between affordable milk and flavoured treats would have no meaning at all.","D":"Affordable fresh milk meets a basic need for food and drink, while flavoured drinks are a preferred way of satisfying that need. Almaty Fresh Milk's survey therefore illustrates needs as requirements and wants as specific choices."}}},{"id":"P1_U1_MCQ_1527","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1527","question":"Sheffield Rolling Mill in Sheffield, the United Kingdom, installed automated rolling equipment. Employment fell from 8,000 to 2,000 workers while steel output stayed high. Which change does this illustrate?","options":{"A":"Expansion of primary sector employment in the local area","B":"Tertiary sector jobs moving into metal manufacturing","C":"Mechanisation reducing the labour needed in the secondary sector","D":"Quaternary research entirely replacing steel production"},"correctOption":"C","correctAnswer":"Mechanisation reducing the labour needed in the secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Steelmaking is secondary sector production, and new rolling equipment allowed the same high output with only 2,000 instead of 8,000 workers. This shows mechanisation reducing the demand for labour in manufacturing.","distractor_reasons":{"A":"Steel production is not primary extraction, and employment fell rather than expanded. The change at Sheffield is a labour reduction in manufacturing, not growth in primary sector jobs.","B":"No service jobs are described as moving into steelmaking. The reduction from 8,000 to 2,000 workers happened inside the plant because machinery replaced manual work, not because of sector transfer.","C":"Steelmaking is secondary sector production, and new rolling equipment allowed the same high output with only 2,000 instead of 8,000 workers. This shows mechanisation reducing the demand for labour in manufacturing.","D":"The plant still produces steel at high output, so production has not been replaced by research. Automated equipment changed the workforce, not the fundamental nature of the business."}}},{"id":"P1_U1_MCQ_1528","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1528","question":"Managua Cement in Managua, Nicaragua, wants to compare its size with another cement producer in the same country. Which pair of measures would give the most meaningful comparison of the two businesses?","options":{"A":"The number of complaints and the colour of delivery vehicles","B":"Annual turnover and the number of people employed","C":"The founder's age and the year the company was registered","D":"The price of cement and the length of the company name"},"correctOption":"B","correctAnswer":"Annual turnover and the number of people employed","questionType":"MCQ","explanation":{"correct_reason":"Business size is commonly measured by sales revenue and workforce numbers, both of which allow a direct comparison between rival producers. Annual turnover and employment give Managua Cement a fair basis for judging scale.","distractor_reasons":{"A":"Complaint counts and vehicle colours do not measure the scale of a business. They might describe service quality or branding, but they cannot compare the size of two cement producers.","B":"Business size is commonly measured by sales revenue and workforce numbers, both of which allow a direct comparison between rival producers. Annual turnover and employment give Managua Cement a fair basis for judging scale.","C":"The founder's age and registration year say nothing about current output or market position. Two firms of very different size could easily share those details, so they are not useful measures.","D":"Cement price reflects the market rather than the firm's scale, and name length is irrelevant. Neither measure tells us how large Managua Cement is relative to its rival."}}},{"id":"P1_U1_MCQ_1529","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1529","question":"Warsaw Coffee Plc in Warsaw, Poland, has 500,000 issued shares and has declared a total dividend payment of $250,000. What is the dividend received per share?","options":{"A":"$0.20","B":"$0.25","C":"$0.40","D":"$0.50"},"correctOption":"D","correctAnswer":"$0.50","questionType":"MCQ","explanation":{"correct_reason":"Dividing the $250,000 total dividend by 500,000 shares gives $0.50 per share. Each shareholder in Warsaw Coffee Plc therefore receives fifty cents for every share held, which matches the declared distribution.","distractor_reasons":{"A":"A dividend of $0.20 on 500,000 shares would distribute only $100,000. That is well short of the $250,000 Warsaw Coffee Plc has declared, so this figure is incorrect.","B":"At $0.25 per share, total payments would be $125,000, exactly half the announced dividend. The calculation must divide $250,000 by 500,000 shares, giving a larger amount.","C":"A payment of $0.40 per share would cost $200,000 across 500,000 shares. Since the company declared $250,000, the actual dividend per share must be higher than forty cents.","D":"Dividing the $250,000 total dividend by 500,000 shares gives $0.50 per share. Each shareholder in Warsaw Coffee Plc therefore receives fifty cents for every share held, which matches the declared distribution."}}},{"id":"P1_U1_MCQ_1530","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1530","question":"Dakar Furniture in Dakar, Senegal, missed delivery dates last month because its timber supplier sent the wrong grades of wood. Which stakeholder group is directly responsible for this operational problem?","options":{"A":"Customers, through their changing tastes in furniture","B":"Employees, through their slow assembly of the order","C":"Suppliers, whose reliable deliveries affect the firm's output","D":"Pressure groups, whose campaigns determine the firm's prices"},"correctOption":"C","correctAnswer":"Suppliers, whose reliable deliveries affect the firm's output","questionType":"MCQ","explanation":{"correct_reason":"The wrong grades of wood came from the timber supplier, causing Dakar Furniture to miss its delivery dates. Suppliers are therefore the stakeholder whose input quality directly affects the firm's ability to produce.","distractor_reasons":{"A":"Customer tastes are not mentioned as the cause. The missed dates resulted from incorrect wood deliveries, not from buyers changing their preferences for furniture designs.","B":"Assembly by employees was not the problem described in Dakar. The wood arrived in the wrong grades, so the delay originated with the supplier rather than the workforce.","C":"The wrong grades of wood came from the timber supplier, causing Dakar Furniture to miss its delivery dates. Suppliers are therefore the stakeholder whose input quality directly affects the firm's ability to produce.","D":"No pressure group is involved in the scenario, and such groups do not set the firm's prices. The operational issue is a supply failure, so this option is unrelated to the event."}}},{"id":"P1_U1_MCQ_1531","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1531","question":"Vilnius Courier in Vilnius, Lithuania, charges $8 to deliver a parcel and spends $2 on fuel and packaging. Customers say the service saves them a trip across the city. How does this business add value?","options":{"A":"By combining bought-in inputs into a service customers value above the $8 price","B":"By manufacturing the parcels from raw materials it owns","C":"By extracting natural resources from the surrounding countryside","D":"By removing the need for any paid inputs in production"},"correctOption":"A","correctAnswer":"By combining bought-in inputs into a service customers value above the $8 price","questionType":"MCQ","explanation":{"correct_reason":"Vilnius Courier uses $2 of fuel and packaging to provide a delivery worth more than the $8 price because it saves customers a trip. Combining inputs into a valued service is how the business creates added value.","distractor_reasons":{"A":"Vilnius Courier uses $2 of fuel and packaging to provide a delivery worth more than the $8 price because it saves customers a trip. Combining inputs into a valued service is how the business creates added value.","B":"The courier carries parcels rather than making them from raw materials. Manufacturing is not the activity described, so it cannot explain how value is created for customers in Vilnius.","C":"No natural resources are extracted by the business. Fuel and packaging are bought in, and the value comes from delivering parcels, not from obtaining raw materials in the countryside.","D":"The firm explicitly spends $2 on fuel and packaging, so paid inputs remain necessary. Value is created by using those inputs well, not by eliminating them from the process."}}},{"id":"P1_U1_MCQ_1532","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1532","question":"Zurich Insurance in Zurich, Switzerland, employs 6,000 people selling household policies and handling claims for customers across the country. Which statement about this business and its sector is most accurate?","options":{"A":"Insurance is part of the secondary sector because it handles money","B":"The tertiary sector consists only of shops and restaurants","C":"Insurance firms extract raw materials for manufacturers to use","D":"Insurance is a tertiary service whose growth reflects the importance of services in developed economies"},"correctOption":"D","correctAnswer":"Insurance is a tertiary service whose growth reflects the importance of services in developed economies","questionType":"MCQ","explanation":{"correct_reason":"Selling policies and settling claims are services, so Zurich Insurance belongs to the tertiary sector. Its 6,000 employees illustrate how services dominate employment in a developed economy such as Switzerland.","distractor_reasons":{"A":"Handling money does not make a firm a manufacturer. Policies and claims are services with no physical production, so the secondary classification is inappropriate for Zurich Insurance.","B":"The tertiary sector includes banking, insurance, transport, health and many other services. Limiting it to shops and restaurants ignores the 6,000 people employed by this insurer.","C":"Insurers do not extract raw materials; that is primary sector work. Zurich Insurance provides financial protection to customers, which is a service rather than the supply of materials.","D":"Selling policies and settling claims are services, so Zurich Insurance belongs to the tertiary sector. Its 6,000 employees illustrate how services dominate employment in a developed economy such as Switzerland."}}},{"id":"P1_U1_MCQ_1533","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1533","question":"Buenos Aires Bikes in Buenos Aires, Argentina, sold 8,000 bicycles last year. Total bicycle sales in its city market were 40,000. What was the firm's market share?","options":{"A":"12%","B":"20%","C":"25%","D":"32%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Eight thousand bicycles sold out of a total market of 40,000 equals twenty percent. Buenos Aires Bikes therefore held one fifth of its city market, which is the market share the question asks for.","distractor_reasons":{"A":"Twelve percent of 40,000 is 4,800 bicycles, well below the 8,000 sold by Buenos Aires Bikes. The share must be recalculated using the sales figures given in the scenario.","B":"Eight thousand bicycles sold out of a total market of 40,000 equals twenty percent. Buenos Aires Bikes therefore held one fifth of its city market, which is the market share the question asks for.","C":"A quarter of 40,000 would be 10,000 bicycles. Because the firm sold only 8,000, its market share is smaller than twenty five percent and this option is too high.","D":"Thirty two percent of 40,000 is 12,800 bicycles, far more than the 8,000 sold. This figure greatly overstates the company's position in the Buenos Aires bicycle market."}}},{"id":"P1_U1_MCQ_1534","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1534","question":"Porto Textiles Ltd in Porto, Portugal, has many distant shareholders while a board of directors makes the daily decisions. Some owners want higher dividends, but managers prefer to retain profit for expansion. Which issue does this show?","options":{"A":"A possible divergence between the goals of owners and managers","B":"Unlimited liability falling on every shareholder","C":"An inability to raise finance by issuing shares","D":"A legal duty to distribute all profit as dividends"},"correctOption":"A","correctAnswer":"A possible divergence between the goals of owners and managers","questionType":"MCQ","explanation":{"correct_reason":"Shareholders want dividends while managers want retained profit for growth. Because directors control daily decisions at Porto Textiles Ltd, this illustrates the separation of ownership from control and a possible clash of objectives.","distractor_reasons":{"A":"Shareholders want dividends while managers want retained profit for growth. Because directors control daily decisions at Porto Textiles Ltd, this illustrates the separation of ownership from control and a possible clash of objectives.","B":"Shareholders in a limited company are liable only for the value of their shares. Unlimited liability does not apply, and the scenario is about objectives rather than debt responsibility.","C":"The company already has many shareholders, showing it can raise finance from share issues. Nothing in the Porto case suggests an inability to obtain funds from investors.","D":"Companies are not legally required to pay out all profit as dividends. Retaining earnings for expansion is allowed, which is exactly what the managers at Porto Textiles propose."}}},{"id":"P1_U1_MCQ_1535","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1535","question":"Tunisia Solar Farms near Tunis, Tunisia, plans to cover 200 hectares with panels. A local environmental group objects because the land is used by migrating birds. Which stakeholder conflict is described?","options":{"A":"Shareholders versus customers over panel prices","B":"Employees versus suppliers over delivery schedules","C":"The government versus banks over interest rates","D":"A pressure group concerned about land use versus a business seeking expansion"},"correctOption":"D","correctAnswer":"A pressure group concerned about land use versus a business seeking expansion","questionType":"MCQ","explanation":{"correct_reason":"The environmental group wants to protect bird habitat while Tunisia Solar Farms wants to expand onto 200 hectares. That is a direct conflict between an external pressure group and the business pursuing its growth objective.","distractor_reasons":{"A":"No disagreement about panel prices is mentioned, and shareholders are not part of the dispute. The objection comes from a group concerned with wildlife, not from buyers or owners.","B":"The scenario does not describe a wages or delivery disagreement between employees and suppliers. The competing interests are conservation of land and construction of the solar farm.","C":"Interest rates and banking relationships are absent from the case. Government and banks are not the opposing parties, so this option does not reflect the conflict described near Tunis.","D":"The environmental group wants to protect bird habitat while Tunisia Solar Farms wants to expand onto 200 hectares. That is a direct conflict between an external pressure group and the business pursuing its growth objective."}}},{"id":"P1_U1_MCQ_1536","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1536","question":"Mendoza Vineyards in Mendoza, Argentina, owns 50 hectares of fertile soil and an irrigation channel that supplies water to its vines. Which factor of production do the land and water represent?","options":{"A":"Capital","B":"Labour","C":"Enterprise","D":"Land"},"correctOption":"D","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"In production, land means all natural resources, including fertile soil and water. The 50 hectares and irrigation channel at Mendoza Vineyards are natural endowments, so they are correctly classified as the land factor.","distractor_reasons":{"A":"Capital refers to man-made equipment such as machinery or buildings. Soil and an irrigation water source occur naturally, so they are not capital goods purchased by the vineyard.","B":"Labour is the effort and skill of workers in the vineyard. Land and water are not human inputs, so calling these natural resources labour would be a category error.","C":"Enterprise is the risk-taking judgement of the owner who organises production. Fertile soil and water cannot make decisions or bear risk, so they do not represent enterprise.","D":"In production, land means all natural resources, including fertile soil and water. The 50 hectares and irrigation channel at Mendoza Vineyards are natural endowments, so they are correctly classified as the land factor."}}},{"id":"P1_U1_MCQ_1537","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1537","question":"Cluj Manufacturing in Cluj-Napoca, Romania, increased its annual output from $500 million to $560 million, according to its production report. What was the percentage rise in output?","options":{"A":"8%","B":"10%","C":"12%","D":"14%"},"correctOption":"C","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Output rose by $60 million from a base of $500 million, and $60 million divided by $500 million equals twelve percent. Cluj Manufacturing therefore increased its secondary sector output by twelve percent.","distractor_reasons":{"A":"Eight percent of $500 million is $40 million, which would lift output only to $540 million. The reported figure is $560 million, so this percentage is too small.","B":"Ten percent of $500 million is $50 million, giving $550 million of output. Since Cluj Manufacturing reached $560 million, the actual increase must be greater than ten percent.","C":"Output rose by $60 million from a base of $500 million, and $60 million divided by $500 million equals twelve percent. Cluj Manufacturing therefore increased its secondary sector output by twelve percent.","D":"Fourteen percent of $500 million is $70 million, which would produce $570 million of output. The final figure of $560 million is lower, so this answer overstates the rise."}}},{"id":"P1_U1_MCQ_1538","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1538","question":"Tunis Ceramics in Tunis, Tunisia, is a family firm that wants to expand but cannot afford a new kiln and lacks experienced middle managers. Which barrier to growth does this illustrate?","options":{"A":"Excess demand forcing the firm to turn away customers","B":"An abundance of economies of scale already available","C":"Limited access to finance and management expertise","D":"A guaranteed market share removing the need to expand"},"correctOption":"C","correctAnswer":"Limited access to finance and management expertise","questionType":"MCQ","explanation":{"correct_reason":"Tunis Ceramics cannot buy a kiln and has no experienced managers, so both money and skills block its expansion. These are common barriers that keep small firms from growing into larger businesses.","distractor_reasons":{"A":"The scenario describes an inability to expand, not excess demand that the firm must refuse. No order backlog or waiting list is mentioned in the Tunis case.","B":"Economies of scale are cost advantages from large output. Since the firm is short of funds and skills, it cannot exploit them, and an abundance of such advantages is not a barrier.","C":"Tunis Ceramics cannot buy a kiln and has no experienced managers, so both money and skills block its expansion. These are common barriers that keep small firms from growing into larger businesses.","D":"A guaranteed market share would encourage expansion rather than prevent it. Tunis Ceramics wants to grow but lacks the finance and expertise needed to do so."}}},{"id":"P1_U1_MCQ_1539","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1539","question":"Colombo Water Board in Colombo, Sri Lanka, is owned by the government, supplies tap water to households and reinvests any surplus in pipes rather than paying dividends to private investors. Which organisation is this?","options":{"A":"A private limited company owned by shareholders","B":"A partnership between local business owners","C":"A sole trader providing a public utility","D":"A public corporation with a public service objective"},"correctOption":"D","correctAnswer":"A public corporation with a public service objective","questionType":"MCQ","explanation":{"correct_reason":"Government ownership, water supply to households and reinvestment instead of private dividends identify a public corporation. Its objective is public service, which matches the work of Colombo Water Board.","distractor_reasons":{"A":"A private limited company has private shareholders who expect returns. Colombo Water Board is state owned and pays no private dividends, so that structure is ruled out.","B":"A partnership is owned by private individuals sharing profit. The water board is owned by government and serves the public, so it is not a partnership of local owners.","C":"A sole trader has one private owner, which cannot supply water to a whole city. The board's public ownership and service role are incompatible with sole trader status.","D":"Government ownership, water supply to households and reinvestment instead of private dividends identify a public corporation. Its objective is public service, which matches the work of Colombo Water Board."}}},{"id":"P1_U1_MCQ_1540","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1540","question":"Bratislava Courier in Bratislava, Slovakia, set a target of reducing delivery complaints from 200 to 100 within six months, with progress reviewed each month. Which kind of objective has the board created?","options":{"A":"A vague mission statement with no measurable outcome","B":"A specific, measurable objective with a clear time limit","C":"An ethical aim with no numerical target or deadline","D":"A legal requirement imposed by the local authority"},"correctOption":"B","correctAnswer":"A specific, measurable objective with a clear time limit","questionType":"MCQ","explanation":{"correct_reason":"The board names a precise change from 200 to 100 complaints, sets a six-month deadline and schedules monthly reviews. Bratislava Courier has therefore created a specific and measurable objective.","distractor_reasons":{"A":"The target gives an exact number and a deadline, so it is not vague. A mission statement would express broad purpose rather than a reduction from 200 to 100 complaints.","B":"The board names a precise change from 200 to 100 complaints, sets a six-month deadline and schedules monthly reviews. Bratislava Courier has therefore created a specific and measurable objective.","C":"Although fewer complaints may benefit customers, the target is expressed numerically and timed. Calling it an aim with no deadline ignores the six-month period and monthly reviews.","D":"No law or local authority requirement is mentioned. The board itself set the complaint target, so it is an internal objective rather than an externally imposed rule."}}},{"id":"P1_U1_MCQ_1541","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1541","question":"Nairobi Packagers in Nairobi, Kenya, buys materials for $30 and sells each finished wooden crate for $50. What is the value added as a percentage of sales revenue per crate?","options":{"A":"20%","B":"30%","C":"60%","D":"40%"},"correctOption":"D","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Each crate adds $20 of value because Nairobi Packagers buys materials for $30 and sells the finished crate for $50. Dividing the $20 margin by the $50 selling price gives forty percent.","distractor_reasons":{"A":"The $20 figure is value added in dollars per crate, not a percentage of sales revenue. Dividing the $20 margin by the $50 selling price produces forty percent.","B":"Thirty percent is the share of revenue spent on bought-in materials, since $30 of the $50 price goes to supplies. The share retained as value added is calculated from the $20 margin.","C":"Sixty percent wrongly compares the $30 material cost with the $20 margin. Value added as a proportion of sales must be the $20 of added value divided by the $50 price.","D":"Each crate adds $20 of value because Nairobi Packagers buys materials for $30 and sells the finished crate for $50. Dividing the $20 margin by the $50 selling price gives forty percent."}}},{"id":"P1_U1_MCQ_1542","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1542","question":"Cartagena Ship Repairs in Cartagena, Colombia, employs divers and engineers who maintain vessels owned by shipping companies. Which economic sector does this business belong to?","options":{"A":"The primary sector","B":"The tertiary sector","C":"The secondary sector","D":"The quaternary sector"},"correctOption":"B","correctAnswer":"The tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Maintaining vessels is a service provided to shipowners, which places Cartagena Ship Repairs in the tertiary sector. The firm does not build new ships or extract materials, so it is not a producer of goods.","distractor_reasons":{"A":"The repair yard does not extract natural resources from the sea or land. It services ships owned by clients, so classifying this work as primary activity ignores its service character.","B":"Maintaining vessels is a service provided to shipowners, which places Cartagena Ship Repairs in the tertiary sector. The firm does not build new ships or extract materials, so it is not a producer of goods.","C":"Shipbuilding is secondary manufacturing, but maintaining existing vessels is a service. Cartagena Ship Repairs does not turn raw materials into newly built ships, so secondary is incorrect.","D":"No research or specialist information work is described. The dock performs practical maintenance for clients, which is a tertiary service rather than a quaternary knowledge activity."}}},{"id":"P1_U1_MCQ_1543","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1543","question":"Dhaka Snack Chain in Dhaka, Bangladesh, expanded by allowing independent shopkeepers to trade under its brand and recipes in return for a fee. Which method of growth is being used?","options":{"A":"Organic growth funded only from retained profit","B":"A merger with a rival snack manufacturer","C":"Franchising the brand to independent operators","D":"A takeover of a major ingredient supplier"},"correctOption":"C","correctAnswer":"Franchising the brand to independent operators","questionType":"MCQ","explanation":{"correct_reason":"Independent shopkeepers paying to use the Dhaka Snack Chain name and recipes are franchisees. The business grows by licensing its brand and know-how rather than owning and running every outlet itself.","distractor_reasons":{"A":"Organic growth would mean the company opening and funding its own shops from retained profit. Here independent owners pay a fee, so the expansion is not purely internal.","B":"A merger would combine two existing snack businesses into one firm. No such combination is described; the chain simply grants rights to individual shopkeepers in Dhaka.","C":"Independent shopkeepers paying to use the Dhaka Snack Chain name and recipes are franchisees. The business grows by licensing its brand and know-how rather than owning and running every outlet itself.","D":"Buying an ingredient supplier would be a takeover of another company in a different stage of production. The scenario describes brand licensing to shopkeepers, not acquiring a supplier."}}},{"id":"P1_U1_MCQ_1544","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1544","question":"Tampere Woodworks in Tampere, Finland, is family owned. Its shares are not traded publicly, and the owners' liability is limited to what they invested. Which legal structure does the firm have?","options":{"A":"A private limited company with limited liability","B":"A public limited company whose shares trade freely","C":"A partnership with unlimited liability for all owners","D":"A sole trader operating without a separate company"},"correctOption":"A","correctAnswer":"A private limited company with limited liability","questionType":"MCQ","explanation":{"correct_reason":"Shares held privately and not traded on an exchange, together with limited liability, identify a private limited company. Tampere Woodworks keeps control in the family while protecting owners' personal assets.","distractor_reasons":{"A":"Shares held privately and not traded on an exchange, together with limited liability, identify a private limited company. Tampere Woodworks keeps control in the family while protecting owners' personal assets.","B":"A public limited company offers shares to the general public and has them traded on a stock exchange. Tampere Woodworks explicitly keeps its shares private, so that structure is eliminated.","C":"Partners normally face unlimited liability for firm debts. The owners here are protected to the value of their investment, which is the opposite of the unlimited liability described.","D":"A sole trader has one owner and no limited liability shield. The family firm has shares and limited liability, so it is a company rather than a single unincorporated owner."}}},{"id":"P1_U1_MCQ_1545","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1545","question":"Windhoek Lodges in Windhoek, Namibia, earned a profit of $1 million. Employees won a wage increase costing $200,000 a year. What percentage of the profit does that wage increase represent?","options":{"A":"10%","B":"20%","C":"25%","D":"40%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The $200,000 wage increase is twenty percent of the $1 million profit. Windhoek Lodges would therefore devote one fifth of its annual profit to the pay rise won by employees.","distractor_reasons":{"A":"Ten percent of $1 million is $100,000, only half of the agreed wage increase. The calculation must compare the full $200,000 cost with the stated profit figure.","B":"The $200,000 wage increase is twenty percent of the $1 million profit. Windhoek Lodges would therefore devote one fifth of its annual profit to the pay rise won by employees.","C":"Twenty five percent of $1 million is $250,000, more than the $200,000 wage bill increase. This option overstates the share of profit absorbed by the pay rise.","D":"Forty percent of $1 million is $400,000, double the actual cost of the wage increase. Since the increase cost $200,000, its share of profit is half that percentage."}}},{"id":"P1_U1_MCQ_1546","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1546","question":"Hyderabad Printing in Hyderabad, India, combines paper, ink, electricity and skilled labour to produce textbooks for schools. What does this example best illustrate about business activity?","options":{"A":"That finished goods can be obtained directly from nature","B":"That services are unable to create any added value","C":"That inputs are transformed into outputs which satisfy customer needs","D":"That production can occur without using any resources"},"correctOption":"C","correctAnswer":"That inputs are transformed into outputs which satisfy customer needs","questionType":"MCQ","explanation":{"correct_reason":"Hyderabad Printing turns paper, ink, power and labour into books that schools need. That transformation of inputs into outputs which satisfy customers is the central idea of business activity.","distractor_reasons":{"A":"Textbooks are manufactured products, not resources taken directly from nature. The paper and ink are inputs that the printing business must combine before a book exists.","B":"The example concerns manufactured books, and services can also add value by meeting needs. Nothing in the scenario supports the claim that services create no added value.","C":"Hyderabad Printing turns paper, ink, power and labour into books that schools need. That transformation of inputs into outputs which satisfy customers is the central idea of business activity.","D":"Production at Hyderabad Printing clearly uses paper, ink, electricity and labour. The idea of output without resources contradicts the inputs explicitly listed in the case."}}},{"id":"P1_U1_MCQ_1547","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1547","question":"Kalgoorlie Gold Mine in Kalgoorlie, Australia, digs ore from the ground and sells it to a refinery. Which economic sector does this extractive business belong to?","options":{"A":"The primary sector","B":"The secondary sector","C":"The tertiary sector","D":"The quaternary sector"},"correctOption":"A","correctAnswer":"The primary sector","questionType":"MCQ","explanation":{"correct_reason":"Mining extracts a natural resource from the ground, which is the defining activity of the primary sector. Kalgoorlie Gold Mine sells ore onward rather than refining it or providing a service.","distractor_reasons":{"A":"Mining extracts a natural resource from the ground, which is the defining activity of the primary sector. Kalgoorlie Gold Mine sells ore onward rather than refining it or providing a service.","B":"Secondary sector firms convert materials into manufactured goods. The mine digs ore and sells it unprocessed to a refinery, so the manufacturing stage occurs elsewhere.","C":"The tertiary sector provides services such as transport or retail. Digging ore is extraction of a natural resource, so describing the mine as a service business is inaccurate.","D":"Quaternary activity involves research and specialist knowledge. Mineral extraction in Kalgoorlie is a primary industry, not a knowledge-based research operation."}}},{"id":"P1_U1_MCQ_1548","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1548","question":"Suzhou Electronics in Suzhou, China, doubled its output and found that bulk purchases cut its average cost from $12 to $9 per unit. Which motive for business growth does this demonstrate?","options":{"A":"Rising unit costs as the firm becomes larger","B":"The complete removal of all market competition","C":"A sustained fall in demand for the company's products","D":"Lower average costs gained through economies of scale"},"correctOption":"D","correctAnswer":"Lower average costs gained through economies of scale","questionType":"MCQ","explanation":{"correct_reason":"As Suzhou Electronics doubled output, bulk buying reduced average cost from $12 to $9 per unit. Falling unit costs from a larger scale of production are economies of scale and a strong reason to grow.","distractor_reasons":{"A":"Unit costs fell rather than rose after expansion. The move from $12 to $9 shows the opposite of rising costs, so this answer contradicts the reported figures.","B":"Growing may strengthen a firm's position, but competition is not removed entirely. The scenario is about cost savings from bulk purchases, not the absence of rivals.","C":"A fall in demand would discourage expansion, yet Suzhou Electronics doubled output. The evidence points to lower costs at higher volume, not to weaker market demand.","D":"As Suzhou Electronics doubled output, bulk buying reduced average cost from $12 to $9 per unit. Falling unit costs from a larger scale of production are economies of scale and a strong reason to grow."}}},{"id":"P1_U1_MCQ_1549","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1549","question":"Harare Legal Partners in Harare, Zimbabwe, shares profits between two partners in the ratio 3:2. If total profit was $250,000, how much did the partner with the larger share receive?","options":{"A":"$150,000","B":"$100,000","C":"$125,000","D":"$50,000"},"correctOption":"A","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio three to two has five parts, so one part of the $250,000 profit is $50,000. The senior partner receives three parts, which is $150,000, leaving $100,000 for the junior partner.","distractor_reasons":{"A":"The ratio three to two has five parts, so one part of the $250,000 profit is $50,000. The senior partner receives three parts, which is $150,000, leaving $100,000 for the junior partner.","B":"The $100,000 figure is the junior partner's two-part share of the $250,000 profit. The question asks for the larger three-part amount, so this option names the wrong partner.","C":"An equal split would give each partner $125,000, but the agreed ratio is three to two. The partner with the larger share must therefore receive more than half the profit.","D":"Fifty thousand dollars is the value of one of the five parts of the ratio. The senior partner receives three such parts, so the correct share is three times this amount."}}},{"id":"P1_U1_MCQ_1550","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1550","question":"Port Moresby Mining near Port Moresby, Papua New Guinea, plans to expand its pit. Shareholders welcome higher profits, but residents fear damage to the river they use for washing and fishing. Which conflict is shown?","options":{"A":"Customers versus suppliers over delivery schedules","B":"Managers versus employees over training budgets","C":"The local community concerned about water versus shareholders wanting higher profits","D":"The government versus banks over interest rates"},"correctOption":"C","correctAnswer":"The local community concerned about water versus shareholders wanting higher profits","questionType":"MCQ","explanation":{"correct_reason":"Residents fear damage to the river they rely on while owners want profit from a larger pit. The opposing interests at Port Moresby Mining are the local community and shareholders over the mine's expansion.","distractor_reasons":{"A":"No disagreement about delivery schedules between customers and suppliers is described. The dispute concerns environmental effects on residents, not the movement of goods.","B":"Training budgets for workers are not mentioned in the case. The competing claims come from local people protecting a river and owners seeking returns, not from staff versus management.","C":"Residents fear damage to the river they rely on while owners want profit from a larger pit. The opposing interests at Port Moresby Mining are the local community and shareholders over the mine's expansion.","D":"Interest rates and banking relationships are absent from the scenario. Neither government nor banks are the parties divided, so this option cannot describe the conflict."}}},{"id":"P1_U1_MCQ_1551","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1551","question":"Florence Leather Goods in Florence, Italy, buys leather for $40 per bag and sells the finished, branded bag for $180. Which activity creates most of the added value in this case?","options":{"A":"Paying a low price for the raw leather","B":"Selling the bags at a discount to clear stock","C":"Reducing the number of skilled designers employed","D":"Designing and branding the bag so customers will pay $180"},"correctOption":"D","correctAnswer":"Designing and branding the bag so customers will pay $180","questionType":"MCQ","explanation":{"correct_reason":"The leather costs $40 but customers pay $180 because of the design and brand. Those activities, rather than the material purchase, create the $140 of value added per bag for Florence Leather Goods.","distractor_reasons":{"A":"Buying leather cheaply only reduces an input cost. The large gap between the $40 material cost and the $180 price comes from what the business adds by designing and branding the product.","B":"Discounting would lower the selling price and shrink the gap over the $40 cost. It would reduce rather than create added value, so it cannot explain the $180 price.","C":"Employing fewer designers would weaken the design work that justifies the high price. The scenario attributes the premium to design and branding, not to cutting skilled staff.","D":"The leather costs $40 but customers pay $180 because of the design and brand. Those activities, rather than the material purchase, create the $140 of value added per bag for Florence Leather Goods."}}},{"id":"P1_U1_MCQ_1552","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1552","question":"Tbilisi Construction in Tbilisi, Georgia, uses concrete, steel and bricklayers to build apartment blocks for local families. Which economic sector does this business operate in?","options":{"A":"The primary sector","B":"The secondary sector","C":"The tertiary sector","D":"The quaternary sector"},"correctOption":"B","correctAnswer":"The secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Construction turns materials such as concrete and steel into finished buildings, which is secondary sector activity. Tbilisi Construction does not extract raw materials or sell a service to clients.","distractor_reasons":{"A":"The primary sector extracts natural resources, whereas this firm buys concrete and steel from other producers. Building apartments is a manufacturing and construction activity, not extraction.","B":"Construction turns materials such as concrete and steel into finished buildings, which is secondary sector activity. Tbilisi Construction does not extract raw materials or sell a service to clients.","C":"Although the apartments serve residents, the business creates physical structures rather than providing a service. Its classification is secondary, not tertiary, despite the end users.","D":"No research or information work is described at Tbilisi Construction. Putting up apartment blocks is practical construction, which belongs to the secondary sector."}}},{"id":"P1_U1_MCQ_1553","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1553","question":"Maputo Logistics in Maputo, Mozambique, increased its number of employees from 400 to 480 during the year. What was the percentage growth in its workforce?","options":{"A":"8%","B":"12%","C":"20%","D":"25%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The workforce grew by 80 employees from a base of 400, and 80 divided by 400 equals twenty percent. Maputo Logistics therefore increased its staffing level by one fifth during the year.","distractor_reasons":{"A":"Eight percent of 400 is only 32 extra workers, far fewer than the increase to 480. The calculation must start from the 80 additional employees actually hired.","B":"Twelve percent of 400 is 48 workers, which would give a workforce of 448. Since the final number was 480, this percentage understates the true growth.","C":"The workforce grew by 80 employees from a base of 400, and 80 divided by 400 equals twenty percent. Maputo Logistics therefore increased its staffing level by one fifth during the year.","D":"Twenty five percent of 400 is 100 workers, which would produce a workforce of 500. Maputo Logistics reached 480, so its growth rate is lower than twenty five percent."}}},{"id":"P1_U1_MCQ_1554","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1554","question":"Addis Ababa Community Clinic in Addis Ababa, Ethiopia, is run by a charity. Any surplus is spent on treating more patients rather than paid to private owners. Which form of organisation does this describe?","options":{"A":"A sole trader seeking personal profit","B":"A partnership of doctors taking drawings","C":"A public limited company with shareholders","D":"A non-profit organisation reinvesting surplus in its cause"},"correctOption":"D","correctAnswer":"A non-profit organisation reinvesting surplus in its cause","questionType":"MCQ","explanation":{"correct_reason":"No private owner takes profit and any surplus funds more treatment, which defines a non-profit organisation. Addis Ababa Community Clinic exists to serve patients rather than distribute earnings to investors.","distractor_reasons":{"A":"A sole trader is one private owner who keeps the profit. The clinic is charity run and reinvests its surplus, so private profit is contrary to the scenario.","B":"A partnership would let doctors share profits among themselves. The scenario says the surplus pays for more treatment, so there are no owners drawing out earnings.","C":"A public limited company has shareholders who expect dividends. The clinic has no such investors and channels money back into patient care, so that structure is wrong.","D":"No private owner takes profit and any surplus funds more treatment, which defines a non-profit organisation. Addis Ababa Community Clinic exists to serve patients rather than distribute earnings to investors."}}},{"id":"P1_U1_MCQ_1555","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1555","question":"Manila Contact Centre in Manila, Philippines, plans to automate some work. Employees want guarantees of job security, while owners want lower operating costs to protect dividends. Which stakeholder conflict is this?","options":{"A":"Employees wanting job security versus owners seeking cost cuts","B":"Customers wanting variety versus suppliers seeking longer contracts","C":"The government seeking tax revenue versus banks seeking interest","D":"Managers seeking bonuses versus customers seeking lower prices"},"correctOption":"A","correctAnswer":"Employees wanting job security versus owners seeking cost cuts","questionType":"MCQ","explanation":{"correct_reason":"Workers fear losing jobs to automation while owners want cheaper operations to protect dividends. The opposing interests at Manila Contact Centre are employees' security against shareholders' drive to cut costs.","distractor_reasons":{"A":"Workers fear losing jobs to automation while owners want cheaper operations to protect dividends. The opposing interests at Manila Contact Centre are employees' security against shareholders' drive to cut costs.","B":"No disagreement about product variety or supplier contracts is described. The dispute concerns automation and its effect on jobs and operating costs, not those two groups.","C":"Tax revenue and bank interest are absent from the scenario. Neither government nor banks are shown in conflict, so this option does not match the case at all.","D":"Managers' bonuses and customer prices are not mentioned. The stated positions belong to employees protecting jobs and owners reducing costs, so this pairing is incorrect."}}},{"id":"P1_U1_MCQ_1556","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1556","question":"Quito Chocolate in Quito, Ecuador, buys cocoa for $4 per kilogram and sells the finished chocolate for $12 per kilogram. What is the main source of the value added by this business?","options":{"A":"The low price paid for the cocoa beans","B":"Processing and branding that let it charge $12 instead of $4","C":"The number of beans grown by cocoa farmers","D":"Government rules setting the price of chocolate"},"correctOption":"B","correctAnswer":"Processing and branding that let it charge $12 instead of $4","questionType":"MCQ","explanation":{"correct_reason":"Cocoa bought for $4 becomes chocolate sold for $12 because Quito Chocolate processes, packages and brands it. That transformation creates the $8 of value added per kilogram of output.","distractor_reasons":{"A":"Paying a low input price reduces cost but does not by itself create the $12 selling price. The added value comes from turning cocoa into a product customers will pay more for.","B":"Cocoa bought for $4 becomes chocolate sold for $12 because Quito Chocolate processes, packages and brands it. That transformation creates the $8 of value added per kilogram of output.","C":"The quantity of beans grown by farmers is an input detail, not the source of the margin. Quito Chocolate adds value through the processing and branding it carries out in Quito.","D":"No government price control is mentioned in the scenario. The higher price arises from what the business does with the cocoa, not from an external regulation."}}},{"id":"P1_U1_MCQ_1557","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1557","question":"In Bogota, Colombia, a district employs 25,000 workers, of whom 15,000 work in shops, banks and transport services. What percentage of the workforce is in the tertiary sector?","options":{"A":"40%","B":"50%","C":"75%","D":"60%"},"correctOption":"D","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"Fifteen thousand of the 25,000 workers hold service jobs, and 15,000 divided by 25,000 equals sixty percent. Three fifths of the Bogota district's workforce is therefore in the tertiary sector.","distractor_reasons":{"A":"Forty percent is the share of workers outside service jobs, namely 10,000 of 25,000. The question asks for those employed in shops, banks and transport, which is the larger group.","B":"Fifty percent of 25,000 is 12,500 workers, fewer than the 15,000 actually counted in services. The tertiary share must therefore be greater than half.","C":"Seventy five percent of 25,000 would be 18,750 service workers. Since only 15,000 are employed in those Bogota services, this percentage is too high.","D":"Fifteen thousand of the 25,000 workers hold service jobs, and 15,000 divided by 25,000 equals sixty percent. Three fifths of the Bogota district's workforce is therefore in the tertiary sector."}}},{"id":"P1_U1_MCQ_1558","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1558","question":"Phnom Penh Rice Mills in Phnom Penh, Cambodia, built a second mill using money saved from its own profits. Which method of growth does this represent?","options":{"A":"Organic growth funded from internal savings","B":"A takeover of a competing rice mill","C":"A merger with a rice exporting business","D":"A nationalisation by the local authority"},"correctOption":"A","correctAnswer":"Organic growth funded from internal savings","questionType":"MCQ","explanation":{"correct_reason":"Building a second mill from the company's own saved profit is internal expansion. Phnom Penh Rice Mills grew organically rather than by purchasing or combining with another business.","distractor_reasons":{"A":"Building a second mill from the company's own saved profit is internal expansion. Phnom Penh Rice Mills grew organically rather than by purchasing or combining with another business.","B":"A takeover means buying an existing rival firm. The new mill was constructed with internal funds, so no competing business was purchased in this case.","C":"A merger would join the rice mill with another company, such as an exporter. The scenario describes a single firm adding its own facility, not joining with a partner.","D":"Nationalisation would transfer ownership to the state. Phnom Penh Rice Mills remains privately funded by its own profits, so state takeover is not what happened."}}},{"id":"P1_U1_MCQ_1559","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1559","question":"Lisbon Shipping Plc in Lisbon, Portugal, must publish detailed accounts and answer to many shareholders who press for higher dividends. Which disadvantage of this legal structure is being described?","options":{"A":"Unlimited liability for every shareholder","B":"Pressure to satisfy many shareholders and disclose information","C":"An inability to transfer shares to new investors","D":"A prohibition on employing professional managers"},"correctOption":"B","correctAnswer":"Pressure to satisfy many shareholders and disclose information","questionType":"MCQ","explanation":{"correct_reason":"A public listed company must disclose accounts and respond to many shareholders who may demand short-term returns. Those drawbacks match the position of Lisbon Shipping Plc, whose owners actually have limited liability.","distractor_reasons":{"A":"Shareholders in a public limited company risk only the value of their shares. Unlimited liability is not a feature of this structure, so it cannot be the disadvantage described.","B":"A public listed company must disclose accounts and respond to many shareholders who may demand short-term returns. Those drawbacks match the position of Lisbon Shipping Plc, whose owners actually have limited liability.","C":"Shares in a public company can generally be bought and sold by investors. The scenario does not suggest any restriction on transferring ownership, so this is wrong.","D":"Public companies routinely employ professional managers to run operations. Nothing in the Lisbon case prevents hiring managers, so this option is not a real drawback."}}},{"id":"P1_U1_MCQ_1560","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1560","question":"Perth Wind Farm near Perth, Australia, needs planning approval from the local council, which has also received many letters from residents. How should the business treat this stakeholder according to power and interest?","options":{"A":"Ignore it because the council has no financial stake","B":"Keep it informed with minimal contact and no discussion","C":"Manage it closely as a key stakeholder with high power and high interest","D":"Treat it as a low priority supplier of building services"},"correctOption":"C","correctAnswer":"Manage it closely as a key stakeholder with high power and high interest","questionType":"MCQ","explanation":{"correct_reason":"The council can grant or refuse planning permission and is strongly concerned about local opinion, so it has both power and interest. Perth Wind Farm should manage such a stakeholder closely.","distractor_reasons":{"A":"A lack of financial investment does not make the council unimportant. Its planning power and the letters from residents give it enormous influence over the project's future.","B":"Minimal contact would risk losing planning permission and local support. With high power and high interest, this stakeholder needs active engagement rather than occasional information.","C":"The council can grant or refuse planning permission and is strongly concerned about local opinion, so it has both power and interest. Perth Wind Farm should manage such a stakeholder closely.","D":"The council is not supplying building services to the wind farm. It is a regulator with decision-making authority, so describing it as a low priority supplier is a category error."}}},{"id":"P1_U1_MCQ_1561","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1561","question":"Kampala Furniture in Kampala, Uganda, spends $85 on timber and fittings for each chair and sells the finished chair for $150. What value does the business add per chair?","options":{"A":"$65","B":"$85","C":"$150","D":"$235"},"correctOption":"A","correctAnswer":"$65","questionType":"MCQ","explanation":{"correct_reason":"Each chair sells for $150 while bought-in timber and fittings cost $85, leaving $65 of value added by Kampala Furniture through cutting, assembly and finishing.","distractor_reasons":{"A":"Each chair sells for $150 while bought-in timber and fittings cost $85, leaving $65 of value added by Kampala Furniture through cutting, assembly and finishing.","B":"The $85 figure is the cost of bought-in materials, not the value added. The margin created by the business is the difference between that cost and the $150 selling price.","C":"The $150 figure is the full selling price of a chair, which includes the cost of materials. Value added deducts the $85 spent on timber and fittings from that price.","D":"The $235 figure adds the $85 material cost to the $150 selling price. Value added is the difference between the two amounts, never their combined total."}}},{"id":"P1_U1_MCQ_1562","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1562","question":"Belfast Call Centre in Belfast, Northern Ireland, created 500 jobs handling customer enquiries just as local shipbuilding yards closed. Which change in employment does this illustrate?","options":{"A":"Primary sector firms replacing service industry jobs","B":"Secondary sector expansion creating 500 new shipyard positions","C":"Quaternary research laboratories closing down service centres","D":"Growth of tertiary employment as manufacturing industry declines"},"correctOption":"D","correctAnswer":"Growth of tertiary employment as manufacturing industry declines","questionType":"MCQ","explanation":{"correct_reason":"A call centre provides services, so its 500 jobs are tertiary. Their arrival as shipbuilding shrinks shows the wider shift from secondary manufacturing toward service employment in Belfast.","distractor_reasons":{"A":"Call centre work does not extract natural resources. The 500 new jobs are services replacing manufacturing jobs, not primary firms taking the place of service industry work.","B":"Shipbuilding yards closed rather than expanded, so no 500 shipyard positions were created. The new employment is in a call centre, which is a tertiary service.","C":"No research laboratories are described in Belfast. The change is a service centre opening as manufacturing declines, which is the opposite of quaternary research closing services.","D":"A call centre provides services, so its 500 jobs are tertiary. Their arrival as shipbuilding shrinks shows the wider shift from secondary manufacturing toward service employment in Belfast."}}},{"id":"P1_U1_MCQ_1563","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1563","question":"Auckland Dairy Co in Auckland, New Zealand, sells 30% of all milk bought in its local area. What does this figure measure about the business?","options":{"A":"Its legal structure and ownership","B":"Its market share, a measure of size relative to competitors","C":"Its added value per litre of milk sold","D":"Its total number of employees only"},"correctOption":"B","correctAnswer":"Its market share, a measure of size relative to competitors","questionType":"MCQ","explanation":{"correct_reason":"Thirty percent of local milk sales is the firm's market share, which compares its size with rival sellers. Auckland Dairy Co can use that figure to judge its competitive position in the area.","distractor_reasons":{"A":"A percentage of sales says nothing about whether the firm is a company, partnership or sole trader. Legal structure requires ownership information, not a share of milk purchases.","B":"Thirty percent of local milk sales is the firm's market share, which compares its size with rival sellers. Auckland Dairy Co can use that figure to judge its competitive position in the area.","C":"Added value would need the price of milk and the cost of bought-in inputs. A thirty percent sales share provides no information about the margin on each litre.","D":"Market share is not a headcount. Auckland Dairy Co could have the same share with very different numbers of workers, so the figure cannot measure employment alone."}}},{"id":"P1_U1_MCQ_1564","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1564","question":"Gaborone Bakeries in Gaborone, Botswana, needs $500,000 to expand and is considering changing from a sole tradership into a limited company. Which advantage of a company supports this decision?","options":{"A":"Owners would gain unlimited liability for the new debts","B":"The business would no longer need to publish any accounts","C":"It could raise capital by issuing shares to investors","D":"The firm would be freed from all tax obligations"},"correctOption":"C","correctAnswer":"It could raise capital by issuing shares to investors","questionType":"MCQ","explanation":{"correct_reason":"A limited company can issue shares to investors, allowing Gaborone Bakeries to raise the $500,000 needed for expansion. Access to share capital is a major advantage over a sole trader or partnership.","distractor_reasons":{"A":"A limited company gives its owners limited liability, not unlimited liability. The change would protect personal assets rather than expose them to business debts.","B":"Companies normally have greater disclosure duties, not fewer. The suggestion that no accounts need be published is contrary to the obligations of incorporated businesses.","C":"A limited company can issue shares to investors, allowing Gaborone Bakeries to raise the $500,000 needed for expansion. Access to share capital is a major advantage over a sole trader or partnership.","D":"No business form removes every tax obligation. A company still pays relevant taxes on its profits, so complete freedom from tax is not an advantage of incorporation."}}},{"id":"P1_U1_MCQ_1565","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1565","question":"Christchurch Eco Tours in Christchurch, New Zealand, has an annual budget of $800,000 and spends $48,000 on local conservation projects. What percentage of its budget goes to conservation?","options":{"A":"4%","B":"5%","C":"8%","D":"6%"},"correctOption":"D","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"The $48,000 conservation spending is six percent of the $800,000 annual budget. Christchurch Eco Tours therefore devotes a small but measurable share of its resources to its environmental objective.","distractor_reasons":{"A":"Four percent of $800,000 is $32,000, less than the $48,000 actually spent. The calculation must use the full conservation figure given in the scenario.","B":"Five percent of $800,000 is $40,000, which understates the $48,000 committed to conservation. The correct percentage is a little higher than five.","C":"Eight percent of $800,000 would be $64,000, more than the reported spending. Since only $48,000 was allocated, the share of the budget is smaller.","D":"The $48,000 conservation spending is six percent of the $800,000 annual budget. Christchurch Eco Tours therefore devotes a small but measurable share of its resources to its environmental objective."}}},{"id":"P1_U1_MCQ_1566","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1566","question":"Guayaquil Electronics in Guayaquil, Ecuador, asks each worker to repeat one tiny assembly task all day. Boredom has risen and mistakes are more common. Which disadvantage of division of labour is shown?","options":{"A":"Higher output made possible by specialisation","B":"Boredom and reduced quality from repetitive work","C":"Lower training costs across the whole workforce","D":"The complete elimination of wasted materials"},"correctOption":"B","correctAnswer":"Boredom and reduced quality from repetitive work","questionType":"MCQ","explanation":{"correct_reason":"Repeating one small task at Guayaquil Electronics causes boredom and more mistakes. These are the classic human drawbacks of excessive division of labour, even though specialisation can raise output.","distractor_reasons":{"A":"Higher output may be a benefit of specialisation, but the scenario reports boredom and errors. The question asks for a disadvantage, so this positive outcome is not relevant.","B":"Repeating one small task at Guayaquil Electronics causes boredom and more mistakes. These are the classic human drawbacks of excessive division of labour, even though specialisation can raise output.","C":"Training costs are not discussed, and repetitive tasks may still need careful instruction. The stated problem is worker dissatisfaction and mistakes, not cheaper training.","D":"Nothing in the case suggests that all material waste has disappeared. The reported rise in mistakes points in the opposite direction, so eliminating waste is not the disadvantage shown."}}},{"id":"P1_U1_MCQ_1567","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1567","question":"Riga Public Transport in Riga, Latvia, is owned by the municipality and runs buses for local residents. Which description of this business and its sector is correct?","options":{"A":"A primary sector business extracting local resources","B":"A private sector company owned by shareholders","C":"A public sector organisation providing a service","D":"A quaternary research laboratory analysing transport data"},"correctOption":"C","correctAnswer":"A public sector organisation providing a service","questionType":"MCQ","explanation":{"correct_reason":"Municipal ownership places Riga Public Transport in the public sector rather than private hands. Running buses for residents is a tertiary service, so it is a public sector service organisation.","distractor_reasons":{"A":"Bus operations do not extract natural resources from the ground. The key fact is municipal ownership, so classifying the service as primary activity is plainly incorrect.","B":"Private sector firms are owned by individuals or investors seeking returns. Riga's buses belong to the municipality, which puts them in the public sector instead.","C":"Municipal ownership places Riga Public Transport in the public sector rather than private hands. Running buses for residents is a tertiary service, so it is a public sector service organisation.","D":"Driving and scheduling buses is not research or knowledge work. The operation is a practical transport service, not a quaternary laboratory analysing data."}}},{"id":"P1_U1_MCQ_1568","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1568","question":"Kumasi Solar Charging in Kumasi, Ghana, was founded after its owner designed pay-as-you-go phone charging kiosks powered by panels for people without reliable electricity. Which entrepreneurial quality is most evident?","options":{"A":"Innovation, creating a new way to meet a customer need","B":"A determination to avoid all financial risk","C":"Exact imitation of an established competitor's product","D":"A refusal to listen to feedback from customers"},"correctOption":"A","correctAnswer":"Innovation, creating a new way to meet a customer need","questionType":"MCQ","explanation":{"correct_reason":"The founder designed a new solar charging service for people without dependable power. Finding an original solution to a real customer problem shows innovation, a central quality of an entrepreneur.","distractor_reasons":{"A":"The founder designed a new solar charging service for people without dependable power. Finding an original solution to a real customer problem shows innovation, a central quality of an entrepreneur.","B":"Entrepreneurs normally accept financial risk, and setting up kiosks requires investment. Avoiding all risk would not explain the creation of a new service in Kumasi.","C":"The kiosks were designed for local conditions rather than copied from a rival. Exact imitation would not show the original thinking displayed by this founder.","D":"Nothing suggests the owner ignored customers. Meeting the need for charging shows responsiveness, which is the opposite of refusing to listen to feedback."}}},{"id":"P1_U1_MCQ_1569","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1569","question":"San Salvador Cement Plc in San Salvador, El Salvador, raised $2 million by issuing 400,000 new shares to fund a new grinding plant. What was the issue price per share?","options":{"A":"$2","B":"$4","C":"$5","D":"$8"},"correctOption":"C","correctAnswer":"$5","questionType":"MCQ","explanation":{"correct_reason":"Dividing the $2 million raised by 400,000 shares gives $5 per share. San Salvador Cement Plc therefore sold each new share to investors at a price of five dollars.","distractor_reasons":{"A":"A price of $2 per share would raise only $800,000 from 400,000 shares. That is well below the $2 million the company actually obtained from the issue.","B":"At $4 per share, 400,000 shares would bring in $1.6 million. Since the firm raised $2 million, the true price must be higher than four dollars.","C":"Dividing the $2 million raised by 400,000 shares gives $5 per share. San Salvador Cement Plc therefore sold each new share to investors at a price of five dollars.","D":"A price of $8 per share would generate $3.2 million from 400,000 shares. This exceeds the reported $2 million, so it cannot be the issue price."}}},{"id":"P1_U1_MCQ_1570","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1570","question":"Aleppo Textile Workshop in Aleppo, Syria, is covering its costs and keeping its workers employed despite a sharp fall in orders. Which business objective is taking priority?","options":{"A":"Profit maximisation above every other consideration","B":"Short-term survival and the protection of jobs","C":"Rapid expansion into several new export markets","D":"Maximising dividend payments to shareholders"},"correctOption":"B","correctAnswer":"Short-term survival and the protection of jobs","questionType":"MCQ","explanation":{"correct_reason":"Covering costs and retaining staff during a fall in orders shows a survival objective. Aleppo Textile Workshop puts continuity and jobs ahead of growth or high profits in difficult conditions.","distractor_reasons":{"A":"Profit maximisation would not be the priority when the firm is merely covering costs. The scenario describes defending the business, not pursuing the highest possible profit.","B":"Covering costs and retaining staff during a fall in orders shows a survival objective. Aleppo Textile Workshop puts continuity and jobs ahead of growth or high profits in difficult conditions.","C":"Expansion into export markets requires confidence and investment that the workshop does not have. Its aim is to stay operating, not to grow rapidly.","D":"With only costs covered, there is little profit to distribute as dividends. The stated focus on keeping workers employed rules out maximising payments to owners."}}},{"id":"P1_U1_MCQ_1571","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1571","question":"Skopje Food Truck in Skopje, North Macedonia, was started by an owner who spotted lunchtime demand, borrowed money and organised suppliers, staff and a route. Which factor of production does the owner's role illustrate?","options":{"A":"Enterprise","B":"Land","C":"Capital alone","D":"Unskilled labour"},"correctOption":"A","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Spotting an opportunity, borrowing funds and coordinating suppliers and staff is the enterprise function. Skopje Food Truck depends on the owner's risk-taking and organising judgement.","distractor_reasons":{"A":"Spotting an opportunity, borrowing funds and coordinating suppliers and staff is the enterprise function. Skopje Food Truck depends on the owner's risk-taking and organising judgement.","B":"Land means natural resources such as the site or raw materials. The owner's contribution is decision-making and organisation, not a natural resource.","C":"Capital is the borrowed money and equipment used by the business. The owner arranges those funds, but the organising and risk-bearing role is enterprise rather than capital itself.","D":"The owner is carrying out skilled coordination, not unskilled manual work. Describing this factor as unskilled labour misses the entrepreneurial judgement involved."}}},{"id":"P1_U1_MCQ_1572","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1572","question":"Helsinki Data Labs in Helsinki, Finland, employs 300 analysts who interpret large datasets for client firms. Which statement best explains the growth of this kind of business?","options":{"A":"Quaternary employment falls as economies become more developed","B":"Data analysts are classified as primary sector workers","C":"The laboratory manufactures the computers it uses","D":"Technological change increases demand for knowledge-based services"},"correctOption":"D","correctAnswer":"Technological change increases demand for knowledge-based services","questionType":"MCQ","explanation":{"correct_reason":"The 300 analysts at Helsinki Data Labs sell specialist knowledge, which is quaternary activity. As technology creates more complex information, demand for such expert interpretation grows.","distractor_reasons":{"A":"Quaternary employment has grown in developed economies rather than fallen. The 300 analysts in Helsinki are evidence of expansion in knowledge-based work.","B":"Interpreting data is not extraction of natural resources. These analysts provide expert services, so they belong in the quaternary sector, not the primary one.","C":"The lab buys computers rather than manufacturing them. Its output is analysis for clients, so it is not a hardware producer in the secondary sector.","D":"The 300 analysts at Helsinki Data Labs sell specialist knowledge, which is quaternary activity. As technology creates more complex information, demand for such expert interpretation grows."}}},{"id":"P1_U1_MCQ_1573","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1573","question":"Lusaka Fabrics in Lusaka, Zambia, saw its annual turnover fall from $2.5 million to $2 million after losing a large retail contract. What was the percentage decrease in turnover?","options":{"A":"15%","B":"20%","C":"25%","D":"30%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Turnover fell by $500,000 from a base of $2.5 million, and $500,000 divided by $2.5 million equals twenty percent. Lusaka Fabrics therefore experienced a one fifth decline in sales revenue.","distractor_reasons":{"A":"Fifteen percent of $2.5 million is $375,000, less than the actual fall. The calculation must use the full $500,000 reduction reported in the scenario.","B":"Turnover fell by $500,000 from a base of $2.5 million, and $500,000 divided by $2.5 million equals twenty percent. Lusaka Fabrics therefore experienced a one fifth decline in sales revenue.","C":"Twenty five percent of $2.5 million is $625,000, which would reduce turnover to $1.875 million. The final figure was $2 million, so this overstates the fall.","D":"Thirty percent of $2.5 million is $750,000, which would leave only $1.75 million of sales. Since turnover was $2 million, the decrease is smaller than thirty percent."}}},{"id":"P1_U1_MCQ_1574","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1574","question":"Pretoria Burger Franchise in Pretoria, South Africa, pays monthly fees to the brand owner and must follow its recipes and store rules. Which disadvantage of franchising does this show?","options":{"A":"Ongoing fees and restrictions on how the outlet is run","B":"Complete freedom to change the brand's entire menu","C":"Unlimited liability imposed on the franchisee by law","D":"No training or support from the franchisor at all"},"correctOption":"A","correctAnswer":"Ongoing fees and restrictions on how the outlet is run","questionType":"MCQ","explanation":{"correct_reason":"The Pretoria franchisee pays regular fees and must obey the brand's recipes and rules, which limits independence and reduces profit. Those are typical drawbacks of joining a franchise.","distractor_reasons":{"A":"The Pretoria franchisee pays regular fees and must obey the brand's recipes and rules, which limits independence and reduces profit. Those are typical drawbacks of joining a franchise.","B":"Franchisees must follow the brand's menu rather than change it freely. The scenario stresses set recipes and store rules, so complete freedom is the opposite of the arrangement.","C":"A franchise agreement does not automatically impose unlimited liability by law. The stated disadvantage is financial fees and operating restrictions, not a special legal liability rule.","D":"Franchisors normally provide training and support as part of the deal. The Pretoria case mentions fees and rules, not an absence of help, so this is not the disadvantage shown."}}},{"id":"P1_U1_MCQ_1575","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1575","question":"Casablanca Soft Drinks in Casablanca, Morocco, aims to raise its share of the local market from 12% to 18% within two years. Which type of business objective is this?","options":{"A":"Survival through reducing every cost","B":"Ethical sourcing of ingredients from local farms","C":"A market share growth target","D":"Maximising short-term dividends for owners"},"correctOption":"C","correctAnswer":"A market share growth target","questionType":"MCQ","explanation":{"correct_reason":"Moving from twelve to eighteen percent of the market over two years is a clear share-building goal. Casablanca Soft Drinks has set a growth objective focused on its competitive position.","distractor_reasons":{"A":"No cost reduction is described, and a larger market share usually requires spending on marketing. Survival through cutting costs is a different and narrower aim.","B":"The objective concerns percentage of sales, not where ingredients come from. Ethical sourcing would involve suppliers and farming standards, which are absent from the scenario.","C":"Moving from twelve to eighteen percent of the market over two years is a clear share-building goal. Casablanca Soft Drinks has set a growth objective focused on its competitive position.","D":"Dividend payments to owners are not mentioned. The target is measured by market share, so it is about competitive growth rather than short-term returns to shareholders."}}},{"id":"P1_U1_MCQ_1576","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1576","question":"Siem Reap Craft Stall in Siem Reap, Cambodia, buys carved wooden blocks for $8 and sells each souvenir for $20. Which change would most directly increase the value added per souvenir?","options":{"A":"Paying a higher price for the carved blocks","B":"Reducing the number of souvenirs sold each week","C":"Lowering the selling price to attract more buyers","D":"Improving carving and packaging so it sells for $24 with the $8 cost unchanged"},"correctOption":"D","correctAnswer":"Improving carving and packaging so it sells for $24 with the $8 cost unchanged","questionType":"MCQ","explanation":{"correct_reason":"With bought-in cost fixed at $8, raising the price from $20 to $24 increases added value from $12 to $16 per souvenir. Improving the product is the most direct way to create more value per item.","distractor_reasons":{"A":"Paying more for the carved blocks raises costs and would shrink the gap between cost and price. Added value would fall, not rise, if the input became more expensive.","B":"Selling fewer units does not change the added value earned on each souvenir. It may reduce total profit, but it cannot increase the per-item margin.","C":"Cutting the selling price to $20 or below reduces the margin over the $8 cost. A lower price narrows added value rather than expanding it.","D":"With bought-in cost fixed at $8, raising the price from $20 to $24 increases added value from $12 to $16 per souvenir. Improving the product is the most direct way to create more value per item."}}},{"id":"P1_U1_MCQ_1577","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1577","question":"In Santiago, Chile, total regional output was $800 million last year, of which $200 million came from agriculture. What percentage of output came from the primary sector?","options":{"A":"20%","B":"25%","C":"30%","D":"40%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Primary output of $200 million out of total regional output of $800 million equals twenty five percent. Agriculture therefore contributed one quarter of Santiago's measured output.","distractor_reasons":{"A":"Twenty percent of $800 million is $160 million, which is less than the $200 million of agricultural output. The actual share must be larger than twenty percent.","B":"Primary output of $200 million out of total regional output of $800 million equals twenty five percent. Agriculture therefore contributed one quarter of Santiago's measured output.","C":"Thirty percent of $800 million would be $240 million, exceeding the reported $200 million. The primary contribution is therefore smaller than thirty percent.","D":"Forty percent of $800 million is $320 million, far above the agricultural figure given. This option greatly overstates the primary sector's share of regional output."}}},{"id":"P1_U1_MCQ_1578","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1578","question":"Tegucigalpa Roastery in Tegucigalpa, Honduras, joined with a rival coffee producer to double its roasting capacity and share distribution. Which method of growth has the business used?","options":{"A":"Organic growth funded entirely from retained earnings","B":"Franchising the brand to local shopkeepers","C":"A merger with another business","D":"A state take-over of both companies"},"correctOption":"C","correctAnswer":"A merger with another business","questionType":"MCQ","explanation":{"correct_reason":"Combining with a rival coffee firm to increase roasting capacity is a merger. Tegucigalpa Roastery grew by joining with another business rather than expanding its own operations gradually.","distractor_reasons":{"A":"Organic growth means using internal resources to expand alone. Here the firm joined a rival, so the increase in capacity came from combining businesses, not retained earnings.","B":"Franchising would involve independent operators paying to use the brand. The scenario describes two producers joining forces, not shopkeepers buying rights to trade.","C":"Combining with a rival coffee firm to increase roasting capacity is a merger. Tegucigalpa Roastery grew by joining with another business rather than expanding its own operations gradually.","D":"A state take-over would transfer ownership to government. Nothing in the case mentions public authorities, so this is not what happened in Tegucigalpa."}}},{"id":"P1_U1_MCQ_1579","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1579","question":"Dar es Salaam Fishermen's Co-operative in Dar es Salaam, Tanzania, is owned by boat crews. Each member has one vote and the proceeds from the catch are shared among members. Which structure is this?","options":{"A":"A public limited company with outside shareholders","B":"A sole trader with unlimited liability","C":"A partnership of exactly three owners","D":"A co-operative owned and controlled by its members"},"correctOption":"D","correctAnswer":"A co-operative owned and controlled by its members","questionType":"MCQ","explanation":{"correct_reason":"Boat crews jointly own the organisation, vote equally and share the proceeds, which defines a co-operative. Dar es Salaam Fishermen's Co-operative is run for the benefit of its own members.","distractor_reasons":{"A":"A public limited company has outside shareholders whose votes usually reflect shareholdings. One vote per member regardless of investment is a co-operative principle, not a company one.","B":"A sole trader has a single private owner. The fishermen jointly own the boats and share proceeds, so they form a collective organisation rather than individual businesses.","C":"A partnership normally involves a small number of named partners sharing profit. The crews form a member-based co-operative with equal votes, which is a different structure.","D":"Boat crews jointly own the organisation, vote equally and share the proceeds, which defines a co-operative. Dar es Salaam Fishermen's Co-operative is run for the benefit of its own members."}}},{"id":"P1_U1_MCQ_1580","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1580","question":"Chiang Mai Restaurants in Chiang Mai, Thailand, has introduced stricter food hygiene checks and fairer menu prices after listening to diners. Which stakeholder group's interests are being addressed?","options":{"A":"Customers seeking safe food and good value","B":"Suppliers seeking longer credit terms","C":"Pressure groups seeking higher business taxes","D":"Competitors seeking weaker hygiene rules"},"correctOption":"A","correctAnswer":"Customers seeking safe food and good value","questionType":"MCQ","explanation":{"correct_reason":"Hygiene and fair prices are the concerns of people eating at the restaurants. Chiang Mai Restaurants is responding to its customers, the stakeholder group that buys its meals.","distractor_reasons":{"A":"Hygiene and fair prices are the concerns of people eating at the restaurants. Chiang Mai Restaurants is responding to its customers, the stakeholder group that buys its meals.","B":"Credit terms for suppliers are not mentioned in the scenario. The changes concern the safety and price of meals, which affect diners rather than the firms delivering ingredients.","C":"No campaign about taxation is described, and pressure groups are not the diners whose views were heard. The improvements respond to customer feedback, not to political demands.","D":"Rivals are not asking for weaker rules in the case. Stronger hygiene checks affect the experience of customers, so competitors' preferences are not the driving interest."}}},{"id":"P1_U1_MCQ_1581","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1581","question":"Rabat Textiles in Rabat, Morocco, buys fabric for $14 per dress and sells each finished dress for $35. If it sold 1,200 dresses last season, what total value did the business add?","options":{"A":"$16,800","B":"$19,200","C":"$25,200","D":"$42,000"},"correctOption":"C","correctAnswer":"$25,200","questionType":"MCQ","explanation":{"correct_reason":"Each dress adds $21 of value because Rabat Textiles pays $14 for fabric and sells the finished dress for $35. Across 1,200 dresses the total value added is $25,200.","distractor_reasons":{"A":"The $16,800 figure is the total spent on fabric, found by multiplying 1,200 dresses by $14. That is a bought-in cost, not the value created by the business.","B":"The $19,200 figure assumes a $16 margin per dress. The actual gap between the $35 selling price and the $14 fabric cost is $21, so the total is larger.","C":"Each dress adds $21 of value because Rabat Textiles pays $14 for fabric and sells the finished dress for $35. Across 1,200 dresses the total value added is $25,200.","D":"The $42,000 figure is total sales revenue from 1,200 dresses at $35 each, not value added. The $16,800 cost of fabric must be deducted to find the value created."}}},{"id":"P1_U1_MCQ_1582","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1582","question":"Lodz Furniture in Lodz, Poland, buys timber from forests and converts it into dining chairs sold through shops. Which economic sector does this business belong to?","options":{"A":"The secondary sector","B":"The primary sector","C":"The tertiary sector","D":"The quaternary sector"},"correctOption":"A","correctAnswer":"The secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Turning timber into chairs is manufacturing, which places Lodz Furniture in the secondary sector. The firm buys raw material from suppliers and transforms it into a finished product for customers.","distractor_reasons":{"A":"Turning timber into chairs is manufacturing, which places Lodz Furniture in the secondary sector. The firm buys raw material from suppliers and transforms it into a finished product for customers.","B":"Primary activity extracts natural resources such as trees. Lodz Furniture buys timber from forest owners, so the extraction takes place elsewhere and its own work is manufacturing.","C":"Although shops sell the chairs, the furniture maker creates physical goods rather than providing a service. Its production activity is secondary, not tertiary.","D":"No research or information work is described at the factory. Making chairs from timber is practical manufacturing, which is clearly secondary sector activity."}}},{"id":"P1_U1_MCQ_1583","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1583","question":"Banjul Catering in Banjul, The Gambia, was started by a former hotel employee who wanted to be her own boss and keep more of the income from her work. Which motive for enterprise does this illustrate?","options":{"A":"A wish to avoid responsibility for business decisions","B":"The desire for independence and higher earnings","C":"A legal requirement to register as a company","D":"A guarantee that no rival will enter the market"},"correctOption":"B","correctAnswer":"The desire for independence and higher earnings","questionType":"MCQ","explanation":{"correct_reason":"Wanting to be her own boss and earn more from her work is a classic motive for starting a venture. Banjul Catering reflects the founder's search for independence rather than any outside obligation.","distractor_reasons":{"A":"Running a catering business increases responsibility rather than avoiding it. The founder makes decisions about menus and prices, so escaping responsibility cannot be her motive.","B":"Wanting to be her own boss and earn more from her work is a classic motive for starting a venture. Banjul Catering reflects the founder's search for independence rather than any outside obligation.","C":"No law required her to set up a firm. She chose to leave employment and work for herself, which is a personal motivation, not a legal compulsion.","D":"Starting a business offers no guarantee against competitors. Other caterers can enter the Banjul market, so a promise of no rivalry is neither realistic nor supported."}}},{"id":"P1_U1_MCQ_1584","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1584","question":"Valparaiso Port Authority in Valparaiso, Chile, is state owned and operates berths and cranes for local exporters, reinvesting fees in maintenance rather than paying private dividends. Which organisation is this?","options":{"A":"A public limited company seeking shareholder dividends","B":"A private limited company owned by a few families","C":"A franchise operating under a foreign brand","D":"A public corporation providing a public service"},"correctOption":"D","correctAnswer":"A public corporation providing a public service","questionType":"MCQ","explanation":{"correct_reason":"State ownership, port services for exporters and reinvestment instead of private dividends identify a public corporation. Valparaiso Port Authority exists to run public infrastructure rather than maximise returns to shareholders.","distractor_reasons":{"A":"A public limited company has private shareholders expecting dividends. The port authority is state owned and reinvests fees, so that structure is ruled out.","B":"Private limited companies are owned by individuals who seek returns. Valparaiso Port Authority is publicly owned and serves the wider community, not a few families.","C":"A franchise trades under another firm's brand and pays fees to it. The port authority is a state body providing infrastructure, so franchising does not describe it.","D":"State ownership, port services for exporters and reinvestment instead of private dividends identify a public corporation. Valparaiso Port Authority exists to run public infrastructure rather than maximise returns to shareholders."}}},{"id":"P1_U1_MCQ_1585","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1585","question":"Kuala Lumpur Recycling in Kuala Lumpur, Malaysia, made a profit of $600,000 and decided to retain 40% for new equipment. How much profit was left to distribute to shareholders?","options":{"A":"$360,000","B":"$240,000","C":"$400,000","D":"$540,000"},"correctOption":"A","correctAnswer":"$360,000","questionType":"MCQ","explanation":{"correct_reason":"Retaining forty percent of the $600,000 profit leaves sixty percent for shareholders, and sixty percent of $600,000 is $360,000. Kuala Lumpur Recycling therefore distributes that amount in dividends.","distractor_reasons":{"A":"Retaining forty percent of the $600,000 profit leaves sixty percent for shareholders, and sixty percent of $600,000 is $360,000. Kuala Lumpur Recycling therefore distributes that amount in dividends.","B":"The $240,000 figure is the forty percent kept for equipment, not the amount distributed. The question asks for what remains after that retention.","C":"The $400,000 figure is roughly two thirds of the profit, but the board retains forty percent. Only sixty percent of $600,000 is available for shareholders.","D":"The $540,000 figure would leave just ten percent retained, not the stated forty percent. The calculation must respect the retention decision in the scenario."}}},{"id":"P1_U1_MCQ_1586","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1586","question":"Wellington Crane Operators in Wellington, New Zealand, sells the skilled work of its drivers to construction firms. Which factor of production does the business mainly contribute through those workers?","options":{"A":"Land","B":"Labour","C":"Enterprise","D":"Capital"},"correctOption":"B","correctAnswer":"Labour","questionType":"MCQ","explanation":{"correct_reason":"The skill and effort of crane drivers are human inputs, which constitute labour. Wellington Crane Operators sells the work of its personnel rather than natural resources or equipment.","distractor_reasons":{"A":"Land refers to natural resources such as minerals or the site itself. The contribution described is the skilled effort of drivers, so it is not a natural resource.","B":"The skill and effort of crane drivers are human inputs, which constitute labour. Wellington Crane Operators sells the work of its personnel rather than natural resources or equipment.","C":"Enterprise is the risk-taking judgement of the owner. Although someone organises the firm, the specifically described contribution of the drivers is their labour.","D":"Capital means the cranes and other equipment. The question asks about what the workers contribute, which is labour, not the machinery they operate."}}},{"id":"P1_U1_MCQ_1587","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1587","question":"Aberdeen Fishing Fleet in Aberdeen, Scotland, landed 40% less catch than a decade ago because stocks are depleted and catch limits are stricter. Which reason for the decline of primary sector activity does this show?","options":{"A":"Growth in service jobs directly depleting fish stocks","B":"Manufacturing firms purchasing all the fishing vessels","C":"Quaternary research replacing the natural fish population","D":"Depletion of natural resources and regulation reducing output"},"correctOption":"D","correctAnswer":"Depletion of natural resources and regulation reducing output","questionType":"MCQ","explanation":{"correct_reason":"Fewer fish and tighter catch limits cut the fleet's landings by forty percent. This shows how resource depletion and government rules can contract primary sector output in Aberdeen.","distractor_reasons":{"A":"Service employment does not itself remove fish from the sea. The reduction comes from depleted stocks and quotas, not from growth in tertiary jobs.","B":"No manufacturer is buying the boats in the scenario. The fleet still exists, but its catch is smaller because of biological and regulatory limits.","C":"Research does not replace a natural fish population. The Aberdeen fleet's problem is a real decline in the resource, not a switch to quaternary activities.","D":"Fewer fish and tighter catch limits cut the fleet's landings by forty percent. This shows how resource depletion and government rules can contract primary sector output in Aberdeen."}}},{"id":"P1_U1_MCQ_1588","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1588","question":"Dakar Cement in Dakar, Senegal, wants to compare its scale with another cement maker by valuing the machinery, buildings and vehicles each firm uses. Which measure of business size is being applied?","options":{"A":"The number of customer complaints received","B":"Market share in the local area only","C":"Capital employed, the value of long-term assets used","D":"The number of shareholders on the register"},"correctOption":"C","correctAnswer":"Capital employed, the value of long-term assets used","questionType":"MCQ","explanation":{"correct_reason":"The value of machinery, buildings and vehicles used in production is capital employed, a recognised measure of business size. Dakar Cement can compare that figure with rival producers.","distractor_reasons":{"A":"Complaint counts measure service quality, not the scale of a firm's operations. Two very different sized cement makers could receive the same number of complaints.","B":"Market share compares sales with rivals, but the scenario values physical assets instead. The measure being applied is capital employed, not a percentage of sales.","C":"The value of machinery, buildings and vehicles used in production is capital employed, a recognised measure of business size. Dakar Cement can compare that figure with rival producers.","D":"A shareholder register does not show how large the business is. Firms of very different asset bases can have similar numbers of owners, so it is not the measure described."}}},{"id":"P1_U1_MCQ_1589","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1589","question":"Espoo Robotics Plc in Espoo, Finland, has 250,000 issued shares and pays a dividend of $0.80 per share. What is the total amount paid to shareholders?","options":{"A":"$160,000","B":"$200,000","C":"$250,000","D":"$320,000"},"correctOption":"B","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Multiplying 250,000 shares by the $0.80 dividend per share gives $200,000 in total payments. Espoo Robotics Plc therefore distributes that sum to its shareholders.","distractor_reasons":{"A":"The $160,000 figure would correspond to a dividend of $0.64 per share, not the $0.80 announced. The calculation must use the given payment per share.","B":"Multiplying 250,000 shares by the $0.80 dividend per share gives $200,000 in total payments. Espoo Robotics Plc therefore distributes that sum to its shareholders.","C":"The $250,000 figure is the number of shares treated as dollars, which is meaningless here. Multiplying 250,000 shares by $0.80 gives the correct total of $200,000.","D":"The $320,000 figure would require a payment of $1.28 on each of the 250,000 shares. That is well above the actual dividend of eighty cents per share."}}},{"id":"P1_U1_MCQ_1590","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1590","question":"Jakarta Battery Works in Jakarta, Indonesia, must install cleaner equipment after new emission limits are introduced, pushing up its costs. Which stakeholder is driving this change?","options":{"A":"Suppliers offering longer credit periods","B":"Customers asking for refunds on old batteries","C":"Shareholders requesting larger dividend payments","D":"Government, whose regulations affect operating costs"},"correctOption":"D","correctAnswer":"Government, whose regulations affect operating costs","questionType":"MCQ","explanation":{"correct_reason":"Emission limits come from government and oblige the factory to spend on cleaner equipment, raising costs. Jakarta Battery Works must respond to government as an external stakeholder.","distractor_reasons":{"A":"Credit terms from suppliers are not mentioned. The higher costs arise from new rules, so the stakeholder setting the requirement is government, not suppliers.","B":"No refund requests from customers are described. The change is required by regulation rather than by buyers unhappy with the product they received.","C":"Shareholders want returns, but they did not introduce emission limits. The pressure to install equipment comes from government rules, not from owners asking for dividends.","D":"Emission limits come from government and oblige the factory to spend on cleaner equipment, raising costs. Jakarta Battery Works must respond to government as an external stakeholder."}}},{"id":"P1_U1_MCQ_1591","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1591","question":"Bujumbura Bean Wash in Bujumbura, Burundi, buys coffee cherries for $3 per kilogram, sells washed beans for $7 and pays workers $2 per kilogram. Which statement about added value is correct?","options":{"A":"Added value equals revenue minus every cost, including wages of $2","B":"Added value is the same as the $3 price paid for raw cherries","C":"Added value is sales revenue minus bought-in materials, before deducting wages","D":"Added value cannot be expressed in money terms at all"},"correctOption":"C","correctAnswer":"Added value is sales revenue minus bought-in materials, before deducting wages","questionType":"MCQ","explanation":{"correct_reason":"Added value compares sales revenue with bought-in materials only: $7 less $3 gives $4 per kilogram. The $2 paid to workers is a cost met out of that added value, not deducted when measuring it.","distractor_reasons":{"A":"Deducting wages as well would measure profit rather than added value. Added value is the margin over bought-in materials, which here is $4 before the $2 wage cost.","B":"The $3 figure is the price of bought-in cherries, an input cost. Added value is what the business creates by washing and selling the beans for $7.","C":"Added value compares sales revenue with bought-in materials only: $7 less $3 gives $4 per kilogram. The $2 paid to workers is a cost met out of that added value, not deducted when measuring it.","D":"Added value is routinely measured in money as selling price less bought-in cost. The figures $7 and $3 show exactly how it can be calculated for Bujumbura Bean Wash."}}},{"id":"P1_U1_MCQ_1592","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1592","question":"Antsirabe Clinic in Antsirabe, Madagascar, employs doctors and nurses who treat patients and offer check-ups for local families. Which economic sector does this healthcare business belong to?","options":{"A":"The tertiary sector","B":"The primary sector","C":"The secondary sector","D":"The quaternary sector"},"correctOption":"A","correctAnswer":"The tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"A clinic provides healthcare services to patients, which places it in the tertiary sector. Treating people is neither extracting raw materials nor manufacturing goods, and research is not its main activity.","distractor_reasons":{"A":"A clinic provides healthcare services to patients, which places it in the tertiary sector. Treating people is neither extracting raw materials nor manufacturing goods, and research is not its main activity.","B":"The primary sector extracts natural resources such as crops or minerals. Medical treatment in Antsirabe is a service delivered to people, not an extraction activity.","C":"Manufacturing converts materials into physical goods. The clinic produces care rather than products, so secondary sector classification does not apply.","D":"Quaternary work is research and specialist information. Although doctors are skilled, the clinic's core activity is treating patients, which is a tertiary service."}}},{"id":"P1_U1_MCQ_1593","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1593","question":"Maseru Garments in Maseru, Lesotho, increased its annual turnover from $4 million to $4.8 million after winning a large export contract. What was the percentage growth in turnover?","options":{"A":"8%","B":"10%","C":"15%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Turnover increased by $800,000 from a base of $4 million, and $800,000 divided by $4 million equals twenty percent. Maseru Garments therefore grew its sales by one fifth.","distractor_reasons":{"A":"Eight percent of $4 million is $320,000, far less than the actual increase of $800,000. The percentage must be calculated from the figures given in the scenario.","B":"Ten percent of $4 million is $400,000, which would give turnover of $4.4 million. Since the final figure was $4.8 million, growth was larger.","C":"Fifteen percent of $4 million is $600,000, producing turnover of $4.6 million. Maseru Garments reached $4.8 million, so this answer is too low.","D":"Turnover increased by $800,000 from a base of $4 million, and $800,000 divided by $4 million equals twenty percent. Maseru Garments therefore grew its sales by one fifth."}}},{"id":"P1_U1_MCQ_1594","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1594","question":"Manzini Architects in Manzini, Eswatini, is run by two architects who share the design work, the client visits and the money needed to rent an office. Which advantage of a partnership does this show?","options":{"A":"One owner makes every decision without consultation","B":"Both partners enjoy limited liability for firm debts","C":"Shared skills, workload and finance between the owners","D":"Shares are traded freely on the stock exchange"},"correctOption":"C","correctAnswer":"Shared skills, workload and finance between the owners","questionType":"MCQ","explanation":{"correct_reason":"Two architects can pool expertise, divide demanding work and contribute capital, which are the chief benefits of a partnership. Manzini Architects is not a company with limited liability.","distractor_reasons":{"A":"Partners consult one another rather than having a single owner decide alone. The scenario describes two architects jointly running the practice, so sole decision making is wrong.","B":"Partners typically face unlimited liability for debts, not limited liability. Manzini Architects has no separate company shield protecting the owners' private assets.","C":"Two architects can pool expertise, divide demanding work and contribute capital, which are the chief benefits of a partnership. Manzini Architects is not a company with limited liability.","D":"Shares traded on a stock exchange are a feature of a public limited company, not a partnership of two architects. No share issue is described in Manzini."}}},{"id":"P1_U1_MCQ_1595","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1595","question":"Braga Linen Works in Braga, Portugal, sets aside 5% of its annual profit to fund staff training, saying that better skills benefit both workers and the firm. Which objective is this?","options":{"A":"Investing in employees as an important stakeholder group","B":"Eliminating all training to increase dividends","C":"Seeking market share by charging the lowest prices","D":"Avoiding any contact with the local community"},"correctOption":"A","correctAnswer":"Investing in employees as an important stakeholder group","questionType":"MCQ","explanation":{"correct_reason":"Spending five percent of profit on training benefits workers and builds useful skills, showing that Braga Linen Works treats employees as an important stakeholder alongside earning profit.","distractor_reasons":{"A":"Spending five percent of profit on training benefits workers and builds useful skills, showing that Braga Linen Works treats employees as an important stakeholder alongside earning profit.","B":"The firm increases training spending rather than eliminating it. Cutting all training would conflict with the stated belief that better skills help both workers and business.","C":"Low prices are not mentioned in the scenario. The objective is measured by a share of profit spent on training, not by the price charged to customers.","D":"The local community is not discussed, and the firm actively consults no one here. The stated aim concerns staff development, so avoiding community contact is unrelated."}}},{"id":"P1_U1_MCQ_1596","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1596","question":"Antalya Tour Guides in Antalya, Turkey, buy transport and entrance tickets and add their local knowledge to offer a day trip that visitors willingly pay for. How does the business add value?","options":{"A":"By extracting natural resources from the surrounding area","B":"By combining bought-in services and knowledge into a valued tour","C":"By manufacturing every souvenir sold to tourists","D":"By avoiding the use of any paid inputs altogether"},"correctOption":"B","correctAnswer":"By combining bought-in services and knowledge into a valued tour","questionType":"MCQ","explanation":{"correct_reason":"Guides buy transport and entry tickets then add local expertise, creating a tour that customers pay for. Combining inputs into a service people value is how Antalya Tour Guides adds value.","distractor_reasons":{"A":"The guides do not extract resources such as minerals or crops. Their value comes from assembling a service using purchased transport and tickets, not from extraction.","B":"Guides buy transport and entry tickets then add local expertise, creating a tour that customers pay for. Combining inputs into a service people value is how Antalya Tour Guides adds value.","C":"Souvenir manufacturing is not described, and the business sells guided trips rather than physical products. Value is created through the tour experience.","D":"Transport and entrance tickets are paid inputs, so the guides cannot avoid costs entirely. Added value arises from using those inputs effectively, not from eliminating them."}}},{"id":"P1_U1_MCQ_1597","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1597","question":"In Gothenburg, Sweden, a manufacturing district employs 40,000 people, of whom 12,000 work in factories. What percentage of the workforce is in the secondary sector?","options":{"A":"30%","B":"25%","C":"40%","D":"12%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Twelve thousand of the 40,000 workers are in manufacturing, and 12,000 divided by 40,000 gives thirty percent. The secondary sector therefore employs three tenths of this district's workforce.","distractor_reasons":{"A":"Twelve thousand of the 40,000 workers are in manufacturing, and 12,000 divided by 40,000 gives thirty percent. The secondary sector therefore employs three tenths of this district's workforce.","B":"Twenty five percent of 40,000 is 10,000 workers, fewer than the 12,000 actually employed in factories. The real share must be a little higher.","C":"Forty percent of 40,000 would be 16,000 factory workers. Since only 12,000 work in manufacturing, this percentage overstates the secondary sector share.","D":"Twelve percent of 40,000 is 4,800 workers, well below the 12,000 counted in factories. This option mistakes the raw count for a percentage of the workforce."}}},{"id":"P1_U1_MCQ_1598","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1598","question":"Salerno Food Group in Salerno, Italy, bought a smaller rival factory and added its output to its own operations. Which method of growth has the business used?","options":{"A":"Internal expansion using retained profit alone","B":"A franchise agreement with local operators","C":"A takeover of another company","D":"A co-operative merger of equal members"},"correctOption":"C","correctAnswer":"A takeover of another company","questionType":"MCQ","explanation":{"correct_reason":"Purchasing a smaller rival factory is a takeover, where one business gains control of another. Salerno Food Group grew by acquiring an existing operation instead of building its own.","distractor_reasons":{"A":"Internal expansion would mean using retained profit to build new capacity. Here the firm bought an existing rival, so buying rather than building caused the growth.","B":"Franchising involves independent operators paying to use a brand. Salerno Food Group acquired a factory outright, so no brand licensing arrangement is involved.","C":"Purchasing a smaller rival factory is a takeover, where one business gains control of another. Salerno Food Group grew by acquiring an existing operation instead of building its own.","D":"A co-operative merger would join member-owned businesses on equal terms. The scenario describes one company purchasing a smaller rival, which is a takeover."}}},{"id":"P1_U1_MCQ_1599","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1599","question":"Riga Retail Plc in Riga, Latvia, is a company whose shares can be bought and sold by members of the public through the stock exchange. Which form of organisation does this describe?","options":{"A":"A private limited company owned only by family members","B":"A public limited company with publicly traded shares","C":"A sole trader with unlimited liability","D":"A partnership that cannot issue shares at all"},"correctOption":"B","correctAnswer":"A public limited company with publicly traded shares","questionType":"MCQ","explanation":{"correct_reason":"A public limited company may offer shares to the general public and have them traded on a stock exchange. Riga Retail Plc's publicly traded shares distinguish it from a private company.","distractor_reasons":{"A":"A private limited company keeps share ownership restricted and does not trade on an exchange. Riga Retail Plc's shares are available to the public, so it is not private.","B":"A public limited company may offer shares to the general public and have them traded on a stock exchange. Riga Retail Plc's publicly traded shares distinguish it from a private company.","C":"A sole trader has one owner and no shares at all. The company described has many shareholders whose holdings are traded, so sole trader status is impossible.","D":"Partnerships do not normally issue shares traded on a stock exchange. The presence of publicly traded shares identifies a public limited company, not a partnership."}}},{"id":"P1_U1_MCQ_1600","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1600","question":"Kisumu Sugar in Kisumu, Kenya, faces a dispute: cane growers want a higher price for their crop, while shareholders want lower costs to protect dividends. Which stakeholder conflict is described?","options":{"A":"Customers versus local schools over donations","B":"Managers versus banks over loan repayments","C":"Employees versus government inspectors over safety","D":"Suppliers seeking higher cane prices versus shareholders seeking lower costs"},"correctOption":"D","correctAnswer":"Suppliers seeking higher cane prices versus shareholders seeking lower costs","questionType":"MCQ","explanation":{"correct_reason":"Cane growers want more for their crop while owners want cheaper inputs to protect profit. The clash at Kisumu Sugar is between suppliers and shareholders over the price paid for cane.","distractor_reasons":{"A":"Local schools and customer donations are not mentioned. The competing claims come from cane suppliers and shareholders, so this pairing is unrelated to the case.","B":"Bank loans and manager decisions are absent from the scenario. The disagreement concerns the price of cane, not the repayment of finance.","C":"Safety inspectors and employees are not the parties described. Although staff exist, the stated conflict is between growers seeking more and owners seeking lower costs.","D":"Cane growers want more for their crop while owners want cheaper inputs to protect profit. The clash at Kisumu Sugar is between suppliers and shareholders over the price paid for cane."}}},{"id":"P1_U1_MCQ_1601","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1601","question":"Tirana Weavers Ltd in Albania buys raw wool for $12 per kilogram and turns it into woven cloth sold to garment makers for $30 per kilogram. Which activity in this chain creates the added value?","options":{"A":"Paying the $12 wool invoice to the supplier","B":"Weaving the $12 wool into cloth worth $30","C":"Transporting finished cloth to the garment maker","D":"Placing advertisements for the cloth in local media"},"correctOption":"B","correctAnswer":"Weaving the $12 wool into cloth worth $30","questionType":"MCQ","explanation":{"correct_reason":"Added value arises when a business transforms inputs into outputs worth more than the inputs cost. At Tirana Weavers, wool bought for $12 per kilogram is woven into cloth sold for $30, so the weaving stage creates the extra $18 of value per kilogram.","distractor_reasons":{"A":"Settling the $12 supplier invoice simply pays a debt for materials already delivered. Payment changes who holds the cash, but it does not combine labour and capital to convert wool into a more valuable cloth product in Albania.","B":"Added value arises when a business transforms inputs into outputs worth more than the inputs cost. At Tirana Weavers, wool bought for $12 per kilogram is woven into cloth sold for $30, so the weaving stage creates the extra $18 of value per kilogram.","C":"Delivering cloth to the garment maker is a distribution service that happens after production. The transformation from $12 wool into $30 cloth has already occurred at the loom, so transport alone does not create that added value.","D":"Advertising may stimulate demand for the cloth, but it does not physically turn $12 of raw wool into material worth $30. The extra value is generated during weaving at the Tirana mill, not in the media campaign."}}},{"id":"P1_U1_MCQ_1602","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1602","question":"In Madagascar, one firm digs clay near Antananarivo, a second fires it into ceramic tiles at Antananarivo Ceramics Ltd, and a shop in the capital sells the tiles to households. Which sequence of economic sectors do these activities illustrate?","options":{"A":"Secondary, primary, tertiary","B":"Tertiary, secondary, primary","C":"Primary, secondary, tertiary","D":"Primary, tertiary, secondary"},"correctOption":"C","correctAnswer":"Primary, secondary, tertiary","questionType":"MCQ","explanation":{"correct_reason":"Digging clay extracts a natural raw material, which is primary production. Firing that clay into tiles is manufacturing, the secondary sector. Selling tiles to households in Antananarivo is a service, so the correct sequence is primary, secondary, tertiary.","distractor_reasons":{"A":"Manufacturing does not come first, because clay is dug from the ground before any factory process. The retailer comes last, so putting secondary before primary reverses the real order of activities in Madagascar.","B":"A shop selling tiles is tertiary, but it is the final stage, not the first. Clay extraction is primary and occurs before firing, so this sequence places the service at the wrong end of the chain.","C":"Digging clay extracts a natural raw material, which is primary production. Firing that clay into tiles is manufacturing, the secondary sector. Selling tiles to households in Antananarivo is a service, so the correct sequence is primary, secondary, tertiary.","D":"The shop's sale is a service and must follow manufacturing, not precede it. Firing clay into ceramic tiles is secondary production, so the order shown puts tertiary and secondary the wrong way round."}}},{"id":"P1_U1_MCQ_1603","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1603","question":"Narantuya notices that foreign buyers want more Mongolian cashmere, borrows $20,000, hires four knitters and registers Erdenet Cashmere Ltd to supply them. Which part of this story best illustrates the role of an entrepreneur?","options":{"A":"Identifying the export opportunity and organising resources to exploit it","B":"Repaying the $20,000 loan after the first order","C":"Knitting garments using the four hired workers","D":"Registering the company name with the authorities"},"correctOption":"A","correctAnswer":"Identifying the export opportunity and organising resources to exploit it","questionType":"MCQ","explanation":{"correct_reason":"An entrepreneur identifies a market opportunity and brings together finance, labour and enterprise to meet it. Narantuya spotted export demand, borrowed $20,000 and organised four knitters, which is the defining entrepreneurial act.","distractor_reasons":{"A":"An entrepreneur identifies a market opportunity and brings together finance, labour and enterprise to meet it. Narantuya spotted export demand, borrowed $20,000 and organised four knitters, which is the defining entrepreneurial act.","B":"Repaying a loan is a financial obligation after trading, not the entrepreneurial function. It shows the business meeting its debts, but the opportunity was identified and organised before any repayment began.","C":"Knitting is the production work carried out by employees once the venture exists. It creates the product, but the entrepreneur's distinctive role is seeing the market gap and combining resources to serve it.","D":"Registration is a legal formality that records the business. It does not itself involve spotting demand or taking the risk, so it illustrates administration rather than the entrepreneurial search for opportunity."}}},{"id":"P1_U1_MCQ_1604","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1604","question":"Reykjavik Fisheries Ltd in Iceland has issued 80,000 ordinary shares with a total share capital of $400,000. The directors declare a dividend of $1.25 per share. What is the total amount paid out to shareholders?","options":{"A":"$50,000","B":"$80,000","C":"$320,000","D":"$100,000"},"correctOption":"D","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Total dividends equal the dividend per share multiplied by the number of shares. Eighty thousand shares at $1.25 each gives 80,000 × 1.25 = $100,000, which is the exact sum paid to Reykjavik Fisheries shareholders.","distractor_reasons":{"A":"Fifty thousand dollars would be the payout at only $0.625 per share on 80,000 shares. The declared dividend is $1.25 per share, so the correct total is twice that figure at $100,000.","B":"Eighty thousand dollars treats each of the 80,000 shares as receiving one dollar. Because the dividend is $1.25 per share, the company actually pays an extra quarter dollar on every share.","C":"Three hundred and twenty thousand dollars is the capital still left after paying $80,000 of dividends, not the dividend itself. The $400,000 share capital is not the amount distributed to owners.","D":"Total dividends equal the dividend per share multiplied by the number of shares. Eighty thousand shares at $1.25 each gives 80,000 × 1.25 = $100,000, which is the exact sum paid to Reykjavik Fisheries shareholders."}}},{"id":"P1_U1_MCQ_1605","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1605","question":"Montevideo Saddlery Ltd in Uruguay has just recorded $90,000 of profit. Its saddle makers ask for a 6% wage rise, while shareholders want the same money paid out as dividends. Which stakeholder conflict is illustrated here?","options":{"A":"Customers versus suppliers","B":"Management versus the government","C":"Local community versus customers","D":"Shareholders seeking dividends versus employees seeking higher wages"},"correctOption":"D","correctAnswer":"Shareholders seeking dividends versus employees seeking higher wages","questionType":"MCQ","explanation":{"correct_reason":"The $90,000 profit can either be distributed to owners as dividends or spent on higher wages for the saddle makers. Employees want a bigger share through pay, while shareholders want it through dividends, so their objectives clash.","distractor_reasons":{"A":"Customers buy saddles and suppliers provide leather, but neither group is making a claim on the $90,000 profit in this scenario. The competing claims come from the owners and the workforce.","B":"Management may decide how to allocate profit, and government collects taxes, but neither is demanding the 6% wage rise. The dispute described is between owners seeking dividends and employees seeking pay.","C":"The local community and customers are not asking for a share of the profit here. The tension arises because the saddle makers want higher wages while shareholders want dividends from the same $90,000.","D":"The $90,000 profit can either be distributed to owners as dividends or spent on higher wages for the saddle makers. Employees want a bigger share through pay, while shareholders want it through dividends, so their objectives clash."}}},{"id":"P1_U1_MCQ_1606","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1606","question":"Kathmandu Tea Estates Ltd in Nepal grows bushes on a hillside plantation, employs 40 pickers and uses drying machines to prepare leaves for export. Which matching of these resources to the factors of production is correct?","options":{"A":"Land = the hillside estate; Labour = the pickers; Capital = the drying machines","B":"Land = the pickers; Labour = the estate; Capital = the export order","C":"Land = the machines; Labour = the estate; Capital = the pickers","D":"Land = the export order; Labour = the machines; Capital = the hillside"},"correctOption":"A","correctAnswer":"Land = the hillside estate; Labour = the pickers; Capital = the drying machines","questionType":"MCQ","explanation":{"correct_reason":"Land covers natural resources and the site of the estate, labour is the effort of the 40 pickers, and capital is the man-made drying machinery. Option A correctly assigns all three inputs used by Kathmandu Tea Estates.","distractor_reasons":{"A":"Land covers natural resources and the site of the estate, labour is the effort of the 40 pickers, and capital is the man-made drying machinery. Option A correctly assigns all three inputs used by Kathmandu Tea Estates.","B":"Pickers provide labour rather than land, and the plantation itself is not labour. An export order is a customer contract, not a factor of production, so this mapping misclassifies the Nepalese resources.","C":"Drying machines are capital equipment, not land, and the hillside estate is land rather than labour. Pickers supply labour, so this option assigns all three categories to the wrong inputs.","D":"An export order is a source of demand, not land, and machines are capital rather than labour. The hillside is natural land, so this arrangement reverses the genuine factors used in Nepal."}}},{"id":"P1_U1_MCQ_1607","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1607","question":"Colombo Spice Mills Ltd in Sri Lanka buys peppercorns from growers, grinds and packages them, then sells jars to supermarkets. Which economic sector does the grinding and packaging stage belong to?","options":{"A":"Primary, because it handles a natural crop","B":"Tertiary, because it sells to supermarkets","C":"Secondary, because it processes the peppercorns into jars","D":"Quaternary, because it uses machinery"},"correctOption":"C","correctAnswer":"Secondary, because it processes the peppercorns into jars","questionType":"MCQ","explanation":{"correct_reason":"Grinding and packaging peppercorns changes a raw agricultural product into a finished consumer good. That transformation is manufacturing, the secondary sector, so Colombo Spice Mills operates in secondary production.","distractor_reasons":{"A":"Although the mill handles a natural crop, it does not extract it from the land. Growing pepper is primary; processing that pepper into jars is the secondary stage carried out in Colombo.","B":"Selling jars to supermarkets is a service, but the stage named in the question is grinding and packaging. The mill's processing activity is secondary, whereas the supermarket's retail function is tertiary.","C":"Grinding and packaging peppercorns changes a raw agricultural product into a finished consumer good. That transformation is manufacturing, the secondary sector, so Colombo Spice Mills operates in secondary production.","D":"Machinery does not place a firm in a separate sector. Using grinding equipment still means physically converting a raw spice into a product, which is secondary production in Sri Lanka."}}},{"id":"P1_U1_MCQ_1608","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1608","question":"Yerevan Brandy Cellars Ltd in Armenia recorded sales of $240,000 last year and $300,000 this year after exporting more bottles. What was the percentage increase in annual sales revenue over the year?","options":{"A":"20%","B":"25%","C":"60%","D":"125%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The rise is $300,000 minus $240,000, which is $60,000. Dividing $60,000 by the original $240,000 gives 0.25, so sales grew by exactly 25% for the Armenian cellar.","distractor_reasons":{"A":"Twenty percent would come from dividing the $60,000 increase by the new sales figure of $300,000. Percentage growth must use the starting $240,000 as the base, giving 25%.","B":"The rise is $300,000 minus $240,000, which is $60,000. Dividing $60,000 by the original $240,000 gives 0.25, so sales grew by exactly 25% for the Armenian cellar.","C":"Sixty thousand dollars is the absolute rise in revenue, not a percentage. To express it as a rate of growth, divide by the original $240,000, which yields 25% rather than 60%.","D":"This year's sales of $300,000 are 125% of last year's $240,000. That figure shows the new level relative to the old, whereas the increase is the extra 25 percentage points above the base."}}},{"id":"P1_U1_MCQ_1609","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1609","question":"Tbilisi Pottery is a one-person workshop in Georgia whose owner keeps all the profits and remains personally responsible for every business debt. Which legal structure does this business have?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Cooperative"},"correctOption":"A","correctAnswer":"Sole trader","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is a single owner who receives all profits and carries unlimited liability for debts. The Tbilisi workshop has one proprietor who keeps every profit and answers personally for liabilities, so sole trading fits.","distractor_reasons":{"A":"A sole trader is a single owner who receives all profits and carries unlimited liability for debts. The Tbilisi workshop has one proprietor who keeps every profit and answers personally for liabilities, so sole trading fits.","B":"A partnership needs at least two owners who agree to share profits and liabilities. This Georgian pottery has a single proprietor, so there is no second partner with whom to share the business.","C":"A public limited company has many shareholders with limited liability and shares traded publicly. The potter instead owns and runs the workshop alone and is fully liable for its debts.","D":"A cooperative is owned and run jointly by members for their mutual benefit, usually with democratic voting. A single owner-operator in Tbilisi does not have the multiple member structure of a cooperative."}}},{"id":"P1_U1_MCQ_1610","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1610","question":"Belgrade Footwear Ltd in Serbia has set a five-year goal of becoming the biggest shoe exporter in the Balkans, even if that means lower profits at first. Which business objective is the firm pursuing?","options":{"A":"Maximising short-term profit","B":"Ensuring immediate survival","C":"Minimising costs only","D":"Growth and market leadership"},"correctOption":"D","correctAnswer":"Growth and market leadership","questionType":"MCQ","explanation":{"correct_reason":"Aiming to become the largest exporter in the Balkans prioritises expansion and market share over immediate earnings. Accepting lower profits at first shows the Serbian firm is pursuing growth and leadership rather than short-term gain.","distractor_reasons":{"A":"Maximising short-term profit would require the company to avoid an expensive expansion drive. Belgrade Footwear explicitly accepts lower initial profits to build export volume, so profit maximisation is not its goal.","B":"Survival means covering costs in a crisis, not deliberately expanding into new markets. The five-year plan to lead Balkan shoe exports is an ambitious growth objective, not a defensive survival measure.","C":"Cutting costs may support competitiveness, but it is not the stated aim here. The objective is to grow exports and become the regional leader, even if costs and reduced profits must be tolerated.","D":"Aiming to become the largest exporter in the Balkans prioritises expansion and market share over immediate earnings. Accepting lower profits at first shows the Serbian firm is pursuing growth and leadership rather than short-term gain."}}},{"id":"P1_U1_MCQ_1611","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1611","question":"Bratislava Automotive Ltd in Slovakia has split car assembly into eight stations, with each worker repeating one task rather than building a whole vehicle. Which benefit is the company most likely seeking from this arrangement?","options":{"A":"Reduced need for any worker training","B":"Greater output through specialisation and practice","C":"Elimination of all machinery costs","D":"Less dependence on component suppliers"},"correctOption":"B","correctAnswer":"Greater output through specialisation and practice","questionType":"MCQ","explanation":{"correct_reason":"Specialisation lets each worker repeat one assembly step, becoming faster and reducing time lost between tasks. Bratislava Automotive's eight stations therefore raise total output through division of labour and practice.","distractor_reasons":{"A":"Workers still need training for their specific station, so training does not disappear. Specialisation may shorten each training period, but the claim that no training is needed is far too strong.","B":"Specialisation lets each worker repeat one assembly step, becoming faster and reducing time lost between tasks. Bratislava Automotive's eight stations therefore raise total output through division of labour and practice.","C":"Splitting tasks among workers does not remove machinery costs; car assembly still uses equipment and robots. The change affects the organisation of labour, not the complete elimination of capital spending.","D":"The firm still depends on suppliers for components regardless of how assembly is divided. Division of labour changes internal work allocation, not the quantity of bought-in parts from outside firms."}}},{"id":"P1_U1_MCQ_1612","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1612","question":"Riga Amber Jewellery Ltd employs 1,000 people in Latvia's amber extraction, 2,000 in jewellery manufacturing and 2,000 in retail. What percentage of these 5,000 workers is employed in the primary sector?","options":{"A":"10%","B":"25%","C":"20%","D":"40%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Amber extraction is the primary sector and employs 1,000 of the 5,000 workers. Dividing 1,000 by 5,000 gives 0.20, so exactly 20% of Riga Amber Jewellery's workforce is in primary production.","distractor_reasons":{"A":"Ten percent would require only 500 workers in extraction. The firm actually employs 1,000 people digging amber, which is one fifth of the 5,000 total, so the share is 20%.","B":"Twenty-five percent is the share represented by 1,250 workers, not the 1,000 employed in extraction. Using 1,000 over the 5,000 total gives 20%, so this option overstates the primary sector.","C":"Amber extraction is the primary sector and employs 1,000 of the 5,000 workers. Dividing 1,000 by 5,000 gives 0.20, so exactly 20% of Riga Amber Jewellery's workforce is in primary production.","D":"Forty percent corresponds to the 2,000 workers in manufacturing, which is the secondary sector. Amber extraction is primary and has only 1,000 workers, or 20% of the workforce."}}},{"id":"P1_U1_MCQ_1613","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1613","question":"Vilnius Linen Ltd in Lithuania wants to compare its size with another textile firm. The owner has data on machine hours, employee numbers, annual sales revenue and the price of linen per metre. Which pair best measures business size?","options":{"A":"Machine hours and price per metre","B":"Employee numbers and price per metre","C":"Number of employees and annual sales revenue","D":"Annual sales revenue and machine hours"},"correctOption":"C","correctAnswer":"Number of employees and annual sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Business size is commonly measured by the number of people employed and by annual turnover. Those two figures show the scale of Vilnius Linen's operations, whereas a unit price or machine hours describe only part of activity.","distractor_reasons":{"A":"Machine hours show how long equipment runs, and the price per metre is a unit value. Neither captures the overall scale of the firm as clearly as workforce size and total sales revenue.","B":"Employee numbers are a valid size measure, but the price of linen per metre is simply a selling price. Pairing it with headcount does not give as complete a picture as sales revenue.","C":"Business size is commonly measured by the number of people employed and by annual turnover. Those two figures show the scale of Vilnius Linen's operations, whereas a unit price or machine hours describe only part of activity.","D":"Sales revenue is a good indicator, yet machine hours reflect only one production input. The standard comparison uses employees together with revenue, which captures both labour and market scale."}}},{"id":"P1_U1_MCQ_1614","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1614","question":"Gdansk Shiprepair Ltd was founded by former dockyard engineers in Poland who each hold a membership share, vote equally on decisions and share the profits. Which form of business organisation is this?","options":{"A":"Sole trader","B":"Cooperative","C":"Public limited company","D":"Partnership"},"correctOption":"B","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and controlled by members who share benefits and usually vote equally. The Gdansk engineers each hold a membership share and vote on decisions, which matches a workers' cooperative.","distractor_reasons":{"A":"A sole trader has one owner, but this Polish ship repair business has many member owners. Equal voting among the engineers is incompatible with a single proprietor controlling the firm.","B":"A cooperative is owned and controlled by members who share benefits and usually vote equally. The Gdansk engineers each hold a membership share and vote on decisions, which matches a workers' cooperative.","C":"A public limited company sells shares to outside investors and voting power normally follows shareholdings. Here every member has an equal vote, which is the cooperative principle rather than a plc structure.","D":"A partnership shares profits among partners, but it does not normally give every employee an equal membership vote. The worker-owned, one-vote arrangement in Gdansk is characteristic of a cooperative."}}},{"id":"P1_U1_MCQ_1615","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1615","question":"Bucharest Textiles Ltd in Romania earned $500,000 before tax. The government wants more corporation tax to fund roads, while shareholders want as much of the profit as possible paid to them. Which stakeholder conflict is shown?","options":{"A":"Employees versus customers","B":"Suppliers versus local community","C":"Managers versus employees","D":"Shareholders versus government over the distribution of profit"},"correctOption":"D","correctAnswer":"Shareholders versus government over the distribution of profit","questionType":"MCQ","explanation":{"correct_reason":"The $500,000 profit can be claimed through taxation by the government or distributed to owners as dividends. Shareholders want a larger payout while the state wants more tax, so these two stakeholders compete over the same profit.","distractor_reasons":{"A":"Employees and customers are not claiming the profit in this account. The dispute is between the tax authority seeking revenue for roads and owners wanting dividends from the Romanian company.","B":"Suppliers provide materials and the local community may benefit from jobs, but neither is demanding a slice of the $500,000. The opposing claims come from government and shareholders.","C":"Managers might implement the policy, and employees might want wages, but the scenario sets the finance minister against shareholders. The clash is therefore about tax versus dividends, not management versus staff.","D":"The $500,000 profit can be claimed through taxation by the government or distributed to owners as dividends. Shareholders want a larger payout while the state wants more tax, so these two stakeholders compete over the same profit."}}},{"id":"P1_U1_MCQ_1616","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1616","question":"Sofia Rose Oil Ltd in Bulgaria sells a litre of rose oil to perfume makers for $900. The petals, solvents and other materials used to make that litre cost $340. What is the value added per litre?","options":{"A":"$560","B":"$340","C":"$900","D":"$1,240"},"correctOption":"A","correctAnswer":"$560","questionType":"MCQ","explanation":{"correct_reason":"Value added equals the selling price minus the cost of materials used. For Sofia Rose Oil, $900 received less $340 of petals and solvents leaves $560 of extra value created per litre in Bulgaria.","distractor_reasons":{"A":"Value added equals the selling price minus the cost of materials used. For Sofia Rose Oil, $900 received less $340 of petals and solvents leaves $560 of extra value created per litre in Bulgaria.","B":"Three hundred and forty dollars is only the cost of the purchased inputs. It is subtracted from the $900 selling price to find added value, so it cannot be the value the firm creates.","C":"Nine hundred dollars is the selling price of a litre, not the value added. It includes the $340 spent on materials, so the firm's own contribution is the remaining $560.","D":"One thousand two hundred and forty dollars is the sum of price and input cost, which has no meaning here. Added value is found by subtracting $340 from $900, not by adding the two figures."}}},{"id":"P1_U1_MCQ_1617","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1617","question":"Athens Marble Ltd is owned by the Greek government and supplies stone for state building projects rather than selling to private customers. In which sector of the economy does this business operate?","options":{"A":"The primary sector only","B":"The public sector","C":"The tertiary sector only","D":"The voluntary sector"},"correctOption":"B","correctAnswer":"The public sector","questionType":"MCQ","explanation":{"correct_reason":"A business owned and controlled by government belongs to the public sector. Athens Marble is state-owned and serves government building projects, so it is a public sector enterprise in Greece.","distractor_reasons":{"A":"Although quarrying marble is primary production, ownership by the Greek state places the firm in the public sector. The question asks about economic sector in terms of who controls the business.","B":"A business owned and controlled by government belongs to the public sector. Athens Marble is state-owned and serves government building projects, so it is a public sector enterprise in Greece.","C":"Supplying stone is not mainly a service activity, and the firm is not privately owned. State ownership is the deciding factor, so the public sector label is correct rather than tertiary.","D":"The voluntary sector consists of charities and non-profit bodies run by volunteers. A government-owned marble company supplying state projects has no such voluntary or charitable character."}}},{"id":"P1_U1_MCQ_1618","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1618","question":"Aveiro Cork Products Ltd in Portugal has used retained profit to open two extra factories and enter a new export market, without buying another company. Which method of growth has it used?","options":{"A":"A takeover of a rival","B":"A merger with a competitor","C":"Organic growth funded from retained profit","D":"A management buyout"},"correctOption":"C","correctAnswer":"Organic growth funded from retained profit","questionType":"MCQ","explanation":{"correct_reason":"Organic growth expands the existing business using its own resources. Porto Cork reinvested retained profit to build two factories and reach a new market, so it grew internally rather than by acquiring another firm.","distractor_reasons":{"A":"A takeover means purchasing control of another company. Porto Cork built its own factories and did not buy a rival, so this is internal expansion rather than a takeover.","B":"A merger combines two separate firms into one. Since no competitor joined Porto Cork and the investment came from retained earnings, the growth is organic, not a merger.","C":"Organic growth expands the existing business using its own resources. Porto Cork reinvested retained profit to build two factories and reach a new market, so it grew internally rather than by acquiring another firm.","D":"A management buyout occurs when managers purchase the company from its owners. Here the company is investing its own profits in new capacity, so no change of ownership is involved."}}},{"id":"P1_U1_MCQ_1619","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1619","question":"Three friends in Marseille run a soap-making business together, split the profits equally and are each personally liable for all of its debts. Which legal structure have they chosen?","options":{"A":"Partnership","B":"Sole trader","C":"Cooperative","D":"Public limited company"},"correctOption":"A","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"A partnership is an association of two or more people who share the profits of a business and carry unlimited liability. The three Marseille friends jointly run the soap firm and are all liable for its debts.","distractor_reasons":{"A":"A partnership is an association of two or more people who share the profits of a business and carry unlimited liability. The three Marseille friends jointly run the soap firm and are all liable for its debts.","B":"A sole trader has just one owner, but three friends share the profits and liabilities here. Multiple owners with joint responsibility make this a partnership rather than sole trading.","C":"A cooperative is owned by members for mutual benefit with democratic control. The scenario emphasises three founders sharing profits and unlimited liability, which is the defining partnership arrangement.","D":"A public limited company offers limited liability to shareholders and can sell shares publicly. The soap makers are personally responsible for all debts, so their firm is not a plc."}}},{"id":"P1_U1_MCQ_1620","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1620","question":"Lyon Silk Printing Ltd in France set a quarterly target of 80,000 metres of printed silk. Actual output reached 68,000 metres. What percentage of its production target did the firm achieve?","options":{"A":"68%","B":"12%","C":"80%","D":"85%"},"correctOption":"D","correctAnswer":"85%","questionType":"MCQ","explanation":{"correct_reason":"Target achievement equals actual output divided by target output. Lyon Silk produced 68,000 of the planned 80,000 metres, and 68,000 ÷ 80,000 = 0.85, so it achieved 85% of target.","distractor_reasons":{"A":"Sixty-eight percent would treat the 68,000 metres as a percentage without dividing by the 80,000 target. Achievement must compare output with the planned figure, giving 85%.","B":"Twelve thousand metres is the shortfall from target, not a percentage, and it equals 15% of 80,000. The achieved share is 68,000 divided by 80,000, which is 85%.","C":"Eighty percent assumes the firm hit 64,000 metres, but actual output was 68,000. Dividing 68,000 by the 80,000 target gives 85%, not 80%.","D":"Target achievement equals actual output divided by target output. Lyon Silk produced 68,000 of the planned 80,000 metres, and 68,000 ÷ 80,000 = 0.85, so it achieved 85% of target."}}},{"id":"P1_U1_MCQ_1621","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1621","question":"Turin Machinery Ltd in Italy uses a factory building, assembly workers, robotic arms and an owner who seeks new orders. Which factor of production is represented by the factory building itself?","options":{"A":"Labour","B":"Capital","C":"Enterprise","D":"Land"},"correctOption":"D","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Land in economics includes natural resources and the physical site on which production occurs. The factory building occupies a site in Turin, so it is classified as land, unlike the robots which are capital equipment.","distractor_reasons":{"A":"Labour is the human effort of the assembly workers, not the structure they work in. A factory building cannot provide labour, so this option confuses the workforce with its workplace.","B":"Capital refers to man-made aids such as robotic arms and tools. Although the building is constructed, the site it occupies is treated as land, while the machinery inside is capital.","C":"Enterprise is the risk-taking and organising role of the owner seeking new orders. A physical factory does not perform that function, so it is not an example of enterprise.","D":"Land in economics includes natural resources and the physical site on which production occurs. The factory building occupies a site in Turin, so it is classified as land, unlike the robots which are capital equipment."}}},{"id":"P1_U1_MCQ_1622","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1622","question":"In Switzerland, a mine extracts silicon, Zurich Instruments Ltd turns it into sensors, and a shop sells the sensors to customers. Which activity is part of the secondary sector?","options":{"A":"Turning silicon into sensors at Zurich Instruments","B":"Extracting silicon from the mine","C":"Selling sensors in the shop","D":"Delivering sensors to customers"},"correctOption":"A","correctAnswer":"Turning silicon into sensors at Zurich Instruments","questionType":"MCQ","explanation":{"correct_reason":"Converting raw silicon into finished sensors is manufacturing, which is secondary production. Zurich Instruments performs that transformation, so its activity belongs to the secondary sector of the Swiss economy.","distractor_reasons":{"A":"Converting raw silicon into finished sensors is manufacturing, which is secondary production. Zurich Instruments performs that transformation, so its activity belongs to the secondary sector of the Swiss economy.","B":"Extracting silicon from a mine obtains a raw material directly from nature. That is primary production, so the mine is not part of the secondary sector.","C":"A shop selling sensors to customers provides a service to consumers. Retailing is tertiary production, so the sale happens after the secondary manufacturing stage.","D":"Delivery is also a service that moves finished goods to buyers. It does not transform the silicon, so it is tertiary rather than secondary production in Switzerland."}}},{"id":"P1_U1_MCQ_1623","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1623","question":"Vienna Coffee Roasters Ltd in Austria has doubled its monthly output from 10,000 to 20,000 bags and found that its average cost per bag has fallen. What does this illustrate?","options":{"A":"Diseconomies of scale","B":"Constant returns to scale","C":"Economies of scale","D":"Diminishing marginal returns"},"correctOption":"C","correctAnswer":"Economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Economies of scale occur when a larger scale of output reduces average costs. Vienna Coffee's rise from 10,000 to 20,000 bags lowered cost per bag, so the firm is benefiting from economies of scale.","distractor_reasons":{"A":"Diseconomies of scale would mean average costs rising as output grows. The Austrian roaster reports the opposite, with costs per bag falling when production doubled, so this is not diseconomy.","B":"Constant returns would leave average cost unchanged as output doubles. Because the cost per bag actually fell after reaching 20,000 bags, the situation is not constant returns.","C":"Economies of scale occur when a larger scale of output reduces average costs. Vienna Coffee's rise from 10,000 to 20,000 bags lowered cost per bag, so the firm is benefiting from economies of scale.","D":"Diminishing marginal returns concern adding variable inputs to a fixed factor in the short run. The data describe average cost falling at a larger scale of production, which is the hallmark of economies of scale."}}},{"id":"P1_U1_MCQ_1624","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1624","question":"Prague Glassworks Ltd in the Czech Republic has 40,000 ordinary shares. The company has decided to distribute $90,000 in total dividends. What dividend will each share receive?","options":{"A":"$2.00","B":"$2.25","C":"$2.50","D":"$4.50"},"correctOption":"B","correctAnswer":"$2.25","questionType":"MCQ","explanation":{"correct_reason":"Dividend per share equals total dividends divided by the number of shares. Prague Glassworks pays $90,000 across 40,000 shares, and 90,000 ÷ 40,000 = 2.25, so each share receives $2.25.","distractor_reasons":{"A":"Two dollars per share would total only $80,000 across 40,000 shares. The declared distribution is $90,000, which is $10,000 more, so the payment per share must be higher.","B":"Dividend per share equals total dividends divided by the number of shares. Prague Glassworks pays $90,000 across 40,000 shares, and 90,000 ÷ 40,000 = 2.25, so each share receives $2.25.","C":"Two dollars and fifty cents per share would require $100,000 in total dividends. The Czech firm is paying $90,000, so dividing by 40,000 gives $2.25 rather than $2.50.","D":"Four dollars and fifty cents is twice the correct amount and would cost $180,000. Dividing the $90,000 payout by 40,000 shares shows each holder receives $2.25."}}},{"id":"P1_U1_MCQ_1625","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1625","question":"Budapest Paprika Mills Ltd in Hungary plans to spend $200,000 of profit on new grinding machinery. Shareholders want that money paid out as dividends instead. Which stakeholder conflict does the plan reveal?","options":{"A":"Owners wanting dividends versus the business reinvesting for growth","B":"Customers wanting lower prices versus suppliers","C":"Government seeking tax versus customers","D":"Employees seeking wages versus the local community"},"correctOption":"A","correctAnswer":"Owners wanting dividends versus the business reinvesting for growth","questionType":"MCQ","explanation":{"correct_reason":"The $200,000 profit can either be reinvested in machinery to support future growth or paid to owners as dividends. Shareholders prefer immediate returns, so their objective conflicts with the firm's reinvestment plans.","distractor_reasons":{"A":"The $200,000 profit can either be reinvested in machinery to support future growth or paid to owners as dividends. Shareholders prefer immediate returns, so their objective conflicts with the firm's reinvestment plans.","B":"Customers and suppliers are not competing for the $200,000 in this case. The disagreement is between owners wanting a payout and the company spending profit on new equipment.","C":"The government is not claiming extra tax in the scenario, and customers are not mentioned as opposing the plan. The real tension is over whether profit goes to shareholders or into machinery.","D":"Employees may benefit from better equipment, but they are not asking for higher wages here. The local community is also uninvolved, so this option misses the owner-versus-reinvestment conflict."}}},{"id":"P1_U1_MCQ_1626","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1626","question":"Zagreb Cooperage Ltd in Croatia buys timber from forests and bends it into oak barrels sold to wineries. Which statement best describes the firm's role in business activity?","options":{"A":"It only provides a service to wineries and creates no product","B":"It extracts raw materials directly from nature","C":"It sells finished goods to final consumers only","D":"It transforms inputs into outputs worth more than the inputs"},"correctOption":"D","correctAnswer":"It transforms inputs into outputs worth more than the inputs","questionType":"MCQ","explanation":{"correct_reason":"Business activity combines factors of production to turn inputs into more valuable outputs. Zagreb Cooperage buys timber and converts it into barrels that wineries value more highly, so it is a transformation activity that creates added value.","distractor_reasons":{"A":"Making barrels is manufacturing, not a pure service. The Croatian firm physically changes timber into a product, so describing it as service-only ignores the transformation that takes place in the workshop.","B":"Extracting timber from forests is the work of the supplier, not of the cooperage. Zagreb Cooperage purchases wood and works on it, so its role is processing rather than extraction of raw materials.","C":"The barrels are sold to wineries, which are business customers, not final consumers. Moreover the statement ignores the production stage, so it fails to describe the firm's real activity in Croatia.","D":"Business activity combines factors of production to turn inputs into more valuable outputs. Zagreb Cooperage buys timber and converts it into barrels that wineries value more highly, so it is a transformation activity that creates added value."}}},{"id":"P1_U1_MCQ_1627","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1627","question":"Near Sarajevo, a forest company plants trees, a sawmill cuts logs into boards, and Sarajevo Furniture Ltd sells finished chairs in a showroom. Which activity belongs to the tertiary sector?","options":{"A":"Planting trees in the forest","B":"Selling chairs in the Sarajevo showroom","C":"Cutting logs into boards at the sawmill","D":"Manufacturing wooden chairs from boards"},"correctOption":"B","correctAnswer":"Selling chairs in the Sarajevo showroom","questionType":"MCQ","explanation":{"correct_reason":"The tertiary sector provides services to customers, and retailing chairs in a showroom is a service. Sarajevo Furniture's shop sells the finished product to buyers, so that selling activity is tertiary production.","distractor_reasons":{"A":"Planting trees produces a natural raw material and is primary production. It occurs at the start of the chain near Sarajevo, not in the service stage that sells chairs to the public.","B":"The tertiary sector provides services to customers, and retailing chairs in a showroom is a service. Sarajevo Furniture's shop sells the finished product to buyers, so that selling activity is tertiary production.","C":"Cutting logs into boards changes a raw material into a semi-finished product. That processing is secondary production, so the sawmill does not provide the tertiary service described.","D":"Manufacturing chairs from boards is also secondary production because it transforms materials into goods. The tertiary activity is the later sale of those chairs in the showroom."}}},{"id":"P1_U1_MCQ_1628","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1628","question":"Skopje Wine Cellars Ltd in North Macedonia produced 50,000 bottles in 2024 and 65,000 bottles in 2025 after adding a second bottling line. What was the percentage increase in output?","options":{"A":"15%","B":"23%","C":"30%","D":"130%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Output rose by 65,000 minus 50,000, which is 15,000 bottles. Dividing 15,000 by the original 50,000 gives 0.30, so the Macedonian cellar increased production by exactly 30%.","distractor_reasons":{"A":"Fifteen percent confuses the 15,000 extra bottles with a percentage. The increase must be divided by the starting output of 50,000 bottles, which gives 30%, not 15%.","B":"Twenty-three percent comes from dividing the 15,000 rise by the new output of 65,000. Percentage growth uses the original 50,000 bottles as the base, producing 30%.","C":"Output rose by 65,000 minus 50,000, which is 15,000 bottles. Dividing 15,000 by the original 50,000 gives 0.30, so the Macedonian cellar increased production by exactly 30%.","D":"This year's 65,000 bottles are 130% of last year's 50,000, but that is the new level relative to the old. The increase itself is the extra 30 percentage points above the base."}}},{"id":"P1_U1_MCQ_1629","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1629","question":"Podgorica Olive Oil Ltd in Montenegro is a private limited company owned by three families. Which statement about the liability of its owners is correct?","options":{"A":"Each owner is fully liable for all company debts","B":"The owners have no responsibility for any unpaid debts","C":"Owners risk only the amount they invested in their shares","D":"All three families share unlimited liability equally"},"correctOption":"C","correctAnswer":"Owners risk only the amount they invested in their shares","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives its shareholders limited liability. The three Montenegrin families risk losing the capital they put into shares, but their personal assets are protected from the company's debts.","distractor_reasons":{"A":"Unlimited liability belongs to sole traders and partnerships, not to a limited company. The three families in Podgorica would not answer personally for every debt of the company.","B":"Limited liability does not mean zero responsibility: shareholders still lose the money invested if the firm fails. The Montenegrin families' share capital is at risk even though personal assets are safe.","C":"A private limited company gives its shareholders limited liability. The three Montenegrin families risk losing the capital they put into shares, but their personal assets are protected from the company's debts.","D":"Sharing liability equally among owners is a feature of a partnership, where each partner is fully liable. A limited company protects the families beyond their share contributions."}}},{"id":"P1_U1_MCQ_1630","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1630","question":"Jijiga Leathercraft Ltd in Ethiopia discharges waste into a nearby river, which lowers its costs but spoils water used by residents. Which stakeholder conflict does this situation reveal?","options":{"A":"Customers versus suppliers","B":"The local community versus the company's owners","C":"Employees versus the government","D":"Managers versus customers"},"correctOption":"B","correctAnswer":"The local community versus the company's owners","questionType":"MCQ","explanation":{"correct_reason":"The owners benefit from lower costs, while residents near the Ethiopian tannery suffer polluted water. These two groups make opposing claims on how the business operates, so the conflict is between the local community and the owners.","distractor_reasons":{"A":"Customers buy leather goods and suppliers provide hides, but neither is affected by the river waste described. The opposing interests are the residents and the owners seeking cheaper production.","B":"The owners benefit from lower costs, while residents near the Ethiopian tannery suffer polluted water. These two groups make opposing claims on how the business operates, so the conflict is between the local community and the owners.","C":"Employees and government are not the groups in conflict here. The pollution harms local residents, while the cost saving benefits the company's owners, so this pair does not match the scenario.","D":"Managers may decide the discharge policy, but customers are not complaining about it. The real clash is between people living near the river and those who gain from lower operating costs."}}},{"id":"P1_U1_MCQ_1631","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1631","question":"Dar es Salaam Dockyards Ltd in Tanzania uses the port site, dock workers, a harbour crane and the manager's plan for new contracts. Which of these inputs is an example of capital?","options":{"A":"The port site beside the harbour","B":"The dock workers loading cargo","C":"The manager's plan for new contracts","D":"The harbour crane used to lift containers"},"correctOption":"D","correctAnswer":"The harbour crane used to lift containers","questionType":"MCQ","explanation":{"correct_reason":"Capital means man-made aids used in production, such as machinery and equipment. The harbour crane is a piece of equipment that helps the Tanzanian dockyard handle cargo, so it is the clearest example of capital here.","distractor_reasons":{"A":"The port site is natural or improved land on which the business operates. It is classified as land, not capital, even though the dockyard's buildings occupy it in Dar es Salaam.","B":"Dock workers supplying their effort are labour. They operate the equipment, but they are not themselves a manufactured aid, so they cannot be counted as capital.","C":"The manager's plan shows organising and risk-taking, which is enterprise. An idea or contract plan is not a physical tool, so it does not fit the definition of capital.","D":"Capital means man-made aids used in production, such as machinery and equipment. The harbour crane is a piece of equipment that helps the Tanzanian dockyard handle cargo, so it is the clearest example of capital here."}}},{"id":"P1_U1_MCQ_1632","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1632","question":"In Zambia, Lusaka Coppercraft Ltd reports 3,000 workers in copper mining, 1,500 in metal manufacturing and 500 in transport services. What percentage of its 5,000 workers is in the primary sector?","options":{"A":"60%","B":"30%","C":"10%","D":"50%"},"correctOption":"A","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"Copper mining extracts a natural resource and is primary production. With 3,000 of the 5,000 workers in mining, 3,000 ÷ 5,000 = 0.60, so 60% of Lusaka Coppercraft's workforce is in the primary sector.","distractor_reasons":{"A":"Copper mining extracts a natural resource and is primary production. With 3,000 of the 5,000 workers in mining, 3,000 ÷ 5,000 = 0.60, so 60% of Lusaka Coppercraft's workforce is in the primary sector.","B":"Thirty percent is the share of the 1,500 workers in metal manufacturing, which is secondary production. Mining is primary and employs 3,000 people, giving 60% of the workforce.","C":"Ten percent corresponds to the 500 transport workers, who provide a tertiary service. The primary sector is copper mining with 3,000 workers, so its share is 60%.","D":"Fifty percent would require 2,500 mining workers, but the company reports 3,000 in extraction. Dividing 3,000 by the 5,000 total gives 60% for the Zambian primary sector."}}},{"id":"P1_U1_MCQ_1633","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1633","question":"Windhoek Karakul Ltd in Namibia exports pelts to 12 countries and employs 150 people. Which pair of indicators best shows the size of the business?","options":{"A":"The number of export countries and the price per pelt","B":"Annual turnover and the number of employees","C":"Brand popularity and the number of delivery vans","D":"The price per pelt and the shareholder dividend"},"correctOption":"B","correctAnswer":"Annual turnover and the number of employees","questionType":"MCQ","explanation":{"correct_reason":"Turnover and workforce are standard measures of business size because they show the scale of activity. Windhoek Karakul's annual sales revenue and its 150 employees indicate how large the Namibian firm really is.","distractor_reasons":{"A":"Exporting to 12 countries shows market reach, and a unit price shows value per pelt, but neither measures total scale. Turnover and headcount give a fuller picture of the business's size.","B":"Turnover and workforce are standard measures of business size because they show the scale of activity. Windhoek Karakul's annual sales revenue and its 150 employees indicate how large the Namibian firm really is.","C":"Brand popularity is hard to measure and delivery vans are only one asset. For the 150-person Namibian exporter, revenue and employees are the more reliable indicators of size.","D":"The price per pelt is a unit value and the dividend is a distribution to owners. Neither reflects the overall scale of operations as well as annual turnover and workforce size."}}},{"id":"P1_U1_MCQ_1634","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1634","question":"Beira Cashew Ltd in Mozambique plans to raise capital by selling shares to thousands of investors through the stock exchange. Which type of business organisation allows this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Cooperative"},"correctOption":"C","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"A public limited company may offer its shares for sale to the general public and often lists on a stock exchange. Beira Cashew's plan to sell shares to many outside investors fits this legal structure exactly.","distractor_reasons":{"A":"A sole trader has one owner who cannot sell shares to outsiders. The Mozambique business wants capital from thousands of investors, which is impossible under sole trading.","B":"A partnership raises finance from its partners rather than by selling shares publicly. Thousands of outside shareholders would not fit the small, personal ownership of a partnership.","C":"A public limited company may offer its shares for sale to the general public and often lists on a stock exchange. Beira Cashew's plan to sell shares to many outside investors fits this legal structure exactly.","D":"A cooperative raises funds through member subscriptions and is controlled by members. It does not normally sell shares freely on a stock exchange to the general public."}}},{"id":"P1_U1_MCQ_1635","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1635","question":"Arusha Honey Ltd in Tanzania pays fair prices to local beekeepers while still aiming to earn enough profit to keep trading. Which combination of objectives does this describe?","options":{"A":"Balancing profit with social responsibility to suppliers","B":"Profit maximisation at any cost to suppliers","C":"Survival only, regardless of supplier interests","D":"Market leadership without regard to profit"},"correctOption":"A","correctAnswer":"Balancing profit with social responsibility to suppliers","questionType":"MCQ","explanation":{"correct_reason":"Paying fair prices to beekeepers shows concern for a stakeholder group, while earning enough profit keeps the firm viable. Arusha Honey is therefore balancing commercial success with social responsibility toward its suppliers.","distractor_reasons":{"A":"Paying fair prices to beekeepers shows concern for a stakeholder group, while earning enough profit keeps the firm viable. Arusha Honey is therefore balancing commercial success with social responsibility toward its suppliers.","B":"Profit maximisation at any cost would mean squeezing the beekeepers' prices, which is the opposite of the fair-payment policy. The firm explicitly tries to support its suppliers.","C":"Survival alone ignores the stated commitment to pay fair prices. Although staying in business matters, the Tanzanian company also has a social objective toward the local beekeepers.","D":"There is no mention of becoming the market leader in the scenario. The aims described are fair dealing with suppliers and sufficient profit, so market leadership is not the objective."}}},{"id":"P1_U1_MCQ_1636","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1636","question":"Mwanza Fish Processing Ltd in Tanzania buys fresh fish for $4 per kilogram and sells frozen fillets for $7 per kilogram. What is the value added per kilogram of fish?","options":{"A":"$4","B":"$7","C":"$11","D":"$3"},"correctOption":"D","correctAnswer":"$3","questionType":"MCQ","explanation":{"correct_reason":"Value added is selling price less the cost of the bought-in input. Mwanza Fish Processing receives $7 and pays $4 for the fish, so processing creates $3 of extra value for every kilogram handled.","distractor_reasons":{"A":"Four dollars is the purchase cost of the raw fish, not the value created. It must be deducted from the $7 selling price to find the extra value generated by the Tanzanian plant.","B":"Seven dollars is the selling price of a kilogram of fillets. It includes the $4 paid for the fish, so the firm's own contribution is only the remaining $3.","C":"Eleven dollars adds the two figures together, which does not measure added value. The correct calculation subtracts the $4 input cost from the $7 selling price, giving $3.","D":"Value added is selling price less the cost of the bought-in input. Mwanza Fish Processing receives $7 and pays $4 for the fish, so processing creates $3 of extra value for every kilogram handled."}}},{"id":"P1_U1_MCQ_1637","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1637","question":"Lilongwe Peanut Ltd in Malawi buys groundnuts from farmers, crushes them into cooking oil and delivers bottles to shops. Which activity is part of the secondary sector?","options":{"A":"Growing groundnuts on the farms","B":"Delivering bottles to the shops","C":"Selling oil to shoppers in stores","D":"Crushing groundnuts into cooking oil"},"correctOption":"D","correctAnswer":"Crushing groundnuts into cooking oil","questionType":"MCQ","explanation":{"correct_reason":"Secondary production processes raw materials into finished goods. Crushing Malawian groundnuts into cooking oil physically transforms the crop, so that stage is the secondary activity carried out by Lilongwe Peanut.","distractor_reasons":{"A":"Growing groundnuts extracts a natural crop from the land, which is primary production. It happens before the factory stage and is done by farmers rather than Lilongwe Peanut.","B":"Delivering bottles to shops moves finished goods to customers and is a service. That distribution stage is tertiary, not the processing stage that changes groundnuts into oil.","C":"Selling oil to shoppers is retailing, which is a tertiary service. It occurs after the peanuts have been crushed, so it is not secondary production in Malawi.","D":"Secondary production processes raw materials into finished goods. Crushing Malawian groundnuts into cooking oil physically transforms the crop, so that stage is the secondary activity carried out by Lilongwe Peanut."}}},{"id":"P1_U1_MCQ_1638","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1638","question":"Blantyre Textiles Ltd in Malawi has bought a smaller rival factory to increase its capacity instead of building new premises. Which method of growth has the firm used?","options":{"A":"External growth through a takeover","B":"Organic growth from retained profit","C":"Growth by franchising its brand","D":"Growth through a cooperative merger of workers"},"correctOption":"A","correctAnswer":"External growth through a takeover","questionType":"MCQ","explanation":{"correct_reason":"External growth occurs when a business expands by acquiring another firm. Blantyre Textiles purchased a rival factory, so it grew by takeover rather than by developing its own existing operations.","distractor_reasons":{"A":"External growth occurs when a business expands by acquiring another firm. Blantyre Textiles purchased a rival factory, so it grew by takeover rather than by developing its own existing operations.","B":"Organic growth means expanding through internal investment, such as building a new plant. The Malawian firm bought an existing rival instead, so its expansion is external.","C":"Franchising lets other traders use a firm's brand and system. Blantyre Textiles acquired a factory outright, so no franchise relationship is involved in this growth method.","D":"A cooperative merger of workers would involve member-owned businesses joining together. Here one company bought a rival factory, which is a straightforward takeover."}}},{"id":"P1_U1_MCQ_1639","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1639","question":"Maseru Woollen Mills Ltd in Lesotho is owned by two people who share the profits and are both fully responsible for the business's debts. Which legal structure does it have?","options":{"A":"Sole trader","B":"Cooperative","C":"Partnership","D":"Public limited company"},"correctOption":"C","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"A partnership is formed when two or more people agree to share profits and carry unlimited liability for debts. The two owners of the Lesotho mill share profits and are fully liable, matching the partnership definition.","distractor_reasons":{"A":"A sole trader has a single owner, whereas two people jointly own the mill. The shared profits and joint liability in Maseru show that more than one proprietor is involved.","B":"A cooperative is run by members for mutual benefit with democratic voting. The scenario stresses two owners sharing profits and unlimited liability, which is a partnership rather than a cooperative.","C":"A partnership is formed when two or more people agree to share profits and carry unlimited liability for debts. The two owners of the Lesotho mill share profits and are fully liable, matching the partnership definition.","D":"A public limited company gives shareholders limited liability and can sell shares publicly. The two owners here are fully responsible for debts, so they do not have the protection of a plc."}}},{"id":"P1_U1_MCQ_1640","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1640","question":"Mbabane Timber Ltd in Eswatini wants to raise annual sales from $250,000 to $300,000 next year after investing in a new sawmill. What percentage increase in sales revenue is required?","options":{"A":"15%","B":"20%","C":"25%","D":"50%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The required rise is $300,000 minus $250,000, which is $50,000. Dividing $50,000 by the starting sales of $250,000 gives 0.20, so the Eswatini firm needs a 20% increase.","distractor_reasons":{"A":"Fifteen percent would be the rise if the increase were $37,500. The actual gap between $300,000 and $250,000 is $50,000, which is 20% of the original sales.","B":"The required rise is $300,000 minus $250,000, which is $50,000. Dividing $50,000 by the starting sales of $250,000 gives 0.20, so the Eswatini firm needs a 20% increase.","C":"Twenty-five percent would require a $62,500 rise from $250,000. The plan only adds $50,000, which is 20% of the original sales figure.","D":"Fifty percent implies a $125,000 rise from $250,000. The plan only adds $50,000, so the needed percentage is 20% rather than 50%."}}},{"id":"P1_U1_MCQ_1641","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1641","question":"Freetown Cocoa Ltd in Sierra Leone ferments, dries and roasts beans worth $2 per kilogram into chocolate drops sold for $8 per kilogram. Which activity creates the added value?","options":{"A":"Processing the beans into chocolate drops","B":"Paying farmers for the delivered beans","C":"Shipping the chocolate to foreign buyers","D":"Advertising the product in newspapers"},"correctOption":"A","correctAnswer":"Processing the beans into chocolate drops","questionType":"MCQ","explanation":{"correct_reason":"Added value is created when inputs are transformed into outputs worth more. Fermenting, drying and roasting $2 beans into $8 chocolate at Freetown Cocoa is that transformation, so processing generates the extra value.","distractor_reasons":{"A":"Added value is created when inputs are transformed into outputs worth more. Fermenting, drying and roasting $2 beans into $8 chocolate at Freetown Cocoa is that transformation, so processing generates the extra value.","B":"Paying farmers settles the cost of the $2 raw beans. It transfers money to suppliers but does not change the beans into a more valuable chocolate product in Sierra Leone.","C":"Shipping moves the finished chocolate to buyers and is a distribution service. The value has already been created by processing before the goods leave the Freetown factory.","D":"Advertising can support sales, but it does not turn $2 of beans into chocolate worth $8. The transformation that adds value takes place during processing at the factory."}}},{"id":"P1_U1_MCQ_1642","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1642","question":"Monrovia Rubber Ltd in Liberia taps latex from rubber trees and ships it to a factory that makes tyres. Which economic sector does the tapping of latex belong to?","options":{"A":"Secondary, because it supplies a factory","B":"Tertiary, because the latex is transported","C":"Public, because the trees are government-owned","D":"Primary, because it extracts a natural resource"},"correctOption":"D","correctAnswer":"Primary, because it extracts a natural resource","questionType":"MCQ","explanation":{"correct_reason":"Primary production obtains natural resources directly from the land. Tapping latex from rubber trees in Liberia extracts a raw material, so the activity carried out by Monrovia Rubber is primary production.","distractor_reasons":{"A":"Supplying a factory does not make the supplier secondary. The factory that turns latex into tyres performs manufacturing, while the Liberian tapping of the trees remains primary extraction.","B":"Transporting latex would be a tertiary service, but the question asks about tapping the trees. Extraction of the raw material is primary, regardless of how the latex is later moved.","C":"Ownership by government would place a business in the public sector, but the question concerns economic sectors of production. Tapping a natural resource is primary whatever the ownership.","D":"Primary production obtains natural resources directly from the land. Tapping latex from rubber trees in Liberia extracts a raw material, so the activity carried out by Monrovia Rubber is primary production."}}},{"id":"P1_U1_MCQ_1643","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1643","question":"Conakry Bauxite Ltd in Guinea wants to compare its size with a rival mining firm. Which pair of indicators is most appropriate for measuring business size?","options":{"A":"Price per tonne and advertising spending","B":"Annual output and number of employees","C":"Number of customers and share price","D":"Brand awareness and dividend per share"},"correctOption":"B","correctAnswer":"Annual output and number of employees","questionType":"MCQ","explanation":{"correct_reason":"Business size is usually judged by how much a firm produces and how many people it employs. Annual output and workforce give a clear comparison between the Guinean miner and its rival.","distractor_reasons":{"A":"Price per tonne is a unit value and advertising is just one cost. Neither shows the scale of Conakry Bauxite's operations as effectively as output volume and employee numbers.","B":"Business size is usually judged by how much a firm produces and how many people it employs. Annual output and workforce give a clear comparison between the Guinean miner and its rival.","C":"Customer numbers and share price can be volatile and reflect market sentiment rather than scale. Output and workforce are more direct indicators of the size of a mining business.","D":"Brand awareness is subjective and dividend per share depends on profit distribution. For comparing two mining firms, production volume and headcount are the practical size measures."}}},{"id":"P1_U1_MCQ_1644","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1644","question":"Bamako Shea Butter Ltd in Mali has 25,000 ordinary shares and declares total dividends of $62,500 after a profitable shea harvest this year. What dividend will each share receive?","options":{"A":"$2.00","B":"$2.25","C":"$2.50","D":"$25.00"},"correctOption":"C","correctAnswer":"$2.50","questionType":"MCQ","explanation":{"correct_reason":"Dividend per share is total dividends divided by the number of shares. Bamako Shea Butter distributes $62,500 over 25,000 shares, and 62,500 ÷ 25,000 = 2.5, so each share earns $2.50.","distractor_reasons":{"A":"Two dollars per share would amount to only $50,000 over 25,000 shares. The Malian company is paying $62,500, so the amount per share is larger than $2.00.","B":"Two dollars and twenty-five cents would total $56,250 across 25,000 shares. Dividing the actual $62,500 payout by 25,000 gives $2.50 for each shareholder.","C":"Dividend per share is total dividends divided by the number of shares. Bamako Shea Butter distributes $62,500 over 25,000 shares, and 62,500 ÷ 25,000 = 2.5, so each share earns $2.50.","D":"Twenty-five dollars per share would cost $625,000, ten times the declared total. Dividing $62,500 by 25,000 shares gives the correct figure of $2.50."}}},{"id":"P1_U1_MCQ_1645","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1645","question":"Bobo Dioulasso Cotton Ltd in Burkina Faso buys cotton from small farmers. The farmers want higher purchase prices, while shareholders want lower costs. Which stakeholder conflict is this?","options":{"A":"Customers versus the government","B":"Employees versus customers","C":"Suppliers versus the company's owners","D":"Managers versus the government"},"correctOption":"C","correctAnswer":"Suppliers versus the company's owners","questionType":"MCQ","explanation":{"correct_reason":"The farmers supply cotton to the Burkina Faso firm and want a higher price, while the owners want cheaper inputs to protect profits. These opposing claims on the same payment create a supplier-versus-owner stakeholder conflict.","distractor_reasons":{"A":"Customers are not asking for a price change in this scenario, and the government is not involved. The disagreement is between the cotton farmers and the shareholders over the purchase price.","B":"Employees are not claiming higher wages here, and customers are not part of the dispute. The opposing groups are the farmers supplying cotton and the owners seeking lower costs.","C":"The farmers supply cotton to the Burkina Faso firm and want a higher price, while the owners want cheaper inputs to protect profits. These opposing claims on the same payment create a supplier-versus-owner stakeholder conflict.","D":"Managers may negotiate the price, but the conflicting objectives belong to the suppliers and owners. The government is not mentioned, so this option does not fit the scenario."}}},{"id":"P1_U1_MCQ_1646","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1646","question":"Niamey Leatherworks Ltd in Niger divides production into cutting, stitching and finishing lines, with each worker staying on one stage. Which benefit is the firm most likely seeking?","options":{"A":"No supervision of workers will ever be needed","B":"Faster output through specialisation and practice","C":"Complete elimination of raw material costs","D":"A guaranteed fall in the price of leather"},"correctOption":"B","correctAnswer":"Faster output through specialisation and practice","questionType":"MCQ","explanation":{"correct_reason":"Division of labour lets workers concentrate on one task and become quicker through repetition. By splitting leatherwork into cutting, stitching and finishing, the Niger firm raises output through specialisation.","distractor_reasons":{"A":"Specialisation does not remove the need for supervision. Workers in Niamey still require coordination and quality checks, so the claim that supervision disappears entirely is unrealistic.","B":"Division of labour lets workers concentrate on one task and become quicker through repetition. By splitting leatherwork into cutting, stitching and finishing, the Niger firm raises output through specialisation.","C":"Changing how work is organised has no effect on the purchase price of leather. Raw material costs remain, so dividing tasks cannot eliminate them from the firm's budget.","D":"The price of leather is set by suppliers and market conditions, not by the internal division of labour. Specialisation affects the speed of production, not the input price."}}},{"id":"P1_U1_MCQ_1647","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1647","question":"Khartoum Gum Arabic Ltd in Sudan collects resin from acacia trees, grinds it into powder and exports the powder to food manufacturers. Which activity is part of the primary sector?","options":{"A":"Grinding the resin into fine powder","B":"Exporting powder to food manufacturers","C":"Selling powdered gum to local shops","D":"Collecting resin from the acacia trees"},"correctOption":"D","correctAnswer":"Collecting resin from the acacia trees","questionType":"MCQ","explanation":{"correct_reason":"Primary production extracts natural resources directly. Collecting resin from acacia trees in Sudan obtains a raw material, so that first stage is the primary activity of Khartoum Gum Arabic.","distractor_reasons":{"A":"Grinding resin into powder changes the raw material into a processed product. That is manufacturing, which belongs to the secondary sector, not primary extraction in Sudan.","B":"Exporting is a service that sends goods to overseas buyers. It is tertiary production, so it cannot be the primary stage of collecting resin from trees.","C":"Selling gum to local shops is retailing, another tertiary service. It occurs after processing and does not involve obtaining the natural resin from acacia trees.","D":"Primary production extracts natural resources directly. Collecting resin from acacia trees in Sudan obtains a raw material, so that first stage is the primary activity of Khartoum Gum Arabic."}}},{"id":"P1_U1_MCQ_1648","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1648","question":"Asmara Jewellery Ltd in Eritrea increased its annual profit from $80,000 to $92,000 after opening a second workshop. What was the percentage rise in profit?","options":{"A":"15%","B":"12%","C":"20%","D":"115%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Profit rose by $92,000 minus $80,000, which is $12,000. Dividing $12,000 by the original $80,000 gives 0.15, so the Eritrean jeweller's profit increased by 15%.","distractor_reasons":{"A":"Profit rose by $92,000 minus $80,000, which is $12,000. Dividing $12,000 by the original $80,000 gives 0.15, so the Eritrean jeweller's profit increased by 15%.","B":"Twelve thousand dollars is the absolute increase, not a percentage. Expressed relative to the starting profit of $80,000, the increase is 15% rather than 12%.","C":"Twenty percent would require a $16,000 rise from $80,000. The actual gain was $12,000, which is 15% of the original profit figure.","D":"This year's $92,000 is 115% of last year's $80,000, but that is the new level relative to the old. The increase itself is the extra 15 percentage points."}}},{"id":"P1_U1_MCQ_1649","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1649","question":"Mogadishu Fish Ltd in Somalia is run by a single entrepreneur who keeps all the profit and is personally liable for every debt. Which legal structure does this business have?","options":{"A":"Partnership","B":"Sole trader","C":"Cooperative","D":"Public limited company"},"correctOption":"B","correctAnswer":"Sole trader","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is one owner who receives all profits and faces unlimited liability. The Somali fish business has a single entrepreneur taking every profit and answering personally for debts, so sole trading applies.","distractor_reasons":{"A":"A partnership requires at least two owners sharing profits and liabilities. There is only one entrepreneur in Mogadishu, so no partnership exists in this case.","B":"A sole trader is one owner who receives all profits and faces unlimited liability. The Somali fish business has a single entrepreneur taking every profit and answering personally for debts, so sole trading applies.","C":"A cooperative is owned and controlled by several members for mutual benefit. A single owner-operator in Somalia does not have the member structure that defines a cooperative.","D":"A public limited company offers limited liability and can sell shares publicly. The entrepreneur is fully liable for all debts, which is the opposite of the protection a plc provides."}}},{"id":"P1_U1_MCQ_1650","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1650","question":"Tripoli Olive Oil Ltd in Libya is focusing on covering its costs and avoiding losses after a difficult year. Which business objective is the firm prioritising?","options":{"A":"Rapid growth","B":"Market leadership","C":"Survival","D":"Profit maximisation"},"correctOption":"C","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"A business aiming simply to cover costs and avoid losses is pursuing survival. After a difficult year, the Libyan olive oil producer is concentrating on staying in operation rather than expanding or maximising profit.","distractor_reasons":{"A":"Rapid growth would involve expanding output or entering new markets. Covering costs after a hard year is a defensive aim, not an ambitious expansion objective in Libya.","B":"Market leadership means becoming the dominant seller, which requires investment and market share gains. The stated priority of avoiding losses is a survival objective, not leadership.","C":"A business aiming simply to cover costs and avoid losses is pursuing survival. After a difficult year, the Libyan olive oil producer is concentrating on staying in operation rather than expanding or maximising profit.","D":"Profit maximisation seeks the largest possible profit, not merely breaking even. The Libyan firm is satisfied with covering costs, so it is not pursuing maximum profit."}}},{"id":"P1_U1_MCQ_1651","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1651","question":"Marrakesh Leather Ltd in Morocco turns imported hides into handbags sold to tourists for $120 each. Which statement correctly identifies the added value created by this business?","options":{"A":"The difference between the $120 selling price and the cost of hides and other inputs","B":"The rent paid on the workshop in Marrakesh","C":"The delivery charge for sending handbags to shops","D":"The amount spent on advertising in tourist magazines"},"correctOption":"A","correctAnswer":"The difference between the $120 selling price and the cost of hides and other inputs","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price of an output minus the cost of the materials and other inputs used to produce it. Marrakesh Leather turns hides into $120 handbags, so the gap between that price and input costs is the added value.","distractor_reasons":{"A":"Added value is the selling price of an output minus the cost of the materials and other inputs used to produce it. Marrakesh Leather turns hides into $120 handbags, so the gap between that price and input costs is the added value.","B":"Rent is a business cost paid for the workshop, not a measure of the value the firm creates. It is deducted when calculating profit and does not describe the transformation of hides into handbags.","C":"Delivery is a distribution service that occurs after the handbags are made. The transport charge is a cost of getting the $120 product to shops, not the value added during production in Morocco.","D":"Advertising spending promotes demand, but it does not turn a hide into a handbag. The extra value comes from the production process, so a marketing budget is not the added value itself."}}},{"id":"P1_U1_MCQ_1652","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1652","question":"Meknes Ceramics Ltd in Morocco employs 600 workers digging clay, 900 making tiles and 1,500 selling them in shops. What percentage of its 3,000 workers is employed in the secondary sector?","options":{"A":"20%","B":"50%","C":"60%","D":"30%"},"correctOption":"D","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Tile manufacture is secondary production and uses 900 of the 3,000 workers. Dividing 900 by 3,000 gives 0.30, so exactly 30% of Meknes Ceramics' workforce is employed in the secondary sector.","distractor_reasons":{"A":"Twenty percent is the share of the 600 clay diggers, who work in the primary sector. Tile making employs 900 workers, which is 30% of the 3,000 total in Morocco.","B":"Fifty percent corresponds to 1,500 shop workers, who provide tertiary services. The secondary sector is tile manufacture with 900 employees, so its share is 30%.","C":"Sixty percent would require 1,800 workers in manufacturing. Meknes Ceramics employs only 900 tile makers out of 3,000, giving 30% rather than 60%.","D":"Tile manufacture is secondary production and uses 900 of the 3,000 workers. Dividing 900 by 3,000 gives 0.30, so exactly 30% of Meknes Ceramics' workforce is employed in the secondary sector."}}},{"id":"P1_U1_MCQ_1653","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1653","question":"Ho Chi Minh City Garments Ltd in Vietnam now sells more shirts and employs more machinists than it did five years ago. Which pair of figures best confirms that the business has grown in size?","options":{"A":"The price of each shirt and the number of designs","B":"The colour of packaging and the number of outlets","C":"The wage paid to machinists and the export price","D":"Annual sales revenue and the number of factory workers"},"correctOption":"D","correctAnswer":"Annual sales revenue and the number of factory workers","questionType":"MCQ","explanation":{"correct_reason":"Turnover and employment are the standard indicators of business size. Higher annual sales revenue and more factory workers directly confirm that Ho Chi Minh City Garments has expanded its Vietnamese operations.","distractor_reasons":{"A":"A shirt price and the count of designs show product range, not scale. The firm could charge more without becoming larger, so these figures do not confirm growth in size.","B":"Packaging colour is irrelevant to size, and outlet count alone is incomplete. Revenue and workforce give a clearer measure of the Vietnamese company's overall scale.","C":"Wages and export prices are unit figures that can rise without any expansion. To confirm growth, the business needs total sales and headcount rather than individual prices.","D":"Turnover and employment are the standard indicators of business size. Higher annual sales revenue and more factory workers directly confirm that Ho Chi Minh City Garments has expanded its Vietnamese operations."}}},{"id":"P1_U1_MCQ_1654","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1654","question":"Da Nang Seafood Ltd in Vietnam is owned by shareholders with limited liability, but its shares are not offered to the public. Which legal structure does this describe?","options":{"A":"Private limited company","B":"Public limited company","C":"Sole trader","D":"Partnership"},"correctOption":"A","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company has shareholders with limited liability but cannot sell shares to the general public. Da Nang Seafood fits this form because owners are protected while shares remain privately held in Vietnam.","distractor_reasons":{"A":"A private limited company has shareholders with limited liability but cannot sell shares to the general public. Da Nang Seafood fits this form because owners are protected while shares remain privately held in Vietnam.","B":"A public limited company may offer shares to the public, which the Vietnamese firm does not do. The absence of a public share offering rules out this legal structure.","C":"A sole trader has one owner with unlimited liability. Da Nang Seafood has several shareholders who enjoy limited liability, so it cannot be a sole trading business.","D":"Partners normally carry unlimited liability for business debts. The shareholders here are protected, so the company is not a partnership despite having several owners."}}},{"id":"P1_U1_MCQ_1655","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1655","question":"Sukhothai Silk Ltd in Thailand buys raw silk from village weavers. The weavers want higher prices, while shareholders want cheaper inputs to protect dividends. Which stakeholder conflict is shown?","options":{"A":"Customers versus the government","B":"Employees versus customers","C":"Suppliers versus the company's owners","D":"Managers versus local residents"},"correctOption":"C","correctAnswer":"Suppliers versus the company's owners","questionType":"MCQ","explanation":{"correct_reason":"The village weavers supply raw silk and want a higher price, whereas owners want lower costs to preserve dividends. Their opposing claims over the same purchase price create a supplier-versus-owner conflict in Thailand.","distractor_reasons":{"A":"Customers are not requesting a price change here, and the government is absent from the scenario. The dispute is between the silk suppliers and the shareholders over input costs.","B":"Employees are not asking for higher wages in this case, and customers are not involved. The clash is between weavers supplying silk and owners seeking cheaper materials.","C":"The village weavers supply raw silk and want a higher price, whereas owners want lower costs to preserve dividends. Their opposing claims over the same purchase price create a supplier-versus-owner conflict in Thailand.","D":"Managers may negotiate the price, but local residents are not making a claim. The conflicting objectives belong to the suppliers and the shareholders, not to managers and residents."}}},{"id":"P1_U1_MCQ_1656","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1656","question":"Bangkok Rice Mills Ltd in Thailand buys paddy rice for $300 per tonne and sells polished rice for $450 per tonne. What is the value added by milling each tonne of rice?","options":{"A":"$300","B":"$150","C":"$450","D":"$750"},"correctOption":"B","correctAnswer":"$150","questionType":"MCQ","explanation":{"correct_reason":"Value added equals the selling price minus the cost of the raw input. Bangkok Rice Mills receives $450 for polished rice and paid $300 for paddy, so milling adds $150 of value per tonne in Thailand.","distractor_reasons":{"A":"Three hundred dollars is the cost of the paddy rice, not the value added. It must be subtracted from the $450 selling price to find the extra value created by milling.","B":"Value added equals the selling price minus the cost of the raw input. Bangkok Rice Mills receives $450 for polished rice and paid $300 for paddy, so milling adds $150 of value per tonne in Thailand.","C":"Four hundred and fifty dollars is the selling price of the polished rice. It includes the $300 spent on paddy, so the mill's own contribution is the remaining $150.","D":"Seven hundred and fifty dollars wrongly adds the price and the input cost together. Added value is found by subtracting $300 from $450, which gives $150."}}},{"id":"P1_U1_MCQ_1657","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1657","question":"Phnom Penh Garments Ltd in Cambodia cuts and sews imported fabric into shirts for export buyers. Which economic sector does this production activity belong to?","options":{"A":"Secondary","B":"Primary","C":"Tertiary","D":"Public"},"correctOption":"A","correctAnswer":"Secondary","questionType":"MCQ","explanation":{"correct_reason":"Cutting and sewing fabric into shirts transforms a material into a finished product. That manufacturing process is secondary production, so the Cambodian factory operates in the secondary sector.","distractor_reasons":{"A":"Cutting and sewing fabric into shirts transforms a material into a finished product. That manufacturing process is secondary production, so the Cambodian factory operates in the secondary sector.","B":"Primary production extracts natural resources, such as growing cotton. The factory buys fabric that has already been made, so its work is manufacturing rather than extraction.","C":"Tertiary activities provide services, such as retailing or transport. Phnom Penh Garments physically produces shirts, so its activity is not a service.","D":"Public sector refers to government ownership, not a stage of production. The question asks about the economic sector of the manufacturing activity, which is secondary."}}},{"id":"P1_U1_MCQ_1658","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1658","question":"Vientiane Coffee Ltd in Laos has opened three new cafes and hired 30 extra staff using profits retained from previous years. Which method of growth is this?","options":{"A":"Growth by takeover of another company","B":"Growth through a merger with a rival","C":"Growth by granting franchises","D":"Organic growth funded from retained profits"},"correctOption":"D","correctAnswer":"Organic growth funded from retained profits","questionType":"MCQ","explanation":{"correct_reason":"Organic growth expands the existing business using its own resources. Vientiane Coffee reinvested retained profits to open three cafes and take on 30 staff, so it grew internally rather than by acquiring a firm.","distractor_reasons":{"A":"A takeover involves buying control of another business. The Lao company opened its own cafes and did not purchase a rival chain, so this is internal expansion.","B":"A merger combines two separate companies into one. No other firm joined Vientiane Coffee, and the funding came from its own profits, so the growth is organic.","C":"Franchising would mean allowing other people to trade under the firm's name. Here the company owns and staffs the new cafes itself, so no franchise arrangement is involved.","D":"Organic growth expands the existing business using its own resources. Vientiane Coffee reinvested retained profits to open three cafes and take on 30 staff, so it grew internally rather than by acquiring a firm."}}},{"id":"P1_U1_MCQ_1659","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1659","question":"Yangon Rice Exports Ltd in Myanmar was founded by four traders who share the profits and are each fully liable for the firm's debts. Which legal structure have they chosen?","options":{"A":"Sole trader","B":"Partnership","C":"Cooperative","D":"Public limited company"},"correctOption":"B","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"A partnership is an association of two or more owners who share profits and carry unlimited liability. Four traders jointly run the Myanmar rice firm and are all fully liable, which matches a partnership exactly.","distractor_reasons":{"A":"A sole trader has one proprietor, but four traders share the profits and debts here. Multiple owners with joint responsibility make this a partnership rather than sole trading.","B":"A partnership is an association of two or more owners who share profits and carry unlimited liability. Four traders jointly run the Myanmar rice firm and are all fully liable, which matches a partnership exactly.","C":"A cooperative is owned by members for mutual benefit with democratic voting. The scenario highlights four founders sharing profits and unlimited liability, which is the defining partnership feature.","D":"A public limited company gives shareholders limited liability and permits public share sales. The four traders are fully responsible for debts, so they do not have a plc's protection."}}},{"id":"P1_U1_MCQ_1660","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1660","question":"Kuala Lumpur Electronics Ltd in Malaysia plans to reduce annual costs from $500,000 to $425,000 by improving its supply chain. What percentage cost reduction is that?","options":{"A":"10%","B":"20%","C":"15%","D":"75%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The saving is $500,000 minus $425,000, which is $75,000. Dividing $75,000 by the original $500,000 gives 0.15, so the Malaysian firm is planning a 15% cut in costs.","distractor_reasons":{"A":"Ten percent of $500,000 is $50,000, which would reduce costs only to $450,000. The plan goes further, bringing spending down by $75,000 to $425,000.","B":"Twenty percent would require a $100,000 reduction from $500,000. The actual saving is $75,000, which is 15% of the starting cost base.","C":"The saving is $500,000 minus $425,000, which is $75,000. Dividing $75,000 by the original $500,000 gives 0.15, so the Malaysian firm is planning a 15% cut in costs.","D":"Seventy-five thousand dollars is the cash saving, not a percentage. Expressed against the original $500,000 cost, the reduction is 15%."}}},{"id":"P1_U1_MCQ_1661","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1661","question":"Penang Batik Ltd in Malaysia uses wax, dyes, skilled painters and a workshop to produce patterned cloth. Which statement about these factors of production is correct?","options":{"A":"The painters are land and the wax is labour","B":"The dyes are labour and the workshop is capital","C":"The painters provide labour while wax and dyes are capital inputs","D":"The workshop is enterprise and the painters are capital"},"correctOption":"C","correctAnswer":"The painters provide labour while wax and dyes are capital inputs","questionType":"MCQ","explanation":{"correct_reason":"Labour is the human effort of the painters, while purchased materials such as wax and dyes are produced inputs classed as capital. Option C correctly matches the Malaysian resources to their factors of production.","distractor_reasons":{"A":"Painters supply human effort, which is labour, not land. Wax is a bought-in material rather than labour, so this option swaps the categories used in the Penang workshop.","B":"Dyes are materials and do not provide labour; the painters do. The workshop may be treated as land, so both parts of this mapping are inaccurate for the Malaysian firm.","C":"Labour is the human effort of the painters, while purchased materials such as wax and dyes are produced inputs classed as capital. Option C correctly matches the Malaysian resources to their factors of production.","D":"Enterprise is the organising role of the owner, not a physical workshop. The painters are labour rather than capital, so this option reverses the genuine factors in Penang."}}},{"id":"P1_U1_MCQ_1662","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1662","question":"Johor Bahru Palm Oil Ltd in Malaysia owns a plantation, a refinery and a chain of supermarkets. Which activity is part of the secondary sector?","options":{"A":"Planting oil palm trees on the plantation","B":"Refining palm fruit into cooking oil","C":"Selling bottles of oil in supermarkets","D":"Delivering bottles to store shelves"},"correctOption":"B","correctAnswer":"Refining palm fruit into cooking oil","questionType":"MCQ","explanation":{"correct_reason":"Secondary production processes raw materials into finished products. Refining palm fruit into cooking oil transforms the crop, so that stage at Johor Bahru Palm Oil is the secondary activity.","distractor_reasons":{"A":"Planting oil palms obtains a natural crop from the land, which is primary production. It takes place on the plantation before any refining occurs in Malaysia.","B":"Secondary production processes raw materials into finished products. Refining palm fruit into cooking oil transforms the crop, so that stage at Johor Bahru Palm Oil is the secondary activity.","C":"Selling bottles in supermarkets is retailing, a service to shoppers. That activity belongs to the tertiary sector and happens after the oil has been refined.","D":"Delivery moves finished goods to stores and is also a tertiary service. It does not convert palm fruit into oil, so it is not the secondary stage."}}},{"id":"P1_U1_MCQ_1663","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1663","question":"Bandung Textiles Ltd in Indonesia doubled output from 20,000 to 40,000 metres of cloth and found its average cost per metre falling. What does this illustrate?","options":{"A":"Diseconomies of scale","B":"Constant returns to scale","C":"Diminishing marginal returns","D":"Economies of scale"},"correctOption":"D","correctAnswer":"Economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Economies of scale arise when increasing production lowers average cost. Bandung Textiles doubled output to 40,000 metres and saw cost per metre fall, so the Indonesian firm is enjoying economies of scale.","distractor_reasons":{"A":"Diseconomies of scale would raise average cost as output expands. Cost per metre fell after reaching 40,000 metres, so the opposite of diseconomy is happening in Indonesia.","B":"Constant returns would leave average cost unchanged when output doubles. Since the cost per metre declined, the business is not experiencing constant returns to scale.","C":"Diminishing marginal returns relate to adding variable inputs to a fixed factor in the short run. Falling average cost at a larger scale points instead to economies of scale.","D":"Economies of scale arise when increasing production lowers average cost. Bandung Textiles doubled output to 40,000 metres and saw cost per metre fall, so the Indonesian firm is enjoying economies of scale."}}},{"id":"P1_U1_MCQ_1664","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1664","question":"Medan Tobacco Ltd in Indonesia has 60,000 ordinary shares and has declared total dividends of $180,000 following a strong harvest. What dividend does each share receive?","options":{"A":"$3.00","B":"$0.30","C":"$30.00","D":"$6.00"},"correctOption":"A","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"Dividend per share is the total distribution divided by the number of shares. Medan Tobacco pays $180,000 across 60,000 shares, and 180,000 ÷ 60,000 = 3, so each share receives $3.00.","distractor_reasons":{"A":"Dividend per share is the total distribution divided by the number of shares. Medan Tobacco pays $180,000 across 60,000 shares, and 180,000 ÷ 60,000 = 3, so each share receives $3.00.","B":"Thirty cents per share would total only $18,000 over 60,000 shares. The Indonesian company is distributing ten times that amount, so the correct payment is $3.00 per share.","C":"Thirty dollars per share would require $1,800,000, ten times the declared dividend. Dividing $180,000 by 60,000 shares gives $3.00 instead.","D":"Six dollars per share would cost $360,000, twice the actual payout. The correct calculation of $180,000 over 60,000 shares gives $3.00 to each shareholder."}}},{"id":"P1_U1_MCQ_1665","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1665","question":"Tagum Fruit Exports Ltd in the Philippines is deciding whether to open a packing plant that would create local jobs but reduce this year's dividends. Which stakeholder conflict is shown?","options":{"A":"Customers versus suppliers","B":"Shareholders seeking dividends versus the local community seeking jobs","C":"Government versus customers","D":"Employees versus suppliers"},"correctOption":"B","correctAnswer":"Shareholders seeking dividends versus the local community seeking jobs","questionType":"MCQ","explanation":{"correct_reason":"The new plant would benefit local residents through employment but reduce the profit available to owners. Shareholders want dividends while the community wants jobs, so these two stakeholder groups have conflicting interests.","distractor_reasons":{"A":"Customers and suppliers are not making competing claims in this decision. The trade-off is between owners who want dividends and residents who want the packing plant's jobs.","B":"The new plant would benefit local residents through employment but reduce the profit available to owners. Shareholders want dividends while the community wants jobs, so these two stakeholder groups have conflicting interests.","C":"The government is not demanding anything in the scenario, and customers are unaffected. The real disagreement is over spending profit on a plant rather than paying owners.","D":"Employees and suppliers are not the opposing groups described. Workers may gain from the plant, but the conflict is between shareholders wanting payouts and the community wanting employment."}}},{"id":"P1_U1_MCQ_1666","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1666","question":"Taipei Semiconductor Ltd in Taiwan uses a clean-room site, engineers, automated machines and an owner who wins new contracts. Which input is classified as land?","options":{"A":"The engineers operating the equipment","B":"The automated production machines","C":"The site and its clean-room building","D":"The owner seeking new contracts"},"correctOption":"C","correctAnswer":"The site and its clean-room building","questionType":"MCQ","explanation":{"correct_reason":"Land includes the natural site and fixed structures used in production. The Taipei site and its clean-room building provide the location for making chips, so they are classified as land rather than capital.","distractor_reasons":{"A":"Engineers supply human effort and skill, which is labour. They work inside the facility but do not represent the land on which the Taiwanese plant stands.","B":"Automated machines are manufactured aids used in production, so they are capital equipment. They operate on the site but are not themselves the land factor.","C":"Land includes the natural site and fixed structures used in production. The Taipei site and its clean-room building provide the location for making chips, so they are classified as land rather than capital.","D":"The owner's contract-winning role is enterprise, involving risk and organisation. A person seeking orders is not the physical site occupied by the semiconductor works."}}},{"id":"P1_U1_MCQ_1667","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1667","question":"Kaohsiung Shipbuilding Ltd in Taiwan buys steel plates, builds cargo vessels and hires a port tug service to move them. Which activity is tertiary production?","options":{"A":"The tug service at the port","B":"Mining the iron ore for steel","C":"Rolling steel into ship plates","D":"Assembling the cargo vessels"},"correctOption":"A","correctAnswer":"The tug service at the port","questionType":"MCQ","explanation":{"correct_reason":"Tertiary production provides services rather than goods. The tug service helps move finished vessels in the Taiwanese port, so it is a service activity and therefore belongs to the tertiary sector.","distractor_reasons":{"A":"Tertiary production provides services rather than goods. The tug service helps move finished vessels in the Taiwanese port, so it is a service activity and therefore belongs to the tertiary sector.","B":"Mining iron ore extracts a natural resource directly from the ground, which is primary production. It does not provide the service described in the Taiwanese shipbuilding chain.","C":"Rolling steel into plates transforms a material into a product, which is secondary manufacturing. It is not a service like the tug operation at the port.","D":"Assembling cargo vessels is also secondary production because it produces a physical good. The tertiary stage is the hired tug service, not the construction work."}}},{"id":"P1_U1_MCQ_1668","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1668","question":"Busan Electronics Ltd in South Korea raised output from 80,000 to 92,000 components a month after adding a night shift. What was the percentage increase in monthly output?","options":{"A":"12%","B":"20%","C":"115%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Output increased by 92,000 minus 80,000, which is 12,000 components. Dividing 12,000 by the original 80,000 gives 0.15, so the Korean factory raised monthly output by 15%.","distractor_reasons":{"A":"Twelve thousand is the absolute rise in components, not a percentage. Divided by the original 80,000 units, the growth rate is 15% rather than 12%.","B":"Twenty percent of 80,000 is 16,000 components, but output rose by only 12,000. The correct percentage increase for the Korean plant is 15%.","C":"This month's 92,000 units are 115% of the previous 80,000, which shows the new level relative to the old. The increase itself is the extra 15 percentage points.","D":"Output increased by 92,000 minus 80,000, which is 12,000 components. Dividing 12,000 by the original 80,000 gives 0.15, so the Korean factory raised monthly output by 15%."}}},{"id":"P1_U1_MCQ_1669","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1669","question":"Kyoto Tea Ltd in Japan is owned and run by its employees, each of whom holds a membership share and has one vote on decisions. Which legal structure is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Cooperative"},"correctOption":"D","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and controlled by members who share benefits and vote equally. The Japanese tea employees hold membership shares and one vote each, so the business is a workers' cooperative.","distractor_reasons":{"A":"A sole trader has a single owner, whereas the Kyoto tea business has many employee members. One-vote membership is incompatible with a single proprietor.","B":"A partnership shares profits among a few partners, but it does not normally give every employee an equal vote. The member-controlled structure in Japan is a cooperative.","C":"A public limited company sells shares to outside investors, with voting power usually tied to shareholdings. Here each employee member has one vote, which is the cooperative principle.","D":"A cooperative is owned and controlled by members who share benefits and vote equally. The Japanese tea employees hold membership shares and one vote each, so the business is a workers' cooperative."}}},{"id":"P1_U1_MCQ_1670","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1670","question":"Nagoya Robotics Ltd in Japan has recorded strong profits. Workers want higher wages, while shareholders want the money paid out as dividends. Which stakeholder conflict arises?","options":{"A":"Employees versus shareholders over the distribution of profit","B":"Customers versus suppliers","C":"Government versus the local community","D":"Managers versus customers"},"correctOption":"A","correctAnswer":"Employees versus shareholders over the distribution of profit","questionType":"MCQ","explanation":{"correct_reason":"The Japanese firm's profit can go to workers as higher wages or to owners as dividends. Employees and shareholders both want a larger share of the same profit, so their objectives conflict.","distractor_reasons":{"A":"The Japanese firm's profit can go to workers as higher wages or to owners as dividends. Employees and shareholders both want a larger share of the same profit, so their objectives conflict.","B":"Customers buy robots and suppliers deliver parts, but neither group is claiming the profit here. The opposing claims come from the workforce and the owners in Japan.","C":"The government is not seeking extra tax in the scenario, and the community is not mentioned. The conflict is between employees wanting pay and shareholders wanting dividends.","D":"Managers may decide the allocation, but customers are not asking for a share of the profit. The real disagreement is between workers and owners over how profit is split."}}},{"id":"P1_U1_MCQ_1671","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1671","question":"Fukuoka Seafood Ltd in Japan splits processing into sorting, filleting and packing stations, with each worker staying at one station. Which benefit is the firm seeking?","options":{"A":"The complete removal of worker training","B":"A guaranteed fall in the price of fish","C":"Higher output through specialisation and practice","D":"A reduction in the number of customers"},"correctOption":"C","correctAnswer":"Higher output through specialisation and practice","questionType":"MCQ","explanation":{"correct_reason":"Division of labour allows workers to focus on one stage and gain speed through repetition. Fukuoka Seafood's three stations therefore increase output as employees become practised at their allocated tasks.","distractor_reasons":{"A":"Workers still require training for their particular station, so training is not removed. Specialisation may shorten learning time, but it cannot eliminate instruction altogether in Japan.","B":"The price of fish is determined by suppliers and market conditions, not by dividing processing tasks. Specialisation affects how quickly fish is handled, not the purchase price.","C":"Division of labour allows workers to focus on one stage and gain speed through repetition. Fukuoka Seafood's three stations therefore increase output as employees become practised at their allocated tasks.","D":"Organising work into stations does not reduce the customer base. If anything, faster processing may help the Japanese firm serve more buyers, not fewer."}}},{"id":"P1_U1_MCQ_1672","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1672","question":"Almaty Grain Ltd in Kazakhstan employs 800 workers in grain farming, 400 in flour milling and 800 in retail. What percentage of its 2,000 workers is in the primary sector?","options":{"A":"20%","B":"40%","C":"60%","D":"80%"},"correctOption":"B","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Grain farming extracts a natural crop and is primary production. With 800 of 2,000 workers on the farms, 800 ÷ 2,000 = 0.40, so 40% of Almaty Grain's workforce is primary.","distractor_reasons":{"A":"Twenty percent is the share of the 400 flour millers, who work in the secondary sector. Farming employs 800 people, which is 40% of the 2,000 workers in Kazakhstan.","B":"Grain farming extracts a natural crop and is primary production. With 800 of 2,000 workers on the farms, 800 ÷ 2,000 = 0.40, so 40% of Almaty Grain's workforce is primary.","C":"Sixty percent would require 1,200 farm workers, but only 800 are recorded in grain farming. Dividing 800 by 2,000 gives 40% for the primary sector.","D":"Eighty percent would mean 1,600 workers in farming. The remaining 1,200 are in milling and retail, so the true primary share is 800 out of 2,000, or 40%."}}},{"id":"P1_U1_MCQ_1673","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1673","question":"Tashkent Cotton Ltd in Uzbekistan has bought a rival spinning mill to expand capacity rather than building its own new factory. Which growth method has it used?","options":{"A":"External growth through a takeover","B":"Organic growth from retained profit","C":"Growth through a workers' cooperative","D":"Growth by franchising its brand"},"correctOption":"A","correctAnswer":"External growth through a takeover","questionType":"MCQ","explanation":{"correct_reason":"External growth happens when a firm expands by acquiring another business. Tashkent Cotton purchased a rival mill, so it increased capacity through a takeover instead of internal investment.","distractor_reasons":{"A":"External growth happens when a firm expands by acquiring another business. Tashkent Cotton purchased a rival mill, so it increased capacity through a takeover instead of internal investment.","B":"Organic growth means expanding existing operations, for example by constructing a new factory. The Uzbek firm bought an established competitor, so its growth is external.","C":"A cooperative is owned by its members, not created by purchasing a rival. The mill was acquired by Tashkent Cotton, so the growth method is a takeover.","D":"Franchising involves granting others the right to use a brand. No such arrangement is described here; the company simply bought another spinning mill."}}},{"id":"P1_U1_MCQ_1674","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1674","question":"Bishkek Wool Ltd in Kyrgyzstan is run by three friends who share the profits and are each personally liable for all of the business's debts. Which legal structure is it?","options":{"A":"Sole trader","B":"Cooperative","C":"Public limited company","D":"Partnership"},"correctOption":"D","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"A partnership is formed by two or more owners who share profits and carry unlimited liability. Three friends jointly run the Kyrgyz wool firm and are personally liable for debts, so it is a partnership.","distractor_reasons":{"A":"A sole trader has one owner, but three friends share the profits and liabilities here. Multiple owners with joint responsibility make this a partnership rather than sole trading.","B":"A cooperative is owned by members with democratic voting and mutual benefit. The scenario stresses three founders sharing profits and full liability, which is the partnership definition.","C":"A public limited company offers shareholders limited liability. The three friends are personally responsible for all debts, so their business cannot be a plc.","D":"A partnership is formed by two or more owners who share profits and carry unlimited liability. Three friends jointly run the Kyrgyz wool firm and are personally liable for debts, so it is a partnership."}}},{"id":"P1_U1_MCQ_1675","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1675","question":"Khujand Aluminium Ltd in Tajikistan aims to become the largest aluminium exporter in Central Asia within a decade, even if profits are modest at first. Which objective is it pursuing?","options":{"A":"Survival only","B":"Growth and market leadership","C":"Profit maximisation alone","D":"Cost minimisation alone"},"correctOption":"B","correctAnswer":"Growth and market leadership","questionType":"MCQ","explanation":{"correct_reason":"Becoming the leading exporter in Central Asia prioritises market share and expansion over immediate earnings. Accepting modest early profits shows the Tajik firm is pursuing growth and leadership.","distractor_reasons":{"A":"Survival means covering costs during a crisis, not planning to dominate regional exports. The ten-year ambition in Dushanbe is a growth objective rather than a defensive one.","B":"Becoming the leading exporter in Central Asia prioritises market share and expansion over immediate earnings. Accepting modest early profits shows the Tajik firm is pursuing growth and leadership.","C":"Profit maximisation would avoid an expensive expansion that depresses early profits. The company accepts modest returns to build market share, so profit maximisation is not its aim.","D":"Cost minimisation is not the stated goal, even though it could help competitiveness. The firm wants to grow into the leading aluminium exporter in its region."}}},{"id":"P1_U1_MCQ_1676","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1676","question":"Amman Pharmaceuticals Ltd in Jordan sells a bottle of medicine for $25. The chemicals, glass bottle and packaging used for that bottle cost $9. What is the value added per bottle?","options":{"A":"$9","B":"$25","C":"$16","D":"$34"},"correctOption":"C","correctAnswer":"$16","questionType":"MCQ","explanation":{"correct_reason":"Value added is the selling price minus the cost of materials used in production. Amman Pharmaceuticals receives $25 for a bottle and spends $9 on chemicals and packaging, so it adds $16 of value per bottle in Jordan.","distractor_reasons":{"A":"Nine dollars is the cost of the chemicals, bottle and packaging, not the value created. Those inputs are subtracted from the $25 price to reveal the $16 added by the Jordanian firm.","B":"Twenty-five dollars is the selling price of the medicine. It includes the $9 spent on materials, so the firm's own contribution is the remaining $16, not the full price.","C":"Value added is the selling price minus the cost of materials used in production. Amman Pharmaceuticals receives $25 for a bottle and spends $9 on chemicals and packaging, so it adds $16 of value per bottle in Jordan.","D":"Thirty-four dollars wrongly adds the price and the input cost. Added value is calculated by subtracting $9 from $25, which leaves $16 for each bottle produced."}}},{"id":"P1_U1_MCQ_1677","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1677","question":"Byblos Publishing Ltd in Lebanon buys paper made from forest pulp, prints books and sells them through bookshops. Which activity is part of the secondary sector?","options":{"A":"Growing trees for wood pulp","B":"Selling books in the bookshops","C":"Printing the books at the press","D":"Delivering books to the shops"},"correctOption":"C","correctAnswer":"Printing the books at the press","questionType":"MCQ","explanation":{"correct_reason":"Printing transforms paper into finished books, which is manufacturing and therefore secondary production. Byblos Publishing's press carries out that conversion, so printing is its secondary-sector activity.","distractor_reasons":{"A":"Growing trees produces a natural raw material and is primary production. It happens at the forest stage before paper is made and books are printed in Lebanon.","B":"Selling books in shops is a service to readers, which belongs to the tertiary sector. It takes place after the books have been printed at the press.","C":"Printing transforms paper into finished books, which is manufacturing and therefore secondary production. Byblos Publishing's press carries out that conversion, so printing is its secondary-sector activity.","D":"Delivering books to shops moves finished goods and is a tertiary service. It does not change paper into books, so it is not the secondary stage."}}},{"id":"P1_U1_MCQ_1678","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1678","question":"Damascus Textiles Ltd in Syria wants evidence that it has grown over five years. Which pair of figures would best demonstrate an increase in the size of the business?","options":{"A":"The price per metre and the number of patterns","B":"The colour of packaging and the number of vans","C":"The wage rate and the selling price per shirt","D":"Annual sales revenue and the number of employees"},"correctOption":"D","correctAnswer":"Annual sales revenue and the number of employees","questionType":"MCQ","explanation":{"correct_reason":"Business size is shown by total turnover and workforce. Rising annual sales revenue and more employees would clearly demonstrate that the Syrian textile firm has expanded its operations over five years.","distractor_reasons":{"A":"A price per metre and a count of patterns reflect product range, not scale. They could rise without the company becoming larger in Syria.","B":"Packaging colour is irrelevant, and vans are only one type of asset. These figures do not show the overall size of the business as well as revenue and headcount.","C":"Wage rates and selling prices are unit measures that can change without expansion. Total sales and employment are the standard indicators of business growth.","D":"Business size is shown by total turnover and workforce. Rising annual sales revenue and more employees would clearly demonstrate that the Syrian textile firm has expanded its operations over five years."}}},{"id":"P1_U1_MCQ_1679","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1679","question":"Riyadh Dates Ltd in Saudi Arabia is owned by one family, whose members have limited liability, but its shares are not sold to the public. Which legal structure is this?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Private limited company"},"correctOption":"D","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives its shareholders limited liability while keeping their shares out of public sale. The family owning Riyadh Dates has protection but no public share offering, so this structure fits.","distractor_reasons":{"A":"A sole trader has one owner with unlimited liability. The family shareholders here are protected, so the business cannot be a sole trading concern.","B":"Partners normally carry unlimited liability for debts. The owners of the Saudi date firm have limited liability, which rules out a partnership.","C":"A public limited company may sell shares to the public. Riyadh Dates does not offer its shares publicly, so it is a private rather than a public company.","D":"A private limited company gives its shareholders limited liability while keeping their shares out of public sale. The family owning Riyadh Dates has protection but no public share offering, so this structure fits."}}},{"id":"P1_U1_MCQ_1680","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1680","question":"Doha Pearl Ltd in Qatar set a target of selling 40,000 pearls this year and actually sold 34,000. What percentage of its sales target did the firm achieve?","options":{"A":"85%","B":"15%","C":"34%","D":"40%"},"correctOption":"A","correctAnswer":"85%","questionType":"MCQ","explanation":{"correct_reason":"Target achievement equals actual sales divided by the target. Doha Pearl sold 34,000 of 40,000 pearls, and 34,000 ÷ 40,000 = 0.85, so the firm reached 85% of its target.","distractor_reasons":{"A":"Target achievement equals actual sales divided by the target. Doha Pearl sold 34,000 of 40,000 pearls, and 34,000 ÷ 40,000 = 0.85, so the firm reached 85% of its target.","B":"Fifteen percent is the shortfall from target, since 6,000 of 40,000 pearls were not sold. The question asks what share was achieved, which is 85%.","C":"Thirty-four thousand is the number of pearls sold, not a percentage. Dividing that figure by the 40,000 target gives the achievement rate of 85%.","D":"Forty thousand is the target itself, expressed as a count of pearls. Achievement must compare actual sales with that target, producing 85% for the Qatari firm."}}},{"id":"P1_U1_MCQ_1681","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1681","question":"Dubai Logistics Ltd in the United Arab Emirates uses a warehouse site, forklift trucks, delivery drivers and an owner who finds clients. Which input is an example of capital?","options":{"A":"The warehouse site in Dubai","B":"The forklift trucks","C":"The delivery drivers","D":"The owner finding clients"},"correctOption":"B","correctAnswer":"The forklift trucks","questionType":"MCQ","explanation":{"correct_reason":"Capital consists of man-made aids used in production, such as vehicles and equipment. The forklift trucks help Dubai Logistics move goods, so they are the clearest example of capital among the inputs listed.","distractor_reasons":{"A":"The warehouse site is the land on which the business operates. It is classified as land rather than capital, even though buildings have been constructed on it in Dubai.","B":"Capital consists of man-made aids used in production, such as vehicles and equipment. The forklift trucks help Dubai Logistics move goods, so they are the clearest example of capital among the inputs listed.","C":"Delivery drivers supply human effort and are therefore labour. They operate the vehicles but are not themselves manufactured equipment, so they are not capital.","D":"The owner who finds clients performs the organising and risk-taking role of enterprise. That function is not a physical aid, so it does not count as capital."}}},{"id":"P1_U1_MCQ_1682","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1682","question":"Muscat Frankincense Ltd in Oman harvests resin from trees, processes it into incense and sells the packets in shops. Which activity belongs to the primary sector?","options":{"A":"Processing resin into incense","B":"Selling packets in the shops","C":"Harvesting resin from the trees","D":"Delivering packets to shops"},"correctOption":"C","correctAnswer":"Harvesting resin from the trees","questionType":"MCQ","explanation":{"correct_reason":"Primary production extracts natural resources directly from the land. Harvesting resin from frankincense trees in Oman obtains a raw material, so it is the primary activity of Muscat Frankincense.","distractor_reasons":{"A":"Processing resin into incense changes the raw material into a finished product. That is secondary manufacturing, so it does not belong to the primary sector in Oman.","B":"Selling packets in shops is a service provided to customers. Retailing is tertiary production, which occurs after the resin has been harvested and processed.","C":"Primary production extracts natural resources directly from the land. Harvesting resin from frankincense trees in Oman obtains a raw material, so it is the primary activity of Muscat Frankincense.","D":"Delivering packets to shops is a transport service. It does not obtain the natural resin, so it is tertiary rather than primary production."}}},{"id":"P1_U1_MCQ_1683","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1683","question":"Sana'a Coffee Ltd in Yemen used its own savings to open two more roasteries and hire 20 extra workers, without purchasing another business. Which growth method is this?","options":{"A":"Organic growth using internal funds","B":"Growth by taking over a rival","C":"Growth through a merger","D":"Growth by franchising to others"},"correctOption":"A","correctAnswer":"Organic growth using internal funds","questionType":"MCQ","explanation":{"correct_reason":"Organic growth expands the existing firm with its own resources. Sana'a Coffee used savings to add two roasteries and 20 workers, so it grew internally rather than by acquiring another company.","distractor_reasons":{"A":"Organic growth expands the existing firm with its own resources. Sana'a Coffee used savings to add two roasteries and 20 workers, so it grew internally rather than by acquiring another company.","B":"A takeover means buying control of another business. The Yemeni firm opened its own premises and did not purchase a competitor, so its growth is internal.","C":"A merger joins two existing companies into one. No other business combined with Sana'a Coffee, and its own savings funded the expansion, so this is organic growth.","D":"Franchising allows other traders to use a firm's name and system. The new roasteries are owned and staffed by the company itself, so no franchise is involved."}}},{"id":"P1_U1_MCQ_1684","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1684","question":"Kuwait City Petrochemicals Ltd in Kuwait has 80,000 ordinary shares and has declared total dividends of $240,000 after a profitable year. What dividend will each share receive?","options":{"A":"$0.30","B":"$3.50","C":"$30.00","D":"$3.00"},"correctOption":"D","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"Dividend per share equals total dividends divided by the number of shares. Kuwait City Petrochemicals distributes $240,000 across 80,000 shares, and 240,000 ÷ 80,000 = 3, so each share earns $3.00.","distractor_reasons":{"A":"Thirty cents per share would pay out only $24,000 on 80,000 shares. The declared total in Kuwait is $240,000, ten times larger, giving $3.00 per share.","B":"Three dollars and fifty cents per share would require $280,000 in total dividends. The company is distributing $240,000, so the correct amount is $3.00 per share.","C":"Thirty dollars per share would cost $2,400,000, far beyond the declared payout. Dividing $240,000 by 80,000 shares shows each holder receives $3.00.","D":"Dividend per share equals total dividends divided by the number of shares. Kuwait City Petrochemicals distributes $240,000 across 80,000 shares, and 240,000 ÷ 80,000 = 3, so each share earns $3.00."}}},{"id":"P1_U1_MCQ_1685","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1685","question":"Manama Aluminium Ltd in Bahrain has made a large profit. The government wants more corporation tax for schools, while shareholders want higher dividends. Which stakeholder conflict is shown?","options":{"A":"Customers versus suppliers","B":"Employees versus customers","C":"Managers versus customers","D":"Shareholders versus government over the distribution of profit"},"correctOption":"D","correctAnswer":"Shareholders versus government over the distribution of profit","questionType":"MCQ","explanation":{"correct_reason":"The profit can be paid to owners as dividends or collected by the state as corporation tax. Shareholders want a larger payout while the Bahraini government wants more revenue, so the two groups compete over the same profit.","distractor_reasons":{"A":"Customers and suppliers are not claiming the profit in this case. The opposing groups are the tax authority seeking school funding and the owners wanting dividends.","B":"Employees are not asking for higher wages here, and customers are not involved. The conflict is over tax versus dividends from the Bahrain company's profit.","C":"Managers may implement the payment, but customers are not making a claim. The disagreement is between shareholders and government over how profit is distributed.","D":"The profit can be paid to owners as dividends or collected by the state as corporation tax. Shareholders want a larger payout while the Bahraini government wants more revenue, so the two groups compete over the same profit."}}},{"id":"P1_U1_MCQ_1686","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1686","question":"Tehran Carpets Ltd in Iran buys wool for $20 per square metre and sells finished carpets for $150 per square metre. Which statement correctly describes the added value per square metre?","options":{"A":"It is the $130 difference between the selling price and the wool cost","B":"It is the $20 paid to the wool supplier","C":"It is the full $150 received from the customer","D":"It is the $170 sum of the price and the input cost"},"correctOption":"A","correctAnswer":"It is the $130 difference between the selling price and the wool cost","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price less the cost of materials. Tehran Carpets receives $150 per square metre and pays $20 for wool, so the Iranian firm adds $130 of value to every square metre produced.","distractor_reasons":{"A":"Added value is the selling price less the cost of materials. Tehran Carpets receives $150 per square metre and pays $20 for wool, so the Iranian firm adds $130 of value to every square metre produced.","B":"Twenty dollars is the purchase cost of the wool, not the value created. It is deducted from the $150 selling price to find the extra value generated by weaving in Iran.","C":"One hundred and fifty dollars is the selling price, which includes the $20 cost of wool. The firm's own contribution is the remaining $130, not the whole price.","D":"One hundred and seventy dollars wrongly adds price and cost together. Added value is found by subtracting the $20 wool cost from the $150 selling price, giving $130."}}},{"id":"P1_U1_MCQ_1687","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1687","question":"Isfahan Steel Ltd in Iran buys iron ore from a mine, converts it into steel sheets and uses a haulage firm to deliver them. Which business is in the secondary sector?","options":{"A":"The mine supplying iron ore","B":"The haulage firm delivering sheets","C":"Isfahan Steel, which makes the sheets","D":"The shop selling steel to the public"},"correctOption":"C","correctAnswer":"Isfahan Steel, which makes the sheets","questionType":"MCQ","explanation":{"correct_reason":"Converting iron ore into steel sheets is manufacturing, which is secondary production. Isfahan Steel performs that transformation, so it is the secondary-sector business in the Iranian chain.","distractor_reasons":{"A":"The mine extracts iron ore from the ground, which is primary production. It supplies a raw material but does not manufacture the steel sheets in Iran.","B":"The haulage firm transports finished sheets and provides a service, so it is tertiary. Delivery does not transform the ore into steel.","C":"Converting iron ore into steel sheets is manufacturing, which is secondary production. Isfahan Steel performs that transformation, so it is the secondary-sector business in the Iranian chain.","D":"A shop selling steel provides a retailing service to customers, which is tertiary production. It does not carry out the conversion of ore into metal."}}},{"id":"P1_U1_MCQ_1688","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1688","question":"Karachi Textiles Ltd in Pakistan increased annual profit from $50,000 to $60,000 after exporting to a new market. What was the percentage increase in profit?","options":{"A":"10%","B":"20%","C":"50%","D":"120%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Profit rose by $60,000 minus $50,000, which is $10,000. Dividing $10,000 by the original $50,000 gives 0.20, so the Pakistani textile firm increased profit by 20%.","distractor_reasons":{"A":"Ten thousand dollars is the absolute gain, not a percentage. Measured against the starting profit of $50,000, the increase is 20% rather than 10%.","B":"Profit rose by $60,000 minus $50,000, which is $10,000. Dividing $10,000 by the original $50,000 gives 0.20, so the Pakistani textile firm increased profit by 20%.","C":"Fifty percent would require a $25,000 rise from $50,000. The actual improvement was $10,000, which is 20% of the original profit.","D":"This year's $60,000 is 120% of last year's $50,000, showing the new level relative to the old. The increase itself is the extra 20 percentage points above the base."}}},{"id":"P1_U1_MCQ_1689","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1689","question":"Islamabad Software Ltd in Pakistan is owned by one developer who keeps all the profit and is personally liable for every debt. Which legal structure does it have?","options":{"A":"Sole trader","B":"Partnership","C":"Private limited company","D":"Cooperative"},"correctOption":"A","correctAnswer":"Sole trader","questionType":"MCQ","explanation":{"correct_reason":"A sole trader is a single owner who receives all profits and carries unlimited liability. The Islamabad developer keeps every profit and answers personally for debts, so sole trading is the correct structure.","distractor_reasons":{"A":"A sole trader is a single owner who receives all profits and carries unlimited liability. The Islamabad developer keeps every profit and answers personally for debts, so sole trading is the correct structure.","B":"A partnership requires at least two owners who share profits and liabilities. Only one developer owns this software business, so there is no partnership in Pakistan.","C":"A private limited company protects shareholders with limited liability. The developer is fully liable for all debts, so the firm does not have that protection.","D":"A cooperative is owned by several members for mutual benefit. A single owner-operator in Islamabad does not have the member structure that defines a cooperative."}}},{"id":"P1_U1_MCQ_1690","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1690","question":"Multan Cotton Ltd in Pakistan is concentrating on covering its costs after a poor harvest, rather than expanding output or chasing high profits. Which objective is the firm pursuing?","options":{"A":"Rapid growth","B":"Market leadership","C":"Profit maximisation","D":"Survival"},"correctOption":"D","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"A business focused on covering costs and staying in operation is pursuing survival. After a poor cotton harvest, the Pakistani firm is prioritising continued trading over expansion or high profits.","distractor_reasons":{"A":"Rapid growth would mean increasing output or entering new markets. Covering costs after a bad harvest is a defensive aim, not an expansion objective.","B":"Market leadership requires gaining a large share of competitors' customers. The company is not seeking dominance but simply trying to remain solvent in Pakistan.","C":"Profit maximisation aims for the largest possible profit, whereas covering costs only breaks even. The firm is satisfied with survival rather than maximum profit.","D":"A business focused on covering costs and staying in operation is pursuing survival. After a poor cotton harvest, the Pakistani firm is prioritising continued trading over expansion or high profits."}}},{"id":"P1_U1_MCQ_1691","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1691","question":"Peshawar Carpets Ltd in Pakistan divides weaving into separate stations, with each worker perfecting one knotting stage. Which benefit is the firm most likely seeking from this organisation?","options":{"A":"The end of all worker training","B":"A lower market price for wool","C":"Higher output through specialisation and practice","D":"Fewer buyers for its carpets"},"correctOption":"C","correctAnswer":"Higher output through specialisation and practice","questionType":"MCQ","explanation":{"correct_reason":"Division of labour lets each worker repeat one stage and become faster through practice. By assigning a single knotting task per station, Peshawar Carpets raises output through specialisation.","distractor_reasons":{"A":"Workers still need instruction in their assigned knotting stage. Specialisation may reduce training time, but it cannot remove the need for training altogether in Pakistan.","B":"The price of wool depends on suppliers and market conditions, not on how weaving is organised. Dividing tasks affects production speed, not the cost of the raw material.","C":"Division of labour lets each worker repeat one stage and become faster through practice. By assigning a single knotting task per station, Peshawar Carpets raises output through specialisation.","D":"Organising weaving into stations does not reduce the number of buyers. Faster production may allow the firm to serve more customers, not fewer."}}},{"id":"P1_U1_MCQ_1692","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1692","question":"Quetta Fruit Ltd in Pakistan employs 900 workers in orchards, 300 in packaging and 300 in transport services. What percentage of its 1,500 workers is in the tertiary sector?","options":{"A":"60%","B":"10%","C":"20%","D":"40%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Transport services are tertiary production and employ 300 of the 1,500 workers. Dividing 300 by 1,500 gives 0.20, so 20% of Quetta Fruit's workforce is in the tertiary sector.","distractor_reasons":{"A":"Sixty percent is the share of the 900 orchard workers, who are in the primary sector. Transport employs 300 people, which is 20% of the 1,500 total.","B":"Ten percent would require only 150 transport workers. The company reports 300 in transport services, so the tertiary share is 20% rather than 10%.","C":"Transport services are tertiary production and employ 300 of the 1,500 workers. Dividing 300 by 1,500 gives 0.20, so 20% of Quetta Fruit's workforce is in the tertiary sector.","D":"Forty percent corresponds to 600 workers, which is neither the transport nor the packaging count. The 300 transport workers represent 20% of the Pakistani firm's workforce."}}},{"id":"P1_U1_MCQ_1693","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1693","question":"Chennai Auto Parts Ltd in India has doubled its monthly production and found that its average cost per component has fallen. What does this situation illustrate?","options":{"A":"Diseconomies of scale","B":"Constant returns to scale","C":"Economies of scale","D":"Diminishing marginal returns"},"correctOption":"C","correctAnswer":"Economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Economies of scale occur when a larger scale of output reduces average costs. Chennai Auto Parts doubled production and saw cost per component fall, so the Indian firm benefits from economies of scale.","distractor_reasons":{"A":"Diseconomies of scale would push average costs upward as output rises. The Indian firm reports falling costs, so it is experiencing the opposite effect.","B":"Constant returns would keep average cost unchanged when output doubles. Because cost per component fell, this is not a case of constant returns to scale.","C":"Economies of scale occur when a larger scale of output reduces average costs. Chennai Auto Parts doubled production and saw cost per component fall, so the Indian firm benefits from economies of scale.","D":"Diminishing marginal returns involve adding variable inputs to a fixed factor in the short run. Falling average cost at larger output is instead evidence of economies of scale."}}},{"id":"P1_U1_MCQ_1694","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1694","question":"Bengaluru Software Ltd in India has limited-liability shareholders but does not offer its shares for sale on any stock exchange. Which type of company is it?","options":{"A":"Public limited company","B":"Private limited company","C":"Sole trader","D":"Partnership"},"correctOption":"B","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company has shareholders with limited liability whose shares are not publicly traded. Bengaluru Software fits this structure because owners are protected while shares remain private in India.","distractor_reasons":{"A":"A public limited company may sell shares to the public and list on a stock exchange. The Indian software firm does not trade its shares publicly, so it is not a plc.","B":"A private limited company has shareholders with limited liability whose shares are not publicly traded. Bengaluru Software fits this structure because owners are protected while shares remain private in India.","C":"A sole trader has a single owner with unlimited liability. This company has several protected shareholders, so it cannot be a sole trading business.","D":"Partners carry unlimited liability for business debts. The shareholders in Bengaluru have limited liability, which rules out a partnership structure."}}},{"id":"P1_U1_MCQ_1695","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1695","question":"Mumbai Textiles Ltd in India buys cotton from local growers. The growers want higher prices, while shareholders want to keep input costs low. Which stakeholder conflict is this?","options":{"A":"Customers versus the government","B":"Employees versus customers","C":"Government versus the local community","D":"Suppliers versus the company's shareholders"},"correctOption":"D","correctAnswer":"Suppliers versus the company's shareholders","questionType":"MCQ","explanation":{"correct_reason":"Cotton growers supply the raw material and want a higher price, while shareholders want cheaper inputs to protect profits. Their opposing objectives over the same purchase price create a supplier-versus-owner conflict in India.","distractor_reasons":{"A":"Customers and the government are not claiming the cotton payment in this scenario. The disagreement is between growers supplying cotton and shareholders seeking low costs.","B":"Employees are not asking for higher wages here, and customers are not involved. The conflicting groups are the cotton suppliers and the owners of the Indian firm.","C":"The government is not seeking more tax, and the local community is not making a claim. The real tension is over the price paid to growers versus returns to shareholders.","D":"Cotton growers supply the raw material and want a higher price, while shareholders want cheaper inputs to protect profits. Their opposing objectives over the same purchase price create a supplier-versus-owner conflict in India."}}},{"id":"P1_U1_MCQ_1696","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1696","question":"Kolkata Jute Ltd in India buys raw jute for $200 per tonne and sells finished sacks for $320 per tonne. What is the value added by processing each tonne of jute?","options":{"A":"$120","B":"$200","C":"$320","D":"$520"},"correctOption":"A","correctAnswer":"$120","questionType":"MCQ","explanation":{"correct_reason":"Value added is the selling price minus the cost of the raw input. Kolkata Jute receives $320 per tonne and paid $200 for jute, so processing adds $120 of value to each tonne in India.","distractor_reasons":{"A":"Value added is the selling price minus the cost of the raw input. Kolkata Jute receives $320 per tonne and paid $200 for jute, so processing adds $120 of value to each tonne in India.","B":"Two hundred dollars is the purchase cost of the raw jute, not the value created. It must be deducted from the $320 selling price to find the $120 added by the Indian mill.","C":"Three hundred and twenty dollars is the selling price of the sacks. It includes the $200 cost of jute, so the firm's own contribution is the remaining $120 per tonne.","D":"Five hundred and twenty dollars adds the two figures, which is not how value added is found. Subtracting $200 from $320 gives the correct figure of $120."}}},{"id":"P1_U1_MCQ_1697","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1697","question":"Ahmedabad Ceramics Ltd in India digs clay from a quarry, fires it into tiles and sells the tiles through showrooms. Which activity is retailing to the final customer?","options":{"A":"Digging clay from the quarry","B":"Selling tiles in the showrooms","C":"Firing clay into ceramic tiles","D":"Delivering tiles to building sites"},"correctOption":"B","correctAnswer":"Selling tiles in the showrooms","questionType":"MCQ","explanation":{"correct_reason":"The tertiary sector provides services to customers, and selling tiles in a showroom is retailing. Ahmedabad Ceramics' showroom staff serve buyers, so that selling activity is tertiary production.","distractor_reasons":{"A":"Digging clay extracts a natural raw material from the ground, which is primary production. It occurs at the quarry before any tiles are manufactured in India.","B":"The tertiary sector provides services to customers, and selling tiles in a showroom is retailing. Ahmedabad Ceramics' showroom staff serve buyers, so that selling activity is tertiary production.","C":"Firing clay into tiles transforms a raw material into a finished product, which is secondary manufacturing. It is not the service of selling to customers.","D":"Delivery to building sites is transport rather than retailing; it moves goods before the customer buys. The showroom sale is where Ahmedabad Ceramics serves the buyer directly."}}},{"id":"P1_U1_MCQ_1698","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1698","question":"Jaipur Jewellery Ltd in India has purchased a competing jewellery chain with cash reserves to increase its market share. Which method of growth has the firm used?","options":{"A":"External growth through a takeover","B":"Organic growth from retained profits","C":"Growth by granting franchises","D":"Growth through a cooperative"},"correctOption":"A","correctAnswer":"External growth through a takeover","questionType":"MCQ","explanation":{"correct_reason":"External growth involves expanding by acquiring another business. Jaipur Jewellery bought a competing chain, so it increased market share through a takeover rather than by internal development.","distractor_reasons":{"A":"External growth involves expanding by acquiring another business. Jaipur Jewellery bought a competing chain, so it increased market share through a takeover rather than by internal development.","B":"Organic growth uses a firm's own resources, such as opening new outlets itself. The Indian jeweller purchased an existing rival, so its growth is external.","C":"Franchising allows others to trade under the firm's brand. No such agreements are described; the company bought the competing shops outright.","D":"A cooperative is owned by members for mutual benefit. The acquisition in Jaipur is a normal purchase of a rival, not the formation of a member-owned body."}}},{"id":"P1_U1_MCQ_1699","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1699","question":"Lucknow Handicrafts Ltd in India is owned by its artisans, each holding a membership share and casting one vote on major decisions. Which legal structure is this?","options":{"A":"Cooperative","B":"Sole trader","C":"Partnership","D":"Public limited company"},"correctOption":"A","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and run by members who share benefits and vote equally. The Lucknow artisans hold membership shares and one vote each, so their handicraft business is a cooperative.","distractor_reasons":{"A":"A cooperative is owned and run by members who share benefits and vote equally. The Lucknow artisans hold membership shares and one vote each, so their handicraft business is a cooperative.","B":"A sole trader has a single owner, but the Lucknow workshop has many artisan members. One-vote membership cannot describe a single proprietor.","C":"A partnership shares profits among a few partners, but it does not normally give every worker an equal vote. The member-controlled Indian firm is a cooperative.","D":"A public limited company sells shares to outside investors, with voting usually linked to shareholdings. Here each artisan has one vote, which is the cooperative principle."}}},{"id":"P1_U1_MCQ_1700","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1700","question":"Nagpur Oranges Ltd in India set a target of 50,000 crates for the season and sold 42,500 crates. What percentage of its sales target did the firm achieve?","options":{"A":"15%","B":"42.5%","C":"50%","D":"85%"},"correctOption":"D","correctAnswer":"85%","questionType":"MCQ","explanation":{"correct_reason":"Target achievement is actual sales divided by the target. Nagpur Oranges sold 42,500 of 50,000 crates, and 42,500 ÷ 50,000 = 0.85, so the Indian firm achieved 85% of its target.","distractor_reasons":{"A":"Fifteen percent is the shortfall, since 7,500 crates were not sold. The question asks for the share achieved, which is 85% of the 50,000-crate target.","B":"Forty-two thousand five hundred is the number of crates sold, not a percentage. Dividing it by the 50,000 target gives the 85% achievement rate.","C":"Fifty thousand is the target itself, expressed as a count of crates. Achievement compares actual sales with that target, producing 85% for the Indian grower.","D":"Target achievement is actual sales divided by the target. Nagpur Oranges sold 42,500 of 50,000 crates, and 42,500 ÷ 50,000 = 0.85, so the Indian firm achieved 85% of its target."}}},{"id":"P1_U1_MCQ_1701","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1701","question":"Marlowe Joinery in Bristol makes wooden dining chairs. Each chair sells for $180, and the timber and bought-in hardware cost $70 per chair; wages and overheads add a further $60. What is the value added per chair?","options":{"A":"$110","B":"$120","C":"$70","D":"$60"},"correctOption":"A","correctAnswer":"$110","questionType":"MCQ","explanation":{"correct_reason":"Value added is the selling price less the cost of bought-in materials: $180 minus $70 gives $110 per chair. Wages and overheads are not purchased materials, so they are not deducted when calculating value added.","distractor_reasons":{"A":"Value added is the selling price less the cost of bought-in materials: $180 minus $70 gives $110 per chair. Wages and overheads are not purchased materials, so they are not deducted when calculating value added.","B":"$120 is revenue minus every cost, which is profit, not value added. Value added excludes wages and overheads and deducts only the $70 of bought-in materials from the $180 selling price.","C":"$70 is the cost of the timber and hardware, which is the bought-in material cost subtracted from the $180 selling price, not the extra value created by the joinery's own work.","D":"$60 is only the wages and overheads figure. These are internal costs, not purchased materials, so they cannot represent the value added of $180 minus $70 per chair."}}},{"id":"P1_U1_MCQ_1702","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1702","question":"Dromara Shellfish operates in Galway Bay, growing mussels on ropes and lifting them from the water. The catch is sold unprocessed to a processing plant in Cork. Which sector of economic activity does Dromara Shellfish operate in?","options":{"A":"Secondary, because the mussels are later processed by another firm","B":"Primary, because it extracts a natural resource directly from the sea","C":"Tertiary, because the mussels are transported to the buyer","D":"Public, because sea fishing is regulated by the government"},"correctOption":"B","correctAnswer":"Primary, because it extracts a natural resource directly from the sea","questionType":"MCQ","explanation":{"correct_reason":"Dromara Shellfish harvests mussels from the sea, extracting a natural resource in its raw form. That is the defining feature of primary sector activity, regardless of the fact that a separate plant later processes the catch.","distractor_reasons":{"A":"Secondary activity involves turning raw materials into finished goods. Dromara does no processing itself; the Cork plant does that, so the mussel farmer's own activity remains firmly primary.","B":"Dromara Shellfish harvests mussels from the sea, extracting a natural resource in its raw form. That is the defining feature of primary sector activity, regardless of the fact that a separate plant later processes the catch.","C":"Transport is carried out by the buyer's haulier, not by Dromara. Tertiary activity means providing a service such as transport, which is not what this shellfish-growing business actually does.","D":"Regulation by government does not make a privately owned firm part of the public sector. Ownership and control decide the sector, and Dromara is a privately owned shellfish business."}}},{"id":"P1_U1_MCQ_1703","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1703","question":"Naledi Mokoena noticed that offices in Gaborone discard large amounts of unused stationery each month. She began collecting it and reselling it to small schools at affordable prices. Which entrepreneurial characteristic does Naledi's action best illustrate?","options":{"A":"Risk avoidance, because she uses only donated goods","B":"Efficiency, because she keeps her own costs low","C":"Opportunity recognition, because she spotted an unmet need and acted on it","D":"Conformity, because she follows existing recycling practices"},"correctOption":"C","correctAnswer":"Opportunity recognition, because she spotted an unmet need and acted on it","questionType":"MCQ","explanation":{"correct_reason":"Naledi saw wasted stationery and schools that could not afford supplies, then organised a service linking the two. Recognising a gap in the market and taking action to exploit it is opportunity recognition.","distractor_reasons":{"A":"Naledi does take a risk: the stationery is donated and demand is uncertain, so she may not recover her collection costs. Avoiding risk is therefore not what her behaviour shows.","B":"Keeping costs low may help the venture, but it is not the key point. The central feature is that she identified unmet demand from schools and created a way of meeting it.","C":"Naledi saw wasted stationery and schools that could not afford supplies, then organised a service linking the two. Recognising a gap in the market and taking action to exploit it is opportunity recognition.","D":"She is not simply following established practice. By creating a new collection and resale service she is acting creatively, so conformity does not describe her entrepreneurial behaviour."}}},{"id":"P1_U1_MCQ_1704","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1704","question":"Liisa and Markus, two friends in Tallinn, opened a small cafe together. They share the decisions and the profits equally, and neither has registered a company; both are personally liable for the cafe's debts. What is the legal structure of the cafe?","options":{"A":"A sole trader, because one of them manages the business","B":"A private limited company, because profits are shared","C":"A public limited company, because it sells drinks to the public","D":"A partnership, because two people jointly own and run the business"},"correctOption":"D","correctAnswer":"A partnership, because two people jointly own and run the business","questionType":"MCQ","explanation":{"correct_reason":"Two people who jointly own and manage a business and share its profits form a partnership. The absence of a registered company and the personal liability of both owners confirm that this is a partnership.","distractor_reasons":{"A":"A sole trader has a single owner. Liisa and Markus share ownership, decisions and profits, so the business cannot be a sole trader even if one of them manages day to day.","B":"A private limited company is a separate legal entity with limited liability and registered shares. Neither feature is present here, and both owners are personally liable for all debts.","C":"Selling drinks to the public does not make a firm a public limited company. A plc must have shares traded on a stock exchange, which is not the case for this small cafe.","D":"Two people who jointly own and manage a business and share its profits form a partnership. The absence of a registered company and the personal liability of both owners confirm that this is a partnership."}}},{"id":"P1_U1_MCQ_1705","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1705","question":"Quillford Stationery in Accra sold 2,000 notebooks during March at $6 each. Its total costs for the month, including materials and wages, were $9,500. What was the business's profit for March?","options":{"A":"$9,500","B":"$2,500","C":"$12,000","D":"$2,000"},"correctOption":"B","correctAnswer":"$2,500","questionType":"MCQ","explanation":{"correct_reason":"Revenue is 2,000 notebooks multiplied by $6, giving $12,000. Profit is revenue less total costs, so $12,000 minus $9,500 equals $2,500 for the month.","distractor_reasons":{"A":"$9,500 is the total cost figure, not the profit. Profit is what remains after costs are subtracted from the $12,000 sales revenue, so the cost cannot be the answer.","B":"Revenue is 2,000 notebooks multiplied by $6, giving $12,000. Profit is revenue less total costs, so $12,000 minus $9,500 equals $2,500 for the month.","C":"$12,000 is the sales revenue, calculated as 2,000 times $6. Revenue is not profit because the $9,500 of costs still has to be deducted before the profit can be found.","D":"$2,000 is the number of notebooks sold, not a money amount of profit. Multiplying that quantity by the $6 price and then deducting $9,500 gives the correct $2,500."}}},{"id":"P1_U1_MCQ_1706","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1706","question":"Ngozi Eze runs a bakery in Enugu. She is deciding whether to buy a second mixing machine or to purchase extra flour. Which statement correctly identifies the factors of production involved in these two items?","options":{"A":"Both the mixing machine and the flour are land","B":"The mixing machine is labour and the flour is capital","C":"The flour is enterprise and the mixing machine is labour","D":"The mixing machine is capital and the flour is land as a raw material"},"correctOption":"D","correctAnswer":"The mixing machine is capital and the flour is land as a raw material","questionType":"MCQ","explanation":{"correct_reason":"A mixing machine is a manufactured aid to production, so it is capital. Flour is a natural raw material, so it counts as land. Ngozi's own organising role would be the enterprise factor.","distractor_reasons":{"A":"Land means natural resources, which fits the flour but not a manufactured machine. A mixing machine has been made by people to help produce other goods, so it is capital, not land.","B":"Labour is the human effort put into production, not a machine. The mixing machine is capital, while the flour is a natural raw material; the labour factor would be Ngozi's bakers.","C":"Enterprise is the risk-taking, organising role of the owner, not a bag of flour. The flour is a raw material from land, and the machine is capital, so this classification is wrong.","D":"A mixing machine is a manufactured aid to production, so it is capital. Flour is a natural raw material, so it counts as land. Ngozi's own organising role would be the enterprise factor."}}},{"id":"P1_U1_MCQ_1707","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1707","question":"In Soweto, a bus service is owned and funded by the local municipality, which keeps fares low so that residents can travel to work. It is managed by council appointees rather than private shareholders. Which sector of economic activity does this bus service belong to?","options":{"A":"The public sector, because it is owned and controlled by government","B":"The primary sector, because it provides transport to workers","C":"The secondary sector, because it operates a fleet of vehicles","D":"The private sector, because passengers pay a fare"},"correctOption":"A","correctAnswer":"The public sector, because it is owned and controlled by government","questionType":"MCQ","explanation":{"correct_reason":"Ownership and control determine the sector. Because the municipality owns and runs the bus service and funds it from public money, it is a public sector organisation providing a service to residents.","distractor_reasons":{"A":"Ownership and control determine the sector. Because the municipality owns and runs the bus service and funds it from public money, it is a public sector organisation providing a service to residents.","B":"Primary activity extracts natural resources such as farming or mining. Carrying passengers is a service, so the bus operation cannot be primary even though its passengers happen to be workers.","C":"Secondary activity converts materials into finished goods. Running a bus fleet provides a transport service rather than manufacturing, so it is not secondary sector activity.","D":"Charging a fare does not make an organisation private. The decisive point is that the municipality owns and controls the service, so it remains in the public sector."}}},{"id":"P1_U1_MCQ_1708","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1708","question":"Halden Foods in Bergen wants to judge how large it is compared with other firms selling the same range of frozen meals. It already knows its own sales revenue and its number of employees. Which additional measure would best show its relative size?","options":{"A":"The number of delivery vans it owns","B":"The total value of its assets alone","C":"Its share of the total market for frozen meals","D":"The wages paid to its senior managers"},"correctOption":"C","correctAnswer":"Its share of the total market for frozen meals","questionType":"MCQ","explanation":{"correct_reason":"Market share compares one firm's sales with total sales in the same market, so it shows Halden Foods' size relative to its direct rivals. Revenue or employees alone give no comparison with competing firms.","distractor_reasons":{"A":"Counting delivery vans says little about scale relative to rivals, since firms use different distribution methods. It does not measure how much of the frozen-meal market Halden Foods actually supplies.","B":"Asset value shows the resources a firm controls but not its position against competitors. A firm can hold expensive assets yet sell very little compared with others in the same market.","C":"Market share compares one firm's sales with total sales in the same market, so it shows Halden Foods' size relative to its direct rivals. Revenue or employees alone give no comparison with competing firms.","D":"Senior managers' wages are an internal cost and reveal nothing about relative size. They do not indicate how Halden Foods compares with rival sellers of frozen meals."}}},{"id":"P1_U1_MCQ_1709","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1709","question":"Ravensdale Retail Ltd in Leeds has 40,000 ordinary shares in issue. After tax, it made a profit of $90,000. The directors decided to retain $50,000 for expansion and distribute the remainder to shareholders. What is the dividend per share?","options":{"A":"$1.00","B":"$2.25","C":"$1.25","D":"$0.50"},"correctOption":"A","correctAnswer":"$1.00","questionType":"MCQ","explanation":{"correct_reason":"Dividends paid are $90,000 minus the $50,000 retained, which is $40,000. Dividing $40,000 by the 40,000 shares gives a dividend of $1.00 per share.","distractor_reasons":{"A":"Dividends paid are $90,000 minus the $50,000 retained, which is $40,000. Dividing $40,000 by the 40,000 shares gives a dividend of $1.00 per share.","B":"$2.25 would be the whole $90,000 profit spread over 40,000 shares, but $50,000 was retained rather than paid out. Only the $40,000 distribution should be divided by the share count.","C":"$1.25 is not supported by the figures: $40,000 distributed across 40,000 shares is $1.00. To reach $1.25 the company would have needed to pay out $50,000, which it retained.","D":"$0.50 would result from dividing only $20,000 by 40,000 shares. The actual amount distributed is $40,000, so the correct dividend per share is $1.00."}}},{"id":"P1_U1_MCQ_1710","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1710","question":"At a fair-trade cooperative in Mondragon, workers have been asking the board for higher wages and improved safety equipment. At the same time, the cooperative's suppliers are pressing for payment within fourteen days instead of sixty. Whose objectives are the workers expressing?","options":{"A":"Shareholders, because they want higher dividends","B":"Employees, because they seek better pay and safer conditions","C":"Customers, because they want lower prices","D":"Suppliers, because they want prompt payment"},"correctOption":"B","correctAnswer":"Employees, because they seek better pay and safer conditions","questionType":"MCQ","explanation":{"correct_reason":"The workers are asking for higher wages and better safety equipment, which are the objectives of employees. Suppliers have a separate aim of quicker payment, so the workers' demands clearly come from the employee stakeholder group.","distractor_reasons":{"A":"Shareholders want a return on their investment, usually through dividends or a rising share value. Higher wages and safety equipment for workers are not shareholder objectives, even if they affect profit.","B":"The workers are asking for higher wages and better safety equipment, which are the objectives of employees. Suppliers have a separate aim of quicker payment, so the workers' demands clearly come from the employee stakeholder group.","C":"Customers generally want good quality at low prices. The workers in this scenario are not asking about prices; they want better pay and safer conditions, which is an employee concern.","D":"Suppliers want prompt payment, and that is the separate demand described later in the scenario. The question asks specifically about the workers, whose stated aims are higher wages and safety equipment."}}},{"id":"P1_U1_MCQ_1711","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1711","question":"A call centre in Cebu organises its staff so that one team handles technical questions, a second deals with billing and a third manages complaints. Each team focuses on a narrow range of tasks. What is this working arrangement an example of?","options":{"A":"Centralisation, because all decisions are taken at headquarters","B":"Delegation, because managers give away all responsibility","C":"Division of labour, because tasks are split between specialists","D":"Formalisation, because every call is recorded"},"correctOption":"C","correctAnswer":"Division of labour, because tasks are split between specialists","questionType":"MCQ","explanation":{"correct_reason":"Splitting the workload so that different teams specialise in technical questions, billing and complaints is division of labour. Each group concentrates on one part of the process, which is the essence of specialisation.","distractor_reasons":{"A":"Centralisation concerns where decisions are made, not how tasks are divided. The scenario describes teams specialising in particular calls, not decision-making authority being concentrated at head office.","B":"Delegation means handing authority to others while retaining accountability. Nothing in the scenario says managers are passing down authority; it simply describes staff specialising in different types of calls.","C":"Splitting the workload so that different teams specialise in technical questions, billing and complaints is division of labour. Each group concentrates on one part of the process, which is the essence of specialisation.","D":"Formalisation refers to written rules and procedures. Although calls may be recorded, the defining feature described is that teams specialise in distinct tasks, which is division of labour."}}},{"id":"P1_U1_MCQ_1712","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1712","question":"A company in Split provides ferry passengers with online ticket booking, travel insurance and travel advice for a fee. It owns no ferries and carries no goods or passengers itself. Which sector of economic activity is this company in?","options":{"A":"Primary, because it deals with ferry operators","B":"Secondary, because it uses computer systems","C":"Public, because ferries are a public service","D":"Tertiary, because it sells services to travellers"},"correctOption":"D","correctAnswer":"Tertiary, because it sells services to travellers","questionType":"MCQ","explanation":{"correct_reason":"The company sells services such as booking, insurance and advice rather than extracting resources or manufacturing goods. Providing services to customers is tertiary sector activity, so this is the correct classification.","distractor_reasons":{"A":"Primary activity extracts natural resources from land or sea. Dealing with ferry operators does not involve extraction, and the company's own output is intangible advice and booking services.","B":"Using computer systems does not turn a firm into a manufacturer. Secondary activity means converting materials into physical goods, whereas this company produces no physical product at all.","C":"The fact that ferries may be a public service does not place this private company in the public sector. Sector is determined by what the business does, and it provides services.","D":"The company sells services such as booking, insurance and advice rather than extracting resources or manufacturing goods. Providing services to customers is tertiary sector activity, so this is the correct classification."}}},{"id":"P1_U1_MCQ_1713","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1713","question":"Kiruna Timber in Sweden increased its annual sales revenue from $2.5 million to $3.0 million during the last financial year. What was the percentage increase in revenue?","options":{"A":"16.7%","B":"20%","C":"25%","D":"50%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The rise in revenue is $3.0 million minus $2.5 million, which is $0.5 million. Dividing $0.5 million by the original $2.5 million and multiplying by 100 gives a 20% increase.","distractor_reasons":{"A":"Dividing the $0.5 million increase by the new figure of $3.0 million would give about 16.7%, but percentage change must use the original value as the base. The correct comparison is with $2.5 million.","B":"The rise in revenue is $3.0 million minus $2.5 million, which is $0.5 million. Dividing $0.5 million by the original $2.5 million and multiplying by 100 gives a 20% increase.","C":"A 25% increase would require a rise of $0.625 million on a base of $2.5 million. The actual rise was $0.5 million, so the percentage is 20%, not 25%.","D":"50% would mean revenue had grown by half of the original $2.5 million, that is $1.25 million. Since revenue rose by only $0.5 million, the growth is 20%."}}},{"id":"P1_U1_MCQ_1714","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1714","question":"A furniture maker in Da Nang is considering turning the business into a limited company. The owner's main reason is that if the business fails, personal savings and the family home would not be used to pay its debts. Which feature of a limited company is this?","options":{"A":"Separate legal personality, because the company can own assets","B":"Transferability of shares, because ownership can be sold","C":"Continuity, because the company survives the owner's death","D":"Limited liability, because the owner's personal assets are protected"},"correctOption":"D","correctAnswer":"Limited liability, because the owner's personal assets are protected","questionType":"MCQ","explanation":{"correct_reason":"Limited liability means shareholders risk only the money they invested, so personal savings and the family home are safe if the company cannot pay its debts. That is exactly the owner's concern in Da Nang.","distractor_reasons":{"A":"Separate legal personality allows the company to own assets and sue in its own name, but it does not by itself explain the protection of personal savings. The specific benefit described is limited liability.","B":"Transferability of shares concerns how easily ownership can be passed to someone else. The owner in Da Nang is worried about debts, not about selling shares, so this is not the relevant feature.","C":"Continuity means the business can continue after an owner leaves or dies. The scenario focuses on protecting personal property from business debts, which is limited liability, not continuity.","D":"Limited liability means shareholders risk only the money they invested, so personal savings and the family home are safe if the company cannot pay its debts. That is exactly the owner's concern in Da Nang."}}},{"id":"P1_U1_MCQ_1715","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1715","question":"A low-cost airline based in Kuala Lumpur has cut its fares below those of its rivals in order to attract more domestic passengers, even though this has reduced its short-term profit. Which business objective is the airline pursuing?","options":{"A":"Increasing market share, because it wants a larger proportion of passengers","B":"Profit maximisation, because lower fares always raise total profit","C":"Survival, because the airline is close to collapse","D":"Social responsibility, because cheaper travel helps local people"},"correctOption":"A","correctAnswer":"Increasing market share, because it wants a larger proportion of passengers","questionType":"MCQ","explanation":{"correct_reason":"By setting fares below rivals to win passengers, the airline is trying to increase its share of the domestic market. Accepting lower short-term profit is a common feature of a market-share objective.","distractor_reasons":{"A":"By setting fares below rivals to win passengers, the airline is trying to increase its share of the domestic market. Accepting lower short-term profit is a common feature of a market-share objective.","B":"Profit maximisation means seeking the highest possible profit, but the airline has deliberately accepted lower short-term profit. Cutting fares does not guarantee higher profit, so this is not the aim.","C":"Survival means covering costs to stay in business, often in a crisis. There is no sign the airline is close to collapse; it is making a competitive choice to attract more passengers.","D":"Cheaper fares may benefit travellers, but the scenario gives no indication of a social goal. The airline's stated purpose is to take passengers from rivals, which is a market-share objective."}}},{"id":"P1_U1_MCQ_1716","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1716","question":"A farmer in Nakuru has a single plot of land that can grow either maize or beans, but not both. After comparing expected returns, she plants maize. What is the opportunity cost of this decision?","options":{"A":"The price at which the maize will eventually be sold","B":"The cost of the seeds and fertiliser used on the maize","C":"The beans that could have been grown on the same plot","D":"The income the farmer earned last season"},"correctOption":"C","correctAnswer":"The beans that could have been grown on the same plot","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best alternative forgone. By choosing maize, the farmer gives up the chance to grow beans on that plot, so the forgone bean crop is the opportunity cost.","distractor_reasons":{"A":"The selling price of the maize is a benefit of the chosen option, not a cost of the decision. Opportunity cost looks at what was given up, which here is the alternative bean crop.","B":"Seeds and fertiliser are explicit costs of growing maize, not the opportunity cost. The concept refers to the benefits of the rejected alternative, namely the beans that could have been planted.","C":"Opportunity cost is the value of the next best alternative forgone. By choosing maize, the farmer gives up the chance to grow beans on that plot, so the forgone bean crop is the opportunity cost.","D":"Last season's income is a past figure and has no bearing on this choice. Opportunity cost concerns the alternative available at the time of the decision, which is the forgone bean harvest."}}},{"id":"P1_U1_MCQ_1717","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1717","question":"In a district near Kumasi, 12,000 people work in farming, 8,000 in manufacturing and 20,000 in shops and services. What percentage of the workforce is employed in the primary sector?","options":{"A":"30%","B":"20%","C":"50%","D":"40%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Total employment is 12,000 plus 8,000 plus 20,000, which is 40,000. Farming is the primary sector, so 12,000 divided by 40,000 and multiplied by 100 gives 30%.","distractor_reasons":{"A":"Total employment is 12,000 plus 8,000 plus 20,000, which is 40,000. Farming is the primary sector, so 12,000 divided by 40,000 and multiplied by 100 gives 30%.","B":"20% would be the share of manufacturing, since 8,000 out of 40,000 is one fifth. The question asks about the primary sector, which is farming, so the relevant figure is 12,000.","C":"50% is the share of workers in shops and services, the tertiary sector, because 20,000 of 40,000 is half. The primary sector is farming, whose 12,000 workers make up 30%.","D":"40% does not match any sector here. With 40,000 workers in total, the 12,000 in farming represent 30%; 40% would require 16,000 workers in the primary sector."}}},{"id":"P1_U1_MCQ_1718","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1718","question":"An entrepreneur in Tallinn has borrowed money to launch a parcel-delivery app even though two large firms already dominate the market. She knows the venture could fail and leave her in debt, but she believes customers will switch to a faster service. Which entrepreneurial quality is she showing?","options":{"A":"Risk avoidance, because she has researched the market","B":"Willingness to take a risk, because she has borrowed money despite uncertainty","C":"Imitation, because she copies the two dominant firms","D":"Cost minimisation, because she keeps her prices low"},"correctOption":"B","correctAnswer":"Willingness to take a risk, because she has borrowed money despite uncertainty","questionType":"MCQ","explanation":{"correct_reason":"Borrowing money to enter a market dominated by established rivals, while accepting the possibility of failure and debt, shows a willingness to take a risk. Research does not remove that financial exposure.","distractor_reasons":{"A":"Researching the market does not make the venture safe. She has borrowed money and faces strong competitors, so she is taking a genuine risk rather than avoiding one.","B":"Borrowing money to enter a market dominated by established rivals, while accepting the possibility of failure and debt, shows a willingness to take a risk. Research does not remove that financial exposure.","C":"She is not copying the dominant firms; she is offering a faster service to win customers away from them. That is competitive innovation, not imitation of existing providers.","D":"Keeping prices low may be part of her plan, but the scenario emphasises borrowing and the chance of failure. The quality on display is willingness to take a risk."}}},{"id":"P1_U1_MCQ_1719","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1719","question":"A sole trader in Valparaiso used personal savings and a loan secured on her home to start a small grocery shop. The shop failed with debts larger than its assets. Which statement about the owner's position is correct?","options":{"A":"She has limited liability, so her home is protected from creditors","B":"Her liability is shared equally with the bank that made the loan","C":"She has unlimited liability, so her personal assets can be used to pay the debts","D":"The debts are written off automatically because the shop has closed"},"correctOption":"C","correctAnswer":"She has unlimited liability, so her personal assets can be used to pay the debts","questionType":"MCQ","explanation":{"correct_reason":"A sole trader has unlimited liability, meaning there is no legal separation between the owner and the business. Creditors can therefore claim personal assets such as savings or the family home to settle the shop's debts.","distractor_reasons":{"A":"Limited liability belongs to companies, not sole traders. Because there is no separate legal entity here, the owner's personal savings and home remain available to creditors.","B":"Liability is not shared with the lender. The bank is a creditor that can claim repayment, but the sole trader alone is responsible for the full amount owed by the business.","C":"A sole trader has unlimited liability, meaning there is no legal separation between the owner and the business. Creditors can therefore claim personal assets such as savings or the family home to settle the shop's debts.","D":"Closing the shop does not erase its debts. With unlimited liability, the owner remains personally responsible and creditors may pursue personal assets until the debts are settled."}}},{"id":"P1_U1_MCQ_1720","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1720","question":"The management of a chocolate factory in Ecatepec wants to install automated machinery to reduce production costs. Workers fear that this will cost them their jobs, while shareholders are pressing for higher dividends from the savings. What does this situation illustrate?","options":{"A":"That shareholders and workers always share the same objectives","B":"A disagreement between the factory and its customers over chocolate quality","C":"That cost reduction benefits every stakeholder equally","D":"A conflict between the objective of higher returns for owners and employees' job security"},"correctOption":"D","correctAnswer":"A conflict between the objective of higher returns for owners and employees' job security","questionType":"MCQ","explanation":{"correct_reason":"Shareholders want higher dividends from lower costs, whereas employees want to keep their jobs. These aims conflict because automation that raises returns may create redundancies, so the scenario shows a clash of stakeholder objectives.","distractor_reasons":{"A":"The scenario shows the opposite: shareholders welcome the cost savings while workers fear job losses. Their objectives are clearly not the same, so this option misreads the situation.","B":"Customers and chocolate quality are not mentioned. The disagreement described is between management and shareholders on one side and workers fearing redundancy on the other.","C":"Cost reduction does not benefit everyone equally. Here it may raise dividends for shareholders but reduce job security for employees, which is why the stakeholders are in conflict.","D":"Shareholders want higher dividends from lower costs, whereas employees want to keep their jobs. These aims conflict because automation that raises returns may create redundancies, so the scenario shows a clash of stakeholder objectives."}}},{"id":"P1_U1_MCQ_1721","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1721","question":"A tailor in Fez buys cloth for $28 and thread for $4 to make a jacket, which he sells for $120. Assuming these are the only bought-in materials, what is the value added by the tailor?","options":{"A":"$92","B":"$88","C":"$32","D":"$120"},"correctOption":"B","correctAnswer":"$88","questionType":"MCQ","explanation":{"correct_reason":"The bought-in materials cost $28 for cloth plus $4 for thread, a total of $32. Subtracting this from the $120 selling price leaves $88, which is the value the tailor adds through his own work.","distractor_reasons":{"A":"$92 would come from deducting only the $28 cloth and ignoring the $4 thread. Both are bought-in materials, so the full $32 must be subtracted from the $120 price.","B":"The bought-in materials cost $28 for cloth plus $4 for thread, a total of $32. Subtracting this from the $120 selling price leaves $88, which is the value the tailor adds through his own work.","C":"$32 is the cost of the cloth and thread, the materials purchased from other businesses. Value added is the selling price less that cost, so it is $88, not the material cost itself.","D":"$120 is the selling price of the jacket, which is the sales revenue. It is not value added, because the $32 cost of bought-in materials has to be deducted first."}}},{"id":"P1_U1_MCQ_1722","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1722","question":"A mining company near Sudbury extracts nickel ore from the ground and sells it unprocessed to a smelter hundreds of kilometres away. Which sector of economic activity is the mining company engaged in?","options":{"A":"Secondary, because the ore is used by a smelter","B":"Tertiary, because the ore is transported to another city","C":"Public, because mineral rights are owned by the government","D":"Primary, because it extracts a natural resource from the earth"},"correctOption":"D","correctAnswer":"Primary, because it extracts a natural resource from the earth","questionType":"MCQ","explanation":{"correct_reason":"Digging nickel ore out of the ground is the extraction of a natural resource in its raw state. That is primary sector activity, even though a separate smelter later processes the ore into metal.","distractor_reasons":{"A":"The company extracts the ore but does not refine it. Processing raw materials into finished products is secondary activity, and that work is done by the smelter, not the mining firm.","B":"Transporting the ore is a service provided by a haulier or rail firm. The mining company's own activity is extraction, so it belongs to the primary sector rather than tertiary services.","C":"Government ownership of mineral rights does not turn a private mining company into a public sector organisation. The sector is determined by the activity of extraction, not by licensing rules.","D":"Digging nickel ore out of the ground is the extraction of a natural resource in its raw state. That is primary sector activity, even though a separate smelter later processes the ore into metal."}}},{"id":"P1_U1_MCQ_1723","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1723","question":"A bakery in Izmir has used its retained profits to open three new branches in nearby towns over two years, without borrowing money or purchasing another business. What type of growth has the bakery achieved?","options":{"A":"Organic growth, because it expanded using its own resources","B":"Takeover, because it now operates in several towns","C":"Diversification, because it sells bread in new locations","D":"Merger, because two previously separate firms combined"},"correctOption":"A","correctAnswer":"Organic growth, because it expanded using its own resources","questionType":"MCQ","explanation":{"correct_reason":"Opening new branches with retained profits, without borrowing or acquiring another firm, is organic or internal growth. The bakery expands its existing business using resources it has generated itself.","distractor_reasons":{"A":"Opening new branches with retained profits, without borrowing or acquiring another firm, is organic or internal growth. The bakery expands its existing business using resources it has generated itself.","B":"A takeover means buying control of an existing business. The bakery simply opened its own new branches, so no other firm was purchased in the two-year period.","C":"Diversification means moving into different products or markets. Selling the same bread in additional towns is geographic expansion of the existing product, not diversification.","D":"A merger requires two separate businesses to combine. The scenario describes one bakery adding branches, so there has been no combination of firms."}}},{"id":"P1_U1_MCQ_1724","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1724","question":"Forty coffee growers near Hue have formed a joint organisation to buy fertiliser in bulk and sell their beans together. Each member owns a share and has one vote at meetings, and surplus is returned to members. What type of organisation have they created?","options":{"A":"A public limited company, because it has many members","B":"A sole trader, because the growers work independently","C":"A cooperative, because members jointly own and vote on the business","D":"A partnership, because every member is personally liable for debts"},"correctOption":"C","correctAnswer":"A cooperative, because members jointly own and vote on the business","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and democratically controlled by its members, each with a vote, and any surplus is returned to them. The growers near Hue fit this description exactly.","distractor_reasons":{"A":"A public limited company has shares traded on a stock exchange and is driven by shareholder profit. The growers' body has one vote per member and returns surplus to members, which is a cooperative.","B":"A sole trader has one owner. Here forty growers jointly own the buying and selling organisation, so it cannot be a sole trader even though each still farms independently.","C":"A cooperative is owned and democratically controlled by its members, each with a vote, and any surplus is returned to them. The growers near Hue fit this description exactly.","D":"A partnership typically involves a small number of partners with unlimited liability. The growers' arrangement is a member-owned cooperative with democratic voting, not a partnership."}}},{"id":"P1_U1_MCQ_1725","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1725","question":"A gym in Gijon has 600 members who each pay a monthly subscription of $25. Assuming all members pay in full, what is the gym's total subscription revenue for one month?","options":{"A":"$15,000","B":"$600","C":"$625","D":"$12,000"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Total subscription revenue is the number of members multiplied by the monthly fee: 600 times $25 equals $15,000. This is the figure the gym would record as its monthly income from members.","distractor_reasons":{"A":"Total subscription revenue is the number of members multiplied by the monthly fee: 600 times $25 equals $15,000. This is the figure the gym would record as its monthly income from members.","B":"$600 is just the number of members, not a revenue figure. Revenue is found by multiplying that count by the $25 each member pays every month.","C":"$625 would be the result of adding 600 and $25, which is meaningless here. Monthly revenue requires multiplication of the 600 members by the $25 subscription.","D":"$12,000 would be the revenue if only 480 members paid, since 480 times $25 is $12,000. The scenario states all 600 members pay in full, so revenue is $15,000."}}},{"id":"P1_U1_MCQ_1726","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1726","question":"A software developer in Belgrade uses a laptop, a rented office and her own idea for a accounting application to create and sell a new product. Which factor of production is represented by her idea and decision to start the business?","options":{"A":"Land, because the idea is a natural resource","B":"Enterprise, because she organises resources and takes the risk","C":"Capital, because the idea can be sold repeatedly","D":"Labour, because she types the program code herself"},"correctOption":"B","correctAnswer":"Enterprise, because she organises resources and takes the risk","questionType":"MCQ","explanation":{"correct_reason":"Enterprise is the factor that combines land, labour and capital and bears the risk of the venture. The developer's idea and her decision to bring the laptop, office and her coding together make her the enterprise factor.","distractor_reasons":{"A":"Land refers to natural resources, such as minerals or farmland. An idea for an accounting application is not a natural resource, although the office she rents does use land.","B":"Enterprise is the factor that combines land, labour and capital and bears the risk of the venture. The developer's idea and her decision to bring the laptop, office and her coding together make her the enterprise factor.","C":"Capital means manufactured aids such as the laptop and office equipment. An idea is not a physical aid to production, so it is not capital even if it can be sold many times.","D":"Labour is the effort of employees, such as the hours she spends writing code. Her idea and willingness to organise the whole venture go beyond labour and constitute enterprise."}}},{"id":"P1_U1_MCQ_1727","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1727","question":"A plant in Monterrey buys sheets of steel and presses them into car body panels, which it delivers to a vehicle assembly plant. Which sector of economic activity does this plant operate in?","options":{"A":"Primary, because it supplies the car industry","B":"Tertiary, because it delivers the panels to customers","C":"Secondary, because it converts steel into a manufactured product","D":"Public, because the assembly plant is government owned"},"correctOption":"C","correctAnswer":"Secondary, because it converts steel into a manufactured product","questionType":"MCQ","explanation":{"correct_reason":"Pressing steel sheets into car body panels is a manufacturing process that converts a raw material into a finished component. That transformation is the defining characteristic of secondary sector activity.","distractor_reasons":{"A":"Primary activity extracts natural resources, but this plant buys steel that has already been produced. Its own work is shaping that material, which is manufacturing rather than extraction.","B":"Delivering panels is a transport service, but the plant's main activity is making the panels. Tertiary sector classification depends on providing services, not on the act of delivery.","C":"Pressing steel sheets into car body panels is a manufacturing process that converts a raw material into a finished component. That transformation is the defining characteristic of secondary sector activity.","D":"Ownership of the customer does not decide the plant's sector. Even if the assembly plant were public, the panel maker converts materials into goods and is therefore secondary."}}},{"id":"P1_U1_MCQ_1728","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1728","question":"A family bakery in Ljubljana has grown from a single shop with two bakers into twelve outlets employing ninety people. Which set of figures best demonstrates that the bakery has grown in size?","options":{"A":"The price of a loaf and the cost of flour","B":"The number of ovens in the original shop only","C":"The bakery's prices compared with a rival in the same street","D":"The rise from one shop to twelve outlets and from two to ninety employees"},"correctOption":"D","correctAnswer":"The rise from one shop to twelve outlets and from two to ninety employees","questionType":"MCQ","explanation":{"correct_reason":"Business size is commonly measured by the number of outlets and the number of employees. Moving from one shop and two bakers to twelve outlets and ninety staff shows clear expansion on both measures.","distractor_reasons":{"A":"The price of a loaf and the cost of flour tell us about costs and pricing, not about the scale of the business. They cannot show whether the bakery has expanded over time.","B":"Looking only at the ovens in the original shop ignores the eleven new outlets entirely. Size must be judged across the whole business, not one part of it.","C":"Comparing prices with a rival shows competitiveness, not growth. The bakery's own increase in outlets and employees is the relevant evidence of a larger business.","D":"Business size is commonly measured by the number of outlets and the number of employees. Moving from one shop and two bakers to twelve outlets and ninety staff shows clear expansion on both measures."}}},{"id":"P1_U1_MCQ_1729","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1729","question":"Two partners in Trondheim share their business profits in the ratio 3:2. This year's profit is $45,000. How much does the partner receiving the larger share get?","options":{"A":"$18,000","B":"$27,000","C":"$15,000","D":"$30,000"},"correctOption":"B","correctAnswer":"$27,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio 3:2 has five parts in total, so each part is $45,000 divided by 5, which is $9,000. The larger partner receives three parts, that is 3 times $9,000, giving $27,000.","distractor_reasons":{"A":"$18,000 is two parts of $9,000, which is the smaller partner's share. The question asks for the partner with the larger three-part share, so the answer is $27,000.","B":"The ratio 3:2 has five parts in total, so each part is $45,000 divided by 5, which is $9,000. The larger partner receives three parts, that is 3 times $9,000, giving $27,000.","C":"$15,000 does not correspond to the 3:2 split of $45,000. Five equal parts are $9,000 each, so neither partner receives $15,000 under the agreed ratio.","D":"$30,000 would be two thirds of the profit, which would require a 2:1 split. The agreed ratio is 3:2, so the larger share is three fifths, or $27,000."}}},{"id":"P1_U1_MCQ_1730","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1730","question":"A supermarket chain in Valencia has extended the time it takes to pay its suppliers from thirty days to ninety days, while also cutting shelf prices to attract shoppers. Which stakeholder group is most clearly disadvantaged by these decisions?","options":{"A":"Customers, because they now pay higher prices","B":"Shareholders, because dividends must be reduced","C":"Employees, because their wages are delayed","D":"Suppliers, because they wait much longer for payment"},"correctOption":"D","correctAnswer":"Suppliers, because they wait much longer for payment","questionType":"MCQ","explanation":{"correct_reason":"Suppliers previously received payment after thirty days and now wait ninety days, which strains their own cash flow. They are the stakeholders clearly disadvantaged, while shoppers benefit from lower prices.","distractor_reasons":{"A":"Customers are not disadvantaged here because prices were cut rather than raised. The group facing a real loss is the suppliers, who must finance a much longer wait for their money.","B":"Nothing in the scenario says dividends are reduced. Delaying supplier payments can actually help the chain's cash position, so shareholders are not the disadvantaged group described.","C":"Employee wages are not mentioned. The change affects the payment terms offered to suppliers, extending the wait from thirty to ninety days, so workers are not the affected stakeholders.","D":"Suppliers previously received payment after thirty days and now wait ninety days, which strains their own cash flow. They are the stakeholders clearly disadvantaged, while shoppers benefit from lower prices."}}},{"id":"P1_U1_MCQ_1731","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1731","question":"A pottery in Iznik divides production so that one worker shapes pots, a second applies glaze and a third packs finished pieces for dispatch. What is the main advantage of arranging work in this way?","options":{"A":"Greater efficiency and faster output as workers specialise in one task","B":"Higher prices because customers prefer handmade pottery","C":"Lower material costs because less clay is needed","D":"Elimination of all waste because no worker makes mistakes"},"correctOption":"A","correctAnswer":"Greater efficiency and faster output as workers specialise in one task","questionType":"MCQ","explanation":{"correct_reason":"When each worker specialises in shaping, glazing or packing, they become skilled at that task and output rises. This division of labour increases efficiency and speeds up the whole production process.","distractor_reasons":{"A":"When each worker specialises in shaping, glazing or packing, they become skilled at that task and output rises. This division of labour increases efficiency and speeds up the whole production process.","B":"Specialisation does not by itself raise prices. Customers may value handmade pottery, but the benefit described in the scenario is the faster, more efficient production from splitting tasks.","C":"Dividing tasks does not reduce the quantity of clay used in each pot. The advantage is in how work is organised, not in saving raw materials.","D":"Specialisation can reduce errors but cannot eliminate all waste. Workers may still make mistakes, so claiming that no waste occurs is far too strong."}}},{"id":"P1_U1_MCQ_1732","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1732","question":"A national railway in Senegal is owned by the government, funded from the national budget and managed by a state-appointed board. It carries passengers and freight across the country. Which sector does this railway belong to?","options":{"A":"Primary, because it transports agricultural produce","B":"Private sector, because passengers buy tickets","C":"Public sector, because it is owned and controlled by the state","D":"Secondary, because it maintains a large fleet of locomotives"},"correctOption":"C","correctAnswer":"Public sector, because it is owned and controlled by the state","questionType":"MCQ","explanation":{"correct_reason":"The railway is owned, funded and controlled by the government through a state-appointed board. Those features place it firmly in the public sector, whatever goods or passengers it carries.","distractor_reasons":{"A":"Carrying farm produce does not make the railway a primary activity. Primary sector means extracting natural resources, whereas a railway provides a transport service.","B":"Selling tickets does not transfer ownership to the private sector. The decisive facts are state ownership and state control, so the railway remains a public body.","C":"The railway is owned, funded and controlled by the government through a state-appointed board. Those features place it firmly in the public sector, whatever goods or passengers it carries.","D":"Maintaining locomotives is a support activity, not the railway's core function of providing transport. It also does not change the fact that the state owns and runs the organisation."}}},{"id":"P1_U1_MCQ_1733","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1733","question":"The total market for mobile phones in Quito is 200,000 units a year. A local electronics retailer sells 24,000 phones in the same period. What is the retailer's market share?","options":{"A":"12%","B":"8.3%","C":"24%","D":"20%"},"correctOption":"A","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Here 24,000 divided by 200,000 is 0.12, so the retailer supplies 12% of the Quito market.","distractor_reasons":{"A":"Market share is the firm's sales divided by total market sales, multiplied by 100. Here 24,000 divided by 200,000 is 0.12, so the retailer supplies 12% of the Quito market.","B":"About 8.3% would result from dividing 200,000 by 24,000 incorrectly. Market share compares the firm's 24,000 units with the 200,000-unit total, giving 12%, not the reverse.","C":"24% would be the share if the total market were 100,000 units. Since the Quito market is actually 200,000 units, the retailer's 24,000 sales represent only 12%.","D":"20% would require sales of 40,000 phones out of the 200,000-unit market. The retailer sells 24,000, so its share is 12% rather than one fifth."}}},{"id":"P1_U1_MCQ_1734","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1734","question":"A family in Bruges runs a chocolate business that has been registered as a separate legal entity. Its shares are held only by family members and cannot be bought by the public. Which type of business organisation is this?","options":{"A":"A sole trader, because one family member manages it","B":"A private limited company, because shares are privately held","C":"A public limited company, because it sells chocolate publicly","D":"A partnership, because several family members are involved"},"correctOption":"B","correctAnswer":"A private limited company, because shares are privately held","questionType":"MCQ","explanation":{"correct_reason":"A private limited company is a separate legal entity whose shares are not offered to the public. The Bruges chocolate firm is registered and its shares stay within the family, so it is a private limited company.","distractor_reasons":{"A":"A sole trader has no separate legal entity and no shares. The chocolate business is registered as a company with shares, so it cannot be a sole trader.","B":"A private limited company is a separate legal entity whose shares are not offered to the public. The Bruges chocolate firm is registered and its shares stay within the family, so it is a private limited company.","C":"Selling chocolate to the public does not make a firm a public limited company. A plc must offer its shares for public trading, which the family explicitly does not do.","D":"A partnership does not issue shares or become a separate legal entity. The family business has registered shares held privately, which points to a private limited company."}}},{"id":"P1_U1_MCQ_1735","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1735","question":"A small farm in Tuscany aims to cover all its costs and provide steady work for the family, but the owner has no wish to expand or to maximise profits. Which business objective best describes this aim?","options":{"A":"Profit maximisation, because the farm wants the highest possible return","B":"Market leadership, because the farm wants to outsell rivals","C":"Survival, because the priority is covering costs and keeping the family employed","D":"Growth, because the farm plans to buy more land each year"},"correctOption":"C","correctAnswer":"Survival, because the priority is covering costs and keeping the family employed","questionType":"MCQ","explanation":{"correct_reason":"The farm's aim is simply to cover its costs and keep the family in work, with no drive to expand. That is a survival objective, focused on continuing to operate rather than on growth or maximum profit.","distractor_reasons":{"A":"Profit maximisation means pursuing the largest possible profit, which the owner explicitly rejects. Covering costs and keeping jobs secure is a more modest, survival-oriented aim.","B":"Market leadership involves outselling competitors and gaining a large share. The Tuscan farm has no such ambition, so this objective does not match its stated purpose.","C":"The farm's aim is simply to cover its costs and keep the family in work, with no drive to expand. That is a survival objective, focused on continuing to operate rather than on growth or maximum profit.","D":"Growth means expanding output or buying more land. The owner has no wish to expand, so growth is clearly not the objective being described."}}},{"id":"P1_U1_MCQ_1736","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1736","question":"A fisherman in Essaouira can use his boat and his working day either to catch sardines or to take tourists on short sea trips. He decides to fish. The income he would have earned from the trips is an example of what?","options":{"A":"An explicit cost, because he buys fuel for the boat","B":"A fixed cost, because it does not change with the catch","C":"A revenue stream, because tourists pay for the trips","D":"An opportunity cost, because it is the benefit of the forgone alternative"},"correctOption":"D","correctAnswer":"An opportunity cost, because it is the benefit of the forgone alternative","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best option given up. By choosing to fish, the fisherman forgoes the income from tourist trips, so that lost income is the opportunity cost of his decision.","distractor_reasons":{"A":"An explicit cost involves an actual payment, such as buying fuel. The forgone tourist income involves no payment; it is the benefit sacrificed, which makes it an opportunity cost.","B":"A fixed cost does not vary with output, but the tourist income is not a cost of fishing at all. It represents the value of the alternative use of his boat and time.","C":"Tourist trips would generate revenue if they were chosen, but they were not. The concept being tested is the benefit given up, not revenue actually earned from the chosen activity.","D":"Opportunity cost is the value of the next best option given up. By choosing to fish, the fisherman forgoes the income from tourist trips, so that lost income is the opportunity cost of his decision."}}},{"id":"P1_U1_MCQ_1737","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1737","question":"In a district of Hanoi, 45,000 people are employed: 9,000 in farming, 18,000 in factories and the remainder in shops and services. What percentage of workers are employed in the tertiary sector?","options":{"A":"20%","B":"40%","C":"45%","D":"60%"},"correctOption":"B","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"The remainder in shops and services is 45,000 minus 9,000 minus 18,000, which equals 18,000. Dividing 18,000 by the 45,000 total and multiplying by 100 gives 40% in the tertiary sector.","distractor_reasons":{"A":"20% is the share of the 9,000 farming workers, since 9,000 out of 45,000 is one fifth. Farming is primary, whereas the question asks about shops and services.","B":"The remainder in shops and services is 45,000 minus 9,000 minus 18,000, which equals 18,000. Dividing 18,000 by the 45,000 total and multiplying by 100 gives 40% in the tertiary sector.","C":"45% does not follow from the figures. The tertiary group is 18,000 of 45,000 workers, which is 40%; 45% would require 20,250 workers in services.","D":"60% would be the combined share of farming and factories, because 27,000 of 45,000 is 60%. The tertiary sector alone accounts for the remaining 18,000 workers, or 40%."}}},{"id":"P1_U1_MCQ_1738","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1738","question":"A packaging company in Taipei has developed a strong, biodegradable material made from cassava starch to replace plastic wrapping used by food manufacturers. Which entrepreneurial characteristic does this best demonstrate?","options":{"A":"Risk avoidance, because cassava is a safe material","B":"Cost leadership, because biodegradable wrap is always cheaper","C":"Imitation, because other firms already use cassava","D":"Innovation, because it has created a new product using a different material"},"correctOption":"D","correctAnswer":"Innovation, because it has created a new product using a different material","questionType":"MCQ","explanation":{"correct_reason":"Developing a biodegradable wrapping from cassava starch to replace plastic involves creating a new product and applying a new idea. That is innovation, a key entrepreneurial characteristic.","distractor_reasons":{"A":"Choosing a safe material does not mean risk has been avoided. The company invested in developing a new product whose market demand is uncertain, which is a risk-taking step.","B":"The scenario gives no evidence that the new wrapping is cheaper than plastic. Its purpose is to replace plastic with a biodegradable option, so cost leadership is not demonstrated.","C":"The company has developed its own material rather than copying rivals. Nothing in the scenario suggests other firms already use cassava, so imitation is not supported.","D":"Developing a biodegradable wrapping from cassava starch to replace plastic involves creating a new product and applying a new idea. That is innovation, a key entrepreneurial characteristic."}}},{"id":"P1_U1_MCQ_1739","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1739","question":"A brewery in Manchester wants to raise a large amount of capital by offering its shares for sale to the general public and having them traded on a stock exchange. Which legal structure is it planning to adopt?","options":{"A":"A public limited company, because its shares can be traded publicly","B":"A private limited company, because it produces a consumer product","C":"A sole trader, because one person can own a brewery","D":"A partnership, because several investors will hold shares"},"correctOption":"A","correctAnswer":"A public limited company, because its shares can be traded publicly","questionType":"MCQ","explanation":{"correct_reason":"A public limited company may offer shares to the public and have them traded on a stock exchange, allowing it to raise large sums of capital. The Manchester brewery's plan matches this structure exactly.","distractor_reasons":{"A":"A public limited company may offer shares to the public and have them traded on a stock exchange, allowing it to raise large sums of capital. The Manchester brewery's plan matches this structure exactly.","B":"A private limited company cannot sell shares to the general public. Because the brewery specifically wants public share trading, it must become a public limited company instead.","C":"A sole trader has a single owner and cannot issue shares at all. The plan to sell shares publicly and raise large capital rules out sole trader status.","D":"Partners do not hold shares traded on a stock exchange. Public share offerings are a feature of a public limited company, not a partnership."}}},{"id":"P1_U1_MCQ_1740","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1740","question":"A new car-parts factory in Bratislava has been welcomed by the local council because it will create 400 jobs and pay business rates that fund local services. Which stakeholder group's objectives are highlighted in this reaction?","options":{"A":"Customers, because they want a wider choice of car parts","B":"Employees, because they all want higher wages immediately","C":"The local community and government, because they value jobs and tax revenue","D":"Suppliers, because they expect large orders from the factory"},"correctOption":"C","correctAnswer":"The local community and government, because they value jobs and tax revenue","questionType":"MCQ","explanation":{"correct_reason":"The council represents government and the local community, both of which gain from new employment and business rates that fund services. These are the stakeholder objectives reflected in the welcome given to the factory.","distractor_reasons":{"A":"Customers might benefit from more choice, but the council's reaction focuses on jobs and rates, not on product variety. The objectives described are those of government and the community.","B":"Employees want jobs and wages, but the statement comes from the council and stresses local rates as well as employment. The group highlighted is wider than the workforce alone.","C":"The council represents government and the local community, both of which gain from new employment and business rates that fund services. These are the stakeholder objectives reflected in the welcome given to the factory.","D":"Suppliers may hope for orders, yet nothing in the scenario mentions them. The council's comments are about employment and business rates, which concern the community and government."}}},{"id":"P1_U1_MCQ_1741","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1741","question":"A vineyard in Mendoza sells a bottle of wine for $14. The glass bottle, cork and label are bought in from suppliers at a total cost of $5 per bottle. What is the value added by the vineyard for each bottle?","options":{"A":"$9","B":"$5","C":"$14","D":"$19"},"correctOption":"A","correctAnswer":"$9","questionType":"MCQ","explanation":{"correct_reason":"Value added is sales revenue less the cost of bought-in materials. The $14 selling price minus the $5 cost of glass, cork and label leaves $9, which is the value the vineyard adds by making and marketing the wine.","distractor_reasons":{"A":"Value added is sales revenue less the cost of bought-in materials. The $14 selling price minus the $5 cost of glass, cork and label leaves $9, which is the value the vineyard adds by making and marketing the wine.","B":"$5 is the cost of the bottle, cork and label, the materials bought from other firms. Value added is the selling price less that cost, so it is $9 rather than the material cost.","C":"$14 is the selling price of a bottle. It represents sales revenue, not value added, because the $5 spent on bought-in materials must be subtracted to find the value created.","D":"$19 would come from adding the $5 material cost to the $14 price. Value added subtracts bought-in costs from revenue, so the correct figure is $9 per bottle."}}},{"id":"P1_U1_MCQ_1742","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1742","question":"A beekeeper in the Rif mountains keeps hives among wild flowers and sells pots of honey directly to households in nearby towns. The honey is bottled on site but is otherwise unprocessed. Which sector is this business in?","options":{"A":"Secondary, because the honey is put into pots","B":"Primary, because it collects a natural product from the land","C":"Tertiary, because the beekeeper sells to households","D":"Public, because the mountains are government owned"},"correctOption":"B","correctAnswer":"Primary, because it collects a natural product from the land","questionType":"MCQ","explanation":{"correct_reason":"Collecting honey from hives is taking a natural product from the land, which is primary sector activity. Simple bottling does not turn it into manufacturing, and selling direct does not change the sector.","distractor_reasons":{"A":"Putting honey into pots is packaging, not converting a raw material into a different product. The beekeeper's core activity is gathering a natural product, so the business is primary.","B":"Collecting honey from hives is taking a natural product from the land, which is primary sector activity. Simple bottling does not turn it into manufacturing, and selling direct does not change the sector.","C":"Selling directly to households is a retail service, but the defining activity here is the collection of honey. Retail would be tertiary only if that were the main business carried out.","D":"Government ownership of the land does not make a privately run beekeeping business public. Sector classification depends on the activity of collecting a natural product."}}},{"id":"P1_U1_MCQ_1743","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1743","question":"A fashion retailer in Singapore has become much larger by purchasing two competing chains and merging their shops into its own group. Which method of growth has the retailer used?","options":{"A":"Organic growth, because it reinvested its profits","B":"Market development, because it entered new overseas markets","C":"External growth through takeover, because it bought other firms","D":"Franchising, because independent owners run the shops"},"correctOption":"C","correctAnswer":"External growth through takeover, because it bought other firms","questionType":"MCQ","explanation":{"correct_reason":"Buying two competing chains is a takeover, which is a form of external growth. The retailer expanded by bringing existing businesses under its control rather than by building new shops itself.","distractor_reasons":{"A":"Organic growth means expanding using the firm's own resources, such as opening new branches. Here the retailer purchased two existing chains, so the growth is external.","B":"The scenario does not mention entry into overseas markets. The expansion came from buying competitors, which is a takeover rather than market development.","C":"Buying two competing chains is a takeover, which is a form of external growth. The retailer expanded by bringing existing businesses under its control rather than by building new shops itself.","D":"Franchising involves other people owning and running outlets under the brand. The retailer bought the chains outright, so the shops are not independently owned franchises."}}},{"id":"P1_U1_MCQ_1744","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1744","question":"A community sports club in Christchurch is run by volunteers and reinvests all surplus into new facilities rather than paying dividends to owners. Which type of organisation best describes this club?","options":{"A":"A public limited company, because it offers services to the public","B":"A partnership, because the volunteers share the work","C":"A sole trader, because one manager is in charge","D":"A not-for-profit organisation, because surplus is reinvested rather than distributed"},"correctOption":"D","correctAnswer":"A not-for-profit organisation, because surplus is reinvested rather than distributed","questionType":"MCQ","explanation":{"correct_reason":"The club does not aim to distribute profits to owners; instead it reinvests any surplus in facilities and is run by volunteers. Those features make it a not-for-profit organisation.","distractor_reasons":{"A":"A public limited company has shares traded publicly and seeks returns for shareholders. The club neither issues shares nor distributes profit, so it is not a plc.","B":"A partnership involves owners who share profits and are usually liable for debts. The club's surplus is reinvested and it is volunteer-run, so partnership does not fit.","C":"A sole trader has one owner who keeps all profits. The club is run collectively by volunteers and has no individual owner taking the surplus, so it is not a sole trader.","D":"The club does not aim to distribute profits to owners; instead it reinvests any surplus in facilities and is run by volunteers. Those features make it a not-for-profit organisation."}}},{"id":"P1_U1_MCQ_1745","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1745","question":"A cinema in Ghent sold 1,200 tickets at $9 each last weekend and had total operating costs of $7,000. What profit did the cinema make over the weekend?","options":{"A":"$7,000","B":"$3,800","C":"$10,800","D":"$2,800"},"correctOption":"B","correctAnswer":"$3,800","questionType":"MCQ","explanation":{"correct_reason":"Ticket revenue is 1,200 multiplied by $9, giving $10,800. Subtracting the $7,000 of operating costs leaves a profit of $3,800 for the weekend.","distractor_reasons":{"A":"$7,000 is the operating costs, not the profit. Profit is what remains once those costs are taken away from the $10,800 earned from selling tickets.","B":"Ticket revenue is 1,200 multiplied by $9, giving $10,800. Subtracting the $7,000 of operating costs leaves a profit of $3,800 for the weekend.","C":"$10,800 is the total ticket revenue, calculated from 1,200 tickets at $9 each. It is not profit because the $7,000 of costs still needs to be deducted.","D":"$2,800 does not follow from the data. With revenue of $10,800 and costs of $7,000, the correct profit is $3,800."}}},{"id":"P1_U1_MCQ_1746","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1746","question":"A dressmaker in Milan owns a sewing machine, buys bolts of silk and uses her own design skills to make and sell garments. Which combination of factors of production does this description illustrate?","options":{"A":"Land, labour and capital, but no enterprise","B":"Capital and labour only, because silk is a manufactured fabric","C":"Land and enterprise only, because no machinery is involved","D":"Land from the silk, capital from the machine and enterprise from her designs"},"correctOption":"D","correctAnswer":"Land from the silk, capital from the machine and enterprise from her designs","questionType":"MCQ","explanation":{"correct_reason":"The silk is a raw material and therefore land, the sewing machine is a manufactured aid and therefore capital, and the dressmaker's design and organising role is enterprise. Her work also supplies labour.","distractor_reasons":{"A":"Enterprise is present because the dressmaker creates designs and organises the business. Ignoring it misses a key factor, even though land, labour and capital are also used.","B":"Silk originates from natural fibres and counts as a raw material, which is land. The dressmaker also shows enterprise, so saying only capital and labour are involved is incomplete.","C":"The sewing machine is clearly a piece of capital equipment, so machinery is involved. The description also includes labour in the dressmaker's own work, making this option wrong.","D":"The silk is a raw material and therefore land, the sewing machine is a manufactured aid and therefore capital, and the dressmaker's design and organising role is enterprise. Her work also supplies labour."}}},{"id":"P1_U1_MCQ_1747","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1747","question":"A call-centre operator in Manila answers customers' questions on behalf of a European bank and is paid a fee for each month of service provided. Which sector of economic activity does the call centre belong to?","options":{"A":"Tertiary, because it provides a service to customers","B":"Primary, because it is located in a large city","C":"Secondary, because it uses telephone equipment","D":"Public, because its client is a bank"},"correctOption":"A","correctAnswer":"Tertiary, because it provides a service to customers","questionType":"MCQ","explanation":{"correct_reason":"Answering questions and handling enquiries is a service provided for a fee. Service provision is the defining feature of the tertiary sector, so the call centre is a tertiary business.","distractor_reasons":{"A":"Answering questions and handling enquiries is a service provided for a fee. Service provision is the defining feature of the tertiary sector, so the call centre is a tertiary business.","B":"Location in a large city does not determine the sector. Primary activity means extracting natural resources, whereas this call centre sells intangible support services.","C":"Using telephones and computers does not make a firm a manufacturer. Secondary activity means converting materials into goods, and the call centre produces no physical product.","D":"The fact that its client is a bank does not make the call centre public. It is the service it provides that places the business in the tertiary sector."}}},{"id":"P1_U1_MCQ_1748","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1748","question":"A wheat farm in the Punjab used to sell all its grain to a flour mill. It has now opened its own bakery and sells bread directly to local shops. What type of growth is this an example of?","options":{"A":"Backward vertical integration, because it bought a flour mill","B":"Diversification into an unrelated product","C":"Forward vertical integration, because it moved closer to the final customer","D":"Horizontal growth, because it bought another wheat farm"},"correctOption":"C","correctAnswer":"Forward vertical integration, because it moved closer to the final customer","questionType":"MCQ","explanation":{"correct_reason":"The farm now processes its own wheat into bread and sells to shops, moving forward along the supply chain towards the consumer. That is forward vertical integration, not a move into unrelated goods.","distractor_reasons":{"A":"Backward integration would mean taking control of an earlier stage, such as buying a supplier. The farm instead added a later stage by baking and selling bread.","B":"Bread is made from the farm's own wheat, so this is closely related to its existing business. Diversification into unrelated products is not what has happened.","C":"The farm now processes its own wheat into bread and sells to shops, moving forward along the supply chain towards the consumer. That is forward vertical integration, not a move into unrelated goods.","D":"Horizontal growth means acquiring or merging with a competitor at the same stage. The farm did not buy another farm; it added processing and selling activities."}}},{"id":"P1_U1_MCQ_1749","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1749","question":"A company in Turin has 250,000 ordinary shares in issue and has declared a total dividend payment of $125,000. What is the dividend received per share?","options":{"A":"$0.50","B":"$0.25","C":"$2.00","D":"$1.25"},"correctOption":"A","correctAnswer":"$0.50","questionType":"MCQ","explanation":{"correct_reason":"The total dividend of $125,000 is spread across 250,000 shares. Dividing $125,000 by 250,000 gives $0.50, so each shareholder receives fifty cents per share.","distractor_reasons":{"A":"The total dividend of $125,000 is spread across 250,000 shares. Dividing $125,000 by 250,000 gives $0.50, so each shareholder receives fifty cents per share.","B":"$0.25 would be the result of dividing $125,000 by 500,000 shares. With only 250,000 shares in issue, the dividend per share is twice that amount at $0.50.","C":"$2.00 would require a total dividend of $500,000 across 250,000 shares. The declared payment is $125,000, giving a dividend of $0.50 per share.","D":"$1.25 would come from dividing 250,000 shares by $125,000, which reverses the calculation. The correct method is total dividend divided by number of shares."}}},{"id":"P1_U1_MCQ_1750","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1750","question":"Managers at an engineering firm in Sheffield are considering replacing skilled machinists with automated equipment to reduce costs. Shareholders welcome the expected rise in dividends, but the workers threaten to leave. What does this illustrate?","options":{"A":"That all stakeholders benefit equally from new technology","B":"A conflict between shareholders seeking higher returns and employees wanting job security","C":"That shareholders have no influence on management decisions","D":"A disagreement between the firm and its suppliers over delivery times"},"correctOption":"B","correctAnswer":"A conflict between shareholders seeking higher returns and employees wanting job security","questionType":"MCQ","explanation":{"correct_reason":"Shareholders gain from higher dividends produced by cost savings, while workers risk losing their jobs. The opposing aims of these two stakeholder groups show a clear conflict of objectives.","distractor_reasons":{"A":"The stakeholders do not benefit equally: shareholders gain from lower costs and workers may lose their jobs. The scenario is about a clash, not shared benefits.","B":"Shareholders gain from higher dividends produced by cost savings, while workers risk losing their jobs. The opposing aims of these two stakeholder groups show a clear conflict of objectives.","C":"Shareholders are clearly influential here because management is responding to their wish for higher dividends. The scenario does not suggest they have no influence.","D":"Suppliers and delivery times are not mentioned. The disagreement is instead between shareholders and employees over the consequences of introducing automation."}}},{"id":"P1_U1_MCQ_1751","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1751","question":"A charity shop in Cork sorts donated clothes, prices them and serves customers who want affordable clothing. Which statement best describes the business activity carried out by this shop?","options":{"A":"It only involves making physical goods, so the shop is not a business","B":"It is limited to firms that aim to make a profit for owners","C":"It combines resources to provide goods or services that satisfy customer needs","D":"It excludes organisations that are owned by charities"},"correctOption":"C","correctAnswer":"It combines resources to provide goods or services that satisfy customer needs","questionType":"MCQ","explanation":{"correct_reason":"Business activity brings together resources such as donated clothes, shop space and workers' time to provide goods and services that meet customers' needs. The Cork charity shop does exactly that, whether or not it seeks profit.","distractor_reasons":{"A":"Business activity includes services as well as physical goods. The shop provides a retail service, so it is a business even though it does not manufacture the clothes it sells.","B":"Business activity is not limited to profit-making firms. Charities and social enterprises also combine resources to satisfy needs, as the Cork shop demonstrates.","C":"Business activity brings together resources such as donated clothes, shop space and workers' time to provide goods and services that meet customers' needs. The Cork charity shop does exactly that, whether or not it seeks profit.","D":"Charity ownership does not exclude an organisation from business activity. What matters is that resources are organised to provide goods or services to customers."}}},{"id":"P1_U1_MCQ_1752","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1752","question":"A forestry company in Lapland plants pine seedlings, tends the trees for decades and then harvests timber, selling the logs to a paper mill. Which sector of economic activity does this company operate in?","options":{"A":"Secondary, because it supplies wood to a manufacturing business","B":"Tertiary, because it manages a large area of forest","C":"Public, because forests are protected by law","D":"Primary, because it grows and harvests a natural resource"},"correctOption":"D","correctAnswer":"Primary, because it grows and harvests a natural resource","questionType":"MCQ","explanation":{"correct_reason":"Planting and harvesting trees is the cultivation and extraction of a natural resource, which is the defining feature of primary sector activity. The paper mill carries out the later manufacturing stage.","distractor_reasons":{"A":"Supplying a manufacturer does not make the supplier secondary. The forestry company extracts timber in its raw form, so its own activity remains primary.","B":"Managing woodland is not a service sold to customers in the way that banking or transport is. The company's output is logs, a raw material, so it is primary.","C":"Legal protection of forests does not turn a private forestry company into a public body. Its activity of growing and harvesting timber determines the sector.","D":"Planting and harvesting trees is the cultivation and extraction of a natural resource, which is the defining feature of primary sector activity. The paper mill carries out the later manufacturing stage."}}},{"id":"P1_U1_MCQ_1753","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1753","question":"A chain of hair salons in Osaka increased the number of its outlets from 40 to 50 during one year. What was the percentage increase in the number of salons?","options":{"A":"10%","B":"25%","C":"20%","D":"12.5%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The chain added 10 salons, since 50 minus 40 is 10. Dividing the increase of 10 by the original 40 outlets and multiplying by 100 gives a 25% rise in the number of salons.","distractor_reasons":{"A":"10 is the number of new salons, not the percentage increase. To find the percentage, the increase must be divided by the original 40 outlets, giving 25%.","B":"The chain added 10 salons, since 50 minus 40 is 10. Dividing the increase of 10 by the original 40 outlets and multiplying by 100 gives a 25% rise in the number of salons.","C":"20% would result from dividing the 10 new salons by the final total of 50. Percentage growth must use the original figure of 40 as the base, so the answer is 25%.","D":"12.5% would be the share that 10 new salons represent of 80 outlets. With only 40 original outlets, the growth rate is 10 divided by 40, which is 25%."}}},{"id":"P1_U1_MCQ_1754","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1754","question":"A sole trader in Bilbao wants to expand her workshop, protect her personal savings from business debts and raise money from investors without offering shares to the general public. Which legal structure should she choose?","options":{"A":"Remain a sole trader, because expansion is always easier alone","B":"Form a partnership, because partners always have limited liability","C":"Convert to a public limited company, because it can sell shares to anyone","D":"Form a private limited company, which offers limited liability and privately held shares"},"correctOption":"D","correctAnswer":"Form a private limited company, which offers limited liability and privately held shares","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives limited liability, so personal savings are protected, and it can raise finance by issuing shares that are not offered to the public. This matches the trader's three requirements.","distractor_reasons":{"A":"Remaining a sole trader would leave personal savings exposed because of unlimited liability. It also makes raising money from outside investors far harder, so it does not meet her needs.","B":"Partners generally have unlimited liability for business debts, so a partnership would not protect her savings. The requirement of limited liability points to a limited company.","C":"A public limited company can sell shares to anyone, but the trader specifically wants to keep shares away from the general public. A private limited company is the appropriate form.","D":"A private limited company gives limited liability, so personal savings are protected, and it can raise finance by issuing shares that are not offered to the public. This matches the trader's three requirements."}}},{"id":"P1_U1_MCQ_1755","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1755","question":"A smartphone manufacturer in Shenzhen has set itself the aim of becoming the best-selling brand in its home market within three years, investing heavily in new models and advertising. Which objective is the firm pursuing?","options":{"A":"Market leadership, because it aims to outsell all rivals","B":"Survival, because it is trying to cover its costs","C":"Ethical responsibility, because it invests in new models","D":"Cost minimisation, because it wants the cheapest handsets"},"correctOption":"A","correctAnswer":"Market leadership, because it aims to outsell all rivals","questionType":"MCQ","explanation":{"correct_reason":"The Shenzhen firm wants to become the best-selling brand, which means gaining the largest share of sales ahead of competitors. That is a market leadership objective supported by investment and advertising.","distractor_reasons":{"A":"The Shenzhen firm wants to become the best-selling brand, which means gaining the largest share of sales ahead of competitors. That is a market leadership objective supported by investment and advertising.","B":"Survival means simply covering costs and staying in business. A three-year plan to become the top-selling brand is an ambitious growth aim, not a modest survival objective.","C":"Investing in new models is not by itself ethical behaviour, and no social or environmental goal is mentioned. The stated aim is to outsell rivals in the home market.","D":"The firm is spending heavily on models and advertising rather than cutting costs. Its target is sales leadership, not producing the cheapest handsets."}}},{"id":"P1_U1_MCQ_1756","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1756","question":"A household in Maputo has only enough income this week for one purchase: a sack of rice for the family's meals or a new mobile phone for the teenagers. They buy the rice. Which statement correctly classifies the two goods?","options":{"A":"Both are needs because the family wants them","B":"The phone is a need and the rice is a want","C":"Rice is a need because it provides essential food, while the phone is a want","D":"Both are wants because neither is essential to survival"},"correctOption":"C","correctAnswer":"Rice is a need because it provides essential food, while the phone is a want","questionType":"MCQ","explanation":{"correct_reason":"Food is essential for the household's survival, so the rice is a need. A new mobile phone is desirable but not necessary for basic well-being, making it a want in this situation.","distractor_reasons":{"A":"Wanting something does not make it a need. The rice satisfies the basic requirement of food, whereas the phone is an optional extra, so the two goods are not both needs.","B":"The classifications are reversed. The rice provides essential nourishment and is the need, while a new phone is an optional want that the family could postpone.","C":"Food is essential for the household's survival, so the rice is a need. A new mobile phone is desirable but not necessary for basic well-being, making it a want in this situation.","D":"Rice is essential to survival, so it cannot be classed as a want. Only the phone is discretionary, which is why the correct answer distinguishes the two goods."}}},{"id":"P1_U1_MCQ_1757","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1757","question":"In a region of Oaxaca, 25,000 people are working: 5,000 in farming, 10,000 in factories and 10,000 in shops and services. What percentage of the workforce is employed in the secondary sector?","options":{"A":"40%","B":"20%","C":"25%","D":"50%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Factories provide manufacturing jobs, which belong to the secondary sector. There are 10,000 such workers out of 25,000 in total, so 10,000 divided by 25,000 and multiplied by 100 gives 40%.","distractor_reasons":{"A":"Factories provide manufacturing jobs, which belong to the secondary sector. There are 10,000 such workers out of 25,000 in total, so 10,000 divided by 25,000 and multiplied by 100 gives 40%.","B":"20% is the share of the 5,000 farming workers, since 5,000 out of 25,000 is one fifth. Farming is primary, while the question asks about manufacturing jobs.","C":"25% does not match the figures. The 10,000 factory workers are 40% of the 25,000 workforce; 25% would require only 6,250 workers in manufacturing.","D":"50% would be the combined share of factories and services, because 20,000 of 25,000 is 80% not 50%. The secondary sector alone accounts for 10,000 workers, or 40%."}}},{"id":"P1_U1_MCQ_1758","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1758","question":"An entrepreneur in Lomé noticed that market traders' goods were soaked by rain and started making strong waterproof carry bags from recycled fabric. Which entrepreneurial quality is this action best demonstrating?","options":{"A":"Imitation, because other traders sell bags","B":"Innovation, because she devised a new product to solve a real problem","C":"Risk avoidance, because recycled fabric is inexpensive","D":"Cost leadership, because she wants the lowest prices"},"correctOption":"B","correctAnswer":"Innovation, because she devised a new product to solve a real problem","questionType":"MCQ","explanation":{"correct_reason":"She observed a problem, damaged goods, and created a new waterproof bag from recycled fabric to solve it. Developing a new product in response to a real need is entrepreneurial innovation.","distractor_reasons":{"A":"She is not copying existing traders; she created a product designed for a problem they face. There is no evidence that other sellers offered the same waterproof bags.","B":"She observed a problem, damaged goods, and created a new waterproof bag from recycled fabric to solve it. Developing a new product in response to a real need is entrepreneurial innovation.","C":"Starting a new venture always carries the risk that customers will not buy the bags. Using cheap material does not remove that risk, so risk avoidance is not the quality shown.","D":"The scenario focuses on solving the problem of rain damage, not on undercutting rivals. Low prices may follow, but innovation is the characteristic being demonstrated."}}},{"id":"P1_U1_MCQ_1759","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1759","question":"Farmers near Eldoret have set up a cooperative through which they buy fertiliser in bulk and market their produce together. What is the chief advantage for the individual farmer of belonging to this organisation?","options":{"A":"Each farmer keeps all decisions to themselves","B":"The cooperative guarantees the highest possible market price","C":"Bulk buying lowers costs and joint marketing gives greater bargaining power","D":"Farmers no longer have to pay any transport costs"},"correctOption":"C","correctAnswer":"Bulk buying lowers costs and joint marketing gives greater bargaining power","questionType":"MCQ","explanation":{"correct_reason":"By joining together, farmers can purchase fertiliser in large quantities at lower unit prices and negotiate as a group with buyers. These are the main benefits of the cooperative structure described.","distractor_reasons":{"A":"A cooperative involves shared decision-making, not each farmer acting alone. The benefits come precisely from coordinating purchases and sales rather than keeping decisions separate.","B":"The cooperative strengthens bargaining power but cannot guarantee the highest price. Market conditions still determine what buyers will pay for the farmers' produce.","C":"By joining together, farmers can purchase fertiliser in large quantities at lower unit prices and negotiate as a group with buyers. These are the main benefits of the cooperative structure described.","D":"Transport costs are not eliminated by forming a cooperative. Produce still has to be moved to market, even if it is done more efficiently through a shared arrangement."}}},{"id":"P1_U1_MCQ_1760","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1760","question":"A theme park on Jeju island is criticised by an environmental pressure group for its high water use, while its managers defend the park by pointing to the 350 jobs it provides. Which stakeholder objectives are in conflict here?","options":{"A":"Customers and suppliers over ticket prices","B":"Shareholders and the government over tax rates","C":"The local council and visitors over opening hours","D":"The pressure group's environmental aims and management's desire to protect employment"},"correctOption":"D","correctAnswer":"The pressure group's environmental aims and management's desire to protect employment","questionType":"MCQ","explanation":{"correct_reason":"The pressure group wants reduced water use to protect the environment, whereas management stresses the jobs the park creates. These are opposing stakeholder objectives, one environmental and one concerned with employment.","distractor_reasons":{"A":"Ticket prices are not mentioned, and the critics are an environmental group rather than customers or suppliers. The conflict described concerns water use and jobs.","B":"Shareholders and tax rates do not appear in the scenario. The disagreement is between a pressure group concerned about water and managers defending local employment.","C":"Opening hours and the local council are not part of the statement. The clashing aims are environmental protection on one side and safeguarding 350 jobs on the other.","D":"The pressure group wants reduced water use to protect the environment, whereas management stresses the jobs the park creates. These are opposing stakeholder objectives, one environmental and one concerned with employment."}}},{"id":"P1_U1_MCQ_1761","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1761","question":"A joinery in Truro buys timber for $40 and metal hardware for $10 to build a table, which it sells to a customer for $200. What is the value added by the joinery on this table?","options":{"A":"$160","B":"$150","C":"$50","D":"$200"},"correctOption":"B","correctAnswer":"$150","questionType":"MCQ","explanation":{"correct_reason":"The bought-in materials are $40 of timber plus $10 of hardware, a total of $50. Deducting this from the $200 selling price gives $150, the value the joinery adds by making the table.","distractor_reasons":{"A":"$160 would result from subtracting only the $40 timber and forgetting the $10 of hardware. Both are bought-in materials and must be deducted from the $200 price.","B":"The bought-in materials are $40 of timber plus $10 of hardware, a total of $50. Deducting this from the $200 selling price gives $150, the value the joinery adds by making the table.","C":"$50 is the cost of the timber and hardware, the materials purchased from suppliers. Value added is the selling price less that cost, so the figure is $150.","D":"$200 is the selling price, which is sales revenue rather than value added. The $50 cost of bought-in materials has to be subtracted before value added can be found."}}},{"id":"P1_U1_MCQ_1762","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1762","question":"A shipping company based in Piraeus carries shipping containers between ports for manufacturers and retailers, charging a fee per voyage. Which sector of economic activity does this company operate in?","options":{"A":"Primary, because it carries raw materials","B":"Secondary, because it owns a fleet of vessels","C":"Public, because ports are owned by the state","D":"Tertiary, because it provides a transport service"},"correctOption":"D","correctAnswer":"Tertiary, because it provides a transport service","questionType":"MCQ","explanation":{"correct_reason":"Carrying containers between ports is a transport service provided for a fee, which makes it tertiary sector activity. The company does not extract resources or manufacture the goods it carries.","distractor_reasons":{"A":"Transporting raw materials does not make the carrier a primary producer. Primary activity extracts resources; this company merely moves goods that other businesses have produced.","B":"Owning vessels is not the same as manufacturing them. The company's activity is providing shipping services, so it belongs to the tertiary sector rather than secondary industry.","C":"State ownership of ports does not place a private shipping company in the public sector. The company's own service activity determines its sector.","D":"Carrying containers between ports is a transport service provided for a fee, which makes it tertiary sector activity. The company does not extract resources or manufacture the goods it carries."}}},{"id":"P1_U1_MCQ_1763","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1763","question":"A cosmetics firm in Marseille has purchased a small rival brand in order to enter the luxury skincare market without developing its own products from scratch. Which method of growth has it used?","options":{"A":"External growth through acquisition, because it bought another firm","B":"Organic growth, because it used its own profits","C":"Diversification into an unrelated industry","D":"Franchising, because the rival brand is run by others"},"correctOption":"A","correctAnswer":"External growth through acquisition, because it bought another firm","questionType":"MCQ","explanation":{"correct_reason":"Buying an existing rival brand is an acquisition, which is a form of external growth. The Marseille firm gains access to the luxury market by taking over another business rather than building from scratch.","distractor_reasons":{"A":"Buying an existing rival brand is an acquisition, which is a form of external growth. The Marseille firm gains access to the luxury market by taking over another business rather than building from scratch.","B":"Organic growth means expanding through the firm's own operations, such as launching new products. Here the firm bought an established brand, so the growth is external.","C":"Luxury skincare is still cosmetics, so the move is within the same industry. Buying a related rival is not diversification into an unrelated line of business.","D":"Franchising involves letting independent operators use a brand. The firm purchased the rival outright, so the acquired brand is not being run as a franchise."}}},{"id":"P1_U1_MCQ_1764","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1764","question":"An entrepreneur in Adelaide pays an annual fee to use a well-known pizza brand's name, logo and recipes, and receives training and marketing support in return. Which form of business organisation is this?","options":{"A":"A cooperative, because the brand is jointly owned","B":"A public limited company, because a well-known brand is involved","C":"A franchise, because the owner licenses the brand and methods","D":"A sole trader, because the entrepreneur keeps all the profits"},"correctOption":"C","correctAnswer":"A franchise, because the owner licenses the brand and methods","questionType":"MCQ","explanation":{"correct_reason":"A franchisee pays a fee to use an established brand's name, recipes and support while running their own outlet. The Adelaide entrepreneur's arrangement matches the definition of a franchise.","distractor_reasons":{"A":"A cooperative is owned democratically by its members. Here the brand belongs to the franchisor and the entrepreneur simply licenses it, so there is no joint ownership.","B":"A famous brand does not make the outlet a public limited company. There is no mention of shares being traded publicly, so plc status is not supported.","C":"A franchisee pays a fee to use an established brand's name, recipes and support while running their own outlet. The Adelaide entrepreneur's arrangement matches the definition of a franchise.","D":"The entrepreneur may keep profits after fees, but the defining feature is the paid licence to use the brand and methods. That makes it a franchise, not an ordinary sole trader."}}},{"id":"P1_U1_MCQ_1765","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1765","question":"A bakery in Plovdiv sold 3,000 loaves at $2 each last week and had total costs of $4,200. What was the bakery's profit for the week?","options":{"A":"$1,800","B":"$4,200","C":"$6,000","D":"$1,200"},"correctOption":"A","correctAnswer":"$1,800","questionType":"MCQ","explanation":{"correct_reason":"Revenue from 3,000 loaves at $2 each is $6,000. Subtracting the total costs of $4,200 leaves a profit of $1,800 for the week.","distractor_reasons":{"A":"Revenue from 3,000 loaves at $2 each is $6,000. Subtracting the total costs of $4,200 leaves a profit of $1,800 for the week.","B":"$4,200 is the total cost figure, not the profit. Profit is what remains after the costs are deducted from the $6,000 sales revenue.","C":"$6,000 is the sales revenue, found by multiplying 3,000 loaves by $2. It is not profit because the $4,200 of costs must be subtracted first.","D":"$1,200 does not follow from the figures. With revenue of $6,000 and costs of $4,200, the weekly profit is $1,800."}}},{"id":"P1_U1_MCQ_1766","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1766","question":"A car plant in Bratislava uses welding robots, bought-in components and trained engineers to produce vehicles. Which factor of production is represented by the welding robots?","options":{"A":"Land, because they are made from natural materials","B":"Capital, because they are manufactured aids used in production","C":"Labour, because they perform the work of employees","D":"Enterprise, because they organise the production line"},"correctOption":"B","correctAnswer":"Capital, because they are manufactured aids used in production","questionType":"MCQ","explanation":{"correct_reason":"Capital consists of manufactured items used to produce other goods, such as machinery and equipment. Welding robots are exactly that, so they are the capital factor in the car plant.","distractor_reasons":{"A":"Land refers to natural resources such as minerals or farmland. Although robots are made of materials, they are manufactured equipment, so they belong to capital rather than land.","B":"Capital consists of manufactured items used to produce other goods, such as machinery and equipment. Welding robots are exactly that, so they are the capital factor in the car plant.","C":"Robots may do work once performed by people, but labour is the human effort of employees. The engineers and technicians provide labour; the robots themselves are capital.","D":"Enterprise is the organising and risk-taking role of the owner or managers. Robots cannot make decisions or bear risk, so they do not represent enterprise."}}},{"id":"P1_U1_MCQ_1767","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1767","question":"A company in Antwerp buys rough diamonds, cuts and polishes them into gemstones, and sells the finished stones to jewellery makers. Which sector of economic activity does this company operate in?","options":{"A":"Primary, because diamonds are mined from the earth","B":"Tertiary, because the stones are sold to other firms","C":"Secondary, because it processes a raw material into a finished product","D":"Public, because precious stones are regulated by law"},"correctOption":"C","correctAnswer":"Secondary, because it processes a raw material into a finished product","questionType":"MCQ","explanation":{"correct_reason":"Cutting and polishing rough diamonds into gemstones transforms a raw material into a finished product. That manufacturing process is the defining characteristic of secondary sector activity.","distractor_reasons":{"A":"Mining diamonds would be primary activity, but this company buys rough stones rather than extracting them. Its own work is processing, which is secondary.","B":"Selling the finished stones to jewellers is only the final step. The company's main activity is cutting and polishing, so it is classified as secondary rather than tertiary.","C":"Cutting and polishing rough diamonds into gemstones transforms a raw material into a finished product. That manufacturing process is the defining characteristic of secondary sector activity.","D":"Regulation of the diamond trade does not make a private company part of the public sector. Ownership and the activity of processing determine the classification."}}},{"id":"P1_U1_MCQ_1768","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1768","question":"A supermarket chain in Perth has opened 30 new stores in five years and has also acquired a regional rival. Which pair of objectives has the chain most clearly been pursuing?","options":{"A":"Survival and ethical trading, because it keeps prices low","B":"Cost minimisation and staff welfare, because it employs more people","C":"Social responsibility and product quality, because it serves more customers","D":"Growth and increased market share, because it expanded its own stores and bought a rival"},"correctOption":"D","correctAnswer":"Growth and increased market share, because it expanded its own stores and bought a rival","questionType":"MCQ","explanation":{"correct_reason":"Opening 30 new outlets and acquiring a rival both enlarge the chain's operations and its share of grocery sales. These actions point clearly to objectives of growth and market share.","distractor_reasons":{"A":"Survival means merely staying in business, while the chain has expanded substantially. Low prices are not mentioned, so ethical trading is not supported by the scenario.","B":"Employing more people is a consequence of expansion, not evidence of a staff welfare objective. The scenario gives no information about costs or wages.","C":"Serving more customers does not by itself prove a social responsibility objective. The evidence given is expansion through new stores and a takeover, which indicates growth.","D":"Opening 30 new outlets and acquiring a rival both enlarge the chain's operations and its share of grocery sales. These actions point clearly to objectives of growth and market share."}}},{"id":"P1_U1_MCQ_1769","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1769","question":"A limited company in Graz has 80,000 ordinary shares and has declared a total dividend of $60,000. How much dividend does a shareholder receive for each share held?","options":{"A":"$0.60","B":"$0.75","C":"$1.33","D":"$0.50"},"correctOption":"B","correctAnswer":"$0.75","questionType":"MCQ","explanation":{"correct_reason":"Dividend per share is the total payment divided by the number of shares. $60,000 divided by 80,000 gives $0.75, so each share earns seventy-five cents.","distractor_reasons":{"A":"$0.60 would be the dividend if the company had 100,000 shares. With 80,000 shares sharing $60,000, the payment per share is $0.75.","B":"Dividend per share is the total payment divided by the number of shares. $60,000 divided by 80,000 gives $0.75, so each share earns seventy-five cents.","C":"$1.33 comes from dividing 80,000 shares by $60,000, which reverses the correct calculation. The dividend per share is total dividend divided by share count.","D":"$0.50 would require a total dividend of $40,000 across 80,000 shares. The company declared $60,000, so the dividend is $0.75 per share."}}},{"id":"P1_U1_MCQ_1770","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1770","question":"A smartphone factory in Hanoi can either raise wages to keep its skilled workers or spend the money on automated machinery that would increase returns for shareholders. Which stakeholders are in conflict in this decision?","options":{"A":"Customers and suppliers over delivery schedules","B":"Management and the government over taxation","C":"Employees and customers over product quality","D":"Employees seeking higher wages and shareholders seeking higher returns"},"correctOption":"D","correctAnswer":"Employees seeking higher wages and shareholders seeking higher returns","questionType":"MCQ","explanation":{"correct_reason":"Spending on wages benefits employees, while spending on machinery that raises returns benefits shareholders. The same money cannot satisfy both, so these two stakeholder groups have conflicting objectives.","distractor_reasons":{"A":"Customers and suppliers are not part of the choice described. The conflict is over whether money goes to wages or to machinery that raises shareholder returns.","B":"Taxation is not mentioned. The decision concerns the division of funds between employees and shareholders, not a dispute between management and government.","C":"Product quality is not at issue. The choice is between higher wages for workers and higher returns for shareholders, so customers are not the conflicting group.","D":"Spending on wages benefits employees, while spending on machinery that raises returns benefits shareholders. The same money cannot satisfy both, so these two stakeholder groups have conflicting objectives."}}},{"id":"P1_U1_MCQ_1771","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1771","question":"A tailor in Marrakesh has arranged his workshop so that one assistant stitches sleeves, another finishes hems and a third delivers completed garments. What is this way of organising production called?","options":{"A":"Division of labour, because tasks are divided among specialists","B":"Centralisation, because the tailor makes every decision alone","C":"Delegation, because the tailor has no responsibility left","D":"Diversification, because the workshop offers several services"},"correctOption":"A","correctAnswer":"Division of labour, because tasks are divided among specialists","questionType":"MCQ","explanation":{"correct_reason":"Assigning stitching, finishing and delivery to different people means each worker specialises in one task. This is division of labour, which can raise speed and skill through repetition.","distractor_reasons":{"A":"Assigning stitching, finishing and delivery to different people means each worker specialises in one task. This is division of labour, which can raise speed and skill through repetition.","B":"Centralisation refers to where decisions are made, not how tasks are split. The scenario describes specialised jobs, not the tailor keeping all decision-making authority.","C":"Delegation involves passing authority to others while remaining accountable. Nothing here says the tailor has given away responsibility; assistants simply perform distinct tasks.","D":"Diversification means entering new products or markets. The workshop still produces the same garments, so the arrangement is specialisation, not diversification."}}},{"id":"P1_U1_MCQ_1772","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1772","question":"A national broadcaster in Cairo is financed mainly by government funds, is accountable to a government ministry and provides news and entertainment to viewers. Which sector does it belong to?","options":{"A":"Primary, because it gathers information from the country","B":"Private sector, because viewers watch its programmes","C":"Public sector, because it is funded and controlled by the state","D":"Secondary, because it operates broadcasting equipment"},"correctOption":"C","correctAnswer":"Public sector, because it is funded and controlled by the state","questionType":"MCQ","explanation":{"correct_reason":"The broadcaster receives government funding and is accountable to a ministry, so it is owned and controlled by the state. That places it firmly in the public sector.","distractor_reasons":{"A":"Gathering news is not the extraction of natural resources. Primary sector means farming, mining or fishing, which is quite different from producing broadcast content.","B":"Having viewers does not make the broadcaster private. The decisive facts are state funding and government control, so it remains a public sector body.","C":"The broadcaster receives government funding and is accountable to a ministry, so it is owned and controlled by the state. That places it firmly in the public sector.","D":"Operating equipment does not make an organisation a manufacturer. The broadcaster provides a service, and in any case its state control is the key classification point."}}},{"id":"P1_U1_MCQ_1773","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1773","question":"A brewery near Malmo increased its annual sales revenue from $4.0 million to $4.6 million. What was the percentage increase in revenue over the year?","options":{"A":"15%","B":"12%","C":"6%","D":"60%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $0.6 million, since $4.6 million minus $4.0 million is $0.6 million. Dividing that increase by the original $4.0 million and multiplying by 100 gives 15%.","distractor_reasons":{"A":"Revenue rose by $0.6 million, since $4.6 million minus $4.0 million is $0.6 million. Dividing that increase by the original $4.0 million and multiplying by 100 gives 15%.","B":"12% would result from comparing the $0.6 million increase with the new $4.6 million figure. Percentage change must use the original $4.0 million as the base, giving 15%.","C":"6% is not supported by the data. An increase of $0.6 million on a base of $4.0 million is 15%, not six percent.","D":"60% would mean the revenue had grown by $2.4 million, which is far more than the actual $0.6 million rise. The correct percentage increase is 15%."}}},{"id":"P1_U1_MCQ_1774","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1774","question":"Two friends in Bergen run a management consultancy together. They share all profits and decisions and are each fully responsible for the firm's debts. Which legal structure do they have?","options":{"A":"A private limited company, because it is a consultancy","B":"A partnership, because two owners share profits and unlimited liability","C":"A public limited company, because they advise many clients","D":"A cooperative, because they work as a team"},"correctOption":"B","correctAnswer":"A partnership, because two owners share profits and unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Two people who jointly own a business, share its profits and have unlimited liability for its debts form a partnership. The Bergen consultancy fits that description precisely.","distractor_reasons":{"A":"A private limited company is a separate legal entity with limited liability and shares. The friends are personally responsible for debts, so the business is not a limited company.","B":"Two people who jointly own a business, share its profits and have unlimited liability for its debts form a partnership. The Bergen consultancy fits that description precisely.","C":"Having many clients does not create a public limited company. A plc requires shares traded publicly, which is not the case for this two-person consultancy.","D":"A cooperative is owned and democratically controlled by a wider group of members. Two friends sharing profits and liabilities constitute a partnership."}}},{"id":"P1_U1_MCQ_1775","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1775","question":"A fair-trade coffee cooperative in Addis Ababa sets the prices it pays farmers so that they receive a stable income, even though this means lower returns for the business. Which objective is the cooperative prioritising?","options":{"A":"Profit maximisation, because it wants the highest possible surplus","B":"Market leadership, because it wants to dominate coffee exports","C":"A social or ethical objective, because it aims to secure farmers' livelihoods","D":"Cost minimisation, because it wants to pay suppliers as little as possible"},"correctOption":"C","correctAnswer":"A social or ethical objective, because it aims to secure farmers' livelihoods","questionType":"MCQ","explanation":{"correct_reason":"The cooperative accepts lower returns in order to give farmers a stable income, putting the welfare of its members ahead of profit. That is a social or ethical objective.","distractor_reasons":{"A":"Profit maximisation would require keeping more of the revenue, but the cooperative deliberately pays farmers enough to reduce its own surplus. Profit is not the priority here.","B":"There is no mention of outcompeting other exporters or gaining market dominance. The aim described is supporting farmers' incomes, which is a social goal.","C":"The cooperative accepts lower returns in order to give farmers a stable income, putting the welfare of its members ahead of profit. That is a social or ethical objective.","D":"Paying farmers a stable income is the opposite of minimising supplier payments. The cooperative is choosing to pay more rather than less."}}},{"id":"P1_U1_MCQ_1776","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1776","question":"A farmer in Campinas grows sugarcane on land she owns, uses a tractor and hires workers to harvest the crop. Which set of factors of production is being used in this business?","options":{"A":"Land and labour only, because no machinery is mentioned","B":"Capital and enterprise only, because the crop is sold for profit","C":"Labour and land only, because the tractor is not used in farming","D":"Land from the field, capital from the tractor and labour from the hired workers"},"correctOption":"D","correctAnswer":"Land from the field, capital from the tractor and labour from the hired workers","questionType":"MCQ","explanation":{"correct_reason":"The field is land, the tractor is manufactured capital equipment and the hired workers provide labour. The farmer also shows enterprise by organising these resources to grow and sell sugarcane.","distractor_reasons":{"A":"A tractor is explicitly mentioned, and it is capital equipment. Ignoring it makes this answer incomplete, even though land and labour are also present.","B":"The land and the hired workers are clearly used, so capital and enterprise alone are not enough. The farmer's organising role is enterprise, but it is not the only factor.","C":"The tractor is used to harvest the crop and is a piece of capital. Saying it is not used in farming contradicts the scenario directly.","D":"The field is land, the tractor is manufactured capital equipment and the hired workers provide labour. The farmer also shows enterprise by organising these resources to grow and sell sugarcane."}}},{"id":"P1_U1_MCQ_1777","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1777","question":"In a province of Chiang Mai, 60,000 workers are employed: 15,000 in agriculture, 15,000 in manufacturing and 30,000 in services. What percentage of the workforce works in the tertiary sector?","options":{"A":"25%","B":"50%","C":"30%","D":"60%"},"correctOption":"B","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Services are tertiary sector activity, and 30,000 of the 60,000 workers are employed in them. Dividing 30,000 by 60,000 and multiplying by 100 gives 50%.","distractor_reasons":{"A":"25% is the share of the 15,000 agricultural workers, since 15,000 out of 60,000 is one quarter. Agriculture is primary, not the tertiary sector asked about.","B":"Services are tertiary sector activity, and 30,000 of the 60,000 workers are employed in them. Dividing 30,000 by 60,000 and multiplying by 100 gives 50%.","C":"30% does not match the data. The 30,000 service workers are half of the 60,000 total, so their share is 50% rather than 30%.","D":"60% would require 36,000 workers in services. There are 30,000, which is exactly half of the workforce, so the correct share is 50%."}}},{"id":"P1_U1_MCQ_1778","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1778","question":"A delivery firm in Tripoli has expanded by opening its own depots in four neighbouring cities, funding the expansion entirely from profits it retained. Which type of growth has the firm achieved?","options":{"A":"External growth, because it entered four new cities","B":"Takeover, because it now controls several depots","C":"Diversification, because it delivers to more places","D":"Organic growth, because it expanded using its own retained profits"},"correctOption":"D","correctAnswer":"Organic growth, because it expanded using its own retained profits","questionType":"MCQ","explanation":{"correct_reason":"Opening new depots with money generated by the business itself is organic or internal growth. No other firm was bought, so expansion came from the firm's own resources.","distractor_reasons":{"A":"External growth involves merging with or acquiring another business. The firm opened its own depots, so entering new cities alone does not make the growth external.","B":"A takeover means purchasing an existing company. The firm built new depots rather than buying rivals, so there has been no takeover.","C":"Delivering the same service to additional cities is market expansion, not diversification into different products or unrelated lines of business.","D":"Opening new depots with money generated by the business itself is organic or internal growth. No other firm was bought, so expansion came from the firm's own resources."}}},{"id":"P1_U1_MCQ_1779","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1779","question":"A tailor in Mombasa runs a small workshop alone, keeps all the profits and is personally responsible for every debt the business incurs. Which legal structure does the tailor's business have?","options":{"A":"A sole trader, because one person owns the business and has unlimited liability","B":"A partnership, because the tailor works with customers","C":"A private limited company, because profits are kept by the owner","D":"A public limited company, because the workshop serves the public"},"correctOption":"A","correctAnswer":"A sole trader, because one person owns the business and has unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"A single owner who keeps all profits and is personally liable for all debts is a sole trader. There is no separate legal entity, which is why the tailor's own resources back the business.","distractor_reasons":{"A":"A single owner who keeps all profits and is personally liable for all debts is a sole trader. There is no separate legal entity, which is why the tailor's own resources back the business.","B":"A partnership needs at least two owners who share profits. Serving customers does not create partners, so the tailor's one-person business is not a partnership.","C":"A private limited company is a separate legal entity with limited liability and shares. The tailor keeps all profits personally and has unlimited liability, so it is not a company.","D":"Trading with the public does not make a firm a public limited company. A plc requires publicly traded shares, which a small one-person workshop does not have."}}},{"id":"P1_U1_MCQ_1780","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1780","question":"A mining company in Kalgoorlie must decide whether to increase dividends for shareholders or spend more on safety equipment requested by employees and local residents. What does this decision illustrate?","options":{"A":"That shareholder objectives always take priority over all others","B":"That safety spending has no effect on the amount available as dividends","C":"A conflict between shareholders wanting higher dividends and employees and residents wanting greater safety","D":"Agreement between all stakeholders about how profits should be used"},"correctOption":"C","correctAnswer":"A conflict between shareholders wanting higher dividends and employees and residents wanting greater safety","questionType":"MCQ","explanation":{"correct_reason":"Money spent on safety equipment cannot also be paid out as dividends, so shareholders' wish for higher returns clashes with employees' and residents' wish for a safer operation. This is a stakeholder conflict.","distractor_reasons":{"A":"The scenario presents a choice rather than stating that shareholders always win. Stakeholder objectives compete, and no automatic priority is established.","B":"Safety spending uses company funds and therefore reduces what can be distributed. Claiming it has no effect on dividends ignores the trade-off at the heart of the decision.","C":"Money spent on safety equipment cannot also be paid out as dividends, so shareholders' wish for higher returns clashes with employees' and residents' wish for a safer operation. This is a stakeholder conflict.","D":"The stakeholders want different uses of the same money, so they are not in agreement. The decision highlights opposing objectives, not a shared view."}}},{"id":"P1_U1_MCQ_1781","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1781","question":"A potter in Faenza buys clay for $6 and glazes for $4 to make a vase, which she sells in her shop for $30. What is the value added by the potter for each vase?","options":{"A":"$20","B":"$10","C":"$24","D":"$30"},"correctOption":"A","correctAnswer":"$20","questionType":"MCQ","explanation":{"correct_reason":"The bought-in materials are $6 of clay and $4 of glazes, totalling $10. Subtracting this from the $30 selling price leaves $20, the value the potter adds through her shaping and decorating work.","distractor_reasons":{"A":"The bought-in materials are $6 of clay and $4 of glazes, totalling $10. Subtracting this from the $30 selling price leaves $20, the value the potter adds through her shaping and decorating work.","B":"$10 is the cost of the clay and glazes, the materials bought from other suppliers. Value added is the selling price less that cost, so it is $20 rather than $10.","C":"$24 would come from deducting only the $6 clay and ignoring the $4 glazes. Both are bought-in materials, so the full $10 must be subtracted from $30.","D":"$30 is the selling price of the vase, which is sales revenue. Value added requires deducting the $10 cost of bought-in materials from that price."}}},{"id":"P1_U1_MCQ_1782","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1782","question":"A fleet of small fishing boats in Reykjavik catches cod in northern waters and sells the catch at the quay without canning or processing it. Which sector of economic activity is this fleet in?","options":{"A":"Secondary, because the cod is later sold to a factory","B":"Primary, because it catches a natural resource from the sea","C":"Tertiary, because the boats unload at a quay","D":"Public, because fishing is controlled by quotas"},"correctOption":"B","correctAnswer":"Primary, because it catches a natural resource from the sea","questionType":"MCQ","explanation":{"correct_reason":"Catching cod from the sea is extracting a natural resource, which is the defining feature of primary sector activity. Selling the unprocessed catch at the quay does not change that classification.","distractor_reasons":{"A":"The fleet does not process the fish; it lands and sells them raw. Any later canning by a factory is a separate business, so the fishing boats remain primary.","B":"Catching cod from the sea is extracting a natural resource, which is the defining feature of primary sector activity. Selling the unprocessed catch at the quay does not change that classification.","C":"Unloading at a quay is not the provision of a service to customers. The fleet's activity is catching fish, a natural resource, so it is not tertiary.","D":"Fishing quotas are government regulations, but they do not make privately owned boats public. Ownership and activity determine the sector."}}},{"id":"P1_U1_MCQ_1783","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1783","question":"An entrepreneur in Dhaka started a small garment unit with her own savings and then used the profits it earned to open two more factories. Which feature of enterprise does this mainly illustrate?","options":{"A":"Risk avoidance, because she used savings rather than loans","B":"Imitation, because garment making is a common business","C":"Enterprise, because she organised resources and reinvested profits to expand","D":"Cost leadership, because she sells the cheapest garments"},"correctOption":"C","correctAnswer":"Enterprise, because she organised resources and reinvested profits to expand","questionType":"MCQ","explanation":{"correct_reason":"Enterprise involves combining resources, bearing risk and making decisions to grow a business. The entrepreneur organised a garment unit and reinvested its profits to open two more factories.","distractor_reasons":{"A":"Using savings does not remove risk, since her money would be lost if the venture failed. Taking that risk while building the business is part of enterprise.","B":"There is no evidence she copied another firm. Starting with savings and expanding through reinvested profits shows independent organising, not imitation.","C":"Enterprise involves combining resources, bearing risk and making decisions to grow a business. The entrepreneur organised a garment unit and reinvested its profits to open two more factories.","D":"The scenario says nothing about low prices or undercutting competitors. The focus is on how she organised and expanded the business, which is enterprise."}}},{"id":"P1_U1_MCQ_1784","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1784","question":"A family in Kyoto has registered its tea business as a company. The shares are held only by family members and are not available to the general public. What type of business organisation is this?","options":{"A":"A sole trader, because the family runs the business","B":"A partnership, because several relatives own the business","C":"A public limited company, because it is a registered company","D":"A private limited company, because its shares are privately held"},"correctOption":"D","correctAnswer":"A private limited company, because its shares are privately held","questionType":"MCQ","explanation":{"correct_reason":"A private limited company is a registered business whose shares cannot be offered to the public. The Kyoto tea company's shares are held only by family members, so it is a private limited company.","distractor_reasons":{"A":"A sole trader has a single owner and no registered company with shares. The tea business is a registered company with family shareholders, so it is not a sole trader.","B":"A partnership does not issue shares or register as a limited company in this way. The presence of privately held shares points to a private limited company.","C":"Registration alone does not create a public limited company. A plc must offer shares to the public, which the family explicitly does not do.","D":"A private limited company is a registered business whose shares cannot be offered to the public. The Kyoto tea company's shares are held only by family members, so it is a private limited company."}}},{"id":"P1_U1_MCQ_1785","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1785","question":"A museum in Krakow admitted 18,000 visitors last month, each paying $8, and had total costs of $110,000. What was the museum's surplus for the month?","options":{"A":"$34,000 deficit","B":"$34,000 surplus","C":"$110,000","D":"$144,000"},"correctOption":"B","correctAnswer":"$34,000 surplus","questionType":"MCQ","explanation":{"correct_reason":"Admission revenue is 18,000 visitors times $8, giving $144,000. After deducting total costs of $110,000, the museum is left with a surplus of $34,000 for the month.","distractor_reasons":{"A":"Revenue of $144,000 exceeds costs of $110,000, so the result is a surplus, not a deficit. A deficit would occur only if costs were greater than revenue.","B":"Admission revenue is 18,000 visitors times $8, giving $144,000. After deducting total costs of $110,000, the museum is left with a surplus of $34,000 for the month.","C":"$110,000 is the total cost figure. The surplus is found by subtracting this from the $144,000 admission revenue, leaving $34,000.","D":"$144,000 is the admission revenue calculated from 18,000 visitors at $8 each. It is not the surplus because the $110,000 of costs must be deducted."}}},{"id":"P1_U1_MCQ_1786","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1786","question":"A family in Beira has enough money this month for only one item: a sack of maize meal for the household or a new television for the living room. They buy the maize meal. Which statement correctly describes these two items?","options":{"A":"Both are needs because they are household purchases","B":"The television is a need and the maize meal is a want","C":"Both are wants because the family could survive without either","D":"Maize meal is a need because it provides food, while the television is a want"},"correctOption":"D","correctAnswer":"Maize meal is a need because it provides food, while the television is a want","questionType":"MCQ","explanation":{"correct_reason":"Food is necessary for the family's survival, so the maize meal is a need. A new television provides entertainment but is not essential, making it a want in this situation.","distractor_reasons":{"A":"Being a household purchase does not make something a need. The maize meal meets the basic requirement of food, whereas a television is an optional luxury for this family.","B":"The classifications are reversed. The maize meal supplies essential food and is the need, while a new television is a want the family can delay.","C":"The family cannot simply do without food, so maize meal is not a want. Only the television is discretionary, which is why the two items must be classified differently.","D":"Food is necessary for the family's survival, so the maize meal is a need. A new television provides entertainment but is not essential, making it a want in this situation."}}},{"id":"P1_U1_MCQ_1787","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1787","question":"A company in Karachi buys imported motorbike kits and assembles them into complete motorcycles, which it sells to local dealers. Which sector of economic activity does the company operate in?","options":{"A":"Secondary, because it turns components into finished motorcycles","B":"Primary, because the components were made from raw materials","C":"Tertiary, because it sells to dealers","D":"Public, because the roads are state owned"},"correctOption":"A","correctAnswer":"Secondary, because it turns components into finished motorcycles","questionType":"MCQ","explanation":{"correct_reason":"Assembling components into complete motorcycles is a manufacturing process that produces a finished good. That conversion of inputs into products is the defining feature of secondary sector activity.","distractor_reasons":{"A":"Assembling components into complete motorcycles is a manufacturing process that produces a finished good. That conversion of inputs into products is the defining feature of secondary sector activity.","B":"The company assembles bought-in kits; it does not extract raw materials. The earlier production of components belongs to other firms, so this company's own activity is secondary.","C":"Selling to dealers is only the final step. The core activity is assembling motorcycles, so the company is classified as secondary rather than tertiary.","D":"State ownership of roads has no bearing on the company sector. Its core activity of assembling motorcycles determines its classification as secondary."}}},{"id":"P1_U1_MCQ_1788","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1788","question":"A bakery chain in Wellington has opened new outlets in several suburbs, paying for all of them out of profits it retained rather than borrowing or buying competitors. Which type of growth has taken place?","options":{"A":"External growth, because new suburbs were entered","B":"Takeover, because several outlets are now controlled","C":"Organic growth, because retained profits funded new outlets","D":"Diversification, because the chain now serves more customers"},"correctOption":"C","correctAnswer":"Organic growth, because retained profits funded new outlets","questionType":"MCQ","explanation":{"correct_reason":"Organic growth means expanding the existing business using its own resources. The Wellington chain funded new outlets from retained profits and did not acquire any other firm.","distractor_reasons":{"A":"Entering new suburbs is geographic expansion, but external growth requires a merger or takeover. Since the chain opened its own outlets, growth is organic.","B":"A takeover means buying an established business. Controlling several outlets that the chain built itself is not a takeover of other companies.","C":"Organic growth means expanding the existing business using its own resources. The Wellington chain funded new outlets from retained profits and did not acquire any other firm.","D":"Serving more customers is a result of expansion, not diversification. The chain still sells the same bakery products, so it has not moved into a different line of business."}}},{"id":"P1_U1_MCQ_1789","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1789","question":"A company in Porto has 200,000 ordinary shares in issue and has declared a total dividend of $90,000. What dividend will a shareholder receive per share?","options":{"A":"$0.45","B":"$0.90","C":"$2.22","D":"$0.40"},"correctOption":"A","correctAnswer":"$0.45","questionType":"MCQ","explanation":{"correct_reason":"The total dividend of $90,000 is divided among 200,000 shares. The result is $0.45 per share, which is the amount paid to an owner of each ordinary share.","distractor_reasons":{"A":"The total dividend of $90,000 is divided among 200,000 shares. The result is $0.45 per share, which is the amount paid to an owner of each ordinary share.","B":"$0.90 would be the dividend per share if only 100,000 shares were in issue. With 200,000 shares sharing $90,000, the payment is $0.45.","C":"$2.22 comes from dividing 200,000 shares by $90,000, which is the wrong way round. Dividend per share is total dividend divided by the number of shares.","D":"$0.40 would require a total dividend of $80,000 across 200,000 shares. The declared amount is $90,000, so each share earns $0.45."}}},{"id":"P1_U1_MCQ_1790","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1790","question":"The directors of a steelworks in Santander are considering closing an old plant to reduce costs and protect dividends, even though 200 workers would lose their jobs. Which stakeholder groups bear the cost of this decision?","options":{"A":"Shareholders, because they receive lower dividends","B":"Employees and the local community, because jobs disappear","C":"Customers, because steel prices would rise","D":"Suppliers, because they would receive smaller orders"},"correctOption":"B","correctAnswer":"Employees and the local community, because jobs disappear","questionType":"MCQ","explanation":{"correct_reason":"Closing the plant saves money for shareholders but removes 200 jobs, so workers lose their incomes and the surrounding community loses employment and spending. They bear the cost of the decision.","distractor_reasons":{"A":"Shareholders are the ones protected by the decision, since dividends are maintained. The group that loses out is the workforce and the community around the plant.","B":"Closing the plant saves money for shareholders but removes 200 jobs, so workers lose their incomes and the surrounding community loses employment and spending. They bear the cost of the decision.","C":"Steel prices are not mentioned and would not necessarily rise. The clear cost described in the scenario is the loss of 200 jobs, not a change in prices.","D":"Supplier orders may change, but the scenario does not discuss them. The stakeholders explicitly affected are the workers facing redundancy and their community."}}},{"id":"P1_U1_MCQ_1791","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1791","question":"A cooperative in Palermo processes tomatoes into passata and sells jars to supermarkets. Which factor of production is represented by the pasta-making machines and bottling line in its factory?","options":{"A":"Land, because the machines are made from metal","B":"Labour, because the machines replace the workers","C":"Capital, because they are manufactured aids used in production","D":"Enterprise, because the machines decide what to produce"},"correctOption":"C","correctAnswer":"Capital, because they are manufactured aids used in production","questionType":"MCQ","explanation":{"correct_reason":"Capital refers to manufactured items used to produce other goods, such as machinery and equipment. The machines and bottling line in the Palermo factory are capital goods used to make passata.","distractor_reasons":{"A":"Land means natural resources like the tomatoes themselves, not manufactured equipment. Although machines are made of metal, they are produced aids and therefore capital.","B":"Machines may assist workers, but labour is the human effort employees contribute. The people operating the line provide labour; the machines are capital equipment.","C":"Capital refers to manufactured items used to produce other goods, such as machinery and equipment. The machines and bottling line in the Palermo factory are capital goods used to make passata.","D":"Enterprise is the organising and risk-taking role of the cooperative's members. Machines cannot make decisions or take risks, so they are not enterprise."}}},{"id":"P1_U1_MCQ_1792","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1792","question":"A university in Utrecht provides teaching and research services, funded by student fees and government grants. Which sector of economic activity does this university belong to?","options":{"A":"Primary, because it produces new knowledge","B":"Secondary, because it publishes books","C":"Public, because all universities are government owned","D":"Tertiary, because it provides education services"},"correctOption":"D","correctAnswer":"Tertiary, because it provides education services","questionType":"MCQ","explanation":{"correct_reason":"Education is a service provided to students, so the university's main activity is tertiary. Funding from fees and grants does not change the fact that it delivers an intangible service.","distractor_reasons":{"A":"Producing knowledge is not the extraction of natural resources. Primary sector means activities like farming and mining, which are quite different from teaching and research.","B":"Publishing books may happen, but it is a support activity. The university's core output is education, a service, so it is not a secondary sector manufacturer.","C":"Not all universities are government owned, and the scenario does not say this one is. Sector classification by activity makes the university tertiary regardless of its funding.","D":"Education is a service provided to students, so the university's main activity is tertiary. Funding from fees and grants does not change the fact that it delivers an intangible service."}}},{"id":"P1_U1_MCQ_1793","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1793","question":"A company in Ghent increased its workforce from 240 employees to 276 during the year. What was the percentage increase in the number of employees?","options":{"A":"10%","B":"15%","C":"36%","D":"12%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The company took on 36 extra staff, since 276 minus 240 is 36. Dividing the increase of 36 by the original 240 employees and multiplying by 100 gives 15%.","distractor_reasons":{"A":"10% would require an increase of 24 employees on a base of 240. The actual increase is 36, so the growth in workforce is 15%.","B":"The company took on 36 extra staff, since 276 minus 240 is 36. Dividing the increase of 36 by the original 240 employees and multiplying by 100 gives 15%.","C":"36 is the number of additional employees, not a percentage. To express it as a percentage, it must be divided by the original workforce of 240, giving 15%.","D":"12% would result from dividing 36 by the new total of 276 or from another wrong base. Percentage growth uses the original 240 employees, producing 15%."}}},{"id":"P1_U1_MCQ_1794","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1794","question":"A sole trader in Blantyre wants to expand her tailoring business, protect her personal assets from creditors and raise money from investors, while keeping the shares away from the general public. Which structure should she adopt?","options":{"A":"Stay a sole trader, because expansion does not need outside finance","B":"Form a partnership, because partners have limited liability","C":"Become a public limited company, because it can raise capital easily","D":"Register a private limited company, which offers limited liability and private shares"},"correctOption":"D","correctAnswer":"Register a private limited company, which offers limited liability and private shares","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives limited liability to protect personal assets and can issue shares to investors without offering them to the public, matching all three of the trader's requirements.","distractor_reasons":{"A":"Remaining a sole trader would leave personal assets exposed to business debts and make outside investment difficult. It fails to meet the trader's stated needs.","B":"Partners generally have unlimited liability, so a partnership would not protect the trader's personal assets. The requirement for limited liability points to a limited company.","C":"A public limited company can raise capital from the public, but the trader wants shares kept private. A private limited company is the suitable structure.","D":"A private limited company gives limited liability to protect personal assets and can issue shares to investors without offering them to the public, matching all three of the trader's requirements."}}},{"id":"P1_U1_MCQ_1795","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1795","question":"A cosmetics brand in Copenhagen promises that none of its products is tested on animals and pays fair prices to the farmers who supply its ingredients, even though this raises costs. Which objective is the brand pursuing?","options":{"A":"Ethical and social responsibility, because it puts principles ahead of lower costs","B":"Profit maximisation, because higher costs always increase profit","C":"Market leadership, because it aims to be the largest cosmetics firm","D":"Survival, because it is struggling to cover its costs"},"correctOption":"A","correctAnswer":"Ethical and social responsibility, because it puts principles ahead of lower costs","questionType":"MCQ","explanation":{"correct_reason":"The brand accepts higher costs to avoid animal testing and pay farmers fairly, placing ethical principles ahead of cheap production. That is an ethical and social responsibility objective.","distractor_reasons":{"A":"The brand accepts higher costs to avoid animal testing and pay farmers fairly, placing ethical principles ahead of cheap production. That is an ethical and social responsibility objective.","B":"Profit maximisation would encourage cutting costs, while the brand knowingly accepts higher costs. The scenario gives no sign that higher costs raise profit.","C":"There is no mention of becoming the largest firm or outselling rivals. The brand's distinguishing feature is its ethical standards, not market dominance.","D":"Survival means covering costs to stay in business, but the brand is deliberately taking on extra costs for ethical reasons. That is a positive choice, not a struggle to survive."}}},{"id":"P1_U1_MCQ_1796","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1796","question":"A farmer in Isfahan spends the day selling apples at the market. She could instead have earned a wage teaching at a local school that day. The teaching wage she gave up is an example of what?","options":{"A":"An explicit cost, because the school pays a wage","B":"A revenue figure, because the apples were sold","C":"An opportunity cost, because it is the value of the next best alternative forgone","D":"A fixed cost, because it does not depend on the apple harvest"},"correctOption":"C","correctAnswer":"An opportunity cost, because it is the value of the next best alternative forgone","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the benefit of the next best option that is given up. By choosing to sell apples, the farmer forgoes the teaching wage, so that wage is the opportunity cost of her choice.","distractor_reasons":{"A":"An explicit cost involves an actual payment made by the business. She did not pay the school; she simply missed the chance to earn there, which is an opportunity cost.","B":"Revenue from apples is the benefit of the chosen activity, not the cost of the decision. The concept being tested is the teaching wage she did not receive.","C":"Opportunity cost is the benefit of the next best option that is given up. By choosing to sell apples, the farmer forgoes the teaching wage, so that wage is the opportunity cost of her choice.","D":"A fixed cost does not vary with output, but the teaching wage is not a cost of the farm at all. It represents the value of an alternative use of her day."}}},{"id":"P1_U1_MCQ_1797","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1797","question":"In a district of Kutaisi, 80,000 people work: 20,000 in farming, 32,000 in factories and 28,000 in shops and services. What percentage of workers are in the primary sector?","options":{"A":"25%","B":"20%","C":"40%","D":"35%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Farming is the primary sector, with 20,000 workers out of a total of 80,000. Dividing 20,000 by 80,000 and multiplying by 100 gives 25%.","distractor_reasons":{"A":"Farming is the primary sector, with 20,000 workers out of a total of 80,000. Dividing 20,000 by 80,000 and multiplying by 100 gives 25%.","B":"20% does not match the figures. The 20,000 farm workers are one quarter of the 80,000 total, so the primary sector share is 25%, not 20%.","C":"40% is the share of the 32,000 factory workers, since 32,000 out of 80,000 is 40%. Factories are secondary, while the question asks about the primary sector.","D":"35% is close to the services share of 28,000 out of 80,000, which is 35%. Services are tertiary, so this is not the primary sector figure."}}},{"id":"P1_U1_MCQ_1798","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1798","question":"An entrepreneur in Amman noticed that office workers struggled to find affordable lunches near their workplaces and opened a chain of low-priced meal kiosks. Which entrepreneurial characteristic does this show most clearly?","options":{"A":"Risk avoidance, because the meals are inexpensive","B":"Opportunity recognition, because she spotted an unmet customer need","C":"Imitation, because other kiosks already exist","D":"Cost leadership, because she buys food cheaply"},"correctOption":"B","correctAnswer":"Opportunity recognition, because she spotted an unmet customer need","questionType":"MCQ","explanation":{"correct_reason":"She observed that workers could not find affordable lunches and created kiosks to meet that need. Spotting a gap in the market and taking action to fill it is opportunity recognition.","distractor_reasons":{"A":"Opening a new chain involves financial risk regardless of how cheap the meals are. The scenario does not suggest she avoided risk, so this is not the quality shown.","B":"She observed that workers could not find affordable lunches and created kiosks to meet that need. Spotting a gap in the market and taking action to fill it is opportunity recognition.","C":"Nothing in the scenario says she copied existing kiosks. She identified a gap and acted on it, which is opportunity recognition rather than imitation.","D":"Low prices are part of her offering, but the key point is that she noticed an unmet need. Cost leadership is not evidenced by buying food cheaply in the description."}}},{"id":"P1_U1_MCQ_1799","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1799","question":"A manufacturing company in Hamburg wants to raise a large sum of capital by selling shares to the general public and having those shares traded on a stock exchange. Which legal structure does it need?","options":{"A":"A sole trader, because it is owned by one person","B":"A private limited company, because it is a registered business","C":"A public limited company, because its shares can be traded publicly","D":"A partnership, because several people will invest"},"correctOption":"C","correctAnswer":"A public limited company, because its shares can be traded publicly","questionType":"MCQ","explanation":{"correct_reason":"Only a public limited company may invite the public to buy its shares and have them traded on a stock exchange, which is how the Hamburg firm plans to raise large amounts of capital.","distractor_reasons":{"A":"A sole trader has one owner and cannot issue shares at all. The plan to sell shares to the public rules out sole trader status completely.","B":"A private limited company cannot offer shares to the general public. Since the firm specifically wants public trading, it must become a public limited company.","C":"Only a public limited company may invite the public to buy its shares and have them traded on a stock exchange, which is how the Hamburg firm plans to raise large amounts of capital.","D":"Partners do not issue publicly traded shares. The ability to sell shares on a stock exchange is a defining feature of a public limited company."}}},{"id":"P1_U1_MCQ_1800","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1800","question":"A brewery in Tabor is considering replacing its traditional recipe with cheaper ingredients to raise dividends. Long-standing customers have said they would stop buying if the taste changed. What does this illustrate?","options":{"A":"That customers always agree with shareholders about product changes","B":"That changing a recipe has no effect on customer loyalty","C":"Agreement between all stakeholders on how to increase dividends","D":"A conflict between shareholders seeking higher dividends and customers wanting the traditional recipe kept"},"correctOption":"D","correctAnswer":"A conflict between shareholders seeking higher dividends and customers wanting the traditional recipe kept","questionType":"MCQ","explanation":{"correct_reason":"Shareholders want higher dividends from cheaper ingredients, but customers value the traditional taste and threaten to stop buying. These opposing stakeholder objectives show a clear conflict over the brewery's recipe.","distractor_reasons":{"A":"Customers and shareholders do not agree here: shareholders favour cheaper ingredients while customers want the traditional recipe retained. Their objectives clearly clash.","B":"The customers have explicitly said they would stop buying if the taste changed, so the recipe change does affect loyalty. This option contradicts the scenario.","C":"There is no agreement: shareholders want the cost savings while customers want the original recipe kept. The situation is a dispute, not a shared view on dividends.","D":"Shareholders want higher dividends from cheaper ingredients, but customers value the traditional taste and threaten to stop buying. These opposing stakeholder objectives show a clear conflict over the brewery's recipe."}}},{"id":"P1_U1_MCQ_1801","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1801","question":"Nyakio Weavers Ltd in Kisumu, Kenya sells handwoven baskets for $48,000 a year. During the year it buys $17,500 of rattan and dyes. What is the value added by the business?","options":{"A":"$17,500","B":"$30,500","C":"$48,000","D":"$65,500"},"correctOption":"B","correctAnswer":"$30,500","questionType":"MCQ","explanation":{"correct_reason":"Value added is sales revenue minus the cost of bought-in materials. Nyakio Weavers receives $48,000 from selling baskets and spends $17,500 on rattan and dyes, so $48,000 minus $17,500 leaves $30,500 of value added by its own work.","distractor_reasons":{"A":"$17,500 is simply the spend on rattan and dyes, the bought-in materials, rather than the extra value the workers create by weaving and selling the baskets.","B":"Value added is sales revenue minus the cost of bought-in materials. Nyakio Weavers receives $48,000 from selling baskets and spends $17,500 on rattan and dyes, so $48,000 minus $17,500 leaves $30,500 of value added by its own work.","C":"$48,000 is the total sales revenue from baskets, not value added, because it still includes the $17,500 cost of the materials that had to be bought in.","D":"$65,500 wrongly adds revenue and material costs together; value added subtracts bought-in costs from sales income rather than adding the two amounts."}}},{"id":"P1_U1_MCQ_1802","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1802","question":"A workforce survey of businesses in Luanda, Angola counted 2,500 workers: 400 in farming and fishing, 900 in manufacturing, and the rest in shops, transport and services. What percentage work in the tertiary sector?","options":{"A":"16%","B":"36%","C":"48%","D":"52%"},"correctOption":"C","correctAnswer":"48%","questionType":"MCQ","explanation":{"correct_reason":"The tertiary count is the remainder: 2,500 minus 400 minus 900 equals 1,200 workers in shops, transport and services. Dividing 1,200 by the 2,500 total gives 0.48, so 48% of the workers are in the tertiary sector.","distractor_reasons":{"A":"16% is the share in farming and fishing, 400 out of 2,500, which belongs to the primary sector and not to the service-based tertiary sector in the question.","B":"36% is the manufacturing share, 900 out of 2,500, which belongs to the secondary sector and leaves out the shops, transport and service workers altogether.","C":"The tertiary count is the remainder: 2,500 minus 400 minus 900 equals 1,200 workers in shops, transport and services. Dividing 1,200 by the 2,500 total gives 0.48, so 48% of the workers are in the tertiary sector.","D":"52% would require 1,300 tertiary workers, but subtracting the 400 primary and 900 secondary workers from 2,500 actually leaves 1,200, which is 48% of the total."}}},{"id":"P1_U1_MCQ_1803","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1803","question":"Usha Solar Ltd in Jaipur, India installed solar panels for households and grew from 250 employees to 320 employees in two years. What was the percentage increase in its workforce over those two years?","options":{"A":"28%","B":"22%","C":"70%","D":"12%"},"correctOption":"A","correctAnswer":"28%","questionType":"MCQ","explanation":{"correct_reason":"The rise in employees is 320 minus 250, which is 70 extra workers. Measured against the original 250 employees, 70 divided by 250 equals 0.28, so the workforce grew by 28% over the two years.","distractor_reasons":{"A":"The rise in employees is 320 minus 250, which is 70 extra workers. Measured against the original 250 employees, 70 divided by 250 equals 0.28, so the workforce grew by 28% over the two years.","B":"22% uses the new total of 320 as the denominator, 70 divided by 320, but a percentage increase must always be calculated against the starting figure of 250 employees.","C":"70 is only the absolute number of extra workers taken on, not a percentage; the question asks for the growth measured relative to the original workforce of 250.","D":"12% does not follow from these figures. The increase of 70 workers against the original 250 gives 28%, not a figure anywhere close to twelve percent."}}},{"id":"P1_U1_MCQ_1804","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1804","question":"Alvarez, Reyes and Santos trade as a partnership in Manila, Philippines, sharing profits in the ratio 2:3:5. The partnership earns $120,000 profit this year. How much does Santos, who has the largest share, receive?","options":{"A":"$24,000","B":"$36,000","C":"$40,000","D":"$60,000"},"correctOption":"D","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"The parts of the ratio add up to 2 plus 3 plus 5, which is 10 parts in total. Santos holds 5 of those 10 parts, so the share is 5/10 of the $120,000 profit, giving Santos $60,000.","distractor_reasons":{"A":"$24,000 is two tenths of the profit and would belong to the partner with the smallest share in the 2:3:5 split, not to Santos with the largest share.","B":"$36,000 represents three tenths of $120,000, which is the middle partner's portion under the agreed ratio, rather than the largest portion received by Santos.","C":"$40,000 would be the answer if the $120,000 were divided equally among the three partners, but the agreed 2:3:5 ratio instead gives Santos $60,000.","D":"The parts of the ratio add up to 2 plus 3 plus 5, which is 10 parts in total. Santos holds 5 of those 10 parts, so the share is 5/10 of the $120,000 profit, giving Santos $60,000."}}},{"id":"P1_U1_MCQ_1805","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1805","question":"Longbrook Coffee Ltd in Bristol, United Kingdom aims to earn at least $15,000 profit each month. Last month its revenue was $62,000 and its total costs were $49,500. By how much did it fall short of, or exceed, that profit objective?","options":{"A":"$12,500 above target","B":"$2,500 above target","C":"$2,500 below target","D":"$12,500 below target"},"correctOption":"C","correctAnswer":"$2,500 below target","questionType":"MCQ","explanation":{"correct_reason":"Profit is $62,000 revenue minus $49,500 of costs, which gives $12,500. Set against the $15,000 monthly objective, that is $2,500 short, so the cafe finished $2,500 below its profit target.","distractor_reasons":{"A":"$12,500 is the actual profit earned, not the gap against the objective. The cafe hoped for $15,000, so it did not exceed the target by its entire profit figure.","B":"$2,500 above target reverses the comparison: a profit of $12,500 is less than the $15,000 goal, so the business is below the objective, not above it.","C":"Profit is $62,000 revenue minus $49,500 of costs, which gives $12,500. Set against the $15,000 monthly objective, that is $2,500 short, so the cafe finished $2,500 below its profit target.","D":"$12,500 below target confuses the profit with the shortfall. The deficit against the $15,000 aim comes to just $2,500, not the whole profit amount."}}},{"id":"P1_U1_MCQ_1806","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1806","question":"Red River Furniture Ltd in Hanoi, Vietnam splits its production into cutting, sanding, assembly and finishing, with each worker repeating only one of these tasks. What is this arrangement of work called?","options":{"A":"Division of labour","B":"Diversification","C":"Job enrichment","D":"Diseconomies of scale"},"correctOption":"A","correctAnswer":"Division of labour","questionType":"MCQ","explanation":{"correct_reason":"Breaking the making of furniture into separate cutting, sanding, assembly and finishing tasks, each repeated by one worker, is division of labour. It raises output speed and skill because workers specialise in a narrow job.","distractor_reasons":{"A":"Breaking the making of furniture into separate cutting, sanding, assembly and finishing tasks, each repeated by one worker, is division of labour. It raises output speed and skill because workers specialise in a narrow job.","B":"Diversification means moving into different products or markets, which is not happening here. The Hanoi factory still makes the same furniture, only the tasks have been split up.","C":"Job enrichment would widen a worker's duties and give more varied, responsible tasks, the opposite of repeating one narrow step such as sanding all day in this factory.","D":"Diseconomies of scale refer to rising average costs as a whole firm becomes too large; they do not describe splitting production into separate tasks among workers."}}},{"id":"P1_U1_MCQ_1807","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1807","question":"Nervion Components Ltd in Bilbao, Spain imports steel and presses it into car body panels for vehicle makers. Which sector of the economy does this activity belong to?","options":{"A":"Primary sector","B":"Tertiary sector","C":"Voluntary sector","D":"Secondary sector"},"correctOption":"D","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Turning imported steel into car body panels is manufacturing, which is the secondary sector. The business takes a raw material and changes its form into a finished component for vehicle makers, rather than extracting or selling services.","distractor_reasons":{"A":"The primary sector covers extraction of natural materials such as mining ore or growing crops, whereas this Bilbao firm buys steel and processes it into panels.","B":"The tertiary sector provides services such as transport or retail, but pressing steel into car body panels produces a physical manufactured good, which is secondary activity.","C":"The voluntary sector consists of charities and non-profit bodies, while this company manufactures components for vehicle makers and operates as a business.","D":"Turning imported steel into car body panels is manufacturing, which is the secondary sector. The business takes a raw material and changes its form into a finished component for vehicle makers, rather than extracting or selling services."}}},{"id":"P1_U1_MCQ_1808","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1808","question":"Golden Crust Bakeries in Krakow, Poland financed twelve new outlets over three years using its own retained profits, without borrowing or buying another company. Which route to growth does this describe?","options":{"A":"A merger","B":"Organic growth","C":"A takeover","D":"A joint venture"},"correctOption":"B","correctAnswer":"Organic growth","questionType":"MCQ","explanation":{"correct_reason":"Expanding by opening twelve new outlets funded from retained profits, without acquiring another firm, is organic growth. The bakery builds its own capacity from internal resources rather than combining with a rival.","distractor_reasons":{"B":"Expanding by opening twelve new outlets funded from retained profits, without acquiring another firm, is organic growth. The bakery builds its own capacity from internal resources rather than combining with a rival.","A":"A merger involves two existing businesses agreeing to combine, which did not happen here; the Krakow bakery simply opened new outlets of its own using retained profits.","C":"A takeover means buying control of another company, but this firm neither borrowed nor purchased a rival, growing instead through its own twelve new branches.","D":"A joint venture requires a separate business set up jointly with another party, whereas this bakery expanded alone using its own funds in Krakow."}}},{"id":"P1_U1_MCQ_1809","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1809","question":"Northern Maple Foods Plc in Toronto, Canada sells its shares to the public on a stock exchange and is owned by several thousand shareholders. Which legal structure does this describe?","options":{"A":"Sole trader","B":"Partnership","C":"Public limited company","D":"Cooperative"},"correctOption":"C","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"A company whose shares trade publicly on a stock exchange and which has thousands of shareholders is a public limited company. Public share ownership and limited liability are the defining features described in this case.","distractor_reasons":{"A":"A sole trader has one private owner and cannot sell shares to the public, so it cannot describe a company with several thousand shareholders quoted on an exchange.","B":"A partnership is owned by a small group of partners who share profits, not by thousands of shareholders holding publicly traded shares as in this case.","C":"A company whose shares trade publicly on a stock exchange and which has thousands of shareholders is a public limited company. Public share ownership and limited liability are the defining features described in this case.","D":"A cooperative is owned and voted on by its members, often on a one-member-one-vote basis, rather than by shareholders buying publicly listed shares."}}},{"id":"P1_U1_MCQ_1810","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1810","question":"Chenab Cotton Farm near Multan, Pakistan wants to use more fertiliser to raise yields and profits, but the local water authority warns that runoff will pollute the river used by villagers. Which stakeholder conflict is shown?","options":{"A":"Employees versus customers","B":"The farm owner's profit goal versus the local community's environmental interest","C":"Suppliers versus managers","D":"Competitors versus shareholders"},"correctOption":"B","correctAnswer":"The farm owner's profit goal versus the local community's environmental interest","questionType":"MCQ","explanation":{"correct_reason":"The owner wants higher yields and profit from extra fertiliser, while villagers and the water authority want a clean river. The clash is between the farm's profit objective and the local community's interest in an unpolluted environment.","distractor_reasons":{"A":"Employees and customers are not the groups in dispute here; the described tension is between the farm's profit aim and the villagers' concern about river pollution.","B":"The owner wants higher yields and profit from extra fertiliser, while villagers and the water authority want a clean river. The clash is between the farm's profit objective and the local community's interest in an unpolluted environment.","C":"No disagreement between suppliers and managers is mentioned. The conflict concerns fertiliser runoff affecting the river and the community that depends on it.","D":"Competitors and shareholders are not central to this case; the scenario sets the farm's pursuit of profit against the environmental wishes of local residents."}}},{"id":"P1_U1_MCQ_1811","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1811","question":"Aissa Tayal runs Sunrise Tailoring Ltd in Dakar, Senegal. She buys cloth, uses a sewing machine and her own labour, and takes the risk of selling dresses in the market. What do these inputs illustrate?","options":{"A":"Division of labour","B":"Specialisation by task","C":"Market segmentation","D":"The factors of production"},"correctOption":"D","correctAnswer":"The factors of production","questionType":"MCQ","explanation":{"correct_reason":"Cloth and the workplace are land or raw materials, the sewing machine is capital, Aissa's work is labour, and her risk-taking and organising are enterprise. Together these are the factors of production used to make dresses.","distractor_reasons":{"A":"Division of labour means splitting the dressmaking into separate tasks among workers, which is not described; the case lists the types of input used by one business.","B":"Specialisation by task would involve each worker focusing on one stage of production, whereas this scenario identifies the broad categories of resource the tailor combines.","C":"Market segmentation divides customers into distinct groups, which is a marketing idea and has nothing to do with the cloth, machine, labour and enterprise listed here.","D":"Cloth and the workplace are land or raw materials, the sewing machine is capital, Aissa's work is labour, and her risk-taking and organising are enterprise. Together these are the factors of production used to make dresses."}}},{"id":"P1_U1_MCQ_1812","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1812","question":"North Atlantic Catch Ltd operates a small fleet from Reykjavik, Iceland, catching cod at sea and selling the fish to restaurants. Which economic sector is this business in?","options":{"A":"Primary sector","B":"Secondary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"A","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Catching cod from the sea is the extraction of a natural resource, which places the fleet in the primary sector. The business obtains a raw natural product rather than manufacturing goods or providing a service.","distractor_reasons":{"A":"Catching cod from the sea is the extraction of a natural resource, which places the fleet in the primary sector. The business obtains a raw natural product rather than manufacturing goods or providing a service.","B":"The secondary sector processes materials into manufactured goods, but this Icelandic fleet simply harvests fish from the sea and does not turn them into processed products.","C":"The tertiary sector covers services such as transport or retail, whereas catching fish is the direct extraction of a natural resource and therefore belongs to the primary sector.","D":"The public sector involves government-owned bodies, yet this is a privately run fishing business operating its own fleet from Reykjavik."}}},{"id":"P1_U1_MCQ_1813","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1813","question":"Kalev Couriers Ltd in Tallinn, Estonia has bought a smaller delivery firm offering the same service in the same city, hoping to raise its market share. What type of growth has taken place?","options":{"A":"Market development","B":"Organic growth","C":"Horizontal integration","D":"Diversification"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Buying a rival that provides the same delivery service in the same market is horizontal integration. The two businesses operate at the same stage of activity, so the takeover simply enlarges the firm's share of existing customers.","distractor_reasons":{"A":"Market development means taking existing products into new markets, but the acquired firm serves the same Tallinn market and the same delivery service, not a new one.","B":"Organic growth means expanding through one's own new outlets or sales, whereas here the courier firm grew by purchasing an existing competing business.","C":"Buying a rival that provides the same delivery service in the same market is horizontal integration. The two businesses operate at the same stage of activity, so the takeover simply enlarges the firm's share of existing customers.","D":"Diversification would mean moving into unrelated products or markets, which is not the case when one courier buys another courier in the same city."}}},{"id":"P1_U1_MCQ_1814","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1814","question":"A graduate in Nairobi, Kenya pays an annual fee to a well-known coffee brand for the right to use its name, recipes and training, while owning and running her own outlet. What arrangement is this?","options":{"A":"A partnership","B":"A franchise","C":"A public limited company","D":"A cooperative"},"correctOption":"B","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"Paying a fee to use an established brand's name, recipes and support while running one's own outlet is franchising. The owner gains a recognised formula and training in exchange for fees and following the brand's rules.","distractor_reasons":{"A":"A partnership involves shared ownership and profits between partners, but here the graduate owns her outlet alone and merely licenses the coffee brand's name.","B":"Paying a fee to use an established brand's name, recipes and support while running one's own outlet is franchising. The owner gains a recognised formula and training in exchange for fees and following the brand's rules.","C":"A public limited company sells shares to the public, which is not described; this is an independently owned single outlet paying to use another firm's brand.","D":"A cooperative is jointly owned and democratically run by its members, unlike this arrangement where one owner pays an external brand for the right to trade under its name."}}},{"id":"P1_U1_MCQ_1815","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1815","question":"Sarno Bakers, a family bakery in Naples, Italy, has watched sales fall for six months and is now focused on covering its costs so that it can keep trading into next year. What is its main objective at present?","options":{"A":"Survival","B":"Market leadership","C":"Profit maximisation","D":"Social responsibility"},"correctOption":"A","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"When a firm concentrates on covering costs after falling sales so it can continue trading, its objective is survival. The bakery is protecting its ability to operate rather than chasing growth or the largest possible profit.","distractor_reasons":{"A":"When a firm concentrates on covering costs after falling sales so it can continue trading, its objective is survival. The bakery is protecting its ability to operate rather than chasing growth or the largest possible profit.","B":"Market leadership means being the biggest or most successful competitor, which is unrealistic for a bakery whose sales have fallen for six months and is only covering costs.","C":"Profit maximisation seeks the highest possible profit, but this family bakery is content merely to meet its costs and stay open, which indicates a survival objective.","D":"Social responsibility involves prioritising wider benefits such as community or environment, which is not mentioned; the bakery's concern is staying in business."}}},{"id":"P1_U1_MCQ_1816","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1816","question":"Lapu Service Centre Ltd in Cebu, Philippines trains its agents so that one group handles only billing questions and another only technical support, with each agent repeating the same type of call. What is the main benefit of this arrangement?","options":{"A":"Higher wages for every agent","B":"No training would be needed at all","C":"Greater variety in each agent's daily work","D":"Faster, more consistent service through repetition"},"correctOption":"D","correctAnswer":"Faster, more consistent service through repetition","questionType":"MCQ","explanation":{"correct_reason":"Splitting calls into billing and technical support lets each agent specialise and become expert through repetition, so queries are handled faster and more consistently. Specialisation is the source of the benefit described in this centre.","distractor_reasons":{"A":"Higher wages are not guaranteed by dividing the calls; the benefit of specialisation here is speed and consistency of service, not a change in the agents' pay.","B":"Training is still required, indeed the case says agents are trained, so it is wrong to claim that dividing work removes the need for any training whatsoever.","C":"The arrangement reduces variety because each agent handles only one type of call, so greater variety in daily work cannot be the benefit being described.","D":"Splitting calls into billing and technical support lets each agent specialise and become expert through repetition, so queries are handled faster and more consistently. Specialisation is the source of the benefit described in this centre."}}},{"id":"P1_U1_MCQ_1817","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1817","question":"Akwaaba Mobile Ltd competes privately in Accra, Ghana, selling mobile services, while the government owns the national electricity grid and regulates both industries. Which economic system does this illustrate?","options":{"A":"A pure command economy","B":"A mixed economy","C":"A free market economy with no state involvement","D":"A traditional barter economy"},"correctOption":"B","correctAnswer":"A mixed economy","questionType":"MCQ","explanation":{"correct_reason":"Private competition from the mobile firm alongside government ownership of electricity and regulation is a mixed economy. Both market forces and state involvement shape activity, rather than one side controlling everything.","distractor_reasons":{"A":"A command economy would have the state directing all production, but here a private company competes freely in the mobile market, so the system is not purely command-based.","B":"Private competition from the mobile firm alongside government ownership of electricity and regulation is a mixed economy. Both market forces and state involvement shape activity, rather than one side controlling everything.","C":"A free market with no state involvement is contradicted by the government owning the electricity grid and regulating industries, which shows clear public participation.","D":"A barter economy relies on direct exchange of goods without money, whereas the scenario describes modern mobile services sold by a company in Accra."}}},{"id":"P1_U1_MCQ_1818","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1818","question":"Svitava Brewery, a small craft brewer in Brno, Czech Republic, cannot afford a bottling line and must borrow at high interest because it has little collateral to offer the bank. What difficulty of small businesses does this show?","options":{"A":"Diseconomies of scale","B":"Overtrading","C":"Difficulty raising finance","D":"Poor product quality"},"correctOption":"C","correctAnswer":"Difficulty raising finance","questionType":"MCQ","explanation":{"correct_reason":"The brewery lacks collateral and so faces expensive borrowing for its bottling line, showing that small firms often struggle to raise finance. Limited assets and short trading history make lenders cautious about small businesses.","distractor_reasons":{"A":"Diseconomies of scale mean rising average costs as a firm grows very large, whereas this small brewer's problem is obtaining money to buy equipment, not the cost of being big.","B":"Overtrading means expanding sales faster than working capital can support, which is not described; the stated problem is the absence of collateral for a loan.","C":"The brewery lacks collateral and so faces expensive borrowing for its bottling line, showing that small firms often struggle to raise finance. Limited assets and short trading history make lenders cautious about small businesses.","D":"Nothing suggests the beer is poor quality; customers are not mentioned. The obstacle is financial, since the bank demands security the small brewery cannot provide."}}},{"id":"P1_U1_MCQ_1819","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1819","question":"Litoral Stores is a single shop in Rosario, Argentina, owned and managed by one person who keeps all the profit but is personally responsible for every debt the business incurs. Which legal structure does this describe?","options":{"A":"Partnership with limited liability","B":"Private limited company with limited liability","C":"Cooperative with shared ownership","D":"Sole trader with unlimited liability"},"correctOption":"D","correctAnswer":"Sole trader with unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"One owner who takes all profits and is personally liable for all debts is a sole trader with unlimited liability. There is no separation between the owner's own finances and those of the shop in Rosario.","distractor_reasons":{"A":"A partnership needs at least two owners sharing profits, so it cannot describe one shopkeeper in Rosario, and partnerships commonly carry unlimited rather than limited liability.","B":"A private limited company has a separate legal identity and limited liability, protecting personal assets, whereas this owner is personally responsible for the shop's debts.","C":"A cooperative is jointly owned by members with shared decision-making, not by a single proprietor who keeps all the profit and bears all the risks alone.","D":"One owner who takes all profits and is personally liable for all debts is a sole trader with unlimited liability. There is no separation between the owner's own finances and those of the shop in Rosario."}}},{"id":"P1_U1_MCQ_1820","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1820","question":"Tejo Retail Ltd, a supermarket chain in Lisbon, Portugal, has started delaying payment to its vegetable growers by 90 days to hold on to cash, causing resentment among the farms that supply it. Which stakeholder relationship is under strain?","options":{"A":"Suppliers","B":"Customers","C":"Competitors","D":"The local community"},"correctOption":"A","correctAnswer":"Suppliers","questionType":"MCQ","explanation":{"correct_reason":"The growers supply vegetables to the chain and are annoyed by late payment, so the strained relationship is with suppliers. They are an external stakeholder group directly affected by the supermarket's cash-flow decision.","distractor_reasons":{"A":"The growers supply vegetables to the chain and are annoyed by late payment, so the strained relationship is with suppliers. They are an external stakeholder group directly affected by the supermarket's cash-flow decision.","B":"Customers are not mentioned as complaining; the resentment comes from the farms that deliver produce, so it is the supplier relationship that has been damaged.","C":"No rival supermarket is involved in this situation, so competitors cannot be the stakeholders described as resentful about the delayed payments.","D":"The local community is not in dispute here; the affected group consists of the specific vegetable growers who sell produce to the Lisbon chain."}}},{"id":"P1_U1_MCQ_1821","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1821","question":"Aire Print Ltd in Leeds, United Kingdom produces catalogues sold to customers for $90,000 a year. The printer spends $34,000 on paper, ink and other bought-in materials. What is the value added by the business?","options":{"A":"$56,000","B":"$34,000","C":"$90,000","D":"$124,000"},"correctOption":"A","correctAnswer":"$56,000","questionType":"MCQ","explanation":{"correct_reason":"Value added equals sales revenue less the cost of materials bought in. Aire Print earns $90,000 from catalogues and spends $34,000 on paper and ink, so $90,000 minus $34,000 gives $56,000 added by the printer's own work.","distractor_reasons":{"A":"Value added equals sales revenue less the cost of materials bought in. Aire Print earns $90,000 from catalogues and spends $34,000 on paper and ink, so $90,000 minus $34,000 gives $56,000 added by the printer's own work.","B":"$34,000 is the amount spent on paper, ink and other materials, which are bought-in costs, not the extra value created by printing and selling the catalogues.","C":"$90,000 is total sales revenue from the catalogues, not value added, because it includes the $34,000 cost of the paper and ink used up in production.","D":"$124,000 comes from adding revenue and material costs together, but value added requires subtracting the bought-in materials from the sales figure."}}},{"id":"P1_U1_MCQ_1822","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1822","question":"A local employment survey in Medellin, Colombia found 1,600 workers in the area: 280 in farming, 600 in factories and the remainder in shops and services. What share of the workers are employed in the secondary sector?","options":{"A":"17.5%","B":"45%","C":"62.5%","D":"37.5%"},"correctOption":"D","correctAnswer":"37.5%","questionType":"MCQ","explanation":{"correct_reason":"Factory workers are in the secondary sector, and there are 600 of them. Dividing 600 by the total of 1,600 workers gives 0.375, so 37.5% of the workforce in the survey is employed in secondary activity.","distractor_reasons":{"A":"17.5% is the farming share, 280 out of 1,600, which belongs to the primary sector and is not the factory-based secondary employment asked about here.","B":"45% is not supported by the figures; the 600 factory workers out of 1,600 give 37.5%, while the remaining 720 workers are in shops and services.","C":"62.5% corresponds to the 1,000 workers outside factories, combining primary and service jobs; the question asks only for the 600 in secondary employment.","D":"Factory workers are in the secondary sector, and there are 600 of them. Dividing 600 by the total of 1,600 workers gives 0.375, so 37.5% of the workforce in the survey is employed in secondary activity."}}},{"id":"P1_U1_MCQ_1823","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1823","question":"Bromo Exports Ltd, a seafood exporter in Surabaya, Indonesia, increased its annual revenue from $800,000 to $920,000 after winning new overseas contracts. What was the percentage increase in revenue?","options":{"A":"12%","B":"15%","C":"120%","D":"13%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $920,000 minus $800,000, which is $120,000. Comparing this increase with the original $800,000 gives 120,000 divided by 800,000, equal to 0.15, or a 15% rise in revenue.","distractor_reasons":{"A":"12% would come from dividing the $120,000 increase by the new revenue of $920,000, but percentage growth is measured against the starting revenue of $800,000.","B":"Revenue rose by $920,000 minus $800,000, which is $120,000. Comparing this increase with the original $800,000 gives 120,000 divided by 800,000, equal to 0.15, or a 15% rise in revenue.","C":"120% confuses the $120,000 increase with a percentage of the $800,000 starting revenue; the true proportional rise is only 15%.","D":"13% is close but incorrect; the exact calculation of 120,000 divided by 800,000 produces 0.15, which is precisely 15% growth."}}},{"id":"P1_U1_MCQ_1824","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1824","question":"Limmat Precision Ltd in Zurich, Switzerland has been registered with a share capital of 40,000 ordinary shares. An investor buys 2,500 of those shares. What percentage of the company does she own?","options":{"A":"4%","B":"5%","C":"6.25%","D":"16%"},"correctOption":"C","correctAnswer":"6.25%","questionType":"MCQ","explanation":{"correct_reason":"Ownership is the investor's shares divided by the total shares issued. She holds 2,500 of the 40,000 shares, and 2,500 divided by 40,000 equals 0.0625, so she owns 6.25% of Limmat Precision.","distractor_reasons":{"A":"4% would correspond to 1,600 shares out of 40,000, not the 2,500 shares the investor actually purchased in the Zurich company.","B":"5% would be 2,000 shares out of 40,000, whereas the investor bought 2,500 shares, giving 6.25% ownership of the business.","C":"Ownership is the investor's shares divided by the total shares issued. She holds 2,500 of the 40,000 shares, and 2,500 divided by 40,000 equals 0.0625, so she owns 6.25% of Limmat Precision.","D":"16% wrongly inverts the calculation by dividing 40,000 by 2,500; the correct proportion is the 2,500 shares she owns over the full 40,000."}}},{"id":"P1_U1_MCQ_1825","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1825","question":"St Kilda Fitness Ltd in Melbourne, Australia has set a profit objective equal to 20% of its annual revenue. If revenue this year is $250,000, what profit figure must the gym achieve to meet that objective?","options":{"A":"$20,000","B":"$50,000","C":"$200,000","D":"$30,000"},"correctOption":"B","correctAnswer":"$50,000","questionType":"MCQ","explanation":{"correct_reason":"A profit margin objective of 20% of revenue means multiplying $250,000 by 0.20. That calculation gives $50,000, so the Melbourne gym must earn $50,000 of profit to reach its stated target.","distractor_reasons":{"A":"$20,000 mistakes the percentage itself for the monetary amount; twenty percent of $250,000 is $50,000, not $20,000. The stem gives 20% for St Kilda Fitness Ltd, which does not support this option.","B":"A profit margin objective of 20% of revenue means multiplying $250,000 by 0.20. That calculation gives $50,000, so the Melbourne gym must earn $50,000 of profit to reach its stated target.","C":"$200,000 is 80% of revenue, the portion left if profit were 20%, but the objective concerns the profit share itself, which is $50,000.","D":"$30,000 does not equal 20% of $250,000; the required profit is a fifth of revenue, amounting to $50,000. The stem gives 20% for St Kilda Fitness Ltd, which does not support this option."}}},{"id":"P1_U1_MCQ_1826","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1826","question":"Jamura Garments Ltd in Dhaka, Bangladesh asks sewers to stitch the same seam for eight hours a day, and managers have noticed rising boredom and absenteeism. Which drawback of dividing work in this way does the situation illustrate?","options":{"A":"Lower output per worker","B":"Higher unit costs of production","C":"Boredom from repetitive work reducing motivation","D":"Much longer training for each task"},"correctOption":"C","correctAnswer":"Boredom from repetitive work reducing motivation","questionType":"MCQ","explanation":{"correct_reason":"Repeating one seam all day gives little variety, so workers become bored and demotivated, which helps explain the absenteeism at the Dhaka factory. This is a recognised disadvantage of narrow specialisation in production.","distractor_reasons":{"A":"Division of labour normally raises output per worker through practice, so lower output is not the problem shown; the reported issue is boredom and absence among the sewers.","B":"Higher unit costs are not indicated by the case; specialisation usually lowers unit costs, and the symptoms described are worker boredom and rising absenteeism.","C":"Repeating one seam all day gives little variety, so workers become bored and demotivated, which helps explain the absenteeism at the Dhaka factory. This is a recognised disadvantage of narrow specialisation in production.","D":"A single repetitive task is quick to learn, so training is not longer; the difficulty arises from tedious repetition rather than from complex skills."}}},{"id":"P1_U1_MCQ_1827","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1827","question":"Rambla Travel Ltd in Barcelona, Spain books flights, hotels and tours for holidaymakers and earns commission on each reservation. Which sector of the economy does this business operate in?","options":{"A":"Primary sector","B":"Tertiary sector","C":"Secondary sector","D":"Extractive sector"},"correctOption":"B","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Booking flights and hotels for holidaymakers is a service, and service provision belongs to the tertiary sector. The Barcelona agency does not extract raw materials or manufacture physical goods, it sells travel assistance.","distractor_reasons":{"A":"The primary sector extracts natural resources such as fish or minerals, whereas this agency earning commission on reservations clearly provides a service to travellers.","B":"Booking flights and hotels for holidaymakers is a service, and service provision belongs to the tertiary sector. The Barcelona agency does not extract raw materials or manufacture physical goods, it sells travel assistance.","C":"The secondary sector manufactures goods from materials, but a travel agency selling bookings and taking commission produces no physical product at all.","D":"Extractive activity means obtaining materials from nature, which is unrelated to a Barcelona firm arranging holidays for customers in exchange for commission."}}},{"id":"P1_U1_MCQ_1828","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1828","question":"Mukisa Foods Ltd in Kampala, Uganda has grown by building factories in three neighbouring countries, reaching new customers and spreading its risk across different markets. Which is a key reason for this growth?","options":{"A":"To avoid competing with any other firm","B":"To reduce the amount it produces","C":"To change its legal structure to a sole trader","D":"To increase sales and spread risk across markets"},"correctOption":"D","correctAnswer":"To increase sales and spread risk across markets","questionType":"MCQ","explanation":{"correct_reason":"Building factories in three neighbouring countries lets the business reach more customers, raise sales and spread risk if one market weakens. Those are common motives for growth, and they match the Kampala firm's expansion.","distractor_reasons":{"A":"Growth does not remove competition; the firm will face new rivals in each neighbouring country, so avoiding all competitors cannot be the reason described here.","B":"The company built extra factories, which increases rather than reduces output, so a smaller scale of production is not what its expansion is aiming for.","C":"Opening factories abroad has nothing to do with becoming a sole trader; a sole trader has one owner and could not operate this group of plants.","D":"Building factories in three neighbouring countries lets the business reach more customers, raise sales and spread risk if one market weakens. Those are common motives for growth, and they match the Kampala firm's expansion."}}},{"id":"P1_U1_MCQ_1829","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1829","question":"A designer in Copenhagen, Denmark registers Amager Design Ltd as a private company so that if the business fails, her personal savings will be protected from its debts. Which feature of this legal structure is she gaining?","options":{"A":"Limited liability","B":"Unlimited liability","C":"A public issue of shares","D":"Government ownership"},"correctOption":"A","correctAnswer":"Limited liability","questionType":"MCQ","explanation":{"correct_reason":"Protecting personal savings from the company's debts is limited liability, a key feature of a registered private company. The owner risks only the money invested in the business, not her own separate assets.","distractor_reasons":{"A":"Protecting personal savings from the company's debts is limited liability, a key feature of a registered private company. The owner risks only the money invested in the business, not her own separate assets.","B":"Unlimited liability would expose the designer's own savings to creditors, which is exactly the outcome she is trying to avoid by registering the company.","C":"A public issue of shares involves selling shares to the general public, which this private company is not doing; it has only the owner's own investment.","D":"Government ownership applies to state-run bodies, whereas this is a privately owned design business registered by its founder in Copenhagen."}}},{"id":"P1_U1_MCQ_1830","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1830","question":"Wayne Assembly Ltd in Detroit, United States is considering replacing 300 car plant workers with robots to reduce costs. Which stakeholder group is most directly threatened by this proposal?","options":{"A":"Shareholders","B":"Customers","C":"Employees","D":"Suppliers"},"correctOption":"C","correctAnswer":"Employees","questionType":"MCQ","explanation":{"correct_reason":"The 300 workers whose jobs would be taken by robots are employees, the group directly losing out from the proposal. Their interest in job security conflicts with the firm's wish to cut production costs.","distractor_reasons":{"A":"Shareholders may even welcome lower costs, so they are not the threatened group; the people losing their jobs at the Detroit plant are the employees.","B":"Customers are not directly harmed by installing robots and might benefit from lower prices; the proposal's immediate effect is on the workers' positions.","C":"The 300 workers whose jobs would be taken by robots are employees, the group directly losing out from the proposal. Their interest in job security conflicts with the firm's wish to cut production costs.","D":"Suppliers of parts or machinery are not the group facing job losses; the decision concerns replacing the plant's own workforce with robots."}}},{"id":"P1_U1_MCQ_1831","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1831","question":"Fraser Timber Ltd in Vancouver, Canada buys logs, cuts them into planks and sells the planks to house builders. What does this sequence of activities best illustrate about business activity?","options":{"A":"Only the provision of services","B":"Production that adds value by changing the form of materials","C":"Purely financial dealing with no physical output","D":"Retailing goods without any transformation"},"correctOption":"B","correctAnswer":"Production that adds value by changing the form of materials","questionType":"MCQ","explanation":{"correct_reason":"Sawing logs into planks changes the form of the raw material and makes it more useful to builders, so the firm is adding value through production. The planks can be sold for more than the original logs cost.","distractor_reasons":{"A":"The business produces physical planks rather than only a service; the cutting and selling of timber is a goods-producing activity in Vancouver.","B":"Sawing logs into planks changes the form of the raw material and makes it more useful to builders, so the firm is adding value through production. The planks can be sold for more than the original logs cost.","C":"Financial dealing would involve money or shares, but this company handles logs and planks, creating a tangible product for house builders.","D":"Retailing without transformation would mean passing goods on unchanged, whereas the logs are sawn into a different product before being sold."}}},{"id":"P1_U1_MCQ_1832","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1832","question":"Cidade Transportes runs the city bus network in Curitiba, Brazil. It is funded by the municipality and keeps fares low so residents can travel, rather than trying to maximise profit for owners. Which sector is it in?","options":{"A":"Private sector","B":"Voluntary sector","C":"Primary sector","D":"Public sector"},"correctOption":"D","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"A bus service funded and owned by the local municipality to provide affordable transport belongs to the public sector. Its aim is serving residents rather than earning profits for private shareholders.","distractor_reasons":{"A":"The private sector consists of privately owned profit-seeking firms, while this network is funded by the municipality and deliberately keeps fares low for residents.","B":"The voluntary sector is made up of charities and non-profit groups, whereas a city-funded transport authority is part of government-provided provision.","C":"The primary sector extracts natural resources, which has nothing to do with running a municipal bus service for the people of Curitiba.","D":"A bus service funded and owned by the local municipality to provide affordable transport belongs to the public sector. Its aim is serving residents rather than earning profits for private shareholders."}}},{"id":"P1_U1_MCQ_1833","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1833","question":"An analyst comparing two hotels in Bangkok, Thailand wants a straightforward measure of their size. Which of the following measures compares the businesses by the number of people on their payroll?","options":{"A":"Number of employees","B":"Market share only","C":"Profit margin","D":"Guest satisfaction score"},"correctOption":"A","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"Counting employees is a direct measure of business size based on the workforce, so it compares the two Bangkok hotels by how many people they employ. Other measures look at value or performance rather than payroll.","distractor_reasons":{"A":"Counting employees is a direct measure of business size based on the workforce, so it compares the two Bangkok hotels by how many people they employ. Other measures look at value or performance rather than payroll.","B":"Market share measures a firm's portion of total sales, not the size of its workforce, and the analyst specifically wants a count of people employed.","C":"Profit margin relates profit to revenue and says nothing about how many staff a hotel has, so it is not a payroll-based size measure.","D":"A guest satisfaction score indicates service quality rather than scale, so it cannot compare the hotels by the number of people they employ."}}},{"id":"P1_U1_MCQ_1834","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1834","question":"Forty coffee farmers near Hue, Vietnam jointly own a processing mill and each has one vote in its decisions, whatever the size of their farm. Which form of business organisation does this describe?","options":{"A":"Sole traders","B":"Public limited company","C":"Cooperative","D":"Franchise"},"correctOption":"C","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned jointly by its members and usually runs on one-member-one-vote, which matches the forty farmers sharing the Hue mill. The business exists to serve its members rather than outside shareholders.","distractor_reasons":{"A":"Sole traders each own their own separate business, so they could not jointly own one processing mill with equal voting rights as these farmers do.","B":"A public limited company is owned by shareholders whose votes usually depend on shares held, not by members each having a single equal vote in a mill.","C":"A cooperative is owned jointly by its members and usually runs on one-member-one-vote, which matches the forty farmers sharing the Hue mill. The business exists to serve its members rather than outside shareholders.","D":"A franchise involves paying a brand owner for the right to trade under its name, which has nothing to do with farmers jointly owning their own mill."}}},{"id":"P1_U1_MCQ_1835","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1835","question":"Adansi Cocoa Ltd in Kumasi, Ghana pays cocoa farmers above the market price and funds a local school, even though this reduces the company's profit. Which objective is the business pursuing alongside trade?","options":{"A":"Profit maximisation alone","B":"Sales growth alone","C":"Survival at any cost","D":"Social responsibility"},"correctOption":"D","correctAnswer":"Social responsibility","questionType":"MCQ","explanation":{"correct_reason":"Paying farmers more and supporting a school at the expense of profit shows social responsibility, an objective that considers the interests of suppliers and the community as well as the firm's own financial results.","distractor_reasons":{"A":"Profit maximisation alone would reject above-market payments and school funding because both reduce profit, so it cannot explain the Kumasi company's choices.","B":"Sales growth alone concerns increasing revenue, not paying suppliers more or funding a school, so it does not capture the community-focused behaviour described.","C":"Survival at any cost would mean cutting spending to stay in business, whereas this firm deliberately accepts lower profit to support farmers and the school.","D":"Paying farmers more and supporting a school at the expense of profit shows social responsibility, an objective that considers the interests of suppliers and the community as well as the firm's own financial results."}}},{"id":"P1_U1_MCQ_1836","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1836","question":"A mechanic at Alborz Auto Care in Tehran, Iran used to repair all vehicles but now only fits brake pads, giving up other repair work to focus on that job. What is the value of the next best alternative she gave up called?","options":{"A":"Opportunity cost","B":"Value added","C":"Comparative advantage","D":"Division of labour"},"correctOption":"A","correctAnswer":"Opportunity cost","questionType":"MCQ","explanation":{"correct_reason":"The other repair work forgone when the mechanic chose to fit brake pads is the next best alternative given up, which is the opportunity cost of her decision to specialise in Tehran.","distractor_reasons":{"A":"The other repair work forgone when the mechanic chose to fit brake pads is the next best alternative given up, which is the opportunity cost of her decision to specialise in Tehran.","B":"Value added is revenue minus materials bought in and does not measure a forgone alternative, so it cannot describe the repair work the mechanic stopped doing.","C":"Comparative advantage concerns the ability to produce at a lower relative cost than another producer, not the value of the option the mechanic surrendered.","D":"Division of labour describes splitting production into separate tasks, which is the situation itself rather than the value of the alternative work she gave up."}}},{"id":"P1_U1_MCQ_1837","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1837","question":"Cuu Long Rice Farms near Can Tho, Vietnam harvests rice from its fields and sells the crop to a milling company. Which sector of the economy does this farming activity belong to?","options":{"A":"Secondary sector","B":"Tertiary sector","C":"Primary sector","D":"Public sector"},"correctOption":"C","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Growing and harvesting rice is the extraction of a natural product from the land, which places the farm in the primary sector. The mill that later processes the rice would belong to the secondary sector.","distractor_reasons":{"A":"The secondary sector processes raw materials into finished goods, which describes the milling company rather than the farm that simply grows and harvests the rice.","B":"The tertiary sector provides services such as transport or retail, whereas harvesting a crop from fields is the direct production of a natural raw material.","C":"Growing and harvesting rice is the extraction of a natural product from the land, which places the farm in the primary sector. The mill that later processes the rice would belong to the secondary sector.","D":"The public sector involves government-owned provision, but this is a farm growing rice for sale to a milling business in the Mekong Delta."}}},{"id":"P1_U1_MCQ_1838","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1838","question":"Alpenrose Hotel in Innsbruck, Austria competes with large chains by tailoring stays to guests and making decisions quickly without head-office approval. What advantage of being a small business does this illustrate?","options":{"A":"Lower average costs than any large rival","B":"Flexibility and personal customer service","C":"Guaranteed access to cheap finance","D":"Economies of scale in purchasing"},"correctOption":"B","correctAnswer":"Flexibility and personal customer service","questionType":"MCQ","explanation":{"correct_reason":"Tailoring stays and deciding quickly without head-office approval show that a small hotel can be flexible and offer personal service. These are classic advantages of small size in competing against larger chains.","distractor_reasons":{"A":"Small firms do not automatically have lower average costs; large chains often benefit from lower unit costs, so this cannot be inferred from the Innsbruck example.","B":"Tailoring stays and deciding quickly without head-office approval show that a small hotel can be flexible and offer personal service. These are classic advantages of small size in competing against larger chains.","C":"The case says nothing about finance, and small businesses often face higher borrowing costs, so cheap finance is not the advantage being illustrated.","D":"Economies of scale in purchasing are a benefit of large firms buying in bulk, not of a small hotel that relies on personal attention and quick local decisions."}}},{"id":"P1_U1_MCQ_1839","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1839","question":"The founders of Liffey Ventures Plc in Dublin, Ireland want to raise money by offering shares to the general public and having those shares traded on the stock exchange. Which legal structure are they forming?","options":{"A":"Sole trader","B":"Partnership","C":"Private limited company","D":"Public limited company"},"correctOption":"D","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"Offering shares to the general public and having them traded on a stock exchange are the defining features of a public limited company. That structure lets the Dublin firm raise capital from many outside investors.","distractor_reasons":{"A":"A sole trader has a single owner and cannot issue shares to the public, so it cannot achieve the founders' aim of raising capital on the stock exchange.","B":"A partnership is owned by a few partners and does not sell shares to the public, so it would not allow trading on the Dublin stock exchange.","C":"A private limited company keeps its shares among a small group and cannot advertise them to the public, unlike the structure the founders intend to create.","D":"Offering shares to the general public and having them traded on a stock exchange are the defining features of a public limited company. That structure lets the Dublin firm raise capital from many outside investors."}}},{"id":"P1_U1_MCQ_1840","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1840","question":"At Vistula Retail Ltd in Warsaw, Poland, the family shareholders want to reinvest profits for long-term growth, while the hired managers are pressing for larger bonuses this year. Which stakeholder conflict does this show?","options":{"A":"Owners versus managers","B":"Customers versus suppliers","C":"Government versus the local community","D":"Competitors versus employees"},"correctOption":"A","correctAnswer":"Owners versus managers","questionType":"MCQ","explanation":{"correct_reason":"The shareholders who own the business favour reinvestment for growth, while the employed managers want immediate bonuses. Their differing aims show a conflict between owners and managers over how profits should be used.","distractor_reasons":{"A":"The shareholders who own the business favour reinvestment for growth, while the employed managers want immediate bonuses. Their differing aims show a conflict between owners and managers over how profits should be used.","B":"Customers and suppliers are not in disagreement in this case; the opposing views come from the family owners and the salaried managers in Warsaw.","C":"No government body or community representative is involved in the dispute, which concerns how the company's profit should be allocated between two internal groups.","D":"Competitors and employees are not the parties described; the tension is between the owners wanting reinvestment and managers seeking higher pay now."}}},{"id":"P1_U1_MCQ_1841","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1841","question":"Douro Bakehouse Ltd in Porto, Portugal sells bread and pastries to local shops for $75,000 a year. It spends $28,000 on flour, yeast and other ingredients. What is the value added by this bakery?","options":{"A":"$28,000","B":"$75,000","C":"$103,000","D":"$47,000"},"correctOption":"D","correctAnswer":"$47,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is revenue from sales minus the cost of bought-in materials. The Porto bakery receives $75,000 and spends $28,000 on ingredients, leaving $75,000 minus $28,000, which is $47,000 of value added by baking.","distractor_reasons":{"A":"$28,000 is the cost of flour, yeast and other ingredients, the bought-in materials, rather than the extra value created by the bakery's own work.","B":"$75,000 is the sales revenue from bread and pastries, not value added, because it still contains the $28,000 spent on purchased ingredients.","C":"$103,000 wrongly adds the sales revenue and the ingredient costs; value added subtracts bought-in costs from revenue instead of adding them.","D":"Value added is revenue from sales minus the cost of bought-in materials. The Porto bakery receives $75,000 and spends $28,000 on ingredients, leaving $75,000 minus $28,000, which is $47,000 of value added by baking."}}},{"id":"P1_U1_MCQ_1842","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1842","question":"A survey of 3,000 workers in Izmir, Turkey recorded 750 in farming, 1,050 in manufacturing and the rest working in shops, transport and other services. What percentage of the workers are in the service sector?","options":{"A":"40%","B":"25%","C":"35%","D":"60%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"The service workers are the remainder after farming and manufacturing: 3,000 minus 750 minus 1,050 equals 1,200. Dividing 1,200 by the 3,000 total gives 0.40, so 40% of the workers are in services.","distractor_reasons":{"A":"The service workers are the remainder after farming and manufacturing: 3,000 minus 750 minus 1,050 equals 1,200. Dividing 1,200 by the 3,000 total gives 0.40, so 40% of the workers are in services.","B":"25% is the farming share, 750 out of 3,000, which is the primary sector and not the service employment the question is asking about.","C":"35% is the manufacturing share, 1,050 out of 3,000, which belongs to the secondary sector and ignores the shops, transport and service jobs.","D":"60% would require 1,800 service workers, but subtracting 750 and 1,050 from 3,000 leaves only 1,200, which is 40% of the total surveyed."}}},{"id":"P1_U1_MCQ_1843","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1843","question":"Puteri Mobile Ltd estimates that the mobile phone market in Kuala Lumpur, Malaysia is worth $400 million a year, while its own annual sales there are $68 million. What is the company's market share?","options":{"A":"15%","B":"16%","C":"17%","D":"68%"},"correctOption":"C","correctAnswer":"17%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales. Puteri Mobile sells $68 million out of a $400 million market, and 68 divided by 400 equals 0.17, so its share is 17%.","distractor_reasons":{"A":"15% would mean sales of $60 million in a $400 million market, but Puteri Mobile's sales are $68 million, giving a 17% share.","B":"16% would require $64 million of sales out of $400 million; the actual $68 million produces a share of 17%, not 16%.","C":"Market share is the firm's sales divided by total market sales. Puteri Mobile sells $68 million out of a $400 million market, and 68 divided by 400 equals 0.17, so its share is 17%.","D":"68% mistakes the $68 million sales figure for a percentage; that amount is only 17% of the $400 million total market in Kuala Lumpur."}}},{"id":"P1_U1_MCQ_1844","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1844","question":"Three lawyers trade as Lima Legal Partners in Lima, Peru, sharing profits in the ratio 3:4:5. If the partnership makes $144,000 profit this year, how much does the lawyer with the four-part share receive?","options":{"A":"$36,000","B":"$48,000","C":"$60,000","D":"$72,000"},"correctOption":"B","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio parts total 3 plus 4 plus 5, which is 12. The lawyer with 4 parts receives 4/12 of the $144,000 profit, and one twelfth is $12,000, so the share is $48,000.","distractor_reasons":{"A":"$36,000 is three twelfths of the profit, the portion of the partner with the smallest 3-part share, not the lawyer with the middle four-part share.","B":"The ratio parts total 3 plus 4 plus 5, which is 12. The lawyer with 4 parts receives 4/12 of the $144,000 profit, and one twelfth is $12,000, so the share is $48,000.","C":"$60,000 is five twelfths of the profit and would go to the partner holding the largest 5-part share in the Lima partnership.","D":"$72,000 is half the profit, which would require 6 of 12 parts, more than the 4 parts that this lawyer is entitled to under the ratio."}}},{"id":"P1_U1_MCQ_1845","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1845","question":"Karnaphuli Tailors in Chittagong, Bangladesh aims to make $6,000 profit a month. In March its sales were $21,000 and its total costs were $16,200. By how much did the business beat or miss its profit objective?","options":{"A":"$1,200 below target","B":"$4,800 below target","C":"$1,200 above target","D":"$4,800 above target"},"correctOption":"A","correctAnswer":"$1,200 below target","questionType":"MCQ","explanation":{"correct_reason":"Profit is sales of $21,000 minus costs of $16,200, giving $4,800. Against the $6,000 objective that is a shortfall of $1,200, so the tailoring business missed its monthly target by $1,200.","distractor_reasons":{"A":"Profit is sales of $21,000 minus costs of $16,200, giving $4,800. Against the $6,000 objective that is a shortfall of $1,200, so the tailoring business missed its monthly target by $1,200.","B":"$4,800 is the actual profit, not the gap to the objective; the difference between $4,800 earned and $6,000 planned is just $1,200.","C":"$1,200 above target reverses the comparison; profit of $4,800 is lower than the $6,000 goal, so the firm finished below, not above, the objective.","D":"$4,800 above target confuses the profit figure with a surplus over target; the business actually fell short of its $6,000 aim."}}},{"id":"P1_U1_MCQ_1846","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1846","question":"Meijo Robotics Ltd in Nagoya, Japan has bought new automated machines for its production line. Which factor of production do these machines represent in the business's output of robot parts?","options":{"A":"Land","B":"Capital","C":"Labour","D":"Enterprise"},"correctOption":"B","correctAnswer":"Capital","questionType":"MCQ","explanation":{"correct_reason":"Manufactured machines used to produce other goods are capital, one of the factors of production. The automated equipment bought by the Nagoya firm is a produced resource that helps workers make robot parts.","distractor_reasons":{"A":"Land refers to natural resources and raw materials, not to machines that have been made by people, so the automated equipment is not an example of land.","B":"Manufactured machines used to produce other goods are capital, one of the factors of production. The automated equipment bought by the Nagoya firm is a produced resource that helps workers make robot parts.","C":"Labour is the human effort and skill put into production, whereas the question asks about the machines that assist the workers in the factory.","D":"Enterprise is the risk-taking and organising function of the owner or manager, not the physical equipment purchased for the production line."}}},{"id":"P1_U1_MCQ_1847","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1847","question":"Highveld Clinic Ltd is a privately owned hospital in Johannesburg, South Africa. It charges patients fees and is run to earn profits for its shareholders. Which sector of the economy does it belong to?","options":{"A":"Public sector","B":"Voluntary sector","C":"Private sector","D":"Primary sector"},"correctOption":"C","correctAnswer":"Private sector","questionType":"MCQ","explanation":{"correct_reason":"A hospital owned by private individuals and operated to earn profits for shareholders is in the private sector. Although healthcare is a service, ownership and the profit motive determine this classification.","distractor_reasons":{"A":"The public sector covers government-owned services, but this clinic is privately owned and answers to shareholders rather than to the state in Johannesburg.","B":"The voluntary sector includes charities that do not distribute profits, whereas this hospital explicitly aims to earn profits for its owners.","C":"A hospital owned by private individuals and operated to earn profits for shareholders is in the private sector. Although healthcare is a service, ownership and the profit motive determine this classification.","D":"The primary sector extracts natural resources, which has no bearing on a hospital charging fees for medical treatment in South Africa."}}},{"id":"P1_U1_MCQ_1848","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1848","question":"Andalusia Pharmacies in Malaga, Spain has funded three new branches from its own retained profits over two years, taking over no other business and raising no outside finance. Which route to growth is this?","options":{"A":"A merger","B":"A takeover","C":"Diversification","D":"Organic growth"},"correctOption":"D","correctAnswer":"Organic growth","questionType":"MCQ","explanation":{"correct_reason":"Opening three new branches using retained profits, with no purchase of another firm, is organic growth. The pharmacies expand their own existing business step by step from internally generated funds.","distractor_reasons":{"A":"A merger would require another business to agree to combine with the pharmacies, but the case describes three branches opened by the firm itself.","B":"A takeover means buying an existing company, which the Malaga business did not do, since it funded new branches from its own retained profits.","C":"Diversification means entering unrelated lines of business, whereas these are more branches of the same pharmacy operation in Malaga. The situation described for Andalusia Pharmacies does not support this option.","D":"Opening three new branches using retained profits, with no purchase of another firm, is organic growth. The pharmacies expand their own existing business step by step from internally generated funds."}}},{"id":"P1_U1_MCQ_1849","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1849","question":"Two architects run Torrens Architects as a partnership in Adelaide, Australia. They discover that a mistake by one of them leaves both personally liable for the firm's debts. Which feature of a partnership does this show?","options":{"A":"Unlimited liability shared by the partners","B":"Limited liability for each partner","C":"A separate legal identity with no personal risk","D":"Ownership spread among public shareholders"},"correctOption":"A","correctAnswer":"Unlimited liability shared by the partners","questionType":"MCQ","explanation":{"correct_reason":"Partners normally have unlimited liability, so a mistake by one can leave all partners personally responsible for the firm's debts. The Adelaide architects' situation illustrates this shared personal risk.","distractor_reasons":{"A":"Partners normally have unlimited liability, so a mistake by one can leave all partners personally responsible for the firm's debts. The Adelaide architects' situation illustrates this shared personal risk.","B":"Limited liability would protect each partner's own assets, which is the opposite of what happened when both architects became responsible for the debt.","C":"A partnership generally has no separate legal identity that shields the owners, so the idea of no personal risk is wrong in this case.","D":"Public shareholders own companies that sell shares to the public, not a two-person architectural partnership in Adelaide. The situation described for the business does not support this option."}}},{"id":"P1_U1_MCQ_1850","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1850","question":"Sheaf Steel Ltd in Sheffield, United Kingdom has been told by the city council that it must reduce emissions or face fines, even though the equipment would be expensive. Which stakeholder is applying this pressure?","options":{"A":"Employees","B":"Government or local authority","C":"Customers","D":"Shareholders"},"correctOption":"B","correctAnswer":"Government or local authority","questionType":"MCQ","explanation":{"correct_reason":"The city council is a local authority, part of government, and it is threatening fines over emissions. That makes the government stakeholder the source of pressure on the Sheffield steelworks in this case.","distractor_reasons":{"A":"Employees are not imposing fines; the warning comes from the council about pollution, so the workforce is not the stakeholder applying pressure here.","B":"The city council is a local authority, part of government, and it is threatening fines over emissions. That makes the government stakeholder the source of pressure on the Sheffield steelworks in this case.","C":"Customers are not threatening penalties over emissions; the demand to cut pollution comes from the local authority in Sheffield. The situation described for Sheaf Steel Ltd does not support this option.","D":"Shareholders might oppose expensive equipment, but they are not the body issuing fines; the pressure described originates with the city council."}}},{"id":"P1_U1_MCQ_1851","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1851","question":"Oder Dental Ltd in Wroclaw, Poland employs technicians who make only crowns and others who make only bridges, with each person repeating one type of dental appliance. What is this way of organising production called?","options":{"A":"Job rotation","B":"Diversification","C":"Division of labour","D":"Vertical integration"},"correctOption":"C","correctAnswer":"Division of labour","questionType":"MCQ","explanation":{"correct_reason":"Splitting dental work into separate crown-making and bridge-making jobs, each repeated by specialist technicians, is division of labour. It allows workers to gain skill and speed through focusing on one task.","distractor_reasons":{"A":"Job rotation would move workers between different tasks, but these technicians stay on one type of appliance, so the arrangement is the opposite of rotation.","B":"Diversification means adding different products or markets, whereas the laboratory still makes the same dental appliances and only divides the tasks among staff.","C":"Splitting dental work into separate crown-making and bridge-making jobs, each repeated by specialist technicians, is division of labour. It allows workers to gain skill and speed through focusing on one task.","D":"Vertical integration means owning other stages of the supply chain, which is not described; the change here is how work is divided inside one laboratory."}}},{"id":"P1_U1_MCQ_1852","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1852","question":"Maas Marine Insurance in Rotterdam, Netherlands arranges cargo cover for Dutch firms sending goods abroad and earns premiums for handling the risk. Which sector of the economy does this belong to?","options":{"A":"Tertiary sector","B":"Primary sector","C":"Secondary sector","D":"Manufacturing sector"},"correctOption":"A","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Arranging insurance and earning premiums is a service, and services belong to the tertiary sector. The Rotterdam firm handles risk for clients rather than extracting materials or making physical goods.","distractor_reasons":{"A":"Arranging insurance and earning premiums is a service, and services belong to the tertiary sector. The Rotterdam firm handles risk for clients rather than extracting materials or making physical goods.","B":"The primary sector extracts natural resources such as fish or minerals, whereas an insurance broker providing cover to shippers produces no raw material.","C":"The secondary sector turns materials into manufactured products, which does not describe a broker arranging policies and collecting premiums for clients.","D":"Manufacturing is part of the secondary sector and involves making goods, while this Rotterdam business sells intangible insurance cover to its customers."}}},{"id":"P1_U1_MCQ_1853","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1853","question":"An analyst comparing two furniture makers in Zhengzhou, China wants a measure of size based on the value of goods they produce and sell. Which measure fits that description best?","options":{"A":"Market share","B":"Value of output or sales revenue","C":"Number of shareholders","D":"Profit per employee"},"correctOption":"B","correctAnswer":"Value of output or sales revenue","questionType":"MCQ","explanation":{"correct_reason":"The value of output or sales revenue records the monetary worth of goods a firm produces and sells, so it directly matches the analyst's chosen measure of size for the two Zhengzhou furniture makers.","distractor_reasons":{"A":"Market share compares a firm's sales with the whole market rather than showing the absolute value of what the two furniture makers produce and sell.","B":"The value of output or sales revenue records the monetary worth of goods a firm produces and sells, so it directly matches the analyst's chosen measure of size for the two Zhengzhou furniture makers.","C":"The number of shareholders shows how many owners hold shares, which says nothing about the value of furniture produced or sold by the businesses.","D":"Profit per employee measures efficiency or productivity, not the total value of output, so it does not describe the size measure the analyst wants."}}},{"id":"P1_U1_MCQ_1854","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1854","question":"Lee Hair Studio is a salon in Cork, Ireland owned and managed by one hairdresser, who keeps all the profit and makes every decision about the business herself. Which legal structure does this describe?","options":{"A":"Partnership","B":"Private limited company","C":"Franchise","D":"Sole trader"},"correctOption":"D","correctAnswer":"Sole trader","questionType":"MCQ","explanation":{"correct_reason":"A business owned and run by one person who takes all profits and decisions is a sole trader. The Cork salon has a single proprietor, with no partners, shares or parent brand involved.","distractor_reasons":{"A":"A partnership needs at least two owners sharing profits and decisions, which is not the case for the single hairdresser running the salon alone.","B":"A private limited company has a separate legal identity and shareholders, whereas this salon is simply owned and controlled by one individual.","C":"A franchise would mean trading under another brand's name and paying fees, but the Cork salon is independently owned by the hairdresser herself.","D":"A business owned and run by one person who takes all profits and decisions is a sole trader. The Cork salon has a single proprietor, with no partners, shares or parent brand involved."}}},{"id":"P1_U1_MCQ_1855","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1855","question":"Reno Books in Bologna, Italy has seen revenue fall by 18% and is now concentrating on cutting costs enough to remain open through the next year. What is the shop's main objective in these circumstances?","options":{"A":"Profit maximisation","B":"Rapid expansion","C":"Survival","D":"Market leadership"},"correctOption":"C","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Cutting costs after an 18% revenue fall so the shop can stay open next year is a survival objective. The bookshop is focused on continuing to trade rather than on expansion or the highest possible profit.","distractor_reasons":{"A":"Profit maximisation seeks the largest attainable profit, but this shop is only trying to cover costs and keep trading after revenue fell by 18%.","B":"Rapid expansion would require spending on more outlets or stock, which is impossible for a bookshop struggling to cover its costs in Bologna.","C":"Cutting costs after an 18% revenue fall so the shop can stay open next year is a survival objective. The bookshop is focused on continuing to trade rather than on expansion or the highest possible profit.","D":"Market leadership means outselling rivals, which is not the priority of a business trying simply to remain open after a sharp fall in revenue."}}},{"id":"P1_U1_MCQ_1856","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1856","question":"Pichincha Toy Works in Quito, Ecuador takes plain wooden blocks supplied by customers and carves and paints them into finished toys that sell for more than the blocks cost. What best describes this business's activity?","options":{"A":"Transforming inputs into higher-value outputs","B":"Buying and selling goods without any change","C":"Providing government services","D":"Extracting raw materials from nature"},"correctOption":"A","correctAnswer":"Transforming inputs into higher-value outputs","questionType":"MCQ","explanation":{"correct_reason":"Carving and painting wooden blocks into toys changes their form and increases what customers will pay, so the workshop is transforming inputs into higher-value outputs and thereby adding value through production.","distractor_reasons":{"A":"Carving and painting wooden blocks into toys changes their form and increases what customers will pay, so the workshop is transforming inputs into higher-value outputs and thereby adding value through production.","B":"Buying and reselling unchanged goods would mean passing the blocks on as they arrived, whereas this Quito workshop changes them into carved, painted toys.","C":"Government services are provided by public bodies, but this is a private workshop making and selling toys to customers for a higher price than the inputs cost.","D":"Extracting raw materials means obtaining them from nature, while the workshop receives wooden blocks from customers and works on them rather than sourcing timber itself."}}},{"id":"P1_U1_MCQ_1857","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1857","question":"In Seoul, South Korea, privately owned firms compete to sell electronics while the government owns the railways and sets rules for the industry. Which economic system does this combination illustrate?","options":{"A":"A pure command economy","B":"A traditional economy","C":"A barter economy","D":"A mixed economy"},"correctOption":"D","correctAnswer":"A mixed economy","questionType":"MCQ","explanation":{"correct_reason":"Private electronics firms competing alongside government-owned railways and regulation is a mixed economy. Market forces and state involvement both shape what is produced and how resources are allocated.","distractor_reasons":{"A":"A command economy would have the state directing all production, yet private electronics firms compete freely in Seoul, so the system is not purely command-based.","B":"A traditional economy relies on custom and long-standing patterns of work, whereas modern electronics firms and state railways show an industrial economy.","C":"A barter economy exchanges goods directly without money, which is unrelated to this description of competing companies and publicly owned transport.","D":"Private electronics firms competing alongside government-owned railways and regulation is a mixed economy. Market forces and state involvement both shape what is produced and how resources are allocated."}}},{"id":"P1_U1_MCQ_1858","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1858","question":"Jalisco Drinks Ltd in Guadalajara, Mexico has purchased a competing soft-drinks bottler in the same city, aiming to raise its share of the local market. What type of growth has occurred?","options":{"A":"Organic growth","B":"Joint venture","C":"Horizontal integration","D":"Franchising"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Buying a rival bottler operating at the same stage of production in the same market is horizontal integration. The takeover increases the firm's share of existing soft-drinks customers in Guadalajara.","distractor_reasons":{"A":"Organic growth would mean building new capacity from the firm's own resources, not purchasing an established competing bottler in Guadalajara.","B":"A joint venture involves setting up a new business jointly with another partner, whereas this is a straightforward purchase of one company by another.","C":"Buying a rival bottler operating at the same stage of production in the same market is horizontal integration. The takeover increases the firm's share of existing soft-drinks customers in Guadalajara.","D":"Franchising involves licensing a brand to independent traders, which is not what happened when Jalisco Drinks bought another bottling company."}}},{"id":"P1_U1_MCQ_1859","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1859","question":"A family in Fukuoka, Japan wants limited liability and to keep all shares among relatives, with no sale of shares to the public. Which legal structure best meets these requirements?","options":{"A":"Public limited company","B":"Private limited company","C":"Partnership","D":"Sole trader"},"correctOption":"B","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company gives its owners limited liability while keeping shares within a small group and prohibiting public share sales, which is exactly what this Fukuoka family wants.","distractor_reasons":{"A":"A public limited company is allowed to sell shares to the public, which conflicts with the family's wish to keep ownership among relatives only.","B":"A private limited company gives its owners limited liability while keeping shares within a small group and prohibiting public share sales, which is exactly what this Fukuoka family wants.","C":"A partnership usually carries unlimited liability and does not issue shares to family members in the way the Fukuoka group requires.","D":"A sole trader has one owner and cannot keep shares among several relatives, so it does not fit a family wanting limited liability together."}}},{"id":"P1_U1_MCQ_1860","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1860","question":"Nickel Belt Mining Ltd near Sudbury, Canada plans to extend a mine closer to homes, creating jobs but worrying residents about dust and noise. Which stakeholder conflict is highlighted by this decision?","options":{"A":"Managers versus suppliers","B":"Customers versus competitors","C":"Employees versus government","D":"The local community's quality of life versus the company's expansion plans"},"correctOption":"D","correctAnswer":"The local community's quality of life versus the company's expansion plans","questionType":"MCQ","explanation":{"correct_reason":"Residents concerned about dust and noise want their quality of life protected, while the mine wants to expand and provide jobs. The tension is between the local community and the company's growth plans.","distractor_reasons":{"A":"Managers and suppliers are not in dispute here; the worries come from nearby residents affected by the proposed mine expansion near Sudbury.","B":"Customers and competitors are not the opposing groups described, since the conflict centres on local residents' environmental concerns about the mine.","C":"Employees might welcome the jobs, and no dispute between workers and government is described; the objection comes from the community living near the site.","D":"Residents concerned about dust and noise want their quality of life protected, while the mine wants to expand and provide jobs. The tension is between the local community and the company's growth plans."}}},{"id":"P1_U1_MCQ_1861","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1861","question":"Delft Ceramics Studio in Delft, Netherlands sells its pottery for $54,000 a year and spends $19,500 on clay, glaze and other materials. What is the value added by the studio?","options":{"A":"$19,500","B":"$54,000","C":"$34,500","D":"$73,500"},"correctOption":"C","correctAnswer":"$34,500","questionType":"MCQ","explanation":{"correct_reason":"Value added is sales revenue less the cost of bought-in materials. The studio earns $54,000 from selling pottery and spends $19,500 on clay and glaze, so $54,000 minus $19,500 gives $34,500 of added value.","distractor_reasons":{"A":"$19,500 is the amount paid for clay, glaze and materials, which are bought-in costs, not the value the studio adds by shaping and firing the pottery.","B":"$54,000 is the total sales revenue from pottery, not value added, because it includes the $19,500 spent on purchased materials.","C":"Value added is sales revenue less the cost of bought-in materials. The studio earns $54,000 from selling pottery and spends $19,500 on clay and glaze, so $54,000 minus $19,500 gives $34,500 of added value.","D":"$73,500 adds the sales revenue to the material costs, whereas value added requires subtracting the bought-in materials from the sales figure."}}},{"id":"P1_U1_MCQ_1862","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1862","question":"A survey of businesses in Leon, Nicaragua counted 2,000 workers: 500 in farming, 700 in factories and the rest in services. What percentage of these workers are employed in the primary sector?","options":{"A":"35%","B":"25%","C":"40%","D":"15%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Farming is primary activity, and the survey found 500 farm workers. Dividing 500 by the total of 2,000 workers gives 0.25, so 25% of those employed in the area work in the primary sector.","distractor_reasons":{"A":"35% would mean 700 workers out of 2,000, which is the number in factories and therefore the secondary sector, not the 500 in farming.","B":"Farming is primary activity, and the survey found 500 farm workers. Dividing 500 by the total of 2,000 workers gives 0.25, so 25% of those employed in the area work in the primary sector.","C":"40% would require 800 workers, more than the 500 recorded in farming; the correct primary share is 500 divided by 2,000, which is 25%.","D":"15% corresponds to 300 workers, not the 500 in farming; the survey's primary sector share is 25% of the total workforce."}}},{"id":"P1_U1_MCQ_1863","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1863","question":"Lambton Quay Hotels in Wellington, New Zealand increased annual revenue from $1.2 million to $1.35 million after refurbishing its rooms. What was the percentage rise in revenue?","options":{"A":"10%","B":"15%","C":"11%","D":"12.5%"},"correctOption":"D","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"Revenue grew from $1,200,000 to $1,350,000, an increase of $150,000. Dividing 150,000 by the original $1,200,000 gives 0.125, so revenue rose by 12.5%.","distractor_reasons":{"A":"10% would be $120,000 of extra revenue on a base of $1.2 million, but the actual increase is $150,000, giving 12.5%.","B":"15% would come from dividing the $150,000 rise by the new total of $1.35 million, but growth is measured against the original figure of $1.2 million.","C":"11% is an approximation that does not match the figures; 150,000 divided by 1,200,000 is exactly 0.125, or 12.5%. The stem gives $1.2 for Lambton Quay Hotels, which does not support this option.","D":"Revenue grew from $1,200,000 to $1,350,000, an increase of $150,000. Dividing 150,000 by the original $1,200,000 gives 0.125, so revenue rose by 12.5%."}}},{"id":"P1_U1_MCQ_1864","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1864","question":"Two friends form Daugava Design Partners in Riga, Latvia, agreeing to split profits in the ratio 3:2. If the partnership earns $85,000 this year, how much does the partner with the larger share receive?","options":{"A":"$51,000","B":"$34,000","C":"$42,500","D":"$17,000"},"correctOption":"A","correctAnswer":"$51,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio has 3 plus 2, or 5 parts in total. The partner with 3 parts takes 3/5 of the $85,000 profit; one fifth is $17,000, so three fifths amount to $51,000.","distractor_reasons":{"A":"The ratio has 3 plus 2, or 5 parts in total. The partner with 3 parts takes 3/5 of the $85,000 profit; one fifth is $17,000, so three fifths amount to $51,000.","B":"$34,000 is two fifths of the profit and belongs to the partner with the smaller 2-part share, not the one with the larger share.","C":"$42,500 is exactly half of the profit, which would apply only if the ratio were equal, rather than the agreed 3:2 split.","D":"$17,000 is one fifth of the profit, the value of a single ratio part, but the larger partner is entitled to three such parts."}}},{"id":"P1_U1_MCQ_1865","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1865","question":"Sicilia Bakers in Palermo, Italy aims to make $9,000 profit per month. In July its revenue was $38,000 and its total costs were $30,500. By how much did the bakery beat or miss its profit target?","options":{"A":"$7,500 below target","B":"$1,500 above target","C":"$7,500 above target","D":"$1,500 below target"},"correctOption":"D","correctAnswer":"$1,500 below target","questionType":"MCQ","explanation":{"correct_reason":"Profit is revenue of $38,000 minus costs of $30,500, giving $7,500. Compared with the $9,000 objective, that is $1,500 short, so the Palermo bakery missed its monthly profit target by $1,500.","distractor_reasons":{"A":"$7,500 is the profit actually earned, not the difference from the target; the gap between $7,500 and $9,000 is $1,500.","B":"$1,500 above target reverses the comparison: profit of $7,500 is less than the $9,000 goal, so the bakery is below the objective.","C":"$7,500 above target confuses the month's profit with a surplus over the goal; the bakery fell $1,500 short of what it planned.","D":"Profit is revenue of $38,000 minus costs of $30,500, giving $7,500. Compared with the $9,000 objective, that is $1,500 short, so the Palermo bakery missed its monthly profit target by $1,500."}}},{"id":"P1_U1_MCQ_1866","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1866","question":"A young designer in Bratislava, Slovakia takes the risk of starting Danube Design Studio, organises the other resources and invents new products for clients. Which factor of production does the designer's role illustrate?","options":{"A":"Enterprise","B":"Land","C":"Labour","D":"Capital"},"correctOption":"A","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Taking the risk, organising resources and introducing new products is enterprise, the factor of production supplied by the entrepreneur. It is the driving role that brings the other factors together in the studio.","distractor_reasons":{"A":"Taking the risk, organising resources and introducing new products is enterprise, the factor of production supplied by the entrepreneur. It is the driving role that brings the other factors together in the studio.","B":"Land means natural resources and raw materials, not the organising and risk-taking work carried out by the founder of the design studio.","C":"Labour is the ordinary effort of employees, whereas the question emphasises risk-taking and innovation, which are the distinctive contribution of enterprise.","D":"Capital refers to manufactured equipment and finance used in production, not to the person who decides to start and run the business."}}},{"id":"P1_U1_MCQ_1867","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1867","question":"Corrib Charity Shop in Galway, Ireland is staffed by volunteers and uses donations and sales to fund local projects, with no profits distributed to owners. Which sector of the economy does it belong to?","options":{"A":"Public sector","B":"Private sector","C":"Voluntary sector","D":"Primary sector"},"correctOption":"C","correctAnswer":"Voluntary sector","questionType":"MCQ","explanation":{"correct_reason":"A shop run by volunteers that uses funds for local projects rather than distributing profit is in the voluntary sector. Charities and non-profit organisations make up this part of the economy.","distractor_reasons":{"A":"The public sector is government-owned and funded through taxation, whereas this Galway shop relies on volunteers and donations rather than state control.","B":"The private sector consists of profit-seeking businesses owned by private individuals, unlike a charity shop whose surplus funds community projects.","C":"A shop run by volunteers that uses funds for local projects rather than distributing profit is in the voluntary sector. Charities and non-profit organisations make up this part of the economy.","D":"The primary sector extracts natural resources, which has nothing to do with a charity shop selling donated goods in Galway."}}},{"id":"P1_U1_MCQ_1868","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1868","question":"Two regional carriers in Addis Ababa, Ethiopia have agreed to combine their flight operations into one larger airline, sharing routes and fleets. What type of growth does this represent?","options":{"A":"Organic growth","B":"A merger","C":"A sole trader expansion","D":"Franchising"},"correctOption":"B","correctAnswer":"A merger","questionType":"MCQ","explanation":{"correct_reason":"When two existing airlines agree to combine into one business, that is a merger. The two firms join their resources voluntarily instead of growing slowly from their own profits or buying each other outright.","distractor_reasons":{"A":"Organic growth builds capacity from the firm's own resources, whereas here two separate carriers in Addis Ababa are joining operations together.","B":"When two existing airlines agree to combine into one business, that is a merger. The two firms join their resources voluntarily instead of growing slowly from their own profits or buying each other outright.","C":"A sole trader has a single owner and cannot be formed by two airlines merging their fleets and routes into one larger carrier.","D":"Franchising means licensing independent traders to use a brand, not two airlines agreeing to pool their operations into a single company."}}},{"id":"P1_U1_MCQ_1869","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1869","question":"Magyar Rail is wholly owned by the government in Budapest, Hungary and is required to run unprofitable rural lines because local people depend on them. What type of organisation is this?","options":{"A":"Private limited company","B":"Franchise","C":"Partnership","D":"Public corporation"},"correctOption":"D","correctAnswer":"Public corporation","questionType":"MCQ","explanation":{"correct_reason":"A publicly owned body set up to provide a service, here running rural rail lines for local people, is a public corporation. Government ownership and a public-service duty are its defining features.","distractor_reasons":{"A":"A private limited company is owned by private shareholders seeking returns, which does not fit a rail operator wholly owned by the Hungarian government.","B":"A franchise involves a private trader licensing a brand, whereas this railway is state-owned and required to serve passengers on unprofitable routes.","C":"A partnership has a few private owners sharing profits, not a government body operating essential transport for the public in Budapest.","D":"A publicly owned body set up to provide a service, here running rural rail lines for local people, is a public corporation. Government ownership and a public-service duty are its defining features."}}},{"id":"P1_U1_MCQ_1870","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1870","question":"Andaman Resort Group in Phuket, Thailand has set a target of resolving every guest complaint within two hours, hoping to improve customer satisfaction and word of mouth. Which objective is it pursuing?","options":{"A":"Improving customer service","B":"Maximising short-term profit only","C":"Reducing the range of services offered","D":"Avoiding all government regulation"},"correctOption":"A","correctAnswer":"Improving customer service","questionType":"MCQ","explanation":{"correct_reason":"Setting a two-hour limit for handling guest complaints is a clear aim to improve customer service. The target is about satisfying holidaymakers so that they speak well of the Phuket resorts.","distractor_reasons":{"A":"Setting a two-hour limit for handling guest complaints is a clear aim to improve customer service. The target is about satisfying holidaymakers so that they speak well of the Phuket resorts.","B":"Maximising short-term profit only would focus on revenue and costs, not on a service-quality promise about dealing with guest complaints within two hours.","C":"The group is adding a service standard rather than reducing its range of services, so cutting offerings cannot be the objective described here.","D":"Nothing in the scenario concerns regulation; the target concerns complaint handling and satisfying customers at the resorts in Thailand. The situation described for Andaman Resort Group does not support this option."}}},{"id":"P1_U1_MCQ_1871","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1871","question":"Paulista Legal Ltd in Sao Paulo, Brazil assigns each lawyer to one field, such as tax or property, so they develop expertise and complete cases more quickly. Which advantage of dividing work is shown?","options":{"A":"Higher unit costs for each case","B":"Greater expertise and speed from repetition","C":"No training needed for any of the lawyers","D":"Complete elimination of all mistakes"},"correctOption":"B","correctAnswer":"Greater expertise and speed from repetition","questionType":"MCQ","explanation":{"correct_reason":"Focusing each lawyer on tax or property work builds expertise and lets cases be handled faster, which is the main gain from division of labour. Repetition develops skill and saves time in the Sao Paulo firm.","distractor_reasons":{"A":"Division of labour normally lowers unit costs through efficiency, so higher costs per case are not the advantage shown by the specialised legal team.","B":"Focusing each lawyer on tax or property work builds expertise and lets cases be handled faster, which is the main gain from division of labour. Repetition develops skill and saves time in the Sao Paulo firm.","C":"Lawyers still need training in their chosen field, and the case says they develop expertise, so it is wrong to claim that no training is required.","D":"Specialisation can reduce errors but cannot remove every mistake, so complete elimination of all errors is too strong a claim for this example."}}},{"id":"P1_U1_MCQ_1872","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1872","question":"Monterrey Appliances Ltd in Monterrey, Mexico assembles refrigerators from components made by other firms and sells the finished products to retailers. Which sector does this activity belong to?","options":{"A":"Primary sector","B":"Tertiary sector","C":"Voluntary sector","D":"Secondary sector"},"correctOption":"D","correctAnswer":"Secondary sector","questionType":"MCQ","explanation":{"correct_reason":"Assembling components into finished refrigerators is manufacturing, which is the secondary sector. The Monterrey plant changes parts into a physical product, rather than extracting materials or providing a service.","distractor_reasons":{"A":"The primary sector extracts natural resources, while this plant receives components from other firms and builds refrigerators from them. The situation described for Monterrey Appliances Ltd does not support this option.","B":"The tertiary sector provides services, but assembling a physical refrigerator produces a manufactured good, so it is not a service activity.","C":"The voluntary sector consists of non-profit bodies, whereas this company manufactures appliances and sells them to retailers for profit. The situation described for Monterrey Appliances Ltd does not support this option.","D":"Assembling components into finished refrigerators is manufacturing, which is the secondary sector. The Monterrey plant changes parts into a physical product, rather than extracting materials or providing a service."}}},{"id":"P1_U1_MCQ_1873","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1873","question":"Ravi Beverages Ltd in Lahore, Pakistan wants to understand its position relative to rival soft-drink sellers in the same city. Which measure of size or performance would directly show its portion of total sales?","options":{"A":"Market share","B":"Number of shareholders","C":"Total land owned","D":"Hours of operation"},"correctOption":"A","correctAnswer":"Market share","questionType":"MCQ","explanation":{"correct_reason":"Market share states the firm's sales as a percentage of all sales in the market, so it directly compares Ravi Beverages with its Lahore rivals in terms of the portion of customers it serves.","distractor_reasons":{"A":"Market share states the firm's sales as a percentage of all sales in the market, so it directly compares Ravi Beverages with its Lahore rivals in terms of the portion of customers it serves.","B":"The number of shareholders shows ownership structure and says nothing about how the firm's sales compare with those of its competitors in Lahore.","C":"The total land owned measures physical assets, not the portion of the soft-drink market the business supplies compared with rivals.","D":"Hours of operation describe when the business trades, which cannot indicate its standing relative to other sellers in the same market."}}},{"id":"P1_U1_MCQ_1874","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1874","question":"An entrepreneur in San Jose, Costa Rica pays an annual fee to a fast-food brand for the right to use its logo, menu and training in her own restaurant. What type of business arrangement is this?","options":{"A":"Partnership","B":"Cooperative","C":"Franchise","D":"Public limited company"},"correctOption":"C","correctAnswer":"Franchise","questionType":"MCQ","explanation":{"correct_reason":"Paying a fee to use an established brand's logo, menu and support while owning the outlet is a franchise. The owner trades independently but follows the brand's rules and standards in San Jose.","distractor_reasons":{"A":"A partnership involves shared ownership and profits between partners, whereas the restaurant is owned by one entrepreneur who merely licenses a brand.","B":"A cooperative is owned jointly by members who vote on decisions, not an independently owned outlet paying fees to an outside brand owner.","C":"Paying a fee to use an established brand's logo, menu and support while owning the outlet is a franchise. The owner trades independently but follows the brand's rules and standards in San Jose.","D":"A public limited company sells shares to the public, which is not happening here; the business is a single restaurant using a licensed brand name."}}},{"id":"P1_U1_MCQ_1875","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1875","question":"Suomi Market Ltd in Helsinki, Finland has been accused by vegetable farmers of squeezing purchase prices so low that they cannot invest, while shoppers enjoy the low shelf prices. Which stakeholder conflict is shown?","options":{"A":"Managers versus owners","B":"Suppliers versus the supermarket's low-price objective","C":"Employees versus customers","D":"Government versus competitors"},"correctOption":"B","correctAnswer":"Suppliers versus the supermarket's low-price objective","questionType":"MCQ","explanation":{"correct_reason":"The farmers supply vegetables and object to prices that are too low for investment, while the chain wants to keep shelf prices down for shoppers. The conflict is between suppliers and the low-price goal.","distractor_reasons":{"A":"Managers and owners are not in dispute here; the complaint comes from the farmers who deliver produce to the Finnish supermarket chain.","B":"The farmers supply vegetables and object to prices that are too low for investment, while the chain wants to keep shelf prices down for shoppers. The conflict is between suppliers and the low-price goal.","C":"Employees and customers are not the opposing groups; the tension is with the external farms that sell produce to the supermarket.","D":"Neither a government body nor a competitor is described as objecting; the disagreement is between the chain's pricing objective and its suppliers."}}},{"id":"P1_U1_MCQ_1876","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1876","question":"Table Bay Taxis in Cape Town, South Africa buys fuel and vehicle maintenance but earns its income by carrying passengers. What is the main source of value added in this business?","options":{"A":"Only the price paid for fuel","B":"The purchase cost of the vehicles alone","C":"Government licensing of the taxi fleet","D":"The transport service, for which customers pay more than the bought-in inputs cost"},"correctOption":"D","correctAnswer":"The transport service, for which customers pay more than the bought-in inputs cost","questionType":"MCQ","explanation":{"correct_reason":"Value added here comes from the service of carrying passengers, since fares exceed the cost of fuel and maintenance bought in. The drivers' work turns those inputs into a service customers are willing to pay for.","distractor_reasons":{"A":"Fuel is a bought-in cost, not a source of added value; it is the service of transporting passengers that generates the fare income in Cape Town.","B":"The cost of the vehicles is an input or capital item, not value added; the taxis create value by providing journeys that customers pay for.","C":"Licensing may allow the firm to operate but does not create the value described; the added value comes from carrying passengers at a fare above input costs.","D":"Value added here comes from the service of carrying passengers, since fares exceed the cost of fuel and maintenance bought in. The drivers' work turns those inputs into a service customers are willing to pay for."}}},{"id":"P1_U1_MCQ_1877","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1877","question":"Cuyo Vineyards near Mendoza, Argentina grows grapes on its land and sells the fruit to wineries rather than making wine itself. Which sector does this activity belong to?","options":{"A":"Secondary sector","B":"Primary sector","C":"Tertiary sector","D":"Public sector"},"correctOption":"B","correctAnswer":"Primary sector","questionType":"MCQ","explanation":{"correct_reason":"Growing grapes is cultivation of a natural product from the land, which places the vineyard in the primary sector. The wineries that turn the grapes into wine would be in the secondary sector.","distractor_reasons":{"A":"The secondary sector processes materials into manufactured goods, which describes the wineries buying the grapes, not the vineyard growing them.","B":"Growing grapes is cultivation of a natural product from the land, which places the vineyard in the primary sector. The wineries that turn the grapes into wine would be in the secondary sector.","C":"The tertiary sector covers services such as transport and retail, whereas growing and selling grapes is the production of a natural raw material.","D":"The public sector involves government-owned activity, but this is a privately run vineyard selling its grape crop to wineries near Mendoza."}}},{"id":"P1_U1_MCQ_1878","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1878","question":"A start-up in Tel Aviv, Israel has developed a promising app but cannot afford the advertising budget that larger competitors spend. What challenge of being a small business does this illustrate?","options":{"A":"Too many shareholders to manage","B":"Excessive bureaucracy slowing decisions","C":"Limited finance to compete with larger firms","D":"Diseconomies of scale in a small team"},"correctOption":"C","correctAnswer":"Limited finance to compete with larger firms","questionType":"MCQ","explanation":{"correct_reason":"Being unable to fund the marketing that bigger rivals can afford shows that small firms often have limited finance. The start-up has a good product but lacks the money to promote it against established competitors.","distractor_reasons":{"A":"The problem is not a large number of owners; the start-up's difficulty is the cost of advertising compared with the budgets of bigger firms.","B":"Excessive bureaucracy is more typical of large organisations, whereas this small team's obstacle is a shortage of funds for marketing its app.","C":"Being unable to fund the marketing that bigger rivals can afford shows that small firms often have limited finance. The start-up has a good product but lacks the money to promote it against established competitors.","D":"Diseconomies of scale arise when a large firm becomes inefficient, not when a small start-up struggles to pay for advertising."}}},{"id":"P1_U1_MCQ_1879","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1879","question":"Three dentists run Rideau Dental Partners in Ottawa, Canada. They learn that a lawsuit against one of them could put all three dentists' personal assets at risk. Which feature of partnerships does this show?","options":{"A":"Unlimited liability","B":"Limited liability","C":"A separate legal identity protecting owners","D":"Public ownership of shares"},"correctOption":"A","correctAnswer":"Unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Partners generally have unlimited liability, so a claim against one dentist can endanger the personal assets of all the partners. The Ottawa practice illustrates the shared personal risk of this legal structure.","distractor_reasons":{"A":"Partners generally have unlimited liability, so a claim against one dentist can endanger the personal assets of all the partners. The Ottawa practice illustrates the shared personal risk of this legal structure.","B":"Limited liability would shield the dentists' personal assets from the claim, which is the opposite of what the situation describes.","C":"A partnership does not have a separate legal identity that fully protects owners, so personal assets can be at risk as the case shows.","D":"Public ownership of shares applies to quoted companies, not to a three-dentist partnership in Ottawa where owners are personally liable."}}},{"id":"P1_U1_MCQ_1880","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1880","question":"Aare Chocolate Ltd in Bern, Switzerland plans to cut 200 factory jobs to satisfy shareholders demanding higher profit, and the workforce has responded angrily. Which stakeholder conflict does this show?","options":{"A":"Customers versus suppliers","B":"Government versus the local community","C":"Shareholders' profit goal versus employees' job security","D":"Competitors versus customers"},"correctOption":"C","correctAnswer":"Shareholders' profit goal versus employees' job security","questionType":"MCQ","explanation":{"correct_reason":"Shareholders want higher profits and the job cuts are meant to deliver that, while employees want to keep their jobs. The dispute is between the owners' profit objective and workers' desire for security.","distractor_reasons":{"A":"Customers and suppliers are not in conflict here; the disagreement is between shareholders pressing for profit and workers facing redundancy in Bern.","B":"No government body is involved in the decision, and the angry response comes from employees rather than from the local community.","C":"Shareholders want higher profits and the job cuts are meant to deliver that, while employees want to keep their jobs. The dispute is between the owners' profit objective and workers' desire for security.","D":"Competitors and customers are not the opposing groups; the case concerns internal stakeholders, namely owners and employees of the chocolate factory."}}},{"id":"P1_U1_MCQ_1881","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1881","question":"Scheldt Cycles Ltd in Ghent, Belgium sells assembled bicycles to retailers for $88,000 a year and buys frames, tyres and gears costing $39,000. What is the value added by this business?","options":{"A":"$39,000","B":"$49,000","C":"$88,000","D":"$127,000"},"correctOption":"B","correctAnswer":"$49,000","questionType":"MCQ","explanation":{"correct_reason":"Value added is sales revenue minus bought-in materials. The Ghent business receives $88,000 for bicycles and spends $39,000 on frames, tyres and gears, so $88,000 minus $39,000 leaves $49,000 of added value.","distractor_reasons":{"A":"$39,000 is the cost of the bought-in frames, tyres and gears, not the additional value created by assembling and selling the bicycles.","B":"Value added is sales revenue minus bought-in materials. The Ghent business receives $88,000 for bicycles and spends $39,000 on frames, tyres and gears, so $88,000 minus $39,000 leaves $49,000 of added value.","C":"$88,000 is total sales revenue from bicycles, not value added, because it includes the $39,000 cost of purchased components. The stem gives $88,000 for Scheldt Cycles Ltd, which does not support this option.","D":"$127,000 incorrectly adds sales revenue to material costs; value added is found by subtracting the cost of bought-in parts from sales."}}},{"id":"P1_U1_MCQ_1882","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1882","question":"A survey in Tampere, Finland recorded 2,500 workers: 375 in farming, 1,000 in manufacturing and the rest in shops, transport and services. What percentage work in the service sector?","options":{"A":"15%","B":"40%","C":"45%","D":"55%"},"correctOption":"C","correctAnswer":"45%","questionType":"MCQ","explanation":{"correct_reason":"Service workers are the remainder: 2,500 minus 375 minus 1,000 equals 1,125. Dividing 1,125 by the 2,500 total gives 0.45, so 45% of the workers in the survey are in the service sector.","distractor_reasons":{"A":"15% is the farming share, 375 out of 2,500, which belongs to the primary sector rather than to the shops, transport and services asked about.","B":"40% would require 1,000 service workers, which is the manufacturing count; the actual remainder after farming and manufacturing is 1,125.","C":"Service workers are the remainder: 2,500 minus 375 minus 1,000 equals 1,125. Dividing 1,125 by the 2,500 total gives 0.45, so 45% of the workers in the survey are in the service sector.","D":"55% would mean 1,375 service workers, but subtracting 375 and 1,000 from 2,500 leaves 1,125, which is 45% of those surveyed."}}},{"id":"P1_U1_MCQ_1883","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1883","question":"Plata Market chain in Montevideo, Uruguay recorded sales of $45 million last year in a grocery market estimated to be worth $300 million. What was its market share?","options":{"A":"15%","B":"45%","C":"30%","D":"12%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the chain's sales divided by the whole market. Plata Market sold $45 million out of a $300 million market, and 45 divided by 300 equals 0.15, giving a 15% share.","distractor_reasons":{"A":"Market share is the chain's sales divided by the whole market. Plata Market sold $45 million out of a $300 million market, and 45 divided by 300 equals 0.15, giving a 15% share.","B":"45% mistakes the $45 million sales figure for a percentage; that amount is only 15% of the $300 million grocery market in Montevideo.","C":"30% would mean sales of $90 million out of $300 million, twice the $45 million actually recorded by the Uruguayan chain.","D":"12% would correspond to $36 million of sales in a $300 million market, but Plata Market's sales were $45 million, giving 15%."}}},{"id":"P1_U1_MCQ_1884","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1884","question":"Sava Industries Ltd in Ljubljana, Slovenia has 25,000 ordinary shares in issue. An investor purchases 3,750 of them. What percentage of the company does she now own?","options":{"A":"10%","B":"12%","C":"25%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Ownership is the shares held divided by shares in issue. The investor owns 3,750 of the 25,000 shares, and 3,750 divided by 25,000 equals 0.15, so she holds 15% of Sava Industries.","distractor_reasons":{"A":"10% would be 2,500 shares out of 25,000, fewer than the 3,750 the investor actually bought in the Slovenian company.","B":"12% would require 3,000 shares out of 25,000, so it understates the 3,750 shares acquired, which represent 15% ownership. The stem gives 25,000 for Sava Industries Ltd, which does not support this option.","C":"25% would mean 6,250 shares, well above the 3,750 purchased; the correct proportion is 3,750 divided by 25,000, which is 15%.","D":"Ownership is the shares held divided by shares in issue. The investor owns 3,750 of the 25,000 shares, and 3,750 divided by 25,000 equals 0.15, so she holds 15% of Sava Industries."}}},{"id":"P1_U1_MCQ_1885","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1885","question":"Canterbury Cafe Ltd in Christchurch, New Zealand wants to earn $8,000 profit in a month. During one month revenue was $30,000 and total costs were $23,600. By how much did the cafe beat or miss its target?","options":{"A":"$1,600 above target","B":"$1,600 below target","C":"$6,400 below target","D":"$6,400 above target"},"correctOption":"B","correctAnswer":"$1,600 below target","questionType":"MCQ","explanation":{"correct_reason":"Profit is $30,000 revenue minus $23,600 costs, which equals $6,400. Measured against the $8,000 objective, that is $1,600 short, so the cafe missed its monthly profit target by $1,600.","distractor_reasons":{"A":"$1,600 above target reverses the comparison; profit of $6,400 is below the $8,000 goal, so the cafe is short of its objective.","B":"Profit is $30,000 revenue minus $23,600 costs, which equals $6,400. Measured against the $8,000 objective, that is $1,600 short, so the cafe missed its monthly profit target by $1,600.","C":"$6,400 below target confuses the actual profit with the shortfall; the gap between $6,400 earned and $8,000 planned is only $1,600.","D":"$6,400 above target mistakes the month's profit for a surplus over the goal, when in fact the cafe fell $1,600 short of its target."}}},{"id":"P1_U1_MCQ_1886","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1886","question":"A joiner at Nidelva Joinery in Trondheim, Norway can spend a day making one table worth $600 or three chairs worth $250 each. If she chooses to make the table, what is the opportunity cost of that decision?","options":{"A":"$600","B":"$250","C":"$1,050","D":"$750 of chairs forgone"},"correctOption":"D","correctAnswer":"$750 of chairs forgone","questionType":"MCQ","explanation":{"correct_reason":"Making the table means giving up the three chairs she could have produced, worth 3 times $250, which is $750. That forgone alternative is the opportunity cost of choosing the table in Trondheim.","distractor_reasons":{"A":"$600 is the value of the table she chose to make, the benefit gained, not the value of the alternative she gave up.","B":"$250 is the value of just one chair, but she could have made three chairs, so the full opportunity cost is $750.","C":"$1,050 adds the value of the table and the three chairs together, whereas opportunity cost counts only what was forgone, the $750 of chairs.","D":"Making the table means giving up the three chairs she could have produced, worth 3 times $250, which is $750. That forgone alternative is the opportunity cost of choosing the table in Trondheim."}}},{"id":"P1_U1_MCQ_1887","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1887","question":"Bandra Payments Ltd in Mumbai, India processes card transactions for retailers and charges a fee for each payment it handles. Which sector of the economy does this business operate in?","options":{"A":"Tertiary sector","B":"Primary sector","C":"Secondary sector","D":"Extractive sector"},"correctOption":"A","correctAnswer":"Tertiary sector","questionType":"MCQ","explanation":{"correct_reason":"Processing card payments on behalf of retailers is a service, and services are classed as tertiary activity. The Mumbai firm handles transactions for clients rather than extracting materials or manufacturing goods.","distractor_reasons":{"A":"Processing card payments on behalf of retailers is a service, and services are classed as tertiary activity. The Mumbai firm handles transactions for clients rather than extracting materials or manufacturing goods.","B":"The primary sector extracts natural resources such as minerals or crops, which is unrelated to a company processing electronic payments for shops.","C":"The secondary sector manufactures physical goods from materials, whereas this business provides an intangible service and produces no product. The situation described for Bandra Payments Ltd does not support this option.","D":"Extractive activity involves obtaining raw materials from nature, not charging retailers a fee for handling their card transactions in Mumbai."}}},{"id":"P1_U1_MCQ_1888","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1888","question":"Sevilla Bus Ltd in Seville, Spain has bought another bus company running services on the same city routes, hoping to carry more passengers. What type of growth is this?","options":{"A":"Organic growth","B":"Market development","C":"Horizontal integration","D":"Diversification"},"correctOption":"C","correctAnswer":"Horizontal integration","questionType":"MCQ","explanation":{"correct_reason":"Purchasing another firm operating at the same stage and in the same market is horizontal integration. The two bus companies serve the same Seville routes, so the takeover simply gives the buyer more passengers.","distractor_reasons":{"A":"Organic growth would mean running more buses of its own from internal resources, not buying an existing operator on the same routes in Seville.","B":"Market development means taking existing services into new markets, but the acquired company serves the same city routes as the buyer.","C":"Purchasing another firm operating at the same stage and in the same market is horizontal integration. The two bus companies serve the same Seville routes, so the takeover simply gives the buyer more passengers.","D":"Diversification involves moving into unrelated products or markets, which is not the case when one city bus operator buys another city bus operator."}}},{"id":"P1_U1_MCQ_1889","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1889","question":"Two friends in Vilnius, Lithuania register Neris Design Ltd with a separate legal identity so that their personal savings are protected if the business cannot pay its debts. Which legal structure have they chosen?","options":{"A":"Partnership","B":"Private limited company","C":"Sole trader","D":"Franchise"},"correctOption":"B","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A separate legal identity that shields the owners' personal savings is the defining feature of a limited company. Since the shares are not offered publicly, Neris Design is a private limited company.","distractor_reasons":{"A":"A partnership does not give a fully separate legal identity, so the partners' own savings would remain exposed to business debts in Vilnius.","B":"A separate legal identity that shields the owners' personal savings is the defining feature of a limited company. Since the shares are not offered publicly, Neris Design is a private limited company.","C":"A sole trader has just one owner with unlimited liability, so it cannot describe two friends protecting their personal savings through registration.","D":"A franchise involves licensing a brand from another business, which is unrelated to registering a company for limited liability in Lithuania."}}},{"id":"P1_U1_MCQ_1890","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1890","question":"Pearl River Phones Ltd in Shenzhen, China is investing heavily so that it can overtake its rivals and become the largest seller in its segment within three years. Which business objective is this?","options":{"A":"Survival","B":"Cost minimisation only","C":"Social responsibility","D":"Market leadership and growth"},"correctOption":"D","correctAnswer":"Market leadership and growth","questionType":"MCQ","explanation":{"correct_reason":"Aiming to overtake rivals and become the biggest seller in its segment within three years is an objective of market leadership and growth. The heavy investment is directed at winning a larger share of the market.","distractor_reasons":{"A":"Survival means simply staying in business, whereas this Shenzhen company is spending heavily to become the biggest seller, which is a growth ambition.","B":"Cost minimisation only concerns reducing expenses, not overtaking competitors; the stated aim is to lead the market within three years.","C":"Social responsibility concerns wider benefits to society or the environment, which are not mentioned in this plan to beat rivals in China.","D":"Aiming to overtake rivals and become the biggest seller in its segment within three years is an objective of market leadership and growth. The heavy investment is directed at winning a larger share of the market."}}},{"id":"P1_U1_MCQ_1891","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1891","question":"Saone Bistro in Lyon, France employs separate chefs for sauces, grills and desserts, with each cook repeating only one kind of preparation. What does this arrangement best illustrate?","options":{"A":"Division of labour","B":"Diversification","C":"Market segmentation","D":"Public ownership"},"correctOption":"A","correctAnswer":"Division of labour","questionType":"MCQ","explanation":{"correct_reason":"Giving each chef responsibility for one kind of preparation, such as sauces or desserts, splits the kitchen work into specialist tasks. That is division of labour, which can improve speed and consistency in the Lyon bistro.","distractor_reasons":{"A":"Giving each chef responsibility for one kind of preparation, such as sauces or desserts, splits the kitchen work into specialist tasks. That is division of labour, which can improve speed and consistency in the Lyon bistro.","B":"Diversification means adding new products or markets, while the bistro still serves the same meals and has merely divided the cooking tasks among staff.","C":"Market segmentation divides customers into groups with different needs, which is unrelated to how the kitchen's cooking tasks are allocated among chefs.","D":"Public ownership means state control of a business, whereas this is a privately run bistro in Lyon whose chefs specialise in particular dishes."}}},{"id":"P1_U1_MCQ_1892","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1892","question":"Delta Power Authority in Cairo, Egypt is state-owned and has a duty to supply affordable electricity to rural villages, even where doing so is not profitable. Which sector does this organisation belong to?","options":{"A":"Private sector","B":"Voluntary sector","C":"Public sector","D":"Primary sector"},"correctOption":"C","correctAnswer":"Public sector","questionType":"MCQ","explanation":{"correct_reason":"An organisation owned by the state and tasked with providing an affordable service to citizens belongs to the public sector. Its priority is supplying villagers rather than earning profits for shareholders.","distractor_reasons":{"A":"The private sector consists of privately owned, profit-seeking firms, whereas this electricity authority is state-owned and serves rural villages. The situation described for Delta Power Authority does not support this option.","B":"The voluntary sector comprises charities and non-profit groups, not a government-owned utility supplying power to homes in Egypt. The situation described for Delta Power Authority does not support this option.","C":"An organisation owned by the state and tasked with providing an affordable service to citizens belongs to the public sector. Its priority is supplying villagers rather than earning profits for shareholders.","D":"The primary sector extracts natural resources, which does not describe a state-owned authority providing electricity to rural communities. The situation described for Delta Power Authority does not support this option."}}},{"id":"P1_U1_MCQ_1893","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1893","question":"Puget Coffee Ltd in Seattle, United States has grown by letting independent owners trade under its brand and follow its standards in return for fees and a share of sales. What method of growth is this?","options":{"A":"A merger","B":"Franchising","C":"A takeover","D":"Organic growth through company-owned outlets"},"correctOption":"B","correctAnswer":"Franchising","questionType":"MCQ","explanation":{"correct_reason":"Allowing independent owners to trade under the brand, follow standards and pay fees is franchising. The Seattle company expands through franchisees rather than by owning and running every outlet itself.","distractor_reasons":{"A":"A merger means two existing firms combining, which is not happening here; independent owners are paying to use the brand rather than merging with it.","B":"Allowing independent owners to trade under the brand, follow standards and pay fees is franchising. The Seattle company expands through franchisees rather than by owning and running every outlet itself.","C":"A takeover would mean buying other companies, whereas this brand grows by charging fees to independent traders who choose to use its name.","D":"Organic growth through company-owned outlets would mean the Seattle firm opening and managing each site itself, not licensing independents to trade under its brand."}}},{"id":"P1_U1_MCQ_1894","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1894","question":"Twenty dairy farmers near Kilkenny, Ireland jointly own Nore Dairy Co-op and each has one vote on how the creamery is run, regardless of the size of their herd. Which form of organisation is this?","options":{"A":"Sole traders","B":"Public limited company","C":"Franchise","D":"Cooperative"},"correctOption":"D","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A business owned jointly by members who each have one vote is a cooperative. The twenty farmers run the creamery for their mutual benefit rather than for outside shareholders in Kilkenny.","distractor_reasons":{"A":"Sole traders each own separate businesses, so they could not jointly own one creamery with equal voting rights as these farmers do.","B":"A public limited company is owned by shareholders whose voting power usually follows their shareholding, not by members each holding a single equal vote.","C":"A franchise involves paying a brand owner for the right to trade under its name, which has nothing to do with farmers jointly owning their own creamery.","D":"A business owned jointly by members who each have one vote is a cooperative. The twenty farmers run the creamery for their mutual benefit rather than for outside shareholders in Kilkenny."}}},{"id":"P1_U1_MCQ_1895","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1895","question":"Wakra Air Services in Doha, Qatar has introduced automatic compensation for passengers whenever a flight is delayed more than two hours, hoping to rebuild goodwill. Which stakeholder group is it prioritising?","options":{"A":"Customers","B":"Suppliers","C":"Competitors","D":"The local community"},"correctOption":"A","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"The passengers who receive compensation for delays are the airline's customers, so the policy prioritises that stakeholder group. The aim of rebuilding goodwill is aimed directly at the people buying flights.","distractor_reasons":{"A":"The passengers who receive compensation for delays are the airline's customers, so the policy prioritises that stakeholder group. The aim of rebuilding goodwill is aimed directly at the people buying flights.","B":"Suppliers provide fuel, aircraft or catering and are not receiving compensation here; the payments go to passengers on delayed flights from Doha.","C":"Competitors are not given compensation by the airline; the measure is intended to win favour with travellers rather than with rival carriers.","D":"The local community is not singled out for payments; the policy covers passengers who experience delays, making customers the relevant stakeholders."}}},{"id":"P1_U1_MCQ_1896","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1896","question":"Boland Wines Ltd near Stellenbosch, South Africa grows grapes on its vineyard and relies on the climate and soil of the valley. Which factor of production does the vineyard land represent?","options":{"A":"Labour","B":"Capital","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"The vineyard and the natural conditions of the valley are natural resources, which is the factor of production called land. It supplies the raw material and growing environment for the grapes.","distractor_reasons":{"A":"Labour is the human effort of the workers in the vineyard, not the land itself or the natural conditions that help the grapes grow.","B":"Capital refers to made equipment such as presses or trucks, whereas the question asks about the vineyard and the valley's natural resources.","C":"The vineyard and the natural conditions of the valley are natural resources, which is the factor of production called land. It supplies the raw material and growing environment for the grapes.","D":"Enterprise is the risk-taking and organising by the owners of the wine business, not the physical land and natural conditions near Stellenbosch."}}},{"id":"P1_U1_MCQ_1897","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1897","question":"In Ho Chi Minh City, Vietnam, family shops compete with state-owned enterprises and the government fixes prices for some utilities. Which economic system does this combination illustrate?","options":{"A":"A command economy","B":"A mixed economy","C":"A pure free market economy","D":"A traditional barter economy"},"correctOption":"B","correctAnswer":"A mixed economy","questionType":"MCQ","explanation":{"correct_reason":"Private family shops competing while state enterprises operate and the government controls some prices is a mixed economy. Market forces and government intervention both influence how resources are allocated.","distractor_reasons":{"A":"A command economy would have the state deciding all production, but family shops compete freely in Ho Chi Minh City, so the system is not purely command-based.","B":"Private family shops competing while state enterprises operate and the government controls some prices is a mixed economy. Market forces and government intervention both influence how resources are allocated.","C":"A pure free market would have no price controls or state enterprises, both of which are present in the Vietnamese system described here.","D":"A barter economy exchanges goods directly without money, which does not describe modern shops, state firms and regulated utility prices."}}},{"id":"P1_U1_MCQ_1898","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1898","question":"Maritsa Textiles Ltd in Plovdiv, Bulgaria has closed one of its two plants and sold the equipment so it can focus on its most profitable product line. What does this decision illustrate about business size?","options":{"A":"Growth through a merger","B":"Horizontal integration","C":"Franchising","D":"A deliberate reduction in scale to improve focus and profitability"},"correctOption":"D","correctAnswer":"A deliberate reduction in scale to improve focus and profitability","questionType":"MCQ","explanation":{"correct_reason":"Closing a plant and selling equipment to concentrate on the most profitable line is a deliberate cut in the scale of operations. The firm becomes smaller on purpose to improve focus and overall profitability.","distractor_reasons":{"A":"A merger would make the business larger by combining with another firm, whereas Maritsa Textiles has closed a plant and sold machinery.","B":"Horizontal integration means taking over a rival at the same stage of activity, not shutting down part of one's own production in Plovdiv.","C":"Franchising involves licensing a brand to other traders, which is unrelated to a textile maker reducing its number of factories and selling equipment.","D":"Closing a plant and selling equipment to concentrate on the most profitable line is a deliberate cut in the scale of operations. The firm becomes smaller on purpose to improve focus and overall profitability."}}},{"id":"P1_U1_MCQ_1899","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1899","question":"Bouregreg Bank Plc in Casablanca, Morocco has issued shares that trade on the local stock exchange, allowing thousands of investors to own part of the bank. Which legal structure does this describe?","options":{"A":"Public limited company","B":"Sole trader","C":"Partnership","D":"Cooperative"},"correctOption":"A","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"Shares traded on a stock exchange and held by thousands of investors define a public limited company. This legal form lets the Casablanca bank raise capital from the public rather than from a few private owners.","distractor_reasons":{"A":"Shares traded on a stock exchange and held by thousands of investors define a public limited company. This legal form lets the Casablanca bank raise capital from the public rather than from a few private owners.","B":"A sole trader has a single owner and cannot issue publicly traded shares, so it cannot describe a bank owned by thousands of investors.","C":"A partnership has a few partners sharing profits and does not have shares listed on a stock exchange for thousands of members of the public.","D":"A cooperative is owned by members who usually have equal votes, not by shareholders buying and selling listed shares on the Moroccan exchange."}}},{"id":"P1_U1_MCQ_1900","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1900","question":"Somerset Quarries Ltd near Bath, United Kingdom plans to extend its quarry closer to homes, bringing jobs but raising dust and noise worries among residents. Which stakeholder conflict is shown by this proposal?","options":{"A":"Employees versus suppliers","B":"Customers versus shareholders","C":"The local community's quality of life versus the company's expansion plans","D":"Government versus competitors"},"correctOption":"C","correctAnswer":"The local community's quality of life versus the company's expansion plans","questionType":"MCQ","explanation":{"correct_reason":"Residents worried about dust and noise want their surroundings protected, while the quarry wants to expand and create jobs. The conflict is between the local community's quality of life and the firm's expansion plans.","distractor_reasons":{"A":"Employees and suppliers are not the opposing groups here; the objections come from residents living near the proposed extension of the quarry.","B":"Customers and shareholders are not in dispute in the scenario, which focuses on the impact of expansion on people living close to the site.","C":"Residents worried about dust and noise want their surroundings protected, while the quarry wants to expand and create jobs. The conflict is between the local community's quality of life and the firm's expansion plans.","D":"No government body or competitor is described as opposing the plan; the tension is between local residents and the company's growth ambitions."}}},{"id":"P1_U1_MCQ_1901","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1901","question":"Mbeki Textiles Ltd in Durban buys cotton fabric for $6 per metre and converts it into finished shirts sold to retailers for $18 each. Which action directly creates the added value in this business?","options":{"A":"Transporting the finished shirts to the retailer's warehouse","B":"Converting bought-in fabric into shirts worth more than the inputs","C":"Paying the supplier for the cotton fabric delivered","D":"Advertising the shirts in a local newspaper"},"correctOption":"B","correctAnswer":"Converting bought-in fabric into shirts worth more than the inputs","questionType":"MCQ","explanation":{"correct_reason":"Added value is created when a business uses factors of production to transform inputs into outputs worth more than the cost of those inputs. Here $6 of fabric becomes a shirt sold for $18, so the conversion process in Durban creates the added value.","distractor_reasons":{"A":"Transporting finished shirts to a retailer is a distribution service, not the transformation that creates added value. The $6 fabric has already been converted before the shirts reach the warehouse, so delivery alone adds little.","B":"Added value is created when a business uses factors of production to transform inputs into outputs worth more than the cost of those inputs. Here $6 of fabric becomes a shirt sold for $18, so the conversion process in Durban creates the added value.","C":"Paying suppliers for $6 of cotton fabric is simply settling a payable obligation. The purchase transfers ownership of an input; it does not combine factors of production to raise the $6 input into an $18 output.","D":"Advertising promotes demand but does not physically transform the $6 of fabric into an $18 shirt. Marketing can help realise added value, yet the value is created during production at the Durban plant."}}},{"id":"P1_U1_MCQ_1902","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1902","question":"In Accra, a firm harvests cocoa beans, another roasts and grinds them into cocoa butter, and a third sells chocolate bars in supermarkets. Which combination of sectors do these three firms represent?","options":{"A":"Tertiary, secondary, primary","B":"Primary, tertiary, secondary","C":"Primary, secondary, tertiary","D":"Secondary, primary, tertiary"},"correctOption":"C","correctAnswer":"Primary, secondary, tertiary","questionType":"MCQ","explanation":{"correct_reason":"Harvesting cocoa beans extracts a natural raw material, which is primary production. Roasting and grinding into cocoa butter processes that material, which is secondary. Selling chocolate bars to consumers is a tertiary service, so the order is primary, secondary, tertiary.","distractor_reasons":{"A":"This option begins with tertiary, but harvesting cocoa in Accra extracts a raw material rather than providing a service. The sequence must start with primary production before processing and retail can occur.","B":"Roasting beans into cocoa butter is manufacturing, which is secondary, not tertiary. Only the supermarket sale is a service, so placing tertiary second reverses the actual order of activities.","C":"Harvesting cocoa beans extracts a natural raw material, which is primary production. Roasting and grinding into cocoa butter processes that material, which is secondary. Selling chocolate bars to consumers is a tertiary service, so the order is primary, secondary, tertiary.","D":"The first activity cannot be secondary because cocoa beans are gathered from farms, not manufactured. This sequence also puts primary last, whereas extraction happens before processing and retailing in Accra."}}},{"id":"P1_U1_MCQ_1903","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1903","question":"Kalu Electronics Ltd in Lagos earned $40,000 profit two years ago. Last year its profit rose to $52,000. What was the percentage increase in the firm's annual profit over that period?","options":{"A":"30%","B":"23.1%","C":"12%","D":"130%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The increase is $52,000 minus $40,000, which equals $12,000. Dividing $12,000 by the original $40,000 gives 0.30, or a 30% rise in profit. Option A is the exact percentage increase for the Lagos firm.","distractor_reasons":{"A":"The increase is $52,000 minus $40,000, which equals $12,000. Dividing $12,000 by the original $40,000 gives 0.30, or a 30% rise in profit. Option A is the exact percentage increase for the Lagos firm.","B":"Dividing the $12,000 increase by the new profit of $52,000 gives about 23.1%, but percentage change must use the original $40,000 as the base. That wrong denominator produces option B.","C":"$12,000 is the absolute profit increase in dollars, not a percentage. Expressing the rise relative to the $40,000 starting profit is required, giving 30% rather than 12%.","D":"$52,000 divided by $40,000 is 1.30, which means the new profit is 130% of the old one. The increase itself is only the extra 30 percentage points above the original base."}}},{"id":"P1_U1_MCQ_1904","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1904","question":"A group of five friends in Lyon opens a restaurant, sharing the work and the profits equally, and each is personally liable for all the business debts. Which legal structure have they chosen?","options":{"A":"Public limited company","B":"Sole trader","C":"Cooperative","D":"Partnership"},"correctOption":"D","correctAnswer":"Partnership","questionType":"MCQ","explanation":{"correct_reason":"An association of two or more people who agree to share the profits of a business and who carry unlimited liability is a partnership. Five friends in Lyon sharing work and debts fits that definition exactly.","distractor_reasons":{"A":"A public limited company has shareholders with limited liability and can sell shares to the public, so it does not match five friends personally responsible for every restaurant debt in Lyon.","B":"A sole trader is a single owner, but this restaurant has five friends who jointly manage it and split profits. The personal liability is shared, so the structure cannot be sole trading.","C":"A cooperative is owned and run by members for mutual benefit, often with one vote each. The scenario stresses profit-sharing and joint liability among five founders, which describes a partnership.","D":"An association of two or more people who agree to share the profits of a business and who carry unlimited liability is a partnership. Five friends in Lyon sharing work and debts fits that definition exactly."}}},{"id":"P1_U1_MCQ_1905","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1905","question":"A sugar company in Mauritius has promised local cane farmers a guaranteed price for their crop, while shareholders press for higher dividends. Which stakeholder conflict is most likely to arise from this situation?","options":{"A":"Customers versus suppliers","B":"Shareholders versus suppliers","C":"Employees versus the government","D":"Managers versus customers"},"correctOption":"B","correctAnswer":"Shareholders versus suppliers","questionType":"MCQ","explanation":{"correct_reason":"Guaranteeing cane prices benefits local farmers, who are suppliers to the Mauritius mill, but it raises costs and can reduce dividends. Shareholders seeking higher returns therefore conflict with the suppliers over how profit is distributed.","distractor_reasons":{"A":"Customers buy the sugar and are not party to the guaranteed cane price paid to farmers. The disagreement is about the split between owners and cane suppliers, not about consumer interests.","B":"Guaranteeing cane prices benefits local farmers, who are suppliers to the Mauritius mill, but it raises costs and can reduce dividends. Shareholders seeking higher returns therefore conflict with the suppliers over how profit is distributed.","C":"Employees and the government are not the opposing groups described here. The tension comes from promising farmers a price that squeezes the returns available to the company's shareholders.","D":"Managers may implement the policy, but the conflict described is over dividend payments versus farmer payments. Customers simply purchase sugar and are not asking for a share of profits."}}},{"id":"P1_U1_MCQ_1906","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1906","question":"A greenhouse grower near Mombasa uses glasshouses, workers, seedlings and tractors to produce tomatoes for local markets. Which combination correctly matches these inputs to the factors of production?","options":{"A":"Land=seedlings, Labour=tractors, Capital=workers","B":"Land=glasshouses, Labour=seedlings, Capital=tractors","C":"Land=workers, Labour=glasshouses, Capital=seedlings","D":"Land=the site and glasshouses, Labour=workers, Capital=tractors and seedlings"},"correctOption":"D","correctAnswer":"Land=the site and glasshouses, Labour=workers, Capital=tractors and seedlings","questionType":"MCQ","explanation":{"correct_reason":"Land means the natural site and fixed structures like glasshouses, labour is the effort of workers, and capital covers man-made aids such as tractors and purchased seedlings. Option D matches all three factors to the Mombasa grower's inputs.","distractor_reasons":{"A":"Seedlings are not land; they are a produced input, and tractors are capital rather than labour. Workers provide labour, so this option swaps the categories for the Mombasa greenhouse.","B":"Seedlings are a produced input, which is capital, not labour. Glasshouses can count as land improvements, but tractors are capital equipment, so the mapping is wrong.","C":"Workers are labour, not land, and glasshouses are capital structures rather than labour. Seedlings are bought inputs, so this arrangement misclassifies every factor used near Mombasa.","D":"Land means the natural site and fixed structures like glasshouses, labour is the effort of workers, and capital covers man-made aids such as tractors and purchased seedlings. Option D matches all three factors to the Mombasa grower's inputs."}}},{"id":"P1_U1_MCQ_1907","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1907","question":"In the city of Tarragona, 2,400 workers are employed in manufacturing, 1,600 in farming and 4,000 in services. What percentage of the total workforce works in the secondary sector?","options":{"A":"30%","B":"20%","C":"50%","D":"40%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Manufacturing is the secondary sector, employing 2,400 of Tarragona's 8,000 workers. Dividing 2,400 by 8,000 gives 0.30, so 30% of the workforce is in secondary production.","distractor_reasons":{"A":"Manufacturing is the secondary sector, employing 2,400 of Tarragona's 8,000 workers. Dividing 2,400 by 8,000 gives 0.30, so 30% of the workforce is in secondary production.","B":"Farming employs 1,600 workers, which is 20% of the 8,000 total, but farming is primary, not secondary. The 20% figure therefore answers the wrong sector question.","C":"Services employ 4,000 workers, or 50% of the workforce, yet services form the tertiary sector. This option mistakes the largest employer for the secondary manufacturing sector in Tarragona.","D":"The 40% figure does not correspond to any single sector here: manufacturing is 30%, farming 20% and services 50%. Using 2,400 over 8,000 gives 30%, not 40%."}}},{"id":"P1_U1_MCQ_1908","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1908","question":"A family bakery in Kraków has opened three new outlets and now delivers bread across the region. Which measure is most likely to show that this business has genuinely grown in size?","options":{"A":"The bakery's price per loaf","B":"The number of recipes it offers","C":"Its total annual sales revenue and workforce","D":"The colour of its delivery vans"},"correctOption":"C","correctAnswer":"Its total annual sales revenue and workforce","questionType":"MCQ","explanation":{"correct_reason":"Business size is commonly measured by turnover, number of employees or capital employed. The Kraków bakery's three outlets, regional deliveries and larger workforce show growth through higher sales revenue and headcount, not through price or recipe count.","distractor_reasons":{"A":"A higher loaf price changes revenue per unit but does not by itself show the bakery has grown. Size is judged by total output or sales, not by the price charged in one Kraków shop.","B":"Offering more recipes widens the product range but says nothing about the scale of operations. Growth in size is measured by sales, employees or output, not by the variety of bread on display.","C":"Business size is commonly measured by turnover, number of employees or capital employed. The Kraków bakery's three outlets, regional deliveries and larger workforce show growth through higher sales revenue and headcount, not through price or recipe count.","D":"The colour of delivery vans is a cosmetic detail unrelated to business size. What matters for the Kraków bakery is the volume of bread sold and the number of people it employs."}}},{"id":"P1_U1_MCQ_1909","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1909","question":"Three partners in Vancouver share profits in the ratio 2:3:5. If the partnership earns $90,000 in a year, how much does the partner with the largest share receive?","options":{"A":"$18,000","B":"$45,000","C":"$27,000","D":"$30,000"},"correctOption":"B","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"The ratio parts total 2+3+5 = 10. The largest share is 5 parts, so 5/10 of $90,000 equals $45,000. Option B is the amount received by the senior partner in Vancouver.","distractor_reasons":{"A":"$18,000 corresponds to 2 parts out of 10, the smallest share. The question asks for the largest share, which is 5 parts, so the correct amount is $45,000.","B":"The ratio parts total 2+3+5 = 10. The largest share is 5 parts, so 5/10 of $90,000 equals $45,000. Option B is the amount received by the senior partner in Vancouver.","C":"$27,000 represents 3 parts of the ten, the middle share. Adding the ratios gives ten parts, and five parts of $90,000 must be $45,000, not the middle amount.","D":"$30,000 would be one third of the profit, but the ratios are 2:3:5, not equal thirds. The largest partner takes half of the $90,000, which is $45,000."}}},{"id":"P1_U1_MCQ_1910","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1910","question":"A charitable clinic in Jaipur reinvests all surplus funds into free treatment for patients rather than distributing any profits. Which objective best describes this organisation?","options":{"A":"To provide a service and maximise social benefit","B":"To maximise shareholder dividends","C":"To achieve the highest possible market share","D":"To minimise the wage bill"},"correctOption":"A","correctAnswer":"To provide a service and maximise social benefit","questionType":"MCQ","explanation":{"correct_reason":"Reinvesting every surplus into free treatment shows the clinic prioritises serving patients and creating social benefit over making private gains. That is the defining aim of a nonprofit organisation in Jaipur.","distractor_reasons":{"A":"Reinvesting every surplus into free treatment shows the clinic prioritises serving patients and creating social benefit over making private gains. That is the defining aim of a nonprofit organisation in Jaipur.","B":"There are no shareholders receiving dividends here, because all surplus funds go back into free care. Profit distribution is the opposite of the clinic's stated social purpose in Jaipur.","C":"Market share is about capturing customers from rivals, which is not mentioned. The clinic's decision to treat patients freely points to a service objective rather than a competitive sales target.","D":"Keeping wages low is not described and would not explain reinvestment in free treatment. The clinic's objective is measured by the health benefit delivered, not by cutting the wage bill."}}},{"id":"P1_U1_MCQ_1911","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1911","question":"At a phone assembly plant in Ho Chi Minh City, one worker fits screens, another installs batteries and a third tests each handset. What is this working arrangement an example of?","options":{"A":"Diseconomies of scale","B":"Centralisation","C":"Diversification","D":"Division of labour"},"correctOption":"D","correctAnswer":"Division of labour","questionType":"MCQ","explanation":{"correct_reason":"Splitting the production process into separate tasks, with each worker specialising in one job, is division of labour. The Ho Chi Minh City plant gains speed and skill as each employee repeatedly fits screens, batteries or tests handsets.","distractor_reasons":{"A":"Diseconomies of scale refer to rising average costs when a firm becomes too large. The described specialisation on the assembly line usually improves efficiency, so it is not a diseconomy.","B":"Centralisation concerns where decision-making authority sits, not how tasks are divided among workers. Assigning screen fitting, battery installation and testing is a work organisation choice, not authority.","C":"Diversification means expanding into different products or markets. Here the same phones are assembled by workers doing distinct jobs, which is specialisation within one production process.","D":"Splitting the production process into separate tasks, with each worker specialising in one job, is division of labour. The Ho Chi Minh City plant gains speed and skill as each employee repeatedly fits screens, batteries or tests handsets."}}},{"id":"P1_U1_MCQ_1912","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1912","question":"In Sweden, a company owned by the national government runs the rail network, while a family firm runs a chain of cafés. Which sectors do these two businesses belong to according to ownership?","options":{"A":"Both are in the private sector","B":"Rail is private, cafés are public","C":"Rail is public sector, cafés are private sector","D":"Both are in the tertiary sector only"},"correctOption":"C","correctAnswer":"Rail is public sector, cafés are private sector","questionType":"MCQ","explanation":{"correct_reason":"A government-owned rail operator belongs to the public sector because the state controls it. The family-owned café chain is in the private sector. Ownership, not the service provided, determines the sector in Sweden.","distractor_reasons":{"A":"The rail network is state-owned, so it cannot be private. Only the family café chain is privately owned; classifying both businesses as private ignores government ownership in Sweden.","B":"This reverses the ownership: the rail company is publicly owned and the cafés are privately owned. The government controls the railway, while the family controls the café business.","C":"A government-owned rail operator belongs to the public sector because the state controls it. The family-owned café chain is in the private sector. Ownership, not the service provided, determines the sector in Sweden.","D":"Both do provide services, which makes them tertiary, but the question is about ownership sectors. The public-private distinction is the relevant one, so this option misses the point."}}},{"id":"P1_U1_MCQ_1913","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1913","question":"A software firm in Tallinn has merged with a rival to remove duplicated costs and reach a wider customer base. Which reason for business growth does this decision best illustrate?","options":{"A":"Economies of scale and access to more customers","B":"Avoiding all forms of competition","C":"Removing the need for any employees","D":"Switching from tertiary to primary production"},"correctOption":"A","correctAnswer":"Economies of scale and access to more customers","questionType":"MCQ","explanation":{"correct_reason":"Merging lets the Tallinn firm spread fixed costs over more customers and eliminate duplicate departments, gaining economies of scale. A wider customer base also increases sales potential, which is a classic motive for growth.","distractor_reasons":{"A":"Merging lets the Tallinn firm spread fixed costs over more customers and eliminate duplicate departments, gaining economies of scale. A wider customer base also increases sales potential, which is a classic motive for growth.","B":"Growth does not remove competition; the merged firm still faces other software providers. The merger reduces internal duplication, not the existence of rivals in the Estonian market.","C":"Merging does not eliminate the need for employees, since software development and support still require staff. The aim is lower average costs and more customers, not a workforce of zero.","D":"The firm remains a tertiary software business; growth by merger does not turn it into a primary producer. Extracting raw materials is unrelated to combining two software companies."}}},{"id":"P1_U1_MCQ_1914","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1914","question":"A graphic designer in Lisbon runs her studio alone, keeps all the profits and is personally responsible for any business debts. What is the main disadvantage of this legal structure?","options":{"A":"She must publish annual accounts publicly","B":"She has unlimited liability for business debts","C":"She cannot choose her own working hours","D":"She must distribute profits to shareholders"},"correctOption":"B","correctAnswer":"She has unlimited liability for business debts","questionType":"MCQ","explanation":{"correct_reason":"A sole trader has unlimited liability, meaning personal assets can be used to pay business debts. The Lisbon designer keeps all profits and controls her hours, but she personally carries every financial risk.","distractor_reasons":{"A":"Sole traders do not have to publish detailed annual accounts for public inspection; that duty falls on companies. The real drawback here is that the designer's own savings back the studio's debts.","B":"A sole trader has unlimited liability, meaning personal assets can be used to pay business debts. The Lisbon designer keeps all profits and controls her hours, but she personally carries every financial risk.","C":"One advantage of sole trading is freedom to set your own hours, so this is not a disadvantage. The designer's problem is financial exposure, not a lack of control over her schedule.","D":"There are no shareholders in a sole trader business to receive dividends. All profit belongs to the Lisbon designer, so distributing profits to outside owners cannot be the drawback."}}},{"id":"P1_U1_MCQ_1915","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1915","question":"A mine in Katanga employs 3,200 people, of whom 800 are due to be retrained when a new processing method is introduced. What percentage of the workforce will need retraining?","options":{"A":"20%","B":"30%","C":"25%","D":"40%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Dividing the 800 workers requiring retraining by the total workforce of 3,200 gives 0.25, which is 25%. Option C is the share of the Katanga mine's employees affected by the new processing method.","distractor_reasons":{"A":"20% would mean 640 of the 3,200 workers, not the 800 stated. The correct calculation uses 800 over 3,200, giving 25% of the mine workforce needing retraining.","B":"30% of 3,200 is 960 workers, which exceeds the 800 mentioned. Since 800 divided by 3,200 equals 0.25, the affected proportion is 25%, not 30%.","C":"Dividing the 800 workers requiring retraining by the total workforce of 3,200 gives 0.25, which is 25%. Option C is the share of the Katanga mine's employees affected by the new processing method.","D":"40% would require 1,280 workers to be retrained, far more than the 800 in the scenario. Eight hundred out of 3,200 simplifies to one quarter, or 25%."}}},{"id":"P1_U1_MCQ_1916","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1916","question":"A furniture maker in Mysore uses wood, saws, carpenters and a workshop to produce chairs. Which list correctly identifies the factors of production represented by the wood, saws and carpenters?","options":{"A":"Wood=capital, saws=land, carpenters=labour","B":"Wood=labour, saws=capital, carpenters=land","C":"Wood=capital, saws=labour, carpenters=land","D":"Wood=land, saws=capital, carpenters=labour"},"correctOption":"D","correctAnswer":"Wood=land, saws=capital, carpenters=labour","questionType":"MCQ","explanation":{"correct_reason":"Timber is a natural resource, so wood is land. Saws are manufactured tools, which are capital. The carpenters supply effort, which is labour. Option D matches the Mysore workshop's inputs to the three factors correctly.","distractor_reasons":{"A":"Wood comes from forests, making it land rather than capital, and saws are tools, not land. Only the carpenters are correctly labelled as labour in the Mysore furniture workshop.","B":"Carpenters provide labour, not land, and wood is a natural input, not labour. Saws are capital goods, so this option mixes up the categories used in the Mysore workshop.","C":"Saws are capital equipment, not labour, and the carpenters are labour, not land. Wood is a raw material classified as land, so this sequence is wrong for the Mysore maker.","D":"Timber is a natural resource, so wood is land. Saws are manufactured tools, which are capital. The carpenters supply effort, which is labour. Option D matches the Mysore workshop's inputs to the three factors correctly."}}},{"id":"P1_U1_MCQ_1917","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1917","question":"In the province of Cebu, 9,000 people work in agriculture, 6,000 in industry and 15,000 in services. What share of total employment is in the primary sector?","options":{"A":"30%","B":"20%","C":"50%","D":"25%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Agriculture is the primary sector, employing 9,000 people. Total employment is 9,000 plus 6,000 plus 15,000, which is 30,000. Nine thousand divided by 30,000 equals 30%, so option A is correct.","distractor_reasons":{"A":"Agriculture is the primary sector, employing 9,000 people. Total employment is 9,000 plus 6,000 plus 15,000, which is 30,000. Nine thousand divided by 30,000 equals 30%, so option A is correct.","B":"Industry employs 6,000 people, or 20% of the 30,000 total, but industry is secondary. The primary sector is agriculture, which accounts for 9,000 workers, or 30%.","C":"Services employ 15,000 people, 50% of those working in Cebu, yet services are tertiary. The question asks about primary employment, so the agricultural 9,000 must be used.","D":"25% would imply 7,500 agricultural workers out of 30,000, not the 9,000 stated. Dividing 9,000 by 30,000 gives 30% for the province's primary sector."}}},{"id":"P1_U1_MCQ_1918","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1918","question":"A courier firm in Santiago wants to compare its size with a rival in the same industry. Which single measure would be most appropriate for comparing the scale of the two businesses?","options":{"A":"The colour of their logos","B":"The number of directors' meetings held","C":"Annual turnover and number of employees","D":"The firms' stated missions"},"correctOption":"C","correctAnswer":"Annual turnover and number of employees","questionType":"MCQ","explanation":{"correct_reason":"Turnover and employee count are standard measures of business size and allow fair comparison between firms in the same industry. The Santiago courier and its rival can be ranked by sales revenue and headcount.","distractor_reasons":{"A":"A logo's colour is a branding choice and gives no information about scale. Comparing business size requires quantitative figures such as turnover, capital employed or number of workers.","B":"How often directors meet says little about the scale of deliveries or staff. The Santiago firms should be compared using sales and employment, not the frequency of board meetings.","C":"Turnover and employee count are standard measures of business size and allow fair comparison between firms in the same industry. The Santiago courier and its rival can be ranked by sales revenue and headcount.","D":"Mission statements describe aims, not size. Two couriers may have identical missions yet very different turnover and workforces, so missions cannot rank them by scale."}}},{"id":"P1_U1_MCQ_1919","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1919","question":"A drinks manufacturer in Johannesburg sells shares to the public and its shareholders enjoy limited liability for the company's debts. Which legal structure does this describe?","options":{"A":"Sole trader","B":"Public limited company","C":"Partnership","D":"Public corporation"},"correctOption":"B","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"A company that offers shares for sale to the general public and gives shareholders limited liability is a public limited company. The Johannesburg drinks maker matches that structure, unlike a private firm owned by a few people.","distractor_reasons":{"A":"A sole trader is owned by one person and cannot sell shares to the public. Limited liability and public share ownership point instead to a company structure for the Johannesburg manufacturer.","B":"A company that offers shares for sale to the general public and gives shareholders limited liability is a public limited company. The Johannesburg drinks maker matches that structure, unlike a private firm owned by a few people.","C":"In a partnership the owners usually have unlimited liability and cannot freely sell shares on a public market. The limited-liability feature rules this out for the drinks business.","D":"A public corporation is state-owned, whereas this Johannesburg firm has shares held by the public. Ownership by private shareholders makes it a public limited company."}}},{"id":"P1_U1_MCQ_1920","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1920","question":"A fashion retailer in Milan is considering closing an unprofitable store to raise profits for owners, but staff at that store will lose their jobs. Which stakeholder conflict does this illustrate?","options":{"A":"Suppliers versus customers","B":"Managers versus shareholders","C":"The government versus the local council","D":"Shareholders versus employees"},"correctOption":"D","correctAnswer":"Shareholders versus employees","questionType":"MCQ","explanation":{"correct_reason":"Closing the store raises profit for shareholders but costs employees their jobs. The opposing interests of owners seeking returns and workers seeking job security are the stakeholder conflict illustrated in Milan.","distractor_reasons":{"A":"Suppliers and customers are not the groups losing or gaining here. The store closure affects owners' profits and staff employment, so the conflict lies between shareholders and employees.","B":"Managers make the decision but are not identified as losing out. The real tension is between shareholders who want higher profit and the employees who would be made redundant in Milan.","C":"Government and council interests are not mentioned in the scenario. The direct clash is between the retailer's owners and the store workers facing redundancy.","D":"Closing the store raises profit for shareholders but costs employees their jobs. The opposing interests of owners seeking returns and workers seeking job security are the stakeholder conflict illustrated in Milan."}}},{"id":"P1_U1_MCQ_1921","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1921","question":"A sawmill in Vancouver turns locally sourced logs into planed timber that is sold to construction firms. Which description best captures the economic activity taking place at the sawmill?","options":{"A":"Providing a service to final consumers","B":"Processing raw materials into finished or semi-finished goods","C":"Retailing goods directly to households","D":"Extracting a natural resource from the forest"},"correctOption":"B","correctAnswer":"Processing raw materials into finished or semi-finished goods","questionType":"MCQ","explanation":{"correct_reason":"The sawmill receives logs, a raw material, and processes them into planed timber, a semi-finished product for builders. That transformation is manufacturing activity, adding value before the timber reaches construction firms in Vancouver.","distractor_reasons":{"A":"The sawmill sells to construction firms, not final consumers, and it produces a physical good rather than a service. Its role is processing inputs in Vancouver, not delivering a service to households.","B":"The sawmill receives logs, a raw material, and processes them into planed timber, a semi-finished product for builders. That transformation is manufacturing activity, adding value before the timber reaches construction firms in Vancouver.","C":"Retailing means selling goods to the public in small quantities. The mill's output goes to other businesses as timber, so it is not a retail operation.","D":"Extracting logs from the forest is primary activity carried out by forestry firms. The sawmill begins after extraction, converting those logs into usable timber."}}},{"id":"P1_U1_MCQ_1922","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1922","question":"A fisherman in Bergen catches cod, a nearby plant fillets and freezes it, and a restaurant serves cod dinners. Which order correctly lists the sectors involved in this chain?","options":{"A":"Secondary, primary, tertiary","B":"Tertiary, secondary, primary","C":"Primary, secondary, tertiary","D":"Primary, tertiary, secondary"},"correctOption":"C","correctAnswer":"Primary, secondary, tertiary","questionType":"MCQ","explanation":{"correct_reason":"Catching cod is extraction of a natural resource, so it is primary. Filleting and freezing are processing, which is secondary. Serving meals in a Bergen restaurant is a tertiary service, giving the order primary, secondary, tertiary.","distractor_reasons":{"A":"Fishing cannot be secondary because cod is harvested, not manufactured. The Bergen sequence must begin with the primary catch, followed by the processing plant and finally the restaurant.","B":"A restaurant provides a service, which is tertiary and comes last, not first. The correct order starts with the fisherman, then the plant, then the Bergen restaurant.","C":"Catching cod is extraction of a natural resource, so it is primary. Filleting and freezing are processing, which is secondary. Serving meals in a Bergen restaurant is a tertiary service, giving the order primary, secondary, tertiary.","D":"Freezing and filleting occur before the meal is served, so secondary must precede tertiary. Placing the restaurant second reverses the final two stages in Norway."}}},{"id":"P1_U1_MCQ_1923","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1923","question":"A retailer in Melbourne grew from 12 stores to 18 stores in three years. By what percentage did the number of stores increase over those three years?","options":{"A":"50%","B":"33.3%","C":"6%","D":"150%"},"correctOption":"A","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"The retailer added 18 minus 12, which is 6 stores. Six divided by the original 12 stores equals 0.50, a 50% increase. Option A is the percentage growth in the Melbourne chain's outlets.","distractor_reasons":{"A":"The retailer added 18 minus 12, which is 6 stores. Six divided by the original 12 stores equals 0.50, a 50% increase. Option A is the percentage growth in the Melbourne chain's outlets.","B":"Dividing the 6 new stores by the final total of 18 gives about 33.3%, but percentage growth uses the starting figure of 12. The correct increase from 12 to 18 is 50%.","C":"Six is the absolute number of additional stores, not a percentage. The six extra outlets must be compared with the original 12 to give a 50% rise for the Melbourne retailer.","D":"Eighteen divided by twelve is 1.5, meaning the chain now has 150% of its former size. The increase itself, however, is only the extra 50% above the starting number."}}},{"id":"P1_U1_MCQ_1924","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1924","question":"A coffee brand in Seattle allows independent owners to use its name and recipes in return for a fee and a share of sales. What type of business organisation does this arrangement represent?","options":{"A":"A sole trader with no outside links","B":"A public corporation","C":"A partnership between equal owners","D":"A franchise"},"correctOption":"D","correctAnswer":"A franchise","questionType":"MCQ","explanation":{"correct_reason":"A franchise exists when a firm grants others the right to trade under its brand and follow its system for a fee or royalty. The Seattle coffee company and its independent outlet owners fit that arrangement.","distractor_reasons":{"A":"Each outlet may be run by a sole trader, but the link to a brand and royalty payments makes the arrangement a franchise, not an isolated one-person business with no outside ties.","B":"There is no indication the Seattle brand is state-owned or that its shares are publicly traded. The defining feature here is the licensing of the brand to independent operators.","C":"The owners are not necessarily equal partners sharing all profits and debts. They pay fees to use a proven brand, which is the hallmark of a franchise agreement.","D":"A franchise exists when a firm grants others the right to trade under its brand and follow its system for a fee or royalty. The Seattle coffee company and its independent outlet owners fit that arrangement."}}},{"id":"P1_U1_MCQ_1925","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1925","question":"A family hotel in Bath has cut room prices to cover its basic running costs during a quiet season, aiming simply to stay in business. Which objective is the hotel pursuing?","options":{"A":"Profit maximisation","B":"Market leadership","C":"Survival","D":"Diversification"},"correctOption":"C","correctAnswer":"Survival","questionType":"MCQ","explanation":{"correct_reason":"Covering costs during a difficult period so the hotel can continue trading is the objective of survival. The Bath owners are not seeking maximum profit or dominance, just enough revenue to keep operating.","distractor_reasons":{"A":"Profit maximisation would focus on the highest possible earnings, but the hotel is only trying to meet its running costs. Keeping the doors open in Bath takes priority over profit.","B":"Market leadership means being the dominant provider, which is not suggested by cutting prices to cover costs. The hotel's immediate goal is staying in business through the quiet season.","C":"Covering costs during a difficult period so the hotel can continue trading is the objective of survival. The Bath owners are not seeking maximum profit or dominance, just enough revenue to keep operating.","D":"Diversification would involve adding new products or markets. Simply lowering prices to survive a slack period does not change the hotel's range of services in Bath."}}},{"id":"P1_U1_MCQ_1926","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1926","question":"A tea estate in Sri Lanka sells dried leaves to a packing firm, which puts them in branded foil bags for supermarkets. Which business activity adds the most value at the packing stage?","options":{"A":"Growing the tea bushes","B":"Harvesting the leaves by hand","C":"Transporting leaves to the factory","D":"Packaging and branding the tea for retailers"},"correctOption":"D","correctAnswer":"Packaging and branding the tea for retailers","questionType":"MCQ","explanation":{"correct_reason":"At the packing stage, value is added by processing dried leaves into a branded, retailer-ready product that commands a higher price. Growing and harvesting in Sri Lanka create raw material, but packaging and branding deliver the final customer appeal.","distractor_reasons":{"A":"Growing tea bushes is primary production that supplies the raw leaf, but the question asks specifically about the packing firm's activity. Cultivation happens before the leaves reach the Sri Lankan packing stage.","B":"Hand-harvesting supplies the input; it is not what the packing firm does. The value added at the later stage comes from turning dried leaves into a branded product for supermarkets.","C":"Moving leaves to the factory is transport, which does not change the product's form or brand. The Sri Lankan packing firm adds value by creating a finished, labelled bag of tea.","D":"At the packing stage, value is added by processing dried leaves into a branded, retailer-ready product that commands a higher price. Growing and harvesting in Sri Lanka create raw material, but packaging and branding deliver the final customer appeal."}}},{"id":"P1_U1_MCQ_1927","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1927","question":"A regional economy in Patagonia has 1,500 farm workers, 3,500 factory workers and 5,000 service workers. What percentage of the total workforce is employed in the primary sector?","options":{"A":"15%","B":"35%","C":"50%","D":"30%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Primary employment is farming, with 1,500 workers. The total workforce is 1,500 plus 3,500 plus 5,000, which equals 10,000. Dividing 1,500 by 10,000 gives 0.15, so 15% work in the primary sector.","distractor_reasons":{"A":"Primary employment is farming, with 1,500 workers. The total workforce is 1,500 plus 3,500 plus 5,000, which equals 10,000. Dividing 1,500 by 10,000 gives 0.15, so 15% work in the primary sector.","B":"Factory workers number 3,500, which is 35% of the 10,000 total, but that is secondary employment. The primary sector here is farming, which employs 1,500 people in Patagonia.","C":"Service workers make up half the workforce, but services are tertiary. The question concerns the 1,500 farmers, whose share of Patagonia's 10,000 workers is 15%.","D":"30% of 10,000 would be 3,000 farm workers, not the 1,500 recorded. One thousand five hundred out of 10,000 simplifies to 15% for the primary sector."}}},{"id":"P1_U1_MCQ_1928","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1928","question":"An entrepreneur in Nairobi spotted that office workers lacked affordable lunches and started a chain of healthy meal kiosks. Which characteristic of enterprise does this mainly demonstrate?","options":{"A":"Avoiding any risk by copying an existing firm","B":"Working only for a regular salary","C":"Identifying a customer need and organising resources to meet it","D":"Receiving a guaranteed government profit"},"correctOption":"C","correctAnswer":"Identifying a customer need and organising resources to meet it","questionType":"MCQ","explanation":{"correct_reason":"Enterprise involves spotting an opportunity, here the lack of affordable lunches for Nairobi office workers, and organising labour and capital to satisfy it. The founder took the initiative to create and run the meal kiosk business.","distractor_reasons":{"A":"The Nairobi founder identified a gap rather than copying an existing business. Enterprise accepts uncertainty, so avoiding all risk is not what the kiosk start-up demonstrates.","B":"The person is an owner-entrepreneur, not an employee drawing a salary. Starting meal kiosks means organising resources and seeking customers, not working for someone else's wage.","C":"Enterprise involves spotting an opportunity, here the lack of affordable lunches for Nairobi office workers, and organising labour and capital to satisfy it. The founder took the initiative to create and run the meal kiosk business.","D":"There is no mention of guaranteed government profit. The kiosks must attract office workers and cover costs, which is the essence of private enterprise in Nairobi."}}},{"id":"P1_U1_MCQ_1929","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1929","question":"A private limited company in Turin has 20,000 shares. An investor buys 2,500 of them. What percentage of the company's shares does the investor now own?","options":{"A":"8%","B":"12.5%","C":"20%","D":"25%"},"correctOption":"B","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"The investor holds 2,500 shares out of a total of 20,000. Dividing 2,500 by 20,000 gives 0.125, which is 12.5%. Option B is the exact percentage of the Turin company owned.","distractor_reasons":{"A":"8% of 20,000 would be 1,600 shares, not the 2,500 purchased. The correct fraction is 2,500 over 20,000, which equals 12.5% of the company.","B":"The investor holds 2,500 shares out of a total of 20,000. Dividing 2,500 by 20,000 gives 0.125, which is 12.5%. Option B is the exact percentage of the Turin company owned.","C":"20% would require 4,000 shares out of 20,000. Since the investor bought 2,500 shares, the holding is one eighth of the Turin company, or 12.5%.","D":"25% of 20,000 is 5,000 shares, double the 2,500 actually bought. Two thousand five hundred divided by 20,000 gives 12.5%, not a quarter."}}},{"id":"P1_U1_MCQ_1930","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1930","question":"A mobile network in Cairo has introduced cheaper data bundles after surveying customer complaints about high charges. Which stakeholder group has most directly influenced this decision?","options":{"A":"Customers","B":"Suppliers","C":"Competitors","D":"Local residents"},"correctOption":"A","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Customer complaints about prices prompted the cheaper bundles, so the needs of customers directly shaped the decision. The Cairo network responded to the people who buy and use its mobile services.","distractor_reasons":{"A":"Customer complaints about prices prompted the cheaper bundles, so the needs of customers directly shaped the decision. The Cairo network responded to the people who buy and use its mobile services.","B":"Suppliers provide network equipment but are not cited as complaining about data charges. The feedback came from users of the service, making customers the influencing stakeholder.","C":"Competitors are not mentioned as pressing for the change. Although rival networks may have affected pricing generally, the stated trigger was direct customer complaints in Cairo.","D":"Local residents generally are too broad a group; the specific stakeholders were paying customers who raised the issue. Their complaints about high charges led to the new bundles."}}},{"id":"P1_U1_MCQ_1931","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1931","question":"A bakery in Seville has $10,000 to spend and must choose between buying a new oven or a delivery van. If it buys the oven, what is the opportunity cost of that decision?","options":{"A":"The $10,000 spent on the oven","B":"The delivery van it gives up","C":"The extra bread the oven produces","D":"The bakery's existing customers"},"correctOption":"B","correctAnswer":"The delivery van it gives up","questionType":"MCQ","explanation":{"correct_reason":"Opportunity cost is the value of the next best alternative forgone. By spending $10,000 on the oven, the Seville bakery gives up the delivery van it would otherwise have bought.","distractor_reasons":{"A":"The $10,000 is the money spent, not the opportunity cost. Cost here is measured by the benefit of the van surrendered, which is the next best use of that money.","B":"Opportunity cost is the value of the next best alternative forgone. By spending $10,000 on the oven, the Seville bakery gives up the delivery van it would otherwise have bought.","C":"Extra bread from the oven is a benefit of the chosen option, not the cost. The opportunity cost in Seville is the forgone van, not the output gained from the oven.","D":"Existing customers are not given up by buying an oven; they remain with the bakery. Opportunity cost concerns the alternative purchase that cannot be made with the $10,000."}}},{"id":"P1_U1_MCQ_1932","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1932","question":"In Poland, the government owns the postal service while privately owned firms run most supermarkets and clinics. Which type of economic system does this mixture indicate?","options":{"A":"Command economy","B":"Free market economy","C":"Traditional economy","D":"Mixed economy"},"correctOption":"D","correctAnswer":"Mixed economy","questionType":"MCQ","explanation":{"correct_reason":"A mixed economy combines state ownership with private enterprise. Poland's government-run postal service alongside private supermarkets and clinics is exactly that blend of public and private provision.","distractor_reasons":{"A":"A command economy has the state controlling nearly all production, but most supermarkets and clinics here are privately owned. The presence of private firms rules out a pure command system.","B":"A free market economy would leave nearly everything to private firms, yet the postal service is government-owned. That public element makes the Polish system mixed.","C":"A traditional economy relies on customs and subsistence production, which is not described. The Polish example is about ownership patterns in a modern economy.","D":"A mixed economy combines state ownership with private enterprise. Poland's government-run postal service alongside private supermarkets and clinics is exactly that blend of public and private provision."}}},{"id":"P1_U1_MCQ_1933","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1933","question":"A craft brewery in Porto expanded rapidly and now struggles with delayed orders and confused responsibilities among newly hired staff. Which problem of rapid business growth does this situation best illustrate?","options":{"A":"Lower total revenue","B":"Lack of customer demand","C":"Coordination and communication difficulties","D":"Too few products to sell"},"correctOption":"C","correctAnswer":"Coordination and communication difficulties","questionType":"MCQ","explanation":{"correct_reason":"Rapid expansion often creates coordination problems as new employees join and roles become unclear. The Porto brewery's delayed orders and confused responsibilities show communication breaking down as the business grows.","distractor_reasons":{"A":"The brewery's problem is not falling revenue; rapid growth usually raises sales. Delayed orders reflect internal coordination, not a decline in total income.","B":"Orders are delayed because of internal confusion, suggesting demand exists. A lack of customer demand would show as unsold stock, not a backlog in Porto.","C":"Rapid expansion often creates coordination problems as new employees join and roles become unclear. The Porto brewery's delayed orders and confused responsibilities show communication breaking down as the business grows.","D":"Nothing suggests too few products; the issue is managing a larger workforce. Growth problems here are organisational, not a narrow product range."}}},{"id":"P1_U1_MCQ_1934","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1934","question":"Four friends in Cork run a design agency. Their liability is limited to what they invested, and they cannot sell shares to the public. What type of company is this?","options":{"A":"Private limited company","B":"Public limited company","C":"Partnership","D":"Sole trader"},"correctOption":"A","correctAnswer":"Private limited company","questionType":"MCQ","explanation":{"correct_reason":"A private limited company has limited liability for its owners and restricts the sale of shares, usually to friends and family. Four friends in Cork with limited liability and no public share issue fit this structure.","distractor_reasons":{"A":"A private limited company has limited liability for its owners and restricts the sale of shares, usually to friends and family. Four friends in Cork with limited liability and no public share issue fit this structure.","B":"A public limited company can sell shares to the general public, which these friends cannot do. Limited liability alone does not make a firm public; the share restriction is decisive.","C":"Partners normally have unlimited liability and no separate legal personality. The Cork agency's limited liability and company status point to a private limited company instead.","D":"A sole trader has just one owner with unlimited liability. Four friends sharing a company with limited liability cannot be described as a sole trader."}}},{"id":"P1_U1_MCQ_1935","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1935","question":"A cooperative in Rotterdam has 600 worker-members. If 150 of them vote for a new profit-sharing plan, what percentage of the members supports the plan?","options":{"A":"20%","B":"30%","C":"25%","D":"40%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"One hundred and fifty members out of 600 voted for the plan. Dividing 150 by 600 gives 0.25, which is 25%. Option C is the proportion of Rotterdam worker-members supporting profit sharing.","distractor_reasons":{"A":"20% of 600 would be 120 members, not the 150 recorded. One hundred and fifty divided by 600 equals 25%, so support for the plan is a quarter of the members.","B":"30% of 600 is 180 members, which is more than the 150 who voted yes. The correct share is 150 over 600, giving 25% support.","C":"One hundred and fifty members out of 600 voted for the plan. Dividing 150 by 600 gives 0.25, which is 25%. Option C is the proportion of Rotterdam worker-members supporting profit sharing.","D":"40% of 600 is 240 members, well above the 150 in favour. The yes vote represents one quarter, or 25%, of Rotterdam's cooperative members."}}},{"id":"P1_U1_MCQ_1936","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1936","question":"A car plant in Bratislava introduced assembly-line specialisation and found each worker became faster at a single task. Which benefit of division of labour does this illustrate?","options":{"A":"Increased speed and skill from repetition","B":"Higher costs from training","C":"Greater variety for each worker","D":"Elimination of all quality checks"},"correctOption":"A","correctAnswer":"Increased speed and skill from repetition","questionType":"MCQ","explanation":{"correct_reason":"Repeating one task lets workers develop expertise and work faster, which is a key benefit of division of labour. The Bratislava plant gains efficiency as employees concentrate on fitting or assembling a single component.","distractor_reasons":{"A":"Repeating one task lets workers develop expertise and work faster, which is a key benefit of division of labour. The Bratislava plant gains efficiency as employees concentrate on fitting or assembling a single component.","B":"Training costs may be a drawback of specialisation, but the scenario highlights faster work, not higher costs. The observed benefit at Bratislava is improved speed through repetition.","C":"Specialisation narrows each worker's tasks rather than widening variety. The Bratislava employees focus on one job, so variety is reduced, not increased.","D":"Quality checks are not removed by dividing labour, and the scenario does not say they are. Specialisation changes how work is organised, not whether inspection occurs."}}},{"id":"P1_U1_MCQ_1937","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1937","question":"A survey in Tallinn counted 7,500 workers in services, 5,000 in manufacturing and 2,500 in farming. What percentage of workers is in the secondary sector?","options":{"A":"20%","B":"50%","C":"30%","D":"33.3%"},"correctOption":"D","correctAnswer":"33.3%","questionType":"MCQ","explanation":{"correct_reason":"Manufacturing represents secondary production, employing 5,000 people. The total is 7,500 plus 5,000 plus 2,500, which is 15,000. Five thousand divided by 15,000 is approximately 0.333, or 33.3%.","distractor_reasons":{"A":"Farming employs 2,500 people, which is about 16.7% of the 15,000 total, not 20%. More importantly, farming is primary, so it cannot answer the secondary-sector question.","B":"Services employ 7,500 workers, exactly half of the Tallinn total, but they are tertiary. The secondary figure must come from the 5,000 manufacturing workers.","C":"30% of 15,000 would be 4,500 manufacturing workers, not the 5,000 counted. Five thousand out of 15,000 works out to roughly 33.3% in secondary employment.","D":"Manufacturing represents secondary production, employing 5,000 people. The total is 7,500 plus 5,000 plus 2,500, which is 15,000. Five thousand divided by 15,000 is approximately 0.333, or 33.3%."}}},{"id":"P1_U1_MCQ_1938","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1938","question":"A logistics firm in Rotterdam wants a measure of size that reflects the value of its long-term assets and the funding behind them. Which measure should it use?","options":{"A":"Number of customer complaints","B":"Capital employed","C":"Price of its cheapest service","D":"Number of rival firms"},"correctOption":"B","correctAnswer":"Capital employed","questionType":"MCQ","explanation":{"correct_reason":"Capital employed measures the long-term funds used in a business, including fixed assets and working capital. For the Rotterdam logistics firm it reflects the scale of assets and finance better than complaints or prices.","distractor_reasons":{"A":"Complaints indicate service quality, not business size. A large firm may receive many complaints simply because it has many customers, so this is not a reliable size measure.","B":"Capital employed measures the long-term funds used in a business, including fixed assets and working capital. For the Rotterdam logistics firm it reflects the scale of assets and finance better than complaints or prices.","C":"The price of a cheap service says nothing about total scale. Size is better captured by capital employed, turnover or employee numbers at the Rotterdam firm.","D":"The number of rivals describes the market, not the firm's own size. The logistics business should look at its own assets and funding, which capital employed captures."}}},{"id":"P1_U1_MCQ_1939","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1939","question":"A group of dairy farmers in Normandy jointly owns a processing plant and each member has one vote when decisions are made. What type of organisation is this?","options":{"A":"Cooperative","B":"Sole trader","C":"Public limited company","D":"Franchise"},"correctOption":"A","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"A cooperative is owned and controlled by its members for their mutual benefit, commonly with one vote per member regardless of size. The Normandy dairy farmers jointly owning the plant fit that definition.","distractor_reasons":{"A":"A cooperative is owned and controlled by its members for their mutual benefit, commonly with one vote per member regardless of size. The Normandy dairy farmers jointly owning the plant fit that definition.","B":"A sole trader has a single owner, whereas the plant is owned collectively by many farmers. One vote per member also shows shared democratic control, not sole ownership.","C":"A public limited company sells shares to the public and votes usually follow shareholdings. The Normandy plant is member-owned with equal votes, so it is a cooperative.","D":"A franchise involves licensing a brand from a parent firm, not members jointly owning a plant. The farmers' cooperative ownership and voting make the answer clear."}}},{"id":"P1_U1_MCQ_1940","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1940","question":"A smartphone maker in Shenzhen has demanded shorter payment terms from its component suppliers to improve its own cash flow. Which stakeholder is most likely to be disadvantaged by this change?","options":{"A":"Shareholders","B":"Customers","C":"Managers","D":"Suppliers"},"correctOption":"D","correctAnswer":"Suppliers","questionType":"MCQ","explanation":{"correct_reason":"Shorter payment terms mean suppliers wait longer for their money, which strains their cash flow. The Shenzhen phone maker benefits, but the component suppliers are the stakeholders likely to lose out.","distractor_reasons":{"A":"Shareholders may benefit from improved cash flow, so they are not disadvantaged. The party waiting longer for payment is the supplier, not the company's owners.","B":"Customers buying phones are unaffected by how quickly suppliers are paid. The disadvantage falls on the firms providing components to the Shenzhen manufacturer.","C":"Managers implement the payment change but are not described as losing. Suppliers face the cash-flow squeeze, making them the disadvantaged stakeholder group.","D":"Shorter payment terms mean suppliers wait longer for their money, which strains their cash flow. The Shenzhen phone maker benefits, but the component suppliers are the stakeholders likely to lose out."}}},{"id":"P1_U1_MCQ_1941","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1941","question":"A call centre in Manila found that repetitive, narrowly defined tasks led to bored staff and higher error rates. Which drawback of division of labour does this situation show?","options":{"A":"Faster training of employees","B":"Boredom and reduced motivation from repetition","C":"Lower output per worker","D":"Greater product variety"},"correctOption":"B","correctAnswer":"Boredom and reduced motivation from repetition","questionType":"MCQ","explanation":{"correct_reason":"When workers repeat one small task, the work can become monotonous, reducing motivation and increasing mistakes. The Manila call centre's boredom and errors illustrate this well-known drawback of division of labour.","distractor_reasons":{"A":"Faster training is generally an advantage of specialisation, not a drawback. The Manila problem is staff boredom and errors, which stem from repetitive work.","B":"When workers repeat one small task, the work can become monotonous, reducing motivation and increasing mistakes. The Manila call centre's boredom and errors illustrate this well-known drawback of division of labour.","C":"Division of labour usually raises output per worker through practice; the issue here is quality and motivation. Higher errors reflect boredom, not a fall in output.","D":"Product variety is not related to how tasks are divided among employees. The call centre's difficulty is the repetitive nature of each worker's job in Manila."}}},{"id":"P1_U1_MCQ_1942","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1942","question":"A national health service in Thailand is funded by taxes and provides free treatment at its hospitals. Which sector does it belong to, and what is its main objective?","options":{"A":"Private sector, profit maximisation","B":"Public sector, profit maximisation","C":"Public sector, providing a service to citizens","D":"Private sector, providing a service to citizens"},"correctOption":"C","correctAnswer":"Public sector, providing a service to citizens","questionType":"MCQ","explanation":{"correct_reason":"A tax-funded health service owned by the state is in the public sector, and its aim is to provide healthcare rather than earn profit. Thai citizens receive free treatment, showing a service objective.","distractor_reasons":{"A":"The service is tax-funded and state-run, so it is not private. Its goal is free treatment, not maximising profit for owners.","B":"Although it is in the public sector, the objective is not profit maximisation. Free hospital care in Thailand is about serving citizens, not generating financial returns.","C":"A tax-funded health service owned by the state is in the public sector, and its aim is to provide healthcare rather than earn profit. Thai citizens receive free treatment, showing a service objective.","D":"The service objective is correct, but the sector is wrong. Because the state funds and runs it, the Thai health service belongs to the public sector."}}},{"id":"P1_U1_MCQ_1943","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1943","question":"A software firm in Helsinki increased its annual revenue from $250,000 to $300,000 between two consecutive years. What was the percentage increase in revenue over that period?","options":{"A":"20%","B":"25%","C":"50%","D":"16.7%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Revenue rose by $300,000 minus $250,000, which is $50,000. Dividing $50,000 by the original $250,000 gives 0.20, so the Helsinki software firm's revenue grew by 20%.","distractor_reasons":{"A":"Revenue rose by $300,000 minus $250,000, which is $50,000. Dividing $50,000 by the original $250,000 gives 0.20, so the Helsinki software firm's revenue grew by 20%.","B":"Dividing the $50,000 rise by the new revenue of $300,000 gives about 16.7%, not 25%. Percentage growth must use the old $250,000 base, giving exactly 20%.","C":"A 50% rise would require an increase of $125,000 on $250,000, far more than the $50,000 recorded. The actual percentage increase is 20%.","D":"16.7% comes from dividing $50,000 by $300,000, the wrong denominator. Using the starting revenue of $250,000 gives a 20% increase for the Helsinki firm."}}},{"id":"P1_U1_MCQ_1944","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1944","question":"A joinery in Gdańsk is owned by one person who is personally liable for all its debts. Which statement about the legal structure of this business is correct?","options":{"A":"It has limited liability and a separate legal personality","B":"Its owner faces unlimited liability for business debts","C":"It must sell shares on the stock exchange","D":"It is owned and funded by the state"},"correctOption":"B","correctAnswer":"Its owner faces unlimited liability for business debts","questionType":"MCQ","explanation":{"correct_reason":"A one-person business with personal responsibility for all debts is a sole trader, and the defining feature is unlimited liability. The Gdańsk joinery's owner can be pursued for business debts using personal assets.","distractor_reasons":{"A":"Sole traders do not have limited liability or a separate legal personality; the owner and business are legally one. The Gdańsk joinery's personal liability rules out that statement.","B":"A one-person business with personal responsibility for all debts is a sole trader, and the defining feature is unlimited liability. The Gdańsk joinery's owner can be pursued for business debts using personal assets.","C":"There are no shares to sell on any stock exchange in a sole trader business. The joinery is owned and run by one person who carries all the debt risk.","D":"State ownership would make it a public corporation, but this joinery has a single private owner. Personal liability for debts confirms it is not government-owned."}}},{"id":"P1_U1_MCQ_1945","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1945","question":"A supermarket chain in Valencia is cutting prices below its rivals to win a larger share of the local grocery market. Which objective is the chain pursuing?","options":{"A":"Profit maximisation","B":"Market share growth","C":"Survival","D":"Diversification"},"correctOption":"B","correctAnswer":"Market share growth","questionType":"MCQ","explanation":{"correct_reason":"Undercutting rivals to win a larger slice of the grocery market is a market-share objective. The Valencia chain prioritises attracting customers from competitors over short-term profit per sale.","distractor_reasons":{"A":"Cutting prices may reduce profit per item, so the aim is not immediate profit maximisation. The chain wants more customers than rivals in Valencia, which is a market-share goal.","B":"Undercutting rivals to win a larger slice of the grocery market is a market-share objective. The Valencia chain prioritises attracting customers from competitors over short-term profit per sale.","C":"Survival means covering costs in a crisis, not deliberately undercutting competitors. The Valencia supermarket is competing aggressively for market share, not merely staying open.","D":"Diversification would mean entering new markets or products. Keeping the same grocery business but chasing more customers is a market-share objective."}}},{"id":"P1_U1_MCQ_1946","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1946","question":"An inventor in Kyoto combines her savings, a small workshop and her own ideas to launch a new line of sensors. Which factor of production is represented by her ideas and willingness to take risks?","options":{"A":"Enterprise","B":"Land","C":"Labour","D":"Capital"},"correctOption":"A","correctAnswer":"Enterprise","questionType":"MCQ","explanation":{"correct_reason":"Enterprise is the factor that combines the others and involves innovation and risk-taking. The Kyoto inventor's ideas and readiness to launch the sensor line represent enterprise, distinct from her savings or workshop.","distractor_reasons":{"A":"Enterprise is the factor that combines the others and involves innovation and risk-taking. The Kyoto inventor's ideas and readiness to launch the sensor line represent enterprise, distinct from her savings or workshop.","B":"Land refers to natural resources, not ideas. The workshop is a man-made asset, and her savings are capital, so the innovative risk-taking must be enterprise.","C":"Labour is the physical and mental effort of employees, but the scenario highlights her ideas and risk-taking. That organising, innovative role is enterprise, not ordinary labour.","D":"Capital means money and man-made aids such as savings and the workshop. The inventor's ideas and willingness to risk them are the separate factor called enterprise."}}},{"id":"P1_U1_MCQ_1947","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1947","question":"In the city of Nice, 12,000 people work in services, 6,000 in manufacturing and 2,000 in farming. What proportion of employment is in the tertiary sector?","options":{"A":"60%","B":"30%","C":"10%","D":"50%"},"correctOption":"A","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"Services employing 12,000 people form the tertiary sector. Total employment in Nice is 12,000 plus 6,000 plus 2,000, which equals 20,000. Twelve thousand over 20,000 is 0.60, or 60%.","distractor_reasons":{"A":"Services employing 12,000 people form the tertiary sector. Total employment in Nice is 12,000 plus 6,000 plus 2,000, which equals 20,000. Twelve thousand over 20,000 is 0.60, or 60%.","B":"Manufacturing employs 6,000 people, 30% of the 20,000 total, but that is secondary employment. The tertiary figure is the 12,000 service workers, giving 60%.","C":"Farming accounts for 2,000 of 20,000 workers, which is 10%, yet this is primary employment. The question asks for the tertiary share, which is much larger.","D":"50% of 20,000 is 10,000 workers, not the 12,000 in services. Dividing 12,000 by 20,000 gives 60% for Nice's tertiary sector."}}},{"id":"P1_U1_MCQ_1948","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1948","question":"A large cement works in Auckland purchases raw materials in bulk and runs one modern kiln, lowering its average cost per tonne. What economic advantage is the firm enjoying?","options":{"A":"Diseconomies of scale","B":"Division of labour","C":"Economies of scale","D":"Market segmentation"},"correctOption":"C","correctAnswer":"Economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Buying inputs in bulk and spreading the cost of a modern kiln over more output reduces average cost per tonne, which is economies of scale. The Auckland cement works benefits from operating at a larger scale.","distractor_reasons":{"A":"Diseconomies of scale mean average costs rising with size, the opposite of the lower cost per tonne described. The Auckland works is gaining from scale, not suffering from it.","B":"Division of labour concerns splitting tasks among workers, not bulk purchasing or using one large kiln. The cost advantage here comes from the scale of production.","C":"Buying inputs in bulk and spreading the cost of a modern kiln over more output reduces average cost per tonne, which is economies of scale. The Auckland cement works benefits from operating at a larger scale.","D":"Market segmentation involves dividing customers into groups, which is unrelated to lower production costs. The Auckland firm's saving is an economy of scale."}}},{"id":"P1_U1_MCQ_1949","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1949","question":"Two partners in Edinburgh share profits in the ratio 3:2. If the business makes $75,000 in a year, how much does the partner with the smaller share receive?","options":{"A":"$45,000","B":"$30,000","C":"$25,000","D":"$15,000"},"correctOption":"B","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"The ratios total 3+2 = 5 parts. The smaller share is 2 parts, so 2/5 of $75,000 is $30,000. Option B is what the junior partner in Edinburgh receives.","distractor_reasons":{"A":"$45,000 is 3 parts out of 5, the larger partner's share. The question asks for the smaller share, which is 2/5 of $75,000, or $30,000.","B":"The ratios total 3+2 = 5 parts. The smaller share is 2 parts, so 2/5 of $75,000 is $30,000. Option B is what the junior partner in Edinburgh receives.","C":"$25,000 would be one third of the profit, but the agreed ratio is 3:2, not equal thirds. The smaller partner takes two fifths, which is $30,000.","D":"$15,000 is only one fifth of $75,000, whereas the smaller share is two fifths. Two parts out of five gives $30,000 for the Edinburgh partner."}}},{"id":"P1_U1_MCQ_1950","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1950","question":"A mining firm in Antofagasta has funded a new water pipeline for the nearby town to reduce local complaints about its operations. Which stakeholder group is it trying to reassure?","options":{"A":"The local community","B":"Its competitors","C":"Its suppliers","D":"Its shareholders only"},"correctOption":"A","correctAnswer":"The local community","questionType":"MCQ","explanation":{"correct_reason":"Funding a pipeline for the nearby town responds to local complaints and aims to keep the community supportive. The Antofagasta mining firm is addressing residents affected by its operations, not rivals or suppliers.","distractor_reasons":{"A":"Funding a pipeline for the nearby town responds to local complaints and aims to keep the community supportive. The Antofagasta mining firm is addressing residents affected by its operations, not rivals or suppliers.","B":"Competitors are not mentioned and would not be reassured by a local water project. The pipeline is aimed at townspeople living near the mine in Antofagasta.","C":"Suppliers sell inputs to the mine; they are not the group complaining about its local impact. The intended beneficiaries are residents of the nearby town.","D":"Shareholders may welcome better relations, but the project directly targets the community. Saying shareholders only are being reassured ignores the town's complaints."}}},{"id":"P1_U1_MCQ_1951","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1951","question":"A confectionery in Zurich buys cocoa and sugar worth $2 for each box of chocolates and sells the box for $7. Which figure represents the added value created per box?","options":{"A":"$2","B":"$7","C":"$9","D":"$5"},"correctOption":"D","correctAnswer":"$5","questionType":"MCQ","explanation":{"correct_reason":"Added value per box is selling price minus the cost of bought-in materials: $7 minus $2 equals $5. The Zurich confectionery adds $5 of value through its production process.","distractor_reasons":{"A":"$2 is the cost of the bought-in cocoa and sugar, not the added value. Added value is the selling price of $7 less those $2 of materials, which is $5 per box.","B":"$7 is the selling price, which includes the cost of materials. Added value excludes the $2 of inputs, so the Zurich firm creates $5 of value per box.","C":"$9 adds the $2 materials to the $7 price, which is not a meaningful measure. The correct calculation is $7 minus $2, giving $5 of added value.","D":"Added value per box is selling price minus the cost of bought-in materials: $7 minus $2 equals $5. The Zurich confectionery adds $5 of value through its production process."}}},{"id":"P1_U1_MCQ_1952","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1952","question":"A forestry company in Karelia plants and harvests pine trees, selling the timber to local mills. Which sector of the economy does this activity belong to?","options":{"A":"Secondary","B":"Tertiary","C":"Primary","D":"Public"},"correctOption":"C","correctAnswer":"Primary","questionType":"MCQ","explanation":{"correct_reason":"Planting and harvesting trees extracts a natural resource, which is the defining feature of primary production. The Karelia forestry company works directly with nature rather than manufacturing or providing a service.","distractor_reasons":{"A":"Secondary production processes raw materials into goods, but harvesting pine is extraction. Manufacturing begins after the timber reaches a sawmill, not in the Karelia forest.","B":"Tertiary activities provide services, whereas growing and felling trees produces a raw material. The forestry company's work is primary, not a service to consumers.","C":"Planting and harvesting trees extracts a natural resource, which is the defining feature of primary production. The Karelia forestry company works directly with nature rather than manufacturing or providing a service.","D":"Public sector refers to state ownership, not the type of activity. The sector classification here is by economic activity, which makes Karelia's tree harvesting primary."}}},{"id":"P1_U1_MCQ_1953","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1953","question":"A home-based candle maker in Ghent has grown so much that she is considering converting her sole tradership into a company. Which is likely to be a key advantage of becoming a company?","options":{"A":"She keeps every profit for herself","B":"Limited liability and easier access to finance","C":"No need to keep any records","D":"Freedom from all regulation"},"correctOption":"B","correctAnswer":"Limited liability and easier access to finance","questionType":"MCQ","explanation":{"correct_reason":"Forming a company gives limited liability, protecting personal assets, and makes it easier to raise finance by issuing shares. The Ghent candle maker's growth makes these advantages more important than the simplicity of sole trading.","distractor_reasons":{"A":"As a company owner she would still benefit from profits, but keeping every penny is not the key advantage. Limited liability and finance access drive the conversion in Ghent.","B":"Forming a company gives limited liability, protecting personal assets, and makes it easier to raise finance by issuing shares. The Ghent candle maker's growth makes these advantages more important than the simplicity of sole trading.","C":"Companies face more record-keeping, not less. Accounts must be prepared and filed, so avoiding records cannot be the reason for incorporating the candle business.","D":"Companies are subject to regulations and company law, so freedom from all rules is false. The benefit is liability protection and finance, not deregulation."}}},{"id":"P1_U1_MCQ_1954","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1954","question":"The national electricity supplier in Zambia is owned by the government and must provide power to remote villages even though some connections lose money. What type of organisation is it?","options":{"A":"A public limited company","B":"A sole trader","C":"A cooperative","D":"A public corporation"},"correctOption":"D","correctAnswer":"A public corporation","questionType":"MCQ","explanation":{"correct_reason":"A public corporation is a state-owned body created to provide a service, often accepting losses to serve remote communities. The Zambia electricity supplier's government ownership and social obligation match this structure.","distractor_reasons":{"A":"A public limited company has private shareholders seeking returns and sells shares publicly. The Zambia supplier is wholly state-owned with a service duty, so it is a public corporation.","B":"A sole trader has one private owner, quite different from a national state-owned supplier. The obligation to serve remote villages also points to a public body.","C":"A cooperative is owned by its members, such as farmers or workers. The electricity supplier is owned by the government, not by member-consumers.","D":"A public corporation is a state-owned body created to provide a service, often accepting losses to serve remote communities. The Zambia electricity supplier's government ownership and social obligation match this structure."}}},{"id":"P1_U1_MCQ_1955","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1955","question":"A company in Bilbao has 5,000 shareholders. If 1,250 of them attend the annual general meeting, what percentage of the total shareholder base is that?","options":{"A":"15%","B":"30%","C":"25%","D":"20%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"One thousand two hundred and fifty shareholders out of 5,000 attended. Dividing 1,250 by 5,000 gives 0.25, which is 25%. Option C is the attendance rate at the Bilbao company's meeting.","distractor_reasons":{"A":"15% of 5,000 is 750 people, not the 1,250 who attended. One thousand two hundred and fifty over 5,000 equals 25%, so a quarter of shareholders were present.","B":"30% of 5,000 would be 1,500 attendees, more than the 1,250 recorded. The correct proportion is 1,250 divided by 5,000, giving 25%.","C":"One thousand two hundred and fifty shareholders out of 5,000 attended. Dividing 1,250 by 5,000 gives 0.25, which is 25%. Option C is the attendance rate at the Bilbao company's meeting.","D":"20% of 5,000 is 1,000 shareholders, fewer than the 1,250 who came. The actual attendance is one quarter, or 25%, of the Bilbao shareholder base."}}},{"id":"P1_U1_MCQ_1956","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1956","question":"A brewery in Leuven uses malt, hops, water and machinery to produce beer for pubs. Which term best describes the process of turning these inputs into beer?","options":{"A":"Consumption","B":"Saving","C":"Retailing","D":"Production"},"correctOption":"D","correctAnswer":"Production","questionType":"MCQ","explanation":{"correct_reason":"Combining malt, hops, water and machinery to create beer is production: the transformation of inputs into outputs. The Leuven brewery converts raw materials into a drink that can be sold to pubs.","distractor_reasons":{"A":"Consumption means using the finished beer, which happens in pubs, not at the brewery. The Leuven process described is making the product, not consuming it.","B":"Saving means setting aside income rather than making goods. The brewery is actively combining inputs, so the relevant activity is production.","C":"Retailing is selling to final customers, which pubs do. The brewery supplies those pubs, so its own activity is production, not retail.","D":"Combining malt, hops, water and machinery to create beer is production: the transformation of inputs into outputs. The Leuven brewery converts raw materials into a drink that can be sold to pubs."}}},{"id":"P1_U1_MCQ_1957","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1957","question":"In the region of Biobío, 6,000 people work in forestry, 9,000 in factories and 15,000 in shops and offices. What percentage works in the primary sector?","options":{"A":"20%","B":"30%","C":"50%","D":"25%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Forestry is primary production, employing 6,000 people. The regional total is 6,000 plus 9,000 plus 15,000, which equals 30,000. Dividing 6,000 by 30,000 gives 0.20, or 20%.","distractor_reasons":{"A":"Forestry is primary production, employing 6,000 people. The regional total is 6,000 plus 9,000 plus 15,000, which equals 30,000. Dividing 6,000 by 30,000 gives 0.20, or 20%.","B":"Factory workers number 9,000, which is 30% of the 30,000 total, but that is secondary employment. The primary sector here is forestry, with 6,000 workers in Biobío.","C":"Shops and offices employ 15,000 people, half the total, but they are tertiary. The question asks for the 6,000 forestry workers, a 20% share.","D":"25% of 30,000 would be 7,500 workers, more than the 6,000 in forestry. Six thousand out of 30,000 equals 20% for the Biobío primary sector."}}},{"id":"P1_U1_MCQ_1958","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1958","question":"An entrepreneur in Kaohsiung invested her savings in a food cart despite uncertain sales, hoping to attract lunchtime customers. Which feature of enterprise does this show most clearly?","options":{"A":"Avoiding uncertainty altogether","B":"Guaranteeing a fixed salary","C":"Willingness to take a financial risk","D":"Owning natural resources"},"correctOption":"C","correctAnswer":"Willingness to take a financial risk","questionType":"MCQ","explanation":{"correct_reason":"Investing savings in a food cart when sales are uncertain shows willingness to take financial risk, a central feature of enterprise. The Kaohsiung founder accepts possible loss in pursuit of customers.","distractor_reasons":{"A":"The entrepreneur does not avoid uncertainty; she commits savings despite not knowing sales. That acceptance of risk is the opposite of avoiding it.","B":"She is not drawing a guaranteed salary; her income depends on the cart's success. The scenario is about risk and initiative, not fixed pay.","C":"Investing savings in a food cart when sales are uncertain shows willingness to take financial risk, a central feature of enterprise. The Kaohsiung founder accepts possible loss in pursuit of customers.","D":"A food cart does not involve owning natural resources such as land or minerals. The key feature shown is risk-taking, not resource ownership."}}},{"id":"P1_U1_MCQ_1959","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1959","question":"A technology startup in Dublin is deciding whether to become a private limited company. Which is a likely disadvantage of this legal structure compared with sole trading?","options":{"A":"Unlimited personal liability","B":"More administration and legal formalities","C":"Inability to keep any profit","D":"Owners cannot make decisions"},"correctOption":"B","correctAnswer":"More administration and legal formalities","questionType":"MCQ","explanation":{"correct_reason":"A private limited company must register documents, keep accounts and follow company law, creating more paperwork than sole trading. The Dublin startup trades higher administration for limited liability and finance access.","distractor_reasons":{"A":"Limited liability is an advantage of a company, not a disadvantage; sole traders are the ones with unlimited personal liability. The company's owners risk only their investment.","B":"A private limited company must register documents, keep accounts and follow company law, creating more paperwork than sole trading. The Dublin startup trades higher administration for limited liability and finance access.","C":"Company owners can retain profits or distribute them as dividends; they do not lose all profit. The drawback is administrative burden, not a ban on keeping earnings.","D":"The company's directors still make decisions, so owners are not powerless. The real disadvantage for the Dublin startup is extra legal and administrative work."}}},{"id":"P1_U1_MCQ_1960","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1960","question":"A football club in Naples reinvests ticket money into youth facilities and local community projects rather than paying large dividends. Which objective is the club emphasising?","options":{"A":"Maximising shareholder dividends","B":"Cutting every possible cost","C":"Beating every rival at any cost","D":"Serving community and sporting goals"},"correctOption":"D","correctAnswer":"Serving community and sporting goals","questionType":"MCQ","explanation":{"correct_reason":"Putting ticket income into youth and local projects shows the Naples club prioritises community and sporting aims over paying owners. Its objective is service to supporters and the area rather than dividend maximisation.","distractor_reasons":{"A":"Large dividends are explicitly not paid, so maximising shareholder returns is not the emphasis. The Naples club channels money back into facilities and community work.","B":"Reinvesting in youth facilities is spending, not cutting costs. The club's priority is where money goes, not reducing every expense.","C":"Beating rivals is not the stated aim; the investment is in youth and community projects. Winning may matter, but the scenario emphasises broader sporting and social goals.","D":"Putting ticket income into youth and local projects shows the Naples club prioritises community and sporting aims over paying owners. Its objective is service to supporters and the area rather than dividend maximisation."}}},{"id":"P1_U1_MCQ_1961","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1961","question":"A furniture restorer in Utrecht buys old chairs, repairs them and sells them at a much higher price. Which economic activity creates the added value here?","options":{"A":"Delivering the chairs to customers","B":"Repairing and refurbishing the chairs","C":"Advertising the chairs online","D":"Paying for the old chairs"},"correctOption":"B","correctAnswer":"Repairing and refurbishing the chairs","questionType":"MCQ","explanation":{"correct_reason":"Added value comes from transforming inputs into more valuable outputs. By repairing and refurbishing old chairs, the Utrecht restorer turns low-value items into furniture that sells for more.","distractor_reasons":{"A":"Delivery moves the finished chairs to buyers but does not restore them. The Utrecht restorer creates value through the repair work before delivery takes place.","B":"Added value comes from transforming inputs into more valuable outputs. By repairing and refurbishing old chairs, the Utrecht restorer turns low-value items into furniture that sells for more.","C":"Advertising may attract buyers but does not physically improve the chairs. The added value is created when the restorer repairs them in Utrecht.","D":"Paying for old chairs is an input cost, not value creation. The restorer adds value by improving the chairs and selling them for a higher price."}}},{"id":"P1_U1_MCQ_1962","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1962","question":"A company in Kumasi processes local cocoa beans into chocolate and employs 200 workers in its factory. Which economic sector does this business belong to today?","options":{"A":"Primary","B":"Tertiary","C":"Secondary","D":"Public sector"},"correctOption":"C","correctAnswer":"Secondary","questionType":"MCQ","explanation":{"correct_reason":"Turning cocoa beans into chocolate is manufacturing, which is the secondary sector. The Kumasi factory takes a raw agricultural material and processes it into a finished product for consumers.","distractor_reasons":{"A":"Growing cocoa is primary, but the Kumasi company does not farm the beans; it processes them. Manufacturing places the business in the secondary sector, not primary.","B":"A tertiary business provides services, whereas this factory makes a physical product. Processing beans into chocolate is clearly secondary production.","C":"Turning cocoa beans into chocolate is manufacturing, which is the secondary sector. The Kumasi factory takes a raw agricultural material and processes it into a finished product for consumers.","D":"Public sector means state-owned, which is not stated for the Kumasi company. Sector here is classified by activity, which makes it secondary."}}},{"id":"P1_U1_MCQ_1963","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1963","question":"A hotel in Antalya increased its workforce from 80 to 96 staff after adding a new wing. By what percentage did employment rise over that period?","options":{"A":"20%","B":"25%","C":"16%","D":"80%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The hotel added 96 minus 80, which is 16 staff. Dividing 16 by the original 80 gives 0.20, or a 20% increase in the Antalya hotel's workforce.","distractor_reasons":{"A":"The hotel added 96 minus 80, which is 16 staff. Dividing 16 by the original 80 gives 0.20, or a 20% increase in the Antalya hotel's workforce.","B":"Dividing the 16 new staff by the final 96 gives about 16.7%, not 25%. Percentage growth uses the starting 80, so the correct rise is 20%.","C":"16% would mean about 13 extra staff, not the 16 actually hired. Sixteen divided by the original 80 is 20% growth for the Antalya hotel.","D":"80% of 80 would be 64 new staff, far more than 16. The workforce grew from 80 to 96, which is an increase of one fifth, or 20%."}}},{"id":"P1_U1_MCQ_1964","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1964","question":"Two architects in Helsinki run a partnership and disagree about a large project, with both personally liable for its debts. Which disadvantage of partnerships does this illustrate?","options":{"A":"Limited liability protection","B":"Shared decisions can cause disagreement and unlimited liability","C":"Inability to hire any staff","D":"An inability to make any profit"},"correctOption":"B","correctAnswer":"Shared decisions can cause disagreement and unlimited liability","questionType":"MCQ","explanation":{"correct_reason":"Partners share decisions, which can lead to disputes, and they normally have unlimited liability for business debts. The Helsinki architects' disagreement and personal exposure show two classic drawbacks of a partnership.","distractor_reasons":{"A":"Limited liability is not a feature of a typical partnership; partners usually have unlimited liability. So it cannot be the disadvantage described in Helsinki.","B":"Partners share decisions, which can lead to disputes, and they normally have unlimited liability for business debts. The Helsinki architects' disagreement and personal exposure show two classic drawbacks of a partnership.","C":"Partnerships can employ staff; nothing prevents the architects hiring assistants. The problem is decision-making and liability, not a ban on employees.","D":"Partnerships can certainly make profits, which are shared among partners. The scenario is about disagreements and debt exposure, not an inability to earn."}}},{"id":"P1_U1_MCQ_1965","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1965","question":"A factory in Łódź has introduced longer shifts to meet a large order, and workers have complained about fatigue. Which stakeholder group's interests are most directly affected?","options":{"A":"Shareholders","B":"Employees","C":"Suppliers","D":"Customers"},"correctOption":"B","correctAnswer":"Employees","questionType":"MCQ","explanation":{"correct_reason":"The longer shifts directly affect the factory workers, who are employees, and their complaints about fatigue reflect their interests. The Łódź management must weigh these against the need to fulfil the order.","distractor_reasons":{"A":"Shareholders may gain from fulfilling the order, but they are not experiencing longer shifts. The group directly affected is the workforce in Łódź.","B":"The longer shifts directly affect the factory workers, who are employees, and their complaints about fatigue reflect their interests. The Łódź management must weigh these against the need to fulfil the order.","C":"Suppliers deliver materials and are not doing the extra hours. The complaint about fatigue comes from employees, not from the factory's suppliers.","D":"Customers want the order delivered but are not working the shifts. The stakeholder raising concerns is the factory's employees in Łódź."}}},{"id":"P1_U1_MCQ_1966","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1966","question":"A company in Medellín has developed an affordable water filter for households that lack clean drinking water. Which basic economic problem is it trying to address?","options":{"A":"Satisfying needs with scarce resources","B":"Eliminating all competition","C":"Maximising share price immediately","D":"Avoiding the use of factors of production"},"correctOption":"A","correctAnswer":"Satisfying needs with scarce resources","questionType":"MCQ","explanation":{"correct_reason":"Clean water is a need, and resources are scarce, so producing an affordable filter uses limited factors to satisfy that need. The Medellín firm is responding to the basic economic problem of scarcity and wants.","distractor_reasons":{"A":"Clean water is a need, and resources are scarce, so producing an affordable filter uses limited factors to satisfy that need. The Medellín firm is responding to the basic economic problem of scarcity and wants.","B":"The company is not trying to remove all rivals; it is meeting a household need. Competition may exist, but the scenario focuses on providing clean water.","C":"An immediate share price maximisation is not stated; the product targets a basic need. The firm uses resources to address scarcity rather than stock market goals.","D":"Making a filter necessarily uses factors of production such as labour and capital. Avoiding them is impossible, so this cannot be the company's aim."}}},{"id":"P1_U1_MCQ_1967","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1967","question":"In the city of Lviv, 4,000 people work in farming, 5,000 in manufacturing and 11,000 in services. What percentage of the workforce is in secondary employment?","options":{"A":"25%","B":"20%","C":"55%","D":"30%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Manufacturing is secondary employment, with 5,000 workers. Total employment in Lviv is 4,000 plus 5,000 plus 11,000, which equals 20,000. Five thousand over 20,000 is 0.25, or 25%.","distractor_reasons":{"A":"Manufacturing is secondary employment, with 5,000 workers. Total employment in Lviv is 4,000 plus 5,000 plus 11,000, which equals 20,000. Five thousand over 20,000 is 0.25, or 25%.","B":"Farming employs 4,000 people, 20% of the 20,000 total, but it is primary. The secondary figure comes from the 5,000 manufacturing workers, giving 25%.","C":"Services employ 11,000 people, 55% of Lviv's workforce, yet they are tertiary. The question asks about secondary employment, which is 25%.","D":"30% of 20,000 is 6,000 workers, more than the 5,000 in manufacturing. Five thousand out of 20,000 equals 25% for the secondary sector."}}},{"id":"P1_U1_MCQ_1968","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1968","question":"A rafting operator in Queenstown wants to judge its size relative to a competitor. Which figure would best show the scale of its trading activity?","options":{"A":"Its annual turnover","B":"Its owner's age","C":"The number of rivers nearby","D":"Its opening year"},"correctOption":"A","correctAnswer":"Its annual turnover","questionType":"MCQ","explanation":{"correct_reason":"Turnover measures the total value of sales and is a standard indicator of business size. The Queenstown operator can compare its trading scale with a rival by looking at annual turnover.","distractor_reasons":{"A":"Turnover measures the total value of sales and is a standard indicator of business size. The Queenstown operator can compare its trading scale with a rival by looking at annual turnover.","B":"An owner's age has no bearing on the scale of the business. Size is measured by financial or employment figures such as turnover.","C":"Nearby rivers describe the environment, not the firm's own output. A large and small operator could use the same river, so this does not measure size.","D":"The year a firm opened is history, not current scale. The Queenstown operator should use turnover to compare trading activity."}}},{"id":"P1_U1_MCQ_1969","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1969","question":"Three friends in Brno contribute $20,000, $30,000 and $50,000 as capital to a company. What percentage of the total capital did the largest contributor provide?","options":{"A":"20%","B":"50%","C":"30%","D":"40%"},"correctOption":"B","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"Total capital is $20,000 plus $30,000 plus $50,000, which equals $100,000. The largest contribution is $50,000, so 50,000 divided by 100,000 is 0.50, or 50%.","distractor_reasons":{"A":"$20,000 is 20% of the $100,000 total, but that is the smallest contribution. The largest provider gave $50,000, which is 50%.","B":"Total capital is $20,000 plus $30,000 plus $50,000, which equals $100,000. The largest contribution is $50,000, so 50,000 divided by 100,000 is 0.50, or 50%.","C":"$30,000 is 30% of the total, the middle contribution. The question asks for the biggest share, which is $50,000 out of $100,000, or 50%.","D":"40% of $100,000 is $40,000, which no partner contributed. The largest amount, $50,000, represents half the Brno company's capital in total."}}},{"id":"P1_U1_MCQ_1970","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1970","question":"Managers at an insurance firm in Zurich want to spend more on staff training, while shareholders want the money paid out as dividends. Which stakeholder conflict is this?","options":{"A":"Suppliers versus employees","B":"Managers versus shareholders","C":"Customers versus the government","D":"Employees versus customers"},"correctOption":"B","correctAnswer":"Managers versus shareholders","questionType":"MCQ","explanation":{"correct_reason":"Managers favour retaining earnings for training, whereas shareholders prefer dividends. The opposing preferences over how funds are used create a conflict between management and owners in Zurich.","distractor_reasons":{"A":"Suppliers are not part of this disagreement; the dispute is over spending on training versus dividends. Employees may benefit from training, but they are not the opposing group.","B":"Managers favour retaining earnings for training, whereas shareholders prefer dividends. The opposing preferences over how funds are used create a conflict between management and owners in Zurich.","C":"Customers and government are not mentioned. The conflict is internal, between managers wanting investment and shareholders wanting dividend payouts in Zurich.","D":"Customers are unaffected by the training budget decision described here. The clash is between management and owners over the use of profits."}}},{"id":"P1_U1_MCQ_1971","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1971","question":"A garment factory in Dhaka assigns cutting, stitching and ironing to separate teams, raising daily output. Which advantage of division of labour is illustrated here?","options":{"A":"Reduced output per worker","B":"Higher average costs always","C":"Greater efficiency and higher output","D":"Elimination of specialisation"},"correctOption":"C","correctAnswer":"Greater efficiency and higher output","questionType":"MCQ","explanation":{"correct_reason":"Dividing garment production into cutting, stitching and ironing lets each team specialise, which raises speed and daily output. The Dhaka factory benefits from greater efficiency, a key advantage of division of labour.","distractor_reasons":{"A":"The factory's daily output rose, so reduced output per worker is wrong. Specialisation normally increases productivity as workers repeat a narrow task.","B":"Higher average costs are not shown; the gain is more output. Division of labour can lower unit costs through efficiency, so this option contradicts the scenario.","C":"Dividing garment production into cutting, stitching and ironing lets each team specialise, which raises speed and daily output. The Dhaka factory benefits from greater efficiency, a key advantage of division of labour.","D":"The factory is increasing specialisation by separating tasks, not removing it. Each team focuses on one stage, which is the essence of division of labour."}}},{"id":"P1_U1_MCQ_1972","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1972","question":"In Ghana, a state-owned railway carries passengers and a privately owned cocoa farm grows beans for export. Which statement about their economic sectors is correct?","options":{"A":"The railway is public sector; the cocoa farm is primary private sector","B":"Both are in the secondary sector","C":"The railway is private; the farm is public","D":"Both are tertiary sector businesses"},"correctOption":"A","correctAnswer":"The railway is public sector; the cocoa farm is primary private sector","questionType":"MCQ","explanation":{"correct_reason":"The state-owned railway belongs to the public sector, while the cocoa farm is privately owned and extracts a crop, making it primary. Ownership and activity together place them in different sectors in Ghana.","distractor_reasons":{"A":"The state-owned railway belongs to the public sector, while the cocoa farm is privately owned and extracts a crop, making it primary. Ownership and activity together place them in different sectors in Ghana.","B":"A cocoa farm is primary, not secondary, and a railway provides a service, not manufacturing. Classifying both as secondary misreads their activities.","C":"This reverses ownership: the railway is state-owned and the farm is private. The cocoa farm's crop extraction also makes it primary.","D":"A cocoa farm is primary, not tertiary, so both cannot be tertiary. Only the railway, as a service, fits the tertiary category."}}},{"id":"P1_U1_MCQ_1973","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1973","question":"A mobile phone brand in Chengdu doubled its sales while total market sales stayed constant over the same year. What happened to its market share?","options":{"A":"It halved","B":"It increased","C":"It stayed the same","D":"It became zero"},"correctOption":"B","correctAnswer":"It increased","questionType":"MCQ","explanation":{"correct_reason":"If a firm's sales double while the whole market remains unchanged, its share of that market must rise. The Chengdu brand captured a larger proportion of constant total sales.","distractor_reasons":{"A":"Halving would require sales to fall relative to the market. Here the Chengdu brand's sales doubled, so its share clearly grew, not shrank.","B":"If a firm's sales double while the whole market remains unchanged, its share of that market must rise. The Chengdu brand captured a larger proportion of constant total sales.","C":"A constant share would need sales to grow at the same rate as the market. With total sales unchanged, doubling its own sales must raise the share.","D":"Zero share would mean no sales at all, the opposite of doubling sales. The Chengdu firm's market share increased substantially."}}},{"id":"P1_U1_MCQ_1974","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1974","question":"A franchisee in Perth must follow the parent company's rules and pay a share of revenue, limiting her freedom. Which disadvantage of franchising does this show?","options":{"A":"Loss of independence and ongoing fees","B":"Unlimited liability for the parent firm","C":"A complete absence of brand recognition","D":"Inability to sell any products"},"correctOption":"A","correctAnswer":"Loss of independence and ongoing fees","questionType":"MCQ","explanation":{"correct_reason":"Franchisees give up some independence because they must follow the parent's procedures and pay royalties. The Perth outlet owner's constrained freedom and fee payments are the classic costs of joining a franchise.","distractor_reasons":{"A":"Franchisees give up some independence because they must follow the parent's procedures and pay royalties. The Perth outlet owner's constrained freedom and fee payments are the classic costs of joining a franchise.","B":"The parent firm's liability is not the issue; the franchisee's own business is separate. The drawback described is loss of autonomy and fee payments.","C":"A major advantage of franchising is using an established brand, so an absence of recognition is wrong. The Perth outlet gains brand awareness but loses freedom.","D":"Franchisees sell the brand's products; they are not unable to sell anything. The limitation is on decision-making, not on trading altogether."}}},{"id":"P1_U1_MCQ_1975","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1975","question":"A factory in Graz employs 2,500 workers and plans to make 500 of them redundant. What percentage of the workforce will lose their jobs as a result?","options":{"A":"10%","B":"30%","C":"25%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Five hundred workers out of 2,500 are to be made redundant. Dividing 500 by 2,500 gives 0.20, which is 20%. Option D is the share of the Graz workforce affected.","distractor_reasons":{"A":"10% of 2,500 is 250 workers, half the number actually affected. Five hundred divided by 2,500 equals 20% of the Graz factory workforce.","B":"30% of 2,500 is 750 redundancies, more than the 500 planned. The correct proportion is 500 over 2,500, giving 20%.","C":"25% of 2,500 is 625 workers, not the 500 stated. Five hundred out of 2,500 simplifies to one fifth, or 20%.","D":"Five hundred workers out of 2,500 are to be made redundant. Dividing 500 by 2,500 gives 0.20, which is 20%. Option D is the share of the Graz workforce affected."}}},{"id":"P1_U1_MCQ_1976","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1976","question":"A vineyard in Mendoza owns the land, vines and irrigation system used to grow grapes. Which factor of production do the land and vines represent?","options":{"A":"Labour","B":"Capital","C":"Land","D":"Enterprise"},"correctOption":"C","correctAnswer":"Land","questionType":"MCQ","explanation":{"correct_reason":"Land as a factor includes natural resources and improvements fixed to the site, such as the Mendoza vineyard's soil, vines and irrigation. They are not labour or movable man-made capital.","distractor_reasons":{"A":"Labour is the effort of workers picking grapes, not the land or vines. The Mendoza vineyard's soil and irrigation belong to the land factor.","B":"Capital means man-made aids like tractors and machinery. Vines planted in the ground and the site itself are treated as land, not capital.","C":"Land as a factor includes natural resources and improvements fixed to the site, such as the Mendoza vineyard's soil, vines and irrigation. They are not labour or movable man-made capital.","D":"Enterprise is the organising and risk-taking role of the owner. The vineyard's physical land and vines are a factor of production called land."}}},{"id":"P1_U1_MCQ_1977","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1977","question":"In the city of Tampere, 3,000 people work in farming, 7,000 in factories and 10,000 in services. What percentage of workers is employed in the primary sector?","options":{"A":"15%","B":"35%","C":"50%","D":"25%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Farming is primary employment, with 3,000 workers. Total employment in Tampere is 3,000 plus 7,000 plus 10,000, which equals 20,000. Three thousand divided by 20,000 is 0.15, or 15%.","distractor_reasons":{"A":"Farming is primary employment, with 3,000 workers. Total employment in Tampere is 3,000 plus 7,000 plus 10,000, which equals 20,000. Three thousand divided by 20,000 is 0.15, or 15%.","B":"Factory workers number 7,000, which is 35% of the 20,000 total, but that is secondary employment. The primary sector here is farming, with 3,000 workers.","C":"Services employ 10,000 people, half the Tampere workforce, but they are tertiary. The question asks about the 3,000 farmers, a 15% share.","D":"25% of 20,000 is 5,000 workers, more than the 3,000 in farming. Three thousand out of 20,000 equals 15% for the primary sector."}}},{"id":"P1_U1_MCQ_1978","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1978","question":"A bakery chain in Wrocław reinvests most of its profit into new ovens and shops instead of paying owners large dividends. Which aim is it pursuing?","options":{"A":"Survival only","B":"Maximising current dividends","C":"Reducing total output","D":"Long-term growth and expansion"},"correctOption":"D","correctAnswer":"Long-term growth and expansion","questionType":"MCQ","explanation":{"correct_reason":"Reinvesting earnings into new ovens and shops aims to expand the business over time. The Wrocław bakery prioritises long-term growth rather than paying out profits immediately to owners.","distractor_reasons":{"A":"Survival means covering costs in a crisis, not investing in new ovens and shops. The Wrocław chain is actively expanding, which is a growth aim.","B":"Paying large dividends is explicitly avoided, so maximising current payouts is not the aim. Profits are retained to fund more shops.","C":"Buying new ovens increases capacity rather than reducing output. The bakery's reinvestment shows expansion, not a cut in production at all.","D":"Reinvesting earnings into new ovens and shops aims to expand the business over time. The Wrocław bakery prioritises long-term growth rather than paying out profits immediately to owners."}}},{"id":"P1_U1_MCQ_1979","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1979","question":"A manufacturing firm in Ljubljana has shareholders whose personal savings are protected if the business fails. Which feature of a company does this situation describe?","options":{"A":"Unlimited liability","B":"Public ownership","C":"Limited liability","D":"Partnership status"},"correctOption":"C","correctAnswer":"Limited liability","questionType":"MCQ","explanation":{"correct_reason":"Limited liability means shareholders risk only the amount they invested, protecting personal savings if the firm fails. The Ljubljana manufacturer's shareholders enjoy exactly that protection.","distractor_reasons":{"A":"Unlimited liability would put personal savings at risk, the opposite of the protection described. The Ljubljana shareholders are shielded, so liability is limited.","B":"Public ownership means the state controls the firm, which is not stated here. The feature described is limited liability, not government ownership.","C":"Limited liability means shareholders risk only the amount they invested, protecting personal savings if the firm fails. The Ljubljana manufacturer's shareholders enjoy exactly that protection.","D":"Partners usually have unlimited liability, so they would not be protected. The Ljubljana firm's shareholder protection shows it is a company, not a partnership."}}},{"id":"P1_U1_MCQ_1980","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1980","question":"A chemical plant in Rotterdam has been told by regulators to cut emissions below a new legal limit, even though this raises costs. Which stakeholder is imposing this change?","options":{"A":"Customers","B":"Suppliers","C":"Shareholders","D":"The government"},"correctOption":"D","correctAnswer":"The government","questionType":"MCQ","explanation":{"correct_reason":"Regulators setting and enforcing an emissions limit represent the government, which can require businesses to change practices. The Rotterdam plant must comply even though cutting emissions raises its costs.","distractor_reasons":{"A":"Customers buy the chemicals but are not setting legal limits. The requirement comes from regulators, so the influencing stakeholder is the government.","B":"Suppliers provide inputs and do not impose emission rules. The Rotterdam plant's new obligation is a legal one from the authorities.","C":"Shareholders might resist higher costs, but they are not imposing the limit. The external requirement comes from government regulators in the Netherlands.","D":"Regulators setting and enforcing an emissions limit represent the government, which can require businesses to change practices. The Rotterdam plant must comply even though cutting emissions raises its costs."}}},{"id":"P1_U1_MCQ_1981","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1981","question":"A bookshop in Uppsala buys second-hand books for $4 each and sells them for $9 after cleaning and rebinding. What is the added value per book?","options":{"A":"$4","B":"$9","C":"$5","D":"$13"},"correctOption":"C","correctAnswer":"$5","questionType":"MCQ","explanation":{"correct_reason":"Added value is selling price minus the cost of bought-in books: $9 minus $4 equals $5. The Uppsala shop creates $5 of value by cleaning and rebinding each book.","distractor_reasons":{"A":"$4 is the purchase cost of a second-hand book, not the added value. Added value is the $9 selling price less that $4 cost, which is $5.","B":"$9 is the final selling price, which includes the original $4 cost. The value the Uppsala shop adds is the $5 difference.","C":"Added value is selling price minus the cost of bought-in books: $9 minus $4 equals $5. The Uppsala shop creates $5 of value by cleaning and rebinding each book.","D":"$13 incorrectly adds $4 and $9. The correct calculation is $9 minus $4, giving $5 of added value per book."}}},{"id":"P1_U1_MCQ_1982","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1982","question":"In Chile, the national copper company is state-controlled and employs thousands of workers, while most retail banks are privately owned. Which statement about their sectors is correct?","options":{"A":"Both are public sector","B":"Copper is private, banks are public","C":"Both are primary sector","D":"Copper is public sector, banks are private sector"},"correctOption":"D","correctAnswer":"Copper is public sector, banks are private sector","questionType":"MCQ","explanation":{"correct_reason":"A state-controlled copper company belongs to the public sector, while privately owned banks are in the private sector. Ownership determines the classification in Chile, not the industry itself.","distractor_reasons":{"A":"The banks are privately owned, so they cannot be public sector. Only the state-controlled copper company is publicly owned in Chile.","B":"This reverses the ownership: copper is state-controlled and banks are privately owned. The public-private split should follow who controls each firm.","C":"Copper extraction is primary, but banking is a tertiary service, so both cannot be primary. The question concerns ownership sectors.","D":"A state-controlled copper company belongs to the public sector, while privately owned banks are in the private sector. Ownership determines the classification in Chile, not the industry itself."}}},{"id":"P1_U1_MCQ_1983","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1983","question":"A café chain in Malmö saw its annual profit fall from $60,000 to $48,000 in one year. What was the percentage decrease in profit over that year?","options":{"A":"20%","B":"25%","C":"12%","D":"80%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Profit fell by $60,000 minus $48,000, which is $12,000. Dividing $12,000 by the original $60,000 gives 0.20, a 20% decrease for the Malmö café chain.","distractor_reasons":{"A":"Profit fell by $60,000 minus $48,000, which is $12,000. Dividing $12,000 by the original $60,000 gives 0.20, a 20% decrease for the Malmö café chain.","B":"Dividing the $12,000 fall by the new profit of $48,000 gives 25%, but percentage change uses the original $60,000. The correct decrease is 20%.","C":"$12,000 is the absolute fall in dollars, not a percentage. Compared with the $60,000 starting profit, the drop is 20%.","D":"80% of $60,000 would be $48,000, the remaining profit, not the decrease. The Malmö chain's profit fell by one fifth, or 20%."}}},{"id":"P1_U1_MCQ_1984","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1984","question":"A photographer in Bruges runs a sole trader business and enjoys being her own boss. Which advantage of sole trading does this clearly illustrate for her?","options":{"A":"Limited liability","B":"Easy access to large amounts of share capital","C":"Independence and keeping all profits","D":"Free public auditing"},"correctOption":"C","correctAnswer":"Independence and keeping all profits","questionType":"MCQ","explanation":{"correct_reason":"A sole trader controls the business, makes her own decisions and keeps all profits. The Bruges photographer's independence and ownership of earnings are the classic advantages of sole trading.","distractor_reasons":{"A":"Sole traders have unlimited liability, not limited liability. The photographer's own assets back the business, so liability protection is not an advantage.","B":"A sole trader cannot issue shares to raise capital, so large share capital is unavailable. Finance is usually limited to personal savings and loans.","C":"A sole trader controls the business, makes her own decisions and keeps all profits. The Bruges photographer's independence and ownership of earnings are the classic advantages of sole trading.","D":"Sole traders are not required to have public audits; that applies to larger companies. The benefit here is independence, not auditing."}}},{"id":"P1_U1_MCQ_1985","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1985","question":"A small hotel in Innsbruck is fully booked every night but its owner decides not to expand, preferring to maintain personal service. Which objective is highlighted?","options":{"A":"Profit maximisation at any cost","B":"Rapid market dominance","C":"Cutting all staff","D":"Maintaining a preferred style of service and independence"},"correctOption":"D","correctAnswer":"Maintaining a preferred style of service and independence","questionType":"MCQ","explanation":{"correct_reason":"The Innsbruck owner values personal service and independence more than expansion, even though demand is strong. This shows objectives can reflect personal preferences rather than maximum growth or profit.","distractor_reasons":{"A":"The hotel is fully booked, but the owner rejects expansion, so profit maximisation at any cost is not the aim. Personal service matters more.","B":"Market dominance would require expansion, which the owner declines. The hotel's priority is its existing style rather than dominating the market.","C":"Nothing suggests cutting staff; maintaining personal service likely needs staff. The decision is about avoiding growth, not reducing the workforce.","D":"The Innsbruck owner values personal service and independence more than expansion, even though demand is strong. This shows objectives can reflect personal preferences rather than maximum growth or profit."}}},{"id":"P1_U1_MCQ_1986","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1986","question":"At a newspaper printer in Leipzig, one team sets type, another runs the presses and a third bundles the finished copies. What is this arrangement called?","options":{"A":"Centralisation","B":"Diversification","C":"Division of labour","D":"Diseconomies of scale"},"correctOption":"C","correctAnswer":"Division of labour","questionType":"MCQ","explanation":{"correct_reason":"Splitting the printing process into distinct jobs performed by different teams is division of labour. The Leipzig printer specialises tasks to produce newspapers more efficiently.","distractor_reasons":{"A":"Centralisation concerns where decisions are made, not how tasks are divided. The Leipzig arrangement describes work specialisation among teams at the printer.","B":"Diversification means adding new products or markets, which is not happening. The same newspapers are produced by teams doing separate jobs.","C":"Splitting the printing process into distinct jobs performed by different teams is division of labour. The Leipzig printer specialises tasks to produce newspapers more efficiently.","D":"Diseconomies of scale mean rising costs with size, not specialisation. Dividing tasks usually improves efficiency at the Leipzig printer over time."}}},{"id":"P1_U1_MCQ_1987","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1987","question":"A survey in Mérida found 1,200 workers in agriculture, 3,600 in industry and 5,200 in services. What percentage of the workforce is in the secondary sector?","options":{"A":"24%","B":"36%","C":"52%","D":"30%"},"correctOption":"B","correctAnswer":"36%","questionType":"MCQ","explanation":{"correct_reason":"Industry is the secondary sector, with 3,600 workers. Total employment is 1,200 plus 3,600 plus 5,200, which equals 10,000. Three thousand six hundred divided by 10,000 is 0.36, or 36%.","distractor_reasons":{"A":"Agriculture employs 1,200 people, 12% of the 10,000 total, not 24%. It is also primary, so it cannot answer a secondary-sector question.","B":"Industry is the secondary sector, with 3,600 workers. Total employment is 1,200 plus 3,600 plus 5,200, which equals 10,000. Three thousand six hundred divided by 10,000 is 0.36, or 36%.","C":"Services employ 5,200 people, 52% of Mérida's workers, but they are tertiary. The secondary figure comes from the 3,600 in industry.","D":"30% of 10,000 is 3,000 workers, fewer than the 3,600 in industry. Three thousand six hundred out of 10,000 gives 36%."}}},{"id":"P1_U1_MCQ_1988","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1988","question":"A food processor in Rennes has launched a second product line so that a poor harvest for one item will not destroy total sales. Which reason for growth does this show?","options":{"A":"Reducing the number of customers","B":"Avoiding all forms of specialisation","C":"Immediate profit maximisation only","D":"Spreading risk across different products"},"correctOption":"D","correctAnswer":"Spreading risk across different products","questionType":"MCQ","explanation":{"correct_reason":"Adding a second line reduces dependence on one crop, spreading risk if a harvest fails. The Rennes processor grows to stabilise sales, not simply to increase output.","distractor_reasons":{"A":"The firm wants to protect sales, not reduce customers. A second product line is intended to attract or retain buyers when one harvest is poor.","B":"The processor is diversifying its products, which is a form of specialisation across lines, not avoiding the benefits of specialisation altogether in Rennes.","C":"Risk reduction, not immediate profit maximisation alone, drives the second line. The Rennes firm accepts a steadier sales base as the goal.","D":"Adding a second line reduces dependence on one crop, spreading risk if a harvest fails. The Rennes processor grows to stabilise sales, not simply to increase output."}}},{"id":"P1_U1_MCQ_1989","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1989","question":"A company in Bari has 8,000 shares in total. An investor owns 1,600 of them after buying them recently. What percentage of the company does she own?","options":{"A":"10%","B":"25%","C":"20%","D":"40%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The investor holds 1,600 shares out of 8,000. Dividing 1,600 by 8,000 gives 0.20, which is 20%. Option C is her percentage ownership in the Bari company.","distractor_reasons":{"A":"10% of 8,000 is 800 shares, half what she owns. One thousand six hundred divided by 8,000 equals 20% of the company.","B":"25% of 8,000 would be 2,000 shares, more than the 1,600 held. The correct holding is one fifth, or 20%, of the Bari firm.","C":"The investor holds 1,600 shares out of 8,000. Dividing 1,600 by 8,000 gives 0.20, which is 20%. Option C is her percentage ownership in the Bari company.","D":"40% of 8,000 is 3,200 shares, double her holding. One thousand six hundred out of 8,000 gives 20% ownership in the Bari firm."}}},{"id":"P1_U1_MCQ_1990","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1990","question":"An airline in Doha has introduced a more generous baggage allowance after passengers complained about extra fees. Which stakeholder group drove this change most directly?","options":{"A":"Suppliers","B":"Competitors","C":"Employees","D":"Customers"},"correctOption":"D","correctAnswer":"Customers","questionType":"MCQ","explanation":{"correct_reason":"Passengers are the airline's customers, and their complaints about fees led to the new allowance. The Doha carrier responded directly to the people who buy tickets and use the service.","distractor_reasons":{"A":"Suppliers provide aircraft and fuel, not passenger feedback. The complaints came from travellers, making customers the driving stakeholder group in Doha.","B":"Competitors are not cited as the cause; the change followed passenger complaints. Rival airlines may matter, but the stated trigger is customer feedback.","C":"Employees work for the airline and are not described as complaining about baggage fees. The feedback came from customers in Doha.","D":"Passengers are the airline's customers, and their complaints about fees led to the new allowance. The Doha carrier responded directly to the people who buy tickets and use the service."}}},{"id":"P1_U1_MCQ_1991","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1991","question":"A hospital in Vienna employs nurses, doctors and cleaners to provide care. Which factor of production is represented by the daily work of these employees?","options":{"A":"Land","B":"Capital","C":"Labour","D":"Enterprise"},"correctOption":"C","correctAnswer":"Labour","questionType":"MCQ","explanation":{"correct_reason":"Labour is the human effort, both mental and physical, contributed by workers. The Vienna hospital's nurses, doctors and cleaners supply labour to deliver healthcare services.","distractor_reasons":{"A":"Land refers to natural resources and the site, not the work of staff. The hospital building may be land, but the employees provide labour.","B":"Capital means equipment such as scanners and beds. The doctors and nurses are people supplying effort, which is labour, not capital.","C":"Labour is the human effort, both mental and physical, contributed by workers. The Vienna hospital's nurses, doctors and cleaners supply labour to deliver healthcare services.","D":"Enterprise is the organising and risk-taking function, usually the managers or owners. The everyday work of the Vienna hospital staff is labour."}}},{"id":"P1_U1_MCQ_1992","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1992","question":"In Vietnam, the state controls key industries while private shops and farms operate freely. Which economic system combines these two forms of business ownership today?","options":{"A":"Command","B":"Mixed","C":"Free market","D":"Traditional"},"correctOption":"B","correctAnswer":"Mixed","questionType":"MCQ","explanation":{"correct_reason":"A mixed economy blends state control of key sectors with private enterprise. Vietnam's state-run industries alongside private shops and farms are a clear example of that combination.","distractor_reasons":{"A":"A command economy would have the state controlling nearly all activity, but private shops and farms operate freely. That private element makes it mixed.","B":"A mixed economy blends state control of key sectors with private enterprise. Vietnam's state-run industries alongside private shops and farms are a clear example of that combination.","C":"A free market economy would leave little role for state control, yet Vietnam's government controls key industries. The blend is a mixed economy.","D":"A traditional economy relies on custom and subsistence, not a modern mix of state and private ownership. The Vietnamese model is mixed."}}},{"id":"P1_U1_MCQ_1993","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1993","question":"A small engineering firm in Katowice wants to expand but lacks the funds for new machinery. Which source of finance might best help it grow?","options":{"A":"Retained profit or a bank loan","B":"Issuing new coins","C":"Selling shares to the public freely","D":"Ignoring all costs"},"correctOption":"A","correctAnswer":"Retained profit or a bank loan","questionType":"MCQ","explanation":{"correct_reason":"A small firm can fund expansion using retained profits or borrowing from a bank. The Katowice engineering company needs capital for machinery, and these are realistic sources for a private business.","distractor_reasons":{"A":"A small firm can fund expansion using retained profits or borrowing from a bank. The Katowice engineering company needs capital for machinery, and these are realistic sources for a private business.","B":"A firm cannot simply issue coins; money supply is controlled by the state. The Katowice business must obtain finance through savings, profit or loans.","C":"A small private firm cannot usually sell shares to the public; that requires becoming a public company. Retained profit or a bank loan is more practical.","D":"Ignoring costs would not provide funding and would harm the business. The firm needs a genuine source of finance, such as profit or a loan."}}},{"id":"P1_U1_MCQ_1994","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1994","question":"A group of taxi drivers in Havana jointly owns a radio dispatch service and shares the profits equally. What type of legal organisation is this?","options":{"A":"Sole trader","B":"Public limited company","C":"Franchise","D":"Cooperative"},"correctOption":"D","correctAnswer":"Cooperative","questionType":"MCQ","explanation":{"correct_reason":"When members jointly own a business and share its benefits, it is a cooperative. The Havana taxi drivers collectively own the dispatch service and split profits, fitting that structure.","distractor_reasons":{"A":"A sole trader has one owner, but many drivers own this service collectively. Shared ownership by members makes it a cooperative.","B":"A public limited company sells shares to the public and is not owned equally by its users. The Havana drivers' mutual ownership points to a cooperative.","C":"A franchise licenses a brand from a parent firm, which is not described. The drivers own and run the service themselves.","D":"When members jointly own a business and share its benefits, it is a cooperative. The Havana taxi drivers collectively own the dispatch service and split profits, fitting that structure."}}},{"id":"P1_U1_MCQ_1995","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_1995","question":"A company in Nantes employs 1,800 staff, and 450 of them are part of the union representing workers. What percentage of employees are union members?","options":{"A":"15%","B":"30%","C":"25%","D":"20%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Four hundred and fifty employees out of 1,800 belong to the union. Dividing 450 by 1,800 gives 0.25, which is 25%. Option C is the union membership rate at the Nantes company.","distractor_reasons":{"A":"15% of 1,800 is 270 workers, fewer than the 450 members. Four hundred and fifty over 1,800 equals 25%, so a quarter of staff are in the union.","B":"30% of 1,800 would be 540 members, more than the 450 recorded. The correct proportion is 450 divided by 1,800, giving 25%.","C":"Four hundred and fifty employees out of 1,800 belong to the union. Dividing 450 by 1,800 gives 0.25, which is 25%. Option C is the union membership rate at the Nantes company.","D":"20% of 1,800 is 360 employees, not the 450 in the union. Four hundred and fifty out of 1,800 simplifies to one quarter, or 25%."}}},{"id":"P1_U1_MCQ_1996","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.1 Business activity","questionNumber":"P1_U1_MCQ_1996","question":"A coffee roaster in Addis Ababa buys green beans for $3 per kilo and sells roasted beans for $8. Which statement about added value is correct?","options":{"A":"Added value is $3 per kilo","B":"Added value is $5 per kilo, the price less input cost","C":"Added value is $8 per kilo","D":"Added value cannot be calculated here"},"correctOption":"B","correctAnswer":"Added value is $5 per kilo, the price less input cost","questionType":"MCQ","explanation":{"correct_reason":"Added value is the selling price minus the cost of bought-in materials: $8 minus $3 equals $5 per kilo. The Addis Ababa roaster creates that $5 by processing the green beans.","distractor_reasons":{"A":"$3 is the cost of green beans, not the added value. Added value is the $8 selling price less that $3 cost, which is $5.","B":"Added value is the selling price minus the cost of bought-in materials: $8 minus $3 equals $5 per kilo. The Addis Ababa roaster creates that $5 by processing the green beans.","C":"$8 is the selling price, which includes the $3 cost of beans. The value the roaster adds is the $5 difference.","D":"Added value can be calculated: $8 minus $3 gives $5 per kilo. The figures in the scenario are sufficient for this calculation."}}},{"id":"P1_U1_MCQ_1997","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.2 Economic sectors","questionNumber":"P1_U1_MCQ_1997","question":"In the city of Surabaya, 8,000 people work in services, 4,000 in manufacturing and 3,000 in farming. What percentage of workers is in the tertiary sector?","options":{"A":"25%","B":"20%","C":"33.3%","D":"about 53.3%"},"correctOption":"D","correctAnswer":"about 53.3%","questionType":"MCQ","explanation":{"correct_reason":"Services form the tertiary sector, with 8,000 workers. Total employment is 8,000 plus 4,000 plus 3,000, which equals 15,000. Eight thousand divided by 15,000 is approximately 0.533, or 53.3%.","distractor_reasons":{"A":"25% of 15,000 would be 3,750 workers, close to but not the 8,000 in services. Eight thousand out of 15,000 gives about 53.3% tertiary employment.","B":"Manufacturing employs 4,000 people, about 26.7% of the total, not 20%, and it is secondary. The tertiary figure is the 8,000 service workers.","C":"33.3% of 15,000 is 5,000 workers, fewer than the 8,000 in services. Eight thousand over 15,000 is about 53.3% for Surabaya's tertiary sector.","D":"Services form the tertiary sector, with 8,000 workers. Total employment is 8,000 plus 4,000 plus 3,000, which equals 15,000. Eight thousand divided by 15,000 is approximately 0.533, or 53.3%."}}},{"id":"P1_U1_MCQ_1998","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.3 Enterprise, business growth and size","questionNumber":"P1_U1_MCQ_1998","question":"A cleaning company in Wellington wants a simple way to compare its size with another local firm. Which measure would be easiest to count directly?","options":{"A":"Brand reputation","B":"Owner's experience","C":"Number of employees","D":"Customer satisfaction"},"correctOption":"C","correctAnswer":"Number of employees","questionType":"MCQ","explanation":{"correct_reason":"The number of employees is a simple, directly countable measure of business size. The Wellington cleaning company can compare headcount with a rival without complex financial analysis.","distractor_reasons":{"A":"Reputation is subjective and hard to quantify, so it is not an easy direct measure. Employee numbers give a clear, countable comparison.","B":"An owner's experience says nothing about the scale of the firm. Size measures such as employee count are objective and comparable.","C":"The number of employees is a simple, directly countable measure of business size. The Wellington cleaning company can compare headcount with a rival without complex financial analysis.","D":"Satisfaction surveys measure quality, not size. The Wellington firm needs a scale indicator like number of workers, not opinion scores."}}},{"id":"P1_U1_MCQ_1999","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.4 Types of business organisation","questionNumber":"P1_U1_MCQ_1999","question":"A car parts maker in Košice wants to raise large sums by selling shares to the public. Which legal structure would allow this for the company?","options":{"A":"Public limited company","B":"Sole trader","C":"Partnership","D":"Cooperative"},"correctOption":"A","correctAnswer":"Public limited company","questionType":"MCQ","explanation":{"correct_reason":"Only a public limited company can offer shares for sale to the general public and raise large amounts of capital. The Košice car parts maker needs that structure to attract widespread investment.","distractor_reasons":{"A":"Only a public limited company can offer shares for sale to the general public and raise large amounts of capital. The Košice car parts maker needs that structure to attract widespread investment.","B":"A sole trader cannot sell shares and relies on personal funds and loans. The Košice manufacturer's need for public share capital rules this out.","C":"A partnership raises finance from the partners' own resources, not by selling shares publicly. Public share issue requires a company structure.","D":"A cooperative raises funds from members, not the investing public. The car parts maker wants public shares, so a public limited company is suitable."}}},{"id":"P1_U1_MCQ_2000","section":"1","unit":"Unit 1: Understanding business activity","chapter":"1.5 Business objectives and stakeholder objectives","questionNumber":"P1_U1_MCQ_2000","question":"A dam project in Kenya promises cheaper electricity for households but will displace families living in the reservoir area. Which stakeholder conflict does this create?","options":{"A":"Customers versus suppliers","B":"Managers versus employees","C":"Shareholders versus the government","D":"Local community versus the wider consumer interest"},"correctOption":"D","correctAnswer":"Local community versus the wider consumer interest","questionType":"MCQ","explanation":{"correct_reason":"Households gain cheaper power while families near the dam lose their homes, pitting the local community against the wider consumer benefit. The Kenyan project shows how stakeholders can experience very different outcomes.","distractor_reasons":{"A":"Suppliers are not the group being displaced; the conflict involves local residents and electricity users. Customers benefit, while the community bears the cost.","B":"Managers and employees are not the opposing parties described. The tension is between people living near the dam and those who will enjoy cheaper electricity.","C":"The government may promote the project, but the scenario does not frame shareholders against it. The real divide is local residents versus the broader consumer interest.","D":"Households gain cheaper power while families near the dam lose their homes, pitting the local community against the wider consumer benefit. The Kenyan project shows how stakeholders can experience very different outcomes."}}}];
